INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-14393','望中有怀','朱長文','quantangshi','','卷15','龙向洞中衔雨出，鸟从花里带香飞。
白云断处见明月，黄叶落时闻捣衣。','',''),('quantangshi-14394','题虎丘山西寺','朱長文','quantangshi','','卷15','王氏家山昔在兹，陆机为赋陆云诗。
青莲香匝东西宇，日月与僧无尽时。','',''),('quantangshi-14395','吴兴送梁补阙归朝赋得荻花','朱長文','quantangshi','','卷15','柳家汀洲孟冬月，云寒水清荻花发。
一枝持赠朝天人，愿比蓬莱殿前雪。','',''),('quantangshi-14396','句','朱長文','quantangshi','','卷15','夜静忽疑身是梦，更闻寒雨滴芭蕉。','',''),('quantangshi-14397','独不见','戴叔倫','quantangshi','','卷15','前宫路非远，旧苑春将遍。
玉户看早梅，雕梁数飞燕。
身轻逐舞袖，香暖传歌扇。
自和秋风词，长侍昭阳殿。
谁信后庭人，年年独不见。','',''),('quantangshi-14398','去妇怨','戴叔倫','quantangshi','','卷15','出户不敢啼，风悲日凄凄。
心知恩义绝，谁忍分明别。
下坂车辚辚，畏逢乡里亲。
空持牀前幔，却寄家中人。
忽辞王吉去，为是秋胡死。
若比今日情，烦冤不相似。','',''),('quantangshi-14399','古意','戴叔倫','quantangshi','','卷15','悠悠南山云，濯濯东流水。
念我平生欢，托居在东里。
失既不足忧，得亦不为喜。
安贫固其然，处贱宁独耻。
云闲虚我心，水清澹吾味。
云水俱无心，斯可长伉俪。','',''),('quantangshi-14400','南野','戴叔倫','quantangshi','','卷15','治田长山下，引流坦溪曲。
东山有遗茔，南野起新筑。
家世素业儒，子孙鄙食禄。
披云朝出畊，带月夜归读。
身勚竟亡疲，团团欣在目。
野芳绿可采，泉美清可掬。
茂树延晚凉，早田候秋熟。
茶烹松火红，酒吸荷杯绿。
解佩临清池，抚琴看修竹。
此怀谁与同，此乐君所独。','',''),('quantangshi-14401','曾游','戴叔倫','quantangshi','','卷15','泊舟古城下，高阁快登眺。
大江会彭蠡，羣峰豁玄峤。
清影涵空明，黛色凝远照。
碑留太史书，词刻长公调。
绝粒感楚囚，丹衷犹照耀。
怀哉不可招，凭阑一悲啸。','',''),('quantangshi-14402','江行','戴叔倫','quantangshi','','卷15','漾舟晴川里，挂席候风生。
临泛何容与，爱此江水清。
芦洲隐遥嶂，露日映孤城。
自顾疎野性，屡忘鸥鸟情。
聊复于时顾，暂欲解尘缨。
驱驰非吾愿，虚怀浩已盈。','',''),('quantangshi-14403','孤鸿篇','戴叔倫','quantangshi','','卷15','江上双飞鸿，饮啄行相随。
翔风一何厉，中道伤其雌。
顾影明月下，哀鸣声正悲。
已无矰𥐊患，岂乏稻梁资。
嗈嗈慕俦匹，远集清江湄。
中有孤文鵷，翩翩好容仪。
共欣相知遇，毕志同栖迟。
野田鸱鸮鸟，相妒复相疑。
鸿志不汝较，奋翼起高飞。
焉随腐鼠欲，负此云霄期。','',''),('quantangshi-14404','感怀二首 一','戴叔倫','quantangshi','','卷15','尺帛无长裁，浅水无长流。
水浅易成枯，帛短谁人收。
人生取舍间，趋竞固非优。
旧交迹虽疎，中心自云稠。
新交意虽密，中道生怨尤。
踟蹰复踟蹰，世路今悠悠。','',''),('quantangshi-14405','感怀二首 二','戴叔倫','quantangshi','','卷15','主人饮君酒，劝君弗相违。
但当尽弘量，觞至无复辞。
人生百年中，会合能几时。
不见枝上花，昨满今渐稀。
花落还再开，人老无少期。
古来贤达士，饮酒不复疑。','',''),('quantangshi-14406','喜雨','戴叔倫','quantangshi','','卷15','闲居倦时燠，开轩俯平林。
雷声殷遥空，云气布层阴。
川上风雨来，洒然涤烦襟。
田家共欢笑，沟浍亦已深。
团团聚邻曲，斗酒相与斟。
樵歌野田中，渔钓沧江浔。
苍天暨有念，悠悠终我心。','',''),('quantangshi-14407','叹葵花','戴叔倫','quantangshi','','卷15','今日见花落，明日见花开。
花开能向日，花落委苍苔。
自不同凡卉，看时几日回。','',''),('quantangshi-14408','从军行','戴叔倫','quantangshi','','卷15','丈夫四方志，结发事远游。
远游历燕蓟，独戍边城陬。
西风壠水寒，明月关山悠。
酬恩仗孤剑，十年弊貂裘。
封侯属何人，磋跎雪盈头。
老马思故枥，穷鳞忆深流。
弹铗动深慨，浩歌气横秋。
报国期努力，功名良见收。','',''),('quantangshi-14409','九日与敬处士左学士同赋采菊上东山便为首句','戴叔倫','quantangshi','','卷15','采菊上东山，山高路非远。
江湖乍辽敻，城郭亦在眼。
昼日市井喧，闰年禾稼晚。
开尊会佳客，长啸临绝巘。
戏鹤唳且闲，断云轻不卷。
乡心各万里，醉话时一展。
乔木列遥天，残阳贯平坂。
徒忧征车重，自笑谋虑浅。
却顾郡斋中，寄傲与君同。','',''),('quantangshi-14410','奉天酬别郑谏议云逵卢拾遗景亮见别之作','戴叔倫','quantangshi','','卷15','巨孽盗都城，传闻天下惊。
陪臣九江畔，走马来赴难。
伏奏见龙颜，旋持手诏还。
单车不可驻，朱槛未遑攀。
故人出相饯，共悲行路难。
临岐荷赠言，对酒独伤魂。
世故山川险，忧多思虑昏。
重阴蔽芳月，叠岭明旧雪。
泥积辙更深，木冰花不发。
郑君间世贤，忠孝乃双全。
大义弃妻子，至淳易生死。
知心三四人，越境千余里。
骏马帐前发，惊尘路旁起。
楼头俛首看，莫敢相留止。
拜阙奏良图，留中沃圣谟。
洗兵救衞郡，诱敌讨幽都。
名亚典属国，良选谏大夫。
从容九霄上，谈笑授阴符。
卢生富才术，特立居近密。
采掇献吾君，朝廷视听新。
宽饶狂自比，汲黯直为邻。
就列继三事，主文当七人。
可怜长守道，不觉五逢春。
昔去城南陌，各为天际客。
关河烟雾深，寸步音尘隔。
羁旅忽相遇，别离又兹夕。
前悲涕未干，后喜心已戚。
而我方老大，颇为风眩迫。
夫君并少年，何尔鬓须白。
惆怅语不尽，裴回情转剧。
一尊自共持，以慰长相忆。','',''),('quantangshi-14411','梧桐','戴叔倫','quantangshi','','卷15','亭亭南轩外，贞干修且直。
广叶结青阴，繁花连素色。
天资韶雅性，不愧知音识。','',''),('quantangshi-14412','孤石','戴叔倫','quantangshi','','卷15','迥若千仞峰，孤危不盈尺。
早晚他山来，犹带烟雨迹。
贞坚自有分，不乱和氏璧。','',''),('quantangshi-14413','花','戴叔倫','quantangshi','','卷15','花发炎景中，芳春独能久。
因风任开落，向日无先后。
若待秋霜来，兰荪共何有。','',''),('quantangshi-14414','竹','戴叔倫','quantangshi','','卷15','卷箨正离披，新枝复蒙密。
翛翛月下闻，褭褭林际出。
岂独对芳菲，终年色如一。','',''),('quantangshi-14415','怀素上人草书歌','戴叔倫','quantangshi','','卷15','楚僧怀素工草书，古法尽能新有余。
神清骨竦意真率，醉来为我挥健笔。
始从破体变风姿，一一花开春景迟。
忽为壮丽就枯涩，龙蛇腾盘兽屹立。
驰毫骤墨剧奔驷，满座失声看不及。
心手相师势转奇，诡形怪状翻合宜。
人人细问此中妙，怀素自言初不知。','',''),('quantangshi-14416','女耕田行','戴叔倫','quantangshi','','卷15','乳燕入巢笋成竹，谁家二女种新谷。
无人无牛不及犁，持刀斫地翻作泥。
自言家贫母年老，长兄从军未娶嫂。
去年灾疫牛囤空，截绢买刀都市中。
头巾掩面畏人识，以刀代牛谁与同。
姊妹相携心正苦，不见路人唯见土。
疏通畦陇防乱苗，整顿沟塍待时雨。
日正南冈下饷归，可怜朝雉扰惊飞。
东邻西舍花发尽，共惜余芳泪满衣。','',''),('quantangshi-14417','柳花歌送客往桂阳','戴叔倫','quantangshi','','卷15','沧浪渡头柳花发，断续因风飞不绝。
摇烟拂水积翠间，缀雪含霜谁忍攀。
夹岸纷纷送君去，鸣棹孤寻到何处。
移家深入桂水源，种柳新成花更繁。
定知别后消散尽，却忆今朝伤旅魂。','',''),('quantangshi-14418','边城曲','戴叔倫','quantangshi','','卷15','人生莫作远行客，远行莫戍黄沙碛。
黄沙碛下八月时，霜风裂肤百草衰。
尘沙晴天迷道路，河水悠悠向东去。
胡笳听彻双泪流，羁魂惨惨生边愁。
原头猎火夜相向，马蹄蹴蹋层冰上。
不似京华侠少年，清歌妙舞落花前。','',''),('quantangshi-14419','屯田词','戴叔倫','quantangshi','','卷15','春来耕田遍沙碛，老稚欣欣种禾麦。
麦苗渐长天苦晴，土干确确鉏不得。
新禾未熟飞蝗至，青苗食尽余枯茎。
捕蝗归来守空屋，囊无寸帛瓶无粟。
十月移屯来向城，官教去伐南山木。
驱牛驾车入山去，霜重草枯牛冻死。
艰辛历尽谁得知，望断天南泪如雨。','',''),('quantangshi-14420','巫山高','戴叔倫','quantangshi','','卷15','巫山峨峨高插天，危峰十二凌紫烟。
瞿塘嘈嘈急如弦，洄流势逆将覆船。
云梯岂可进，百[丈]那能牵，陆行巉岩水不前。
洒泪向流水，泪归东海边。
含愁对明月，明月空自圆。
故乡回首思绵绵，侧身天地心茫然。','',''),('quantangshi-14421','早春曲','戴叔倫','quantangshi','','卷15','青楼昨夜东风转，锦帐凝寒觉春浅。
垂杨摇丝莺乱啼，褭褭烟光不堪翦。
博山吹云龙脑香，铜壶滴愁更漏长。
玉颊啼红梦初醒，羞见青鸾镜中影。
侬家少年爱游逸，万里轮蹄去无迹。
朱颜未衰消息稀，肠断天涯草空碧。','',''),('quantangshi-14422','白苎词','戴叔倫','quantangshi','','卷15','馆娃宫中露华冷，月落啼鵶散金井。
吴王扶头酒初醒，秉烛张筵乐清景。
美人不眠怜夜永，起舞亭亭乱花影。
新裁白苎胜红绡，玉佩珠缨金步摇。
回鸾转凤意自娇，银筝锦瑟声相调。
君恩如水流不断，但愿年年此同宵。
东风吹花落庭树，春色催人等闲去。
大家为欢莫延伫，顷刻铜龙报天曙。','',''),('quantangshi-14423','行路难','戴叔倫','quantangshi','','卷15','出门行路难，富贵安可期。
淮阴不免恶少辱，阮生亦作穷途悲。
颠倒英雄古来有，封侯却属屠沽儿。
长安车马随轻肥，青云宾从纷交驰。
白眼向人多意气，宰牛烹羊如折葵。
宴乐宁知白日短，时时醉拥双蛾眉。
扬雄闭门空读书，门前碧草春离离。
不如拂衣且归去，世上浮名徒尔为。','',''),('quantangshi-14424','相思曲','戴叔倫','quantangshi','','卷15','高楼重重闭明月，肠断仙郎隔年别。
紫箫横笛寂无声，独向瑶窗坐愁绝。
鱼沈雁杳天涯路，始信人间别离苦。
恨满牙牀翡翠衾，怨折金钗凤皇股。
井深辘轳嗟绠短，衣带相思日应缓。
将刀斫水水复连，挥刃割情情不断。
落红乱逐东流水，一点芳心为君死。
妾身愿作巫山云，飞入仙郎梦魂里。','',''),('quantangshi-14425','送别钱起','戴叔倫','quantangshi','','卷15','阳关多古调，无奈醉中闻。
归梦吴山远，离情楚水分。
孤舟经暮雨，征路入秋云。
后夜同明月，山窗定忆君。','',''),('quantangshi-14426','送张南史','戴叔倫','quantangshi','','卷15','陋巷无车辙，烟萝总是春。
贾生独未达，原宪竟忘贫。
草座留山月，荷衣远洛尘。
最怜知己在，林下访闲人。','',''),('quantangshi-14427','春日早朝应制','戴叔倫','quantangshi','','卷15','仙仗肃朝官，承平圣主欢。
月沈宫漏静，雨湿禁花寒。
丹荔来金阙，朱樱贡玉盘。
六龙扶御日，只许近臣看。','',''),('quantangshi-14428','早行寄朱山人放','戴叔倫','quantangshi','','卷15','山晓旅人去，天高秋气悲。
明河川上没，芳草露中衰。
此别又千里，少年能几时。
心知剡溪路，聊且寄前期。','',''),('quantangshi-14429','除夜宿石头驿','戴叔倫','quantangshi','','卷15','旅馆谁相问，寒灯独可亲。
一年将尽夜，万里未归人。
寥落悲前事，支离笑此身。
愁颜与衰鬓，明日又逢春。','',''),('quantangshi-14430','吴明府自远而来留宿','戴叔倫','quantangshi','','卷15','出门逢故友，衣服满尘埃。
岁月不可问，山川何处来。
绮城容弊宅，散职寄灵台。
自此留君醉，相欢得几回。','',''),('quantangshi-14431','客夜与故人偶集','戴叔倫','quantangshi','','卷15','天秋月又满，城阙夜千重。
还作江南会，翻疑梦里逢。
风枝惊暗鹊，露草覆寒蛩。
羁旅长堪醉，相留畏晓钟。','',''),('quantangshi-14432','送友人东归','戴叔倫','quantangshi','','卷15','万里杨柳色，出关送故人。
轻烟拂流水，落日照行尘。
积梦江湖阔，忆家兄弟贫。
裴回灞亭上，不语自伤春。','',''),('quantangshi-14433','江上别张欢','戴叔倫','quantangshi','','卷15','年年五湖上，厌见五湖春。
长醉非关酒，多愁不为贫。
山川迷道路，伊洛困风尘。
今日扁舟别，俱为沧海人。','',''),('quantangshi-14434','广陵送赵主簿自蜀归绛州宁觐','戴叔倫','quantangshi','','卷15','将归汾水上，远省锦城来。
已泛西江尽，仍随北雁回。
暮云征马速，晓月故关开。
渐向庭闱近，留君醉一杯。','',''),('quantangshi-14435','别友人','戴叔倫','quantangshi','','卷15','扰扰倦行役，相逢陈蔡间。
如何百年内，不见一人闲。
对酒惜余景，问程愁乱山。
秋风万里道，又出穆陵关。','',''),('quantangshi-14436','宿城南盛本道怀皇甫冉','戴叔倫','quantangshi','','卷15','暑夜宿[南城]，怀人梦不成。
高楼邀落月，叠鼓送残更。
隔浦云林近，满川风露清。
东崎不可见，矫首若为情。','',''),('quantangshi-14437','晖上人独坐亭','戴叔倫','quantangshi','','卷15','萧条心境外，兀坐独参禅。
萝月明盘石，松风落润泉。
性空长入定，心悟自通玄。
去住浑无迹，青山谢世缘。','',''),('quantangshi-14438','送崔融','戴叔倫','quantangshi','','卷15','王者应无敌，天兵动远征。
建牙连朔漠，飞骑入胡城。
夜月边城影，秋风陇水声。
陈琳能草檄，含笑出长平。','',''),('quantangshi-14439','游少林寺','戴叔倫','quantangshi','','卷15','步入招提路，因之访道林。
石龛苔藓积，香径白云深。
双树含秋色，孤峰起夕阴。
屧廊行欲遍，回首一长吟。','',''),('quantangshi-14440','崇德道中','戴叔倫','quantangshi','','卷15','暖日菜心稠，晴烟麦穗抽。
客心双去翼，归梦一扁舟。
废塔巢双鹤，长波漾白鸥。
关山明月到，怆恻十年游。','',''),('quantangshi-14441','雨','戴叔倫','quantangshi','','卷15','历历愁心乱，迢迢独夜长。
春帆江上雨，晓镜鬓边霜。
啼鸟云山静，落花溪水香。
家人亦念我，与汝黯相忘。','',''),('quantangshi-14442','过贾谊宅','戴叔倫','quantangshi','','卷15','一谪长沙地，三年叹逐臣。
上书忧汉室，作赋吊灵均。
旧宅秋荒草，西风客荐苹。
凄凉回首处，不见洛阳人。','',''),('quantangshi-14443','冬日有怀李贺长吉','戴叔倫','quantangshi','','卷15','岁晚斋居寂，情人动我思。
每因一尊酒，重和百篇诗。
月冷猨啼惨，天高雁去迟。
夜郎流落久，何日是归期。','',''),('quantangshi-14444','送郎士元','戴叔倫','quantangshi','','卷15','白发金陵客，怀归不暂留。
交情分两地，行色载孤舟。
黄叶蝉吟晚，沧江雁送秋。
何年重会此，诗酒复追游。','',''),('quantangshi-14445','春江独钓','戴叔倫','quantangshi','','卷15','独钓春江上，春江引趣长。
断烟栖草碧，流水带花香。
心事同沙鸟，浮生寄野航。
荷衣尘不染，何用濯沧浪。','',''),('quantangshi-14446','山居即事','戴叔倫','quantangshi','','卷15','岩云掩竹扉，去鸟带余晖。
地僻生涯薄，山深俗事稀。
养花分宿雨，翦叶补秋衣。
野渡逢渔子，同舟荡月归。','',''),('quantangshi-14447','赋得长亭柳','戴叔倫','quantangshi','','卷15','濯濯长亭柳，阴连灞水流。
雨搓金缕细，烟褭翠丝柔。
送客添新恨，听莺忆旧游。
赠行多折取，那得到深秋。','',''),('quantangshi-14448','客中言怀','戴叔倫','quantangshi','','卷15','白发照乌纱，逢人只自嗟。
官闲如致仕，客久似无家。
夜雨孤灯梦，春风几度花。
故园归有日，诗酒老生涯。','',''),('quantangshi-14449','山行','戴叔倫','quantangshi','','卷15','山行分曙色，一路见人稀。
野鸟啼还歇，林花堕不飞。
云迷栖鹤寺，水涩钓鱼矶。
回首天将暝，逢僧话未归。','',''),('quantangshi-14450','春日访山人','戴叔倫','quantangshi','','卷15','远访山中客，分泉谩煮茶。
相携林下坐，共惜鬓边华。
归路逢残雨，沿溪见落花。
候门童子问，游乐到谁家。','',''),('quantangshi-14451','卧病','戴叔倫','quantangshi','','卷15','门掩青山卧，莓苔积雨深。
病多知药性，客久见人心。
众鸟趋林健，孤蝉抱叶吟。
沧洲诗社散，无梦盍朋簪。','',''),('quantangshi-14452','赠月溪羽士','戴叔倫','quantangshi','','卷15','月明溪水上，谁识步虚声。
夜静金波冷，风微玉练平。
自知尘梦远，一洗道心清。
更弄瑶笙罢，秋空鹤又鸣。','',''),('quantangshi-14453','赠行脚僧','戴叔倫','quantangshi','','卷15','补衲随缘住，难违尘外踪。
木杯能渡水，铁钵肯降龙。
到处栖云榻，何年卧雪峰。
知师归日近，应偃旧房松。','',''),('quantangshi-14454','重游长真寺','戴叔倫','quantangshi','','卷15','同到长真寺，青山四面同。
鸟啼花竹暗，人散户庭空。
蒲润千年雨，松门午夜风。
旧游悲往日，回首各西东。','',''),('quantangshi-14455','晚望','戴叔倫','quantangshi','','卷15','山气碧氤氲，深林带夕曛。
人归孤嶂晚，犬吠隔溪云。
杉竹何年种，烟尘此地分。
桃源宁异此，犹恐世间闻。','',''),('quantangshi-14456','寄赠翠岩奉上人','戴叔倫','quantangshi','','卷15','兰若倚西冈，年深松桂长。
似闻葛洪井，还近赞公房。
挂衲云林静，翻经石榻凉。
下方一回首，烟露日苍苍。','',''),('quantangshi-14457','过龙湾五王阁访友人不遇','戴叔倫','quantangshi','','卷15','野桥秋水落，江阁暝烟微。
白日又欲午，高人犹未归。
青林依古塔，虚馆静柴扉。
坐久思题字，翻怜柿叶稀。','',''),('quantangshi-14458','与友人过山寺','戴叔倫','quantangshi','','卷15','共有春山兴，幽寻此日同。
谈诗访灵彻，入社愧陶公。
竹暗闭房雨，茶香别院风。
谁知尘境外，路与白云通。','',''),('quantangshi-14459','赋得古井送王明府','戴叔倫','quantangshi','','卷15','古井庇幽亭，涓涓一窦明。
仙源通海水，灵液孕山精。
久旱宁同涸，长年秪自清。
欲彰贞白操，酌献使君行。','',''),('quantangshi-14460','送耿十三湋复往辽海','戴叔倫','quantangshi','','卷15','仗剑万里去，孤城辽海东。
旌旗愁落日，鼓角壮悲风。
野迥边尘息，烽消戍垒空。
辕门正休暇，投策拜元戎。','',''),('quantangshi-14461','寄禅师寺华上人次韵三首 一','戴叔倫','quantangshi','','卷15','百年浑是客，白发总盈颠。
佛国三秋别，云台五色连。
朝盘香积饭，夜瓮落花泉。
遥忆谈玄地，月高人未眠。','',''),('quantangshi-14462','寄禅师寺华上人次韵三首 二','戴叔倫','quantangshi','','卷15','禅心如落叶，不逐晓风颠。
猊坐翻萧瑟，臯比喜接连。
芙蓉开紫雾，湘玉映清泉。
白昼谈经罢，闲从石上眠。','',''),('quantangshi-14463','寄禅师寺华上人次韵三首 三','戴叔倫','quantangshi','','卷15','德士名难避，风流学济颠。
礼罗加璧至，荐鹗与云连。
尘世休飞锡，松林且枕泉。
近闻离讲席，听雨半山眠。','',''),('quantangshi-14464','独坐','戴叔倫','quantangshi','','卷15','白发怀闽峤，丹心恋蓟门。
官闲胜道院，宅远类荒村。
二月霜花薄，羣山雨气昏。
东菑春事及，好向野人论。','',''),('quantangshi-14465','李大夫见赠因之有呈','戴叔倫','quantangshi','','卷15','何言访衰疾，旌斾重淹留。
谢礼诚难答，裁诗岂易酬。
江清寒照动，山迥野云秋。
一醉龙沙上，终欢胜旧游。','',''),('quantangshi-14466','长沙送梁副端归京','戴叔倫','quantangshi','','卷15','奏书归阙下，祖帐出湘东。
满座他乡别，何年此会同。
藉芳怜岸草，闻笛怨江风。
且莫乘流去，心期在醉中。','',''),('quantangshi-14467','和尉迟侍郎夏杪闻蝉','戴叔倫','quantangshi','','卷15','楚人方苦热，柱史独闻蝉。
晴日暮江上，惊风一叶前。
荡摇清管杂，幽咽野风传。
旅舍闻君听，无由更昼眠。','',''),('quantangshi-14468','和李相公勉晦日蓬池游宴','戴叔倫','quantangshi','','卷15','高会吹台中，新年月桂空。
貂蝉临野水，旌斾引春风。
细草萦斜岸，纤条出故丛。
微文复看猎，宁与解神同。','',''),('quantangshi-14469','彭婆馆逢韦判官使还','戴叔倫','quantangshi','','卷15','受辞分路远，会府见君稀。
雨雪经年去，轩车此日归。
暮春愁见别，久客顺相依。
寂寞伊川上，杨花空自飞。','',''),('quantangshi-14470','酬别刘九郎评事传经同泉字','戴叔倫','quantangshi','','卷15','举袂掩离弦，枉君愁思篇。
忽惊池上鹭，下咽陇头泉。
对牖墙阴满，临扉日影圆。
赖闻黄太守，章句此中传。','',''),('quantangshi-14471','汉南遇方评事','戴叔倫','quantangshi','','卷15','移家住汉阴，不复问华簪。
贳酒宜城近，烧田梦泽深。
暮山逢鸟入，寒水见鱼沈。
与物皆无累，终年惬本心。','',''),('quantangshi-14472','湘中怀古','戴叔倫','quantangshi','','卷15','昔人从逝水，有客吊秋风。
何意千年隔，论心一日同。
楚亭方作乱，汉律正酬功。
倏忽桑田变，谗言亦已空。','',''),('quantangshi-14473','京口怀古','戴叔倫','quantangshi','','卷15','大江横万里，古渡渺千秋。
浩浩波声险，苍苍天色愁。
三方归汉鼎，一水限吴州。
霸国今何在，清泉长自流。','',''),('quantangshi-14474','逢友生言怀','戴叔倫','quantangshi','','卷15','安亲非避地，羁旅十余年。
道长时流许，家贫故旧怜。
相逢今岁暮，远别一方偏。
去住俱难说，江湖正渺然。','',''),('quantangshi-14475','长门怨','戴叔倫','quantangshi','','卷15','自忆专房宠，曾居第一流。
移恩向他处，暂妒不容收。
夜静管弦绝，月明宫殿秋。
空将旧时意，长望凤皇楼。','',''),('quantangshi-14476','郊园即事寄萧侍郎','戴叔倫','quantangshi','','卷15','衰鬓辞余秩，秋风入故园。
结茅成暖室，汲井及清源。
邻里桑麻接，儿童笑语喧。
终朝非役役，聊寄远人言。','',''),('quantangshi-14477','赠韦评事儹','戴叔倫','quantangshi','','卷15','与道共浮沈，人间岁月深。
是非园吏梦，忧喜塞翁心。
细草谁开径，芳条自结阴。
由来居物外，无事可抽簪。','',''),('quantangshi-14478','送少微上人入蜀','戴叔倫','quantangshi','','卷15','十方俱是梦，一念偶寻山。
望刹经巴寺，持瓶向蜀关。
乱猨心本定，流水性长闲。
世俗多离别，王城几日还。','',''),('quantangshi-14479','送道虔上人游方','戴叔倫','quantangshi','','卷15','律仪通外学，诗思入禅关。
烟景随缘到，风姿与道闲。
贯花留静室，咒水度空山。
谁识浮云意，悠悠天地间。','',''),('quantangshi-14480','送嵩律师头陁寺','戴叔倫','quantangshi','','卷15','相传五部学，更有一人成。
此日灵山去，何方半座迎。
麻衣逢雪暖，草履蹑云轻。
若见中林石，应知第四生。','',''),('quantangshi-14481','舟中见雨','戴叔倫','quantangshi','','卷15','今夜初听雨，江南杜若青。
功名何卤莽，兄弟总雕零。
梦远愁蝴蝶，情深愧鹡鸰。
抚孤终日意，身世尚流萍。','',''),('quantangshi-14482','送僧南归','戴叔倫','quantangshi','','卷15','兵尘犹澒洞，僧舍亦征求。
师向江南去，予方毂下留。
风霜两足白，宇宙一身浮。
归及梅花发，题诗寄陇头。','',''),('quantangshi-14483','江干','戴叔倫','quantangshi','','卷15','江干望不极，楼阁影缤纷。
水气多为雨，人烟远是云。
予生何濩落，客路转辛勤。
杨柳牵愁思，和春上翠帬。','',''),('quantangshi-14484','过友人隐居','戴叔倫','quantangshi','','卷15','潇洒绝尘喧，清溪流遶门。
水声鸣石濑，萝影到林轩。
地静留眠鹿，庭虚下饮猨。
春花正夹岸，何必问桃源。','',''),('quantangshi-14485','宿天竺寺晓发罗源','戴叔倫','quantangshi','','卷15','黄昏投古寺，深院一灯明。
水砌长杉列，风廊败叶鸣。
山云留别偈，王事速归程。
迢遰罗源路，轻舆候晓行。','',''),('quantangshi-14486','留宿罗源西峰寺示辉上人','戴叔倫','quantangshi','','卷15','一宿西峰寺，尘烦暂觉清。
远林生夕籁，高阁起钟声。
山寂僧初定，廊深火自明。
虽云殊出处，聊与说无生。','',''),('quantangshi-14487','题横山寺','戴叔倫','quantangshi','','卷15','偶入横山寺，湖山景最幽。
露涵松翠湿，风涌浪花浮。
老衲供茶盌，斜阳送客舟。
自缘归思促，不得更迟留。','',''),('quantangshi-14488','泛舟','戴叔倫','quantangshi','','卷15','风软扁舟稳，行依绿水堤。
孤尊秋露滑，短棹晚烟迷。
夜静月初上，江空天更低。
飘飘信流去，悞过子猷溪。','',''),('quantangshi-14489','宿灵岩寺','戴叔倫','quantangshi','','卷15','马疲盘道峻，投宿入招提。
雨急山溪涨，云迷岭树低。
凉风来殿角，赤日下天西。
偃腹虚檐外，林空鸟恣啼。','',''),('quantangshi-14490','江上别刘驾','戴叔倫','quantangshi','','卷15','天涯芳草遍，江路又逢春。
海月留人醉，山花笑客贫。
离杯倾祖帐，征骑逐行尘。
回首风流地，登临少一人。','',''),('quantangshi-14491','南轩','戴叔倫','quantangshi','','卷15','野居何处是，轩外一横塘。
座纳薰风细，帘垂白日长。
面山如对画，临水坐流觞。
更爱闲花木，欣欣得向阳。','',''),('quantangshi-14492','泊雁','戴叔倫','quantangshi','','卷15','泊雁鸣深渚，收霞落晚川。
柝随风敛阵，楼映月低弦。
漠漠汀帆转，幽幽岸火然。
壑危通细路，沟曲绕平田。','',''),('quantangshi-14493','巡诸州渐次空灵戍','戴叔倫','quantangshi','','卷15','寒尽鸿先至，春回客未归。
蚤知名是病，不敢绣为衣。
雾积川原暗，山多郡县稀。
明朝下湘岸，更逐鹧鸪飞。','',''),('quantangshi-14494','潭州使院书情寄江夏贺兰副端','戴叔倫','quantangshi','','卷15','云雨一萧散，悠悠关复河。
俱从泛舟役，近隔洞庭波。
楚水去不尽，秋风今又过。
无因得相见，却恨寄书多。','',''),('quantangshi-14495','过柳州','戴叔倫','quantangshi','','卷15','地尽江南戍，山分桂北林。
火云三月合，石路九疑深。
暗谷随风过，危桥共鸟寻。
羁魂愁似绝，不复待猨吟。','',''),('quantangshi-14496','经巴东岭','戴叔倫','quantangshi','','卷15','巴山不可上，徒驭亦裴回。
旧栈歌难度，朝云湿未开。
瀑泉飞雪雨，惊兽走风雷。
此去无停候，征人几日回。','',''),('quantangshi-14497','过申州','戴叔倫','quantangshi','','卷15','万人曾战死，几处见休兵。
井邑初安堵，儿童未长成。
凉风吹古木，野火入残营。
牢落千余里，山空水复清。','',''),('quantangshi-14498','次下牢韵','戴叔倫','quantangshi','','卷15','独立荒亭上，萧萧对晚风。
天高吴塞阔，日落楚山空。
猨叫三声断，江流一水通。
前程千万里，一夕宿巴东。','',''),('quantangshi-14499','潘处士宅会别','戴叔倫','quantangshi','','卷15','相邀寒影晚，惜别故山空。
邻里疎林在，池塘野水通。
十年难遇后，一醉几人同。
复此悲行子，萧萧逐转蓬。','',''),('quantangshi-14500','暮春沐发晦日书怀寄韦功曹沨李录事从训王少府纯','戴叔倫','quantangshi','','卷15','朝沐敞南闱，盘跚待日曦。
持梳发更落，览镜意多违。
吾友见尝少，春风去不归。
登高取一醉，犹可及芳菲。','',''),('quantangshi-14501','长安早春赠万评事','戴叔倫','quantangshi','','卷15','春风归戚里，晓日上花枝。
清管新莺发，重门细柳垂。
经过千骑客，调笑五陵儿。
何事灵台客，狂歌自不知。','',''),('quantangshi-14502','留别宋处士','戴叔倫','quantangshi','','卷15','留欢方继烛，此会岂他人。
乡里游从旧，儿童内外亲。
夜深愁不醉，老去别何频。
莫折园中柳，相看惜暮春。','',''),('quantangshi-14503','留别道州李使君圻','戴叔倫','quantangshi','','卷15','泷路下丹徼，邮童挥画桡。
山回千骑隐，云断两乡遥。
渔沪拥寒溜，畲田落远烧。
维舟更相忆，惆怅坐空宵。','',''),('quantangshi-14504','将游东都留别包谏议','戴叔倫','quantangshi','','卷15','衰客慙墨绶，素舸逐秋风。
云雨恩难报，江湖意已终。
县当仙洞口，路出故园东。
唯有新离恨，长留梦寐中。','',''),('quantangshi-14505','灞岸别友','戴叔倫','quantangshi','','卷15','车马去迟迟，离言未尽时。
看花一醉别，会面几年期。
樵路高山馆，渔洲楚帝祠。
南登回首处，犹得望京师。','',''),('quantangshi-14506','临川从事还别崔法曹','戴叔倫','quantangshi','','卷15','谬官辞获免，滥狱会平反。
远与故人别，龙钟望所言。
阴天寒不雨，古木夜多猨。
老病北归去，余年学灌园。','',''),('quantangshi-14507','海上别薛舟','戴叔倫','quantangshi','','卷15','行旅悲摇落，风波厌别离。
客程秋草远，心事故人知。
暮鸟翻江岸，征徒起路岐。
自应无定所，还似欲相随。','',''),('quantangshi-14508','婺州路别录事','戴叔倫','quantangshi','','卷15','府中相见少，江上独行遥。
会日起离恨，新年别旧僚。
春云犹伴雪，寒渚未通潮。
回首羣山暝，思君转寂寥。','',''),('quantangshi-14509','建中癸亥岁奉天除夜宿武当山北茅平村','戴叔倫','quantangshi','','卷15','岁除日又暮，山险路仍新。
驱传迷深谷，瞻星记北辰。
古亭聊假寐，中夜忽逢人。
相问皆呜咽，伤心不待春。','',''),('quantangshi-14510','京口送皇甫司马副端曾舒州辞满归去东都','戴叔倫','quantangshi','','卷15','潮水忽复过，云帆俨欲飞。
故园双阙下，左宦十年归。
晚景照华发，凉风吹绣衣。
淹留更一醉，老去莫相违。','',''),('quantangshi-14511','送李审之桂州谒中丞叔','戴叔倫','quantangshi','','卷15','知音不可遇，才子向天涯。
远水下山急，孤舟上路赊。
乱云收暮雨，杂树落疎花。
到日应文会，风流胜阮家。','',''),('quantangshi-14512','送王翁信及第归江东旧隐','戴叔倫','quantangshi','','卷15','南行无俗侣，秋雁与寒云。
野趣自多惬，名香日总闻。
吴山中路断，浙水半江分。
此地登临惯，含情一送君。','',''),('quantangshi-14513','送李明府之任','戴叔倫','quantangshi','','卷15','身为百里长，家宠五诸侯。
含笑听猨狖，摇鞭望斗牛。
梅花堪比雪，芳草不知秋。
别后南风起，相思梦岭头。','',''),('quantangshi-14514','送郭太祝中孚归江东','戴叔倫','quantangshi','','卷15','乡人去欲尽，北雁又南飞。
京洛风尘久，江湖音信稀。
旧山知独往，一醉莫相违。
未得辞羁旅，无劳问是非。','',''),('quantangshi-14515','新秋夜寄江右友人','戴叔倫','quantangshi','','卷15','遥夜独不寐，寂寥蓬户中。
河明五陵上，月满九门东。
旧知亲友散，故园江海空。
怀归正南望，此夕起秋风。','',''),('quantangshi-14516','清明日送邓芮二子还乡','戴叔倫','quantangshi','','卷15','钟鼓喧离日，车徒促夜装。
晓厨新变火，轻柳暗翻霜。
传镜看华发，持杯话故乡。
每嫌儿女泪，今日自霑裳。','',''),('quantangshi-14517','送谢夷甫宰余姚县','戴叔倫','quantangshi','','卷15','君去方为宰，干戈尚未销。
邑中残老小，乱后少官僚。
廨宇经兵火，公田没海潮。
到时应变俗，新政满余姚。','',''),('quantangshi-14518','送柳道时余北还','戴叔倫','quantangshi','','卷15','征役各异路，烟波同旅愁。
轻桡上桂水，大艑下扬州。
何处成后会，今朝分旧游。
离心比杨柳，萧飒不胜秋。','',''),('quantangshi-14519','送万户曹之任扬州便归旧隐','戴叔倫','quantangshi','','卷15','拟归云壑去，聊寄宦名中。
俸禄资生事，文章实国风。
听潮回楚浪，看月照隋宫。
傥有登楼望，还应伴庾公。','',''),('quantangshi-14520','送李长史纵之任常州','戴叔倫','quantangshi','','卷15','不与名利隔，且为江汉游。
吴山本佳丽，谢客旧淹留。
狭道通陵口，贫家住蒋州。
思归复怨别，寥落讵关秋。','',''),('quantangshi-14521','南宾送蔡侍御游蜀','戴叔倫','quantangshi','','卷15','巴江秋欲尽，远别更凄然。
月照高唐峡，人随贾客船。
积云藏嶮路，流水促行年。
不料相逢日，空悲尊酒前。','',''),('quantangshi-14522','送崔拾遗峒江淮访图书','戴叔倫','quantangshi','','卷15','九门思谏议，万里采风谣。
关外逢秋月，天涯过晚潮。
雁来云杳杳，木落浦萧萧。
空怨他乡别，回舟暮寂寥。','',''),('quantangshi-14523','九日送洛阳李丞之任','戴叔倫','quantangshi','','卷15','为文通绝境，从宦及良辰。
洛下知名早，腰边结绶新。
且倾浮菊酒，聊拂染衣尘。
独恨沧波侣，秋来别故人。','',''),('quantangshi-14524','奉陪李大夫九日宴龙沙','戴叔倫','quantangshi','','卷15','邦君采菊地，近接旅人居。
一命招衰疾，清光照里闾。
去官惭比谢，下榻贵同徐。
莫怪沙边倒，偏霑杯酌余。','',''),('quantangshi-14525','送车参军江陵','戴叔倫','quantangshi','','卷15','槐花落尽柳阴清，萧索凉天楚客情。
海上旧山无的信，东门归路不堪行。
身随幻境劳多事，迹学禅心厌有名。
公子道存知不弃，欲依刘表住南荆。','',''),('quantangshi-14526','游清溪兰若','戴叔倫','quantangshi','','卷15','西看叠嶂几千重，秀色孤标此一峰。
丹竈久闲荒宿草，碧溪深处有潜龙。
灵仙已去空岩室，到客唯闻古寺钟。
远对白云幽隐在，年年不离旧杉松。','',''),('quantangshi-14527','赠史开府','戴叔倫','quantangshi','','卷15','南天胡马独悲嘶，白首相逢话鼓鼙。
野战频年沙朔外，旌竿高与雪峰齐。
扁舟远泛轻全楚，落日愁看旧紫泥。
早晚瑶阶归伏奏，独能画地取关西。','',''),('quantangshi-14528','登楼望月寄凤翔李少尹','戴叔倫','quantangshi','','卷15','陌上凉风槐叶凋，夕阳清露湿寒条。
登楼望月楚山迥，月到南楼山独遥。
心送情人趋凤阙，目随阳雁极烟霄。
轩辕不重无名客，此地还能访寂寥。','',''),('quantangshi-14529','和汴州李相公勉人日喜春','戴叔倫','quantangshi','','卷15','年来日日春光好，今日春光好更新。
独献菜羹怜应节，遍传金胜喜逢人。
烟添柳色看犹浅，鸟踏梅花落已频。
东合此时闻一曲，翻令和者不胜春。','',''),('quantangshi-14530','奉酬卢端公饮后赠诸公见示之作','戴叔倫','quantangshi','','卷15','佐幕临戎旌斾间，五营无事万家闲。
风吹杨柳渐拂地，日映楼台欲下山。
绮席昼开留上客，朱门半掩拟重关。
当时不敢辞先醉，误逐羣公倒载还。','',''),('quantangshi-14531','赠司空拾遗','戴叔倫','quantangshi','','卷15','侍臣何事辞云陛，江上弹冠见雪花。
望阙未承丹凤诏，开门空对楚人家。
陈琳草奏才还在，王粲登楼兴不赊。
高馆更容尘外客，仍令归去待琼华。','',''),('quantangshi-14532','越溪村居','戴叔倫','quantangshi','','卷15','年来桡客寄禅扉，多话贫居在翠微。
黄雀数声催柳变，清溪一路踏花归。
空林野寺经过少，落日深山伴侣稀。
负米到家春未尽，风萝闲扫钓鱼矶。','',''),('quantangshi-14533','赠韩道士','戴叔倫','quantangshi','','卷15','日暮秋风吹野花，上清归客意无涯。
桃源寂寂烟霞闭，天路悠悠星汉斜。
还似世人生白发，定知仙骨变黄芽。
东城南陌频相见，应是壶中别有家。','',''),('quantangshi-14534','寄万德躬故居','戴叔倫','quantangshi','','卷15','日暮山风吹女萝，故人舟楫定如何。
吕仙祠下寒砧急，帝子阁前秋水多。
闽海风尘鸣戍鼓，江湖烟雨暗渔蓑。
何时醉把黄花酒，听尔南征长短歌。','',''),('quantangshi-14535','寄司空曙','戴叔倫','quantangshi','','卷15','细雨柴门生远愁，向来诗句若为酬。
林花落处频中酒，海燕飞时独倚楼。
北郭晚晴山更远，南塘春尽水争流。
可能相别还相忆，莫遣杨花笑白头。','',''),('quantangshi-14536','过故人陈羽山居','戴叔倫','quantangshi','','卷15','向来携酒共追攀，此日看云独未还。
不见山中人半载，依然松下屋三间。
峰攒仙境丹霞上，水遶渔矶绿玉湾。
却望夏洋怀二妙，满崖霜树晓斑斑。','',''),('quantangshi-14537','吊畅当','戴叔倫','quantangshi','','卷15','万里江南一布衣，早将佳句动京畿。
徒闻子敬遗琴在，不见相如驷马归。
朔雪恐迷新冢草，秋风愁老故山薇。
玉堂知己能铭述，犹得精魂慰所依。','',''),('quantangshi-14538','寄刘禹锡','戴叔倫','quantangshi','','卷15','谢相园西石径斜，知君习隐暂为家。
有时出郭行芳草，长日临池看落花。
春去能忘诗共赋，客来应是酒频赊。
五年不见西山色，怅望浮云隐落霞。','',''),('quantangshi-14539','寄孟郊','戴叔倫','quantangshi','','卷15','乱余城郭怕经过，到处闲门长薜萝。
用世空悲闻道浅，入山偏喜识僧多。
醉归花径云生履，樵罢松岩雪满蓑。
石上幽期春又暮，何时载酒听高歌。','',''),('quantangshi-14540','赠徐山人','戴叔倫','quantangshi','','卷15','乱余山水半凋残，江上逢君春正阑。
针自指南天窅窅，星犹拱北夜漫漫。
汉陵帝子黄金盌，晋代神仙白玉棺。
回首风尘千里外，故园烟雨五峰寒。','',''),('quantangshi-14541','过贾谊旧居','戴叔倫','quantangshi','','卷15','楚乡卑湿叹殊方，鵩赋人非宅已荒。
谩有长书忧汉室，空将哀些吊沅湘。
雨余古井生秋草，叶尽疎林见夕阳。
过客不须频太息，咸阳宫殿亦凄凉。','',''),('quantangshi-14542','宫词','戴叔倫','quantangshi','','卷15','紫禁迢迢宫漏鸣，夜深无语独含情。
春风鸾镜愁中影，明月羊车梦里声。
尘暗玉堦綦迹断，香飘金屋篆烟清。
贞心一任蛾眉妒，买赋何须问马卿。','',''),('quantangshi-14543','汉宫人入道','戴叔倫','quantangshi','','卷15','萧萧白发出宫门，羽服星冠道意存。
霄汉九重辞凤阙，云山何处访桃源。
瑶池醉月劳仙梦，玉辇乘春却帝恩。
回首吹箫天上伴，上阳花落共谁言。','',''),('quantangshi-14544','二灵寺守岁','戴叔倫','quantangshi','','卷15','守岁山房迥绝缘，灯光香灺共萧然。
无人更献椒花颂，有客同参栢子禅。
已悟化城非乐界，不知今夕是何年。
忧心悄悄浑忘寐，坐待扶桑日丽天。','',''),('quantangshi-14545','暮春感怀 一','戴叔倫','quantangshi','','卷15','杜宇声声唤客愁，故园何处此登楼。
落花飞絮成春梦，剩水残山异昔游。
歌扇多情明月在，舞衣无意彩云收。
东皇去后韶华尽，老圃寒香别有秋。','',''),('quantangshi-14546','暮春感怀 二','戴叔倫','quantangshi','','卷15','四十无闻嬾慢身，放情丘壑任天真。
悠悠往事杯中物，赫赫时名扇外尘。
短策看云松寺晚，疎帘听雨草堂春。
山花水鸟皆知己，百遍相过不厌贫。','',''),('quantangshi-14547','哭朱放','戴叔倫','quantangshi','','卷15','几年湖海挹余芳，岂料兰摧一夜霜。
人世空传名耿耿，泉台杳隔路茫茫。
碧窗月落琴声断，华表云深鹤梦长。
最是不堪回首处，九泉烟冷树苍苍。','',''),('quantangshi-14548','酬盩厔耿少府湋见寄','戴叔倫','quantangshi','','卷15','方丈萧萧落叶中，暮天深巷起悲风。
流年不尽人自老，外事无端心已空。
家近小山当海畔，身留环衞荫墙东。
遥闻相访频逢雪，一醉寒宵谁与同。','',''),('quantangshi-14549','赠慧上人','戴叔倫','quantangshi','','卷15','仙槎江口槎溪寺，几度停舟访未能。
自恨频年为远客，喜从异郡识高僧。
云霞色酽禅房衲，星月光涵古殿灯。
何日却飞真锡返，故人丘木翳寒藤。','',''),('quantangshi-14550','渐至涪州先寄王员外使君纵','戴叔倫','quantangshi','','卷15','文教通夷俗，均输问火田。
江分巴字水，树入夜郎烟。
毒瘴含秋气，阴崖蔽曙天。
路难空计日，身老不由年。
将命宁知远，归心讵可传。
星郎复何意，出守五溪边。','',''),('quantangshi-14551','和河南罗主簿送校书兄归江南','戴叔倫','quantangshi','','卷15','兄弟泣殊方，天涯指故乡。
断云无定处，归雁不成行。
草莽人烟少，风波水驿长。
上虞亲渤澥，东楚隔潇湘。
古戍阴传火，寒芜晓带霜。
海门潮滟滟，沙岸荻苍苍。
京辇辞芸阁，蘅芳忆草堂。
知君始宁隐，还缉旧荷裳。','',''),('quantangshi-14552','晓闻长乐钟声','戴叔倫','quantangshi','','卷15','汉苑钟声早，秦郊曙色分。
霜凌万户彻，风散一城闻。
已启蓬莱殿，初朝鸳鹭羣。
虚心方应物，大扣欲干云。
近杂鸡人唱，新传凫氏文。
能令翰苑客，流听思氛氲。','',''),('quantangshi-14553','听霜钟','戴叔倫','quantangshi','','卷15','渺渺飞霜夜，寥寥远岫钟。
出云疑断续，入户乍舂容。
度枕频惊梦，随风几韵松。
悠扬来不已，杳霭去何从。
仿髴烟岚隔，依稀岩峤重。
此时聊一听，余响绕千峰。','',''),('quantangshi-14554','听霜钟','戴叔倫','quantangshi','','卷15','寥亮来丰岭，分明辨古钟。
应霜如自击，中节每相从。
静听非闲扣，潜应蕴圣踪。
风间时断续，云外更舂容。
虚警和清籁，雄鸣隔乱峰。
因知谕知己，感激更难逢。','',''),('quantangshi-14555','酬崔法曹遗劒','戴叔倫','quantangshi','','卷15','临风脱佩劒，相劝静胡尘。
自料无筋力，何由答故人。','',''),('quantangshi-14556','敬报孙常州二首 一','戴叔倫','quantangshi','','卷15','衰病苦奔走，未尝追旧游。
何言问憔悴，此日驻方舟。','',''),('quantangshi-14557','敬报孙常州二首 二','戴叔倫','quantangshi','','卷15','远道曳故屐，余春会高斋。
因言别离久，得尽平生怀。','',''),('quantangshi-14558','将赴东阳留上包谏议','戴叔倫','quantangshi','','卷15','敝邑连山远，仙舟数刻同。
多惭屡回首，前路在泥中。','',''),('quantangshi-14559','答崔法曹','戴叔倫','quantangshi','','卷15','后会知不远，今欢亦愿留。
江天梅雨散，况在月中楼。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-14560','问严居士易','戴叔倫','quantangshi','','卷15','自公来问易，不复待加年。
更有垂帘会，遥知续草玄。','',''),('quantangshi-14561','新年第二夜答处上人宿玉芝观见寄','戴叔倫','quantangshi','','卷15','阳春已三日，会友闻昨夜。
可爱剡溪僧，独寻陶景舍。','',''),('quantangshi-14562','赴抚州对酬崔法曹夜雨滴空堦五首 一','戴叔倫','quantangshi','','卷15','雨落湿孤客，心惊比栖鸟。
空阶夜滴繁，相乱应到晓。','',''),('quantangshi-14563','赴抚州对酬崔法曹夜雨滴空堦五首 二','戴叔倫','quantangshi','','卷15','高会枣树宅，清言莲社僧。
两乡同夜雨，旅馆又无灯。','',''),('quantangshi-14564','赴抚州对酬崔法曹夜雨滴空堦五首 三','戴叔倫','quantangshi','','卷15','谤议不自辨，亲朋那得知。
雨中驱马去，非是独伤离。','',''),('quantangshi-14565','赴抚州对酬崔法曹夜雨滴空堦五首 四','戴叔倫','quantangshi','','卷15','离室雨初晦，客程云陡暗。
方为对吏人，敢望邮童探。','',''),('quantangshi-14566','赴抚州对酬崔法曹夜雨滴空堦五首 五','戴叔倫','quantangshi','','卷15','纵酒常掷盏，狂歌时入室。
离羣怨雨声，幽抑方成疾。','',''),('quantangshi-14567','又酬晓灯[离暗]室五首 一','戴叔倫','quantangshi','','卷15','知疑奸叟谤，闲与情人话。
犹是别时灯，不眠同此夜。','',''),('quantangshi-14568','又酬晓灯[离暗]室五首 二','戴叔倫','quantangshi','','卷15','寒灯扬晓焰，重屋惊春雨。
应想远行人，路逢泥泞阻。','',''),('quantangshi-14569','又酬晓灯[离暗]室五首 三','戴叔倫','quantangshi','','卷15','灯光照虚屋，雨影悬空壁。
一向檐下声，远来愁处滴。','',''),('quantangshi-14570','又酬晓灯[离暗]室五首 四','戴叔倫','quantangshi','','卷15','楚僧话寂灭，俗虑比虚空。
赖有残灯喻，相传昏暗中。','',''),('quantangshi-14571','又酬晓灯[离暗]室五首 五','戴叔倫','quantangshi','','卷15','雨声乱灯影，明灭在空堦。
并枉五言赠，知同万里怀。','',''),('quantangshi-14572','同赋龙沙墅','戴叔倫','quantangshi','','卷15','回转沙岸近，欹斜林岭重。
因君访遗迹，此日见真龙。','',''),('quantangshi-14573','昭君词','戴叔倫','quantangshi','','卷15','汉宫若远近，路在寒沙上。
到死不得归，何人共南望。','',''),('quantangshi-14574','劝陆三饮酒','戴叔倫','quantangshi','','卷15','寒郊好天气，劝酒莫辞频。
扰扰钟陵市，无穷不醉人。','',''),('quantangshi-14575','关山月二首 一','戴叔倫','quantangshi','','卷15','月出照关山，秋风人未还。
清光无远近，乡泪半书间。','',''),('quantangshi-14576','关山月二首 二','戴叔倫','quantangshi','','卷15','一雁过连营，繁霜覆古城。
胡笳在何处，半夜起边声。','',''),('quantangshi-14577','送王司直','戴叔倫','quantangshi','','卷15','西塞云山远，东风道路长。
人心胜潮水，相送过浔阳。','',''),('quantangshi-14578','宿无可上人房','戴叔倫','quantangshi','','卷15','偶来人境外，何处染嚣尘。
倘许栖林下，僧中老此身。','',''),('quantangshi-14579','山居','戴叔倫','quantangshi','','卷15','麋鹿自成羣，何人到白云。
山中无外事，终日醉醺醺。','',''),('quantangshi-14580','口号','戴叔倫','quantangshi','','卷15','白发千茎雪，寒窗嬾着书。
最怜吟苜蓿，不及向桑榆。','',''),('quantangshi-14581','夜坐','戴叔倫','quantangshi','','卷15','夜静河汉高，独坐庭前月。
忽起故园思，动作经年别。','',''),('quantangshi-14582','堤上柳','戴叔倫','quantangshi','','卷15','垂柳万条丝，春来织别离。
行人攀折处，闺妾断肠时。','',''),('quantangshi-14583','遣兴','戴叔倫','quantangshi','','卷15','明月临沧海，闲云恋故山。
诗名满天下，终日掩柴关。','',''),('quantangshi-14584','赠张挥使','戴叔倫','quantangshi','','卷15','谪戍孤城小，思家万里遥。
汉廷求衞霍，劒佩上青霄。','',''),('quantangshi-14585','偶成','戴叔倫','quantangshi','','卷15','野水连天碧，峯峦入海青。
沧浪者谁子，一曲醉中听。','',''),('quantangshi-14586','画蝉','戴叔倫','quantangshi','','卷15','饮露身何洁，吟风韵更长。
斜阳千万树，无处避螳螂。','',''),('quantangshi-14587','题天柱山图','戴叔倫','quantangshi','','卷15','拔翠五云中，擎天不计功。
谁能凌绝顶，看取日升东。','',''),('quantangshi-14588','松鹤','戴叔倫','quantangshi','','卷15','雨湿松阴凉，风落松花细。
独鹤爱清幽，飞来不飞去。','',''),('quantangshi-14589','草堂一上人','戴叔倫','quantangshi','','卷15','一公持一钵，相复度遥岑。
地瘦无黄独，春来草更深。','',''),('quantangshi-14590','题黄司直园','戴叔倫','quantangshi','','卷15','为忆去年梅，凌寒特地来。
门前空腊尽，浑未有花开。','',''),('quantangshi-14591','北山游亭','戴叔倫','quantangshi','','卷15','西崦水泠泠，沿冈有游亭。
自从春草长，遥见祗青青。','',''),('quantangshi-14592','赠李唐山人','戴叔倫','quantangshi','','卷15','此意无所欲，闭门风景迟。
