闭户不曾出，诗名满世间。','',''),('quantangshi-14594','答孙常州见忆','戴叔倫','quantangshi','','卷15','画鷁春风里，迢遥去若飞。
那能寄相忆，不并子猷归。','',''),('quantangshi-14595','送裴明州效南朝体','戴叔倫','quantangshi','','卷15','沅水连湘水，千波万浪中。
