且向白云求一醉，莫教愁梦到乡关。','',''),('quantangshi-14653','对月答袁明府','戴叔倫','quantangshi','','卷15','山下孤城月上迟，相留一醉本无期。
明年此夕游何处，纵有清光知对谁。','',''),('quantangshi-14654','送前上饶严明府摄玉山','戴叔倫','quantangshi','','卷15','家在故林吴楚间，冰为溪水玉为山。
更将旧政化邻邑，遥见逋人相逐还。','',''),('quantangshi-14655','听歌回马上赠崔法曹','戴叔倫','quantangshi','','卷15','秋风里许杏花开，杏树傍边醉客来。
共待夜深听一曲，醒人骑马断肠回。','',''),('quantangshi-14656','酬骆侍御答诗','戴叔倫','quantangshi','','卷15','风传画阁空知晓，雨湿江城不见春。
堆案遶牀君莫怪，已经愁思古时人。','',''),('quantangshi-14657','送孙直游郴州','戴叔倫','quantangshi','','卷15','孤舟上水过湘沅，桂岭南枝花正繁。
行客自知心有托，不闻惊浪与啼猨。','',''),('quantangshi-14658','麓山寺会送尹秀才','戴叔倫','quantangshi','','卷15','湖上逢君亦不闲，暂将离别到深山。
飘蓬惊鸟那自定，强欲相留云树间。','',''),('quantangshi-14659','送董颋','戴叔倫','quantangshi','','卷15','霜雁羣飞下楚田，羁人掩泪望秦天。
君行江海无定所，别后相思何处边。','',''),('quantangshi-14660','别张员外','戴叔倫','quantangshi','','卷15','木叶纷纷湘水滨，此中何事往频频。
临风自笑归时晚，更送浮云逐故人。','',''),('quantangshi-14661','送张评事','戴叔倫','quantangshi','','卷15','城郭喧喧争送远，危梁褭褭渡东津。
杨花展转引征骑，莫怪山中多看人。','',''),('quantangshi-14662','送吕少府','戴叔倫','quantangshi','','卷15','共醉流芳独归去，故园高士日相亲。
深山古路无杨柳，折取桐花寄远人。','',''),('quantangshi-14663','送人游岭南','戴叔倫','quantangshi','','卷15','少别华阳万里游，近南风景不曾秋。
红芳绿笋是行路，纵有啼猨听却幽。','',''),('quantangshi-14664','妻亡后别妻弟','戴叔倫','quantangshi','','卷15','杨柳青青满路垂，赠行惟折古松枝。
停舟一对湘江哭，哭罢无言君自知。','',''),('quantangshi-14665','和崔法曹建溪闻猨','戴叔倫','quantangshi','','卷15','曾向巫山峡里行，羁猨一叫一回惊。
闻道建溪肠欲断，的知断着第三声。','',''),('quantangshi-14666','湘南即事','戴叔倫','quantangshi','','卷15','卢橘花开枫叶衰，出门何处望京师。
沅湘日夜东流去，不为愁人住少时。','',''),('quantangshi-14667','代书寄京洛旧游','戴叔倫','quantangshi','','卷15','今年十月温风起，湘水悠悠生白苹。
欲寄远书还不敢，却愁惊动故乡人。','',''),('quantangshi-14668','蕲州行营作','戴叔倫','quantangshi','','卷15','蕲水城西向北看，桃花落尽柳花残。
朱旗半卷山川小，白马连嘶草树寒。','',''),('quantangshi-14669','题武当逸禅师兰若','戴叔倫','quantangshi','','卷15','我身本似远行客，况是乱时多病身。
经山涉水向何处，羞见竹林禅定人。','',''),('quantangshi-14670','谷城逢杨评事','戴叔倫','quantangshi','','卷15','远自五陵独窜身，筑阳山中归路新。
横流夜长不得渡，驻马荒亭逢故人。','',''),('quantangshi-14671','听韩使君美人歌','戴叔倫','quantangshi','','卷15','仙人此夜忽凌波，更唱瑶台一遍歌。
嫁与将军天上住，人间可得再相过。','',''),('quantangshi-14672','转应词','戴叔倫','quantangshi','','卷15','边草，边草，边草尽来共老。
山南山北雪晴，千里万里月明。
明月，明月，胡笳一声愁绝。','',''),('quantangshi-14673','精舍对雨','戴叔倫','quantangshi','','卷15','空门寂寂澹吾身，溪雨微微洗客尘。
卧向白云晴未尽，任他黄鸟醉芳春。','',''),('quantangshi-14674','宿灌阳滩','戴叔倫','quantangshi','','卷15','十月江边芦叶飞，灌阳滩冷上舟迟。
今朝未遇高风便，还与沙鸥宿水湄。','',''),('quantangshi-14675','酬赠张众甫','戴叔倫','quantangshi','','卷15','野人无本意，散木任天材。
分向空山老，何言上苑来。
迢遥千里道，依倚九层台。
出处宁知命，轮辕岂自媒。
更慙张处士，相与别蒿莱。','',''),('quantangshi-14676','客舍秋怀呈骆正字士则','戴叔倫','quantangshi','','卷15','无言堪自喩，偶坐更相悲。
木落惊年长，门闲惜草衰。
买山犹未得，谏猎又非时。
设被浮名系，归休渐欲迟。','',''),('quantangshi-14677','寄中书李舍人纾','戴叔倫','quantangshi','','卷15','萍翻蓬自卷，不共本心期。
复入重城里，频看百草滋。
水流归思远，花发长年悲。
尽日春风起，无人见此时。','',''),('quantangshi-14678','赠康老人洽','戴叔倫','quantangshi','','卷15','酒泉布衣旧才子，少小知名帝城里。
一篇飞入九重门，乐府喧喧闻至尊。
宫中美人皆唱得，七贵因之尽相识。
南邻北里日经过，处处淹留乐事多。
不脱弊裘轻锦绮，长吟佳句掩笙歌。
贤王贵主于我厚，骏马苍头如己有。
暗将心事隔风尘，尽掷年光逐杯酒。
青门几度见春归，折柳寻花送落晖。
杜陵往往逢秋暮，望月临风攀古树。
繁霜入鬓何足论，旧国连天不知处。
尔来倏忽五十年，却忆当时思眇然。
多识故侯悲宿草，曾看流水没桑田。
百人会中一身在，被褐饮瓢终不改。
陌头车马共营营，不解如君任此生。','',''),('quantangshi-14679','暮春游长沙东湖赠辛兖州巢父二首 一','戴叔倫','quantangshi','','卷15','湘流分曲浦，缭绕古城东。
岸转千家合，林开一镜空。
人生无事少，心赏几回同。
且复忘羁束，悠悠落照中。','',''),('quantangshi-14680','暮春游长沙东湖赠辛兖州巢父二首 二','戴叔倫','quantangshi','','卷15','回环路不尽，历览意弥新。
古木畲田火，澄江荡桨人。
缓歌寻极浦，一醉送残春。
莫恨长沙远，他年忆此辰。','',''),('quantangshi-14681','同兖州张秀才过王侍御参谋宅赋十韵','戴叔倫','quantangshi','','卷15','十年官不进，歛迹无怨咎。
漂荡海内游，淹留楚乡久。
因参戎幕下，寄宅湘川口。
翦竹开广庭，瞻山敞虚牖。
闲门早春至，陋巷新晴后。
覆地落残梅，和风褭轻柳。
逢迎车马客，邀结风尘友。
意惬时会文，夜长聊饮酒。
秉心转孤直，沈照随可否。
岂学屈大夫，忧慙对渔叟。','',''),('quantangshi-14682','同辛兖州巢父卢副端岳相思献酬之作因抒归怀兼呈辛魏二院长杨长宁','戴叔倫','quantangshi','','卷15','暮角发高城，情人坐中起。
临觞不及醉，分散秋风里。
虽有明日期，离心若千里。
前欢反惆怅，后会还如此。
焉得夜淹留，一回终宴喜。
羁游复牵役，皆去重湖水。
早晚泛归舟，吾从数君子。','',''),('quantangshi-14683','酬袁太祝长卿小湖村山居书怀见寄','戴叔倫','quantangshi','','卷15','背江居隙地，辞职作遗人。
耕凿资余力，樵渔逐四邻。
麦秋桑叶大，梅雨稻田新。
篱落栽山果，池塘养海鳞。
放歌聊自足，幽思忽相亲。
余亦归休者，依君老此身。','',''),('quantangshi-14684','送汶水王明府','戴叔倫','quantangshi','','卷15','何时别故乡，归去佩铜章。
亲族移家尽，闾阎百战场。
背关余古木，近塞足风霜。
遗老应相贺，知君不下堂。','',''),('quantangshi-14685','奉同汴州李相公勉送郭布殿中出巡','戴叔倫','quantangshi','','卷15','轩车出东阁，都邑遶南河。
马首先春至，人心比岁和。
省风传隐恤，持法去烦苛。
却想埋轮者，论功此日多。','',''),('quantangshi-14686','送东阳顾明府罢归','戴叔倫','quantangshi','','卷15','祖帐临鲛室，黎人拥鷁舟。
坐蓝高士去，继组鄙夫留。
白日落寒水，青枫遶曲洲。
相看作离别，一倍不禁愁。','',''),('quantangshi-14687','抚州对事后送外生宋垓归饶州觐侍呈上姊夫','戴叔倫','quantangshi','','卷15','淮汴初丧乱，蒋山烽火起。
与君随亲族，奔迸辞故里。
京口附商客，海门正狂风。
忧心不敢住，夜发惊浪中。
云开方见日，潮尽炉峯出。
石壁转棠阴，鄱阳寄茅室。
淹留三十年，分种越人田。
骨肉无半在，乡园犹未旋。
尔家习文艺，旁究天人际。
父子自相传，优游聊卒岁。
学成不求达，道胜那厌贫。
时入闾巷醉，好是羲皇人。
顷因物役牵，偶逐簪组辈。
谤书喧朝市，抚己慙浅昧。
世业大小礼，近通颜谢诗。
念渠还领会，非敢独为师。','',''),('quantangshi-14688','永康孙明府颋秩满将归枉路访别','戴叔倫','quantangshi','','卷15','门前水流咽，城下乱山多。
非是还家路，宁知枉骑过。
风烟复欲隔，悲笑屡相和。
不学陶公醉，无因奈别何。','',''),('quantangshi-14689','将赴湖南留别东阳旧僚兼示吏人','戴叔倫','quantangshi','','卷15','智力苦不足，黎甿殊未安。
忽从新命去，复隔旧寮欢。
晓路整车马，离亭会衣冠。
冰坚细流咽，烧尽乱峯寒。
耆老相饯送，儿童亦悲酸。
桐乡寄生怨，欲话此情难。','',''),('quantangshi-14690','抚州处士胡泛见送北回两馆至南昌县界查溪兰若别','戴叔倫','quantangshi','','卷15','移罇铺山曲，祖帐查溪阴。
铺山即远道，查溪非故林。
凄然诵新诗，落泪霑素襟。
郡政我何有，别情君独深。
禅庭古树秋，宿雨清沈沈。
挥袂千里远，悲伤去住心。','',''),('quantangshi-14691','将巡郴永途中作','戴叔倫','quantangshi','','卷15','行役留三楚，思归又一春。
自疑冠下发，聊此镜中人。
机息知名误，形衰恨道贫。
空将旧泉石，长与梦相亲。','',''),('quantangshi-14692','桂阳北岭偶过野人所居聊书即事呈王永州邕李道州圻','戴叔倫','quantangshi','','卷15','犬吠空山响，林深一迳存。
隔云寻板屋，渡水到柴门。
日昼风烟静，花明草树繁。
乍疑秦世客，渐识楚人言。
不记逃乡里，居然长子孙。
种田烧险谷，汲井凿高原。
畦叶藏春雉，庭柯宿旅猨。
岭阴无瘴疠，地隙有兰荪。
内户均皮席，枯瓢沃野餐。
远心知自负，幽赏讵能论。
转步重崖合，瞻途落照昏。
他时愿携手，莫比武陵源。','',''),('quantangshi-14693','下鼻亭泷行八十里聊状艰险寄青苗郑副端朔阳','戴叔倫','quantangshi','','卷15','泷水天际来，鼻山地中坼。
盘涡几十处，叠溜皆千尺。
直写卷沈沙，惊翻冲绝壁。
淙淙振崖谷，汹汹竟朝夕。
人语不自闻，日光乱相射。
舣舟始摇漾，举棹旋奔激。
既下同建瓴，半空方避石。
前危苦未尽，后险何其迫。
倏闪疾风雷，苍皇荡魂魄。
因随伏流出，忽与跳波隔。
远想欲回轩，岂兹还泛鷁。
云涯多候馆，努力勤登历。','',''),('quantangshi-14694','少女生日感怀','戴叔倫','quantangshi','','卷15','五逢晬日今方见，置尔怀中自惘然。
乍喜老身辞远役，翻悲一笑隔重泉。
欲教针线娇难解，暂弄琴书性已便。
还有蔡家残史籍，可能分与外人传。','',''),('quantangshi-14695','张评事涉秦居士系见访郡斋即同赋中字','戴叔倫','quantangshi','','卷15','轺车忽枉辙，郡府自生风。
遣吏山禽在，开罇野客同。
古墙抽腊笋，乔木扬春鸿。
能赋传幽思，清言尽至公。
城欹残照入，池曲大江通。
此地人来少，相欢一醉中。','',''),('quantangshi-14696','小雪','戴叔倫','quantangshi','','卷15','花雪随风不厌看，更多还肯失林峦。
愁人正在书窗下，一片飞来一片寒。','',''),('quantangshi-14697','句','戴叔倫','quantangshi','','卷15','邻里龙沙北。
麦秋桑叶大，梅雨稻田新。
篱落栽山果，池塘养锦鳞。','',''),('quantangshi-14698','竞渡歌','張建封','quantangshi','','卷15','五月五日天晴明，杨花绕江啼晓莺。
使君未出郡斋外，江上早闻齐和声。
使君出时皆有准，马前已被红旗引。
两岸罗衣破晕香，银钗照日如霜刃。
鼓声三下红旗开，两龙跃出浮水来。
棹影斡波飞万劒，鼓声劈浪鸣千雷。
鼓声渐急标将近，两龙望标目如瞬。
坡上人呼霹雳惊，竿头彩挂虹霓晕。
前船抢水已得标，后船失势空挥桡。
疮眉血首争不定，输岸一朋心似烧。
只将输赢分罚赏，两岸十舟五来往。
须臾戏罢各东西，竞脱文身请书上。
吾今细观竞度儿，何殊当路权相持。
不思得岸各休去，会到摧车折檝时。','',''),('quantangshi-14699','酬韩校书愈打球歌','張建封','quantangshi','','卷15','仆本修文持笔者，今来帅领红旌下。
不能无事习虵矛，闲就平场学使马。
军中伎痒骁智材，竞驰骏逸随我来。
护军对引相向去，风呼月旋朋先开。
俯身仰击复傍击，难于古人左右射。
齐观百步透短门，谁羡养由遥破的。
儒生疑我新发狂，武夫爱我生雄光。
杖移鬃底拂尾后，星从月下流中场。
人不约，心自一，马不鞭，蹄自疾。
凡情莫辨捷中能，拙目翻惊巧时失。
韩生讶我为斯艺，劝我徐驱作安计。
不知戎事竟何成，且愧吾人一言惠。','',''),('quantangshi-14700','春山夜月','于良史','quantangshi','','卷15','春山多胜事，赏翫夜忘归。
掬水月在手，弄花香满衣。
兴来无远近，欲去惜芳菲。
南望鸣钟处，楼台深翠微。','',''),('quantangshi-14701','宿蓝田山口奉寄沈员外','于良史','quantangshi','','卷15','山暝飞羣鸟，川长泛四邻。
烟归河畔草，月照渡头人。
朋友怀东道，乡关恋北辰。
去留无所适，岐路独迷津。','',''),('quantangshi-14702','冬日野望寄李赞府','于良史','quantangshi','','卷15','地际朝阳满，天边宿雾收。
风兼残雪起，河带断冰流。
北阙驰心极，南图尚旅游。
登临思不已，何处得销愁。','',''),('quantangshi-14703','闲居寄薛华','于良史','quantangshi','','卷15','隐几读黄老，闲居耳目清。
僻居人事少，多病道心生。
雨洗山林湿，鸦鸣池馆晴。
晚来因废卷，行药至西城。','',''),('quantangshi-14704','江上送友人','于良史','quantangshi','','卷15','看尔动行棹，未收离别筵。
千帆忽见及，乱却故人船。
纷泊雁羣起，逶迤沙溆连。
长亭十里外，应是少人烟。','',''),('quantangshi-14705','田家秋日送友','于良史','quantangshi','','卷15','苍茫日初宴，遥野云初收。
残雨北山里，夕阳东渡头。
舟依渔溓合，水入田家流。
何意君迷驾，山林应有秋。','',''),('quantangshi-14706','自吟','于良史','quantangshi','','卷15','出身三十年，发白衣犹碧。
日暮倚朱门，从朱污袍赤。','',''),('quantangshi-14707','感兴','崔膺','quantangshi','','卷15','富贵难义合，困穷易感恩。
古来忠烈士，多出贫贱门。
世上桃李树，但结繁华子。
白屋抱关人，青云壮心死。
本以势利交，势尽交情已。
如何失情后，始叹门易轨。','',''),('quantangshi-14708','别佳人','崔膺','quantangshi','','卷15','壠上流泉壠下分，断肠呜咽不堪闻。
嫦娥一入月中去，巫峡千秋空白云。','',''),('quantangshi-14709','御沟新柳','馮宿','quantangshi','','卷15','夹道天渠远，垂丝御柳新。
千条宜向日，万户共迎春。
轻翠含烟发，微音逐吹频。
静看思渡口，回望忆江滨。
袅袅分游骑，依依驻旅人。
阳和如可及，攀折在兹辰。','',''),('quantangshi-14710','酬白乐天刘梦得','馮宿','quantangshi','','卷15','共称洛邑难其选，何幸天书用不才。
遥约和风新草木，且令新雪静尘埃。
临岐有愧倾三省，别酌无辞醉百杯。
明岁杏园花下集，须知春色自东来。','',''),('quantangshi-14711','乐府答孟东野戏赠','陸長源','quantangshi','','卷15','芙蓉初出水，菡萏露中花。
风吹着枯木，无奈值空槎。','',''),('quantangshi-14712','酬孟十二新居见寄','陸長源','quantangshi','','卷15','大道本夷旷，高情亦冲虚。
因随白云意，偶逐青萝居。
青萝纷蒙密，四序无惨舒。
余清濯子襟，散彩还吾庐。
去岁登美第，策名在公车。
将必继管萧，岂惟蹑应徐。
首夏尚清和，残芳遍丘墟。
褰帏荫窗柳，汲井滋园蔬。
达者贵知心，古人不愿余。
爱君蒋生迳，且着茂陵书。','',''),('quantangshi-14713','答东野夷门雪','陸長源','quantangshi','','卷15','好丹与素道不同，失意得途事皆别。
东隣少年乐未央，南客思归肠欲绝。
千里长河冰复冰，云鸿冥冥楚山雪。','',''),('quantangshi-14714','句','陸長源','quantangshi','','卷15','忽然一曲称君心，破却中人百家产。
城外平人驱欲尽，帐中犹打衮花球。','',''),('quantangshi-14715','寄兴国池鹤上刘相公','張衆甫','quantangshi','','卷15','驯狎经时久，䙰褷短翮存。
不随淮海变，空愧稻粱恩。
独立秋天静，单栖夕露繁。
欲飞还敛翼，讵敢望乘轩。','',''),('quantangshi-14716','送李司直使吴','張衆甫','quantangshi','','卷15','使臣方拥传，王事远辞家。
震泽逢残雨，新丰过落花。
水萍千叶散，风柳万条斜。
何处看离恨，春江无限沙。','',''),('quantangshi-14717','送李观之宣州谒袁中丞赋得三州渡','張衆甫','quantangshi','','卷15','古渡大江滨，西南距要津。
自当舟檝路，应济往来人。
翻浪惊飞鸟，回风起绿苹。
君看波上客，岁晚独垂纶。','',''),('quantangshi-14718','宿慧山寺','王武陵','quantangshi','','卷15','秋日游古寺，秋山正苍苍。
泛舟次岩壑，稽首金仙堂。
下有寒泉流，上有珍禽翔。
石门吐明月，竹木涵清光。
中夜河沈沈，但闻松桂香。
旷然出尘境，忧虑澹已忘。','',''),('quantangshi-14719','秋暮登北楼','王武陵','quantangshi','','卷15','秋满空山悲客心，山楼晴望散幽襟。
一川红树迎霜老，数曲清溪绕寺深。
寒气急催遥塞雁，夕风高送远城砧。
三年海上音书绝，乡国萧条惟梦寻。','',''),('quantangshi-14720','宿慧山寺 一','朱宿','quantangshi','','卷15','古寺隐秋山，登攀度林樾。
悠然清莲界，此地尘境绝。
机闲任昼昏，虑澹知生灭。
微吹递遥泉，疎松对残月。
庭虚露华缀，池净荷香发。
心悟形未留，迟迟履归辙。','',''),('quantangshi-14721','宿慧山寺 二','朱宿','quantangshi','','卷15','岁月人间促，烟霞此地多。
殷勤竹林寺，更得几回过。','',''),('quantangshi-14722','送惟良上人归江南','盧綸','quantangshi','','卷15','落日映危樯，归僧向岳阳。
注瓶寒浪静，读律夜船香。
苦雾沈山影，阴霾发海光。
羣生一何负，多病礼医王。','',''),('quantangshi-14723','送韩都护还边','盧綸','quantangshi','','卷15','好勇知名早，争雄上将间。
战多春入塞，猎惯夜登山。
阵合龙蛇动，军移草木闲。
今来部曲尽，白首过萧关。','',''),('quantangshi-14724','送吉中孚校书归楚州旧山','盧綸','quantangshi','','卷15','青袍芸阁郎，谈笑挹侯王。
旧箓藏云穴，新诗满帝乡。
名高闲不得，到处人争识。
谁知冰雪颜，已杂风尘色。
此去复如何，东臯岐路多。
藉芳临紫陌，回首忆沧波。
年来倦萧索，但说淮南乐。
并檝湖上游，连樯月中泊。
沿溜入阊门，千灯夜市喧。
喜逢邻舍伴，遥语问乡园。
下淮风自急，树杪分郊邑。
送客随岸行，离人出帆立。
渔村绕水田，澹澹隔晴烟。
欲就林中醉，先期石上眠。
林昏天未曙，但向云边去。
暗入无路山，心知有花处。
登高日转明，下望见春城。
洞里草空长，冢边人自耕。
寥寥行异境，过尽千峰影。
露色凝古坛，泉声落寒井。
仙成不可期，多别自堪悲。
为问桃源客，何人见乱时。','',''),('quantangshi-14725','送姨弟裴均尉诸曁','盧綸','quantangshi','','卷15','相悲得成长，同是外家恩。
旧业废三亩，弱年成一门。
城开山日早，吏散渚禽喧。
东阁谬容止，予心君冀言。','',''),('quantangshi-14726','送邓州崔长史','盧綸','quantangshi','','卷15','出山车骑次诸侯，坐领图书见督邮。
遶郭桑麻通淅口，满川风景接襄州。
高城鸟过方催夜，废垒蝉鸣不待秋。
闻说元规偏爱月，知君常得伴登楼。','',''),('quantangshi-14727','送盐铁裴判官入蜀','盧綸','quantangshi','','卷15','传诏收方贡，登车着赐衣。
榷商蛮客富，税地芋田肥。
云白风雷歇，林清洞穴稀。
炎凉君莫问，见即在忘归。','',''),('quantangshi-14728','送魏广下第归扬州','盧綸','quantangshi','','卷15','楚乡云水内，春日众山开。
淮浪参差起，江帆次第来。
独归初失桂，共醉忽停杯。
汉诏年年有，何愁掩上才。','',''),('quantangshi-14729','送潘述应宏词下第归江南','盧綸','quantangshi','','卷15','愁与醉相和，昏昏竟若何。
感年怀阙久，失意梦乡多。
雨里行青草，山前望白波。
江楼覆棋好，谁引仲宣过。','',''),('quantangshi-14730','送从舅成都县丞广归蜀','盧綸','quantangshi','','卷15','襃谷通岷岭，青冥此路深。
晚程椒瘴热，野饭荔枝阴。
古郡三刀夜，春桥万里心。
唯应对杨柳，暂醉卓家琴。','',''),('quantangshi-14731','送宋校书赴宣州幕','盧綸','quantangshi','','卷15','南想宣城郡，清江野戍闲。
艨艟高映浦，睥睨曲随山。
名寄图书内，威生将吏间。
春行板桥暮，应伴庾公还。','',''),('quantangshi-14732','送李纵别驾加员外郎却赴常州幕','盧綸','quantangshi','','卷15','霄汉正联飞，江湖又独归。
暂欢同赐被，不待易朝衣。
山雨迎军晚，芦风候火微。
还当宴铃阁，谢守亦光辉。','',''),('quantangshi-14733','送元赞府重任龙门县','盧綸','quantangshi','','卷15','二职亚陶公，归程与梦同。
柳垂平泽雨，鱼跃大河风。
混迹威长在，孤清志自雄。
应嗤向隅者，空寄路尘中。','',''),('quantangshi-14734','送黎燧尉阳翟','盧綸','quantangshi','','卷15','玉貌承严训，金声称上才。
列筵青草偃，骤马绿杨开。
潘县花添发，梅家鹤暂来。
谁知望恩者，空逐路人回。','',''),('quantangshi-14735','送丹阳赵少府','盧綸','quantangshi','','卷15','恭闻林下别，未至亦霑裳。
荻岸雨声尽，江天虹影长。
佩韦宗嬾慢，偷橘爱芳香。
遥想从公后，称荣在上堂。','',''),('quantangshi-14736','送菊潭王明府','盧綸','quantangshi','','卷15','组绶掩衰颜，辉光里第间。
晚凉经灞水，清昼入商山。
行境逢花发，弹琴见鹤还。
唯应理农后，乡老贺君闲。','',''),('quantangshi-14737','送陈明府赴萍县','盧綸','quantangshi','','卷15','素舸载陶公，南随万里风。
梅花成雪岭，橘树当家僮。
祠掩荒山下，田开野荻中。
岁终书善绩，应与古碑同。','',''),('quantangshi-14738','送申屠正字往湖南迎亲兼谒赵和州因呈上侍郎使君并戏简前历阳李明府','盧綸','quantangshi','','卷15','晓月朣朦映水关，水边因到历阳山。
千艘财货朱桥下，一曲闾阎青荻间。
坦腹定逢潘令醉，上楼应伴庾公闲。
欢余若问南行计，知念天涯负米还。','',''),('quantangshi-14739','送李尚书郎君昆季侍从归觐滑州','盧綸','quantangshi','','卷15','凤雏联翼美王孙，彩服戎装拟塞垣。
金鼎对筵调野膳，玉鞭齐骑引行轩。
冰河一曲旌旗满，墨诏千封雨露繁。
更说务农能罢战，敢持謌颂庆晨昏。','',''),('quantangshi-14740','送张调参军侍从归觐荆南因寄长林司空十四曙','盧綸','quantangshi','','卷15','玉勒侍行襜，郄超未有髯。
守儒轻猎骑，承诲访沈潜。
云势将峰杂，江声与屿兼。
还当见王粲，应念二毛添。','',''),('quantangshi-14741','送马尚书郎君侍从归觐太原','盧綸','quantangshi','','卷15','玉人垂玉鞭，百骑带櫜鞬。
从赏野邮静，献新秋果鲜。
塞屯丰雨雪，虏帐失山川。
遥想称觞后，唯当共被眠。','',''),('quantangshi-14742','送张成季往江上赋得垂杨','盧綸','quantangshi','','卷15','垂杨真可怜，地胜觉春偏。
一穗雨声里，千条池色前。
露繁光的皪，日丽影团圆。
若到隋堤望，应逢花满船。','',''),('quantangshi-14743','送陕府王司法','盧綸','quantangshi','','卷15','东门雪覆尘，出送陕城人。
粉郭朝喧市，朱桥夜掩津。
上寮应重学，小吏已甘贫。
谢朓曾为掾，希君一比邻。','',''),('quantangshi-14744','送太常李主簿归觐省','盧綸','quantangshi','','卷15','粲粲美仍都，清闲一贵儒。
定交分玉劒，发咏写冰壶。
风景随台位，河山入障图。
上堂多庆乐，肯念谷中愚。','',''),('quantangshi-14745','送从叔程归西川幕','盧綸','quantangshi','','卷15','千山冰雪晴，山静锦花明。
羣鹤栖莲府，诸戎拜柳营。
浪依巴字息，风入蜀关清。
岂念在贫巷，竹林鸣鸟声。','',''),('quantangshi-14746','送万巨','盧綸','quantangshi','','卷15','把酒留君听琴，难堪岁暮离心。
霜叶无风自落，秋云不雨空阴。
人愁荒村路细，马怯寒溪水深。
望断青山独立，更知何处相寻。','',''),('quantangshi-14747','途中遇雨马上口号留别张刘二端公','盧綸','quantangshi','','卷15','阴雷慢转野云长，骏马双嘶爱雨凉。
应念龙钟在泥滓，欲摧肝胆事王章。','',''),('quantangshi-14748','送夔州班使君','盧綸','quantangshi','','卷15','晓日照楼船，三军拜峡前。
白云随浪散，青壁与城连。
万岭岷峨雪，千家橘柚川。
还知楚河内，天子许经年。','',''),('quantangshi-14749','送从舅成都丞广归蜀','盧綸','quantangshi','','卷15','巴字天边水，秦人去是归。
栈长山雨响，溪乱火田稀。
俗富行应乐，官雄禄岂微。
魏舒终有泪，还识甯家衣。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-14750','无题','盧綸','quantangshi','','卷15','耻将名利托交亲，只向尊前乐此身。
才大不应成滞客，时危且喜是闲人。
高歌犹爱思归引，醉语惟夸漉酒巾。
囗囗囗囗囗囗囗，岂能偏遣老风尘。','',''),('quantangshi-14751','题念济寺','盧綸','quantangshi','','卷15','灵空闻偈夜清静，雨里花枝朝暮开。
故友九泉留语别，逐臣千里寄书来。','',''),('quantangshi-14752','河口逢江州朱道士因听琴','盧綸','quantangshi','','卷15','庐山道士夜携琴，映月相逢辨语音。
引坐霜中弹一弄，满船商客有归心。','',''),('quantangshi-14753','送夏侯校书归华阴别墅','盧綸','quantangshi','','卷15','山前白鹤村，竹雪覆柴门。
候客定为黍，务农因燎原。
乳冰悬暗井，莲石照晴轩。
贳酒邻里睦，曝衣场圃喧。
依然望君去，余性亦何昏。','',''),('quantangshi-14754','送绛州郭参军','盧綸','quantangshi','','卷15','炎天故绛路，千里麦花香。
董泽雷声发，汾桥水气凉。
府趋随宓贱，野宴接王祥。
送客今何幸，经宵醉玉堂。','',''),('quantangshi-14755','中书舍人李座上送颍阳徐少府','盧綸','quantangshi','','卷15','颍阳春色似河阳，一望繁花一县香。
今日送官君最恨，可怜才子白须长。','',''),('quantangshi-14756','与从弟瑾同下第后出关言别 一','盧綸','quantangshi','','卷15','同作金门献赋人，二年悲见故园春。
到阙不沾新雨露，还家空带旧风尘。','',''),('quantangshi-14757','与从弟瑾同下第后出关言别 二','盧綸','quantangshi','','卷15','杂花飞尽柳阴阴，官路逶迤绿草深。
对酒已成千里客，望山空寄两乡心。','',''),('quantangshi-14758','与从弟瑾同下第后出关言别 三','盧綸','quantangshi','','卷15','出关愁暮一沾裳，满野蓬生古战场。
孤村树色昏残雨，远寺钟声带夕阳。','',''),('quantangshi-14759','与从弟瑾同下第后出关言别 四','盧綸','quantangshi','','卷15','谁怜苦志已三冬，却欲躬耕学老农。
流水白云寻不尽，期君何处得相逢。','',''),('quantangshi-14760','赴虢州留别故人','盧綸','quantangshi','','卷15','世故相逢各未闲，百年多在别离间。
昨夜秋风今夜雨，不知何处入空山。','',''),('quantangshi-14761','冬夜赠别友人','盧綸','quantangshi','','卷15','愁听千家流水声，相思独向月中行。
侵堦暗草秋霜重，遍郭寒山夜月明。
连年客舍唯多病，数亩田园又废耕。
更送乘轺归上国，应怜贡禹未成名。','',''),('quantangshi-14762','送顾秘书献书后归岳州','盧綸','quantangshi','','卷15','黄叶落不尽，苍苔随雨生。
当轩置尊酒，送客归江城。
竹里闻机杼，舟中见弟兄。
岳阳贤太守，应为改乡名。','',''),('quantangshi-14763','送衞司法河中觐省','盧綸','quantangshi','','卷15','出身因强学，不以外家荣。
年少无遗事，官闲有政声。
晓山临野渡，落日照军营。
共赏高堂下，连行弟与兄。','',''),('quantangshi-14764','送从叔牧永州','盧綸','quantangshi','','卷15','五侯轩盖行何疾，零陵太守登车日。
零陵太守泪盈巾，此日长安方欲春。
虎符龙节照岐路，何苦愁为江海人。
彼方韶景无时节，山水诸花恣开发。
客投津戍少闻猨，雁过潇湘更逢雪。
郡斋无事好闲眠，秔稻油油绿满川。
浪里争迎三蜀货，月中喧泊九江船。
今朝小阮同夷老，欲闻明年借几年。','',''),('quantangshi-14765','送赵真长归夏县旧山依阳征君读书','盧綸','quantangshi','','卷15','临杯忽泫然，非是恶离弦。
尘陌望松雪，我衰君少年。
幽僧曝山果，寒鹿守冰泉。
感物如有待，况依回也贤。','',''),('quantangshi-14766','留别耿湋侯钊冯着','盧綸','quantangshi','','卷15','相识少相知，与君俱已衰。
笙镛新宅第，岐路古山陂。
学道功难就，为儒事本迟。
惟当与渔者，终老遂其私。','',''),('quantangshi-14767','送浑炼归觐却赴阙庭','盧綸','quantangshi','','卷15','露幕拥簪裾，台庭饯伯鱼。
彩衣人竞看，银诏帝亲书。
知子当元老，为臣饯二疎。
执圭期已迫，捧膳步宁徐。
而我诚愚者，夫君岂病诸。
探题多决胜，馔玉每分余。
荣比成功后，恩同造化初。
甑尘方欲合，笼翮或将舒。
榆荚钱难比，杨花雪不如。
明朝古堤路，心断玉人车。','',''),('quantangshi-14768','送崔邠拾遗','盧綸','quantangshi','','卷15','皎洁无瑕清玉壶，晓乘华幰向天衢。
石建每闻宗谨孝，刘歆不敢炫师儒。
谏修郊庙开宸虑，议按休征浅瑞图。
今日攀车复何者，辕门垂白一愚夫。','',''),('quantangshi-14769','送浑别驾赴舒州','盧綸','quantangshi','','卷15','江平芦荻齐，五两贴樯低。
遶郭覆晴雪，满船闻曙鸡。
鳣鲂宜入贡，橘柚亦成蹊。
还似海沂日，风清无鼓鼙。','',''),('quantangshi-14770','送从叔士准赴任润州司士','盧綸','quantangshi','','卷15','云起山城暮，沈沈江上天。
风吹建业雨，浪入广陵船。
久是吴门客，尝闻谢守贤。
终悲去国远，泪尽竹林前。','',''),('quantangshi-14771','送尹枢令狐楚及第后归觐','盧綸','quantangshi','','卷15','佳人比香草，君子即芳兰。
宝器金罍重，清音玉佩寒。
贡文齐受宠，献礼两承欢。
鞍马并汾地，争迎陆与潘。','',''),('quantangshi-14772','东潭宴饯河南赵少府','盧綸','quantangshi','','卷15','十载奉戎轩，日闻君子言。
方将贺荣爵，遽乃怆离尊。
岸转台阁丽，潭清弦管繁。
松篁难晦节，雨露不私恩。
坐使吏相勉，居为儒所尊。
可怜桃李树，先发信陵门。','',''),('quantangshi-14773','赋得馆娃宫送王山人游江东','盧綸','quantangshi','','卷15','苍苍枫树林，草合废宫深。
越水风浪起，吴王歌管沈。
燕归巢已尽，鹤语冢难寻。
旅泊彼何夜，希君抽玉琴。','',''),('quantangshi-14774','送畅当还旧山','盧綸','quantangshi','','卷15','常逢明月马尘间，是夜照君归处山。
山中松桂花尽发，头白属君如等闲。','',''),('quantangshi-14775','斅颜鲁公送挺贇归翠微寺','盧綸','quantangshi','','卷15','挺贇惠学该儒释，袖有颜徐真草迹。
一斋三请纪行诗，诮我垂鞭弄鸣镝。
寺悬金榜半山隅，石路荒凉松树枯。
虎迹印雪大如斗，闰月暮天过得无。','',''),('quantangshi-14776','送契玄法师赴内道场','盧綸','quantangshi','','卷15','昏昏醉老夫，灌顶遇醍醐。
嫔御呈心镜，君王赐髻珠。
降魔须战否，问疾敢行无。
深契何相秘，儒宗本不殊。','',''),('quantangshi-14777','送畅当赴山南幕','盧綸','quantangshi','','卷15','含情脱佩刀，持以佐贤豪。
是月霜霰下，伊人行役劳。
事将名共易，文与行空高。
去矣奉戎律，悲君为我曹。','',''),('quantangshi-14778','颜侍御厅丛篁咏送薛存诚','盧綸','quantangshi','','卷15','玉干百余茎，生君此堂侧。
拂帘寒雨响，拥砌深溪色。
何事凤皇雏，兹焉理归翼。','',''),('quantangshi-14779','秋晚河西县楼送浑中允赴朝阙','盧綸','quantangshi','','卷15','高楼吹玉箫，车马上河桥。
岐路自奔隘，壶觞终寂寥。
芳兰生贵里，片玉立清朝。
今日台庭望，心遥非地遥。','',''),('quantangshi-14780','达奚中丞东斋壁画山水各赋一物得树杪悬泉送长安赵元阳少府','盧綸','quantangshi','','卷15','素壁画飞泉，从云落树颠。
练垂疑叶响，云并觉枝偏。
利物得双劒，为儒当一贤。
应思洒尘陌，调膳亦芳鲜。','',''),('quantangshi-14781','送信州姚使君','盧綸','quantangshi','','卷15','朱幡徐转候羣官，猨鸟无声郡宇宽。
楚国上腴收赋重，汉家良牧得人难。
铜铅满穴山能富，鸿雁连羣地亦寒。
几日政声闻户外，九江行旅得相欢。','',''),('quantangshi-14782','送畅当','盧綸','quantangshi','','卷15','四望无极路，千里流大河。
秋风满离袂，唯老事唯多。','',''),('quantangshi-14783','送史兵曹判官赴楼烦','盧綸','quantangshi','','卷15','渥洼龙种散云时，千里繁花乍别离。
中有重臣承霈泽，外无轻虏犯旌旗。
山川自与郊坰合，帐幕时因水草移。
敢谢亲贤得琼玉，仲宣能赋亦能诗。','',''),('quantangshi-14784','送昙延法师讲罢赴上都','盧綸','quantangshi','','卷15','金缕架裟国大师，能销坏宅火烧时。
复来拥膝说无住，知向人天何处期。','',''),('quantangshi-14785','送道士郄彝素归内道场','盧綸','quantangshi','','卷15','病老正相仍，忽逢张道陵。
羽衣风淅淅，仙貌玉棱棱。
叱我问中寿，教人祈上升。
楼居五云里，几与武皇登。','',''),('quantangshi-14786','赋得彭祖楼送杨德宗归徐州幕','盧綸','quantangshi','','卷15','四户八窗明，玲珑逼上清。
外栏黄鹄下，中柱紫芝生。
每带云霞色，时闻箫管声。
望君兼有月，幢盖俨层城。','',''),('quantangshi-14787','送饯从叔辞丰州幕归嵩阳旧居','盧綸','quantangshi','','卷15','白须宗孙侍坐时，愿持寿酒前致词。
鄙词何所拟，请自边城始。
边城贵者李将军，战鼓遥疑天上闻。
屯田布锦周千里，牧马攒花溢万羣。
白云本是乔松伴，来遶青营复飞散。
三声画角咽不通，万里蓬根一时断。
丰州闻说似凉州，沙塞晴明部落稠。
行客已去依独戍，主人犹自在高楼。
梦亲旌斾何由见，每阻清风一回面。
洞里先生那怪迟，人天无路自无期。
砂泉丹井非同味，桂树榆林不并枝。
吾翁致身殊得计，地仙亦是三千岁。
莫着戎衣期上清，东方曼倩逢人轻。','',''),('quantangshi-14788','送静居法师','盧綸','quantangshi','','卷15','五色香幢重复重，宝舆升座发神钟。
薝卜名花飘不断，醍醐法味洒何浓。
九天论道当宸眷，七祖传心合圣踪。
愿比灵山前世别，多生还得此相逢。','',''),('quantangshi-14789','送刘判官赴丰州','盧綸','quantangshi','','卷15','衔杯吹急管，满眼起风砂。
大漠山沈雪，长城草发花。
策行须耻战，虏在莫言家。
余亦祈勋者，如何别左车。','',''),('quantangshi-14790','将赴京留献令公','盧綸','quantangshi','','卷15','沙鹤惊鸣野雨收，大河风物飒然秋。
力微恩重谅难报，不是行人不解愁。','',''),('quantangshi-14791','落第后归山下旧居留别刘起居昆季','盧綸','quantangshi','','卷15','寂寞过朝昏，沈忧岂易论。
有时空卜命，无事可酬恩。
寄食依邻里，成家望子孙。
风尘知世路，衰贱到君门。
醉里因多感，愁中欲强言。
花林逢废井，战地识荒园。
怅别临晴野，悲春上古原。
鸟归山外树，人过水边村。
潘岳方称老，嵇康本厌喧。
谁堪将落羽，回首仰飞翻。','',''),('quantangshi-14792','将赴阌乡灞上留别钱起员外','盧綸','quantangshi','','卷15','暖景登桥望，分明春色来。
离心自惆怅，车马亦裴回。
远雪和霜积，高花占日开。
从官竟何事，忧患已相催。','',''),('quantangshi-14793','虢州逢侯钊同寻南观因赠别','盧綸','quantangshi','','卷15','相见翻惆怅，应怜责废官。
过深慙禄在，识浅赖刑宽。
独失耕农业，同思弟侄欢。
衰贫羞客过，卑束会君难。
放鹤登云壁，浇花遶石坛。
兴远江海上，迹在是非端。
林密风声细，山高雨色寒。
悠然此中别，宾仆亦阑干。','',''),('quantangshi-14794','赴池州拜觐舅氏留上考功郎中舅','盧綸','quantangshi','','卷15','孤贱易磋砣，其如酷似何。
衰荣同族少，生长外家多。
别国桑楡在，沾衣血泪和。
应怜失行雁，霜霰寄烟波。','',''),('quantangshi-14795','送从侄滁州觐省','盧綸','quantangshi','','卷15','爱尔似龙媒，翩翩千里回。
书从外氏学，竹自晋时栽。
拥棹逢鸥舞，凭阑见雨来。
上堂多庆乐，不醉莫停杯。','',''),('quantangshi-14796','奉和圣制麟德殿宴百僚','盧綸','quantangshi','','卷15','云辟御筵张，山呼圣寿长。
玉栏丰瑞草，金陛立神羊。
台鼎资庖膳，天星奉酒浆。
蛮夷陪作位，犀象舞成行。
网已祛三面，歌因守四方。
千秋不可极，花发满宫香。','',''),('quantangshi-14797','和考功王员外杪秋忆终南旧居','盧綸','quantangshi','','卷15','静忆溪边宅，知君许谢公。
晓霜凝耒耜，初日照梧桐。
涧鼠喧藤蔓，山禽窜石藂。
白云当岭雨，黄叶遶堦风。
野果垂桥上，高泉落水中。
欢荣来自间，羸贱赏曾同。
月满珠藏海，天晴鹤在笼。
余阴如可寄，愿得隐墙东。','',''),('quantangshi-14798','酬畅当寻嵩岳麻道士见寄','盧綸','quantangshi','','卷15','闻逐樵夫闲看棋，忽逢人世是秦时。
开云种玉嫌山浅，渡海传书怪鹤迟。
阴洞石牀微有字，古坛松树半无枝。
烦君远示青囊箓，愿得相从一问师。','',''),('quantangshi-14799','酬李端长安寓居偶咏见寄','盧綸','quantangshi','','卷15','自别前峰隐，同为外累侵。
几年亲酒会，此日有僧寻。
学稼功还弃，论边事亦沈。
众欢徒满目，专爱久离心。
览鬓丝垂镜，弹琴泪洒襟。
访田悲洛下，寄宅忆山阴。
薄溜漫青石，横云架碧林。
坏檐藤障密，衰菜棘篱深。
流散俱多故，忧伤并在今。
唯当竢高躅，归止共抽簪。','',''),('quantangshi-14800','和常舍人晚秋集贤院即事十二韵寄赠江南徐薛二侍郎','盧綸','quantangshi','','卷15','纶阁九华前，森沈彩仗连。
洞门开旭日，清禁肃秋天。
霜满朝容备，钟余漏唱传。
摇璫陪羽扇，端弁入炉烟。
麟笔删金篆，龙绡荐玉编。
汲书荀勖定，汉史蔡邕专。
御竹潜通笋，宫池暗泻泉。
乱藂萦弱蕙，堕叶洒枯莲。
列署齐游日，重江并谪年。
登封思议草，侍讲忆同筵。
沧海风涛广，黝山瘴雨偏。
唯应缄上宝，赠远一呈妍。','',''),('quantangshi-14801','酬苗员外仲夏归郊居遇雨见寄','盧綸','quantangshi','','卷15','雷响风仍急，人归鸟亦还。
乱云方至水，骤雨已喧山。
田鼠依林上，池鱼戏草间。
因兹屏埃雾，一咏一开颜。','',''),('quantangshi-14802','和太常王卿立秋日即事','盧綸','quantangshi','','卷15','嵩高云日明，潘岳赋初成。
篱槿花无色，堦桐叶有声。
绛纱垂簟净，白羽拂衣轻。
鸿雁悲天远，龟鱼觉水清。
别弦添楚思，牧马动边情。
田雨农官问，林风苑吏惊。
松篁终茂盛，蓬艾自衰荣。
遥仰凭轩夕，惟应喜宋生。','',''),('quantangshi-14803','和李使君三郎早秋城北亭楼宴崔司士因寄关中弟张评事时遇','盧綸','quantangshi','','卷15','黄花古城路，上尽见青山。
桑柘晴川口，牛羊落照间。
野情随卷幔，军士隔重关。
道合偏多赏，官微独不闲。
鹤分琴久罢，书到雁应还。
为谢登龙客，琼枝寄一攀。','',''),('quantangshi-14804','和赵端公九日登石亭上和州家兄','盧綸','quantangshi','','卷15','洛浦想江津，悲懽共此辰。
采花湖岸菊，望国旧楼人。
雁别声偏苦，松寒色转新。
传书问渔叟，借寇尔何因。','',''),('quantangshi-14805','酬赵少尹戏示诸侄元阳等因以见赠','盧綸','quantangshi','','卷15','八龙三虎俨成行，琼树花开鹤翼张。
且请同观舞鸜鹆，何须竟哂食槟榔。
归时每爱怀朱橘，戏处常闻佩紫囊。
谬入阮家逢庆乐，竹林因得奉壶觞。','',''),('quantangshi-14806','奉和户曹叔夏夜寓直寄呈同曹诸公并见示','盧綸','quantangshi','','卷15','歛板捧清词，恭闻侍直时。
暮尘归众骑，邃宇舍诸司。
华月先灯至，清风与簟随。
乱萤光熠熠，行树影离离。
龙卧人宁识，鹏抟鷃岂知。
便因当五夜，敢望竹林期。','',''),('quantangshi-14807','和金吾裴将军使往河北宣慰因访张氏昆季旧居兼寄赵侍郎赵卿拜陵未回','盧綸','quantangshi','','卷15','飞轩不驻轮，感激汉儒臣。
气慑千夫勇，恩传万里春。
古原收野燎，寒笛怨空邻。
书此达良友，五陵风雨频。','',''),('quantangshi-14808','和太常李主簿秋中山下别墅即事','盧綸','quantangshi','','卷15','清秋来几时，宋玉已先知。
旷朗霞映竹，澄明山满池。
葺桥双鹤赴，收果众猨随。
韶乐方今奏，云林徒蔽亏。','',''),('quantangshi-14809','酬韦渚秋夜有怀见寄','盧綸','quantangshi','','卷15','萧条良夜永，秋草对衰颜。
露下鸟初定，月明人自闲。
独悲无旧业，共喜出时艰。
为问功成后，同游何处山。','',''),('quantangshi-14810','同吉中孚梦桃源 一','盧綸','quantangshi','','卷15','春雨夜不散，梦中山亦阴。
云中碧潭水，路暗红花林。
花水自深浅，无人知古今。','',''),('quantangshi-14811','同吉中孚梦桃源 二','盧綸','quantangshi','','卷15','夜静春梦长，梦逐仙山客。
园林满芝术，鸡犬傍篱栅。
几处花下人，看予笑头白。','',''),('quantangshi-14812','同柳侍郎题侯钊侍郎新昌里','盧綸','quantangshi','','卷15','清源君子居，左右尽图书。
三迳春自足，一飘欢有余。
庭莎成野席，阑药是家蔬。
幽显岂殊迹，昔贤徒病诸。','',''),('quantangshi-14813','酬孙侍御春日见寄','盧綸','quantangshi','','卷15','经过里巷春，同是谢家邻。
愿我觉衰早，荷君留醉频。
松高犹覆草，鹤起暂萦尘。
始悟达人志，患名非患贫。','',''),('quantangshi-14814','和王员外冬夜寓直','盧綸','quantangshi','','卷15','高步长裾锦帐郎，居然自是汉贤良。
潘岳叙年因鬓发，扬雄托谏在文章。
九天韶乐飘寒月，万户香尘裛晓霜。
坐见重门俨朝骑，可怜云路独翺翔。','',''),('quantangshi-14815','酬金部王郎中省中春日见寄','盧綸','quantangshi','','卷15','南宫树色晓森森，虽有春光未有阴。
鹤侣正疑芳景引，玉人那为簿书沈。
山含瑞气偏当日，莺逐轻风不在林。
更有阮郎迷路处，万株红树一溪深。','',''),('quantangshi-14816','奉和陕州十四翁中丞寄雷州二十翁司户','盧綸','quantangshi','','卷15','联飞独不前，迥落海南天。
贾傅竟行矣，邵公唯泫然。
瘴开山更远，路极水无边。
沈劣本多感，况闻原上篇。','',''),('quantangshi-14817','和李中丞酬万年房署少府过汾州景云观因以寄上房与李早年同居此观','盧綸','quantangshi','','卷15','显晦澹无迹，贤哉常晏如。
如何警孤鹤，忽乃传双鱼。
叙以泉石旧，怅然风景余。
低回青油幕，梦寐白云居。
玉洞桂香满，雪坛松影疎。
沈思瞩仙侣，纾组正军书。
积学早成道，感恩难遂初。
梅生谅多感，归止岂吾庐。','',''),('quantangshi-14818','酬陈翃郎中冬至携柳郎窦郎归河中旧居见寄','盧綸','quantangshi','','卷15','三旬一休沐，清景满林庐。
南郭羣儒从，东牀两客居。
烧烟浮雪野，麦陇润冰渠。
班白皆持酒，蓬茅尽有书。
终期买寒渚，同此利蒲鱼。','',''),('quantangshi-14819','酬李益端公夜宴见赠','盧綸','quantangshi','','卷15','戚戚一西东，十年今始同。
可怜歌酒夜，相对两衰翁。','',''),('quantangshi-14820','和陈翃郎中拜本府少尹兼侍御史献上侍中因呈同院诸公','盧綸','quantangshi','','卷15','金印垂鞍白马肥，不同疏广老方归。
三千士里文章伯，四十年来锦绣衣。
节比青松当涧直，心随黄雀绕檐飞。
乡中贺者唯争路，不识传呼獬豸威。','',''),('quantangshi-14821','和王仓少尹暇日言怀','盧綸','quantangshi','','卷15','清秋多暇日，况乃是夫君。
习静通仙事，书空阅篆文。
劒飞终上汉，鹤梦不离云。
无限烟霄路，何嗟迹未分。','',''),('quantangshi-14822','和崔侍郎游万固寺','盧綸','quantangshi','','卷15','闻说中方高树林，曙华先照啭春禽。
风云才子冶游思，蒲柳老人惆怅心。
石路青苔花漫漫，雪檐垂溜玉森森。
贺君此去君方至，河水东流西日沈。','',''),('quantangshi-14823','和裴延龄尚书寄题果州谢舍人仙居','盧綸','quantangshi','','卷15','飘然去谒八仙翁，自地从天香满空。
紫盖迥标双鹤上，语音犹在五云中。
青溪不接渔樵路，丹井唯传草木风。
歌此因思捧金液，露盘长庆汉皇宫。','',''),('quantangshi-14824','酬崔侍御早秋卧病书情见寄时君亦抱疾在假中','盧綸','quantangshi','','卷15','掷地金声信有之，莹然冰玉见清词。
元凯癖成官始贵，相如渴甚貌逾衰。
荒园每觉虫鸣早，华馆常闻客散迟。
寂寞罢琴风满树，几多黄叶落蛛丝。','',''),('quantangshi-14825','酬灵澈上人','盧綸','quantangshi','','卷15','军人奉役本无期，落叶花开总不知。
走马城中头雪白，若为将面见汤师。','',''),('quantangshi-14826','敬酬大府二十四舅览诗卷因以见示','盧綸','quantangshi','','卷15','郄公怜戆亦怜愚，忽赠金盘径寸珠。
彻底碧潭滋涸溜，压枝红艳照枯株。
九门洞启延高论，百辟联行挹大儒。
顾己文章非酷似，敢将幽劣俟洪炉。','',''),('quantangshi-14827','雨中酬友人','盧綸','quantangshi','','卷15','看山独行归竹院，水遶前堦草生遍。
空林细雨暗无声，唯有愁心两相见。','',''),('quantangshi-14828','酬人失题','盧綸','quantangshi','','卷15','孤鸾将鹤羣，晴日丽春云。
何幸晚飞者，清音长此闻。','',''),('quantangshi-14829','哭司农苗主簿','盧綸','quantangshi','','卷15','原头殡御遶新茔，原下行人望哭声。
更想秋山连古木，唯应石上见君名。','',''),('quantangshi-14830','得耿湋司法书因叙长安故友零落兵部苗员外发祕省李校书端相次倾逝潞府崔功曹峒长林司空丞曙俱谪远方余以摇落之时对书增叹因呈河中郑仓曹畅参军昆季','盧綸','quantangshi','','卷15','鬓似衰蓬心似灰，惊悲相集老相催。
故友九泉留语别，逐臣千里寄书来。
尘容带病何堪问，泪眼逢秋不喜开。
幸接野居宜屣步，冀君清夜一申哀。','',''),('quantangshi-14831','同兵部李纾侍郎刑部包佶侍郎哭皇甫侍御曾','盧綸','quantangshi','','卷15','攀龙与泣麟，哀乐不同尘。
九陌霄汉侣，一灯冥漠人。
舟沈惊海阔，兰折怨霜频。
已矣复何见，故山应更春。','',''),('quantangshi-14832','纶与吉侍郎中孚司空郎中曙苗员外发崔补阙峒耿拾遗湋李校书端风尘追游向三十载数公皆负当时盛称荣耀未几俱沈下泉畅博士当感怀前踪有五十韵见寄輙有所酬以申悲旧兼寄夏侯侍御审侯仓曹钊','盧綸','quantangshi','','卷15','禀命孤且贱，少为病所婴。
八岁始读书，四方遂有兵。
童心幸不羁，此去负平生。
是月胡入洛，明年天陨星。
夜行登灞陵，惝怳靡所征。
云海一翻荡，鱼龙俱不宁。
因浮襄江流，远寄鄱阳城。
鄱阳富学徒，诮我戆无营。
谕以诗礼义，朂随宾荐名。
舟车更滞留，水陆互阴晴。
晓望怯云阵，夜愁惊鹤声。
凄凄指宋郊，浩浩入秦京。
沴气既风散，皇威如日明。
方逢粟比金，未识公与卿。
十上不可待，三年竟无成。
偶为达者知，扬我于王廷。
素志且不立，青袍徒见萦。
昏孱夙自保，静躁本殊形。
始趋甘棠阴，旋遇密人迎。
考实绩无取，责能才固轻。
新丰古离宫，宫树锁云扃。
中复莅兹邑，往惟曾所经。
缭垣何逶迤，水殿亦峥嵘。
夜雨滴金砌，阴风吹玉楹。
官曹虽检率，国步日夷平。
命蹇固安分，祸来非有萌。
因逢骇浪飘，几落无辜刑。
巍巍登坛臣，独正天柱倾。
悄悄失途子，分将秋草并。
百年甘守素，一顾乃拾青。
相逢十月交，众卉飘已零。
感旧谅戚戚，问孤恳茕茕。
侍郎文章宗，杰出淮楚灵。
掌赋若吹籁，司言如建瓴。
郎中善余庆，雅韵与琴清。
郁郁松带雪，萧萧鸿入冥。
员外真贵儒，弱冠被华缨。
月香飘桂实，乳溜滴琼英。
补阙思冲融，巾拂艺亦精。
彩蝶戏芳圃，瑞云凝翠屏。
拾遗兴难侔，逸调旷无程。
九酝贮弥洁，三花寒转馨。
校书才智雄，举世一娉婷。
赌墅鬼神变，属词鸾凤惊。
差肩曳长裾，总辔奉和铃。
共赋瑶台雪，同观金谷筝。
倚天方比劒，沈井忽如瓶。
神昧不可问，天高莫尔听。
君持玉盘珠，泻我怀袖盈。
读罢涕交颐，愿言跻百龄。','',''),('quantangshi-14833','酬李叔度秋夜喜相遇因伤关东僚友丧逝见赠','盧綸','quantangshi','','卷15','寒月照秋城，秋风泉涧鸣。
过时见兰蕙，独夜感衰荣。
酒散同移疾，心悲似远行。
以愚求作友，何德敢称兄。
谷变波长急，松枯药未成。
恐看新鬓色，怯问故人名。
野泽云阴散，荒原日气生。
羁飞本难定，非是恶弦惊。','',''),('quantangshi-14834','同李益伤秋','盧綸','quantangshi','','卷15','岁去人头白，秋来树叶黄。
搔头向黄叶，与尔共悲伤。','',''),('quantangshi-14835','白发叹','盧綸','quantangshi','','卷15','发白晓梳头，女惊妻泪流。
不知丝色后，堪得几回秋。','',''),('quantangshi-14836','逢病军人','盧綸','quantangshi','','卷15','行多有病住无粮，万里还乡未到乡。
蓬鬓哀吟古城下，不堪秋气入金疮。','',''),('quantangshi-14837','村南逢病叟','盧綸','quantangshi','','卷15','双膝过颐顶在肩，四邻知姓不知年。
卧驱鸟雀惜禾黍，犹恐诸孙无社钱。','',''),('quantangshi-14838','七夕诗','盧綸','quantangshi','','卷15','祥光若可求，闺女夜登楼。
月露浩方下，河云凝不流。
铅华潜警曙，机杼暗传秋。
回想歛余睠，人天俱是愁。','',''),('quantangshi-14839','七夕诗','盧綸','quantangshi','','卷15','凉风吹玉露，河汉有幽期。
星彩光仍隐，云容掩复离。
良宵惊曙早，闰岁怨秋迟。
何事金闺子，空传得网丝。','',''),('quantangshi-14840','长门怨','盧綸','quantangshi','','卷15','空空古廊殿，寒月落斜晖。
卧听未央曲，满箱歌舞衣。','',''),('quantangshi-14841','妾薄命','盧綸','quantangshi','','卷15','妾年初二八，两度嫁狂夫。
薄命今犹在，坚贞扫地无。','',''),('quantangshi-14842','伦开府席上赋得咏美人名解愁','盧綸','quantangshi','','卷15','不敢苦相留，明知不自由。
嚬眉乍欲语，歛笑又低头。
舞态兼些醉，歌声似带羞。
今朝总见也，只不解人愁。','',''),('quantangshi-14843','王评事驸马花烛诗 一','盧綸','quantangshi','','卷15','万条银烛引天人，十月长安半夜春。
步障三千隘将断，几多珠翠落香尘。','',''),('quantangshi-14844','王评事驸马花烛诗 二','盧綸','quantangshi','','卷15','一人女壻万人怜，一夜调疎抵百年。
为报司徒好将息，明珠解转又能圆。','',''),('quantangshi-14845','王评事驸马花烛诗 三','盧綸','quantangshi','','卷15','人主人臣是亲家，千秋万岁保荣华。
几时曾向高天上，得见今宵月里花。','',''),('quantangshi-14846','王评事驸马花烛诗 四','盧綸','quantangshi','','卷15','比翼和鸣双凤皇，欲栖金帐满城香。
平明却入天泉里，日气曈昽五色光。','',''),('quantangshi-14847','和赵给事白蝇拂歌','盧綸','quantangshi','','卷15','华堂多众珍，白拂称殊异。
柄裁沈节香袭人，上结为文下垂穗。
霜缕霏微莹且柔，虎须乍细龙髯稠。
皎然素色不因染，淅尔凉风非为秋。
羣蝇青苍恣游息，广庖万品无颜色。
金屏成点玉成瑕，昼眠宛转空咨嗟。
此时满筵看一举，荻花忽旋杨花舞。
砉如寒隼惊暮禽，飒若繁埃得轻雨。
主人说是故人留，每诫如新比白头。
若将挥玩闲临水，愿接波中一白鸥。','',''),('quantangshi-14848','萧常侍瘿柏亭歌','盧綸','quantangshi','','卷15','柏之异者山中灵，何人断绝为君亭。
云翻浪卷不可识，鸟兽成形花倒植。
莓苔旧点色尚青，霹雳残痕节犹黑。
金貂主人汉三老，构此穷年下朝早。
心规目制不暂疲，匠者受之无一词。
清晨拂匣菱生镜，落日凭阑星满池。
攒甍鬬拱无斤迹，根瘿联悬同素壁。
数层乱泻云里峯，万片争呈雪中石。
重帘不动自飘香，似到瀛洲白玉堂。
水精如意刁金色，云母屏风透掩光。
四堦绵绵被纤草，草上依微众山道。
松间汲井烟翠寒，洞里围碁天景好。
愚儒敢欲贺成功，鸾凤栖翔固不同。
应念废材今接地，一枝思寄户庭中。','',''),('quantangshi-14849','慈恩寺石磬歌','盧綸','quantangshi','','卷15','灵山石磬生海西，海涛平处与山齐。
长眉老僧同佛力，呪使鲛人往求得。
珠穴沈成绿浪痕，天衣拂尽苍苔色。
星汉徘徊山有风，禅翁静扣月明中。
羣仙下云龙出水，鸾鹤交飞半空里。
山精木魅不可听，落叶秋砧一时起。
花宫杳杳响泠泠，无数沙门昏梦醒。
古廊灯下见行道，疎林池边闻诵经。
徒壮洪钟祕高阁，万金费尽工雕凿。
岂如全质挂青松，数叶残云一片峯。
吾师宝之寿中国，愿同劫石无终极。','',''),('quantangshi-14850','送张郎中还蜀歌','盧綸','quantangshi','','卷15','秦家御史汉家郎，亲专两印征殊方。
功成走马朝天子，伏槛论边若流水。
晓离仙署趋紫微，夜接高儒读青史。
泸南五将望君还，愿以天书示百蛮。
曲栈重江初过雨，前旌后骑不同山。
迎车拜舞多耆老，旧卒新营遍青草。
塞口云生火候迟，烟中鹤唳军行早。
黄花川下水交横，远映孤霞蜀国晴。
邛竹笋长椒瘴起，荔枝花发杜鹃鸣。
回首岷峨半天黑，传觞接膝何由得。
空令豪士仰威名，无复贫交恃颜色。
垂杨不动雨纷纷，锦帐胡瓶争送君。
须臾醉起箫笳发，空见红旌入白云。','',''),('quantangshi-14851','宴席赋得姚美人拍筝歌','盧綸','quantangshi','','卷15','出帘仍有钿筝随，见罢翻令恨识迟。
微收皓腕缠红袖，深遏朱弦低翠眉。
忽然高张应繁节，玉指回旋若飞雪。
凤箫韶管寂不喧，绣幕纱窗俨秋月。
有时轻弄和郎歌，慢处声迟情更多。
已愁红脸能佯醉，又恐朱门难再过。
昭阳伴里最聪明，出到人间才长成。
遥知禁曲难翻处，犹是君王说小名。','',''),('quantangshi-14852','陈翃郎中北亭送侯钊侍御赋得带冰流歌','盧綸','quantangshi','','卷15','溪中鸟鸣春景旦，一派寒冰忽开散。
璧方镜员流不断，白云鳞鳞满河汉。
叠处浅，旋处深。
撇捩寒鱼上复沈，羣鹅鼓舞扬清音。
主人有客簪白笔，玉壶贮水光如一。
持此赠君君饮之，圣君识君冰玉姿。','',''),('quantangshi-14853','栖岩寺隋文帝马脑盏歌','盧綸','quantangshi','','卷15','天宫宝器隋朝物，鏁在金函比金骨。
开函捧之光乃发，阿修罗王掌中月。
五云如拳轻复浓，昔曾噀酒今藏龙。
规形环影相透彻，乱雪繁花千万重。
可怜贞质无今名，可叹隋陵一抱土。
宫中艳女满宫春，得亲此宝能几人。
一留寒殿殿将坏，唯有幽光通隙尘。
山中老僧眉似雪，忍死相传保扃鐍。','',''),('quantangshi-14854','难绾刀子歌','盧綸','quantangshi','','卷15','黄金鞘里青芦叶，丽若翦成銛且翣。
轻冰薄玉状不分，一尺寒光堪决云。
吹毛可试不可触，似有虫搜阙裂文。
淬之几堕前池水，焉知不是蛟龙子。
割鸡刺虎皆若空，愿应君心逐君指。
并州难绾竟何人，每成此物如有神。','',''),('quantangshi-14855','腊日观咸宁王部曲娑勒擒豹歌','盧綸','quantangshi','','卷15','山头曈曈日将出，山下猎围照初日。
前林有兽未识名，将军促骑无人声。
潜形踠伏草不动，双雕旋转羣鸦鸣。
阴方质子才三十，译语受词蕃语揖。
舍鞍解甲疾如风，人忽虎蹲兽人立。
歘然扼颡批其颐，爪牙委地涎淋漓。
既苏复吼拗仍怒，果叶英谋生致之。
拖自深丛目如电，万夫失容千马战。
传呼贺拜声相连，杀气腾凌阴满川。
始知缚虎如缚鼠，败虏降羌生眼前。
祝尔嘉词尔无苦，献尔将随犀象舞。
苑中流水禁中山，期尔攫搏开天颜。
非熊之兆庆无极，愿纪雄名传百蛮。','',''),('quantangshi-14856','赋得白鸥歌送李伯康归使','盧綸','quantangshi','','卷15','积水深源，白鸥翻翻。
倒影光素，于潭之间。
衔鱼鱼落乱惊鸣，争扑莲藂莲叶倾。
尔不见波中鸥鸟闲无营，何必汲汲劳其生。
柳花冥蒙大堤口，悠扬相和乍无有。
轻随去浪杳不分，细舞清风亦何有。
似君换得白鹅时，独凭阑干雪满池。
今日还同看鸥鸟，如何羽翮复参差。
复参差，海涛澜漫何由期。','',''),('quantangshi-14857','皇帝感词 一','盧綸','quantangshi','','卷15','提劒风雷动，垂衣日月明。
禁花呈瑞色，国老见星精。
发棹鱼先跃，窥巢鸟不惊。
山呼一万岁，直入九重城。','',''),('quantangshi-14858','皇帝感词 二','盧綸','quantangshi','','卷15','天香五凤彩，御马六龙文。
雨露清驰道，风雷翊上军。
高旍花外转，行漏乐前闻。
时见金鞭举，空中指瑞云。','',''),('quantangshi-14859','皇帝感词 三','盧綸','quantangshi','','卷15','妙算干戈止，神谋宇宙清。
两堦文物盛，七德武功成。
校猎长杨苑，屯军细柳营。
归来献明主，歌舞溢春城。','',''),('quantangshi-14860','皇帝感词 四','盧綸','quantangshi','','卷15','天乐下天中，云輧俨在空。
铅黄艳河汉，笑语合笙镛。
已见长随凤，仍闻不避熊。
君王亲试舞，阊阖静无风。','',''),('quantangshi-14861','天长久词 一','盧綸','quantangshi','','卷15','玉砌红花树，香风不敢吹。
春光解天意，偏发殿南枝。','',''),('quantangshi-14862','天长久词 二','盧綸','quantangshi','','卷15','虹桥千步廊，半在水中央。
天子方清暑，宫娃起夜妆。','',''),('quantangshi-14863','天长久词 三','盧綸','quantangshi','','卷15','辞辇复当熊，倾心奉六宫。
君王若看貌，甘在众妃中。','',''),('quantangshi-14864','天长久词 四','盧綸','quantangshi','','卷15','云日呈祥礼物殊，彤庭生献五单于。
塞垣万里无飞鸟，可是边城用郅都。','',''),('quantangshi-14865','天长久词 五','盧綸','quantangshi','','卷15','台殿云深秋色微，君王初赐六宫衣。
楼船泛罢归犹早，行遣才人鬬射飞。','',''),('quantangshi-14866','和张仆射塞下曲 一','盧綸','quantangshi','','卷15','鹫翎金仆姑，燕尾绣蝥弧。
独立扬新令，千营共一呼。','',''),('quantangshi-14867','和张仆射塞下曲 二','盧綸','quantangshi','','卷15','林暗草惊风，将军夜引弓。
平明寻白羽，没在石棱中。','',''),('quantangshi-14868','和张仆射塞下曲 三','盧綸','quantangshi','','卷15','月黑雁飞高，单于夜遁逃。
欲将轻骑逐，大雪满弓刀。','',''),('quantangshi-14869','和张仆射塞下曲 四','盧綸','quantangshi','','卷15','野幕敞琼筵，羌戎贺劳旋。
醉和金甲舞，雷鼓动山川。','',''),('quantangshi-14870','和张仆射塞下曲 五','盧綸','quantangshi','','卷15','调箭又呼鹰，俱闻出世能。
奔狐将迸雉，扫尽古丘陵。','',''),('quantangshi-14871','和张仆射塞下曲 六','盧綸','quantangshi','','卷15','亭亭七叶贵，荡荡一隅清。
他日题麟阁，唯应独不名。','',''),('quantangshi-14872','古艳诗 一','盧綸','quantangshi','','卷15','残妆色浅髻鬟开，笑映朱帘覰客来。
推醉谁知弄花钿，潘郎不敢使人催。','',''),('quantangshi-14873','古艳诗 二','盧綸','quantangshi','','卷15','自拈裙带结同心，暖处偏知香气深。
爱捉狂夫问闲事，不知歌舞用黄金。','',''),('quantangshi-14874','孤松吟酬浑赞善','盧綸','quantangshi','','卷15','深山荒松枝，雪压半离披。
朱门青松树，万叶承清露。
露重色逾鲜，吟风似远泉。
天寒香自发，日丽影常圆。
阴郊一夜雪，榆柳皆枯折。
回首望君家，翠盖满琼花。
捧君青松曲，自顾同衰木。
曲罢不相亲，深山头白人。','',''),('quantangshi-14875','从军行','盧綸','quantangshi','','卷15','二十在边城，军中得勇名。
卷旗收败马，占碛拥残兵。
覆阵乌鸢起，烧山草木明。
塞闲思远猎，师老厌分营。
雪岭无人迹，冰河足雁声。
李陵甘此没，惆怅汉公卿。','',''),('quantangshi-14876','和马郎中画鹤赞','盧綸','quantangshi','','卷15','高高华亭，有鹤在屏。
削玉点漆，乘轩姓丁。
暮云冥冥，双垂雪翎。
晨光炯炯，一直朱顶。
含音俨容，绝粒遗影。
君以为真，相期缑岭。','',''),('quantangshi-14877','送朝长史赴荆南旧幕','盧綸','quantangshi','','卷15','元瑜思旧幕，几夜梦旌旃。
暑退蒹葭雨，秋生鼓角天。
月明三峡路，浪里九江船。
囗囗囗囗囗，囗囗囗囗囗。','',''),('quantangshi-14878','送渭南崔少府归徐郎中幕','盧綸','quantangshi','','卷15','叶下山边路，行人见自悲。
夜寒逢雪处，日暖到村时。
语少心常苦，愁深醉自迟。
囗囗囗囗囗，羡有幕中期。','',''),('quantangshi-14879','寄郑七纲','盧綸','quantangshi','','卷15','小来落托复迍邅，一辱君知二十年。
舍去形骸容傲慢，引随兄弟共团圆。
羁游不定同云聚，薄宦相萦若网牵。
他日吴公如记问，愿将黄绶比青毡。','',''),('quantangshi-14880','逢南中使因寄岭外故人','盧綸','quantangshi','','卷15','见说南来处，苍梧接桂林。
过秋天更暖，边海日长阴。
巴路缘云出，蛮乡入洞深。
信回人自老，梦到月应沈。
碧水通春色，青山寄远心。
炎方难久客，为尔一沾襟。','',''),('quantangshi-14881','代员将军罢战后归旧里赠朔北故人','盧綸','quantangshi','','卷15','结发事疆场，全生俱到乡。
连云防铁岭，同日破渔阳。
牧马胡天晚，移军碛路长。
枕戈眠古戍，吹角立繁霜。
归老勋仍在，酬恩虏未亡。
独行过邑里，多病对农桑。
雄劒依尘橐，阴符寄药囊。
空余麾下将，犹逐羽林郎。','',''),('quantangshi-14882','江北忆崔汶','盧綸','quantangshi','','卷15','夜问江西客，还知在楚乡。
全身出部伍，尽室逐渔商。
晴日游瓜步，新年对汉阳。
月昏惊浪白，瘴起觉云黄。
望岭家何处，登山泪几行。
闽中传有雪，应且住南康。','',''),('quantangshi-14883','早春归盩厔旧居却寄耿拾遗湋李校书端','盧綸','quantangshi','','卷15','野日初晴麦壠分，竹园相接鹿成羣。
几家废井生青草，一树繁花傍古坟。
引水忽惊冰满涧，向田空见石和云。
可怜荒岁青山下，惟有松枝好寄君。','',''),('quantangshi-14884','春日山中忆崔峒吉中孚','盧綸','quantangshi','','卷15','延步爱清晨，空山日照春。
蜜房那有主，石室自无邻。
泉急鱼依藻，花繁鸟近人。
谁言失徒侣，唯与老相亲。','',''),('quantangshi-14885','客舍喜崔补阙司空拾遗访宿','盧綸','quantangshi','','卷15','步月访诸邻，蓬居宿近臣。
乌裘先醉客，清镜早朝人。
坏壁烟垂网，香街火照尘。
悲荣俱是分，吾亦乐吾贫。','',''),('quantangshi-14886','苦雨闻包谏议欲见访戏赠','盧綸','quantangshi','','卷15','草气厨烟咽不开，绕牀连壁尽生苔。
常时多病因多雨，那敢烦君车马来。','',''),('quantangshi-14887','客舍苦雨即事寄钱起郎士元二员外','盧綸','quantangshi','','卷15','积雨暮凄凄，羁人状鸟栖。
响空宫树接，覆水野云低。
穴蚁多随草，巢蜂半坠泥。
遶池墙藓合，拥溜瓦松齐。
旧圃平如海，新沟曲似溪。
坏阑留众蝶，欹栋止羣鸡。
莠盛终无实，槎枯返有荑。
绿萍藏废井，黄叶隐危堤。
闾里欢将绝，朝昏望亦迷。
不知霄汉侣，何路可相携。','',''),('quantangshi-14888','郊居对雨寄赵涓给事包佶郎中','盧綸','quantangshi','','卷15','暑雨青山里，随风到野居。
乱沤浮曲砌，悬溜响前除。
尘镜愁多掩，蓬头嬾更梳。
夜窗凄枕席，阴壁润图书。
萧飒宜新竹，龙钟拾野蔬。
石泉空自咽，药圃不堪锄。
浊水淙深辙，荒兰拥败渠。
繁枝留宿鸟，碎浪出寒鱼。
桑屐时登望，荷衣自卷舒。
应怜在泥滓，无路托高车。','',''),('quantangshi-14889','蓝溪期萧道士采药不至','盧綸','quantangshi','','卷15','春风生百药，几处术苗香。
人远花空落，溪深日复长。
病多知药性，老近忆仙方。
清节何由见，三山桂自芳。','',''),('quantangshi-14890','雪谤后书事上皇甫大夫','盧綸','quantangshi','','卷15','盛德总羣英，高标仰国桢。
独安巡狩日，曾掩赵张名。
业就难辞宠，朝回更授兵。
晓川分牧马，夜雪覆连营。
长策威殊俗，嘉谋翊圣明。
画图规阵势，梦笔纪山行。
绶拂池中影，珂摇竹外声。
赐欢征妓乐，陪醉问公卿。
却忆经前事，翻疑得此生。
分深存没感，恩在子孙荣。
览镜愁将老，扪心喜复惊。
岂言沈族重，但觉杀身轻。
有泪沾坟典，无家集弟兄。
东西遭世难，流浪识交情。
阅古宗文举，推才慕正平。
应怜守贫贱，又欲事躬耕。','',''),('quantangshi-14891','春日忆司空文明','盧綸','quantangshi','','卷15','桃李风多日欲阴，百劳飞处落花深。
贫居静久难逢信，知隔春山不可寻。','',''),('quantangshi-14892','卧病寓居龙兴观枉冯十七着作书知罢摄洛阳赴缑氏因题十四韵寄冯生并赠乔尊师','盧綸','quantangshi','','卷15','乞假依山宅，蹉跎属岁周。
弱荑轻采拾，钝质称归休。
潘岳衰将至，刘桢病未瘳。
步迟乘羽客，起晏滞书邮。
幸以编方验，终贻骨肉忧。
灼龟炉气冷，曝药树阴稠。
语命心堪醉，伤离梦亦愁。
荤膻居已绝，鸾鹤见无由。
世累如尘积，年光剧水流。
蹑云知有路，济海岂无舟。
倚玉翻成难，投砖敢望酬。
卑栖君就禄，羸惫我逢秋。
腐叶填荒辙，阴萤出古沟。
依然在遐想，愿子励风猷。','',''),('quantangshi-14893','秋夜寄冯着作','盧綸','quantangshi','','卷15','河汉净无云，鸿声此夜闻。
素心难比石，苍鬓欲如君。
露槿月中落，风萤池上分。
何言千载友，同迹不同羣。','',''),('quantangshi-14894','洛阳早春忆吉中孚校书司空曙主簿因寄清江上人','盧綸','quantangshi','','卷15','值迥逢高驻马频，雪晴闲看洛阳春。
莺声报远同芳信，柳色邀欢似故人。
酒貌昔将花共艳，鬓毛今与草争新。
年来百事皆无绪，唯与汤师结净因。','',''),('quantangshi-14895','偶逢姚校书凭附书达河南郄推官因以戏赠','盧綸','quantangshi','','卷15','寄书常切到常迟，今日凭君君莫辞。
若问玉人殊易识，莲花府里最清羸。','',''),('quantangshi-14896','夜中得循州赵司马侍郎书因寄回使','盧綸','quantangshi','','卷15','瘴海寄双鱼，中宵达我居。
两行灯下泪，一纸岭南书。
地说炎蒸极，人称老病余。
殷勤报贾傅，莫共酒杯疎。','',''),('quantangshi-14897','晚次新丰北野老家书事呈赠韩质明府','盧綸','quantangshi','','卷15','机鸣舂响日暾暾，鸡犬相和汉古村。
数派清泉黄菊盛，一林寒露紫棃繁。
衰翁正席矜新社，稚子齐襟读古论。
共说年来但无事，不知何者是君恩。','',''),('quantangshi-14898','书情上大尹十兄','盧綸','quantangshi','','卷15','紫陌绝纤埃，油幢千骑来。
剖辞纷若雨，犇吏殷成雷。
圣泽初忧壅，羣心本在台。
海鳞方泼刺，云翼暂徘徊。
芳室芝兰茂，春蹊桃李开。
江湖余派少，鸿雁远声哀。
命厌蓍龟诱，年惊弟侄催。
磨铅慙砥砺，挥策愧驽骀。
玉管能喧谷，金炉可变灰。
应怜费思者，衔泪亦衔枚。','',''),('quantangshi-14899','春思贻李方陵','盧綸','quantangshi','','卷15','长安三月春，难别复难亲。
不识冶游伴，多逢憔悴人。
渐知欢澹薄，转觉老殷勤。
去矣尽如此，此辞悲未陈。','',''),('quantangshi-14900','驿中望山戏赠渭南陆贽主簿','盧綸','quantangshi','','卷15','官微多惧事多同，拙性偏无主驿功。
山在门前登不得，鬓毛衰尽路尘中。','',''),('quantangshi-14901','太白西峯偶宿车祝二尊师石室晨登前巘凭眺书怀即事寄呈凤翔齐员外张侍御','盧綸','quantangshi','','卷15','弱龄诚昧鄙，遇胜惟求止。
如何羁滞中，得步青冥里。
青冥有桂藂，冰雪两仙翁。
毛节未归海，丹梯闲倚空。
逍遥拟上清，洞府不知名。
醮罢雨雷至，客辞山忽明。
山明鸟声乐，日气生嵓壑。
嵓壑树修修，白云如水流。
白云消散尽，陇塞俨然秋。
积阻关河固，绵联烽戍稠。
五营承庙略，四野失边愁。
吁嗟系尘役，又负灵仙迹。
芝术自芳香，泥沙几沈溺。
书此欲沾衣，平生事每违。
烟霄不可仰，鸾鹤自追随。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-14902','赠韩山人','盧綸','quantangshi','','卷15','见君何事不慙颜，白发生来未到山。
更叹无家又无药，往来唯在酒徒间。','',''),('quantangshi-14903','赠李果毅','盧綸','quantangshi','','卷15','向日磨金镞，当风着锦衣。
上城邀贼语，走马截雕飞。','',''),('quantangshi-14904','春日书情赠别司空曙','盧綸','quantangshi','','卷15','壮志随年尽，谋身意未安。
风尘交契阔，老大别离难。
腊近晴多暖，春迟夜却寒。
谁堪少兄弟，三十又无官。','',''),('quantangshi-14905','冬晓呈邻里','盧綸','quantangshi','','卷15','终夜寝衣冷，开门思曙光。
空堦一藂叶，华室四邻霜。
望阙觉天迥，忆山愁路荒。
途中一留滞，双鬓飒然苍。','',''),('quantangshi-14906','首冬寄河东昭德里书事贻郑损仓曹','盧綸','quantangshi','','卷15','清冬和暖天，老钝昼多眠。
日爱闾巷静，每闻官吏贤。
寒葅供家食，腐叶宿厨烟。
且复执杯酒，无烦轻议边。','',''),('quantangshi-14907','浑赞善东斋戏赠陈归','盧綸','quantangshi','','卷15','长裾珠履飒轻尘，闲以琴书列上宾。
公子无讐可邀请，侯嬴此坐是何人。','',''),('quantangshi-14908','春日卧病示赵季黄','盧綸','quantangshi','','卷15','病中饶泪眼常昏，闻说花开亦闭门。
语少渐知琴思苦，卧多唯觉鸟声喧。
黄埃满市图书贱，黑雾连山虎豹尊。
今日支离顾形影，向君凡在几重恩。','',''),('quantangshi-14909','秋幕中夜独坐迟明因陪陈翃郎中晨谒上公因书即事兼呈同院诸公','盧綸','quantangshi','','卷15','风凄露泫然，明月在山巅。
独倚古庭树，仰看深夜天。
叶翻萤不定，虫思草无边。
南舍机杼发，东方云景鲜。
簪裘肃已整，车骑俨将前。
百雉拱双戟，万夫尊一贤。
琳琅多谋蕴，律吕更相宣。
晓桂香浥露，新鸿晴满川。
熙熙造化功，穆穆唐尧年。
顾己草同贱，誓心金匪坚。
蹇辞慙自寡，渴病老难痊。
书此更何问，边韶唯昼眠。','',''),('quantangshi-14910','寄赠库部王郎中','盧綸','quantangshi','','卷15','谔谔汉名臣，从天令若春。
叙辞皆诏旨，称宦即星辰。
草木承风偃，云雷施泽均。
威惩治粟尉，恩洽让田人。
泉货方将散，京坻自此陈。
五营俱益竈，千里不停轮。
未远金门籍，旋清玉塞尘。
硕儒推庆重，良友颂公频。
鹤发逢新镜，龙门跃旧鳞。
荷君偏有问，深感浩难申。','',''),('quantangshi-14911','寄赠畅当山居','盧綸','quantangshi','','卷15','古村荒石路，岁晏独言归。
山雪厚三尺，社楡麄十围。
虬龙宁守蛰，鸾鹤岂矜飞。
君子固安分，毋听劳者讥。','',''),('quantangshi-14912','偶宿山中忆畅当','盧綸','quantangshi','','卷15','深山夜雪晴，坐忆晓山明。
读易罢三卷，弹琴当五更。
薜萝枯有影，嵓壑冻无声。
此夕一相望，君应知我诚。','',''),('quantangshi-14913','秋中野望寄舍弟绶兼令呈上西川尚书舅','盧綸','quantangshi','','卷15','忧来思远望，高处殊非惬。
夜露湿苍山，秋陂满黄叶。
人随雁迢遰，栈与云重叠。
骨肉暂分离，形神遂疲薾。
红旌渭阳骑，几日劳登涉。
蜀道蔼松筠，巴江盛舟檝。
小生即何限，简诲偏盈箧。
旧恨尚填膺，新悲复萦睫。
因求种瓜利，自喜归耕捷。
井臼赖依邻，儿童亦胜汲。
尘容不在照，雪鬓那堪镊。
唯有飡霞心，知夫与天接。','',''),('quantangshi-14914','行药前轩呈董山人','盧綸','quantangshi','','卷15','不觉老将至，瘦来方自惊。
朝昏多病色，起坐有劳声。
腠暖苦肌痒，藏虚唯耳鸣。
桑公富灵术，一为保余生。','',''),('quantangshi-14915','翫春因寄冯衞二补阙戏呈李益','盧綸','quantangshi','','卷15','掖垣春色自天来，红药当堦次第开。
萱草藂藂尔何物，等闲穿破绿莓苔。','',''),('quantangshi-14916','新移北厅因贻同院诸公兼呈畅博士','盧綸','quantangshi','','卷15','华轩迩台座，顾影忝时伦。
弱质偃弥旷，清风来亦频。
恩辉坐凌迈，景物恣芳新。
终乃愧吾友，无容私此身。','',''),('quantangshi-14917','与张擢对酌','盧綸','quantangshi','','卷15','张翁对卢叟，一榼山村酒。
倾酒请予歌，忽蒙张翁呵。
呵予官非屈，曲有怨词多。
歌罢谢张翁，所思殊不同。
予悲方为老，君责一何空。
曾看乐官录，向是悲翁曲。
张老闻此词，汪汪泪盈目。
卢叟醉言麄，一杯凡数呼。
回头顾张老，敢欲戏为儒。','',''),('quantangshi-14918','喜从弟激初至','盧綸','quantangshi','','卷15','儒服策羸车，惠然过我庐。
叙年慙已长，称从意何疎。
作吏清无比，为文丽有余。
应嗤受恩者，头白读兵书。','',''),('quantangshi-14919','寻贾尊师','盧綸','quantangshi','','卷15','玉洞秦时客，焚香映绿萝。
新传左慈诀，曾与右军鹅。
井臼阴苔遍，方书古字多。
成都今日雨，应与酒相和。','',''),('quantangshi-14920','秋中过独孤郊居','盧綸','quantangshi','','卷15','开园过水到郊居，共引家童拾野蔬。
高树夕阳连古巷，菊花棃叶满荒渠。
秋山近处行过寺，夜雨寒时起读书。
帝里诸亲别来久，岂知王粲爱樵渔。','',''),('quantangshi-14921','同耿拾遗春中题第四郎新修书院','盧綸','quantangshi','','卷15','得接西园会，多因野性同。
引藤连树影，移石间花丛。
学就晨昏外，欢生礼乐中。
春游随墨客，夜宿伴潜公。
散帙灯惊燕，开帘月带风。
朝朝在门下，自与五侯通。','',''),('quantangshi-14922','春日题杜叟山下别业','盧綸','quantangshi','','卷15','白鸟羣飞山半晴，渚田相接有泉声。
园中晓露青丛合，桥上春风绿野明。
云影断来峯影出，林花落尽草花生。
今朝醉舞同君乐，始信幽人不爱荣。','',''),('quantangshi-14923','过终南柳处士','盧綸','quantangshi','','卷15','五老正相寻，围棋到煮金。
石摧丹井闭，月过洞门深。
猨鸟三时下，藤萝十里阴。
绿泉多草气，青壁少花林。
自愧非仙侣，何言见道心。
悠哉宿山口，雷雨夜沈沈。','',''),('quantangshi-14924','宿澄上人院','盧綸','quantangshi','','卷15','竹窗闻远水，月出似溪中。
香覆经年火，幡飘后夜风。
性昏知道晚，学浅喜言同。
一悟归身处，何山路不通。','',''),('quantangshi-14925','题李沆林园','盧綸','quantangshi','','卷15','古巷牛羊出，重门接柳阴。
闲看入竹路，自有向山心。
种药齐幽石，耕田到远林。
愿同词赋客，得兴谢家深。','',''),('quantangshi-14926','过司空曙村居','盧綸','quantangshi','','卷15','南北与山邻，蓬庵庇一身。
繁霜疑有雪，枯草似无人。
遂性在耕稼，所交唯贱贫。
何言张掾傲，每重德璋亲。','',''),('quantangshi-14927','题念济寺晕上人院','盧綸','quantangshi','','卷15','泉响竹潇潇，潜公居处遥。
虚空闻偈夜，清净雨花朝。
放鹤临山阁，降龙步石桥。
世尘徒委积，劫火定焚烧。
苔壁云难聚，风篁露易摇。
浮生亦无着，况乃是芭蕉。','',''),('quantangshi-14928','题杨虢县竹亭','盧綸','quantangshi','','卷15','夜宿密公室，话馀将昼兴。
遶堦三迳雪，当户一池冰。
家训资风化，心源隐政能。
明朝复何见，莱草古沟堘。','',''),('quantangshi-14929','过楼观李尊师','盧綸','quantangshi','','卷15','城阙望烟霞，常悲仙路赊。
宁知樵子径，得到葛洪家。
犬吠松间月，人行洞里花。
留诗千岁鹤，送客五云车。
访世山空在，观棋日未斜。
不知尘俗士，谁解种胡麻。','',''),('quantangshi-14930','雪谤后逢李叔度','盧綸','quantangshi','','卷15','相逢空握手，往事不堪思。
见少情难尽，愁深语自迟。
草生分路处，雨散出山时。
强得宽离恨，唯当说后期。','',''),('quantangshi-14931','春日过李侍御','盧綸','quantangshi','','卷15','高柳满春城，东园有鸟声。
折花朝露滴，漱石野泉清。
心许陶家醉，诗逢谢客呈。
应怜末行吏，曾是鲁诸生。','',''),('quantangshi-14932','出山逢耿湋','盧綸','quantangshi','','卷15','云雪离披山万里，别来曾住最高峰。
暂到人间归不得，长安陌上又相逢。','',''),('quantangshi-14933','题金吾郭将军石伏茅堂','盧綸','quantangshi','','卷15','云戟曙沈沈，轩墀清且深。
家传成栋美，尧宠结茅心。
玉佩多依石，油幢亦在林。
炉香诸洞暖，殿影众山阴。
草奏风生笔，筵开雪满琴。
客从龙阙至，僧自虎溪寻。
萧洒延清赏，风流会素襟。
终朝息尘步，一醉间华簪。','',''),('quantangshi-14934','题贾山人园林','盧綸','quantangshi','','卷15','竹影朦胧松影长，素琴清簟好风凉。
连春诗会烟花满，半夜酒醒兰蕙香。
五字每将称玉友，一尊曾不顾金囊。
长沙流谪君非远，莫遣英名负洛阳。','',''),('quantangshi-14935','秋夜同畅当宿藏公院','盧綸','quantangshi','','卷15','礼足一垂泪，医王知病由。
风萤方喜夜，露槿已伤秋。
顾以儿童爱，每从仁者求。
将祈竟何得，灭迹在缁流。','',''),('quantangshi-14936','重同畅当奘公院闻琴','盧綸','quantangshi','','卷15','悞以音声祈远公，请将徽轸付秋风。
漾漾硖流吹不尽，月华如在白波中。','',''),('quantangshi-14937','同耿湋宿陆澧旅舍','盧綸','quantangshi','','卷15','当轩云月开，清夜故人杯。
拥褐觉霜下，抱琴闻雁来。
迎风君顾步，临路我迟回。
双鬓共如此，此懽非易陪。','',''),('quantangshi-14938','题苗员外竹间亭','盧綸','quantangshi','','卷15','高甃绝行尘，开帘似有春。
风倾竹上雪，山对酒边人。
步暖先逢日，书空远见邻。
还同内斋暇，登赏及诸姻。','',''),('quantangshi-14939','奉陪侍中登白楼','盧綸','quantangshi','','卷15','高楼倚玉梯，朱槛与云齐。
顾盼亲霄汉，谈谐息鼓鼙。
洪河斜更直，野雨急仍低。
今日陪尊俎，唯当醉似泥。','',''),('quantangshi-14940','九日奉陪侍郎登白楼','盧綸','quantangshi','','卷15','碧霄孤鹤发清音，上宰因添望阙心。
睥睨三层连步障，茱萸一朵映华簪。
红霞似绮河如带，白露团珠菊散金。
此日所从何所问，俨然冠剑拥成林。','',''),('quantangshi-14941','春日喜雨奉和马侍中宴白楼','盧綸','quantangshi','','卷15','鹳鹤相呼绿野宽，鼎臣闲倚玉栏干。
洪河拥沫流仍急，苍岭和云色更寒。
艳艳风光呈瑞岁，泠泠歌颂振雕盘。
今朝醉舞共乡老，不觉倾欹獬豸冠。','',''),('quantangshi-14942','奉陪侍中游石笋溪十二韵','盧綸','quantangshi','','卷15','朝日照灵山，山溪浩纷错。
图书无旧记，鲧禹应新凿。
双壁泻天河，一峰吐莲萼。
潭心乱雪卷，嵓腹繁珠落。
彩蛤攒锦囊，芳萝袅花索。
猨羣曝阳岭，龙穴腥阴壑。
静得渔者言，闲闻洞仙博。
欹松倚朱幰，广石屯油幕。
国泰事留侯，山春纵康乐。
间关殊状鸟，烂熳无名药。
欲验少君方，还吟大隐作。
旌幢不可驻，古塞新沙漠。','',''),('quantangshi-14943','九日奉陪侍中宴白楼','盧綸','quantangshi','','卷15','露白菊氛氲，西楼盛袭文。
玉筵秋令节，金钺汉元勋。
说剑风生座，抽琴鹤遶云。
謏儒无以答，愿得备前军。','',''),('quantangshi-14944','九日奉陪侍中宴后亭','盧綸','quantangshi','','卷15','玉壶倾菊酒，一顾得淹留。
彩笔征枚叟，花筵舞莫愁。
管弦能驻景，松桂不停秋。
为谢蓬蒿辈，如何霜霰稠。','',''),('quantangshi-14945','九日奉陪令公登白楼同咏菊','盧綸','quantangshi','','卷15','琼尊犹有菊，可以献留侯。
愿比三花秀，非同百卉秋。
金英分蘂细，玉露结房稠。
黄雀知恩在，衔飞亦上楼。','',''),('quantangshi-14946','奉陪浑侍中上巳日泛渭河','盧綸','quantangshi','','卷15','青舸锦帆开，浮天接上台。
晚莺和玉笛，春浪动金罍。
舟檝方朝海，鲸鲵自曝腮。
应怜似萍者，空逐榜人回。','',''),('quantangshi-14947','奉陪侍中春日过武安君庙','盧綸','quantangshi','','卷15','长裾间貔虎，遗庙盛攀登。
白羽三千骑，红林一万层。
元臣达幽契，祝史告明征。
抚坐悲今古，瞻容感废兴。
回风卷藂栢，骤雨湿诸陵。
倏忽烟花霁，当营看月生。','',''),('quantangshi-14948','过玉[真]公主影殿','盧綸','quantangshi','','卷15','夕照临窗起暗尘，青松绕殿不知春。
君看白发诵经者，半是宫中歌舞人。','',''),('quantangshi-14949','题嘉祥殿南溪印禅师壁画影堂','盧綸','quantangshi','','卷15','双屐参差锡杖斜，衲衣交膝对天花。
瞻容悟问修持劫，似指前溪无数沙。','',''),('quantangshi-14950','题伯夷庙','盧綸','quantangshi','','卷15','中条山下黄礓石，垒作夷齐庙里神。
落叶满堦尘满座，不知浇酒为何人。','',''),('quantangshi-14951','早春游樊川野居却寄李端校书兼呈崔峒补阙司空曙主簿耿湋拾遗','盧綸','quantangshi','','卷15','白水遍沟堘，青山对杜陵。
晴明人望鹤，旷野鹿随僧。
古柳连巢折，荒堤带草崩。
阴桥全覆雪，瀑溜半垂冰。
鬬鼠摇松影，游龟落石层。
韶光偏不待，衰败巧相仍。
桂树曾争折，龙门几共登。
琴师阮校尉，诗和柳吴兴。
舐笔求书扇，张屏看画蝇。
卜邻空遂约，问卦独无征。
投足经危路，收才遇直绳。
守农穷自固，行乐病何能。
掩帙蓬蒿晚，临川景气澄。
飒然成一叟，谁更慕骞腾。','',''),('quantangshi-14952','同钱郎中晚春过慈恩寺','盧綸','quantangshi','','卷15','不见僧中旧，仍逢雨后春。
惜花将爱寺，俱是白头人。','',''),('quantangshi-14953','曲江春望 一','盧綸','quantangshi','','卷15','菖蒲飜叶柳交枝，暗上莲舟鸟不知。
更到无花最深处，玉楼金殿影参差。','',''),('quantangshi-14954','曲江春望 二','盧綸','quantangshi','','卷15','翠黛红妆画鷁中，共惊云色带微风。
箫管曲长吹未尽，花南水北雨蒙蒙。','',''),('quantangshi-14955','曲江春望 三','盧綸','quantangshi','','卷15','泉声遍野入芳洲，拥沫吹花草上流。
落日行人渐无路，巢乌乳燕满高楼。','',''),('quantangshi-14956','春日陪李庶子遵善寺东院晓望','盧綸','quantangshi','','卷15','映竹水田分，当山起雁羣。
阳峰高对寺，阴井下通云。
雪昼唯逢鹤，花时此见君。
由来禅诵地，多有谢公文。','',''),('quantangshi-14957','华清宫 一','盧綸','quantangshi','','卷15','汉家天子好经过，白日青山宫殿多。
见说只今生草处，禁泉荒石已相和。','',''),('quantangshi-14958','华清宫 二','盧綸','quantangshi','','卷15','水气朦胧满画梁，一回开殿满山香。
宫娃几许经歌舞，白首翻令忆建章。','',''),('quantangshi-14959','题兴善寺后池','盧綸','quantangshi','','卷15','隔窗栖白鹤，似与镜湖邻。
月照何年树，花逢几遍人。
岸莎青有路，苔径绿无尘。
永愿容依止，僧中老此身。','',''),('quantangshi-14960','陪中书李纾舍人夜泛东池','盧綸','quantangshi','','卷15','看月复听琴，移舟出树阴。
夜村机杼急，秋水芰荷深。
石静龟潜上，萍开果暗沈。
何言奉杯酒，得见五湖心。','',''),('quantangshi-14961','宴赵氏昆季书院因与会文并率尔投赠','盧綸','quantangshi','','卷15','诗礼挹余波，相懽在琢磨。
琴尊方会集，珠玉忽骈罗。
谢族风流盛，于门福庆多。
花攒骐骥枥，锦绚凤凰窠。
咏雪因饶妹，书经为爱鹅。
仍闻广练被，更有远儒过。','',''),('quantangshi-14962','题天华观','盧綸','quantangshi','','卷15','峰嶂徘徊霞景新，一潭寒水绝纤鳞。
朱字灵书千万轴，苍髯道士两三人。
芝童解说壶中事，玉管能留天上春。
眼见仙丹求不得，汉家簪绂在羸身。','',''),('quantangshi-14963','宿石瓮寺','盧綸','quantangshi','','卷15','殿有寒灯草有萤，千林万壑寂无声。
烟凝积水龙蛇蛰，露湿空山星汉明。
昏霭雾中悲世界，曙霞光里见王城。
回瞻相好因垂泪，苦海波涛何日平。','',''),('quantangshi-14964','题悟真寺','盧綸','quantangshi','','卷15','万峯交掩一峰开，晓色常从天上来。
似到西方诸佛国，莲花影里数楼台。','',''),('quantangshi-14965','题云际寺上方','盧綸','quantangshi','','卷15','松高萝蔓轻，中有石牀平。
下界水长急，上方灯自明。
空门不易启，初地本无程。
回步忽山尽，万缘从此生。','',''),('quantangshi-14966','九日同司直九叔崔侍御登宝鸡南楼','盧綸','quantangshi','','卷15','把菊叹将老，上楼悲未还。
短长新白发，重叠旧青山。
霜气清衿袖，琴声引醉颜。
竹林唯七友，何幸亦登攀。','',''),('quantangshi-14967','同王员外雨后登开元寺南楼因寄西岩警上人','盧綸','quantangshi','','卷15','过雨开楼看晚虹，白云相逐水相通。
寒蝉噪暮野无日，古树伤秋天有风。
数穗远烟凝壠上，一枝繁果忆山中。
何言暂别东林友，惆怅人间事不同。','',''),('quantangshi-14968','同赵进马元阳春日登长春宫古城望河中因寄郑损仓曹','盧綸','quantangshi','','卷15','城头春霭晓蒙蒙，指望关桥满袖风。
云骑闲嘶宫柳外，玉人愁立草花中。
钟分寺路山光绿，河绕军州日气红。
迹忝已成方恋赏，此时离恨与君同。','',''),('quantangshi-14969','同崔峒补阙慈恩寺避暑','盧綸','quantangshi','','卷15','寺凉高树合，卧石绿阴中。
伴鹤慙仙侣，依僧学老翁。
鱼沈荷叶露，鸟散竹林风。
始悟尘居者，应将火宅同。','',''),('quantangshi-14970','春日登楼有怀','盧綸','quantangshi','','卷15','花正浓时人正愁，逢花却欲替花羞。
年来笑伴皆归去，今日晴明独上楼。','',''),('quantangshi-14971','长安春望','盧綸','quantangshi','','卷15','东风吹雨过青山，却望千门草色闲。
家在梦中何日到，春生江上几人还。
川原缭绕浮云外，宫阙参差落照间。
谁念为儒逢世难，独将衰鬓客秦关。','',''),('quantangshi-14972','冬日登城楼有怀因赠程腾','盧綸','quantangshi','','卷15','生涯何事多羁束，赖此登临畅心目。
郭南郭北无数山，万井逶迤流水间。
弹琴对酒不知暮，岸帻题诗身自闲。
风声肃肃雁飞绝，云色茫茫欲成雪。
遥思海客天外归，坐想征人两头别。
世情多以风尘隔，泣尽无因画筹策。
谁知白首窗下人，不接朱门坐中客。
贱亦不足叹，贵亦不足陈。
长卿未遇杨朱泣，蔡泽无媒原宪贫。
如今万乘方用武，国命天威借貔虎。
穷达皆为身外名，公侯可废刀头取。
君不见汉家边将在边庭，白羽三千出井陉。
当风看猎拥珠翠，岂在终年穷一经。','',''),('quantangshi-14973','过仙游寺','盧綸','quantangshi','','卷15','上方下方雪中路，白云流水如闲步。
数峰行尽犹未归，寂寞经声竹阴暮。','',''),('quantangshi-14974','同路郎中韩侍御春日题野寺','盧綸','quantangshi','','卷15','寺前山远古陂宽，寺里人稀春草寒。
何事最堪悲色相，折花将与老僧看。','',''),('quantangshi-14975','奉和李益游栖岩寺','盧綸','quantangshi','','卷15','林香雨气新，山寺绿无尘。
遂结云外赏，共游天上春。
鹤鸣金阙丽，僧语竹房邻。
待月水流急，惜花风起频。
何方非坏境，此地有归人。
回首空门路，皤然一幻身。','',''),('quantangshi-14976','秋夜同畅当宿潭上西亭','盧綸','quantangshi','','卷15','圆月出山头，七贤林下游。
梢梢寒叶坠，滟滟月波流。
凫鹄共思晓，菰蒲相与秋。
明当此中别，一为望汀洲。','',''),('quantangshi-14977','山中一绝','盧綸','quantangshi','','卷15','饥食松花渴饮泉，偶从山后到山前。
阳坡软草厚如织，因与鹿麛相伴眠。','',''),('quantangshi-14978','与畅当夜泛秋潭','盧綸','quantangshi','','卷15','萤火扬莲丛，水凉多夜风。
离人将落叶，俱在一船中。','',''),('quantangshi-14979','秋夜宴集陈翃郎中圃亭美校书郎张正元归乡','盧綸','quantangshi','','卷15','泉清兰菊稠，红果落城沟。
保庆台榭古，感时琴瑟秋。
硕儒欢颇至，名士礼能周。
为谢邑中少，无惊池上鸥。','',''),('quantangshi-14980','春游东潭','盧綸','quantangshi','','卷15','移舟试望家，漾漾似天涯。
日暮满潭雪，白鸥和柳花。','',''),('quantangshi-14981','同薛存诚登栖岩寺','盧綸','quantangshi','','卷15','衰蹇步难前，上山如上天。
尘泥来自晚，猨鹤到何先。
万壑应孤磬，百花通一泉。
苍苍此明月，下界正沈眠。','',''),('quantangshi-14982','河中府崇福寺看花','盧綸','quantangshi','','卷15','闻道山花如火红，平明登寺已经风。
老僧无见亦无说，应与看人心不同。','',''),('quantangshi-14983','冬日宴郭监林亭','盧綸','quantangshi','','卷15','玉勒聚如云，森森鸾鹤羣。
据梧花罽接，沃盥石泉分。
华味慙初识，新声喜尽闻。
此山招老贱，敢不谢夫君。','',''),('quantangshi-14984','奉和李舍人昆季咏玫瑰花寄赠徐侍郎','盧綸','quantangshi','','卷15','独鹤寄烟霜，双鸾思晚芳。
旧阴依谢宅，新艳出萧墙。
蝶散摇轻露，莺衔入夕阳。
雨朝胜濯锦，风夜剧焚香。
断日千层艳，孤霞一片光。
密来惊叶少，动处觉枝长。
布影期高赏，留春为远方。
尝闻赠琼玖，叨和愧升堂。','',''),('quantangshi-14985','同耿湋司空曙二拾遗题韦员外东斋花树','盧綸','quantangshi','','卷15','绿砌红花树，狂风独未吹。
光中疑有焰，密处似无枝。
鸟动香轻发，人愁影屡移。
今朝数片落，为报汉郎知。','',''),('quantangshi-14986','观袁修侍郎涨新池','盧綸','quantangshi','','卷15','引水香山近，穿云复遶林。
才闻篱外响，已觉石边深。
满处侵苔色，澄来见柳阴。
微风月明夜，知有五湖心。','',''),('quantangshi-14987','和徐法曹赠崔洛阳斑竹杖以诗见答','盧綸','quantangshi','','卷15','玉干一寻余，苔花锦不如。
劲堪和醉倚，轻好向空书。
采拂稽山曲，因依释氏居。
方辰将独步，岂与此君疎。','',''),('quantangshi-14988','早秋望华清宫中树因以成咏','盧綸','quantangshi','','卷15','可怜云木藂，满禁碧蒙蒙。
色润灵泉近，阴清辇路通。
玉坛标八桂，金井识双桐。
交映凝寒露，相和起夜风。
数枝盘石上，几叶落云中。
燕拂宜秋霁，蝉鸣觉昼空。
翠屏更隐见，珠缀共玲珑。
雷雨生成早，樵苏禁令雄。
野藤高助绿，仙果迥呈红。
惆怅缭垣暮，兹山闻暗蛩。','',''),('quantangshi-14989','小鱼咏寄泾州杨侍郎','盧綸','quantangshi','','卷15','莲花影里暂相离，才出浮萍值罟师。
上得龙门还失浪，九江何处是归期。','',''),('quantangshi-14990','贼中与严越卿曲江看花','盧綸','quantangshi','','卷15','红枝欲折紫枝殷，隔水连宫不用攀。
会待长风吹落尽，始能开眼向青山。','',''),('quantangshi-14991','同畅当咏蒲团','盧綸','quantangshi','','卷15','团团锦花结，乃是前溪蒲。
拥坐称儒褐，倚眠宜病夫。
唯当学禅寂，终老与之俱。','',''),('quantangshi-14992','焦篱店醉题','盧綸','quantangshi','','卷15','洛下渠头百卉新，满筵歌笑独伤春。
何须更弄邵翁伯，即我此身如此人。','',''),('quantangshi-14993','陈翃中丞东斋赋白玉簪','盧綸','quantangshi','','卷15','美矣新成太华峰，翠莲枝折叶重重。
松阴满涧闲飞鹤，潭影通云暗上龙。
漠漠水香风颇馥，涓涓乳溜味何浓。
因声远报浮丘子，不奏登封时不容。','',''),('quantangshi-14994','新茶咏寄上西川相公二十三舅大夫二十舅','盧綸','quantangshi','','卷15','三献蓬莱始一尝，日调金鼎阅芳香。
贮之玉合才半饼，寄与阿连题数行。','',''),('quantangshi-14995','泊扬子江岸','盧綸','quantangshi','','卷15','山映南徐暮，千帆入古津。
鱼惊出浦火，月照渡江人。
清镜催双鬓，沧波寄一身。
空怜莎草色，长接故园春。','',''),('quantangshi-14996','晚次鄂州','盧綸','quantangshi','','卷15','云开远见汉阳城，犹是孤帆一日程。
估客昼眠知浪静，舟人夜语觉潮生。
三湘衰鬓逢秋色，万里归心对月明。
旧业已随征战尽，更堪江上鼓鼙声。','',''),('quantangshi-14997','夜投丰德寺谒海上人','盧綸','quantangshi','','卷15','半夜中峰有磬声，偶逢樵者问山名。
上方月晓闻僧语，下路林疎见客行。
野鹤巢边松最老，毒龙潜处水偏清。
愿得远公知姓字，焚香洗钵过浮生。','',''),('quantangshi-14998','江行次武昌县','盧綸','quantangshi','','卷15','家寄五湖间，扁舟往复还。
年年生白发，处处上青山。
去国空知远，安身竟不闲。
更悲江畔柳，长是北人攀。','',''),('quantangshi-14999','夜泊金陵','盧綸','quantangshi','','卷15','圆月出高城，苍苍照水营。
江中正吹笛，楼上又无更。
洛下仍传箭，关西欲进兵。
谁知五湖外，诸将但争名。','',''),('quantangshi-15000','渡浙江','盧綸','quantangshi','','卷15','前船后船未相及，五两头平北风急。
飞沙卷地日色昏，一半征帆浪花湿。','',''),('quantangshi-15001','李端公','盧綸','quantangshi','','卷15','故关衰草遍，离别自堪悲。
路出寒云外，人归暮雪时。
少孤为客早，多难识君迟。
掩泪空相向，风尘何处期。','',''),('quantangshi-15002','秋晚山中别业','盧綸','quantangshi','','卷15','树老野泉清，幽人好独行。
去闲知路静，归晚喜山明。
兰芰通荒井，牛羊出古城。
茂陵秋最冷，谁念一书生。','',''),('quantangshi-15003','关口逢徐迈','盧綸','quantangshi','','卷15','废寺连荒垒，那知见子真。
关城夜有雪，冰渡晓无人。
酒里唯多病，山中愿作邻。
常闻兄弟乐，谁肯信家贫。','',''),('quantangshi-15004','山中咏古木','盧綸','quantangshi','','卷15','高木已萧索，夜雨复秋风。
坠叶鸣藂竹，斜根拥断蓬。
半侵山色里，长在水声中。
此地何人到，云门去亦通。','',''),('quantangshi-15005','酬李端公野寺病居见寄','盧綸','quantangshi','','卷15','野寺钟昏山正阴，乱藤高竹水声深。
田夫就饷还依草，野雉惊飞不过林。
斋沫暂思同静室，清羸已觉助禅心。
寂寞日长谁问疾，料君惟取古方寻。','',''),('quantangshi-15006','送少微上人游蜀','盧綸','quantangshi','','卷15','瓶钵绕禅衣，连宵宿翠微。
树开巴水远，山晓蜀星稀。
识遍中朝贵，多谙外学非。
何当一传付，道侣愿知归。','',''),('quantangshi-15007','送宁国夏侯丞','盧綸','quantangshi','','卷15','楚国青芜上，秋云似白波。
五湖长路少，九派乱山多。
谢守通诗宴，陶公许醉过。
怃然饯离阻，年鬓两蹉跎。','',''),('quantangshi-15008','送袁偁','盧綸','quantangshi','','卷15','谏猎名空久，多因病与贫。
买书行几市，带雨别何人。
客路山连水，军州日映尘。
凄凉一分手，俱恨老相亲。','',''),('quantangshi-15009','赠别李纷','盧綸','quantangshi','','卷16','头白乘驴悬布囊，一回言别泪千行。
儿孙满眼无归处，唯到尊前似故乡。','',''),('quantangshi-15010','罪所送苗员外上都','盧綸','quantangshi','','卷16','谋身当议罪，宁遣友朋闻。
祸近防难及，愁长事未分。
寂寥惊远语，幽闭望归云。
亲戚如相见，唯应泣向君。','',''),('quantangshi-15011','送李校书赴东川幕','盧綸','quantangshi','','卷16','泥坂望青城，浮云与栈平。
字形知国号，眉势识山名。
编简尘封阁，戈鋋雪照营。
男儿须聘用，莫信笔堪耕。','',''),('quantangshi-15012','至德中赠内兄刘赞','盧綸','quantangshi','','卷16','时难访亲戚，相见喜还悲。
好学年空在，从戎事已迟。
听琴泉落处，步履雪深时。
惆怅多边信，青山共有期。','',''),('quantangshi-15013','春日灞亭同苗员外寄皇甫侍御','盧綸','quantangshi','','卷16','坐见春云暮，无因报所思。
川平人去远，日暖雁飞迟。
对酒山长在，看花鬓自衰。
谁堪登灞岸，还作旧乡悲。','',''),('quantangshi-15014','送颜推官游银夏谒韩大夫','盧綸','quantangshi','','卷16','丛篁叫寒笛，满眼塞山青。
才子尊前画，将军石上铭。
猎声云外响，战血雨中腥。
苦乐从来事，因君一涕零。','',''),('quantangshi-15015','咸阳送房济侍御归太原幕','盧綸','quantangshi','','卷16','旧居无旧邻，似见故乡春。
复对别离酒，欲成衰老人。
客衣频染泪，军旅亦多尘。
握手重相勉，平生心所因。','',''),('quantangshi-15016','宝泉寺送李益端公归邠宁幕','盧綸','quantangshi','','卷16','参差岩障东，云日晃龙宫。
石净非因雨，松凉不为风。
恋泉将鹤并，偷果与猨同。
眼界尘虽染，心源蔽已通。
莲花国何限，贝叶字无穷。
早晚登麟阁，慈门欲付公。','',''),('quantangshi-15017','送何召下第后归蜀','盧綸','quantangshi','','卷16','襃斜行客过，栈道响危空。
路湿云初上，山明日正中。
水程通海货，地利杂吴风。
一别金门远，何人复荐雄。','',''),('quantangshi-15018','宿定陵寺','盧綸','quantangshi','','卷16','古塔荒台出禁墙，磬声初尽漏声长。
云生紫殿幡花湿，月照青山松栢香。
禅室夜闻风过竹，奠筵朝启露霑裳。
谁悟威灵同寂灭，更堪砧杵发昭阳。','',''),('quantangshi-15019','送彭开府往云中觐使君兄','盧綸','quantangshi','','卷16','一门三代贵，非是主恩偏。
破虏山铭在，承家剑艺全。
夺旗貂帐侧，射虎雪林前。
雁塞逢兄弟，云州发管弦。
冻河光带日，枯草净无烟。
儒者曾修武，因贻上将篇。','',''),('quantangshi-15020','送李缃','盧綸','quantangshi','','卷16','旧国仍连五将营，儒衣何处谒公卿。
波翻远水蒹葭动，路入寒村机杼鸣。
嵇康书论多归兴，谢氏家风有学名。
为问西来雨中客，空山几处是前程。','',''),('quantangshi-15021','送内弟韦宗仁归信州觐省','盧綸','quantangshi','','卷16','常嗟外族兄弟稀，转觉心孤是送归。
醉掩壶觞人有泪，梦惊波浪日无辉。
烹鱼绿岸烟浮草，摘橘青溪露湿衣。
闻说江楼长卷幔，几回风起望胡威。','',''),('quantangshi-15022','长安疾后首秋夜即事','盧綸','quantangshi','','卷16','九重深锁禁城秋，月过南宫渐映楼。
紫陌夜深槐露滴，碧空云尽火星流。
清风刻漏传三殿，甲第歌钟乐五侯。
楚客病来乡思苦，寂寥灯下不胜愁。','',''),('quantangshi-15023','送崔琦赴宣州幕','盧綸','quantangshi','','卷16','五马临流待幕宾，羡君谈笑出风尘。
身闲就养宁辞远，世难移家莫厌贫。
天际晓山三峡路，津头腊市九江人。
何处遥知最惆怅，满湖青草雁声春。','',''),('quantangshi-15024','送杨皞东归','盧綸','quantangshi','','卷16','登楼掩泣话归期，楚树荆云发远思。
日里扬帆闻戍鼓，舟中酹酒见山祠。
西江风浪何时尽，北客音书欲寄谁。
若说湓城杨司马，知君望国有新诗。','',''),('quantangshi-15025','至德中途中书事却寄李僴','盧綸','quantangshi','','卷16','乱离无处不伤情，况复看碑对古城。
路遶寒山人独去，月临秋水雁空惊。
颜衰重喜归乡国，身贱多惭问姓名。
今日主人还共醉，应怜世故一儒生。','',''),('quantangshi-15026','奉和太常王卿酬中书李舍人中书寓直春夜对月见寄','盧綸','quantangshi','','卷16','露如轻雨月如霜，不见星河见雁行。
虚晕入池波自泛，满轮当苑桂多香。
春台几望黄龙阙，云路宁分白玉郎。
是夜巴歌应金石，岂殊萤影对清光。','',''),('quantangshi-15027','酬包佶郎中览拙卷后见寄','盧綸','quantangshi','','卷16','令伯支离晚读书，岂知词赋称相如。
枉逢花木无新思，拙就溪潭损旧居。
禁路看山歌自缓，云司玩月漏应疎。
沈忧敢望金门召，空愧巴歈并子虚。','',''),('quantangshi-15028','送史寀滑州谒贾仆射','盧綸','quantangshi','','卷16','朱门洞启俨行车，金鐍装囊半是书。
君向东州问徐胤，羊公何事灭吹鱼。','',''),('quantangshi-15029','送鲍中丞赴太原','盧綸','quantangshi','','卷16','分路引鸣驺，喧喧似陇头。
暂移西掖望，全解北门忧。
专幕临都护，分曹制督邮。
积冰营不下，盛雪猎方休。
白草连胡帐，黄云拥戍楼。
今朝送旌斾，一减鲁儒羞。','',''),('quantangshi-15030','送耿拾遗湋充括图书使往江淮','盧綸','quantangshi','','卷16','传令收遗籍，诸儒喜饯君。
孔家唯有地，禹穴但生云。
编简知还续，虫鱼亦自分。
如逢北山隐，一为谢移文。','',''),('quantangshi-15031','送郭判官赴振武','盧綸','quantangshi','','卷16','黄河九曲流，缭绕古边州。
鸣雁飞初夜，羌胡正晚秋。
凄凉金管思，迢遰玉人愁。
七叶推多庆，须怀杀敌忧。','',''),('quantangshi-15032','春江夕望','盧綸','quantangshi','','卷16','洞庭芳草遍，楚客莫思归。
经难人空老，逢春雁自飞。
东西兄弟远，存没友朋稀。
独立还垂泪，天南一布衣。','',''),('quantangshi-15033','送元昱尉义兴','盧綸','quantangshi','','卷16','欲成云海别，一夜梦天涯。
白浪缘江雨，青山绕县花。
风标当剧部，冠带称儒家。
去矣谢亲爱，知予发已华。','',''),('quantangshi-15034','送黎兵曹往陕府结亲','盧綸','quantangshi','','卷16','郎马两如龙，春朝上路逢。
鸳鸯初集水，薜荔欲依松。
步帐歌声转，妆台烛影重。
何言在阴者，得是戴侯宗。','',''),('quantangshi-15035','送乐平苗明府','盧綸','quantangshi','','卷16','累职比柴桑，清秋入楚乡。
一船灯照浪，两岸树凝霜。
亭吏趋寒雾，山城敛曙光。
无辞折腰久，仲德在鸳行。','',''),('quantangshi-15036','晚到盩厔耆老家','盧綸','quantangshi','','卷16','老翁曾旧识，相引出柴门。
苦话别时事，因寻溪上村。
数年何处客，近日几家存。
冒雨看禾黍，逢人忆子孙。
乱藤穿井口，流水到篱根。
惆怅不堪住，空山月又昏。','',''),('quantangshi-15037','卧病书怀','盧綸','quantangshi','','卷16','苦心三十载，白首遇艰难。
旧地成孤客，全家赖钓竿。
貌衰缘药尽，起晚为山寒。
老病今如此，无人更问看。','',''),('quantangshi-15038','落第后归终南别业','盧綸','quantangshi','','卷16','久为名所误，春尽始归山。
落羽羞言命，逢人强破颜。
交疎贫病里，身老是非间。
不及东溪月，渔翁夜往还。','',''),('quantangshi-15039','送朝邑张明府','盧綸','quantangshi','','卷16','千室暮山西，浮云与树齐。
剖辞云落纸，拥吏雪成泥。
野火芦千顷，河田水万畦。
不知琴月夜，谁得听乌啼。','',''),('quantangshi-15040','送李方东归','盧綸','quantangshi','','卷16','故交三四人，闻别共霑巾。
举目是陈事，满城无至亲。
身从丧日病，家自俭年贫。
此去何堪远，遗孤在旧邻。','',''),('quantangshi-15041','秋晚霁后野望忆夏侯审','盧綸','quantangshi','','卷16','天晴禾黍平，畅目亦伤情。
野店云日丽，孤庄砧杵鸣。
川原唯寂寞，岐路自纵横。
前后无俦侣，此怀谁与呈。','',''),('quantangshi-15042','送王尊师','盧綸','quantangshi','','卷16','梦别一仙人，霞衣满鹤身。
旌幢天路晚，桃杏海山春。
种玉非求稔，烧金不为贫。
自怜头白早，难与葛洪亲。','',''),('quantangshi-15043','送抚州周使君','盧綸','quantangshi','','卷16','周郎三十余，天子赐鱼书。
龙节随云水，金铙动里闾。
松声三楚远，乡思百花初。
若转弘农守，萧咸事不如。','',''),('quantangshi-15044','赠别司空曙','盧綸','quantangshi','','卷16','有月曾同赏，无秋不共悲。
如何与君别，又是菊花时。','',''),('quantangshi-15045','送王录事赴任苏州','盧綸','quantangshi','','卷16','古堤迎拜路，万里一帆前。
潮作浇田雨，云成煮海烟。
吏闲唯重法，俗富不忧边。
西掖今宵咏，还应寄阿连。','',''),('quantangshi-15046','大梵山寺院奉呈趣上人赵中丞','盧綸','quantangshi','','卷16','渐欲休人事，僧房学闭关。
伴鱼浮水上，看鹤向林间。
寺古秋仍早，松深暮更闲。
月中随道友，夜夜坐空山。','',''),('quantangshi-15047','送恒操上人归江外觐省','盧綸','quantangshi','','卷16','依佛不违亲，高堂与寺邻。
问安双树晓，求膳一僧贫。
持呪过龙庙，翻经化海人。
还同惠休去，儒者亦霑巾。','',''),('quantangshi-15048','上巳日陪齐相公花楼宴','盧綸','quantangshi','','卷16','钟陵暮春月，飞观延羣英。
晨霞耀中轩，满席罗金琼。
持杯凝远睇，触物结幽情。
树色参差绿，湖光潋滟明。
礼卑瞻绛帐，恩浃厕华缨。
徒记山阴兴，祓禊乃为荣。','',''),('quantangshi-15049','寒食','盧綸','quantangshi','','卷16','孤客飘飘岁载华，况逢寒食倍思家。
莺啼远墅多从柳，人哭荒坟亦有花。
浊水秦渠通渭急，黄埃京洛上原斜。
驱车西近长安好，宫观参差半隐霞。','',''),('quantangshi-15050','舟中寒食','盧綸','quantangshi','','卷16','寒食空江曲，孤舟渺水前。
鬬鸡沙鸟异，禁火岸花然。
日霁开愁望，波喧警醉眠。
因看数茎鬓，倍欲惜芳年。','',''),('quantangshi-15051','元日早朝呈故省诸公','盧綸','quantangshi','','卷16','万戟淩霜布，森森瑞气间。
垂衣当晓日，上寿对南山。
济济延多士，跹跹舞百蛮。
小臣无事谏，空愧伴鸣环。','',''),('quantangshi-15052','元日朝回中夜书情寄南宫二故人','盧綸','quantangshi','','卷16','鸣佩随鵷鹭，登堦见冕旒。
无能裨圣代，何事别沧洲。
闲夜贫还醉，浮名老渐羞。
凤城春欲晚，郎吏忆同游。','',''),('quantangshi-15053','裴给事宅白牡丹','盧綸','quantangshi','','卷16','长安豪贵惜春残，争翫街西紫牡丹。
别有玉盘承露冷，无人起就月中看。','',''),('quantangshi-15054','送韦判官得雨中山','盧綸','quantangshi','','卷16','前峰后岭碧蒙蒙，草拥惊泉树带风。
人语马嘶听不得，更堪长路在云中。','',''),('quantangshi-15055','送宛丘任少府','盧綸','quantangshi','','卷16','带绶别乡亲，东为千里人。
俗讹唯竞祭，地古不留春。
野戍云藏火，军城树拥尘。
少年何所重，才子又清贫。','',''),('quantangshi-15056','送永阳崔明府','盧綸','quantangshi','','卷16','鹤唳蒹葭晓，中流见楚城。
浪清风乍息，山白月犹明。
废路开荒木，归人种古营。
悬闻正讹俗，邴曼更知名。','',''),('quantangshi-15057','割飞二刀子歌','盧綸','quantangshi','','卷16','我家有翦刀，人云鬼国铁。
裁罗裁绮无钝时，用来三年一股折。
南中匠人淳用钢，再令盘屈随手伤。
改锻割飞二刀子，色迎霁雪锋含霜。
两条神物秋冰薄，刃淬初蟾鞘金错。
越戟吴钩不足夸，斩犀切玉应怀怍。
日试曾磨汉水边，掌中恄栗声冷然。
神惊魄悸却收得，刃头已吐微微烟。
刀乎刀乎何烨烨，魑魅须藏怪须慑。
若非良工变尔形，只向裁缝委箱箧。','',''),('quantangshi-15058','送郎士元使君赴郢州','盧綸','quantangshi','','卷16','赐衣兼授节，行日郢中闻。
花发登山庙，天晴阅水军。
渔商三楚接，郡邑九江分。
高兴应难遂，元戎有大勋。','',''),('quantangshi-15059','春词','盧綸','quantangshi','','卷16','北苑罗裙带，尘衢锦绣鞵。
醉眠芳树下，半被落花埋。','',''),('quantangshi-15060','清如玉壶冰','盧綸','quantangshi','','卷16','玉壶冰始结，循吏政初成。
既有虚心鉴，还如照胆清。
瑶池慙洞澈，金镜让澄明。
气若朝霜动，形随夜月盈。
临人能不蔽，待物本无情。
怯对圆光裹，妍蚩自此呈。','',''),('quantangshi-15061','山店','盧綸','quantangshi','','卷16','登登山路行时尽，决决溪泉到处闻。
风动叶声山犬吠，一家松火隔秋云。','',''),('quantangshi-15062','长至日上公献寿','崔琮','quantangshi','','卷16','应律三阳首，朝天万国同。
斗边看子月，台上候祥风。
五夜钟初动，千门日正融。
玉阶文物盛，仙仗武貔雄。
率舞皆羣辟，称觞即上公。
南山为圣寿，长对未央宫。','',''),('quantangshi-15063','长至日上公献寿','李竦','quantangshi','','卷16','候晓金门辟，乘时玉历长。
羽仪瞻上宰，云物丽初阳。
汉礼方传佩，尧年正捧觞。
日行临观阙，帝锡洽圭璋。
盛美超三代，洪休降百祥。
自怜朝末坐，空此咏无[疆]。','',''),('quantangshi-15064','赋得西戎献白玉环','李竦','quantangshi','','卷16','当时无外守，方物四夷通。
列土金河北，朝天玉塞东。
自将荆璞比，不与郑环同。
正朔虽传汉，衣冠尚带戎。
幸承提佩宠，多愧琢磨功。
绝域知文教，争趋上国风。','',''),('quantangshi-15065','新安江行','章八元','quantangshi','','卷16','江源南去永，野渡暂维梢。
古戍悬鱼网，空林露鸟巢。
雪晴山脊见，沙浅浪痕交。
自笑无媒者，逢人作解嘲。','',''),('quantangshi-15066','酬刘员外月下见寄','章八元','quantangshi','','卷16','夜凉河汉白，卷箔出南轩。
过月鸿争远，辞枝叶暗翻。
独谣闻丽曲，缓步接清言。
宣室思前席，行看拜主恩。','',''),('quantangshi-15067','寄都官刘员外','章八元','quantangshi','','卷16','旧宅平津邸，槐阴接汉宫。
鸣驺驰道上，寒日直庐中。
白雪歌偏丽，青云宦早通。
悠然一缝掖，千里限清风。','',''),('quantangshi-15068','题慈恩寺塔','章八元','quantangshi','','卷16','十层突兀在虚空，四十门开面面风。
却怪鸟飞平地上，自惊人语半天中。
回梯暗踏如穿洞，绝顶初攀似出笼。
落日凤城佳气合，满城春树雨蒙蒙。','',''),('quantangshi-15069','归桐庐旧居寄严长史','章八元','quantangshi','','卷16','昨辞夫子棹归舟，家在桐庐忆旧丘。
三月暖时花竞发，两溪分处水争流。
近闻江老传乡语，遥见家山减旅愁。
或在醉中逢夜雪，怀贤应向剡川游。','',''),('quantangshi-15070','天台道中示同行','章八元','quantangshi','','卷16','八重岩崿叠晴空，九色烟霞遶洞宫。
仙道多因迷路得，莫将心事问樵翁。','',''),('quantangshi-15071','元日望含元殿御扇开合','章八元','quantangshi','','卷16','万国来朝岁，千年觐圣君。
辇迎仙杖出，扇匝御香焚。
俯对朝容近，先知曙色分。
冕旒开处见，钟磬合时闻。
影动承朝日，花攒似庆云。
蒲葵那可比，徒用隔炎氛。','',''),('quantangshi-15072','清明日赐百僚新火','史延','quantangshi','','卷16','上苑连侯第，清明及暮春。
九天初改火，万井属良辰。
颁赐恩逾洽，承时庆自均。
翠烟和柳嫩，红焰出花新。
宠命尊三老，祥光烛万人。
太平当此日，空复荷陶甄。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-15073','清明日赐百僚新火','韓濬','quantangshi','','卷16','朱骑传红烛，天厨赐近臣。
火随黄道见，烟遶白榆新。
荣耀分他日，恩光共此辰。
更调金鼎膳，还暖玉堂人。
灼灼千门晓，辉辉万井春。
应怜萤聚夜，瞻望及东邻。','',''),('quantangshi-15074','清明日赐百僚新火','韓濬','quantangshi','','卷16','改火清明后，优恩赐近臣。
漏残丹禁晚，燧发白榆新。
瑞彩来双阙，神光焕四邻。
气回侯第暖，烟散帝城春。
利用调羹鼎，余辉烛缙绅。
皇明如照隐，愿及聚萤人。','',''),('quantangshi-15075','清明日赐百僚新火','韓濬','quantangshi','','卷16','御火传香殿，华光及侍臣。
星流中使马，烛耀九衢人。
转影连金屋，分辉丽锦茵。
焰迎红蘂发，烟染绿条春。
助律和风早，添炉暖气新。
谁怜一寒士，犹望照东邻。','',''),('quantangshi-15076','投珠于泉','獨孤綬','quantangshi','','卷16','至道归淳朴，明珠被弃捐。
天真来照乘，成性却沈泉。
不是灵蛇吐，非缘合浦还。
岸傍随月落，波底共星悬。
致远终无胫，怀贪遂息肩。
欲知恭俭德，所宝在惟贤。','',''),('quantangshi-15077','秦镜','獨孤綬','quantangshi','','卷16','万古秦时镜，从来抱至精。
依台月自吐，在匣水常清。
烂烂金光发，澄澄物象生。
云天皆洞鉴，表里尽虚明。
但见人窥胆，全胜响应声。
妍媸定可识，何处更逃情。','',''),('quantangshi-15078','秦镜','張佐','quantangshi','','卷16','楼上秦时镜，千秋独有名。
菱花寒不落，冰质夏长清。
龙在形难掩，人来胆易呈。
升台宜远照，开匣乍藏明。
皎色新磨出，圆规旧铸成。
愁容如可鉴，当欲拂尘缨。','',''),('quantangshi-15079','忆游天台寄道流','張佐','quantangshi','','卷16','忆昨天台到赤城，几朝仙籁耳中生。
云龙出水风声急，海鹤鸣臯日色清。
石笋半山移步险，桂花当涧拂衣轻。
今来尽是人间梦，刘阮茫茫何处行。','',''),('quantangshi-15080','龟负图','張佐','quantangshi','','卷16','天意将垂象，神龟出负图。
五方行有配，八卦义宁孤。
作瑞旌君德，披文叶帝谟。
乘流喜得路，逢圣幸存躯。
莲叶池通泛，桃花水自浮。
还寻九江去，安肯曳泥途。','',''),('quantangshi-15081','上元日梦王母献白玉环','張佐','quantangshi','','卷16','梦中朝上日，阙下拜天颜。
彷佛瞻王母，分明献玉环。
灵姿趋甲帐，悟道契玄关。
似见霜姿白，如看月彩弯。
霓裳归物外，凤历晓人寰。
仙圣非相远，昭昭寤寐间。','',''),('quantangshi-15082','良田无晚岁','張佐','quantangshi','','卷16','人功虽未及，地力信非常。
不任耕耘早，偏宜黍稷良。
无年皆有获，后种亦先芳。
膴膴盈千亩，青青保万箱。
何须祭田祖，讵要察农祥。
况是春三月，和风日又长。','',''),('quantangshi-15083','下第献座主张谓','閻濟美','quantangshi','','卷16','謇谔王臣直，文明雅量全。
望炉金自跃，应物镜何偏。
南国幽沈尽，东堂礼乐宣。
转令游艺士，更惜至公年。
芳树欢新景，青云泣暮天。
唯愁凤池拜，孤贱更谁怜。','',''),('quantangshi-15084','天津桥望洛城残雪','閻濟美','quantangshi','','卷16','新霁洛城端，千家积雪寒。
未收清禁色，偏向上阳残。','',''),('quantangshi-15085','尚书郎上直闻春漏','張少博','quantangshi','','卷16','建礼含香处，重城待漏辰。
徐声传凤阙，晓唱辨鸡人。
银箭听将尽，铜壶滴更新。
催筹当五夜，移刻及三春。
杳杳从天远，泠泠出禁频。
直庐残响曙，肃穆对钩陈。','',''),('quantangshi-15086','雪夜观象阙待漏','張少博','quantangshi','','卷16','残雪初睛后，鸣珂奉阙庭。
九门传晓漏，五夜候晨扃。
北斗横斜汉，东方落曙星。
烟氛初动色，簪佩未分形。
雪重犹垂白，山遥不辨青。
鸡人更唱处，偏入此时听。','',''),('quantangshi-15087','尚书郎上直闻春漏','周徹','quantangshi','','卷16','建礼通华省，含香直紫宸。
静闻铜史漏，暗识桂宫春。
滴沥疑将绝，清泠发更新。
寒声临雁沼，疎韵应鸡人。
迥入千门彻，行催五夜频。
高台闲自听，非是驻征轮。','',''),('quantangshi-15088','及第后赠试官','高拯','quantangshi','','卷16','公子求贤未识真，欲将毛遂比常伦。
当时不及三千客，今日何如十九人。','',''),('quantangshi-15089','赋得花发上林','王表','quantangshi','','卷16','御苑春何早，繁花已绣林。
笑迎明主仗，香拂美人簪。
地接楼台近，天垂雨露深。
晴光来戏蝶，夕景动栖禽。
欲托凌云势，先开捧日心。
方知桃李树，从此别成阴。','',''),('quantangshi-15090','清明日登城春望寄大夫使君','王表','quantangshi','','卷16','春城闲望爱睛天，何处风光不眼前。
寒食花开千树雪，清明日出万家烟。
兴来促席唯同舍，醉后狂歌尽少年。
闻说莺啼却惆怅，诗成不见谢临川。','',''),('quantangshi-15091','成德乐','王表','quantangshi','','卷16','赵女乘春上画楼，一声歌发满城秋。
无端更唱关山曲，不是征人亦泪流。','',''),('quantangshi-15092','花发上林','獨孤授','quantangshi','','卷16','上苑韶容早，芳菲正吐花。
无言向春日，闲笑任年华。
润色笼轻霭，睛光艳晚霞。
影连千户竹，香散万人家。
幸遶楼台近，仍怀雨露赊。
愿君垂采摘，不使落风沙。','',''),('quantangshi-15093','赋得花发上林','王儲','quantangshi','','卷16','东陆和风至，先开上苑花。
穠枝藏宿鸟，香蘂拂行车。
散白怜睛日，舒红爱晚霞。
桃间留御马，梅处入胡笳。
城郭连增媚，楼台映转华。
岂同幽谷草，春至发犹赊。','',''),('quantangshi-15094','赋得花发上林','周渭','quantangshi','','卷16','灼灼花凝雪，春来发上林。
向风初散蘂，垂叶欲成阴。
人过香随远，烟晴色自深。
净时空结雾，疎处未藏禽。
菶茸何年植，间关几日吟。
一枝如可冀，不负折芳心。','',''),('quantangshi-15095','赠龙兴观主吴崇岳','周渭','quantangshi','','卷16','楮为冠子布为裳，吞得丹霞寿最长。
混俗性灵常乐道，出尘风格早休粮。
枕中经妙谁传与，肘后方新自写将。
百尺松梢几飞步，鹤栖板上礼虚皇。','',''),('quantangshi-15096','从军有苦乐行','李益','quantangshi','','卷16','劳者且莫歌，我欲送君觞。
从军有苦乐，此曲乐未央。
仆居在陇上，陇水断人肠。
东过秦宫路，宫路入咸阳。
时逢汉帝出，谏猎至长杨。
讵驰游侠窟，非结少年场。
一旦承嘉惠，轻身重恩光。
秉笔参帷帟，从军至朔方。
边地多阴风，草木自凄凉。
断绝海云去，出没胡沙长。
参差引雁翼，隐辚腾军装。
劒文夜如水，马汗冻成霜。
侠气五都少，矜功六郡良。
山河起目前，睚眦死路傍。
北逐驱獯虏，西临复旧疆。
昔还赋余资，今出乃赢粮。
一矢弢夏服，我弓不再张。
寄语丈夫雄，苦乐身自当。','',''),('quantangshi-15097','登长城','李益','quantangshi','','卷16','汉家今上郡，秦塞古长城。
有日云长惨，无风沙自惊。
当今圣天子，不战四夷平。','',''),('quantangshi-15098','杂曲','李益','quantangshi','','卷16','妾本蚕家女，不识贵门仪。
藁砧持玉斧，交结五陵儿。
十日或一见，九日在路岐。
人生此夫壻，富贵欲何为。
杨柳徒可折，南山不可移。
妇人贵结发，宁有再嫁资。
嫁女莫望高，女心愿所宜。
宁从贱相守，不愿贵相离。
蓝叶郁重重，蓝花若榴色。
少妇归少年，华光自相得。
谁言配君子，以奉百年身。
有义即夫壻，无义还他人。
爱如寒炉火，弃若秋风扇。
山岳起面前，相看不相见。
丈夫非小儿，何用强相知。
不见朝生菌，易成还易衰。
征客欲临路，居人还出门。
北风河梁上，四野愁云繁。
岂不恋我家，夫壻多感恩。
前程有日月，勋绩在河源。
少妇马前立，请君听一言。
春至草亦生，谁能无别情。
殷勤展心素，见新莫忘故。
遥望孟门山，殷勤报君子。
既为随阳雁，勿学西流水。
尝闻生别离，悲莫悲于此。
同器不同荣，堂下即千里。
与君贫贱交，何异萍上水。
托身天使然，同生复同死。','',''),('quantangshi-15099','送辽阳使还军','李益','quantangshi','','卷16','征人歌且行，北上辽阳城。
二月戎马息，悠悠边草生。
青山出塞断，代地入云平。
昔者匈奴战，多闻杀汉兵。
平生报国愤，日夜角弓鸣。
勉君万里去，勿使虏尘惊。','',''),('quantangshi-15100','赋得早燕送别','李益','quantangshi','','卷16','碧草缦如线，去来双[飞燕]。
长门未有春，先入班姬殿。
梁空绕不息，檐寒窥欲遍。
今至随红萼，昔还悲素扇。
一别与秋鸿，差池讵相见。','',''),('quantangshi-15101','秋晚溪中寄怀大理齐司直','李益','quantangshi','','卷16','凤翔属明代，羽翼文葳蕤。
昆仑进琪树，飞舞下瑶池。
振仪自西睠，东夏复分厘。
国典唯平法，伊人方在斯。
荒岳宁桁杨肃，芳辉兰玉滋。
明质鹜高景，飘颻服缨绥。
天寒清洛苑，秋夕白云司。
况复空岩侧，苍苍幽桂期。
岁寒坐流霰，山川犹别离。
浩思凭尊酒，氛氲独含辞。','',''),('quantangshi-15102','溪中月下寄杨子尉封亮','李益','quantangshi','','卷16','蘅若夺幽色，衔思恍无悰。
宵长霜雾多，岁晏淮海风。
团团山中月，三五离夕同。
露凝朱弦绝，觞至兰玉空。
清光液流波，盛明难再逢。
尝恐河汉远，坐窥烟景穷。
小人谅处阴，君子树大功。
永愿厉高翼，慰我丹桂丛。','',''),('quantangshi-15103','春晚赋得余花落','李益','quantangshi','','卷16','留春春竟去，春去花如此。
蝶舞遶应稀，鸟惊飞讵已。
衰红辞故萼，繁绿扶雕蕊。
自委不胜愁，庭风那更起。','',''),('quantangshi-15104','闻亡友王七嘉禾寺得素琴','李益','quantangshi','','卷16','故人惜此去，留琴明月前。
今来我访旧，泪洒白云天。
讵欲匣孤响，送君归夜泉。
抚琴犹可绝，况此故无弦。
何必雍门奏，然后泪潺湲。','',''),('quantangshi-15105','校书郎杨凝往年以古镜贶别今追赠以诗','李益','quantangshi','','卷16','明镜出匣时，明如云间月。
一别青春鉴，回光照华髪。
美人昔自爱，鞶带手中结。
愿以三五期，经天无玷缺。','',''),('quantangshi-15106','置酒行','李益','quantangshi','','卷16','置酒命所欢，凭觞遂为戚。
日往不再来，兹辰坐成昔。
百龄非久长，五十将半百。
胡为劳我形，已须还复白。
西山鸾鹤羣，矫矫烟雾翮。
明霞发金丹，阴洞潜水碧。
安得凌风羽，崦嵫驻灵魄。
无然坐衰老，慙叹东陵柏。','',''),('quantangshi-15107','长社窦明府宅夜送王屋道士常究子','李益','quantangshi','','卷16','旦随三鸟去，羽节凌霞光。
暮与双凫宿，云车下紫阳。
天坛临月近，洞水出山长。
海峤年年别，丘陵徒自伤。','',''),('quantangshi-15108','观回军三韵','李益','quantangshi','','卷16','行行上陇头，陇月暗悠悠。
万里将军没，回旌陇戍秋。
谁令呜咽水，重入故营流。','',''),('quantangshi-15109','华山南庙','李益','quantangshi','','卷16','阴山临古道，古庙闭山碧。
落日春草中，搴芳荐瑶席。
明灵达精意，仿髴如不隔。
岩雨神降时，回飙入松栢。
常闻坑儒后，此地返秦璧。
自古害忠良，神其辅宗祏。','',''),('quantangshi-15110','喜邢校书远至对雨同赋远晚饭阮返五韵','李益','quantangshi','','卷16','雀噪空城阴，木衰羇思远。
已蔽青山望，徒悲白云晚。
别离千里风，雨中同一饭。
开径说逢康，临觞方接阮。
旅宦竟何如，劳飞思自返。','',''),('quantangshi-15111','城西竹园送裴佶王达','李益','quantangshi','','卷16','葳蕤凌风竹，寂寞离人觞。
怆怀非外至，沈郁自中肠。
远行从此始，别袂重凄霜。','',''),('quantangshi-15112','月下喜邢校书至自洛','李益','quantangshi','','卷16','天河夜未央，漫漫复苍苍。
重君远行至，及此明目光。
华星暎衰柳，暗水入寒塘。
客心定何似，余欢方自长。','',''),('quantangshi-15113','北至太原','李益','quantangshi','','卷16','炎祚昔昏替，皇基此郁盘。
玄命久已集，抚运良乃艰。
南厄羊肠险，北走雁门寒。
始于一戎定，垂此亿世安。
唐风本忧思，王业寔艰难。
中历虽横溃，天纪未可干。
圣明所兴国，灵岳固不殚。
咄咄薄游客，斯言殊不刊。','',''),('quantangshi-15114','入华山访隐者经仙人石坛','李益','quantangshi','','卷16','三考四岳下，官曹少休沐。
久负青山诺，今还获所欲。
尝闻玉清洞，金简受玄箓。
夙驾升天行，云游恣霞宿。
平明矫轻策，扪石入空曲。
仙人古石坛，苔遶青瑶局。
阳桂凌烟紫，阴萝冒水绿。
隔世闻丹经，悬泉注明玉。
前惊羽人会，白日天居肃。
问我将致辞，笑之自相目。
竦身云遂起，仰见双白鹄。
堕其一纸书，文字类鸟足。
视之了不识，三返又三复。
归来问方士，举世莫解读。
何必若蜉蝣，然后为局促。
鄙哉宦游子，身志俱降辱。
再往不及期，劳歌叩山木。','',''),('quantangshi-15115','罢镜','李益','quantangshi','','卷16','手中青铜镜，照我少年时。
衰飒一如此，清光难复持。
欲令孤月掩，从遣半心疑。
纵使逢人见，犹胜自见悲。','',''),('quantangshi-15116','华阴东泉同张处士诣藏律师兼简县内同官因寄齐中书','李益','quantangshi','','卷16','苍崖抱寒泉，沦照洞金碧。
潜鳞孕明晦，山灵閟幽赜。
前峯何其诡，万变穷日夕。
松老风易悲，山秋云更白。
故人邑中吏，五里仙雾隔。
美质简琼瑶，英声铿金石。
烦君竟相问，问我此何适。
我因赞时理，书寄西飞翮。
哲匠熙百工，日月被光泽。
大国本多士，荆岑无遗璧。
高网弥八纮，皇图明四辟。
羣材既兼畅，顾我在草泽。
贵无身外名，贱有区中役。
忽忽百龄内，殷殷千虑迫。
人生已如寄，在寄复为客。
旧国不得归，风尘满阡陌。','',''),('quantangshi-15117','答郭黄中孤云首章见赠','李益','quantangshi','','卷16','孤云生西北，从风东南飘。
帝乡日已远，苍梧无还飙。
已矣玄凤叹，严霜集灵苕。
君其勉我怀，岁暮孰不雕。','',''),('quantangshi-15118','合源溪期张计不至','李益','quantangshi','','卷16','霜露肃时序，缅然方独寻。
暗溪迟仙侣，寒涧闻松禽。
寂历兹夜永，清明秋序深。
微波澹澄夕，烟景含虚林。
素志久沦否，幽怀方自吟。','',''),('quantangshi-15119','竹溪','李益','quantangshi','','卷16','访竹越云崖，即林若溪绝。
宁知修干下，漠漠秋苔洁。
清光溢空曲，茂色临幽澈。
采摘愧芳鲜，奉君岁暮节。','',''),('quantangshi-15120','送诸曁王主簿之任','李益','quantangshi','','卷16','别愁已万绪，离曲方三奏。
远宦一辞乡，南天异风候。
秦城岁芳老，越国春山秀。
落日望寒涛，公门闭清昼。
何用慰相思，裁书寄关右。','',''),('quantangshi-15121','罢秩后入华山采茯苓逢道者','李益','quantangshi','','卷16','委绶来名山，观奇恣所停。
山中若有闻，言此不死庭。
遂逢五老人，一谓西岳灵。
或闻樵人语，飞去入昴星。
授我出云路，苍然凌石屏。
视之有文字，乃古黄庭经。
左右长松列，动摇风露零。
上蟠千年枝，阴虬负青冥。
下结九秋霰，流膏为茯苓。
取之砂石间，异若龟鹤形。
况闻秦宫女，华发变已青。
有如上帝心，与我千万龄。
始疑有仙骨，炼魂可永宁。
何事逐豪游，饮啄以膻腥。
神物亦自閟，风雷护此扃。
欲传山中宝，回策忽已暝。
乃悲世上人，求醒终不醒。','',''),('quantangshi-15122','自朔方还与郑式瞻崔称郑子周岑赞同会法云寺三门避暑','李益','quantangshi','','卷16','予本疎放士，朅来非外矫。
误落边尘中，爱山见山少。
始投清凉宇，门值烟岫表。
参差互明灭，彩翠竟昏晓。
泠泠远风来，过此羣木杪。
英英二三彦，襟旷去烦扰。
游川出潜鱼，息阴倦飞鸟。
徇物不可穷，唯于此心了。','',''),('quantangshi-15123','来从窦车骑行','李益','quantangshi','','卷16','束发逢世屯，怀恩抱明义。
读书良有感，学劒慙非智。
遂别鲁诸生，来从窦车骑。
追兵赴边急，络马黄金辔。
出入燕南陲，由来重意气。
自经臯兰战，又破楼烦地。
西北护三边，东南留一尉。
时过歘如云，参差不自意。
将军失恩泽，万事从此异。
置酒高台上，薄暮秋风至。
长戟与我归，归来同弃置。
自酌还自饮，非名又非利。
歌出易水寒，琴下雍门泪。
出逢平乐旧，言在天阶侍。
问我从军苦，自陈少年贵。
丈夫交四海，徒论身自致。
汉将不封侯，苏卿劳远使。
今我终此曲，此曲诚不易。
贵人难识心，何由知忌讳。','',''),('quantangshi-15124','夜发军中','李益','quantangshi','','卷16','边马枥上惊，雄劒匣中鸣。
半夜军书致，匈奴寇六城。
中坚分暗阵，太乙起神兵。
出没风云合，苍黄豺虎争。
今日边庭战，缘赏不缘名。','',''),('quantangshi-15125','将赴朔方早发汉武泉','李益','quantangshi','','卷16','弭盖出故关，穷秋首边路。
问我此何为，平生重一顾。
风吹山下草，系马河边树。
奉役良有期，回瞻终未屡。
去乡幸未远，戎衣今已故。
岂惟幽朔寒，念我机中素。
去矣勿复言，所酬知音遇。','',''),('quantangshi-15126','城傍少年','李益','quantangshi','','卷16','长生边城傍，出身事弓马。
少年有胆气，独猎阴山下。
偶与匈奴逢，曾擒射雕者。
名悬壮士籍，请君少相假。','',''),('quantangshi-15127','游子吟','李益','quantangshi','','卷16','女羞夫壻薄，客耻主人贱。
遭遇同众流，低回愧相见。
君非青铜镜，何事空照面。
莫以衣上尘，不谓心如练。
人生当荣盛，待士勿言倦。
君看白日驰，何异弦上箭。','',''),('quantangshi-15128','饮马歌','李益','quantangshi','','卷16','百马饮一泉，一马争上游。
一马喷成泥，百马饮浊流。
上有沧浪客，对之空叹息。
自顾缨上尘，裴回终日夕。
为问泉上翁，何时见沙石。','',''),('quantangshi-15129','莲塘驿','李益','quantangshi','','卷16','五月渡淮水，南行遶山陂。
江村远鸡应，竹里闻缲丝。
楚女肌发美，莲塘烟露滋。
菱花覆碧渚，黄鸟双飞时。
渺渺溯洄远，凭风托微词。
斜光动流睇，此意难自持。
女歌本轻艳，客行多怨思。
女萝蒙幽蔓，拟上青桐枝。','',''),('quantangshi-15130','五城道中','李益','quantangshi','','卷16','金铙随玉节，落日河边路。
沙鸣后骑来，雁起前军度。
五城鸣斥堠，三秦新召募。
天寒白登道，塞浊阴山雾。
仍闻旧兵老，尚在乌兰戍。
笳箫汉思繁，旌旗边色故。
寝兴倦弓甲，勤役伤风露。
来远赏不行，锋交勋乃茂。
未知朔方道，何年罢兵赋。','',''),('quantangshi-15131','与王楚同登青龙寺上方','李益','quantangshi','','卷16','连冈出古寺，流睇移芳宴。
鸟没汉诸陵，草平秦故殿。
摇光浅深树，拂木参差燕。
春心断易迷，远目伤难徧。
壮日各轻年，暮年方自见。','',''),('quantangshi-15132','登夏州城观送行人赋得六州胡儿歌','李益','quantangshi','','卷16','六州胡儿六蕃语，十岁骑羊逐沙鼠。
沙头牧马孤雁飞，汉军游骑貂锦衣。
云中征戍三千里，今日征行何岁归。
无定河边数株柳，共送行人一杯酒。
胡儿起作和蕃歌，齐唱呜呜尽垂手。
心知旧国西州远，西向胡天望乡久。
回头忽作异方声，一声回尽征人首。
蕃音虏曲一难分，似说边情向塞云。
故国关山无限路，风沙满眼堪断魂。
不见天边青作冢，古来愁杀汉昭君。','',''),('quantangshi-15133','从军夜次六胡北饮马磨劒石为祝殇辞','李益','quantangshi','','卷16','我行空碛，见沙之磷磷，与草之幂幂。
半没胡儿磨劒石，当时洗劒血成川。
至今草与沙皆赤，我因扣石问以言。
水流呜咽幽草根，君宁独不怪阴磷。
吹火荧荧又为碧，有鸟自称蜀帝魂。
南人伐竹湘山下，交根接叶满泪痕。
请君先问湘江水，然我此恨乃可论。
秦亡汉绝三十国，关山战死知何极。
风飘雨洒水自流，此中有冤消不得。
为之弹劒作哀吟，风沙四起云沈沈。
满营战马嘶欲尽，毕昴不见胡天阴。
东征曾吊长平苦，往往睛明独风雨。
年移代去感精魂，空山月暗闻鼙鼓。
秦坑赵卒四十万，未若格鬬伤戎虏。
圣君破胡为六州，六州又尽为胡丘。
韩公三城断胡路，汉甲百万屯边秋。
乃分司空授朔土，拥以玉节临诸侯。
汉为一雪万世讐，我今抽刀勒劒石，告尔万世为唐休。
又闻招魂有美酒，为我浇酒祝东流。
殇为魂兮，可以归还故乡些。
沙场地无人兮，尔独不可以久留。','',''),('quantangshi-15134','登天坛夜见海','李益','quantangshi','','卷16','朝游碧峯三十六，夜上天坛月边宿。
仙人携我搴玉英，坛上夜半东方明。
仙钟撞撞近海日，海中离离三山出。
霞梯赤城遥可分，霓旌绛节倚彤云。
八鸾五凤纷在御，王母欲上朝元君。
羣仙指此为我说，几见尘飞沧海竭。
竦身别我期丹宫，空山处处遗清风。
九州下视杳未旦，一半浮生皆梦中。
始知武皇求不死，去逐瀛洲羡门子。','',''),('quantangshi-15135','大礼毕皇帝御丹凤门改元建中大赦','李益','quantangshi','','卷16','大明曈曈天地分，六龙负日升天门。
凤凰飞来衔帝箓，言我万代金皇孙。
灵鸡鼓舞承天赦，高翔百尺垂朱幡。
宸居穆清受天历，建中甲子合上元。
昊穹景命即已至，王事乃可酬干坤。
升中告成答玄贶，泥金检玉昭鸿恩。
云亭之事略可记，七十二君宁独尊。
小臣欲上封禅表，久而未就归文园。','',''),('quantangshi-15136','轻薄篇','李益','quantangshi','','卷16','豪不必驰千骑，雄不在垂双鞬。
天生俊气自相逐，出与雕鹗同飞翻。
朝行九衢不得意，下鞭走马城西原。
忽闻燕雁一声去，回鞍挟弹平陵园。
归来青楼曲未半，美人玉色当金尊。
淮阴少年不相下，酒酣半笑倚市门。
安知我有不平色，白日欲落红尘昏。
死生容易如反掌，得意失意由一言。
少年但饮莫相问，此中报讐亦报恩。','',''),('quantangshi-15137','野田行','李益','quantangshi','','卷16','日没出古城，野田何茫茫。
寒狐啸青冢，鬼火烧白杨。
昔人未为泉下客，行到此中曾断肠。','',''),('quantangshi-15138','古别离','李益','quantangshi','','卷16','双劒欲别风凄然，雌沈水底雄上天。
江回汉转两不见，云交雨合知何年。
古来万事皆由命，何用临岐苦涕涟。','',''),('quantangshi-15139','效古促促曲为河上思妇作','李益','quantangshi','','卷16','促促何促促，黄河九回曲。
嫁与棹船郎，空牀将影宿。
不道君心不如石，那教妾貌长如玉。','',''),('quantangshi-15140','汉宫少年行','李益','quantangshi','','卷16','君不见上宫警夜营八屯，冬冬街鼓朝朱轩。
玉堦霜仗拥未合，少年排入铜龙门。
暗闻弦管九天上，宫漏沈沈清吹繁。
平明走马绝驰道，呼鹰挟弹通缭垣。
玉笼金锁养黄口，探雏取卵伴王孙。
分曹陆博快一掷，迎欢先意笑语喧。
巧为柔媚学优孟，儒衣嬉戏冠沐猿。
晚来香街经柳市，行过倡舍宿桃根。
相逢杯酒一言失，回朱点白闻至尊。
金张许史伺颜色，王侯将相莫敢论。
岂知人事无定势，朝欢暮戚如掌翻。
椒房宠移子爱夺，一夕秋风生戾园。
徒用黄金将买赋，宁知白玉暗成痕。
持杯收水水已覆，徙薪避火火更燔。
欲求四老张丞相，南山如天不可上。','',''),('quantangshi-15141','竹窗闻风寄苗发司空曙','李益','quantangshi','','卷16','微风惊暮坐，临牖思悠哉。
开门复动竹，疑是故人来。
时滴枝上露，稍沾堦下苔。
何当一入幌，为拂绿琴埃。','',''),('quantangshi-15142','赋得垣衣','李益','quantangshi','','卷16','漠漠复霏霏，为君垣上衣。
昭阳辇下草，应笑此生非。
掩蔼青春去，苍茫白露稀。
犹胜萍逐水，流浪不相依。','',''),('quantangshi-15143','送人流贬','李益','quantangshi','','卷16','汉章虽约法，秦律已除名。
谤远人多惑，官微不自明。
霜风先独树，瘴雨失荒城。
畴昔长沙事，三年召贾生。','',''),('quantangshi-15144','送人南归','李益','quantangshi','','卷16','人言下江疾，君道下江迟。
五月江路恶，南风惊浪时。
应知近家喜，还有异乡悲。
无奈孤舟夕，山歌闻竹枝。','',''),('quantangshi-15145','水亭夜坐赋得晓雾','李益','quantangshi','','卷16','月落寒雾起，沈思浩通川。
宿禽啭木散，山泽一苍然。
漠漠沙上路，沄沄洲外田。
犹当依远树，断续欲穷天。','',''),('quantangshi-15146','送常曾侍御使西蕃寄题西川','李益','quantangshi','','卷16','凉王宫殿尽，芜没陇云西。
今日闻君使，雄心逐鼓鼙。
行当收汉垒，直可取蒲泥。
旧国无由到，烦君下马题。','',''),('quantangshi-15147','入南山至全师兰若','李益','quantangshi','','卷16','木陨水归壑，寂然无念心。
南行有真子，被褐息山阴。
石路瑶草散，松门寒景深。
吾师亦何爱，自起定中吟。','',''),('quantangshi-15148','送韩将军还边','李益','quantangshi','','卷16','白马羽林儿，扬鞭薄暮时。
独将轻骑出，暗与伏兵期。
雨雪移军远，旌旗上壠迟。
圣心戎寄重，未许让恩私。','',''),('quantangshi-15149','晚春卧病喜振上人见访','李益','quantangshi','','卷16','卧牀如旧日，窥户易伤春。
灵寿扶衰力，芭蕉对病身。
道心空寂寞，时物自芳新。
旦夕谁相访，唯当摄上人。','',''),('quantangshi-15150','春行','李益','quantangshi','','卷16','侍臣朝谒罢，戚里自相过。
落日青丝骑，春风白紵歌。
恩承三殿近，猎向五陵多。
归路南桥望，垂杨拂细波。','',''),('quantangshi-15151','洛阳河亭奉酬留守羣公追送','李益','quantangshi','','卷16','离亭饯落晖，腊酒减春衣。
岁晚烟霞重，川寒云树微。
戎装千里至，旧路十年归。
还似汀洲雁，相逢又背飞。','',''),('quantangshi-15152','寻纪道士偶会诸叟','李益','quantangshi','','卷16','山阴寻道士，暎竹羽衣新。
侍坐双童子，陪游五老人。
水花松下静，坛草雪中春。
见说桃源洞，如今犹避秦。','',''),('quantangshi-15153','同萧炼师宿太乙庙','李益','quantangshi','','卷16','微月空山曙，春祠谒少君。
落花坛上拂，流水洞中闻。
酒引芝童奠，香余桂子焚。
鹤飞将羽节，遥向赤城分。','',''),('quantangshi-15154','送同落第者东归','李益','quantangshi','','卷16','东门有行客，落日满前山。
圣代谁知者，沧洲今独还。
片云归海暮，流水背城闲。
余亦依嵩颍，松花深闭关。','',''),('quantangshi-15155','送柳判官赴振武','李益','quantangshi','','卷16','边庭汉仪重，旌甲似云中。
虏地山川壮，单于鼓角雄。
关寒塞榆落，月白胡天风。
君逐嫖姚将，麒麟有战功。','',''),('quantangshi-15156','述怀寄衡州令狐相公','李益','quantangshi','','卷16','调元方翼圣，轩盖忽言东。
道以中枢密，心将外理同。
白头生远浪，丹叶下高枫。
江上萧疎雨，何人对谢公。','',''),('quantangshi-15157','喜入兰陵望紫阁峯呈宣上人','李益','quantangshi','','卷16','剃草开三径，巢林喜一枝。
地宽留种竹，泉浅欲开池。
紫阁当疎牖，青松入坏篱。
从今安僻陋，萧相是吾师。','',''),('quantangshi-15158','喜见外弟又言别','李益','quantangshi','','卷16','十年离乱后，长大一相逢。
问姓惊初见，称名忆旧容。
别来沧海事，语罢暮天钟。
明日巴陵道，秋山又几重。','',''),('quantangshi-15159','立春日宁州行营因赋朔风吹飞雪','李益','quantangshi','','卷16','边声日夜合，朔风惊复来。
龙山不可望，千里一裴回。
捐扇破谁执，素纨轻欲裁。
非时妬桃李，自是舞阳台。','',''),('quantangshi-15160','献刘济','李益','quantangshi','','卷16','草绿古燕州，莺声引独游。
雁归天北畔，春尽海西头。
向日花偏落，驰年水自流。
感恩知有地，不上望京楼。','',''),('quantangshi-15161','哭柏岩禅师','李益','quantangshi','','卷16','遍与傍人别，临终尽不愁。
影堂谁为扫，坐塔自看修。
白日钟边晚，青苔钵上秋。
天涯禅弟子，空到柏岩游。','',''),('quantangshi-15162','赴邠宁留别','李益','quantangshi','','卷16','身承汉飞将，束发即言兵。
侠少何相问，从来事不平。
黄云断朔吹，白雪拥沙城。
幸应边书募，横戈会取名。','',''),('quantangshi-15163','紫骝马','李益','quantangshi','','卷16','争场看鬬鸡，白鼻紫骝嘶。
漳水春闺晚，丛台日向低。
歇鞍珠作汗，试劒玉如泥。
为谢红梁燕，年年妾独栖。','',''),('quantangshi-15164','夜上受降城闻笛','李益','quantangshi','','卷16','入夜思归切，笛声清更哀。
愁人不愿听，自到枕前来。
风起塞云断，夜深关月开。
平明独惆怅，落尽一庭梅。','',''),('quantangshi-15165','同崔邠登鹳雀楼','李益','quantangshi','','卷16','鹳雀楼西百尺樯，汀洲云树共茫茫。
汉家箫鼓空流水，魏国山河半夕阳。
事去千年犹恨速，愁来一日即为长。
风烟倂起思归望，远目非春亦自伤。','',''),('quantangshi-15166','奉酬崔员外副使携琴宿使院见示','李益','quantangshi','','卷16','忽闻此夜携琴宿，遂叹常时尘吏喧。
庭木已衰空月亮，城砧自急对霜繁。
犹持副节留军府，未荐高词直掖垣。
谁问南飞长绕树，官微同在谢公门。','',''),('quantangshi-15167','送贾校书东归寄振上人','李益','quantangshi','','卷16','北风吹雁数声悲，况指前林是别时。
秋草不堪频送远，白云何处更相期。
山随匹马行看暮，路入寒城独去迟。
为向东州故人道，江淹已拟惠休诗。','',''),('quantangshi-15168','过马嵬二首 一','李益','quantangshi','','卷16','路至墙垣问樵者，顾予云是太真宫。
太真血染马蹄尽，朱阁影随天际空。
丹壑不闻歌吹夜，玉堦唯有薜萝风。
世人莫重霓裳曲，曾致干戈是此中。','',''),('quantangshi-15169','过马嵬二首 二','李益','quantangshi','','卷16','金甲银旌尽已回，苍茫罗袖隔风埃。
浓香犹自随鸾辂，恨魄无由离马嵬。
南内真人悲帐殿，东溟方士问蓬莱。
唯留坡畔弯环月，时送残辉入夜台。','',''),('quantangshi-15170','盐州过胡儿饮马泉','李益','quantangshi','','卷16','绿杨着水草如烟，旧是胡儿饮马泉。
几处吹笳明月夜，何人倚劒白云天。
从来冻合关山路，今日分流汉使前。
莫遣行人照容鬓，恐惊憔悴入新年。','',''),('quantangshi-15171','宿冯翊夜雨赠主人','李益','quantangshi','','卷16','危心惊夜雨，起望漫悠悠。
气耿残灯暗，声繁高树秋。
凉轩辞夏扇，风幌揽轻裯。
思绪蓬初断，归期燕暂留。
关山蔼已失，脸泪逬难收。
赖君时一笑，方能解四愁。','',''),('quantangshi-15172','送襄阳李尚书','李益','quantangshi','','卷16','天寒发梅柳，忆昔到襄州。
树暖然红烛，江清展碧油。
风烟临岘首，云水接昭丘。
俗尚春秋学，词称文选楼。
都门送旌节，符竹领诸侯。
汉沔分戎寄，黎元减圣忧。
时追山简兴，本自习家流。
莫废思康乐，诗情满沃洲。','',''),('quantangshi-15173','春日晋祠同声会集得疎字韵','李益','quantangshi','','卷16','风壤瞻唐本，山祠阅晋余。
水亭开帟幕，岩榭引簪裾。
地绿苔犹少，林黄柳尚疎。
菱苕生皎镜，金碧照澄虚。
翰苑声何旧，宾筵醉止初。
中州有辽雁，好为系边书。','',''),('quantangshi-15174','再赴渭北使府留别','李益','quantangshi','','卷16','结发逐鸣鼙，连兵追谷蠡。
山川搜伏虏，铠甲被重犀。
故府旌旗在，新军羽校齐。
报恩身未死，识路马还嘶。
列嶂高烽举，当营太白低。
平戎七尺劒，封检一丸泥。
截海取蒲类，跑泉饮䴙鹈。
汉庭中选重，更事五原西。','',''),('quantangshi-15175','送归中丞使新罗册立吊祭','李益','quantangshi','','卷16','东望扶桑日，何年是到时。
片帆通雨露，积水隔华夷。
浩渺风来远，虚明鸟去迟。
长波静云月，孤岛宿旌旗。
别叶传秋意，回潮动客思。
沧溟无旧路，何处问前期。','',''),('quantangshi-15176','赋得路傍一株柳送邢校书赴延州使府','李益','quantangshi','','卷16','路傍一株柳，此路向延州。
延州在何处，此路起悠悠。','',''),('quantangshi-15177','重赠邢校书','李益','quantangshi','','卷16','俱从四方事，共会九秋中。
断蓬与落叶，相值各因风。','',''),('quantangshi-15178','照镜','李益','quantangshi','','卷16','衰鬓朝临镜，将看却自疑。
慙君明似月，照我白如丝。','',''),('quantangshi-15179','书院无历日以诗代书问路侍御六月大小','李益','quantangshi','','卷16','野性迷尧历，松窗有道经。
故人为柱史，为我数堦蓂。','',''),('quantangshi-15180','闻鸡赠主人','李益','quantangshi','','卷16','胶胶司晨鸣，报尔东方旭。
无事恋君轩，今君重凫鹄。','',''),('quantangshi-15181','登白楼见白鸟席上命鹧鸪辞','李益','quantangshi','','卷16','一鸟如霜雪，飞向白楼前。
问君何以至，天子太平年。','',''),('quantangshi-15182','石楼山见月','李益','quantangshi','','卷16','紫塞连年戍，黄砂碛路穷。
故人今夜宿，见月石楼中。','',''),('quantangshi-15183','惜春伤同幕故人孟郎中兼呈去年看花友','李益','quantangshi','','卷16','畏老身全老，逢春解惜春。
今年看花伴，已少去年人。','',''),('quantangshi-15184','嘉禾寺见亡友王七题壁','李益','quantangshi','','卷16','今日忆君处，忆君君岂知。
空余暗尘字，读罢泪仍垂。','',''),('quantangshi-15185','听唱赤白桃李花','李益','quantangshi','','卷16','赤白桃李花，先皇在时曲。
欲向西宫唱，西宫[宫]树绿。','',''),('quantangshi-15186','江南词','李益','quantangshi','','卷16','嫁得瞿塘贾，朝朝悞妾期。
早知潮有信，嫁与弄潮儿。','',''),('quantangshi-15187','赠内兄卢纶','李益','quantangshi','','卷16','世故中年别，余生此会同。
却将悲与病，来对朗陵翁。','',''),('quantangshi-15188','答窦二曹长留酒还榼','李益','quantangshi','','卷16','榼小非由榼，星朗是酒星。
解酲元有数，不用吓刘伶。','',''),('quantangshi-15189','答广宣供奉问兰陵居','李益','quantangshi','','卷16','居北有朝路，居南无住人。
劳师问家第，山色是南邻。','',''),('quantangshi-15190','乞宽禅师瘿山罍呈宣供奉','李益','quantangshi','','卷16','石色凝秋藓，峰形若夏云。
谁留秦苑地，好赠杏溪君。','',''),('quantangshi-15191','观骑射','李益','quantangshi','','卷16','边头射雕将，走马出中军。
远见平原上，翻身向暮云。','',''),('quantangshi-15192','幽州赋诗见意时佐刘幕','李益','quantangshi','','卷16','征戍在桑干，年年蓟水寒。
殷勤驿西路，北去向长安。','',''),('quantangshi-15193','军次阳城烽舍北流泉','李益','quantangshi','','卷16','何地可潸然，阳城烽树边。
今朝望乡客，不饮北流泉。','',''),('quantangshi-15194','金吾子','李益','quantangshi','','卷16','绣帐博山炉，银鞍冯子都。
黄昏莫攀折，惊起欲栖乌。','',''),('quantangshi-15195','山鹧鸪词','李益','quantangshi','','卷16','湘江斑竹枝，锦翅鹧鸪飞。
处处湘云合，郎从何处归。','',''),('quantangshi-15196','立秋前一日览镜','李益','quantangshi','','卷16','万事销身外，生涯在镜中。
唯将满鬓雪，明日对秋风。','',''),('quantangshi-15197','代人乞花','李益','quantangshi','','卷16','绣户朝眠起，开帘满地花。
春风解人意，欲落妾西家。','',''),('quantangshi-15198','上洛桥','李益','quantangshi','','卷16','金谷园中柳，春来似舞腰。
何堪好风景，独上洛阳桥。','',''),('quantangshi-15199','扬州怀古','李益','quantangshi','','卷16','故国歌钟地，长桥车马尘。
彭城阁边柳，偏似不胜春。','',''),('quantangshi-15200','水宿闻雁','李益','quantangshi','','卷16','早雁忽为双，惊秋风水窗。
夜长人自起，星月满空江。','',''),('quantangshi-15201','扬州早雁','李益','quantangshi','','卷16','江上三千雁，年年过故宫。
可怜江上月，偏照断根蓬。','',''),('quantangshi-15202','下楼','李益','quantangshi','','卷16','话旧全应老，逢春喜又悲。
看花行拭泪，倍觉下楼迟。','',''),('quantangshi-15203','度破讷沙二首 一','李益','quantangshi','','卷16','眼见风来沙旋移，经年不省草生时。
莫言塞北无春到，总有春来何处知。','',''),('quantangshi-15204','度破讷沙二首 二','李益','quantangshi','','卷16','破讷沙头雁正飞，䴙鹈泉上战初归。
平明日出东南地，满碛寒光生铁衣。','',''),('quantangshi-15205','拂云堆','李益','quantangshi','','卷16','汉将新从虏地来，旌旗半上拂云堆。
单于每近沙场猎，南望阴山哭始回。','',''),('quantangshi-15206','中桥北送穆质兄弟应制戏赠萧二策','李益','quantangshi','','卷16','洛水桥边雁影疎，陆机兄弟驻行车。
欲陈汉帝登封草，犹待萧郎寄内书。','',''),('quantangshi-15207','九月十日雨中过张伯佳期柳镇未至以诗招之','李益','quantangshi','','卷16','柳吴兴近无消息，张长公贫苦寂寥。
唯有角巾霑雨至，手持残菊向西招。','',''),('quantangshi-15208','汴河曲','李益','quantangshi','','卷16','汴水东流无限春，隋家宫阙已成尘。
行人莫上长堤望，风起杨花愁杀人。','',''),('quantangshi-15209','塞下曲 一','李益','quantangshi','','卷16','蕃州部落能结束，朝暮驰猎黄河曲。
燕歌未断塞鸿飞，牧马羣嘶边草绿。','',''),('quantangshi-15210','塞下曲 二','李益','quantangshi','','卷16','秦筑长城城已摧，汉武北上单于台。
古来征战虏不尽，今日还复天兵来。','',''),('quantangshi-15211','塞下曲 三','李益','quantangshi','','卷16','黄河东流流九折，沙场埋恨何时绝。
蔡琰没去造胡笳，苏武归来持汉节。','',''),('quantangshi-15212','塞下曲 四','李益','quantangshi','','卷16','为报如今都护雄，匈奴且莫下云中。
请书塞北阴山石，愿比燕然车骑功。','',''),('quantangshi-15213','夜上西城听梁州曲二首 一','李益','quantangshi','','卷16','行人夜上西城宿，听唱梁州双筦逐。
此时秋月满关山，何处关山无此曲。','',''),('quantangshi-15214','夜上西城听梁州曲二首 二','李益','quantangshi','','卷16','鸿雁新从北地来，闻声一半却飞回。
金河戍客肠应断，更在秋风百尺台。','',''),('quantangshi-15215','暖川','李益','quantangshi','','卷16','胡风冻合䴙鹈泉，牧马千羣逐暖川。
塞外征行无尽日，年年移帐雪中天。','',''),('quantangshi-15216','过马嵬','李益','quantangshi','','卷16','汉将如云不直言，寇来翻罪绮罗恩。
托君休洗莲花血，留记千年妾泪痕。','',''),('quantangshi-15217','答许五端公马上口号','李益','quantangshi','','卷16','晚逐旌旗俱白首，少游京洛共缁尘。
不堪身外悲前事，强向杯中觅旧春。','',''),('quantangshi-15218','牡丹','李益','quantangshi','','卷16','紫蕊丛开未到家，却教游客赏繁华。
始知年少求名处，满眼空中别有花。','',''),('quantangshi-15219','边思','李益','quantangshi','','卷16','腰悬锦带佩吴钩，走马曾防玉塞秋。
莫笑关西将家子，秪将诗思入凉州。','',''),('quantangshi-15220','奉和武相公春晓闻莺','李益','quantangshi','','卷16','蜀道山川心易惊，缘窗残梦晓闻莺。
分明似写文君恨，万怨千愁弦上声。','',''),('quantangshi-15221','送客还幽州','李益','quantangshi','','卷16','惆怅秦城送独归，蓟门云树远依依。
秋来莫射南飞雁，从遣乘春更北飞。','',''),('quantangshi-15222','柳杨送客','李益','quantangshi','','卷16','青枫江畔白苹洲，楚客伤离不待秋。
君见隋朝更何事，柳杨南渡水悠悠。','',''),('quantangshi-15223','从军北征','李益','quantangshi','','卷16','天山雪后海风寒，横笛偏吹行路难。
碛里征人三十万，一时回向月明看。','',''),('quantangshi-15224','听晓角','李益','quantangshi','','卷16','边霜昨夜堕关榆，吹角当城汉月孤。
无限塞鸿飞不度，秋风卷入小单于。','',''),('quantangshi-15225','宫怨','李益','quantangshi','','卷16','露湿晴花春殿香，月明歌吹在昭阳。
似将海水添宫漏，共滴长门一夜长。','',''),('quantangshi-15226','暮过回乐烽','李益','quantangshi','','卷16','烽火高飞百尺台，黄昏遥自碛西来。
昔时征战回应乐，今日从军乐未回。','',''),('quantangshi-15227','奉和武相公郊居寓目','李益','quantangshi','','卷16','黄扉晚下禁垣钟，归坐南闱山万重。
独有月中高兴尽，雪峯明处见寒松。','',''),('quantangshi-15228','诣红楼院寻广宣不遇留题','李益','quantangshi','','卷16','柿叶翻红霜景秋，碧天如水倚红楼。
隔窗爱竹无人问，遣向邻房觅户钩。','',''),('quantangshi-15229','回军行','李益','quantangshi','','卷16','关城榆叶早疎黄，日暮沙云古战场。
表请回军掩尘骨，莫教士卒哭龙荒。','',''),('quantangshi-15230','邠宁春日','李益','quantangshi','','卷16','桃李年年上国新，风沙日日塞垣人。
伤心更见庭前柳，忽有千条欲占春。','',''),('quantangshi-15231','古瑟怨','李益','quantangshi','','卷16','破瑟悲秋已减弦，湘灵沈怨不知年。
感君拂拭遗音在，更奏新声明月天。','',''),('quantangshi-15232','夜宴观石将军舞','李益','quantangshi','','卷16','微月东南上戍楼，琵琶起舞锦缠头。
更闻横笛关山远，白草胡沙西塞秋。','',''),('quantangshi-15233','春夜闻笛','李益','quantangshi','','卷16','寒山吹笛唤春归，迁客相看泪满衣。
洞庭一夜无穷雁，不待天明尽北飞。','',''),('quantangshi-15234','扬州送客','李益','quantangshi','','卷16','南行直入鹧鸪羣，万岁桥边一送君。
闻道望乡闻不得，梅花暗落岭头云。','',''),('quantangshi-15235','统汉峰下','李益','quantangshi','','卷16','统汉峰西降户营，黄河战骨拥长城。
只今已勒燕然石，北地无人空月明。','',''),('quantangshi-15236','避暑女冠','李益','quantangshi','','卷16','雾袖烟裾云母冠，碧琉璃簟井冰寒。
焚香欲使三清鸟，静拂桐阴上玉坛。','',''),('quantangshi-15237','行舟','李益','quantangshi','','卷16','柳花飞入正行舟，卧引菱花信碧流。
闻道风光满扬子，天晴共上望乡楼。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-15238','隋宫燕','李益','quantangshi','','卷16','燕语如伤旧国春，宫花一落已成尘。
自从一闭风光后，几度飞来不见人。','',''),('quantangshi-15239','送人归岳阳','李益','quantangshi','','卷16','烟草连天枫树齐，岳阳归路子规啼。
春江万里巴陵戍，落日看沈碧水西。','',''),('quantangshi-15240','上汝州郡楼','李益','quantangshi','','卷16','黄昏鼓角似边州，三十年前上此楼。
今日山城对垂泪，伤心不独为悲秋。','',''),('quantangshi-15241','临滹沱见蕃使列名','李益','quantangshi','','卷16','漠南春色到滹沱，碧柳青青塞马多。
万里关山今不闭，汉家频许郅支和。','',''),('quantangshi-15242','写情','李益','quantangshi','','卷16','水纹珍簟思悠悠，千里佳期一夕休。
从此无心爱良夜，任他明月下西楼。','',''),('quantangshi-15243','夜上受降城闻笛','李益','quantangshi','','卷16','回乐峰前沙似雪，受降城下月如霜。
不知何处吹芦管，一夜征人尽望乡。','',''),('quantangshi-15244','赴渭北宿石泉驿南望黄堆烽','李益','quantangshi','','卷16','边城已在虏城中，烽火南飞入汉宫。
汉庭议事先黄老，麟阁何人定战功。','',''),('quantangshi-15245','逢归信偶寄','李益','quantangshi','','卷16','无事将心寄柳条，等闲书字满芭蕉。
乡关若有东流信，遣送扬州近驿桥。','',''),('quantangshi-15246','赠毛仙翁','李益','quantangshi','','卷16','玉树溶溶仙气深，含光混俗似无心。
长愁忽作鹤飞去，一片孤云何处寻。','',''),('quantangshi-15247','长干行','李益','quantangshi','','卷16','忆妾深闺里，烟尘不曾识。
嫁与长干人，沙头候风色。
五月南风兴，思君下巴陵。
八月西风起，想君发扬子。
去来悲如何，见少离别多。
湘潭几日到，妾梦越风波。
昨夜狂风度，吹折江头树。
渺渺暗无边，行人在何处。
好乘浮云骢，佳期兰渚东。
鸳鸯绿浦上，翡翠锦屏中。
自怜十五余，颜色桃花红。
那作商人妇，愁水复愁风。','',''),('quantangshi-15248','和丘员外题湛长史旧居','李益','quantangshi','','卷16','昔降英王顾。
屏身幽岩曲，灵波结繁笳。
爽籁赴鸣玉，运转春华至。
岁来山草绿，青松掩落晖。
白云竟空谷，伊人抚遗叹。
恻恻芳又缛，云谁斅美香。
分毫寄明牧。','',''),('quantangshi-15249','送客归振武','李益','quantangshi','','卷16','骏马事轻车，军行万里沙。
胡山通嗢落，汉节绕浑邪。
桂满天西月，芦吹塞北笳。
别离俱报主，路极不为赊。','',''),('quantangshi-15250','府试古镜','李益','quantangshi','','卷16','旧是秦时镜，今藏古匣中。
龙盘初挂月，凤舞欲生风。
石黛曾留殿，朱光适在宫。
应祥知道泰，鉴物觉神通。
肝胆诚难隐，妍媸信易穷。
幸居君子室，长愿免尘蒙。','',''),('quantangshi-15251','赠宣大师','李益','quantangshi','','卷16','一国沙弥独解诗，人人道胜惠林师。
先皇诏下征还日，今上龙飞入内时。
看月忆来松寺宿，寻花思作杏溪期。
因论佛地求心地，秪说常吟是住持。','',''),('quantangshi-15252','汉宫词','李益','quantangshi','','卷16','汉室长陵小市东，珠帘绣户对春风。
君王昨日移仙仗，玉辇将迎入汉中。','',''),('quantangshi-15253','江南曲','李益','quantangshi','','卷16','长乐花枝雨点销，江城日暮好相邀。
春楼不闭葳蕤锁，绿水回连宛转桥。','',''),('quantangshi-15254','宿石邑山中','李益','quantangshi','','卷16','浮云不共此山齐，山霭苍苍望转迷。
晓月暂飞高树里，秋河隔在数峯西。','',''),('quantangshi-15255','寄赠衡州杨使君','李益','quantangshi','','卷16','湘竹斑斑湘水春，衡阳太守虎符新。
朝来笑向归鸿道，早晚南飞见主人。','',''),('quantangshi-15256','途中寄李二','李益','quantangshi','','卷16','杨柳含烟灞岸春，年年攀折为行人。
好风若借低枝便，莫遣青丝扫路尘。','',''),('quantangshi-15257','寄许炼师','李益','quantangshi','','卷16','扫石焚香礼碧空，露华偏湿蕊珠宫。
如何说得天坛上，万里无云月在中。','',''),('quantangshi-15258','失题','李益','quantangshi','','卷16','世故相逢各未闲，百年多在别离间。
昨夜秋风今夜雨，不知何处入空山。','',''),('quantangshi-15259','塞下曲','李益','quantangshi','','卷16','伏波惟愿裹尸还，定远何须生入关。
莫遣只轮归海窟，仍留一箭射天山。','',''),('quantangshi-15260','上黄堆烽','李益','quantangshi','','卷16','心期紫阁山中月，身过黄堆烽上云。
年发已从书劒老，戎衣更逐霍将军。','',''),('quantangshi-15261','句','李益','quantangshi','','卷16','闲庭草色能留马，当路杨花不避人。','',''),('quantangshi-15262','古别离二首 一','李端','quantangshi','','卷16','水国叶黄时，洞庭霜落夜。
行舟闻商估，宿在枫林下。
此地送君还，茫茫似梦间。
后期知几日，前路转多山。
巫峡通湘浦，迢迢隔云雨。
天晴见海樯，月落闻津鼓。
人老自多愁，水深难急流。
清宵歌一曲，白首对汀洲。','',''),('quantangshi-15263','古别离二首 二','李端','quantangshi','','卷16','与君桂阳别，令君岳阳待。
后事忽差池，前期日空在。
木落雁嗷嗷，洞庭波浪高。
远山云似盖，极浦树如毫。
朝发能几里，暮来风又起。
如何两处愁，皆在孤舟里。
昨夜天月明，长川寒且清。
菊花开欲尽，荠菜泊来生。
下江帆势速，五两遥相逐。
欲问去时人，知投何处宿。
空令猿啸时泣对湘簟竹。','',''),('quantangshi-15264','折杨柳','李端','quantangshi','','卷16','东城攀柳叶，柳叶低着草。
少壮莫轻年，轻年有衰老。
柳发遍川冈，登高堪断肠。
雨烟轻漠漠，何树近君乡。
赠君折杨柳，颜色岂能久。
上客莫沾巾，佳人正回首。
新柳送君行，古柳伤君情。
突兀临荒渡，婆娑出旧营。
隋家两岸尽，陶宅五株荣。
日暮偏愁望，春山有鸟声。','',''),('quantangshi-15265','留别柳中庸','李端','quantangshi','','卷16','惆怅流水时，萧条背城路。
离人出古亭，嘶马入寒树。
江海正风波，相逢在何处。','',''),('quantangshi-15266','野亭三韵送钱员外','李端','quantangshi','','卷16','野菊开欲稀，寒泉流渐浅。
幽人步林后，叹此年华晚。
倚杖送行云，寻思故山远。','',''),('quantangshi-15267','归山招王逵','李端','quantangshi','','卷16','日长原野静，杖策步幽巘。
雉雊麦苗阴，蝶飞溪草晚。
我生好闲放，此去殊未返。
自是君不来，非关故山远。','',''),('quantangshi-15268','过谷口元赞善所居','李端','quantangshi','','卷16','入谷访君来，秋泉已堪涉。
林间人独坐，月下山相接。
重露湿苍苔，明灯照黄叶。
故交一不见，素发何稠叠。','',''),('quantangshi-15269','旅次岐山得山友书却寄凤翔张尹','李端','quantangshi','','卷16','本与戴征君，同师竹上坐。
偶为名利引，久废论真果。
昨日山信回，寄书来责我。','',''),('quantangshi-15270','九日赠司空文明','李端','quantangshi','','卷16','我有惆怅词，待君醉时说。
长来逢九日，难与菊花别。
摘却正开花，暂言花未发。','',''),('quantangshi-15271','芜城','李端','quantangshi','','卷16','昔人登此地，丘陇已前悲。
今日又非昔，春风能几时。
风吹城上树，草没城边路。
城里月明时，精灵自来去。','',''),('quantangshi-15272','送吉中孚拜官归楚州','李端','quantangshi','','卷16','才子神骨清，虚竦眉眼明。
貌应同衞玠，鬓且异潘生。
初戴莓苔帻，来过丞相宅。
满堂归道师，众口宗诗伯。
须臾里巷传，天子亦知贤。
出诏升高士，驰声在少年。
自为才哲爱，日与侯王会。
匡主一言中，荣亲千里外。
更闻仙士友，往往东回首。
驱石不成羊，指丹空毙狗。
孤帆淮上归，商估夜相依。
海雾寒将尽，天星晓欲稀。
潮头来始歇，浦口喧争发。
乡树尚和云，邻船犹带月。
到洞必伤情，巡房见旧名。
醮疎坛路涩，汲少井栏倾。
别我长安道，前期共须老。
方随水向山，肯惜花辞岛。
怅望执君衣，今朝风景好。','',''),('quantangshi-15273','荆州泊','李端','quantangshi','','卷16','南楼西下时，月里闻来棹。
桂水舳舻回，荆州津济闹。
移帷望星汉，引带思容貌。
今夜一江人，唯应妾身觉。','',''),('quantangshi-15274','春游乐','李端','quantangshi','','卷16','游童苏合弹，倡女蒲葵扇。
初日映城时，相思忽相见。
褰裳蹋路草，理鬓回花面。
薄暮不同归，留情此芳甸。','',''),('quantangshi-15275','千里思','李端','quantangshi','','卷16','凉州风月美，遥望居延路。
泛泛下天云，青青缘塞树。
燕山苏武上，海岛田横住。
更是草生时，行人出门去。','',''),('quantangshi-15276','白鹭咏','李端','quantangshi','','卷16','迥起来应近，高飞去自遥。
映林同落雪，拂水状飜潮。
犹有幽人兴，相逢到碧霄。','',''),('quantangshi-15277','冬夜与故友聚送吉校书','李端','quantangshi','','卷16','途穷别则怨，何必天涯去。
共作出门人，不见归乡路。
殷勤执杯酒，怅望送亲故。
月色入闲轩，风声落高树。
云霄望且远，齿发行应暮。
九日泣黄花，三秋悲白露。
君行过洛阳，莫向青山度。','',''),('quantangshi-15278','与苗员外山行','李端','quantangshi','','卷16','古人留路去，今日共君行。
若待青山尽，应逢白发生。
谁知到兰若，流落一书名。','',''),('quantangshi-15279','早春同庾侍郎题青龙上方院','李端','quantangshi','','卷16','相见惜余辉，齐行登古寺。
风烟结远恨，山水含芳意。
车马莫前归，留看巢鹤至。','',''),('quantangshi-15280','送从叔赴洪州','李端','quantangshi','','卷16','荣家兼佐幕，叔父似还乡。
王粲名虽重，郄超髯未长。
鸣桡过夏口，敛笏见浔阳。
后夜相思处，中庭月一方。','',''),('quantangshi-15281','送路司谏侍从叔赴洪州','李端','quantangshi','','卷16','郄超本绝伦，得意在芳春。
勋业耿家盛，风流荀氏均。
声名金作赋，白皙玉为身。
敛笏辞天子，乘龟从丈人。
度关行且猎，鞍马何躞蹀。
猿啸暮应愁，湖流春好涉。
浔阳水分送，于越山相接。
梅雨细如丝，蒲帆轻似叶。
逢风燕不定，值石波先叠。
楼见远公庐，船经徐穉业。
邑人多秉笔，州吏亦负笈。
村女解收鱼，津童能用檝。
唯我有荆扉，无成未得归。
见君兄弟出，今日自霑衣。','',''),('quantangshi-15282','病后游青龙寺','李端','quantangshi','','卷16','病来形貌秽，斋沫入东林。
境静闻神远，身羸向道深。
芭蕉高自折，荷叶大先沈。','',''),('quantangshi-15283','夜寻司空文明逢深上人因寄晋侍御','李端','quantangshi','','卷16','鹤裘筇竹杖，语笑过林中。
正是月明夜，陶家见远公。
自嫌山客务，不与汉官同。','',''),('quantangshi-15284','长安书事寄薛戴','李端','quantangshi','','卷16','朔雁去成行，哀蝉响如昨。
时芳一憔悴，暮序何萧索。
笑语且无聊，逢迎多约略。
三山不可见，百岁空挥霍。
故事尽为愁，新知无复乐。
夫君又离别，而我加寂寞。
惠远纵相寻，陶潜祗独酌。
主人恩则厚，客子才自薄。
委曲见提携，因循成蹇剥。
论边书未上，招隐诗还作。
贵者已朝餐，岂能敦宿诺。
飞禽虽失树，流水长思壑。
千里寄琼枝，梦寐青山郭。','',''),('quantangshi-15285','鲜于少府宅看花','李端','quantangshi','','卷16','谢家能植药，万簇相萦倚。
烂熳绿苔前，婵娟青草里。
垂栏复照户，映竹仍临水。
骤雨发芳香，回风舒锦绮。
孤光杂新故，众色更重累。
散碧出疎茎，分黄成细蘂。
游蜂高更下，惊蝶坐还起。
玉貌对应慙，霞标方不似。
春阴怜弱蔓，夏日同短晷。
回落报荣衰，交关鬬红紫。
花时苟未赏，老至谁能止。
上客屡移牀，幽僧劳凭几。
初合虽薄劣，却得陪君子。
敢问贤主人，何如种桃李。','',''),('quantangshi-15286','慈恩寺怀旧','李端','quantangshi','','卷16','去者不可忆，旧游相见时。
凌霄徒更发，非是看花期。
倚玉交文友，登龙年月久。
东阁许联牀，西郊亦携手。
彼苍何暖昧，薄劣翻居后。
重入远师溪，谁尝陶令酒。
伊昔会禅宫，容辉在眼中。
篮舆来问道，玉柄解谈空。
孔席亡颜子，僧堂失谢公。
遗文一书壁，新竹再移丛。
始聚终成散，朝欢暮不同。
春霞方照日，夜烛忽迎风。
蚁鬬声犹在，鸮灾道已穷。
问天应默默，归宅太匆匆。
凄其履还路，莽苍云林暮。
九陌似无人，五陵空有雾。
缅怀山阳笛，永恨平原赋。
错莫过门栏，分明识行路。
上智本全真，郄公况重臣。
唯应抚灵运，暂是忆嘉宾。
存信松犹小，缄哀草尚新。
鲤庭埋玉树，那忍见门人。','',''),('quantangshi-15287','赠薛戴','李端','quantangshi','','卷16','晓雾忽为霜，寒蝉还罢响。
行人在长道，日暮多归想。
射策本何功，名登绛帐中。
遂矜丘室重，不料阮途穷。
交结慙时辈，龙钟似老翁。
机非鄙夫正，懒是平生性。
欹枕鸿雁高，闭关花药盛。
厨烟当雨绝，阶竹连窗暝。
欲赋苦饥行，无如消渴病。
旧业历胡尘，荒原少四邻。
田园空有处，兄弟未成人。
毛义心长苦，袁安家转贫。
今呈胸臆事，当为泪沾巾。','',''),('quantangshi-15288','东门送客','李端','quantangshi','','卷16','绿杨新草路，白发故乡人。
既壮还应老，游梁复滞秦。
逢花莫漫折，能有几多春。','',''),('quantangshi-15289','送韩绅卿','李端','quantangshi','','卷16','春雨昨开花，秋霜忽霑草。
荣枯催日夕，去住皆须老。
君望汉家原，高坟渐成道。','',''),('quantangshi-15290','襄阳曲','李端','quantangshi','','卷16','襄阳堤路长，草碧柳枝黄。
谁家女儿临夜妆，红罗帐里有灯光。
雀钗翠羽动明璫，欲出不出脂粉香。
同居女伴正衣裳，中庭寒月白如霜。
贾生十八称才子，空得门前一断肠。','',''),('quantangshi-15291','胡腾儿','李端','quantangshi','','卷16','胡腾身是凉州儿，肌肤如玉鼻如锥。
桐布轻衫前后卷，葡萄长带一边垂。
帐前跪作本音语，拾襟搅袖为君舞。
安西旧牧收泪看，洛下词人抄曲与。
扬眉动目踏花毡，红汗交流珠帽偏。
醉却东倾又西倒，双靴柔弱满灯前。
环行急蹴皆应节，反手叉腰如却月。
丝桐忽奏一曲终，呜呜画角城头发。
胡腾儿，胡腾儿，故乡路断知不知。','',''),('quantangshi-15292','赠康洽','李端','quantangshi','','卷16','黄须康兄酒泉客，平生出入王侯宅。
今朝醉卧又明朝，忽忆故乡头已白。
流年恍惚瞻西日，陈事苍茫指南陌。
声名恒压鲍参军，班位不过扬执戟。
迩来七十遂无机，空是咸阳一布衣。
后辈轻肥贱衰朽，五侯门馆许因依。
自言万物有移改，始信桑田变成海。
同时献赋人皆尽，共壁题诗君独在。
步出东城风景和，青山满眼少年多。
汉家尚壮今则老，发短心长知奈何。
华堂举杯白日晚，龙钟相见谁能免。
君今已反我正来，朱颜宜笑能几回。
借问朦胧花树下，谁家畚插筑高台。','',''),('quantangshi-15293','瘦马行','李端','quantangshi','','卷16','城傍牧马驱未过，一马徘徊起还卧。
眼中有泪皮有疮，骨毛焦瘦令人伤。
朝朝放在儿童手，谁觉举头看故乡。
往时汉地相驰逐，如雨如风过平陆。
岂意今朝驱不前，蚊蚋满身泥上腹。
路人识是名马儿，畴昔三军不得骑。
玉勒金鞍既已远，追奔获兽有谁知。
终身枥上食君草，遂与驽骀一时老。
傥借长鸣陇上风，犹期一战安西道。','',''),('quantangshi-15294','杂歌呈郑锡司空文明','李端','quantangshi','','卷16','昨宵梦到亡何乡，忽见一人山之阳。
高冠长剑立石堂，鬓眉飒爽瞳子方。
胡麻作饭琼作浆，素书一帙在柏牀。
啖我还丹拍我背，令我延年在人代。
乃书数字与我持，小儿归去须读之。
觉来知是虚无事，山中雪平云覆地。
东岭啼猿三四声，卷帘一望心堪碎。
蓬莱有梯不可蹑，向海回头泪盈睫。
且闻童子是苍蝇，谁谓庄生异蝴蝶。
学仙去来辞故人，长安道路多风尘。','',''),('quantangshi-15295','杂歌','李端','quantangshi','','卷16','汉水至清泥则浊，松枝至坚萝则弱。
十三女儿事他家，颜色如花终索寞。
兰生当门燕巢幙，兰芽未吐燕泥落。
为姑偏忌诸嫂良，作妇翻嫌壻家恶。
人生照镜须自知，无盐何用妬西施。
秦庭野鹿忽为马，巧伪乱真君试思。
伯奇掇蜂贤父逐，曾参杀人慈母疑。
酒沽千日人不醉，琴弄一弦心已悲。
常闻善交无尔汝，谗口甚甘良药苦。
山鸡锦翼岂凤凰，陇鸟人言止鹦鹉。
向栩非才徒隐竈，田文有命那关户。
犀烛江行见鬼神，木人登席呈歌舞。
乐生东去终居赵，阳虎北辕飜适楚。
世间反覆不易陈，缄此贻君泪如雨。','',''),('quantangshi-15296','乌栖曲','李端','quantangshi','','卷16','白马逐朱车，黄昏入狭斜。
狭斜柳树乌争宿，争枝未得飞上屋。
东房少妇壻从军，每听乌啼知夜分。','',''),('quantangshi-15297','送客东归','李端','quantangshi','','卷16','昨夜东风吹尽雪，两京路上梅花发。
行人相见便东西，日暮溪头饮马别。
把君衫袖望垂杨，两行泪下思故乡。','',''),('quantangshi-15298','王敬伯歌','李端','quantangshi','','卷16','妾本舟中女，闻君江上琴。
君初感妾意，妾亦感君心。
遂出合欢被，同为交颈禽。
传杯唯畏浅，接膝犹嫌远。
侍婢奏箜篌，女郎歌宛转。
宛转怨如何，中庭霜渐多。
霜多叶可惜，昨日非今夕。
徒结万重欢，终成一宵客。
王敬伯，绿水青山从此隔。','',''),('quantangshi-15299','救生寺望春寄畅当','李端','quantangshi','','卷16','东西南北望，望远悲潜蓄。
红黄绿紫花，花开看不足。
今年与子少相随，他年与子老相逐。','',''),('quantangshi-15300','荆门歌送兄赴夔州','李端','quantangshi','','卷16','余兄佐郡经西楚，饯行因赋荆门雨。
𩆵𩆵燮燮声渐繁，浦里人家收市喧。
重阴大点过欲尽，碎浪柔文相与飜。
云间怅望荆衡路，万里青山一时暮。
琵琶寺里响空廊，熨斗陂前湿荒戍。
沙尾长樯发渐稀，竹竿草屩涉流归。
夷陵已远半成烧，汉上游倡始濯衣。
船门相对多商估，葛服龙钟篷下语。
自是湘州石燕飞，那关齐地商羊舞。
曾为江客念江行，肠断秋荷雨打声。
摩天古木不可见，住岳高僧空得名。
今朝拜首临欲别，遥忆荆门雨中发。','',''),('quantangshi-15301','妾薄命','李端','quantangshi','','卷16','忆妾初嫁君，花鬟如绿云。
回灯入绮帐，转面脱罗裙。
折步教人学，偷香与客熏。
容颜南国重，名字北方闻。
一从失恩意，转觉身顦顇。
对镜不梳头，倚窗空落泪。
新人莫恃新，秋至会无春。
从来闭在长门者，必是宫中第一人。','',''),('quantangshi-15302','关山月','李端','quantangshi','','卷16','露湿月苍苍，关头榆叶黄。
回轮照海远，分彩上楼长。
水冻频移幕，兵疲数望乡。
只应城影外，万里共胡霜。','',''),('quantangshi-15303','度关山','李端','quantangshi','','卷16','雁塞日初晴，狐关雪复平。
危楼缘广漠，古窦傍长城。
拂剑金星出，弯弧玉羽鸣。
谁知系虏者，贾谊是书生。','',''),('quantangshi-15304','巫山高','李端','quantangshi','','卷16','巫山十二峯，皆在碧虚中。
回合云藏月，霏微雨带风。
猿声寒过涧，树色暮连空。
愁向高唐望，清秋见楚宫。','',''),('quantangshi-15305','雨雪曲','李端','quantangshi','','卷16','天山一丈雪，杂雨夜霏霏。
湿马胡歌乱，经烽汉火微。
丁零苏武别，疎勒范羌归。
若看关头下，长榆叶定稀。','',''),('quantangshi-15306','春游乐','李端','quantangshi','','卷16','柘弹连钱马，银钩妥堕鬟。
摘桑春陌上，踏草夕阳间。
意合辞先露，心诚貌却闲。
明朝若相忆，云雨出巫山。','',''),('quantangshi-15307','山下泉','李端','quantangshi','','卷16','碧水暎丹霞，溅溅度浅沙。
暗通山下草，流出洞中花。
净色和云落，喧声遶石斜。
明朝更寻去，应到阮郎家。','',''),('quantangshi-15308','送客赴洪州','李端','quantangshi','','卷16','草色随骢马，悠悠共出秦。
水传云梦晓，山接洞庭春。
帆影连三峡，猿声在四邻。
青门一分手，难见杜陵人。','',''),('quantangshi-15309','与郑锡游春','李端','quantangshi','','卷16','东门垂柳长，回首独心伤。
日暖临芳草，天晴忆故乡。
暎花鸎上下，过水蝶飞扬。
借问同行客，今朝泪几行。','',''),('quantangshi-15310','送友人','李端','quantangshi','','卷16','闻说湘川路，年年古木多。
猿啼巫峡夜，月照洞庭波。
穷海人还去，孤城雁与过。
青山不同赏，来往自蹉跎。','',''),('quantangshi-15311','题从叔沆林园','李端','quantangshi','','卷16','阮宅闲园暮，窗中见树阴。
樵歌依远草，僧语过长林。
鸟哢花间曲，人弹竹里琴。
自嫌身未老，已有住山心。','',''),('quantangshi-15312','送少微上人入蜀','李端','quantangshi','','卷16','削发本求道，何方不是归。
松风开法席，江月濯禅衣。
飞阁蝉鸣早，漫天客过稀。
戴颙常执笔，不觉此身非。','',''),('quantangshi-15313','雨后游辋川','李端','quantangshi','','卷16','骤雨归山尽，颓阳入辋川。
看虹登晚墅，踏石过春泉。
紫葛藏仙井，黄花出野田。
自知无路去，回步就人烟。','',''),('quantangshi-15314','同皇甫侍御题惟一上人房','李端','quantangshi','','卷16','焚香居一室，尽日见空林。
得道轻年暮，安禅爱夜深。
东西皆是梦，存没岂关心。
唯羡诸童子，持经在竹阴。','',''),('quantangshi-15315','同苗员外宿荐福寺僧舍','李端','quantangshi','','卷16','潘安秋兴动，凉夜宿僧房。
倚杖云离月，垂帘竹有霜。
回风生远迳，落叶飒长廊。
一与交亲会，空贻别后伤。','',''),('quantangshi-15316','送客往湘江','李端','quantangshi','','卷16','识君年已老，孤棹向潇湘。
素发临高镜，清晨入远乡。
三山分夏口，五两映涔阳。
更逐巴东客，南行泪几行。','',''),('quantangshi-15317','送友人游蜀','李端','quantangshi','','卷16','嘉陵天气好，百里见双流。
帆影缘巴字，钟声出汉州。
绿原春草晚，青木暮猿愁。
本是风流地，游人易白头。','',''),('quantangshi-15318','送友人游江东','李端','quantangshi','','卷16','江上花开尽，南行见杪春。
鸟声悲古木，云影入通津。
返景斜连草，回潮暗动苹。
谢公今在郡，应喜得诗人。','',''),('quantangshi-15319','送乐平苗明府得家字','李端','quantangshi','','卷16','本自求彭泽，谁云道里赊。
山从石壁断，江向弋阳斜。
暮色随枫树，阴云暗荻花。
诸侯旧调鼎，应重宰臣家。','',''),('quantangshi-15320','过宋州','李端','quantangshi','','卷16','睢阳陷虏日，外绝救兵来。
世乱忠臣死，时清明主哀。
荒郊春草徧，故垒野花开。
欲为将军哭，东流水不回。','',''),('quantangshi-15321','茂陵山行陪韦金部','李端','quantangshi','','卷16','宿雨朝来歇，空山秋气清。
盘云双鹤下，隔水一蝉鸣。
古道黄花落，平芜赤烧生。
茂陵虽有病，犹得伴君行。','',''),('quantangshi-15322','江上逢司空曙','李端','quantangshi','','卷16','共尔髫年故，相逢万里余。
新春两行泪，故国一封书。
夏口帆初落，涔阳雁正疎。
唯当执杯酒，暂食汉江鱼。','',''),('quantangshi-15323','逢王泌自东京至','李端','quantangshi','','卷16','逢君自乡至，雪涕问田园。
几处生乔木，谁家在旧村。
山峰横二室，水色映千门。
愁见游从处，如今花正繁。','',''),('quantangshi-15324','山中期吉中孚','李端','quantangshi','','卷16','行人路不同，花落到山中。
水暗蒹葭雾，月明杨柳风。
年华惊已掷，志业飒然空。
何必龙钟后，方期事远公。','',''),('quantangshi-15325','酬前大理寺评事张芬','李端','quantangshi','','卷16','君家旧林壑，寄在乱峰西。
近日春云满，相思路亦迷。
闻钟投野寺，待月过前溪。
怅望成幽梦，依依识故蹊。','',''),('quantangshi-15326','赋得山泉送房造','李端','quantangshi','','卷16','泉水山边去，高人月下看。
润松秋色净，落涧夜声寒。
委曲穿深竹，潺湲过远滩。
圣朝无隐者，早晚罢渔竿。','',''),('quantangshi-15327','宿兴善寺后堂池','李端','quantangshi','','卷16','草堂高树下，月向后池生。
野客如僧静，新荷共水平。
锦鳞沉不食，绣羽乱相鸣。
即事思江海，谁能万里行。','',''),('quantangshi-15328','忆皎然上人','李端','quantangshi','','卷16','未得从师去，人间万事劳。
云门不可见，山木已应高。
向日开柴户，惊秋问敝袍。
何由宿峰顶，窗里望波涛。','',''),('quantangshi-15329','赠衡岳隐禅师','李端','quantangshi','','卷16','旧住衡州寺，随缘偶北来。
夜禅山雪下，朝汲竹门开。
半偈传初尽，羣生意未回。
唯当与樵者，杖锡入天台。','',''),('quantangshi-15330','云阳观寄袁稠','李端','quantangshi','','卷16','花洞晚阴阴，仙坛隔杏林。
漱泉春谷冷，捣药夜窗深。
石上开仙酌，松间对玉琴。
戴家溪北住，雪后去相寻。','',''),('quantangshi-15331','晚游东田寄司空曙','李端','quantangshi','','卷16','暮来思远客，独立在东田。
片雨无妨景，残虹不映天。
别愁逢夏果，归兴入秋蝉。
莫作隳官意，陶潜未必贤。','',''),('quantangshi-15332','题崔端公园林','李端','quantangshi','','卷16','上士爱清辉，开门向翠微。
抱琴看鹤去，枕石待云归。
野坐苔生席，高眠竹挂衣。
旧山东望远，惆怅暮花飞。','',''),('quantangshi-15333','早春雪夜寄卢纶兼呈秘书元丞','李端','quantangshi','','卷16','闻君随谢朓，春夜宿前川。
看竹云垂地，寻僧月满田。
熊寒方入树，鱼乐稍离船。
独夜羇愁客，惟知惜故年。','',''),('quantangshi-15334','早春夜集耿拾遗宅','李端','quantangshi','','卷16','如何逋客会，忽在侍臣家。
新草犹停雪，寒梅未放花。
衔杯鸡欲唱，逗月雁应斜。
年齿俱憔悴，谁堪故国赊。','',''),('quantangshi-15335','元丞宅送胡浚及第东归觐省','李端','quantangshi','','卷16','登龙兼折桂，归去当高车。
旧楚枫犹在，前隋柳已疎。
月中逢海客，浪里得乡书。
见说江边住，知君不厌鱼。','',''),('quantangshi-15336','送魏广下第归扬州宁亲','李端','quantangshi','','卷16','游宦今空返，浮淮一雁秋。
白云阴泽国，青草遶扬州。
调膳过花下，张筵到水头。
昆山仍有玉，岁晏莫淹留。','',''),('quantangshi-15337','归山与酒徒别','李端','quantangshi','','卷16','野客本无事，此来非有求。
烦君征乐饯，未免忆山愁。
红烛侵明月，青娥促白头。
童心久已尽，岂为艳歌留。','',''),('quantangshi-15338','冬夜寄韩弇','李端','quantangshi','','卷16','独坐知霜下，开门见木衰。
壮应随日去，老岂与人期。
废井虫鸣早，阴阶菊发迟。
兴来空忆戴，不似剡溪时。','',''),('quantangshi-15339','闻吉道士还俗因而有赠','李端','quantangshi','','卷16','闻有华阳客，儒裳谒紫微。
旧山连药卖，孤鹤带云归。
柳市名犹在，桃源梦已稀。
还乡见鸥鸟，应愧背船飞。','',''),('quantangshi-15340','韦员外东斋看花','李端','quantangshi','','卷16','入花凡几步，此树独相留。
发艳红枝合，垂烟绿水幽。
倂开偏觉好，未落已成愁。
一到芳菲下，空招两鬓秋。','',''),('quantangshi-15341','边头作','李端','quantangshi','','卷16','邠郊泉脉动，落日上城楼。
羊马水草足，羌胡帐幕稠。
射雕过海岸，传箭怯边州。
何事归朝将，今年又拜侯。','',''),('quantangshi-15342','宿深上人院听远泉','李端','quantangshi','','卷16','泉声宜远听，入夜对支公。
断续来方尽，潺湲咽又通。
何年出石下，几里在山中。
君问穷源处，禅心与此同。','',''),('quantangshi-15343','茂陵村行赠何兆','李端','quantangshi','','卷16','春天黄鸟啭，野迳白云闲。
解带依芳草，支颐想故山。
人行九州路，树老五陵间。
谁道临邛远，相如自忆还。','',''),('quantangshi-15344','送友人还洛','李端','quantangshi','','卷16','去国渡关河，蝉鸣古树多。
平原正超忽，行子复蹉跎。
去事不可想，旧游难再过。
何当嵩岳下，相见在烟萝。','',''),('quantangshi-15345','送戴征士还山','李端','quantangshi','','卷16','柔桑锦臆雉，相送到烟霞。
独隐空山里，闲门几树花。
草生杨柳岸，鸟啭竹林家。
不是谋生拙，无为末路赊。','',''),('quantangshi-15346','秋日旅舍别司空文明','李端','quantangshi','','卷16','凉风飒穷巷，秋思满高云。
吏隐俱不就，此心仍别君。
素怀宗淡泊，羁旅念功勋。
转忆西林寺，江声月下闻。','',''),('quantangshi-15347','旅舍对雪赠考功王员外','李端','quantangshi','','卷16','杨花惊满路，面市忽狂风。
骤下摇兰叶，轻飞集竹丛。
欲将琼树比，不共玉人同。
独望徽之棹，青山在雪中。','',''),('quantangshi-15348','送丁少府往唐上','李端','quantangshi','','卷16','因君灞陵别，故国一回看。
共食田文饭，先之梅福官。
江风转日暮，山月满潮寒。
不得同舟望，淹留岁月阑。','',''),('quantangshi-15349','赠李龟年','李端','quantangshi','','卷16','青春事汉主，白首入秦城。
遍识才人字，多知旧曲名。
风流随故事，语笑合新声。
独有垂杨树，偏伤日暮情。','',''),('quantangshi-15350','送郭补阙归江阳','李端','quantangshi','','卷16','东门春尚浅，杨柳未成阴。
雁影愁斜日，鸎声怨故林。
隋宫江上远，梁苑雪中深。
独有怀归客，难为欲别心。','',''),('quantangshi-15351','早春会王逵主人得蓬字','李端','quantangshi','','卷16','今年华鬓色，半在故人中。
欲写无穷恨，先期一醉同。
绿丛犹覆雪，红萼已凋风。
莫负归山契，君看陌上蓬。','',''),('quantangshi-15352','宿山寺思归','李端','quantangshi','','卷16','僧房秋雨歇，愁卧夜更深。
欹枕闻鸿雁，回灯见竹林。
归萤入草尽，落月映窗沉。
拭泪无人觉，长谣向壁阴。','',''),('quantangshi-15353','送客赴江陵寄郢州郎士元','李端','quantangshi','','卷16','露下晚蝉愁，诗人旧怨秋。
沅湘莫留滞，宛洛好遨游。
饮马逢黄菊，离家值白头。
竟陵明月夜，为上庾公楼。','',''),('quantangshi-15354','送客赋得巴江夜猿','李端','quantangshi','','卷16','巴水天边路，啼猿伤客情。
迟迟云外尽，杳杳树中生。
残月暗将落，空霜寒欲明。
楚人皆掩泪，闻到第三声。','',''),('quantangshi-15355','秋日忆暕上人','李端','quantangshi','','卷16','一从持钵别，更未到人间。
好静居贫寺，遗名弃近山。
雨前缝百衲，叶下闭重关。
若便浔阳去，须将旧客还。','',''),('quantangshi-15356','寄上舍人叔','李端','quantangshi','','卷16','车马朝初下，看山忆独寻。
会知逢水尽，且爱入云深。
残雨开斜日，新蝉发迥林。
阮咸虽别巷，遥识此时心。','',''),('quantangshi-15357','送古之奇赴安西幕','李端','quantangshi','','卷16','畴昔十年兄，相逢五校营。
今宵举杯酒，陇月见军城。
堠火经阴绝，边人接晓行。
殷勤送书记，强虏几时平。','',''),('quantangshi-15358','送张芬归江东兼寄柳中庸','李端','quantangshi','','卷16','久是天涯客，偏伤落木时。
如何故国见，更欲异乡期。
鸟暮东西急，波寒上下迟。
空将满眼泪，千里怨相思。','',''),('quantangshi-15359','送丘丹归江东','李端','quantangshi','','卷16','故山霜落久，才子忆荆扉。
旅舍寻人别，秋风逐雁归。
梦愁枫叶尽，醉惜菊花稀。
肯学求名者，经年未拂衣。','',''),('quantangshi-15360','卧病寄苗员外','李端','quantangshi','','卷16','故人初未贵，相见得淹留。
一自朝天去，因成计日游。
月明应独醉，叶下肯同愁。
因恨刘桢病，空园卧见秋。','',''),('quantangshi-15361','送杨臯擢第归江东','李端','quantangshi','','卷16','隋堤望楚国，江上一归人。
绿气千樯暮，青风万里春。
试才初得桂，泊渚肯伤苹。
拜手终凄怆，恭承中外亲。','',''),('quantangshi-15362','题郑少府林园','李端','quantangshi','','卷16','谢家今日晚，词客愿抽毫。
枥马方回影，池鹅正理毛。
竹筒传水远，麈尾坐僧高。
独有宗雷贱，过君着敝袍。','',''),('quantangshi-15363','送吉中孚拜官归业','李端','quantangshi','','卷16','南入华阳洞，无人古树寒。
吟诗开旧帙，带绶上荒坛。
因病求归易，霑恩更隐难。
孟宗应献鲊，家近守渔官。','',''),('quantangshi-15364','送杨少府赴阳翟','李端','quantangshi','','卷16','冠带仁兄后，光辉寿母前。
陆云还入洛，潘岳更张筵。
井邑嵩山对，园林颍水连。
东人欲相送，旅舍已潸然。','',''),('quantangshi-15365','慈恩寺暕上人房招耿拾遗','李端','quantangshi','','卷16','悠然对惠远，共结故山期。
汲井树阴下，闭门亭午时。
地闲花落厚，石浅水流迟。
愿与神仙客，同来事本师。','',''),('quantangshi-15366','宿山寺雪夜寄吉中孚','李端','quantangshi','','卷16','独爱僧房竹，春来长到池。
云遮皆晃朗，雪压半低垂。
不见侵山叶，空闻拂地枝。
鄙夫今夜兴，唯有子猷知。','',''),('quantangshi-15367','赠赵神童','李端','quantangshi','','卷16','圣朝殊汉令，才子少登科。
每见先鸣早，常惊后进多。
独居方寂寞，相对觉蹉跎。
不是通家旧，频劳文举过。','',''),('quantangshi-15368','宿云际寺赠深上人','李端','quantangshi','','卷16','暂别青蓝寺，今来发欲斑。
独眠孤烛下，风雨在前山。
坏宅终须去，空门不易还。
支公有方便，一愿启玄关。','',''),('quantangshi-15369','送从兄赴洪州别驾兄善琴','李端','quantangshi','','卷16','援琴兼爱竹，遥夜在湘沅。
鹤舞月将下，乌啼霜正繁。
乱流喧橘岸，飞雪暗荆门。
佐郡无辞屈，其如相府恩。','',''),('quantangshi-15370','山中期张芬不至','李端','quantangshi','','卷16','石堤春草碧，双燕向西飞。
怅望云天暮，佳人何处归。
药栏虫网遍，苔井水痕稀。
谁道嵇康嬾，山中自掩扉。','',''),('quantangshi-15371','寄畅当','李端','quantangshi','','卷16','麦秀草芊芊，幽人好昼眠。
云霞生岭上，猿鸟下牀前。
颜子方敦行，支郎久住禅。
中林轻暂别，约略已经年。','',''),('quantangshi-15372','送义兴元少府','李端','quantangshi','','卷16','逢君惠连第，初命[便]光辉。
已得羣公祖，终妨太傅讥。
路长人反顾，草断燕回飞。
本是江南客，还同衣锦归。','',''),('quantangshi-15373','卧病别郑锡','李端','quantangshi','','卷16','病来喜无事，多卧竹林间。
此日一相见，明朝还掩关。
幽人爱芳草，志士惜颓颜。
岁[晏]不我弃，期君在故山。','',''),('quantangshi-15374','书志赠畅当','李端','quantangshi','','卷16','少喜神仙术，未去已蹉跎。
壮志一为累，浮生事渐多。
衰颜不相识，岁暮定相过。
请问宗居士，君其奈老何。','',''),('quantangshi-15375','送诸曁裴少府','李端','quantangshi','','卷16','山公访嵇绍，赵武见韩侯。
事去恩犹在，名成泪却流。
一官同北去，千里赴南州。
才子清风后，无贻相府忧。','',''),('quantangshi-15376','送郑宥入蜀迎觐','李端','quantangshi','','卷16','宁亲西陟险，君去异王阳。
在世谁非客，还家即是乡。
剑门千转尽，巴水一支长。
请语愁猿道，无烦促泪行。','',''),('quantangshi-15377','送耿拾遗湋使江南括图书','李端','quantangshi','','卷16','驱传草连天，回风满树蝉。
将过夫子宅，前问孝廉船。
汉使收三箧，周诗采百篇。
别来将有泪，不是怨流年。','',''),('quantangshi-15378','送王少府游河南','李端','quantangshi','','卷16','马卿方失意，东去谒诸侯。
过宋人应少，游梁客独愁。
鸟翻千室暮，蝉急两河秋。
仆本无媒者，因君泪亦流。','',''),('quantangshi-15379','送别驾赴晋陵即舍人叔之兄','李端','quantangshi','','卷16','诸宗称叔父，从子亦光辉。
谢脁中书直，王祥别乘归。
江帆冲雨上，海树隔潮微。
南阮贫无酒，唯将泪湿衣。','',''),('quantangshi-15380','卧病寄阎寀','李端','quantangshi','','卷16','病中贪好景，强步出幽居。
紫葛垂山径，黄花遶野渠。
荒林飞老鹤，败堰过游鱼。
纵忆同年友，无人可寄书。','',''),('quantangshi-15381','晚夏闻蝉寄广文','李端','quantangshi','','卷16','昨日莺啭声，今朝蝉忽鸣。
朱颜向华发，定是几年程。
故国白云远，闲居青草生。
因垂数行泪，书报十年兄。','',''),('quantangshi-15382','归山居寄钱起','李端','quantangshi','','卷16','怅望青山下，回头泪满巾。
故乡多古树，落日少行人。
发鬓将回色，簪缨未到身。
谁知武陵路，亦有汉家臣。','',''),('quantangshi-15383','晓发瓜州','李端','quantangshi','','卷16','晓发悲行客，停桡独未前。
寒江半有月，野戍渐无烟。
棹唱临高岸，鸿嘶发远田。
谁知避徒御，对酒一潸然。','',''),('quantangshi-15384','江上喜逢司空文明','李端','quantangshi','','卷16','秦人江上见，握手泪沾巾。
落日见秋草，暮年逢故人。
非夫长作客，多病浅谋身。
台阁旧亲友，谁曾见苦辛。','',''),('quantangshi-15385','同苗发慈恩寺避暑','李端','quantangshi','','卷16','追凉寻宝刹，畏日望璇题。
卧草同鸳侣，临池似虎溪。
树闲人迹外，山晚鸟行西。
若问无心法，莲花隔淤泥。','',''),('quantangshi-15386','送潘述宏词下第归江外','李端','quantangshi','','卷16','唱高人不和，此去泪难收。
上国经年住，长江满目流。
弈棊知胜偶，射策请焚舟。
应是田囗囗，玄成许尔游。','',''),('quantangshi-15387','送张少府赴夏县','李端','quantangshi','','卷16','虽为州县职，还欲抱琴过。
树古闻风早，山枯见雪多。
鸡声连绛市，马色傍黄河。
太守新临郡，还逢五袴歌。','',''),('quantangshi-15388','酬秘书元丞郊园卧疾见寄','李端','quantangshi','','卷16','闻说漳滨卧，题诗怨岁华。
求医主高手，报疾到贫家。
撒枕销行蚁，移杯失画蛇。
明朝九衢上，应见玉人车。','',''),('quantangshi-15389','送成都韦丞还蜀','李端','quantangshi','','卷16','蜀门云树合，高栈有猿愁。
驱传加新命，之官向旧游。
晨装逢酒雨，夜梦见刀州。
远别长相忆，当年莫滞留。','',''),('quantangshi-15390','晚秋旅舍寄苗员外','李端','quantangshi','','卷16','争途苦不前，贫病遂连牵。
向暮同行客，当秋独长年。
晚花唯有菊，寒叶已无蝉。
吏部逢今日，还应瓮下眠。','',''),('quantangshi-15391','送惟良上人归润州','李端','quantangshi','','卷16','拟诗偏不类，又送上人归。
寄世同高鹤，寻仙称坏衣。
雨行江草短，露坐海帆稀。
正被空门缚，临岐乞解围。','',''),('quantangshi-15392','送何兆下第还蜀','李端','quantangshi','','卷16','重江不可涉，孤客莫晨装。
高木莎城小，残星栈道长。
褭猿枫子落，过雨荔枝香。
劝尔成都住，文翁有草堂。','',''),('quantangshi-15393','送友人宰湘阴','李端','quantangshi','','卷16','从宦舟行远，浮湘又入闽。
蒹葭无朔雁，柽栝有蛮神。
传吏闲调象，山精暗讼人。
唯须千树橘，暂救李衡贫。','',''),('quantangshi-15394','送元晟归江东旧居','李端','quantangshi','','卷16','泽国舟车接，关门雨雪乖。
春天行故楚，夜月下清淮。
讲易居山寺，论诗到郡斋。
蒋家人暂别，三路草连堦。','',''),('quantangshi-15395','送黎少府赴阳翟','李端','quantangshi','','卷16','诗礼称才子，神仙是丈人。
玉山那惜醉，金谷已无春。
白马如风疾，青袍夺草新。
不嫌鸣吠客，愿用百年身。','',''),('quantangshi-15396','送夏侯审游蜀','李端','quantangshi','','卷16','西望烟绵树，愁君上蜀时。
同林息商客，隔栈见罛师。
石滑羊肠险，山空杜宇悲。
琴心正幽怨，莫奏凤凰诗。','',''),('quantangshi-15397','单推官厅前双桐咏','李端','quantangshi','','卷16','封植因高兴，孤贞契素期。
由来得地早，何事结花迟。
叶重凝烟后，条寒过雨时。
还同李家树，争赋角弓诗。','',''),('quantangshi-15398','送宋校书赴宣州幕','李端','quantangshi','','卷16','浮舟压芳草，容裔逐江春。
远避看书吏，行当入幕宾。
夜潮冲老树，晓雨破轻苹。
鸳鹭多伤别，栾家德在人。','',''),('quantangshi-15399','送赵给事侄尉丹阳','李端','quantangshi','','卷16','太傅怜羣从，门人亦贱回。
入官先爱子，赐酒许同杯。
淮海春多雨，蒹葭夜有雷。
遥知拜庆后，梅尉称仙才。','',''),('quantangshi-15400','宿瓜洲寄柳中庸','李端','quantangshi','','卷16','怀人同不寐，清夜起论文。
月魄正出海，雁行斜上云。
寒潮来滟滟，秋叶下纷纷。
便送江东去，徘徊祗待君。','',''),('quantangshi-15401','夜宴虢县张明府宅逢宇文评事','李端','quantangshi','','卷16','虢田留古宅，入夜足秋风。
月影来窗里，灯光落水中。
征诗逢谢客，饮酒得陶公。
更爱疎篱下，繁霜湿菊丛。','',''),('quantangshi-15402','冬夜集张尹后阁','李端','quantangshi','','卷16','乘龟兼戴豸，白面映朱衣。
安石还须起，泉明不得归。
譍门常吏在，登席旧寮稀。
远客长先醉，那知亚相威。','',''),('quantangshi-15403','将之泽潞留别王郎中','李端','quantangshi','','卷16','弱年知己少，前路主人稀。
贫病期相惜，艰难又忆归。
事成应未卜，身贱又无机。
幸到龙门下，须因羽翼飞。','',''),('quantangshi-15404','晚次巴陵','李端','quantangshi','','卷16','雪后柳条新，巴陵城下人。
烹鱼邀水客，载酒奠山神。
云去低斑竹，波回动白苹。
不堪逢楚老，日暮正江春。','',''),('quantangshi-15405','送荀道士归庐山','李端','quantangshi','','卷16','先生归有处，欲别笑无言。
绿水到山口，青林连洞门。
月明寻石路，云霁望花源。
早晚还乘鹤，悲歌向故园。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-15406','送张淑归觐叔父','李端','quantangshi','','卷16','日惨长亭暮，天高大泽闲。
风中闻草木，雪里见江山。
马向塞云去，人随古道还。
阮家今夜乐，应在竹林间。','',''),('quantangshi-15407','送郭参军赴绛州','李端','quantangshi','','卷16','登车君莫望，故绛柳条春。
蒲泽逢胡雁，桃源见晋人。
佐军髯尚短，掷地思还新。
小谢常携手，因之醉路尘。','',''),('quantangshi-15408','送袁稠游江南','李端','quantangshi','','卷16','江南衰草遍，十里见长亭。
客去逢摇落，鸿飞入杳冥。
空城寒雨细，深院晓灯青。
欲去行人起，徘徊恨酒醒。','',''),('quantangshi-15409','送夏中丞赴宁国任','李端','quantangshi','','卷16','楚县入青枫，长江一派通。
板桥寻谢客，古邑事陶公。
片雨收山外，连云上汉东。
陆机犹滞洛，念子望南鸿。','',''),('quantangshi-15410','送衞雄下第归同州','李端','quantangshi','','卷16','不才先上第，词客却空还。
边地行人少，平芜尽日闲。
一蝉陂树里，众火陇云间。
羡汝归茅屋，书窗见远山。','',''),('quantangshi-15411','送单少府赴扶风','李端','quantangshi','','卷16','少年趋盛府，颜色比花枝。
范匄非童子，杨修岂小儿。
叨陪丈人行，常恐阿戎欺。
此去云霄近，看君逸足驰。','',''),('quantangshi-15412','题山中别业','李端','quantangshi','','卷16','旧宅在山中，闲门与寺通。
往来黄叶路，交结白头翁。
晚笋难成竹，秋花不满丛。
生涯祗麤粝，吾岂讳言穷。','',''),('quantangshi-15413','送司空文明归江上旧居','李端','quantangshi','','卷16','野菊有黄花，送君千里还。
鸿来燕又去，离别惜容颜。
流水通归梦，行云失故关。
江风正摇落，宋玉莫登山。','',''),('quantangshi-15414','送新城戴叔伦明府','李端','quantangshi','','卷16','遥想隋堤路，春天楚国情。
白云当海断，青草隔淮生。
雁起斜还直，潮回远复平。
莱芜不可到，一醉送君行。','',''),('quantangshi-15415','送雍丘任少府','李端','quantangshi','','卷16','丛车饯才子，路走许东偏。
远水同春色，繁花胜雪天。
鸟行侵楚邑，树影向殷田。
莫学生乡思，梅真正少年。','',''),('quantangshi-15416','送雍郢州','李端','quantangshi','','卷16','厌郎思出守，遂领汉东军。
望月逢殷浩，缘江送范云。
城闲烟草遍，浦逈雪林分。
谁伴楼中宿，吟诗估客闻。','',''),('quantangshi-15417','寄王密卿','李端','quantangshi','','卷16','酒乐今年少，僧期近日频。
买山多为竹，卜宅不缘贫。
志业归初地，文章寄此身。
嵇康虽有病，犹得见情人。','',''),('quantangshi-15418','与萧远上人游少华山寄皇甫侍御','李端','quantangshi','','卷16','寻危兼采药，渡水又登山。
独与高僧去，逍遥落日间。
渐看闾里远，自觉性情闲。
廻首知音在，因令怅望还。','',''),('quantangshi-15419','代村中老人答','李端','quantangshi','','卷16','京洛风尘后，村乡烟火稀。
少年曾失所，衰暮欲何依。
夜静临江哭，天寒踏雪归。
时清应不见，言罢泪盈衣。','',''),('quantangshi-15420','赠故将军','李端','quantangshi','','卷16','平生在边日，鞍马若星流。
独出间千里，相知满九州。
恃功凌主将，作气见王侯。
谁道廉颇老，犹能报远讐。','',''),('quantangshi-15421','送陆郎中归田司空幕','李端','quantangshi','','卷16','汉家分列宿，东土佐诸侯。
结束还军府，光辉过御沟。
农桑连紫陌，分野入青州。
覆被恩难报，西看成白头。','',''),('quantangshi-15422','酬晋侍御见寄','李端','quantangshi','','卷16','野客蒙诗赠，殊恩欲报难。
本求文举识，不在子真官。
细雨双林暮，重阳九日寒。
贫斋一丛菊，愿与上宾看。','',''),('quantangshi-15423','送铜泽王归城','李端','quantangshi','','卷16','昔闻公族出，其从亦高车。
为善唯求乐，分贫必及疎。
身承汉枝叶，手习鲁诗书。
尚说无功德，三年在石渠。','',''),('quantangshi-15424','江上别柳中庸','李端','quantangshi','','卷16','秦人江上见，握手便霑衣。
近日相知少，往年亲故稀。
远游何处去，旧业几时归。
更向巴陵宿，堪闻雁北飞。','',''),('quantangshi-15425','喜皇甫郎中拜谕德兼集贤学士','李端','quantangshi','','卷16','为郎三载后，宠命一朝新。
望苑迁词客，儒林拜丈人。
莺飞绮阁曙，柳拂画堂春。
几日调金鼎，诸君欲望尘。','',''),('quantangshi-15426','送黎兵曹往陕府结婚','李端','quantangshi','','卷16','东方发车骑，君是上头人。
奠雁逢良日，行媒及仲春。
时称渡河妇，宜配坦牀宾。
安得同门吏，扬鞭入后尘。','',''),('quantangshi-15427','送窦兵曹','李端','quantangshi','','卷16','梨花开上苑，游女着罗衣。
闻道情人怨，应须走马归。
御桥迟日暖，官渡早莺稀。
莫遣佳期过，看看蝴蝶飞。','',''),('quantangshi-15428','留别故人','李端','quantangshi','','卷16','此别不可道，此心当语谁。
春风灞水上，饮马桃花时。
误作好文士，祗应游宦迟。
留书下朝客，我有故山期。','',''),('quantangshi-15429','奉送宋中丞使河源','李端','quantangshi','','卷16','东周遣戍役，才子欲离羣。
部领河源去，悠悠陇水分。
笳声悲塞草，马首渡关云。
辛苦逢炎热，何时及汉军。','',''),('quantangshi-15430','都亭驿送郭判官之幽州幕府','李端','quantangshi','','卷16','幕府参戎事，承明伏奏归。
都亭使者出，杯酒故人违。
细雨霑官骑，轻风拂客衣。
还从大夫后，吾党亦光辉。','',''),('quantangshi-15431','送王羽林往秦州','李端','quantangshi','','卷16','秦州贵公子，汉日羽林郎。
事主来中禁，荣亲上北堂。
輶车花拥路，宝劒雪生光。
直扫三边靖，承恩向建章。','',''),('quantangshi-15432','送友入关','李端','quantangshi','','卷16','闻君帝城去，西望一沾巾。
落日见秋草，暮年逢故人。
非才长作客，有命懒谋身。
近更婴衰疾，空思老汉滨。','',''),('quantangshi-15433','代宗挽歌','李端','quantangshi','','卷16','祖庭三献罢，严衞百灵朝。
警跸移前殿，宫车上渭桥。
寒霜凝羽葆，野吹咽笳箫。
已向新京兆，谁云天路遥。','',''),('quantangshi-15434','张左丞挽歌二首 一','李端','quantangshi','','卷16','素斾低寒水，清笳出晓风。
鸟来伤贾傅，马立葬滕公。
松柏青山上，城池白日中。
一朝今古隔，唯有月明同。','',''),('quantangshi-15435','张左丞挽歌二首 二','李端','quantangshi','','卷16','祸集钩方失，灾生劒忽飞。
无由就日拜，空忆自天归。
门吏看还葬，宫官识赐衣。
东堂哀赠毕，从此故臣稀。','',''),('quantangshi-15436','奉和王元二相避暑怀杜太尉','李端','quantangshi','','卷16','艰难尝共理，海晏更相悲。
况复登堂处，分明避暑时。
绿槐千穗绽，丹药一番迟。
蓬荜今何幸，先朝大雅诗。','',''),('quantangshi-15437','青龙寺题故昙上人房','李端','quantangshi','','卷16','远公留故院，一径雪中微。
童子逢皆老，门人问亦稀。
飜经徒有处，携履遂无归。
空念寻巢鹤，时来傍影飞。','',''),('quantangshi-15438','早春夜望','李端','quantangshi','','卷16','旧雪逐泥沙，新雷发草芽。
晓霜应傍鬓，夜雨莫催花。
行矣前途晚，归欤故国赊。
不劳报春尽，从此惜年华。','',''),('quantangshi-15439','宴伊东岸','李端','quantangshi','','卷16','晴洲无远近，一树一潭春。
芳草留归骑，朱樱掷舞人。
空花对酒落，小翠隔林新。
竟日皆携手，何由遇此辰。','',''),('quantangshi-15440','云际中峰居喜见苗发','李端','quantangshi','','卷16','自得中峰住，深林亦闭关。
经秋无客到，入夜有僧还。
暗涧泉声小，荒村树影闲。
高窗不可望，星月满空山。','',''),('quantangshi-15441','宿洞庭','李端','quantangshi','','卷16','白水连天暮，洪波带日流。
风高云梦夕，月满洞庭秋。
沙上渔人火，烟中贾客舟。
西园与南浦，万里共悠悠。','',''),('quantangshi-15442','江上赛神','李端','quantangshi','','卷16','疎鼓应繁丝，送神归九疑。
苍龙随赤凤，帝子上天时。
骤雨归山疾，长江下日迟。
独怜游宦子，今夜泊天涯。','',''),('quantangshi-15443','奉和元丞侍从游南城别业','李端','quantangshi','','卷16','垂朱领孙子，从宴在池塘。
献寿回龟顾，和羹跃鲤香。
高松先草晚，平石助泉凉。
余橘期相及，门生有陆郎。','',''),('quantangshi-15444','送从舅成都丞广南归蜀','李端','quantangshi','','卷16','巴字天边水，秦人去是归。
栈长山雨响，溪乱火田稀。
俗富行应乐，官雄禄岂微。
魏舒终有泪，还湿甯家衣。','',''),('quantangshi-15445','赠郭驸马 一','李端','quantangshi','','卷16','青春都尉最风流，二十功成便拜侯。
金距鬬鸡过上苑，玉鞭骑马出长楸。
熏香荀令偏怜少，傅粉何郎不解愁。
日暮吹箫杨柳陌，路人遥指凤凰楼。','',''),('quantangshi-15446','赠郭驸马 二','李端','quantangshi','','卷16','方塘似镜草芊芊，初月如钩未上弦。
新开金埒看调马，旧赐铜山许铸钱。
杨柳入楼吹玉笛，芙蓉出水妬花钿。
今朝都尉如相顾，愿脱长裾学少年。','',''),('quantangshi-15447','宿淮浦忆司空文明','李端','quantangshi','','卷16','愁心一倍长离忧，夜思千重恋旧游。
秦地故人成远梦，楚天凉雨在孤舟。
诸溪近海潮皆应，独树边淮叶尽流。
别恨转深何处写，前程唯有一登楼。','',''),('quantangshi-15448','送濮阳录事赴忠州','李端','quantangshi','','卷16','成名不遂双旌远，主印还为一郡雄。
赤叶黄花随野岸，青山白水映江枫。
巴人夜语孤舟里，越鸟春啼万壑中。
闻说古书多未校，肯令才子久西东。','',''),('quantangshi-15449','送马尊师','李端','quantangshi','','卷16','南入商山松路深，石牀溪水昼阴阴。
云中采药随青节，洞里耕田映绿林。
直上烟霞空举手，回经丘壠自伤心。
武陵花木应长在，愿与渔人更一寻。','',''),('quantangshi-15450','题元注林园','李端','quantangshi','','卷16','谢家门馆似山林，碧石青苔满树阴。
乳鹊眄巢花巷静，鸣鸠鼓翼竹园深。
桔槔转水兼通药，方丈留僧共听琴。
独有野人箕踞惯，过君始得一长吟。','',''),('quantangshi-15451','野寺病居喜卢纶见访','李端','quantangshi','','卷16','青青麦壠白云阴，古寺无人新草深。
乳燕拾泥依古井，鸣鸠拂羽历花林。
千年驳藓明山履，万尺垂萝入水心。
一卧漳滨今欲老，谁知才子忽相寻。','',''),('quantangshi-15452','送皎然上人归山','李端','quantangshi','','卷16','适来世上岂缘名，适去人间岂为情。
古寺山中几日到，高松月下一僧行。
云阴鸟道苔方合，雪映龙潭水更清。
法主欲归须有说，门人流泪厌浮生。','',''),('quantangshi-15453','赠道士','李端','quantangshi','','卷16','姓氏不书高士传，形神自得逸人风。
已传花洞将秦接，更指茅山与蜀通。
嬾说岁年齐绛老，甘为乡曲号涪翁。
终朝卖卜无人识，敝服徒行入市中。','',''),('quantangshi-15454','题云际寺准上人房','李端','quantangshi','','卷16','高僧居处似天台，锡杖铜瓶对绿苔。
竹巷雨晴春鸟啭，山房日午老人来。
园中鹿过椒枝动，潭底龙游水沫开。
独夜焚香礼遗像，空林月出始应回。','',''),('quantangshi-15455','山中寄苗员外','李端','quantangshi','','卷16','鸟鸣花发空山里，衡岳幽人藉草时。
既近浅流安笔砚，还因平石布蓍龟。
千寻楚水横琴望，万里秦城带酒思。
闻说潘安方寓直，与君相见渐难期。','',''),('quantangshi-15456','忆故山赠司空曙','李端','quantangshi','','卷16','汉主金门正召才，马卿多病自迟回。
旧山蹔别老将至，芳草欲阑归去来。
云在高天风会起，年如流水日长催。
知君素有栖禅意，岁晏蓬门迟尔开。','',''),('quantangshi-15457','闲园即事赠考功王员外','李端','quantangshi','','卷16','南陌晴云稍变霞，东风动柳水纹斜。
园林带雪潜生草，桃李虽春未有花。
幸接上宾登郑驿，羞为长女似黄家。
今朝一望还成暮，欲别芳菲恋岁华。','',''),('quantangshi-15458','寄庐山真上人','李端','quantangshi','','卷16','高僧无迹本难寻，更得禅行去转深。
青草湖中看五老，白云山上宿双林。
月明潭色澄空性，夜静猨声证道心。
更[说谢]公南座好，烟萝到地几重阴。','',''),('quantangshi-15459','题觉公新兰若','李端','quantangshi','','卷16','头白禅师何处还，独开兰若树林间。
鬼因巫祝传移社，神见天人请施山。
猛虎听经金磬动，猕猴献蜜雪窗闲。
新斋结誓如相许，愿与雷宗永闭关。','',''),('quantangshi-15460','赠道者','李端','quantangshi','','卷16','窗中忽有鹤飞声，方士因知道欲成。
来取图书安枕里，便驱鸡犬向山行。
花开深洞仙门小，路过悬桥羽节轻。','',''),('quantangshi-15461','代弃妇答贾客','李端','quantangshi','','卷16','玉垒城边争走马，铜鞮市里共乘舟。
鸣环动佩恩无尽，掩袖低巾泪不流。
畴昔将歌邀客醉，如今欲舞对君羞。
忍怀贱妾平生曲，独上襄阳旧酒楼。','',''),('quantangshi-15462','和李舍人直中书对月见寄','李端','quantangshi','','卷16','名卿步月正淹留，上客裁诗怨别游。
素魄近成班女扇，清光远似庾公楼。
婵娟更称凭高望，皎洁能传自古愁。
盈手入怀皆不见，阳春曲丽转难酬。','',''),('quantangshi-15463','卧病闻吉中孚拜官寄元秘书昆季','李端','quantangshi','','卷16','汉家采使不求声，自慰文章道欲行。
毛遂登门虽异赏，韩非入传滥齐名。
云归暂爱青山出，客去还愁白发生。
年少奉亲皆愿达，敢将心事向玄成。','',''),('quantangshi-15464','江上逢柳中庸','李端','quantangshi','','卷16','旧住衡山曾夜归，见君江客忆荆扉。
星沉岭上人行早，月过湖西鹤唳稀。
弱竹万株频碍帻，新泉数步一褰衣。
今来唯有禅心在，乡路翻成向翠微。','',''),('quantangshi-15465','戏赠韩判官绅卿','李端','quantangshi','','卷16','少寻道士居嵩岭，晚事高僧住沃洲。
齿发未知何处老，身名且被外人愁。
欲随山水居茅洞，已有田园在虎丘。
独怪子猷缘掌马，雪时不肯更乘舟。','',''),('quantangshi-15466','送周长史','李端','quantangshi','','卷16','青枫树里宣城郡，独佐诸侯上板桥。
江客亦能传好信，山僧多解说南朝。
云阴出浦看帆小，草色连天见雁遥。
别有空园落桃杏，知将丝组系兰桡。','',''),('quantangshi-15467','题故将军庄','李端','quantangshi','','卷16','曾将数骑过桑干，遥对单于饬马鞍。
塞北征儿谙用剑，关西宿将许登坛。
田园芜没归耕晚，弓箭开离出猎难。
唯有老身如刻画，犹期圣主解衣看。','',''),('quantangshi-15468','夜投丰德寺谒海上人','李端','quantangshi','','卷16','半夜中峰有磬声，偶寻樵者问山名。
上方月晓闻僧语，下界林疎见客行。
野鹤巢边松最老，毒龙潜处水偏清。
愿得远山知姓字，焚香洗钵过余生。','',''),('quantangshi-15469','塞上','李端','quantangshi','','卷16','二十在边城，军中得勇名。
卷旗收败马，占碛拥残兵。
覆阵乌鸢起，烧山草木明。
塞闲思远猎，师老厌分营。
雪岭无人迹，冰河足雁声。
李陵甘此没，惆怅汉公卿。','',''),('quantangshi-15470','送彭将军云中觐兄','李端','quantangshi','','卷16','闻说苍鹰守，今朝欲下韛。
因令白马将，兼道觅封侯。
略地关山冷，防河雨雪稠。
飜弓骋猨臂，承箭惜貂裘。
设伏军谋密，坑降塞邑愁。
报恩唯有死，莫使汉家羞。','',''),('quantangshi-15471','奉赠苗员外','李端','quantangshi','','卷16','朱户敞高扉，青槐碍落晖。
八龙承庆重，三虎递朝归。
坐竹人声绝，横琴鸟语稀。
花慙潘岳貌，年称老莱衣。
叶暗新樱熟，丝长粉蝶飞。
应怜鲁儒贱，空与故山违。','',''),('quantangshi-15472','酬丘拱外甥览余旧文见寄','李端','quantangshi','','卷16','丘迟本才子，始冠即周旋。
舅乏郄鉴爱，君如衞玠贤。
礼将金友等，情向玉人偏。
鄙俗那劳似，龙钟却要怜。
投甎聊取笑，赠绮一何妍。
野坐临黄菊，溪行踏绿钱。
岩高云反下，洞黑水潜穿。
僻岭猿偷栗，枯池雁唼莲。
身居霞外寺，思发月明田。
犹恨萦尘网，昏昏过几年。','',''),('quantangshi-15473','赠岐山姜明府','李端','quantangshi','','卷16','昨夜闻山雨，归心便似迟。
几回惊叶落，即到白头时。
雁影将魂去，虫声与泪期。
马卿兼病老，宋玉对秋悲。
谢客才为别，陶公已见思。
非关口腹累，自是雪霜姿。
酿酒栽黄菊，炊粳折绿葵。
山河方入望，风日正宜诗。
牧竖寒骑马，边烽晚立旗。
兰凋犹有气，柳脆不成丝。
别后如相问，高僧知所之。','',''),('quantangshi-15474','下第上薛侍郎','李端','quantangshi','','卷16','蓬荜春风起，开帘却自悲。
如何飘梗处，又到采兰时。
明镜方重照，微城寄一辞。
家贫求禄早，身贱报恩迟。
幸得皮存矣，须劳翼长之。
铭肌非厚答，肉骨是前期。
纵觉新人好，宁忘旧主疑。
终慙太丘道，不为小生私。','',''),('quantangshi-15475','奉和秘书元丞杪秋忆终南旧居','李端','quantangshi','','卷16','高门有才子，能履古人踪。
白社陶元亮，青云阮仲容。
田园忽归去，车马杳难逢。
废巷临秋水，支颐向暮峰。
行鱼避杨柳，惊鸭触芙蓉。
石窦红泉细，山桥紫菜重。
凤雏终食竹，鹤侣暂巢松。
愿接烟霞赏，羁离计不从。','',''),('quantangshi-15476','送归中丞使新罗','李端','quantangshi','','卷16','东望扶桑日，何年是到时。
片帆通雨露，积水隔华夷。
浩淼风来远，虚冥鸟去迟。
长波静云月，孤岛宿旌旗。
别叶传秋意，回潮动客思。
沧溟无旧路，何处问前期。','',''),('quantangshi-15477','暮春寻终南柳处士','李端','quantangshi','','卷16','庞眉一居士，鹑服隐尧时。
种豆初成亩，还丹旧日师。
入溪花径远，向岭鸟行迟。
紫葛垂苔壁，青菰映柳丝。
偶来尘外事，暂与素心期。
终恨游春宫，同为岁月悲。','',''),('quantangshi-15478','雪夜寻太白道士','李端','quantangshi','','卷16','雪路夜朦胧，寻师杏树东。
石坛连竹静，醮火照山红。
再拜开金箓，焚香使玉童。
篷瀛三岛至，天地一壶通。
别客曾留药，逢舟或借风。
出游居鹤上，避祸入羊中。
过洞偏回首，登门未发蒙。
桑田如可见，沧海几时空。','',''),('quantangshi-15479','得山中道友书寄苗銭二员外','李端','quantangshi','','卷16','有谋皆轗轲，非病亦迟回。
壮志年年减，驰晖日日催。
还山不及伴，到阙又无媒。
高卧成长策，微官称下才。
诗人识何谢，居士别宗雷。
迹向尘中隐，书从谷口来。
药栏遭鹿践，涧户被猿开。
野鹤巢云窦，游龟上水苔。
新欢追易失，故思渺难裁。
自有归期在，劳君示劫灰。','',''),('quantangshi-15480','酬前驾部员外郎苗发','李端','quantangshi','','卷16','马融方直校，阅简复持铅。
素业高风继，青春壮思全。
论文多在夜，宿寺不虚年。
自署区中职，同荒郭外田。
山邻三径绝，野意八行传。
煮玉矜新法，留符识旧仙。
涵苔溪溜浅，摇浪竹桥悬。
复洞潜栖燕，疎杨半翳蝉。
咏歌虽有和，云锦独成妍。
应以冯唐老，相讥示此篇。','',''),('quantangshi-15481','宿荐福寺东池有怀故园因寄元校书','李端','quantangshi','','卷16','暮雨风吹尽，东池一夜凉。
伏流回弱荇，明月入垂杨。
石竹闲开碧，蔷薇暗吐黄。
倚琴看鹤舞，摇扇引桐香。
旧笋方辞箨，新莲未满房。
林幽花晚发，地远草先长。
抚枕愁华鬓，凭栏想故乡。
露余清汉直，云卷白榆行。
惊鹊仍依树，游鱼不过粱。
系舟偏忆戴，炊黍愿期张。
末路还思借，前恩讵敢忘。
从来叔夜嬾，非是接舆狂。
众病婴公干，羣忧集孝璋。
慙将多误曲，今日献周郎。','',''),('quantangshi-15482','送王副使还并州','李端','quantangshi','','卷16','并州近胡地，此去事风沙。
铁马垂金络，貂裘犯雪花。
曾持两郡印，多比五侯家。
继世新恩厚，从军旧国赊。
戍烟千里直，边雁一行斜。
想到清油幕，长谋出左军。','',''),('quantangshi-15483','晚春过夏侯校书值其沉醉戏赠','李端','quantangshi','','卷16','欹冠枕如意，独寝落花前。
姚馥清时醉，边韶白日眠。
曝褌还当屋，张幕便成天。
谒客唯题凤，偷儿欲觇毡。
失杯犹离席，坠履反登筵。
本是墙东隐，今为瓮下仙。
卧龙髯乍磔，栖蝶腹何便。
阮籍供琴韵，陶潜余秫田。
人逢毂阳望，春似永和年。
愿我非工饮，期君行见怜。
尝知渴羌好，亦觉醉胡贤。
炙熟樽方竭，车回辖且全。
噀风仍作雨，洒地即成泉。
自鄙新丰过，迟回惜十年。','',''),('quantangshi-15484','哭张南史因寄南史侄叔宗','李端','quantangshi','','卷16','争路忽摧车，沈钩未得鱼。
结交唯我少，丧旧自君初。
谏草文难似，围棊智不如。
仲宣新有赋，叔夜近无书。
地闭滕公宅，山荒谢客庐。
歼良从此恨，福善竟成虚。
酿酒多同醉，烹鸡或取余。
阮咸虽永别，岂共仲容疎。','',''),('quantangshi-15485','长安感事呈卢纶','李端','quantangshi','','卷16','十五事文翰，大儿轻孔融。
长裾游邸第，笑傲五侯中。
谏猎一朝寝，论边素未工。
蹉跎潘鬓至，蹭蹬阮途穷。
贷布怜宁兴，无金命未通。
王陵固似戆，郭最遂非雄。
敛板辞羣彦，回车访老农。
咏诗怀洛下，送客忆山东。
沈病魂神浊，清斋思虑空。
羸将衞玠比，冷共邺侯同。
草舍才遮雨，荆窗不碍风。
梨教通子守，酒是远师供。
扪虱欣时泰，迎猫达岁丰。
原门唯有席，井饮但加葱。
少壮衿齐德，高年觉宋聋。
寓书先论嬾，读易反求蒙。
昔慕能鸣雁，今怜半死桐。
秉心犹似矢，搔首忽如蓬。
赤叶翻藤架，黄花盖菊丛。
聊将呈匠伯，今已学愚公。','',''),('quantangshi-15486','游终南山因寄苏奉礼士尊师苗员外','李端','quantangshi','','卷16','半岭逢仙驾，清晨独采芝。
壶中开白日，雾里卷朱旗。
猨鸟知归路，松萝见会时。
鸡声传洞远，鹤语报家迟。
童子闲驱石，樵夫乐看棊。
依稀醉后拜，恍惚梦中辞。
海上终难接，人间益自疑。
风尘甘独老，山水但相思。
愿得烧丹诀，流沙永待师。','',''),('quantangshi-15487','长安书事寄卢纶','李端','quantangshi','','卷16','弱冠家庐岳，从师岁月深。
翻同老夫见，殊寡少年心。
及此时方晏，因之名亦沈。
趋途非要路，避事乐空林。
素业在山下，青泉当树阴。
交游有凋丧，离别代追寻。
向秀初闻笛，钟期久罢琴。
残愁犹满貌，余泪可霑襟。
勿以朱颜好，而忘白发侵。
终期入灵洞，相与炼黄金。','',''),('quantangshi-15488','送郭良辅下第东归','李端','quantangshi','','卷16','献策不得意，驰车东出秦。
暮年千里客，落日万家春。','',''),('quantangshi-15489','妾薄命','李端','quantangshi','','卷16','自从君弃妾，憔悴不羞人。
唯余坏粉泪，未免映衫匀。','',''),('quantangshi-15490','送暕上人游春','李端','quantangshi','','卷16','独将支遁去，欲往戴颙家。
晴野人临水，春山树发花。','',''),('quantangshi-15491','晦日同苗员外游曲江','李端','quantangshi','','卷16','晦日同携手，临流一望春。
可怜杨柳陌，愁杀故乡人。','',''),('quantangshi-15492','溪行逢雨与柳中庸','李端','quantangshi','','卷16','日落众山昏，萧萧暮雨繁。
那堪两处宿，共听一声猨。','',''),('quantangshi-15493','和张尹忆东篱菊','李端','quantangshi','','卷16','传书报刘尹，何事忆陶家。
若为篱边菊，山中有此花。','',''),('quantangshi-15494','幽居作','李端','quantangshi','','卷16','山舍千年树，江亭万里云。
回潮迎伍相，骤雨送湘君。','',''),('quantangshi-15495','题云际寺暕上人故院','李端','quantangshi','','卷16','白发怱怱色，青山草草心。
远公仍下世，从此别东林。','',''),('quantangshi-15496','观邻老栽松','李端','quantangshi','','卷16','虽过老人宅，不解老人心。
何事残阳里，栽松欲待阴。','',''),('quantangshi-15497','赠胡居士','李端','quantangshi','','卷16','孔融过五十，海内故人稀。
相府恩犹在，知君未拂衣。','',''),('quantangshi-15498','荐福寺送元伟','李端','quantangshi','','卷16','送客攀花后，寻僧坐竹时。
明朝莫回望，青草马行迟。','',''),('quantangshi-15499','哭苗垂','李端','quantangshi','','卷16','旧友无由见，孤坟草欲长。
月斜邻笛尽，车马出山阳。','',''),('quantangshi-15500','客行赠冯着','李端','quantangshi','','卷16','旅行虽别路，日暮各思归。
欲下今朝泪，知君亦湿衣。','',''),('quantangshi-15501','芜城','李端','quantangshi','','卷16','风吹城上树，草没城边路。
城里月明时，精灵自来去。','',''),('quantangshi-15502','赠山中老人','李端','quantangshi','','卷16','白首独一身，青山为四邻。
虽行故乡陌，不见故乡人。','',''),('quantangshi-15503','拜新月','李端','quantangshi','','卷16','开帘见新月，便即下阶拜。
细语人不闻，北风吹裙带。','',''),('quantangshi-15504','听筝','李端','quantangshi','','卷16','鸣筝金粟柱，素手玉房前。
欲得周郎顾，时时误拂弦。','',''),('quantangshi-15505','赠何兆','李端','quantangshi','','卷16','文章似扬马，风骨又清羸。
江汉君犹在，英灵信未衰。','',''),('quantangshi-15506','同司空文明过坚上人故院','李端','quantangshi','','卷16','我与雷居士，平生事远公。
无人知是旧，共到影堂中。','',''),('quantangshi-15507','杂诗','李端','quantangshi','','卷16','主第辞高饮，石家赴宵会。
金谷走车来，玉人骑马待。','',''),('quantangshi-15508','感兴','李端','quantangshi','','卷16','香炉最高顶，中有高人住。
日暮下山来，月明上山去。','',''),('quantangshi-15509','问张山人疾','李端','quantangshi','','卷16','先生沈病意何如，蓬艾门前客转疎。
不见领徒过绛帐，唯闻与婢削丹书。','',''),('quantangshi-15510','江上送客','李端','quantangshi','','卷16','故人南去汉江阴，秋雨萧萧云梦深。
江上见人应下泪，由来远客易伤心。','',''),('quantangshi-15511','闺情','李端','quantangshi','','卷16','月落星稀天欲明，孤灯未灭梦难成。
披衣更向门前望，不忿朝来鹊喜声。','',''),('quantangshi-15512','送刘侍郎','李端','quantangshi','','卷16','几人同去谢宣城，未及酬恩隔死生。
唯有夜猨知客恨，峄阳溪路第三声。','',''),('quantangshi-15513','重送郑宥归蜀因寄何兆','李端','quantangshi','','卷16','黄花西上路何如，青壁连天雁亦疎。
为报长卿休涤器，汉家思见茂陵书。','',''),('quantangshi-15514','宿石涧店闻妇人哭','李端','quantangshi','','卷16','山店门前一妇人，哀哀夜哭向秋云。
自说夫因征战死，朝来逢着旧将军。','',''),('quantangshi-15515','与道者别','李端','quantangshi','','卷16','闻说沧溟今已浅，何当白鹤更归来。
旧师唯有先生在，忍见门人掩泪回。','',''),('quantangshi-15516','长门怨','李端','quantangshi','','卷16','金壶漏尽禁门开，飞燕昭阳侍寝回。
随分独眠秋殿里，遥闻语笑自天来。','',''),('quantangshi-15517','忆友怀野寺旧居','李端','quantangshi','','卷16','自嫌野性共人疎，忆向西林更结庐。
寄谢山阴许都讲，昨来频得远公书。','',''),('quantangshi-15518','听夜雨寄卢纶','李端','quantangshi','','卷16','暮雨萧条过凤城，霏霏飒飒重还轻。
闻君此夜东林宿，听得荷池几番声。','',''),('quantangshi-15519','昭君词','李端','quantangshi','','卷16','李陵初送子卿回，汉月明时惆怅来。
忆着长安旧游处，千门万户玉楼台。','',''),('quantangshi-15520','春晚游鹤林寺寄使府诸公','李端','quantangshi','','卷16','野寺寻春花已迟，背岩惟有两三枝。
明朝携酒犹堪醉，为报春风且莫吹。','',''),('quantangshi-15521','南充谢郡客游澧州留赠宇文中丞','暢當','quantangshi','','卷16','仆本濩落人，辱当州郡使。
量力颇及早，谢归今即已。
萧萧若凌虚，襟带顿销靡。
车服率然来，涔阳作游子。
郁郁寡开颜，默默独行李。
忽逢平生友，一笑方在此。
秋情宁风日，楚思浩云水。
为语弋林者，冥冥鸿远矣。','',''),('quantangshi-15522','宿报恩寺精舍','暢當','quantangshi','','卷16','钟梵送沈景，星多露渐光。
风中兰靡靡，月下树苍苍。
夜殿若山横，深松如涧凉。
羸然虎溪子，迟我一虚牀。
杳杳空寂舍，蒙蒙莲桂香。
拥褐依西壁，纱灯霭中央。','',''),('quantangshi-15523','自平阳馆赴郡','暢當','quantangshi','','卷16','晨兴平阳馆，见月沈江水。
溶溶山雾披，肃肃沙鹭起。
奉恩谬符竹，伏轼省顽鄙。
何当施教化，愧迎小郡史。
寥落火耕俗，征途青冥里。
德绥及吾民，不德将鹿矣。
擒奸非性能，多愍会衰齿。
恭承共理诏，恒惧坠诸地。','',''),('quantangshi-15524','天柱隐所重答江州应物','暢當','quantangshi','','卷16','寂寞一怅望，秋风山景清。
此中惟草色，翻意见人行。
荒径饶松子，深萝绝鸟声。
阳崖全带日，宽嶂偶通耕。
拙昧难容世，贫寒别有情。
烦君琼玖赠，幽懒百无成。','',''),('quantangshi-15525','山居酬韦苏州见寄','暢當','quantangshi','','卷16','孤柴泄烟处，此中山叟居。
观云宁有事，耽酒讵知余。
水定鹤翻去，松歌峰俨如。
犹烦使君问，更欲结深庐。','',''),('quantangshi-15526','春日过奉诚园','暢當','quantangshi','','卷16','帝里阳和日，游人到御园。
暖催新景气，春认旧兰荪。
咏德先臣没，成蹊大树存。
见桐犹近井，看柳尚依门。
献地非更宅，遗忠永奉恩。
又期攀桂后，来赏百花繁。','',''),('quantangshi-15527','军中醉饮寄沈八刘叟','暢當','quantangshi','','卷16','酒渴爱江清，余酣漱晚汀。
软莎欹坐稳，冷石醉眠醒。
野膳随行帐，华音发从伶。
数杯君不见，都已遣沈冥。','',''),('quantangshi-15528','偶宴西蜀摩诃池','暢當','quantangshi','','卷16','珍木郁清池，风荷左右披。
浅觞宁及醉，慢舸不知移。
荫簟流光冷，凝簪照影欹。
胡为独羁者，雪涕向涟漪。','',''),('quantangshi-15529','奉送杜中丞赴洪州','暢當','quantangshi','','卷16','诏出凤凰宫，新恩连帅雄。
江湖经战阵，草木待仁风。
豪右贪威爱，纡繁德简通。
多慙君子顾，攀饯路尘中。','',''),('quantangshi-15530','九日陪皇甫使君泛江宴赤岸亭','暢當','quantangshi','','卷16','羁旅逢佳节，逍遥忽见招。
同倾菊花酒，缓棹木兰桡。
平楚堪愁思，长江去寂寥。
猿啼不离峡，滩沸镇如潮。
举目关山异，伤心乡国遥。
徒言欢满座，谁觉客魂消。','',''),('quantangshi-15531','蒲中道中二首 一','暢當','quantangshi','','卷16','苍苍中条山，厥形极奇磈。
我欲涉其崖，濯足黄河水。','',''),('quantangshi-15532','蒲中道中二首 二','暢當','quantangshi','','卷16','古刹栖杮林，绿阴覆苍瓦。
岁晏来品题，拾叶总堪写。','',''),('quantangshi-15533','登鹳雀楼','暢當','quantangshi','','卷16','逈临飞鸟上，高出世尘间。
天势围平野，河流入断山。','',''),('quantangshi-15534','宿潭上二首 一','暢當','quantangshi','','卷16','夜潭有仙舸，与月当水中。
嘉宾爱明月，游子惊秋风。','',''),('quantangshi-15535','宿潭上二首 二','暢當','quantangshi','','卷16','青蒲野陂水，白露明月天。
中夜秋风起，心事坐潸然。','',''),('quantangshi-15536','别卢纶','暢當','quantangshi','','卷16','故交君独在，又欲与君离。
我有新秋泪，非关宋玉悲。','',''),('quantangshi-15537','题沈八斋','暢當','quantangshi','','卷16','江斋一入何亭亭，因寄沦涟心杳冥。
绿绮琴弹白雪引，乌丝绢勒黄庭经。','',''),('quantangshi-15538','早春','暢諸','quantangshi','','卷16','献岁春犹浅，园林未尽开。
雪和新雨落，风带旧寒来。
听鸟闻归雁，看花识早梅。
生涯知几日，更被一年催。','',''),('quantangshi-15539','晓过南宫闻太常清乐','陸贄','quantangshi','','卷16','南宫闻古乐，拂曙听初惊。
烟霭遥迷处，丝桐暗辨名。
节随新律改，声带绪风轻。
合雅将移俗，同和自感情。
远音兼晓漏，余响过春城。
九奏明初日，寥寥天地清。','',''),('quantangshi-15540','禁中春松','陸贄','quantangshi','','卷16','阴阴清禁里，苍翠满春松。
雨露恩偏近，阳和色更浓。
高枝分晓日，虚吹杂宵钟。
香助炉烟远，形疑盖影重。
愿符千载寿，不羡五株封。
傥得回天眷，全胜老碧峰。','',''),('quantangshi-15541','赋得御园芳草','陸贄','quantangshi','','卷16','阴阴御园里，瑶草日光长。
靃靡含烟雾，依稀带夕阳。
雨余荑更密，风暖蕙初香。
拥仗缘驰道，乘舆入建章。
湿烟摇不散，细影乱无行。
恒恐韶光晚，何人辨早芳。','',''),('quantangshi-15542','句','陸贄','quantangshi','','卷16','遶堦流㶁㶁，来砌树阴阴。','',''),('quantangshi-15543','晓过南宫闻太常清乐','張濛','quantangshi','','卷16','玉珂经礼寺，金奏过南宫。
雅调乘清晓，飞声向远空。
慢随飘去雪，轻逐度来风。
迥出重城里，傍闻九陌中。
应将肆夏比，更与五英同。
一听南薫曲，因知大舜功。','',''),('quantangshi-15544','禁中春松','常沂','quantangshi','','卷16','映殿松偏好，森森列禁中。
攒柯霑圣泽，疎盖引皇风。
晚色连秦苑，春香满汉宫。
操将金石固，材与直臣同。
翠影宜青琐，苍枝秀碧空。
还知沐天眷，千载更葱茏。','',''),('quantangshi-15545','禁中春松','周存','quantangshi','','卷16','几岁含贞节，青青紫禁中。
日华留偃盖，雉尾转春风。
不为繁霜改，那将众木同。
千条攒翠色，百尺澹晴空。
影密金茎近，花明凤沼通。
安知幽涧侧，独与散樗丛。','',''),('quantangshi-15546','西戎献马','周存','quantangshi','','卷16','天马从东道，皇威被远戎。
来参八骏列，不假贰师功。
影别流沙路，嘶流上苑风。
望云时蹀足，向月每争雄。
禀异才难状，标奇志岂同。
驱驰如见许，千里一朝通。','',''),('quantangshi-15547','小苑春望宫池柳色','黎逢','quantangshi','','卷16','上林新柳变，小苑暮天晴。
始望和烟密，遥怜拂水轻。
色承阳气暖，阴带御沟清。
不厌随风弱，仍宜向日明。
垂丝遍阁榭，飞絮触帘旌。
渐到依依处，思闻出谷鸎。','',''),('quantangshi-15548','夏首犹清和','黎逢','quantangshi','','卷16','早夏宜初景，和光起禁城。
祝融将御节，炎帝启朱明。
日送残花晚，风过御苑清。
郊原浮麦气，池沼发荷英。
树影临山动，禽飞入汉轻。
幸逢尧禹化，全胜谷中情。','',''),('quantangshi-15549','小苑春望宫池柳色','張昔','quantangshi','','卷16','小苑春初至，皇衢日更清。
遥分万条柳，回出九重城。
隐映龙池润，参差凤阙明。
影宜宫雪曙，色带禁烟晴。
深浅残阳变，高低晓吹轻。
年光正堪折，欲寄一枝荣。','',''),('quantangshi-15550','小苑春望宫池柳色','丁位','quantangshi','','卷16','小苑春初望，宫池柳色轻。
低昂含晓景，萦转带新晴。
似盖芳初合，如丝荫渐成。
依依连水暗，袅袅出墙明。
虽以阳和发，能令旅思生。
他时花满路，从此接迁莺。','',''),('quantangshi-15551','小苑春望宫池柳色','友直','quantangshi','','卷16','柳色新池遍，春光御苑晴。
叶依青阁密，条向碧流倾。
路暗阴初重，波摇影转清。
风从垂处度，烟就望中生。
断续游蜂聚，飘颻戏蝶轻。
怡然变芳节，愿及一枝荣。','',''),('quantangshi-15552','小苑春望宫池柳色','楊系','quantangshi','','卷16','胜游从小苑，宫柳望春晴。
拂地青丝嫩，萦风绿带轻。
光含烟色远，影透水文清。
玉笛吟何得，金闺画岂成。
皇风吹欲断，圣日映逾明。
愿驻高枝上，还同出谷莺。','',''),('quantangshi-15553','小苑春望宫池柳色','崔績','quantangshi','','卷16','帝京春气早，御柳已先荣。
嫩叶随风散，浮光向月明。
悠扬生别意，断续引芳声。
积翠连驰道，飘花出禁城。
柔条依水弱，远色带烟轻。
南望龙池畔，斜光照晚晴。','',''),('quantangshi-15554','小苑春望宫池柳色','張季略','quantangshi','','卷16','韶光归汉苑。
柳色发春城，半见离宫出。
才分远水明，青葱当淑景。
隐映媚新晴，积翠烟初合。
微黄叶未生，迎春看尚嫩。
照日见先荣，倘得辞幽谷。
高枝寄一名。','',''),('quantangshi-15555','小苑春望宫池柳色','裴達','quantangshi','','卷16','胜游经小苑，闲望上春城。
御路韶光发，宫池柳色轻。
乍浓含雨润，微澹带云晴。
羃历残烟敛，摇扬落照明。
几条垂广殿，数树影高旌。
独有风尘客，思同雨露荣。','',''),('quantangshi-15556','南至日太史登台书云物','裴逵','quantangshi','','卷16','圆丘才展礼，佳气近初分。
太史新簪笔，高台纪彩云。
烟空和缥缈，晓色共氛氲。
道泰资贤辅，年丰荷圣君。
恭惟司国瑞，兼用察人文。
应念怀铅客，终朝望碧雰。','',''),('quantangshi-15557','小苑春望宫池柳色','沈迴','quantangshi','','卷16','今来游上苑，春染柳条轻。
濯濯方含色，依依若有情。
分行临曲沼，先发媚重城。
拂水枝偏弱，摇风丝已生。
变黄随淑景，吐翠逐新晴。
伫立徒延首，裴回欲寄诚。','',''),('quantangshi-15558','长安春夜宿开元观','楊憑','quantangshi','','卷16','霓裳下晚烟，留客杏花前。
徧问人寰事，新从洞府天。
长松皆扫月，老鹤不知年。
为说蓬瀛路，云涛几处连。','',''),('quantangshi-15559','晚泊江戍','楊憑','quantangshi','','卷16','旅棹依遥戍，清湘急晚流。
若为南浦宿，逢此北风秋。
云月孤鸿晚，关山几路愁。
年年不得意，零落对沧洲。','',''),('quantangshi-15560','巴江雨夜','楊憑','quantangshi','','卷16','五岭天无雁，三巴客问津。
纷纷轻汉暮，漠漠暗江春。
青草连湖岸，繁花忆楚人。
芳菲无限路，几夜月明新。','',''),('quantangshi-15561','边塞行','楊憑','quantangshi','','卷16','九原临得水，双足是重城。
独许为儒老，相怜从骑行。
细丛榆塞逈，高点雁山晴。
圣主嗤炎汉，无心自勒兵。','',''),('quantangshi-15562','乐游园望月','楊憑','quantangshi','','卷16','炎灵全盛地，明月半秋时。
今古人同望，盈亏节暗移。
彩凝双月逈，轮度八川迟。
共惜鸣珂去，金波送酒巵。','',''),('quantangshi-15563','千叶桃花','楊憑','quantangshi','','卷16','千叶桃花胜百花，孤荣春晚驻年华。
若教避俗秦人见，知向河源旧侣夸。','',''),('quantangshi-15564','春中泛舟','楊憑','quantangshi','','卷16','仙郎归奏过湘东，正值三湘二月中。
惆怅满川桃杏醉，醉看还与曲江同。','',''),('quantangshi-15565','雨中怨秋','楊憑','quantangshi','','卷16','辞家远客怆秋风，千里寒云与断蓬。
日暮隔山投古寺，钟声何处雨蒙蒙。','',''),('quantangshi-15566','秋日独游曲江','楊憑','quantangshi','','卷16','信马闲过忆所亲，秋山行尽路无尘。
主人莫惜松阴醉，还有千钱沽酒人。','',''),('quantangshi-15567','寄别','楊憑','quantangshi','','卷16','晚烟洲雾共苍苍，河雁惊飞不作行。
廻斾转舟行数里，歌声犹自逐清湘。','',''),('quantangshi-15568','边情','楊憑','quantangshi','','卷16','新种如今屡请和，玉关边上幸无他。
欲知北海苦辛处，看取节毛余几多。','',''),('quantangshi-15569','早发湘中','楊憑','quantangshi','','卷16','按节鸣笳中贵催，红旌白斾满船开。
迎愁湓浦登城望，西见荆门积水来。','',''),('quantangshi-15570','海榴','楊憑','quantangshi','','卷16','海榴殷色透帘栊，看盛看衰意欲同。
若许三英随五马，便将浓艳鬬繁红。','',''),('quantangshi-15571','春情','楊憑','quantangshi','','卷16','暮雨朝云几日归，如丝如雾湿人衣。
三湘二月春光早，莫逐狂风缭乱飞。','',''),('quantangshi-15572','送客往荆州','楊憑','quantangshi','','卷16','巴丘过日又登城，云水湘东一日平。
若爱春秋繁露学，正逢元凯镇南荆。','',''),('quantangshi-15573','赠马炼师','楊憑','quantangshi','','卷16','心嫌碧落更何从，月帔花冠冰雪容。
行雨若迷归处路，近南惟见祝融峰。','',''),('quantangshi-15574','湘江泛舟','楊憑','quantangshi','','卷16','湘川洛浦三千里，地角天涯南北遥。
除却同倾百壶外，不愁谁奈两魂销。','',''),('quantangshi-15575','送别','楊憑','quantangshi','','卷16','江岸梅花雪不如，看君驿驭向南徐。
相闻不必因来雁，云里飞輧落素书。','',''),('quantangshi-15576','赠窦牟','楊憑','quantangshi','','卷16','直用天才众却瞋，应欺李杜久为尘。
南荒不死中华老，别玉翻同西国人。','',''),('quantangshi-15577','送别','楊凝','quantangshi','','卷16','樽酒邮亭暮，云帆驿使归。
野鸥寒不起，川雨冻难飞。
吴会家移遍，轩辕梦去稀。
姓杨皆足泪，非是强沾衣。','',''),('quantangshi-15578','送客东归','楊凝','quantangshi','','卷16','君向古营州，边风战地愁。
草青缦别路，柳亚拂孤楼。
人意伤难醉，莺啼咽不流。
芳菲只合乐，离思返如秋。','',''),('quantangshi-15579','送客归湖南','楊凝','quantangshi','','卷16','湖南树色尽，了了辨潭州。
雨散今为别，云飞何处游。
情来偏似醉，泪迸不成流。
那向萧条路，缘湘篁竹愁。','',''),('quantangshi-15580','送客归淮南','楊凝','quantangshi','','卷16','画舫照河堤，暄风百草齐。
行丝直网蝶，去燕旋遗泥。
郡向高天近，人从别路迷。
非关御沟上，今日各东西。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-15581','春情','楊凝','quantangshi','','卷16','旧宅洛川阳，曾游游侠场。
水添杨柳色，花绊绮罗香。
赵瑟多愁曲，秦家足艳妆。
江潭远相忆，春梦不胜长。','',''),('quantangshi-15582','秋夜听捣衣','楊凝','quantangshi','','卷16','砧杵闻秋夜，裁缝寄远方。
声微渐湿露，响细未经霜。
兰牖唯遮树，风帘不碍凉。
云中望何处，听此断人肠。','',''),('quantangshi-15583','从军行','楊凝','quantangshi','','卷16','都尉出居延，强兵集五千。
还将张博望，直救范祁连。
汉卒悲箫鼓，胡姬湿采旃。
如今意气尽，流泪挹流泉。','',''),('quantangshi-15584','和直禁省','楊凝','quantangshi','','卷16','宵直丹宫近，风传碧树凉。
漏稀银箭滴，月度网轩光。
凤诏裁多暇，兰灯梦更长。
此时颜范贵，十步旧连行。','',''),('quantangshi-15585','留别','楊凝','quantangshi','','卷16','玉节随东阁，金闺别旧僚。
若为花满寺，跃马上河桥。','',''),('quantangshi-15586','送客往洞庭','楊凝','quantangshi','','卷16','九江归路远，万里客舟还。
若过巴江水，湘东满碧烟。','',''),('quantangshi-15587','别友人','楊凝','quantangshi','','卷16','倦客惊危路，伤禽遶树枝。
非逢暴公子，不敢涕流离。','',''),('quantangshi-15588','初渡淮北岸','楊凝','quantangshi','','卷16','别梦虽难觉，悲魂最易销。
殷勤淮北岸，乡近去家遥。','',''),('quantangshi-15589','咏雨','楊凝','quantangshi','','卷16','尘浥多人路，泥归足燕家。
可怜缭乱点，湿尽满宫花。','',''),('quantangshi-15590','柳絮','楊凝','quantangshi','','卷16','河畔多杨柳，追游尽狭斜。
春风一回送，乱入莫愁家。','',''),('quantangshi-15591','花枕','楊凝','quantangshi','','卷16','席上沈香枕，楼中荡子妻。
那堪一夜里，长湿两行啼。','',''),('quantangshi-15592','送客往鄜州','楊凝','quantangshi','','卷16','新参将相事营平，锦带騂弓结束轻。
晓上关城吟画角，暗驰羗马发支兵。
回中地近风常急，鄜畤年多草自生。
近喜扶阳系戎相，从来衞霍笑长缨。','',''),('quantangshi-15593','送客往夏州','楊凝','quantangshi','','卷16','怜君此去过居延，古塞黄云共渺然。
沙阔独行寻马迹，路迷遥指戍楼烟。
夜投孤店愁吹笛，朝望行尘避控弦。
闻有故交今从骑，何须着论更言钱。','',''),('quantangshi-15594','春霁晚望','楊凝','quantangshi','','卷16','细雨晴深小苑东，春云开气逐光风。
雄儿走马神光上，静女看花佛寺中。
书劒学多心欲嬾，田园荒废望频空。
南归路极天连海，惟有相思明月同。','',''),('quantangshi-15595','唐昌观玉蘂花','楊凝','quantangshi','','卷16','瑶华琼蘂种何年，萧史秦嬴向紫烟。
时控彩鸾过旧邸，摘花持献玉皇前。','',''),('quantangshi-15596','别李协','楊凝','quantangshi','','卷16','江边日暮不胜愁，送客霑衣江上楼。
明月峡添明月照，蛾眉峰似两眉愁。','',''),('quantangshi-15597','初次巴陵','楊凝','quantangshi','','卷16','西江浪接洞庭波，积水遥连天上河。
乡信为凭谁寄去，汀洲燕雁渐来多。','',''),('quantangshi-15598','上巳','楊凝','quantangshi','','卷16','帝京元巳足繁华，细管清弦七贵家。
此日风光谁不共，纷纷皆是掖垣花。','',''),('quantangshi-15599','春怨','楊凝','quantangshi','','卷16','花满帘栊欲度春，此时夫壻在咸秦。
绿窗孤寝难成寐，紫燕双飞似弄人。','',''),('quantangshi-15600','送客归常州','楊凝','quantangshi','','卷16','行到河边从此辞，寒天日远暮帆迟。
可怜芳草成衰草，公子归时过绿时。','',''),('quantangshi-15601','送别','楊凝','quantangshi','','卷16','春愁不尽别愁来，旧泪犹长新泪催。
相思倘寄相思字，君到扬州扬子回。','',''),('quantangshi-15602','送客入蜀','楊凝','quantangshi','','卷16','劒阁迢迢梦想间，行人归路遶梁山。
明朝骑马摇鞭去，秋雨槐花子午关。','',''),('quantangshi-15603','送别','楊凝','quantangshi','','卷16','仙花笑尽石门中，石室重重掩绿空。
蹔下云峰能几日，却回烟驾驭春风。','',''),('quantangshi-15604','残花','楊凝','quantangshi','','卷16','五马踟蹰在路岐，南来只为看花枝。
莺衔蝶弄红芳尽，此日深闺那得知。','',''),('quantangshi-15605','戏赠友人','楊凝','quantangshi','','卷16','湘阴直与地阴连，此日相逢忆醉年。
美酒非如平乐贵，十升不用一千钱。','',''),('quantangshi-15606','赠同游','楊凝','quantangshi','','卷16','此囗风雨后，已觉减年华。
若待皆无事，应难更有花。
管弦临夜急，榆柳向江斜。
且莫看归路，同须醉酒家。','',''),('quantangshi-15607','送人出塞','楊凝','quantangshi','','卷16','北风吹雨雪，举目已凄凄。
战鬼秋频哭，征鸿夜不栖。
沙平关路直，碛广郡楼低。
此去非东鲁，人多事鼓鼙。','',''),('quantangshi-15608','寻僧元皎因病','楊凝','quantangshi','','卷16','此僧迷友着，因病得寻师。
话尽山中事，归当月上时。
高松连寺影，亚竹入窗枝。
闲忆草堂路，相逢非素期。','',''),('quantangshi-15609','夜泊渭津','楊凝','quantangshi','','卷16','飘飘东去客，一宿渭城边。
远处星垂岸，中流月满船。
凉归夜深簟，秋入雨余天。
渐觉家山小，残程尚几年。','',''),('quantangshi-15610','晚夏逢友人','楊凝','quantangshi','','卷16','一别同袍友，相思已十年。
长安多在客，久病忽闻蝉。
骤雨才沾地，阴云不徧天。
微凉堪话旧，移榻晚风前。','',''),('quantangshi-15611','别谪者','楊凝','quantangshi','','卷16','此地闻犹恶，人言是所之。
一家书绝久，孤驿梦成迟。
八月三湘道，闻猨冒雨时。
不须祠楚相，臣节转堪疑。','',''),('quantangshi-15612','行思','楊凝','quantangshi','','卷16','千里岂云去，欲归如路穷。
人间无暇日，马上又秋风。
破月衔高岳，流星拂晓空。
此时皆在梦，行色独怱怱。','',''),('quantangshi-15613','感怀题从舅宅','楊凝','quantangshi','','卷16','郗家庭树下，几度醉春风。
今日花还发，当时事不同。
流言应未息，直道竟难通。
徒遣相思者，悲歌向暮空。','',''),('quantangshi-15614','与友人会','楊凝','quantangshi','','卷16','蝉吟槐蘂落，的的是愁端。
病觉离家远，贫知处事难。
真交无所隐，深语有余欢。
未必闻歌吹，羁心得蹔宽。','',''),('quantangshi-15615','下第后蒙侍郎示意指于新先辈宣恩感谢','楊凝','quantangshi','','卷16','才薄命如此，自嗟兼自疑。
遭逢好交日，黜落至公时。
倚玉甘无路，穿杨却未期。
更慙君侍坐，问许可言诗。','',''),('quantangshi-15616','奉酬韦滁州寄示','楊凌','quantangshi','','卷16','淮扬为郡暇，坐惜流芳歇。
散怀累榭风，清暑澄潭月。
陪燕辞三楚，戒途绵百越。
非当远别离，雅奏何由发。','',''),('quantangshi-15617','梅里旅夕','楊凌','quantangshi','','卷16','沧洲东望路，旅棹怆羁游。
枫浦蝉随岸，沙汀鸥转流。
露天星上月，水国夜生秋。
谁忍持相忆，南归一叶舟。','',''),('quantangshi-15618','钟陵雪夜酬友人','楊凌','quantangshi','','卷16','穷腊催年急，阳春怯和歌。
残灯闪壁尽，夜雪透窗多。
归路山川险，游人梦寐过。
龙洲不可泊，岁晚足惊波。','',''),('quantangshi-15619','润州水楼','楊凌','quantangshi','','卷16','归心不可留，雪桂一丛秋。
叶雨空江月，萤飞白露洲。
野蝉依独树，水郭带孤楼。
遥望山川路，相思万里游。','',''),('quantangshi-15620','江上秋月','楊凌','quantangshi','','卷16','陇雁送乡心，羁情属岁阴。
惊秋黄叶遍，愁暮碧云深。
月色吴江上，风声楚木林。
交亲几重别，归梦并愁侵。','',''),('quantangshi-15621','阁前双槿','楊凌','quantangshi','','卷16','羣玉开双槿，丹荣对绛纱。
含烟疑出火，隔雨怪舒霞。
向晚争辞蘂，迎朝鬬发花。
非关后桃李，为欲继年华。','',''),('quantangshi-15622','小苑春望宫池柳色','楊凌','quantangshi','','卷16','上苑闲游早，东风柳色轻。
储胥遥掩映，池水隔微明。
春至条偏弱，寒余叶未成。
和烟变浓淡，转日异阴晴。
不独芳菲好，还因雨露荣。
行人望攀折，远翠暮愁生。','',''),('quantangshi-15623','送客往睦州','楊凌','quantangshi','','卷16','水阔尽南天，孤舟去渺然。
惊秋路傍客，日暮数声蝉。','',''),('quantangshi-15624','送客之蜀','楊凌','quantangshi','','卷16','西蜀三千里，巴南水一方。
晓云天际断，夜月峡中长。','',''),('quantangshi-15625','剡溪看花','楊凌','quantangshi','','卷16','花落千廻舞，莺声百啭歌。
还同异方乐，不奈客愁多。','',''),('quantangshi-15626','江中风','楊凌','quantangshi','','卷16','白浪暗江中，南泠路不通。
高樯帆自满，出浦莫呼风。','',''),('quantangshi-15627','咏破扇','楊凌','quantangshi','','卷16','粉落空牀弃，尘生故箧留。
先来无一半，情断不胜愁。','',''),('quantangshi-15628','贾客愁','楊凌','quantangshi','','卷16','山水路悠悠，逢滩即殢留。
西江风未便，何日到荆州。','',''),('quantangshi-15629','即事寄人','楊凌','quantangshi','','卷16','中禁鸣钟日欲高，北窗欹枕望频搔。
相思寂寞青苔合，唯有春风啼伯劳。','',''),('quantangshi-15630','早春雪中','楊凌','quantangshi','','卷16','新年雨雪少晴时，屡失寻梅看柳期。
乡信忆随回雁早，江春寒带故阴迟。','',''),('quantangshi-15631','北行留别','楊凌','quantangshi','','卷16','日日山川烽火频，山河重起旧烟尘。
一生孤负龙泉劒，羞把诗书问故人。','',''),('quantangshi-15632','秋原野望','楊凌','quantangshi','','卷16','客雁秋来次第逢，家书频寄两三封。
夕阳天外云归尽，乱见青山无数峰。','',''),('quantangshi-15633','春霁花萼楼南闻宫莺','楊凌','quantangshi','','卷16','祥烟瑞气晓来轻，柳变花开共作晴。
黄鸟远啼鳷鹊观，春风流出凤皇城。','',''),('quantangshi-15634','明妃怨','楊凌','quantangshi','','卷16','汉国明妃去不还，马驮弦管向阴山。
匣中纵有菱花镜，羞对单于照旧颜。','',''),('quantangshi-15635','句','楊凌','quantangshi','','卷16','南园桃李花落尽，春风寂寞摇空枝。','',''),('quantangshi-15636','题玉真观公主山池院','司空曙','quantangshi','','卷16','香殿留遗影，春朝玉户开。
羽衣重素几，珠网俨轻埃。
石自蓬山得，泉经太液来。
柳丝遮绿浪，花粉落青苔。
镜掩鸾空在，霞消凤不回。
唯余古桃树，传是上仙栽。','',''),('quantangshi-15637','送永阳崔明府','司空曙','quantangshi','','卷16','古国羣舒地，前当桐柏关。
连绵江上雨，稠叠楚南山。
沙馆行帆息，枫洲候吏还。
乘篮若有暇，精舍在林间。','',''),('quantangshi-15638','送曹三同猗游山寺','司空曙','quantangshi','','卷16','山蹋青芜尽，凉秋古寺深。
何时得连策，此夜更闻琴。
穷水云同穴，过僧虎共林。
殷勤如念我，遗尔挂冠心。','',''),('quantangshi-15639','送崔校书赴梓幕','司空曙','quantangshi','','卷16','碧峯天柱下，鼓角镇南军。
管记催飞檄，蓬莱辍校文。
栈霜朝似雪，江雾晚成云。
想出褒中望，巴庸方路分。','',''),('quantangshi-15640','送夔州班使君','司空曙','quantangshi','','卷16','鱼国巴庸路，麾幢汉守过。
晓樯争市隘，夜鼓祭神多。
云白当山雨，风清满峡波。
夷陵旧人吏，犹诵两岐歌。','',''),('quantangshi-15641','送菊潭王明府','司空曙','quantangshi','','卷16','业成洙泗客，皓发着儒衣。
一与游人别，仍闻带印归。
林多宛地古，云尽汉山稀。
莫爱浔阳隐，嫌官计亦非。','',''),('quantangshi-15642','送太易上人赴东洛','司空曙','quantangshi','','卷16','遥见登山处，青芜雪后春。
云深岳庙火，寺宿洛阳人。
饵药将斋折，唯诗与道亲。
凡经几回别，麈尾不离身。','',''),('quantangshi-15643','和王卿立秋即事','司空曙','quantangshi','','卷16','秋宜何处看，试问白云官。
暗入蝉鸣树，微侵蝶绕兰。
向风凉稍动，近日暑犹残。
九陌浮埃减，千峯爽气攒。
换衣防竹暮，沈果讶泉寒。
宫响传花杵，天清出露盘。
高禽当侧弁，游鲔对凭栏。
一奏招商曲，空令继唱难。','',''),('quantangshi-15644','和李员外与舍人咏玫瑰花寄徐侍郎','司空曙','quantangshi','','卷16','仙吏紫薇郎，奇花共翫芳。
攒星排绿蒂，照眼发红光。
暗妬翻堦药，遥连直署香。
游枝蜂绕易，碍刺鸟衔妨。
露湿凝衣粉，风吹散蕊黄。
蒙茏珠树合，焕烂锦屏张。
留客胜看竹，思人比爱棠。
如传采苹咏，远思满潇湘。','',''),('quantangshi-15645','冬夜耿拾遗王秀才就宿因伤故人','司空曙','quantangshi','','卷16','旧时闻笛泪，今夜重沾衣。
方恨同人少，何堪相见稀。
竹烟凝涧壑，林雪似芳菲。
多谢劳车马，应怜独掩扉。','',''),('quantangshi-15646','早春游慈恩南池','司空曙','quantangshi','','卷16','山寺临池水，春愁望远生。
蹋桥逢鹤起，寻竹值泉横。
新柳丝犹短，轻苹叶未成。
还如虎溪上，日暮伴僧行。','',''),('quantangshi-15647','雨夜见投之作','司空曙','quantangshi','','卷16','出户繁星尽，池塘暗不开。
动衣凉气度，遰树远声来。
灯外初行电，城隅偶隐雷。
因知谢文学，晓望比尘埃。','',''),('quantangshi-15648','龙池寺望月寄韦使君阎别驾','司空曙','quantangshi','','卷16','清光此夜中，万古望应同。
当野山沈雾，低城树有风。
花宫纷共邃，水府皓相空。
遥想高楼上，唯君对庾公。','',''),('quantangshi-15649','秋夜忆兴善院寄苗发','司空曙','quantangshi','','卷16','右军多住寺，此夜后池秋。
自与山僧伴，那因洛客愁。
卷帘霜霭霭，满目水悠悠。
若有诗相赠，期君忆惠休。','',''),('quantangshi-15650','病中寄郑十六兄','司空曙','quantangshi','','卷16','倦枕欲徐行，开帘秋月明。
手便筇杖冷，头喜葛巾轻。
绿草前侵水，黄花半上城。
虚消此尘景，不见十年兄。','',''),('quantangshi-15651','衞明府寄枇杷叶以诗答','司空曙','quantangshi','','卷16','倾筐呈绿叶，重叠色何鲜。
讵是秋风里，犹如晓露前。
仙方当见重，消疾本应便。
全胜甘蕉赠，空投谢氏篇。','',''),('quantangshi-15652','过庆宝寺','司空曙','quantangshi','','卷16','黄叶前朝寺，无僧寒殿开。
池晴龟出曝，松暮鹤飞回。
古井碑横草，阴廊画杂苔。
禅宫亦销歇，尘世转堪哀。','',''),('quantangshi-15653','奉和张大夫酬高山人','司空曙','quantangshi','','卷16','野客居铃阁，重门将校稀。
豸冠亲谷弁，龟印识荷衣。
座右寒飙爽，谈余暮角微。
苍生须太傅，山在岂容归。','',''),('quantangshi-15654','送严使君游山','司空曙','quantangshi','','卷16','家楚依三户，辞州选一钱。
酒杯同寄世，客棹任销年。
赤烧兼山远，青芜与浪连。
青春明月夜，知上鄂君船。','',''),('quantangshi-15655','送柳震归蜀','司空曙','quantangshi','','卷16','白日双流静，西看蜀国春。
桐花能乳鸟，竹节竞祠神。
蹇步徒相望，先鞭不可亲。
知从江仆射，登榻更何人。','',''),('quantangshi-15656','送乐平苗明府','司空曙','quantangshi','','卷16','天际山多处，东安古邑深。
绿田通竹里，白浪隔枫林。
诗有江僧和，门唯越客寻。
应将放鱼化，一境表吾心。','',''),('quantangshi-15657','赠送郑钱二郎中','司空曙','quantangshi','','卷16','梅含柳已动，昨日起东风。
惆怅心徒壮，无如鬓作翁。
百年飘若水，万绪尽归空。
何可宗禅客，迟回岐路中。','',''),('quantangshi-15658','酬郑十四望驿不得同宿见赠因寄张参军','司空曙','quantangshi','','卷16','逢君喜成泪，暂似故乡中。
谪宦犹多惧，清宵不得终。
月烟高有鹤，宿草净无虫。
明日郄超会，应思下客同。','',''),('quantangshi-15659','暮春野望寄钱起','司空曙','quantangshi','','卷16','草长花落树，羸病强寻春。
无复少年意，空余华发新。
青原高见水，白社静逢人。
寄谢南宫客，轩车不可亲。','',''),('quantangshi-15660','送王使君小子孝廉登科归省','司空曙','quantangshi','','卷16','年少通经学，登科尚佩觿。
张冯本名士，蔡廓是佳儿。
鞍马临岐路，龙钟对别离。
寄书胡太守，请与故人知。','',''),('quantangshi-15661','云阳寺石竹花','司空曙','quantangshi','','卷16','一自幽山别，相逢此寺中。
高低俱出叶，深浅不分丛。
野蝶难争白，庭榴暗让红。
谁怜芳最久，春露到秋风。','',''),('quantangshi-15662','送高胜重谒曹王','司空曙','quantangshi','','卷16','江上青枫岸，阴阴万里春。
朝辞郢城酒，暮见洞庭人。
兴比乘舟访，恩怀倒屣亲。
想君登旧榭，重喜扫芳尘。','',''),('quantangshi-15663','闲园书事招畅当','司空曙','quantangshi','','卷16','闻蝉昼眠后，欹枕对蓬蒿。
羸病嬾寻戴，田园方咏陶。
傍檐虫挂静，出树蝶飞高。
惆怅临清镜，思君见鬓毛。','',''),('quantangshi-15664','过钱员外','司空曙','quantangshi','','卷16','为郎头已白，迹向市朝稀。
移病居荒宅，安贫着败衣。
野园随客醉，雪寺伴僧归。
自说东峯下，松萝满故扉。','',''),('quantangshi-15665','赠庾侍御','司空曙','quantangshi','','卷16','年少身无累，相逢忆此时。
雪过云寺宿，酒向竹园期。
白发今催老，清琴但起悲。
唯应逐宗炳，内学愿为师。','',''),('quantangshi-15666','赠李端','司空曙','quantangshi','','卷16','共忆南浮日，登高望若何。
楚田湖草远，江寺海榴多。
载酒寻山宿，思人带雪过。
东西几回别，此会各磋砣。','',''),('quantangshi-15667','送流人','司空曙','quantangshi','','卷16','闻说南中事，悲君重窜身。
山村枫子鬼，江庙石郎神。
童稚留荒宅，图书托故人。
青门好风景，为尔一沾巾。','',''),('quantangshi-15668','过胡居士覩王右丞遗文','司空曙','quantangshi','','卷16','旧日相知尽，深居独一身。
闭门空有雪，看竹永无人。
每许前山隐，曾怜陋巷贫。
题诗今尚在，暂为拂流尘。','',''),('quantangshi-15669','送郎使君赴郢州','司空曙','quantangshi','','卷16','使君持节去，云水满前程。
楚寺多连竹，江樯远暎城。
登楼向月望，赛庙傍山行。
若动思乡咏，应贻谢步兵。','',''),('quantangshi-15670','贼平后送人北归','司空曙','quantangshi','','卷16','世乱同南去，时清独北还。
他乡生白发，旧国见青山。
晓月过残垒，繁星宿故关。
寒禽与衰草，处处伴愁颜。','',''),('quantangshi-15671','观猎骑','司空曙','quantangshi','','卷16','缠臂绣纶巾，貂裘窄称身。
射禽风助箭，走马雪翻尘。
金埒争开道，香车为驻轮。
翩翩不知处，传是霍家亲。','',''),('quantangshi-15672','同苗员外宿荐福常师房','司空曙','quantangshi','','卷16','浮生共多故，聚宿喜君同。
人息时闻磬，灯摇乍有风。
霜堦疑水际，夜木似山中。
一愿持如意，长来事远公。','',''),('quantangshi-15673','送乔广下第归淮南','司空曙','quantangshi','','卷16','遥想长淮尽，荒堤楚路斜。
戍旌标白浪，罟网入青葭。
啼鸟仍临水，愁人更见花。
东堂一枝在，为子惜年华。','',''),('quantangshi-15674','风筝','司空曙','quantangshi','','卷16','高风吹玉柱，万籁忽齐飘。
飒树迟难度，萦空细渐销。
松泉鹿门夜，笙鹤洛滨朝。
坐与真僧听，支颐向寂寥。','',''),('quantangshi-15675','闲居寄苗发','司空曙','quantangshi','','卷16','渐向浮生老，前期竟若何。
独身居处静，永夜坐时多。
厌逐青林客，休吟白雪歌。
支公有遗寺，重与谢安过。','',''),('quantangshi-15676','送王先生归南山','司空曙','quantangshi','','卷16','儒中年最老，独有济南生。
爱子方传业，无官自耦耕。
竹通山舍远，云接雪田平。
愿作门人去，相随隐姓名。','',''),('quantangshi-15677','寄天台秀师','司空曙','quantangshi','','卷16','天台瀑布寺，传有白头师。
幻迹示羸病，空门无住持。
雪晴看鹤去，海夜与龙期。
永愿亲瓶屦，呈功得问疑。','',''),('quantangshi-15678','送夏侯审赴宁国','司空曙','quantangshi','','卷16','青圻连白浪，晓日渡南津。
山叠陵阳树，舟多建业人。
烟霞高占寺，枫竹暗停神。
如接玄晖集，江丞独见亲。','',''),('quantangshi-15679','云阳馆与韩绅宿别','司空曙','quantangshi','','卷16','故人江海别，几度隔山川。
乍见翻疑梦，相悲各问年。
孤灯寒照雨，湿竹暗浮烟。
更有明朝恨，离杯惜共传。','',''),('quantangshi-15680','送卢使君赴夔州','司空曙','quantangshi','','卷16','铙管随旌斾，高秋远上巴。
白波连雾雨，青壁断蒹葭。
凭几双童静，登楼万井斜。
政成知变俗，当应画轮车。','',''),('quantangshi-15681','夜闻回雁','司空曙','quantangshi','','卷16','雁响天边过，高高望不分。
飕飗传细雨，嘹唳隔长云。
散向谁家尽，归来几客闻。
还将今夜意，西海话苏君。','',''),('quantangshi-15682','赋得的的帆向浦','司空曙','quantangshi','','卷16','向浦参差去，随波远近还。
初移芳草里，正在夕阳间。
隐暎回孤驿，微明出乱山。
向空看不尽，归思满江关。','',''),('quantangshi-15683','秋思呈尹植裴说','司空曙','quantangshi','','卷16','静向嬾相偶，年将衰共催。
前途懽不集，往事恨空来。
昼景委红叶，月华销绿苔。
沈思竟何有，坐结玉琴哀。','',''),('quantangshi-15684','闲园即事寄暕公','司空曙','quantangshi','','卷16','欲就东林寄一身，尚怜儿女未成人。
柴门客去残阳在，药圃虫喧秋雨频。
近水方同梅市隐，曝衣多笑阮家贫。
深山兰若何时到，羡与闲云作四邻。','',''),('quantangshi-15685','题暕上人院','司空曙','quantangshi','','卷16','闭门不出自焚香，拥褐看山岁月长。
雨后绿苔生石井，秋来黄叶遍绳牀。
身闲何处无真性，年老曾言隐故乡。
更说本师同学在，几时携手见衡阳。','',''),('quantangshi-15686','长安晓望寄程补阙','司空曙','quantangshi','','卷16','迢遰山河拥帝京，参差宫殿接云平。
风吹晓漏经长乐，柳带晴烟出禁城。
天净笙歌临路发，日高车马隔尘行。
独有浅才甘未达，多慙名在鲁诸生。','',''),('quantangshi-15687','下第日书情寄上叔父','司空曙','quantangshi','','卷16','微才空觉滞京师，末学曾为叔父知。
雪里题诗偏见赏，林间饮酒独令随。
游客尽伤春色老，贫居还惜暮阴移。
欲归江海寻山去，愿报何人得桂枝。','',''),('quantangshi-15688','南原望汉宫','司空曙','quantangshi','','卷16','荒原空有汉宫名，衰草茫茫雉堞平。
连雁下时秋水在，行人过尽暮烟生。
西陵歌吹何年绝，南陌登临此日情。
故事悠悠不可问，寒禽野水自纵横。','',''),('quantangshi-15689','早夏寄元校书','司空曙','quantangshi','','卷16','独游野径送芳菲，高竹林居接翠微。
绿岸草深虫入徧，青藂花尽蝶来稀。
珠荷荐果香寒簟，玉柄摇风满夏衣。
蓬荜永无车马到，更当斋夜忆玄晖。','',''),('quantangshi-15690','赠衡岳隐禅师','司空曙','quantangshi','','卷16','拥褐安居南岳头，白云高寺见衡州。
石窗湖水摇寒月，枫树猨声报夜秋。
讲席旧逢山鸟至，梵经初向竺僧求。
垂垂身老将传法，因下人间逐北游。','',''),('quantangshi-15691','题凌云寺','司空曙','quantangshi','','卷16','春山古寺遶沧波，石磴盘空鸟道过。
百丈金身开翠壁，万龛灯焰隔烟萝。
云生客到侵衣湿，花落僧禅覆地多。
不与方袍同结社，下归尘世竟如何。','',''),('quantangshi-15692','晦日益州北池陪宴','司空曙','quantangshi','','卷16','临泛从公日，仙舟翠幕张。
七桥通碧沼，双树接花塘。
玉烛收寒气，金波隐夕光。
野闻歌管思，水静绮萝香。
游骑萦林远，飞桡截岸长。
郊原怀灞浐，陂溠写江潢。
常侍传花诏，偏裨问羽觞。
岂令南岘首，千载播余芳。','',''),('quantangshi-15693','送曲山人之衡州','司空曙','quantangshi','','卷16','白石先生眉发光，已分甜雪饮红浆。
衣巾半染烟霞气，语笑兼和药草香。
茅洞玉声流暗水，衡山碧色暎朝阳。
千年城郭如相问，华表峩峩有夜霜。','',''),('quantangshi-15694','立秋日','司空曙','quantangshi','','卷16','律变新秋至，萧条自此初。
花酣莲报谢，叶在柳呈疎。
澹日非云暎，清风似雨余。
卷帘凉暗度，迎扇暑先除。
草静多翻燕，波澄乍露鱼。
今朝散骑省，作赋兴何如。','',''),('quantangshi-15695','咏古寺花','司空曙','quantangshi','','卷16','共爱芳菲此树中，千跗万萼裹枝红。
迟迟欲去犹回望，覆地无人满寺风。','',''),('quantangshi-15696','酬张芬有赦后见赠','司空曙','quantangshi','','卷16','紫凤朝衔五色书，阳春忽布网罗除。
已将心变寒灰后，岂料光生腐草余。
建水风烟收客泪，杜陵花竹梦郊居。
劳君故有诗相赠，欲报琼瑶恨不如。','',''),('quantangshi-15697','哭苗员外呈张参军','司空曙','quantangshi','','卷16','思君甯家宅，久接竹林期。
尝值偷琴处，亲闻比玉时。
高人不易合，弱冠早相知。
试艺临诸友，能文即我师。
凌寒松未老，先暮槿何衰。
季子生前别，羊昙醉后悲。
寿堂乖一恸，奠席阻长辞。
因沥殊方泪，遥成墓下诗。','',''),('quantangshi-15698','金陵怀古','司空曙','quantangshi','','卷16','辇路江枫暗，宫庭野草春。
伤心庾开府，老作北朝臣。','',''),('quantangshi-15699','发渝州却寄韦判官','司空曙','quantangshi','','卷16','红烛津亭夜见君，繁弦急管两纷纷。
平明分手空江转，唯有猨声满水云。','',''),('quantangshi-15700','送卢彻之太原谒马尚书','司空曙','quantangshi','','卷16','榆落雕飞关塞秋，黄云画角见并州。
翩翩羽骑双旌后，上客亲随郭细侯。','',''),('quantangshi-15701','峡口送友人','司空曙','quantangshi','','卷16','峡口花飞欲尽春，天涯去住泪沾巾。
来时万里同为客，今日飜成送故人。','',''),('quantangshi-15702','故郭婉仪挽歌','司空曙','quantangshi','','卷16','一日辞秦镜，千秋别汉宫。
岂唯泉路掩，长使月轮空。
苦色凝朝露，悲声切暝风。
婉仪余旧德，仍载礼经中。','',''),('quantangshi-15703','送翰林张学士岭南勒圣碑','司空曙','quantangshi','','卷16','汉恩天外洽，周颂日边称。
文独司空羡，书兼太尉能。
出关逢北雁，度岭逐南鹏。
使者翰林客，余春归灞陵。','',''),('quantangshi-15704','送吉校书东归','司空曙','quantangshi','','卷16','少年芸阁吏，罢直暂归休。
独与亲知别，行逢江海秋。
听猨看楚岫，随雁到吴洲。
处处园林好，何人待子猷。','',''),('quantangshi-15705','早春游望','司空曙','quantangshi','','卷16','东风春未足，试望秦城曲。
青草状寒芜，黄花似秋菊。
壮将欢共去，老与悲相逐。
独作游社人，暮过威辇宿。','',''),('quantangshi-15706','秋日趋府上张大夫','司空曙','quantangshi','','卷16','重城洞启肃秋烟，共说羊公在镇年。
鞞鼓暗惊林叶落，旌旗遥拂雁行偏。
石过桥下书曾受，星降人间梦已传。
谪吏何能沐风化，空将歌颂拜车前。','',''),('quantangshi-15707','竹里径','司空曙','quantangshi','','卷16','幽径行迹稀，清阴苔色古。
萧萧风欲来，乍似蓬山雨。','',''),('quantangshi-15708','黄子陂','司空曙','quantangshi','','卷16','岸芳春色晓，水影夕阳微。
寂寂深烟里，渔舟夜不归。','',''),('quantangshi-15709','田鹤','司空曙','quantangshi','','卷16','散下渚田中，隐见菰蒲里。
哀鸣自相应，欲作凌风起。','',''),('quantangshi-15710','药园','司空曙','quantangshi','','卷16','春园芳已遍，绿蔓杂红英。
独有深山客，时来辨药名。','',''),('quantangshi-15711','石井','司空曙','quantangshi','','卷16','苔色遍春石，桐阴入寒井。
幽人独汲时，先乐残阳影。','',''),('quantangshi-15712','板桥','司空曙','quantangshi','','卷16','横遮野水石，前带荒村道。
来往见愁人，清风柳阴好。','',''),('quantangshi-15713','石莲花','司空曙','quantangshi','','卷16','今逢石上生，本自波中有。
红艳秋风里，谁怜众芳后。','',''),('quantangshi-15714','远寺钟','司空曙','quantangshi','','卷16','杳杳疎钟发，因风清复引。
中宵独听之，似与东林近。','',''),('quantangshi-15715','松下雪','司空曙','quantangshi','','卷16','不随晴野尽，独向深松积。
落照入寒光，偏能伴幽寂。','',''),('quantangshi-15716','新柳','司空曙','quantangshi','','卷16','全欺芳蕙晚，似妬寒梅疾。
撩乱发青条，春风来几日。','',''),('quantangshi-15717','唐昌公主院看花','司空曙','quantangshi','','卷16','遗殿空长闭，乘鸾自不回。
至今荒草上，寥落旧花开。','',''),('quantangshi-15718','别张赞','司空曙','quantangshi','','卷16','今日山晴后，残蝉菊发时。
登楼见秋色，何处最相思。','',''),('quantangshi-15719','晚思','司空曙','quantangshi','','卷16','蛩余窗下月，草湿堦前露。
晚景凄我衣，秋风入庭树。','',''),('quantangshi-15720','留卢秦卿','司空曙','quantangshi','','卷16','知有前期在，难分此夜中。
无将故人酒，不及石尤风。','',''),('quantangshi-15721','登岘亭','司空曙','quantangshi','','卷16','岘山回首望秦关，南向荆州几日还。
今日登临唯有泪，不知风景在何山。','',''),('quantangshi-15722','哭麴山人','司空曙','quantangshi','','卷16','忆昔秋风起，君曾叹逐臣。
何言芳草日，自作九泉人。','',''),('quantangshi-15723','过坚上人故院与李端同赋','司空曙','quantangshi','','卷16','旧依支遁宿，曾与戴颙来。
今日空林下，唯知见绿苔。','',''),('quantangshi-15724','病中嫁女妓','司空曙','quantangshi','','卷16','万事伤心在目前，一身垂泪对花筵。
黄金用尽教歌舞，留与他人乐少年。','',''),('quantangshi-15725','江村即事','司空曙','quantangshi','','卷16','钓罢归来不系船，江村月落正堪眠。
纵然一夜风吹去，只在芦花浅水边。','',''),('quantangshi-15726','送郑明府贬岭南','司空曙','quantangshi','','卷16','青枫江色晚，楚客独伤春。
共对一尊酒，相看万里人。
猜嫌成谪宦，正直不防身。
莫畏炎方久，年年雨露新。','',''),('quantangshi-15727','寄衞明府常见短靴褐裘又务持诵是以有末句之赠','司空曙','quantangshi','','卷16','柴桑官舍近东林，儿稚初髫即道心。
侧寄绳牀嫌凭几，斜安苔帻嬾穿簪。
高僧静望山僮逐，走吏喧来水鸭沈。
翠竹黄花皆佛性，莫教尘境误相侵。','',''),('quantangshi-15728','酬李端校书见赠','司空曙','quantangshi','','卷16','绿槐垂穗乳乌飞，忽忆山中独未归。
青镜流年看发变，白云芳草与心违。
乍逢酒客春游惯，久别林僧夜坐稀。
昨日闻君到城阙，莫将簪弁胜荷衣。','',''),('quantangshi-15729','过卢秦卿旧居','司空曙','quantangshi','','卷16','五柳茅茨楚国贤，桔槔蔬圃水涓涓。
黄花寒后难逢蝶，红叶晴来忽有蝉。
韩康助采君臣药，支遁同看内外篇。
为问潜夫空着论，如何侍从赋甘泉。','',''),('quantangshi-15730','秋园','司空曙','quantangshi','','卷16','伤秋不是惜年华，别忆春风碧玉家。
强向衰藂见芳意，茱萸红实似繁花。','',''),('quantangshi-15731','送王使君赴太原拜节度副使','司空曙','quantangshi','','卷16','新从刘太尉，结束向并州。
络脑青丝骑，盘囊锦带钩。
出关逢将校，下岭拥戈矛。
匣闭黄云冷，山传画角秋。
劒锋将破虏，函道罢登楼。
岂作书生老，当封万户侯。','',''),('quantangshi-15732','拟百劳歌','司空曙','quantangshi','','卷16','朱丝纽弦金点杂，双蔕芙蓉共开合。
谁家稚女着罗裳，红粉青眉娇暮妆。
木难作牀牙作席，云母屏风光照壁。
玉颜年几新上头，回身敛笑多自羞。
红销月落不复见，可惜当时谁拂面。','',''),('quantangshi-15733','迎神','司空曙','quantangshi','','卷16','吉日兮临水，沐青兰兮白芷。
假山鬼兮请东皇，托灵均兮邀帝子。
吹参差兮正苦，舞婆娑兮未已。
鸾旌圆盖望欲来，山雨霏霏江浪起。
神既降兮我独知，目成再拜为陈词。','',''),('quantangshi-15734','送神','司空曙','quantangshi','','卷16','神之去，回风袅袅云容与。
桂尊瑶席不复陈，苍山绿水暮愁人。','',''),('quantangshi-15735','残莺百啭歌同王员外耿拾遗吉中孚李端游慈恩各赋一物','司空曙','quantangshi','','卷16','残莺一何怨，百啭相寻续。
始辨下将高，稍分长复促。
绵蛮巧状语，机节终如曲。
野客赏应迟，幽僧闻讵足。
禅斋深树夏阴清，零落空余三两声。
金谷筝中传不似，山阳笛里写难成。
忆昨乱啼无远近，晴宫晓色偏相引。
送暖初随柳色来，辞芳暗逐花枝尽。
歌残莺，歌残莺，悠然万感生。
谢朓羇怀方一听，何郎闲吟本多情。
乃知众鸟非俦比，暮噪晨鸣倦人耳。
共爱奇音那可亲，年年出谷待新春。
此时断绝为君惜，明日玄蝉催发白。','',''),('quantangshi-15736','过终南柳处士','司空曙','quantangshi','','卷16','云起山苍苍，林居萝薜荒。
幽人老深境，素发与青裳。
雨涤莓苔绿，风摇松桂香。
洞泉分溜浅，岩笋出藂长。
败屦安松砌，余棊在石牀。
书名一为别，还路已堪伤。','',''),('quantangshi-15737','春送郭大之官','司空曙','quantangshi','','卷16','明府之官官舍春，春风辞我两三人。
可怜江县闲无事，手板支颐独咏贫。','',''),('quantangshi-15738','送郑锡','司空曙','quantangshi','','卷16','汉阳云树清无极，蜀国风烟思不堪。
莫怪别君偏有泪，十年曾事晋征南。','',''),('quantangshi-15739','同张参军喜李尚书寄新琴','司空曙','quantangshi','','卷16','新琴传凤凰，晴景称高张。
白玉连徽净，朱丝系爪长。
轻埃随拂拭，杂籁满铿锵。
暗想山泉合，如亲兰蕙芳。
正声消郑衞，古状掩笙簧。
远识贤人意，清风愿激扬。','',''),('quantangshi-15740','苦热','司空曙','quantangshi','','卷16','暑气发炎州，焦烟远未收。
啸风兼炽焰，挥汗讶成流。
鹳鹊投林尽，龟鱼拥石稠。
漱泉齐饮酎，衣葛剧兼裘。
长簟贪欹枕，轻巾嬾挂头。
招商如有曲，一为取新秋。','',''),('quantangshi-15741','送人归黔府','司空曙','quantangshi','','卷16','伏波箫鼓水云中，长戟如霜大斾红。
油幕晓开飞鸟绝，翩翩上将独趋风。','',''),('quantangshi-15742','杂兴','司空曙','quantangshi','','卷16','月没辽城暗出师，双龙金角晓天悲。
黄尘满目随风散，不认将军燕尾旗。','',''),('quantangshi-15743','岁暮怀崔峒耿湋','司空曙','quantangshi','','卷16','腊月江天见春色，白花青柳疑寒食。
洛阳旧社各东西，楚国游人不相识。','',''),('quantangshi-15744','观妓','司空曙','quantangshi','','卷16','翠蛾红脸不胜情，管绝弦余发一声。
银烛摇摇尘暗下，却愁红粉泪痕生。','',''),('quantangshi-15745','过长林湖西酒家','司空曙','quantangshi','','卷16','湖草青青三两家，门前桃杏一般花。
迁人到处唯求醉，闻说渔翁有酒赊。','',''),('quantangshi-15746','过阎采病居','司空曙','quantangshi','','卷16','每逢佳节何曾坐，唯有今年不得游。
张邴卧来休送客，菊花枫叶向谁秋。','',''),('quantangshi-15747','送程秀才','司空曙','quantangshi','','卷16','悠悠多路岐，相见又别离。
东风催节换，焰焰春阳散。
楚草渐烟绵，江云亦芜漫。
送子恨何穷，故关如梦中。
游人尽还北，旅雁辞南国。
枫树几回青，逐臣归不得。','',''),('quantangshi-15748','长林令衞象饧丝结歌','司空曙','quantangshi','','卷16','主人雕盘盘素丝，寒女眷眷墨子悲。
乃言假使饧为之，八珍重沓失颜色。
手援玉筯不敢持，始状芙蓉新出水。
仰坼重衣倾万蕊，又如合欢交乱枝。
红茸向暮花参差，吴蚕络茧抽尚绝。
细缕纤毫看欲灭，雪发羞垂倭堕鬟。
绣囊畏并茱萸结，我爱此丝巧。
妙绝世间无，为君作歌陈座隅。','',''),('quantangshi-15749','酬崔峒见寄','司空曙','quantangshi','','卷16','趋陪禁掖雁行随，迁放江潭鹤发垂。
素浪遥疑太液水，青枫忽似万年枝。
嵩南春遍愁魂梦，壶口云深隔路岐。
共望汉朝多沛泽，苍蝇早晚得先知。','',''),('quantangshi-15750','闻春雷','司空曙','quantangshi','','卷16','水国春雷早，阗阗若众车。
自怜迁逐者，犹滞蛰藏余。','',''),('quantangshi-15751','晚秋西省寄上李韩二舍人','司空曙','quantangshi','','卷16','昼漏传清唱，天恩禁旅秋。
雁亲承露掌，砧隔曝衣楼。
赐膳中人送，余香侍女收。
仍闻劳上直，晚步凤池头。','',''),('quantangshi-15752','下武昌江行望涔阳','司空曙','quantangshi','','卷16','悠悠次楚乡，楚口下涔阳。
雪隐洲渚暗，沙高芦荻黄。
渔人共留滞，水鸟自喧翔。
怀土年空尽，春风又淼茫。','',''),('quantangshi-15753','送史申之峡州','司空曙','quantangshi','','卷16','峡口巴江外，无风浪亦翻。
蒹葭新有雁，云雨不离猨。
行客思乡远，愁人赖酒昏。
檀郎好联句，共滞谢家门。','',''),('quantangshi-15754','送王闰','司空曙','quantangshi','','卷16','相送临寒水，苍然望故关。
江芜连梦泽，楚雪入商山。
话我他年旧，看君此日还。
因将自悲泪，一洒别离间。','',''),('quantangshi-15755','江园书事寄卢纶','司空曙','quantangshi','','卷16','种柳南江边，闭门三四年。
艳花那胜竹，凡鸟不如蝉。
嗜酒渐婴渴，读书多欲眠。
平生故交在，白首远相怜。','',''),('quantangshi-15756','送郑况往淮南','司空曙','quantangshi','','卷16','西楚见南关，苍苍落日间。
云离大雷树，潮入秣陵山。
登戍因高望，停桡放溜闲。
陈公有贤榻，君去岂空还。','',''),('quantangshi-15757','题江陵临沙驿楼','司空曙','quantangshi','','卷16','江天清更愁，风柳入江楼。
雁惜楚山晚，蝉知秦树秋。
凄凉多独醉，零落半同游。
岂复平生意，苍然兰杜洲。','',''),('quantangshi-15758','新蝉','司空曙','quantangshi','','卷16','今朝蝉忽鸣，迁客若为情。
便觉一年老，能令万感生。
微风方满树，落日稍沈城。
为问同怀者，凄凉听几声。','',''),('quantangshi-15759','送张弋','司空曙','quantangshi','','卷16','拥棹江天旷，苍然下郢城。
冰霜葭菼变，云泽鹧鸪鸣。
酒倦临流醉，人逢置榻迎。
尝闻藉东观，不独鲁诸生。','',''),('quantangshi-15760','送僧无言归山','司空曙','quantangshi','','卷16','袈裟出尘外，山径几盘缘。
人到白云树，鹤沈青草田。
龛泉朝请盥，松籁夜和禅。
自昔闻多学，逍遥注一篇。','',''),('quantangshi-15761','和卢校书文若早入使院书事','司空曙','quantangshi','','卷16','解带独裴回，秋风如水来。
轩墀湿繁露，琴几拂轻埃。
晨鸟犹在叶，夕虫余囗苔。
苍然发高兴，相仰坐难陪。','',''),('quantangshi-15762','送史泽之长沙','司空曙','quantangshi','','卷16','谢朓怀西府，单车触火云。
野蕉依戍客，庙竹暎湘君。
梦渚巴山断，长沙楚路分。
一杯从别后，风月不相闻。','',''),('quantangshi-15763','田家','司空曙','quantangshi','','卷16','田家喜雨足，邻老相招携。
泉溢沟塍坏，麦高桑柘低。
呼儿催放犊，宿客待烹鸡。
搔首蓬门下，如将轩冕齐。','',''),('quantangshi-15764','送卢堪','司空曙','quantangshi','','卷16','羁贫不易去，此日始西东。
旅舍秋霖叶，行人寒草风。
酒醒余恨在，野饯暂游同。
莫使禰生刺，空留怀袖中。','',''),('quantangshi-15765','送柳震入蜀','司空曙','quantangshi','','卷16','粉堞连青气，喧喧杂万家。
夷人祠竹节，蜀鸟乳桐花。
酒报新丰景，琴迎抵峡斜。
多闻滞游客，不似在天涯。','',''),('quantangshi-15766','送李嘉佑正字括图书兼往扬州觐省','司空曙','quantangshi','','卷16','不事兰台贵，全多韦带风。
儒官比刘向，使者得陈农。
晚烧平芜外，朝阳叠浪东。
归来喜调膳，寒笋出林中。','',''),('quantangshi-15767','送刘侍御','司空曙','quantangshi','','卷16','狱成收夜烛，整豸出登车。
黄叶辞荆楚，青山背汉初。
早朝新羽衞，晚下步徒胥。
应念长沙谪，思乡不食鱼。','',''),('quantangshi-15768','送庞判官赴黔中','司空曙','quantangshi','','卷16','天远风烟异，西南见一方。
乱山来蜀道，诸水出辰阳。
堆案青油暮，看棋画角长。
论文谁可制，记室有何郎。','',''),('quantangshi-15769','送人游岭南','司空曙','quantangshi','','卷16','万里南游客，交州见柳条。
逢迎人易合，时日酒能消。
浪晓浮青雀，风温解黑貂。
囊金如未足，莫恨故乡遥。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-15770','送曹同椅','司空曙','quantangshi','','卷16','青春三十余，众艺尽无如。
中散诗传画，将军扇续书。
楚田晴下雁，江日暖游鱼。
惆怅空相送，欢游自此疎。','',''),('quantangshi-15771','送鄂州张别驾襄阳觐省','司空曙','quantangshi','','卷16','苍苍岘亭路，腊月汉阳春。
带雪半山寺，行沙隔水人。
王祥因就宦，莱子不违亲。
正恨殊乡别，千条楚柳新。','',''),('quantangshi-15772','送魏季羔游长沙觐兄','司空曙','quantangshi','','卷16','芦荻湘江水，萧萧万里秋。
鹤高看迥野，蝉远入中流。
访友多成滞，携家不厌游。
惠连仍有作，知得从兄酬。','',''),('quantangshi-15773','杂言','司空曙','quantangshi','','卷16','伏余西景移，风雨洒轻絺。
燕拂青芜地，蝉鸣红叶枝。','',''),('quantangshi-15774','翫花与衞象同醉','司空曙','quantangshi','','卷16','衰鬓千茎雪，他乡一树花。
今朝与君醉，忘却在长沙。','',''),('quantangshi-15775','送王尊师归湖州','司空曙','quantangshi','','卷16','烟芜满洞青山遶，幢节飘空紫凤飞。
金阙乍看迎日丽，玉箫遥听隔花微。
多开石髓供调膳，时御霓裳奉易衣。
莫学辽东华表上，千年始欲一回归。','',''),('quantangshi-15776','九日洛东亭','司空曙','quantangshi','','卷16','风息斜阳尽，游人曲落间。
采花因覆酒，行草转看山。
柳散新霜下，天晴早雁还。
伤秋非骑省，玄发白成斑。','',''),('quantangshi-15777','九日送人','司空曙','quantangshi','','卷16','送人冠獬豸，值节佩茱萸。
均覆征三壤，登车出五湖。
水风凄落日，岸叶飒衰芜。
自恨尘中使，何因在路隅。','',''),('quantangshi-15778','哭王注','司空曙','quantangshi','','卷16','已叹漳滨卧，何言驻隙难。
异才伤促短，诸友哭门阑。
古道松声暮，荒阡草色寒。
延陵今葬子，空使鲁人观。','',''),('quantangshi-15779','遇谷口道士','司空曙','quantangshi','','卷16','一见林中客，闲知州县劳。
白云秋色远，苍岭夕阳高。
自说名因石，谁逢手种桃。
丹经傥相授，何用恋青袍。','',''),('quantangshi-15780','喜外弟卢纶见宿','司空曙','quantangshi','','卷16','静夜四无邻，荒居旧业贫。
雨中黄叶树，灯下白头人。
以我独沈久，愧君相见频。
平生自有分，况是蔡家亲。','',''),('quantangshi-15781','深上人见访忆李端','司空曙','quantangshi','','卷16','雁稀秋色尽，落日对寒山。
避事多称疾，留僧独闭关。
心归尘俗外，道胜有无间。
仍忆东林友，相期久不还。','',''),('quantangshi-15782','宿青龙寺故昙上人院','司空曙','quantangshi','','卷16','年深宫院在，旧客自相逢。
闭户临寒竹，无人有夜钟。
降龙今已去，巢鹤竟何从。
坐见繁星晓，凄凉识旧峯。','',''),('quantangshi-15783','送张炼师还峨嵋山','司空曙','quantangshi','','卷16','太一天坛天柱西，垂萝为幌石为梯。
前登灵境青霄绝，下视人间白日低。
松籁万声和管磐，丹光五色杂虹霓。
春山一入寻无路，鸟响烟深水满溪。','',''),('quantangshi-15784','逢江客问南中故人因以诗寄','司空曙','quantangshi','','卷16','南客何时去，相逢问故人。
望乡空泪落，嗜酒转家贫。
疎嬾辞微禄，东西任老身。
上楼多看月，临水共伤春。
五柳终期隐，双鸥自可亲。
应怜折腰吏，冉冉在风尘。','',''),('quantangshi-15785','送臯法师','司空曙','quantangshi','','卷16','江草知寒柳半衰，行吟怨别独迟迟。
何人讲席投如意，唯有东林远法师。','',''),('quantangshi-15786','送郑佶归洛阳','司空曙','quantangshi','','卷16','苍苍楚色水云间，一醉春风送尔还。
何处乡心最堪羡，汝南初见洛阳山。','',''),('quantangshi-15787','分流水','司空曙','quantangshi','','卷16','古时愁别泪，滴作分流水。
日夜东西流，分流几千里。
通塞两不见，波澜各自起。
与君相背飞，去去心如此。','',''),('quantangshi-15788','和耿拾遗元日观早朝','司空曙','quantangshi','','卷16','元日争朝阙，奔流若会溟。
路尘和薄雾，骑火接低星。
门响双鱼钥，车喧百子铃。
冕旒当翠殿，幢戟满彤庭。
积岁方编瑞，乘春即省刑。
大官陈禹玉，司历献尧蓂。
寿酒三觞退，箫韶九奏停。
太阳开物象，霈泽及生灵。
南陌高山碧，东方晓气青。
自怜扬子贱，归草太玄经。','',''),('quantangshi-15789','塞下曲','司空曙','quantangshi','','卷16','寒柳接胡桑，军门向大荒。
幕营随月魄，兵气长星芒。
横吹催春酒，重裘隔夜霜。
冰开不防虏，青草满辽阳。','',''),('quantangshi-15790','关山月','司空曙','quantangshi','','卷16','苍茫明月上，夜久光如积。
野幕冷胡霜，关楼宿边客。
陇头秋露暗，碛外寒沙白。
唯有故乡人，霑裳此闻笛。','',''),('quantangshi-15791','御制雨后出城观览敕朝臣已下属和','司空曙','quantangshi','','卷16','上上开鹑野，师师出凤城。
因知圣主念，得遂老农情。
陇麦垂秋合，郊尘得雨清。
时新荐玄祖，岁足富苍生。
却马川原静，闻鸡水土平。
薰弦歌舜德，和鼎致尧名。
览物欣多稼，垂衣御大明。
史官何所录，称瑞满天京。','',''),('quantangshi-15792','奉和常舍人晚秋集贤院即事寄徐薛二侍郎','司空曙','quantangshi','','卷16','蔼蔼凤凰宫，兰台玉署通。
夜霜凝树羽，朝日照相风。
官附三台贵，儒开百氏宗。
司言陈禹命，侍讲发尧聪。
香卷青编内，铅分绿字中。
缀签从太史，锵佩揖羣公。
池接天泉碧，林交御果红。
寒龟登故叶，秋蝶恋疎藂。
颜谢征文并，钟裴直事同。
离羣惊海鹤，属思怨江枫。
地远姑苏外，山长越绝东。
慙当哲匠后，下曲本难工。','',''),('quantangshi-15793','题鲜于秋林园','司空曙','quantangshi','','卷16','雨后园林好，幽行迥野通。
远山芳草外，流水落花中。
客醉悠悠惯，莺啼处处同。
夕阳自一望，日暮杜陵东。','',''),('quantangshi-15794','登秦岭','司空曙','quantangshi','','卷16','南登秦岭头，回首始堪忧。
汉阙青门远，商山蓝水流。
三湘迁客去，九陌故人游。
从此思乡泪，双垂不复收。','',''),('quantangshi-15795','独游寄衞长林','司空曙','quantangshi','','卷16','草绿春阳动，迟迟泽畔游。
恋花同野蝶，爱水剧江鸥。
身外唯须醉，人间尽是愁。
那知鸣玉者，不羡卖瓜侯。','',''),('quantangshi-15796','望水','司空曙','quantangshi','','卷16','高楼晴见水，楚色霭相和。
野极空如练，天遥不辨波。
永无人迹到，时有鸟行过。
况是苍茫外，残阳照最多。','',''),('quantangshi-15797','望商山路','司空曙','quantangshi','','卷16','南见青山道，依然去国时。
已甘长避地，谁料有还期。
雨霁残阳薄，人愁独望迟。
空残华发在，前事不堪思。','',''),('quantangshi-15798','题落叶','司空曙','quantangshi','','卷16','霜景催危叶，今朝半树空。
萧条故国异，零落旅人同。
飒岸浮寒水，依堦拥夜虫。
随风偏可羡，得到洛阳宫。','',''),('quantangshi-15799','寄准上人','司空曙','quantangshi','','卷16','昨闻归旧寺，暂别欲经年。
樵客应同步，邻僧定伴禅。
后峯秋有雪，远涧夜鸣泉。
偶与支公论，人间自共传。','',''),('quantangshi-15800','送况上人还荆州因寄衞侍御象','司空曙','quantangshi','','卷16','惠持游蜀久，策杖欲西还。
共别此宵月，独归何处山。
对鸥沙草畔，洗足野云间。
知有玄晖会，斋心受八关。','',''),('quantangshi-15801','别卢纶','司空曙','quantangshi','','卷16','有月多共赏，无秋不共悲。
如何与君别，又是菊黄时。','',''),('quantangshi-15802','雪二首 一','司空曙','quantangshi','','卷16','乐游春苑望鹅毛，宫殿如星树似毫。
漫漫一川横渭水，太阳初出五陵高。','',''),('quantangshi-15803','雪二首 二','司空曙','quantangshi','','卷16','王屋南崖见洛城，石龛松寺上方平。
半山槲叶当窗下，一夜曾闻雪打声。','',''),('quantangshi-15804','酬衞长林岁日见呈','司空曙','quantangshi','','卷16','地暖雪花摧，天春斗柄回。
朱泥一丸药，柏叶万年杯。
旅雁辞人去，繁霜满镜来。
今朝彩盘上，神燕不须雷。','',''),('quantangshi-15805','杜鹃行','司空曙','quantangshi','','卷16','古时杜宇称望帝，魂作杜鹃何微细。
跳枝窜叶树木中，抢翔瞥捩雌随雄。
毛衣惨黑自顦顇，众鸟安肯相尊崇。
隳形不敢栖华屋，短翮唯愿巢深丛。
穿皮啄朽觜欲秃，苦饥始得食一虫。
谁言养雏不自哺，此语亦足为愚蒙。
声音咽哕若有谓，号啼略与婴儿同。
口干垂血转迫促，似欲上诉于苍穹。
蜀人闻之皆起立，至今相效传遗风。
乃知变化不可穷，岂知昔日居深宫，嫔妃左右如花红。','',''),('quantangshi-15806','寄胡居士','司空曙','quantangshi','','卷16','日暖风微南陌头，青田红树起春愁。
伯劳相逐行人别，岐路空归野水流。
徧地寻僧同看雪，谁期载酒共登楼。
为言惆怅嵩阳寺，明月高松应独游。','',''),('quantangshi-15807','寒塘','司空曙','quantangshi','','卷16','晓发梳临水，寒塘坐见秋。
乡心正无限，一雁度南楼。','',''),('quantangshi-15808','为李魏公赋谢汧公','司空曙','quantangshi','','卷16','白雪高吟际，青霄远望中。
谁言路遐旷，宫征暗相通。','',''),('quantangshi-15809','梁城老人怨','司空曙','quantangshi','','卷16','朝为耕钟人，暮作刀枪鬼。
相看父子血，共染城壕水。','',''),('quantangshi-15810','扬州选蒙相公赏判雪后呈上','崔峒','quantangshi','','卷16','自得山公许，休畊海上田。
慙看长史传，欲弃钓鱼船。
穷巷殷忧日，芜城雨雪天。
此时瞻相府，心事比旌悬。','',''),('quantangshi-15811','客舍书情寄赵中丞','崔峒','quantangshi','','卷16','东楚复西秦，浮云类此身。
关山劳策蹇，僮仆惯投人。
孤客来千里，全家托四邻。
生涯难自料，中夜问[情亲]。','',''),('quantangshi-15812','客舍有怀因呈诸在事','崔峒','quantangshi','','卷16','读书常苦节，待诏岂辞贫。
暮雪犹驱马，晡飡又寄人。
愁来占吉梦，老去惜良辰。
延首平津阁，家山日已春。','',''),('quantangshi-15813','书怀寄杨郭李王判官','崔峒','quantangshi','','卷16','惯作云林客，因成懒漫人。
吏欺从政拙，妻笑理家贫。
李郭应时望，王杨入幕频。
从容丞相阁，知忆故园春。','',''),('quantangshi-15814','奉和给事寓直','崔峒','quantangshi','','卷16','桂枝家共折，鸡树代相传。
忝向鸾台下，仍看雁影连。
夜闲方步月，漏尽欲朝天。
知去丹墀近，明王许荐贤。','',''),('quantangshi-15815','初入集贤院赠李献仁','崔峒','quantangshi','','卷16','燕代官初罢，江湖路便分。
九迁从命薄，四十幸人闻。
迹愧趋丹禁，身曾系白云。
何由返沧海，昨日谒明君。','',''),('quantangshi-15816','酬李补阙雨中寄赠','崔峒','quantangshi','','卷16','十年随马宿，几度受人恩。
白发还乡井，微官有子孙。
竹窗寒雨滴，苦砌夜虫喧。
独愧东垣友，新诗慰旅魂。','',''),('quantangshi-15817','初除拾遗酬丘二十二见寄','崔峒','quantangshi','','卷16','江海久垂纶，朝衣忽挂身。
丹墀初谒帝，白发免羞人。
才愧文章士，名当谏诤臣。
空余荐贤分，不敢负交亲。','',''),('quantangshi-15818','刘展下判官相招以诗答之','崔峒','quantangshi','','卷16','国有非常宠，家承异姓勋。
背恩慙皎日，不义若浮云。
但使忠贞在，甘从玉石焚。
窜身如有地，梦寐见明君。','',''),('quantangshi-15819','送侯山人赴会稽','崔峒','quantangshi','','卷16','仙客辞萝月，东来就一官。
且归沧海住，犹向白云看。
猨呌江天暮，虫声野浦寒。
时游镜湖里，为我把鱼竿。','',''),('quantangshi-15820','宿禅智寺上方演大师院','崔峒','quantangshi','','卷16','石林高几许，金刹在中峰。
白日空山梵，清霜后夜钟。
竹窗回翠壁，苔径入寒松。
幸接无生法，疑心怯所从。','',''),('quantangshi-15821','题空山人石室','崔峒','quantangshi','','卷16','早晚悟无生，头陀不到城。
云山知夏腊，猨鸟见修行。
地僻无溪路，人寻逐水声。
年年深谷里，谁识远公名。','',''),('quantangshi-15822','登蒋山开善寺','崔峒','quantangshi','','卷16','山殿秋云里，香烟出翠微。
客寻朝磬至，僧背夕阳归。
下界千门见，前朝万事非。
看心兼送目，葭菼暮依依。','',''),('quantangshi-15823','题崇福寺禅院','崔峒','quantangshi','','卷16','僧家竟何事，扫地与焚香。
清磬度山翠，闲云来竹房。
身心尘外远，岁月坐中长。
向晚禅堂掩，无人空夕阳。','',''),('quantangshi-15824','秋晚送丹徒许明府赴上国因寄江南故人','崔峒','quantangshi','','卷16','秋暮之彭泽，篱花远近逢。
君书前日至，别后此时重。
寒夜江边月，晴天海上峰。
还知南地客，招引住新丰。','',''),('quantangshi-15825','送薛仲方归扬州','崔峒','quantangshi','','卷16','佳句应无敌，贞心不有猜。
慙为丈人行，怯见后生才。
泛舸贪斜月，浮桡值早梅。
绿杨新过雨，芳草待君来。','',''),('quantangshi-15826','送韦员外还京','崔峒','quantangshi','','卷16','十年离乱后，此去若为情。
春晚香山绿，人稀豫水清。
野陂看独树，关路逐残莺。
前殿朝明主，应怜白发生。','',''),('quantangshi-15827','润州送友人','崔峒','quantangshi','','卷16','见君还此地，洒泪向江边。
国士劳相问，家书无处传。
荒城胡马迹，塞木戍人烟。
一路堪愁思，孤舟何渺然。','',''),('quantangshi-15828','送张芬东归','崔峒','quantangshi','','卷16','喧喧五衢上，鞍马自驱驰。
落日临阡陌，贫交欲别离。
早知时事异，堪与世人随。
握手将何赠，君心我独知。','',''),('quantangshi-15829','送苏修游上饶','崔峒','quantangshi','','卷16','爱尔无羁束，云山恣意过。
一身随远岫，孤棹任轻波。
世事关情少，渔家寄宿多。
芦花浅淡处，江月奈人何。','',''),('quantangshi-15830','送陆明府之盱眙','崔峒','quantangshi','','卷16','陶令之官去，穷愁惨别魂。
白烟横海戍，红叶下淮村。
澹浪摇山郭，平芜到县门。
政成堪吏隐，免负府公恩。','',''),('quantangshi-15831','江南回逢赵曜因送任十一赴交城主簿','崔峒','quantangshi','','卷16','江上长相忆，因高北望看。
不知携老幼，何处度艰难。
屈指同人尽，伤心故里残。
遥怜驱匹马，白首到微官。','',''),('quantangshi-15832','送薛良史往越州谒从叔','崔峒','quantangshi','','卷16','辞家年已久，与子分偏深。
易得相思泪，难为欲别心。
孤云随浦口，几日到山阴。
遥想兰亭下，清风满竹林。','',''),('quantangshi-15833','送丘二十二之苏州','崔峒','quantangshi','','卷16','积水与寒烟，嘉禾路几千。
孤猨啼海岛，羣雁起湖田。
曾见长洲苑，尝闻大雅篇。
却将封事去，知尔爱闲眠。','',''),('quantangshi-15834','登润州芙蓉楼','崔峒','quantangshi','','卷16','上古人何在，东流水不归。
往来潮有信，朝暮事成非。
烟树临沙静，云帆入海稀。
郡楼多逸兴，良牧谢玄晖。','',''),('quantangshi-15835','江上书怀','崔峒','quantangshi','','卷16','骨肉天涯别，江山日落时。
泪流襟上血，发变镜中丝。
胡越书难到，存亡梦岂知。
登高回首罢，形影自相随。','',''),('quantangshi-15836','春日忆姚氏外甥','崔峒','quantangshi','','卷16','离乱人相失，春秋雁自飞。
祗缘行路远，未必寄书稀。
二月花无数，频年意有违。
落晖看过后，独坐泪沾衣。','',''),('quantangshi-15837','送真上人还兰若','崔峒','quantangshi','','卷16','得道云林久，年深暂一归。
出山逢世乱，乞食觉人稀。
半偈初传法，中峰又掩扉。
爱憎应不染，尘俗自依依。','',''),('quantangshi-15838','润州送师弟自江夏往台州','崔峒','quantangshi','','卷16','远客乘流去，孤帆向夜开。
春风江上使，前日汉阳来。
别路犹千里，离心重一杯。
剡溪木未落，羡尔过天台。','',''),('quantangshi-15839','送李道士归山','崔峒','quantangshi','','卷16','秋城临古路，城上望君还。
旷野入寒草，独行随远山。
授人鸿宝内，将犬白云间。
早晚烧丹罢，遥知冰雪寒。','',''),('quantangshi-15840','宿江西窦主簿厅','崔峒','quantangshi','','卷16','广庭方缓步，星汉话中移。
月满关山道，乌啼霜树枝。
时艰难会合，年长重亲知。
前事成金石，凄然泪欲垂。','',''),('quantangshi-15841','喜逢妻弟郑损因送入京','崔峒','quantangshi','','卷16','乱后自江城，相逢喜复惊。
为经多载别，欲问小时名。
对酒悲前事，论文畏后生。
遥知盈卷轴，纸贵在江城。','',''),('quantangshi-15842','咏门下画小松上元王杜三相公','崔峒','quantangshi','','卷16','昔闻生涧底，今见起毫端。
众草此时没，何人知岁寒。
岂能裨栋宇，且贵出门阑。
只在丹青意，凌云也不难。','',''),('quantangshi-15843','寄上礼部李侍郎','崔峒','quantangshi','','卷16','吴楚相逢处，江湖共泛时。
任风舟去远，待月酒行迟。
白发常同欢，青云本要期。
贵来君却少，秋至老偏悲。
玉佩明朝盛，苍苔陋巷滋。
追寻恨无路，唯有梦相思。','',''),('quantangshi-15844','书情寄上苏州韦使君兼呈吴县李明府','崔峒','quantangshi','','卷16','数年湖上谢浮名，竹杖纱巾遂性情。
云外有时逢寺宿，日西无事傍江行。
陶潜县里看花发，庾亮楼中对月明。
谁念献书来万里，君王深在九重城。','',''),('quantangshi-15845','题桐庐李明府官舍','崔峒','quantangshi','','卷16','讼堂寂寂对烟霞，五柳门前聚晓鵶。
流水声中视公事，寒山影里见人家。
观风竞美新为政，计日还知旧触邪。
可惜陶潜无限酒，不逢篱菊正开花。','',''),('quantangshi-15846','赠窦十九','崔峒','quantangshi','','卷16','灵台暮宿意多违，木落花开羡客归。
江海几时传锦字，风尘不觉化缁衣。
山阳会里同人少，灞曲农时故老稀。
幸得汉皇容直谏，怜君未遇觉人非。','',''),('quantangshi-15847','虔州见郑表新诗因以寄赠','崔峒','quantangshi','','卷16','梅花岭里见新诗，感激情深过楚词。
平子四愁今莫比，休文八咏自同时。
萍乡露冕真堪惜，凤沼鸣珂已讶迟。
才子风流定难见，湖南春草但相思。','',''),('quantangshi-15848','赠元秘书','崔峒','quantangshi','','卷16','旧书稍稍出风尘，孤客逢秋感此身。
秦地谬为门下客，淮阴徒笑市中人。
也闻阮籍寻常醉，见说陈平不久贫。
幸有故人茅屋在，更将心事问情亲。','',''),('quantangshi-15849','送韦八少府判官归东京','崔峒','quantangshi','','卷16','玄成世业紫真官，文似相如貌胜潘。
鸿雁南飞人独去，云山一别岁将阑。
清淮水急桑林晚，古驿霜多柿叶寒。
琼树相思何日见，银钩数字莫为难。','',''),('quantangshi-15850','送冯八将军奏事毕归滑台幕府','崔峒','quantangshi','','卷16','王门别后到沧洲，帝里相逢俱白头。
自欢马卿常带疾，还嗟李广不封侯。
棠梨宫里瞻龙衮，细柳营中着虎裘。
想到滑台桑叶落，黄河东注杏园秋。','',''),('quantangshi-15851','送王侍御佐婺州','崔峒','quantangshi','','卷16','闻君作尉向江潭，吴越风烟到自谙。
客路寻常经竹径，人家大底傍山岚。
缘溪花木偏宜远，避地衣冠尽向南。
惟有夜猨啼海树，思乡望北意难堪。','',''),('quantangshi-15852','越中送王使君赴江华','崔峒','quantangshi','','卷16','皂盖春风自越溪，独寻芳树桂阳西。
远水浮云随马去，空山弱筱向云低。
遥知异政荆门北，旧许新诗康乐齐。
万里相思在何处，九疑残雪白猿啼。','',''),('quantangshi-15853','送皇甫冉往白田','崔峒','quantangshi','','卷16','江边尽日雉鸣飞，君向白田何日归。
楚地蒹葭连海逈，隋朝杨柳映堤稀。
津楼故市无行客，山馆空庭闭落晖。
试问疲人与征战，使君双泪定沾衣。','',''),('quantangshi-15854','题兰若','崔峒','quantangshi','','卷16','绝顶茅庵老此生，寒云孤木独经行。
世人那得知幽迳，遥向青峰礼磬声。','',''),('quantangshi-15855','送贺兰广赴选','崔峒','quantangshi','','卷16','而今用武尔攻文，流辈干时独卧云。
白发青袍趋会府，定应衡镜却慙君。','',''),('quantangshi-15856','清江曲内一绝','崔峒','quantangshi','','卷16','八月长江去浪平，片帆一道带风轻。
极目不分天水色，南山南是岳阳城。','',''),('quantangshi-15857','武康郭外望许纬先生山居','崔峒','quantangshi','','卷16','湖上千峰带落晖，白云开处见柴扉。
松门一迳仍生草，应是仙人向郭稀。','',''),('quantangshi-15858','送司空曙之苏州','苗發','quantangshi','','卷16','盘门吴旧地，蝉尽草秋时。
归国人皆久，移家君独迟。
广陵经水宿，建邺有僧期。
若到西霞寺，应看江总碑。','',''),('quantangshi-15859','送孙德谕罢官往黔州','苗發','quantangshi','','卷16','中岁分符典石城，两朝趋陛谒承明。
阙下昨承归老疏，天南今切去乡情。
亲知握手三秋别，几杖扶身万里行。
伯道暮年无嗣子，欲将家事托门生。','',''),('quantangshi-15860','送归中丞使新罗册立吊祭','吉中孚','quantangshi','','卷16','官称汉独坐，身是鲁诸生。
绝域通王制，穷天向水程。
岛中分万象，日处转双旌。
气积鱼龙窟，涛翻水浪声。
路长经岁去，海尽向山行。
复道殊方礼，人瞻汉使荣。','',''),('quantangshi-15861','咏被中绣鞵','夏侯審','quantangshi','','卷16','云里蟾钩落凤窝，玉郎沈醉也摩挲。
陈王当日风流减，只向波间见袜罗。','',''),('quantangshi-15862','行路难','王烈','quantangshi','','卷16','行客满长路，路长良足哀。
白日持角弓，射人而取财。
千金谁家子，纷纷死黄埃。
见者不敢言，言者不得回。
家人各望归，岂知长不来。','',''),('quantangshi-15863','雪','王烈','quantangshi','','卷16','雪飞当梦蝶，风度几惊人。
半夜一窗晓，平明千树春。
花园应失路，白屋忽为邻。
散入仙厨里，还如云母尘。','',''),('quantangshi-15864','酬崔峝','王烈','quantangshi','','卷16','狥世甘长往，逢时忝一官。
欲朝青琐去，羞向白云看。
荣宠无心易，艰危抗节难。
思君写怀抱，非敢和幽兰。','',''),('quantangshi-15865','塞上曲二首 一','王烈','quantangshi','','卷16','红颜岁岁老金微，砂碛年年卧铁衣。
白草城中春不入，黄花戍上雁长飞。','',''),('quantangshi-15866','塞上曲二首 二','王烈','quantangshi','','卷16','孤城夕对戍楼闲，回合青冥万仞山。
明镜不须生白发，风沙自解老红颜。','',''),('quantangshi-15867','伤李端','衞象','quantangshi','','卷16','才子浮生促，泉台此路赊。
官卑扬执戟，年少贾长沙。
人去门栖鵩，灾成酒误虵。
唯余封禅草，留在茂陵家。','',''),('quantangshi-15868','古词','衞象','quantangshi','','卷16','鹊血雕弓湿未干，䴙鹈新淬劒光寒。
辽东老将鬓成雪，犹向旄头夜夜看。','',''),('quantangshi-15869','晴江秋望','崔季卿','quantangshi','','卷16','八月长江万里晴，千帆一道带风轻。
尽日不分天水色，洞庭南是岳阳城。','',''),('quantangshi-15870','赠兄','何兆','quantangshi','','卷16','洛阳纸价因兄贵，蜀地红牋为弟贫。
南北东西九千里，除兄与弟更无人。','',''),('quantangshi-15871','玉蘂花','何兆','quantangshi','','卷16','羽车潜下玉龟山，尘世何缘覩蕣颜。
惟有多情天上雪，好风吹上绿云鬟。','',''),('quantangshi-15872','句','何兆','quantangshi','','卷16','芙蓉十二池心漏，薝卜三千灌顶香。','',''),('quantangshi-15873','严陵滩下寄常建','奚賈','quantangshi','','卷16','日入溪水静，寻真此亦难。
乃知沧洲人，道成仍钓竿。
漾檝乘微月，振衣生早寒。
纷吾成独往，自速耽考盘。
已息汉阴诮，且同濠上观。
旷然心无涯，谁问容膝安。','',''),('quantangshi-15874','谒李尊师','奚賈','quantangshi','','卷16','万物返常性，惟道贵自然。
先生容其微，隐几为列仙。
炼魄闭琼户，养毛飞洞天。
将知逍遥久，得道无岁年。','',''),('quantangshi-15875','寻许山人亭子','奚賈','quantangshi','','卷16','桃源若远近，渔子棹轻舟。
川路行难尽，人家到渐幽。
山禽拂席起，溪水入庭流。
君是何年隐，如今成白头。','',''),('quantangshi-15876','句','奚賈','quantangshi','','卷16','眠涧花自落，步林鸟不飞。
溪谷何萧条，日入人独行。
落日下平楚，孤烟生洞庭。','',''),('quantangshi-15877','富阳南楼望浙江风起','張南史','quantangshi','','卷16','南楼渚风起，树杪见沧波。
稍觉征帆上，萧萧暮雨多。
沙洲殊未极，云水更相和。
欲问任公子，垂纶意若何。','',''),('quantangshi-15878','奉酬李舍人秋日寓直见寄','張南史','quantangshi','','卷16','秋日金华直，遥知玉佩清。
九重门更肃，五色诏初成。
槐落宫中影，鸿高苑外声。
飜从魏阙下，江海寄幽情。','',''),('quantangshi-15879','同韩侍郎秋朝使院','張南史','quantangshi','','卷16','重门启曙关，一叶报秋还。
露井桐柯湿，风庭鹤翅闲。
忘情簪白笔，假梦入青山。
惆怅祗应此，难裁语默间。','',''),('quantangshi-15880','送朱大游塞','張南史','quantangshi','','卷16','岁暮一为别，江湖聊自宽。
且无人事处，谁谓客行难。
郢曲怜公子，吴州忆伯鸾。
苍苍远山际，松柏独宜寒。','',''),('quantangshi-15881','送郑录事赴太原','張南史','quantangshi','','卷16','叹息不相见，红颜今白头。
重为西候别，方起北风愁。
六月胡天冷，双城汾水流。
卢谌即故吏，还复向并州。','',''),('quantangshi-15882','送余赞善使还赴薛尚书幕','張南史','quantangshi','','卷16','音书不可论，河塞雪纷纷。
雁足期苏武，狐裘见薛君。
城池通紫陌，鞍马入黄云。
远棹漳渠水，平流几处分。','',''),('quantangshi-15883','送李侍御入茅山采药','張南史','quantangshi','','卷16','苦县家风在，茅山道录传。
聊听骢马使，却就紫阳仙。
江海生岐路，云霞入洞天。
莫令千岁鹤，飞到草堂前。','',''),('quantangshi-15884','寄中书李舍人','張南史','quantangshi','','卷16','昨宵凄断处，对月与临风。
鹤病三江上，兰衰百草中。
题诗随谢客，饮酒寄黄翁。
早岁心相待，还因贵贱同。','',''),('quantangshi-15885','和崔中丞中秋月','張南史','quantangshi','','卷16','秋夜月偏明，西楼独有情。
千家看露湿，万里觉天清。
映水金波动，衔山桂树生。
不知飞鹊意，何用此时惊。','',''),('quantangshi-15886','西陵怀灵一上人兼寄朱放','張南史','quantangshi','','卷16','淮海风涛起，江关忧思长。
同悲鹊遶树，独坐雁随阳。
山晚云藏雪，汀寒月照霜。
由来濯缨处，渔父爱沧浪。','',''),('quantangshi-15887','寄静虚上人云门','張南史','quantangshi','','卷16','寒日白云里，法侣自提携。
竹径通城下，松门隔水西。
方同沃洲去，不自武陵迷。
仿髴心疑处，高峯是会稽。','',''),('quantangshi-15888','送司空十四北游宋州','張南史','quantangshi','','卷16','九拒危城下，萧条送尔归。
寒风吹画角，暮雪犯征衣。
道里犹成间，亲朋重与违。
白云愁欲断，看入大梁飞。','',''),('quantangshi-15889','殷卿宅夜宴','張南史','quantangshi','','卷16','日暗城乌宿，天寒枥马嘶。
词人留上客，妓女出中闺。
积雪连灯照，回廊映竹迷。
太常今夜宴，谁不醉如泥。','',''),('quantangshi-15890','宣城雪后还望郡中寄孟侍御','張南史','quantangshi','','卷16','腊后年华变，关西驿骑遥。
塞鸿连暮雪，江柳动寒条。
山水还鄣郡，图书入汉朝。
高楼非别处，故使百忧销。','',''),('quantangshi-15891','独孤常州北亭','張南史','quantangshi','','卷16','北洫敞高明，凭轩见野情。
朝回五马迹，更胜百花名。
海树凝烟远，湖田见鹤清。
云光侵素壁，水影荡闲楹。
俗赖褰帷谒，人欢倒屣迎。
始能崇结构，独有谢宣城。','',''),('quantangshi-15892','早春书事奉寄中书李舍人','張南史','quantangshi','','卷16','儒服山东士，衡门洛下居。
风尘游上路，简册委空庐。
戎马生郊日，贤人避地初。
窜身初浩荡，投迹岂踌躇。
翠羽怜穷鸟，琼枝顾散樗。
还令亲道术，倒欲混樵渔。
敝緼袍多补，飞蓬鬓少梳。
诵诗陪贾谊，酌酒伴应璩。
鹤膝兵家备，凫茨俭岁储。
泊舟依野水，开迳接园蔬。
暂阅新山泽，长怀故里闾。
思贤乘朗月，览古到荒墟。
在竹慙充箭，为兰幸免锄。
那堪闻相府，更遣诣公车。
蹇足终难进，嚬眉竟未舒。
事从因病止，生寄负恩余。
不见神仙久，无由鄙恡祛。
帝庭张礼乐，天阁绣簪裾。
日色浮青琐，香烟近玉除。
神清王子敬，气逐马相如。
铜漏时常静，金门步转徐。
唯看五字表，不记八行书。
宿昔投知己，周旋谢起予。
只应高位隔，讵是故情疎。
为报周多士，须怜楚子虚。
一身从弃置，四节苦居诸。
柳发三条陌，花飞六辅渠。
灵盘浸沆瀣，龙首映储胥。
北海樽留客，西江水救鱼。
长安同日远，不敢咏归欤。','',''),('quantangshi-15893','陆胜宅秋暮雨中探韵同作','張南史','quantangshi','','卷16','同人永日自相将，深竹闲园偶辟疆。
已被秋风教忆鲙，更闻寒雨劝飞觞。
归心莫问三江水，旅服徒沾九日霜。
醉里欲寻骑马路，萧条几处有垂杨。','',''),('quantangshi-15894','春日道中寄孟侍御','張南史','quantangshi','','卷16','春来游子傍归路，时有白云遮独行。
水流乱赴石潭响，花开不知山树名。
谁家鱼网求鲜食，几处人烟事火耕。
昨日已尝村酒熟，一杯思与孟嘉倾。','',''),('quantangshi-15895','江北春望赠皇甫补阙','張南史','quantangshi','','卷16','闲园柳绿井桃红，野径荒墟左右通。
清逈独连江水北，芳菲更似洛城东。
时看雨歇人归岫，每觉潮来树起风。
闻道金门堪避世，何须身与海鸥同。','',''),('quantangshi-15896','酬张二仓曹杨子闲居见寄兼呈韩郎中左补阙皇甫冉','張南史','quantangshi','','卷16','孤云独鹤自悠悠，别后经年尚泊舟。
渔父致词相借问，仙郎能赋许依投。
折芳远计三春草，乘兴闲看万里流。
莫怪杜门频乞假，不堪扶病拜龙楼。','',''),('quantangshi-15897','秋夜闻雁寄南十五兼呈空和尚','張南史','quantangshi','','卷16','晚节闻君道趣深，结茅栽树近东林。
禅师几度曾摩顶，高士何年更发心。
北渚三更闻过雁，西城万木动寒砧。
不见支公与玄度，相思拥膝坐长吟。','',''),('quantangshi-15898','雪','張南史','quantangshi','','卷16','雪，雪。
花片，玉屑。
结阴风，凝暮节。
高岭虚晶，平原广洁。
初从云外飘，还向空中噎。
千门万户皆静，兽炭皮裘自热。
此时双舞洛阳人，谁悟郢中歌断绝。','',''),('quantangshi-15899','月','張南史','quantangshi','','卷16','月，月。
暂盈，还缺。
上虚空，生溟渤。
散彩无际，移轮不歇。
桂殿入西秦，菱歌映南越。
正看云雾秋卷，莫待关山晓没。
天涯地角不可寻，清光永夜何超忽。','',''),('quantangshi-15900','泉','張南史','quantangshi','','卷16','泉，泉。
色净，苔鲜。
石上激，云中悬。
津流竹树，脉乱山川。
扣玉千声应，含风百道连。
太液倂归池上，云阳旧出宫边。
北陵井深凿不到，我欲添泪作潺湲。','',''),('quantangshi-15901','竹','張南史','quantangshi','','卷16','竹，竹。
披山，连谷。
出东南，殊草木。
叶细枝动，霜停露宿。
成林处处云，抽笋年年玉。
天风乍起争韵，池水相涵更绿。
却寻庾信小园中，闲对数竿心自足。','',''),('quantangshi-15902','花','張南史','quantangshi','','卷16','花，花。
深浅，芬葩。
凝为雪，错为霞。
莺和蝶到，苑占宫遮。
已迷金谷路，频驻玉人车。
芳草欲陵芳树，东家半落西家。
愿得春风相伴去，一攀一折向天涯。','',''),('quantangshi-15903','草','張南史','quantangshi','','卷16','草，草。
折宜，看好。
满地生，催人老。
金殿玉砌，荒城古道。
青青千里遥，怅怅三春早。
每逢南北离别，乍逐东西倾倒。
一身本是山中人，聊与王孙慰怀抱。','',''),('quantangshi-15904','送人','王建','quantangshi','','卷16','白日向西没，黄河复东流。
人生足着地，宁免四方游。
我行无返顾，祝子勿回头。
当须向前去，何用起离忧。
但恐无广路，平地作山丘。
令我车与马，欲疾反停留。
蜀客多积货，边人易封侯。
男儿恋家乡，欢乐为仇讐。
丁宁相劝勉，苦口幸无尤。
对面无相成，不如豺虎俦。
彼远不寄书，此寒莫寄裘。
与君俱绝迹，两念无因由。','',''),('quantangshi-15905','主人故亭','王建','quantangshi','','卷16','主人昔专城，城南起高亭。
贵与宾客游，工者夜不宁。
酒食宴圃人，栽接望早成。
经年使家僮，远道求异英。
郡中暂闲暇，遶树引诸生。
开泉浴山禽，为爱山中声。
世间事难保，一日各徂征。
死生不相及，花落实方荣。
我来至此中，守吏非本名。
重君昔为主，相与下马行。
旧岛日日摧，池水不复清。
岂无后人赏，所贵手自营。
浇酒向所思，风起如有灵。
此去不重来，重来伤我形。','',''),('quantangshi-15906','古从军','王建','quantangshi','','卷16','汉家逐单于，日没处河曲。
浮云道旁起，行子车下宿。
枪城围鼓角，毡帐依山谷。
马上悬壶浆，刀头分颊肉。
来时高堂上，父母亲结束。
回面不见家，风吹破衣服。
金疮在肢节，相与拔箭镞。
闻道西凉州，家家妇女哭。','',''),('quantangshi-15907','邯郸主人','王建','quantangshi','','卷16','远客无主人，夜投邯郸市。
飞蛾绕残烛，半夜人醉起。
垆边酒家女，遗我缃绮被。
合成双凤花，宛转不相离。
纵令颜色改，勿遣合欢异。
一念始为难，万金谁足贵。
门前长安道，去者如流水。
晨风羣鸟翔，裴回别离此。','',''),('quantangshi-15908','泛水曲','王建','quantangshi','','卷16','载酒入烟浦，方舟泛绿波。
子酌我复饮，子饮我还歌。
莲深微路通，峰曲幽气多。
阅芳无留瞬，弄桂不停柯。
水上秋日鲜，西山碧峩峩。
兹欢良可贵，谁复更来过。','',''),('quantangshi-15909','江南杂体二首 一','王建','quantangshi','','卷16','江上风翛翛，竹间湘水流。
日夜桂花落，行人去悠悠。
复见离别处，虫声阴雨秋。','',''),('quantangshi-15910','江南杂体二首 二','王建','quantangshi','','卷16','处处江草绿，行人发潇湘。
潇湘回雁多，日夜思故乡。
春梦不知数，空山兰蕙芳。','',''),('quantangshi-15911','远征归','王建','quantangshi','','卷16','万里发辽阳，处处问家乡。
回车不淹辙，雨雪满衣裳。
行见日月疾，坐思道路长。
但令不征戍，暗镜生重光。','',''),('quantangshi-15912','思远人','王建','quantangshi','','卷16','妾思常悬悬，君行复绵绵。
征途向何处，碧海与青天。
岁久自有念，谁令长在边。
少年若不归，兰室如黄泉。','',''),('quantangshi-15913','伤近者不见','王建','quantangshi','','卷16','离人隔中庭，幸不为远征。
雕梁下有壁，闻语亦闻行。
天涯尚寄信，此处不传情。
君能并照水，形影自分明。','',''),('quantangshi-15914','元日早朝','王建','quantangshi','','卷16','大国礼乐备，万邦朝元正。
东方色未动，冠劒门已盈。
帝居在蓬莱，肃肃钟漏清。
将军领羽林，持戟巡宫城。
翠华皆宿陈，雪仗罗天兵。
庭燎远煌煌，旗上日月明。
圣人龙火衣，寝殿开旋扃。
龙楼横紫烟，宫女天中行。
六蕃倍位次，衣服各异形。
举头看玉牌，不识宫殿名。
左右雉扇开，蹈舞分满庭。
朝服带金玉，珊珊相触声。
泰阶备雅乐，九奏鸾凤鸣。
裴回庆云中，竽磬寒铮铮。
三公再献寿，上帝锡永贞。
天明告四方，羣后保太平。','',''),('quantangshi-15915','闻故人自征戍回','王建','quantangshi','','卷16','昔闻着征戍，三年一还乡。
今来不换兵，须死在战场。
念子无气力，徒学事戎行。
少年得生还，有同堕穹苍。
自去报尔家，再行上高堂。
尔弟修废枥，尔母缝新裳。
恍恍恐不真，犹未苦承望。
每日空出城，畏渴携壶浆。
安得缩地经，忽使在我傍。
亦知远行劳，人悴马玄黄。
慎莫多停留，苦我居者肠。','',''),('quantangshi-15916','七泉寺上方','王建','quantangshi','','卷16','长年好名山，本性今得从。
回看尘迹遥，稍见糜鹿踪。
老僧云中居，石门青重重。
阴泉养成龟，古壁飞却龙。
扫石礼新经，悬幡上高峰。
日夕猿鸟合，觅食听山钟。
将火寻远泉，煮茶傍寒松。
晚随收药人，便宿南涧中。
晨起冲露行，湿花枝茸茸。
归依向禅师，愿作香火翁。','',''),('quantangshi-15917','从元太守夏宴西楼','王建','quantangshi','','卷16','六月晨亦热，卑居多烦昏。
五马游西城，几杖随朱轮。
西楼临方塘，嘉木当华轩。
凫鹥满中流，有酒复盈尊。
山东地无山，平视大海垠。
高风凉气来，灏景沈清源。
青衿俨坐傍，礼容益敦敦。
愿为颜氏徒，歌咏夫子门。','',''),('quantangshi-15918','酬栢侍御闻与韦处士同游灵台寺见寄','王建','quantangshi','','卷16','西域传中说，灵台属雍州。
有泉皆圣迹，有石皆佛头。
所出薝卜香，外国俗来求。
毒蛇护其下，樵者不可偷。
古碑在云巅，备载置寺由。
魏家移下来，后人始增修。
近与韦处士，爱此山之幽。
各自具所须，竹笼盛茶瓯。
牵马过危栈，襞衣涉奔流。
草开平路尽，林下大石稠。
过郭转经峰，忽见东西楼。
瀑布当寺门，逬落衣裳秋。
石苔铺紫花，溪叶裁碧油。
松根载殿高，飘颻仙山浮。
县中贤大夫，一月前此游。
赛神贺得雨，岂暇多停留。
二十韵新诗，远寄寻山俦。
清冷玉涧泣，冷切石磬愁。
君名高难闲，余身愚终休。
相将长无因，从今生离忧。','',''),('quantangshi-15919','荆南赠别李肇着作转韵诗','王建','quantangshi','','卷16','辉天复耀地，再为歌咏始。
素传学道徒，清门有君子。
文涧泻潺潺，德峰来垒垒。
两京二十年，投食公卿间。
封章既不下，故旧多慙颜。
卖马市耕牛，却归湘浦山。
麦收蚕上簇，衣食应丰足。
碧涧伴僧禅，秋山对雨宿。
且欢身体适，幸免缨组束。
上宰镇荆州，敬重同岁游。
欢逢通世友，简授画戎筹。
迟迟就公食，怆怆别野裘。
主人开宴席，礼数无形迹。
醉笑或颠吟，发谈皆损益。
临甃理芳鲜，升堂引宾客。
早岁慕嘉名，远思今始平。
孔门忝同辙，潘馆幸诸甥。
自知再婚娶，岂望为亲情。
欣欣还切切，又二千里别。
楚笔防寄书，蜀茶忧远热。
关山足重叠，会合何时节。
莫叹各从军，且愁岐路分。
美人停玉指，离瑟不中闻。
争向巴山夜，猿声满碧云。','',''),('quantangshi-15920','早发金堤驿','王建','quantangshi','','卷16','虫声四野合，月色满城白。
家家闭户眠，行人发孤驿。
离家尚苦热，衣服唯轻綌。
时节忽复迁，秋风彻经脉。
人睡落堑辙，马惊入芦荻。
慰远时问程，惊昏忽摇策。
从军岂云乐，忧患常萦积。
唯愿在贫家，团圆过朝夕。','',''),('quantangshi-15921','和裴相公道中赠别张相公','王建','quantangshi','','卷16','云间双凤鸣，一去一归城。
鞍马朝天色，封章恋阙情。
日临宫树高，烟盖沙草平。
会当戎事息，联影遶池行。','',''),('quantangshi-15922','和钱舍人水植诗','王建','quantangshi','','卷16','盆里盛野泉，晚鲜幽更好。
初活草根浮，重生荷叶小。
多时水马出，尽日蜻蜓遶。
朝早独来看，冷星沈碧晓。','',''),('quantangshi-15923','题寿安南馆','王建','quantangshi','','卷16','明蒙竹间亭，天暖幽桂碧。
云生四面山，水接当阶石。
湿树浴鸟痕，破苔卧鹿迹。
不缘尘驾触，堪作商皓宅。','',''),('quantangshi-15924','送张籍归江东','王建','quantangshi','','卷16','清泉澣尘缁，灵药释昏狂。
君诗发大雅，正气回我肠。
复令五彩姿，洁白归天常。
昔岁同讲道，青襟在师傍。
出处两相因，如彼衣与裳。
行行成此归，离我适咸阳。
失意未还家，马蹄尽四方。
访余咏新文，不倦道路长。
僮仆怀昔念，亦如还故乡。
相亲惜昼夜，寝息不异牀。
犹将在远道，忽忽起思量。
黄金未为罍，无以挹酒浆。
所念俱贫贱，安得相发扬。
回车远归省，旧宅江南厢。
归乡非得意，但贵情义彰。
五月天气热，波涛毒于汤。
慎勿多饮酒，药膳愿自强。','',''),('quantangshi-15925','励学','王建','quantangshi','','卷16','买地不肥实，其繁系耕凿。
良田少锄理，兰焦香亦薄。
勿以听者迷，故使宫征错。
谁言三岁童，还能分善恶。
孜孜日求益，犹恐业未博。
况我性顽蒙，复不勤修学。
有如朝暮食，暂亏忧陨获。
若使无六经，贤愚何所托。','',''),('quantangshi-15926','山中寄及第故人','王建','quantangshi','','卷16','长长南山松，短短北磵杨。
俱承日月照，幸免斤斧伤。
去年与子别，诚言暂还乡。
如何弃我去，天路忽腾骧。
谁谓有双目，识貌不识肠。
岂知心内乖，着我薜萝裳。
寻君向前事，不叹今异翔。
往往空室中，寤寐说圭璋。
十年居此溪，松桂日苍苍。
自从无佳人，山中不辉光。
尽弃所留药，亦焚旧草堂。
还君誓已书，归我学仙方。
既为参与辰，各愿不相望。
始终名利途，慎勿罹咎殃。','',''),('quantangshi-15927','求友','王建','quantangshi','','卷16','鉴形须明镜，疗疾须良医。
若无傍人见，形疾安自知。
世路薄言行，学成弃其师。
每怀一饭恩，不重劝勉词。
斅学既不诚，朋友道日亏。
遂作名利交，四海争奔驰。
常慕正直人，生死不相离。
苟能成我身，甘与僮仆随。
我言彼当信，彼道我无疑。
针药及病源，以石投深池。
终朝举善道，敬爱当行之。
纵令误所见，亦贵本相规。
不求立名声，所贵去瑕玼。
各愿贻子孙，永为后世资。','',''),('quantangshi-15928','寄李益少监兼送张实游幽州','王建','quantangshi','','卷16','大雅废已久，人伦失其常。
天若不生君，谁复为文纲。
迷者得道路，溺者遇舟航。
国风人已变，山泽增辉光。
星辰有其位，岂合离帝傍。
贤人既遐征，凤鸟安来翔。
少小慕高名，所念隔山冈。
集卷新纸封，每读常焚香。
古来难自达，取鉴在贤良。
未为知音故，徒恨名不彰。
谅无金石坚，性命岂能长。
常恐一世中，不上君子堂。
伟哉清河子，少年志坚强。
箧中有素文，千里求发扬。
自愿音韵乖，无因合宫商。
幸君达精诚，为我求回章。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-15929','寄崔列中丞','王建','quantangshi','','卷16','火山无冷地，浊流无清源。
人生在艰世，何处避谗言。
诸侯镇九州，天子开四门。
尚有忠义士，不得申其冤。
嘉木移远植，为我当行轩。
君子居要途，易失主人恩。
我爱古人道，师君直且温。
贪泉誓不饮，邪路誓不奔。
如何非冈坂，故使车轮翻。
妓妾随他人，家事幸获存。
当时门前客，默默空冤烦。
从今遇明代，善恶亦须论。
莫以曾见疑，直道遂不敦。','',''),('quantangshi-15930','喩时','王建','quantangshi','','卷16','去者如弊帷，来者如新衣。
鲜华非久长，色落还弃遗。
讵知行者夭，岂悟壮者衰。
区区未死间，回面相是非。
好闻苦不乐，好视忽生疵。
乃明万物情，皆逐人心移。
古今尽如此，达士将何为。','',''),('quantangshi-15931','赠王侍御','王建','quantangshi','','卷16','愚者昧邪正，贵将平道行。
君子抱仁义，不惧天地倾。
三受主人辟，方出咸阳城。
迟疑匪自崇，将显求贤名。
自来掌军书，无不尽臣诚。
何必操白刃，始致海内平。
恭事四海人，甚于敬公卿。
有恶如己辱，闻善如已荣。
或人居饥寒，进退陈中情。
彻晏听苦辛，坐卧身不宁。
以心应所求，尽家犹为轻。
衣食有亲疎，但恐逾礼经。
我今愿求益，讵敢为友生。
幸君扬素风，永作来者程。','',''),('quantangshi-15932','宋氏五女','王建','quantangshi','','卷16','五女誓终养，贞孝内自持。
兔丝自萦纡，不上青松枝。
晨昏在亲傍，闲则读书诗。
自得圣人心，不因儒者知。
少年绝音华，贵绝父母词。
素钗垂两髦，短窄古时衣。
行成闻四方，征诏环佩随。
同时入皇宫，联影步玉墀。
乡中尚其风，重为修茅茨。
圣朝有良史，将此为女师。','',''),('quantangshi-15933','送于丹移家洺州','王建','quantangshi','','卷16','忆昔门馆前，君当童子年。
今来见成长，俱过远所传。
诗礼不外学，兄弟相攻研。
如彼贩海翁，岂种溪中田。
四方尚尔文，独我敬尔贤。
但爱金玉声，不贵金玉坚。
孤遗一室中，寝食不相捐。
饱如肠胃同，疾若肤体连。
耕者求沃土，沤者求深源。
彼邦君子居，一日可徂迁。
念此居处近，各为衣食牵。
从今不见面，犹胜异山川。
既乖欢会期，郁郁两难宣。
素琴苦无徽，安得宫商全。
他皆缓别日，我愿促行轩。
送人莫长歌，长歌离恨延。
羸马不知去，过门常盘旋。
会当为尔邻，有地容一泉。','',''),('quantangshi-15934','留别舍弟','王建','quantangshi','','卷16','孤贱相长育，未曾为远游。
谁不重欢爱，晨昏阙珍羞。
出门念衣车，草木当穷秋。
非疾有忧叹，实为人子尤。
世情本难合，对面隔山丘。
况复干戈地，儒夫何所投。
与尔俱长成，尚为沟壑忧。
岂非轻岁月，少小不勤修。
从今解思量，勉力谋善猷。
但得成尔身，衣食宁我求。
固合受此训，堕慢为身羞。
岁暮当归来，慎莫怀远游。','',''),('quantangshi-15935','坏屋','王建','quantangshi','','卷16','官家有坏屋，居者愿离得。
苟或幸其迁，回循任倾侧。
若当君子住，一日还修餙。
必使换榱楹，先须木端直。
永令雀与鼠，无处求栖息。
坚固传后人，从今勉劳力。
以兹喩臣下，亦可成邦国。
虽曰愚者词，将来幸无惑。','',''),('quantangshi-15936','送薛蔓应举','王建','quantangshi','','卷16','四海重贡献，珠賮称至珍。
圣朝开礼闱，所贵集嘉宾。
若生在世间，此路出常伦。
一士登甲科，九族光彩新。
憧憧车马徒，争路长安尘。
万目视高天，升者得苦辛。
况子当少年，丈人在咸秦。
出门见宫阙，献赋侍朱轮。
有贤大国丰，无子一家贫。
男儿富邦家，岂为荣其身。
煌煌文明代，俱幸生此辰。
自顾非国风，难以合圣人。
子去东堂上，我归南涧滨。
愿君勤作书，与我山中邻。','',''),('quantangshi-15937','将归故山留别杜侍御','王建','quantangshi','','卷16','有川不得涉，有路不得行。
沈沈百忧中，一日如一生。
错来干诸侯，石田废春耕。
虎戟衞重门，何因达中诚。
日月俱照辉，山川异阴晴。
如何百里间，开目不见明。
我今归故山，誓与草木并。
愿君去丘坂，长使道路平。','',''),('quantangshi-15938','送韦处士老舅','王建','quantangshi','','卷16','忆昨痴小年，不知有经籍。
常随童子游，多向外家剧。
偷花入邻里，弄笔书墙壁。
照水学梳头，应门未穿帻。
人前赏文性，棃果蒙不惜。
赋字咏新泉，探题得幽石。
自从出关辅，三十年作客。
风雨一飘颻，亲情多阻隔。
如何二千里，尘土驱蹇瘠。
良久陈苦辛，从头叹衰白。
既来今又去，暂笑还成戚。
落日动征车，春风卷离席。
云台观西路，华岳祠前柏。
会得过帝乡，重寻旧行迹。','',''),('quantangshi-15939','送同学故人','王建','quantangshi','','卷16','各为四方人，此地同事师。
业成有先后，不得长相随。
出林多道路，缘冈复遶陂。
念君辛苦行，令我形体疲。
黄叶堕车前，四散当此时。
亭上夜萧索，山风水离离。','',''),('quantangshi-15940','幽州送申稷评事归平卢','王建','quantangshi','','卷16','行子绕天北，山高塞复深。
升堂展客礼，临水濯缨襟。
驱驰戎地马，聚散林间禽。
一杯泻东流，各愿无异心。
蓟亭虽苦寒，春夕勿重衾。
从军任白头，莫卖故山岑。','',''),('quantangshi-15941','温门山','王建','quantangshi','','卷16','早入温门山，羣峰乱如戟。
崩崖欲相触，呀豁断行迹。
脱屐寻浅流，定足畏欹石。
路尽十里溪，地多千岁栢。
洞门昼阴黑，深处惟石壁。
似见丹砂光，亦闻钟乳滴。
灵池出山底，沸水冲地脉。
暖气成湿烟，蒙蒙窗中白。
随僧入古寺，便是云外客。
月出天气凉，夜钟山寂寂。','',''),('quantangshi-15942','代故人新姬侍疾','王建','quantangshi','','卷16','双毂不回辙，子疾已在傍。
侍坐长摇扇，迎医渐下牀。
新施箱中幔，未洗来时妆。
奉君缠绵意，幸愿莫相忘。','',''),('quantangshi-15943','采桑','王建','quantangshi','','卷16','鸟鸣桑叶间，绿条复柔柔。
攀看去手近，放下长长钩。
黄花盖野田，白马少年游。
所念岂回顾，良人在高楼。','',''),('quantangshi-15944','晓思','王建','quantangshi','','卷16','晓气生绿水，春条露霏霏。
林间栖鸟散，远念征人起。
幽花宿含彩，早蝶寒弄翅。
君行非晨风，讵能从门至。','',''),('quantangshi-15945','早起','王建','quantangshi','','卷16','回灯正衣裳，出户星未稀。
堂前候姑起，环佩生晨辉。
暗池光羃䍥，密树花葳蕤。
九城钟漏绝，遥听直郎归。','',''),('quantangshi-15946','酬张十八病中寄诗','王建','quantangshi','','卷16','本性慵远行，绵绵病自生。
见君绸缪思，慰我寂寞情。
风幌夜不掩，秋灯照雨明。
彼愁此又忆，一夕两盈盈。','',''),('quantangshi-15947','凉州行','王建','quantangshi','','卷16','凉州四边沙皓皓，汉家无人开旧道。
边头州县尽胡兵，将军别筑防秋城。
万里人家皆已没，年年旌节发西京。
多来中国收妇女，一半生男为汉语。
蕃人旧日不耕犂，相学如今种禾黍。
驱羊亦着锦为衣，为惜毡裘防鬬时。
养蚕缫茧成匹帛，那堪绕帐作旌旗。
城头山鸡鸣角角，洛阳家家学胡乐。','',''),('quantangshi-15948','寒食行','王建','quantangshi','','卷16','寒食家家出古城，老人看屋少年行。
丘壠年年无旧道，车徒散行入衰草。
牧儿驱牛下冢头，畏有家人来洒扫。
远人无坟水头祭，还引妇姑望乡拜。
三日无火烧纸钱，纸钱那得到黄泉。
但看壠上无新土，此中白骨应无主。','',''),('quantangshi-15949','促剌词','王建','quantangshi','','卷16','促剌复促剌，水中无鱼山无石。
少年虽嫁不得归，头白犹着父母衣。
田边旧宅非所有，我身不及逐鸡飞。
出门若有归死处，猛虎当衢向前去。
百年不遗踏君门，在家谁唤为新妇。
岂不见他邻舍娘，嫁来常在舅姑傍。','',''),('quantangshi-15950','壠头水','王建','quantangshi','','卷16','壠水何年壠头别，不在山中亦呜咽。
征人塞耳马不行，未到壠头闻水声。
谓是西流入蒲海，还闻北去绕龙城。
壠东壠西多屈曲，野麋饮水长簇簇。
胡兵夜回水旁住，忆着来时磨劒处。
向前无井复无泉，放马回看壠头树。','',''),('quantangshi-15951','北邙行','王建','quantangshi','','卷16','北邙山头少闲士，尽是洛阳人旧墓。
旧墓人家归葬多，堆着黄金无买处。
天涯悠悠葬日促，冈坂崎岖不停毂。
高张素幕绕铭旌，夜唱挽歌山下宿。
洛阳城北复城东，魂车祖马长相逢。
车辙广若长安路，蒿草少于松柏树。
涧底盘陀石渐稀，尽向坟向作羊虎。
谁家石碑文字灭，后人重取书年月。
朝朝车马送葬回，还起大宅与高台。','',''),('quantangshi-15952','温泉宫行','王建','quantangshi','','卷16','十月一日天子来，青绳御路无尘埃。
宫前内里汤各别，每个白玉芙蓉开。
朝元阁向山上起，城绕青山龙暖水。
夜开金殿看星河，宫女知更月明里。
武皇得仙王母去，山鸡昼鸣宫中树。
温泉决决出宫流，宫使年年修玉楼。
禁兵去尽无射猎，日西麋鹿登城头。
棃园弟子偷曲谱，头白人间教歌舞。','',''),('quantangshi-15953','春词','王建','quantangshi','','卷16','红烟满户日照梁，天丝软弱虫飞扬。
菱花霍霍绕帷光，美人对镜着衣裳。
庭中并种相思树，夜夜还栖双凤凰。','',''),('quantangshi-15954','辽东行','王建','quantangshi','','卷16','辽东万里辽水曲，古戍无城复无屋。
黄云盖地雪作山，不惜黄金买衣服。
战回各自收弓箭，正西回面家乡远。
年年郡县送征人，将与辽东作丘坂。
宁为草木乡中生，有身不向辽东行。','',''),('quantangshi-15955','塞上梅','王建','quantangshi','','卷16','天山路傍一株梅，年年花发黄云下。
昭君已殁汉使回，前后征人惟系马。
日夜风吹满陇头，还随陇水东西流。
此花若近长安路，九衢年少无攀处。','',''),('quantangshi-15956','戴胜词','王建','quantangshi','','卷16','戴胜谁与尔为名，木中作窠墙上鸣。
声声催我急种毂，人家向田不归宿。
紫冠采采褐羽斑，衔得蜻蜓飞过屋。
可怜白鹭满绿池，不如戴胜知天时。','',''),('quantangshi-15957','秋千词','王建','quantangshi','','卷16','长长丝绳紫复碧，袅袅横枝高百尺。
少年儿女重秋千，盘巾结带分两边。
身轻裙薄易生力，双手向空如鸟翼。
下来立定重系衣，复畏斜风高不得。
傍人送上那足贵，终赌鸣璫鬬自起。
回回若与高树齐，头上宝钗从堕地。
眼前争胜难为休，足踏平地看始愁。','',''),('quantangshi-15958','开池得古钗','王建','quantangshi','','卷16','美人开池北堂下，拾得宝钗金未化。
凤凰半在双股齐，钿花落处生黄泥。
当时堕地觅不得，暗想窗中还夜啼。
可知将来对夫壻，镜前学梳古时髻。
莫言至死亦不遗，还似前人初得时。','',''),('quantangshi-15959','赛神曲','王建','quantangshi','','卷16','男抱琵琶女作舞，主人再拜听神语。
新妇上酒勿辞勤，使尔舅姑无所苦。
椒浆湛湛桂座新，一双长箭系红巾。
但愿牛羊满家宅，十月报赛南山神。
青天无风水复碧，龙马上鞍牛服轭。
纷纷醉舞踏衣裳，把酒路旁劝行客。','',''),('quantangshi-15960','田家留客','王建','quantangshi','','卷16','人家少能留我屋，客有新浆马有粟。
远行僮仆应苦饥，新妇厨中炊欲熟。
不嫌田家破门户，蚕房新泥无风土。
行人但饮莫畏贫，明府上来何苦辛。
丁宁回语屋中妻，有客勿令儿夜啼。
双冢直西有县路，我教丁男送君去。','',''),('quantangshi-15961','精衞词','王建','quantangshi','','卷16','精衞谁教尔填海，海边石子青磊磊。
但得海水作枯池，海中鱼龙何所为。
口穿岂为空衔石，山中草木无全枝。
朝在树头暮海里，飞多羽折时堕水。
高山未尽海未平，愿我身死子还生。','',''),('quantangshi-15962','老妇叹镜','王建','quantangshi','','卷16','嫁时明镜老犹在，黄金镂画双凤背。
忆昔咸阳初买来，灯前自绣芙蓉带。
十年不开一片铁，长向暗中梳白发。
今日后牀重照看，生死终当此长别。','',''),('quantangshi-15963','望夫石','王建','quantangshi','','卷16','望夫处，江悠悠，化为石，不回头。
上头日日风复雨，行人归来石应语。','',''),('quantangshi-15964','别鹤曲','王建','quantangshi','','卷16','主人一去池水绝，池鹤散飞不相别。
青天漫漫碧水重，知向何山风雪中。
万里虽然音影在，两心终是死生同。
池边巢破松树死，树头年年乌生子。','',''),('quantangshi-15965','乌栖曲','王建','quantangshi','','卷16','章华宫人夜上楼，君王望月西山头。
夜深宫殿门不锁，白露满山山叶堕。','',''),('quantangshi-15966','雉将雏','王建','quantangshi','','卷16','雉咿喔，雏出㲉，毛斑斑，觜啄啄。
学飞未得一尺高，还逐母行旋母脚。
麦垄浅浅难蔽身，远去恋雏低怕人。
时时土中鼓两翅，引雏拾虫不相离。','',''),('quantangshi-15967','白紵歌二首 一','王建','quantangshi','','卷16','天河漫漫北斗璨，宫中乌啼知夜半。
新缝白紵舞衣成，来迟邀得吴王迎。
低鬟转面掩双袖，玉钗浮动秋风生。
酒多夜长夜未晓，月明灯光两相照，后庭歌声更窈窕。','',''),('quantangshi-15968','白紵歌二首 二','王建','quantangshi','','卷16','馆娃宫中春日暮，荔枝木瓜花满树。
城头乌栖休击鼓，青蛾弹瑟白紵舞。
夜天曈曈不见星，宫中火照西江明。
美人醉起无次第，堕钗遗佩满中庭。
此时但愿可君意，回昼为宵亦不寐，年年奉君君莫弃。','',''),('quantangshi-15969','短歌行','王建','quantangshi','','卷16','人初生，日初出，上山迟，下山疾。
百年三万六千朝，夜里分将强半日。
有歌有舞须早为，昨日健于今日时。
人家见生男女好，不知男女催人老。
短歌行，无乐声。','',''),('quantangshi-15970','饮马长城窟','王建','quantangshi','','卷16','长城窟，长城窟边多马骨。
古来此地无井泉，赖得秦家筑城卒。
征人饮马愁不回，长城变作望乡堆。
蹄踪未干人去近，续后马来泥污尽。
枕弓睡着待水生，不见阴山在前阵。
马蹄足脱装马头，健儿战死谁封侯。','',''),('quantangshi-15971','乌夜啼','王建','quantangshi','','卷16','庭树乌，尔何不向别处栖？
夜夜夜半当户啼。
家人把烛出洞户，惊栖失羣飞落树。
一飞直欲飞上天，回回不离旧栖处。
未明重绕主人屋，欲下空中黑相触。
风飘雨湿亦不移，君家树头多好枝。','',''),('quantangshi-15972','簇蚕辞','王建','quantangshi','','卷16','蚕欲老，箔头作茧丝皓皓。
场宽地高风日多，不向中庭晒蒿草。
神蚕急作莫悠扬，年来为尔祭神桑。
但得青天不下雨，上无苍蝇下无鼠。
新妇拜簇愿茧稠，女洒桃浆男打鼓。
三日开箔雪团团，先将新茧送县官。
已闻乡里催织作，去与谁人身上着。','',''),('quantangshi-15973','渡辽水','王建','quantangshi','','卷16','渡辽水，此去咸阳五千里。
来时父母知隔生，重着衣裳如送死。
亦有白骨归咸阳，营家各与题本乡。
身在应无回渡日，驻马相看辽水傍。','',''),('quantangshi-15974','空城雀','王建','quantangshi','','卷16','空城雀，何不飞来人家住？
空城无人种禾黍，土间生子草间长。
满地蓬蒿幸无主，近村虽有高树枝。
雨中无食长苦饥，八月小儿挟弓箭。
家家畏向田头飞，但能不出空城里。
秋时百草皆有子，报言黄口莫啾啾，长尔得成无横死。','',''),('quantangshi-15975','水运行','王建','quantangshi','','卷16','西江运船立红帜，万棹千帆绕江水。
去年六月无稻苗，已说水乡人饿死。
县官部船日算程，暴风恶雨亦不停。
在生有乐当有苦，三年作官一年行。
坏舟畏鼠复畏漏，恐向太仓折升斗。
辛勤耕种非毒药，看着不入农夫口。
用尽百金不为贵，但得一金即为利。
远征海稻供边食，岂如多种边头地。','',''),('quantangshi-15976','当窗织','王建','quantangshi','','卷16','叹息复叹息，园中有枣行人食。
贫家女为富家织，翁母隔墙不得力。
水寒手澁丝脆断，续来续去心肠烂。
草虫促促机下啼，两日催成一匹半。
输官上顶有零落，姑未得衣身不着。
当窗却羡青楼倡，十指不动衣盈箱。','',''),('quantangshi-15977','失钗怨','王建','quantangshi','','卷16','贫女铜钗惜于玉，失却来寻一日哭。
嫁时女伴与作妆，头戴此钗如凤凰。
双杯行酒六亲喜，我家新妇宜拜堂。
镜中乍无失髻样，初起犹疑在牀上。
高楼翠钿飘舞尘，明日从头一遍新。','',''),('quantangshi-15978','春燕词','王建','quantangshi','','卷16','新燕新燕何不定，东家绿池西家井。
飞鸣当户影悠扬，一遶檐头一遶梁。
黄姑说向新妇女，去年堕子污衣箱。
已能辞山复过海，幸我堂前故巢在。
求食慎勿爱高飞，空中饥鸢为尔害。
辛勤作窠在画梁，愿得年年主人富。','',''),('quantangshi-15979','主人故池','王建','quantangshi','','卷16','高池高阁上连起，荷叶团团盖秋水。
主人已远凉风生，旧客不来芙蓉死。','',''),('quantangshi-15980','古宫怨','王建','quantangshi','','卷16','乳乌哑哑飞复啼，城头晨夕宫中栖。
吴王别殿绕江水，后宫不开美人死。','',''),('quantangshi-15981','关山月','王建','quantangshi','','卷16','关山月，营开道白前军发。
冻轮当碛光悠悠，照见三堆两堆骨。
边风割面天欲明，金沙岭西看看没。','',''),('quantangshi-15982','赠离曲','王建','quantangshi','','卷16','合欢叶堕梧桐秋，鸳鸯背飞水分流。
少年使我忽相弃，雌号雄鸣夜悠悠。
夜长月没虫切切，冷风入房灯焰灭。
若知中路各西东，彼此不忘同心结。
收取头边蛟龙枕，留着箱中双雉裳。
我今焚却旧房物，免使他人登尔牀。','',''),('quantangshi-15983','宛转词','王建','quantangshi','','卷16','宛宛转转胜上纱，红红绿绿苑中花。
纷纷泊泊夜飞鵶，寂寂寞寞离人家。','',''),('quantangshi-15984','水夫谣','王建','quantangshi','','卷16','苦哉生长当驿边，官家使我牵驿船。
辛苦日多乐日少，水宿沙行如海鸟。
逆风上水万斛重，前驿迢迢后淼淼。
半夜缘堤雪和雨，受他驱遣还复去。
衣寒衣湿披短蓑，臆穿足裂忍痛何。
到明辛苦无处说，齐声腾踏牵船出。
一间茆屋何所值，父母之乡去不得。
我愿此水作平田，长使水夫不怨天。','',''),('quantangshi-15985','田家行','王建','quantangshi','','卷16','男声欣欣女颜悦，人家不怨言语别。
五月虽热麦风清，檐头索索缲车鸣。
野蚕作茧人不取，叶间扑扑秋蛾生。
麦收上场绢在轴，的知输得官家足。
不望入口复上身，且免向城卖黄犊。
回家衣食无厚薄，不见县门身即乐。','',''),('quantangshi-15986','去妇','王建','quantangshi','','卷16','新妇去年腁手足，衣不暇缝蚕废簇。
白头使我忧家事，还如夜里烧残烛。
当初为取傍人语，岂道如今自辛苦。
在时纵嫌织绢迟，有丝不上邻家机。','',''),('quantangshi-15987','神树词','王建','quantangshi','','卷16','我家家西老棠树，须晴即晴雨即雨。
四时八节上杯盘，愿神莫离神处所。
男不着丁女在舍，官事上下无言语。
老身长健树婆娑，万岁千年作神主。','',''),('quantangshi-15988','祝鹊','王建','quantangshi','','卷16','神鹊神鹊好言语，行人早回多利赂。
我今庭中栽好树，与汝作巢当报汝。','',''),('quantangshi-15989','古谣','王建','quantangshi','','卷16','一东一西壠头水，一聚一散天边霞。
一来一去道上客，一颠一倒池中麻。','',''),('quantangshi-15990','公无渡河','王建','quantangshi','','卷16','渡头恶天两岸远，波涛塞川如叠坂。
幸无白刃驱向前，何用将身自弃捐。
蛟龙啮骨鱼食血，黄泥直下无青天。
男儿纵轻妇人语，惜君性命还须取。
妇人无力挽断衣，舟沈身死悔难追。
公无渡河，公须自为。','',''),('quantangshi-15991','海人谣','王建','quantangshi','','卷16','海人无家海里住，采珠役象为岁赋。
恶波横天山塞路，未央宫中常满库。','',''),('quantangshi-15992','行见月','王建','quantangshi','','卷16','月初生，居人见月一月行。
行行一年十二月，强半马上看盈缺。
百年欢乐能几何，在家见少行见多。
不缘衣食相驱遣，此身谁愿长奔波。
箧中有帛仓有粟，岂向天涯走碌碌。
家人见月望我归，正是道上思家时。','',''),('quantangshi-15993','七夕曲','王建','quantangshi','','卷16','河边独自看星宿，夜织天丝难接续。
抛梭振镊动明璫，为有秋期眠不足。
遥愁今夜河水隔，龙驾车辕鹊填石。
流苏翠帐星渚间，环佩无声灯寂寂。
两情缠绵忽如故，复畏秋风生晓路。
幸回郎意且斯须，一年中别今始初，明星未出少停车。','',''),('quantangshi-15994','两头纤纤','王建','quantangshi','','卷16','两头纤纤青玉玦，半白半黑头上发。
逼逼仆仆春冰裂，磊磊落落桃花结。','',''),('quantangshi-15995','独漉歌','王建','quantangshi','','卷16','独独漉漉，鼠食猫肉。
乌日中，鹤露宿，黄河水直人心曲。','',''),('quantangshi-15996','寄远曲','王建','quantangshi','','卷16','美人别来无处所，巫山月明湘江雨。
千回相见不分明，井底看星梦中语。
两心相对尚难知，何况万里不相疑。','',''),('quantangshi-15997','伤韦令孔雀词','王建','quantangshi','','卷16','可怜孔雀初得时，美人为尔别开池。
池边凤凰作伴侣，羌声鹦鹉无言语。
雕笼玉架嫌不栖，夜夜思归向南舞。
如今憔悴人见恶，万里更求新孔雀。
热眠雨水饥拾虫，翠尾盘泥金彩落。
多时人养不解飞，海山风黑何处归。','',''),('quantangshi-15998','伤邻家鹦鹉词','王建','quantangshi','','卷16','东家小女不惜钱，买得鹦鹉独自怜。
自从死却家中女，无人更共鹦鹉语。
十日不饮一滴浆，泪渍绿毛头似鼠。
舌关哑咽畜哀怨，开笼放飞离人眼。
短声亦绝翠臆翻，新墓崔嵬旧巢远。
此禽有志女有灵，定为连理相并生。','',''),('quantangshi-15999','春来曲','王建','quantangshi','','卷16','春欲来，每日望春门早开。
黄衫白马带尘土，逢着探春人却回。
御堤内园晓过急，九衢大宅家家入。
青帝少女染桃花，露妆初出红犹湿。
光风暾暾蝶宛宛，遶树气匝枝柯软。
可怜寒食街中郎，早起着得单衣裳。
少年即见春好处，似我白头无好树。','',''),('quantangshi-16000','春去曲','王建','quantangshi','','卷16','春已去，花亦不知春去处。
缘冈绕涧却归来，百回看着无花树。
就中一夜东风恶，收红拾紫无遗落。
老夫不比少年儿，不中数与春别离。','',''),('quantangshi-16001','东征行','王建','quantangshi','','卷16','桐栢水西贼星落，枭雏夜飞林木恶。
相国刻日波涛清，当朝自请东南征。
舍人为宾侍郎副，晓觉蓬莱欠佩声。
玉阶舞蹈谢旌节，生死向前山可穴。
同时赐马并赐衣，御楼看带弓刀发。
马前猛士三百人，金书左右红旗新。
司庖常膳皆得对，好事将军封尔身。
男儿生杀在手里，营门老将皆忧死。
曈曈白日当南山，不立功名终不还。','',''),('quantangshi-16002','荆门行','王建','quantangshi','','卷16','江边行人暮悠悠，山头殊未见荆州。
岘亭西南路多曲，栎林深深石镞镞。
看炊红米煮白鱼，夜向鸡鸣店家宿。
南中三月蚊蚋生，黄昏不闻人语声。
生纱帷疎薄如雾，隔衣噆肤耳边鸣。
欲明不待灯火起，唤得官船过蛮水。
女儿停客茆屋新，开门扫地桐花里。
犬声扑扑寒溪烟，人家烧竹种山田。
巴云欲雨薰石热，麋鹿度江虫出穴。
大蛇过处一山腥，野牛惊跳双角折。
斜分汉水横千山，山青水绿荆门关。
向前问个长沙路，旧是屈原沈溺处。
谁家丹旐已南来，逢着流人从此去。
月明山鸟多不栖，下枝飞上高枝啼。
主人念远心不怿，罗衫卧对章台夕。
红烛交横各自归，酒醒还是他乡客。
壮年留滞尚思家，况复白头在天涯。','',''),('quantangshi-16003','镜听词','王建','quantangshi','','卷16','重重摩挲嫁时镜，夫壻远行凭镜听。
回身不遣别人知，人意丁宁镜神圣。
怀中收拾双锦带，恐畏街头见惊怪。
嗟嗟际际下堂阶，独自竈前来跪拜。
出门愿不闻悲哀，郎在任郎回未回。
月明地上人过尽，好语多同皆道来。
卷帷上牀喜不定，与郎裁衣失翻正。
可中三日得相见，重绣锦囊磨镜面。','',''),('quantangshi-16004','行宫词','王建','quantangshi','','卷16','上阳宫到蓬莱殿，行宫岩岩遥相见。
向前天子行幸多，马蹄车辙山川遍。
当时州县每年修，皆留内人看玉案。
禁兵夺得明堂后，长闭桃源与绮绣。
开元歌舞古草头，梁州乐人世嫌旧。
官家乏人作宫户，不泥宫墙斫宫树。
两边仗屋半崩摧，夜火入林烧殿柱。
休封中岳六十年，行宫不见人眼穿。','',''),('quantangshi-16005','羽林行','王建','quantangshi','','卷16','长安恶少出名字，楼下劫商楼上醉。
天明下直明光宫，散入五陵松柏中。
百回杀人身合死，赦书尚有收城功。
九衢一日消息定，乡吏籍中重改姓。
出来依旧属羽林，立在殿前射飞禽。','',''),('quantangshi-16006','射虎行','王建','quantangshi','','卷16','自去射虎得虎归，官差射虎得虎迟。
独行以死当虎命，两人因疑终不定。
朝朝暮暮空手回，山下绿苗成道径。
远立不敢污箭镞，闻死还来分虎肉。
惜留猛虎着深山，射杀恐畏终身闲。','',''),('quantangshi-16007','远将归','王建','quantangshi','','卷16','远将归，胜未别离时。
在家相见热，新归欢不足。
去愿车轮迟，回思马蹄速。
但令在舍相对贫，不向天涯金遶身。','',''),('quantangshi-16008','寻幢歌','王建','quantangshi','','卷16','人间百戏皆可学，寻幢不比诸余乐。
重梳短髻下金钿，红帽青巾各一边。
身轻足捷胜男子，绕竿四面争先缘。
习多依附攲竿滑，上下蹁跹皆着袜。
翻身垂颈欲落地，却住把腰初似歇。
大竿百夫擎不起，褭褭半在青云里。
纤腰女儿不动容，戴行直舞一曲终。
回头但觉人眼见，矜难恐畏天无风。
险中更险何曾失，山鼠悬头猿挂膝。
小垂一手当舞盘，斜惨双蛾看落日。
斯须改变曲解新，贵欲欢他平地人。
散时满面生颜色，行步依前无气力。','',''),('quantangshi-16009','铜雀台','王建','quantangshi','','卷17','娇爱更何日，高台空数层。
含啼暎双袖，不忍看西陵。
漳水东流无复来，百花辇路为苍苔。
青楼月夜长寂寞，碧云日莫空裴回。
君不见邺中万事非昔时，古人不在今人悲。
春风不逐君王去，草色年年旧宫路。
宫中歌舞已浮云，空指行日往来处。','',''),('quantangshi-16010','鸡鸣曲','王建','quantangshi','','卷17','鸡初鸣，明星照东屋。
鸡再鸣，红霞生海腹。
百官待漏双阙前，圣人亦挂山龙服。
宝钗命妇灯下起，环佩玲珑晓光里。
直内初烧玉案香，司更尚滴铜壶水。
金吾衞里直郎妻，到明不睡听晨鸡。
天头日月相送迎，夜栖旦鸣人不迷。','',''),('quantangshi-16011','送衣曲','王建','quantangshi','','卷17','去秋送衣渡黄河，今秋送衣上陇坂。
妇人不知道径处，但问新移军近远。
半年着道经雨湿，开笼见风衣领急。
旧来十月初点衣，与郎着向营中集。
絮时厚厚绵纂纂，贵欲征人身上暖。
愿身莫着裹尸归，愿妾不死长送衣。','',''),('quantangshi-16012','斜路行','王建','quantangshi','','卷17','世间娶容非娶妇，中庭牡丹胜松树。
九衢大道人不行，走马奔车逐斜路。
斜路行熟直路荒，东西岂是横太行。
南楼弹弦北户舞，行人到此多回徨。
头白如丝面如茧，亦学少年行不返。
纵令自解思故乡，轮折蹄穿白日晚。
谁将古曲换斜音，回取行人斜路心。','',''),('quantangshi-16013','织锦曲','王建','quantangshi','','卷17','大女身为织锦户，名在县家供进簿。
长头起样呈作官，闻道官家中苦难。
回花侧叶与人别，唯恐秋天丝线干。
红缕葳蕤紫茸软，蝶飞参差花宛转。
一梭声尽重一梭，玉腕不停罗袖卷。
窗中夜久睡髻偏，横钗欲堕垂着肩。
合衣卧时参没后，停灯起在鸡鸣前。
一匹千金亦不卖，限日未成宫里怪。
锦江水涸贡转多，宫中尽着单丝罗。
莫言山积无尽日，百丈高楼一曲歌。','',''),('quantangshi-16014','捣衣曲','王建','quantangshi','','卷17','月明中庭捣衣石，掩帷下堂来捣帛。
妇姑相对神力生，双揎白腕调杵声。
高楼敲玉节会成，家家不睡皆起听。
秋天丁丁复冻冻，玉钗低昂衣带动。
夜深月落冷如刀，湿着一双纤手痛。
回编易裂看生熟，鸳鸯纹成水波曲。
重烧熨斗帖两头，与郎裁作迎寒裘。','',''),('quantangshi-16015','秋夜曲二首 一','王建','quantangshi','','卷17','天清漏长霜泊泊，兰绿收荣桂膏涸。
高楼云鬟弄婵娟，古瑟暗断秋风弦。
玉关遥隔万里道，金刀不翦双泪泉。
香囊火死香气少，向帷合眼何时晓。
城乌作营啼野月，秦州少妇生离别。','',''),('quantangshi-16016','秋夜曲二首 二','王建','quantangshi','','卷17','秋灯向壁掩洞房，良人此夜直明光。
天河悠悠漏水长，南楼北斗两相当。','',''),('quantangshi-16017','题台州隐静寺','王建','quantangshi','','卷17','隐静灵仙寺天凿，杯度飞来建岩壑。
五峰直上插银河，一涧当空泻寥廓。
崆峒黯淡碧琉璃，白云吞吐红莲阁。
不知势压天几重，钟声常闻月中落。','',''),('quantangshi-16018','送人游塞','王建','quantangshi','','卷17','初晴天堕丝，晚色上春枝。
城下路分处，边头人去时。
停车数行日，劝酒问回期。
亦是茫茫客，还从此别离。','',''),('quantangshi-16019','塞上逢故人','王建','quantangshi','','卷17','百战一身在，相逢白发生。
何时得乡信，每日算归程。
走马登寒壠，驱羊入废城。
羌笳三两曲，人醉海西营。','',''),('quantangshi-16020','南中','王建','quantangshi','','卷17','天南多鸟声，州县半无城。
野市依蛮姓，山邨逐水名。
瘴烟沙上起，阴火雨中生。
独有求珠客，年年入海行。','',''),('quantangshi-16021','汴路水驿','王建','quantangshi','','卷17','晚泊水边驿，柳塘初起风。
蛙鸣蒲叶下，鱼入稻花中。
去舍已云远，问程犹向东。
近来多怨别，不与少年同。','',''),('quantangshi-16022','淮南使廻留别窦侍御','王建','quantangshi','','卷17','恋恋春恨结，绵绵淮草深。
病身愁至夜，远道畏逢阴。
忽逐酒杯会，暂同风景心。
从今一分散，还是晓枝禽。','',''),('quantangshi-16023','汴路即事','王建','quantangshi','','卷17','千里河烟直，青槐夹岸长。
天涯同此路，人语各殊方。
草市迎江货，津桥税海商。
廻看故宫柳，憔悴不成行。','',''),('quantangshi-16024','山居','王建','quantangshi','','卷17','屋在瀑泉西，茅檐下有溪。
闭门留野鹿，分食养山鸡。
桂熟长收子，兰生不作畦。
初开洞中路，深处转松梯。','',''),('quantangshi-16025','醉后忆山中故人','王建','quantangshi','','卷17','花开草复秋，云水自悠悠。
因醉暂无事，在山难免愁。
遇晴须看月，鬬健且登楼。
暗想山中伴，如今尽白头。','',''),('quantangshi-16026','送流人','王建','quantangshi','','卷17','见说长沙去，无亲亦共愁。
阴云鬼门夜，寒雨瘴江秋。
水国山魈引，蛮乡洞主留。
渐看归处远，垂白住炎州。','',''),('quantangshi-16027','贫居','王建','quantangshi','','卷17','眼底贫家计，多时总莫嫌。
蠹生腾药纸，字暗换书签。
避雨拾黄叶，遮风下黑帘。
近来身不健，时就六壬占。','',''),('quantangshi-16028','过赵居士拟置草堂处所','王建','quantangshi','','卷17','休师竹林北，空可两三间。
虽爱独居好，终来相伴闲。
犹嫌近前树，为碍看南山。
的有深耕处，春初须早还。','',''),('quantangshi-16029','新开望山处','王建','quantangshi','','卷17','新开望山处，今朝减病眠。
应移千里道，犹自数峰偏。
故欲遮春巷，还来遶暮天。
老夫行步弱，免到寺门前。','',''),('quantangshi-16030','题东华观','王建','quantangshi','','卷17','路尽烟水外，院门题上清。
鹤雏灵解语，琼叶软无声。
白发道心熟，黄衣仙骨轻。','',''),('quantangshi-16031','饭僧','王建','quantangshi','','卷17','别屋炊香饭，薰辛不入家。
温泉调葛面，净手摘藤花。
蒲鲊除青叶，芹虀带紫芽。
愿师常伴食，消气有姜茶。','',''),('quantangshi-16032','照镜','王建','quantangshi','','卷17','忽自见憔悴，壮年人亦疑。
发缘多病落，力为不行衰。
暖手揉双目，看图引四肢。
老来真爱道，所恨觉还迟。','',''),('quantangshi-16033','归昭应留别城中','王建','quantangshi','','卷17','喜得近京城，官卑意亦荣。
竝牀欢未定，离室思还生。
计拙偷闲住，经过买日行。
如无自来分，一驿是遥程。','',''),('quantangshi-16034','答寄芙蓉冠子','王建','quantangshi','','卷17','一学芙蓉叶，初开映水幽。
虽经小儿手，不称老夫头。
枕上眠常戴，风前醉恐柔。
明年有闺阁，此样必难求。','',''),('quantangshi-16035','长安春游','王建','quantangshi','','卷17','骑马傍闲坊，新衣着雨香。
桃花红粉醉，柳树白云狂。
不觉愁春去，何曾得日长。
牡丹相次发，城里又须忙。','',''),('quantangshi-16036','冬夜感怀','王建','quantangshi','','卷17','晚年恩爱少，耳目静于僧。
竟夜不闻语，空房唯有灯。
气嘘寒被湿，霜入破窗凝。
断得人间事，长如此亦能。','',''),('quantangshi-16037','初到昭应呈同僚','王建','quantangshi','','卷17','白发初为吏，有慙年少郎。
自知身上拙，不称世间忙。
秋雨悬墙绿，暮山宫树黄。
同官若容许，长借老僧房。','',''),('quantangshi-16038','县丞厅即事','王建','quantangshi','','卷17','宫殿半山上，人家高下居。
古厅眠受魇，老吏语多虚。
雨水洗荒竹，溪沙填废渠。
圣朝收外府，皆自九天除。','',''),('quantangshi-16039','闲居即事','王建','quantangshi','','卷17','老病贪光景，寻常不下帘。
妻愁耽酒僻，人怪考诗严。
小婢偷红纸，娇儿弄白髯。
有时看旧卷，未免意中嫌。','',''),('quantangshi-16040','林居','王建','quantangshi','','卷17','荒林四面通，门在野田中。
顽仆长如客，贫居未胜蓬。
旧绵衣不暖，新草屋多风。
唯去山南近，闲亲贩药翁。','',''),('quantangshi-16041','原上新居十三首 一','王建','quantangshi','','卷17','新占原头地，本无山可归。
荒藤生叶晚，老杏着花稀。
厨舍近泥竈，家人初饱薇。
弟兄今四散，何日更相依。','',''),('quantangshi-16042','原上新居十三首 二','王建','quantangshi','','卷17','一家榆柳新，四面远无邻。
人少愁闻病，庄孤幸得贫。
耕牛长愿饱，樵仆每怜勤。
终日忧衣食，何由[脱]此身。','',''),('quantangshi-16043','原上新居十三首 三','王建','quantangshi','','卷17','长安无旧识，百里是天涯。
寂寞思逢客，荒凉喜见花。
访僧求贱药，将马中豪家。
乍得新蔬菜，朝盘忽觉奢。','',''),('quantangshi-16044','原上新居十三首 四','王建','quantangshi','','卷17','鸡鸣村舍遥，花发亦萧条。
野竹初生笋，溪田未得苗。
家贫僮仆瘦，春冷菜蔬焦。
甘分长如此，无名在圣朝。','',''),('quantangshi-16045','原上新居十三首 五','王建','quantangshi','','卷17','春来梨枣尽，啼哭小儿饥。
邻富鸡常去，庄贫客渐稀。
借牛畊地晚，卖树纳钱迟。
墙下当官路，依山补竹篱。','',''),('quantangshi-16046','原上新居十三首 六','王建','quantangshi','','卷17','自埽一间房，唯铺独卧牀。
野羹溪菜滑，山纸水苔香。
陈药初和白，新经未入黄。
近来心力少，休读养生方。','',''),('quantangshi-16047','原上新居十三首 七','王建','quantangshi','','卷17','拟作读经人，空房置净巾。
锁茶藤箧密，曝药竹牀新。
老病应随业，因缘不离身。
焚香向居士，无计出诸尘。','',''),('quantangshi-16048','原上新居十三首 八','王建','quantangshi','','卷17','移家近住邨，贫苦自安存。
细问梨果植，远求花药根。
倩人开废井，趂犊入新园。
长爱当山立，黄昏不闭门。','',''),('quantangshi-16049','原上新居十三首 九','王建','quantangshi','','卷17','和暖遶林行，新贫足喜声。
埽渠忧竹旱，浇地引兰生。
山客凭栽树，家僮使入城。
门前粉壁上，书着县官名。','',''),('quantangshi-16050','原上新居十三首 十','王建','quantangshi','','卷17','住处钟鼓外，免争当路桥。
身闲时却困，儿病可来娇。
鸡睡日阳暖，蜂狂花艳烧。
长安足门户，叠叠看登朝。','',''),('quantangshi-16051','原上新居十三首 十一','王建','quantangshi','','卷17','近来年纪到，世事总无心。
古碣凭人打，闲诗任客吟。
送经还野苑，移石入幽林。
谷口春风恶，梨花盖地深。','',''),('quantangshi-16052','原上新居十三首 十二','王建','quantangshi','','卷17','嬾更学诸余，林中埽地居。
腻衣穿不洗，白发短慵梳。
苦相常多泪，劳生自悟虚。
闲行人事绝，亲故亦无书。','',''),('quantangshi-16053','原上新居十三首 十三','王建','quantangshi','','卷17','住处去山近，傍园麋鹿行。
野桑穿井长，荒竹过墙生。
新识邻里面，未谙邨社情。
石田无力及，贱赁与人耕。','',''),('quantangshi-16054','送李评事使蜀','王建','quantangshi','','卷17','劝酒不依巡，明朝万里人。
转江云栈细，近驿板桥新。
石冷啼猿影，松昏戏鹿尘。
少年为客好，况是益州春。','',''),('quantangshi-16055','新修道居','王建','quantangshi','','卷17','世间无所入，学道处新成。
两面有山色，六时闻磬声。
闲加经遍数，老爱字分明。
若得离烦恼，焚香过一生。','',''),('quantangshi-16056','赠洪誓师','王建','quantangshi','','卷17','老僧真古画，闲坐语中听。
识病方书圣，谙山草木灵。
人来多施药，愿满不持经。
相伴寻溪竹，秋苔袜履青。','',''),('quantangshi-16057','题法云禅院僧','王建','quantangshi','','卷17','不剃头多日，禅来白发长。
合邨迎住寺，同学乞修房。
觉少持经力，忧无养病粮。
上山犹得在，自解衲衣裳。','',''),('quantangshi-16058','赠溪翁','王建','quantangshi','','卷17','溪田借四邻，不省解忧身。
看日和仙药，书符救病人。
伴僧斋过夏，中酒卧经旬。
应得丹砂力，春来黑发新。','',''),('quantangshi-16059','谢李续主簿','王建','quantangshi','','卷17','馆舍幸相近，因风及病身。
一官虽隔水，四韵是同人。
衰卧朦胧晓，贫居冷落春。
少年无不好，莫恨满头尘。','',''),('quantangshi-16060','寒食','王建','quantangshi','','卷17','田舍清明日，家家出火迟。
白衫眠古巷，红索搭高枝。
纱带生难结，铜钗重欲垂。
斩新衣踏尽，还似去年时。','',''),('quantangshi-16061','贻小尼师','王建','quantangshi','','卷17','新剃青头发，生来未埽眉。
身轻礼拜稳，心慢记经迟。
唤起犹侵晓，催斋已过时。
春晴堦下立，私地弄花枝。','',''),('quantangshi-16062','惜欢','王建','quantangshi','','卷17','当欢须且欢，过后买应难。
岁去停灯守，花开把火看。
狂来欺酒浅，愁尽觉天宽。
次第头皆白，齐年人已残。','',''),('quantangshi-16063','山中惜花','王建','quantangshi','','卷17','忽看花渐稀，罪过酒醒时。
寻觅风来处，惊张夜落时。
游丝缠故蘂，宿夜守空枝。
开取当轩地，年年树底期。','',''),('quantangshi-16064','和武门下伤韦令孔雀','王建','quantangshi','','卷17','孤号秋阁阴，韦令在时禽。
觅伴海山黑，思乡橘柚深。
举头闻旧曲，顾尾惜残金。
顦顇不飞去，重君池上心。','',''),('quantangshi-16065','题所赁宅牡丹花','王建','quantangshi','','卷17','赁宅得花饶，初开恐是妖。
粉光深紫腻，肉色退红娇。
且愿风留着，惟愁日炙燋。
可怜零落蘂，收取作香烧。','',''),('quantangshi-16066','隐者居','王建','quantangshi','','卷17','山人住处高。
看日上蟠桃，雪缕青山脉。
云生白鹤毛，朱书护身咒。
水噀断邪刀，何物中长食。
胡麻慢火熬。','',''),('quantangshi-16067','昭应官舍','王建','quantangshi','','卷17','绕厅春草合，知道县家闲。
行见雨遮院，卧看人上山。
避风新浴后，请假未醒间。
朝客轻卑吏，从他不往还。','',''),('quantangshi-16068','送严大夫赴桂州','王建','quantangshi','','卷17','岭头分界候，一半属湘潭。
水驿门旗出，山峦洞主参。
辟邪犀角重，解酒荔枝甘。
莫叹京华远，安南更有南。','',''),('quantangshi-16069','望行人','王建','quantangshi','','卷17','自从江树秋，日日望江楼。
梦见离珠浦，书来在桂州。
不同鱼比目，终恨水分流。
久不开明镜，多应是白头。','',''),('quantangshi-16070','塞上','王建','quantangshi','','卷17','漫漫复凄凄，黄沙暮渐迷。
人当故乡立，马过旧营嘶。
断雁逢冰碛，回军占雪溪。
夜来山下哭，应是送降奚。','',''),('quantangshi-16071','杜中丞书院新移小竹','王建','quantangshi','','卷17','此地本无竹，远从山寺移。
经年求养法，隔日记浇时。
嫩绿卷新叶，残黄收故枝。
色轻寒不动，声与静相宜。
爱护出常数，稀稠看自知。
贫来缘未有，客散独行迟。','',''),('quantangshi-16072','同于汝锡赏白牡丹','王建','quantangshi','','卷17','晓日花初吐，春寒白未凝。
月光裁不得，苏合点难胜。
柔腻于云叶，新鲜掩鹤膺。
统心黄倒晕，侧茎紫重棱。
乍敛看如睡，初开问欲譍。
竝香幽蕙死，比艳美人憎。
价数千金贵，形相两眼疼。
自知颜色好，愁被彩光凌。','',''),('quantangshi-16073','送吴郎中赴忠州','王建','quantangshi','','卷17','西台复南省，清白上天知。
家每因穷散，官多为直移。
遥边过驿近，买药出城迟。
朝野凭人别，亲情伴酒悲。
故园愁去后，白发想回时。
何处忠州界，山头卓望旗。','',''),('quantangshi-16074','照镜','王建','quantangshi','','卷17','终日自缠绕，此身无适缘。
万愁生旅夜，百病凑衰年。
少睡憎明屋，慵行待暖天。
痒头梳有虱，风耳炙闻蝉。
摇白方多错，回金法不全。
家贫何所恋，时在老僧边。','',''),('quantangshi-16075','秋日送杜虔州','王建','quantangshi','','卷17','忆得宿新宅，别来余蕙香。
初闻守郡远，一日卧空牀。
野驿烟火湿，路人消息狂。
山楼添鼓角，村栅立旗枪。
晚渚露荷败，早衙风桂凉。
谢家章句出，江月少辉光。','',''),('quantangshi-16076','送郑权尚书南海','王建','quantangshi','','卷17','七郡双旌贵，人皆不忆廻。
戍头龙脑铺，关口象牙堆。
勅设熏炉出，蛮辞咒节开。
市喧山贼破，金贱海船来。
白氎家家织，红蕉处处栽。
已将身报国，莫起望乡台。','',''),('quantangshi-16077','题别遗爱草堂兼呈李十使君','王建','quantangshi','','卷17','曾住炉峰下，书堂对药台。
斩新萝径合，依旧竹牕开。
砌水亲看决，池荷手自栽。
五年方蹔至，一宿又须回。
纵未长归得，犹胜不到来。
君家白鹿洞，闻道亦生苔。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-16078','赏牡丹','王建','quantangshi','','卷17','此花名价别，开艳益皇都。
香遍苓菱死，红烧踯躅枯。
软光笼细脉，妖色暖鲜肤。
满蘂攒黄粉，含棱缕绛苏。
好和薰御服，堪画入宫图。
晚态愁新妇，残妆望病夫。
教人知个数，留客赏斯须。
一夜轻风起，千金买亦无。','',''),('quantangshi-16079','赠王枢密','王建','quantangshi','','卷17','三朝行坐镇相随，今上春宫见小时。
脱下御衣先赐着，进来龙马每教骑。
长承密旨归家少，独奏边机出殿迟。
自是姓同亲向说，九重争得外人知。','',''),('quantangshi-16080','早秋过龙武李将军书斋','王建','quantangshi','','卷17','高树蝉声秋巷里，朱门冷静似闲居。
重装墨画数茎竹，长着香薰一架书。
语笑侍儿知礼数，吟哦野客任狂疎。
就中爱读英雄传，欲立功勋恐不如。','',''),('quantangshi-16081','江陵即事','王建','quantangshi','','卷17','瘴云梅雨不成泥，十里津楼压大堤。
蜀女下沙迎水客，巴童傍驿卖山鸡。
寺多红药烧人眼，地足青苔染马蹄。
夜半独眠愁在远，北看归路隔蛮溪。','',''),('quantangshi-16082','题花子赠渭州陈判官','王建','quantangshi','','卷17','腻如云母轻如粉，艳胜香黄薄胜蝉。
点绿斜蒿新叶嫩，添红石竹晚花鲜。
鸳鸯比翼人初帖，蛱蝶重飞样未传。
况复萧郎有情思，可怜春日镜台前。','',''),('quantangshi-16083','送从侄拟赴江陵少尹','王建','quantangshi','','卷17','江陵少尹好闲官，亲故皆来劝自宽。
无事日长贫不易，有才年少屈终难。
沙头欲买红螺盏，渡口多呈白角盘。
应向章华台下醉，莫冲云雨夜深寒。','',''),('quantangshi-16084','华清宫感旧','王建','quantangshi','','卷17','尘到朝元边使急，千官夜发六龙回。
辇前月照罗衫泪，马上风吹蜡烛灰。
公主妆楼金锁涩，贵妃汤殿玉莲开。
有时云外闻天乐，知是先皇沐浴来。','',''),('quantangshi-16085','九仙公主旧庄','王建','quantangshi','','卷17','仙居五里外门西，石路亲回御马蹄。
天使来栽宫里树，罗衣自买院前溪。
野牛行傍浇花井，本主分将灌药畦。
楼上凤皇飞去后，白云红叶属山鸡。','',''),('quantangshi-16086','郭家溪亭','王建','quantangshi','','卷17','高亭望见长安树，春草冈西旧院斜。
光动绿烟遮岸行，粉开红艳塞溪花。
野泉闻洗亲王马，古柳曾停贵主车。
妆阁书楼倾侧尽，云山新卖与官家。','',''),('quantangshi-16087','题金家竹溪','王建','quantangshi','','卷17','少年因病离天仗，乞得归家自养身。
买断竹溪无别主，散分泉水与新邻。
山头鹿下长惊犬，池面鱼行不怕人。
乡使到来常欵语，还闻世上有功臣。','',''),('quantangshi-16088','题应圣观','王建','quantangshi','','卷17','精思堂上画三身，回作仙宫度美人。
赐额御书金字贵，行香天乐羽衣新。
空廊鸟啄花甎缝，小殿虫缘玉像尘。
头白女冠犹说得，蔷薇不似已前春。','',''),('quantangshi-16089','同于汝锡游降圣观','王建','quantangshi','','卷17','秦时桃树满山坡，骑鹿先生降大罗。
路尽溪头逢地少，门连内里见天多。
荒泉坏简朱砂暗，古塔残经篆字讹。
闻说开元斋醮日，晓移行漏帝亲过。','',''),('quantangshi-16090','逍遥翁溪亭','王建','quantangshi','','卷17','逍遥翁在此裴回，帝改溪名起石台。
车马到春常借问，子孙因选暂归来。
稀疎野竹人移折，零落蕉花雨打开。
无主青山何所直，卖供官税不如灰。','',''),('quantangshi-16091','寻李山人不遇','王建','quantangshi','','卷17','山客长须少在时，溪中放鹤洞中碁。
生金有气寻还远，仙药成窠见即移。
莫为无家陪寺食，应缘将米寄人炊。
从头石上留名去，独向南峰问老师。','',''),('quantangshi-16092','题石瓮寺','王建','quantangshi','','卷17','青崖白石夹城东，泉脉钟声内里通。
地压龙蛇山色别，屋连宫殿匠名同。
檐灯经夏纱笼黑，溪叶先秋腊树红。
天子亲题诗总在，画扉长鏁碧龛中。','',''),('quantangshi-16093','早登西禅寺阁','王建','quantangshi','','卷17','上方台殿第三层，朝壁红窗日气凝。
烟雾开时分远寺，山川晴处见崇陵。
沙湾漾水图新粉，绿野荒阡晕色缯。
莫说城南月灯阁，自诸楼看总难胜。','',''),('quantangshi-16094','题江寺兼求药子','王建','quantangshi','','卷17','隋朝旧寺楚江头，深谢师僧引客游。
空赏野花无过夜，若看琪树即须秋。
红珠落地求谁与，青角垂阶自不收。
愿乞野人三两粒，归家将助小庭幽。','',''),('quantangshi-16095','题诜法师院','王建','quantangshi','','卷17','三年说戒龙宫里，巡礼还来向水行。
多爱贫穷人远请，长修破落寺先成。
秋天盆底新荷色，夜地房前小竹声。
僧院不求诸处好，转经唯有一窗明。','',''),('quantangshi-16096','酬于汝锡晓雪见寄','王建','quantangshi','','卷17','欲明天色白漫漫，打叶穿帘雪未干。
薄落堦前人踏尽，差池树里鸟衔残。
旋销迎暖沾墙少，斜舞遮春到地难。
劳动更裁新样绮，红灯一夜剪刀寒。','',''),('quantangshi-16097','从军后寄山中友人','王建','quantangshi','','卷17','爱仙无药住溪贫，脱却山衣事汉臣。
夜半听鸡梳白发，天明走马入红尘。
村童近去嫌腥食，野鹤高飞避俗人。
劳动先生远相示，别来弓箭不离身。','',''),('quantangshi-16098','寄汴州令狐相公','王建','quantangshi','','卷17','三军江口拥双旌，虎帐长开自教兵。
机鏁恶徒狂寇尽，恩驱老将壮心生。
水门向晚茶商闹，桥市通宵酒客行。
秋日梁王池阁好，新歌散入管弦声。','',''),('quantangshi-16099','别李赞侍御','王建','quantangshi','','卷17','同受艰难骠骑营，半年中听揭枪声。
草头送酒驱村乐，贼里看花着探兵。
讲易工夫寻已圣，说诗门户别来情。
荐书自入无消息，卖尽寒衣却出城。','',''),('quantangshi-16100','和蒋学士新授章服','王建','quantangshi','','卷17','五色箱中绛服春，笏花成就白鱼新。
看宣赐处惊回眼，着谢恩时便称身。
瑞草唯承天上露，红鸾不受世间尘。
翰林同贺文章出，惊动茫茫下界人。','',''),('quantangshi-16101','岁晚自感','王建','quantangshi','','卷17','人皆欲得长年少，无那排门白发催。
一向破除愁不尽，百方回避老须来。
草堂未办终须置，松树难成亦且栽。
沥酒愿从今日后，更逢二十度花开。','',''),('quantangshi-16102','昭应官舍','王建','quantangshi','','卷17','痴顽终日羡人闲，却喜因官得近山。
斜对寺楼分寂寂，远从溪路借潺潺。
眇身多病唯亲药，空院无钱不要关。
文案把来看未会，虽书一字甚慙颜。','',''),('quantangshi-16103','寄旧山僧','王建','quantangshi','','卷17','因依老宿发心初，半学修心半读书。
雪后每常同席卧，花时未省两山居。
猎人箭底求伤雁，钓户竿头乞活鱼。
一向风尘取烦恼，不知衰病日难除。','',''),('quantangshi-16104','武陵春日','王建','quantangshi','','卷17','寻春何事却悲凉，春到他乡忆故乡。
秦女洞桃欹涧碧，楚王堤柳舞烟黄。
波涛入梦家山远，名利关身客路长。
不似冥心叩尘寂，玉编金轴有仙方。','',''),('quantangshi-16105','寄分司张郎中','王建','quantangshi','','卷17','一别京华年岁久，卷中多见岭南诗。
声名已压众人上，愁思未平双鬓知。
江郡迁移犹远地，仙官荣庞是分司。
青天白日当头上，会有求闲不得时。','',''),('quantangshi-16106','上武元衡相公','王建','quantangshi','','卷17','旌旗坐镇蜀江雄，帝命重开旧合崇。
襃贬唐书天历上，捧持尧日庆云中。
孤情逈出鸾皇远，健思潜搜海岳空。
长得萧何为国相，自西流水尽朝宗。','',''),('quantangshi-16107','上张弘靖相公','王建','quantangshi','','卷17','传封三世尽河东，家占中条第一峰。
旱岁天教作霖雨，明时帝用补山龙。
草开旧路沙痕在，日照新池凤迹重。
卑散自知霄汉隔，若为门下赐从容。','',''),('quantangshi-16108','上裴度舍人','王建','quantangshi','','卷17','小松双对凤池开，履迹衣香逼上台。
天意皆从彩毫出，宸心尽向紫烟来。
非时玉案呈宣旨，每日金堦谢赐回。
仙侣何因记名姓，县丞头白走尘埃。','',''),('quantangshi-16109','上杜元颖相公','王建','quantangshi','','卷17','学士金銮殿后居，天中行坐侍龙舆。
承恩不许离牀谢，密诏常教倚案书。
马上唤遮红觜鸭，船头看钓赤鳞鱼。
闲曹散吏无相识，犹记荆州拜谒初。','',''),('quantangshi-16110','赠卢汀谏议','王建','quantangshi','','卷17','青蛾不得在牀前，空室焚香独自眠。
功证诗篇离景象，药成官位属神仙。
闲过寺观长冲夜，立送封章直上天。
近见兰台诸吏说，御诗新集未教传。','',''),('quantangshi-16111','贺杨巨源博士拜虞部员外','王建','quantangshi','','卷17','合归兰署已多时，上得金梯亦未迟。
两省郎官开道路，九州山泽属曹司。
诸生拜别收书卷，旧客看来读制词。
残着几丸仙药在，分张还遣病夫知。','',''),('quantangshi-16112','赠郭将军','王建','quantangshi','','卷17','承恩新拜上将军，当直巡更近五云。
天下表章经院过，宫中语笑隔墙闻。
密封计策非时奏，别赐衣裳到处薰。
向晚临堦看号簿，眼前风景任支分。','',''),('quantangshi-16113','赠田将军','王建','quantangshi','','卷17','初从学院别先生，便领偏师得战名。
大小独当三百阵，纵横祗用五千兵。
回残匹帛归天库，分好旌旗入禁营。
自执金吾长上直，蓬莱宫里夜巡更。','',''),('quantangshi-16114','赠胡泟将军','王建','quantangshi','','卷17','书生难得是金吾，近日登科记总无。
半夜进傩当玉殿，未明排仗到铜壶。
朱牌面上分官契，黄纸头边押勅符。
恐要蕃中新道路，指挥重画五城图。','',''),('quantangshi-16115','留别田尚书','王建','quantangshi','','卷17','拟报平生未杀身，难离门馆起居频。
不看匣里钗头古，犹恋机中锦样新。
一旦甘为漳岸老，全家却作杜陵人。
朝天路在骊山下，专望红旗拜旧尘。','',''),('quantangshi-16116','送唐大夫罢节归山','王建','quantangshi','','卷17','年少平戎老学仙，表求骸骨乞生全。
不堪腰下悬金印，已向云西寄玉田。
旄节抱归官路上，公卿送到国门前。
人间鸡犬同时去，遥听笙歌隔水烟。','',''),('quantangshi-16117','送司空神童','王建','quantangshi','','卷17','杏花坛上授书时，不废中庭趂蝶飞。
暗写五经收部秩，初年七岁着衫衣。
秋堂白发先生别，古巷青襟旧伴归。
独向凤城持荐表，万人丛里有光辉。','',''),('quantangshi-16118','送振武张尚书','王建','quantangshi','','卷17','回天转地是将军，扶助春宫上五云。
抚背恩虽同骨肉，拥旄名未敌功勋。
尽收壮勇填兵数，不向蕃浑夺马羣。
闲即单于台下猎，威声直到海西闻。','',''),('quantangshi-16119','送吴谏议上饶州','王建','quantangshi','','卷17','鄱阳太守是真人，琴在牀头箓在身。
曾向先皇边谏事，还应上帝处称臣。
养生自有年支药，税户应停月进银。
净扫水堂无侍女，下街唯共鹤殷勤。','',''),('quantangshi-16120','赠阎少保','王建','quantangshi','','卷17','髭须虽白体轻健，九十三来却少年。
问事爱知天宝里，识人皆是武皇前。
玉装劒佩身长带，绢写方书子不传。
侍女常时教合药，亦闻私地学求仙。','',''),('quantangshi-16121','送魏州李相公','王建','quantangshi','','卷17','百代功勋一日成，三年五度换双旌。
闲来不对人论战，难处长先自请行。
旗下可闻诛败将，阵头多是用降兵。
当朝面受新恩去，算料妖星不敢生。','',''),('quantangshi-16122','赠索暹将军','王建','quantangshi','','卷17','浑身着箭瘢犹在，万槊千刀总过来。
轮劒直冲生马队，抽旗旋踏死人堆。
闻休鬬战心还痒，见说烟尘眼即开。
泪滴先皇堦下土，南衙班里趁朝回。','',''),('quantangshi-16123','赠王屋道士赴诏','王建','quantangshi','','卷17','玉皇符诏下天坛，玳瑁头簪白角冠。
鹤遣院中童子养，鹿凭山下老人看。
法成不怕刀枪利，体实常欺石榻寒。
能断世间腥血昧，长生只要一丸丹。','',''),('quantangshi-16124','赠王处士','王建','quantangshi','','卷17','松树当轩雪满地，青山掩障碧纱幮。
鼠来案上常偷水，鹤在牀前亦看碁。
道士写将行气法，家童授与步虚词。
世间有似君应少，便乞从今作我师。','',''),('quantangshi-16125','洛中张籍新居','王建','quantangshi','','卷17','最是城中闲静处，更回门向寺前开。
云山且喜重重见，亲故应须得得来。
借倩学生排药合，留连处士乞松栽。
自君移到无多日，墙上人名满绿苔。','',''),('quantangshi-16126','题裴处士碧虚溪居','王建','quantangshi','','卷17','鸟声真似深山里，平地人间自不同。
春圃紫芹长卓卓，暖泉青草一丛丛。
松台前后花皆别，竹崦高低水尽通。
细问来时从近远，溪名载入县图中。','',''),('quantangshi-16127','送阿史那将军安西迎旧使灵榇','王建','quantangshi','','卷17','汉家都护边头没，旧将麻衣万里迎。
阴地背行山下火，风天错到碛西城。
单于送葬还垂泪，部曲招魂亦道名。
却入杜陵秋巷里，路人来去读铭旌。','',''),('quantangshi-16128','赠崔礼驸马','王建','quantangshi','','卷17','凤皇楼阁连宫树，天子崔郎自爱贫。
金埒减添栽药地，玉鞭平与卖书人。
家中弦管听常少，分外诗篇看即新。
一月一回陪内宴，马蹄犹压踏香尘。','',''),('quantangshi-16129','赠太清卢道士','王建','quantangshi','','卷17','上清道士未升天，南岳中华作散仙。
书卖八分通字学，丹烧九转定人年。
修行近日形如鹤，导引多时骨似绵。
想向诸山寻礼遍，却回还守老君前。','',''),('quantangshi-16130','送宫人入道','王建','quantangshi','','卷17','休梳丛鬓洗红妆，头戴芙蓉出未央。
弟子抄将歌遍叠，宫人分散舞衣裳。
问师初得经中字，入静犹烧内里香。
发愿蓬莱见王母，却归人世施仙方。','',''),('quantangshi-16131','上李吉甫相公','王建','quantangshi','','卷17','圣朝齐贺说逢殷，霄汉无云日月真。
金鼎调和天膳美，瑶池沐浴赐衣新。
两河开地山川正，四海休兵造化仁。
曾向山东为散吏，当今窦宪是贤臣。','',''),('quantangshi-16132','上李益庶子','王建','quantangshi','','卷17','紫烟楼阁碧纱亭，上界诗仙独自行。
奇险驱回还寂寞，云山经用始鲜明。
藕绡纹缕裁来滑，镜水波涛滤得清。
昏思愿因秋露洗，幸容堦下礼先生。','',''),('quantangshi-16133','题元郎中新宅','王建','quantangshi','','卷17','近移松树初栽药，经帙书签一切新。
铺设暖房迎道士，支分闲院着医人。
买来高石虽然贵，入得朱门未免贫。
惟有好诗名字出，倍教年少损心神。','',''),('quantangshi-16134','初授太府丞言怀','王建','quantangshi','','卷17','除书亦下属微班，唤作官曹便不闲。
检案事多关市井，听人言志在云山。
病童唤着唯行慢，老马鞭多转放顽。
此去仙宫无一里，遥看松树众家攀。','',''),('quantangshi-16135','赠李愬仆射','王建','quantangshi','','卷17','唐州将士死生同，尽逐双旌旧镇空。
独破淮西功业大，新除陇右世家雄。
知时每笑论兵法，识势还轻立战功。
次第各分茅土贵，殊勋并在一门中。','',''),('quantangshi-16136','书赠旧浑二曹长','王建','quantangshi','','卷17','二年同在华清下，入县门中最近邻。
替饮觥筹知户小，助成书屋见家贫。
夜碁临散停分客，朝浴先回各送人。
僮仆使来传语熟，至今行酒校殷勤。','',''),('quantangshi-16137','上崔相公','王建','quantangshi','','卷17','枯桂衰兰一遍春，唯将道德定君臣。
施行圣泽山川润，图画天文彩色新。
开阁覆看祥瑞历，封名直进薜萝人。
应怜老病无知己，自别溪中满鬓尘。','',''),('quantangshi-16138','寄杨十二秘书','王建','quantangshi','','卷17','初移古寺正南方，静是浮山远是庄。
人定犹行背街鼓，月高还去打僧房。
新诗欲写中朝满，旧卷常抄外国将。
闲出天门醉骑马，可怜蓬阁秘书郎。','',''),('quantangshi-16139','谢田赞善见寄','王建','quantangshi','','卷17','五侯三任未相称，头白如丝作县丞。
错判符曹羣吏笑，乱书岩石一山憎。
自知酒病衰肠怯，遥怕春残百鸟凌。
年少力生犹不敌，况加顦顇闷腾腾。','',''),('quantangshi-16140','晚秋病中','王建','quantangshi','','卷17','万事风吹过耳轮，贫儿活计亦曾闻。
偶逢新语书红叶，难得闲人话白云。
霜下野花浑着地，寒来溪鸟不成羣。
病多体痛无心力，更被头边药气熏。','',''),('quantangshi-16141','薛二十池亭','王建','quantangshi','','卷17','每个树边消一日，遶池行匝又须行。
异花多是非时有，好竹皆当要处生。
斜竖小桥看岛势，远移山石作泉声。
浮萍着岸风吹歇，水面无尘晚更清。','',''),('quantangshi-16142','故梁国公主池亭','王建','quantangshi','','卷17','平阳池馆枕秦川，门锁南山一朵烟。
素柰花开西子面，绿榆枝散沈郎钱。
装檐玳瑁随风落，傍岸䴔䴖逐暖眠。
寂寞空余歌舞地，玉箫声绝凤归天。','',''),('quantangshi-16143','题柱国寺','王建','quantangshi','','卷17','皇帝施钱修此院，半居天上半人间。
丹梯暗出三重阁，古像斜开一面山。
松柏自穿空地少，川原不税小僧闲。
行香天使长相续，早起离城日午还。','',''),('quantangshi-16144','昭应官舍书事','王建','quantangshi','','卷17','县在华清宫北面，晓看楼殿正相当。
庆云出处依时报，御果呈来每度尝。
腊月近汤泉不冻，夏天临渭屋多凉。
两衙早被官拘束，登阁巡溪亦属忙。','',''),('quantangshi-16145','昭应李郎中见贻佳作次韵奉酬','王建','quantangshi','','卷17','窗户风凉四面开，陶公爱晚上高台。
中庭不热青山入，野水初晴白鸟来。
静思道心缘境熟，麤疎文字见诗回。
诸生围遶新篇读，玉阙仙宫少此才。','',''),('quantangshi-16146','闲说','王建','quantangshi','','卷17','桃花百叶不成春，鹤寿千年也未神。
秦陇州缘鹦鹉贵，王侯家为牡丹贫。
歌头舞遍回回别，鬓样眉心日日新。
鼓动六街骑马出，相逢总是学狂人。','',''),('quantangshi-16147','自伤','王建','quantangshi','','卷17','衰门海内几多人，满眼公卿总不亲。
四授官资元七品，再经婚娶尚单身。
图书亦为频移尽，兄弟还因数散贫。
独自在家长似客，黄昏哭向野田春。','',''),('quantangshi-16148','田侍中宴席','王建','quantangshi','','卷17','香熏罗幕暖成烟，火照中庭烛满筵。
整顿舞衣呈玉腕，动摇歌扇露金钿。
青蛾侧座调双管，彩凤斜飞入五弦。
虽是沂公门下客，争将肉眼看云天。','',''),('quantangshi-16149','寒食日看花','王建','quantangshi','','卷17','早入公门到夜归，不因寒食少闲时。
颠狂遶树猿离鏁，跳踯缘冈马断羁。
酒污衣裳从客笑，醉饶言语觅花知。
老来自喜身无事，仰面西园得咏诗。','',''),('quantangshi-16150','和少府崔卿微雪早朝','王建','quantangshi','','卷17','蓬莱春雪晓犹残，点地成花遶百官。
已傍祥鸾迷殿角，还穿瑞草入袍襴。
无多白玉阶前湿，积渐青松叶上干。
