省得老僧留不住，重寻更可有因由。','',''),('quantangshi-16230','道中寄杜书记','王建','quantangshi','','卷17','西南东北暮天斜，巴字江边楚树花。
珍重荆州杜书记，闲时多在广师家。','',''),('quantangshi-16231','听琴','王建','quantangshi','','卷17','无事此身离白云，松风溪水不曾闻。
至心听着仙翁引，今看青山围绕君。','',''),('quantangshi-16232','赠陈评事','王建','quantangshi','','卷17','识君虽向歌钟会，说事不离云水间。
春夜酒醒长起坐，灯前一纸洞庭山。','',''),('quantangshi-16233','寄画松僧','王建','quantangshi','','卷17','天香寺里古松僧，不画枯松落石层。
最爱临江两三树，水禽栖处解无藤。','',''),('quantangshi-16234','花褐裘','王建','quantangshi','','卷17','对织芭蕉雪毳新，长缝双袖窄裁身。
到头须向边城着，消杀秋风称猎尘。','',''),('quantangshi-16235','夜看美人宫棊','王建','quantangshi','','卷17','宫棊布局不依经，黑白分明子数停。
巡拾玉沙天汉晓，犹残织女两三星。','',''),('quantangshi-16236','上田仆射','王建','quantangshi','','卷17','一方新地隔河烟，曾接诸生听管弦。
却忆去年寒食会，看花犹在水堂前。','',''),('quantangshi-16237','江陵道中','王建','quantangshi','','卷17','菱叶参差萍叶重，新蒲半折夜来风。
江村水落平地出，溪畔渔船青草中。','',''),('quantangshi-16238','冬至后招于秀才','王建','quantangshi','','卷17','日近山红暖气新，一阳先入御沟春。
闻闲立马重来此，沐浴明年称意身。','',''),('quantangshi-16239','别曲','王建','quantangshi','','卷17','毒蛇在肠疮满背，去年别家今别弟。
马头对哭各东西，天边柳絮无根蔕。','',''),('quantangshi-16240','长安别','王建','quantangshi','','卷17','长安清明好时节，只宜相送不宜别。
恶心牀上铜片明，照见离人白头发。','',''),('quantangshi-16241','宫人斜','王建','quantangshi','','卷17','未央墙西青草路，宫人斜里红妆墓。
一边载出一边来，更衣不减寻常数。','',''),('quantangshi-16242','春词','王建','quantangshi','','卷17','良人朝早半夜起，樱桃如珠露如水。
下堂把火送郎回，移枕重眠晓窗里。','',''),('quantangshi-16243','野池','王建','quantangshi','','卷17','野池水满连秋堤，菱花结实蒲叶齐。
川口雨晴风复止，蜻蜓上下鱼东西。','',''),('quantangshi-16244','题崔秀才里居','王建','quantangshi','','卷17','自知名出休呈卷，爱去人家远处居。
时复打门无别事，铺头来索买残书。','',''),('quantangshi-16245','酬栢侍御答酒','王建','quantangshi','','卷17','茱萸酒法大家同，好是盛来白椀中。
这度自知颜色重，不消诗里弄溪翁。','',''),('quantangshi-16246','别药栏','王建','quantangshi','','卷17','芍药丁香手里栽，临行一日绕千回。
外人应怪难辞别，总是山中自取来。','',''),('quantangshi-16247','长门','王建','quantangshi','','卷17','长门闭定不求生，烧却头花卸却筝。
病卧玉窗秋雨下，遥闻别院唤人声。','',''),('quantangshi-16248','题渭亭','王建','quantangshi','','卷17','云开远水傍秋天，沙岸蒲帆隔野烟。
一片蔡州青草色，日西铺在古台边。','',''),('quantangshi-16249','过喜祥山馆','王建','quantangshi','','卷17','夜过深山算驿程，三回黑地听泉声。
自离军马身轻健，得向溪边尽足行。','',''),('quantangshi-16250','送迁客','王建','quantangshi','','卷17','万里潮州一逐臣，悠悠青草海边春。
天涯莫道无回日，上岭还逢向北人。','',''),('quantangshi-16251','废寺','王建','quantangshi','','卷17','废寺乱来为县驿，荒松老柏不生烟。
空廊屋漏画僧尽，梁上犹书天宝年。','',''),('quantangshi-16252','题禅师房','王建','quantangshi','','卷17','浮生不住叶随风，填海移山总是空。
长向人间愁老病，谁来闲坐此房中。','',''),('quantangshi-16253','看石楠花','王建','quantangshi','','卷17','留得行人忘却归，雨中须是石楠枝。
明朝独上铜台路，容见花开少许时。','',''),('quantangshi-16254','长安县后亭看画','王建','quantangshi','','卷17','水冻横桥雪满池，新排石笋绕巴篱。
县门斜掩无人吏，看画双飞白鹭鸶。','',''),('quantangshi-16255','华岳庙二首 一','王建','quantangshi','','卷17','女巫遮客买神盘，争取琵琶庙里弹。
闻有马蹄生拍树，路人来去向南看。','',''),('quantangshi-16256','华岳庙二首 二','王建','quantangshi','','卷17','自移西岳门长锁，一个行人一遍开。
上庙参天今见在，夜头风起觉神来。','',''),('quantangshi-16257','酬赵侍御','王建','quantangshi','','卷17','年少同为邺下游，闲寻野寺醉登楼。
别来衣马从胜旧，争向边尘满白头。','',''),('quantangshi-16258','镊白','王建','quantangshi','','卷17','总道老来无用处，何须白发在前生。
如今不用偷年少，拔却三茎又五茎。','',''),('quantangshi-16259','送山人二首 一','王建','quantangshi','','卷17','嵩山古寺离来久。
回见溪桥野叶黄，辛苦老师看守处。
为悬秋药闭空房。','',''),('quantangshi-16260','送山人二首 二','王建','quantangshi','','卷17','山客狂来跨白驴，袖中遗却颍阳书。
人间亦有妻儿在，抛向嵩阳古观居。','',''),('quantangshi-16261','扬州寻张籍不见','王建','quantangshi','','卷17','别后知君在楚城，扬州寺里觅君名。
西江水阔吴山远，却打船头向北行。','',''),('quantangshi-16262','宿长安县后斋','王建','quantangshi','','卷17','新向金阶奏罢兵，长安县里绕池行。
喜欢得伴山僧宿，看雪吟诗直到明。','',''),('quantangshi-16263','夜看扬州市','王建','quantangshi','','卷17','夜市千灯照碧云，高楼红袖客纷纷。
如今不似时平日，犹自笙歌彻晓闻。','',''),('quantangshi-16264','寄韦谏议','王建','quantangshi','','卷17','百年看似暂时间，头白求官亦未闲。
独有龙门韦谏议，三征不起恋青山。','',''),('quantangshi-16265','寻补阙旧宅','王建','quantangshi','','卷17','知得清名二十年，登山上坂乞新篇。
除书近拜侍臣去，空院鸟啼风竹前。','',''),('quantangshi-16266','初冬旅游','王建','quantangshi','','卷17','远投人宿趁房迟，僮仆伤寒马亦饥。
为客悠悠十月尽，庄头栽竹已过时。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-16267','江馆对雨','王建','quantangshi','','卷17','鸟声愁雨似秋天，病客思家一向眠。
草馆门临广州路，夜闻蛮语小江边。','',''),('quantangshi-16268','雨过山村','王建','quantangshi','','卷17','雨里鸡鸣一两家，竹溪村路板桥斜。
妇姑相唤浴蚕去，闲看中庭栀子花。','',''),('quantangshi-16269','山店','王建','quantangshi','','卷17','登登石路何时尽，决决溪泉到处闻。
风动叶声山犬吠，一家松火隔秋云。','',''),('quantangshi-16270','雨中寄东溪韦处士','王建','quantangshi','','卷17','雨中溪破无干地，浸着牀头湿着书。
一个月来山水隔，不知茅屋若为居。','',''),('quantangshi-16271','乞竹','王建','quantangshi','','卷17','乞取池西三两竿，房前栽着病时看。
亦知自惜难判割，犹胜横根引出栏。','',''),('quantangshi-16272','人家看花','王建','quantangshi','','卷17','年少狂疎逐君马，去来憔悴到京华。
恨无闲地栽仙药，长傍人家看好花。','',''),('quantangshi-16273','未央风','王建','quantangshi','','卷17','五更先起玉阶东，渐入千门万户中。
总向高楼吹舞袖，秋风还不及春风。','',''),('quantangshi-16274','归山庄','王建','quantangshi','','卷17','长安寄食半年余，重向人边乞荐书。
山路独归冲夜雪，落斜骑马避柴车。','',''),('quantangshi-16275','寒食忆归','王建','quantangshi','','卷17','京中曹局无多事，寒食贫儿要在家。
