不分君家新酒熟，好诗收得被回将。','',''),('quantangshi-16281','赠人二首 一','王建','quantangshi','','卷17','金炉烟里要班头，欲得归山可自由。
每度报朝愁入阁，在先教示小千牛。','',''),('quantangshi-16282','赠人二首 二','王建','quantangshi','','卷17','多在蓬莱少在家，越绯衫上有红霞。
朝回不向诸余处，骑马城西检校花。','',''),('quantangshi-16283','楼前','王建','quantangshi','','卷17','天宝年前勤政楼，每年三日作千秋。
飞龙老马曾教舞，闻着音声总举头。','',''),('quantangshi-16284','寄刘蕡问疾','王建','quantangshi','','卷17','年少病多应为酒，谁家将息过今春。
赊来半夏重熏尽，投着山中旧主人。','',''),('quantangshi-16285','听雨','王建','quantangshi','','卷17','半夜思家睡里愁，雨声落落屋檐头。
照泥星出依前黑，淹烂庭花不肯休。','',''),('quantangshi-16286','新晴','王建','quantangshi','','卷17','夏夜新晴星校少，雨收残水入天河。
