若无别事为留滞，应便抛家宿看来。','',''),('quantangshi-16293','江楼对雨寄杜书记','王建','quantangshi','','卷17','竹烟花雨细相和，看着闲书睡更多。
好是主人无事日，应持小酒按新歌。','',''),('quantangshi-16294','观蛮妓','王建','quantangshi','','卷17','欲说昭君歛翠蛾，清声委曲怨于歌。
谁家年少春风里，抛与金钱唱好多。','',''),('quantangshi-16295','送顾非熊秀才归丹阳','王建','quantangshi','','卷17','江城柳色海门烟，欲到茅山始下船。
知道君家当瀑布，菖蒲潭在草堂前。','',''),('quantangshi-16296','老人歌','王建','quantangshi','','卷17','白发老人垂泪行，上皇生日出京城。
如今供奉多新意，错唱当时一半声。','',''),('quantangshi-16297','和元郎中从八月十二至十五夜翫月五首 一','王建','quantangshi','','卷17','半秋初入中旬夜，已向堦前守月明。
从未圆时看却好，一分分见傍轮生。','',''),('quantangshi-16298','和元郎中从八月十二至十五夜翫月五首 二','王建','quantangshi','','卷17','乱云遮却台东月，不许教依次第看。
莫为诗家先见镜，被他宠与作艰难。','',''),('quantangshi-16299','和元郎中从八月十二至十五夜翫月五首 三','王建','quantangshi','','卷17','今夜月明胜昨夜，新添桂树近东枝。
