对时先奏牙间将，次第天恩与节旄。','',''),('quantangshi-16312','田侍郎归镇 三','王建','quantangshi','','卷17','踏着家乡马脚轻，暮山秋色眼前明。
老人上酒齐头拜，得侍中来尽再生。','',''),('quantangshi-16313','田侍郎归镇 四','王建','quantangshi','','卷17','功成谁不拥藩方，富贵还须是本乡。
