语多更觉承恩泽，数对君王忆陇山。','',''),('quantangshi-16404','宫词一百首 七十七','王建','quantangshi','','卷17','分朋闲坐赌樱桃，收却投壶玉腕劳。
各把沈香双陆子，局中鬬累阿谁高。','',''),('quantangshi-16405','宫词一百首 七十八','王建','quantangshi','','卷17','禁寺红楼内里通，笙歌引驾夹城东。
裹头宫监堂前立，手把牙鞘竹弹弓。','',''),('quantangshi-16406','宫词一百首 七十九','王建','quantangshi','','卷17','春风院院落花堆，金锁生衣掣不开。
更筑歌台起妆殿，明朝先进画图来。','',''),('quantangshi-16407','宫词一百首 八十','王建','quantangshi','','卷17','舞来汗湿罗衣彻，楼上人扶下玉梯。
归到院中重洗面，金花盆里泼银泥。','',''),('quantangshi-16408','宫词一百首 八十一','王建','quantangshi','','卷17','宿妆残粉未明天，总立昭阳花树边。
寒食内人长白打，库中先散与金钱。','',''),('quantangshi-16409','宫词一百首 八十二','王建','quantangshi','','卷17','众中偏得君王笑，偷把金箱笔砚开。
书破红蛮隔子上，旋推当直美人来。','',''),('quantangshi-16410','宫词一百首 八十三','王建','quantangshi','','卷17','敎遍宫娥唱遍词，暗中头白没人知。
楼中日日歌声好，不问从初学阿谁。','',''),('quantangshi-16411','宫词一百首 八十四','王建','quantangshi','','卷17','青楼小妇砑裙长，总被抄名入敎坊。
春设殿前多队舞，朋头各自请衣裳。','',''),('quantangshi-16412','宫词一百首 八十五','王建','quantangshi','','卷17','水中芹叶土中花，拾得还将避众家。
总待别人般数尽，袖中拈出郁金芽。','',''),('quantangshi-16413','宫词一百首 八十六','王建','quantangshi','','卷17','玉箫改调筝移柱，催换红罗绣舞筵。
未戴柘枝花帽子，两行宫监在帘前。','',''),('quantangshi-16414','宫词一百首 八十七','王建','quantangshi','','卷17','窗窗户户院相当，总有珠帘玳瑁牀。
虽道君王不来宿，帐中长是炷牙香。','',''),('quantangshi-16415','宫词一百首 八十八','王建','quantangshi','','卷17','雨入珠帘满殿凉，避风新出玉盆汤。
内人恐要秋衣着，不住熏笼换好香。','',''),('quantangshi-16416','宫词一百首 八十九','王建','quantangshi','','卷17','金吾除夜进傩名，画袴朱衣四队行。
院院烧灯如白日，沈香火底坐吹笙。','',''),('quantangshi-16417','宫词一百首 九十','王建','quantangshi','','卷17','树头树底觅残红，一片西飞一片东。
自是桃花贪结子，错敎人恨五更风。','',''),('quantangshi-16418','宫词一百首 九十一','王建','quantangshi','','卷17','金殿当头紫合重，仙人掌上玉芙蓉。
太平天子朝迎日，五色云车驾六龙。','',''),('quantangshi-16419','宫词一百首 九十二','王建','quantangshi','','卷17','鸳鸯瓦上瞥然声，昼寝宫娥梦里惊。
元是我王金弹子，海棠花下打流莺。','',''),('quantangshi-16420','宫词一百首 九十三','王建','quantangshi','','卷17','忽地金舆向月陂，内人接着便相随。
却回龙武军前过，当处敎开卧鸭池。','',''),('quantangshi-16421','宫词一百首 九十四','王建','quantangshi','','卷17','画作天河刻作牛，玉梭金镊采桥头。
每年宫里穿针夜，勑赐诸亲乞巧楼。','',''),('quantangshi-16422','宫词一百首 九十五','王建','quantangshi','','卷17','春来睡困不梳头，懒逐君王苑北游。
暂向玉花阶上坐，簸钱赢得两三筹。','',''),('quantangshi-16423','宫词一百首 九十六','王建','quantangshi','','卷17','步行送入长门里，不许来辞旧院花。
只恐他时身到此，乞恩求赦放还家。','',''),('quantangshi-16424','宫词一百首 九十七','王建','quantangshi','','卷17','缣罗不着索轻容，对面敎人染退红。
衫子成来一遍出，明朝半片在园中。','',''),('quantangshi-16425','宫词一百首 九十八','王建','quantangshi','','卷17','弹棋玉指两叁差，背局临虚鬬着危。
先打角头红子落，上三金字半边垂。','',''),('quantangshi-16426','宫词一百首 九十九','王建','quantangshi','','卷17','后宫宫女无多少，尽向园中笑一团。
舞蝶落花相觅着，春风共语亦应难。','',''),('quantangshi-16427','宫词一百首 一百','王建','quantangshi','','卷17','宛转黄金白柄长，青荷叶子画鸳鸯。
把来不是呈新样，欲进微风到御牀。','',''),('quantangshi-16428','宫词一百首 一百一','王建','quantangshi','','卷17','供御香方加减频，水沈山麝每回新。
内中不许相传出，已被医家写与人。','',''),('quantangshi-16429','宫词一百首 一百二','王建','quantangshi','','卷17','药童食后送云浆，高殿无风扇少凉。
每到日中重掠鬓，衩衣骑马绕宫廊。','',''),('quantangshi-16430','句','王建','quantangshi','','卷17','单于不向南牧马，席萁遍满天山下却公不易胜，莫着外家欺。
锦江诗弟子，时寄五花牋。
花烧落第眼，雨破到家程。
一朝金凤庭前下，当是虚皇诏沈曦。
宣城四面水茫茫，草盖江城竹夹墙。','',''),('quantangshi-16431','铜雀妓','劉商','quantangshi','','卷17','魏主矜蛾眉，美人美于玉。
高台无昼夜，歌舞竟未足。
盛色如转圜，夕阳落深谷。
仍令身殁后，尚纵平生欲。
红粉泪纵横，调弦向空屋。
举头君不在，惟见西陵木。
玉辇岂再来，娇鬟为谁绿。
那堪秋风里，更舞阳春曲。
曲罢情不胜，凭阑向西哭。
台边生野草，来去罥罗縠。
况复陵寝间，双双见麋鹿。','',''),('quantangshi-16432','哭韩淮端公兼上崔中丞','劉商','quantangshi','','卷17','坚贞与和璧，利用归干将。
金玉徒自宝，高贤无比方。
挺生岩松姿，孤直凌雪霜。
亭亭结清阴，不竞桃李芳。
读书哂霸业，翊赞思皇王。
千载有疑议，一言能否臧。
儒风久沦弊，颜闵寿不长。
邦国岂殄瘁，斯人今又亡。
别离长春草，存没隔楚乡。
闻问尚书恸，泪凝向日黄。
奄忽薤露曦，杳冥泉夜长。
贤愚自修短，天色空苍苍。
铭旌歛归魂，荆棘生路傍。
门柳日萧索，繐帷掩空堂。
灯孤晦处明，高节殁后彰。
芳兰已灰烬，幕府留余香。
常爱独坐尊，绣衣如雁行。
至今虚左位，言发泪霑裳。','',''),('quantangshi-16433','秋夜听严绅巴童唱竹枝歌','劉商','quantangshi','','卷17','巴人远从荆山客，回首荆山楚云隔。
思归夜唱竹枝歌，庭槐叶落秋风多。
曲中历历叙乡土，乡思绵绵楚词古。
身骑吴牛不畏虎，手提蓑笠欺风雨。
猨啼日暮江岸边，绿芜连山水连天。
来时十三今十五，一成新衣已再补。
鸿雁南飞报邻伍，在家欢乐辞家苦。
天晴露白钟漏迟，泪痕满面看竹枝。
曲终寒竹风袅袅，西方落日东方晓。','',''),('quantangshi-16434','乌夜啼','劉商','quantangshi','','卷17','遶树哑哑惊复栖，含烟碧树高枝齐。
月明露湿枝亦滑，城上女墙西月低。
愁人出户听乌啼，团团明月堕墙西。
月中有桂树，日中有伴侣。
何不上天去？一声啼到曙。','',''),('quantangshi-16435','随阳雁歌送兄南游','劉商','quantangshi','','卷17','塞鸿声声飞不住，终日南征向何处。
大漠穷阴多冱寒，分飞不得长怀安。
春去秋来年岁疾，湖南蓟北关山难。
寒飞万里胡天雪，夜度千门汉家月。
去住应多两地情，东西动作经年别。
南州风土复何如，春雁归时早寄书。','',''),('quantangshi-16436','赋得射雉歌送杨协律表弟赴婚期','劉商','quantangshi','','卷17','昔日才高容貌古，相敬如宾不相覩。
手奉苹蘩喜盛门，心知礼义感君恩。
三星照户春空尽，一树桃花竟不言。
结束车舆强游往，和风霁日东臯上。
鸾凤参差陌上行，麦苗萦陇雉初鸣。
修容尽饰将何益，极虑呈材欲导情。
六艺从师得机要，百发穿杨含绝妙。
白羽风驰碎锦毛，青娥怨处嫣然笑。
杨生词赋比潘郎，不似前贤貌不扬。
听调琴弄能和室，更解弯弧足自防。
秋深为尔持圆扇，莫忘鲁连飞一箭。','',''),('quantangshi-16437','泛舒城南溪赋得沙鹤歌奉饯张侍御赴河南元博士赴扬州拜觐仆射','劉商','quantangshi','','卷17','终日闾阎逐羣鸡，喜逢野鹤临清溪。
绿苔春水水中影，夜月平沙沙上栖。
惊谓汀洲白苹发，又疑曲渚前年雪。
紫顶昂藏肯狎人，一声嘹亮冲天阙。
素质翩翩带落晖，湖南渭阳相背飞。
东西分散别离促，宇宙苍茫相见稀。
皇华地仙如鹤驭，乘驾飘飘留不住。
延望乘虚入紫霞，陌头回首空烟树。
会使抟风羽翮轻，九霄云路随先鸣。','',''),('quantangshi-16438','姑苏怀古送秀才下第归江南','劉商','quantangshi','','卷17','姑苏台枕吴江水，层级鳞差向天倚。
秋高露白万林空，低望吴田三百里。
当时雄盛如何比，千仞无根立平地。
台前夹月吹玉鸾，台上迎凉撼金翠。
银河倒泻君王醉，滟酒峩冠眄西子。
宫娃酣态舞娉婷，香飙四飒青城坠。
伍员结舌长嘘嚱，忠谏无因到君耳。
城乌啼尽海霞销，深掩金屏日高睡。
王道潜隳伍员死，可叹斗间瞻王气。
会稽句践拥长矛，万马鸣蹄扫空垒。
瓦解冰销真可耻，凝艳妖芳安足恃。
可怜荒堞晚冥蒙，麋鹿呦呦达遗址。
君怀逸气还东吴，吟狂日日游姑苏。
兴来下笔到奇景，瑶盘迸洒蛟人珠。
大鹏矫翼翻云衢，嵩峰霁后凌天孤。
海潮秋打罗刹石，月魄夜当彭蠡湖。
有时凝思家虚无，霓幢彷佛游仙都。
琳琅暗戛玉华殿，天香静褭金芙蕖。
君声日下闻来久，清赡何人敢敌手。
我逃名迹遁西林，不得灞陵倾别酒。
莫便五湖为隐沦，年年三十升仙人。','',''),('quantangshi-16439','金井歌','劉商','quantangshi','','卷17','文明化洽天地清，和气氤氲孕至灵。
瑞雪不散抱层岭，阳谷霞光射山顶。
剃草披沙石窦开，生金曜日明金井。
虞衡相贺为祯祥，畏人采攫持殳戕。
羊驰马走尘满道，郡邸封章开建章。
君王俭德先简易，赡国肥家在仁义。
山泽藏金与万人，宣言郡邑无专利。
闾阎少长竞奔凑，黄金满袖家富有。
驩心蹈舞歌皇风，愿载讴歌青史中。','',''),('quantangshi-16440','柳条歌送客','劉商','quantangshi','','卷17','露井夭桃春未到，迟日犹寒柳开早。
高枝低枝飞鹂黄，千条万条覆宫墙。
几回离别折欲尽，一夜东风吹又长。
毵毵拂人行不进，依依送君无远近。
青春去住随柳条，却寄来人以为信。','',''),('quantangshi-16441','胡笳十八拍 第一拍','劉商','quantangshi','','卷17','汉室将衰兮四夷不宾，动干戈兮征战频。
哀哀父母生育我，见离乱兮当此辰。
纱窗对镜未经事，将谓珠帘能蔽身。
一朝胡骑入中国，苍黄处处逢胡人。
忽将薄命委锋镝，可惜红颜随虏尘。','',''),('quantangshi-16442','胡笳十八拍 第二拍','劉商','quantangshi','','卷17','马上将余向绝域，厌生求死死不得。
戎羯腥膻岂是人，豺狼喜怒难姑息。
行尽天山足霜霰，风土萧条近胡国。
万里重阴鸟不飞，寒沙莽莽无南北。','',''),('quantangshi-16443','胡笳十八拍 第三拍','劉商','quantangshi','','卷17','如羇囚兮在缧絏，忧虑万端无处说。
使余刀兮剪余发，食余肉兮饮余血。
诚知杀身愿如此，以余为妻不如死。
早被蛾眉累此身，空悲弱质柔如水。','',''),('quantangshi-16444','胡笳十八拍 第四拍','劉商','quantangshi','','卷17','山川路长谁记得，何处天涯是乡国。
自从惊怖少精神，不觉风霜损颜色。
夜中归梦来又去，朦胧岂解传消息。
漫漫胡天叫不闻，明明汉月应相识。','',''),('quantangshi-16445','胡笳十八拍 第五拍','劉商','quantangshi','','卷17','水头宿兮草头坐，风吹汉地衣裳破。
羊脂沐发长不梳，羔子皮裘领仍左。
狐襟貉袖腥复膻，昼披行兮夜披卧。
毡帐时移无定居，日月长兮不可过。','',''),('quantangshi-16446','胡笳十八拍 第六拍','劉商','quantangshi','','卷17','怪得春光不来久，胡中风土无花柳。
天翻地覆谁得知，如今正南看北斗。
姓名音信两不通，终日经年常闭口。
是非取与在指撝，言语传情不如手。','',''),('quantangshi-16447','胡笳十八拍 第七拍','劉商','quantangshi','','卷17','男儿妇人带弓箭，塞马蕃羊卧霜霰。
寸步东西岂自由，偷生乞死非情愿。
龟兹觱篥愁中听，碎叶琵琶夜深怨。
竟夕无云月上天，故乡应得重相见。','',''),('quantangshi-16448','胡笳十八拍 第八拍','劉商','quantangshi','','卷17','忆昔私家恣娇小，远取珍禽学驯扰。
如今沦弃念故乡，悔不当初放林表。
朔风萧萧寒日暮，星河寥落胡天晓。
旦夕思归不得归，愁心想似笼中鸟。','',''),('quantangshi-16449','胡笳十八拍 第九拍','劉商','quantangshi','','卷17','当日苏武单于问，道是宾鸿解传信。
学他刺血写得书，书上千重万重恨。
髯胡少年能走马，弯弓射飞无远近。
遂令边雁转怕人，绝域何由达方寸。','',''),('quantangshi-16450','胡笳十八拍 第十拍','劉商','quantangshi','','卷17','恨凌辱兮恶腥膻，憎胡地兮怨胡天。
生得胡儿欲弃捐，及生母子情宛然。
貌殊语异憎还爱，心中不觉常相牵。
朝朝暮暮在眼前，腹生手养宁不怜。','',''),('quantangshi-16451','胡笳十八拍 第十一拍','劉商','quantangshi','','卷17','日来月往相催迁，迢迢星岁欲周天。
无冬无夏卧霜霰，水冻草枯为一年。
汉家甲子有正朔，绝域三光空自悬。
几回鸿雁来又去，肠断蟾蜍亏复圆。','',''),('quantangshi-16452','胡笳十八拍 第十二拍','劉商','quantangshi','','卷17','破瓶落井空永沈，故乡望断无归心。
宁知远使问姓名，汉语泠泠传好音。
梦魂几度到乡国，觉后翻成哀怨深。
如今果是梦中事，喜过悲来情不任。','',''),('quantangshi-16453','胡笳十八拍 第十三拍','劉商','quantangshi','','卷17','童稚牵衣双在侧，将来不可留又忆。
还乡惜别两难分，宁弃胡儿归旧国。
山川万里复边戍，背面无由得消息。
泪痕满面对残阳，终日依依向南北。','',''),('quantangshi-16454','胡笳十八拍 第十四拍','劉商','quantangshi','','卷17','莫以胡儿可羞耻，恩情亦各言其子。
手中十指有长短，截之痛惜皆相似。
还乡岂不见亲族，念此飘零隔生死。
南风万里吹我心，心亦随风度辽水。','',''),('quantangshi-16455','胡笳十八拍 第十五拍','劉商','quantangshi','','卷17','叹息襟怀无定分，当时怨来归又恨。
不知愁怨情若何，似有锋铓扰方寸。
悲欢竝行情未快，心意相尤自相问。
不缘生得天属亲，岂向仇讐结恩信。','',''),('quantangshi-16456','胡笳十八拍 第十六拍','劉商','quantangshi','','卷17','去时只觉天苍苍，归日始知胡地长。
重阴白日落何处，秋雁所向应南方。
平沙四顾自迷惑，远近悠悠随雁行。
征途未尽马蹄尽，不见行人边草黄。','',''),('quantangshi-16457','胡笳十八拍 第十七拍','劉商','quantangshi','','卷17','行尽胡天千万里，唯见黄沙白云起。
马饥跑雪衔草根，人渴敲冰饮流水。
燕山仿髴辨烽戍，鼙鼓如闻汉家垒。
努力前程是帝乡，生前免向胡中死。','',''),('quantangshi-16458','胡笳十八拍 第十八拍','劉商','quantangshi','','卷17','归来故乡见亲族，田园半芜春草绿。
明烛重燃煨烬灰，寒泉更洗沈泥玉。
载持巾栉礼仪好，一弄丝桐生死足。
出入关山十二年，哀情尽在胡笳曲。','',''),('quantangshi-16459','杂言同豆卢郎中郭南七里桥哀悼姚仓曹','劉商','quantangshi','','卷17','桥边足离别，终日为悲辛。
登桥因叹逝，却羡别离人。
桥下东流水，芳树樱桃蘂。
流水与潮回，花落明年开。
可怜三语掾，长作九泉灰。
宿昔欢游在何处，花前饮足求仙去。','',''),('quantangshi-16460','春日卧病','劉商','quantangshi','','卷17','楚客经年病，孤舟人事稀。
晚晴江柳变，春暮塞鸿归。
今日方知命，前身自觉非。
不能忧岁计，无限故山薇。','',''),('quantangshi-16461','题禅居废寺','劉商','quantangshi','','卷17','凋残精舍在，连步访缁衣。
古殿门空掩，杨花雪乱飞。
鹤巢松影薄，僧少磬声稀。
青眼能留客，疎钟逼夜归。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-16462','题山寺','劉商','quantangshi','','卷17','扁舟水淼淼，曲岸复长塘。
古寺春山上，登楼忆故乡。
云烟横极浦，花木拥回廊。
更有思归意，晴明陟上方。','',''),('quantangshi-16463','题杨侍郎新亭','劉商','quantangshi','','卷17','毗陵过柱史，简易在茅茨。
芳草如花种，修篁带笋移。
径幽人未赏，檐静燕初窥。
野客怜霜壁，青松画一枝。','',''),('quantangshi-16464','同徐城季明府游重光寺题晃师壁','劉商','quantangshi','','卷17','野寺僧房远，陶潜引客来。
鸟喧残果落，兰败几花开。
真性知无住，微言欲望回。
竹风清磬晚，归策步苍苔。','',''),('quantangshi-16465','送林衮侍御东阳秩满赴上都','劉商','quantangshi','','卷17','几年乌府内，何处逐凫归。
关吏迷骢马，铜章累绣衣。
野亭山草绿，客路柳花飞。
况复长安远，音书从此稀。','',''),('quantangshi-16466','送人之江东','劉商','quantangshi','','卷17','含香仍佩玉，宜入镜中行。
尽室随乘兴，扁舟不计程。
渡江霖雨霁，对月夜潮生。
莫虑当炎暑，稽山水木清。','',''),('quantangshi-16467','送李元规昆季赴举','劉商','quantangshi','','卷17','见诵甘泉赋，心期折桂归。
凤雏皆五色，鸿渐又双飞。
别思看衰柳，秋风动客衣。
明朝问礼处，蹔觉雁行稀。','',''),('quantangshi-16468','送杨闲侍御拜命赴上都','劉商','quantangshi','','卷17','贺客移星使，丝纶出紫微。
手中霜作简，身上绣为衣。
骢马朝天疾，台乌向日飞。
亲朋皆避路，不是送人稀。','',''),('quantangshi-16469','赋得月下闻蛩送别','劉商','quantangshi','','卷17','物候改秋节，炎凉此夕分。
暗虫声徧草，明月夜无云。
清逈檐外见，凄其篱下闻。
感时兼惜别，羇思自纷纷。','',''),('quantangshi-16470','重阳日寄上饶李明府','劉商','quantangshi','','卷17','重阳秋雁未衔芦，始觉他乡节候殊。
旅馆但知闻蟋蟀，邮童不解献茱萸。
陶潜何处登高醉，倦客停桡一事无。
来岁公田多种黍，莫敎黄菊笑杨朱。','',''),('quantangshi-16471','同诸子哭张元易','劉商','quantangshi','','卷17','盛德高名总是空，神明福善大朦胧。
游魂永永无归日，流水年年自向东。
素帷旅榇乡关远，丹旐孤灯客舍中。
伯道共悲无后嗣，孀妻老母断根蓬。','',''),('quantangshi-16472','合肥至日愁中寄郑明府','劉商','quantangshi','','卷17','失计为卑吏，三年滞楚乡。
不能随世俗，应是昧行藏。
白璧空无玷，黄沙只自伤。
暮天乡思乱，晓镜鬓毛苍。
灰管移新律，穷阴变一阳。
岁时人共换，幽愤日先长。
拙宦惭知己，无媒悔自强。
迍邅羞薄命，恩惠费余光。
众口诚难称，长川却易防。
鱼竿今尚在，行此掉沧浪。','',''),('quantangshi-16473','送庐州贾使君拜命','劉商','quantangshi','','卷17','考绩朝称贵，时清武用文。
二天移外府，三命佐元勋。
佩玉兼高位，摐金阅上军。
威容冠是铁，图画阁名芸。
人咏甘棠茂，童谣竹马羣。
悬旌风肃肃，卧辙泪纷纷。
特达恩难报，升沈路易分。
侯嬴不得从，心逐信陵君。','',''),('quantangshi-16474','怨妇','劉商','quantangshi','','卷17','净扫黄金阶，飞霜皎如雪。
下帘弹箜篌，不忍见秋月。','',''),('quantangshi-16475','绿珠怨','劉商','quantangshi','','卷17','从来上台榭，不敢倚阑干。
零落知成血，高楼直下看。','',''),('quantangshi-16476','古意','劉商','quantangshi','','卷17','达晓寝衣冷，开帷霜露凝。
风吹昨夜泪，一片枕前冰。','',''),('quantangshi-16477','哭萧抡','劉商','quantangshi','','卷17','何处哭故人，青门水如箭。
当时水头别，从此不相见。','',''),('quantangshi-16478','送从弟赴上都','劉商','quantangshi','','卷17','车骑秦城远，囊装楚客贫。
月明思远道，诗罢诉何人。','',''),('quantangshi-16479','登相国寺阁','劉商','quantangshi','','卷17','晴日登临好，春风各望家。
垂杨夹城路，客思逐杨花。','',''),('quantangshi-16480','酬浚上人采药见寄','劉商','quantangshi','','卷17','玉英期共采，云岭独先过。
应得灵芝也，诗情一倍多。','',''),('quantangshi-16481','曲水寺枳实','劉商','quantangshi','','卷17','枳实遶僧房，攀枝置药囊。
洞庭山上橘，霜落也应黄。','',''),('quantangshi-16482','酬问师','劉商','quantangshi','','卷17','虚空无处所，仿髴似琉璃。
诗境何人到，禅心又过诗。','',''),('quantangshi-16483','殷秀才求诗','劉商','quantangshi','','卷17','倾盖见芳姿，晴天琼树枝。
连城犹隐石，唯有卞和知。','',''),('quantangshi-16484','行营即事','劉商','quantangshi','','卷17','万姓厌干戈，三边尚未和。
将军夸宝劒，功在杀人多。','',''),('quantangshi-16485','送刘寰北归','劉商','quantangshi','','卷17','南巢登望县城孤，半是青山半是湖。
知尔素多山水兴，此回归去更来无。','',''),('quantangshi-16486','送王閈归苏州','劉商','quantangshi','','卷17','深山穷谷没人来，邂逅相逢眼渐开。
云鹤洞宫君未到，夕阳帆影几时回。','',''),('quantangshi-16487','送人往虔州','劉商','quantangshi','','卷17','莫叹乘轺道路赊，高楼日日望还家。
人到南康皆下泪，唯君笑向此中花。','',''),('quantangshi-16488','送僧往湖南','劉商','quantangshi','','卷17','闲出东林日影斜，稻苗深浅映袈裟。
船到南湖风浪静，可怜秋水照莲花。','',''),('quantangshi-16489','送元使君自楚移越','劉商','quantangshi','','卷17','露冕行春向若耶，野人怀惠欲移家。
东风二月淮阴郡，唯见棠棃一树花。','',''),('quantangshi-16490','移居深山谢别亲故','劉商','quantangshi','','卷17','不食黄精不采薇，葛苗为带草为衣。
孤云更入深山去，人绝音书雁自飞。','',''),('quantangshi-16491','送王永二首 一','劉商','quantangshi','','卷17','君去春山谁共游，鸟啼花落水空流。
如今送别临溪水，他日相思来水头。','',''),('quantangshi-16492','送王永二首 二','劉商','quantangshi','','卷17','绵衣似热裌衣寒，时景虽和春已阑。
诚知暂别那惆怅，明日藤花独自看。','',''),('quantangshi-16493','送别','劉商','quantangshi','','卷17','灞岸青门有弊庐，昨来闻道半丘墟。
陌头空送长安使，旧里无人可寄书。','',''),('quantangshi-16494','送王贞','劉商','quantangshi','','卷17','清阳玉润复多才，邂逅佳期过早梅。
槿花亦可浮杯上，莫待东篱黄菊开。','',''),('quantangshi-16495','送薛六暂游扬州','劉商','quantangshi','','卷17','志在乘轩鸣玉珂，心期未快隐青萝。
广陵行路风尘合，城郭新秋砧杵多。','',''),('quantangshi-16496','送杨行元赴举','劉商','quantangshi','','卷17','晚渡邗沟惜别离，渐看烽火马行迟。
千钧何处穿杨叶，二月长安折桂枝。','',''),('quantangshi-16497','行营送人','劉商','quantangshi','','卷17','鞞鼓喧喧对古城，独寻归鸟马蹄轻。
回来看觅莺飞处，即是将军细柳营。','',''),('quantangshi-16498','滑州送人先归','劉商','quantangshi','','卷17','河水冰消雁北飞，寒衣未足又春衣。
自怜漂荡经年客，送别千回独未归。','',''),('quantangshi-16499','送浚上人','劉商','quantangshi','','卷17','木落前山霜露多，手持寒锡远头陀。
眼看庭树梅花发，不见诗人独咏歌。','',''),('quantangshi-16500','高邮送弟遇北游','劉商','quantangshi','','卷17','门临楚国舟船路，易见行人易别离。
今日送君心最恨，孤帆水下又风吹。','',''),('quantangshi-16501','送豆卢郎赴海陵','劉商','quantangshi','','卷17','烟波极目已霑襟，路出东塘水更深。
看取海头秋草色，一如江上别离心。','',''),('quantangshi-16502','送女子','劉商','quantangshi','','卷17','青娥宛宛聚为裳，乌鹊桥成别恨长。
惆怅梧桐非旧影，不悲鸿雁暂随阳。','',''),('quantangshi-16503','酬道芬寄昼松','劉商','quantangshi','','卷17','闻道铅华学沈宁，寒枝淅沥叶青青。
一株将比囊中树，若个年多有茯苓。','',''),('quantangshi-16504','山翁持酒相访以画松酬之','劉商','quantangshi','','卷17','白社风霜惊暮年，铜瓶桑落慰秋天。
怜君意厚留新画，不着松枝当酒钱。','',''),('quantangshi-16505','题潘师房','劉商','quantangshi','','卷17','渡水傍山寻石壁，白云飞处洞门开。
仙人来往行无迹，石径春风长绿苔。','',''),('quantangshi-16506','谢自然却还旧居','劉商','quantangshi','','卷17','仙侣招邀自有期，九天升降五云随。
不知辞罢虚皇日，更向人间住几时。','',''),('quantangshi-16507','寄李俌','劉商','quantangshi','','卷17','挂却衣冠披薜荔，世人应是笑狂愚。
年来渐觉髭须黑，欲寄松花君用无。','',''),('quantangshi-16508','赠头陀师','劉商','quantangshi','','卷17','少壮从戎马上飞，雪山童子未缁衣。
秋山年长头陀处，说我军前射虎归。','',''),('quantangshi-16509','赠严四草屦','劉商','quantangshi','','卷17','轻微菅蒯将何用，容足偷安事颇同。
日入信陵宾馆静，赠君闲步月明中。','',''),('quantangshi-16510','题刘偃庄','劉商','quantangshi','','卷17','何事退耕沧海畔，闲看富贵白云飞。
门前种稻三回熟，县里官人四考归。','',''),('quantangshi-16511','题黄陂夫人祠','劉商','quantangshi','','卷17','苍山云雨逐明神，唯有香名万岁春。
东风三月黄陂水，只见桃花不见人。','',''),('quantangshi-16512','题道济上人房','劉商','quantangshi','','卷17','何处营求出世间，心中无事即身闲。
门外水流风叶落，唯将定性对前山。','',''),('quantangshi-16513','棃树阴','劉商','quantangshi','','卷17','福庭人静少攀援，雨露偏滋影易繁。
磊落紫香香亚树，清阴满地昼当轩。','',''),('quantangshi-16514','秋蝉声','劉商','quantangshi','','卷17','萧条旅舍客心惊，断续僧房静又清。
借问蝉声何所为，人家古寺两般声。','',''),('quantangshi-16515','归山留别子侄二首 一','劉商','quantangshi','','卷17','车马驱驰人在世，东西南北鹤随云。
莫言贫病无留别，百代簪缨将付君。','',''),('quantangshi-16516','归山留别子侄二首 二','劉商','quantangshi','','卷17','不逐浮云不羡鱼，杏花茅屋向阳居。
鹤鸣华表应传语，雁度霜天懒寄书。','',''),('quantangshi-16517','与湛上人院画松','劉商','quantangshi','','卷17','水墨乍成岩下树，摧残半隐洞中[云]。
猷公曾住天台寺，阴雨猨声何处闻。','',''),('quantangshi-16518','白沙宿窦常宅观妓','劉商','quantangshi','','卷17','杨子澄江映晚霞，柳条垂岸一千家。
主人留客江边宿，十月繁霜见杏花。','',''),('quantangshi-16519','上巳日两县寮友会集时主邮不遂驰赴辄题以寄方寸','劉商','quantangshi','','卷17','踏青看竹共佳期，春水晴山祓禊词。
独坐邮亭心欲醉，樱桃落尽暮愁时。','',''),('quantangshi-16520','怀张璪','劉商','quantangshi','','卷17','苔石苍苍临涧水，阴风褭褭动松枝。
世间唯有张通会，流向衡阳那得知。','',''),('quantangshi-16521','与于中丞','劉商','quantangshi','','卷17','万顷荒临不敢看，买山容足拟求安。
田园失计全芜没，何处春风种蕙兰。','',''),('quantangshi-16522','袁十五远访山门','劉商','quantangshi','','卷17','僻居谋道不谋身，避病桃源不避秦。
远入青山何所见，寒花满径白头人。','',''),('quantangshi-16523','行营病中','劉商','quantangshi','','卷17','心许征南破虏归，可言羸病卧戎衣。
迟迟不见怜弓箭，惆怅秋鸿敢近飞。','',''),('quantangshi-16524','合溪水涨寄敬山人','劉商','quantangshi','','卷17','共爱碧溪临水住，相思来往践莓苔。
而今却欲嫌溪水，雨涨春流隔往来。','',''),('quantangshi-16525','不羡花','劉商','quantangshi','','卷17','惆怅朝阳午又斜，剩栽桃李学仙家。
花开花落人如旧，谁道容颜不及花。','',''),('quantangshi-16526','醉后','劉商','quantangshi','','卷17','春草秋风老此身，一瓢长醉任家贫。
醒来还爱浮萍草，漂寄官河不属人。','',''),('quantangshi-16527','题水洞二首 一','劉商','quantangshi','','卷17','桃花流出武陵洞，梦想仙家云树春。
今看水入洞中去，却是桃花源里人。','',''),('quantangshi-16528','题水洞二首 二','劉商','quantangshi','','卷17','长看岩穴泉流出，忽听悬泉入洞声。
莫摘山花抛水上，花浮出洞世人惊。','',''),('quantangshi-16529','代人村中悼亡二首 一','劉商','quantangshi','','卷17','花落茅檐转寂寥，魂随暮雨此中销。
迩来庭柳无人折，长得垂枝一万条。','',''),('quantangshi-16530','代人村中悼亡二首 二','劉商','quantangshi','','卷17','虚室无人乳燕飞，苍苔满地履痕稀。
庭前唯有蔷薇在，花似残妆叶似衣。','',''),('quantangshi-16531','观猎三首 一','劉商','quantangshi','','卷17','梦非熊虎数年间，驱尽豺狼宇宙闲。
传道单于闻校猎，相期不敢过阴山。','',''),('quantangshi-16532','观猎三首 二','劉商','quantangshi','','卷17','日隐寒山猎未归，鸣弦落羽雪霏霏。
梁园射尽南飞雁，淮楚人惊阳鸟啼。','',''),('quantangshi-16533','观猎三首 三','劉商','quantangshi','','卷17','松月东轩许独游，深恩未报复淹留。
梁园日暮从公猎，每过青山不举头。','',''),('quantangshi-16534','画石','劉商','quantangshi','','卷17','苍藓千年粉绘传，坚贞一片色犹全。
那知忽遇非常用，不把分铢补上天。','',''),('quantangshi-16535','咏双开莲花','劉商','quantangshi','','卷17','菡萏新花晓竝开，浓妆美笑面相隈。
西方采画迦陵鸟，早晚双飞池上来。','',''),('quantangshi-16536','夜闻邻管','劉商','quantangshi','','卷17','何事霜天月满空，鹂雏百啭向春风。
邻家思妇更长短，杨柳如丝在管中。','',''),('quantangshi-16537','山中寄元二侍御二首 一','劉商','quantangshi','','卷17','心期汗漫卧云扃，家计漂零水上萍。
桃李向秋雕落尽，一枝松色独青青。','',''),('quantangshi-16538','山中寄元二侍御二首 二','劉商','quantangshi','','卷17','拖紫锵金济世才，知君倚玉望三台。
深山穷谷无人到，唯有狂愚独自来。','',''),('quantangshi-16539','上崔十五老丈','劉商','quantangshi','','卷17','天汉乘槎可问津，寂寥深景到无因。
看花独往寻诗客，不为经时谒丈人。','',''),('quantangshi-16540','袁德师求画松','劉商','quantangshi','','卷17','柏偃松𢼮势自分，森梢古意出浮云。
如今眼暗画不得，旧有三株持赠君。','',''),('quantangshi-16541','早夏月夜问王开','劉商','quantangshi','','卷17','清风首夏夜犹寒，嫩笋侵阶竹数竿。
君向苏台长见月，不知何事此中看。','',''),('quantangshi-16542','裴十六厅即事','劉商','quantangshi','','卷17','主人能政讼庭闲，帆影云峰户牖间。
每到夕阳岚翠近，只言篱障倚前山。','',''),('quantangshi-16543','春日行营即事','劉商','quantangshi','','卷17','风引双旌马首齐，曹南战胜日平西。
为儒不解从戎事，花落春深闻鼓鼙。','',''),('quantangshi-16544','画树后呈浚师','劉商','quantangshi','','卷17','翔凤边风十月寒，苍山古木更摧残。
为君壁上画松柏，劲雪严霜君试看。','',''),('quantangshi-16545','吊从甥','劉商','quantangshi','','卷17','日晚河边访惸独，衰柳寒芜遶茅屋。
儿童惊走报人来，孀妇开门一声哭。','',''),('quantangshi-16546','句','劉商','quantangshi','','卷17','邮筒不解献茱萸。
赵侯首带鹿耳巾，规模出自陶弘景。','',''),('quantangshi-16547','登城楼作','陳翊','quantangshi','','卷17','井邑白云间，严城远带山。
沙墟阴欲暮，郊色淡方闲。
孤径回榕岸，层峦破枳关。
寥寥分远望，暂得一开颜。','',''),('quantangshi-16548','宴柏台','陳翊','quantangshi','','卷17','华台陈桂席，密榭宴清真。
柏叶犹霜气，桃花似汉津。
青尊照深夕，绿绮映芳春。
欲忆相逢后，无言岭海人。','',''),('quantangshi-16549','过马侍中亭','陳翊','quantangshi','','卷17','草色照双扉，轩车到客稀。
苔衣香屐迹，花绶少尘飞。
薄望怜池净，开畦爱雨肥。
相过忘日昃，坐待白云归。','',''),('quantangshi-16550','寄邵校书楚苌','陳翊','quantangshi','','卷17','爱酒时称僻，高情自不凡。
向人方白眼，违俗有青岩。
云际开三径，烟中挂一帆。
相期同岁晚，闲兴与松杉。','',''),('quantangshi-16551','龙池春草','陳翊','quantangshi','','卷17','青春光凤苑，细草徧龙池。
曲渚交苹叶，回塘惹柳枝。
因风初苒苒，覆岸欲离离。
色带金堤静，阴连玉树移。
日光浮靃靡，波影动参差。
岂比生幽远，芳馨众不知。','',''),('quantangshi-16552','郊行示友人','陳翊','quantangshi','','卷17','水开长镜引诸峦，春洞花深落翠寒。
醉向丝萝惊自醒，与君清耳听松湍。','',''),('quantangshi-16553','送别萧二','陳翊','quantangshi','','卷17','橘花香覆白苹洲，江引轻帆入远游。
千里云天风雨夕，忆君不敢再登楼。','',''),('quantangshi-16554','游仙','劉復','quantangshi','','卷17','税驾倚扶桑，逍遥望九州。
二老佐轩辕，移戈戮蚩尤。
功成弃之去，乘龙上天游。
天上见玉皇，寿与天地休。
俯视昆仑宫，五城十二楼。
王母何窈眇，玉质清且柔。
扬袂折琼枝，寄我天东头。
相思千万岁，大运浩悠悠。
安用知吾道，日月不能周。
寄音青鸟翼，谢尔碧海流。','',''),('quantangshi-16555','寺居清晨','劉復','quantangshi','','卷17','高枕对晓月，衣巾清且凉。
露华朝未曦，滴沥含虚光。
隔竹闻汲井，开扉见焚香。
幽心感衰病，结念依法王。
青冥早云飞，杳霭空鸟翔。
此情皆有释，悠然知所忘。','',''),('quantangshi-16556','出东城','劉復','quantangshi','','卷17','步出东城门，独行已旁徨。
伊洛泛清流，密林含朝阳。
芳景虽可瞩，忧怀在中肠。
人生几何时，苒苒随流光。
愿得心所亲，尊酒坐高堂。
一为浮沈隔，会合殊未央。
双戏水中凫，和鸣自翱翔。
我无此羽翼，安可以比方。','',''),('quantangshi-16557','经禁城','劉復','quantangshi','','卷17','日没路且长，游子欲涕零。
荒城无人路，秋草飞寒萤。
东南古丘墟，莽苍驰郊坰。
黄云晦断岸，枯井临崩亭。
昔人竟何之，穷泉独冥冥。
苍苔没碑版，朽骨无精灵。
俛仰寄世间，忽如流波萍。
金石非汝寿，浮生等臊腥。
不如学神仙，服食求丹经。','',''),('quantangshi-16558','出三城留别幕中三判官','劉復','quantangshi','','卷17','翔禽托高柯，倦客念主人。
恩义有所知，四海同一身。
况皆旷大姿，翰音见良辰。
陈规佐武略，高视据要津。
常愿投素诚，今果得所申。
金罍列四座，广厦无氛尘。
留连徂暑中，观望历数旬。
河山险以固，士卒勇且仁。
饬装去未归，相追越城闉。
愧无青玉案，缄佩永不泯。','',''),('quantangshi-16559','送刘秀才南归','劉復','quantangshi','','卷17','鸟啼杨柳垂，此别千万里。
古路入商山，春风生灞水。
停车落日在，罢酒离人起。
蓬户寄龙沙，送归情讵已。','',''),('quantangshi-16560','送王伦','劉復','quantangshi','','卷17','春江日未曛，楚客酣送君。
翩翩孤黄鹤，万里沧洲云。
四方各有志，岂得常顾羣。
山连巴湘远，水与荆吴分。
清光日修阻，尺素安可论。
相思寄梦寐，瑶草空氛氲。','',''),('quantangshi-16561','长相思','劉復','quantangshi','','卷17','长相思，在桂林，苍梧山远潇湘深。
秋堂零泪倚金瑟，朱颜摇落随光阴。
长宵嘹唳鸿命侣，河汉苍苍隔牛女。
宁知一水不可渡，况复万山修且阻。
彩丝织绮文双鸳，昔时赠君君可怜。
何言一去瓶落井，流尘歇灭金炉前。','',''),('quantangshi-16562','长歌行','劉復','quantangshi','','卷17','淮南木落秋云飞，楚宫商歌今正悲。
青春白日不与我，当垆举酒劝君持。
出门驱驰四方事，徒用辛勤不得意。
三山海底无见期，百龄世间莫虚弃。
君不见金城帝业汉家有，东制诸侯欲长久。
奸雄窃命风尘昏，函谷重关不能守。
龙蛇出没经两朝，胡虏凭陵大道销。
河水东流宫阙尽，五陵松柏自萧萧。','',''),('quantangshi-16563','春游曲','劉復','quantangshi','','卷17','春风戏狭斜，相见莫愁家。
细酌蒲桃酒，娇歌玉树花。
裁衫催白紵，迎客走朱车。
不觉重城暮，争栖柳上鵶。','',''),('quantangshi-16564','杂曲','劉復','quantangshi','','卷17','宝劒饰文犀，当风似切泥。
逢君感意气，贳酒杜陵西。
赵女颜虽少，宛驹齿正齐。
娇多不肯别，更待夜乌啼。','',''),('quantangshi-16565','春雨','劉復','quantangshi','','卷17','细雨度深闺，莺愁欲嬾啼。
如烟飞漠漠，似露湿凄凄。
草色行看靡，花枝暮欲低。
晓听钟鼓动，早送锦障泥。','',''),('quantangshi-16566','夕次襄邑','劉復','quantangshi','','卷17','何处成吾道，经年远路中。
客心犹向北，河水自归东。
古戍飘残角，疎林振夕风。
轻舟难载月，那与故人同。','',''),('quantangshi-16567','夏日','劉復','quantangshi','','卷17','暎日纱窗深且闲，含桃红日石榴殷。
银瓶绠转桐花井，沈水烟销金博山。
文簟象牀娇倚瑟，彩匳铜镜嬾拈环。
明朝戏去谁相伴，年少相逢狭路间。','',''),('quantangshi-16568','送黄晔明府岳州湘阴赴任','劉復','quantangshi','','卷17','拟占名塲第一科，龙门十上困风波。
三年护塞从戎远，万里投荒失意多。
花县到时铜墨贵，叶舟行处水云和。
遥知布惠苏民后，应向祠堂吊汨罗。','',''),('quantangshi-16569','禅门寺暮钟','劉復','quantangshi','','卷17','簨簴高悬于阗钟，黄昏发地殷龙宫。
游人忆到嵩山夜，叠阁连楼满太空。','',''),('quantangshi-16570','同张深秀才游华严寺','冷朝陽','quantangshi','','卷17','同游云外寺，渡水入禅关。
立埽窗前石，坐看池上山。
有僧飞锡到，留客话松间。
不是缘名利，好来长伴闲。','',''),('quantangshi-16571','中秋与空上人同宿华严寺','冷朝陽','quantangshi','','卷17','埽榻相逢宿，论诗旧梵宫。
磬声迎鼓尽，月色过山穷。
庭簇安禅草，窗飞带火虫。
一宵何惜别，回首隔秋风。','',''),('quantangshi-16572','宿柏岩寺','冷朝陽','quantangshi','','卷17','幽寺在岩中，行唯一径通。
客吟孤峤月，蝉噪数枝风。
秋色生苔砌，泉声入梵宫。
吾师修道处，不与世间同。','',''),('quantangshi-16573','登灵善寺塔','冷朝陽','quantangshi','','卷17','飞阁青霞里，先秋独早凉。
天花映窗近，月桂拂檐香。
华岳三峰小，黄河一带长。
空闻指归路，烟处有垂杨。','',''),('quantangshi-16574','瀑布泉','冷朝陽','quantangshi','','卷17','潺湲半空里，霖落石房边。
风激珠光碎，山欹练影偏。
急流难起浪，迸沫祗如烟。
自古惟今日，凄凉一片泉。','',''),('quantangshi-16575','冬日逢冯法曹话怀','冷朝陽','quantangshi','','卷17','分襟二年内，多少事相干。
礼乐风全变，尘埃路渐难。
秋林新叶落，霜月满庭寒。
虽喜逢知己，他乡岁又阑。','',''),('quantangshi-16576','送唐六赴举','冷朝陽','quantangshi','','卷17','秋色生边思，送君西入关。
草衰空大野，叶落露青山。
故国烟霞外，新安道路间。
碧霄知己在，香桂月中攀。','',''),('quantangshi-16577','送远上人归京','冷朝陽','quantangshi','','卷17','夏腊岁方深，思归彻曙吟。
未离销雪院，已有过云心。
寒磬清函谷，孤钟宿华阴。
别京游旧寺，月色似双林。','',''),('quantangshi-16578','别郎上人','冷朝陽','quantangshi','','卷17','过云寻释子，话别更依依。
静室开来久，游人到自稀。
触风香气尽，隔水磬声微。
独傍孤松立，尘中多是非。','',''),('quantangshi-16579','立春','冷朝陽','quantangshi','','卷17','玉律传佳节，青阳应此辰。
土牛呈岁稔，彩燕表年春。
腊尽星回次，寒余月建寅。
风光行处好，云物望中新。
流水初销冻，潜鱼欲振鳞。
梅花将柳色，偏思越乡人。','',''),('quantangshi-16580','送红线','冷朝陽','quantangshi','','卷17','采菱歌怨木兰舟，送客魂销百尺楼。
还似洛妃乘雾去，碧天无际水空流。','',''),('quantangshi-16581','南至日太史登台书云物','于尹躬','quantangshi','','卷17','至日行时令，登台约礼文。
官称伯赵氏，色辨五方云。
昼漏听初发，阳光望渐分。
司天为岁备，持简出人羣。
惠爱周微物，生灵荷圣君。
长当有嘉瑞，郁郁复纷纷。','',''),('quantangshi-16582','赠别二首 一','柳郴','quantangshi','','卷17','江浦程千里，离尊泪数行。
无论吴与楚，俱是客他乡。','',''),('quantangshi-16583','赠别二首 二','柳郴','quantangshi','','卷17','何处最悲辛，长亭临古津。
往来舟檝路，前后别离人。','',''),('quantangshi-16584','句','柳郴','quantangshi','','卷17','他乡生白发，旧国有青山。','',''),('quantangshi-16585','望终南春雪','李子卿','quantangshi','','卷17','山势抱西秦，初年瑞雪频。
色摇鹑野霁，影落凤城春。
辉耀银峰逼，晶明玉树亲。
尚寒由气劲，不夜为光新。
荆岫全疑近，昆丘宛合邻。
余辉傥可借，回照读书人。','',''),('quantangshi-16586','九日登青山','朱灣','quantangshi','','卷17','昔人惆怅处，系马又登临。
旧地烟霞在，多时草木深。
水将空合色，云与我无心。
想见龙山会，良辰亦似今。','',''),('quantangshi-16587','秋夜宴王郎中宅赋得露中菊','朱灣','quantangshi','','卷17','众芳春竞发，寒菊露偏滋。
受气何曾异，开花独自迟。
晚成犹待赏，欲采未过时。
忍弃东篱下，看随秋草衰。','',''),('quantangshi-16588','奉使设宴戏掷笼筹','朱灣','quantangshi','','卷17','今日陪樽俎，良筹复在兹。
献酬君有礼，赏罚我无私。
莫怪斜相向，还将正自持。
一朝权入手，看取令行时。','',''),('quantangshi-16589','咏双陆骰子','朱灣','quantangshi','','卷17','采采应缘白，钻心不为名。
掌中犹可重，手下莫言轻。
有对唯求敌，无私直任争。
君看一掷后，当取擅场声。','',''),('quantangshi-16590','咏壁上酒瓢呈萧明府','朱灣','quantangshi','','卷17','不是难提挈，行藏固有期。
安身未得所，开口欲从谁。
应物心无倦，当垆柄会持。
莫将成废器，还有对樽时。','',''),('quantangshi-16591','咏玉','朱灣','quantangshi','','卷17','歌玉屡招疑，终朝省复思。
既哀黄鸟兴，还复白圭诗。
请益先求友，将行必择师。
谁知不鸣者，独下董生帷。','',''),('quantangshi-16592','送陈偃赋得白鸟翔翠微','朱灣','quantangshi','','卷17','不知鸥与鹤，天畔弄晴晖。
背日分明见，临川相暎微。
净中云一点，回处雪孤飞。
正好南枝住，翩翩何所归。','',''),('quantangshi-16593','题段上人院壁画古松','朱灣','quantangshi','','卷17','石上盘古根，谓言天生有。
安知草木性，变在画师手。
阴深方丈间，直趣幽且闲。
木纹离披势搓捽，中裂空心火烧出。
扫成三寸五寸枝，便是千年万年物。
莓苔浓淡色不同，一面死皮生蠹虫。
风霜未必来到此，气色杳在寒山中。
孤标可玩不可取，能使支公道场古。','',''),('quantangshi-16594','逼寒节寄崔七','朱灣','quantangshi','','卷17','闲庭只是长莓苔，三径曾无车马来。
旅馆尚愁寒食火，羁心嬾向不然灰。
门前下客虽弹铗，溪畔穷鱼且曝腮。
他日趋庭应问礼，须言陋巷有颜回。','',''),('quantangshi-16595','长安喜雪','朱灣','quantangshi','','卷17','千门万户雪花浮，点点无声落瓦沟。
全似玉尘消更积，半成冰片结还流。
光含晓色清天苑，轻逐微风遶御楼。
平地已霑盈尺润，年丰须荷富人侯。','',''),('quantangshi-16596','宴杨驸马山亭','朱灣','quantangshi','','卷17','垂杨拂岸草茸茸，绣户窗前花影重。
鲙下玉盘红缕细，酒开金瓮绿醅浓。
中朝驸马何平叔，南国词人陆士龙。
落日泛舟同醉处，回潭百丈映千峰。','',''),('quantangshi-16597','过宣上人湖上兰若','朱灣','quantangshi','','卷17','十年湖上结幽期，偏向东林遇远师。
未道姓名童子识，不酬言语上人知。
闲花落日滋苔径，细雨和烟着柳枝。
问我别来何所得，解将无事当无为。','',''),('quantangshi-16598','同达奚宰游窦子明仙坛','朱灣','quantangshi','','卷17','松桧阴深一径微，中峰石室到人稀。
仙官不住青山在，故老相传白日飞。
华表问栽何岁木，片云留着去时衣。
今朝茂宰寻真处，暂驻双凫且莫归。','',''),('quantangshi-16599','平陵寓居再逢寒食','朱灣','quantangshi','','卷17','几回江上泣途穷，每遇良辰叹转蓬。
火燧知从新节变，灰心还与故人同。
莫听黄鸟愁啼处，自有花开久客中。
贫病固应无挠事，但将怀抱醉春风。','',''),('quantangshi-16600','寻隐者韦九山人于东溪草堂','朱灣','quantangshi','','卷17','寻得仙源访隐沦，渐来深处渐无尘。
初行竹裹唯通马，直到花间始见人。
四面云山谁作主，数家烟火自为邻。
路傍樵客何须问，朝市如今不是秦。','',''),('quantangshi-16601','假摄池州留别东溪隐居','朱灣','quantangshi','','卷17','一官仍是假，岂愿数离羣。
愁鬓看如雪，浮名认是云。
暂辞南国隐，莫勒北山文。
今后松溪月，还应梦见君。','',''),('quantangshi-16602','咏柏板','朱灣','quantangshi','','卷17','赴节心长在，从绳道可观。
须知片木用，莫向散材看。
空为歌偏苦，仍愁和即难。
既能亲掌握，愿得接同欢。','',''),('quantangshi-16603','筝柱子','朱灣','quantangshi','','卷17','散木今何幸，良工不弃捐。
力微慙一柱，材薄仰羣弦。
且喜声相应，宁辞迹屡迁。
知音如见赏，雅调为君传。','',''),('quantangshi-16604','送李司直归浙东幕兼寄鲍行军持节大夫初拜东平郡王','朱灣','quantangshi','','卷17','翩翩书记早曾闻，二十年来愿见君。
今日相逢悲白发，同时几许在青云。
人从北固山边去，水到西陵渡口分。
会作王门曳裙客，为余前谢鲍参军。','',''),('quantangshi-16605','七贤庙','朱灣','quantangshi','','卷17','常慕晋高士，放心日沈冥。
湛然对一壶，土木为我形。
下马访陈迹，披榛诣荒庭。
相看两不言，犹谓醉未醒。
长啸或可拟，幽琴难再听。
同心不共世，空见藓门青。','',''),('quantangshi-16606','同清江师月夜听坚正二上人为怀州转法华经歌','朱灣','quantangshi','','卷17','若耶溪畔云门僧，夜闲燕坐听真乘。
莲花祕偈药草喻，二师身住口不住。
凿井求泉会到源，闭门避火终迷路。
前心后心皆此心，梵音妙音柔软音。
清泠霜磬有时动，寂历空堂宜夜深。
向来不寐何所事，一念才生百虑息。
风翻乱叶林有声，雪映闲庭月无色。
玄关密迹难可思，醒人悟兮醉人疑。
衣中系宝觉者谁，临川内史字得之。','',''),('quantangshi-16607','寒城晚角','朱灣','quantangshi','','卷17','高台高高画角雄，五更初发寒城中。
寒城北临大河水，淇门贼烽隔岸是。
长风送过黎阳川，我军气雄贼心死。
羇人此夜寐不成，万里边情枕上生。
乍似陇头戍，寒泉幽咽流不住。
又如巴江头，啼猨带雨断续愁。
忽忆嫖姚北征伐，空山宿兵寒对月。
一声老将起，三奏行人发。
冀马为之嘶，朔云为之结。
二十年来天下兵，到处不曾无此声。
洛阳陌，长安路。
角声朝朝兼暮暮，平居闻之尚难度。
何况天山征戍儿，云中下营雪里吹。','',''),('quantangshi-16608','重阳日陪韦卿宴','朱灣','quantangshi','','卷17','何必龙山好，南亭赏不暌。
清规陈侯事，雅兴谢公题。
入座青峰近，当轩远树齐。
仙家自有月，莫叹夕阳西。','',''),('quantangshi-16609','忆长安 四月','丘丹','quantangshi','','卷17','忆长安，四月时，南郊万乘旌旗。
尝酎玉巵更献，含桃丝笼交驰。
芳草落花无限，金张许史相随。','',''),('quantangshi-16610','状江南 季冬','丘丹','quantangshi','','卷17','江南季冬月，红蟹大如𤬊。
湖水龙为镜，炉峰气作烟。','',''),('quantangshi-16611','和韦使君秋夜见寄','丘丹','quantangshi','','卷17','露滴梧叶鸣，秋风桂花发。
中有学仙侣，吹箫弄山月。','',''),('quantangshi-16612','奉酬韦苏州使君','丘丹','quantangshi','','卷17','久作烟霞侣，蹔将簪组亲。
还同褚伯玉，入馆忝州人。','',''),('quantangshi-16613','和韦使君听江笛送陈侍御','丘丹','quantangshi','','卷17','离樽闻夜笛，寥亮入寒城。
月落车马散，凄恻主人情。','',''),('quantangshi-16614','奉酬韦使君送归山之作','丘丹','quantangshi','','卷17','侧闻郡守至，偶乘黄犊出。
不别桃源人，一见经累日。
蝉鸣念秋稼，兰酌动离瑟。
临水降麾幢，野艇才容膝。
参差碧山路，目送江帆疾。
涉海得骊珠，栖梧惭凤质。
愧非郑公里，归扫蒙笼室。','',''),('quantangshi-16615','奉酬重送归山','丘丹','quantangshi','','卷17','卖药有时至，自知来往疎。
遽辞池上酌，新得山中书。
步出芙蓉府，归乘觳𧥆车。
猥蒙招隐作，岂愧班生庐。','',''),('quantangshi-16616','经湛长史草堂','丘丹','quantangshi','','卷17','身退谢名累，道存嘉止足。
设醴降华幡，挂冠守空谷。
偶寻野外寺，仰慕贤者躅。
不见昔簪裾，犹有旧松竹。
烟霞虽异世，风韵如在瞩。
余即江海上，归辙青山曲。','',''),('quantangshi-16617','萧山祗园寺','丘丹','quantangshi','','卷17','东晋许徴君，西方彦上人。
生时犹定见，悟后了前因。
灵塔多年古，高僧苦行频。
碑存才记日，藤老岂知春。
车骑归萧詧，云林识许询。
千秋不相见，悟定是吾身。','',''),('quantangshi-16618','奉使过石门观瀑','丘丹','quantangshi','','卷17','溪上望悬泉，耿耿云中见。
披榛上岩岫，峭壁正东面。
千仞泻联珠，一潭喷飞霰。
嵯𤄓满山响，坐觉炎氛变。
照日类虹霓，从风似绡练。
灵奇既天造，惜处穷海甸。
吾祖昔登临，谢公亦游衍。
王程惧淹泊，下磴空延眷。
千里雷尚闻，峦回树葱蒨。
此来共贱役，探讨愧前彦。
永欲洗尘缨，终当惬此愿。','',''),('quantangshi-16619','秋夕宿石门馆','丘丹','quantangshi','','卷17','暝从石门宿，摇落四岩空。
潭月漾山足，天河泻涧中。
杉松寒似雨，猨鸟夕惊风。
独卧不成寝，苍然想谢公。','',''),('quantangshi-16620','状江南 孟夏','賈弇','quantangshi','','卷17','江南孟夏天，慈竹笋如编。
蜃气为楼阁，蛙声作管弦。','',''),('quantangshi-16621','状江南 仲秋','沈仲昌','quantangshi','','卷17','江南仲秋天，鱏鼻大如船。
雷是樟亭浪，苔为界石钱。','',''),('quantangshi-16622','忆长安 正月','謝良輔','quantangshi','','卷17','忆长安，正月时，和风喜气相随。
献寿彤庭万国，烧灯青玉五枝。
终南往往残雪，渭水处处流澌。','',''),('quantangshi-16623','忆长安 十二月','謝良輔','quantangshi','','卷17','忆长安，腊月时，温泉彩仗新移。
瑞气遥迎凤辇，日光先暖龙池。
取酒虾蟇陵下，家家守岁传巵。','',''),('quantangshi-16624','状江南 仲春','謝良輔','quantangshi','','卷17','江南仲春天，细雨色如烟。
丝为武昌柳，布作石门泉。','',''),('quantangshi-16625','状江南 孟冬','謝良輔','quantangshi','','卷17','江南孟冬天，荻穗软如绵。
绿绢芭蕉裂，黄金橘柚悬。','',''),('quantangshi-16626','忆长安 二月','鮑防','quantangshi','','卷17','忆长安，二月时，玄鸟初至禖祠。
百啭宫莺绣羽，千条御柳黄丝。
更有曲江胜地，此来寒食佳期。','',''),('quantangshi-16627','状江南 孟春','鮑防','quantangshi','','卷17','江南孟春天，荇叶大如钱。
白[雪]装梅树，青袍似葑田。','',''),('quantangshi-16628','杂感','鮑防','quantangshi','','卷17','汉家海内承平久，万国戎王皆稽首。
天马常衔苜蓿花，胡人岁献葡萄酒。
五月荔枝初破颜，朝离象郡夕函关。
雁飞不到桂阳岭，马走先过林邑山。
甘泉御果垂仙阁，日暮无人香自落。
远物皆重近皆轻，鸡虽有德不如鹤。','',''),('quantangshi-16629','送薛补阙入朝','鮑防','quantangshi','','卷17','平原门下十余人，独受恩多未杀身。
每叹陆家兄弟少，更怜杨氏子孙贫。
柴门岂断施行马，鲁酒那堪醉近臣。
赖有军中遗令在，犹将谈笑对风尘。','',''),('quantangshi-16630','人日陪宣州范中丞传正与范侍御传真宴东峰亭','鮑防','quantangshi','','卷17','人日春风绽早梅，谢家兄弟看花来。
吴姬对酒歌千曲，秦女留人酒百杯。
丝柳向空轻婉转，玉山看日渐裴回。
流光易去懽难得，莫厌频频上此台。','',''),('quantangshi-16631','上巳寄孟中丞','鮑防','quantangshi','','卷17','世间禊事风流处，镜里云山若画屏。
今日会稽王内史，好将宾客醉兰亭。','',''),('quantangshi-16632','秋暮忆中秋夜与王璠侍御赏月因怆远离聊以奉寄','鮑防','quantangshi','','卷17','前月月明夜，美人同远光。
清尘一以间，今夕坐相忘。
风落芙蓉露，疑余绣被香。','',''),('quantangshi-16633','元日早朝行','鮑防','quantangshi','','卷17','干元发生春为宗，盛德在木斗建东。
东方岁星大明宫，南山喜气摇晴空。
望云五等舞万玉，献寿一声出千峰。
文昌随彩礼乐正，太平下直旌旗红。
师旷应律调黄钟，王良运策调时龙。
玄冥无事归朔土，青帝放身入朱宫。
九韶九变五声里，四方四友一身中。
天何言哉乐无穷，广成彭祖为三公。
野臣潜随击壤老，日下鼓腹歌可封。','',''),('quantangshi-16634','忆长安 三月','杜奕','quantangshi','','卷17','忆长安，三月时，上苑遍是花枝。
青门几场送客，曲水竟日题诗。
骏马金鞭无数，良辰美景追随。','',''),('quantangshi-16635','忆长安 六月','鄭概','quantangshi','','卷17','忆长安，六月时，风台水榭逶迤。
朱果雕笼香透，分明紫禁寒随。
尘惊九衢客散，赭珂滴沥青骊。','',''),('quantangshi-16636','状江南 孟秋','鄭概','quantangshi','','卷17','江南孟秋天，稻花白如毡。
素腕慙新藕，残妆妒晚莲。','',''),('quantangshi-16637','忆长安 七月','陳元初','quantangshi','','卷17','忆长安，七月时，槐花点散罘罳。
七夕针楼竞出，中元香供初移。
绣毂金鞍无限，游人处处归迟。','',''),('quantangshi-16638','忆长安 八月','呂渭','quantangshi','','卷17','忆长安，八月时，阙下天高旧仪。
衣冠共颁金镜，犀象对舞丹墀。
更爱终南灞上，可怜秋草碧滋。','',''),('quantangshi-16639','状江南 仲冬','呂渭','quantangshi','','卷17','江南仲冬天，紫蔗节如鞭。
海将盐作雪，山用火耕田。','',''),('quantangshi-16640','贞元十一年知贡举挠阁不能定去留寄诗前主司','呂渭','quantangshi','','卷17','独坐贡闱里，愁多芳草生。
仙翁昨日事，应见此时情。','',''),('quantangshi-16641','皇帝移晦日为中和节','呂渭','quantangshi','','卷17','皇心不向晦，改节号中和。
淑气同风景，嘉名别咏歌。
湔裙移旧俗，赐尺下新科。
历象千年正，酺醵四海多。
花随春令发，鸿度岁阳过。
天地齐休庆，欢声欲荡波。','',''),('quantangshi-16642','经湛长史草堂','呂渭','quantangshi','','卷17','岩居旧风景，人世今成昔。
木落古山空，猨啼秋月白。
谁同西府僚，几谢南平客。
摧残松桂老，萧散烟云夕。
迹留异代远，境入空门寂。
惟有草堂僧，陈诗在石壁。','',''),('quantangshi-16643','忆长安 九月','范燈','quantangshi','','卷17','忆长安，九月时，登高望见昆池。
上苑初开露菊，芳林正献霜梨。
更想千门万户，[月]明砧杵参差。','',''),('quantangshi-16644','状江南 季夏','范燈','quantangshi','','卷17','江南季夏天，身热汗如泉。
蚊蚋成雷泽，袈裟作水田。','',''),('quantangshi-16645','忆长安 十月','樊珣','quantangshi','','卷17','忆长安，十月时，华清士马相驰。
万国来朝汉阙，五陵共猎秦祠。
昼夜歌钟不歇，山河四塞京师。','',''),('quantangshi-16646','状江南 仲夏','樊珣','quantangshi','','卷17','江南仲夏天，时雨下如川。
卢橘垂金弹，甘蕉吐白莲。','',''),('quantangshi-16647','忆长安 十一月','劉蕃','quantangshi','','卷17','忆长安，子月时，千官贺至丹墀。
御苑雪开琼树，龙堂冰作瑶池。
兽炭毡炉正好，貂裘狐白相宜。','',''),('quantangshi-16648','状江南 季秋','劉蕃','quantangshi','','卷17','江南季秋天，栗熟大如拳。
枫叶红霞举，苍芦白浪川。','',''),('quantangshi-16649','太寥歌','張志和','quantangshi','','卷17','化元灵哉，碧虚清哉。
红霞明哉，冥哉茫哉，惟化之工无彊哉。','',''),('quantangshi-16650','空洞歌','張志和','quantangshi','','卷17','无自而然，自然之元。
无造而化，造化之端。
廓然慤然，其形团圞。
反尔之视，绝尔之思，可以观。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-16651','渔父歌 一','張志和','quantangshi','','卷17','西塞山前白鹭飞，桃花流水鳜鱼肥。
青箬笠，绿蓑衣，斜风细雨不须归。','',''),('quantangshi-16652','渔父歌 二','張志和','quantangshi','','卷17','钓台渔父褐为裘，两两三三舴艋舟。
能纵棹，惯乘流，长江白浪不曾忧。','',''),('quantangshi-16653','渔父歌 三','張志和','quantangshi','','卷17','霅溪湾里钓渔翁，舴艋为家西复东。
江上雪，浦边风，笑着荷衣不叹穷。','',''),('quantangshi-16654','渔父歌 四','張志和','quantangshi','','卷17','松江蟹舍主人欢，菰饭莼羹亦共餐。
枫叶落，荻花干，醉宿渔舟不觉寒。','',''),('quantangshi-16655','渔父歌 五','張志和','quantangshi','','卷17','青草湖中月正圆，巴陵渔父棹歌连。
钓车子，橛头船，乐在风波不用仙。','',''),('quantangshi-16656','上巳日忆江南禊事','張志和','quantangshi','','卷17','黄河西绕郡城流，上巳应无祓禊游。
为忆渌江春水色，更随宵梦向吴洲。','',''),('quantangshi-16657','渔父','張志和','quantangshi','','卷17','八月九月芦花飞，南溪老人垂钓归。
秋山入帘翠滴滴，野艇倚槛云依依。
却把渔竿寻小径，闲梳鹤发对斜晖。
翻嫌四皓曾多事，出为储皇定是非。','',''),('quantangshi-16658','和答弟志和渔父歌','張松齡','quantangshi','','卷17','乐是风波钓是闲，草堂松径已胜攀。
太湖水，洞庭山，狂风浪起且须还。','',''),('quantangshi-16659','歌','陸羽','quantangshi','','卷17','不羡黄金罍，不羡白玉杯。
不羡朝入省，不羡暮入台。
惟羡西江水，曾向金陵城下来。','',''),('quantangshi-16660','会稽东小山','陸羽','quantangshi','','卷17','月色寒潮入剡溪，青猨叫断绿林西。
昔人已逐东流去，空见年年江草齐。','',''),('quantangshi-16661','句','陸羽','quantangshi','','卷17','辟彊旧林间，怪石纷相向。
绝涧方险寻，乱岩亦危造。
泻从千仞石，寄逐九江船。','',''),('quantangshi-16662','寒食寄李补阙','郭鄖','quantangshi','','卷17','兰陵士女满晴川，郊外纷纷拜古埏。
万井闾阎皆禁火，九原松柏自生烟。
人间后事悲前事，镜里今年老去年。
介子终知禄不及，王孙谁肯一相怜。','',''),('quantangshi-16663','仲月赏花','韋同則','quantangshi','','卷17','梅花似雪柳含烟，南地风光腊月前。
把酒且须拼却醉，风流何必待歌筵。','',''),('quantangshi-16664','西亭暇日书怀十二韵献上相公','李夷簡','quantangshi','','卷17','胜赏不在远，怃然念玄搜。
兹亭有殊致，经始富人侯。
澄澹分沼沚，萦回间林丘。
荷香夺芳麝，石溜当鸣球。
抚俗来康济，经邦去咨谋。
宽明洽时论，惠爱闻甿讴。
代斵岂容易，守成获优游。
文翁旧学校，子产昔田畴。
琬琰富佳什，池台想旧游。
谁言矜改作，曾是日增修。
宪省忝陪属，岷峨嗣徽猷。
提携当有路，勿使滞刀州。','',''),('quantangshi-16665','城南访裴氏昆季','李約','quantangshi','','卷17','相思起中夜，夙驾访柴荆。
早雾桑柘隐，晓光溪涧明。
村蹊嵩棘间，往往断新耕。
贫野烟火微，昼无乌鸢声。
田头逢饷人，道君南山行。
南山千里峰，尽是相思情。
野老无拜揖，村童多躶形。
相呼看车马，颜色喜相惊。
荒圃鸡豚乐，雨墙禾莠生。
欲君知我来，壁上空书名。','',''),('quantangshi-16666','岁日感怀','李約','quantangshi','','卷17','曙气变东风，蟾壶夜漏穷。
新春几人老，旧历四时空。
身贱悲添岁，家贫喜过冬。
称觞惟有感，欢庆在儿童。','',''),('quantangshi-16667','从军行三首 一','李約','quantangshi','','卷17','看图闲敎阵，画地静论边。
乌垒天西戍，鹰姿塞上川。
路长唯算月，书远每题年。
无复生还望，翻思未别前。','',''),('quantangshi-16668','从军行三首 二','李約','quantangshi','','卷17','栅壕三面鬬，箭尽举烽频。
营柳和烟暮，关榆带雪春。
边城多老将，碛路少归人。
杀尽金河卒，年年添塞尘。','',''),('quantangshi-16669','从军行三首 三','李約','quantangshi','','卷17','候火起雕城，尘沙拥战声。
游军藏汉帜，降骑说蕃情。
霜落滹沱浅，秋深太白明。
嫖姚方虎视，不觉说添兵。','',''),('quantangshi-16670','赠韦况','李約','quantangshi','','卷17','我有心中事，不与韦三说。
秋夜洛阳城，明月照张八。','',''),('quantangshi-16671','观祈雨','李約','quantangshi','','卷17','桑条无叶土生烟，箫管迎龙水庙前。
朱门几处看歌舞，犹恐春阴咽管弦。','',''),('quantangshi-16672','江南春','李約','quantangshi','','卷17','池塘春暖水纹开，堤柳垂丝间野梅。
江上年年芳意早，蓬瀛春色逐潮来。','',''),('quantangshi-16673','过华清宫','李約','quantangshi','','卷17','君王游乐万机轻，一曲霓裳四海兵。
玉辇升天人已尽，故宫犹有树长生。','',''),('quantangshi-16674','病中宿宜阳馆闻雨','李約','quantangshi','','卷17','难眠夏夜抵秋赊，帘幔深垂窗烛斜。
风吹桐竹更无雨，白发病人心到家。','',''),('quantangshi-16675','江南曲','于鵠','quantangshi','','卷17','偶向江边采白苹，还随女伴赛江神。
众中不敢分明语，暗掷金钱卜远人。','',''),('quantangshi-16676','山中寄樊仆射','于鵠','quantangshi','','卷17','却忆东溪日，同年事鲁儒。
僧房闲共宿，酒肆醉相扶。
天畔双旌贵，山中病客孤。
无谋还有计，春谷种桑榆。','',''),('quantangshi-16677','题宇文𧚞山寺读书院','于鵠','quantangshi','','卷17','读书林下寺，不出动经年。
草阁连僧院，山厨共石泉。
云庭无履迹，龛壁有灯烟。
年少今头白，删诗到几篇。','',''),('quantangshi-16678','赠兰若僧','于鵠','quantangshi','','卷17','一身禅诵苦，洒扫古花宫。
静室门常闭，深萝月不通。
悬灯乔木上，鸣磬乱幡中。
附入高僧传，长称二远公。','',''),('quantangshi-16679','题邻居','于鵠','quantangshi','','卷17','僻巷邻家少，茅檐喜竝居。
蒸梨常共竈，浇薤亦同渠。
传屐朝寻药，分灯夜读书。
虽然在城市，还得似樵渔。','',''),('quantangshi-16680','山中自述','于鵠','quantangshi','','卷17','三十无名客，空山独卧秋。
病多知药性，年长信人愁。
萤影竹窗下，松声茅屋头。
近来心更静，不梦世间游。','',''),('quantangshi-16681','山中寄韦钲','于鵠','quantangshi','','卷17','嬾成身病日，因醉卧多时。
送客出溪少，读书终卷迟。
幽窗闻坠叶，晴景见游丝。
早晚来收药，门前有紫芝。','',''),('quantangshi-16682','南溪书斋','于鵠','quantangshi','','卷17','茅屋往来久，山深不置门。
草生垂井口，花落拥篱根。
入院将雏鸟，寻萝抱子猿。
曾逢异人说，风景似桃源。','',''),('quantangshi-16683','夜会李太守宅','于鵠','quantangshi','','卷17','郡斋常夜埽，不卧独吟诗。
把烛近幽客，升堂戴接䍦。
微风吹冻叶，余雪落寒枝。
明日逢山伴，须令隐者知。','',''),('quantangshi-16684','题柏台山僧','于鵠','quantangshi','','卷17','上方唯一室，禅定对山容。
行道临孤壁，持斋听远钟。
枯藤离旧树，朽石落高峰。
不向云间见，还应梦里逢。','',''),('quantangshi-16685','寄续尊师','于鵠','quantangshi','','卷17','得道任发白，亦逢城市游。
新经天上取，稀药洞中收。
春木带枯叶，新蒲生漫流。
年年望灵鹤，常在此山头。','',''),('quantangshi-16686','题南峰褚道士','于鵠','quantangshi','','卷17','得道南山久，曾敎四皓碁。
闭门医病鹤，倒箧养神龟。
松际风长在，泉中草不衰。
谁知茅屋里，有路向峨嵋。','',''),('quantangshi-16687','赠不食姑','于鵠','quantangshi','','卷17','不食非关药，天生是女仙。
见人还起拜，留伴亦开田。
无窟寻溪宿，兼衣扫叶眠。
不知何代女，犹带剪刀钱。','',''),('quantangshi-16688','送李明府归别业','于鵠','quantangshi','','卷17','寄家丹水边，归去种春田。
白发无知己，空山又一年。
鹿裘长酒气，茅屋有茶烟。
亦拟辞人世，何溪有瀑泉。','',''),('quantangshi-16689','题树下禅师','于鵠','quantangshi','','卷17','久行多不定，树下是禅牀。
寂寂心无住，年年日自长。
虫虵同宿磵，草木共经霜。
已见南人说，天台有旧房。','',''),('quantangshi-16690','宿王尊师隐居','于鵠','quantangshi','','卷17','夜爱云林好，寒天月里行。
青牛眠树影，白犬吠猨声。
一磬山院静，千灯溪路明。
从来此峰客，几个得长生。','',''),('quantangshi-16691','题服柏先生','于鵠','quantangshi','','卷17','服柏不飞炼，闲眠闭草堂。
有泉唯盥漱，留火为焚香。
新雨闲门静，孤松满院凉。
仍闻枕中术，曾授汉淮王。','',''),('quantangshi-16692','哭凌霄山光上人','于鵠','quantangshi','','卷17','身没碧峰里，门人改葬期。
买山寻主远，垒塔化人迟。
鬼火穿空院，秋萤入素帷。
黄昏溪路上，闻哭竺干师。','',''),('quantangshi-16693','途中寄杨涉','于鵠','quantangshi','','卷17','萧萧芦荻晚，一迳入荒陂。
日色云收处，蛙声雨歇时。
前村见来久，羸马自行迟。
闻作王门客，应闲白接䍦。','',''),('quantangshi-16694','送韦判官归蓟门','于鵠','quantangshi','','卷17','桑干归路远，闻说亦愁人。
有雪常经夏，无花空到春。
下营云外火，收马月中尘。
白首从戎客，青衫未离身。','',''),('quantangshi-16695','出塞 一','于鵠','quantangshi','','卷17','葱岭秋尘起，全军取月支。
山川引行阵，蕃汉列旌旗。
转战疲兵少，孤城外救迟。
边人逢圣代，不见偃戈时。','',''),('quantangshi-16696','出塞 二','于鵠','quantangshi','','卷17','微雪军将出，吹笳天未明。
观兵登古戍，斩将对双旌。
分阵瞻山势，潜兵制马鸣。
如今青史上，已有灭胡名。','',''),('quantangshi-16697','出塞 三','于鵠','quantangshi','','卷17','单于骄爱猎，放火到军城。
乘月调新马，防秋置远营。
空山朱戟影，寒碛铁衣声。
度水逢胡说，沙阴有伏兵。','',''),('quantangshi-16698','赠李太守','于鵠','quantangshi','','卷17','几年为郡守，家似布衣贫。
沽酒迎幽客，无金与近臣。
捣茶书院静，讲易药堂春。
归阙功成后，随车有野人。','',''),('quantangshi-16699','送张司直入单于','于鵠','quantangshi','','卷17','若过并州北，谁人不忆家。
塞深无伴侣，路尽有平沙。
碛冷唯逢雁，天春不见花。
莫随征将意，垂老事轻车。','',''),('quantangshi-16700','惜花','于鵠','quantangshi','','卷17','夜来花欲尽，始惜两三枝。
早起寻稀处，闲眠记落时。
蘂焦蜂自散，蔕折蝶还移。
攀着殷勤别，明年更有期。','',''),('quantangshi-16701','春山居','于鵠','quantangshi','','卷17','独来多任性，唯与白云期。
深处花开尽，迟眠人不知。
水流山暗处，风起月明时。
望见南峰近，年年嬾更移。','',''),('quantangshi-16702','游瀑泉寺','于鵠','quantangshi','','卷17','日夕寻未遍，古木寺高低。
粉壁犹遮岭，朱楼尚隔溪。
厨窗通涧鼠，殿迹立山鸡。
更有无人处，明朝独向西。','',''),('quantangshi-16703','送宫人入道归山','于鵠','quantangshi','','卷17','十岁吹萧入汉宫，看修水殿种芙蓉。
自伤白发辞金屋，许着黄衣向玉峰。
解语老猨开晓户，学飞雏鹤落高松。
定知别后宫中伴，应听缑山半夜钟。','',''),('quantangshi-16704','巴女谣','于鵠','quantangshi','','卷17','巴女骑牛唱竹枝，藕丝菱叶傍江时。
不愁日暮还家错，记得芭蕉出槿篱。','',''),('quantangshi-16705','公子行','于鵠','quantangshi','','卷17','少年初拜大长秋，半醉垂鞭见列侯。
马上抱鸡三市鬬，袖中携劒五陵游。
玉箫金管迎归院，锦袖红妆拥上楼。
更向院西新买宅，月波春水入门流。','',''),('quantangshi-16706','长安游','于鵠','quantangshi','','卷17','久卧长安春复秋，五侯长乐客长愁。
绣帘朱毂逢花住，锦幨银珂触雨游。
何处少年吹玉笛，谁家鹦鹉语红楼。
年年只是看他贵，不及南山任白头。','',''),('quantangshi-16707','别齐太守','于鵠','quantangshi','','卷17','花里南楼春夜寒，还如王屋上天坛。
归山不道无明月，谁共相从到晓看。','',''),('quantangshi-16708','登古城','于鵠','quantangshi','','卷17','独上闲城却下迟，秋山惨惨冢累累。
当时还有登城者，荒草如今知是谁。','',''),('quantangshi-16709','哭刘夫子','于鵠','quantangshi','','卷17','近问南州客，云亡已数春。
痛心曾受业，追服恨无亲。
孀妇归乡里，书斋属四邻。
不知经乱后，奠祭有何人。','',''),('quantangshi-16710','醉后寄山中友人','于鵠','quantangshi','','卷17','昨日山家春酒浓，野人相劝久从容。
独忆卸冠眠细草，不知谁送出深松。
都忘醉后逢廉度，不省归时见鲁恭。
知己尚嫌身酩酊，路人应恐笑龙钟。','',''),('quantangshi-16711','温泉僧房','于鵠','quantangshi','','卷17','云里前朝寺，修行独几年。
山村无施食，盥漱亦安禅。
古塔巢溪鸟，深房闭谷泉。
自言曾入室，知处梵王天。','',''),('quantangshi-16712','题美人','于鵠','quantangshi','','卷17','秦女窥人不解羞，攀花趁蝶出墙头。
胸前空带宜男草，嫁得萧郎爱远游。','',''),('quantangshi-16713','寻李暹','于鵠','quantangshi','','卷17','任性常多出，人来得见稀。
市楼逢酒住，野寺送僧归。
檐下悬秋叶，篱头晒褐衣。
门前南北路，谁肯入柴扉。','',''),('quantangshi-16714','寻李逸人旧居','于鵠','quantangshi','','卷17','旧隐松林下，冲泉入两涯。
琴书随弟子，鸡犬在邻家。
茅屋长黄菌，槿篱生白花。
幽坟无处访，恐是入烟霞。','',''),('quantangshi-16715','赠碧玉','于鵠','quantangshi','','卷17','新绣笼裙豆蔲花，路人笑上返金车。
霓裳禁曲无人解，暗问梨园弟子家。','',''),('quantangshi-16716','舟中月明夜闻笛','于鵠','quantangshi','','卷17','浦里移舟候信风，芦花漠漠夜江空。
更深何处人吹笛，疑是孤吟寒水中。','',''),('quantangshi-16717','送迁客二首 一','于鵠','quantangshi','','卷17','得罪谁人送，来时不到家。
白头无侍子，多病向天涯。
莽苍凌江水，黄昏见塞花。
如今贾谊赋，不漫说长沙。','',''),('quantangshi-16718','送迁客二首 二','于鵠','quantangshi','','卷17','流人何处去，万里向江州。
孤驿瘴烟重，行人巴草秋。
上帆南去远，送雁北看愁。
遍问炎方客，无人得白头。','',''),('quantangshi-16719','赠王道者','于鵠','quantangshi','','卷17','去寻长不出，门似绝人行。
牀下石苔满，屋头秋草生。
学琴寒月短，写易晚窗明。
唯到黄昏后，溪中闻磬声。','',''),('quantangshi-16720','题合溪干洞','于鵠','quantangshi','','卷17','渡水傍山寻绝壁，白云飞处洞天开。
仙人来往行无迹，石径春风长绿苔。','',''),('quantangshi-16721','过张老园林','于鵠','quantangshi','','卷17','身老无修饰，头巾用白纱。
开门朝扫径，辇水夜浇花。
药气闻深巷，桐阴到数家。
不愁还酒债，腰下有丹砂。','',''),('quantangshi-16722','寓意','于鵠','quantangshi','','卷17','自小看花长不足，江边寻得数株红。
黄昏人散东风起，吹落谁家明月中。','',''),('quantangshi-16723','哭王都护','于鵠','quantangshi','','卷17','老将明王识，临终拜上公。
告哀乡路远，助葬戍城空。
素幔朱门里，铭旌秋巷中。
史官如不滥，独传说英雄。','',''),('quantangshi-16724','饯司农宋卿立太尉碑了还江东','于鵠','quantangshi','','卷17','追立新碑日，怜君苦一身。
远移深涧石，助立故乡人。
草色荒坟绿，松阴古殿春。
平生心已遂，归去得垂纶。','',''),('quantangshi-16725','送唐大夫让节归山','于鵠','quantangshi','','卷17','年老功成乞罢兵，玉阶匍匐进双旌。
朱门鸳瓦为仙观，白领狐裘出帝城。
侍女休梳官样髻，蕃童新改道家名。
到时浸发春泉里，犹梦红楼箫管声。','',''),('quantangshi-16726','买山吟','于鵠','quantangshi','','卷17','买得幽山属汉阳，槿篱疎处种桄榔。
唯有猕猴来往熟，弄人抛果满书堂。','',''),('quantangshi-16727','古词三首 一','于鵠','quantangshi','','卷17','素丝带金地，窗间掬飞尘。
偷得凤凰钗，门前乞行人。','',''),('quantangshi-16728','古词三首 二','于鵠','quantangshi','','卷17','新长青丝发，哑哑言语黠。
随人敲铜镜，街头救明月。','',''),('quantangshi-16729','古词三首 三','于鵠','quantangshi','','卷17','东家新长儿，与妾同时生。
竝长两心熟，到大相呼名。','',''),('quantangshi-16730','秦越人洞中咏','于鵠','quantangshi','','卷17','扁鹊得仙处，传是西南峰。
年年山下人，长见骑白龙。
洞门黑无底，日夜唯雷风。
清斋将入时，戴星兼抱松。
石径阴且寒，地响知远钟。
似行山林外，闻叶履声重。
低碍更俯身，渐远昼夜同。
时时白蝙蝠，飞入茅衣中。
行久路转窄，静闻水淙淙。
但愿逢一人，自得朝天宫。','',''),('quantangshi-16731','宿西山修下元斋咏','于鵠','quantangshi','','卷17','幽人在何处，松桧深冥冥。
西峰望紫云，知处安期生。
沐浴溪水暖，新衣礼仙名。
脱屐入静堂，遶像随礼行。
碧纱笼寒灯，长幡缀金铃。
林下听法人，起坐枯叶声。
启奏修律仪，天曙山鸟鸣。
分行布菅茅，列坐满中庭。
持斋候撞钟，玉函散宝经。
焚香开卷时，照耀金室明。
投简石洞深，称过上帝灵。
学道能苦心，自古无不成。','',''),('quantangshi-16732','过凌霄洞天谒张先生祠','于鵠','quantangshi','','卷17','戢戢乱峰里，一峰独凌天。
下看如尖高，上有十里泉。
志人爱幽深，一住五十年。
悬牍到其上，乘牛耕药田。
衣食不下求，乃是云中仙。
山僧独知处，相引冲碧烟。
断崖昼昏黑，槎臬横只椽。
面壁攀石棱，养力方敢前。
累歇日已没，始到茅堂边。
见客不问谁，礼质无周旋。
醉卧枕欹树，寒坐展青毡。
折松扫藜牀，秋菓颜色鲜。
炼蜜敲石炭，洗澡乘瀑泉。
白犬舐客衣，惊走闻腥膻。
乃知轩冕徒，宁比云壑眠。','',''),('quantangshi-16733','早上凌霄第六峰入紫溪礼白鹤观祠','于鵠','quantangshi','','卷17','路转第六峰，传是十里程。
放石试浅深，䃂壁虵鸟惊。
欲下先襞衣，路底避枯茎。
回途歇嵌窟，整带重冠缨。
及到紫石溪，暗暗已天明。
渐近神仙居，桂花湿溟溟。
阴苔无人踪，时得白鹤翎。
忽然见朱楼，象牌题玉京。
沈沈五云影，香风散萦萦。
清斋上玉堂，窗户悬水精。
青童撞金屑，杵臼声丁丁。
膻腥遥问谁，稽首称姓名。
若容在溪口，愿乞残云英。','',''),('quantangshi-16734','山中访道者','于鵠','quantangshi','','卷17','触烟入溪口，岸岸唯柽栎。
其中尽碧流，十里不通屐。
出林山始转，绝径缘峭壁。
把藤借行势，侧足凭石脉。
㰹牙断行处，光滑猿猱迹。
忽然风景异，乃到神仙宅。
天晴茅屋头，残云蒸气白。
隔窗梳发声，久立闻吹笛。
抱琴出门来，不顾人间客。
山院不洒扫，四时自虚寂。
落叶埋长松，出地才数尺。
曾读上清经，知注长生籍。
愿示不死方，何山有琼液。','',''),('quantangshi-16735','寄卢俨员外秋衣词','于鵠','quantangshi','','卷17','寄远空以心，心诚亦难知。
箧中有秋帛，裁作远客衣。
缝制虽女功，尺度手自持。
容貌常目中，长短不复疑。
斜缝密且坚，游客多尘缁。
意欲都无言，澣濯耐岁时。
殷勤托行人，传语慎勿遗。
别来年已老，亦闻鬓成丝。
纵然更相逢，握手唯是悲。
所寄莫复弃，愿见长相思。','',''),('quantangshi-16736','种树','于鵠','quantangshi','','卷17','一树新栽益四邻，野夫如到旧山春。
树成多是人先老，垂白看他攀折人。','',''),('quantangshi-16737','哭李暹','于鵠','quantangshi','','卷17','驱马街中哭送君，灵车碾雪隔城闻。
唯有山僧与樵客，共舁孤榇入幽坟。','',''),('quantangshi-16738','古挽歌 一','于鵠','quantangshi','','卷17','双辙出郭门，绵绵东西道。
送死多于生，几人得终老。
见此切肺肝，不如归山好。
不闻哀哭声，默默安怀抱。
时尽从物化，又免生忧扰。
世间寿者稀，尽为悲伤恼。','',''),('quantangshi-16739','古挽歌 二','于鵠','quantangshi','','卷17','送哭谁家车，灵幡紫带长。
青童抱何物，明月与香囊。
可惜罗衣色，看舁入水泉。
莫愁埏道暗，烧漆得千年。','',''),('quantangshi-16740','古挽歌 三','于鵠','quantangshi','','卷17','阴风吹黄蒿，挽歌度秋水。
车马却归城，孤坟月明里。','',''),('quantangshi-16741','悼孩子','于鵠','quantangshi','','卷17','年长始一男，心亦颇自娱。
生来岁未周，奄然却归无。
裸送不以衣，瘗埋于中衢。
乳母抱出门，所生亦随呼。
婴孩无哭仪，礼经不可逾。
亲戚相问时，抑悲空叹吁。
襁褓在旧牀，每见立踟蹰。
静思益伤情，畏老为独夫。','',''),('quantangshi-16742','别旧山','于鵠','quantangshi','','卷17','旧伴同游尽却回，云中独宿守花开。
自是去人身渐老，暮山流水任东来。','',''),('quantangshi-16743','寄周恽','于鵠','quantangshi','','卷17','家在荒陂长似秋，蓼花芹叶水虫幽。
去年相伴寻山客，明月今宵何处游。','',''),('quantangshi-16744','野田行','于鵠','quantangshi','','卷17','日暮出古城，野田何茫茫。
寒狐上孤冢，鬼火烧白杨。
昔人未为泉下客，若到此中还断肠。','',''),('quantangshi-16745','塞上曲','于鵠','quantangshi','','卷17','行人朝走马，直走蓟城傍。
蓟城通汉北，万里别吴乡。
海上一烽火，沙中百战场。
军书发上郡，春色度河阳。
袅袅汉宫柳，青青胡地桑。
琵琶出塞曲，横笛断君肠。','',''),('quantangshi-16746','襄阳寒食','于鵠','quantangshi','','卷17','烟水初销见万家，东风吹柳万条斜。
大堤欲上谁相伴，马踏春泥半是花。','',''),('quantangshi-16747','泛舟入后溪','于鵠','quantangshi','','卷17','雨余芳草净沙尘，水绿沙平一带春。
唯有啼鹃似留客，桃花深处更无人。','',''),('quantangshi-16748','宝劒篇','劉長川','quantangshi','','卷17','宝劒不可得，相逢几许难。
今朝一度见，赤色照人寒。
匣里星文动，环边月影残。
自然神鬼伏，无事莫空弹。','',''),('quantangshi-16749','将赴东都上李相公','劉長川','quantangshi','','卷17','四海兵初偃，平津阁正开。
谁知大炉下，还有不然灰。','',''),('quantangshi-16750','寄邢逸人','鄭常','quantangshi','','卷17','羡君无外事，日与世情违。
地僻人难到，溪深鸟自飞。
儒衣荷叶老，野饭药苗肥。
畴昔江湖意，而今忆共归。','',''),('quantangshi-16751','送头陀上人赴庐山寺','鄭常','quantangshi','','卷17','僧家无住着，早晚出东林。
得道非真相，头陀是苦心。
持斋山果熟，倚锡野云深。
溪寺谁相待，香花与梵音。','',''),('quantangshi-16752','谪居汉阳白沙口阻雨因题驿亭','鄭常','quantangshi','','卷17','汉阳无远近，见说过湓城。
云雨经春客，江山几日程。
终随鸥鸟去，秖待海潮生。
前路逢渔父，多惭问姓名。','',''),('quantangshi-16753','穆陵路','陳存','quantangshi','','卷17','西游匣长劒，日暮湘楚间。
歇马上秋草，逢人问故关。
孤村绿塘水，旷野白云山。
方念此中去，何时此路还。','',''),('quantangshi-16754','清溪馆作','陳存','quantangshi','','卷17','指途清溪里，左右唯深林。
云蔽望乡处，雨愁为客心。
遇人多物役，听鸟时幽音。
何必沧浪水，庶兹浣尘襟。','',''),('quantangshi-16755','寓居武丁馆','陳存','quantangshi','','卷17','暑雨飘已过，凉飙触幽衿。
虚馆无喧尘，绿槐多昼阴。
俯视古苔积，仰聆早蝉吟。
放卷一长想，闭门千里心。','',''),('quantangshi-16756','楚州赠别周愿侍御','陳存','quantangshi','','卷17','漂泊楚水来，舍舟坐高馆。
途穷在中路，孤征慕前伴。
风雨一留宿，关山去欲嬾。
淮南木叶飞，夜闻广陵散。','',''),('quantangshi-16757','送刘秀才南归','陳存','quantangshi','','卷17','鸟啼杨柳垂，此别千万里。
古路入商山，春风去灞水。
停车落日在，罢酒离人起。
蓬户寄龙沙，送归情讵已。','',''),('quantangshi-16758','丹阳作','陳存','quantangshi','','卷17','暂入新丰市，犹闻旧酒香。
抱琴沽一醉，尽日卧垂杨。','',''),('quantangshi-16759','早行','王觀','quantangshi','','卷17','鸡唱催人起，又生前去愁。
路明残月在，山露宿云收。
村店烟火动，渔家灯烛幽。
趋名与趋利，行役几时休。','',''),('quantangshi-16760','赠营妓','崔瓘','quantangshi','','卷17','寒檐寂寂雨霏霏，候馆萧条烛烬微。
只有今宵同此宴，翠娥佯醉欲先归。','',''),('quantangshi-16761','酒席赋得匏瓢','鄭審','quantangshi','','卷17','华阁与贤开。
仙瓢自远来，幽林尝伴许。
陋巷亦随回，挂影怜红壁。
倾心向绿杯，何曾斟酌处。
不使玉山颓。','',''),('quantangshi-16762','奉使巡检两京路种果树事毕入秦因咏','鄭審','quantangshi','','卷17','圣德周天壤，韶华满帝畿。
九重承涣汗，千里树芳菲。
陜塞余阴薄，关河旧色微。
发生和气动，封植众心归。
春露条应弱，秋霜果定肥。
影移行子盖，香扑使臣衣。
入迳迷驰道，分行接禁闱。
何当扈仙跸，攀折奉恩辉。','',''),('quantangshi-16763','丹阳作','朱彬','quantangshi','','卷17','暂入新丰市，犹闻旧酒香。
抱琴沽一醉，尽日卧垂杨。','',''),('quantangshi-16764','采桑','李彥遠','quantangshi','','卷17','采桑畏日高，不待春眠足。
攀条有余态，那矜貌如玉。
千金岂不赠，五马空踯躅。
何以变真性，幽篁雪中绿。','',''),('quantangshi-16765','章仇公席上咏真珠姬','范元凱','quantangshi','','卷17','神女初离碧玉阶，彤云犹拥牡丹鞋。
应知子建怜罗袜，顾步裴回拾翠钗。','',''),('quantangshi-16766','烂柯山四首 一','劉迥','quantangshi','','卷17','白云引策仗，苔径谁往还。
渐见松树偃，时闻鸟声闲。
豁然喧氛尽，独对万重山。','',''),('quantangshi-16767','烂柯山四首 二','劉迥','quantangshi','','卷17','石桥架绝壑，苍翠横鸟道。
凭槛云脚下，颓阳日犹蚤。
霓裳倘一遇，千载长不老。','',''),('quantangshi-16768','烂柯山四首 三','劉迥','quantangshi','','卷17','灵境偶一寻，洞天碧云上。
烂柯有遗迹，羽客何由访。
日暮怅欲还，晴烟满千嶂。','',''),('quantangshi-16769','烂柯山四首 四','劉迥','quantangshi','','卷17','绳牀宴坐久，石窟绝行迹。
能在人代中，遂将人代隔。
白云风扬飞，非欲待归客。','',''),('quantangshi-16770','前年春与独孤常州兄花时为别倏已三年矣今莺花又尔覩物增怀因之抒情聊以奉寄','李幼卿','quantangshi','','卷17','近日霜毛一番新，别时芳草两回春。
不堪花落花开处，况是江南江北人。
薄宦龙钟心懒慢，故山寥落水奫沦。
缘君爱我疵瑕少，愿窃仁风寄老身。','',''),('quantangshi-16771','游烂柯山四首 一','李幼卿','quantangshi','','卷17','拂雾理孤策，薄霄眺层岑。
迥升烟雾外，豁见天地心。
物象不可及，迟回空咏吟。','',''),('quantangshi-16772','游烂柯山四首 二','李幼卿','quantangshi','','卷17','巨石何崔嵬，横桥架山顶。
傍通日月过，仰望虹霓迥。
圣者开津梁，谁能度兹岭。','',''),('quantangshi-16773','游烂柯山四首 三','李幼卿','quantangshi','','卷17','二仙自围棊，偶与樵夫会。
仙家异人代，俄顷千年外。
笙鹤何时还，仪形尚相对。','',''),('quantangshi-16774','游烂柯山四首 四','李幼卿','quantangshi','','卷17','石室过云外，二僧俨禅寂。
不语对空山，无心向来客。
作礼未及终，忘循旧形迹。','',''),('quantangshi-16775','游烂柯山四首 一','李深','quantangshi','','卷17','寻源路不迷，绝顶与云齐。
坐引羣峰小，平看万木低。
双林春色上，正有子规啼。','',''),('quantangshi-16776','游烂柯山四首 二','李深','quantangshi','','卷17','嵌空横洞天，磅礴倚崖巘。
宛如虹势出，可赏不可转。
真兴得津粱，抽簪永游衍。','',''),('quantangshi-16777','游烂柯山四首 三','李深','quantangshi','','卷17','羽客无姓名，仙棊但闻见。
行看负薪客，坐使桑田变。
怀古正怡然，前山早莺啭。','',''),('quantangshi-16778','游烂柯山四首 四','李深','quantangshi','','卷17','稽首期发蒙，吾师岂无说。
安禅即方丈，演法皆寂灭。
鸣磬雨花香，斋堂饭松屑。','',''),('quantangshi-16779','游烂柯山 一','羊滔','quantangshi','','卷17','步登春岩里，更上最远山。
聊见宇宙阔，遂令身世闲。
清辉赏不尽，高驾何时还。','',''),('quantangshi-16780','游烂柯山 二','羊滔','quantangshi','','卷17','石梁耸千尺，高盼出林囗。
亘壑蹑丹虹，排云弄清影。
路期访道客，游衍空井井。','',''),('quantangshi-16781','游烂柯山 三','羊滔','quantangshi','','卷17','采薪穷冥搜，深路转清暎。
安知洞天里，偶坐得棋圣。
至今追灵迹，可用陶静性。','',''),('quantangshi-16782','游烂柯山 四','羊滔','quantangshi','','卷17','沙门何处人，携手俱灭迹。
深入不动境，乃知真圆寂。
有时归罗浮，白日见飞锡。','',''),('quantangshi-16783','游烂柯山 一','薛戎','quantangshi','','卷17','登岩已寂历，绝顶更岧嶤。
响像如天近，窥临与世遥。
悠然畅心目，万虑一时销。','',''),('quantangshi-16784','游烂柯山 二','薛戎','quantangshi','','卷17','圣游本无迹，留此示津粱。
架险知何适，遗名但不亡。
只今成佛宇，化度果难量。','',''),('quantangshi-16785','游烂柯山 三','薛戎','quantangshi','','卷17','二仙行自适，日月徒迁徙。
不语寄手谈，无心引樵子。
蒙分一丸药，相偶穷年祀。','',''),('quantangshi-16786','游烂柯山 四','薛戎','quantangshi','','卷17','仙山习禅处，了知通李释。
昔作异时人，今成相对寂。
便是不二门，自生瞻仰意。','',''),('quantangshi-16787','游烂柯山 一','謝勮','quantangshi','','卷17','独凌清景出，下视众山中。
云日遥相对，川原无不通。
自致高标末，何心待驭风。','',''),('quantangshi-16788','游烂柯山 二','謝勮','quantangshi','','卷17','宛演横半规，穹崇翠微上。
云扃掩苔石，千古无人赏。
宁知后贤心，登此共来往。','',''),('quantangshi-16789','游烂柯山 三','謝勮','quantangshi','','卷17','仙弈示樵夫，能言忘归路。
因看斧柯烂，孙子发已素。
孰云遗迹久，举意如旦暮。','',''),('quantangshi-16790','游烂柯山 四','謝勮','quantangshi','','卷17','仙僧会真要，应物常渊默。
惟将无住理，转与信人说。
月影清江中，可观不可得。','',''),('quantangshi-16791','奉和圣制三日书怀因以示百寮','崔元翰','quantangshi','','卷17','佳节上元巳，芳时属暮春。
流觞想兰亭，捧劒传金人。
风轻水初绿，日迟花更新。
天文信昭回，皇道颇敷陈。
恭己每从俭，清心常保真。
戒兹游衍乐，书以示羣臣。','',''),('quantangshi-16792','奉和圣制重阳旦日百寮曲江宴示怀','崔元翰','quantangshi','','卷17','偶圣覩昌期，受恩慙弱质。
幸逢良宴会，况是清秋日。
远岫对壶觞，澄澜映簪绂。
炮羔备丰膳，集凤调鸣律。
薄劣厕英豪，欢娱忘衰疾。
平臯行雁下，曲渚双凫出。
沙岸菊开花，霜枝果垂实。
天文见成象，帝念资勤恤。
探道得玄珠，斋心居特室。
岂如横汾唱，其事徒骄逸。','',''),('quantangshi-16793','奉和圣制中元日题奉敬寺','崔元翰','quantangshi','','卷17','妙道非本说，殊途成异名。
圣人得其要，俱以化羣生。
凤吹从上苑，龙宫连外城。
花鬘列后殿，云车驻前庭。
松竹含新秋，轩窗有余清。
缅怀崆峒事，须继箫管声。
离相境都寂，忘言理更精。
域中信称大，天下乃为轻。
屈己由济物，尧心岂所荣。','',''),('quantangshi-16794','奉和登玄武楼观射即事书怀赐孟涉应制','崔元翰','quantangshi','','卷17','宁岁常有备，殊方靡不宾。
禁营列武卫，帝座彰威神。
讲事一临幸，加恩徧抚巡。
城高凤楼耸，塲逈兽侯新。
饮羽连百中，控弦逾六钧。
拣材尽爪士，受任皆信臣。
光赏文藻丽，便繁心膂亲。
复如观太清，昭烂垂芳辰。','',''),('quantangshi-16795','清明节郭侍御偶与李侍御孔校书王秀才游开化寺卧病不得同游赋得十韵兼呈马十八郎丞公','崔元翰','quantangshi','','卷17','山色入层城，钟声临复岫。
乘闲息边事，探异怜春候。
曲阁下重阶，回廊遥对溜。
石间花徧落，草上云时覆。
钻火见樵人，饮泉逢野兽。
道情亲法侣，时望登朝右。
执宪糺奸邪，刊书正讹谬。
茂才当时选，公子生人秀。
赠答继篇章，欢娱重朋旧。
垂帘独衰疾，击缶酬金奏。','',''),('quantangshi-16796','杂言奉和圣制至承光院见自生藤感其得地因以成咏应制','崔元翰','quantangshi','','卷17','新藤正可翫，得地又逢时。
罗生密叶交绿蔓，欲布清阴垂紫蕤。
已带朝光暖，犹含轻露滋。
遥依千华殿，稍上万年枝。
余芳连桂树，积润傍莲池。
岂如幽谷无人见，空覆荒榛杂兔丝。
圣心对此应有感，隐迹如斯谁复知。
怀贤劳永叹，比物赋新诗。
聘丘园，访茅茨。
为谢中林士，王道本无私。','',''),('quantangshi-16797','雨中对后檐丛竹','崔元翰','quantangshi','','卷17','含风摇砚水，带雨拂墙衣。
乍似秋江上，渔家半掩扉。','',''),('quantangshi-16798','赋得沈珠于泉','獨孤良器','quantangshi','','卷17','皎洁沈泉水，荧煌照乘珠。
沈非将宝契，还与不贪符。
风折璇成浪，空涵影似浮。
深看星并入，静向月同无。
光价怜时重，亡情信道枢。
不应无胫至，自为暗投殊。','',''),('quantangshi-16799','雪席口占','高崇文','quantangshi','','卷17','崇文宗武不崇文，提戈出塞号将军。
那个𩩉儿射雁落，白毛空里乱纷纷。','',''),('quantangshi-16800','雪席口占','高崇文','quantangshi','','卷17','崇文崇武不崇文，提戈出塞旧从军。
有似蕃儿射雁落，白毛空里乱纷纷。','',''),('quantangshi-16801','行县至浮查山寺','羅珦','quantangshi','','卷17','三十年前此布衣，鹿鸣西上虎符归。
行时宾从过前寺，到处松杉长旧围。
野老竞遮官道拜，沙鸥遥避隼旟飞。
春风一宿琉璃地，自有泉声惬素机。','',''),('quantangshi-16802','赋四相诗 中书令汉阳王张柬之','皇甫澈','quantangshi','','卷17','周历革元命，天步值艰阻。
烈烈张汉阳，左袒清诸武。
休明神器正，文物旧仪覩。
南向翊大君，西宫朝圣母。
茂勋镂钟鼎，鸿劳食茅土。
至今称五王，卓立迈万古。','',''),('quantangshi-16803','赋四相诗 中书令钟绍京','皇甫澈','quantangshi','','卷17','景龙仙驾远，中禁奸衅结。
谋猷叶圣朝，披鳞奋英节。
青宫阊阖启，涤秽氛沴灭。
紫气重昭回，皇天新日月。
从容庙堂上，肃穆人神悦。
唐元佐命功，辉焕何烈烈。','',''),('quantangshi-16804','赋四相诗 礼部尚书门下侍郎平章事李岘','皇甫澈','quantangshi','','卷17','时来遇明圣，道济宁邦国。
猗欤瑚琏器，竭我股肱力。
进贤黜不肖，错枉举诸直。
宦官既却坐，权奸亦移职。
载践每若惊，三已无愠色。
昭昭垂宪章，来世实作则。','',''),('quantangshi-16805','赋四相诗 门下侍郎平章事王缙','皇甫澈','quantangshi','','卷17','舟檝济巨川，山河资秀气。
服膺究儒业，屈指取高位。
北征戮骄悍，东守辑携贰。
论道致巍巍，持衡无事事。
知己不易遇，宰相固有器。
瞻事华壁中，来者谁其嗣。','',''),('quantangshi-16806','上巳泛舟得迟字','張登','quantangshi','','卷17','令节推元巳，天涯喜有期。
初筵临泛地，旧俗祓禳时。
枉渚潮新上，残春日正迟。
竹枝游女曲，桃叶渡江词。
风鷁今方退，沙鸥亦未疑。
且同山简醉，倒载莫褰帷。','',''),('quantangshi-16807','送王主簿游南海','張登','quantangshi','','卷17','平生推久要，留滞共三年。
明日东南路，穷荒雾露天。
旷怀常寄酒，素业不言钱。
道在贫非病，时来丑亦妍。
过山乘蜡屐，涉海附楼船。
行矣无为恨，宗门有大贤。','',''),('quantangshi-16808','重阳宴集同用寒字','張登','quantangshi','','卷17','锡宴逢佳节，穷荒亦共欢。
恩深百日泽，雨借九秋寒。
望气人谣洽，临风客以难。
座移山色在，杯尽菊香残。
欲识投醪遍，应从落帽看。
还宵须命烛，举首谢三官。','',''),('quantangshi-16809','仲秋夜郡内西亭对月','張登','quantangshi','','卷17','天高月满影悠悠，一夜炎荒并觉秋。
气与露清凝众草，色如霜白怯轻裘。
高临华宇还知隙，静映长江不共流。
囗直西倾河汉曙，遗风犹想武昌楼。','',''),('quantangshi-16810','冬至夜郡斋宴别前华阴卢主簿','張登','quantangshi','','卷17','虎宿方冬至，鸡人积夜筹。
相逢一尊酒，共结两乡愁。
王俭花为府，卢谌幄内璆。
明朝更临水，怅望岭南流。','',''),('quantangshi-16811','小雪日戏题绝句','張登','quantangshi','','卷17','甲子徒推小雪天，刺梧犹绿槿花然。
融和长养无时歇，却是炎洲雨露偏。','',''),('quantangshi-16812','招客游寺','張登','quantangshi','','卷17','江城吏散卷春阴，山寺鸣钟隔雨深。
招取遗民赴僧社，竹堂分坐静看心。','',''),('quantangshi-16813','句','張登','quantangshi','','卷17','孤高齐帝石，萧洒晋亭峰。
境旷穷山外，城标涨海头。','',''),('quantangshi-16814','陪韩退之窦贻周同寻刘尊师不遇得师字','韋執中','quantangshi','','卷17','早尚逍遥境，常怀汗漫期。
星郎同访道，羽客杳何之。
物外求仙侣，人间失我师。
不知柯烂者，何处看围棊。','',''),('quantangshi-16815','寻人偶题','邵真','quantangshi','','卷17','日昃不复午，落花难归树。
人生能几何，莫厌相逢遇。','',''),('quantangshi-16816','墙阴残雪','何頻瑜','quantangshi','','卷17','积雪还因地，墙阴久尚残。
影添斜月白，光借夕阳寒。
皎洁开帘近，清荧步履看。
状花飞着树，如玉不成盘。
冰薄方宁及，霜浓比亦难。
谁怜高卧处，岁暮叹袁安。','',''),('quantangshi-16817','题度支杂事典庭中柏树','駱浚','quantangshi','','卷17','干耸一条青玉直，叶铺千叠绿云低。
争如燕雀偏巢此，却是鸳鸯不得栖。','',''),('quantangshi-16818','梢云','羅讓','quantangshi','','卷17','殊质资灵贶，凌空发瑞云。
梢梢含树彩，郁郁动霞文。
不比因风起，全非触石分。
叶光闲泛滟，枝杪静氛氲。
隐见心无宰，裴回庆自君。
翻飞如可托，长愿在横汾。','',''),('quantangshi-16819','闰月定四时','羅讓','quantangshi','','卷17','月闰随寒暑，畴人定职司。
余分将考日，积算自成时。
律候行宜表，阴阳运不欺。
气薰灰琯验，数仂卦辞推。
六律文明序，三年理暗移。
当知岁功立，唯是奉无私。','',''),('quantangshi-16820','享文恭太子庙乐章','陳京','quantangshi','','卷17','歌以德发，声以乐贵。
乐善名存，追仙礼异。
鸾旌拱修，凤鸣合次。
神听皇慈，仲月皆至。','',''),('quantangshi-16821','步虚词十九首 一','韋渠牟','quantangshi','','卷17','玉简真人降，金书道箓通。
烟霞方蔽日，云雨已生风。
四极威仪异，三天使命同。
那将人世恋，不去上清宫。','',''),('quantangshi-16822','步虚词十九首 二','韋渠牟','quantangshi','','卷17','羽驾正翩翩，云鸿最自然。
霞冠将月晓，珠佩与星连。
镂玉留新诀，雕金得旧编。
不知飞鸾鹤，更有几人仙。','',''),('quantangshi-16823','步虚词十九首 三','韋渠牟','quantangshi','','卷17','上帝求仙使，真符取玉郎。
三才闲布象，二景郁生光。
骑吏排龙虎，笙歌走凤皇。
天高人不见，暗入白云乡。','',''),('quantangshi-16824','步虚词十九首 四','韋渠牟','quantangshi','','卷17','鸾鹤共裴回，仙官使者催。
香花三洞启，风雨百神来。
凤篆文初定，龙泥印已开。
何须生羽翼，始得上瑶台。','',''),('quantangshi-16825','步虚词十九首 五','韋渠牟','quantangshi','','卷17','羽节忽排烟，苏君已得仙。
命风驱日月，缩地走山川。
几处留丹竈，何时种玉田。
一朝骑白虎，直上紫微天。','',''),('quantangshi-16826','步虚词十九首 六','韋渠牟','quantangshi','','卷17','静发降灵香，思神意智长。
虎存时促步，龙想更成章。
扣齿风雷响，挑灯日月光。
仙云在何处，仿髴满空堂。','',''),('quantangshi-16827','步虚词十九首 七','韋渠牟','quantangshi','','卷17','几度游三洞，何方召百神。
风云皆守一，龙虎亦全真。
执节仙童小，烧香玉女春。
应须绝岩内，委曲问皇人。','',''),('quantangshi-16828','步虚词十九首 八','韋渠牟','quantangshi','','卷17','上法杳无营，玄修似有情。
道宫琼作想，真帝玉为名。
召岳驰旌节，驱雷发吏兵。
云车降何处，斋室有仙卿。','',''),('quantangshi-16829','步虚词十九首 九','韋渠牟','quantangshi','','卷17','羽卫一何鲜，香云起暮烟。
方朝太素帝，更向玉清天。
凤曲凝犹吹，龙骖俨欲前。
真文几时降，知在永和年。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-16830','步虚词十九首 十','韋渠牟','quantangshi','','卷17','大道何年学，真符此日催。
还持金作印，未要玉为台。
羽节分明授，霞衣整顿裁。
应缘五云使，敎上列仙来。','',''),('quantangshi-16831','步虚词十九首 十一','韋渠牟','quantangshi','','卷17','独自授金书，萧条咏紫虚。
龙行还当马，云起自成车。
九转风烟合，千年井竈余。
参差从太一，寿等混元初。','',''),('quantangshi-16832','步虚词十九首 十二','韋渠牟','quantangshi','','卷17','道学已通神，香花会女真。
霞牀珠斗帐，金荐玉舆轮。
一室心偏静，三天夜正春。
灵官竟谁降，仙相有夫人。','',''),('quantangshi-16833','步虚词十九首 十三','韋渠牟','quantangshi','','卷17','上界有黄房，仙家道路长。
神来知位次，乐变叶宫商。
竞把瑠璃盏，都倾白玉浆。
霞衣最芬馥，苏合是灵香。','',''),('quantangshi-16834','步虚词十九首 十四','韋渠牟','quantangshi','','卷17','珠佩紫霞缨，夫人会八灵。
太霄犹有观，绝宅岂无形。
暮雨裴回降，仙歌宛转听。
谁逢玉妃辇，应检九真经。','',''),('quantangshi-16835','步虚词十九首 十五','韋渠牟','quantangshi','','卷17','西海辞金母，东方拜木公。
云行疑带雨，星步欲凌风。
羽袖挥丹凤，霞巾曳彩虹。
飘颻九霄外，下视望仙宫。','',''),('quantangshi-16836','步虚词十九首 十六','韋渠牟','quantangshi','','卷17','玉树襍金花，天河织女家。
月邀丹凤舃，风送紫鸾车。
雾縠笼绡带，云屏列锦霞。
瑶台千万里，不觉往来赊。','',''),('quantangshi-16837','步虚词十九首 十七','韋渠牟','quantangshi','','卷17','舞凤凌天出，歌麟入夜听。
云容衣眇眇，风韵曲泠泠。
扣齿端金简，焚香检玉经。
仙宫知不远，祗近太微星。','',''),('quantangshi-16838','步虚词十九首 十八','韋渠牟','quantangshi','','卷17','紫府与玄洲，谁来物外游。
无烦骑白鹿，不用驾青牛。
金化颜应驻，云飞鬓不秋。
仍闻碧海上，更用玉为楼。','',''),('quantangshi-16839','步虚词十九首 十九','韋渠牟','quantangshi','','卷17','辔鹤复骖鸾，全家去不难。
鸡声随羽化，犬影入云看。
酿玉当成酒，烧金且转丹。
何妨五色绶，次第给仙官。','',''),('quantangshi-16840','览外生卢纶诗因以示此','韋渠牟','quantangshi','','卷17','卫玠清谈性最强，明时独拜正员郎。
关心珠玉曾无价，满手琼瑶更有光。
谋略久参花府盛，才名常带粉闱香。
终期内殿聊诗句，共汝朝天会柏梁。','',''),('quantangshi-16841','赠窦五判官','韋渠牟','quantangshi','','卷17','故旧相逢三两家，爱君兄弟有声华。
文辉锦彩珠垂露，逸兴江天绮散霞。
美玉自矜频献璞，真金难与细披沙。
终须撰取新诗品，更比芙蓉出水花。','',''),('quantangshi-16842','湖上闲居','竇參','quantangshi','','卷17','避影将息阴，自然知音稀。
向来深林中，偶亦有所窥。
飞鸟口衔食，引雏上高枝。
高枝但各有，安知宜不宜。
止止复何云，物情何自私。','',''),('quantangshi-16843','迁谪江表久未归','竇參','quantangshi','','卷17','一自经放逐，裴回无所从。
便为寒山云，不得随飞龙。
名岂不欲保，归岂不欲早。
苟无三月资，难适千里道。
离心与羁思，终日常草草。
人生年几齐，忧苦即先老。
谁能假羽翼，使我畅怀抱。','',''),('quantangshi-16844','登潜山观','竇參','quantangshi','','卷17','山势欲相抱，一条微径盘。
攀萝歇复行，始得凌仙坛。
闻道葛夫子，此中炼还丹。
丹成五色光，服之生羽翰。
灵草空自绿，余霞谁共餐。
至今步虚处，犹有孤飞鸾。
幽幽古殿门，下压浮云端。
万丈水声落，四时松色寒。
既入无何乡，转嫌人事难。
终当远尘俗，高卧从所安。','',''),('quantangshi-16845','淮西席上醉歌','盧羣','quantangshi','','卷17','祥瑞不在凤凰麒麟，太平须得边将忠臣。
卫霍真诚奉主，貔虎十万一身。
江河潜注息浪，蛮貊款塞无尘。
但得百寮师长肝胆，不用三军罗绮金银。','',''),('quantangshi-16846','天池晚棹','韋臯','quantangshi','','卷17','雨霁天池生意足，花间谁咏采莲曲。
舟浮十里芰荷香，歌发一声山水绿。
春暖鱼抛水面纶，晚晴鹭立波心玉。
扣舷归载月黄昏，直至更深不假烛。','',''),('quantangshi-16847','赠何遐','韋臯','quantangshi','','卷17','腰间宝劒七星文，掌上弯弓挂六钧。
箭发囗云双雁落，始知秦地有将军。','',''),('quantangshi-16848','忆玉箫','韋臯','quantangshi','','卷17','黄雀衔来已数春，别时留解赠佳人。
长江不见鱼书至，为遣相思梦入秦。','',''),('quantangshi-16849','观翟玉妓','李愿','quantangshi','','卷17','女郎闺阁春，抱瑟坐花茵。
艳粉宜斜烛，羞蛾惨向人。
寄情摇玉柱，流眄整罗巾。
幸以芳香袖，承君宛转尘。','',''),('quantangshi-16850','思妇','李愿','quantangshi','','卷17','良人久不至，惟恨锦屏孤。
顦顇衣宽日，空房问女巫。','',''),('quantangshi-16851','徐州使院赋','王智興','quantangshi','','卷17','三十年前老健儿，刚被郎中遣作诗。
江南花柳从君咏，塞北烟尘我独知。','',''),('quantangshi-16852','茶山诗','袁高','quantangshi','','卷17','禹贡通远俗，所图在安人。
后王失其本，职吏不敢陈。
亦有奸佞者，因兹欲求伸。
动生千金费，日使万姓贫。
我来顾渚源，得与茶事亲。
甿辍耕农耒，采采实苦辛。
一夫旦当役，尽室皆同臻。
扪葛上欹壁，蓬头入荒榛。
终朝不盈掬，手足皆鳞皴。
悲嗟遍空山，草木为不春。
阴岭芽未吐，使者牒已频。
心争造化功，走挺麋鹿均。
选纳无昼夜，捣声昏继晨。
众工何枯栌，俯视弥伤神。
皇帝尚巡狩，东郊路多堙。
周回遶天涯，所献愈艰勤。
况减兵革困，重兹固疲民。
未知供御余，谁合分此珍。
顾省忝邦守，又慙复因循。
茫茫沧海间，丹愤何由申。','',''),('quantangshi-16853','送惟详律师自越之义兴','崔子向','quantangshi','','卷17','阳羡诸峰顶，何曾异剡山。
雨晴人到寺，木落夜开关。
缝衲纱灯亮，看心锡杖闲。
西方知有社，未得与师还。','',''),('quantangshi-16854','上鲍大夫','崔子向','quantangshi','','卷17','行尽江南塞北时，无人不诵鲍家诗。
东堂桂树何年折，直至如今少一枝。','',''),('quantangshi-16855','题越王台','崔子向','quantangshi','','卷17','越井岗头松柏老，越王台上生秋草。
古木多年无子孙，牛羊践踏成官道。','',''),('quantangshi-16856','赠韩退之','張署','quantangshi','','卷17','九疑峰畔二江前，恋阙思乡日抵年。
白简趋朝曾竝命，苍梧左宦一聊翩。
鲛人远泛渔舟水，鵩鸟闲飞露里天。
涣汗几时流率土，扁舟西下共归田。','',''),('quantangshi-16857','享惠昭太子庙乐章','歸登','quantangshi','','卷17','嘉荐既陈，祀事孔明。
间歌在堂，万舞在庭。
外则尽物，内则尽诚。
凤笙如闻，歆其洁精。','',''),('quantangshi-16858','剡溪行却寄新别者','朱放','quantangshi','','卷17','潺湲寒溪上，自此成离别。
廻首望归人，移舟逢暮雪。
频行识草树，渐老伤年发。
唯有白云心，为向东山月。','',''),('quantangshi-16859','九日陪刘中丞宴昌乐寺送梁廷评','朱放','quantangshi','','卷17','独坐三台妙，重阳百越间。
水心观远俗，霜气入秋山。
不弃遗簪旧，宁辞落帽还。
仍闻西上客，咫尺谒天颜。','',''),('quantangshi-16860','经故贺宾客镜湖道士观','朱放','quantangshi','','卷17','已得归乡里，逍遥一外臣。
那随流水去，不待镜湖春。
雪里登山屐，林间漉酒巾。
空余道士观，谁是学仙人。','',''),('quantangshi-16861','送着公归越','朱放','quantangshi','','卷17','谁能愁此别，到越会相逢。
长忆云门寺，门前千万峰。
石牀埋积雪，山路倒枯松。
莫学白道士，无人知去踪。','',''),('quantangshi-16862','秣陵送客入京','朱放','quantangshi','','卷17','秣陵春已至，君去学归鸿。
绿水琴声切，青袍草色同。
鸟喧金谷树，花满洛阳宫。
日日相思处，江边杨柳风。','',''),('quantangshi-16863','灵门寺赠灵一上人','朱放','quantangshi','','卷17','所思劳旦夕，惆怅去湘东。
禅客知何在，春山几处同。
独行残雪里，相见暮云中。
请住东林寺，弥年事远公。','',''),('quantangshi-16864','江上送别','朱放','quantangshi','','卷17','浦边新见柳摇时，北客相逢只自悲。
惆怅空知思后会，艰难不敢料前期。
行看汉月愁征战，共折江花怨别离。
向夕孤城分首处，寂寥横笛为君吹。','',''),('quantangshi-16865','归桐庐旧居寄严长史','朱放','quantangshi','','卷17','昨辞天子棹归舟，家在桐庐忆旧丘。
三月暖时花竞发，两溪分处水争流。
近闻江老传乡语，遥见家山减旅愁。
或在醉中逢夜雪，怀贤应向剡川游。','',''),('quantangshi-16866','竹','朱放','quantangshi','','卷17','青林何森然，沈沈独曙前。
出墙同淅沥，开户满婵娟。
箨卷初呈粉，苔侵乱上钱。
疎中思水过，深处若山连。
叠夜常栖露，清朝乍有蝉。
砌阴迎缓策，檐翠对欹眠。
迸笋双分箭，繁梢一向偏。
月过惊散雪，风动极闻泉。
幽谷添诗谱，高人欲制篇。
萧萧意何恨，不独往湘川。','',''),('quantangshi-16867','铜雀妓','朱放','quantangshi','','卷17','恨唱歌声咽，愁翻舞袖迟。
西陵日欲暮，是妾断肠时。','',''),('quantangshi-16868','毗陵留别','朱放','quantangshi','','卷17','别离非一处，此处最伤情。
白发将春草，相随日日生。','',''),('quantangshi-16869','题竹林寺','朱放','quantangshi','','卷17','岁月人间促，烟霞此地多。
殷勤竹林寺，能得几廻过。','',''),('quantangshi-16870','答陆[澧]','朱放','quantangshi','','卷17','松叶堪为酒，春来酿几多。
不辞山路远，踏雪也相过。','',''),('quantangshi-16871','杨子津送人','朱放','quantangshi','','卷17','今朝杨子津，忽见五溪人。
老病无余事，丹砂乞五斤。','',''),('quantangshi-16872','山中谒皇甫曾','朱放','quantangshi','','卷17','寻源路已尽，笑入白云间。
不解乘轺客，那知有此山。','',''),('quantangshi-16873','剡山夜月','朱放','quantangshi','','卷17','月在沃洲山上，人归剡县溪边。
漠漠黄花覆水，时时白鹭惊船。','',''),('quantangshi-16874','九日与杨凝崔淑期登江上山会有故不得往因赠之','朱放','quantangshi','','卷17','欲从携手登高去，一到门前意已无。
那得更将头上发，学他年少插茱萸。','',''),('quantangshi-16875','山中听子规','朱放','quantangshi','','卷17','幽人自爱山中宿，又近葛洪丹井西。
窗中有个长松树，半夜子规来上啼。','',''),('quantangshi-16876','乱后经淮阴岸','朱放','quantangshi','','卷17','荒村古岸谁家在，野水浮云处处愁。
唯有河边衰柳树，蝉声相送到扬州。','',''),('quantangshi-16877','送张山人','朱放','quantangshi','','卷17','知君住处足风烟，古寺荒村在眼前。
便欲移家逐君去，唯愁未有买山钱。','',''),('quantangshi-16878','别李季兰','朱放','quantangshi','','卷17','古岸新花开一枝，岸傍花下有分离。
莫将罗袖拂花落，便是行人肠断时。','',''),('quantangshi-16879','游石涧寺','朱放','quantangshi','','卷17','闻道幽深石涧寺，不逢流水亦难知。
莫道山僧无伴侣，猕猴长在古松枝。','',''),('quantangshi-16880','新安所居答相访人所居萧使君为制','朱放','quantangshi','','卷17','谢公见我多愁疾，为我开门对碧山。
君若欲来看猿鸟，不须争把桂枝攀。','',''),('quantangshi-16881','送魏校书','朱放','quantangshi','','卷17','长恨江南足别离，几廻相送复相随。
杨花撩乱扑流水，愁杀人行知不知。','',''),('quantangshi-16882','送温台','朱放','quantangshi','','卷17','眇眇天涯君去时，浮云流水自相随。
人生一世长如客，何必今朝是别离。','',''),('quantangshi-16883','句','朱放','quantangshi','','卷17','爱彼云外人，求取磵底泉。
风吹芭蕉拆，鸟啄梧桐落。','',''),('quantangshi-16884','古意','武元衡','quantangshi','','卷17','蜀国春与秋，岷江朝夕流。
长波东接海，万里至扬州。
开门面淮甸，楚俗饶欢宴。
舞榭黄金梯，歌楼白云面。
荡子未言归，池塘月如练。','',''),('quantangshi-16885','塞下曲','武元衡','quantangshi','','卷17','草枯马蹄轻，角弓劲如石。
骄虏初欲来，风尘暗南国。
走檄召都尉，星火剿羌狄。
吾身许报主，何暇避锋镝。
白露湿铁衣，半夜待攻击。
龙沙早立功，名向燕然勒。','',''),('quantangshi-16886','独不见','武元衡','quantangshi','','卷17','荆门一柱观，楚国三休殿。
环佩俨神仙，辉光生顾盼。
春风细腰舞，明月高堂宴。
梦泽水连云，渚宫花似霰。
俄惊白日晚，始悟炎凉变。
别岛异波潮，离鸿分海县。
南北断相闻，叹嗟独不见。','',''),('quantangshi-16887','旬假南亭寄熊郎中','武元衡','quantangshi','','卷17','旬休屏戎事，凉雨北窗眠。
江城一夜雨，万里绕山川。
草木散幽气，池塘鸣早蝉。
妍芳落春后，旅思生秋前。
红槿粲庭艳，绿蒲繁渚烟。
行歌独谣酌，坐发朱丝弦。
哀玉不可扣，华烛徒湛然。
闻君乐林卧，郡阁旷周旋。
酬对龙象侣，灌注清泠泉。
如何无碍智，犹苦病缠牵。','',''),('quantangshi-16888','晨兴寄赠窦使君','武元衡','quantangshi','','卷17','江陵岁方晏，晨起眄庭柯。
白露伤红叶，清风断绿萝。
徇时真气索，念远怀忧多。
夙昔乐山意，纵横南浦波。
有美婵娟子，百虑攒双蛾。
缄情郁不舒，幽行骈复罗。
为予歌苦寒，酌酒朱颜酡。
世事浮云变，功名将奈何。','',''),('quantangshi-16889','秋日对酒','武元衡','quantangshi','','卷17','行年过始衰，秋至独先悲。
事往怜神魄，感深滋涕涕。
百忧纷在虑，一醉兀无思。
宝瑟拂麈匣，徽音凝朱丝。
幽圃蕙兰气，烟窗松桂姿。
我乏济时略，杖节抚藩维。
山川大兵后，牢落空城池。
惊沙犹振野，绿草生荒陂。
物变风雨顺，人怀天地慈。
春耕事秋战，戎马去封陲。
波澜暗超忽，坚白亦磷缁。
客有自嵩颍，重征栖隐期。
丹诀学仙晚，白云归谷迟。
君恩不可报，霜露绕南枝。','',''),('quantangshi-16890','安邑里中秋怀寄高员外','武元衡','quantangshi','','卷17','原宪素非贫，嵇康自寡欲。
守道识通穷，达命齐荣辱。
庭梧变葱蒨，篱菊扬芳馥。
坠叶翻夕霜，高堂瞬华烛。
况兹寒夜永，复叹流年促。
感物思殷勤，怀贤心踯躅。
雄词封禅草，丽句阳春曲。
高德十年兄，异才千里足。
咫尺邈雪霜，相望如琼玉。
欲识岁寒心，松筠更秋绿。','',''),('quantangshi-16891','送唐次','武元衡','quantangshi','','卷17','都门去马嘶，灞水春流浅。
青槐驿路长，白日离尊晚。
望望烟景微，草色行人远。','',''),('quantangshi-16892','秋夜雨中怀友','武元衡','quantangshi','','卷17','庭空雨鸣骄，天寒雁啼苦。
青灯淡吐光，白发悄无语。
几年不与联牀吟，君方客吴我犹楚。','',''),('quantangshi-16893','望夫石','武元衡','quantangshi','','卷17','佳名望夫处，苔藓封孤石。
万里水连天，巴江暮云碧。
湘妃泣下竹成斑，子规夜啼江树白。','',''),('quantangshi-16894','行路难','武元衡','quantangshi','','卷17','君不见道旁废井傍开花，原是昔年骄贵家。
几度美人来照影，濯纤笑引银瓶绠。
风飘雨散今奈何，绣闼雕甍绿苔多。
笙歌鼎沸君莫矜，豪奢未必长多金。
休说编氓朴无耻，至竟终须合天理。
非故败他却成此，苏张终作多言鬼。
行路难，路难不在九折湾。','',''),('quantangshi-16895','长相思','武元衡','quantangshi','','卷17','长相思，陇云愁，单于台上望伊州。
雁书绝，蝉鬓秋。
行人天一畔，暮雨海西头。
殷勤大河水，东注不还流。','',''),('quantangshi-16896','出塞作','武元衡','quantangshi','','卷17','夙驾逾人境，长驱出塞垣。
边风引去骑，胡沙拂征辕。
奏笳山月白，结阵瘴云昏。
虽云风景异华夏，亦喜地理通楼烦。
白羽矢飞先火礮，黄金甲耀夺朝暾。
要须洒扫龙沙净，归谒明光一报恩。','',''),('quantangshi-16897','桃源行送友','武元衡','quantangshi','','卷17','武陵川径入幽遐，中有鸡犬秦人家，家傍流水多桃花。
桃花两边种来久，流水一通何时有。
垂条落蘂暗春风，夹岸芳菲至山口。
岁岁年年能寂寥，林下青苔日为厚。
时有仙鸟来衔花，曾无世人此携手。
可怜不知若为名，君往从之多所更。
古驿荒桥平路尽，崩湍怪石小溪行。
相见维舟登览处，红堤绿岸宛然成。
多君此去从仙隐，令人晚节悔营营。','',''),('quantangshi-16898','长安叙怀寄崔十五','武元衡','quantangshi','','卷17','延首直城西，花飞绿草齐。
迢遥隔山水，怅望思游子。
百啭黄鹂细雨中，千条翠柳衡门里。
门对长安九衢路，愁心不惜芳菲度。
风尘冉冉秋复春，钟鼓喧喧朝复暮。
汉家宫阙在中天，紫陌朝臣车马连。
萧萧霓旌合仙杖，悠悠剑佩入炉烟。
李广少时思报国，终军未遇敢论边。
无媒守儒行，荣悴纷相映。
家甚长卿贫，身多公干病。
不知身病竟如何，嬾向青山眠薜萝。
鸡黍空多元伯惠，琴书不见子猷过。
超名累岁与君同，自叹还随鷁退风。
闻说唐生子孙在，何当一为问穷通。','',''),('quantangshi-16899','兵行褒斜谷作','武元衡','quantangshi','','卷17','古地接龟沙，边风送征雁。
霜明草正腓，峰逼日易晏。
集旅布嵌谷，驱马历层涧。
岷河源涉屡，蜀甸途行惯。
矢橐弧室岂领军，儋爵食禄由从宦。
注意奏凯赴都畿，速令提兵还石坂。
三川顿使气象清，卖刀买犊消忧患。','',''),('quantangshi-16900','西亭早秋送徐员外','武元衡','quantangshi','','卷17','鼎铉辞台座，麾幢领益州。
曲池连月晓，横角满城秋。
有美皇华使，曾同白社游。
今年重相见，偏觉艳歌愁。','',''),('quantangshi-16901','送徐员外还京','武元衡','quantangshi','','卷17','九折朱轮动，三巴白露生。
蕙兰秋意晚，关塞别魂惊。
宝瑟连宵怨，金罍尽醉倾。
旄头星未落，分手辘轳鸣。','',''),('quantangshi-16902','送柳郎中裴起居','武元衡','quantangshi','','卷17','沱江水绿波，喧鸟去乔柯。
南浦别离处，东风兰杜多。
长亭春婉娩，层汉路蹉跎。
会有归朝日，班超奈老何。','',''),('quantangshi-16903','八月十五酬从兄常望月有怀','武元衡','quantangshi','','卷17','坐爱圆景满，况兹秋夜长。
寒光生露草，夕韵出风篁。
地远惊金奏，天高失雁行。
如何北楼望，不得共池塘。','',''),('quantangshi-16904','酬太常从兄留别','武元衡','quantangshi','','卷17','乡路日兹始，征轩行复留。
张骞随汉节，王浚守刀州。
泽国烟花度，铜梁雾雨愁。
别离无可奈，万恨锦江流。','',''),('quantangshi-16905','春日与诸公泛舟','武元衡','quantangshi','','卷17','千里雪山开，沱江春水来。
驻帆云缥缈，吹管鹤裴回。
身外流年驶，尊前落景催。
不应归棹远，明月在高台。','',''),('quantangshi-16906','送兄归洛使谒严司空','武元衡','quantangshi','','卷17','六岁蜀城守，千茎蓬鬓丝。
忧心不自遣，骨肉又伤离。
楚峡饶云雨，巴江足梦思。
殷勤孔北海，时节易流移。','',''),('quantangshi-16907','同洛阳诸公饯卢起居','武元衡','quantangshi','','卷17','萧条寒日晏，凄惨别魂惊。
宝瑟无声怨，金囊故赠轻。
赤墀方载笔，油幕尚言兵。
暮宿青泥驿，烦君泪满缨。','',''),('quantangshi-16908','台中题壁','武元衡','quantangshi','','卷17','柏台年未老，蓬鬓忽苍苍。
无事裨明主，何心弄宪章。
雀声愁霰雪，鸿思恨关梁。
会脱簪缨去，故山瑶草芳。','',''),('quantangshi-16909','江上寄隐者','武元衡','quantangshi','','卷17','归舟不计程，江月屡亏盈。
霭霭沧波路，悠悠离别情。
蒹葭连水国，鼙鼓近梁城。
却忆沿江叟，汀洲春草生。','',''),('quantangshi-16910','送严绅游兰溪','武元衡','quantangshi','','卷17','剡岭穷边海，君游别岭西。
暮云秋水阔，寒雨夜猿啼。
地僻秦人少，山多越路迷。','',''),('quantangshi-16911','秋思','武元衡','quantangshi','','卷17','秋室浩烟雾，风柳怨寒蜩。
机杼夜声切，蕙兰芳意消。
美人湘水曲，桂檝洞庭遥。
常恐时光谢，蹉跎红艳凋。','',''),('quantangshi-16912','夏日别卢太卿','武元衡','quantangshi','','卷17','汉水清且广，江波渺复深。
叶舟烟雨夜，之子别离心。
汀草结春怨，山云连暝阴。
年年南北泪，今古共霑襟。','',''),('quantangshi-16913','西亭题壁寄中书李相公','武元衡','quantangshi','','卷17','昏旦倦兴寝，端忧力尚微。
廉颇不觉老，蘧瑗始知非。
授钺虚三顾，持衡旷万机。
空余蝴蝶梦，迢遰故山归。','',''),('quantangshi-16914','八月十五夜与诸公锦楼望月得中字','武元衡','quantangshi','','卷17','玉轮初满空，迥出锦城东。
相向秦楼镜，分飞碣石鸿。
桂香随窈窕，珠缀隔玲珑。
不及前秋月，圆辉凤沼中。','',''),('quantangshi-16915','四川使宅有韦令公时孔雀存焉暇日与诸公同翫座中兼故府宾妓兴嗟久之因赋此诗用广其意','武元衡','quantangshi','','卷17','荀令昔居此，故巢留越禽。
动摇金翠尾，飞舞碧梧阴。
上客彻瑶瑟，美人伤蕙心。
会因南国使，得放海云深。','',''),('quantangshi-16916','窦三中丞去岁有台中五言四韵未及酬报今领黔南途经蜀门百里而近愿言欵觌封略间然因追曩篇持以赠之','武元衡','quantangshi','','卷17','在昔谬司宪，常僚惟有君。
报恩如皎日，致位等青云。
削藁书难见，除苛事早吟。
双旌不可驻，风雪路岐分。','',''),('quantangshi-16917','春分与诸公同宴呈陆三十四郎中','武元衡','quantangshi','','卷17','南国宴佳宾，交情老倍亲。
月慙红烛泪，花笑白头人。
宝瑟常余怨，琼枝不让春。
更闻歌子夜，桃李艳妆新。','',''),('quantangshi-16918','津梁寺采新茶与幕中诸公遍赏芳香尤异因题四韵兼呈陆郎中','武元衡','quantangshi','','卷17','灵州碧岩下，荑英初散芳。
涂涂犹宿露，采采不盈筐。
阴窦藏烟湿，单衣染焙香。
幸将调鼎味，一为奏明光。','',''),('quantangshi-16919','元和癸巳余领蜀之七年奉诏徴还二月二十八日清明途经百牢关因题石门洞','武元衡','quantangshi','','卷17','昔佩兵符去，今持相印还。
天光临井络，春物度巴山。
鸟道青冥外，风泉洞壑间。
何慙班定远，辛苦玉门关。','',''),('quantangshi-16920','夕次潘山下','武元衡','quantangshi','','卷17','南国独行日，三巴春草齐。
漾波归海疾，危栈入云迷。
锦谷岚烟里，刀州晚照西。
旅情方浩荡，蜀魄满林啼。','',''),('quantangshi-16921','夏日对雨寄朱放拾遗','武元衡','quantangshi','','卷17','才非谷永传，无意谒王侯。
小暑金将伏，微凉麦正秋。
远山欹枕见，暮雨闭门愁。
更忆东林寺，诗家第一流。','',''),('quantangshi-16922','早春送欧阳炼师归山','武元衡','quantangshi','','卷17','双鹤五云车，初辞汉帝家。
人寰新甲子，天路旧烟霞。
羽节临风驻，霓裳逐雨斜。
昆仑有琪树，相忆寄瑶华。','',''),('quantangshi-16923','长安春望','武元衡','quantangshi','','卷17','宿雨净烟霞，春风绽百花。
绿杨中禁路，朱戟五侯家。
草色金堤晚，莺声御柳斜。
无媒犹未达，应共惜年华。','',''),('quantangshi-16924','经严祕校维故宅','武元衡','quantangshi','','卷17','掩泪山阳宅，生涯此路穷。
香销芸阁闭，星落草堂空。
丽藻浮名里，哀声夕照中。
不堪投钓处，隣笛怨春风。','',''),('quantangshi-16925','秋夜寄江南旧游','武元衡','quantangshi','','卷17','寥落九秋晚，端忧时物残。
隔林萤影度，出禁漏声寒。
愁雨洞房掩，孤灯遥夜阑。
怀贤梦南国，兴尽水漫漫。','',''),('quantangshi-16926','送陆书还吴','武元衡','quantangshi','','卷17','君住包山下，何年入帝乡。
成名归旧业，叹别见秋光。
橘柚吴洲远，芦花楚水长。
我行经此路，京口向云阳。','',''),('quantangshi-16927','山中月夜寄朱张二舍人','武元衡','quantangshi','','卷17','午夜更漏里，九重霄汉间。
月华云阙迥，秋色凤池闲。
御锦通清禁，天书出暗关。
嵇康不求达，终岁在空山。','',''),('quantangshi-16928','送冯谏议赴河北宣慰','武元衡','quantangshi','','卷17','汉代衣冠盛，尧年雨露多。
恩荣辞紫禁，冰雪渡黄河。
待诏孤城启，宣风万岁和。
今宵燕分野，应见使星过。','',''),('quantangshi-16929','夜坐闻雨寄严十少府','武元衡','quantangshi','','卷17','多负云霄志，生涯岁序侵。
风翻凉叶乱，雨滴洞房深。
迢遰三秋梦，殷勤独夜心。
怀贤不觉寐，清磬发东林。','',''),('quantangshi-16930','资圣寺贲法师晚春茶会','武元衡','quantangshi','','卷17','虚室昼常掩，心源知悟空。
禅庭一雨后，莲界万花中。
时节流芳暮，人天此会同。
不知方便理，何路出樊笼。','',''),('quantangshi-16931','慈恩寺起上人院','武元衡','quantangshi','','卷17','禅堂支许同，清论道源穷。
起灭秋云尽，虚无夕霭空。
池澄山倒影，林动叶翻风。
他日焚香待，还来礼惠聪。','',''),('quantangshi-16932','送魏正则擢第归江陵','武元衡','quantangshi','','卷17','客路商山外，离筵小暑前。
高文常独步，折桂及龆年。
关国通秦限，波涛隔汉川。
叨同会府选，分手倍依然。','',''),('quantangshi-16933','酬韩弇归崖见寄','武元衡','quantangshi','','卷17','惆怅人间事，东山遂独游。
露凝瑶草晚，鱼戏石潭秋。
轩冕应相待，烟霞莫遽留。
君看仲连意，功立始沧洲。','',''),('quantangshi-16934','河东赠别炼师','武元衡','quantangshi','','卷17','多累有行役，相逢秋节分。
游人甘失路，野鹤亦离羣。
戎马犯边垒，天兵屯塞云。
孔璋才素健，羽檄定纷纷。','',''),('quantangshi-16935','秋日将赴江上杨弘微时任凤翔寄诗别','武元衡','quantangshi','','卷17','寂寞两相阻，悠悠南北心。
燕惊沧海远，鸿避朔云深。
夜梦江亭月，离忧陇树阴。
兼秋无限思，惆怅属瑶琴。','',''),('quantangshi-16936','夏与熊王二秀才同宿僧院','武元衡','quantangshi','','卷17','共将缨上尘，来问雪山人。
世网从知累，禅心自证真。
境空宜入梦，藤古不留春。
一听林公法，灵嘉愿寄身。','',''),('quantangshi-16937','宜阳所居白蜀葵答咏柬诸公','武元衡','quantangshi','','卷17','冉冉众芳歇，亭亭虚室前。
敷荣时已背，幽赏地宜偏。
红艳世方重，素华徒可怜。
何当君子愿，知不竞喧妍。','',''),('quantangshi-16938','送寇侍御司马之明州','武元衡','quantangshi','','卷17','斗酒上河梁，惊魂去越乡。
地穷沧海阔，云入剡山长。
莲唱蒲萄熟，人烟橘柚香。
兰亭应驻楫，今古共风光。','',''),('quantangshi-16939','送严侍御','武元衡','quantangshi','','卷17','巴檄故人去，苍苍枫树林。
云山千里合，雾雨四时阴。
峡路猨声断，桃源犬吠深。
不须贪胜赏，汉节待南侵。','',''),('quantangshi-16940','酬元十二','武元衡','quantangshi','','卷17','偶寻乌府客，同醉习家池。
积雪初迷径，孤云遂失期。
风前劳引领，月下重相思。
何必因尊酒，幽心两自知。','',''),('quantangshi-16941','秋晚途次坊州界寄崔玉员外','武元衡','quantangshi','','卷17','崎岖崖谷迷，寒雨暮成泥。
征路出山顶，乱云生马蹄。
望乡程杳杳，怀远思凄凄。
欲识分麾重，孤城万壑西。','',''),('quantangshi-16942','度东径岭','武元衡','quantangshi','','卷17','又过雁门北，不胜南客悲。
三边上岩见，双泪望乡垂。
暮角云中戍，残阳天际旗。
更看飞白羽，胡马在封陲。','',''),('quantangshi-16943','送李正字之蜀','武元衡','quantangshi','','卷17','已献甘泉赋，仍登片玉科。
汉官新组绶，蜀国旧烟萝。
劒壁秋云断，巴江夜月多。
无穷别离思，遥寄竹枝歌。','',''),('quantangshi-16944','玉泉寺与润上人望秋山怀张少尹','武元衡','quantangshi','','卷17','山寒天降霜，烟月共苍苍。
况此绿岩晚，尚余丹桂芳。
禅心殊众乐，人世满秋光。
莫怪频回首，孤云思帝乡。','',''),('quantangshi-16945','酬崔使君寄麈尾','武元衡','quantangshi','','卷17','贤人嘉尚同，今制古遗风。
寄我襟怀里，辞君掌握中。
金声劳振远，玉柄借谈空。
执玩驰心处，迢迢巴峡东。','',''),('quantangshi-16946','送邓州潘使君赴任','武元衡','quantangshi','','卷17','川陆一都会，旌旗千里舒。
虎符中禁授，熊轼上流居。
橘柚金难并，池塘练不如。
春风行部日，应驻士元车。','',''),('quantangshi-16947','和李中丞题故将军林亭','武元衡','quantangshi','','卷17','帝里清和节，侯家邸第春。
烟霏瑶草露，苔暗杏梁尘。
城郭悲歌旧，池塘丽句新。
年年车马客，钟鼓乐他人。','',''),('quantangshi-16948','送韦侍御司议赴东都','武元衡','quantangshi','','卷17','洛京千里近，离绪亦纷纷。
文宪芙蓉沼，元方羔雁羣。
河关连巩树，嵩少接秦云。
独有临风思，睽携不可闻。','',''),('quantangshi-16949','送吴侍御司马赴台州','武元衡','quantangshi','','卷17','卢耽佐郡遥，川陆共迢迢。
风景轻吴会，文章变越谣。
烟林繁橘柚，云海浩波潮。
余有灵山梦，前君到石桥。','',''),('quantangshi-16950','送七兄赴歙州','武元衡','quantangshi','','卷17','车马去憧憧，都门闻晓钟。
客程将日远，离绪与春浓。
流水逾千度，归云隔万重。
玉杯倾酒尽，不换惨凄容。','',''),('quantangshi-16951','德宗皇帝挽歌词三首 一','武元衡','quantangshi','','卷17','道启轩皇圣，威扬夏禹功。
讴歌亭育外，文武盛明中。
日月光连璧，烟尘屏大风。
为人祈福处，台树与天通。','',''),('quantangshi-16952','德宗皇帝挽歌词三首 二','武元衡','quantangshi','','卷17','圣历囗勤政，瑶图庆运长。
寿宫开此地，仙驾缈何乡。
风断清笳调，云愁绿斾扬。
上升知不恨，弘济任城王。','',''),('quantangshi-16953','德宗皇帝挽歌词三首 三','武元衡','quantangshi','','卷17','尝闻阊阖前，星拱北辰箓。
今来大明祖，辇驾桥山曲。
松柏韵幽音，鱼龙焰寒烛。
岁岁秋风辞，兆人歌不足。','',''),('quantangshi-16954','顺宗至德大圣皇帝挽歌词三首 一','武元衡','quantangshi','','卷17','桥山同轨会，轩后葬衣冠。
东海风波变，西陵松柏攒。
鼎湖仙已去，金掌露宁干。
万木泉扃月，空怜凫雁寒。','',''),('quantangshi-16955','顺宗至德大圣皇帝挽歌词三首 二','武元衡','quantangshi','','卷17','容卫晓徘徊，严城阊阖开。
乌号龙驭远，遏密凤声哀。
昆浪黄河注，崦嵫白日颓。
恭闻天子孝，不忍望铜台。','',''),('quantangshi-16956','顺宗至德大圣皇帝挽歌词三首 三','武元衡','quantangshi','','卷17','哀挽渭川曲，空歌汾水阳。
夜泉愁更咽，秋日惨无光。
缵夏功传启，兴周业继昌。
回瞻五陵上，烟雨为苍苍。','',''),('quantangshi-16957','昭德皇后挽歌词','武元衡','quantangshi','','卷17','玉扆将迁坐，金鸡忽报晨。
佩环仙驭远，星月夜台新。
剑没川空冷，菱寒镜不春。
国门车马会，多是濯龙亲。','',''),('quantangshi-16958','春晚奉陪相公西亭宴集','武元衡','quantangshi','','卷17','林花春向阑，高会重邀欢。
感物惜芳景，放怀因彩翰。
玉颜穠处并，银烛焰中看。
若折持相赠，风光益别难。','',''),('quantangshi-16959','送崔判官使太原','武元衡','quantangshi','','卷17','劳君车马此逡巡，我与刘君本世亲。
两地山河分节制，十年京洛共风尘。
笙歌几处胡天月，罗绮长留蜀国春。
报主由来须尽敌，相期万里宝刀新。','',''),('quantangshi-16960','幕中诸公有观猎之作因继之','武元衡','quantangshi','','卷17','刀州城北劒山东，甲士屯云骑散风。
旌斾遍张林岭动，豺狼驱尽塞垣空。
衔芦远雁愁萦缴，绕树啼猨怯避弓。
为报府中诸从事，燕然未勒莫论功。','',''),('quantangshi-16961','同幕中诸公送李侍御归朝','武元衡','quantangshi','','卷17','昔年专席奉清朝，今日持书即旧僚。
珠履会中箫管思，白云归处帝乡遥。
巴江暮雨连三峡，剑壁危梁上九霄。
岁月不堪相送尽，颓颜更被别离凋。','',''),('quantangshi-16962','送张六谏议归朝','武元衡','quantangshi','','卷17','诏书前日下丹霄，头戴儒冠脱皂貂。
笛怨柳营烟漠漠，云愁江馆雨萧萧。
鸳鸿得路争先翥，松柏凌寒独后凋。
归去朝端如有问，玉关门外老班超。','',''),('quantangshi-16963','酬严司空荆南见寄','武元衡','quantangshi','','卷17','金貂再领三公府，玉帐连封万户侯。
帘卷青山巫峡晓，烟开碧树渚宫秋。
刘琨坐啸风清塞，谢朓题诗月满楼。
白雪调高歌不得，美人南国翠蛾愁。','',''),('quantangshi-16964','南徐别业早春有怀','武元衡','quantangshi','','卷17','生涯扰扰竟何成，自爱深居隐姓名。
远雁临空翻夕照，残云带雨过春城。
花枝入户犹含润，泉水侵堦乍有声。
虚度年华不相见，离肠怀土并关情。','',''),('quantangshi-16965','摩诃池宴','武元衡','quantangshi','','卷17','摩诃池上春光早，爱水看花日日来。
穠李雪开歌扇掩，绿杨风动舞腰回。
芜台事往空留恨，金谷时危悟惜才。
昼短欲将清夜继，西园自有月裴回。','',''),('quantangshi-16966','至栎阳崇道寺闻严十少府趋侍','武元衡','quantangshi','','卷17','云连万木夕沈沈，草色泉声古院深。
闻说羊车趋盛府，何言琼树在东林。
松筠自古多年契，风月怀贤此夜心。
惆怅送君身未达，不堪摇落听秋砧。','',''),('quantangshi-16967','春暮郊居寄朱舍人','武元衡','quantangshi','','卷17','幽深不让子真居，度日闲眠世事疎。
春水满池新雨霁，香风入户落花余。
目随鸿雁穷苍翠，心寄溪云任卷舒。
回首知音青琐闼，何时一为荐相如。','',''),('quantangshi-16968','送温况游蜀','武元衡','quantangshi','','卷17','游人西去客三巴，身逐孤蓬不定家。
山近峨眉飞暮雨，江连濯锦起朝霞。
云深九折刀州远，路绕千岩剑阁斜。
应到严君开卦处，将余一为问生涯。','',''),('quantangshi-16969','崔敷叹春物将谢恨不同览时余方为事牵束及往寻不遇题之留赠','武元衡','quantangshi','','卷17','九陌迟迟丽景斜，禁街西访隐沦赊。
门依高柳空飞絮，身逐闲云不在家。
轩冕强来趋世路，琴尊空负赏年华。
残阳寂寞东城去，惆怅春风落尽花。','',''),('quantangshi-16970','秋灯对雨寄史近崔积','武元衡','quantangshi','','卷17','坐听宫城传晚漏，起看衰叶下寒枝。
空庭绿草结离念，细雨黄花赠所思。
蟋蟀已惊良节度，茱萸偏忆故人期。
相逢莫厌尊前醉，春去秋来自不知。','',''),('quantangshi-16971','春题龙门香山寺','武元衡','quantangshi','','卷17','众香天上梵仙宫，钟磬寥寥半碧空。
清景乍开松岭月，乱流长响石楼风。
山河杳映春云外，城阙参差茂树中。
欲尽出寻那可得，三千世界本无穷。','',''),('quantangshi-16972','酬陆三与邹十八侍御','武元衡','quantangshi','','卷17','城分流水郭连山，拂露开怀一解颜。
令尹关中仙史会，河阳县里玉人闲。
共怜秋隼惊飞至，久想云鸿待侣还。
莫恨殷勤留此地，东崖桂树昔同攀。','',''),('quantangshi-16973','酬谈校书长安秋夜对月寄诸故旧','武元衡','quantangshi','','卷17','故园千里渺遐情，黄叶萧条白露生。
惊鹊遶枝风满幌，寒钟送晓月当楹。
蓬山高价传新韵，槐市芳年挹盛名。
莫怪孔融悲岁序，五侯门馆重娄卿。','',''),('quantangshi-16974','送田三端公还鄂州','武元衡','quantangshi','','卷17','孤云迢遰恋沧洲，劝酒梨花对白头。
南陌送归车骑合，东城怨别管弦愁。
青油幕里人如玉，黄鹤楼中月并钩。
君去庾公应借问，驰心千里大江流。','',''),('quantangshi-16975','送李秀才赴滑州诣大夫舅','武元衡','quantangshi','','卷17','陌头车马去翩翩，白面怀书美少年。
东武杨公姻娅重，西州谢傅舅甥贤。
长亭叫月新秋雁，官渡含风古树蝉。
知己满朝留不住，贵臣河上拥旌旃。','',''),('quantangshi-16976','秋日书怀','武元衡','quantangshi','','卷17','金貂玉铉奉君恩，夜漏晨钟老掖垣。
参决万机空有愧，静观羣动亦无言。
杯中壮志红颜歇，林下秋声绛叶翻。
倦鸟不知归去日，青芜白露满郊园。','',''),('quantangshi-16977','南昌滩','武元衡','quantangshi','','卷17','渠江明净峡逶迤，船到名滩拽𥮘迟。
橹窡动摇妨作梦，巴童指点笑吟诗。
畲余宿麦黄山腹，日背残花白水湄。
物色可怜心莫限，此行都是独行时。','',''),('quantangshi-16978','奉和圣制丰年多庆九日示怀','武元衡','quantangshi','','卷17','令节寰宇泰，神都佳气浓。
赓歌禹功盛，击壤尧年丰。
九奏碧霄里，千官皇泽中。
南山澄凝黛，曲水清涵空。
金玉美王度，欢康谣国风。
睿文垂日月，永与天无穷。','',''),('quantangshi-16979','夏日陪冯许二侍郎与严祕书游昊天观览旧题寄同里杨华州中丞','武元衡','quantangshi','','卷17','三伏草木变，九城车马烦。
碧霄回骑射，丹洞入桃源。
台殿云浮栋，緌缨鹤在轩。
莫将真破妄，聊用静持喧。
石甃古苔冷，水筠凉簟翻。
黄公垆下叹，旌斾国东门。','',''),('quantangshi-16980','奉和圣制重阳日即事','武元衡','quantangshi','','卷17','玉烛降寒露，我皇歌古风。
重阳德泽展，万国欢娱同。
绮陌拥行骑，香尘凝晓空。
神都自蔼蔼，佳气助葱葱。
律吕阴阳畅，景光天地通。
徒然被鸿霈，无以报玄功。','',''),('quantangshi-16981','秋日台中寄怀简诸僚','武元衡','quantangshi','','卷17','宪府日多事，秋光照碧林。
干云岩翠合，布石地苔深。
忧悔耿遐抱，尘埃缁素襟。
物情牵局促，友道旷招寻。
颓节风霜变，流年芳景侵。
池荷足幽气，烟竹又繁阴。
簪组赤墀恋，池鱼沧海心。
涤烦滞幽赏，永度瑶华音。','',''),('quantangshi-16982','奉酬淮南中书相公见寄','武元衡','quantangshi','','卷17','扬州隋故都，竹使汉名儒。
翊圣恩华异，持衡节制殊。
朝廷连受脤，台座接讦谟。
金玉裁王度，丹书奉帝俞。
九重辞象魏，千[里]握兵符。
铁马秋临塞，虹旌夜渡泸。
江长梅笛怨，天远桂轮孤。
浩叹烟霜晓，芳期兰蕙芜。
雅言书一札，宾海雁东隅。
岁月奔波尽，音徽雾雨濡。
蜀江分井络，锦浪入淮湖。
独抱相思恨，关山不可逾。','',''),('quantangshi-16983','甫构西亭偶题因呈监军及幕中诸公','武元衡','quantangshi','','卷17','瀛海无因泛，昆丘岂易寻。
数峰聊在目，一境暂清心。
悦彼松柏性，爱兹桃李阴。
列芳凭有土，丛干聚成林。
信矣子牟恋，归欤尼父吟。
暗香兰露滴，空翠蕙楼深。
负鼎位尝忝，荷戈年屡侵。
百城烦鞅掌，九仞喜岖嵚。
巴汉溯沿楫，岷峨千万岑。
恩偏不敢去，范蠡畏镕金。','',''),('quantangshi-16984','和杨弘微春日曲江南望','武元衡','quantangshi','','卷17','迟景霭悠悠，伤春南陌头。
暄风一澹荡，遐思几殷忧。
龙去空仙沼，鸾飞掩妓楼。
芳菲余雨露，冠盖旧公侯。
朱戟千门闭，黄鹂百啭愁。
烟蒙宫树晚，花咽石泉流。
寒谷律潜应，中林兰自幽。
商山将避汉，晋室正藩周。
黍稷闻兴叹，琼瑶畏见投。
君心即吾事，微向在沧洲。','',''),('quantangshi-16985','长安秋夜怀陈京昆季','武元衡','quantangshi','','卷17','钟鼓九衢绝，出门千里同。
远情高枕夜，秋思北窗空。
静见烟凝烛，闲听叶坠桐。
玉壶思洞彻，琼树忆葱笼。
萤影疎帘外，鸿声暗雨中。
羇愁难会面，嬾慢责微躬。
甲乙科攀桂，图书阁践蓬。
一瓢非可乐，六翮未因风。
寥落悲秋尽，蹉跎惜岁穷。
明朝不相见，流泪菊花丛。','',''),('quantangshi-16986','冬日汉江南行将赴夏口途次江陵界寄裴尚书','武元衡','quantangshi','','卷17','五部拥双旌，南依墨客卿。
关山迥梁甸，波浪接湓城。
烟景迷时候，云帆渺去程。
蛤珠冯月吐，芦雁触罗惊。
浦树凝寒晦，江天湛镜清。
赏心随处惬，壮志逐年轻。
舟檝不可驻，提封如任情。
向方曾指路，射策许言兵。
兰渚歇芳意，菱歌非应声。
元戎武昌守，羊祜幸连营。','',''),('quantangshi-16987','奉酬中书李相公早朝于中书候传点偶书所怀','武元衡','quantangshi','','卷17','寥落曙钟断，微明烟月沈。
翠霞仙仗合，清漏掖垣深。
北极星遥拱，南山阙迥临。
兰釭竟晓焰，琪树欲秋阴。
霄汉慙联步，貂蝉愧并簪。
德容温比玉，王度式如金。
鱼水千里运，箫韶九奏音。
代天惊度日，掷地喜开襟。
文武时方泰，唐虞道可寻。
忝陪申及甫，清净奉尧心。','',''),('quantangshi-16988','甲午岁相国李公有北园寄赠之作吟翫历时屡促酬答机务不暇未及报章今古遽分电波增感留墓劒而心许感邻笛而意伤寓哀冥寞以广遗韵云','武元衡','quantangshi','','卷17','机事劳西掖，幽怀寄北园。
鹤巢深更静，蝉噪断犹喧。
仙酝百花馥，艳歌双袖翻。
碧云诗变雅，皇泽叶流根。
未报雕龙赠，俄伤泪劒痕。
佳城关白日，哀挽向青门。
礼命公台重，烟霜陇树繁。
天高不可问，空使辅星昏。','',''),('quantangshi-16989','和杨三舍人晚秋与崔二舍人张祕监苗考功同游昊天观时中书寓直不得陪随因追往年曾与旧僚联游此观纪题在壁已有沦亡书事感怀輙以呈寄兼呈东省三给事之作杨君见徴鄙词因以继和','武元衡','quantangshi','','卷17','瑶圃高秋会，金闺奉诏辰。
朱轮天上客，白石洞中人。
佩响泉声杂，朝衣羽服亲。
九重青琐闭，三秀紫芝新。
化药秦方士，偷桃汉侍臣。
玉笙王子驾，辽鹤令威身。
叹逝颓波速，缄词丽曲春。
重将凄恨意，苔壁问遗尘。','',''),('quantangshi-16990','酬李十一尚书西亭暇日书怀见寄十二韵之作','武元衡','quantangshi','','卷17','鼎铉昔云忝，西南分主忧。
烟尘开僰道，旌节护蛮陬。
任重功无立，力微恩未酬。
据鞍慙齿发，责帅惧春秋。
高德闻郑履，俭居称晏裘。
三刀君入梦，九折我回輈。
时景屡迁易，兹言期退休。
方追故山事，岂谓台堦留。
遐抱清净理，眷言兰杜幽。
一缄琼玖赠，万里别离愁。
巴岭云外没，蜀江天际流。
怀贤耿遥思，相望凤池头。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-16991','秋怀奉寄朱补阙','武元衡','quantangshi','','卷17','上苑繁霜降，骚人起恨初。
白云深陋巷，衰草遍闲居。
暮色秋烟重，寒声牖叶虚。
潘生秋思苦，陶令世情疎。
已制归田赋，犹陈谏猎书。
不知青琐客，投分竟何如。','',''),('quantangshi-16992','奉酬中书相公至日圜丘行事合于中书宿斋移止于集贤院叙情见寄之什','武元衡','quantangshi','','卷17','郊庙祗严祀，斋庄觌上玄。
别开金虎观，不离紫微天。
树古长杨接，池清太液连。
仲山方补衮，文举自伤年。
风溢铜壶漏，香凝绮阁烟。
仍闻白雪唱，流咏满鵾弦。','',''),('quantangshi-16993','途次','武元衡','quantangshi','','卷17','去国策羸马，劳歌行路难。
地崇秦制险，人乐汉恩宽。
御沼澄泉碧，宫梨拂露丹。
鼎成仙驭远，龙化宿云残。
不问三苗宠，谁陪万国欢。
至今松桂色，长助玉楼寒。','',''),('quantangshi-16994','题故蔡国公主九华观上池院','武元衡','quantangshi','','卷17','朱门临九衢，云木蔼仙居。
曲沼天波接，层台凤舞余。
曙烟深碧筱，香露湿红蕖。
瑶瑟含风韵，纱窗积翠虚。
