满堂谁是知音者，不惜千金与莫愁。','',''),('quantangshi-17072','酬韦胄曹','武元衡','quantangshi','','卷18','相逢异县蹉跎意，无复少年容易欢。
桃李美人攀折尽，何如松柏四时寒。','',''),('quantangshi-17073','同幕府夜宴惜花','武元衡','quantangshi','','卷18','芳草落花明月榭，朝云暮雨锦城春。
莫愁红艳风前散，自有青蛾镜里人。','',''),('quantangshi-17074','代佳人赠张郎中','武元衡','quantangshi','','卷18','洛阳佳丽本神仙，冰雪颜容桃李年。
心爱阮郎留不住，独将珠泪湿红铅。','',''),('quantangshi-17075','饯裴行军赴朝命','武元衡','quantangshi','','卷18','来时圣主假光辉，心恃朝恩计日归。
谁料忽成云雨别，独将边泪洒戎衣。','',''),('quantangshi-17076','秋日经潼关感寓','武元衡','quantangshi','','卷18','昔年曾逐汉征东，三授兵符百战中。
力保山河嗟下世，秋风牢落故营空。','',''),('quantangshi-17077','赠歌人','武元衡','quantangshi','','卷18','仙歌静转玉箫催，疑是流莺禁苑来。
他日相思梦巫峡，莫敎云雨晦阳台。','',''),('quantangshi-17078','见郭侍郎题壁','武元衡','quantangshi','','卷18','万里枫江偶问程，青苔壁上故人名。
悠悠身世限南北，一别十年空复情。','',''),('quantangshi-17079','癸巳岁吉甫圜丘摄事合于中书后阁宿斋常负忝愧移止于集贤院会门下相公以七言垂寄亦有所酬短章绝韵不足抒意因叙所怀奉寄相公兼呈集贤院诸学士','李吉甫','quantangshi','','卷18','淮海同三入，枢衡过六年。
庙斋兢永夕，书府会羣仙。
粉壁连霜曙，冰池对月圆。
岁时忧里换，钟漏静中传。
蓬发颜空老，松心契独全。
赠言因傅说，垂训在三篇。','',''),('quantangshi-17080','夏夜北园即事寄门下武相公','李吉甫','quantangshi','','卷18','结构非华宇，登临似古原。
僻殊萧相宅，芜胜邵平园。
避暑依南庑，追凉在北轩。
烟霞霄外静，草露月中繁。
鹊绕惊还止，虫吟思不喧。
怀君欲有赠，宿昔贵忘言。','',''),('quantangshi-17081','九日小园独谣赠门下武相公','李吉甫','quantangshi','','卷18','小园休沐暇，暂与故山期。
树杪悬丹枣，苔阴落紫梨。
舞丛新菊徧，绕格古藤垂。
受露红兰晚，迎霜白薤肥。
上公留凤沼，冠劒侍清祠。
应念端居者，长慙补衮诗。','',''),('quantangshi-17082','怀伊川赋','李吉甫','quantangshi','','卷18','龙门南岳尽伊原，草树人烟目所存。
正是北州梨枣熟，梦魂秋日到郊园。','',''),('quantangshi-17083','奉和武相公省中宿斋酬李相公见寄','鄭絪','quantangshi','','卷18','高阁安仁省，名园广武庐。
沐兰朝太一，种竹咏华胥。
禁静疎钟彻，庭开爽韵虚。
洪钧齐万物，缥帙整羣书。
寒露滋新菊，秋风落故蕖。
同怀不同赏，幽意竟何如。','',''),('quantangshi-17084','寒夜闻霜钟','鄭絪','quantangshi','','卷18','霜钟初应律，寂寂出重林。
拂水宜清听，凌空散逈音。
舂容时未歇，摇曳夜方深。
月下和虚籁，风前间远砧。
净兼寒漏彻，闲畏曙更侵。
遥想千山外，泠泠何处寻。','',''),('quantangshi-17085','奉酬宣上人九月十五日东亭望月见赠因怀紫阁旧游','鄭絪','quantangshi','','卷18','中年偶逐鸳鸾侣，弱岁多从麋鹿羣。
紫阁道流今不见，红楼禅客早曾闻。
松斋月朗星初散，苔砌霜繁夜欲分。
一览彩牋佳句满，何人更咏惠休文。','',''),('quantangshi-17086','九日登高怀邵二','鄭絪','quantangshi','','卷18','簪茱泛菊俯平阡，饮过三杯却惘然。
十岁此辰同醉友，登高各处已三年。','',''),('quantangshi-17087','享太庙乐章','鄭絪','quantangshi','','卷18','于穆时文，受天明命。
允恭玄默，化成理定。
出震嗣德，应干传圣。
猗欤缉熙，千亿流庆。','',''),('quantangshi-17088','句','鄭絪','quantangshi','','卷18','情人共惆怅，良友不同游。','',''),('quantangshi-17089','和黄门相公诏还题石门洞','鄭餘慶','quantangshi','','卷18','紫氛随马处，黄阁驻车情。
嵌壑惊山势，周滩恋水声。
地分三蜀限，关志百牢名。
琬琰攀酬郢，微言鼎饪情。','',''),('quantangshi-17090','享太庙乐章','鄭餘慶','quantangshi','','卷18','开邸除暴，时迈勋尊。
三元告命，四极骏奔。
金枝翠叶，辉烛瑶琨。
象德亿载，贻庆汤孙。','',''),('quantangshi-17091','和黄门武相公诏还题石门洞','趙宗儒','quantangshi','','卷18','益部恩辉降，同荣汉相还。
韶芳满归路，轩骑出重关。
望日朝天阙，披云过蜀山。
更题风雅韵，永绝翠嵓间。','',''),('quantangshi-17092','和武相公锦楼翫月得浓字','柳公綽','quantangshi','','卷18','此夜年年月，偏宜此地逢。
近看江水浅，遥辨雪山重。
万井金花肃，千林玉露浓。
不唯楼上思，飞盖亦陪从。','',''),('quantangshi-17093','题梓州牛头寺','柳公綽','quantangshi','','卷18','一出西城第二桥，两边山木晚萧萧。
井花净洗行人耳，留听溪声入夜潮。','',''),('quantangshi-17094','赠毛仙翁','柳公綽','quantangshi','','卷18','桃源千里远，花洞四时春。
中有含真客，长为不死人。
松高枝叶茂，鹤老羽毛新。
莫遣同篱槿，朝荣暮化尘。','',''),('quantangshi-17095','和武相公中秋锦楼翫月得苍字','張正一','quantangshi','','卷18','高秋今夜月，皓色正苍苍。
远水澄如练，孤鸿逈带霜。
旅人方积思，繁宿稍沈光。
朱槛叨陪赏，尤宜清漏长。','',''),('quantangshi-17096','奉和武相公中秋锦楼翫月得来字','徐放','quantangshi','','卷18','玉露中秋夜，金波碧落开。
鹊惊初泛滥，鸿思共裴回。
远月清光徧，高空爽气来。
此时陪永望，更得上燕台。','',''),('quantangshi-17097','和武相公中秋锦楼翫月 一','崔備','quantangshi','','卷18','清景同千里，寒光尽一年。
竟天多雁过，通夕少人眠。
照别江楼上，添愁野帐前。
隋侯恩未报，犹有夜珠圆。','',''),('quantangshi-17098','和武相公中秋锦楼翫月 二','崔備','quantangshi','','卷18','四时皆有月，一夜独当秋。
照耀初含露，裴回正满楼。
遥连雪山净，逈入锦江流。
愿以清光末，年年许从游。','',''),('quantangshi-17099','奉陪武相公西亭夜宴陆郎中','崔備','quantangshi','','卷18','宾阁玳筵开，通宵递玉杯。
尘随歌扇起，雪逐舞衣回。
剪烛清光发，添香暖气来。
令君敦宿好，更为一裴回。','',''),('quantangshi-17100','清溪路中寄诸公','崔備','quantangshi','','卷18','偏郡隔云岑，回溪路更深。
少留攀桂树，长渴望梅林。
野笋资公膳，山花慰客心。
别来无信息，可谓井瓶沈。','',''),('quantangshi-17101','奉酬中书相公至日圜丘行事合于中书宿直移止于集贤院叙情见寄之什','崔備','quantangshi','','卷18','典籍开书府，恩荣避鼎司。
郊丘资有事，斋戒守无为。
宿雾蒙琼树，余香覆玉墀。
进经逢乙夜，展礼值明时。
勋共山河列，名同竹帛垂。
年年佐尧舜，相与致雍熙。','',''),('quantangshi-17102','使院忆山中道侣兼怀李约','崔備','quantangshi','','卷18','松竹去名岳，衡茅思旧居。
山君水上印，天女月中书。
旧秩芸香在，空匳药气余。
褐衣宽易揽，白发少难梳。
病柳伤摧折，残花惜扫除。
忆巢同倦鸟，避网甚跳鱼。
阮巷惭交绝，商嵓愧迹疎。
与君非宦侣，何日共樵渔。','',''),('quantangshi-17103','奉陪武相公西亭夜[宴]陆郎中','蕭祜','quantangshi','','卷18','弘阁陈芳宴，佳宾此会难。
交逢贵日重，醉得少时欢。
舒黛凝歌思，求音足笔端。
一闻清佩动，珠玉夜珊珊。','',''),('quantangshi-17104','游石堂观','蕭祜','quantangshi','','卷18','西山高高何所如，上有古昔真人居。
嵚崖巨石自成室，其下磅礴含清虚。
我来斯邑访遗迹，乃遇沈生躭载籍。
沈生为政哀惸[嫠]，又能索隐探灵奇。
欣然向我话佳境，与我崎岖到山顶。
甘瓜剖绿出寒泉，碧瓯浮花酌春茗。
嚼瓜啜茗身清凉，汗消絺綌如迎霜。
胡为空山百草花，倏尔笾豆肆我旁。
始惊知周无小大，力寡多方验斯在。
妙用腾声冠盖间，胜游恣意烟霞外。
故碑石像凡几年，云郁雨霏生绿烟。
我知游此多灵仙，缥缈月中飞下天。
天风微微夕露委，松梢飕飕晓声起。
凤去空遗箫管音，星翻寥落银河水。
劝君学道此时来，结茅独宿何辽哉。
斋心玄默感灵卫，必见鸾鹤相裴回。
我爱崇山双劒北，峰如人首拄天黑。
羣仙伛偻势奔走，壮若归尊趋有德。
半岩有洞顶有池，出入灵怪潜蛟螭。
我去不得昼夜思，梦游曾信南风吹。
南风吹我到林岭，故国不见秦天逈。
山花名药扑地香，月色泉声洞心冷。
荫松散发逢异人，寂寞旷然口不言。
道陵公远莫能识，发短耳长谁独存。
司农惊觉忽惆怅，可惜所游俱是妄。
蕴怀耿耿谁与言，直至今来意通形神开。
拥传又恨斜阳催，一丘人境尚堪恋，何况海上金银台。','',''),('quantangshi-17105','奉陪武相公西亭夜宴陆郎中','王良士','quantangshi','','卷18','芳气袭猗兰，青云展旧欢。
仙来红烛下，花发彩毫端。
海岳期方远，松筠岁正寒。
仍闻言赠处，一字重琅玕。','',''),('quantangshi-17106','南至日隔霜仗望含元殿炉烟','王良士','quantangshi','','卷18','抗殿疏龙首，高高接上玄。
节当南至日，星是北辰天。
宝戟罗仙仗，金炉引御烟。
霏微双阙丽，容曳九门连。
拂曙祥光满，分晴瑞色鲜。
一阳今在历，生植仰陶甄。','',''),('quantangshi-17107','奉陪武相公西亭夜宴陆郎中','獨孤實','quantangshi','','卷18','仙郎膺上才，夜宴接三台。
烛引银河转，花连锦帐开。
静看歌扇举，不觉舞腰回。
寥落东方曙，无辞尽玉杯。','',''),('quantangshi-17108','奉陪武相公西亭夜宴陆郎中','盧士政','quantangshi','','卷18','华堂良宴开，星使自天来。
舞转朱丝逐，歌余素扇回。
水光凌曲槛，夜色霭高台。
不在宾阶末，何由接上台。','',''),('quantangshi-17109','闻莺','于敖','quantangshi','','卷18','玉绳河汉晓纵横，万籁潜收莺独鸣。
能将百啭清心骨，宁止闲窗梦不成。','',''),('quantangshi-17110','和武相公闻莺','皇甫鏞','quantangshi','','卷18','华馆沈沈曙境清，伯劳初啭月微明。
不知台座宵吟久，犹向花窗惊梦声。','',''),('quantangshi-17111','白露为霜','顏粲','quantangshi','','卷18','悲秋将岁晚，繁露已成霜。
徧渚芦先白，霑篱菊自黄。
应钟鸣远寺，拥雁度三湘。
气逼襦衣薄，寒侵宵梦长。
满庭添月色，拂水敛荷香。
独念蓬门下，穷年在一方。','',''),('quantangshi-17112','吴宫敎美人战','顏粲','quantangshi','','卷18','有客陈兵画，功成欲霸吴。
玉颜承将略，金钿指军符。
转佩风云暗，鸣鼙锦绣趋。
雪花频落粉，香汗尽流珠。
掩笑谁干令，严刑必用诛。
至今孙子术，犹可静边隅。','',''),('quantangshi-17113','月暎清淮流','徐敞','quantangshi','','卷18','遥夜淮弥净，浮空月正明。
虚无含气白，凝澹暎波清。
见底深还浅，居高缺复盈。
处柔知坎德，持洁表阴精。
利物功难并，和光道已成。
安流方利涉，应鉴此时情。','',''),('quantangshi-17114','圆灵水镜','徐敞','quantangshi','','卷18','浮光上东洛，杨彩满圆灵。
明灭沦江水，盈虚逐砌蓂。
不分沙岸白，偏照海山清。
练色临窗牖，蟾光霭户庭。
成轮疑璧影，初魄类弓形。
远近凝清质，娟娟出众星。','',''),('quantangshi-17115','虹藏不见','徐敞','quantangshi','','卷18','迎冬小雪至，应节晚虹藏。
玉气徒成象，星精不散光。
美人初比色，飞鸟罢呈祥。
石涧收晴影，天津失彩梁。
霏霏空暮雨，杳杳暎残阳。
舒卷应时令，因知圣历长。','',''),('quantangshi-17116','白露为霜','徐敞','quantangshi','','卷18','早寒青女至，零露结为霜。
入夜飞清景，凌晨积素光。
驷星初皙皙，葭菼复苍苍。
色冒沙滩白，威加木叶黄。
鲜辉袭纨扇，杀气掩干将。
葛屦那堪履，徒令君子伤。','',''),('quantangshi-17117','赋得金茎露','徐敞','quantangshi','','卷18','武帝贵长生，延年饵玉英。
铜盘贮珠露，仙掌抗金茎。
拂曙氛埃敛，凌空沆瀣清。
岧嶤捧瑞气，巃嵸出宫城。
势入浮云耸，形标霁色明。
大君当御宇，何必去蓬瀛。','',''),('quantangshi-17118','圆灵水镜','張聿','quantangshi','','卷18','凤池开月镜，清莹写寥天。
影散微波上，光含片玉悬。
菱花凝泛灧，桂树暎清鲜。
乐广披云日，山涛卷雾年。
濯缨何处去，鉴物自堪妍。
回首看云液，蟾蜍势正圆。','',''),('quantangshi-17119','景风扇物','張聿','quantangshi','','卷18','何处青苹末，呈祥起远空。
晓来摇草树，轻度净尘蒙。
水上微波动，林前媚景通。
寥天鸣万籁，兰径长幽藂。
渐扬抟扶势，应从槖龠功。
开襟若有日，愿覩大王风。','',''),('quantangshi-17120','劒化为龙','張聿','quantangshi','','卷18','古劒诚难屈，精明有所从。
沈埋方出狱，合会却成龙。
牛斗光初歇，蜿蜒气渐浓。
云涛透百丈，水府跃千重。
拖尾迷莲锷，张鳞露锦容。
至今沙岸下，谁得覩玄踪。','',''),('quantangshi-17121','余瑞麦','張聿','quantangshi','','卷18','瑞麦生尧日，芃芃雨露偏。
两岐分更合，异亩頴仍连。
冀获明王庆，宁唯太守贤。
仁风吹靡靡，甘雨长芊芊。
圣德应多稔，皇家配有年。
已闻天下泰，谁为济西田。','',''),('quantangshi-17122','赋得[首夏]犹清和','張聿','quantangshi','','卷18','早夏宜春景，和光起禁城。
祝融将御节，炎帝启朱明。
日送残花晚，风过御苑清。
郊原浮麦气，池沼发荷英。
树影临山动，禽飞入汉轻。
幸逢尧禹化，全胜谷中情。','',''),('quantangshi-17123','移居洞庭','麴信陵','quantangshi','','卷18','重林将叠嶂，此处可逃秦。
水隔人间世，花开洞里春。
荷锄分地利，纵酒乐天真。
万事更何有，吾今已外身。','',''),('quantangshi-17124','吴门送客','麴信陵','quantangshi','','卷18','乱山吴苑外，临水让王祠。
素是伤情处，春非送客时。
不须愁落日，且愿驻青丝。
千里会应到，一尊谁共持。','',''),('quantangshi-17125','长安道','麴信陵','quantangshi','','卷18','朱门暎绿杨，双阙抵通庄。
玉佩声逾远，红尘犹自香。','',''),('quantangshi-17126','出自贼中谒恒上人','麴信陵','quantangshi','','卷18','再拜吾师喜复悲，誓心从此永归依。
浮生恍忽若真梦，何事于中有是非。','',''),('quantangshi-17127','过真律师旧院','麴信陵','quantangshi','','卷18','寂然秋院闭秋光，过客闲来礼影堂。
坚冰销尽还成水，本自无形何足伤。','',''),('quantangshi-17128','酬谈上人咏海石榴','麴信陵','quantangshi','','卷18','真僧相劝外浮华，万法无常可叹嗟。
但试寻思阶下树，何人种此我看花。','',''),('quantangshi-17129','句','麴信陵','quantangshi','','卷18','台笠冒山雨，渚田耕荇花。','',''),('quantangshi-17130','冬日可爱','張正元','quantangshi','','卷18','寒日临清昼，辽天一望时。
未消埋径雪，先暖读书帷。
属思光难驻，舒情影若遗。
晋臣曾比德，谢客昔言诗。
散彩宁偏煦，流阴信不追。
余辉如可就，回烛幸无私。','',''),('quantangshi-17131','临川羡鱼','張正元','quantangshi','','卷18','有客百愁侵，求鱼正在今。
广川何渺漫，高岸几登临。
风水宁相阻，烟霞岂惮深。
不应同逐鹿，讵肯比从禽。
结网非无力，忘筌自有心。
永存芳饵在，伫立思沈沈。','',''),('quantangshi-17132','青云干吕','王履貞','quantangshi','','卷18','异方占瑞气，干吕见青云。
表圣兴中国，来王谒大君。
迎祥殊大乐，叶庆类横汾。
自感明时起，非因触石分。
暎霄难辨色，从吹乍成文。
须使流千载，垂芳在典坟。','',''),('quantangshi-17133','青云干吕 一','彭伉','quantangshi','','卷18','祥辉上干吕，郁郁又纷纷。
远示无为化，将明至道君。
势凝千里静，色向九霄分。
已见从龙意，宁知触石文。
状烟殊散漫，捧日更氛氲。
自使来宾国，西瞻仰瑞云。','',''),('quantangshi-17134','青云干吕 二','彭伉','quantangshi','','卷18','圣布中区化，祥符异域云。
含春初应吕，晕碧已成文。
东起随风暖，西流共日曛。
升时嘉异月，为庆等凝汾。
轻与晴烟比，高将晓雾分。
飘飘如可致，愿此翊明君。','',''),('quantangshi-17135','寄妻','彭伉','quantangshi','','卷18','莫讶相如献赋迟，锦书谁道泪沾衣。
不须化作山头石，待我堂前折桂枝。','',''),('quantangshi-17136','青云干吕','林藻','quantangshi','','卷18','应节偏干吕，亭亭在紫氛。
缀空初布影，捧日已成文。
结盖祥光迥，为楼翠色分。
还同起封上，更似出横汾。
作瑞来藩国，呈形表圣君。
裴回如有托，谁道比闲云。','',''),('quantangshi-17137','吴宫敎战','林藻','quantangshi','','卷18','强吴矜霸略，讲武在深宫。
尽出娇娥辈，先观上将风。
挥戈罗袖卷，擐甲汗装红。
轻笑分旗下，含羞入队中。
鼓停行未整，刑举令方崇。
自可威邻国，何劳骋战功。','',''),('quantangshi-17138','梨岭','林藻','quantangshi','','卷18','曾向岭头题姓字，不穿杨叶不言归。
弟兄各折一枝桂，还向岭头联影飞。','',''),('quantangshi-17139','赠冯宿','李觀','quantangshi','','卷18','寒城上秦原，游子衣飘飘。
黑云截万里，猎火从中烧。
阴空蒸长烟，杀气独不销。
冰交石可裂，风疾山如摇。
时无青松心，顾我独不凋。','',''),('quantangshi-17140','宿裴友书斋','李觀','quantangshi','','卷18','卧君山窗下，山鸟与我言。
清风何飕飗，松栢中夜繁。
久游失归趣，宿此似故园。
林烟横近郊，溪月落古原。
穉子不待晓，花间出柴门。','',''),('quantangshi-17141','御沟新柳','李觀','quantangshi','','卷18','御沟回广陌，芳柳对行人。
翠色枝枝满，年光树树新。
畏逢攀折客，愁见别离辰。
近暎章台骑，遥分禁苑春。
嫩阴初覆水，高影渐离尘。
莫入胡儿笛，还令泪湿巾。','',''),('quantangshi-17142','试中和节诏赐公卿尺诗','李觀','quantangshi','','卷18','淑节韶光媚，皇明宠锡崇。
具寮颁玉尺，成器幸良工。
岂止寻常用，将传度量同。
人何不取利，物亦赖其功。
紫翰宣殊造，丹诚厉匪躬。
奉之无失坠，恩泽自天中。','',''),('quantangshi-17143','省试恩赐耆老布帛','李絳','quantangshi','','卷18','涣汗中天发，殊私海外存。
衰颜逢圣代，华发受皇恩。
烛物明尧日，垂衣辟禹门。
惜时悲落景，赐帛慰余魂。
厚泽沾翔泳，微生保子孙。
盛明今尚齿，欢奉九衢罇。','',''),('quantangshi-17144','和裴相国答张秘书赠马诗','李絳','quantangshi','','卷18','高才名价欲凌云，上驷光华远赠君。
念旧露垂丞相简，感知星动客卿文。
纵横逸气宁称力，驰骋长途定出羣。
伏枥莫令空度岁，黄金结束取功勋。','',''),('quantangshi-17145','赐耆老布帛','崔樞','quantangshi','','卷18','殊私及耆老，圣德赈黎元。
布帛忻天赐，生涯作主恩。
情均皆挟纩，礼异贲丘园。
庆洽时方泰，仁沾月告存。
宁知酬雨露，空识荷干坤。
击壤将何幸，裴回望九门。','',''),('quantangshi-17146','齐优开笼飞去所献楚王鹄','崔樞','quantangshi','','卷18','受命笼齐鹄，交欢献楚王。
惠心先巧辩，戢羽见回翔。
意适清风远，忧除白日长。
度云摇旧影，过树阅新芳。
直取名翻重，宁唯好不伤。
谁言滑稽理，千载戒禽荒。','',''),('quantangshi-17147','试中和节诏赐公卿尺诗','陸復禮','quantangshi','','卷18','春仲令初吉，欢娱乐大中。
皇恩贞百度，宝尺赐羣公。
欲使方隅法，还令规矩同。
捧观珍质丽，拜受圣恩崇。
如荷丘山重，思酬方寸功。
从兹度天地，与国庆无穷。','',''),('quantangshi-17148','赋得白云起封中','李正辭','quantangshi','','卷18','千年泰山顶，云起汉皇封。
不作奇峯状，宁分触石容。
为霖虽易得，表圣自难逢。
冉冉排空上，依依叠影重。
素光非曳练，灵贶是从龙。
岂学无心出，东西任所从。','',''),('quantangshi-17149','赋得白云起封中','張嗣初','quantangshi','','卷18','英英白云起，呈瑞出封中。
表圣宁因地，逢时岂待风。
浮光弥皎洁，流影更冲融。
自叶尧年美，谁云汉日同。
金泥光乍掩，玉检气潜通。
欲与非烟并，亭亭不散空。','',''),('quantangshi-17150','春色满皇州','張嗣初','quantangshi','','卷18','何处年华好，皇州淑气匀。
韶阳潜应律，草木暗迎春。
柳变金堤畔，兰抽曲水滨。
轻黄垂辇道，微绿映天津。
丽景浮丹阙，晴光拥紫宸。
不知幽远地，今日几枝新。','',''),('quantangshi-17151','日暮碧云合','許康佐','quantangshi','','卷18','日际愁阴生，天涯暮云碧。
重重不辨盖，沈沈乍如积。
林色黯疑暝，隟光俄已夕。
出岫且从龙，萦空宁触石。
余辉澹瑶草，浮影凝绮席。
时景讵能留，几思轻尺璧。','',''),('quantangshi-17152','白云起封中','許康佐','quantangshi','','卷18','英英白云起，呈瑞出封中。
表圣宁依地，逢时岂待风。
浮辉弥皎洁，流影更冲融。
自叶尧天美，谁言汉日同。
泥金光乍掩，检玉气俄通。
犹愿非烟瑞，亭亭不散空。','',''),('quantangshi-17153','石季伦金谷园','許堯佐','quantangshi','','卷18','石氏遗文在，凄凉见故园。
轻风思奏乐，衰草忆行轩。
舞榭苍苔掩，歌台落叶繁。
断云归旧壑，流水咽新源。
曲沼残烟敛，丛篁宿鸟喧。
唯余池上月，犹似对金尊。','',''),('quantangshi-17154','石季伦金谷园','李君房','quantangshi','','卷18','梓泽风流地，凄凉迹尚存。
残芳迷妓女，衰草忆王孙。
舞态随人谢，歌声寄鸟言。
池平森灌木，月落吊空园。
流水悲难驻，浮云影自翻。
宾阶余藓石，车马讵喧喧。','',''),('quantangshi-17155','享惠昭太子庙乐章登歌','杜羔','quantangshi','','卷18','因心克孝，位震遗芬。
宾天道茂，轸怀气分。
发只乃祀，咳叹如闻。
二歌斯升，以咏德薰。','',''),('quantangshi-17156','南至日隔仗望含元殿香炉','車𬘔','quantangshi','','卷18','抗殿疏元首，高高接上元。
节当南至日，星是北辰天。
宝戟罗仙仗，金炉引瑞烟。
霏微双阙丽，溶曳九州连。
拂曙祥光满，分晴晓色鲜。
一阳今在历，生植愿陶甄。','',''),('quantangshi-17157','奉和圣制九月十八日赐百寮追赏因书所怀','權德輿','quantangshi','','卷18','锡宴朝野洽，追欢尧舜情。
秋堂丝管动，水榭烟霞生。
黄花媚新霁，碧树含余清。
同和六律应，交泰万宇平。
春藻下中天，湛恩阐文明。
小臣谅何以，亦此彯华缨。','',''),('quantangshi-17158','奉和圣制九日言怀赐中书门下及百寮','權德輿','quantangshi','','卷18','令节在丰岁，皇情喜乂安。
丝竹调六律，簪裾列千官。
烟霜暮景清，水木秋光寒。
筵开曲池上，望尽终南端。
天文丽庆霄，墨妙惊飞鸾。
愿言黄花酒，永奉今日欢。','',''),('quantangshi-17159','奉和圣制重阳日中外同欢以诗言志因示百僚','權德輿','quantangshi','','卷18','玉醴宴嘉节，拜恩欢有余。
煌煌菊花秀，馥馥萸房舒。
白露秋稼熟，清风天籁虚。
和声度箫韶，瑞气深储胥。
百辟皆醉止，万方今宴如。
宸衷在化成，藻思焕琼琚。
微臣徒窃拚，岂足歌唐虞。','',''),('quantangshi-17160','奉和圣制中春麟德殿会百寮观新乐','權德輿','quantangshi','','卷18','仲春蔼芳景，内庭宴羣臣。
森森列干戚，济济趋钩陈。
大乐本天地，中和序人伦。
正声迈咸濩，易象含羲文。
玉俎映朝服，金钿明舞茵。
韶光雪初霁，圣藻风自薫。
时泰恩泽溥，功成行缀新。
赓歌仰昭回，窃比华封人。','',''),('quantangshi-17161','奉和圣制中和节赐百官宴集因示后怀','權德輿','quantangshi','','卷18','万方庆嘉节，宴喜皇泽均。
晓开蓂叶初，景丽星鸟春。
藻思贞百度，着明并三辰。
物情舒在阳，时令弘至仁。
衢酒和乐被，薰弦声曲新。
赓歌武弁侧，永荷玄化醇。','',''),('quantangshi-17162','奉和圣制重阳日即事六韵','權德輿','quantangshi','','卷18','嘉节在阳数，至欢朝野同。
恩随千钟洽，庆属五稼丰。
时菊洗露华，秋池涵霁空。
金丝响仙乐，劒舃罗宗公。
天道光下济，睿词敷大中。
多慙撃壤曲，何以答尧聪。','',''),('quantangshi-17163','奉和圣制丰年多庆九日示怀','權德輿','quantangshi','','卷18','寒露应秋杪，清光澄曙空。
泽均行苇厚，年庆华黍丰。
声明畅八表，宴喜陶九功。
文丽日月合，乐和天地同。
圣言在推诚，臣职惟匪躬。
琐细何以报，翾飞淳化中。','',''),('quantangshi-17164','赠文敬太子庙时享退文舞迎武舞乐章','權德輿','quantangshi','','卷18','干旄羽龠相亏蔽，一进一退殊行缀。
昔献三雍盛礼容，今陈六佾崇仪制。','',''),('quantangshi-17165','读谷梁传二首 一','權德輿','quantangshi','','卷18','荀寅士吉射，诚乃蔽聪明。
奈何赵志父，专举晋阳兵。
下令汉七国，借此以为名。
吾嘉徙薪智，祸乱何由生。','',''),('quantangshi-17166','读谷梁传二首 二','權德輿','quantangshi','','卷18','忆昔溴梁会，岂伊无诸侯。
羣臣自盟歃，君政如赘旒。
有力则宗楚，何人复尊周。
空文徒尔贬，见此[眦]□血流。','',''),('quantangshi-17167','刘绍相访夜话因书即事','權德輿','quantangshi','','卷18','故人怆久别，兹夕欵郊扉。
山僮漉野醖，穉子褰书帷。
清露泫珠莹，金波流玉徽。
忘言我造适，瞪视君无违。
但令静胜躁，自使癯者肥。
不待蘧生年，从此知昔非。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-17168','卧病喜惠上人李炼师茅处士见访因以赠','權德輿','quantangshi','','卷18','沈疴结繁虑，卧见书窗曙。
方外三贤人，惠然来相亲。
整巾起曳策，喜非车马客。
支郎有佳文，新句淩碧云。
霓裳何飘飘，浩志淩紫氛。
复有沈冥士，远系三茅君。
各言麋鹿性，不与簪组羣。
清言出象系，旷迹逃玄纁。
心源蹔澄寂，世故方糺纷。
终当逐师辈，岩桂香氲芬。','',''),('quantangshi-17169','多病戏书因示长孺','權德輿','quantangshi','','卷18','行年未四十，已觉百病生。
眼眩飞蝇影，耳厌远蝉声。
甘辛败六藏，冰炭交七情。
唯思曲肱枕，搔首掷华缨。','',''),('quantangshi-17170','古兴','權德輿','quantangshi','','卷18','月中有桂树，无翼难上天。
海底有龙珠，下隔万丈渊。
人生大限虽百岁，就中三十称一世。
晦明乌兔相推迁，雪霜渐到双鬓边。
沈忧戚戚多浩叹，不得如意居太半。
一气暂聚常恐散，黄河清兮白石烂。','',''),('quantangshi-17171','感寓','權德輿','quantangshi','','卷18','残雨倦欹枕，病中时序分。
秋虫与秋叶，一夜隔窗闻。
虚室对摇落，晤言无与羣。
冥心试观化，世故如丝棼。
但看鸢戾天，岂见山出云。
下里徒撃节，朱弦秘南薰。
梧桐秀朝阳，上有威凤文。
终待九成奏，来仪瑞吾君。','',''),('quantangshi-17172','跌伤伏枕有劝醲酒者蹔忘所苦因有一绝','權德輿','quantangshi','','卷18','一杯宜病士，四体委胡牀。
蹔得遗形处，陶然在醉乡。','',''),('quantangshi-17173','病中苦热','權德輿','quantangshi','','卷18','三伏鼓洪炉，支离一病夫。
倦眠身似火，渴歠汗如珠。
悸乏心难定，沈烦气欲无。
何时洒微雨，因与好风俱。','',''),('quantangshi-17174','览镜见白发数茎光鲜特异','權德輿','quantangshi','','卷18','秋来皎洁白须光，试脱朝簪学酒狂。
一曲酣歌还自乐，儿孙嬉笑挽衣裳。','',''),('quantangshi-17175','南亭晓坐因以示璩','權德輿','quantangshi','','卷18','隐几日无事，风交松桂枝。
园庐含晓霁，草木发华姿。
迹似南山隐，官从小宰移。
万殊同野马，方寸即灵龟。
弱质常多病，流年近始衰。
图书传授处，家有一男儿。','',''),('quantangshi-17176','竹迳偶然作','權德輿','quantangshi','','卷18','退朝此休沐，闭户无尘氛。
杖策入幽迳，清风随此君。
琴觞恣偃傲，兰蕙相氛氲。
幽赏方自适，林西烟景曛。','',''),('quantangshi-17177','拜昭陵过咸阳墅','權德輿','quantangshi','','卷18','季子乏二顷，杨雄才一廛。
伊予此南亩，数已逾前贤。
顷岁辱明命，铭勋镂贞坚。
遂兹操书致，内顾增缺然。
乃葺场圃事，迨今三四年。
适因昭陵拜，得抵咸阳田。
田夫竞致辞，乡耋争来前。
村盘既罗列，鸡黍皆珍鲜。
古称禄代耕，人以食为天。
自慙廪给厚，谅使井税先。
涂涂沟塍雾，漠漠桑柘烟。
荒蹊没古木，精舍临秋泉。
池笼岂所安，樵牧乃所便。
终当解缨络，田里谐因缘。','',''),('quantangshi-17178','早春南亭即事','權德輿','quantangshi','','卷18','虚斋坐清昼，梅坼柳条鲜。
节候开新历，筋骸减故年。
振衣慙艾绶，闚镜叹华颠。
独有开怀处，孙孩戏目前。','',''),('quantangshi-17179','璩授京兆府参军戏书以示兼呈独孤郎','權德輿','quantangshi','','卷18','见尔府中趋，初官足慰吾。
老牛还舐犊，凡鸟亦将雏。
喜至翻成感，痴来或欲殊。
因慙玉润客，应笑此非夫。','',''),('quantangshi-17180','书绅诗','權德輿','quantangshi','','卷18','和静有真质，斯人称最灵。
感物惑天性，触里纷多名。
祸机生隐微，智者鉴未形。
败礼因近习，喆人自居贞。
当令念虑端，鄙嫚不能萌。
苟非不逾矩，焉得遂性情。
谨之在事初，动用各有程。
千里起步武，彗云自纤茎。
心源一流放，骇浪奔长鲸。
渊木苟端深，枝流则贞清。
和理通性术，悠久方昭明。
先师留中庸，可以导此生。','',''),('quantangshi-17181','侍从游后湖宴坐','權德輿','quantangshi','','卷18','绝境殊不远，湖塘直吾庐。
烟霞旦夕生，泛览诚可娱。
慈颜俯见喻，辍尔诗与书。
清旭理轻舟，嬉游散烦劬。
宿雨荡残燠，惠风与之俱。
心灵一开旷，机巧眇已疎。
中流有荷花，花实相芬敷。
田田绿叶映，艳艳红姿舒。
繁香好风结，净质清露濡。
丹霞无容辉，嫮色亦踟蹰。
穠芳射水木，欹叶游龟鱼。
化工若有情，生植皆不如。
轻舟任沿溯，毕景乃踌躇。
家人亦恬旷，稚齿皆忻愉。
素弦激凄清，旨酒盈罇壶。
寿觞既频献，乐极随歌呼。
圆月初出海，澄辉来满湖。
清光照酒酣，俯倾百虑无。
以兹心目畅，敌彼名利途。
轻肥何为者，浆藿自有余。
愿销区中累，保此湖上居。
无用诚自适，年年翫芙蕖。','',''),('quantangshi-17182','晨坐寓兴','權德輿','quantangshi','','卷18','清晨坐虚斋，羣动寂未喧。
泊然一室内，因见万化源。
得丧心既齐，清净敎益敦。
境来每自惬，理胜或不言。
亭柯见荣枯，止水知清浑。
悠悠世上人，此理法难论。','',''),('quantangshi-17183','郊居岁暮因书所怀','權德輿','quantangshi','','卷18','养拙方去喧，深居绝人事。
返耕忘帝力，乐道疎代累。
翛然衡茅下，便有江海意。
宁知肉食尊，自觉儒衣贵。
烟霜当暮节，水石多幽致。
三径日闲安，千峯对深邃。
策藜出村渡，岸帻寻古寺。
月魄清夜琴，猨声警朝寐。
地偏芝桂长，境胜烟霞异。
独鸟带晴光，疎篁净寒翠。
窗前风叶下，枕上溪云至。
散发对农书，斋心看道记。
清言核名理，开卷穷精义。
求誉观朵颐，危身陷芳饵。
纷吾守孤直，世业常恐坠。
就学缉韦编，铭心对欹器。
元和畅万物，动植咸使遂。
素履期不渝，永怀丘中志。','',''),('quantangshi-17184','暮春闲居示同志','權德輿','quantangshi','','卷18','避喧非傲世，幽兴乐郊园。
好古每开卷，居贫常闭门。
曙钟来古寺，旭日上西轩。
稍与清境会，蹔无尘事烦。
静看云起灭，闲望鸟飞翻。
乍问山僧偈，时听渔父言。
体羸谙药性，事简见心源。
冠带惊年长，诗书喜道存。
小池泉脉凑，危栋燕雏喧。
风入松阴静，花添竹影繁。
灌园输井税，学稼奉晨昏。
此外知何有，怡然向一罇。','',''),('quantangshi-17185','田家即事','權德輿','quantangshi','','卷18','闲卧藜牀对落晖，翛然便觉世情非。
漠漠稻花资旅食，青青荷叶制儒衣。
山僧相访期中饭，渔父同游或夜归。
待学尚平婚稼毕，渚烟溪月共忘机。','',''),('quantangshi-17186','寓兴','權德輿','quantangshi','','卷18','弱冠无所就，百忧钟一身。
世德既颠坠，素怀亦堙沦。
风烟隔嵩丘，羸疾滞漳滨。
昭代未通籍，丰年犹食贫。
敢求庖有鱼，但虑甑生尘。
俛首愧僮仆，蹇步羞亲宾。
岂伊当途者，一一由中人。
已矣勿复言，吾将问秋旻。','',''),('quantangshi-17187','浩歌','權德輿','quantangshi','','卷18','杖策出蓬荜，浩歌秋兴长。
北风吹荷衣，箫飒景气凉。
通逵抵山郭，里巷连湖光。
孤云净远峯，绿水溢芳塘。
鱼鸟乐天性，杂英互芬芳。
我心独何为，万虑萦中肠。
履道身未泰，主家谋不臧。
心为世敎牵，迹寄翰墨场。
出处两未定，羁羸空自伤。
沈忧不可裁，伫立河之梁。
晚归茅檐下，左右陈壶觞。
独酌复长谣，放心游八荒。
得丧同一域，是非亦何常。
胡为苦此生，矻矻徒自强。
乃知杯中物，可使忧患忘。
因兹谢时辈，栖息无何乡。','',''),('quantangshi-17188','与道者同守庚申','權德輿','quantangshi','','卷18','洞真善救世，守夜看仙经。
俾我外持内，当兹申配庚。
斋心已恬愉，澡身自澄明。
沈沈帘帏下，霭霭灯烛清。
四支动用息，一室虚白生。
收视忘趋舍，叩齿集神灵。
伊予嗜欲寡，居常疴恙轻。
三尸既伏窜，九藏乃和平。
无令耳目胜，则使性命倾。
窅然深夜中，若与元气并。
释宗称定慧，儒师着诚明。
派分示三敎，理诣无二名。
吉祥能止止，委顺则生生。
视履苟无咎，天佑期永贞。
应物智不劳，虚中理自冥。
岂资金丹术，即此驻颓龄。','',''),('quantangshi-17189','丙庚岁苦贫戏题','權德輿','quantangshi','','卷18','清朝起藜牀，雪霜对枯篱。
家人来告予，今日无晨炊。
鹾醯一已整，薪炭固难期。
厚生彼何人，工拙各异宜。
间岁从使檄，亲宾苦川驰。
虽非悖而[入]□，[与出]□□常相随。
吴门与南亩，颇亦持镃基。
有时[遇丰年]□□□，岁计犹不支。
颜渊谅贤人，陋巷能自怡。
[中忆裴]□□□子野，泰然倾薄糜。
愧非古人心，戚戚愁[朝饥]□□。
[近]□古犹不及，太上那可希。
奈何时风扇，使[我正性]□□□衰。
巧智竞忧劳，展转生浇漓。
吾观黄金[印]□，[未]□胜青松枝。
麤令有鱼菽，岂复求轻肥。
顾慙[主家]□□拙，甘使羣下嗤。
如何致一杯，醉后无所知。','',''),('quantangshi-17190','独酌','權德輿','quantangshi','','卷18','独酌复独酌，满盏流霞色。
身外皆虚名，酒中有全德。
风清与月朗，对此情何极。','',''),('quantangshi-17191','知非','權德輿','quantangshi','','卷18','名敎自可乐，搢绅贵行道。
何必学狂歌，深山对丰草。','',''),('quantangshi-17192','诫言','權德輿','quantangshi','','卷18','言之或未行，前哲所不取。
方寸虽浩然，因之三缄口。','',''),('quantangshi-17193','醉后','權德輿','quantangshi','','卷18','美禄与贤人，相逢自可亲。
愿将花柳月，尽赏醉乡春。','',''),('quantangshi-17194','奉和李相公早朝于中书候传点偶书所怀奉呈门下相公中书相公','權德輿','quantangshi','','卷18','五更钟漏歇，千门扃钥开。
紫宸残月下，黄道晓光来。
辨色趋中禁，分班列上台。
祥烟初缭绕，威凤正裴回。
斧藻归全德，轮辕适众材。
化成风偃草，道合鼎调梅。
渥命随三接，皇恩畅九垓。
嘉言造膝去，喜气沃心回。
东阁延多士，南山赋有台。
阳春那敢和，空此咏康哉。','',''),('quantangshi-17195','奉和于司空二十五丈新卜城南郊居接司徒公别墅即事书情奉献兼呈李裴相公','權德輿','quantangshi','','卷18','一德承昌运，三公翊至尊。
云龙谐理代，鱼水见深恩。
别墅池塘晓，晴郊草木蕃。
沟塍连杜曲，茅土盛于门。
卜筑因登览，经邦每讨论。
退朝鸣玉会，入室断金言。
材俊依东阁，壶觞接后园。
迳深云自起，风静叶初翻。
宰物归心匠，虚中即化源。
巴人宁敢和，空此愧游藩。','',''),('quantangshi-17196','奉和新卜城南郊居得与卫右丞邻舍因赋诗寄赠','權德輿','quantangshi','','卷18','上宰坐论道，郊居仍里仁。
六符既昭晰，万象随陶钧。
旭旦下玉墀，鸣驺拂车茵。
轩窗退残暑，风物迎萧辰。
山泽蜃雨出，林塘鱼鸟驯。
岂同求羊迳，共是羲皇人。
石君五曹重，左户三壤均。
居止烟火接，逢迎鸡黍频。
大方本无隅，盛德必有邻。
千年郢曲后，复此闻阳春。','',''),('quantangshi-17197','奉和韦曲庄言怀贻东曲外族诸弟','權德輿','quantangshi','','卷18','韦曲冠盖里，鲜原郁青葱。
公台睦中外，墅舍邻西东。
驺驭出国门，晨曦正曈昽。
燕居平外土，野服参华虫。
疆畎分古渠，烟霞连灌丛。
长幼序以齿，欢言无不同。
忆昔全盛时，勋劬播休功。
代业扩宇内，光尘蔼墟中。
慨息多永叹，歌诗厚时风。
小生忝瓜葛，慕义斯无穷。','',''),('quantangshi-17198','和王侍郎病中领度支烦迫之余过西园书堂闲望','權德輿','quantangshi','','卷18','凭槛辍繁务，晴光烟树分。
中邦均禹贡，上药验桐君。
满迳风转蕙，卷帘山出云。
锵然玉音发，余兴在斯文。','',''),('quantangshi-17199','奉和度支李侍郎早朝','權德輿','quantangshi','','卷18','夙驾趋北阙，晓星启东方。
鸣驺分骑吏，列烛散康庄。
照灼华簪并，逶迤绮陌长。
腰金初辨色，喷玉自生光。
献替均三壤，贞明集百祥。
下才叨接武，空此愧文昌。','',''),('quantangshi-17200','奉和刘侍郎司徒奉诏伐叛书情呈宰相','權德輿','quantangshi','','卷18','玉帐元侯重，黄枢上宰雄。
缘情词律外，宣力庙谋中。
震耀恭天讨，严凝助岁功。
行看画麟阁，凛凛有英风。','',''),('quantangshi-17201','奉和鄜州刘大夫麦秋出师遮虏有怀中朝亲故','權德輿','quantangshi','','卷18','天子爱全才，故人雄外台。
绿油登上将，青绶亚中台。
亭障鸣笳入，风云转斾来。
兰坊分杳杳，麦壠望莓莓。
月向雕弓满，莲依宝劒开。
行师齐鹤列，锡马尽龙媒。
壮志征梁甫，嘉招萃楚材。
千寻推直干，百炼去纤埃。
间阔劳相望，欢言幸早陪。
每联花下骑，几泛竹间杯。
芳讯双鱼远，流年两鬓催。
何时介圭觐，携手咏康哉。','',''),('quantangshi-17202','太原郑尚书远寄新诗走笔酬赠因代书贺','權德輿','quantangshi','','卷18','晓开阊阖出丝言，共喜全才镇北门。
职重油幢推上略，荣兼革履见深恩。
昔岁经过同二仲，登朝并命慙无用。
曲台分季奉斋祠，直笔系年陪侍从。
芬芳鸡舌向南宫，伏奏丹墀迹又同。
公望数承黄纸诏，虚怀自号白云翁。
戎装躞蹀纷出祖，金印煌煌宠司武。
时看介士阅犀渠，每狎儒生冠章甫。
晋祠汾水古并州，千骑双旌居上头。
新握兵符应感激，远缄诗句更风流。
缁衣诸侯谅称美，白衣尚书何可比。
只今麟阁待丹青，努力加餐报天子。','',''),('quantangshi-17203','奉和许阁老酬淮南崔十七端公见寄','權德輿','quantangshi','','卷18','文行蕴良图，声华挹大巫。
抡才超粉署，驳议在黄枢。
自得环中辨，偏推席上儒。
八音谐雅乐，六辔骋康衢。
密侍仝锵佩，雄才本弃繻。
炉烟霏琐闼，宫漏滴铜壶。
旧友双鱼至，新文六义敷。
断金挥丽藻，比玉咏生刍。
交辟尝推重，单辞忽受诬。
风波疲贾谊，岐路泣杨朱。
溟涨前程险，炎荒旅梦孤。
空悲鸢跕水，翻羡雁衔芦。
故国方迢遰，羁愁自郁纡。
远猷来象魏，霈泽过番禺。
尽室扁舟客，还家万里途。
索居因仕宦，着论拟潜夫。
帆席来应驶，郊园半已芜。
夕阳寻古迳，凉吹动纤枯。
忆昔同驱传，忘怀或据梧。
幕庭依古刹，缗税给中都。
瓜步经过惯，龙沙眺听殊。
春山岚漠漠，秋渚露涂涂。
孰谓原思病，非关甯武愚。
方看簪獬豸，俄叹絷騊駼。
芳讯风情在，佳期岁序徂。
二贤欢最久，三益义非无。
柏悦心应尔，松寒志不渝。
子将陪禁掖，亭伯限江湖。
交分终推毂，离忧莫向隅。
分曹日相见，延首忆田苏。','',''),('quantangshi-17204','奉和李给事省中书情寄刘苗崔三曹长因呈许陈二阁老','權德輿','quantangshi','','卷18','常寮几处伏明光，新诏联翩夕拜郎。
五夜漏清天欲曙，万年枝暖日初长。
分曹列侍登文石，促膝闲谣接羽觞。
共说汉朝荣上赏，岂令三友滞冯唐。','',''),('quantangshi-17205','过张监阁老宅对酒奉酬见赠','權德輿','quantangshi','','卷18','里仁无外事，徐步一开颜。
荆玉收难尽，齐竽喜暂闲。
秋风倾菊酒，霁景下蓬山。
不用投车辖，甘从倒载还。','',''),('quantangshi-17206','奉和张舍人阁老阁中直夜思闻雅琴因以书事通简僚友','權德輿','quantangshi','','卷18','紫垣宿清夜，蔼蔼复沈沈。
圆月衡汉净，好风松涤深。
轩窗韵虚籁，兰雪怀幽音。
珠露销暑气，玉徽结遐心。
盛才本殊伦，雅诰方在今。
伫见舒彩翮，翻飞归凤林。','',''),('quantangshi-17207','和兵部李尚书东亭诗','權德輿','quantangshi','','卷18','三接履声退，东亭斯旷然。
风流披鹤氅，操割佩龙泉。
云卷岩巘叠，雨余松桂鲜。
岂烦禽尚游，所贵天理全。','',''),('quantangshi-17208','和司门殷员外早秋省中书直夜寄荆南卫象端公','權德輿','quantangshi','','卷18','共嗟王粲滞荆州，才子为郎忆旧游。
凉夜偏宜粉署直，清言远待玉人酬。
风生北渚烟波阔，露下南宫星汉秋。
早晚得为同舍侣，知君两地结离忧。','',''),('quantangshi-17209','酬陆三十二参浙东见寄','權德輿','quantangshi','','卷18','骢马别已久，鲤鱼来自烹。
殷勤故人意，怊怅中林情。
茫茫重江外，杳杳一枝琼。
搔首望良觌，为君华发生。','',''),('quantangshi-17210','奉酬张监阁老雪后过中书见赠加两韵简南省僚旧','權德輿','quantangshi','','卷18','寓直久叨荣，新恩倍若惊。
风清五夜永，节换一阳生。
潘鬓年空长，齐竽艺本轻。
常时望连茹，今日剧悬旌。
枉步欢方接，含毫思又萦。
烦君白雪句，岁晏若为情。','',''),('quantangshi-17211','酬主客仲员外见贺正除','權德輿','quantangshi','','卷18','五年承乏奉如纶，才薄那堪侍从臣。
禁署独闻清漏晓，命书慙对紫泥新。
周班每喜簪裾接，郢曲偏宜讽咏频。
忆昔曲台尝议礼，见君论着最相亲。','',''),('quantangshi-17212','奉和太府韦卿阁老左藏库中假山之作','權德輿','quantangshi','','卷18','春山仙掌百花开，九棘腰金有上才。
忽向庭中摹峻极，如从洞里见昭回。
小松已负干霄状，片石皆疑缩地来。
都内今朝似方外，仍传丽曲寄云台。','',''),('quantangshi-17213','奉和崔评事寄外甥刘同州并呈杜宾客许给事王侍郎昆弟杨少尹李侍御并见寄之作','權德輿','quantangshi','','卷18','芳讯来江湖，开缄粲瑶碧。
诗因乘黄赠，才擅雕龙格。
深陈名敎本，谅以仁义积。
藻思成采章，雅音闻皦绎。
清时左冯翊，贵士二千石。
前日应星文，今兹敞华戟。
谢公尝乞墅，甯氏终相宅。
往岁疲草玄，忘年齐举白。
酒酣吟更苦，夜艾谈方剧。
枣巷风雨秋，石头烟水夕。
多逢长者辙，不屑诸公辟。
酷似仰牢之，雄词挹亭伯。
老骥念千里，饥鹰舒六翮。
叵能舍郊扉，来偶朝中客。','',''),('quantangshi-17214','和职方殷郎中留滞江汉初至南宫呈诸公并见寄','權德輿','quantangshi','','卷18','十载别文昌，藩符寄武当。
师贞上介辟，恩擢正员郎。
藻思烟霞丽，归轩印绶光。
还希驻辇问，莫自叹冯唐。','',''),('quantangshi-17215','奉酬从兄南仲见示十九韵','權德輿','quantangshi','','卷18','晋季天下乱，安丘佐关中。
德辉霭家牒，侯籍推时功。
簪缨盛西州，清白传素风。
逢时有舒卷，缮性无穷通。
吾兄挺奇资，向晦道自充。
耕凿汝山下，退然安困蒙。
诗成三百篇，儒有一亩宫。
琴书满座右，芝术生墙东。
丽藻粲相鲜，晨辉艳芳丛。
清光杳无际，皓魄流霜空。
邦有贤诸侯，主盟词律雄。
荐贤比文举，理郡迈文翁。
楼中赏不独，池畔醉每同。
圣朝辟四门，发迹贵名公。
小生何为者，往岁学雕虫。
华簪映武弁，一年被微躬。
开缄捧新诗，琼玉寒青葱。
谬进空内讼，结怀远忡忡。
时来无自疑，刷翮摩苍穹。','',''),('quantangshi-17216','酬崔千牛四郎早秋见寄','權德輿','quantangshi','','卷18','浩歌坐虚室，庭树生凉风。
碧云灭奇彩，白露萎芳丛。
感此时物变，悠然遐想通。
偶来被簪组，自觉如池龙。
少年才藻新，金鼎世业崇。
凤文已彪炳，琼树何青葱。
联镳长安道，接武承明宫。
君登玉墀上，我侍彤庭中。
疲病多内愧，切磋常见同。
起予览新诗，逸韵凌秋空。
相爱每不足，因兹寓深衷。','',''),('quantangshi-17217','酬灵彻上人以诗代书见寄','權德輿','quantangshi','','卷18','莲花出水地无尘，中有南宗了义人。
已取贝多翻半字，还将阳焰谕三身。
碧云飞处诗偏丽，白月圆时信本真。
更喜开缄销热恼，西方社里旧相亲。','',''),('quantangshi-17218','酬蔡十二博士见寄四韵','權德輿','quantangshi','','卷18','芜城十年别，蓬转居不足。
终岁白屋贫，独谣清酒圣。
风尘韦带减，霜雪松心劲。
何以浣相思，启元能尽性。','',''),('quantangshi-17219','戏和三韵','權德輿','quantangshi','','卷18','墨翟突不黔，范丹甑生尘。
君今复劳歌，鹤发吹湿薪。
前诏许真秩，何如巾软轮。','',''),('quantangshi-17220','李十韶州寄途中绝句使者取报修书之际口号酬赠','權德輿','quantangshi','','卷18','诏下忽临山水郡，不妨从事恣攀登。
莫言向北千行雁，别有图南六月鹏。','',''),('quantangshi-17221','崔四郎协律以诗见寄兼惠蜀琴因以酬赠','權德輿','quantangshi','','卷18','临风结烦想，客至传好音。
白雪缄郢曲，朱弦亘蜀琴。
泠泠响幽韵，欵欵寄遐心。
岁晚何以报，与君期断金。','',''),('quantangshi-17222','酬冯绛州早秋绛台感怀见寄','權德輿','quantangshi','','卷18','良牧闲无事，层台思眇然。
六条萦印绶，三晋辨山川。
洗嫧讴谣合，开襟眺听偏。
秋光连大卤，霁景下新田。
叶落径庭树，人归曲沃烟。
武符颁美化，亥字访疑年。
经术推多识，卿曹亦累迁。
斋祠常并冕，官品每差肩。
按部青丝骑，裁诗白露天。
知音愧相访，商洛正闲眠。','',''),('quantangshi-17223','酬赵尚书杏园花下醉后见寄','權德輿','quantangshi','','卷18','春光深处曲江西，八座风流信马蹄。
鹤发杏花相映好，羡君终日醉如泥。','',''),('quantangshi-17224','酬赵尚书城南看花日晚先归见寄','權德輿','quantangshi','','卷18','杜城韦曲徧寻春，处处繁花满目新。
日暮归鞍不相待，与君同是醉乡人。','',''),('quantangshi-17225','伏蒙十六叔寄示喜庆感怀三十韵因献之','權德輿','quantangshi','','卷18','受氏自有殷，树功缅前秦。
圭田接土宇，侯籍相纷纶。
道义集天爵，菁华极人文。
握兰中台并，折桂东堂春。
祖德蹈前哲，家风播清芬。
先公秉明义，大节逢艰屯。
独立挺忠孝，至诚感神人。
命书备追锡，迹远道不伸。
小生谅无似，积庆遭昌辰。
九年西掖忝，五转南宫频。
司理因旷职，曲台仍礼神。
愧非夔龙姿，忽佐尧舜君。
内惟负且乘，徒以弱似仁。
岂足议大政，所忧玷彝伦。
叔父贞素履，含章穷典坟。
百氏若珠贯，九流皆翚分。
黄钟蕴声调，白玉那缁磷。
清论坐虚室，长谣宜幅巾。
开关接人祠，支策无俗宾。
种杏当暑热，烹茶含露新。
井径交碧藓，轩窗栖白云。
飞沈禽鱼乐，芬馥兰桂薰。
经术弘义训，息男茂嘉闻。
筮仕就色养，宴居忘食贫。
四方有翘车，上国有蒲轮。
行当反招隐，岂得常退身。
秦吴路杳杳，朔海望沄沄。
侍坐驰梦寐，结怀积昏昕。
发函捧新诗，慈诲情殷勤。
省躬日三复，拜首书诸绅。','',''),('quantangshi-17226','酬李二十二兄主簿马迹山见寄','權德輿','quantangshi','','卷18','杳杳尘外想，悠悠区中缘。
如何战未胜，曾是敎所牵。
远郊有灵峯，夙昔栖真仙。
鸾声去已久，马迹空依然。
丹崖转初旭，碧落凝秋烟。
松风共箫飒，萝月想婵娟。
内兄蕴遐心，嘉遯性所便。
不能栖枳棘，且复探云泉。
中有冥寂人，闲读逍遥篇。
联袂共支[策]，抠衣赏绝编。
徐行石上苔，静韵风中弦。
烟霞湿儒服，日月生寥天。
新诗来起予，璀璨六义全。
能尽含写意，转令山水鲜。
若闻笙鹤声，宛在耳目前。
登攀阻心赏，愁绝空怀贤。
出处岂异途，心冥即真筌。
蹔从西府檄，终卧东菑田。
不嫌予步蹇，但恐君行膻。
如能固旷怀，谷口期穷年。','',''),('quantangshi-17227','酬陆四十楚源春夜宿虎丘山对月寄梁四敬之兼见贻之作','權德輿','quantangshi','','卷18','东风变[蘅]薄，时景日妍和。
更想千峯夜，浩然幽意多。
蕙香袭闲趾，松露泫乔柯。
潭影漾霞月，石牀封薜萝。
夫君非岁时，已负青冥姿。
龙虎一门盛，渊云四海推。
骎骎步騕褭，婉婉翥长离。
悬圃尽琼树，家林轻桂枝。
声荣徒外奖，恬淡方自适。
逸气凌颢清，仁祠访金碧。
芊眠瑶草秀，断续云窦滴。
芳讯发幽缄，新诗比良觌。
故人石渠署，美价满中朝。
落落杉松直，芬芬兰杜飘。
雄词鼓溟海，旷达豁烟霄。
营道幸同术，论心皆后凋。
循环伐木咏，缅邈招隐情。
慙兹拥肿才，爱彼潺湲清。
拘牵尚多故，梦想何由并。
终结方外期，不待华发生。','',''),('quantangshi-17228','酬穆七侍郎早登使院西楼感怀','權德輿','quantangshi','','卷18','耿耿宵欲半，振衣庭户前。
浩歌抚长劒，临风泛清弦。
晴霜丽寒芜，微月露碧鲜。
杉梧韵幽籁，河汉明秋天。
良夜虽可翫，沈忧逾浩然。
楼中迟启明，林际挥宿烟。
晨风响钟鼓，曙色映山川。
滔滔天外驶，杲杲朝日悬。
因穷西南永，得见天地全。
动植相糺纷，车从竞喧阗。
鳣鲔跃洪流，麕麚倚荒阡。
嗈嗈白云雁，嘒嘒清露蝉。
一气鼓万殊，晦明相推迁。
羲和无停鞅，不得常少年。
当令志气神，及此鬓发玄。
岂唯十六族，今古称其贤。
夫君才气雄，振藻何翩翩。
诗轻沈隐侯，赋拟王仲宣。
小鸟抢榆枋，大鹏激三千。
与君期晚岁，方结林栖缘。','',''),('quantangshi-17229','奉和李大夫题郑评事江楼','權德輿','quantangshi','','卷18','达士无外累，隐几依南郭。
茅栋上江开，布帆当砌落。
支颐散华发，欹枕曝灵药。
入鸟不乱行，观鱼还自乐。
何时金马诏，早岁建安作。
往事尽筌蹄，虚怀寄杯杓。
邦君驻千骑，清论时间酌。
凭槛出烟埃，振衣向寥廓。
心源齐彼是，人境胜岩壑。
何必栖冥冥，然为避矰缴。','',''),('quantangshi-17230','春游茅山酬杜评事见寄','權德輿','quantangshi','','卷18','喜得赏心处，春山岂计程。
连溪芳草合，半岭白云晴。
绝涧漱冰碧，仙坛挹颢清。
怀君在人境，不共此时情。','',''),('quantangshi-17231','和韩侍御白发','權德輿','quantangshi','','卷18','白发今朝见，虚斋晓镜清。
乍分霜简色，微映铁冠生。
幕下多能事，周行挹令名。
流年未可叹，正遇太阶平。','',''),('quantangshi-17232','和邵端公醉后寄于谏议之作','權德輿','quantangshi','','卷18','莫羡檐前柳，春风独早归。
阳和次第发，桃李更芳菲。','',''),('quantangshi-17233','和李大夫西山祈雨因感张曲江故事十韵','權德輿','quantangshi','','卷18','亚相冠貂蝉，分忧统十联。
火星当永日，云汉倬炎天。
斋祷期灵贶，精诚契昔贤。
中宵出驺驭，清夜旅牲牷。
触日看初起，随车应物先。
雷音生绝巘，雨足晦平阡。
潇洒四冥合，空蒙万顷连。
歌谣喧泽国，稼穑徧原田。
故事三台盛，新文六义全。
作霖应自此，天下待丰年。','',''),('quantangshi-17234','同陆太祝鸿渐崔法曹载华见萧侍御留后说得卫抚州报推事使张侍御却回前刺史戴员外无事喜而有作三首 一','權德輿','quantangshi','','卷18','专城书素至留台，忽报张纲揽辔回。
共看昨日蝇飞处，并是今朝鹊喜来。','',''),('quantangshi-17235','同陆太祝鸿渐崔法曹载华见萧侍御留后说得卫抚州报推事使张侍御却回前刺史戴员外无事喜而有作三首 二','權德輿','quantangshi','','卷18','鹤发州民拥使车，人人自说受恩初。
如今天下无冤气，乞为邦君雪谤书。','',''),('quantangshi-17236','同陆太祝鸿渐崔法曹载华见萧侍御留后说得卫抚州报推事使张侍御却回前刺史戴员外无事喜而有作三首 三','權德輿','quantangshi','','卷18','众人哺啜喜君醒，渭水由来不杂泾。
遮莫雪霜撩乱下，松枝竹叶自青青。','',''),('quantangshi-17237','答韦秀才寄一首','權德輿','quantangshi','','卷18','中峯云暗雨霏霏，水涨花塘未得归。
心忆琼枝望不见，几回虚湿薜萝衣。','',''),('quantangshi-17238','户部王曹长杨考功崔刑部二院长并同钟陵使府之旧因以寄赠又陪郎署喜甚常僚因书所怀且叙所知','權德輿','quantangshi','','卷18','忽惊西江侣，共作南宫郎。
宿昔芝兰室，今兹鸳鹭行。
子猷美风味，左户推公器。
含毫白雪飞，出匣青萍利。
子云尝燕居，作赋似相如。
闲成考课奏，别贡贤良书。
子玉谅贞实，持刑慎丹笔。
秋天鸿鹄姿，晚岁松筠质。
伊予诚薄才，何幸复趋陪。
偶来尘右掖，空此忆中台。
时节东流驶，悲欢追往事。
待月登庾楼，排云上萧寺。
盍簪莲府宴，落帽龙沙醉。
极浦送风帆，灵山眺烟翠。
解颐通善谑，喻指穷精义。
搦管或飞章，分曹时按吏。
雨散与蓬飘，秦吴两寂寥。
方期全拥肿，岂望蹑扶摇。
夜直分三署，晨趋共九霄。
外庭时接武，广陌更连镳。
北极星辰拱，南薰气序调。
欣随众君子，并立圣明朝。','',''),('quantangshi-17239','贡院对雪以绝句代八行奉寄崔阁老','權德輿','quantangshi','','卷18','寓宿春闱岁欲除，严风密雪绝双鱼。
思君独步西垣里，日日含香草诏书。','',''),('quantangshi-17240','初秋月夜中书宿直因呈杨阁老','權德輿','quantangshi','','卷18','欹枕直庐暇，风蝉迎早秋。
沈沈玉堂夕，皎皎金波流。
对掌喜新命，分曹谐旧游。
相思翫华彩，因感庾公楼。','',''),('quantangshi-17241','唐开州文编远寄新赋累惠良药咏叹仰佩不觉斐然走笔代书聊书还答','權德輿','quantangshi','','卷18','风雨竦庭柯，端忧坐空堂。
多病时节换，所思道里长。
故人朱两轓，出自尚书郎。
下车今几时，理行远芬芳。
琼瑶览良讯，芣苢满素囊。
结根在贵州，蠲疾传古方。
探撷当五月，殷勤逾八行。
深情婉如此，善祝何可忘。
复有金玉音，焕如龙凤章。
一闻灵洞说，若覩羣仙翔。
三清飞庆霄，百汰成雄铓。
体物信无对，洒心愿相将。
昔年同旅食，终日窥文房。
春风眺芜城，秋水渡柳杨。
君为太史氏，弱质羁楚乡。
今来忝司谏，千骑遥相望。
归云夕鳞鳞，圆魄夜苍苍。
远思结铃阁，何人交羽觞。
伫见征颖川，无为薄淮阳。
政成看再入，列侍炉烟傍。','',''),('quantangshi-17242','待漏假寐梦归江东旧居','權德輿','quantangshi','','卷18','十年江浦卧郊园，闲夜分明结梦魂。
舍下烟萝通古寺，湖中云雨到前轩。
南宗长老知心法，东郭先生识化源。
觉后忽闻清漏晓，又随簪佩入君门。','',''),('quantangshi-17243','祗命赴京途次淮口因书所怀','權德輿','quantangshi','','卷18','弱植素寡偶，趋时非所任。
感恩再登龙，求友皆断金。
彪炳覩奇采，凄锵闻雅音。
适欣佳期接，遽叹离思侵。
靡靡遵远道，忡忡劳寸心。
难成独酌谣，空奏伐木吟。
泬寥清冬时，萧索白昼阴。
交欢谅如昨，滞念纷在今。
因风试矫翼，倦飞会归林。
向晚清淮驶，回首楚云深。','',''),('quantangshi-17244','省中春晚忽忆江南旧居戏书所怀因寄两浙亲故杂言','權德輿','quantangshi','','卷18','前年冠獬豸，戎府随宾介。
去年簪进贤，赞导法宫前。
今兹戴武弁，谬列金门彦。
问我何所能，头冠忽三变。
野性惯疎闲，晨趋兴暮还。
花时限清禁，霁后爱南山。
晚景支颐对尊酒，旧游忆在江湖久。
庾楼柳寺共开襟，枫岸烟塘几携手。
结庐常占练湖春，犹寄藜牀与幅巾。
疲羸只欲思三径，戆直那堪备七人。
更想东南多竹箭，悬圃琅玕共葱蒨。
裁书且附双鲤鱼，偏恨相思未相见。','',''),('quantangshi-17245','寄李衡州','權德輿','quantangshi','','卷18','片石丛花画不如，庇身三迳岂吾庐。
主人千骑东方远，唯望衡阳雁足书。','',''),('quantangshi-17246','寄临海郡崔穉璋','權德輿','quantangshi','','卷18','美酒步兵厨，古人尝宦游。
赤城临海峤，君子今督邮。
吏隐丰暇日，琴壶共冥搜。
新诗寒玉韵，旷思孤云秋。
志士诚勇退，鄙夫自包羞。
终当就知己，莫恋潺湲流。','',''),('quantangshi-17247','李韶州着书常论释氏之理贵州有能公遗迹诗以问之','權德輿','quantangshi','','卷18','常日区中暇，时闻象外言。
曹溪有宗旨，一为勘心源。','',''),('quantangshi-17248','马上赠虚公','權德輿','quantangshi','','卷18','马足早尘深，飘缨又满襟。
吾师有甘露，为洗此时心。','',''),('quantangshi-17249','郴州换印缄遣之际率成三韵因寄李二兄员外使君','權德輿','quantangshi','','卷18','缄题桂阳印，持寄朗陵兄。
刺举官犹屈，风谣政已成。
行看换龟纽，奏最谒承明。','',''),('quantangshi-17250','早发杭州泛富春江寄陆三十一公佐','權德輿','quantangshi','','卷18','候晓起徒驭，春江多好风。
白波连青云，荡漾晨光中。
四望浩无际，沈忧将此同。
未离奔走途，但恐成悲翁。
俯见触饵鳞，仰目淩霄鸿。
缨尘日已厚，心累何时空。
区区此人世，所向皆樊笼。
唯应杯中物，醒醉为穷通。
故人悬圃姿，琼树纷青葱。
终当此山去，共结兰桂丛。','',''),('quantangshi-17251','寄侍御从舅','權德輿','quantangshi','','卷18','靡靡南轩蕙，迎风转芳滋。
落落幽涧松，百尺无附枝。
世物自多故，达人心不羁。
偶陈幕中画，未负林间期。
感恩从慰荐，循性难絷维。
野鹤无俗质，孤云多异姿。
清[泠]松露泫，照灼岩花迟。
终当税尘驾，来就东山嬉。','',''),('quantangshi-17252','湖上晚眺呈惠上人','權德輿','quantangshi','','卷18','湖上烟景好，鸟飞云自还。
幸因居止近，日觉性情闲。
独酌乍临水，清机常见山。
此时何所忆，净侣话玄关。','',''),('quantangshi-17253','新秋月夜寄故人','權德輿','quantangshi','','卷18','客心宜静夜，月色澹新秋。
影落三湘水，诗传八咏楼。
何穷对酒望，几处卷帘愁。
若问相思意，随君万里游。','',''),('quantangshi-17254','自杨子归丹阳初遂闲居聊呈惠公','權德輿','quantangshi','','卷18','移疾喜无事，卷帘松竹寒。
稍知名是累，日与静相欢。
蹇浅逢机少，迂疎应物难。
只思闲夜月，共向沃州看。','',''),('quantangshi-17255','月夜过灵彻上人房因赠','權德輿','quantangshi','','卷18','此身会逐白云去，未洗尘缨还自伤。
今夜幸逢清净境，满庭秋月对支郎。','',''),('quantangshi-17256','戏赠张炼师','權德輿','quantangshi','','卷18','月帔飘颻摘杏花，相邀洞口劝流霞。
半酣乍奏云和曲，疑是龟山阿母家。','',''),('quantangshi-17257','戏赠天竺灵隐二寺寺主','權德輿','quantangshi','','卷18','石路泉流两寺分，寻常钟磬隔山闻。
山僧半在中峰住，共占青峦与白云。','',''),('quantangshi-17258','赠广通上人','權德輿','quantangshi','','卷18','身随猨鸟在深山，早有诗名到世间。
客至上方留盥漱，龙泓洞水昼潺潺。','',''),('quantangshi-17259','赠老将','權德輿','quantangshi','','卷18','白草黄云塞上秋，曾随骠骑出并州。
辘轳劒折虬须白，转战功多独不侯。','',''),('quantangshi-17260','戏赠表兄崔秀才','權德輿','quantangshi','','卷18','何事年年恋隐沦，成名须遣及青春。
明时早献甘泉去，若待公车却误人。','',''),('quantangshi-17261','醉后戏赠苏九翛','權德輿','quantangshi','','卷18','白首书窗成钜儒，不知簪组徧屠沽。
劝君莫问长安路，且读鲁山于蔿于。','',''),('quantangshi-17262','奉送韦起居老舅百日假满归嵩阳旧居','權德輿','quantangshi','','卷18','威凤翔紫气，孤云出寥天。
奇采与幽姿，缥缈皆自然。
尝闻陶唐氏，亦有巢由全。
以此耸风俗，岂必效羁牵。
大君遂羣方，左史蹈前贤。
振衣去朝市，赐告归林泉。
滑和固难久，循性得所便。
有名皆畏途，无事乃真筌。
旧壑穷杳窱，新潭漾沦涟。
嵓花落又开，山月缺复圆。
轻策逗萝迳，幅巾淩翠烟。
机闲鱼鸟狎，体和芝术鲜。
四皓本违难，二疏犹待年。
况今寰海清，复此鬓发玄。
顾慙缨上尘，未绝区中缘。
齐竽终自退，心寄嵩峯巅。','',''),('quantangshi-17263','奉送孔十兄宾客承恩致政归东都旧居','權德輿','quantangshi','','卷18','达人旷迹通出处，每忆安居旧山去。
乞身已见抗疏频，优礼新闻诏书许。
家法遥传阙里训，心源早逐嵩丘侣。
南史编年着盛名，东朝侍讲常虚伫。
角巾华发忽自遂，命服金龟君更与。
白云出岫暂逶迤，鸿鹄入冥无处所。
归路依依童稚乐，都门蔼蔼壶觞举。
能将此道助皇风，自可殊途并伊吕。','',''),('quantangshi-17264','送密秀才吏部驳放后归蜀应崔大理序','權德輿','quantangshi','','卷18','蜀国本多士，雄文似相如。
之子西南秀，名在贤能书。
薄禄且未及，故山念归欤。
迢迢三千里，返驾一羸车。
玉垒长路尽，锦江春物余。
此行无愠色，知尔恋林庐。','',''),('quantangshi-17265','送袁中丞持节册南诏五韵','權德輿','quantangshi','','卷18','西南使星去，远彻通朝聘。
烟雨僰道深，麾幢汉仪盛。
途轻五尺险，水爱双流净。
上国洽恩波，外臣遵礼命。
离堂驻驺驭，且尽罇中圣。','',''),('quantangshi-17266','人日送房二十六侍御归越','權德輿','quantangshi','','卷18','驿骑归时骢马蹄，莲花府映若邪溪。
帝城人日风光早，不惜离堂醉似泥。','',''),('quantangshi-17267','送张阁老中丞持节册吊回鹘','權德輿','quantangshi','','卷18','旌斾翩翩拥汉官，君行常得远人欢。
分职南台知礼重，辍书东观见才难。
金章玉节鸣驺远，白草黄云出塞寒。
欲散别离唯有醉，暂烦宾从驻征鞍。','',''),('quantangshi-17268','送二十叔赴任余杭尉','權德輿','quantangshi','','卷18','拜首直城阴，罇开意不任。
梅仙归剧县，阮巷奏离琴。
春草吴门绿，秋涛浙水深。
十年曾旅寓，应惬宦游心。','',''),('quantangshi-17269','春送十四叔赴任渝州录事绝句','權德輿','quantangshi','','卷18','随牒忽离南北巷，解巾都吏有清风。
巴城鏁印六联静，尽日闲谣廨署中。','',''),('quantangshi-17270','送韦十二丈赴襄城令三韵','權德輿','quantangshi','','卷18','留连出关骑，斟酌临岐酒。
旧业传一经，新官栽五柳。
去去望行尘，青门重回首。','',''),('quantangshi-17271','送薛十九丈授将作主簿分司东都赋得春草','權德輿','quantangshi','','卷18','芊芊远郊外，杳杳春嵓曲。
愁处映微波，望中连净绿。
日暮藉离觞，折芳心断续。','',''),('quantangshi-17272','送正字十九兄归江东醉后绝句','權德輿','quantangshi','','卷18','命驾相思不为名，春风归骑出关程。
离堂莫起临岐叹，文举终当荐禰衡。','',''),('quantangshi-17273','送张詹事致政归嵩山旧隐','權德輿','quantangshi','','卷18','解龟辞汉庭，却忆少微星。
直指常持宪，平反更恤刑。
闲思紫芝侣，归卧白云扃。
明诏优筋力，安车适性灵。
羣公来蔼蔼，独鹤去冥冥。
想到挥金处，嵩吟枕上青。','',''),('quantangshi-17274','送许着作分司东都','權德輿','quantangshi','','卷18','月旦继平舆，风流仕石渠。
分曹向瀍洛，守职正图书。
棣萼荣相映，琼枝色不如。
宾朋争漉酒，徒御侍巾车。
异日始离抱，维思烹鲤鱼。','',''),('quantangshi-17275','送少清赴润州参军因思练旧居','權德輿','quantangshi','','卷18','二纪乐箪瓢，烟霞暮与朝。
因君宦游去，记得春江潮。
远别更搔首，初官方折腰。
青门望离袂，魂为阿连销。','',''),('quantangshi-17276','送浚上人归扬州禅智寺','權德輿','quantangshi','','卷18','𥗤露宗通法已传，麻衣筇杖去悠然。
扬州后学应相待，遥想幡花古寺前。','',''),('quantangshi-17277','献岁送李十兄赴黔中酒后绝句','權德輿','quantangshi','','卷18','一罇岁酒且留欢，三峡黔江去路难。
志士感恩无远近，异时应戴惠文冠。','',''),('quantangshi-17278','送张仆射朝见毕归镇','權德輿','quantangshi','','卷18','青光照目青门曙，玉勒雕戈拥驺驭。
东方连帅南阳公，文武吉甫如古风。
独奉新恩来谒帝，感深更见新诗丽。
共看三接欲为霖，却念百城同望岁。
双旌去去恋储胥，归路莺花伴隼旟。
今日汉庭求上略，留侯自有一编书。','',''),('quantangshi-17279','送韦行军员外赴河阳','權德輿','quantangshi','','卷18','五代武弁侍明光，辍佐中权拜外郎。
记事还同楚倚相，传经远自汉扶阳。
离堂处处罗簪组，东望河桥壮鼙鼓。
三城晓角启轩门，一县繁花照莲府。
上略儒风并者稀，翩翩驺骑有光辉。
只今右职多虚位，应待他时伏奏归。','',''),('quantangshi-17280','送韦中丞奉使新罗','權德輿','quantangshi','','卷18','淳化洽声明，殊方均惠养。
计书重译至，锡命双旌往。
星辞北极远，水泛东溟广。
斗柄辨宵程，天琛宜昼赏。
孤光洲岛迥，净绿烟霞敞。
展礼盛宾徒，交欢觌君长。
经途劳视听，怆别萦梦想。
延颈旬岁期，新恩在归鞅。','',''),('quantangshi-17281','送从翁赴任长子县令','權德輿','quantangshi','','卷18','家风本钜儒，吏职化双凫。
启事才方惬，临人政自殊。
地雄韩上党，秩比鲁中都。
拜首春郊夕，离杯莫向隅。','',''),('quantangshi-17282','送从弟广东归绝句','權德輿','quantangshi','','卷18','夏云如火铄晨辉，欵段羸车整素衣。
知尔业成还出谷，今朝莫怆断行飞。','',''),('quantangshi-17283','送王炼师赴王屋洞','權德輿','quantangshi','','卷18','稔岁在芝田，归程入洞天。
白云辞上国，青鸟会羣仙。
自以碁销日，宁资药驻年。
相看话离合，风驭忽泠然。','',''),('quantangshi-17284','送薛温州','權德輿','quantangshi','','卷18','昨日馈连营，今来刺列城。
方期建礼直，忽访永嘉程。
郡内裁诗暇，楼中迟客情。
凭君减千骑，莫遣海鸥惊。','',''),('quantangshi-17285','送黔中裴中丞阁老赴任','權德輿','quantangshi','','卷18','五谏留中禁，双旌辍上才。
内臣持凤诏，天厩锡龙媒。
宴语暌兰室，辉荣亚柏台。
怀黄宜命服，举白叹离杯。
景霁山川迥，风清雾露开。
辰溪分浩淼，僰道接萦回。
胜理环中得，殊琛徼外来。
行看旬岁诏，传庆在公台。','',''),('quantangshi-17286','送崔谕德致政东归','權德輿','quantangshi','','卷18','天子坐法宫，诏书下江东。
懿此嘉遯士，蒲车赴丘中。
褐衣入承明，朴略多古风。
直道侍太子，昌言沃宸聪。
嵓居四十年，心与鸥鸟同。
一朝受恩泽，自说如池龙。
乞骸归故山，累疏明深衷。
大君不夺志，命锡忽以崇。
旭旦出国门，轻装若秋蓬。
家依白云峤，手植丹桂丛。
竹斋引寒泉，霞月相玲珑。
旷然解赤绶，去逐冥冥鸿。','',''),('quantangshi-17287','送三十叔赴任晋陵','權德輿','quantangshi','','卷18','春云结暮阴，侍坐捧离襟。
黄绶轻装去，青门芳草深。
十年尘右职，三迳寄遐心。
便道停桡处，应过旧竹林。','',''),('quantangshi-17288','送安南裴都护','權德輿','quantangshi','','卷18','忽佩交州印，初辞列宿文。
莫言方任远，且贵主忧分。
迥转朱鸢路，连飞翠羽羣。
戈船航涨海，旌斾卷炎云。
绝徼褰帷识，名香夹毂焚。
怀来通北户，长养洽南薰。
暂叹同心阻，行看异绩闻。
归时无所欲，薏苡或烦君。','',''),('quantangshi-17289','送别沅泛','權德輿','quantangshi','','卷18','念尔强学殖，非贯早从师。
温温禀义方，慥慥习书诗。
计偕来上国，宴喜方怡怡。
经术既修明，艺文亦葳蕤。
伊予谅无取，琐质荷洪慈。
偶来贰仪曹，量力何可支。
废业固相受，避嫌诚自私。
徇吾刺促心，婉尔康庄姿。
古人贵直道，内讼乖坦夷。
用兹处大官，无乃玷清时。
羸车出门去，怅望交涕涕。
琢磨贵分阴，岁月若飙驰。
千里起足下，丰年系镃䥓。
苟令志气坚，伫见缨佩随。
斑斓五彩服，前路春物熙。
旧游忆江南，环堵留蓬茨。
湖水白于练，莼羹细若丝。
别来十三年，梦寐时见之。
宠荣忽逾量，荏苒不自知。
晨兴愧华簪，止足为灵龟。
遐路各自爱，大来行可期。
青冥在目前，努力调羽仪。','',''),('quantangshi-17290','送张曹长工部大夫奉使西番','權德輿','quantangshi','','卷18','殊邻覆露同，奉使小司空。
西候车徒出，南台节印雄。
吊祠将渥命，导驿畅皇风。
故地山河在，新恩玉帛通。
塞云凝废垒，关月照惊蓬。
青史书归日，翻轻五利功。','',''),('quantangshi-17291','九华观宴饯崔十七叔判官赴义武幕兼呈书记萧校书','權德輿','quantangshi','','卷18','炎光三伏昼，洞府宜幽步。
宿雨润芝田，鲜风摇桂树。
阴阴台殿敞，靡靡轩车驻。
晚酌临水清，晨装出关路。
偏荣本郡辟，倍感元臣遇。
记室有门人，因君达书素。','',''),('quantangshi-17292','送文畅上人东游','權德輿','quantangshi','','卷18','桑门许辩才，外学接宗雷。
护法麻衣净，翻经贝叶开。
宗通知不染，妄想自堪哀。
或结西方社，师游早晚回。','',''),('quantangshi-17293','送灵武范司空','權德輿','quantangshi','','卷18','上略在安边，吴钩结束鲜。
三公临右地，七萃拥中坚。
旧垒销烽火，新营辨井泉。
伐谋师以律，贾勇士争先。
塞迥晴看月，沙平远际天。
荣薰知屈指，应在盛秋前。','',''),('quantangshi-17294','送商州杜中丞赴任','權德輿','quantangshi','','卷18','安康地里接商于，帝命专城总赋舆。
夕拜忽辞青琐闼，晨装独捧紫泥书。
深山古驿分驺骑，芳草闲云逐隼旟。
绮皓清风千古在，因君一为谢岩居。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-17295','送殷卿罢举归淮南旧居','權德輿','quantangshi','','卷18','计偕十上竟无成，忽忆嵓居便独行。
志业尝探绝编义，风尘虚作弃繻生。
岁储应叹山田薄，里社诗逢野酝清。
惆怅中年羣从少，相看欲别倍关情。','',''),('quantangshi-17296','送杜尹赴东都','權德輿','quantangshi','','卷18','商于留异绩，河洛贺新迁。
朝选吾公守，时推杜尹贤。
如纶披凤诏，出匣淬龙泉。
风雨交中土，簪裾敞别筵。
清明人比玉，照灼府如莲。
伫报司州政，征黄似頴川。','',''),('quantangshi-17297','送孔江州','權德輿','quantangshi','','卷18','九派寻阳郡，分明似画图。
秋光连瀑布，晴翠辨香炉。
才子厌兰省，邦君荣竹符。
江城多暇日，能寄八行无。','',''),('quantangshi-17298','送浑邓州','權德輿','quantangshi','','卷18','年少守南阳，新恩印绶光。
轻轩出绕溜，利刃发干将。
风劲初下叶，云寒方护霜。
想君行县处，露冕菊潭香。','',''),('quantangshi-17299','埇桥达奚四于十九陈大三侍御夜宴叙各赋二韵','權德輿','quantangshi','','卷18','满树铁冠琼树枝，罇前烛下心相知。
明朝又与白云远，自古河梁多别离。','',''),('quantangshi-17300','酬别蔡十二见赠','權德輿','quantangshi','','卷18','伊人茂天爵，恬澹卧郊园。
傲世方隐几，说经久颛门。
浩歌曳柴车，讵羡丹毂尊。
严霜被鹑衣，不知狐白温。
游心羲文际，爱我相讨论。
潢污忽朝宗，传骑令载奔。
峥嵘岁阴晚，愀怆离念繁。
别馆丝桐清，寒郊烟雨昏。
中饮见逸气，纵谈穷化元。
伫见公车起，圣代待乞言。','',''),('quantangshi-17301','扬州与丁山人别','權德輿','quantangshi','','卷18','将军易道令威仙，华发清谈得此贤。
惆怅今朝广陵别，辽东后会复何年。','',''),('quantangshi-17302','送台州崔录事','權德輿','quantangshi','','卷18','不嫌临海远，微禄代躬耕。
古郡纪纲职，扁舟山水程。
诗因琪树丽，心与瀑泉清。
盛府知音在，何时荐政成。','',''),('quantangshi-17303','送信安刘少府','權德輿','quantangshi','','卷18','相看结离念，尽此林中渌。
夷代轻远游，上才随薄禄。
参卿滞孙楚，隐市同梅福。
吏散时泛弦，宾来闲覆局。
襟情无俗虑，谈笑成逸躅。
此路足滩声，羡君多水宿。','',''),('quantangshi-17304','送李城门罢官归嵩阳','權德輿','quantangshi','','卷18','与君相识处，吏隐在墙东。
启闭千门静，逢迎两掖通。
罢官多暇日，肄业有儒风。
归去尘寰外，春山桂树丛。','',''),('quantangshi-17305','送上虞丞','權德輿','quantangshi','','卷18','越郡佳山水，菁江接上虞。
计程航一苇，试吏佐双凫。
云壑窥仙籍，风谣验地图。
因寻黄绢字，为我吊曹盱。','',''),('quantangshi-17306','送卢评事婺州省觐','權德輿','quantangshi','','卷18','知向东阳去，晨装见彩衣。
客愁青眼别，家喜玉人归。
漠漠水烟晚，萧萧枫叶飞。
双溪泊船处，候吏拜胡威。','',''),('quantangshi-17307','送崔端公郎君入京觐省','權德輿','quantangshi','','卷18','已见风姿美，仍闻艺业勤。
清秋上国路，白皙少年人。
带月轻帆疾，迎霜彩服新。
过庭若有问，一为说漳滨。','',''),('quantangshi-17308','送张周二秀才谒宣州薛侍郎','權德輿','quantangshi','','卷18','儒衣两少年，春棹毂溪船。
湖月供诗兴，岚风费酒钱。
上帆涵浦岸，欹枕傲晴天。
不用愁羁旅，宣城太守贤。','',''),('quantangshi-17309','送张将军归东都旧业','權德輿','quantangshi','','卷18','功名不复求，旧业向东周。
白草辞边骑，青门别故侯。
摧残宝劒折，羸病绿珠愁。
日暮寒风起，犹疑大漠秋。','',''),('quantangshi-17310','送句容王少府簿领赴上都','權德輿','quantangshi','','卷18','上国路绵绵，行人候晓天。
离亭绿绮奏，乡树白云连。
江露湿征袂，山莺宜泊船。
春风若为别，相顾起尊前。','',''),('quantangshi-17311','送从弟谒员外叔父回归义兴','權德輿','quantangshi','','卷18','异乡兄弟少，见尔自依然。
来酌林中酒，去耕湖上田。
何朝逢暑雨，几夜泊鱼烟。
余力当勤学，成名贵少年。','',''),('quantangshi-17312','送梁道士谒寿州崔大夫','權德輿','quantangshi','','卷18','年少一仙官，清羸驾彩鸾。
洞宫云渺渺，花路水漫漫。
岁计芝田熟，晨装月帔寒。
遥知小山桂，五马待邀欢。','',''),('quantangshi-17313','送郑秀才贡举','權德輿','quantangshi','','卷18','西笑意如何，知随贡举科。
吟诗向月露，驱马出烟萝。
晚色平芜远，秋声候雁多。
自怜归未得，相送一劳歌。','',''),('quantangshi-17314','送谢孝廉移家越州','權德輿','quantangshi','','卷18','家承晋太傅，身慕鲁诸生。
又见一帆去，共愁千里程。
沙平古树迥，潮满晓江晴。
从此幽深去，无妨隐姓名。','',''),('quantangshi-17315','送韩孝廉侍从赴举','權德輿','quantangshi','','卷18','贡士去翩翩，如君最少年。
彩衣行不废，儒服代相传。
晓月经淮路，繁阴过楚天。
清谈遇知己，应访孝廉船。','',''),('quantangshi-17316','送陆拾遗秖召赴行在','權德輿','quantangshi','','卷18','鵷鹭承新命，翻飞入汉庭。
歌诗能合雅，献纳每论经。
月晓蜀江迥，猿啼楚树青。
幸因焚草暇，书札访沈冥。','',''),('quantangshi-17317','送暎师归本寺','權德輿','quantangshi','','卷18','还归柳市去，远远出人羣。
苔甃桐花落，山窗桂树薰。
引泉通绝涧，放鹤入孤云。
幸许宗雷到，清谈不易闻。','',''),('quantangshi-17318','送宇文文府赴行在','權德輿','quantangshi','','卷18','送君当岁暮，斗酒破离颜。
车骑拥寒水，雪云凝远山。
且安黄绶屈，莫羡白鸥闲。
从此图南路，青云步武间。','',''),('quantangshi-17319','送岳州温录事赴任','權德輿','quantangshi','','卷18','解巾州主簿，捧檄不辞遥。
独鹤九霄翼，寒松百尺条。
晨装沾雨雪，旅宿候风潮。
为政闲无事，清谈肃郡僚。','',''),('quantangshi-17320','送山人归旧隐','權德輿','quantangshi','','卷18','工为楚辞赋，更着鲁衣冠。
岁俭山田薄，秋深晨服寒。
武人荣燕颔，志士恋渔竿。
会被公车荐，知君久晦难。','',''),('quantangshi-17321','惠上人房宴别','權德輿','quantangshi','','卷18','方袍相引到龙华，支策开襟路不赊。
法味已同香积会，礼容疑在少施家。
逸民羽客期皆至，疎竹青苔景半斜。
究竟相依何处好，匡山古社足烟霞。','',''),('quantangshi-17322','送裴秀才贡举','權德輿','quantangshi','','卷18','儒衣风貌清，去抵汉公卿。
宾贡年犹少，篇章艺已成。
临流惜暮景，话别起乡情。
离酌不辞醉，西江春草生。','',''),('quantangshi-17323','送袁太祝衢婺巡覆','權德輿','quantangshi','','卷18','校缗税亩不妨闲，清兴自随鱼鸟间。
知君此去足佳句，路出桐溪千万山。','',''),('quantangshi-17324','送湖南李侍御赴本使赋采菱亭诗','權德輿','quantangshi','','卷18','旧俗采菱处，津亭风景和。
沅江收暮霭，楚女发清歌。
曲岸萦湘叶，荒堦上白波。
兰桡向莲府，一为枉帆过。','',''),('quantangshi-17325','送穆侍御归东都','權德輿','quantangshi','','卷18','知君儒服贵，彩绣两相辉。
婉婉成名后，翩翩拥传归。
江深烟屿没，山暗雨云飞。
共待酬恩罢，相将去息机。','',''),('quantangshi-17326','送崔端公赴度支江陵院三韵','權德輿','quantangshi','','卷18','津亭风雪霁，斗酒留征棹。
星传指湘江，瑶琴多楚调。
偏愁欲别处，黯黯颓阳照。','',''),('quantangshi-17327','送陆太祝赴湖南幕同用送字','權德輿','quantangshi','','卷18','不惮征路遥，定缘宾礼重。
新知折柳赠，旧侣乘篮送。
此去佳句多，枫江接云梦。','',''),('quantangshi-17328','送李处士归弋阳山居','權德輿','quantangshi','','卷18','暂来城市意何如，却忆葛阳溪上居。
不惮薄田输井税，自将嘉句着州闾。
波翻极浦樯竿出，霜落秋郊树影疎。
想到家山无俗侣，逢迎只是坐篮舆。','',''),('quantangshi-17329','送清洨上人谒信州陆员外','權德輿','quantangshi','','卷18','暂辞长老去随缘，候晓轻装寄客船。
佳句已齐康宝月，清谈远指谢临川。
滩经水濑逢新雪，路过渔潭宿暝烟。
暇日若随千骑出，南岩只在郡楼前。','',''),('quantangshi-17330','送别同用阔字','權德輿','quantangshi','','卷18','耿耿离念繁，萧萧凉叶脱。
缁尘素衣敝，风露秋江阔。
想得读书窗，岩花对巾褐。','',''),('quantangshi-17331','送人使之江陵','權德輿','quantangshi','','卷18','嘉招不辞远，捧檄利攸往。
行役念前程，宴游睽旧赏。
征轺星乍动，江信潮应上。
烟水飞一帆，霜云摇五两。
纷纷别袂举，切切离鸿响。
后会杳何时，悠然劳梦想。','',''),('quantangshi-17332','余干赠别张二十二侍御','權德輿','quantangshi','','卷18','芜城陌上春风别，干越亭边岁暮逢。
驱车又怆南北路，返照寒江千万峯。','',''),('quantangshi-17333','杂言赋得风送崔秀才归白田限三五六七言','權德輿','quantangshi','','卷18','响深涧，思啼猨。
暗入苹洲暖，轻随柳陌暄。
澹荡乍飘云影，芳菲徧满花源。
寂寞春江别君处，和烟带雨送征轩。','',''),('quantangshi-17334','杂言同用离骚体送张评事襄阳觐省','權德輿','quantangshi','','卷18','黯离堂兮日晚，俨壶觞兮送远。
远水霁兮微明，杜蘅秀兮白芷生。
波泫泫兮烟幂幂，凝暮色于空碧。
纷离念兮随君，溯九江兮经七泽。
君之去兮不可留，五采裳兮木兰舟。','',''),('quantangshi-17335','岭上逢久别者又别','權德輿','quantangshi','','卷18','十年曾一别，征路此相逢。
马首向何处，夕阳千万峯。','',''),('quantangshi-17336','赠别表兄韦卿','權德輿','quantangshi','','卷18','新读兵书事护羌，腰间宝劒映金章。
少年百战应轻别，莫笑儒生泪数行。','',''),('quantangshi-17337','古离别','權德輿','quantangshi','','卷18','人生天地间，瞥若六辔驰。
夭寿既常数，奈何生别离。
迹当中人域，正性日已衰。
是非千万境，杳霭情尘滋。
出门事何常，暂别亦难期。
冉冉叹流景，悠悠限山陂。
尽此一夕欢，华罇会前墀。
鸡鸣东方曙，夙驾临通逵。
欲出强移步，欲留难致辞。
两情不得已，念此留何为。
天明去已远，寂默居人归。
入门复上堂，怳怳生惊疑。
经履同游处，犹言常相随。
览物或临盘，翻怪来何迟。
乃知前日欢，本为今日悲。
特此别后心，宁及未见时。
则知交疎分，久久翻易持。
报君未别后，别后当自知。','',''),('quantangshi-17338','早夏青龙寺致斋凭眺感物因书十四韵','權德輿','quantangshi','','卷18','晓出文昌宫，憩兹青莲宇。
洁斋奉明祀，凭览伤夐古。
秦为三月火，汉乃一抱土。
诈力自湮沦，霸仪终莽卤。
中南横峻极，积翠泄云雨。
首夏谅清和，芳阴接场圃。
仁祠閟严净，稽首洗灵府。
虚室僧正禅，危梁燕初乳。
通庄走声利，结驷乃旁午。
观化复何如，刳心信为愈。
盛时忽过量，弱质本无取。
静永环中枢，益愧腰下组。
尘劳期抖擞，陟降聊俯偻。
遗韵留壁间，凄然感东武。','',''),('quantangshi-17339','仲秋朝拜昭陵','權德輿','quantangshi','','卷18','清秋寿原上，诏拜承吉卜。
尝读贞观书，及兹幸斋沐。
文皇昔潜耀，隋季自颠覆。
抚运斯顺人，救焚非逐鹿。
神只戴元圣，君父纳大麓。
良将授兵符，直臣调鼎餗。
无疆传庆祚，有截荷亭育。
仙驭淩紫氛，神游弃黄屋。
方祗护山迹，先正陪岩腹。
杳杳九嵕深，沈沈万灵肃。
鸟飞田已辟，龙去云犹簇。
金气爽林峦，干冈走崖谷。
吾皇弘孝理，率士蒙景福。
拥佑乃清夷，威灵谅回复。
礼承三公重，心愧二卿禄。
展敬何所伸，曾以斧山木。','',''),('quantangshi-17340','拜昭陵出城与张祕监阁老同里临行别承在史馆未归寻辱清辞辄酬之','權德輿','quantangshi','','卷18','仲月当南吕，晨装拜谷林。
逢君在东观，不得话离襟。
策马缘云路，开缄扣玉音。
还期才浃日，里社酒同斟。','',''),('quantangshi-17341','酬冯监拜昭陵回途中遇雨见示','權德輿','quantangshi','','卷18','之子共乘轺，清秋拜上霄。
曙霞迎夙驾，零雨湿回镳。
甘谷行初尽，轩台去渐遥。
望中犹可辨，耘鸟下山椒。','',''),('quantangshi-17342','朔旦冬至摄职南郊因书即事','權德輿','quantangshi','','卷18','大明南至庆天正，朔旦圆丘乐六成。
文轨尽同尧历象，斋祠忝备汉公卿。
星辰列位祥光满，金石交音晓奏清。
更有观台称贺处，黄云捧日瑞升平。','',''),('quantangshi-17343','奉和张监阁老过八陵院题赠杜卿崔员外','權德輿','quantangshi','','卷18','崇饰山园孝理深，万方同感圣人心。
已闻东阁招从事，每向西垣奉德音。
公府从容谈婉婉，宾堦清切景沈沈。
与君跬步如同舍，终日相期此盍簪。','',''),('quantangshi-17344','奉和郑宾客相公摄官丰陵扈从之作','權德輿','quantangshi','','卷18','五辂导灵輼，千夫象缭垣。
行宫移晓漏，彩杖下秋原。
莫究希夷理，空怀涣汗恩。
颐神方蹈道，传圣乃尊尊。
共祝如山寿，俄惊凭几言。
遐荒七月会，肸蠁百灵奔。
豹尾从风直，鸾旗映日翻。
涂刍联法从，营骑肃旌门。
杳霭虞泉夕，凄清楚挽喧。
不堪程尽处，呜咽望文园。','',''),('quantangshi-17345','詹事府宿斋绝句','權德輿','quantangshi','','卷18','清斋四体泰，白昼一室空。
摧颓有古树，骚屑多悲风。','',''),('quantangshi-17346','和王祭酒太社宿斋不得赴李尚书宅会戏书见寄','權德輿','quantangshi','','卷18','元礼门前劳引望，句龙坛下阻欢娱。
此时对局空相忆，博进何人更乐输。','',''),('quantangshi-17347','酬裴端公八月十五日夜对月见怀','權德輿','quantangshi','','卷18','凉夜清秋半，空庭皓月圆。
动摇随积水，皎洁满晴天。
多病嘉期阻，深情丽曲传。
偏怀赏心处，同望庾楼前。','',''),('quantangshi-17348','奉和崔阁老清明日候许阁老交直之际辱裴阁老书招云与考功苗曹长先城南游览独行口号因以简赠','權德輿','quantangshi','','卷18','紫禁宿初回，清明花乱开。
相招直城外，远远上春台。
谏曹将列宿，几处期子玉。
深竹与清泉，家家桃李鲜。
折芳行载酒，胜赏随君有。
愁疾自无悰，临风一搔首。','',''),('quantangshi-17349','和张祕监阁老献岁过蒋大拾遗因呈两省诸公并见示','權德輿','quantangshi','','卷18','二贤同载笔，久次入新年。
焚草淹轻秩，藏书厌旧编。
竹风晴翠动，松雪瑞光鲜。
庆赐行春令，从兹伫九迁。','',''),('quantangshi-17350','酬崔舍人阁老冬至日宿直省中奉简两掖阁老并见示','權德輿','quantangshi','','卷18','令节一阳新，西垣宿近臣。
晓光连凤沼，残漏近鸡人。
白雪飞成曲，黄钟律应均。
层霄翔迅羽，广陌驻归轮。
清切晨趋贵，恩华夜直频。
辍才时所重，分命秩皆真。
左掖期连茹，南宫愧积薪。
九年叨此地，回首倍相亲。','',''),('quantangshi-17351','八月十五日夜瑶台寺对月绝句','權德輿','quantangshi','','卷18','嬴女乘鸾已上天，仁祠空在鼎湖边。
凉风遥夜清秋半，一望金波照粉田。','',''),('quantangshi-17352','夏至日作','權德輿','quantangshi','','卷18','璇枢无停连，四序相错行。
寄言赫曦景，今日一阴生。','',''),('quantangshi-17353','二月二十七日社兼春分端居有怀简所思者','權德輿','quantangshi','','卷18','清昼开帘坐，风光处处生。
看花诗思发，对酒客愁轻。
社日双飞燕，春分百啭莺。
所思终不见，还是一含情。','',''),('quantangshi-17354','甲子岁元日呈郑侍御明府','權德輿','quantangshi','','卷18','万里烟尘合，秦吴遂渺然。
无人来上国，洒泪向新年。
世故看风叶，生涯寄海田。
屠苏聊一醉，犹赖主人贤。','',''),('quantangshi-17355','七夕','權德輿','quantangshi','','卷18','佳期人不见，天上喜新秋。
玉佩霑新露，香车渡浅流。
东西一水隔，迢遰两年愁。
别有穿针处，微明月暎楼。','',''),('quantangshi-17356','嘉兴九日寄丹阳亲故','權德輿','quantangshi','','卷18','穷年路歧客，西望思茫茫。
积水曾南渡，浮云失旧乡。
海边寻别墅，愁里见重阳。
草露荷衣冷，山风菊酒香。
独谣看坠叶，远目徧秋光。
更羡登攀处，烟花满练塘。','',''),('quantangshi-17357','九日北楼宴集','權德輿','quantangshi','','卷18','萧飒秋声楼上闻，霜风漠漠起阴云。
不见携觞王太守，空思落帽孟参军。
风吟蟋蟀寒偏急，酒泛茱萸晚易醺。
心忆旧山何日见，并将愁泪共纷纷。','',''),('quantangshi-17358','奉陪李大夫九日龙沙宴会','權德輿','quantangshi','','卷18','龙沙重九会，千骑驻旌旗。
水木秋光净，丝桐雅奏迟。
烟芜敛暝色，霜菊发寒姿。
今日从公醉，全胜落帽时。','',''),('quantangshi-17359','腊日龙沙会绝句','權德輿','quantangshi','','卷18','帘外寒江千里色，林中罇酒七人期。
宁知腊日龙沙会，却胜重阳落帽时。','',''),('quantangshi-17360','严陵钓台下作','權德輿','quantangshi','','卷18','绝顶耸苍翠，清湍石磷磷。
先生晦其中，天子不得臣。
心灵栖颢气，缨冕犹缁尘。
不乐禁中卧，却归江上春。
潜驱东汉风，日使薄者醇。
焉用佐天子，特此报故人。
人知大贤心，不独私自身。
弛张有深致，耕钓陶天真。
奈何清风后，扰扰论屈伸。
交情同市道，利欲相纷纶。
我行访遗台，仰古怀逸民。
矰缴鸿鹄远，雪霜松桂新。
江流去不穷，山色凌秋旻。
人世自今古，清辉照无垠。','',''),('quantangshi-17361','晓发武阳馆即事书情','權德輿','quantangshi','','卷18','清晨策羸车，嘲唽闻村鸡。
行将骑吏亲，日与情爱暌。
东风变林樾，南亩事耕犂。
青菰冒白水，方塘接广畦。
杂英被长坂，野草蔓幽蹊。
泻卤成沃壤，枯株发柔荑。
芳树莺命雏，深林麏引麑。
杳杳途未极，团团日已西。
哲士务缨弁，鄙夫恋蓬藜。
终当税尘驾，盥濯依春溪。','',''),('quantangshi-17362','丰城劒池驿感题','權德輿','quantangshi','','卷18','龙劒昔未发，泥沙相晦藏。
向非张茂先，孰辨斗牛光。
神物不自达，圣贤亦彷徨。
我行丰城野，慷慨心内伤。','',''),('quantangshi-17363','奉使宜春夜渡新淦江陆路至黄蘖馆路上遇风雨作','權德輿','quantangshi','','卷18','草草理夜装，涉江又登陆。
望路殊未穷，指期今已促。
传呼戒徒御，振辔转林麓。
阴云拥嵓端，霔雨当山腹。
震雷如在耳，飞电来照目。
兽迹不敢窥，马蹄唯务速。
虔心若斋礼，濡体如沐浴。
万窍相怒号，百泉暗奔瀑。
危梁虑足跌，峻坂忧车覆。
问我何以然，前日受微禄。
转知人代事，缨组乃徽束。
向若家居时，安枕春梦熟。
遵途稍已近，候吏来相续。
晓霁心始安，林端见初旭。','',''),('quantangshi-17364','细柳驿','權德輿','quantangshi','','卷18','细柳肃军令，条侯信殊伦。
棘门乃儿戏，从古多其人。
神武今不杀，介夫如搢绅。
息驾幸兹地，怀哉悚精神。','',''),('quantangshi-17365','渭水','權德輿','quantangshi','','卷18','吕叟年八十，皤然持钓钩。
意在静天下，岂唯食营丘。
师臣有家法，小白犹尊周。
日暮驻征策，爱兹清渭流。','',''),('quantangshi-17366','宫人斜绝句','權德輿','quantangshi','','卷18','一路斜分古驿前，阴风切切晦秋烟。
铅华新旧共冥寞，日暮愁鸱飞野田。','',''),('quantangshi-17367','敷水驿','權德輿','quantangshi','','卷18','空见水名敷，秦楼昔事无。
临风驻征骑，聊复捋髭须。','',''),('quantangshi-17368','朝元阁','權德輿','quantangshi','','卷18','缭垣复道上层霄，十月离宫万国朝。
胡马忽来清跸去，空余台殿照山椒。','',''),('quantangshi-17369','石瓮寺','權德輿','quantangshi','','卷18','石瓮灵泉胜宝井，汲人回挂青丝绠。
厨烟半逐白云飞，当昼老僧来灌顶。','',''),('quantangshi-17370','盘豆驿','權德輿','quantangshi','','卷18','盘豆绿云上古驿，望思台下使人愁。
江充得计太子死，日暮戾园风雨秋。','',''),('quantangshi-17371','晚渡扬子江却寄江南亲故','權德輿','quantangshi','','卷18','返照满寒流，轻舟任摇漾。
支颐见千里，烟景非一状。
远岫有无中，片帆风水上。
天清去鸟灭，浦迥寒沙涨。
树晚叠秋岚，江空翻宿浪。
胸中千万虑，对此一清旷。
回首碧云深，佳人不可望。','',''),('quantangshi-17372','新安江路','權德輿','quantangshi','','卷18','深潭与浅滩，万转出新安。
人远禽鱼净，山深水木寒。
啸起青苹末，吟瞩白云端。
即事遂幽赏，何心挂儒冠。','',''),('quantangshi-17373','月夜江行','權德輿','quantangshi','','卷18','扣船不得寐，浩露清衣襟。
弥伤孤舟夜，远结万里心。
幽兴惜瑶草，素怀寄鸣琴。
三奏月初上，寂寞寒江深。','',''),('quantangshi-17374','江城夜泊寄所思','權德輿','quantangshi','','卷18','客程殊未极，舣棹泊回塘。
水宿知寒早，愁眠觉夜长。
远钟和暗杵，曙月照晴霜。
此夕相思意，摇摇不暂忘。','',''),('quantangshi-17375','陪包谏议湖墅路中举帆','權德輿','quantangshi','','卷18','萧萧凉雨歇，境物望中闲。
风际片帆去，烟中独鸟还。
断桥通远浦，野墅接秋山。
更喜陪清兴，尊前一解颜。','',''),('quantangshi-17376','富阳陆路','權德輿','quantangshi','','卷18','又入乱峯去，远程殊未归。
烟萝迷客路，山果落征衣。
攲石临清浅，晴云出翠微。
渔潭明夜泊，心忆谢玄晖。','',''),('quantangshi-17377','晓','權德輿','quantangshi','','卷18','晓风摇五两，残月映石壁。
稍稍曙光开，片帆在空碧。','',''),('quantangshi-17378','昼','權德輿','quantangshi','','卷18','孤舟漾暧景，独鹤下秋空。
安流日正昼，净绿天无风。','',''),('quantangshi-17379','晚','權德輿','quantangshi','','卷18','古树夕阳尽，空江暮霭收。
寂寞扣船坐，独生千里愁。','',''),('quantangshi-17380','夜','權德輿','quantangshi','','卷18','猨声到枕上，愁梦纷难理。
寂寞深夜寒，青霜落秋水。','',''),('quantangshi-17381','奉和韦谏议奉送水部家兄上后书情寄诸兄弟仍通简南宫亲旧并呈两省阁老院长','權德輿','quantangshi','','卷18','驷牡龙旗庆至今，一门儒服耀华簪。
人望皆同照乘宝，家风不重满籝金。
护衣直夜南宫静，焚草清时左掖深。
何幸末班陪两地，阳春欲和意难任。','',''),('quantangshi-17382','奉和史馆张阁老以许陈二阁长爱弟俱为尚书郎伯仲同时列在南北省会于左掖因而有咏','權德輿','quantangshi','','卷18','伯仲尽时贤，平舆与颍川。
桂枝尝徧折，棣萼更相鲜。
丹地晨趋并，黄扉夕拜联。
岂如分侍从，来就凤池边。','',''),('quantangshi-17383','韦宾客宅与诸博士宴集','權德輿','quantangshi','','卷18','累抗乞身章，湛恩比上庠。
宾筵徴稷嗣，家法自扶阳。
簪组欢言久，琴壶雅兴长。
阴岚冒苔石，轻籁韵风篁。
佩玉三朝贵，挥金百虑忘。
因知卧商洛，岂胜白云乡。','',''),('quantangshi-17384','酬张祕监阁老喜太常中书二阁老与德舆同日迁官相代之作','權德輿','quantangshi','','卷18','珠树共飞栖，分封受紫泥。
正名推五字，贵仕仰三圭。
继组心知忝，腰章事颇齐。
蓬山有佳句，喜气在新题。','',''),('quantangshi-17385','国子柳博士兼领太常博士辄申贺赠','權德輿','quantangshi','','卷18','博士本秦官，求才帖职难。
临风曲台净，对月璧池寒。
讲学分阴重，斋祠晓漏残。
朝衣辨色处，双绶更宜看。','',''),('quantangshi-17386','过隐者湖上所居','權德輿','quantangshi','','卷18','蜗舍映平湖，皤然一鲁儒。
唯将酒作圣，不厌谷名愚。
兵法窥黄石，天官辨白榆。
行看软轮起，未可号潜夫。','',''),('quantangshi-17387','从叔将军宅蔷薇花开太府韦卿有题壁长句因以和作','權德輿','quantangshi','','卷18','环列从容蹀躞归，光风骀荡发红薇。
莺藏密叶宜新霁，蝶遶低枝爱晚晖。
艳色当轩迷舞袖，繁香满迳拂朝衣。
名卿洞壑仍相近，佳句新成和者稀。','',''),('quantangshi-17388','奉和许阁老霁后慈恩寺杏园看花同用花字口号','權德輿','quantangshi','','卷18','杏林微雨霁，灼灼满瑶华。
左掖期先至，中园景未斜。
含毫歌白雪，藉草醉流霞。
独限金闺籍，支颐啜茗花。','',''),('quantangshi-17389','奉和陈阁老寒食初假当直从东省往集贤因过史馆看木瓜花寄张蒋二阁老','權德輿','quantangshi','','卷18','昼漏沈沈倦琐闱，西垣东观阅芳菲。
繁花满树似留客，应为主人休澣归。','',''),('quantangshi-17390','晚秋陪崔阁老张祕监阁老苗考功同游昊天观时杨阁老新直未满以诗见寄斐然酬和有愧芜音','權德輿','quantangshi','','卷18','方驾游何许，仙源去似归。
萦回留胜赏，萧洒出尘机。
泛菊贤人至，烧丹姹女飞。
步虚清晓籁，隐几吸晨晖。
竹迳琅玕合，芝田沆瀣曦。
银钩三洞字，瑶笥六铢衣。
丽句翻红药，佳期限紫微。
徒然一相望，郢曲和应稀。','',''),('quantangshi-17391','春日同诸公过兵部王尚书林园','權德輿','quantangshi','','卷18','休沐君相近，时容曳履过。
花间留客久，台上见春多。
松色明金艾，莺声杂玉珂。
更逢新酒熟，相与藉庭莎。','',''),('quantangshi-17392','与沈十九拾遗同游栖霞寺上方于亮上人院会宿二首 一','權德輿','quantangshi','','卷18','摄山标胜绝，暇日谐想瞩。
萦纡松路深，缭绕云岩曲。
重楼回树杪，古像凿山腹。
人远水木清，地深兰桂馥。
层台耸金碧，绝顶摩净绿。
下界诚可悲，南朝纷在目。
焚香入古殿，待月出深竹。
稍觉天籁清，自伤人世促。
宗雷此相遇，偃放从所欲。
清论松枝低，闲吟茗花熟。
一生如土梗，万虑相桎梏。
永愿事潜师，穷年此栖宿。','',''),('quantangshi-17393','与沈十九拾遗同游栖霞寺上方于亮上人院会宿二首 二','權德輿','quantangshi','','卷18','偶来人境外，心赏幸随君。
古殿烟霞夕，深山松桂薰。
岩花点寒溜，石磴扫春云。
清净诸天近，喧尘下界分。
名僧康宝月，上客沈休文。
共宿东林夜，清猨彻曙闻。','',''),('quantangshi-17394','题崔山人草堂','權德輿','quantangshi','','卷18','竹径茆堂接洞天，闲时麈尾漱春泉。
世人车马不知处，时有归云到枕边。','',''),('quantangshi-17395','徐孺亭马上口号','權德輿','quantangshi','','卷18','湖上荒亭临水开，龟文篆字积莓苔。
曲江北海今何处，尽逐东流去不回。','',''),('quantangshi-17396','哭刘四尚书','權德輿','quantangshi','','卷18','士友惜贤人，天朝丧守臣。
才华推独步，声气幸相亲。
理析寰中妙，儒为席上珍。
笑言成月旦，风韵挹天真。
丹地膺推择，青油寄抚循。
岂言朝象魏，翻是卧漳滨。
命赐龙泉重，追荣密印陈。
撤弦惊物故，庀具见家贫。
牢落风悲笛，丸澜涕泣巾。
只嗟蒿里月，非复柳营春。
黄绢碑文在，青松隧路新。
音容无处所，归作北邙尘。','',''),('quantangshi-17397','张工部至薄寒山下有书无由驰报輤车之至倍切悲怀','權德輿','quantangshi','','卷18','书来远自薄寒山，缭绕洮河出古关。
今日难裁秣陵报，薤歌寥落柳车边。','',''),('quantangshi-17398','工部发引日属伤足卧疾不遂执绋','權德輿','quantangshi','','卷18','子春伤足日，况有寝门哀。
元伯归全去，无由白马来。
笳箫里巷咽，龟筮墓田开。
片石潺湲泪，含悲叙史才。','',''),('quantangshi-17399','从事淮南府过亡友杨校书旧厅感念愀然','權德輿','quantangshi','','卷18','故人随化往，倏忽今六霜。
及我就拘限，清风留此堂。
松竹逾映蔚，芝兰自销亡。
绝弦罢流水，闻笛同山阳。
熲如冰玉姿，粲若鸾凤章。
欲翥摧劲翮，先秋落贞芳。
正平赋鹦鹉，文考颂灵光。
二子古不吊，夫君今何伤。
黄墟既杳杳，玄化亦茫茫。
岂必限宿草，含凄洒衣裳。','',''),('quantangshi-17400','哭李晦羣崔季文二处士','權德輿','quantangshi','','卷18','华封西祝尧，贵寿多男子。
二贤无主后，贫贱大壮齿。
未成鸿鹄姿，遽顿骅骝趾。
子渊将叔度，自古不得已。','',''),('quantangshi-17401','观葬者','權德輿','quantangshi','','卷18','涂刍随昼哭，数里至松门。
贵尽人间礼，宁知逝者魂。
笳箫出古陌，烟雨闭寒原。
万古皆如此，伤心反不言。','',''),('quantangshi-17402','成南阳墓','權德輿','quantangshi','','卷18','枯荄没古基，驳藓蔽丰碑。
向晚微风起，如闻坐啸时。','',''),('quantangshi-17403','周平西墓','權德輿','quantangshi','','卷18','英威今寂寞，陈迹对崇丘。
壮志清风在，荒坟白日愁。
穷泉那复晓，乔木不知秋。
岁岁寒塘侧，无人水自流。','',''),('quantangshi-17404','苏小小墓','權德輿','quantangshi','','卷18','万古荒坟在，悠然我独寻。
寂寥红粉尽，冥寞黄泉深。
蔓草映寒水，空郊暧夕阴。
风流有佳句，吟眺一伤心。','',''),('quantangshi-17405','题柳郎中茅山故居','權德輿','quantangshi','','卷18','下马荒堦日欲曛，潺潺石溜静中闻。
鸟啼花落人声绝，寂寞山窗掩白云。','',''),('quantangshi-17406','哭张十八校书','權德輿','quantangshi','','卷18','芸阁为郎一命初，桐州寄傲十年余。
魂随逝水归何处，名在新诗众不如。
蹉跎江浦生华发，牢落寒原会素车。
更忆八行前日到，含凄为报秣陵书。','',''),('quantangshi-17407','题亡友江畔旧居','權德輿','quantangshi','','卷18','寥落留三径，柴扉对楚江。
蟏蛸集暗壁，蜥蜴走寒窗。
松盖欹书幌，苔衣上酒缸。
平生断金契，到此泪成双。','',''),('quantangshi-17408','德宗神武孝文皇帝挽歌词三首 一','權德舆','quantangshi','','卷18','覆露雍熙运，澄清敎化源。
赓歌凝庶绩，羽舞被深恩。
纂业光文祖，贻谋属孝孙。
恭闻留末命，犹是爱元元。','',''),('quantangshi-17409','德宗神武孝文皇帝挽歌词三首 二','權德舆','quantangshi','','卷18','梯航来万国，玉帛庆三朝。
湛露恩方浃，薰风曲正调。
晏车悲卤簿，广乐遏箫韶。
最怆号弓处，龙髯上紫霄。','',''),('quantangshi-17410','德宗神武孝文皇帝挽歌词三首 三','權德舆','quantangshi','','卷18','常时柏梁宴，今日谷林归。
玉斝恩波徧，灵輼烟雨霏。
乔山森羽骑，渭水拥旌旗。
仙驭何由见，耘田鸟自飞。','',''),('quantangshi-17411','顺宗至德大安孝皇帝挽歌三首 一','權德舆','quantangshi','','卷18','十叶开昌运，三辰丽德音。
荐功期瘗玉，昭俭每捐金。
解泽皇风徧，虞泉白日沈。
仍闻起居注，焚奏感人心。','',''),('quantangshi-17412','顺宗至德大安孝皇帝挽歌三首 二','權德舆','quantangshi','','卷18','孝理本忧勤，玄功在啬神。
睿图传上嗣，寿酒比家人。
仙驭三清远，行宫万象新。
小臣司吉从，还扈属车尘。','',''),('quantangshi-17413','顺宗至德大安孝皇帝挽歌三首 三','權德舆','quantangshi','','卷18','候晓传清跸，迎风引彩旒。
共瞻宫辂出，遥想望陵愁。
弓劒随云气，衣冠奉月游。
空余驾龙处，摇落鼎湖秋。','',''),('quantangshi-17414','昭德皇后挽歌词','權德舆','quantangshi','','卷18','淮水源流远，涂山礼命升。
往年求故劒，今夕祔初陵。
鸾镜金波涩，翚衣玉彩凝。
千年子孙庆，孝理在蒸蒸。','',''),('quantangshi-17415','大行皇太后挽歌词三首 一','權德舆','quantangshi','','卷18','筮水灵源浚，因山祔礼崇。
从龙开隧路，合璧向方中。
殿帐金根出，廞衣玉座空。
唯余文母化，阴德满公宫。','',''),('quantangshi-17416','大行皇太后挽歌词三首 二','權德舆','quantangshi','','卷18','配礼归清庙，灵仪出直城。
九虞宁厚载，一惠易尊名。
晓漏铜壶涩，秋风羽翣轻。
容车攀望处，孺慕切皇情。','',''),('quantangshi-17417','大行皇太后挽歌词三首 三','權德舆','quantangshi','','卷18','哀笳出长信，宝劒入延津。
呜咽宫车进，凄凉祠殿新。
青乌灵兆久，白燕瑞书频。
从此山园夕，金波照玉尘。','',''),('quantangshi-17418','惠昭皇太子挽歌词二首 一','權德舆','quantangshi','','卷18','前星落庆霄，薤露逐晨飙。
宫仗黄麾出，仙游紫府遥。
空嗟凤吹去，无复鸡鸣朝。
今夜西园月，重轮更寂寥。','',''),('quantangshi-17419','惠昭皇太子挽歌词二首 二','權德舆','quantangshi','','卷18','东朝闻楚挽，羽翿依稀转。
天归京兆新，日与长安远。
兰芳落故殿，桂影销空苑。
骑吹咽不前，风悲九旗卷。','',''),('quantangshi-17420','赠文敬太子挽歌词二首 一','權德舆','quantangshi','','卷18','盘石公封重，瑶山赠礼尊。
归全荣备物，乐善积深恩。
雁沼寒波咽，鸾旌夕吹翻。
唯余西靡树，千古霸陵原。','',''),('quantangshi-17421','赠文敬太子挽歌词二首 二','權德舆','quantangshi','','卷18','铜壶晓漏初，羽翣拥涂车。
方外留鸿宝，人间得善书。
清笳悲画绶，朱邸散长裾。
还似缑山驾，飘飘向碧虚。','',''),('quantangshi-17422','赠郑国庄穆公主挽歌二首 一','權德舆','quantangshi','','卷18','追饰崇汤沐，遗芳蔼禁闱。
秋原森羽卫，夜壑掩容辉。
睿藻悲难尽，公宫望不归。
笳箫向烟雾，疑是彩鸾飞。','',''),('quantangshi-17423','赠郑国庄穆公主挽歌二首 二','權德舆','quantangshi','','卷18','旧馆闭平阳，容车启寿堂。
霜凝蕣英落，风度薤歌长。
淑德图书在，皇慈礼命彰。
凄凉霸川曲，垄树已成行。','',''),('quantangshi-17424','赠魏国宪穆公主挽歌词二首 一','權德舆','quantangshi','','卷18','汉制荣车服，周诗美肃雍。
礼尊同姓主，恩锡大名封。
外馆留图史，阴堂闭德容。
睿词悲薤露，千古仰芳踪。','',''),('quantangshi-17425','赠魏国宪穆公主挽歌词二首 二','權德舆','quantangshi','','卷18','秦楼晓月残，卤簿列材官。
红绶兰桂歇，粉田风露寒。
凝笳悲驷马，清镜掩孤鸾。
愍册徽音在，都人雪涕看。','',''),('quantangshi-17426','赠梁国惠康公主挽歌词二首 一','權德舆','quantangshi','','卷18','外馆嫔仪贵，中参睿渥深。
初笄横白玉，盛服镂黄金。
风度箫声远，河低婺彩沈。
夜台留册諡，凄怆即徽音。','',''),('quantangshi-17427','赠梁国惠康公主挽歌词二首 二','權德舆','quantangshi','','卷18','杳霭异湘川，飘颻驾紫烟。
凤楼人已去，鸾镜月空悬。
雾湿汤沐地，霜凝脂粉田。
音容无处所，应在玉皇前。','',''),('quantangshi-17428','故太尉兼中书令赠太师西平王挽词','權德舆','quantangshi','','卷18','翊戴推元老，谋猷合大君。
河山封故地，金石表新坟。
劒履归长夜，笳箫咽暮云。
还经誓师处，薤露不堪闻。','',''),('quantangshi-17429','故司徒兼侍中赠太傅北平王挽词','權德舆','quantangshi','','卷18','授律勋庸盛，居中鼎鼐和。
佐时调四气，尽力净三河。
忽访天京兆，空传汉伏波。
今朝麟阁上，偏轸圣情多。','',''),('quantangshi-17430','奉和礼部尚书酬杨着作竹亭歌','權德舆','quantangshi','','卷18','直城朱户相逦连，九逵丹毂声阗阗。
春官自有花源赏，终日南山当目前。
晨摇玉佩趋温室，莫入竹溪疑洞天。
烟销雨过看不足，晴翠鲜飙逗深谷。
独谣一曲泛流霞，闲对千竿连净绿。
萦回疏凿随胜地，石磴岩扉光景异。
虚斋寂寂清籁唫，幽涧纷纷杂英坠。
家承麟趾贵，劒有龙泉赐。
上奉明时事无事，人间方外兴偏多。
能以簪缨狎薜萝，常通内学青莲偈。
更奏新声白雪歌，风入松，云归栋。
鸿飞灭处犹目送，蝶舞闲时梦忽成。
兰台有客叙交情，返照中林曳履声。
直为君恩催造膝，东方辨色谒承明。','',''),('quantangshi-17431','奉和张仆射朝天行','權德舆','quantangshi','','卷18','元侯重寄贞师律，三郡四封今静谧。
丹毂常思阙下来，紫泥忽自天中出。
军装喜气倍趋程，千骑鸣珂入凤城。
周王致理称申甫，今日贤臣见明主。
拜恩稽首纷无已，凝旒前席皇情喜。
逢时自是山出云，献可还同石投水。
昔岁褒衣梁甫吟，当时已有致君心。
专城一鼓妖氛静，拥斾十年天泽深。
日日披诚奉昌运，王人织路传清问。
仙酝尝分玉斝浓，御闲更辍金羁骏。
元正前殿朝君臣，一人负扆百福新。
宫悬彩仗俨然合，瑞气炉烟相与春。
万年枝上东风早，佩玉晨趋光景好。
涂山已见首诸侯，麟阁终当画元老。
温室沈沈漏刻移，退朝宾侣每相随。
雄词乐职波涛阔，旷度交欢云雾披。
自古全才贵文武，懦夫只解冠章甫。
见公抽匣百炼光，试欲磨铅谅无助。','',''),('quantangshi-17432','和李中丞慈恩寺清上人院牡丹花歌','權德舆','quantangshi','','卷18','澹荡韶光三月中，牡丹偏自占春风。
时过宝地寻香径，已见新花出故丛。
曲水亭西杏园北，浓芳深院红霞色。
擢秀全胜珠树林，结根幸在青莲城。
艳蘂鲜房次第开，含烟洗露照苍苔。
庞眉依杖禅僧起，轻翅萦枝舞蝶来。
独坐南台时共美，闲行古刹情何已。
花间一曲奏阳春，应为芬芳比君子。','',''),('quantangshi-17433','锡杖歌送明楚上人归佛川','權德舆','quantangshi','','卷18','上人远自西天竺，头陁行徧国朝寺。
口翻贝叶古字经，手持金策声泠泠。
护法护身唯振锡，石濑云溪深寂寂。
乍来松径风更寒，遥映霜天月成魄。
后夜空山禅诵时，寥寥挂在枯树枝。
真法常传心不住，东西南北随缘路。
佛川此去何时回，应真莫便游天台。','',''),('quantangshi-17434','马秀才草书歌','權德舆','quantangshi','','卷18','伯英草圣称绝伦，后来学者无其人。
白眉年少未弱冠，落纸纷纷运纤腕。
初闻之子十岁余，当时时辈皆不如。
犹轻昔日墨池学，未许前贤团扇书。
艳彩芳姿相点缀，水映荷花风转蕙。
三春并向指下生，万象争分笔端势。
有时当暑如清秋，满堂风雨寒飕飕。
乍疑崩崖瀑水落，又见古木饥鼯愁。
变化纵横出新意，眼看一字千金贵。
忆昔谢安问献之，时人虽见那得知。','',''),('quantangshi-17435','离合诗赠张监阁老','權德舆','quantangshi','','卷18','黄叶从风散，暗嗟时节换。
忽见鬓边霜，勿辞林下觞。
躬行君子道，身负芳名早。
帐殿汉官仪，巾车塞垣草。
交情剧断金，文律每招寻。
始知蓬山下，如见古人心。','',''),('quantangshi-17436','春日雪酬潘孟阳回文','權德舆','quantangshi','','卷18','酒杯春醉好，飞雪晚庭闲。
久忆同前赏，中林对远山。','',''),('quantangshi-17437','五杂组','權德舆','quantangshi','','卷18','五杂组，旗亭客。
往复还，城南陌。
不得已，天涯谪。','',''),('quantangshi-17438','数名诗','權德舆','quantangshi','','卷18','一区杨雄宅，恬然无所欲。
二顷季子田，岁晏常自足。
三端固为累，事物反徽束。
四体苟不动，安得丰菽粟。
五侯诚暐晔，荣甚或为辱。
六翮未骞翔，虞罗乃相触。
七人称作者，杳杳有遐躅。
八桂挺奇姿，森森照初旭。
九歌伤泽畔，怨思徒刺促。
十翼有格言，幽贞谢浮俗。','',''),('quantangshi-17439','星名诗','權德舆','quantangshi','','卷18','虚怀何所欲，岁晏聊懒逸。
云翼谢翩翻，松心保贞实。
风秋景气爽，叶落井迳出。
陶然美酒酣，所谓幽人吉。
自当轻尺璧，岂复埽一室。
安用簪进贤，少微斯可必。','',''),('quantangshi-17440','卦名诗','權德舆','quantangshi','','卷18','节变忽惊春，临风骋望频。
支颐倦书幌，步履整山巾。
时鸟渐成曲，杂芳随意新。
曙霞连观阙，绮陌丽咸秦。
天地今交泰，云雷背遘屯。
中孚谅可乐，书此示家人。','',''),('quantangshi-17441','药名诗','權德舆','quantangshi','','卷18','七泽兰芳千里春，潇湘花落石磷磷。
有时浪白微风起，坐钓藤阴不见人。','',''),('quantangshi-17442','古人名诗','權德舆','quantangshi','','卷18','藩宣秉戎寄，衡石崇势位。
年纪信不留，弛张良自愧。
樵苏则为惬，瓜李斯可畏。
不顾荣官尊，每陈丰亩利。
家林类岩巘，负郭躬敛积。
忌满宠生嫌，养蒙恬胜智。
疎钟皓月晓，晚景丹霞异。
涧谷永不谖，山梁冀无累。
颇符生肇学，得展禽尚志。
从此直不疑，支离疎世事。','',''),('quantangshi-17443','州名诗寄道士','權德舆','quantangshi','','卷18','金兰同道义，琼简复芝田。
平楚白云合，幽崖丹桂连。
松峯明爱景，石窦纳新泉。
冀永南山寿，欢随万福延。','',''),('quantangshi-17444','八音诗','權德舆','quantangshi','','卷18','金谷盛繁华，凉台列簪组。
石崇留客醉，绿珠当座舞。
丝泪可销骨，冶容竟何补。
竹林谅贤人，满酌无所苦。
匏居容宴豆，儒室贵环堵。
土鼓与污尊，颐神则为愈。
革道当在早，谦光斯可取。
木雁才不才，吾知养生主。','',''),('quantangshi-17445','建除诗','權德舆','quantangshi','','卷18','建节出王都，雄雄大丈夫。
除书加右职，骑吏拥前驱。
满月张繁弱，含霜耀鹿卢。
平明跃騕褭，清夜击珊瑚。
定远功那比，平津策乃迂。
执心思报国，效节在忘躯。
破胆销丹浦，颦蛾舞绿珠。
危冠徒自爱，长毂事应殊。
成绩封千室，畴劳使五符。
收功轻骠卫，致埋迈黄虞。
开济今如此，英威古不侔。
闭关草玄者，无乃误为儒。','',''),('quantangshi-17446','六府诗','權德舆','quantangshi','','卷18','金罍暎玉俎，宾友纷宴喜。
木兰泛方塘，桂酒启皓齿。
水榭临空迥，酣歌当座起。
火云散奇峯，瑶瑟韵清徴。
土梗乃虚论，康庄有逸轨。
谷成一编书，谈笑佐天子。','',''),('quantangshi-17447','三妇诗','權德舆','quantangshi','','卷18','大妇刺绣文，中妇缝罗裙。
小妇无所作，娇歌遏行云。
丈人且安坐，金炉香正薰。','',''),('quantangshi-17448','安语','權德舆','quantangshi','','卷18','岩岩五岳镇方舆，八极廓清氛祲除。
挥金得谢归里闾，象牀角枕支体舒。','',''),('quantangshi-17449','危语','權德舆','quantangshi','','卷18','被病独行逢乳虎，狂风骇浪失棹橹。
举人看牓闻晓鼓，孱夫孽子遇妬母。','',''),('quantangshi-17450','大言','權德舆','quantangshi','','卷18','华嵩为佩河为带，南交北朔跬步内。
搏鹏作腊巨鳌鲙，伸舒轶出元气外。','',''),('quantangshi-17451','小言','權德舆','quantangshi','','卷18','醯鸡伺晨驾蚊翼，毫端棘刺分畛域。
蛛丝结构聊荫息，蚁垤崔嵬不可陟。','',''),('quantangshi-17452','杂诗五首 一','權德輿','quantangshi','','卷18','婉彼嬴氏女。
吹箫偶萧史，彩鸾驾非烟。
绰约两仙子，神期谅交感。
相顾乃如此，岂比成都人，琴心中夜起。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-17453','杂诗五首 二','權德輿','quantangshi','','卷18','阳台巫山上，风雨忽清旷。
朝云与游龙，变化千万状。
魂交复目断，缥缈难比况。
兰泽不可亲，凝清坐惆怅。','',''),('quantangshi-17454','杂诗五首 三','權德輿','quantangshi','','卷18','淇水春正绿，上宫兰叶齐。
光风两摇荡，鸣佩出中闺。
一顾授横波，千金呈瓠犀。
徒然路傍子，怳怳复凄凄。','',''),('quantangshi-17455','杂诗五首 四','權德輿','quantangshi','','卷18','碧树泛鲜飙，玉琴含妙曲。
佳人掩鸾镜，婉婉凝相瞩。
文袿映束素，香黛宜𥊑绿。
寂寞远怀春，何时来比目。','',''),('quantangshi-17456','杂诗五首 五','權德輿','quantangshi','','卷18','含颦倚瑶瑟，丹慊结繁虑。
失身不自还，万恨随玉筯。
蘼芜山下路，团扇秋风去。
君看心断时，犹在目成处。','',''),('quantangshi-17457','广陵诗','權德輿','quantangshi','','卷18','广陵实佳丽，隋季此为京。
八方称辐凑，五达如砥平。
大斾映空色，笳箫发连营。
层台出重霄，金碧摩颢清。
交驰流水毂，迥接浮云甍。
青楼旭日映，绿野春风晴。
喷玉光照地，颦蛾价倾城。
灯前互巧笑，陌上相逢迎。
飘飘翠羽薄，掩映红襦明。
兰麝远不散，管弦闲自清。
曲士守文墨，达人随性情。
茫茫竟同尽，冉冉将何营。
且申今日欢，莫务身后名。
肯学诸儒辈，书窗误一生。','',''),('quantangshi-17458','古意','權德輿','quantangshi','','卷18','家人强进酒，酒后能忘情。
持杯未饮时，众感纷已盈。
明月照我房，庭柯振秋声。
空庭白露下，枕席凉风生。
所思万里余，水阔山纵横。
佳期凭梦想，未晓愁鸡鸣。
愿将一心人，当年欢乐平。
长筵暎玉俎，素手弹秦筝。
𥊑睇呈巧笑，惠音激凄清。
此愿良未果，永怀空如酲。','',''),('quantangshi-17459','杂言和常州李员外副使春日戏题十首 一','權德輿','quantangshi','','卷18','随风柳絮轻，暎日杏花明。
无奈花深处，流莺三数声。','',''),('quantangshi-17460','杂言和常州李员外副使春日戏题十首 二','權德輿','quantangshi','','卷18','兰桡画舸转花塘，水映风摇路渐香。
任兴不知行近远，更怜微月照鸣榔。','',''),('quantangshi-17461','杂言和常州李员外副使春日戏题十首 三','權德輿','quantangshi','','卷18','檐前晓色惊双燕，户外春风舞百花。
粉署可怜闲对此，唯令碧玉泛流霞。','',''),('quantangshi-17462','杂言和常州李员外副使春日戏题十首 四','權德輿','quantangshi','','卷18','枕上觉，窗外晓。
怯朝光，惊曙鸟。
花坠露，满芳沼。
柳如丝，风褭褭。
佳期远，相见少。
试一望，魂杳渺。','',''),('quantangshi-17463','杂言和常州李员外副使春日戏题十首 五','權德輿','quantangshi','','卷18','闲庭无事，独步春辉。
韶光满目，落蘂盈衣。
芳树交柯，文禽并飞。
婉彼君子，怅然有违。
对酒不饮，横琴不挥。
不挥者何，知音诚稀。','',''),('quantangshi-17464','杂言和常州李员外副使春日戏题十首 六','權德輿','quantangshi','','卷18','江春好游衍，处处芳菲积。
彩舫入花津，香车依柳陌。
绿杨烟褭褭，红蘂莺寂寂。
如何愁思人，独与风光隔。','',''),('quantangshi-17465','杂言和常州李员外副使春日戏题十首 七','權德輿','quantangshi','','卷18','曙月渐到窗前，移尊更就芳筵。
轻吹乍摇兰烛，春光暗入花钿。
丝竹偏宜静夜，绮罗共占韶年。
不遣通宵尽醉，定知辜负风烟。','',''),('quantangshi-17466','杂言和常州李员外副使春日戏题十首 八','權德輿','quantangshi','','卷18','露洗百花新，帘开月照人。
绿窗销暗烛，兰迳埽清尘。
双燕频惊梦，三桃竞报春。
相思寂不语，珠泪洒红巾。','',''),('quantangshi-17467','杂言和常州李员外副使春日戏题十首 九','權德輿','quantangshi','','卷18','雨歇风轻一院香，红芳绿草接东墙。
春衣试出当轩立，定被邻家暗断肠。','',''),('quantangshi-17468','杂言和常州李员外副使春日戏题十首 十','權德輿','quantangshi','','卷18','春风半，春光徧。
柳如丝，花似霰。
归心劳梦寐，远目伤游眄。
可惜长安无限春，年年空向江南见。','',''),('quantangshi-17469','相思曲','權德輿','quantangshi','','卷18','少小别潘郎，娇羞倚画堂。
有时裁尺素，无事约残黄。
鹊语临妆镜，花飞落绣牀。
相思不解说，明月照空房。','',''),('quantangshi-17470','古乐府','權德輿','quantangshi','','卷18','风光澹荡百花吐，楼上朝朝学歌舞。
身年二八壻侍中，幼妹承恩兄尚主。
绿窗珠箔绣鸳鸯，侍婢先焚百和香。
莺啼日出不知曙，寂寂罗帏春梦长。','',''),('quantangshi-17471','渡江秋怨二首 一','權德輿','quantangshi','','卷18','秋江平，秋月明，孤舟独夜万里情。
万里情，相思远，人不见兮泪满眼。','',''),('quantangshi-17472','渡江秋怨二首 二','權德輿','quantangshi','','卷18','渡秋江兮渺然，望秋月兮婵娟。
色如练，万里徧，我有所思兮不得见。
不得见兮露寒水深，耿遥夜兮伤心。','',''),('quantangshi-17473','秋闺月','權德輿','quantangshi','','卷18','三五二八月如练，海上天涯应共见。
不知何处玉楼前，乍入深闺玳瑁筵。
露浓香迳和愁坐，风动罗帏照独眠。
初卷珠帘看不足，斜抱箜篌未成曲。
稍映妆台临绮窗，遥知不语泪双双。
此时愁望知何极，万里秋天同一色。
霭霭遥分陌上光，迢迢对此闺中忆。
早晚归来欢宴同，可怜歌吹月明中。
此夜不堪肠断绝，愿随流影到辽东。','',''),('quantangshi-17474','薄命篇','權德輿','quantangshi','','卷18','昔住邯郸年尚少，只是娇羞弄花鸟。
青楼碧纱大道边，绿杨日暮风褭褭。
婵娟玉貌二八余，自怜颜色花不如。
丽质全胜秦氏女，藁砧宁用专城居。
岁去年来年渐长，青春红粉全堪赏。
玉楼珠箔但闲居，南陌东城讵来往。
韶光日日看渐迟，[摽]梅既落行有时。
宁知燕赵娉婷子，翻嫁幽并游侠儿。
年年结束青丝骑，出门一去何时至。
秋月空悬翡翠帘，春帏嬾卧鸳鸯被。
沙塞经时不寄书，深闺愁独意何如。
花前拭泪情无限，月下调琴恨有余。
离别苦多相见少，洞房愁梦何由晓。
闲看双燕泪霏霏，静对空牀魂悄悄。
镜里红颜不自禁，陌头香骑动春心。
为问佳期早晚是，人人总解有黄金。','',''),('quantangshi-17475','放歌行','權德輿','quantangshi','','卷18','夕阳不驻东流急，荣名贵在当年立。
青春虚度无所成，白首衔悲亦何及。
拂衣西笑出东山，君臣道合俄顷间。
一言一笑玉墀上，变化生涯如等闲。
朱门杳杳列华戟，座中皆是王侯客。
鸣环动佩暗珊珊，骏马花骢白玉鞍。
十千斗酒不知贵，半醉留宾邀尽欢。
银烛煌煌夜将久，侍婢金罍泻春酒。
春酒盛来琥珀光，暗闻兰麝几般香。
乍看皓腕暎罗袖，微听清歌发杏梁。
双鬟美人君不见，一一皆胜赵飞燕。
迎杯乍举石榴裙，匀粉时交合欢扇。
未央钟漏醉中闻，联骑朝天曙色分。
双阙烟云遥霭霭，五衢车马乱纷纷。
罢朝鸣佩骤归鞍，今日还同昨日欢。
岁岁年年恣游宴，出门满路光辉徧。
一身自乐何足言，九族为荣真可羡。
男儿称意须及时，闭门下帷人不知。
年光看逐转蓬尽，徒咏东山招隐诗。','',''),('quantangshi-17476','旅馆雪晴又覩新月众兴所感因成杂言','權德輿','quantangshi','','卷18','寥寥深夜雪初晴，楼上云开月渐明。
池中片影依稀见，帘外清光远近生。
皎皎晴空疑破镜，广庭积素偏相映。
珠帘卷却光更深，玉指持来色逾净。
梦觉青楼最可怜，婵娟素魄满寒天。
天地寥寥同一色，秦淮楚江无限极。
归鸿断猨何处声，深闺旅馆遥相忆。
长安五侯华阁开，嘉宾列坐倾金罍。
赏明月，翫流雪，纤手蛾眉座中设。
清歌一声无断绝，夜已央，乐未阑。
狐裘兽炭不知寒，珠环翠佩声珊珊。
履舃纷纭桂袖攒，朱颜倚醉尽君欢。
人生少年全不久，相看且劝杯中酒。
丈夫富贵自有期，映雪读书徒白首。','',''),('quantangshi-17477','玉台体十二首 一','權德輿','quantangshi','','卷18','莺啼兰已红，见出凤城东。
粉汗宜斜日，衣香逐上风。
情来不自觉，暗驻五花骢。','',''),('quantangshi-17478','玉台体十二首 二','權德輿','quantangshi','','卷18','婵娟二八正娇羞，日暮相逢南陌头。
试问佳期不肯道，落花深处指青楼。','',''),('quantangshi-17479','玉台体十二首 三','權德輿','quantangshi','','卷18','隐映罗衫薄，轻盈玉腕圆。
相逢不肯语，微笑画屏前。','',''),('quantangshi-17480','玉台体十二首 四','權德輿','quantangshi','','卷18','知向辽东去，由来几许愁。
破颜君莫怪，娇小不禁羞。','',''),('quantangshi-17481','玉台体十二首 五','權德輿','quantangshi','','卷18','楼上吹箫罢，闺中刺绣阑。
佳期不可见，尽日泪潺潺。','',''),('quantangshi-17482','玉台体十二首 六','權德輿','quantangshi','','卷18','泪尽珊瑚枕，魂销玳瑁牀。
罗衣不忍着，羞见绣鸳鸯。','',''),('quantangshi-17483','玉台体十二首 七','權德輿','quantangshi','','卷18','君去期花时，花时君不至。
檐前双燕飞，落妾相思泪。','',''),('quantangshi-17484','玉台体十二首 八','權德輿','quantangshi','','卷18','空闺灭烛后，罗幌独眠时。
泪尽肠欲断，心知人不知。','',''),('quantangshi-17485','玉台体十二首 九','權德輿','quantangshi','','卷18','秋风一夜至，吹尽后庭花。
莫作经时别，西邻是宋家。','',''),('quantangshi-17486','玉台体十二首 十','權德輿','quantangshi','','卷18','独自披衣坐，更深月露寒。
隔帘肠欲断，争敢下堦看。','',''),('quantangshi-17487','玉台体十二首 十一','權德輿','quantangshi','','卷18','昨夜裙带解，今朝蟢子飞。
铅华不可弃，莫是藁砧归。','',''),('quantangshi-17488','玉台体十二首 十二','權德輿','quantangshi','','卷18','万里行人至，深闺夜未眠。
双眉灯下埽，不待镜台前。','',''),('quantangshi-17489','赠友人','權德輿','quantangshi','','卷18','知向巫山逢日暮，轻袿玉佩暂淹留。
晓随云雨归何处，还是襄王梦觉愁。','',''),('quantangshi-17490','舟行见月','權德輿','quantangshi','','卷18','月入孤舟夜半晴，寥寥霜雁两三声。
洞房烛影在何处，欲寄相思梦不成。','',''),('quantangshi-17491','杂兴五首 一','權德輿','quantangshi','','卷18','丛鬓愁眉时势新，初笄绝代北方人。
一颦一笑千金重，肯似成都夜失身。','',''),('quantangshi-17492','杂兴五首 二','權德輿','quantangshi','','卷18','乍听丝声似竹声，又疑丹穴九雏惊。
金波露洗净于昼，寂寞不堪深夜情。','',''),('quantangshi-17493','杂兴五首 三','權德輿','quantangshi','','卷18','琥珀尊开月暎帘，调弦理曲指纤纤。
含羞敛态劝君住，更奏新声刮骨盐。','',''),('quantangshi-17494','杂兴五首 四','權德輿','quantangshi','','卷18','乳燕双飞莺乱啼，百花如绣照深闺。
新妆对镜知无比，微笑时时出瓠犀。','',''),('quantangshi-17495','杂兴五首 五','權德輿','quantangshi','','卷18','巫山云雨洛川神，珠襻香腰稳称身。
惆怅妆成君不见，含情起立问傍人。','',''),('quantangshi-17496','秖役江西路上以诗代书寄内','權德輿','quantangshi','','卷18','辛苦事行役，风波倦晨暮。
摇摇结遐心，靡靡即长路。
别来如昨日，每见缺蟾兔。
潮信催客帆，春光变江树。
宦游岂云惬，归梦无复数。
愧非超旷姿，循此局促步。
笑言思暇日，规劝多远度。
鹑服我久安，荆钗君所慕。
伊予多昧理，初不涉世务。
适因拥肿材，成此懒慢趣。
一身常抱病，不复理章句。
胸中无町畦，与物且多忤。
既非大川檝，则守南山雾。
胡为出处间，徒使名利污。
羁孤望予禄，孩穉待我哺。
未能即忘怀，恨恨以此故。
终当税鞿鞅，岂待毕婚娶。
如何久人寰，俛仰学举措。
衡茅去迢遰，水陆两驰骛。
晰晰窥晓星，涂涂践朝露。
静闻田鹤起，远见沙𩾨聚。
怪石不易跻，急湍那可溯。
渔商闻远岸，烟火明古渡。
下碇夜已深，上崎波不驻。
畏途信非一，离念纷难具。
枕席有余清，壶觞无与晤。
南方出兰桂，归日自分付。
北窗留琴书，无乃委童孺。
春江足鱼雁，彼此勤尺素。
早晚到中闺，怡然两相顾。','',''),('quantangshi-17497','夜泊有怀','權德輿','quantangshi','','卷18','栖鸟向前林，暝色生寒芜。
孤舟去不息，众感非一途。
川程方浩淼，离思方郁纡。
转枕眼未熟，拥衾泪已濡。
窘然风水上，寝食疲朝晡。
心想洞房夜，知君还向隅。','',''),('quantangshi-17498','自桐庐如兰溪有寄','權德輿','quantangshi','','卷18','东南江路旧知名，惆怅春深又独行。
新妇山头云半敛，女儿滩上月初明。
风前荡扬双飞蝶，花里间关百啭莺。
满目归心何处说，欹眠搔首不胜情。','',''),('quantangshi-17499','相思树','權德輿','quantangshi','','卷18','家寄江东远，身对江西春。
空见相思树，不见相思人。','',''),('quantangshi-17500','石楠树','權德輿','quantangshi','','卷18','石楠红叶透帘春，忆得妆成下锦茵。
试折一枝含万恨，分明说向梦中人。','',''),('quantangshi-17501','斗子滩','權德輿','quantangshi','','卷18','斗子滩头夜已深，月华偏照此时心。
春江风水连天阔，归梦悠扬何处寻。','',''),('quantangshi-17502','黄蘖馆','權德輿','quantangshi','','卷18','驱车振楫越山川，候晓通宵冒烟雨。
青枫浦上魂已销，黄蘖馆前心自苦。','',''),('quantangshi-17503','清明日次弋阳','權德輿','quantangshi','','卷18','自叹清明在远乡，桐花覆水葛溪长。
家人定是持新火，点作孤灯照洞房。','',''),('quantangshi-17504','中书夜直寄赠','權德輿','quantangshi','','卷18','通籍在金闺，怀君百虑迷。
迢迢五夜永，脉脉两心齐。
步履疲青琐，开缄倦紫泥。
不堪风雨夜，转枕忆鸿妻。','',''),('quantangshi-17505','病中寓直代书题寄','權德輿','quantangshi','','卷18','愚夫何所任，多病感君深。
自谓青春壮，宁知白发侵。
寝兴劳善祝，疎懒愧良箴。
寂寞闻宫漏，那堪直夜心。','',''),('quantangshi-17506','端午日礼部宿斋有衣服彩结之贶以诗还答','權德輿','quantangshi','','卷18','良辰当五日，偕老祝千年。
彩缕同心丽，轻裾暎体鲜。
寂寥斋画省，欵曲擘香牋。
更想传觞处，孙孩徧目前。','',''),('quantangshi-17507','酬九日','權德輿','quantangshi','','卷18','重九共游娱，秋光景气殊。
他时头似雪，还对插茱萸。','',''),('quantangshi-17508','和九日从杨氏姊游','權德輿','quantangshi','','卷18','秋光风露天，令节庆初筵。
易象家人吉，闺门女士贤。
招邀菊酒会，属和柳花篇。
今日同心赏，全胜落帽年。','',''),('quantangshi-17509','上巳日贡院考杂文不遂赴九华观祓禊之会以二绝句申赠 一','權德輿','quantangshi','','卷18','三日韶光处处新，九华仙洞七香轮。
老夫留滞何由徃，珉玉相和正遶身。','',''),('quantangshi-17510','上巳日贡院考杂文不遂赴九华观祓禊之会以二绝句申赠 二','權德輿','quantangshi','','卷18','禊饮寻春兴有余，深情婉婉见双鱼。
同心齐体如身到，临水烦君便祓除。','',''),('quantangshi-17511','和九华观见怀贡院八韵','權德輿','quantangshi','','卷18','上巳好风景，仙家足芳菲。
地殊兰亭会，人似山阴归。
丹竈缀珠掩，白云岩迳微。
真宫集女士，虚室涵春辉。
拘限心杳杳，欢言望依依。
滞兹文墨职，坐与琴觞违。
丽曲涤烦虚，幽缄发清机。
支颐一吟想，恨不双翻飞。','',''),('quantangshi-17512','桃源篇','權德輿','quantangshi','','卷18','小年尝读桃源记，忽覩良工施绘事。
岩迳初欣缭绕通，溪风转觉芬芳异。
一路鲜云杂彩霞，渔舟远远逐桃花。
渐入空蒙迷岛道，宁知掩映有人家。
庞眉秀骨争迎客，凿井耕田人世隔。
不知汉代有衣冠，犹说秦家变阡陌。
石髓云英甘且香，仙翁留饭出青囊。
相逢自是松乔侣，良会应殊刘阮郎。
内子闲吟倚瑶瑟，翫此沈沈销永日。
忽闻丽曲金玉声，便使老夫思阁笔。','',''),('quantangshi-17513','新月与儿女夜坐听琴举酒','權德輿','quantangshi','','卷18','泥泥露凝叶，骚骚风入林。
以兹皓月圆，不厌良夜深。
列坐屏轻箑，放怀弦素琴。
儿女各冠笄，孙孩遶衣襟。
乃知大隐趣，宛若沧洲心。
方结偕老期，岂惮华发侵。
笑语向兰室，风流传玉音。
愧君袖中字，价重双南金。','',''),('quantangshi-17514','七夕','權德輿','quantangshi','','卷18','今日云軿渡鹊桥，应非脉脉与迢迢。
家人竞喜开妆镜，月下穿针拜九霄。','',''),('quantangshi-17515','县君赴兴庆宫朝贺载之奉行册礼因书即事','權德輿','quantangshi','','卷18','合卺交欢二十年，今朝比翼共朝天。
风传漏刻香车度，日照旌旗彩仗鲜。
顾我华簪鸣玉佩，看君盛服耀金钿。
相期偕老宜家处，鹤发鱼轩更可怜。','',''),('quantangshi-17516','元和元年蒙恩封成纪县伯时室中封安喜县君感庆兼怀聊申贺赠','權德輿','quantangshi','','卷18','启土封成纪，宜家县安喜。
同欣井赋开，共受闺门祉。
珩璜联采组，琴瑟谐宫徴。
更待悬车时，与君欢暮齿。','',''),('quantangshi-17517','河南崔尹即安喜从兄宜于室家四十余岁一昨寓书病传永写告身既枉善祝因成绝句','權德輿','quantangshi','','卷18','五色金光鸾凤飞，三川墨妙巧相辉。
尊崇善祝今如此，共待曾玄捧翟衣。','',''),('quantangshi-17518','奉使丰陵职司卤簿通宵涉路因寄内','權德輿','quantangshi','','卷18','彩仗列森森，行宫夜漏深。
殳鋋方启路，钲鼓正交音。
曙月思兰室，前山辨谷林。
家人念行役，应见此时心。','',''),('quantangshi-17519','酬南园新亭宴会璩新第慰庆之作时任宾客','權德輿','quantangshi','','卷18','南宫烟景浓，平视中南峯。
官闲似休沐，尽室来相从。
日抱汉阴瓮，或成蝴蝶梦。
树老欲连云，竹深疑入洞。
欢言交羽觞，列坐俨成行。
歌吟不能去，待此明月光。
好逑蕴明识，内顾多慙色。
不厌梁鸿贫，常讥伯宗直。
予壻信时英，谏垣金玉声。
男儿才弱冠，射策幸成名。
偃放斯自足，翛然去营欲。
散木固无堪，虚舟常任触。
大隐本吾心，喜君流好音。
相期悬车岁，此地即中林。','',''),('quantangshi-17520','七夕见与诸孙题乞巧文','權德輿','quantangshi','','卷18','外孙争乞巧，内子共题文。
隐暎花匳对，参差绮席分。
鹊桥临片月，河鼓掩轻云。
羡此婴儿辈，欢呼彻曙闻。','',''),('quantangshi-17521','太常寺宿斋有寄','權德輿','quantangshi','','卷18','转枕挑灯候晓鸡，相君应叹太常妻。
长年多病偏相忆，不遣归时醉似泥。','',''),('quantangshi-17522','朝回阅乐寄绝句','權德輿','quantangshi','','卷18','子城风暖百花初，楼上龟兹引导车。
曲罢卿卿理驺驭，细君相望意何如。','',''),('quantangshi-17523','中书宿斋有寄','權德輿','quantangshi','','卷18','铜壶漏滴斗阑干，泛滟金波照露盘。
遥想洞房眠正熟，不堪深夜凤池寒。','',''),('quantangshi-17524','中书送勅赐斋馔戏酬','權德輿','quantangshi','','卷18','常日每齐眉，今朝共解颐。
遥知大官膳，应与众雏嬉。','',''),('quantangshi-17525','勅赐长寿酒因口号以赠','權德輿','quantangshi','','卷18','恩霑长寿酒，归遗同心人。
满酌共君醉，一杯千万春。','',''),('quantangshi-17526','湖南观察使故相国袁公挽歌二首 一','權德輿','quantangshi','','卷18','五驱龙虎节，一入凤皇池。
令尹自无喜，羊公人不疑。
天归京兆日，叶下洞庭时。
湘水秋风至，凄凉吹素旗。','',''),('quantangshi-17527','湖南观察使故相国袁公挽歌二首 二','權德輿','quantangshi','','卷18','丹旐发江臯，人悲雁亦号。
湘南罢亥市，汉上改词曹。
表墓双碑立，尊名一字襃。
常闻平楚狱，为报里门高。','',''),('quantangshi-17528','玉山岭上作','權德輿','quantangshi','','卷18','悠悠驱匹马，征路上连冈。
晚翠深云窦，寒苔净石梁。
荻花偏似雪，枫叶不禁霜。
愁见前程远，空郊下夕阳。','',''),('quantangshi-17529','题邵端公林亭','權德輿','quantangshi','','卷18','春光何处好，柱史有林塘。
莺啭风初暖，花开日欲长。
凿池通野水，扫径阅新芳。
更置盈尊酒，时时醉楚狂。','',''),('quantangshi-17530','酬裴杰秀才新樱桃','權德輿','quantangshi','','卷18','新果真琼液，来应宴紫兰。
圆疑窃龙颔，色已夺鸡冠。
远火微微辨，残星隐隐看。
茂先知味易，曼倩恨偷难。
忍用烹騂骆，从将翫玉盘。
流年如可驻，何必九华丹。','',''),('quantangshi-17531','次滕老庄','權德輿','quantangshi','','卷18','征途无旅馆，当昼喜逢君。
羸病仍留客，朝朝扫白云。','',''),('quantangshi-17532','宿严陵','權德輿','quantangshi','','卷18','身羁从事驱征传，江入新安泛暮涛。
今夜子陵滩下泊，自慙相去九牛毛。','',''),('quantangshi-17533','题云师山房','權德輿','quantangshi','','卷18','云公兰若深山里，月明松殿微风起。
试问空门清净心，莲花不着秋潭水。','',''),('quantangshi-17534','栖霞寺云居室','權德輿','quantangshi','','卷18','一径萦纡至此穷，山僧盥漱白云中。
闲吟定后更何事，石上松枝常有风。','',''),('quantangshi-17535','舟行夜泊','權德輿','quantangshi','','卷18','萧萧落叶送残秋，寂寞寒波急暝流。
今夜不知何处泊，断猨晴月引孤舟。','',''),('quantangshi-17536','发硖石路上却寄内','權德輿','quantangshi','','卷18','莎栅东行五谷深，千峯万壑雨沈沈。
细君几日路经此，应见悲翁相望心。','',''),('quantangshi-17537','冬至宿斋时郡君南内朝谒因寄','權德輿','quantangshi','','卷18','清斋独向丘园拜，盛服想君兴庆朝。
明日一阳生百福，不辞相望阻寒宵。','',''),('quantangshi-17538','和河南罗主簿送校书兄归江南','權德輿','quantangshi','','卷18','兄弟泣殊方，天涯指故乡。
断云无定处，归雁不成行。
草莽人烟少，风波水驿长。
上虞亲渤澥，东楚隔潇湘。
古戍阴传火，寒芜晓带霜。
海门潮滟滟，沙岸荻苍苍。
京辇辞芸阁，衡方忆草堂。
知君始宁隐，还缉旧荷裳。','',''),('quantangshi-17539','与故人夜坐道旧','權德輿','quantangshi','','卷18','笑语欢今夕，烟霞怆昔游。
清羸还对月，迟暮更逢秋。
胜理方自得，浮名不在求。
终当制初服，相与卧林丘。','',''),('quantangshi-17540','句','權德輿','quantangshi','','卷18','耒水波纹细，湘江竹叶轻。
古时楼上清明夜，月照楼前撩乱花。
今日成阴复成子，可怜春尽未归家。
新妇矶头云半歛，女儿滩畔月初明。
回合千峰里，晴光似画图。
征车随反照，候吏暎白云。','',''),('quantangshi-17541','奉酬礼部阁老转韵离合见赠','張薦','quantangshi','','卷18','移居既同里，多幸陪君子。
弘雅重当朝，弓旌早见招。
植根琼林圃，直夜金闺步。
劝深子玉铭，力竞相如赋。
间阔向春闱，日复想光仪。
格言信难继，木石强为词。','',''),('quantangshi-17542','和潘孟阳春日雪回文绝句','張薦','quantangshi','','卷18','迟迟日气暖，漫漫雪天春。
知君欲醉饮，思见此交亲。','',''),('quantangshi-17543','享文恭太子庙乐章','張薦','quantangshi','','卷18','三献具举，九旗将旋。
追劳表德，罢享宾天。
风引仙管，堂虚画筵。
芳馨常在，瞻望悠然。','',''),('quantangshi-17544','礼部权侍郎阁老史馆张秘监阁老有离合酬赠之什宿直吟翫聊继此章','崔邠','quantangshi','','卷18','脉脉羡佳期，月夜吟丽词。
谏垣则随步，东观方承顾。
林雪消艳阳，简册漏华光。
坐更芝兰室，千载各芬芳。
节苦文俱盛，即时人竝命。
翩翻紫霄中，羽翮相辉映。','',''),('quantangshi-17545','享文恭太子庙乐章','崔邠','quantangshi','','卷18','醴齐泛罇彝，轩县动干戚。
入室僾如在，升阶虔所历。
旧疾合威容，定利舒皦泽。
方崇庙貌礼，永被君恩锡。','',''),('quantangshi-17546','和权载之离合诗','楊於陵','quantangshi','','卷18','校德尽圭璋，才臣时所扬。
放情寄文律，方茂经邦术。
王猷符发挥，十载契心期。
昼游有嘉话，书法无隐辞。
信兹酧和美，言与芝兰比。
昨来恣吟绎，日觉祛蒙鄙。','',''),('quantangshi-17547','郡斋有紫薇双本自朱明接于徂暑其花芳馥数旬犹茂庭宇之内逈无其伦予嘉其美而能久因诗纪述','楊於陵','quantangshi','','卷18','晏朝受明命，继夏走天衢。
逮兹三伏候，息驾万里途。
省躬既局蹐，结思多烦纡。
簿领幸无事，宴休谁与娱。
内斋有嘉树，双植分庭隅。
绿叶下成幄，紫花纷若铺。
摛霞晚舒艳，凝露朝垂珠。
炎沴昼方铄，幽姿闲且都。
夭桃固难匹，芍药宁为徒。
懿此时节久，讵同光景驱。
陶甄试一致，品汇乃散殊。
濯质非受彩，无心那夺朱。
粤予负羁絷，留赏益踟蹰。
通夕靡云倦，西南山月孤。','',''),('quantangshi-17548','赠毛仙翁','楊於陵','quantangshi','','卷18','先生赤松侣，混俗游人间。
昆阆无穷路，何时下故山。
千年犹孺质，秘术救尘寰。
莫便冲天去，云雷不可攀。','',''),('quantangshi-17549','答权载之离合诗','許孟容','quantangshi','','卷18','史才司秘府，文哲今超古。
亦有擅风骚，六联文墨曹。
圣贤三代意，工艺千金字。
化识从臣谣，人推仙阁吏。
如登昆阆时，口诵灵真词。
孙简下威凤，系霜琼玉枝。','',''),('quantangshi-17550','奉和武相公春晓闻莺','許孟容','quantangshi','','卷18','碧树当窗啼晓莺，间关入梦听难成。
千回万啭尽愁思，疑是血魂哀困声。','',''),('quantangshi-17551','享文恭太子庙乐章','許孟容','quantangshi','','卷18','觞牢具品，管弦有节。
祝道寅恭，神仪昭晰。
桐圭早贵，象辂追设。
罄达乐成，降歆丰洁。','',''),('quantangshi-17552','和权载之离合诗','馮伉','quantangshi','','卷18','车马退朝后，聿怀在文友。
动词宗伯雄，重美良史功。
亦曾吟鲍谢，二妙尤增价。
雨霜鸿唳天，匝树鸟鸣夜。
覃思各纵横，早擅希代名。
息心欲焚砚，自腼陪羣英。','',''),('quantangshi-17553','享文恭太子庙乐章二首 一','馮伉','quantangshi','','卷18','撰日瞻景，诚陈乐张。
礼容秩秩，羽舞煌煌。
肃将涤濯，祗荐芬芳。
永锡繁祉，思深享尝。','',''),('quantangshi-17554','享文恭太子庙乐章二首 二','馮伉','quantangshi','','卷18','干旄羽龠相亏蔽，一进一退殊行缀。
昔献三雍盛礼容，今陈六佾崇仪制。','',''),('quantangshi-17555','和权载之离合诗','潘孟陽','quantangshi','','卷18','咏歌有离合，永夜观酬答。
笥中操彩牋，竹简何足编。
意深俱妙绝，心契交情结。
计彼官接联，言初竝清切。
翔集本相随，羽仪良在斯。
烟云竞文藻，因喜翫新诗。','',''),('quantangshi-17556','春日雪以回文绝句呈张荐权德舆','潘孟陽','quantangshi','','卷18','春梅杂落雪，发树几花开。
真须尽兴饮，仁里愿同来。','',''),('quantangshi-17557','元日和布泽','潘孟陽','quantangshi','','卷18','至德生成泰，咸欢照育恩。
流辉霑万物，布泽在三元。
北阕祥云逈，东方嘉气繁。
青阳初应律，苍玉正临轩。
恩洽因时令，风和比化原。
自慙同草木，无以答干坤。','',''),('quantangshi-17558','和权载之离合诗','武少儀','quantangshi','','卷18','少年慕时彦，小悟文多变。
木铎比羣英，八方流德声。
雷陈美交契，雨雪音尘继。
恩顾各飞翔，因诗覩瑰丽。
傅野绝遗贤，人希有盛迁。
早钦风与雅，日咏赠酬篇。','',''),('quantangshi-17559','诸葛丞相庙','武少儀','quantangshi','','卷18','执简焚香入庙门，武侯神象俨如存。
因机定蜀延衰汉，以计连吴振弱孙。
欲尽智能倾僭盗，善持忠节转庸昏。
宣王请战贻巾帼，始见才吞亦气吞。','',''),('quantangshi-17560','享太庙乐章','段文昌','quantangshi','','卷18','肃肃清庙，登显至德。
泽周八荒，兵定四极。
生物咸遂，羣盗灭息。
明圣钦承，子孙千亿。','',''),('quantangshi-17561','题武担寺西台','段文昌','quantangshi','','卷18','秋天如镜空，楼阁尽玲珑。
水暗余霞外，山明落照中。
鸟行看渐远，松韵听难穷。
今日登临意，多欢语笑同。','',''),('quantangshi-17562','晚夏登张仪楼呈院中诸公','段文昌','quantangshi','','卷18','重楼窗户开，四望敛烟埃。
远岫林端出，清波城下回。
乍疑蝉韵促，稍觉雪风来。
并起乡关思，销忧在酒杯。','',''),('quantangshi-17563','还别业寻龙华山寺广宣上人','段文昌','quantangshi','','卷18','十里惟闻松桂风，江山忽转见龙宫。
正与休师方话旧，风烟几度入楼中。','',''),('quantangshi-17564','奉陪段相公晚夏登张仪楼','姚向','quantangshi','','卷18','秦相架羣材，登临契上台。
查从银汉落，江自雪山来。
俪曲亲流火，凌风洽小杯。
帝乡如在目，欲下尽裴回。','',''),('quantangshi-17565','和段相公登武担寺西台','姚向','quantangshi','','卷18','开阁锦城中，余闲访梵宫。
九层连昼景，万象写秋空。
天半将身到，江长与海通。
提携出尘土，曾是穆清风。','',''),('quantangshi-17566','和段相公登武担寺西台','溫會','quantangshi','','卷18','桑台烟树中，台榭造云空。
眺听逢秋兴，篇辞变国风。
坐愁高鸟起，笑指远人同。
始愧才情薄，跻攀继韵穷。','',''),('quantangshi-17567','奉陪段相公晚夏登张仪楼','溫會','quantangshi','','卷18','危轩重叠开，访古上裴回。
有舌嗟秦策，飞梁驾楚材。
云霄随凤到，物象为诗来。
欲和关山意，巴歌调更哀。','',''),('quantangshi-17568','和段相公登武担寺西台','李敬伯','quantangshi','','卷18','台上起凉风，乘闲览岁功。
自随台席贵，尽许羽觞同。
楼殿斜晖照，江山极望通。
赋诗思共乐，俱得咏时丰。','',''),('quantangshi-17569','奉陪段相公晚夏登张仪楼','李敬伯','quantangshi','','卷18','层屋架城隈，宾筵此日开。
文锋摧八阵，星分应三台。
望雪烦襟释，当欢远思来。
披云霄汉近，蹔觉出尘埃。','',''),('quantangshi-17570','奉陪段相公晚夏登张仪楼','姚康','quantangshi','','卷18','登览值晴开，诗从野思来。
蜀川新草木，秦日旧楼台。
池景摇中座，山光接上台。
近秋宜晚景，极目断浮埃。','',''),('quantangshi-17571','和段相公登武担寺西台','姚康','quantangshi','','卷18','松迳引清风，登台古寺中。
江平沙岸白，日下锦川红。
疎树山根净，深云鸟迹穷。
自惭陪末席，便与九霄通。','',''),('quantangshi-17572','礼部试早春残雪','姚康','quantangshi','','卷18','微暖春潜至，轻明雪尚残。
银铺光渐湿，圭破色仍寒。
无柳花常在，非秋露正团。
素光浮转薄，皓质驻应难。
幸得依阴处，偏宜带月看。
玉尘销欲尽，穷巷起袁安。','',''),('quantangshi-17573','赋得巨鱼纵大壑','姚康','quantangshi','','卷18','水府乘闲望，圆波息跃鱼。
从来暴泥久，今日脱泉初。
得志宁相忌，无心任宛如。
龙门应可度，鲛室岂常居。
掉尾方穷乐，游鳞每自舒。
乘流千里去，风力藉吹嘘。','',''),('quantangshi-17574','早春对雨','羊士諤','quantangshi','','卷18','南馆垂杨早，东风细雨频。
轻寒消玉斝，幽赏滞朱轮。
千里巴江守，三年故国春。
含情非迟客，悬榻但生尘。','',''),('quantangshi-17575','永宁小园即事','羊士諤','quantangshi','','卷18','萧条梧竹下，秋物映园庐。
宿雨方然桂，朝饥更摘蔬。
阴苔生白石，时菊覆清渠。
陈力当何事，忘言愧道书。','',''),('quantangshi-17576','台中遇直晨览萧侍御壁画山水','羊士諤','quantangshi','','卷18','虫思庭莎白露天，微风吹竹晓凄然。
今来始悟朝回客，暗写归心向石泉。','',''),('quantangshi-17577','过三乡望女几山早岁有卜筑之志','羊士諤','quantangshi','','卷18','女几山头春雪消，路傍仙杏发柔条。
心期欲去知何日，惆怅回车上野桥。','',''),('quantangshi-17578','和李都官郎中经宫人斜','羊士諤','quantangshi','','卷18','翡翠无穷掩夜泉，犹疑一半作神仙。
秋来还照长门月，珠露寒花是野田。','',''),('quantangshi-17579','山阁闻笛','羊士諤','quantangshi','','卷18','临风玉管吹参差，山坞春深日又迟。
李白桃红满城郭，马融闲卧望京师。','',''),('quantangshi-17580','登楼','羊士諤','quantangshi','','卷18','槐柳萧疎遶郡城，夜添山雨作江声。
秋风南陌无车马，独上高楼故国情。','',''),('quantangshi-17581','忆江南旧游二首 一','羊士諤','quantangshi','','卷18','山阴道上桂花初，王谢风流满晋书。
曾作江南步从事，秋来还复忆鲈鱼。','',''),('quantangshi-17582','忆江南旧游二首 二','羊士諤','quantangshi','','卷18','曲水三春弄彩毫，樟亭八月又观涛。
金罍几醉乌程酒，鹤舫闲吟把蟹螯。','',''),('quantangshi-17583','郡中即事三首 一','羊士諤','quantangshi','','卷18','晓风山郭雁飞初，霜拂回塘水榭虚。
鼓角清明如战垒，梧桐摇落似贫居。
青门远忆中人产，白首闲看太史书。
城下秋江寒见底，宾筵莫讶食无鱼。','',''),('quantangshi-17584','郡中即事三首 二','羊士諤','quantangshi','','卷18','红衣落尽暗香残，叶上秋光白露寒。
越女含情已无限，莫敎长袖倚阑干。','',''),('quantangshi-17585','郡中即事三首 三','羊士諤','quantangshi','','卷18','登临何事见琼枝，白露黄花自绕篱。
惟有楼中好山色，稻畦残水入秋池。','',''),('quantangshi-17586','野望二首 一','羊士諤','quantangshi','','卷18','萋萋麦陇杏花风，好是行春野望中。
日暮不辞停五马，鸳鸯飞去绿江空。','',''),('quantangshi-17587','野望二首 二','羊士諤','quantangshi','','卷18','忘怀不使海鸥疑，水映桃花酒满巵。
亭上一声歌白苎，野人归棹亦行迟。','',''),('quantangshi-17588','游西山兰若','羊士諤','quantangshi','','卷18','路傍垂柳古今情，春草春泉咽又生。
借问山僧好风景，看花携酒几人行。','',''),('quantangshi-17589','泛舟入后溪 一','羊士諤','quantangshi','','卷18','东风朝日破轻岚，仙棹初移酒未酣。
玉笛闲吹折杨柳，春风无事傍鱼潭。','',''),('quantangshi-17590','泛舟入后溪 二','羊士諤','quantangshi','','卷18','雨余芳草净沙尘，水绿滩平一带春。
唯有啼鹃似留客，桃花深处更无人。','',''),('quantangshi-17591','看花','羊士諤','quantangshi','','卷18','一到花间一忘归，玉杯瑶瑟减光辉。
歌筵更覆青油幕，忽似朝云瑞雪飞。','',''),('quantangshi-17592','春望','羊士諤','quantangshi','','卷18','莫问华簪发已斑，归心满目是青山。
独上层城倚危槛，柳营春尽马嘶闲。','',''),('quantangshi-17593','寄江陵韩少尹','羊士諤','quantangshi','','卷18','别来玄鬓共成霜，云起无心出帝乡。
蜀国鱼笺数行字，忆君秋梦过南塘。','',''),('quantangshi-17594','贺州宴行营回将','羊士諤','quantangshi','','卷18','九劒盈庭酒满巵，戍人归日及瓜时。
元戎静镇无边事，遣向营中偃画旗。','',''),('quantangshi-17595','游郭驸马大安山池','羊士諤','quantangshi','','卷18','马嘶芳草自淹留，别馆何人属细侯。
仙杏破颜逢醉客，彩鸳飞去避行舟。
洞箫日暖移宾榻，垂柳风多掩妓楼。
坐阅清晖不知暮，烟横北渚水悠悠。','',''),('quantangshi-17596','故萧尚书瘿柏斋前玉蘂树与王起居吏部孟员外同赏','羊士諤','quantangshi','','卷18','柏寝闭何时，瑶华自满枝。
天清凝积素，风暖动芬丝。
留步苍苔暗，停觞白日迟。
因吟茂陵草，幽赏待妍词。','',''),('quantangshi-17597','和武相早朝中书候传点书怀奉呈','羊士諤','quantangshi','','卷18','殿省祕清晓，夔龙升紫微。
星辰拱帝座，劒履翊天机。
耿耿金波缺，沉沉玉漏稀。
彩笺蹲鸷兽，画扇列名翚。
志业丹青重，恩华雨露霏。
三台昭建极，一德庆垂衣。
昌运瞻文敎，雄图本武威。
殊勋如带远，佳气似烟非。
抗节衷无隐，同心尚弼违。
良哉致君日，维岳有光辉。','',''),('quantangshi-17598','和萧侍御监祭白帝城西村寺斋沐览镜有怀吏部孟员外并见赠','羊士諤','quantangshi','','卷18','晚沐金仙宇，迎秋白帝祠。
轩裳烦吏职，风物动心期。
清镜开尘匣，华簪指发丝。
南宫有高步，岁晏岂磷缁。','',''),('quantangshi-17599','送张郎中副使自南省赴凤翔府幕','羊士諤','quantangshi','','卷18','仙郎佐氏谋，廷议宠元侯。
城郭须来贡，河隍亦顺流。
亚夫高垒静，充国大田秋。
当奋燕然笔，铭功向陇头。','',''),('quantangshi-17600','和窦吏部雪中寓直','羊士諤','quantangshi','','卷18','瑞花飘朔雪，灏气满南宫。
迢遰层城掩，徘徊午夜中。
金闺通籍恨，银烛直庐空。
谁问乌台客，家山忆桂丛。','',''),('quantangshi-17601','小园春至偶呈吏部窦郎中','羊士諤','quantangshi','','卷18','松筱虽苦节，冰霜惨其间。
欣然发佳色，如喜东风还。
幽抱想前躅，冥鸿度南山。
春台一以眺，达士亦解颜。
偃息非老圃，沉吟閟玄关。
驰晖忽复失，壮气不得闲。
君子当济物，丹梯谁共攀。
心期自有约，去扫苍苔斑。','',''),('quantangshi-17602','酬吏部窦郎中直夜见寄','羊士諤','quantangshi','','卷18','解巾侍云陛，三命早为郎。
复以雕龙彩，旋归振鹭行。
玉书期养素，金印已怀黄。
兹夕南宫咏，遐情愧不忘。','',''),('quantangshi-17603','永宁里园亭休沐怅然成咏','羊士諤','quantangshi','','卷18','云景含初夏，休归曲陌深。
幽帘宜永日，珍树始清阴。
迟客唯长簟，忘言有匣琴。
画披灵物态，书见古人心。
芳草多留步，鲜飙自满襟。
劳形非立事，潇洒愧头簪。','',''),('quantangshi-17604','登乐游原寄司封孟郎中卢补阙','羊士諤','quantangshi','','卷18','爽节时清眺，秋怀怅独过。
神臯值宿雨，曲水已增波。
白鸟凌风迥，红蕖濯露多。
伊川有归思，君子复如何。','',''),('quantangshi-17605','干元初严黄门自京兆少尹贬牧巴郡以长才英气固多暇日每游郡之东山山侧精舍有盘石细泉䟽为浮杯之胜苔深树老苍然遗躅士谔谬因出守得继兹赏乃赋诗十四韵刻于石壁','羊士諤','quantangshi','','卷18','石座双峰古，云泉九曲深。
寂寥疏凿意，芜没岁时侵。
绕席流还壅，浮杯咽复沉。
追怀王谢侣，更似会稽岑谁谓天池翼，相期宅畔吟。
光辉轻尺璧，然诺重黄金。
几醉东山妓，长悬北阙心。
蕙兰留杂佩，桃李想华簪。
闭阁余何事，鸣驺亦屡寻。
轩裳遵往辙，风景憩中林。
横吹多凄调，安歌送好音。
初筵方侧弁，故老忽沾襟。
盛世当弘济，平生谅所钦。
无能愧陈力，惆怅拂瑶琴。','',''),('quantangshi-17606','闲斋示一二道者','羊士諤','quantangshi','','卷18','幽兰谁复奏，闲匣以端忧。
知止慙先觉，归欤想故侯。
山蝉铃阁晚，江雨麦田秋。
唯有空门学，相期老一丘。','',''),('quantangshi-17607','南池荷花','羊士諤','quantangshi','','卷18','蝉噪城沟水，芙蓉忽已繁。
红花迷越艳，芳意过湘沅。
湛露宜清暑，披香正满轩。
朝朝秖自赏，穠李亦何言。','',''),('quantangshi-17608','郡中翫月寄江南李少尹虞部孟员外三首 一','羊士諤','quantangshi','','卷18','月满自高丘，江通无狭流。
轩窗开到晓，风物坐含秋。
鹊警银河断，蛩悲翠幕幽。
清光望不极，耿耿下西楼。','',''),('quantangshi-17609','郡中翫月寄江南李少尹虞部孟员外三首 二','羊士諤','quantangshi','','卷18','桂华临洛浦，如挹李膺仙。
兹夕披云望，还吟掷地篇。
凤池分直夜，牛渚泛舟年。
会是风流赏，惟君内史贤。','',''),('quantangshi-17610','郡中翫月寄江南李少尹虞部孟员外三首 三','羊士諤','quantangshi','','卷18','圆景旷佳宾，徘徊夜漏频。
金波徒泛酒，瑶瑟已生尘。
露白移长簟，风清挂幅巾。
西园旧才子，想见洛阳人。','',''),('quantangshi-17611','城隍庙赛雨二首 一','羊士諤','quantangshi','','卷18','零雨慰斯人，斋心荐绿苹。
山风箫鼓响，如祭敬亭神。','',''),('quantangshi-17612','城隍庙赛雨二首 二','羊士諤','quantangshi','','卷18','积润通千里，推诚奠一巵。
回飙经画壁，忽似偃云旗。','',''),('quantangshi-17613','郡楼晴望二首 一','羊士諤','quantangshi','','卷18','霁色朝云尽，亭臯露亦曦。
褰开临曲槛，萧瑟换轻衣。
地远秦人望，天晴社燕飞。
无功慙岁晚，唯念故山归。','',''),('quantangshi-17614','郡楼晴望二首 二','羊士諤','quantangshi','','卷18','一雨晴山郭，惊秋碧树风。
兰巵谁与荐，玉斾自无悰。
云景嘶宾雁，岚阴露彩虹。
闲吟嬾闭阁，旦夕郡楼中。','',''),('quantangshi-17615','初移琪树','羊士諤','quantangshi','','卷18','爱此丘中物，烟霜尽日看。
无穷碧云意，更助绿窗寒。','',''),('quantangshi-17616','燕居','羊士諤','quantangshi','','卷18','秋斋膏沐暇，旭日照轩墀。
露重芭蕉叶，香凝橘柚枝。
简书随吏散，宝骑与僧期。
报国得何力，流年已觉衰。','',''),('quantangshi-17617','寄黔府窦中丞','羊士諤','quantangshi','','卷18','汉臣旌节贵，万里护牂牁。
夏月天无暑，秋风水不波。
朝衣蟠艾绶，戎幕偃雕戈。
满岁归龙阙，良哉伫作歌。','',''),('quantangshi-17618','书楼怀古','羊士諤','quantangshi','','卷18','何独文翁化，风流与代深。
泉云无旧辙，骚雅有遗音。
远目穷巴汉，闲情阅古今。
忘言意不极，日暮但横琴。','',''),('quantangshi-17619','九月十日郡楼独酌','羊士諤','quantangshi','','卷18','掾史当授衣，郡中稀物役。
嘉辰怅已失，残菊谁为惜。
棂轩一尊泛，天景洞虚碧。
暮节独赏心，寒江鸣湍石。
归期北州里，旧友东山客。
飘荡云海深，相思桂花白。','',''),('quantangshi-17620','暮秋言怀','羊士諤','quantangshi','','卷18','城隅凝彩画，红树带青山。
迟客金尊晚，谈空玉柄闲。
驰晖三峡水，旅梦百劳关。
非是淮阳薄，丘中只望还。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-17621','题枇杷树','羊士諤','quantangshi','','卷18','珍树寒始花，氛氲九秋月。
佳期若有待，芳意常无绝。
袅袅碧海风，蒙蒙绿枝雪。
急景自余妍，春禽幸流悦。','',''),('quantangshi-17622','上元日紫极宫门观州民然灯张乐','羊士諤','quantangshi','','卷18','山郭通衢隘，瑶坛紫府深。
灯花助春意，舞绶织欢心。
闲似淮阳卧，恭闻乐职吟。
唯将圣明化，聊以达飞沈。','',''),('quantangshi-17623','西郊兰若','羊士諤','quantangshi','','卷18','云天宜北户，塔庙似西方。
林下僧无事，江清日复长。
石泉盈掬冷，山实满枝香。
寂寞传心印，玄言亦已忘。','',''),('quantangshi-17624','在郡三年今秋见白发聊以书事','羊士諤','quantangshi','','卷18','二毛非骑省，朝镜忽秋风。
丝缕寒衣上，霜华旧简中。
承明那足厌，车服愧无功。
日日山城守，淹留岩桂丛。','',''),('quantangshi-17625','郡中端居有怀袁州王员外使君','羊士諤','quantangshi','','卷18','忆作同门友，承明奉直庐。
禁闱人自异，休澣迹非疎。
珥笔金华殿，三朝玉玺书。
恩光荣侍从，文彩应符徐。
青眼真知我，玄谈愧起予。
兰巵招促膝，松砌引长裾。
丽日流莺早，凉天坠露初。
前山临紫阁，曲水眺红蕖。
谁为音尘旷，俄惊岁月除。
风波移故辙，符守忽离居。
济物阴功在，分忧盛业余。
弱翁方大用，延首迟双鱼。','',''),('quantangshi-17626','山寺题壁','羊士諤','quantangshi','','卷18','物外真何事，幽廊步不穷。
一灯心法在，三世影堂空。
山果青苔上，寒蝉落叶中。
归来还闭阁，棠树几秋风。','',''),('quantangshi-17627','暇日适值澄霁江亭游宴','羊士諤','quantangshi','','卷18','碧落风如洗，清光镜不分。
弦歌方对酒，山谷尽无云。
振卧淮阳病，悲秋宋玉文。
今来强携妓，醉舞石榴裙。','',''),('quantangshi-17628','玩槿花','羊士諤','quantangshi','','卷18','何乃诗人兴，妍词属舜华。
风流感异代，窈窕比同车。
凝艳垂清露，惊秋隔绛纱。
蝉鸣复虫思，惆怅竹阴斜。','',''),('quantangshi-17629','郡斋读经','羊士諤','quantangshi','','卷18','壮龄非济物，柔翰误为儒。
及此斋心暇，翛然与道俱。
散材诚独善，正觉岂无徒。
半偈莲生水，幽香桂满炉。
息阴慙蔽芾，讲义得醍醐。
迹似桃源客，身撄竹使符。
华夷参吏事，巴汉混州图。
偃草怀君子，移风念啬夫。
翳桑俄有绩，宿麦复盈租。
圆寂期超诣，凋残幸已苏。
解空囊不智，灭景谷何愚。
几日遵归辙，东菑殆欲芜。','',''),('quantangshi-17630','州民自言巴土冬湿且多阴晦今兹晴朗苦寒霜颇甚故老或异之因示寮吏','羊士諤','quantangshi','','卷18','雨霜以成岁，看旧感前闻。
爱景随朝日，凝阴积暮云。
囗囗囗囗囗，忘言酒暂醺。
囗囗囗囗囗，囗囗囗囗囗。','',''),('quantangshi-17631','斋中有兽皮茵偶成咏','羊士諤','quantangshi','','卷18','逸才岂凡兽，服猛愚人得。
山泽生异姿，蒙戎蔚佳色。
青毡持与藉，重锦裁为饰。
卧阁幸相宜，温然承宴息。','',''),('quantangshi-17632','野夫采鞭于东山偶得元者','羊士諤','quantangshi','','卷18','追风岂无策，持斧有遐想。
凤去留孤根，嵓悬非朽壤。
苔斑自天生，玉节垂云长。
勿谓山之幽，丹梯亦可上。','',''),('quantangshi-17633','守郡累年俄及知命聊以言志','羊士諤','quantangshi','','卷18','南国疑逋客，东山作老夫。
登朝非大隐，出谷是真愚。
气直慙龙劒，心清爱玉壶。
聊持循吏传，早晚囗为徒。','',''),('quantangshi-17634','东渡早梅一树岁华如雪酣赏成咏','羊士諤','quantangshi','','卷18','暇日留囗事，期云亦囗开。
乡心持岁酒，津下赏山梅。
晚实和商鼎，浓香拂寿杯。
唯应招北客，日日踏青来。','',''),('quantangshi-17635','题郡南山光福寺寺即严黄门所置时自给事中京兆少尹出守年三十性乐山水故老云每旬数至后分阃川州门有去思碑即郄拾遗之词也','羊士諤','quantangshi','','卷18','传闻黄阁守，兹地赋长沙。
少壮称时杰，功名惜岁华。
岩廊初建刹，宾从亟鸣笳。
玉帐空严道，甘棠见野花。
碑残犹堕泪，城古自归鸦。
籍籍清风在，怀人谅不遐。','',''),('quantangshi-17636','雨中寒食','羊士諤','quantangshi','','卷18','令节逢烟雨，园亭但掩关。
佳人宿妆薄，芳树彩绳闲。
归思偏消酒，春寒为近山。
花枝不可见，别恨灞陵间。','',''),('quantangshi-17637','晚夏郡中卧疾','羊士諤','quantangshi','','卷18','事外心如寄，虚斋卧更幽。
微风生白羽，畏日隔青油。
用拙怀归去，沉疴畏借留。
东山自有计，蓬鬓莫先秋。','',''),('quantangshi-17638','酬卢司门晚夏过永宁里弊居林亭见寄','羊士諤','quantangshi','','卷18','自叹淮阳卧，谁知去国心。
幽亭来北户，高韵得南金。
苔甃窥泉少，篮舆爱竹深。
风蝉一清暑，应喜脱朝簪。','',''),('quantangshi-17639','山郭风雨朝斋怅然秋思','羊士諤','quantangshi','','卷18','桐竹离披晓，凉风似故园。
惊秋对旭日，感物坐前轩。
江燕飞还尽，山榴落尚繁。
平生信有意，衰久已忘言。','',''),('quantangshi-17640','南馆林塘','羊士諤','quantangshi','','卷18','郡阁山斜对，风烟隔短墙。
清池如写月，珍树尽凌霜。
行乐知无闷，加餐颇自强。
心期空岁晚，鱼意久相忘。','',''),('quantangshi-17641','腊夜对酒','羊士諤','quantangshi','','卷18','琥珀杯中物，琼枝席上人。
乐声方助醉，烛影已含春。
自顾行将老，何辞坐达晨。
传觞称厚德，不问吐车茵。','',''),('quantangshi-17642','池上构小山咏怀','羊士諤','quantangshi','','卷18','玉立出岩石，风清曲囗囗。
偶成聊近意，静对想凝神。
牛渚中流月，兰亭上道春。
古来心可见，寂寞为斯人。','',''),('quantangshi-17643','林塘腊候','羊士諤','quantangshi','','卷18','南国冰霜晚，年华已暗归。
闲招别馆客，远念故山薇。
野艇虚还触，笼禽倦更飞。
忘言亦何事，酣赏步清辉。','',''),('quantangshi-17644','酬礼部崔员外备独永宁里弊居见寄来诗云图书锁尘阁符节守山城','羊士諤','quantangshi','','卷18','守土亲巴俗，腰章囗汉仪。
春行乐职咏，秋感伴牢词。
旧里藏书阁，闲门闭槿篱。
遥慙退朝客，下马独相思。','',''),('quantangshi-17645','梁国惠康公主挽歌词二首 一','羊士諤','quantangshi','','卷18','汤沐成陈迹，山林遂寂寥。
鹊飞应织素，凤起独吹箫。
玉殿中参罢，云軿上汉遥。
皇情非不极，空辍未央朝。','',''),('quantangshi-17646','梁国惠康公主挽歌词二首 二','羊士諤','quantangshi','','卷18','授册荣天使，陈诗感圣恩。
山河启梁国，缟素及于门。
泉向金巵咽，霜来玉树繁。
都人听哀挽，泪尽望寒原。','',''),('quantangshi-17647','南池晨望','羊士諤','quantangshi','','卷18','起来林上月，潇洒故人情。
铃阁人何事，莲塘晓独行。
衣沾竹露爽，茶对石泉清。
鼓吹前贤薄，羣蛙试一鸣。','',''),('quantangshi-17648','林馆避暑','羊士諤','quantangshi','','卷18','池岛清阴里，无人泛酒船。
山蜩金奏响，荷露水精圆。
静胜朝还暮，幽观白已玄。
家林正如此，何事赋归田。','',''),('quantangshi-17649','巴南郡斋雨中偶看长历是日小雪有怀昔年朝谒因成八韵','羊士諤','quantangshi','','卷18','夷落朝云候，王正小雪辰。
缅怀朝紫陌，曾是洒朱轮。
气耿簪裾肃，风严刻漏频。
暗飞金马仗，寒舞玉京尘。
豸角随中宪，龙池列近臣。
蘂珠凝瑞彩，悬圃净华茵。
帝泽千箱庆，天颜万物春。
明廷犹咫尺，高咏愧巴人。','',''),('quantangshi-17650','褒城驿池塘翫月','羊士諤','quantangshi','','卷18','夜长秋始半，圆景丽银河。
北渚清光溢，西山爽气多。
鹤飞闻坠露，鱼戏见增波。
千里家林望，凉飙换绿萝。','',''),('quantangshi-17651','资阳郡中咏怀','羊士諤','quantangshi','','卷18','腰章非达士，闭阁是潜夫。
匣劒宁求试，笼禽但自拘。
江清牛渚镇，酒熟步兵厨。
唯此前贤意，风流似不孤。','',''),('quantangshi-17652','寒食宴城北山池即故郡守荣阳郑钢目为折柳亭','羊士諤','quantangshi','','卷18','别馆青山郭，游人折柳行。
落花经上巳，细雨带清明。
鶗鴂流芳暗，鸳鸯曲水平。
归心何处醉，宝瑟有余声。','',''),('quantangshi-17653','酬彭州萧使君秋中言怀','羊士諤','quantangshi','','卷18','右职移青绶，雄藩拜紫泥。
江回玉垒下，气爽锦城西。
臯鹤惊秋律，琴乌怨夜啼。
离居同舍念，宿昔奉金闺。','',''),('quantangshi-17654','资中早春','羊士諤','quantangshi','','卷18','一雨东风晚，山莺独报春。
淹留巫峡梦，惆怅洛阳人。
柳意笼丹槛，梅香覆锦茵。
年华行可惜，瑶瑟莫生尘。','',''),('quantangshi-17655','郡楼怀长安亲友','羊士諤','quantangshi','','卷18','残暑三巴地，沈阴八月天。
气昏高阁雨，梦倦下帘眠。
愁鬓华簪小，归心社燕前。
相思杜陵野，沟水独潺湲。','',''),('quantangshi-17656','王起居独游青龙寺翫红叶因寄','羊士諤','quantangshi','','卷18','十亩苍苔遶画廊，几株红树过清霜。
高情还似看花去，闲对南山步夕阳。','',''),('quantangshi-17657','夜听琵琶三首 一','羊士諤','quantangshi','','卷18','掩抑危弦咽又通，朔云边月想朦胧。
当时谁佩将军印，长使蛾眉怨不穷。','',''),('quantangshi-17658','夜听琵琶三首 二','羊士諤','quantangshi','','卷18','一曲徘徊星汉稀，夜阑幽怨重依依。
忽似摐金来上马，南枝栖鸟尽惊飞。','',''),('quantangshi-17659','夜听琵琶三首 三','羊士諤','quantangshi','','卷18','破拨声繁恨已长，低鬟敛黛更摧藏。
潺湲陇水听难尽，并觉风沙绕杏梁。','',''),('quantangshi-17660','彭州萧使君出妓夜宴见送','羊士諤','quantangshi','','卷18','玉颜红烛忽惊春，微步凌波暗拂尘。
自是当歌歛眉黛，不因惆怅为行人。','',''),('quantangshi-17661','题松江馆','羊士諤','quantangshi','','卷18','津柳江风白浪平，棹移高馆古今情。
扁舟一去鸱夷子，应笑分符计日程。','',''),('quantangshi-17662','偶题寄独孤使君','羊士諤','quantangshi','','卷18','病起淮阳自有时，秋来未觉长年悲。
坐逢在日唯相望，袅袅凉风满桂枝。','',''),('quantangshi-17663','永宁里小园与沈校书接近怅然题寄','羊士諤','quantangshi','','卷18','故里心期奈别何，手移芳树忆庭柯。
东臯黍熟君应醉，梨叶初红白露多。','',''),('quantangshi-17664','斋中咏怀','羊士諤','quantangshi','','卷18','无心唯有白云知，闲卧高斋梦蝶时。
不觉东风过寒食，雨来萱草出巴篱。','',''),('quantangshi-17665','登郡前山','羊士諤','quantangshi','','卷18','洛阳归客滞巴东，处处山樱雪满丛。
岘首当时为风景，岂将官舍作池笼。','',''),('quantangshi-17666','客有自渠州来说常谏议使君故事怅然成咏','羊士諤','quantangshi','','卷18','才子长沙暂左迁，能将意气慰当年。
至今犹有东山妓，长使歌诗被管弦。','',''),('quantangshi-17667','春日朝罢呈台中寮友','羊士諤','quantangshi','','卷18','退食鵷行振羽仪，九霄双阙迥参差。
云披彩仗春风度，日暖香堦昼刻移。
玉树笼烟鳷鹊观，石渠流水凤凰池。
时清执法惭无事，未有长杨汉主知。','',''),('quantangshi-17668','州民有献杏者瑰丽溢目因感花未几聊以成咏','羊士諤','quantangshi','','卷18','南郭东风赏杏坛，几株芳树昨留欢。
却忆落花飘绮席，忽惊如实满雕盘。
蛾眉半歛千金薄，鷤鴂初鸣百草阑。
志士古来悲节换，美人啼鸟亦长叹。','',''),('quantangshi-17669','西川独孤侍御见寄七言四韵一首为郡翰墨都捐逮此酬答诚乖拙速','羊士諤','quantangshi','','卷18','百雉层城上将坛，列营西照雪峰寒。
文章立事须铭鼎，谈笑论功耻据鞍。
草檄清油推健笔，曳裾黄阁耸危冠。
双金未比三千字，负弩空慙知者难。','',''),('quantangshi-17670','都城从事萧员外寄海梨花诗尽绮丽至惠然远及','羊士諤','quantangshi','','卷18','珠履行台拥附蝉，外郎高步似神仙。
陈词今见唐风盛，从事遥瞻卫国贤。
掷地好词凌彩笔，浣花春水腻鱼笺。
东山芳意须同赏，子看囊盛几日传。','',''),('quantangshi-17671','赴资阳经嶓冢山','羊士諤','quantangshi','','卷18','宁辞旧路驾朱轓，重使疲人感汉恩。
今日鸣驺到嶓峡，还胜博望至河源。','',''),('quantangshi-17672','郡中言怀寄西川萧员外','羊士諤','quantangshi','','卷18','功名无力愧勤王，已近终南得草堂。
身外尽归天竺偈，腰间唯有会稽章。
何时腊酒逢山客，可惜梅枝亚石牀。
岁晚我知仙客意，悬心应在白云乡。','',''),('quantangshi-17673','郡斋感物寄长安亲友','羊士諤','quantangshi','','卷18','晴天春意并无穷，过腊江楼日日风。
琼树花香故人别，兰巵酒色去年同。
闲吟铃阁巴歌里，回首神臯瑞气中。
自愧朝衣犹在箧，归来应是白头翁。','',''),('quantangshi-17674','息舟荆溪入阳羡南山游善权寺呈李功曹巨','羊士諤','quantangshi','','卷18','结缆兰香渚，柴车上连冈。
晏温值初霁，去遶山河长。
献岁冰雪尽，细泉生路傍。
行披烟杉入，激涧横石梁。
层阁表精庐，飞甍切云翔。
冲襟得高步，清眺极远方。
潭嶂积佳气，荑英多早芳。
具观泽国秀，重使春心伤。
念遵烦促途，荣利骛隟光。
勉君脱冠意，共匿无何乡。','',''),('quantangshi-17675','乱后曲江','羊士諤','quantangshi','','卷18','忆昔曾游曲水滨，春来长有探春人。
游春人静空地在，直至春深不似春。','',''),('quantangshi-17676','寻山家','羊士諤','quantangshi','','卷18','独访山家歇还涉，茅屋斜连隔松叶。
主人闻语未开门，绕篱野菜飞黄蝶。','',''),('quantangshi-17677','寄裴校书','羊士諤','quantangshi','','卷18','登高何处见琼枝，白露黄花自绕篱。
惟有楼中好山色，稻畦残水入秋池。','',''),('quantangshi-17678','句','羊士諤','quantangshi','','卷18','风泉留古韵，笙磬想遗音。
桂朽有遗馥，鸾飞安可待。
尘沙蔼如雾，长波惊飙度。
雁起汀洲寒，马嘶高城暮。
银釭倦秋馆，绮瑟瞻永路。
重有携手期，清光倚玉树。','',''),('quantangshi-17679','秋夜闲居即事寄庐山郑员外蜀郡符处士','楊巨源','quantangshi','','卷18','忧思繁未整，良辰会无由。
引领迟佳音，星纪屡以周。
蓬阆绝华耀，况乃处穷愁。
坠叶寒拥砌，灯火夜悠悠。
开琴弄清弦，窥月俯澄流。
冉冉鸿雁度，萧萧帷箔秋。
怅怀石门咏，缅慕碧鸡游。
仿髴蒙颜色，崇兰隐芳洲。','',''),('quantangshi-17680','独不见','楊巨源','quantangshi','','卷18','东风艳阳色，柳绿花如霰。
竞理同心鬟，争持合欢扇。
香传贾娘手，粉离何郎面。
最恨卷帘时，含情独不见。','',''),('quantangshi-17681','题赵孟庄','楊巨源','quantangshi','','卷18','管鲍化为尘，交友存如线。
升堂俱自媚，得路难相见。
懿君敦三益，颓俗期一变。
心同袭芝兰，气合回霜霰。
石门云卧久，玉洞花寻遍。
王浚爱旌旗，梁竦劳州县。
烟鸿秋更远，天马寒愈健。
愿事郭先生，青囊书几卷。','',''),('quantangshi-17682','辞魏博田尚书出境后感恩恋德因登藂台','楊巨源','quantangshi','','卷18','荐书及龙钟，此事镂心骨。
亲知殊悢悢，徒御方咄咄。
藂台邯郸郭，台上见新月。
离恨始分明，[归思]□□更超忽。
怀仁泪空尽，感事情又发。
他时躧履声，晓日照丹阙。','',''),('quantangshi-17683','夏日苦热同长孙主簿过仁寿寺纳凉','楊巨源','quantangshi','','卷18','火入天地罏，南方正何剧。
四郊长云红，六合太阳赤。
爀爀沸泉壑，焰焰燋砂石。
思减祝融权，期匡诸子宅。
因投竹林寺，一问青莲客。
心空得清凉，理证等喧寂。
开襟天籁回，步履雨花积。
微风动珠帘，惠气入瑶席。
境闲性方谧，尘远趣皆适。
淹驾殊未还，朱栏敞虚碧。','',''),('quantangshi-17684','送李虞仲秀才归东都因寄元李二友','楊巨源','quantangshi','','卷18','高翼闲未倦，孤云旷无期。
晴霞海西畔，秋草燕南时。
邺中多上才，耿耿丹霄姿。
顾我于逆旅，与君发光仪。
同将儒者方，获忝携人知。
幽兰与芳佩，寒玉锵美词。
旧友在伊洛，鸣蝉思山陂。
到来再春风，梦尽双琼枝。
素业且无负，青冥殊未迟。
南桥天气好，脉脉一相思。','',''),('quantangshi-17685','和卢谏议朝回书情即事寄两省阁老兼呈二起居谏院诸院长','楊巨源','quantangshi','','卷18','宠位资寂用，回头怜二疎。
超遥比鹤性，皎洁同僧居。
华组澹无累，单牀欢有余。
题诗天风洒，属思红霞舒。
蔼蔼延合东，晨光映林初。
炉香深内殿，山色明前除。
对客默焚稾，何人知谏书。
全仁气逾劲，大辨言甚徐。
逸步寄青璅，闲吟亲绮疏。
清辉被鸾渚，瑞蔼含龙渠。
谢监营野墅，陶公爱吾庐。
悠然远者怀，圣代飘长裾。
端弼缉元化，至音生太虚。
一戎殄欃枪，重译充储胥。
借地种寒竹，看云忆春蔬。
灵机栖杳冥，谈笑登轩车。
晚迹识麒麟，秋英见芙蕖。
危言直且庄，旷抱郁以摅。
志业耿冰雪，光容粲璠璵。
时贤俨仙掖，气谢心何如。','',''),('quantangshi-17686','奉酬窦郎中早入省苦寒见寄','楊巨源','quantangshi','','卷18','玄冥怒含风，羣物戒严节。
空山顽石破，幽涧层冰裂。
题诗金华彦，接武丹霄烈。
旷怀玉京云，孤唱粉垣雪。
穷阴总凝冱，正气直肃杀。
天狼看坠地，霜兔敢拒穴。
悠然蓬蒿士，亦得奉朝谒。
羸骖苦迟迟，单仆怨切切。
端闱仙阶邃，广陌冻桥滑。
旭日鸳鸯行，瑞烟芙蓉阙。
司寒申郑重，成岁在凛冽。
谢监逢酒时，袁生闭门月。
渐思霜霰减，欲报阳和发。
谁家挟纩心，何地当罏热。
惨舒能一改，恭听远者说。','',''),('quantangshi-17687','野园献果呈员外','楊巨源','quantangshi','','卷18','西园果初熟，上客心逾惬。
凝粉乍辞枝，飘红仍带叶。
幽姿写琼实，殷彩呈妆颊。
持此赠佳期，清芬罗袖裛。','',''),('quantangshi-17688','大堤曲','楊巨源','quantangshi','','卷18','二八婵娟大堤女，开垆相对依江渚。
待客登楼向水看，邀郎卷幔临花语。
细雨蒙蒙湿芰荷，巴东商侣挂帆多。
自传芳酒涴红袖，谁调妍妆回翠娥。
珍簟华灯夕阳后，当垆理瑟矜纤手。
月落星微五鼓声，春风摇荡牕前柳。
岁岁逢迎沙岸间，北人多识绿云鬟。
无端嫁与五陵少，离别烟波伤玉颜。','',''),('quantangshi-17689','杨花落','楊巨源','quantangshi','','卷18','北斗南回春物老，红英落尽绿尚早。
韶风澹荡无所依，偏惜垂杨作春好。
此时可怜杨柳花，荥盈艳曳满人家。
人家女儿出罗幕，静扫玉庭待花落。
宝环纤手捧更飞，翠羽轻裾承不着。
历历瑶琴舞金陈，菲红拂黛怜玉人。
东园桃李芳已歇，独有杨花娇暮春。','',''),('quantangshi-17690','月宫词','楊巨源','quantangshi','','卷18','宫中月明何所似，如积如流满田地。
逈过前殿曾学眉，回照长门惯催泪。
昭阳昨夜秋风来，绮阁金铺情影开。
藻井浮花共陵乱，玉阶零露相裴回。
稍映明河泛仙驭，满牕犹在更衣处。
管弦回烛无限情，环佩凭栏不能去。
皎皎苍苍千里同，穿烟飘叶九门通。
珠帘欲卷畏成水，瑶席初陈惊似空。
复值君王事欢宴，宫女三千一时见。
飞盖愁看素晕低，称觞愿踏清辉遍。
江上无云夜可怜，冒沙披浪自婵娟。
若共心赏风流夜，那比高高太液前。','',''),('quantangshi-17691','赠从弟茂卿','楊巨源','quantangshi','','卷18','吾从骥足杨茂卿，性灵且奇才甚清。
海内方微风雅道，邺中更有文章盟。
扣寂由来在渊思，搜奇本自通禅智。
王维证时符水月，杜甫狂处遗天地。
流水东西岐路分，幽州迢遰旧来闻。
若为向北驱疲马，山似寒空塞似云。','',''),('quantangshi-17692','乌啼曲赠张评事','楊巨源','quantangshi','','卷18','可怜杨叶复杨花，雪净烟深碧玉家。
乌栖不定枝条弱，城头夜半声哑哑。
浮萍流荡门前水，任罥芙蓉莫堕沙。','',''),('quantangshi-17693','端午日伏蒙内侍赐晨服','楊巨源','quantangshi','','卷18','彩缕纤仍丽，凌风卷复开。
方应五日至，应自九天来。
在笥清光发，当轩暑气回。
遥知及时节，刀尺火云催。','',''),('quantangshi-17694','胡姬词','楊巨源','quantangshi','','卷18','妍艳照江头，春风好客留。
当垆知妾惯，送酒为郎羞。
香渡传蕉扇，妆成上竹楼。
数钱怜皓腕，非是不能留。','',''),('quantangshi-17695','春日有赠','楊巨源','quantangshi','','卷18','堤暖柳丝斜，风光属谢家。
晚心应恋水，春恨定因花。
步远怜芳草，归迟见绮霞。
由来感情思，独自惜年华。','',''),('quantangshi-17696','襄阳乐','楊巨源','quantangshi','','卷18','闲随少年去，试上大堤游。
画角栖乌起，清弦过客愁。
碑沈楚山石，珠彻汉江秋。
处处风情好，卢家更上楼。','',''),('quantangshi-17697','关山月','楊巨源','quantangshi','','卷18','苍茫临故关，迢遰照秋山。
万里平芜静，孤城落叶闲。
露浓栖雁起，天远戍兵还。
复映征西府，光深组练间。','',''),('quantangshi-17698','长城闻笛','楊巨源','quantangshi','','卷18','孤城笛满林，断续共霜砧。
夜月降羌泪，秋风老将心。
静过寒垒遍，暗入故关深。
惆怅梅花落，山川不可寻。','',''),('quantangshi-17699','春晚东归留赠李功曹','楊巨源','quantangshi','','卷18','芳田岐路斜，脉脉惜年华。
云路青丝骑，香含翠幰车。
歌声仍隔水，醉色未侵花。
唯有怀乡客，东飞羡曙鵶。','',''),('quantangshi-17700','送殷员外使北蕃','楊巨源','quantangshi','','卷18','二轩将雨露，万里入烟沙。
和气生中国，薰风属外家。
塞芦随雁影，关柳拂驼花。
努力黄云北，仙曹有雉车。','',''),('quantangshi-17701','送许侍御充云南哀册使判官','楊巨源','quantangshi','','卷18','万里永昌城，威仪奉圣明。
冰心瘴江冷，霜宪漏天晴。
荒外开亭候，云南降斾旌。
他时功自许，绝域转哀荣。','',''),('quantangshi-17702','秋日题陈宗儒圃亭凄然感旧','楊巨源','quantangshi','','卷18','曾随何水部，待月东亭宿。
今日重凭栏，清风空在竹。
前山依旧碧，闲草经秋绿。
时物方宛然，蛛丝一何速。','',''),('quantangshi-17703','和郑少师相公题慈恩寺禅院','楊巨源','quantangshi','','卷18','旧寺长桐孙，朝天是圣恩。
谢公诗更老，萧傅道方尊。
白法知深得，苍生要重论。
若为将此望，心地向空门。','',''),('quantangshi-17704','同赵校书题普救寺','楊巨源','quantangshi','','卷18','东门高处天，一望几悠然。
白浪过城下，青山满寺前。
尘光分驿道，岚色到人烟。
气象须文字，逢君大雅篇。','',''),('quantangshi-17705','春日与刘评事过故证上人院','楊巨源','quantangshi','','卷18','曾共刘谘议，同时事道林。
与君方掩泪，来客是知心。
堦雪凌春积，钟烟向夕深。
依然旧童子，相送出花阴。','',''),('quantangshi-17706','春雪题兴善寺广宣上人竹院','楊巨源','quantangshi','','卷18','皎洁青莲客，焚香对雪朝。
竹风催淅沥，花雨让飘颻。
触石和云积，萦池拂水消。
只应将日月，颜色不相饶。','',''),('quantangshi-17707','清明日后土祠送田彻','楊巨源','quantangshi','','卷18','清明千万家，处处是年华。
榆柳芳辰火，梧桐今日花。
祭祠结云绮，游陌拥香车。
惆怅田郎去，原回烟树斜。','',''),('quantangshi-17708','酬令狐员外直夜书怀见寄','楊巨源','quantangshi','','卷18','花枝暖欲舒，粉署夜方初。
世职推传盛，春刑是减余。
芸香能护字，铅椠善呈书。
此地从头白，经年望雉车。','',''),('quantangshi-17709','题表丈三大夫书斋','楊巨源','quantangshi','','卷18','盛府自莲花，羣公是岁华。
兰姿丈人圃，松色大夫家。
素卷堆瑶席，朱弦映绛纱。
诗题三百首，高韵照春霞。','',''),('quantangshi-17710','春日送沈赞府归浔阳觐叔父','楊巨源','quantangshi','','卷18','浔阳阮咸宅，九派竹林前。
花屿高如浪，云峰远似天。
江声在南巷，海气入东田。
才子今朝去，风涛思渺然。','',''),('quantangshi-17711','与李文仲秀才同赋泛酒花诗','楊巨源','quantangshi','','卷18','若道春无赖，飞花合逐风。
巧知人意里，解入酒杯中。
香湿胜含露，光摇似泛空。
请君回首看，几片舞芳丛。','',''),('quantangshi-17712','登宁州城楼','楊巨源','quantangshi','','卷18','宋玉本悲秋，今朝更上楼。
清波城下去，此意重悠悠。
晚菊临杯思，寒山满郡愁。
故关非内地，一为汉家羞。','',''),('quantangshi-17713','同薛侍御登黎阳县楼眺黄河','楊巨源','quantangshi','','卷18','倚槛恣流目，高城临大川。
九回纡白浪，一半在青天。
气肃晴空外，光翻晓日边。
开襟值佳景，怀抱更悠然。','',''),('quantangshi-17714','和权相公南园闲涉寄广宣上人','楊巨源','quantangshi','','卷18','浩气抱天和，闲园载酒过。
步因秋景旷，心向晚云多。
翠玉思回凤，玄珠肯在鹅。
问师登几地，空性奈诗何。','',''),('quantangshi-17715','供奉定法师归安南','楊巨源','quantangshi','','卷18','故乡南越外，万里白云峰。
经论辞天去，香花入海逢。
鹭涛清梵彻，蜃阁化城重。
心到长安陌，交州后夜钟。','',''),('quantangshi-17716','池上竹','楊巨源','quantangshi','','卷18','一丛婵娟色，四面清冷波。
气润晚烟重，光闲秋露多。
翠筠入疎柳，清影拂圆荷。
岁晏琅玕实，心期有凤过。','',''),('quantangshi-17717','长安春游','楊巨源','quantangshi','','卷18','凤城春报曲江头，上客年年是胜游。
日暖云山当广陌，天清丝管在高楼。
茏葱树色分仙阁，缥缈花香泛御沟。
桂壁朱门新邸第，汉家恩泽问酇侯。','',''),('quantangshi-17718','送定法师归蜀法师即红楼院供奉广宣上人兄弟','楊巨源','quantangshi','','卷18','凤城初日照红楼，禁寺公卿识惠休。
诗引棣华沾一雨，经分贝叶向双流。
孤猿学定前山夕，远雁伤离几地秋。
空性碧云无处所，约公曾许剡溪游。','',''),('quantangshi-17719','早朝','楊巨源','quantangshi','','卷18','钟声清禁才应彻，漏报仙闱俨已开。
双阙薄烟笼菡萏，九成初日照蓬莱。
朝时但向丹墀拜，仗下方从碧殿回。
圣道逍遥更何事，愿将巴曲赞康哉。','',''),('quantangshi-17720','赠张将军','楊巨源','quantangshi','','卷18','关西诸将揖容光，独立营门劒有霜。
知爱鲁连归海上，肯令王翦在频阳。
天晴红帜当山满，日暮清笳入塞长。
年少功高人最羡，汉家坛树月苍苍。','',''),('quantangshi-17721','和侯大夫秋原山观征人回','楊巨源','quantangshi','','卷18','两河战罢万方清，原上军回识旧营。
立马望云秋塞静，射雕临水晚天晴。
戍闲部伍分岐路，地远家乡寄斾旌。
圣代止戈资庙略，诸侯不复更长征。','',''),('quantangshi-17722','送人过卫州','楊巨源','quantangshi','','卷18','忆昔征南府内游，君家东合最淹留。
纵横联句长侵晓，次第看花直到秋。
论旧举杯先下泪，伤离临水更登楼。
相思前路几回首，满眼青山过卫州。','',''),('quantangshi-17723','寄中书同年舍人','楊巨源','quantangshi','','卷18','晴明紫阁最高峰，仙掖开帘范彦龙。
五色天书词焕烂，九华春殿语从客。
彩毫应染炉烟细，清佩仍含玉漏重。
二十年前同日喜，碧霄何路得相逢。','',''),('quantangshi-17724','酬于驸马二首 一','楊巨源','quantangshi','','卷18','绮陌尘香曙色分，碧山如画又逢君。
蛟藏秋月一片水，骥锁晴空千尺云。
戚里旧知何驸马，诗家今得鲍参军。
阳和本是烟霄曲，须向花间次第闻。','',''),('quantangshi-17725','酬于驸马二首 二','楊巨源','quantangshi','','卷18','芳时碧落心应断，今日清词事不同。
瑶草秋残仙圃在，彩云天远凤楼空。
晴花暖送金羁影，凉叶寒生玉簟风。
长得闻诗欢自足，会看春露湿兰丛。','',''),('quantangshi-17726','将归东都寄令狐舍人','楊巨源','quantangshi','','卷18','绿杨红杏满城春，一骑悠悠万井尘。
岐路未关今日事，风光欲醉长年人。
闲过绮陌寻高寺，强对朱门谒近臣。
多病晚来还有策，雒阳山色旧相亲。','',''),('quantangshi-17727','寄江州白司马','楊巨源','quantangshi','','卷18','江州司马平安否，惠远东林住得无。
湓浦曾闻似衣带，庐峰见说胜香炉。
题诗岁晏离鸿断，望阙天遥病鹤孤。
莫谩拘牵雨花社，青云依旧是前途。','',''),('quantangshi-17728','薛司空自青州归朝','楊巨源','quantangshi','','卷18','天眷君陈久（一作“旧”）在东，归朝人看大司空。
黄河岸畔长无事，沧海东边独有功。
已变畏途成雅俗，仍过旧里揖秋风。
一门累叶凌烟阁，次第仪形汉上公。','',''),('quantangshi-17729','送章孝标校书归杭州因寄白舍人','楊巨源','quantangshi','','卷18','曾过灵隐江边寺，独宿东楼看海门。
潮色银河铺碧落，日光金柱出红盆。
不妨公事资高卧，无限诗情要细论。
若访郡人徐孺子，应须骑马到沙村。','',''),('quantangshi-17730','述旧纪勋太原寄李光颜侍中二首 一','楊巨源','quantangshi','','卷18','玉塞含凄见雁行，北垣新诏拜龙骧。
弟兄间世真飞将，貔虎归时似故乡。
鼓角因风飘朔气，旌旗映水发秋光。
河源收地心犹壮，笑向天西万里霜。','',''),('quantangshi-17731','述旧纪勋太原寄李光颜侍中二首 二','楊巨源','quantangshi','','卷18','倚天长劒截云孤，报国纵横见丈夫。
五载登坛真宰相，六重分阃正司徒。
曾闻转战平坚寇，共说题诗压腐儒。
料敌知机在方寸，不劳心力讲阴符。','',''),('quantangshi-17732','酬卢员外','楊巨源','quantangshi','','卷18','谢傅旌旗控上游，卢郎罇俎借前筹。
舜城风土临清庙，魏国山川在白楼。
云寺当时接高步，水亭今日又同游。
满筵旧府笙歌在，独有羊昙最泪流。','',''),('quantangshi-17733','古意赠王常侍','楊巨源','quantangshi','','卷18','绣户纱窗北里深，香风暗动凤凰簪。
组紃常在佳人手，刀尺空摇寒女心。
欲学齐讴逐云管，还思楚练拂霜砧。
东家少妇当机织，应念无衣雪满林。','',''),('quantangshi-17734','送裴中丞出使','楊巨源','quantangshi','','卷18','一清淮甸假朝纲，金印初迎细柳黄。
辞阙天威和雨露，出关春色避风霜。
龙韬何必陈三略，虎旅由来肃万方。
宣谕生灵真重任，回轩应问石渠郎。','',''),('quantangshi-17735','送绛州卢使君','楊巨源','quantangshi','','卷18','应将清净结心期，又共阳和到郡时。
绛老问年须算字，庾公逢月要题诗。
朱栏迢遰因高胜，粉堞清明欲下迟。
他日徴还作霖雨，不须求赛敬亭祠。','',''),('quantangshi-17736','赠李傅','楊巨源','quantangshi','','卷18','知因公望掩能文，誓激明诚在致君。
曾罢双旌瞻白日，犹将一劒许黄云。
摇牕竹色留僧语，入院松声共鹤闻。
莫被此心生晚计，镇南人忆杜将军。','',''),('quantangshi-17737','上裴中丞','楊巨源','quantangshi','','卷18','六年西掖弘汤诰，三捷东堂总汉科。
政引风霜成物色，语回天地到阳和。
清威更助朝端重，圣泽曾随笔下多。
应笑白须扬执戟，可怜春日老如何。','',''),('quantangshi-17738','和人与人分惠赐冰','楊巨源','quantangshi','','卷18','天水藏来玉堕空，先颁密署几人同。
映盘皎洁非资月，披扇清凉不在风。
莹质方从纶阁内，凝辉更向画堂中。
丽词珍贶难双有，迢遰金舆殿角东。','',''),('quantangshi-17739','观打球有作','楊巨源','quantangshi','','卷18','亲扫球场如砥平，龙骧骤马晓光晴。
入门百拜瞻雄势，动地三军唱好声。
玉勒回时霑赤汗，花鬉分处拂红缨。
欲令四海氛烟静，杖底纤尘不敢生。','',''),('quantangshi-17740','早春即事呈刘员外','楊巨源','quantangshi','','卷18','明朝晴暖即相随，肯信春光被雨欺。
且任文书堆案上，免令杯酒负花时。
马蹄经历须应徧，莺语叮咛已怪迟。
更待杂芳成艳锦，邺中争唱仲宣诗。','',''),('quantangshi-17741','送司徒童子','楊巨源','quantangshi','','卷18','卫多君子鲁多儒，七岁闻天笑舞雩。
光彩春风初转蕙，性灵秋水不藏珠。
两经在口知名小，百拜垂髫禀气殊。
况复元侯旌尔善，桂林枝上得鵷雏。','',''),('quantangshi-17742','寄昭应王丞','楊巨源','quantangshi','','卷18','武皇金辂辗香尘，每岁朝元及此辰。
光动泉心初浴日，气蒸山腹总成春。
讴歌已入云韶曲，词赋方归侍从臣。
瑞霭朝朝犹望幸，天敎赤县有诗人。','',''),('quantangshi-17743','酬崔博士','楊巨源','quantangshi','','卷18','自知顽叟更何能，唯学雕虫谬见称。
长被有情邀唱和，近来无力更祗承。
青松树杪三千鹤，白玉壶中一片冰。
今日为君书壁右，孤城莫怕世人憎。','',''),('quantangshi-17744','酬裴舍人见寄','楊巨源','quantangshi','','卷18','谁道重迁是旧班，自将霄汉比乡关。
二妃楼下宜临水，五老祠西好看山。
再葺吾庐心已足，每来公府路常闲。
诗陪亚相逾三纪，石笥烟霞不共攀。','',''),('quantangshi-17745','和刘员外陪韩仆射野亭公宴','楊巨源','quantangshi','','卷18','好客风流玳瑁簪，重檐高幕晓沈沈。
绮筵霜重旌旗满，玉帐天清丝管声。
繁戏徒过鲁儒目，众欢方集汉郎心。
寒笳一曲严城暮，云骑连嘶香外林。','',''),('quantangshi-17746','酬崔驸马惠笺百张兼贻四韵','楊巨源','quantangshi','','卷18','百张云样乱花开，七字文头艳锦回。
浮碧空从天上得，殷红应自日边来。
捧持价重凌云叶，封裹香深笑海苔。
满箧清光应照眼，欲题凡韵辄裴回。','',''),('quantangshi-17747','赠史开封','楊巨源','quantangshi','','卷18','天低荒草誓师坛，邓艾心知战地宽。
鼓角逈临霜野曙，旌旗高对雪峰寒。
五营向水红尘起，一劒当风白日看。
曾从伏波征绝域，碛西蕃部怯金鞍。','',''),('quantangshi-17748','奉寄通州元九侍御','楊巨源','quantangshi','','卷18','大明宫殿郁苍苍，紫禁龙楼直署香。
九陌华轩争道路，一枝寒玉任烟霜。
须听瑞雪传心语，莫被啼猨续泪行。
共说圣朝容直气，期君新岁奉恩光。','',''),('quantangshi-17749','赠浑钜中允','楊巨源','quantangshi','','卷18','公子髫年四海闻，城南侍猎雪雰雰。
马盘旷野弦开月，雁落寒原箭在云。
曾向天西穿虏阵，惯游花下领儒羣。
一枝琼萼朝光好，彩服飘飘从冠军。','',''),('quantangshi-17750','重送胡大夫赴振武','楊巨源','quantangshi','','卷18','向年擢桂儒生业，今日分茅圣主恩。
旌斾仍将过乡路，轩车争看出都门。
人间文武能双捷，天下安危待一论。
布惠宣威大夫事，不妨诗思许琴尊。','',''),('quantangshi-17751','送陈判官罢举赴江外','楊巨源','quantangshi','','卷18','练思多时冰雪清，拂衣无语别书生。
莫将甲乙为前累，不废烟霄是此行。
定爱红云燃楚色，应看白雨打江声。
心期玉帐亲台位，魏勃因君说姓名。','',''),('quantangshi-17752','奉和裴相公','楊巨源','quantangshi','','卷18','竹寺题名一半空，衰荣三十六人中。
在生本要求知己，垂老应怜值相公。
敢望燮和回旧律，任应时节到春风。
若为问得苍苍意，造化无言自是功。','',''),('quantangshi-17753','和大夫边春呈长安亲故','楊巨源','quantangshi','','卷18','严城吹笛思寒梅，二月冰河一半开。
紫陌诗情依旧在，黑山弓力畏春来。
游人曲岸看花发，走马平沙猎雪回。
旌斾朝天不知晚，将星高处近三台。','',''),('quantangshi-17754','张郎中段员外初直翰林报寄长句','楊巨源','quantangshi','','卷18','秋空如练瑞云明，天上人间莫问程。
丹凤词头供二妙，金銮殿角直三清。
方瞻北极临星月，犹向南班滞姓名。
启沃朝朝深禁里，香炉烟外是公卿。','',''),('quantangshi-17755','奉酬端公春雪见寄','楊巨源','quantangshi','','卷18','造化多情状物亲，剪花铺玉万重新。
闲飘上路呈丰岁，狂舞中庭学醉春。
兴逸何妨寻剡客，唱高还肯寄巴人。
遥知独立芝兰阁，满眼清光压俗尘。','',''),('quantangshi-17756','卢郎中拜陵遇雪蒙见召因寄','楊巨源','quantangshi','','卷18','南宫使者有光辉，欲拜诸陵瑞雪飞。
苹叶已修青玉荐，柳花仍拂赤车衣。
应同谷口寻春去，定似山阴带月归。
寒冷出郊犹未得，羡公将事看芳菲。','',''),('quantangshi-17757','冬夜陪丘侍御先辈听崔校书弹琴','楊巨源','quantangshi','','卷18','雪满中庭月映林，谢家幽赏在瑶琴。
楚妃波浪天南远，蔡女烟沙漠北深。
顾盼何曾因误曲，殷勤终是感知音。
若将雅调开诗兴，未抵丘迟一片心。','',''),('quantangshi-17758','元日含元殿下立仗丹凤楼门下宣赦相公称贺二首 一','楊巨源','quantangshi','','卷18','天垂台耀扫欃枪，寿献香山祝圣明。
丹凤楼前歌九奏，金鸡竿下鼓千声。
衣冠南面薰风动，文字东方喜气生。
从此登封资庙略，两河连海一时清。','',''),('quantangshi-17759','元日含元殿下立仗丹凤楼门下宣赦相公称贺二首 二','楊巨源','quantangshi','','卷18','临轩启扇似云收，率土朝天剧水流。
瑞色含春当正殿，香烟捧日在高楼。
三朝气蚤迎恩泽，万岁声长绕冕旒。
请问汉家功第一，麒麟阁上识酇侯。','',''),('quantangshi-17760','元日观朝','楊巨源','quantangshi','','卷18','北极长尊报圣期，周家何用问元龟。
天颜入曙千官拜，元日迎春万物知。
阊阖回临黄道正，衣裳高对碧山垂。
微臣愿献尧人祝，寿酒年年太液池。','',''),('quantangshi-17761','题贾巡官林亭','楊巨源','quantangshi','','卷18','白鸟闲栖亭树枝，绿罇仍对菊花篱。
许询本爱交禅侣，陈寔由来是好儿。
明月出云秋馆思，远泉经雨夜牕知。
门前长者无虚辙，一片寒光动水池。','',''),('quantangshi-17762','和元员外题升平里新斋','楊巨源','quantangshi','','卷18','自知休沐诸幽胜，遂肯高斋枕广衢。
旧地已开新玉圃，春山仍展绿云图。
心源邀得闲诗证，肺气宜将慢酒扶。
此外唯应任真宰，同尘敢是道门枢。','',''),('quantangshi-17763','送澹公归嵩山龙潭寺葬本师','楊巨源','quantangshi','','卷18','野烟秋水苍茫远，禅境真机去住闲。
双树为家思旧壑，千花成塔礼寒山。
洞宫曾向龙边宿，云径应从鸟外还。
莫恋本师金骨地，空门无处复无关。','',''),('quantangshi-17764','邵州陪王郎中宴','楊巨源','quantangshi','','卷18','西塞无尘多玉筵，貔貅鸳鹭俨相连。
红茵照水开罇俎，翠幕当云发管弦。
歌态晓临团扇静，舞容春映薄衫妍。
鲁儒纵使他时有，不似欢娱及少年。','',''),('quantangshi-17765','和令狐舍人酬峰上人题山栏孤竹','楊巨源','quantangshi','','卷18','满院冰姿粉箨残，一茎青翠近帘端。
离丛自欲亲香火，抱节何妨共岁寒。
能让繁声任真籁，解将孤影对芳兰。
范云许访西林寺，枝叶须和彩凤看。','',''),('quantangshi-17766','寄赠田仓曹湾','楊巨源','quantangshi','','卷18','芳兰媚庭除，灼灼红英舒。
身为陋巷客，门有绛辕车。
朝览夷吾传，暮习颍阳书。
眄云高羽翼，待贾蕴璠璵。
缨弁虽云阻，音尘岂复疎。
若因风雨晦，应念寂寥居。','',''),('quantangshi-17767','上刘侍中','楊巨源','quantangshi','','卷18','命代生申甫，承家翊禹汤。
庙谟膺间气，师律动清霜。
钟鼎勋庸大，山河诫誓长。
英姿凌虎视，逸步压龙骧。
道协陶钧力，恩回日月光。
一言弘社稷，九命备圭璋。
政洽军逾肃，仁敷物已康。
朱门重棨戟，丹诏半缣缃。
位总云龙野，师临涿鹿乡。
射雕天更碧，吹角塞仍黄。
深入平夷路，横行辟汉疆。
功垂贞石远，名映色丝香。
断碛瞻貔武，临池识凤凰。
舞腰凝绮榭，歌响拂雕梁。
杯净传鹦鹉，裘鲜照鷫鸘。
吟诗白羽扇，校猎绿沈枪。
风景佳人地，烟沙壮士场。
幕中邀谢鉴，麾下得周郎。
珠影含空彻，琼枝映座芳。
王浑知武子，陈寔奖元方。
富贵春无限，欢娱夜未央。
管弦随玉帐，尊俎奉金章。
俗理宁因劝，边城讵假防。
军容雄朔漠，公望冠岩廊。
分野邻孤岛，京坻溢万厢。
曙华分碣石，秋色入衡阳。
城远迷玄兔，川明辩白狼。
忠贤多感激，今古共苍茫。
堤拥红蕖艳，桥分翠柳行。
轩车纷自至，亭馆郁相当。
珍簟回烦暑，层轩引早凉。
听琴知思静，说劒觉神扬。
佳景燕台上，清辉郑驿傍。
鼓鼙喧北里，圭玉映东牀。
敢炫由之瑟，甘循赐也墙。
官微思假路，战胜忝升堂。
欲奋三年翼，频回一夕肠。
消忧期酒圣，乘兴任诗狂。
海内栽桃李，天涯荷稻粱。
升沈门下意，谁道在苍苍。','',''),('quantangshi-17768','赠侯侍御','楊巨源','quantangshi','','卷18','步逸辞羣迹，机真结远心。
敦诗扬大雅，映古酌高音。
逃祸栖蜗舍，因醒解豸簪。
紫兰秋露湿，黄鹤晚天阴。
旧业余荒草，寒山出远林。
月明多宿寺，世乱重悲琴。
霄汉时应在，诗书道未沈。
坐期阊阖霁，云暖一开襟。','',''),('quantangshi-17769','怀德抒情寄上信州座主','楊巨源','quantangshi','','卷18','五马江天郡，诸生泪共垂。
宴余明主德，恩在侍臣知。
怅望缄双鲤，龙钟假一枝。
玉峰遥寄梦，云海暗伤离。
幢盖全家去，琴书首路随。
沧州值康乐，明月向元规。
鵷凤终凌汉，蛟龙会出池。
蕙香因曙发，松色肯寒移。
举世瞻风藻，当朝揖羽仪。
加餐门下意，溪水绿逶迤。','',''),('quantangshi-17770','送杜郎中使君赴虔州','楊巨源','quantangshi','','卷18','迢遰南康路，清辉得使君。
虎符秋领俗，鵷署早辞羣。
地远仍连戍，城严本带军。
傍江低槛月，当岭满牕云。
境胜闾阎间，天清水陆分。
和诗将惠政，颂述九衢闻。','',''),('quantangshi-17771','别鹤词送令狐校书之桂府','楊巨源','quantangshi','','卷18','海鹤一为别，高程方窅然。
影摇江汉路，思结潇湘天。
皎然仰白日，真姿栖紫烟。
含情九霄际，顾侣五云前。
遐心属清都，凄响激朱弦。
超遥闻风雨，迢遰各山川。
东南信多水，会合当有年。
雌飞唳冥冥，此意何由传。','',''),('quantangshi-17772','夏日裴尹员外西斋看花','楊巨源','quantangshi','','卷18','笑向东来客，看花枉在前。
始知清夏月，更胜艳阳天。
露湿呈妆污，风吹畏火燃。
葱茏和叶盛，烂熳压枝鲜。
红彩当[铃]阁，清香到玉筵。
蝶栖惊曙色，莺语滞晴烟。
得地殊堪赏，过时倍觉妍。
芳菲迟最好，唯是谢家怜。','',''),('quantangshi-17773','赠邻家老将','楊巨源','quantangshi','','卷18','白首羽林郎，丁年戍朔方。
阴天瞻碛落，秋日渡辽阳。
大漠寒山黑，孤城夜月黄。
十年依蓐食，万里带金疮。
拂雪陈师祭，冲风立敎场。
箭飞琼羽合，旗动火云张。
虎翼分营势，鱼鳞拥阵行。
誓心清塞色，鬬血杂沙光。
战地晴辉薄，军门晓气长。
寇深争暗袭，关逈勒春防。
身贱竟何诉，天高徒自伤。
功成封宠将，力尽到贫乡。
雀老方悲海，鹰衰却念霜。
空余孤劒在，开匣一霑裳。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-17774','和吕舍人喜张员外自北番回至境上先寄二十韵','楊巨源','quantangshi','','卷18','割爱天文动，敦和国步安。
仙姿归旧好，戎意结新欢。
并命瞻鵷鹭，同心揖蕙兰。
玉箫临祖帐，金牓引征鞍。
广陌双旌去，平沙万里看。
海云侵鬓起，边月向眉残。
突兀阴山迥，苍茫朔野宽。
毳庐同甲帐，韦橐比雕盘。
义着亲胡俗，仪全识汉官。
地邻冰鼠净，天映烛龙寒。
节异苏卿执，弦殊蔡女弹。
碛分黄渺渺，塞极黑漫漫。
欢味膻腥列，徴声佅僸攒。
归期先雁候，登路剧鹏搏。
上客离心远，西宫草诏殚。
丽词传锦绮，珍价掩琅玕。
百两开戎垒，千蹄入御栏。
瑞光麟阁上，喜气凤城端。
尚德曾辞劒，柔凶本舞干。
茫茫斗星北，威服古来难。','',''),('quantangshi-17775','春日奉献圣寿无疆词十首 一','楊巨源','quantangshi','','卷18','文物京华盛，讴歌国步康。
瑶池供寿酒，银汉丽宸章。
灵雨含双阙，雷霆肃万方。
代推仙祚远，春共圣恩长。
凤扆临花暖，龙罏旁日香。
遥知千万岁，天意奉君王。','',''),('quantangshi-17776','春日奉献圣寿无疆词十首 二','楊巨源','quantangshi','','卷18','鸳鹭彤庭际，轩车绮陌前。
九城多好色，万井半祥烟。
人醉逢尧酒，莺歌答舜弦。
花明御沟水，香暖禁城天。
赐宴文逾盛，徴歌物更妍。
无穷艳阳月，长照太平年。','',''),('quantangshi-17777','春日奉献圣寿无疆词十首 三','楊巨源','quantangshi','','卷18','云陛临黄道，天门在碧虚。
大明含睿藻，元气抱宸居。
戈偃征苗后，诗传宴镐初。
年华富仙苑，时哲满公车。
化入絪緼大，恩垂涣汗余。
悠然万方静，风俗揖华胥。','',''),('quantangshi-17778','春日奉献圣寿无疆词十首 四','楊巨源','quantangshi','','卷18','玉漏飘青璅，金铺丽紫宸。
云山九门曙，天地一家春。
瑞霭方呈赏，暄风本配仁。
岩廊开凤翼，水殿压鳌身。
文雅逢明代，欢娱及贱臣。
年年未央阙，恩共物华新。','',''),('quantangshi-17779','春日奉献圣寿无疆词十首 五','楊巨源','quantangshi','','卷18','垂拱干坤正，欢心品类同。
紫烟含北极，玄泽付东风。
珠缀留晴景，金茎直晓空。
发生资盛德，交泰让全功。
间气登三事，祥光启四聪。
遐荒似川水，天外亦朝宗。','',''),('quantangshi-17780','春日奉献圣寿无疆词十首 六','楊巨源','quantangshi','','卷18','代是文明昼，春当宴喜时。
罏烟添柳重，宫漏出花迟。
汉典方宽律，周官正采诗。
碧宵传凤吹，红旭在龙旗。
造化膺神契，阳和沃圣思。
无因随百兽，率舞奉丹墀。','',''),('quantangshi-17781','春日奉献圣寿无疆词十首 七','楊巨源','quantangshi','','卷18','睿德符玄化，芳情翊太和。
日轮皇鉴远，天仗圣朝多。
曙色含金牓，晴光转玉珂。
中宫陈广乐，元老进赓歌。
莲叶看龟上，桐花识凤过。
小臣空击壤，沧海是恩波。','',''),('quantangshi-17782','春日奉献圣寿无疆词十首 八','楊巨源','quantangshi','','卷18','物象朝高殿，簪裾溢上京。
春当九衢好，天向万方明。
乐报箫韶发，杯看沆瀣生。
芙蓉丹阙暖，杨柳玉楼晴。
阊阖开中禁，衣裳俨太清。
南山同圣寿，长对凤皇城。','',''),('quantangshi-17783','春日奉献圣寿无疆词十首 九','楊巨源','quantangshi','','卷18','日上苍龙阙，香含紫禁林。
晴光五云叠，春色九重深。
赏叶元和德，文垂雅颂音。
景云随御辇，颢气在宸襟。
永保无疆寿，长怀不战心。
圣朝多庆赐，琼树粉墙阴。','',''),('quantangshi-17784','春日奉献圣寿无疆词十首 十','楊巨源','quantangshi','','卷18','化洽生成遂，功宣动植知。
瑞凝三秀草，春入万年枝。
凤掖嘉言进，鸳行喜气随。
仗临丹地近，衣对碧山垂。
渥泽方柔远，聪明本听卑。
愿同东观士，长对汉威仪。','',''),('quantangshi-17785','衔鱼翠鸟','楊巨源','quantangshi','','卷18','有意莲叶间，瞥然下高树。
擘破得全鱼，一点翠光去。','',''),('quantangshi-17786','和郑相公寻宣上人不遇','楊巨源','quantangshi','','卷18','方寻莲境去，又值竹房空。
几韵飘寒玉，余清不在风。','',''),('quantangshi-17787','题范阳金台驿','楊巨源','quantangshi','','卷18','六国唯求客，千金遂筑台。
若令逢圣代，憔悴郭生回。','',''),('quantangshi-17788','寄薛侍御','楊巨源','quantangshi','','卷18','世上无穷事，生涯莫废诗。
何曾好风月，不是忆君时。','',''),('quantangshi-17789','赋得灞岸柳留辞郑员外','楊巨源','quantangshi','','卷18','杨柳含烟灞岸春，年年攀折为行人。
好风傥借低枝便，莫遣青丝扫路尘。','',''),('quantangshi-17790','折杨柳','楊巨源','quantangshi','','卷18','水边杨柳麴尘丝，立马烦君折一枝。
惟有春风最相惜，殷勤更向手中吹。','',''),('quantangshi-17791','雪中听筝','楊巨源','quantangshi','','卷18','玉柱泠泠对寒雪，清商怨徴声何切。
谁怜楚客向隅时，一片愁心与弦绝。','',''),('quantangshi-17792','卢龙塞行送韦掌记二首 一','楊巨源','quantangshi','','卷18','雨雪粉粉黑水外。
行人共指卢龙塞，万里飞沙压鼓鼙。
三军杀气凝旌斾。','',''),('quantangshi-17793','卢龙塞行送韦掌记二首 二','楊巨源','quantangshi','','卷18','陈琳书记本翩翩，料敌能兵夺酒泉。
圣主好文兼好武，封侯莫比汉皇年。','',''),('quantangshi-17794','题五老峰下费君书院','楊巨源','quantangshi','','卷18','解向花间栽碧松，门前不负老人峰。
已将心事随身隐，认得溪云第几重。','',''),('quantangshi-17795','僧院听琴','楊巨源','quantangshi','','卷18','禅思何妨在玉琴，真僧不见听时心。
离声怨调秋堂夕，云向苍梧湘水深。','',''),('quantangshi-17796','和武相公春晓闻莺','楊巨源','quantangshi','','卷18','语恨飞迟天欲明，殷勤似诉有余情。
仁风已及芳菲节，犹向花溪鸣几声。','',''),('quantangshi-17797','唐昌观玉蘂花','楊巨源','quantangshi','','卷18','晴空素艳照霞新，香洒天风不到尘。
持赠昔闻将白雪，蘂珠宫上玉花春。','',''),('quantangshi-17798','山中主人','楊巨源','quantangshi','','卷18','十里青山有一家，翠屏深处更添霞。
若为说得溪中事，锦石和烟四面花。','',''),('quantangshi-17799','太原赠李属侍御','楊巨源','quantangshi','','卷18','路入桑干塞雁飞，枣郎年少有光辉。
春风走马三千里，不废看花君绣衣。','',''),('quantangshi-17800','崔娘诗','楊巨源','quantangshi','','卷18','清润潘郎玉不如，中庭蕙草雪消初。
风流才子多春思，肠断萧娘一纸书。','',''),('quantangshi-17801','题云师山房','楊巨源','quantangshi','','卷18','云公兰若深山里，月明松殿微风起。
试问空门清净心，莲花不着秋潭水。','',''),('quantangshi-17802','城东早春','楊巨源','quantangshi','','卷18','诗家清景在新春，绿柳才黄半未匀。
若待上林花似锦，出门俱是看花人。','',''),('quantangshi-17803','秋日登亭赠薛侍御','楊巨源','quantangshi','','卷18','潦倒从军何取益，东西走马暂同游。
梁王旧客皆能赋，今日因何独怨秋。','',''),('quantangshi-17804','石水词二首 一','楊巨源','quantangshi','','卷18','银罂深鏁贮清光，无限来人不得尝。
知共金丹争气力，一杯全胜五云浆。','',''),('quantangshi-17805','石水词二首 二','楊巨源','quantangshi','','卷18','山叟和云斸翠屏，煎时分日检仙经。
天人持此扶衰病，胜得瑶池水一瓶。','',''),('quantangshi-17806','答振武李逢吉判官','楊巨源','quantangshi','','卷18','近来时辈都无兴，把酒皆言肺病同。
唯有单于李评事，不将华发负春风。','',''),('quantangshi-17807','宫燕词','楊巨源','quantangshi','','卷18','毛衣似锦语如弦，日暖争高绮陌天。
几处野花留不得，双双飞向御炉前。','',''),('quantangshi-17808','赠崔驸马','楊巨源','quantangshi','','卷18','百尺梧桐画阁齐，箫声落处翠云低。
平阳不惜黄金埒，细雨花骢踏作泥。','',''),('quantangshi-17809','听李凭弹箜篌二首 一','楊巨源','quantangshi','','卷18','听奏繁弦玉殿清，风传曲度禁林明。
君王听乐棃园暖，翻到云门第几声。','',''),('quantangshi-17810','听李凭弹箜篌二首 二','楊巨源','quantangshi','','卷18','花咽娇莺玉漱泉，名高半在御筵前。
汉王欲助人间乐，从遣新声坠九天。','',''),('quantangshi-17811','临水看花','楊巨源','quantangshi','','卷18','一树红花暎绿波，晴明骑马好经过。
今朝几许风吹落，闻道萧郎最惜多。','',''),('quantangshi-17812','观妓人入道二首 一','楊巨源','quantangshi','','卷18','荀令歌钟北里亭，翠娥红粉敞云屏。
舞衣施尽余香在，今日花前学诵经。','',''),('quantangshi-17813','观妓人入道二首 二','楊巨源','quantangshi','','卷18','碧玉芳年事冠军，清歌空得隔花闻。
春来削发芙蓉寺，蝉鬓临风堕绿云。','',''),('quantangshi-17814','方城驿逢孟侍御','楊巨源','quantangshi','','卷18','走马温汤直隼飞，相逢矍铄理征衣。
军中得力儿男事，入驿从容见落晖。','',''),('quantangshi-17815','题清凉寺','楊巨源','quantangshi','','卷18','凭槛霏微松树烟，陶潜曾用道林钱。
一声寒磬空心晓，花雨知从第几天。','',''),('quantangshi-17816','酬令狐舍人','楊巨源','quantangshi','','卷18','晓禁苍苍换直还，暂低鸾翼向人间。
亦知受业公门事，数仞丘墙不见山。','',''),('quantangshi-17817','和令狐郎中','楊巨源','quantangshi','','卷18','题诗一代占清机，秉笔三年直紫微。
自禀道情龆齓异，不同蘧玉学知非。','',''),('quantangshi-17818','美人春怨','楊巨源','quantangshi','','卷18','妾家巫峡阳，罗幌寝兰堂。
晓日临窗久，春风引梦长。
落钗仍挂鬓，微汗欲销黄。
纵便朦胧觉，魂犹逐楚王。','',''),('quantangshi-17819','艳女词','楊巨源','quantangshi','','卷18','露井桃花发，双双燕并飞。
美人姿态里，春色上罗衣。
自爱频开镜，时羞欲掩扉。
心知行路客，遥惹五香归。','',''),('quantangshi-17820','名姝咏','楊巨源','quantangshi','','卷18','阿娇年未多，体弱性能和。
怕重愁拈镜，怜轻喜曳罗。
临津双洛浦，对月两嫦娥。
独有荆王殿，时时暮雨过。','',''),('quantangshi-17821','送太和公主和蕃','楊巨源','quantangshi','','卷18','北路古来难，年光独认寒。
朔云侵鬓起，边月向眉残。
芦井寻沙到，花门度碛看。
薰风一万里，来处是长安。','',''),('quantangshi-17822','秋日韦少府厅池上咏石','楊巨源','quantangshi','','卷18','主人得幽石，日觉公堂清。
一片池上色，孤峰云外情。
旧溪红藓在，秋水绿痕生。
何必澄湖彻，移来有令名。','',''),('quantangshi-17823','失题','楊巨源','quantangshi','','卷18','何事慰朝夕，不逾诗酒情。
山河空道路，蕃汉共刀兵。
礼乐新朝市，园林旧弟兄。
向风一点泪，塞晚暮江平。','',''),('quantangshi-17824','春日题龙门香山寺','楊巨源','quantangshi','','卷18','众香天上梵王宫，钟磬寥寥半碧空。
清景乍开松岭月，乱流长响石楼风。
山河杳映春云外，城阙参差晓树中。
欲尽出寻那可得，三千世界本无穷。','',''),('quantangshi-17825','寄申州卢拱使君','楊巨源','quantangshi','','卷18','领郡仍闻总虎貔，致身还是见男儿。
小船隔水催桃叶，大鼓当风舞柘枝。
酒坐微酣诸客倒，球场慢拨几人随。
从来乐事憎诗苦，莫放窗中远岫知。','',''),('quantangshi-17826','郊居秋日酬奚赞府见寄','楊巨源','quantangshi','','卷18','繁菊照深居，芳香春不如。
闻寻周触士，知伴庾尚书。
日晚汀洲旷，天晴草木疎。
闲言挥麈柄，清步掩蜗庐。
野老能亲牧，高人念远渔。
幽丛临古岸，轻叶度寒渠。
暮色无狂蝶，秋华有嫩蔬。
若为酬郢曲，从此愧璠璵。','',''),('quantangshi-17827','圣恩洗雪镇州寄献裴相公','楊巨源','quantangshi','','卷18','天借春光洗绿林，战尘收尽见花阴。
好生本是君王德，忍死何妨壮士心。
曾贺截云翻栅远，仍闻劚冻下营深。
井陉昨日双旗入，萧相无言泪湿襟。','',''),('quantangshi-17828','贺田仆射子弟荣拜金吾','楊巨源','quantangshi','','卷18','五侯恩泽不同年，叔侄朱门䂍矟连。
凤沼九重相喜气，雁行一半入祥烟。
街衢烛影侵寒月，文武珂声叠晓天。
为数麒麟高阁上，谁家父子勒燕然。','',''),('quantangshi-17829','和裴舍人观田尚书出猎','楊巨源','quantangshi','','卷18','圣代司空比玉清，雄藩观猎见皇情。
云禽已觉高无益，霜兔应知狡不成。
飞鞚拥尘寒草尽，弯弓开月朔风生。
今朝始贺将军贵，紫禁诗人看斾旌。','',''),('quantangshi-17830','送李舍人归兰陵里','楊巨源','quantangshi','','卷18','清词举世皆藏箧，美酒当山为满罇。
三亩嫩蔬临绮陌，四行高树拥朱门。
家贫境胜心无累，名重官闲口不论。
惟有道情常自足，启期天地易知恩。','',''),('quantangshi-17831','同太常尉迟博士阙下待漏','楊巨源','quantangshi','','卷18','沈沈延阁抱丹墀，松色苔花颢露滋。
爽气晓来青玉甃，薰风宿在翠花旗。
方瞻御陌三条广，犹觉仙门一刻迟。
此地含香从白首，冯唐何事怨明时。','',''),('quantangshi-17832','见薛侍御戴不损裹帽子因赠','楊巨源','quantangshi','','卷18','潘郎对青镜，乌帽似新裁。
晓露鸦初洗，春荷叶半开。
堪将护巾栉，不独隔尘埃。
已见笼蝉翼，无因映鹿胎。
何人呈巧思，好手自西来。
有意怜衰丑，烦君致一枚。','',''),('quantangshi-17833','胡二十拜户部兼判度支','楊巨源','quantangshi','','卷18','清机果被公材挠，雄拜知承圣主恩。
庙略已调天府实，国征方觉地官尊。
徒言玉节将分阃，定是沙堤欲到门。
为爱山前新卜第，不妨风月事琴罇。','',''),('quantangshi-17834','元日呈李逢吉舍人','楊巨源','quantangshi','','卷18','华夷文物贺新年，霜仗遥排凤阙前。
一片彩霞迎曙日，万条红烛动春天。
称觞山色和元气，端冕炉香叠瑞烟。
共说正初当圣泽，试过西掖问羣贤。','',''),('quantangshi-17835','和杜中丞西禅院看花','楊巨源','quantangshi','','卷18','一林堆锦映千灯，照眼牵情欲不胜。
知倚晴明娇自足，解将颜色醉相仍。
好风轻引香烟入，甘露才和粉艳凝。
深处最怜莺蹂践，嬾时先被蝶侵凌。
对持真境应无取，分付空门又未能。
迎日似翻红烧断，临流疑映绮霞层。
幽含晚态怜丹桂，盛绩春光识紫藤。
每到花枝独惆怅，山东惟有杜中丞。','',''),('quantangshi-17836','句','楊巨源','quantangshi','','卷18','三刀梦益州，一箭取辽城。
伊陟无闻祖，韦贤不到孙。','',''),('quantangshi-17837','夏至日衡阳郡斋书怀','令狐楚','quantangshi','','卷18','一来江城守，七见江月圆。
齿发将六十，乡关越三千。
褰帷罕游观，闭合多沉眠。
新节还复至，故交尽相捐。
何时羾阊阖，上诉高高天。','',''),('quantangshi-17838','八月十七日夜书怀','令狐楚','quantangshi','','卷18','三五既不留，二八又还过。
金蟾着未出，玉树悲稍破。
谁向西园游，空归北堂卧。
佳期信难得，永夕无可奈。
抚枕独高歌，烦君为予和。','',''),('quantangshi-17839','九日言怀','令狐楚','quantangshi','','卷18','二九即重阳，天清野菊黄。
近来逢此日，多是在他乡。
晚色霞千片，秋声雁一行。
不能高处望，恐断老人肠。','',''),('quantangshi-17840','和寄窦七中丞','令狐楚','quantangshi','','卷18','仙吏秦峨别，新诗鄂渚来。
才推今北斗，职赋旧三台。
雕镂心偏许，缄封手自开。
何年相赠答，却得到中台。','',''),('quantangshi-17841','立秋日悲怀','令狐楚','quantangshi','','卷18','清晓上高台，秋风今日来。
又添新节恨，犹抱故年哀。
泪岂挥能尽，泉终闭不开。
更伤春月过，私服示无缞。','',''),('quantangshi-17842','秋怀寄钱侍郎','令狐楚','quantangshi','','卷18','晚岁俱为郡，新秋各异乡。
燕鸿一声呌，郢树尽青苍。
山霞侵衣润，江风卷簟凉。
相思如汉水，日夜向浔阳。','',''),('quantangshi-17843','立秋日','令狐楚','quantangshi','','卷18','平日本多恨，新秋偏易悲。
燕词如惜别，柳意已呈衰。
事国终无补，还家未有期。
心中旧气味，苦校去年时。','',''),('quantangshi-17844','赠毛仙翁','令狐楚','quantangshi','','卷18','宣州浑是上清宫，客有真人貌似童。
绀发垂缨光髧髧，细髯缘颔绿茸茸。
壶中药物梯霞诀，肘后方书缩地功。
既许焚香为弟子，愿敎年纪共椿同。','',''),('quantangshi-17845','游义兴寺寄上李逢吉相公','令狐楚','quantangshi','','卷18','柳营无事诣莲宫，步步犹疑是梦中。
劳役徒为万夫长，闲游曾与二人同。
凤鸾飞去仙巢在，龙象潜来讲席空。
松下花飞频伫立，一心千里忆梁公。','',''),('quantangshi-17846','游晋祠上李逢吉相公','令狐楚','quantangshi','','卷18','不立晋祠三十年，白头重到一凄然。
泉声自昔锵寒玉，草色虽秋耀翠钿。
少壮同游宁有数，尊荣再会便无缘。
相思临水下双泪，寄入并汾向洛川。','',''),('quantangshi-17847','节度宣武酬乐天梦得','令狐楚','quantangshi','','卷18','蓬莱仙监客曹郎，曾枉高车客大梁。
见拥旌旄治军旅，知亲笔砚事文章。
愁看柳色悬离恨，忆递花枝助酒狂。
洛下相逢肯相寄，南金璀错玉凄凉。','',''),('quantangshi-17848','奉和严司空重阳日同崔常侍崔郎及诸公登龙山落帽台佳宴','令狐楚','quantangshi','','卷18','谢公秋思渺天涯，蜡屐登高为菊花。
贵重近臣光绮席，笑怜从事落乌纱。
萸房暗绽红珠朵，茗碗寒供白露芽。
咏碎龙山归出号，马奔流电妓奔车。','',''),('quantangshi-17849','立春后言怀招汴州李匡衙推','令狐楚','quantangshi','','卷18','闲斋夜击唾壶歌，试望夷门奈远何。
每听塞笳离梦断，时窥清鉴旅愁多。
初惊宵漏丁丁促，已觉春风习习和。
海内故人君最老，花开鞭马更相过。','',''),('quantangshi-17850','奉和仆射相公酬忠武李相公见寄之作','令狐楚','quantangshi','','卷18','丽藻飞来自相庭，五文相错八音清。
初瞻绮色连霞色，又听金声继玉声。
才出山西文与武，欢从塞北弟兼兄。
白头老尹三川上，双和阳春喜复惊。','',''),('quantangshi-17851','郡斋左偏栽竹百余竿炎凉已周青翠不改而为墙垣所蔽有乖爱赏假日命去斋居之东墙由是俯临轩阶低映帷户日夕相对颇有翛然之趣','令狐楚','quantangshi','','卷18','斋居栽竹北窗边，素壁新开映碧鲜。
青蔼近当行药处，绿阴深到卧帷前。
风惊晓叶如闻雨，月过春枝似带烟。
老子忆山心暂缓，退公闲坐对婵娟。','',''),('quantangshi-17852','省中直夜对雪寄李师素侍郎','令狐楚','quantangshi','','卷18','密雪纷初降，重城杳未开。
杂花飞烂熳，连蝶舞徘徊。
洒散千株叶，销凝九陌埃。
素华凝粉署，清气绕霜台。
明觉侵窗积，寒知度塞来。
谢家争拟絮，越岭悞惊梅。
暗魄微茫照，严飙次第催。
稍封黄竹亚，先集紫兰摧。
孙室临书幌，梁园泛酒杯。
静怀琼树倚，醉忆玉山颓。
翠陌饥乌噪，苍云远雁哀。
此时方夜直，想望意悠哉。','',''),('quantangshi-17853','南宫夜直宿见李给事封题其所下制敕知奏直在东省因以诗寄','令狐楚','quantangshi','','卷18','番直同遥夜，严扃限几重。
青编书白雀，黄纸降苍龙。
北极丝纶句，东垣翰墨踪。
尚垂玄露点，犹湿紫泥封。
炫眼凝仙烛，驰心袅禁钟。
定应形梦寐，暂似接音容。
玉树春枝动，金樽腊酿醲。
在朝君最旧，休澣许过从。','',''),('quantangshi-17854','将赴洛下旅次汉南献上相公二十兄言怀八韵','令狐楚','quantangshi','','卷18','台室名曾继，旌门节暂过。
欢情老去少，苦事别离多。
便为开樽俎，应怜出网罗。
百忧今已失，一醉孰知他。
帝德千年日，君恩万里波。
许随黄绮辈，闲唱紫芝歌。
龙衮期重补，梅羹伫再和。
嵩丘来携手，君子意如何。','',''),('quantangshi-17855','青云干吕','令狐楚','quantangshi','','卷18','郁郁复纷纷，青霄干吕云。
色令天下见，候向管中分。
远覆无人境，遥彰有德君。
瑞容惊不散，冥感信稀闻。
湛露羞依草，南风耻带薰。
恭惟汉武帝，余烈尚氛氲。','',''),('quantangshi-17856','圣明乐','令狐楚','quantangshi','','卷18','海浪恬丹徼，边尘静异山。
从今万里外，不复锁萧关。','',''),('quantangshi-17857','春闺思','令狐楚','quantangshi','','卷18','戴胜飞晴野，凌澌下浊河。
春风楼上望，谁见泪痕多。','',''),('quantangshi-17858','宫中乐五首 一','令狐楚','quantangshi','','卷18','楚塞金陵靖，巴山玉垒空。
万方无一事，端拱大明宫。','',''),('quantangshi-17859','宫中乐五首 二','令狐楚','quantangshi','','卷18','雪霁长杨苑，冰开太液池。
宫中行乐日，天下盛明时。','',''),('quantangshi-17860','宫中乐五首 三','令狐楚','quantangshi','','卷18','柳色烟相似，梨花雪不如。
春风真有意，一一丽皇居。','',''),('quantangshi-17861','宫中乐五首 四','令狐楚','quantangshi','','卷18','月上宫花静，烟含苑树深。
银台门已闭，仙漏夜沉沉。','',''),('quantangshi-17862','宫中乐五首 五','令狐楚','quantangshi','','卷18','九重青琐闼，百尺碧云楼。
明月秋风起，珠帘上玉钩。','',''),('quantangshi-17863','春游曲三首 一','令狐楚','quantangshi','','卷18','晓游临碧殿，日上望春亭。
芳树罗仙仗，晴山展翠屏。','',''),('quantangshi-17864','春游曲三首 二','令狐楚','quantangshi','','卷18','一夜好风吹，新花一万枝。
风前调玉管，花下簇金羁。','',''),('quantangshi-17865','春游曲三首 三','令狐楚','quantangshi','','卷18','阊阖春风起，蓬莱雪水消。
相将折杨柳，争取最长条。','',''),('quantangshi-17866','远别离二首 一','令狐楚','quantangshi','','卷18','杨柳黄金穗，梧桐碧玉枝。
春来消息断，早晚是归期。','',''),('quantangshi-17867','远别离二首 二','令狐楚','quantangshi','','卷18','玳织鸳鸯履，金装翡翠篸。
畏人相问着，不拟到城南。','',''),('quantangshi-17868','闺人赠远二首 一','令狐楚','quantangshi','','卷18','君行登陇上，妾梦在闺中。
玉筯千行落，银牀一半空。','',''),('quantangshi-17869','闺人赠远二首 二','令狐楚','quantangshi','','卷18','绮席春眠觉，纱窗晓望迷。
朦胧残梦里，犹自在辽西。','',''),('quantangshi-17870','从军词五首 一','令狐楚','quantangshi','','卷18','荒鸡隔水啼，汗马逐风嘶。
终日随征斾，何时罢鼓鼙。','',''),('quantangshi-17871','从军词五首 二','令狐楚','quantangshi','','卷18','孤心眠夜雪，满眼是秋沙。
万里犹防塞，三年不见家。','',''),('quantangshi-17872','从军词五首 三','令狐楚','quantangshi','','卷18','却望冰河阔，前登雪岭高。
征人几多在，又拟战临洮。','',''),('quantangshi-17873','从军词五首 四','令狐楚','quantangshi','','卷18','胡风千里惊，汉月五更明。
纵有还家梦，犹闻出塞声。','',''),('quantangshi-17874','从军词五首 五','令狐楚','quantangshi','','卷18','暮雪连青海，阴霞覆白山。
可怜班定远，生入玉门关。','',''),('quantangshi-17875','思君恩','令狐楚','quantangshi','','卷18','小苑莺歌歇，长门蝶舞多。
眼看春又去，翠辇不经过。','',''),('quantangshi-17876','王昭君','令狐楚','quantangshi','','卷18','锦车天外去，毳幕雪中开。
魏阙苍龙远，萧关赤雁哀。','',''),('quantangshi-17877','发潭州寄李宁常侍','令狐楚','quantangshi','','卷18','君今侍紫垣，我已堕青天。
委废从兹日，旋归在几年。
心为西靡树，眼是北流泉。
更过长沙去，江风满驿船。','',''),('quantangshi-17878','李相薨后题断金集','令狐楚','quantangshi','','卷18','一览断金集，载悲埋玉人。
牙弦千古绝，珠泪万行新。','',''),('quantangshi-17879','年少行四首 一','令狐楚','quantangshi','','卷18','少小边州惯放狂，骣骑蕃马射黄羊。
如今年老无筋力，犹倚营门数雁行。','',''),('quantangshi-17880','年少行四首 二','令狐楚','quantangshi','','卷18','家本清河住五城，须凭弓箭得功名。
等闲飞鞚秋原上，独向寒云试射声。','',''),('quantangshi-17881','年少行四首 三','令狐楚','quantangshi','','卷18','弓背霞明劒照霜，秋风走马出咸阳。
未收天子河湟地，不拟回头望故乡。','',''),('quantangshi-17882','年少行四首 四','令狐楚','quantangshi','','卷18','霜满中庭月满楼，金樽玉柱对清秋。
当年称意须行乐，不到天明不肯休。','',''),('quantangshi-17883','塞下曲二首 一','令狐楚','quantangshi','','卷18','雪满衣裳冰满须，晓随飞将伐单于。
平生意气今何在，把得家书泪似珠。','',''),('quantangshi-17884','塞下曲二首 二','令狐楚','quantangshi','','卷18','边草萧条塞雁飞，征人南望泪沾衣。
黄尘满面长须战，白发生头未得归。','',''),('quantangshi-17885','游春词','令狐楚','quantangshi','','卷18','高楼晓见一花开，便觉春光四面来。
暖日晴云知次第，东风不用更相催。','',''),('quantangshi-17886','汉苑行','令狐楚','quantangshi','','卷18','云霞五采浮天阙，梅柳千般夹御沟。
不上黄花南北望，岂知春色满神州。','',''),('quantangshi-17887','中元日赠张尊师','令狐楚','quantangshi','','卷18','偶来人世值中元，不献玄都永日闲。
寂寂焚香在仙观，知师遥礼玉京山。','',''),('quantangshi-17888','赴东都别牡丹','令狐楚','quantangshi','','卷18','十年不见小庭花，紫萼临开又别家。
上马出门回首望，何时更得到京华。','',''),('quantangshi-17889','寄礼部刘郎中','令狐楚','quantangshi','','卷18','一别三年在上京，仙垣终日选羣英。
除书每下皆先看，唯有刘郎无姓名。','',''),('quantangshi-17890','坐中闻思帝乡有感','令狐楚','quantangshi','','卷18','年年不见帝乡春，白日寻思夜梦频。
上酒忽闻吹此曲，坐中惆怅更何人。','',''),('quantangshi-17891','春思寄梦得乐天','令狐楚','quantangshi','','卷18','花满中庭酒满樽，平明独坐到黄昏。
春来诗思偏何处，飞过函关入鼎门。','',''),('quantangshi-17892','皇城中花园讥刘白赏春不及','令狐楚','quantangshi','','卷18','五凤楼西花一园，低枝小树尽芳繁。
洛阳才子何曾爱，下马贪趋广运门。','',''),('quantangshi-17893','相思河','令狐楚','quantangshi','','卷18','谁把相思号比河，塞垣车马往来多。
只应自古征人泪，洒向空洲作碧波。','',''),('quantangshi-17894','三月晦日会李员外座中频以老大不醉见讥因有此赠','令狐楚','quantangshi','','卷18','三月唯残一日春，玉山倾倒白鸥驯。
不辞便学山公醉，花下无人作主人。','',''),('quantangshi-17895','赋山','令狐楚','quantangshi','','卷18','山，耸峻，回环。
沧海上，白云间。
商老深寻，谢公远攀。
古岩泉滴滴，幽谷鸟关关。
树岛西连陇塞，猨声南彻荆蛮。
世人只向簪裾老，芳草空余麋鹿闲。','',''),('quantangshi-17896','句','令狐楚','quantangshi','','卷18','何日居三署，终年尾百僚。
移石几回敲废印，开箱何处送新图。
唯应四仲祭，使者暂悲嗟。
偶逢蒲家郎，乃是葛仙客。
行常乘青竹，饥即煮白石。
腰间嫌大组，心内保尺宅。
我愿从之游，深卜炼上液。','',''),('quantangshi-17897','享惠昭太子庙乐章','裴度','quantangshi','','卷18','重轮始发祥，齿胄方兴学。
冥然升紫府，铿尔荐清乐。
奠斝致馨香，在庭纷羽龠。
礼成神既醉，仿髴缑山鹤。','',''),('quantangshi-17898','夏日对雨','裴度','quantangshi','','卷18','登楼逃盛夏，万象正埃尘。
对面雷嗔树，当街雨趁人。
檐疎蛛网重，地湿燕泥新。
吟罢清风起，荷香满四邻。','',''),('quantangshi-17899','白二十二侍郎有双鹤留在洛下予西园多野水长松可以栖息遂以诗请之','裴度','quantangshi','','卷18','闻君有双鹤，羁旅洛城东。
未放归仙去，何如乞老翁。
且将临野水，莫闭在樊笼。
好是长鸣处，西园白露中。','',''),('quantangshi-17900','窦七中丞见示初至夏口献元戎诗辄戏和之','裴度','quantangshi','','卷18','出佐青油幕，来吟白雪篇。
须为九臯鹤，莫上五湖船。
故态君应在，新诗我亦便。
元侯看再入，好被暂流连。','',''),('quantangshi-17901','酬张秘书因寄马赠诗','裴度','quantangshi','','卷18','满城驰逐皆求马，古寺闲行独与君。
代步本慙非逸足，缘情何幸枉高文。
若逢佳丽从将换，莫共驽骀角出羣。
飞控着鞭能顾我，当时王粲亦从军。','',''),('quantangshi-17902','真慧寺','裴度','quantangshi','','卷18','遍寻真迹蹑莓苔，世事全抛不忍回。
上界不知何处去，西天移向此间来。
岩前芍药师亲种，岭上青松佛手栽。
更有一般人不见，白莲花向半天开。','',''),('quantangshi-17903','中书即事','裴度','quantangshi','','卷18','有意效承平，无功答圣明。
灰心缘忍事，霜鬓为论兵。
道直身还在，恩深命转轻。
盐梅非拟议，葵藿是平生。
白日长悬照，苍蝇谩发声。
高阳旧田里，终使谢归耕。','',''),('quantangshi-17904','中和节诏赐公卿尺','裴度','quantangshi','','卷18','阳和行庆赐，尺度及羣公。
荷宠承佳节，倾心立大中。
短长思合制，远近贵攸同。
共仰财成德，将酬分寸功。
作程施有政，垂范播无穷。
愿续南山寿，千春奉圣躬。','',''),('quantangshi-17905','至日登乐游园','裴度','quantangshi','','卷18','阴律随寒改，阳和应节生。
祥云观魏阙，瑞气映秦城。
验炭论时政，书云受岁盈。
晷移长日至，雾敛远霄清。
景暖仙梅动，风柔御柳倾。
那堪封得意，空对物华情。','',''),('quantangshi-17906','奉酬中书相公至日圆丘摄事合于中书后阁宿斋移止于集贤院叙怀见寄之作','裴度','quantangshi','','卷18','翼亮登三命，谟猷本一心。
致斋移秘府，祗事见冲襟。
皓月当延阁，祥风自禁林。
相庭方积玉，王度已如金。
运偶唐虞盛，情同丙魏深。
幽兰与白雪，何处寄庸音。','',''),('quantangshi-17907','太原题厅壁','裴度','quantangshi','','卷18','危事经非一，浮荣得是空。
白头官舍里，今日又春风。','',''),('quantangshi-17908','溪居','裴度','quantangshi','','卷18','门径俯清溪，茅檐古木齐。
红尘飘不到，时有水禽[啼]。','',''),('quantangshi-17909','喜遇刘二十八','裴度','quantangshi','','卷18','病来佳兴少，老去旧游稀。
笑语纵横作，杯觞络绎飞。','',''),('quantangshi-17910','送刘','裴度','quantangshi','','卷18','不归丹掖去，铜竹漫云云。
惟喜因过我，须知未贺君。','',''),('quantangshi-17911','再送','裴度','quantangshi','','卷18','顷来多谑浪，此夕任喧纷。
故态犹应在，行期未要闻。','',''),('quantangshi-17912','凉风亭睡觉','裴度','quantangshi','','卷18','饱食缓行新睡觉，一瓯新茗侍儿煎。
脱巾斜倚绳牀坐，风送水声来耳边。','',''),('quantangshi-17913','雪中讶诸公不相访','裴度','quantangshi','','卷18','忆昨雨多泥又深，犹能携妓远过寻。
满空乱雪花相似，何事居然无赏心。','',''),('quantangshi-17914','傍水闲行','裴度','quantangshi','','卷18','闲余何处觉身轻，暂脱朝衣傍水行。
鸥鸟亦知人意静，故来相近不相惊。','',''),('quantangshi-17915','句','裴度','quantangshi','','卷18','两人同日事征西，今日君先奉紫泥。
待平贼垒报天子，莫指仙山示武夫。
野人不识中书令，唤作陶家与谢家。
君若有心求逸足，我还留意在名姝。','',''),('quantangshi-17916','元和圣德诗','韓愈','quantangshi','','卷18','皇帝即阼，物无违拒。
曰阳而阳，曰雨而雨。
维是元年，有盗在夏。
欲覆其州，以踵近武。
皇帝曰嘻，岂不在我。
负鄙为艰，纵则不可。
出师征之，其众十旅。
军其城下，告以福祸。
腹败枝披，不敢保聚。
掷首陴外，降幡夜竖。
疆外之险，莫过蜀土。
韦臯去镇，刘辟守后。
血人于牙，不肯吐口。
开库啖士，曰随所取。
汝张汝弓，汝鼓汝鼓。
汝为表书，求我帅汝。
事始上闻，在列咸怒。
皇帝曰然，嗟远士女。
苟附而安，则且付与。
读命于庭，出节少府。
朝发京师，夕至其部。
辟喜谓党，汝振而伍。
蜀可全有，此不当受。
万牛脔炙，万瓮行酒。
以锦缠股，以红帕首。
有恇其凶，有饵其诱。
其出穰穰，队以万数。
遂劫东川，遂据城阻。
皇帝曰嗟，其又可许。
爰命崇文，分卒禁御。
有安其驱，无暴我野。
日行三十，徐壁其右。
辟党聚谋，鹿头是守。
崇文奉诏，进退规矩。
战不贪杀，擒不滥数。
四方节度，整兵顿马。
上章请讨，俟命起坐。
皇帝曰嘻，无汝烦苦。
荆并洎梁，在国门户。
出师三千，各选尔丑。
四军齐作，殷其如阜。
或拔其角，或脱其距。
长驱洋洋，无有龃龉。
八月壬午，辟弃城走。
载妻与妾，包裹稚乳。
是日崇文，入处其宇。
分散逐捕，搜原剔薮。
辟穷见窘，无地自处。
俯视大江，不见洲渚。
遂自颠倒，若杵投臼。
取之江中，枷脰械手。
妇女累累，啼哭拜叩。
来献阙下，以告庙社。
周示城市，咸使观覩。
解脱挛索，夹以砧斧。
婉婉弱子，赤立伛偻。
牵头曳足，先断腰膂。
次及其徒，体骸撑拄。
末乃取辟，骇汗如写。
挥刀纷纭，争刌脍脯。
优赏将吏，扶圭缀组。
帛堆其家，粟塞其庾。
哀怜阵没，廪给孤寡。
赠官封墓，周帀宏溥。
经战伐地，宽免租簿。
施令酬功，急疾如火。
天地中间，莫不顺序。
幽恒青魏，东尽海浦。
南至徐蔡，区外杂虏。
怛威赧德，踧踖蹈舞。
掉弃兵革，私习簋簠。
来请来觐，十百其耦。
皇帝曰吁，伯父叔舅。
各安尔位，训厥甿畮。
正月元日，初见宗祖。
躬执百礼，登降拜俯。
荐于新宫，视瞻梁梠。
戚见容色，泪落入俎。
侍祠之臣，助我恻楚。
乃以上辛，于郊用牡。
除于国南，鳞笋毛簴。
庐幕周施，开揭磊砢。
兽盾腾挐，圆坛帖妥。
天兵四罗，旗常婀娜。
驾龙十二，鱼鱼雅雅。
宵升于丘，奠璧献斝。
众乐惊作，轰豗融冶。
紫焰嘘呵，高灵下堕。
羣星从坐，错落侈哆。
日君月妃，焕赫婐㛂。
渎鬼蒙鸿，岳祗嶪峩。
饫沃膻芗，产祥降嘏。
凤皇应奏，舒翼自拊。
赤麟黄龙，逶陀结纠。
卿士庶人，黄童白叟。
踊跃欢呀，失喜噎欧。
干清坤夷，境落褰举。
帝车回来，日正当午。
幸丹凤门，大赦天下。
涤濯刬磢，磨灭瑕垢。
续功臣嗣，拔贤任耉。
孩养无告，仁滂施厚。
皇帝神圣，通达今古。
听聪视明，一似尧禹。
生知法式，动得理所。
天锡皇帝，为天下主。
并包畜养，无异细钜。
亿载万年，敢有违者。
皇帝俭勤，盥濯陶瓦。
斥遣浮华，好此绨紵。
勅戒四方，侈则有咎。
天锡皇帝，多麦与黍。
无召水旱，耗于雀鼠。
亿载万年，有富无窭。
皇帝正直，别白善否。
擅命而狂，既翦既去。
尽逐羣奸，靡有遗侣。
天锡皇帝，厖臣硕辅。
博问遐观，以置左右。
亿载万年，无敢余侮。
皇帝大孝，慈祥悌友。
怡怡愉愉，奉太皇后。
浃于族亲，濡及九有。
天锡皇帝，与天齐寿。
登兹太平，无怠永久。
亿载万年，为父为母。
博士臣愈，职是训诂。
作为歌诗，以配吉甫。','',''),('quantangshi-17917','琴操十首','韓愈','quantangshi','','卷18','秋之水兮，其色幽幽。
我将济兮，不得其由。
涉其浅兮，石啮我足。
乘其深兮，龙入我舟。
我济而悔兮，将安归尤。
归兮归兮，无与石鬬兮，无应龙求。','',''),('quantangshi-17918','琴操十首','韓愈','quantangshi','','卷18','兰之猗猗，扬扬其香。
不采而佩，于兰何伤。
今天之旋，其曷为然。
我行四方，以日以年。
雪霜贸贸，荠麦之茂。
子如不伤，我不尔觏。
荠麦之茂，荠麦之有。
君子之伤，君子之守。','',''),('quantangshi-17919','琴操十首','韓愈','quantangshi','','卷18','龟之氛兮，不能云雨。
龟之枿兮，不中梁柱。
龟之大兮，祗以奄鲁。
知将隳兮，哀莫余伍。
周公有鬼兮，嗟余归辅。','',''),('quantangshi-17920','琴操十首','韓愈','quantangshi','','卷18','雨之施物以孳，我何意于彼为。
自周之先，其艰其勤。
以有疆宇，私我后人。
我祖在上，四方在下。
厥临孔威，敢戏以侮。
孰荒于门，孰治于田。
四海既均，越裳是臣。','',''),('quantangshi-17921','琴操十首','韓愈','quantangshi','','卷18','目窈窈兮，其凝其盲。
耳肃肃兮，听不闻声。
朝不日出兮，夜不见月与星。
有知无知兮，为死为生。
呜呼！臣罪当诛兮，天王圣明。','',''),('quantangshi-17922','琴操十首','韓愈','quantangshi','','卷18','我家于豳，自我先公。
伊我承序，敢有不同。
今狄之人，将土我疆。
民为我战，谁使死伤。
彼岐有岨，我往独处。
尔莫余追，无思我悲。','',''),('quantangshi-17923','琴操十首','韓愈','quantangshi','','卷18','父兮儿寒，母兮儿饥。
儿罪当笞，逐儿何为。
儿在中野，以宿以处。
四无人声，谁与儿语。
儿寒何衣，儿饥何食。
儿行于野，履霜以足。
母生众儿，有母怜之。
独无母怜，儿宁不悲。','',''),('quantangshi-17924','琴操十首','韓愈','quantangshi','','卷18','雉之飞，于朝日。
羣雌孤雄，意气横出。
当东而西，当啄而飞。
随飞随啄，羣雌粥粥。
嗟我虽人，曾不如彼雉鸡。
生身七十年，无一妾与妃。','',''),('quantangshi-17925','琴操十首','韓愈','quantangshi','','卷18','雄鹄衔枝来，雌鹄啄泥归。
巢成不生子，大义当乖离。
江汉水之大，鹄身鸟之微。
更无相逢日，且可绕树相随飞。','',''),('quantangshi-17926','琴操十首','韓愈','quantangshi','','卷18','有兽维狸兮，我梦得之。
其身孔明兮，而头不知。
吉凶何为兮，觉坐而思。
巫咸上天兮，识者其谁。','',''),('quantangshi-17927','南山诗','韓愈','quantangshi','','卷18','吾闻京城南，兹惟羣山囿。
东西两际海，巨细难悉究。
山经及地志，茫昧非受授。
团辞试提挈，挂一念万漏。
欲休谅不能，粗叙所经觏。
尝升崇丘望，戢戢见相凑。
晴明出棱角，缕脉碎分绣。
蒸岚相澒洞，表里忽通透。
无风自飘簸，融液煦柔茂。
横云时平凝，点点露数岫。
天空浮修眉，浓绿画新就。
孤撑有巉绝，海浴褰鹏噣。
春阳潜沮洳，濯濯吐深秀。
岩峦虽嵂崒，软弱类含酎。
夏炎百木盛，荫郁增埋覆。
神灵日歊歔，云气争结构。
秋霜喜刻轹，磔卓立癯瘦。
参差相叠重，刚耿陵宇宙。
冬行虽幽墨，冰雪工琢镂。
新曦照危峨，亿丈恒高袤。
明昏无停态，顷刻异状候。
西南雄太白，突起莫间簉。
藩都配德运，分宅占丁戊。
逍遥越坤位，诋讦陷干窦。
空虚寒兢兢，风气较搜漱。
朱维方烧日，阴霰纵腾糅。
昆明大池北，去觌偶晴昼。
緜联穷俯视，倒侧困清沤。
微澜动水面，踊跃躁猱狖。
惊呼惜破碎，仰喜呀不仆。
前寻径杜墅，岔蔽毕原陋。
崎岖上轩昂，始得观览富。
行行将遂穷，岭陆烦互走。
勃然思坼裂，拥掩难恕宥。
巨灵与夸蛾，远贾期必售。
还疑造物意，固护蓄精佑。
力虽能排斡，雷电怯呵诟。
攀缘脱手足，蹭蹬抵积甃。
茫如试矫首，堛塞生怐愗。
威容丧萧爽，近新迷远旧。
拘官计日月，欲进不可又。
因缘窥其湫，凝湛閟阴嘼。
鱼虾可俯掇，神物安敢寇。
林柯有脱叶，欲堕鸟惊救。
争衔弯环飞，投弃急哺鷇。
旋归道回睨，达枿壮复奏。
吁嗟信奇怪，峙质能化贸。
前年遭谴谪，探历得邂逅。
初从蓝田入，顾盻劳颈脰。
时天晦大雪，泪目苦蒙瞀。
峻涂拖长冰，直上若悬溜。
褰衣步推马，颠蹶退且复。
苍黄忘遐睎，所瞩才左右。
杉篁咤蒲苏，杲耀攒介胄。
专心忆平道，脱险逾避臭。
昨来逢清霁，宿愿忻始副。
峥嵘跻冢顶，倏闪杂鼯鼬。
前低划开阔，烂漫堆众皱。
或连若相从，或蹙若相鬬。
或妥若弭伏，或竦若惊雊。
或散若瓦解，或赴若辐凑。
或翩若船游，或决若马骤。
或背若相恶，或向若相佑。
或乱若抽笋，或嵲若注灸。
或错若绘画，或缭若篆籀。
或罗若星离，或蓊若云逗。
或浮若波涛，或碎若锄耨。
或如贲育伦，赌胜勇前购。
先强势已出，后钝嗔䛠譳。
或如帝王尊，丛集朝贱幼。
虽亲不亵狎，虽远不悖谬。
或如临食案，肴核纷飣餖。
又如游九原，坟墓包椁柩。
或累若盆甖，或揭若㽅豆。
或覆若曝鼈，或颓若寝兽。
或蜿若藏龙，或翼若搏鹫。
或齐若友朋，或随若先后。
或迸若流落，或顾若宿留。
或戾若仇讐，或密若婚媾。
或俨若峩冠，或翻若舞袖。
或屹若战阵，或围若搜狩。
或靡然东注，或偃然北首。
或如火熺焰，或若气饙馏。
或行而不辍，或遗而不收。
或斜而不倚，或弛而不彀。
或赤若秃鬝，或熏若柴槱。
或如龟拆兆，或若卦分繇。
或前横若剥，或后断若姤。
延延离又属，夬夬叛还遘。
喁喁鱼闯萍，落落月经宿。
誾誾树墙垣，巘巘驾库厩。
参参削剑戟，焕焕衔莹琇。
敷敷花披萼，闟闟屋摧溜。
悠悠舒而安，兀兀狂以狃。
超超出犹奔，蠢蠢骇不懋。
大哉立天地，经纪肖营腠。
厥初孰开张，僶俯谁劝侑。
创兹朴而巧，戮力忍劳疚。
得非施斧斤，无乃假诅咒。
鸿荒竟无传，功大莫酬僦。
尝闻于祠官，芬苾降歆嗅。
斐然作歌诗，惟用赞报酭。','',''),('quantangshi-17928','谢自然诗','韓愈','quantangshi','','卷18','果州南充县，寒女谢自然。
童呆无所识，但闻有神仙。
轻生学其术，乃在金泉山。
繁华荣慕绝，父母慈爱捐。
凝心感魑魅，慌惚难具言。
一朝坐空室，云雾生其间。
如聆笙竽韵，来自冥冥天。
白日变幽晦，萧萧风景寒。
檐楹蹔明灭，五色光属联。
观者徒倾骇，踯躅讵敢前。
须臾自轻举，飘若风中烟。
茫茫八纮大，影响无由缘。
里胥上其事，郡守惊且叹。
驱车领官吏，甿俗争相先。
入门无所见，冠履同蜕蝉。
皆云神仙事，灼灼信可传。
余闻古夏后，象物知神奸。
山林民可入，魍魉莫逢旃。
逶迤不复振，后世恣欺谩。
幽明纷杂乱，人鬼更相残。
秦皇虽笃好，汉武洪其源。
自从二主来，此祸竟连连。
木石生怪变，狐狸骋妖患。
莫能尽性命，安得更长延。
人生处万类，知识最为贤。
奈何不自信，反欲从物迁。
往者不可悔，孤魂抱深冤。
来者犹可诫，余言岂空文。
人生有常理，男女各有伦。
寒衣及饥食，在纺绩耕耘。
下以保子孙，上以奉君亲。
苟异于此道，皆为弃其身。
噫乎彼寒女，永托异物羣。
感伤遂成诗，昧者宜书绅。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-17929','秋怀诗十一首 一','韓愈','quantangshi','','卷18','窗前两好树，众叶光薿薿。
秋风一拂披，策策鸣不已。
微灯照空牀，夜半偏入耳。
愁忧无端来，感叹成坐起。
天明视颜色，与故不相似。
羲和驱日月，疾急不可恃。
浮生虽多涂，趋死惟一轨。
胡为浪自苦，得酒且欢喜。','',''),('quantangshi-17930','秋怀诗十一首 二','韓愈','quantangshi','','卷18','白露下百草，萧兰共雕悴。
青青四墙下，已复生满地。
寒蝉暂寂寞，蟋蟀鸣自恣。
运行无穷期，禀受气苦异。
适时各得所，松栢不必贵。','',''),('quantangshi-17931','秋怀诗十一首 三','韓愈','quantangshi','','卷18','彼时何卒卒，我志何曼曼。
犀首空好饮，廉颇尚能饭。
学堂日无事，驱马适所愿。
茫茫出门路，欲去聊自劝。
归还阅书史，文字浩千万。
陈迹竟谁寻，贱嗜非贵献。
丈夫意有在，女子乃多怨。','',''),('quantangshi-17932','秋怀诗十一首 四','韓愈','quantangshi','','卷18','秋气日恻恻，秋空日凌凌。
上无枝上蜩，下无盘中蝇。
岂不感时节，耳目去所憎。
清晓卷书坐，南山见高棱。
其下澄湫水，有蛟寒可罾。
惜哉不得往，岂谓吾无能。','',''),('quantangshi-17933','秋怀诗十一首 五','韓愈','quantangshi','','卷18','离离挂空悲，戚戚抱虚警。
露泫秋树高，虫吊寒夜永。
歛退就新懦，趋营悼前猛。
归愚识夷涂，汲古得修绠。
名浮犹有耻，味薄真自幸。
庶几遗悔尤，即此是幽屏。','',''),('quantangshi-17934','秋怀诗十一首 六','韓愈','quantangshi','','卷18','今晨不成起，端坐尽日景。
虫鸣室幽幽，月吐窗冏冏。
丧怀若迷方，浮念剧含梗。
尘埃慵伺候，文字浪驰骋。
尚须勉其顽，王事有朝请。','',''),('quantangshi-17935','秋怀诗十一首 七','韓愈','quantangshi','','卷18','秋夜不可晨，秋日苦易暗。
我无汲汲志，何以有此憾。
寒鸡空在栖，缺月烦屡瞰。
有琴具徽弦，再鼓听愈淡。
古声久埋灭，无由见真滥。
低心逐时趋，苦勉祗能暂。
有如乘风船，一纵不可缆。
不如覰文字，丹铅事点勘。
岂必求赢余，所要石与甔。','',''),('quantangshi-17936','秋怀诗十一首 八','韓愈','quantangshi','','卷18','卷卷落地叶，随风走前轩。
鸣声若有意，颠倒相追奔。
空堂黄昏暮，我坐默不言。
童子自外至，吹灯当我前。
问我我不应，馈我我不餐。
退坐西壁下，读诗尽数编。
作者非今士，相去时已千。
其言有感触，使我复凄酸。
愿谓汝童子，置书且安眠。
丈夫属有念，事业无穷年。','',''),('quantangshi-17937','秋怀诗十一首 九','韓愈','quantangshi','','卷18','霜风侵梧桐，众叶着树干。
空堦一片下，琤若摧琅玕。
谓是夜气灭，望舒霣其团。
青冥无依倚，飞辙危难安。
惊起出户视，倚楹久丸澜。
忧愁费晷景，日月如跳丸。
迷复不计远，为君驻尘鞍。','',''),('quantangshi-17938','秋怀诗十一首 十','韓愈','quantangshi','','卷18','暮暗来客去，羣嚣各收声。
悠悠偃宵寂，斖斖抱秋明。
世累忽进虑，外忧遂侵诚。
强怀张不满，弱念缺已盈。
诘屈避语穽，冥茫触心兵。
败虞千金弃，得比寸草荣。
知耻足为勇，晏然谁汝令。','',''),('quantangshi-17939','秋怀诗十一首 十一','韓愈','quantangshi','','卷18','鲜鲜霜中菊，既晚何用好。
扬扬弄芳蝶，尔生还不早。
运穷两值遇，婉娈死相保。
西风蛰龙蛇，众木日凋槁。
由来命分尔，泯灭岂足道。','',''),('quantangshi-17940','赴江陵途中寄赠王二十补阙李十一拾遗李二十六员外翰林三学士','韓愈','quantangshi','','卷18','孤臣昔放逐，血泣追愆尤。
汗漫不省识，怳如乘桴浮。
或自疑上疏，上疏岂其由。
是年京师旱，田亩少所收。
上怜民无食，征赋半已休。
有司恤经费，未免烦征求。
富者既云急，贫者固已流。
传闻闾里间，赤子弃渠沟。
持男易斗粟，掉臂莫肯酬。
我时出衢路，饿者何其稠。
亲逢道边死，伫立久咿嚘。
归舍不能食，有如鱼中钩。
适会除御史，诚当得言秋。
拜疏移合门，为忠宁自谋。
上陈人疾苦，无令绝其喉。
下陈畿甸内，根本理宜优。
积雪騐丰熟，幸宽待蚕麰。
天子恻然感，司空叹绸缪。
谓言即施设，乃反迁炎州。
同官尽才俊，偏善柳与刘。
或虑语言泄，传之落冤讐。
二子不宜尔，将疑断还不。
中使临门遣，顷刻不得留。
病妹卧牀褥，分知隔明幽。
悲啼乞就别，百请不颔头。
弱妻抱稚子，出拜忘惭羞。
僶俛不回顾，行行诣连州。
朝为青云士，暮作白头囚。
商山季冬月，冰冻绝行輈。
春风洞庭浪，出没惊孤舟。
逾岭到所任，低颜奉君侯。
酸寒何足道，随事生疮疣。
远地触途异，吏民似猨猴。
生狞多忿很，辞舌纷嘲啁。
白日屋檐下，双鸣鬬鸺鶹。
有蛇类两首，有蛊羣飞游。
穷冬或摇扇，盛夏或重裘。
飓起最可畏，訇哮簸陵丘。
雷霆助光怪，气象难比侔。
疠疫忽潜遘，十家无一瘳。
猜嫌动置毒，对案輙怀愁。
前日遇恩赦，私心喜还忧。
果然又羁絷，不得归锄耰。
此府雄且大，腾凌尽戈矛。
栖栖法曹掾，何处事卑陬。
生平企仁义，所学皆孔周。
早知大理官，不列三后俦。
何况亲犴狱，敲搒发奸偷。
悬知失事势，恐自罹罝罘。
湘水清且急，凉风日修修。
胡为首归路，旅泊尚夷犹。
昨者京使至，嗣皇传冕旒。
赫然下明诏，首罪诛共吺。
复闻颠夭辈，峨冠进鸿畴。
班行再肃穆，璜佩鸣琅璆。
伫继贞观烈，边封脱兜鍪。
三贤推侍从，卓荦倾枚邹。
高议参造化，清文焕皇猷。
协心辅齐圣，致理同毛輶。
小雅咏鹿鸣，食苹贵呦呦。
遗风邈不嗣，岂忆尝同裯。
失志早衰换，前期拟蜉蝣。
自从齿牙缺，始慕舌为柔。
因疾鼻又塞，渐能等薰莸。
深思罢官去，毕命依松楸。
空怀焉能果，但见岁已遒。
殷汤闵禽兽，解网祝蛛蝥。
雷焕掘宝剑，冤氛消斗牛。
兹道诚可尚，谁能借前筹。
殷勤答吾友，明月非暗投。','',''),('quantangshi-17941','暮行河堤上','韓愈','quantangshi','','卷18','暮行河堤上，四顾不见人。
衰草际黄云，感叹愁我神。
夜归孤舟卧，展转空及晨。
谋计竟何就，嗟嗟世与身。','',''),('quantangshi-17942','夜歌','韓愈','quantangshi','','卷18','静夜有清光，闲堂仍独息。
念身幸无恨，志气方自得。
乐哉何所忧，所忧非我力。','',''),('quantangshi-17943','重云李观疾赠之','韓愈','quantangshi','','卷18','天行失其度，阴气来干阳。
重云闭白日，炎燠成寒凉。
小人但咨怨，君子惟忧伤。
饮食为减少，身体岂宁康。
此志诚足贵，惧非职所当。
藜羹尚如此，肉食安可尝。
穷冬百草死，幽桂乃芬芳。
且况天地间，大运自有常。
劝君善饮食，鸾凤本高翔。','',''),('quantangshi-17944','江汉答孟郊','韓愈','quantangshi','','卷18','江汉虽云广，乘舟渡无艰。
流沙信难行，马足常往还。
凄风结冲波，狐裘能御寒。
终宵处幽室，华烛光烂烂。
苟能行忠信，可以居夷蛮。
嗟余与夫子，此义每所敦。
何为复见赠，缱绻在不谖。','',''),('quantangshi-17945','长安交游者赠孟郊','韓愈','quantangshi','','卷18','长安交游者，贫富各有徒。
亲朋相过时，亦各有以娱。
陋室有文史，高门有笙竽。
何能辨荣悴，且欲分贤愚。','',''),('quantangshi-17946','岐山下二首 一','韓愈','quantangshi','','卷18','谁谓我有耳，不闻凤皇鸣。
朅来岐山下，日暮边鸿惊。','',''),('quantangshi-17947','岐山下二首 二','韓愈','quantangshi','','卷18','丹穴五色羽，其名为凤皇。
昔周有盛德，此鸟鸣高冈。
和声随祥风，窅窕相飘扬。
闻者亦何事，但知时俗康。
自从公旦死，千载閟其光。
吾君亦勤理，迟尔一来翔。','',''),('quantangshi-17948','北极赠李观','韓愈','quantangshi','','卷18','北极有羁羽，南溟有沈鳞。
川源浩浩隔，影响两无因。
风云一朝会，变化成一身。
谁言道里远，感激疾如神。
我年二十五，求友昧其人。
哀歌西京市，乃与夫子亲。
所尚苟同趋，贤愚岂异伦。
方为金石姿，万世无缁磷。
无为儿女态，憔悴悲贱贫。','',''),('quantangshi-17949','此日足可惜赠张籍','韓愈','quantangshi','','卷18','此日足可惜，此酒不足尝。
舍酒去相语，共分一日光。
念昔未知子，孟君自南方。
自矜有所得，言子有文章。
我名属相府，欲往不得行。
思之不可见，百端在中肠。
维时月魄死，冬日朝在房。
驱驰公事退，闻子适及城。
命车载之至，引坐于中堂。
开怀听其说，往往副所望。
孔丘殁已远，仁义路久荒。
纷纷百家起，诡怪相披猖。
长老守所闻，后生习为常。
少知诚难得，纯粹古已亡。
譬彼植园木，有根易为长。
留之不遣去，馆置城西旁。
岁时未云几，浩浩观湖江。
众夫指之笑，谓我知不明。
儿童畏雷电，鱼鼈惊夜光。
州家举进士，选试缪所当。
驰辞对我策，章句何炜煌。
相公朝服立，工席歌鹿鸣。
礼终乐亦阕，相拜送于庭。
之子去须臾，赫赫流盛名。
窃喜复窃叹，谅知有所成。
人事安可恒，奄忽令我伤。
闻子高第日，正从相公丧。
哀情逢吉语，惝怳难为双。
暮宿偃师西，徒展转在牀。
夜闻汴州乱，遶壁行旁徨。
我时留妻子，仓卒不及将。
相见不复期，零落甘所丁。
骄儿未绝乳，念之不能忘。
忽如在我所，耳若闻啼声。
中途安得返，一日不可更。
俄有东来说，我家免罹殃。
乘船下汴水，东去趋彭城。
从丧朝至洛，还走不及停。
假道经盟津，出入行涧冈。
日西入军门，羸马颠且僵。
主人愿少留，延入陈壶觞。
卑贱不敢辞，忽忽心如狂。
饮食岂知味，丝竹徒轰轰。
平明脱身去，决若惊凫翔。
黄昏次汜水，欲过无舟航。
号呼久乃至，夜济十里黄。
中流上滩潬，沙水不可详。
惊波暗合沓，星宿争翻芒。
辕马蹢躅鸣，左右泣仆童。
甲午憩时门，临泉窥鬬龙。
东南出陈许，陂泽平茫茫。
道边草木花，红紫相低昂。
百里不逢人，角角雄雉鸣。
行行二月暮，乃及徐南疆。
下马步堤岸，上船拜吾兄。
谁云经艰难，百口无夭殇。
仆射南阳公，宅我睢水阳。
箧中有余衣，盎中有余粮。
闭门读书史，窗户忽已凉。
日念子来游，子岂知我情。
别离未为久，辛苦多所经。
对食每不饱，共言无倦听。
连延三十日，晨坐达五更。
我友二三子，宦游在西京。
东野窥禹穴，李翱观涛江。
萧条千万里，会合安可逢。
淮之水舒舒，楚山直丛丛。
子又舍我去，我怀焉所穷。
男儿不再壮，百岁如风狂。
高爵尚可求，无为守一乡。','',''),('quantangshi-17950','幽怀','韓愈','quantangshi','','卷18','幽怀不能写，行此春江浔。
适与佳节会，士女竞光阴。
凝妆耀洲渚，繁吹荡人心。
间关林中鸟，亦知和为音。
岂无一尊酒，自酌还自吟。
但悲时易失，四序迭相侵。
我歌君子行，视古犹视今。','',''),('quantangshi-17951','君子法天运','韓愈','quantangshi','','卷18','君子法天运，四时可前知。
小人惟所遇，寒暑不可期。
利害有常势，取舍无定姿。
焉能使我心，皎皎远忧疑。','',''),('quantangshi-17952','落叶送陈羽','韓愈','quantangshi','','卷18','落叶不更息，断蓬无复归。
飘颻终自异，邂逅暂相依。
悄悄深夜语，悠悠寒月辉。
谁云少年别，流泪各沾衣。','',''),('quantangshi-17953','归彭城','韓愈','quantangshi','','卷18','天下兵又动，太平竟何时。
訏谟者谁子，无乃失所宜。
前年关中旱，闾井多死饥。
去岁东郡水，生民为流尸。
上天不虚应，祸福各有随。
我欲进短策，无由至彤墀。
刳肝以为纸，沥血以书辞。
上言陈尧舜，下言引龙夔。
言词多感激，文字少葳蕤。
一读已自怪，再寻良自疑。
食芹虽云美，献御固已痴。
缄封在骨髓，耿耿空自奇。
昨者到京城，屡陪高车驰。
周行多俊异，议论无瑕疵。
见待颇异礼，未能去毛皮。
到口不敢吐，徐徐俟其巘。
归来戎马间，惊顾似羁雌。
连日或不语，终朝见相欺。
乘闲輙骑马，茫茫诣空陂。
遇酒即酩酊，君知我为谁。','',''),('quantangshi-17954','醉后','韓愈','quantangshi','','卷18','煌煌东方星，奈此众客醉。
初喧或忿争，中静杂嘲戏。
淋漓身上衣，颠倒笔下字。
人生如此少，酒贱且勤置。','',''),('quantangshi-17955','醉赠张秘书','韓愈','quantangshi','','卷18','人皆劝我酒，我若耳不闻。
今日到君家，呼酒持劝君。
为此座上客，及余各能文。
君诗多态度，蔼蔼春空云。
东野动惊俗，天葩吐奇芬。
张籍学古淡，轩鹤避鸡羣。
阿买不识字，颇知书八分。
诗成使之写，亦足张吾军。
所以欲得酒，为文俟其醺。
酒味既冷冽，酒气又氛氲。
性情渐浩浩，谐笑方云云。
此诚得酒意，余外徒缤纷。
长安众富儿，盘馔罗膻荤。
不解文字饮，惟能醉红裙。
虽得一饷乐，有如聚飞蚊。
今我及数子，固无莸与薰。
险语破鬼胆，高词嫓皇坟。
至宝不雕琢，神功谢锄耘。
方今向太平，元凯承华勋。
吾徒幸无事，庶以穷朝曛。','',''),('quantangshi-17956','同冠峡','韓愈','quantangshi','','卷18','南方二月半，春物亦已少。
维舟山水间，晨坐听百鸟。
宿云尚含姿，朝日忽升晓。
羇旅感和鸣，囚拘念轻矫。
潺湲泪久迸，诘曲思增绕。
行矣且无然，盖棺事乃了。','',''),('quantangshi-17957','送惠师','韓愈','quantangshi','','卷18','惠师浮屠者，乃是不羇人。
十五爱山水，超然谢朋亲。
脱冠翦头发，飞步遗踪尘。
发迹入四明，梯空上秋旻。
遂登天台望，众壑皆嶙峋。
夜宿最高顶，举头看星辰。
光芒相照烛，南北争罗陈。
兹地绝翔走，自然严且神。
微风吹木石，澎湃闻韶钧。
夜半起下视，溟波衔日轮。
鱼龙惊踊跃，呌啸成悲辛。
怪气或紫赤，敲磨共轮囷。
金鸦既腾翥，六合俄清新。
常闻禹穴奇，东去窥瓯闽。
越俗不好古，流传失其真。
幽踪邈难得，圣路嗟长堙。
回临浙江涛，屹起高峨岷。
壮志死不息，千年如隔晨。
是非竟何有，弃去非吾伦。
凌江诣庐岳，浩荡极游巡。
崔崒没云表，陂陀浸湖沦。
是时雨初霁，悬瀑垂天绅。
前年往罗浮，步戛南海漘。
大哉阳德盛，荣茂恒留春。
鹏骞堕长翮，鲸戏侧修鳞。
自来连州寺，曾未造城闉。
日携青云客，探胜穷崖滨。
太守邀不去，羣官请徒频。
囊无一金资，翻谓富者贫。
昨日忽不见，我令访其隣。
奔波自追及，把手问所因。
顾我却兴欢，君宁异于民。
离合自古然，辞别安足珍。
吾闻九疑好，夙志今欲伸。
斑竹啼舜妇，清湘沈楚臣。
衡山与洞庭，此固道所循。
寻崧方抵洛，历华遂之秦。
浮游靡定处，偶往即通津。
吾言子当去，子道非吾遵。
江鱼不池活，野鸟难笼驯。
吾非西方敎，怜子狂且醇。
吾嫉惰游者，怜子愚且谆。
去矣各异趣，何为浪霑巾。','',''),('quantangshi-17958','送灵师','韓愈','quantangshi','','卷18','佛法入中国，尔来六百年。
齐民逃赋役，高士着幽禅。
官吏不之制，纷纷听其然。
耕桑日失隶，朝署时遣贤。
灵师皇甫姓，胤胄本蝉联。
少小涉书史，早能缀文篇。
中间不得意，失迹成延迁。
逸志不拘敎，轩腾断牵挛。
围棊鬬白黑，生死随机权。
六博在一掷，枭卢叱回旋。
战诗谁与敌，浩汗横戈鋋。
饮酒尽百𧣴，嘲诣思逾鲜。
有时醉花月，高唱清且緜。
四座咸寂默，杳如奏湘弦。
寻胜不惮险，黔江屡洄沿。
瞿塘五六月，惊电让归船。
怒水忽中裂，千寻堕幽泉。
环回势益急，仰见团团天。
投身岂得计，性命甘徒捐。
浪沫蹙翻涌，漂浮再生全。
同行二十人，魂骨俱坑填。
灵师不挂怀，冒涉道转延。
开忠二州牧，诗赋时多传。
失职不把笔，珠玑为君编。
强留费日月，密席罗婵娟。
昨者至林邑，使君数开筵。
逐客三四公，盈怀赠兰荃。
湖游泛漭沆，溪宴驻潺湲。
别语不许出，行裾动遭牵。
隣州竞招请，书札何翩翩。
十月下桂岭，乘寒恣窥缘。
落落王员外，争迎获其先。
自从入宾馆，占恡久能专。
吾徒颇携被，接宿穷欢妍。
听说两京事，分明皆眼前。
纵横杂谣俗，琐屑咸罗穿。
材调真可惜，朱丹在磨研。
方将歛之道，且欲冠其颠。
韶阳李太守，高步凌云烟。
得客輙忘食，开囊乞缯钱。
手持南曹叙，字重青瑶镌。
古气参彖系，高标摧太玄。
维舟事干谒，披读头风痊。
还如旧相识，倾壶畅幽悁。
以此复留滞，归骖几时鞭。','',''),('quantangshi-17959','县斋有怀','韓愈','quantangshi','','卷18','少小尚奇伟，平生足悲吒。
犹嫌子夏儒，肯学樊迟稼。
事业窥臯稷，文章蔑曹谢。
濯缨起江湖，缀佩杂兰麝。
悠悠指长道，去去策高驾。
谁为倾国媒，自许连城价。
初随计吏贡，屡入泽宫射。
虽免十上劳，何能一战霸。
人情忌殊异，世路多权诈。
蹉跎颜遂低，摧折气愈下。
冶长信非罪，侯生或遭駡。
怀书出皇都，衔泪渡清灞。
身将老寂寞，志欲死闲暇。
朝食不盈肠，冬衣才掩髂。
军书既频召，戎马乃连跨。
大梁从相公，彭城赴仆射。
弓箭围狐兔，丝竹罗酒{炙火=肉}。
两府变荒凉，三年就休假。
求官去东洛，犯雪过西华。
尘埃紫陌春，风雨灵台夜。
名声荷朋友，援引乏姻娅。
虽陪彤庭臣，讵纵青冥靶。
寒空耸危阙，晓色曜修架。
捐躯辰在丁，铩翮时方蜡。
投荒诚职分，领邑幸宽赦。
湖波翻日车，岭石坼天罅。
毒雾恒熏昼，炎风每烧夏。
雷威固已加，飓势仍相借。
气象杳难测，声音吁可怕。
夷言听未惯，越俗循犹乍。
指摘两憎嫌，睢盱互猜讶。
祗缘恩未报，岂谓生足藉。
嗣皇新继明，率土日流化。
惟思涤瑕垢，长去事桑柘。
斸嵩开云扃，压颍抗风榭。
禾麦种满地，梨枣栽绕舍。
儿童稍长成，雀鼠得驱吓。
官租日输纳，村酒时邀迓。
闲爱老农愚，归弄小女姹。
如今便可尔，何用毕婚嫁。','',''),('quantangshi-17960','合江亭','韓愈','quantangshi','','卷18','红亭枕湘江，蒸水会其左。
瞰临眇空阔，绿净不可唾。
维昔经营初，邦君实王佐。
翦林迁神祠，买地费家货。
梁栋宏可爱，结构丽匪过。
伊人去轩腾，兹宇遂颓挫。
老郎来何暮，高唱久乃和。
树兰盈九畹，栽竹逾万个。
长绠汲沧浪，幽蹊下坎坷。
波涛夜俯听，云树朝对卧。
初如遗宦情，终乃最郡课。
人生诚无几，事往悲岂奈。
萧条緜岁时，契阔继庸懦。
胜事谁复论，丑声日已播。
中丞黜凶邪，天子闵穷饿。
君侯至之初，闾里自相贺。
淹滞乐闲旷，勤苦劝慵惰。
为余扫尘阶，命乐醉众座。
穷秋感平分，新月怜半破。
愿书岩上石，勿使泥尘涴。','',''),('quantangshi-17961','陪杜侍御游湘西两寺独宿有题一首因献杨常侍','韓愈','quantangshi','','卷18','长沙千里平，胜地犹在险。
况当江阔处，斗起势匪渐。
深林高玲珑，青山上琬琰。
路穷台殿辟，佛事焕且俨。
剖竹走泉源，开廊架崖广。
是时秋之残，暑气尚未歛。
羣行忘后先，朋息弃拘检。
客堂喜空凉，华榻有清簟。
涧蔬煮蒿芹，水果剥菱芡。
伊余夙所慕，陪赏亦云忝。
幸逢车马归，独宿门不掩。
山楼黑无月，渔火灿星点。
夜风一何喧，杉桧屡磨颭。
犹疑在波涛，怵惕梦成魇。
静思屈原沈，远忆贾谊贬。
椒兰争妬忌，绛灌共谗谄。
谁令悲生肠，坐使泪盈脸。
翻飞乏羽翼，指摘困瑕玷。
珥貂藩维重，政化类分陕。
礼贤道何优，奉己事苦俭。
大厦栋方隆，巨川檝行剡。
经营诚少暇，游宴固已歉。
旅程愧淹留，徂岁嗟荏苒。
平生每多感，柔翰遇频染。
展转岭猿鸣，曙灯青睒睒。','',''),('quantangshi-17962','岳阳楼别窦司直','韓愈','quantangshi','','卷18','洞庭九州间，厥大谁与让。
南汇羣崖水，北注何奔放。
潴为七百里，吞纳各殊状。
自古澄不清，环混无归向。
炎风日搜搅，幽怪多冗长。
轩然大波起，宇宙隘而妨。
巍峩拔嵩华，腾踔较健壮。
声音一何宏，轰輵车万两。
犹疑帝轩辕，张乐就空旷。
蛟螭露笋簴，缟练吹组帐。
鬼神非人世，节奏颇跌踼。
阳施见夸丽，阴闭感凄怆。
朝过宜春口，极北缺堤障。
夜缆巴陵洲，丛芮才可傍。
星河尽涵泳，俯仰迷下上。
余澜怒不已，喧聒鸣瓮盎。
明登岳阳楼，辉焕朝日亮。
飞廉戢其威，清晏息纤纩。
泓澄湛凝绿，物影巧相况。
江豚时出戏，惊波忽荡漾。
时当冬之孟，隙窍缩寒涨。
前临指近岸，侧坐眇难望。
涤濯神魂醒，幽怀舒以畅。
主人孩童旧，握手乍忻怅。
怜我窜逐归，相见得无恙。
开筵交履舃，烂漫倒家酿。
杯行无留停，高柱送清唱。
中盘进橙栗，投掷倾脯酱。
欢穷悲心生，婉娈不能忘。
念昔始读书，志欲干霸王。
屠龙破千金，为艺亦云亢。
爱才不择行，触事得谗谤。
前年出官由，此祸最无妄。
公卿采虚名，擢拜识天仗。
奸猜畏弹射，斥逐恣欺诳。
新恩移府庭，逼侧厕诸将。
于嗟苦驽缓，但惧失宜当。
追思南渡时，鱼腹甘所葬。
严程迫风帆，劈箭入高浪。
颠沈在须臾，忠鲠谁复谅。
生还真可喜，尅己自惩创。
庶从今日后，粗识得与丧。
事多改前好，趣有获新尚。
誓耕十亩田，不取万乘相。
细君知蚕织，稚子已能饷。
行当挂其冠，生死君一访。','',''),('quantangshi-17963','送文畅师北游','韓愈','quantangshi','','卷18','昔在四门馆，晨有僧来谒。
自言本吴人，少小学城阙。
已穷佛根源，粗识事輗軏。
挛拘屈吾真，戒辖思远发。
荐绅秉笔徒，声誉耀前阀。
从求送行诗，屡造忍颠蹶。
今成十余卷，浩汗罗斧钺。
先生閟穷巷，未得窥剞劂。
又闻识大道，何路补剠刖。
出其囊中文，满听实清越。
谓僧当少安，草序颇排讦。
上论古之初，所以施赏罚。
下开迷惑胸，窙豁劚株橜。
僧时不听莹，若饮水救暍。
风尘一出门，时日多如发。
三年窜荒岭，守县坐深樾。
徴租聚异物，诡制怛巾袜。
幽穷谁共语，思想甚含哕。
昨来得京官，照壁喜见蝎。
况逢旧亲识，无不比鹣蟨。
长安多门户，吊庆少休歇。
而能勤来过，重惠安可揭。
当今圣政初，恩泽完{羽戊}狘。
胡为不自暇，飘戾逐鹯𪆙。
仆射领北门，威德压胡羯。
相公镇幽都，竹帛烂勋伐。
酒场舞闺姝，猎骑围边月。
开张箧中宝，自可得津筏。
从兹富裘马，宁复茹藜蕨。
余期报恩后，谢病老耕垡。
庇身指蓬茅，逞志纵猃猲。
僧还相访来，山药煮可掘。','',''),('quantangshi-17964','答张彻','韓愈','quantangshi','','卷18','辱赠不知报，我歌尔其聆。
首叙始识面，次言后分形。
道途緜万里，日月垂十龄。
浚郊避兵乱，睢岸连门停。
肝胆一古劒，波涛两浮萍。
渍墨窜旧史，磨丹注前经。
义苑手秘宝，文堂耳惊霆。
暄晨蹑露舃，暑夕眠风棂。
结友子让抗，请师我惭丁。
初味犹噉蔗，遂通斯建瓴。
搜奇日有富，嗜善心无宁。
石梁平侹侹，沙水光泠泠。
乘枯摘野艳，沈细抽潜腥。
游寺去陟巘，寻径返穿汀。
缘云竹竦竦，失路麻冥冥。
淫潦忽翻野，平芜眇开溟。
防泄堑夜塞，惧冲城昼扃。
及去事戎辔，相逢宴军伶。
觥秋纵兀兀，猎旦驰駉駉。
从赋始分手，朝京忽同舲。
急时促暗棹，恋月留虚亭。
毕事驱传马，安居守窗萤。
梅花灞水别，宫烛骊山醒。
省选逮投足，乡宾尚摧翎。
尘祛又一掺，泪眦还双荧。
洛邑得休告，华山穷绝陉。
倚岩睨海浪，引袖拂天星。
日驾此回辖，金神所司刑。
泉绅拖修白，石劒攒高青。
磴藓㳠拳局，梯颷颭伶俜。
悔狂已咋指，垂诫仍镌铭。
峩豸忝备列，伏蒲愧分泾。
微诚慕横草，琐力摧撞筵。
叠雪走商岭，飞波航洞庭。
下险疑堕井，守官类拘囹。
荒餐茹獠蛊，幽梦感湘灵。
刺史肃蓍蔡，吏人沸蝗螟。
点缀簿上字，趋跄合前铃。
赖其饱山水，得以娱瞻听。
紫树雕斐亹，碧流滴珑玲。
暎波铺远锦，插地列长屏。
愁狖酸骨死，怪花醉魂馨。
潜苞绛实坼，幽乳翠毛零。
赦行五百里，月变三十蓂。
渐阶羣振鹭，入学诲螟蛉。
苹甘谢鸣鹿，罍满惭罄瓶。
冏冏抱瑚琏，飞飞联鹡鸰。
鱼鬣欲脱背，虬光先照硎。
岂独出丑类，方当动朝廷。
勤来得唔语，勿惮宿寒厅。','',''),('quantangshi-17965','荐士','韓愈','quantangshi','','卷18','周诗三百篇，雅丽理训诰。
曾经圣人手，议论安敢到。
五言出汉时，苏李首更号。
东都渐弥漫，派别百川导。
建安能者七，卓荦变风操。
逶迤抵晋宋，气象日凋耗。
中间数鲍谢，比近最清奥。
齐梁及陈隋，众作等蝉噪。
搜春摘花卉，沿袭伤剽盗。
国朝盛文章，子昂始高蹈。
勃兴得李杜，万类困陵暴。
后来相继生，亦各臻阃奥。
有穷者孟郊，受材实雄骜。
冥观洞古今，象外逐幽好。
横空盘硬语，妥帖力排奡。
敷柔肆纡余，奋猛卷海潦。
荣华肖天秀，捷疾逾响报。
行身践规矩，甘辱耻媚竈。
孟轲分邪正，眸子看瞭眊。
杳然粹而清，可以镇浮躁。
酸寒溧阳尉，五十几何耄。
孜孜营甘旨，辛苦久所冒。
俗流知者谁，指注竞嘲慠。
圣皇索遗逸，髦士日登造。
庙堂有贤相，爱遇均覆焘。
况承归与张，二公迭嗟悼。
青冥送吹嘘，强箭射鲁缟。
胡为久无成，使以归期告。
霜风破佳菊，嘉节迫吹帽。
念将决焉去，感物增恋嫪。
彼微水中荇，尚烦左右芼。
鲁侯国至小，庙鼎犹纳郜。
幸当择珉玉，宁有弃圭瑁。
悠悠我之思，扰扰风中纛。
上言愧无路，日夜惟心祷。
鹤翎不天生，变化在啄菢。
通波非难图，尺地易可漕。
善善不汲汲，后时徒悔懊。
救死具八珍，不如一箪犒。
微诗公勿诮，恺悌神所劳。','',''),('quantangshi-17966','喜侯喜至赠张籍张彻','韓愈','quantangshi','','卷18','昔我在南时，数君常在念。
摇摇不可止，讽咏日喁噞。
如以膏濯衣，每渍垢逾染。
又如心中疾，针石非所砭。
常思得游处，至死无倦厌。
地遐物奇怪，水镜涵石劒。
荒花穷漫乱，幽兽工腾闪。
碍目不忍窥，忽忽坐昏垫。
逢神多所祝，岂忘灵即验。
依依梦归路，历历想行店。
今者诚自幸，所怀无一欠。
孟生去虽索，侯氏来还歉。
欹眠听新诗，屋角月艳艳。
杂作承间骋，交惊舌互舚。
缤纷指瑕疵，拒捍阻城堑。
以余经摧挫，固请发铅椠。
居然妄推让，见谓爇天焰。
比疎语徒妍，悚息不敢占。
呼奴具盘餐，飣餖鱼菜赡。
人生但如此，朱紫安足僭。','',''),('quantangshi-17967','古风','韓愈','quantangshi','','卷18','今日曷不乐，幸时不用兵。
无曰既蹙矣，乃尚可以生。
彼州之赋，去汝不顾。
此州之役，去我奚适。
一邑之水，可走而违。
天下汤汤，曷其而归。
好我衣服，甘我饮食。
无念百年，聊乐一日。','',''),('quantangshi-17968','驽骥','韓愈','quantangshi','','卷18','驽骀诚龌龊，市者何其稠。
力小若易制，价微良易酬。
渴饮一斗水，饥食一束刍。
嘶鸣当大路，志气若有余。
骐骥生绝域，自矜无匹俦。
牵驱入市门，行者不为留。
借问价几何，黄金比嵩丘。
借问行几何，咫尺视九州。
饥食玉山禾，渴饮醴泉流。
问谁能为御，旷世不可求。
惟昔穆天子，乘之极遐游。
王良执其辔，造父挟其輈。
因言天外事，茫惚使人愁。
驽骀谓骐骥，饿死余尔羞。
有能必见用，有德必见收。
孰云时与命，通塞皆自由。
骐骥不敢言，低徊但垂头。
人皆劣骐骥，共以驽骀优。
喟余独兴叹，才命不同谋。
寄诗同心子，为我商声讴。','',''),('quantangshi-17969','马厌谷','韓愈','quantangshi','','卷18','马厌谷兮，士不厌糠籺。
土被文绣兮，士无短褐。
彼其得志兮，不我虞。
一朝失志兮，其何如。
已焉哉，嗟嗟乎鄙夫！。','',''),('quantangshi-17970','出门','韓愈','quantangshi','','卷18','长安百万家，出门无所之。
岂敢尚幽独，与世实参差。
古人虽已死，书上有其辞。
开卷读且想，千载若相期。
出门各有道，我道方未夷。
且于此中息，天命不吾欺。','',''),('quantangshi-17971','嗟哉董生行','韓愈','quantangshi','','卷18','淮水出桐柏，山东驰遥遥。
千里不能休，淝水出其侧。
不能千里百里入淮流，寿州属县有安丰。
唐贞元时县人董生召南隐居行义于其中，刺史不能荐。
天子不闻名声，爵禄不及门。
门外惟有吏，日来徴租更索钱。
嗟哉董生朝出耕，夜归读古人书。
尽日不得息，或山而樵。
或水而渔，入厨具甘旨。
上堂问起居，父母不戚戚。
妻子不咨咨，嗟哉董生孝且慈。
人不识，惟有天翁知。
生祥下瑞无时期，家有狗乳出求食。
鸡来哺其儿，啄啄庭中拾虫蚁。
哺之不食鸣声悲，旁徨踯躅久不去。
以翼来覆待狗归，嗟哉董生。
谁将与俦，时之人。
夫妻相虐，兄弟为讐。
食君之禄，而令父母愁。
亦独何心，嗟哉董生无与俦。','',''),('quantangshi-17972','烽火','韓愈','quantangshi','','卷18','登高望烽火，谁谓塞尘飞。
王城富且乐，曷不事光辉。
勿言日已暮，相见恐行稀。
愿君熟念此，秉烛夜中归。
我歌宁自感，乃独泪霑衣。','',''),('quantangshi-17973','汴州乱二首 一','韓愈','quantangshi','','卷18','汴州城门朝不开，天狗堕地声如雷。
健儿争夸杀留后，连屋累栋烧成灰。
诸侯咫尺不能救，孤士何者自兴哀。','',''),('quantangshi-17974','汴州乱二首 二','韓愈','quantangshi','','卷18','母从子走者为谁，大夫夫人留后儿。
昨日乘车骑大马，坐者起趋乘者下。
庙堂不肯用干戈，呜呼奈汝母子何。','',''),('quantangshi-17975','利劒','韓愈','quantangshi','','卷18','利劒光耿耿，佩之使我无邪心。
故人念我寡徒侣，持用赠我比知音。
我心如冰劒如雪，不能刺谗夫。
使我心腐劒锋折，决云中断开青天。
噫，劒与我俱变化归黄泉。','',''),('quantangshi-17976','龊龊','韓愈','quantangshi','','卷18','龊龊当世士，所忧在饥寒。
但见贱者悲，不闻贵者叹。
大贤事业异，远抱非俗观。
报国心皎洁，念时涕丸澜。
妖姬坐左右，柔指发哀弹。
酒肴虽日陈，感激宁为欢。
秋阴欺白日，泥潦不少干。
河堤决东郡，老弱随惊湍。
天意固有属，谁能诘其端。
愿辱太守荐，得充谏诤官。
排云呌阊阖，披腹呈琅玕。
致君岂无术，自进诚独难。','',''),('quantangshi-17977','河之水二首寄子侄老成 一','韓愈','quantangshi','','卷18','河之水，去悠悠，我不如，水东流。
我有孤侄在海陬，三年不见兮使我生忧。
日复日，夜复夜，三年不见汝，使我鬓发未老而先化。','',''),('quantangshi-17978','河之水二首寄子侄老成 二','韓愈','quantangshi','','卷18','河之水，悠悠去，我不如，水东注。
我有孤侄在海浦，三年不见兮使我心苦。
采蕨于山，缗鱼于渊。
我徂京师，不远其还。','',''),('quantangshi-17979','山石','韓愈','quantangshi','','卷18','山石荦确行径微，黄昏到寺蝙蝠飞。
升堂坐阶新雨足，芭蕉叶大支子肥。
僧言古壁佛画好，以火来照所见稀。
铺牀拂席置羹饭，疎粝亦足饱我饥。
夜深静卧百虫绝，清月出岭光入扉。
天明独去无道路，出入高下穷烟霏。
山红涧碧纷烂漫，时见松枥皆十围。
当流赤足蹋涧石，水声激激风吹衣。
人生如此自可乐，岂必局束为人鞿。
嗟哉吾党二三子，安得至老不更归。','',''),('quantangshi-17980','天星送杨凝郎中贺正','韓愈','quantangshi','','卷18','天星牢落鸡喔咿，仆夫起餐车载脂。
正当穷冬寒未已，借问君子行安之。
会朝元正无不至，受命上宰须及期。
侍从近臣有虚位，公今此去归何时。','',''),('quantangshi-17981','汴泗交流赠张仆射','韓愈','quantangshi','','卷18','汴泗交流郡城角，筑场十步平如削。
短垣三面缭逶迤，击鼓腾腾树赤旗。
新秋朝凉未见日，公早结束来何为。
分曹决胜约前定，百马攒蹄近相暎。
球惊杖奋合且离，红牛缨绂黄金羁。
侧身转臂着马腹，霹雳应手神珠驰。
超遥散漫两闲暇，挥霍纷纭争变化。
发难得巧意气麤，讙声四合壮士呼。
此诚习战非为剧，岂若安坐行良图。
当今忠臣不可得，公马莫走须杀贼。','',''),('quantangshi-17982','忽忽','韓愈','quantangshi','','卷18','忽忽乎余未知生之为乐也，愿脱去而无因。
安得长翮大翼如云生我身，乘风振奋出六合，绝浮尘。
死生哀乐两相弃，是非得失付闲人。','',''),('quantangshi-17983','鸣雁','韓愈','quantangshi','','卷18','嗷嗷鸣雁鸣且飞，穷秋南去春北归。
去寒就暖识所依，天长地阔栖息稀。
风霜酸苦稻粱微，毛羽摧落身不肥。
裴回反顾羣侣违，哀鸣欲下洲渚非。
江南水阔朝云多，草长沙软无网罗。','',''),('quantangshi-17984','龙移','韓愈','quantangshi','','卷18','天昏地黑蛟龙移，雷惊电激雄雌随。
清泉百丈化为土，鱼鼈枯死吁可悲。','',''),('quantangshi-17985','雉带箭','韓愈','quantangshi','','卷18','原头火烧静兀兀，野雉畏鹰出复没。
将军欲以巧伏人，盘马弯弓惜不发。
地形渐窄观者多，雉惊弓满劲箭加。
冲人决起百余尺，红翎白镞相倾斜。
将军仰笑军吏贺，五色离披马前堕。','',''),('quantangshi-17986','条山苍','韓愈','quantangshi','','卷18','条山苍，河水黄。
浪波沄沄去，松柏在山冈。','',''),('quantangshi-17987','赠郑兵曹','韓愈','quantangshi','','卷18','尊酒相逢十载前，君为壮夫我少年。
尊酒相逢十载后，我为壮夫君白首。
我材与世不相当，戢鳞委翅无复望。
当今贤俊皆周行，君何为乎亦遑遑。
杯行到君莫停手，破除万事无过酒。','',''),('quantangshi-17988','桃源图','韓愈','quantangshi','','卷18','神仙有无何渺茫，桃源之说诚荒唐。
流水盘回山百转，生绡数幅垂中堂。
武陵太守好事者，题封远寄南宫下。
南宫先生忻得之，波涛入笔驱文辞。
文工画妙各臻极，异境恍惚移于斯。
架岩凿谷开宫室，接屋连墙千万日。
嬴颠刘蹶了不闻，地坼天分非所恤。
种桃处处惟开花，川原近远蒸红霞。
初来犹自念乡邑，岁久此地还成家。
渔舟之子来何所，物色相猜更问语。
大蛇中断丧前王，羣马南渡开新主。
听终辞绝共凄然，自说经今六百年。
当时万事皆眼见，不知几许犹流传。
争持酒食来相馈，礼数不同樽俎异。
月明伴宿玉堂空，骨冷魂清无梦寐。
夜半金鸡啁哳鸣，火轮飞出客心惊。
人间有累不可住，依然离别难为情。
船开棹进一回顾，万里苍苍烟水暮。
世俗宁知伪与真，至今传者武陵人。','',''),('quantangshi-17989','东方半明','韓愈','quantangshi','','卷18','东方半明大星没，独有太白配残月。
嗟尔残月勿相疑，同光共影须臾期。
残月晖晖，太白睒睒。
鸡三号，更五点。','',''),('quantangshi-17990','赠唐衢','韓愈','quantangshi','','卷18','虎有爪兮牛有角，虎可搏兮牛可触。
奈何君独抱奇材，手把锄犁饿空谷。
当今天子急贤良，匦函朝出开明光。
胡不上书自荐达，坐令四海如虞唐。','',''),('quantangshi-17991','贞女峡','韓愈','quantangshi','','卷18','江盘峡束春湍豪，风雷战鬬鱼龙逃。
悬流轰轰射水府，一泻百里翻云涛。
漂船摆石万瓦裂，咫尺性命轻鸿毛。','',''),('quantangshi-17992','赠侯喜','韓愈','quantangshi','','卷18','吾党侯生字叔起，呼我持竿钓温水。
平明鞭马出都门，尽日行行荆棘里。
温水微茫绝又流，深如车辙阔容輈。
虾蟆跳过雀儿浴，此纵有鱼何足求。
我为侯生不能已，盘针擘粒投泥滓。
晡时坚坐到黄昏，手倦目劳方一起。
暂动还休未可期，虾行蛭渡似皆疑。
举竿引线忽有得，一寸才分鳞与鬐。
是日侯生与韩子，良久叹息相看悲。
我今行事尽如此，此事正好为吾规。
半世遑遑就举选，一名始得红颜衰。
人间事势岂不见，徒自辛苦终何为。
便当提携妻与子，南入箕颍无还时。
叔起君今气方锐，我言至切君勿嗤。
君欲钓鱼须远去，大鱼岂肯居沮洳。','',''),('quantangshi-17993','古意','韓愈','quantangshi','','卷18','太华峰头玉井莲，开花十丈藕如船。
冷比雪霜甘比蜜，一片入口沈疴痊。
我欲求之不惮远，青壁无路难夤缘。
安得长梯上摘实，下种七泽根株连。','',''),('quantangshi-17994','八月十五夜赠张功曹','韓愈','quantangshi','','卷18','纤云四卷天无河，清风吹空月舒波。
沙平水息声影绝，一杯相属君当歌。
君歌声酸辞且苦，不能听终泪如雨。
洞庭连天九疑高，蛟龙出没猩鼯号。
十生九死到官所，幽居默默如藏逃。
下牀畏蛇食畏药，海气湿蛰熏腥臊。
昨者州前捶大鼓，嗣皇继圣登夔臯。
赦书一日行万里，罪从大辟皆除死。
迁者追廻流者还，涤瑕荡垢清朝班。
州家申名使家抑，坎轲祗得移荆蛮。
判司卑官不堪说，未免捶楚尘埃间。
同时辈流多上道，天路幽险难追攀。
君歌且休听我歌，我歌今与君殊科。','',''),('quantangshi-17995','谒衡岳庙遂宿岳寺题门楼','韓愈','quantangshi','','卷18','五岳祭秩皆三公，四方环镇嵩当中。
火维地荒足妖怪，天假神柄专其雄。
喷云泄雾藏半腹，虽有绝顶谁能穷。
我来正逢秋雨节，阴气晦昧无清风。
潜心默祷若有应，岂非正直能感通。
须臾静扫众峰出，仰见突兀撑青空。
紫盖连延接天柱，石廪腾掷堆祝融。
森然魄动下马拜，松柏一迳趋灵宫。
粉墙丹柱动光彩，鬼物图画填青红。
升阶伛偻荐脯酒，欲以菲薄明其衷。
庙令老人识神意，睢盱侦伺能鞠躬。
手持杯珓导我掷，云此最吉余难同。
窜逐蛮荒幸不死，衣食才足甘长终。
侯王将相望久绝，神纵欲福难为功。
夜投佛寺上高阁，星月掩暎云朣胧。
猿鸣钟动不知曙，杲杲寒日生于东。','',''),('quantangshi-17996','岣嵝山','韓愈','quantangshi','','卷18','岣嵝山尖神禹碑，字青石赤形模奇。
科斗拳身薤倒披，鸾飘凤泊拏虎螭。
事严迹秘鬼莫窥，道人独上偶见之。
我来咨嗟涕涟洏，千搜万索何处有，森森绿树猿猱悲。','',''),('quantangshi-17997','永贞行','韓愈','quantangshi','','卷18','君不见太皇谅阴未出令，小人乘时偷国柄。
北军百万虎与貔，天子自将非他师。
一朝夺印付私党，懔懔朝士何能为。
狐鸣枭噪争署置，睗睒跳踉相妩媚。
夜作诏书朝拜官，超资越序曾无难。
公然白日受贿赂，火齐磊落堆金盘。
元臣故老不敢语，昼卧涕泣何丸澜。
董贤三公谁复惜，侯景九锡行可叹。
国家功高德且厚，天位未许庸夫干。
嗣皇卓荦信英主，文如太宗武高祖。
膺图受禅登明堂，共流幽州鲧死羽。
四门肃穆贤俊登，数君匪亲岂其朋。
郎官清要为世称，荒郡迫野嗟可矜。
湖波连天日相腾，蛮俗生梗瘴疠烝。
江氛岭祲昏若凝，一蛇两头见未曾。
怪鸟鸣唤令人憎，虫虫羣飞夜扑灯。
雄虺毒螫堕股肱，食中置药肝心崩。
左右使令诈难凭，慎勿浪信常兢兢。
吾尝同僚情可胜，具书目见非妄征，嗟尔既往宜为惩。','',''),('quantangshi-17998','洞庭湖阻风赠张十一署','韓愈','quantangshi','','卷18','十月阴气盛，北风无时休。
苍茫洞庭岸，与子维双舟。
雾雨晦争泄，波涛怒相投。
犬鸡断四听，粮绝谁与谋。
相去不容步，险如碍山丘。
清谈可以饱，梦想接无由。
男女喧左右，饥啼但啾啾。
非怀北归兴，何用胜羇愁。
云外有白日，寒光自悠悠。
能令暂开霁，过是吾无求。','',''),('quantangshi-17999','李花赠张十一署','韓愈','quantangshi','','卷18','江陵城西二月尾，花不见桃惟见李。
风揉雨练雪羞比，波涛翻空杳无涘。
君知此处花何似，白花倒烛天夜明。
羣鸡惊鸣官吏起，金乌海底初飞来。
朱辉散射青霞开，迷魂乱眼看不得。
照耀万树繁如堆，念昔少年着游燕。
对花岂省曾辞杯，自从流落忧感集。
欲去未到先思廻，祗今四十已如此。
后日更老谁论哉，力携一尊独就醉，不忍虚掷委黄埃。','',''),('quantangshi-18000','杏花','韓愈','quantangshi','','卷18','居邻北郭古寺空，杏花两株能白红。
曲江满园不可到，看此宁避雨与风。
二年流窜出岭外，所见草木多异同。
冬寒不严地恒泄，阳气发乱无全功。
浮花浪蘂镇长有，才开还落瘴雾中。
山榴踯躅少意思，照耀黄紫徒为丛。
鹧鸪钩輈猿呌歇，杳杳深谷攒青枫。
岂如此树一来翫，若在京国情何穷。
今旦胡为忽惆怅，万片飘泊随西东。
明年更发应更好，道人莫忘邻家翁。','',''),('quantangshi-18001','感春四首 一','韓愈','quantangshi','','卷18','我所思兮在何所，情多地遐兮徧处处。
东西南北皆欲往，千江隔兮万山阻。
春风吹园杂花开，朝日照屋百鸟语。
三杯取醉不复论，一生长恨奈何许。','',''),('quantangshi-18002','感春四首 二','韓愈','quantangshi','','卷18','皇天平分成四时，春气漫诞最可悲。
杂花妆林草盖地，白日坐上倾天维。
蜂喧鸟咽留不得，红萼万片从风吹。
岂如秋霜虽惨冽，摧落老物谁惜之。
为此径须沽酒饮，自外天地弃不疑。
近怜李杜无检束，烂漫长醉多文辞。
屈原离骚二十五，不肯哺啜糟与醨。
惜哉此子巧言语，不到圣处宁非痴。
幸逢尧舜明四目，条理品汇皆得宜。
平明出门暮归舍，酩酊马上知为谁。','',''),('quantangshi-18003','感春四首 三','韓愈','quantangshi','','卷18','朝骑一马出，暝就一牀卧。
诗书渐欲抛，节行久已惰。
冠敧感发秃，语误惊齿堕。
孤负平生心，已矣知何奈。','',''),('quantangshi-18004','感春四首 四','韓愈','quantangshi','','卷18','我恨不如江头人，长网横江遮紫鳞。
独宿荒陂射凫雁，卖纳租赋官不嗔。
归来欢笑对妻子，衣食自给宁羞贫。
今者无端读书史，智慧祗足劳精神。
画蛇着足无处用，两鬓霜白趋埃尘。
干愁漫解坐自累，与众异趣谁相亲。
数杯浇肠虽暂醉，皎皎万虑醒还新。
百年未满不得死，且可勤买抛青春。','',''),('quantangshi-18005','寒食日出游','韓愈','quantangshi','','卷18','李花初发君始病，我往看君花转盛。
走马城西惆怅归，不忍千株雪相暎。
迩来又见桃与梨，交开红白如争竞。
可怜物色阻携手，空展霜缣吟九咏。
纷纷落尽泥与尘，不共新妆比端正。
桐华最晚今已繁，君不强起时难更。
关山远别固其理，寸步难见始知命。
忆昔与君同贬官，夜渡洞庭看斗柄。
岂料生还得一处，引袖拭泪悲且庆。
各言生死两追随，直置心亲无貌敬。
念君又署南荒吏，路指鬼门幽且敻。
三公尽是知音人，曷不荐贤陛下圣。
囊空甑倒谁救之，我今一食日还并。
自然忧气损天和，安得康强保天性。
断鹤两翅鸣何哀，絷骥四足气空横。
今朝寒食行野外，绿杨帀岸蒲生迸。
宋玉庭边不见人，轻浪参差鱼动镜。
自嗟孤贱足瑕疵，特见放纵荷宽政。
饮酒宁嫌𧣴底深，题诗尚倚笔锋劲。
明宵故欲相就醉，有月莫愁当火令。','',''),('quantangshi-18006','忆昨行和张十一','韓愈','quantangshi','','卷18','忆昨夹钟之吕初吹灰，上公礼罢元侯廻。
车载牲牢瓮舁酒，并召宾客延邹枚。
腰金首翠光照耀，丝竹迥发清以哀。
青天白日花草丽，玉斝屡举倾金罍。
张君名声座所属，起舞先醉长松摧。
宿酲未解旧痁作，深室静卧闻风雷。
自期殒命在春序，屈指数日怜婴孩。
危辞苦语感我耳，泪落不揜何漼漼。
念昔从君渡湘水，大帆夜划穷高桅。
阳山鸟路出临武，驿马拒地驱频颓。
践蛇茹蛊不择死，忽有飞诏从天来。
伾文未揃崖州炽，虽得赦宥恒愁猜。
近者三奸悉破碎，羽窟无底幽黄能。
眼中了了见乡国，知有归日眉方开。
今君纵署天涯吏，投檄北去何难哉。
无妄之忧勿药喜，一善自足禳千灾。
头轻目朗肌骨健，古劒新劚磨尘埃。
殃消祸散百福并，从此直至耉与鲐。
嵩山东头伊洛岸，胜事不假须穿栽。
君当先行我待满，沮溺可继穷年推。','',''),('quantangshi-18007','刘生诗','韓愈','quantangshi','','卷18','生名师命其姓刘，自少轩轾非常俦。
弃家如遗来远游，东走梁宋暨扬州。
遂凌大江极东陬，洪涛舂天禹穴幽。
越女一笑三年留，南逾横岭入炎州。
青鲸高磨波山浮，怪魅炫曜堆蛟虬。
山㺑讙噪猩猩游，毒气烁体黄膏流。
问胡不归良有由，美酒倾水{炙火=肉}肥牛。
妖歌慢舞烂不收，倒心廻肠为青眸。
千金邀顾不可酬，乃独遇之尽绸缪。
瞥然一饷成十秋，昔须未生今白头。
五管历徧无贤侯，回望万里还家羞。
阳山穷邑惟猿猴，手持钓竿远相投。
我为罗列陈前修，芟蒿斩蓬利锄耰。
天星廻环数才周，文学穰穰囷仓稠。
车轻御良马力优，咄哉识路行勿休，往取将相酬恩讐。','',''),('quantangshi-18008','郑羣赠簟','韓愈','quantangshi','','卷18','蕲州笛竹天下知，郑君所宝尤瓌奇。
携来当昼不得卧，一府传看黄琉璃。
体坚色净又藏节，尽眼凝滑无瑕疵。
法曹贫贱众所易，腰腹空大何能为。
自从五月困暑湿，如坐深甑遭蒸炊。
手磨袖拂心语口，慢肤多汗真相宜。
日暮归来独惆怅，有卖直欲倾家资。
谁谓故人知我意，卷送八尺含风漪。
呼奴扫地铺未了，光彩照耀惊童儿。
青蝇侧翅蚤虱避，肃肃疑有清飙吹。
倒身甘寝百疾愈，却愿天日恒炎曦。
明珠青玉不足报，赠子相好无时衰。','',''),('quantangshi-18009','丰陵行','韓愈','quantangshi','','卷19','羽卫煌煌一百里，晓出都门葬天子。
羣臣杂沓驰后先，宫官穰穰来不已。
是时新秋七月初，金神按节炎气除。
清风飘飘轻雨洒，偃蹇旗斾卷以舒。
逾梁下坂笳鼓咽，嵽嵲遂走玄宫闾。
哭声訇天百鸟噪，幽坎昼闭空灵舆。
皇帝孝心深且远，资送礼备无赢余。
设官置卫锁嫔妓，供养朝夕象平居。
臣闻神道尚清净，三代旧制存诸书。
墓藏庙祭不可乱，欲言非职知何如。','',''),('quantangshi-18010','游青龙寺赠崔大补阙','韓愈','quantangshi','','卷19','秋灰初吹季月管，日出卯南晖景短。
友生招我佛寺行，正值万株红叶满。
光华闪壁见神鬼，赫赫炎官张火伞。
然云烧树火实骈，金乌下啄赬虬卵。
魂翻眼倒忘处所，赤气冲融无间断。
有如流传上古时，九轮照烛干坤旱。
二三道士席其间，灵液屡进玻黎盌。
忽惊颜色变韶稚，却信灵仙非怪诞。
桃源迷路竟茫茫，枣下悲歌徒纂纂。
前年岭隅乡思发，踯躅成山开不算。
去岁羇帆湘水明，霜枫千里随归伴。
猿呼鼯啸鹧鸪啼，恻耳酸肠难濯澣。
思君携手安能得，今者相从敢辞懒。
由来钝呆寡参寻，况是儒官饱闲散。
惟君与我同怀抱，锄去陵谷置平坦。
年少得途未要忙，时清谏疏尤宜罕。
何人有酒身无事，谁家多竹门可款。
须知节候即风寒，幸及亭午犹妍暖。
南山逼冬转清瘦，刻画圭角出崖窾。
当忧复被冰雪埋，汲汲来窥戒迟缓。','',''),('quantangshi-18011','赠崔立之评事','韓愈','quantangshi','','卷19','崔侯文章苦捷敏，高浪驾天输不尽。
曾从关外来上都，随身卷轴车连轸。
朝为百赋犹郁怒，暮作千诗转遒紧。
摇毫掷简自不供，顷刻青红浮海蜃。
才豪气猛易语言，往往蛟螭杂蝼蚓。
知音自古称难遇，世俗乍见那妨哂。
勿嫌法官未登朝，犹胜赤尉长趋尹。
时命虽乖心转壮，技能虚富家逾窘。
念昔尘埃两相逢，争名龃龉持矛楯。
子时专场夸觜距，余始张军严韅靷。
尔来但欲保封疆，莫学庞涓怯孙膑。
窜逐新归厌闻闹，齿发早衰嗟可闵。
频蒙怨句刺弃遗，岂有闲官敢推引。
深藏箧笥时一发，戢戢已多如束笋。
可怜无益费精神，有似黄金掷虚牝。
当今圣人求侍从，拔擢杞梓收楛箘。
东马严徐已奋飞，枚臯即召穷且忍。
复闻王师西讨蜀，霜风冽冽摧朝菌。
走章驰檄在得贤，燕雀纷拏要鹰隼。
窃料二途必处一，岂比恒人长蠢蠢。
劝君韬养待徴招，不用雕琢愁肝肾。
墙根菊花好沽酒，钱帛纵空衣可准。
晖晖檐日暖且鲜，摵摵井梧疎更殒。
高士例须怜麯糵，丈夫终莫生畦畛。
能来取醉任喧呼，死后贤愚俱泯泯。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-18012','送区弘南归','韓愈','quantangshi','','卷19','穆昔南征军不归，虫沙猿鹤伏以飞。
汹汹洞庭莽翠微，九疑鑱天荒是非。
野有象犀水贝玑，分散百宝人士稀。
我迁于南日周围，来见者众莫伊俙。
爰有区子荧荧晖，观以彝训或从违。
我念前人譬葑菲，落以斧引以纆徽。
虽有不逮驱騑騑，或采于薄渔于矶。
服役不辱言不讥，从我荆州来京畿。
离其母妻绝因依，嗟我道不能自肥。
子虽勤苦终何希，王都观阙双巍巍。
腾蹋众骏事鞍鞿，佩服上色紫与绯。
独子之节可嗟唏，母附书至妻寄衣。
开书拆衣泪痕曦，虽不敕还情庶几。
朝暮盘羞恻庭闱，幽房无人感伊威。
人生此难余可祈，子去矣时若发机。
蜃沈海底气升霏，彩雉野伏朝扇翚。
处子窈窕王所妃，苟有令德隐不腓。
况今天子铺德威，蔽能者诛荐受禨。
出送抚背我涕挥，行行正直慎脂韦。
业成志树来颀颀，我当为子言天扉。','',''),('quantangshi-18013','三星行','韓愈','quantangshi','','卷19','我生之辰，月宿南斗。
牛奋其角，箕张其口。
牛不见服箱，斗不挹酒浆。
箕独有神灵，无时停簸扬。
无善名已闻，无恶声已讙。
名声相乘除，得少失有余。
三星各在天，什伍东西陈。
嗟汝牛与斗，汝独不能神。','',''),('quantangshi-18014','剥啄行','韓愈','quantangshi','','卷19','剥剥啄啄，有客至门。
我不出应，客去而嗔。
从者语我，子胡为然。
我不厌客，困于语言。
欲不出纳，以堙其源。
空堂幽幽，有秸有莞。
门以两板，丛书于间。
窅窅深堑，其墉甚完。
彼宁可隳，此不可干。
从者语我，嗟子诚难。
子虽云尔，其口益蕃。
我为子谋，有万其全。
凡今之人，急名与官。
子不引去，与为波澜。
虽不开口，虽不开关。
变化咀嚼，有鬼有神。
今去不勇，其如后艰。
我谢再拜，汝无复云。
往追不及，来不有年。','',''),('quantangshi-18015','青青水中蒲三首 一','韓愈','quantangshi','','卷19','青青水中蒲，下有一双鱼。
君今上陇去，我在与谁居。','',''),('quantangshi-18016','青青水中蒲三首 二','韓愈','quantangshi','','卷19','青青水中蒲，长在水中居。
寄语浮萍草，相随我不如。','',''),('quantangshi-18017','青青水中蒲三首 三','韓愈','quantangshi','','卷19','青青水中蒲，叶短不出水。
妇人不下堂，行子在万里。','',''),('quantangshi-18018','孟东野失子','韓愈','quantangshi','','卷19','失子将何尤，吾将上尤天。
女实主下人，与夺一何偏。
彼于女何有，乃令蕃且延。
此独何罪辜，生死旬日间。
上呼无时闻，滴地泪到泉。
地只为之悲，瑟缩久不安。
乃呼大灵龟，骑云款天门。
问天主下人，薄厚胡不均。
天曰天地人，由来不相关。
吾悬日与月，吾系星与辰。
日月相噬啮，星辰踣而颠。
吾不女之罪，知非女由因。
且物各有分，孰能使之然。
有子与无子，祸福未可原。
鱼子满母腹，一一欲谁怜。
细腰不自乳，举族常孤鳏。
鸱枭啄母脑，母死子始翻。
蝮蛇生子时，坼裂肠与肝。
好子虽云好，未还恩与勤。
恶子不可说，鸱枭蝮蛇然。
有子且勿喜，无子固勿叹。
上圣不待敎，贤闻语而迁。
下愚闻语惑，虽敎无由悛。
大灵顿头受，即日以命还。
地只谓大灵，女往告其人。
东野夜得梦，有夫玄衣巾。
闯然入其户，三称天之言。
再拜谢玄夫，收悲以欢忻。','',''),('quantangshi-18019','陆浑山火和皇甫湜用其韵','韓愈','quantangshi','','卷19','皇甫补官古贲浑，时当玄冬泽干源。
山狂谷很相吐吞，风怒不休何轩轩。
摆磨出火以自燔，有声夜中惊莫原。
天跳地踔颠干坤，赫赫上照穷崖垠。
截然高周烧四垣，神焦鬼烂无逃门。
三光弛隳不复暾，虎熊麋猪逮猴猿。
水龙鼍龟鱼与鼋，鸦鸱雕鹰雉鹄鵾。
燖炮煨爊孰飞奔，祝融告休酌卑尊。
错陈齐玫辟华园，芙蓉披猖塞鲜繁。
千钟万鼓咽耳喧，攒杂啾嚄沸篪埙。
彤幢绛旃紫纛幡，炎官热属朱冠褌。
髹其肉皮通䏶臀，颓胸垤腹车掀辕。
缇颜靺股豹两鞬，霞车虹靷日毂轓。
丹蕤縓盖绯翻㠾，红帷赤幕罗脤膰。
𥁃池波风肉陵屯，谽呀钜壑颇黎盆。
豆登五山瀛四尊，熙熙釂醻笑语言。
雷公擘山海水翻，齿牙嚼啮舌腭反。
电光䃸磹赬目䁔，顼冥收威避玄根。
斥弃舆马背厥孙，缩身潜喘拳肩跟。
君臣相怜加爱恩，命黑螭侦焚其元。
天阙悠悠不可援，梦通上帝血面论。
侧身欲进叱于阍，帝赐九河湔涕痕。
又诏巫阳反其魂，徐命之前问何冤。
火行于冬古所存，我如禁之绝其飧。
女丁妇壬传世婚，一朝结讐奈后昆。
时行当反慎藏蹲，视桃着花可小骞。
月及申酉利复怨，助汝五龙从九鲲。
溺厥邑囚之昆仑，皇甫作诗止睡昏。
辞夸出真遂上焚，要余和增怪又烦，虽欲悔舌不可扪。','',''),('quantangshi-18020','县斋读书','韓愈','quantangshi','','卷19','出宰山水县，读书松桂林。
萧条捐末事，邂逅得初心。
哀狖醒俗耳，清泉洁尘襟。
诗成有共赋，酒熟无孤斟。
青竹时默钓，白云日幽寻。
南方本多毒，北客恒惧侵。
谪谴甘自守，滞留愧难任。
投章类缟带，伫答逾兼金。','',''),('quantangshi-18021','新竹','韓愈','quantangshi','','卷19','笋添南堦竹，日日成清閟。
缥节已储霜，黄苞犹揜翠。
出栏抽五六，当户罗三四。
高标陵秋严，贞色夺春媚。
稀生巧补林，并出疑争地。
纵横乍依行，烂熳忽无次。
风枝未飘吹，露粉先涵泪。
何人可携翫，清景空瞪视。','',''),('quantangshi-18022','晚菊','韓愈','quantangshi','','卷19','少年饮酒时，踊跃见菊花。
今来不复饮，每见恒咨嗟。
伫立摘满手，行行把归家。
此时无与语，弃置奈悲何。','',''),('quantangshi-18023','落齿','韓愈','quantangshi','','卷19','去年落一牙，今年落一齿。
俄然落六七，落势殊未已。
余存皆动摇，尽落应始止。
忆初落一时，但念豁可耻。
及至落二三，始忧衰即死。
每一将落时，懔懔恒在已。
叉牙妨食物，颠倒怯漱水。
终焉舍我落，意与崩山比。
今来落既熟，见落空相似。
余存二十余，次第知落矣。
傥常岁落一，自足支两纪。
如其落并空，与渐亦同指。
人言齿之落，寿命理难恃。
我言生有涯，长短俱死尔。
人言齿之豁，左右惊谛视。
我言庄周云，水雁各有喜。
语讹默固好，嚼废软还美。
因歌遂成诗，持用诧妻子。','',''),('quantangshi-18024','哭杨兵部凝陆歙州参','韓愈','quantangshi','','卷19','人皆期七十，才半岂蹉跎。
并出知己泪，自然白发多。
晨兴为谁恸，还坐久滂沱。
论文与晤语，已矣可如何。','',''),('quantangshi-18025','苦寒','韓愈','quantangshi','','卷19','四时各平分，一气不可兼。
隆寒夺春序，颛顼固不廉。
太昊弛维纲，畏避但守谦。
遂令黄泉下，萌牙夭句尖。
草木不复抽，百味失苦甜。
凶飙搅宇宙，铓刃甚割砭。
日月虽云尊，不能活乌蟾。
羲和送日出，恇怯频窥觇。
炎帝持祝融，呵嘘不相炎。
而我当此时，恩光何由沾。
肌肤生鳞甲，衣被如刀镰。
气寒鼻莫齅，血冻指不拈。
浊醪沸入喉，口角如衔箝。
将持匕箸食，触指如排签。
侵炉不觉暖，炽炭屡已添。
探汤无所益，何况纩与缣。
虎豹僵穴中，蛟螭死幽潜。
荧惑丧缠次，六龙冰脱髯。
芒砀大包内，生类恐尽歼。
啾啾窗间雀，不知已微纤。
举头仰天鸣，所愿晷刻淹。
不如弹射死，却得亲炮燖。
鸾皇苟不存，尔固不在占。
其余蠢动俦，俱死谁恩嫌。
伊我称最灵，不能女覆苫。
悲哀激愤叹，五藏难安恬。
中宵倚墙立，淫泪何渐渐。
天王哀无辜，惠我下顾瞻。
褰旒去耳纩，调和进梅盐。
贤能日登御，黜彼傲与憸。
生风吹死气，豁达如褰帘。
悬乳零落堕，晨光入前檐。
雪霜顿销释，土脉膏且黏。
岂徒兰蕙荣，施及艾与蒹。
日萼行铄铄，风条坐襜襜。
天乎苟其能，吾死意亦厌。','',''),('quantangshi-18026','和虞部卢四酬翰林钱七赤藤杖歌','韓愈','quantangshi','','卷19','赤藤为杖世未窥，台郎始携自滇池。
滇王扫宫避使者，跪进再拜语嗢咿。
绳桥拄过免倾堕，性命造次蒙扶持。
途经百国皆莫识，君臣聚观逐旌麾。
共传滇神出水献，赤龙拔须血淋漓。
又云羲和操火鞭，暝到西极睡所遗。
几重包裹自题署，不以珍怪夸荒夷。
归来捧赠同舍子，浮光照手欲把疑。
空堂昼眠倚牖户，飞电着壁搜蛟螭。
南宫清深禁闱密，唱和有类吹埙篪。
妍辞丽句不可继，见寄聊且慰分司。','',''),('quantangshi-18027','崔十六少府摄伊阳以诗及书见投因酬三十韵','韓愈','quantangshi','','卷19','崔君初来时，相识颇未惯。
但闻赤县尉，不比博士慢。
赁屋得连墙，往来忻莫间。
我时亦新居，触事苦难办。
蔬飱要同吃，破袄请来绽。
谓言安堵后，贷借更何患。
不知孤遗多，举族仰薄宦。
有时未朝餐，得米日已晏。
隔墙闻讙呼，众口极鹅雁。
前计顿乖张，居然见真赝。
娇儿好眉眼，裤脚冻两骭。
捧书随诸兄，累累两角丱。
冬惟茹寒齑，秋始识瓜瓣。
问之不言饥，饫若厌刍豢。
才名三十年，久合居给谏。
白头趋走里，闭口绝谤讪。
府公旧同袍，拔擢宰山涧。
寄诗杂诙俳，有类说鹏鷃。
上言酒味酸，冬衣竟未擐。
下言人吏稀，惟足彪与虥。
又言致猪鹿，此语乃善幻。
三年国子师，肠肚习藜苋。
况住洛之涯，鲂鳟可罩汕。
肯效屠门嚼，久嫌弋者篡。
谋拙日焦拳，活计似锄刬。
男寒涩诗书，妻瘦剩腰襻。
为官不事职，厥罪在欺谩。
行当自劾去，渔钓老葭薍。
岁穷寒气骄，冰雪滑磴栈。
音问难屡通，何由觌清盼。','',''),('quantangshi-18028','送侯参谋赴河中幕','韓愈','quantangshi','','卷19','忆昔初及第，各以少年称。
君颐始生须，我齿清如冰。
尔时心气壮，百事谓己能。
一别讵几何，忽如隔晨兴。
我齿豁可鄙，君颜老可憎。
相逢风尘中，相视迭嗟矜。
幸同学省官，末路再得朋。
东司绝敎授，游[宴]以为恒。
秋渔荫密树，夜博然明灯。
雪迳抵樵叟，风廊折谈僧。
陆浑桃花间，有汤沸如烝。
三月崧少步，踯躅红千层。
洲沙厌晚坐，岭壁穷晨升。
沈冥不计日，为乐不可胜。
迁满一已异，乖离坐难凭。
行行事结束，人马何蹻腾。
感激生胆勇，从军岂尝曾。
洸洸司徒公，天子爪与肱。
提师十万余，四海钦风棱。
河北兵未进，蔡州师新薨。
曷不请扫除，活彼黎与烝。
鄙夫诚怯弱，受恩愧徒弘。
犹思脱儒冠，弃死取先登。
又欲面言事，上书求诏徴。
侵官固非是，妄作谴可惩。
惟当待责免，耕斸归沟塍。
今君得所附，势若脱鞲鹰。
檄笔无与让，幕谋职其膺。
收绩开史牒，翰飞逐溟鹏。
男儿贵立事，流景不可乘。
岁老阴沴作，云颓雪翻崩。
别袖拂洛水，征车转崤陵。
勤勤酒不进，勉勉恨已仍。
送君出门归，愁肠若牵绳。
默坐念语笑，痴如遇寒蝇。
策马谁可适，晤言谁为应。
席尘惜不扫，残尊对空凝。
信知后会时，日月屡环絙。
生期理行役，欢绪绝难承。
寄书惟在频，无恡简与缯。','',''),('quantangshi-18029','东都遇春','韓愈','quantangshi','','卷19','少年气真狂，有意与春竞。
行逢二三月，九州花相暎。
川原晓服鲜，桃李晨妆靓。
荒乘不知疲，醉死岂辞病。
饮噉惟所便，文章倚豪横。
尔来曾几时，白发忽满镜。
旧游喜乖张，新辈足嘲评。
心肠一变化，羞见时节盛。
得闲无所作，贵欲辞视听。
深居疑避仇，默卧如当暝。
朝曦入牖来，鸟唤昏不醒。
为生鄙计算，盐米告屡罄。
坐疲都忘起，冠侧懒复正。
幸蒙东都官，获离机与穽。
乖慵遭傲僻，渐染生弊性。
既去焉能追，有来犹莫骋。
有船魏王池，往往纵孤泳。
水容与天色，此处皆绿净。
岸树共纷披，渚牙相纬经。
怀归苦不果，即事取幽迸。
贪求匪名利，所得亦已并。
悠悠度朝昏，落落捐季孟。
羣公一何贤，上戴天子圣。
谋谟收禹绩，四面出雄劲。
转输非不勤，稽逋有军令。
在庭百执事，奉职各祗敬。
我独胡为哉，坐与亿兆庆。
譬如笼中鸟，仰给活性命。
为诗告友生，负愧终究竟。','',''),('quantangshi-18030','感春五首 一','韓愈','quantangshi','','卷19','辛夷高花最先开，青天露坐始此廻。
已呼孺人戛鸣瑟，更遣稚子传清杯。
选壮军兴不为用，坐狂朝论无由陪。
如今到死得闲处，还有诗赋歌康哉。','',''),('quantangshi-18031','感春五首 二','韓愈','quantangshi','','卷19','洛阳东风几时来，川波岸柳春全廻。
宫门一锁不复启，虽有九陌无尘埃。
策马上桥朝日出，楼阙赤白正崔嵬。
孤吟屡阕莫与和，寸恨至短谁能裁。','',''),('quantangshi-18032','感春五首 三','韓愈','quantangshi','','卷19','春田可耕时已催，王师北讨何当廻。
放车载草农事济，战马苦饥谁念哉。
蔡州纳节旧将死，起居谏议联翩来。
朝廷未省有遗策，肯不垂意瓶与罍。','',''),('quantangshi-18033','感春五首 四','韓愈','quantangshi','','卷19','前随杜尹拜表廻，笑言溢口何欢咍。
孔丞别我适临汝，风骨峭峻遗尘埃。
音容不接祗隔夜，凶讣讵可相寻来。
天公高居鬼神恶，欲保性命诚难哉。','',''),('quantangshi-18034','感春五首 五','韓愈','quantangshi','','卷19','辛夷花房忽全开，将衰正盛须频来。
清晨辉辉烛霞日，薄暮耿耿和烟埃。
朝明夕暗已足叹，况乃满地成摧颓。
迎繁送谢别有意，谁肯留恋少环廻。','',''),('quantangshi-18035','酬裴十六功曹巡府西驿涂中见寄','韓愈','quantangshi','','卷19','相公罢论道，聿至活东人。
御史坐言事，作吏府中尘。
遂令河南治，今古无俦伦。
四海日富庶，道途隘蹄轮。
府西三百里，候馆同鱼鳞。
相公谓御史，劳子去自巡。
是时山水秋，光景何鲜新。
哀鸿鸣清耳，宿雾褰高旻。
遗我行旅诗，轩轩有风神。
譬如黄金盘，照耀荆璞真。
我来亦已幸，事贤友其仁。
持竿洛水侧，孤坐屡穷辰。
多才自劳苦，无用祗因循。
辞免期匪远，行行及山春。','',''),('quantangshi-18036','燕河南府秀才得生字','韓愈','quantangshi','','卷19','吾皇绍祖烈，天下再太平。
诏下诸郡国，岁贡乡曲英。
元和五年冬，房公尹东京。
功曹上言公，是月当登名。
乃选二十县，试官得鸿生。
羣儒负己材，相贺简择精。
怒起簸羽翮，引吭吐铿轰。
此都自周公，文章继名声。
自非绝殊尤，难使耳目惊。
今者遭震薄，不能出声鸣。
鄙夫忝县尹，愧栗难为情。
惟求文章写，不敢妬与争。
还家敕妻儿，具此煎炮烹。
柿红蒲萄紫，肴果相扶檠。
芳荼出蜀门，好酒浓且清。
何能充欢燕，庶以露厥诚。
昨闻诏书下，权公作邦桢。
文人得其职，文道当大行。
阴风搅短日，冷雨涩不晴。
勉哉戒徒驭，家国迟子荣。','',''),('quantangshi-18037','送李翺','韓愈','quantangshi','','卷19','广州万里途，山重江逶迤。
行行何时到，谁能定归期。
揖我出门去，颜色异恒时。
虽云有追送，足迹绝自兹。
人生一世间，不自张与弛。
譬如浮江木，纵横岂自知。
宁怀别时苦，勿作别后思。','',''),('quantangshi-18038','送石洪处士赴河阳幕得起字','韓愈','quantangshi','','卷19','长把种树书，人云避世士。
忽骑将军马，自号报恩子。
风云入壮怀，泉石别幽耳。
钜鹿师欲老，常山险犹恃。
岂惟彼相忧，固是吾徒耻。
去去事方急，酒行可以起。','',''),('quantangshi-18039','送湖南李正字归','韓愈','quantangshi','','卷19','长沙入楚深，洞庭值秋晚。
人随鸿雁少，江共蒹葭远。
历历余所经，悠悠子当返。
孤游怀耿介，旅宿梦婉娩。
风土稍殊音，鱼虾日异饭。
亲交俱在此，谁与同息偃。','',''),('quantangshi-18040','辛卯年雪','韓愈','quantangshi','','卷19','元和六年春，寒气不肯归。
河南二月末，雪花一尺围。
崩腾相排拶，龙凤交横飞。
波涛何飘扬，天风吹幡旗。
白帝盛羽卫，鬖髿振裳衣。
白霓先启途，从以万玉妃。
翕翕陵厚载，哗哗弄阴机。
生平未曾见，何暇议是非。
或云丰年祥，饱食可庶几。
善祷吾所慕，谁言寸诚微。','',''),('quantangshi-18041','醉留东野','韓愈','quantangshi','','卷19','昔年因读李白杜甫诗，长恨二人不相从。
吾与东野生并世，如何复蹑二子踪。
东野不得官，白首夸龙钟。
韩子稍奸黠，自慙青蒿倚长松。
低头拜东野，愿得终始如駏蛩。
东野不廻头，有如寸筳撞钜钟。
我愿身为云，东野变为龙。
四方上下逐东野，虽有离别无由逢。','',''),('quantangshi-18042','李花二首 一','韓愈','quantangshi','','卷19','平旦入西园，梨花数株若矜夸。
旁有一株李，颜色惨惨似含嗟。
问之不肯道所以，独绕百帀至日斜。
忽忆前时经此树，正见芳意初萌牙。
奈何趁酒不省录，不见玉枝攒霜葩。
泫然为汝下雨泪，无由反斾羲和车。
东风来吹不解颜，苍茫夜气生相遮。
冰盘夏荐碧实脆，斥去不御惭其花。','',''),('quantangshi-18043','李花二首 二','韓愈','quantangshi','','卷19','当春天地争奢华，洛阳园苑尤纷拏。
谁将平地万堆雪，翦刻作此连天花。
日光赤色照未好，明月暂入都交加。
夜领张彻投卢仝，乘云共至玉皇家。
长姬香御四罗列，缟裙练帨无等差。
静濯明妆有所奉，顾我未肯置齿牙。
清寒莹骨肝胆醒，一生思虑无由邪。','',''),('quantangshi-18044','招杨之罘','韓愈','quantangshi','','卷19','柏生两石间，万岁终不大。
野马不识人，难以驾车盖。
柏移就平地，马羁入厩中。
马思自由悲，柏有伤根容。
伤根柏不死，千丈日以至。
马悲罢还乐，振迅矜鞍辔。
之罘南山来，文字得我惊。
馆置使读书，日有求归声。
我令之罘归，失得柏与马。
之罘别我去，计出柏马下。
我自之罘归，入门思而悲。
之罘别我去，能不思我为。
洒埽县中居，引水经竹间。
嚣哗所不及，何异山中闲。
前陈百家书，食有肉与鱼。
先王遗文章，缀缉实在余。
礼称独学陋，易贵不远复。
作诗招之罘，晨夕抱饥渴。','',''),('quantangshi-18045','寄卢仝','韓愈','quantangshi','','卷19','玉川先生洛城里，破屋数间而已矣。
一奴长须不裹头，一婢赤脚老无齿。
辛勤奉养十余人，上有慈亲下妻子。
先生结发憎俗徒，闭门不出动一纪。
至今邻僧乞米送，仆忝县尹能不耻。
俸钱供给公私余，时致薄少助祭祀。
劝参留守谒大尹，言语才及輙掩耳。
水北山人得名声，去年去作幕下士。
水南山人又继往，鞍马仆从塞闾里。
少室山人索价高，两以谏官徴不起。
彼皆刺口论世事，有力未免遭驱使。
先生事业不可量，惟用法律自绳己。
春秋三传束高阁，独抱遗经究终始。
往年弄笔嘲同异，怪辞惊众谤不已。
近来自说寻坦途，犹上虚空跨绿駬。
去年生儿名添丁，意令与国充耘耔。
国家丁口连四海，岂无农夫亲耒耜。
先生抱才终大用，宰相未许终不仕。
假如不在陈力列，立言垂范亦足恃。
苗裔当蒙十世宥，岂谓贻厥无基址。
故知忠孝生天性，洁身乱伦安足拟。
昨晚长须来下状，隔墙恶少恶难似。
每骑屋山下窥阚，浑舍惊怕走折趾。
凭依婚媾欺官吏，不信令行能禁止。
先生受屈未曾语，忽此来告良有以。
嗟我身为赤县令，操权不用欲何俟。
立召贼曹呼伍伯，尽取鼠辈尸诸市。
先生又遣长须来，如此处置非所喜。
况又时当长养节，都邑未可猛政理。
先生固是余所畏，度量不敢窥涯涘。
放纵是谁之过欤，效尤戮仆愧前史。
买羊沽酒谢不敏，偶逢明月曜桃李。
先生有意许降临，更遣长须致双鲤。','',''),('quantangshi-18046','酬司门卢四兄云夫院长望秋作','韓愈','quantangshi','','卷19','长安雨洗新秋出，极目寒镜开尘函。
终南晓望蹋龙尾，倚天更觉青巉巉。
自知短浅无所补，从事久此穿朝衫。
归来得便即游览，暂似壮马脱重衔。
曲江荷花盖十里，江湖生目思莫缄。
乐游下瞩无远近，绿槐萍合不可芟。
白首寓居谁借问，平地寸步扃云岩。
云夫吾兄有狂气，嗜好与俗殊酸咸。
日来省我不肯去，论诗说赋相諵諵。
望秋一章已惊绝，犹言低抑避谤谗。
若使乘酣骋雄怪，造化何以当镌劖。
嗟我小生值强伴，怯胆变勇神明鉴。
驰坑跨谷终未悔，为利而止真贪馋。
高揖羣公谢名誉，远追甫白感至諴。
楼头完月不共宿，其奈就缺行攕攕。','',''),('quantangshi-18047','谁氏子','韓愈','quantangshi','','卷19','非痴非狂谁氏子，去入王屋称道士。
白头老母遮门啼，挽断衫袖留不止。
翠眉新妇年二十，载送还家哭穿市。
或云欲学吹凤笙，所慕灵妃嫓萧史。
又云时俗轻寻常，力行险怪取贵仕。
神仙虽然有传说，知者尽知其妄矣。
圣君贤相安可欺，干死穷山竟何俟。
呜呼余心诚岂弟，愿往敎诲究终始。
罚一劝百政之经，不从而诛未晚耳。
谁其友亲能哀怜，写吾此诗持送似。','',''),('quantangshi-18048','河南令舍池台','韓愈','quantangshi','','卷19','灌池才盈五六丈，筑台不过七八尺。
欲将层级压篱落，未许波澜量斗石。
规摹虽巧何足夸，景趣不远真可惜。
长令人吏远趋走，已有蛙黾助狼籍。','',''),('quantangshi-18049','送无本师归范阳','韓愈','quantangshi','','卷19','无本于为文，身大不及胆。
吾尝示之难，勇往无不敢。
蛟龙弄角牙，造次欲手揽。
众鬼囚大幽，下覰袭玄窞。
天阳熙四海，注视首不颔。
鲸鹏相摩窣，两举快一噉。
夫岂能必然，固已谢黯黮。
狂词肆滂葩，低昂见舒惨。
奸穷怪变得，往往造平澹。
蠭蝉碎锦缬，绿池披菡萏。
芝英擢荒榛，孤翮起连菼。
家住幽都远，未识气先感。
来寻吾何能，无殊嗜昌歜。
始见洛阳春，桃枝缀红糁。
遂来长安里，时卦转习坎。
老嬾无鬬心，久不事铅椠。
欲以金帛酬，举室常顑颔。
念当委我去，雪霜刻以憯。
狞飙搅空衢，天地与顿撼。
勉率吐歌诗，慰女别后览。','',''),('quantangshi-18050','石鼓歌','韓愈','quantangshi','','卷19','张生手持石鼓文，劝我试作石鼓歌。
少陵无人谪仙死，才薄将奈石鼓何。
周纲陵迟四海沸，宣王愤起挥天戈。
大开明堂受朝贺，诸侯劒佩鸣相磨。
搜于岐阳骋雄俊，万里禽兽皆遮罗。
镌功勒成告万世，凿石作鼓隳嵯峨。
从臣才艺咸第一，拣选撰刻留山阿。
雨淋日炙野火燎，鬼物守护烦撝呵。
公从何处得纸本，毫发尽备无差讹。
辞严义密读难晓，字体不类隶与科。
年深岂免有缺画，快劒斫断生蛟鼍。
鸾翔凤翥众仙下，珊瑚碧树交枝柯。
金绳铁索锁纽壮，古鼎跃水龙腾梭。
陋儒编诗不收入，二雅褊迫无委蛇。
孔子西行不到秦，掎摭星宿遗羲娥。
嗟予好古生苦晚，对此涕泪双滂沱。
忆昔初蒙博士徴，其年始改称元和。
故人从军在右辅，为我度量掘臼科。
濯冠沐浴告祭酒，如此至宝存岂多。
氊包席裹可立致，十鼓祗载数骆驼。
荐诸太庙比郜鼎，光价岂止百倍过。
圣恩若许留太学，诸生讲解得切磋。
观经鸿都尚填咽，坐见举国来奔波。
剜苔剔藓露节角，安置妥帖平不颇。
大厦深檐与盖覆，经历久远期无佗。
中朝大官老于事，讵肯感激徒媕婀。
牧童敲火牛砺角，谁复着手为摩挲。
日销月铄就埋没，六年西顾空吟哦。
羲之俗书趁姿媚，数纸尚可博白鹅。
继周八代争战罢，无人收拾理则那。
方今太平日无事，柄任儒术崇丘轲。
安能以此上论列，愿借辨口如悬河。
石鼓之歌止于此，呜呼吾意其蹉跎。','',''),('quantangshi-18051','双鸟诗','韓愈','quantangshi','','卷19','双鸟海外来，飞飞到中州。
一鸟落城市，一鸟集岩幽。
不得相伴鸣，尔来三千秋。
两鸟各闭口，万象衔口头。
春风卷地起，百鸟皆飘浮。
两鸟忽相逢，百日鸣不休。
有耳聒皆聋，有口反自羞。
百舌旧饶声，从此恒低头。
得病不呻唤，泯默至死休。
雷公告天公，百物须膏油。
自从两鸟鸣，聒乱雷声收。
鬼神怕嘲咏，造化皆停留。
草木有微情，挑抉示九州。
虫鼠诚微物，不堪苦诛求。
不停两鸟鸣，百物皆生愁。
不停两鸟鸣，自此无春秋。
不停两鸟鸣，日月难旋輈。
不停两鸟鸣，大法失九畴。
周公不为公，孔丘不为丘。
天公怪两鸟，各捉一处囚。
百虫与百鸟，然后鸣啾啾。
两鸟既别处，闭声省愆尤。
朝食千头龙，暮食千头牛。
朝饮河生尘，暮饮海绝流。
还当三千秋，更起鸣相酬。','',''),('quantangshi-18052','赠刘师服','韓愈','quantangshi','','卷19','羡君齿牙牢且洁，大肉硬饼如刀截。
我今呀豁落者多，所存十余皆兀臲。
匙抄烂饭稳送之，合口软嚼如牛呞。
妻儿恐我生怅望，盘中不飣栗与棃。
祗今年才四十五，后日悬知渐莽卤。
朱颜皓颈讶莫亲，此外诸余谁更数。
忆昔太公仕进初，口含两齿无赢余。
虞翻十三比岂少，遂自惋恨形于书。
丈夫命存百无害，谁能点检形骸外。
巨缗东钓傥可期，与子共饱鲸鱼脍。','',''),('quantangshi-18053','题炭谷湫祠堂','韓愈','quantangshi','','卷19','万生都阳明，幽暗鬼所寰。
嗟龙独何智，出入人鬼间。
不知谁为助，若执造化关。
厌处平地水，巢居插天山。
列峰若攒指，石盂仰环环。
巨灵高其捧，保此一掬悭。
森沈固含蓄，本以储阴奸。
鱼鼈蒙拥护，羣嬉傲天顽。
翾翾栖托禽，飞飞一何闲。
祠堂像侔真，擢玉纡烟鬟。
羣怪俨伺候，恩威在其颜。
我来日正中，悚惕思先还。
寄立尺寸地，敢言来途艰。
吁无吹毛刃，血此牛蹄殷。
至令乘水旱，鼓舞寡与鳏。
林丛镇冥冥，穷年无由删。
妍英杂艳实，星琐黄朱斑。
石级皆险滑，颠跻莫牵攀。
龙区雏众碎，付与宿已颁。
弃去可奈何，吾其死茅菅。','',''),('quantangshi-18054','听颖师弹琴','韓愈','quantangshi','','卷19','昵昵儿女语，恩怨相尔汝。
划然变轩昂，勇士赴敌场。
浮云柳絮无根蔕，天地阔远随飞扬。
喧啾百鸟羣，忽见孤凤皇。
跻攀分寸不可上，失势一落千丈强。
嗟余有两耳，未省听丝篁。
自闻颖师弹，起坐在一旁。
推手遽止之，湿衣泪滂滂。
颖乎尔诚能，无以冰炭置我肠。','',''),('quantangshi-18055','送陆畅归江南','韓愈','quantangshi','','卷19','举举江南子，名以能诗闻。
一来取高第，官佐东宫军。
迎妇丞相府，夸映秀士羣。
鸾鸣桂树间，观者何缤纷。
人事喜颠倒，旦夕异所云。
萧萧青云干，遂逐荆棘焚。
岁晚鸿雁过，乡思见新文。
践此秦关雪，家彼吴洲云。
悲啼上车女，骨肉不可分。
感慨都门别，丈夫酒方醺。
我实门下士，力薄蚋与蚊。
受恩不即报，永负湘中坟。','',''),('quantangshi-18056','送进士刘师服东归','韓愈','quantangshi','','卷19','猛虎落槛穽，坐食如孤㹠。
丈夫在富贵，岂必守一门。
公心有勇气，公口有直言。
奈何任埋没，不自求腾轩。
仆本亦进士，颇尝究根源。
由来骨鲠材，喜被软弱吞。
低头受侮笑，隐忍硉兀冤。
泥雨城东路，夏槐作云屯。
还家虽阙短，指日亲晨飧。
携持令名归，自足贻家尊。
时节不可翫，亲交可攀援。
勉来取金紫，勿久休中园。','',''),('quantangshi-18057','嘲鲁连子','韓愈','quantangshi','','卷19','鲁连细而黠，有似黄鹞子。
田巴兀老苍，怜汝矜爪觜。
开端要惊人，雄跨吾厌矣。
高拱禅鸿声，若辍一杯水。
独称唐虞贤，顾未知之耳。','',''),('quantangshi-18058','赠张籍','韓愈','quantangshi','','卷19','吾老着读书，余事不挂眼。
有儿虽甚怜，敎示不免简。
君来好呼出，踉蹡越门限。
惧其无所知，见则先愧赧。
昨因有缘事，上马插手版。
留君住厅食，使立侍盘𧣴。
薄暮归见君，迎我笑而莞。
指渠相贺言，此是黄金产。
吾爱其风骨，粹美无可拣。
试将诗义授，如以肉贯丳。
开祛露毫末，自得高蹇嵼。
我身蹈丘轲，爵位不早绾。
固宜长有人，文章绍编刬。
感荷君子德，怳若乘朽栈。
召令吐所记，解摘了瑟僴。
顾视窗壁间，亲戚竞觇矕。
喜气排寒冬，逼耳鸣睍睆。
如今更谁恨，便可耕灞浐。','',''),('quantangshi-18059','调张籍','韓愈','quantangshi','','卷19','李杜文章在，光焰万丈长。
不知羣儿愚，那用故谤伤。
蚍蜉撼大树，可笑不自量。
伊我生其后，举颈遥相望。
夜梦多见之，昼思反微茫。
徒观斧凿痕，不瞩治水航。
想当施手时，巨刃磨天扬。
垠崖划崩豁，干坤摆雷硠。
惟此两夫子，家居率荒凉。
帝欲长吟哦，故遣起且僵。
翦翎送笼中，使看百鸟翔。
平生千万篇，金薤垂琳琅。
仙官敕六丁，雷电下取将。
流落人间者，太山一毫芒。
我愿生两翅，捕逐出八荒。
精诚忽交通，百怪入我肠。
刺手拔鲸牙，举瓢酌天浆。
腾身跨汗漫，不着织女襄。
顾语地上友，经营无太忙。
乞君飞霞佩，与我高颉颃。','',''),('quantangshi-18060','卢郎中云夫寄示送盘谷子诗两章歌以和之','韓愈','quantangshi','','卷19','昔寻李愿向盘谷，正见高崖巨壁争开张。
是时新晴天井溢，谁把长劒倚太行。
冲风吹破落天外，飞雨白日洒洛阳。
东蹈燕川食旷野，有馈木蕨芽满筐。
马头溪深不可厉，借车载过水入箱。
平沙绿浪榜方口，雁鸭飞起穿垂杨。
穷探极览颇恣横，物外日月本不忙。
归来辛苦欲谁为，坐令再往之计堕眇芒。
闭门长安三日雪，推书扑笔歌慨慷。
旁无壮士遣属和，远忆卢老诗颠狂。
开缄忽覩送归作，字向纸上皆轩昂。
又知李侯竟不顾，方冬独入崔嵬藏。
我今进退几时决，十年蠢蠢随朝行。
家请官供不报答，何异雀鼠偷太仓。
行抽手版付丞相，不待弹劾还耕桑。','',''),('quantangshi-18061','寄皇甫湜','韓愈','quantangshi','','卷19','敲门惊昼睡，问报睦州吏。
手把一封书，上有皇甫字。
拆书放牀头，涕与泪垂四。
昏昏还就枕，惘惘梦相值。
悲哉无奇术，安得生两翅。','',''),('quantangshi-18062','病中赠张十八','韓愈','quantangshi','','卷19','中虚得暴下，避冷卧北窗。
不蹋晓鼓朝，安眠听逢逢。
籍也处闾里，抱能未施邦。
文章自娱戏，金石日击撞。
龙文百斛鼎，笔力可独扛。
谈舌久不掉，非君亮谁双。
扶几导之言，曲节初摐摐。
半途喜开凿，派别失大江。
吾欲盈其气，不令见麾幢。
牛羊满田野，解斾束空杠。
倾尊与斟酌，四壁堆罂缸。
玄帷隔雪风，照炉钉明釭。
夜阑纵捭阖，哆口疏眉厖。
势侔高阳翁，坐约齐横降。
连日挟所有，形躯顿胮肛。
将归乃徐谓，子言得无哤。
回军与角逐，斫树收穷庞。
雌声吐款要，酒壶缀羊腔。
君乃昆仑渠，籍乃岭头泷。
譬如蚁蛭微，讵可陵崆㟅。
幸愿终赐之，斩拔枿与桩。
从此识归处，东流水淙淙。','',''),('quantangshi-18063','杂诗','韓愈','quantangshi','','卷19','古史散左右，诗书置后前。
岂殊蠹书虫，生死文字间。
古道自愚憃，古言自包缠。
当今固殊古，谁与为欣欢。
独携无言子，共升昆仑颠。
长风飘襟裾，遂起飞高圆。
下视禹九州，一尘集豪端。
遨嬉未云几，下已亿万年。
向者夸夺子，万坟厌其巅。
惜哉抱所见，白黑未及分。
慷慨为悲咤，泪如九河飜。
指摘相告语，虽还今谁亲。
翩然下大荒，被发骑骐驎。','',''),('quantangshi-18064','寄崔二十六立之','韓愈','quantangshi','','卷19','西城员外丞，心迹两屈奇。
往岁战词赋，不将势力随。
下驴入省门，左右惊纷披。
傲兀坐试席，深丛见孤罴。
文如飜水成，初不用意为。
四座各低面，不敢捩眼窥。
升阶揖侍郎，归舍日未敧。
佳句喧众口，考官敢瑕疵。
连年收科第，若摘颔底髭。
回首卿相位，通途无他岐。
岂论校书郎，袍笏光参差。
童穉见称说，祝身得如斯。
侪辈妒且热，喘如竹筒吹。
老妇愿嫁女，约不论财赀。
老翁不量分，累月笞其儿。
搅搅争附托，无人角雄雌。
由来人间事，翻覆不可知。
安有巢中鷇，插翅飞天陲。
驹麛着爪牙，猛虎借与皮。
汝头有缰系，汝脚有索縻。
陷身泥沟间，谁复禀指撝。
不脱吏部选，可见偶与奇。
又作朝士贬，得非命所施。
客居京城中，十日营一炊。
逼迫走巴蛮，恩爱座上离。
昨来汉水头，始得完孤羇。
桁挂新衣裳，盎弃食残糜。
苟无饥寒苦，那用分高卑。
怜我还好古，宦途同险巘。
每旬遗我书，竟岁无差池。
新篇奚其思，风幡肆逶迤。
又论诸毛功，劈水看蛟螭。
雷电生睒睗，角鬣相撑披。
属我感穷景，抱华不能摛。
唱来和相报，愧叹俾我疵。
又寄百尺彩，绯红相盛衰。
巧能喻其诚，深浅抽肝脾。
开展放我侧，方餐涕垂匙。
朋交日凋谢，存者逐利移。
子宁独迷误，缀缀意益弥。
举头庭树豁，狂飙卷寒曦。
迢递山水隔，何由应埙篪。
别来就十年，君马记騧骊。
长女当及事，谁助出帨缡。
诸男皆秀朗，几能守家规。
文字锐气在，辉辉见旌麾。
摧肠与戚容，能复持酒巵。
我虽未耋老，发秃骨力羸。
所余十九齿，飘颻尽浮危。
玄花着两眼，视物隔褷䙰。
燕席谢不诣，游鞍悬莫骑。
敦敦凭书案，譬彼鸟黏黐。
且吾闻之师，不以物自隳。
孤豚眠粪壤，不慕太庙牺。
君看一时人，几辈先腾驰。
过半黑头死，阴虫食枯骴。
欢华不满眼，咎责塞两仪。
观名计之利，讵足相陪裨。
仁者耻贪冒，受禄量所宜。
无能食国惠，岂异哀癃罢。
久欲辞谢去，休令众睢睢。
况又婴疹疾，宁保躯不赀。
不能前死罢，内实慙神只。
旧籍在东郡，茅屋枳棘篱。
还归非无指，灞渭扬春澌。
生兮耕吾疆，死也埋吾陂。
文书自传道，不仗史笔垂。
夫子固吾党，新恩释衔羁。
去来伊洛上，相待安罛箅。
我有双饮𧣴，其银得朱提。
黄金涂物象，雕镌妙工倕。
乃令千里鲸，幺麽微螽斯。
犹能争明月，摆掉出渺弥。
野草花叶细，不辨薋菉葹。
緜緜相纠结，状似环城陴。
四隅芙蓉树，擢艳皆猗猗。
鲸以兴君身，失所逢百罹。
月以喻夫道，僶勉励莫亏。
草木明覆载，妍丑齐荣萎。
愿君恒御之，行止杂燧觿。
异日期对举，当如合分支。','',''),('quantangshi-18065','月蚀诗效玉川子作','韓愈','quantangshi','','卷19','元和庚寅斗插子，月十四日三更中。
森森万木夜僵立，寒气屓奰顽无风。
月形如白盘，完完上天东。
忽然有物来噉之，不知是何虫。
如何至神物，遭此狼狈凶。
星如撒沙出，攒集争强雄。
油灯不照席，是夕吐焰如长虹。
玉川子，涕泗下，中庭独行。
念此日月者，为天之眼睛。
此犹不自保，吾道何由行。
尝闻古老言，疑是虾蟆精。
径圆千里纳女腹，何处养女百丑形。
杷沙脚手钝，谁使女解缘青冥。
黄帝有四目，帝舜重其明。
今天祗两目，何故许食使偏盲。
尧呼大水浸十日，不惜万国赤子鱼头生。
女于此时若食日，虽食八九无嚵名。
赤龙黑鸟烧口热，翎鬣倒侧相搪撑。
婪酣大肚遭一饱，饥肠彻死无由鸣。
后时食月罪当死，天罗磕帀何处逃汝刑。
玉川子立于庭而言曰，地行贱臣仝。
再拜敢告上天公，臣有一寸刃。
可刳凶蟆肠，无梯可上天。
天阶无由有臣踪，寄牋东南风。
天门西北祈风通，丁宁附耳莫漏泄。
薄命正值飞廉慵，东方青色龙。
牙角何呀呀，从官百余座。
嚼啜烦官家，月蚀汝不知。
安用为龙窟天河，赤鸟司南方。
尾秃翅觰沙，月蚀于汝头。
汝口开呀呀，虾蟆掠汝两吻过。
忍学省事不以汝觜啄虾蟆，于菟蹲于西。
旗旄卫毵㲚，既从白帝祠。
又食于蜡礼有加，忍令月被恶物食。
枉于汝口插齿牙，乌龟怯奸。
怕寒缩颈，以壳自遮。
终令夸蛾抉汝出，卜师烧锥钻灼满板如星罗。
此外内外官，琐细不足科。
臣请悉埽除，慎勿许语令啾哗。
并光全耀归我月，盲眼镜净无纤瑕。
弊蛙拘送主府官，帝箸下腹尝其皤。
依前使兔操杵臼，玉阶桂树闲婆娑。
姮娥还宫室，太阳有室家。
天虽高，耳属地。
感臣赤心，使臣知意。
虽无明言，潜喻厥旨。
有气有形，皆吾赤子。
虽忿大伤，忍杀孩穉。
还汝月明，安行于次。
尽释众罪，以蛙磔死。','',''),('quantangshi-18066','孟生诗','韓愈','quantangshi','','卷19','孟生江海士，古貌又古心。
尝读古人书，谓言古犹今。
作诗三百首，窅默咸池音。
骑驴到京国，欲和熏风琴。
岂识天子居，九重郁沈沈。
一门百夫守，无籍不可寻。
晶光荡相射，旗戟翩以森。
迁延乍却走，惊怪靡自任。
举头看白日，泣涕下霑襟。
朅来游公卿，莫肯低华簪。
谅非轩冕族，应对多差参。
萍蓬风波急，桑榆日月侵。
奈何从进士，此路转岖嵚。
异质忌处羣，孤芳难寄林。
谁怜松桂性，竞爱桃李阴。
朝悲辞树叶，夕感归巢禽。
顾我多慷慨，穷檐时见临。
清宵静相对，发白聆苦吟。
采兰起幽念，眇然望东南。
秦吴修且阻，两地无数金。
我论徐方牧，好古天下钦。
竹实凤所食，德馨神所歆。
求观众丘小，必上泰山岑。
求观众流细，必泛沧溟深。
子其听我言，可以当所箴。
既获则思返，无为久滞淫。
卞和试三献，期子在秋砧。','',''),('quantangshi-18067','射训狐','韓愈','quantangshi','','卷19','有鸟夜飞名训狐，矜凶挟狡夸自呼。
乘时阴黑止我屋，声势慷慨非常麤。
安然大唤谁畏忌，造作百怪非无须。
聚鬼征妖自朋扇，摆掉栱桷颓塈涂。
慈母抱儿怕入席，那暇更护鸡窠雏。
我念干坤德泰大，卵此恶物常勤劬。
纵之岂即遽有害，斗柄行拄西南隅。
谁谓停奸计尤剧，意欲唐突羲和乌。
侵更历漏气弥厉，何由侥幸休须臾。
咨余往射岂得已，候女两眼张睢盱。
枭惊堕梁蛇走窦，一夫斩颈羣雏枯。','',''),('quantangshi-18068','将归赠孟东野房蜀客','韓愈','quantangshi','','卷19','君门不可入，势利互相推。
借问读书客，胡为在京师。
举头未能对，闭眼聊自思。
倏忽十六年，终朝苦寒饥。
宦途竟寥落，鬓发坐差池。
颍水清且寂，箕山坦而夷。
如今便当去，咄咄无自疑。','',''),('quantangshi-18069','答孟郊','韓愈','quantangshi','','卷19','规模背时利，文字覰天巧。
人皆余酒肉，子独不得饱。
才春思已乱，始秋悲又搅。
朝餐动及午，夜讽恒至卯。
名声暂膻腥，肠肚镇煎煼。
古心虽自鞭，世路终难拗。
弱拒喜张臂，猛拏闲缩爪。
见倒谁肯扶，从嗔我须齩。','',''),('quantangshi-18070','从仕','韓愈','quantangshi','','卷19','居闲食不足，从仕力难任。
两事皆害性，一生恒苦心。
黄昏归私室，惆怅起叹音。
弃置人间世，古来非独今。','',''),('quantangshi-18071','短灯檠歌','韓愈','quantangshi','','卷19','长檠八尺空自长，短檠二尺便且光。
黄帘绿幕朱户闭，风露气入秋堂凉。
裁衣寄远泪眼暗，搔头频挑移近牀。
太学儒生东鲁客，二十辞家来射策。
夜书细字缀语言，两目眵昏头雪白。
此时提携当案前，看书到晓那能眠。
一朝富贵还自恣，长檠高张照珠翠。
吁嗟世事无不然，墙角君看短檠弃。','',''),('quantangshi-18072','送刘师服','韓愈','quantangshi','','卷19','夏半阴气始，淅然云景秋。
蝉声入客耳，惊起不可留。
草草具盘馔，不待酒献酬。
士生为名累，有似鱼中鈎。
赍材入市卖，贵者恒难售。
岂不畏顦顇，为功忌中休。
勉哉耘其业，以待岁晚收。','',''),('quantangshi-18073','符读书城南','韓愈','quantangshi','','卷19','木之就规矩，在梓匠轮舆。
人之能为人，由腹有诗书。
诗书勤乃有，不勤腹空虚。
欲知学之力，贤愚同一初。
由其不能学，所入遂异闾。
两家各生子，提孩巧相如。
少长聚嬉戏，不殊同队鱼。
年至十二三，头角稍相疎。
二十渐乖张，清沟映污渠。
三十骨骼成，乃一龙一猪。
飞黄腾踏去，不能顾蟾蜍。
一为马前卒，鞭背生虫蛆。
一为公与相，潭潭府中居。
问之何因尔，学与不学欤。
金璧虽重宝，费用难贮储。
学问藏之身，身在则有余。
君子与小人，不系父母且。
不见公与相，起身自犂鉏。
不见三公后，寒饥出无驴。
文章岂不贵，经训乃菑畲。
潢潦无根源，朝满夕已除。
人不通古今，马牛而襟裾。
行身陷不义，况望多名誉。
时秋积雨霁，新凉入郊墟。
灯火稍可亲，简编可卷舒。
岂不旦夕念，为尔惜居诸。
恩义有相夺，作诗劝踌躇。','',''),('quantangshi-18074','示爽','韓愈','quantangshi','','卷19','宣城去京国，里数逾三千。
念汝欲别我，解装具盘筵。
日昏不能散，起坐相引牵。
冬夜岂不长，达旦灯烛然。
座中悉亲故，谁肯舍汝眠。
念汝将一身，西来曾几年。
名科揜众俊，州考居吏前。
今从府公召，府公又时贤。
时辈千百人，孰不谓汝妍。
汝来江南近，里闾故依然。
昔日同戏儿，看汝立路边。
人生但如此，其实亦可怜。
吾老世味薄，因循致留连。
强颜班行内，何实非罪愆。
才短难自力，惧终莫洗湔。
临分不汝诳，有路即归田。','',''),('quantangshi-18075','人日城南登高','韓愈','quantangshi','','卷19','初正候才兆，涉七气已弄。
霭霭野浮阳，晖晖水披冻。
圣朝身不废，佳节古所用。
亲交既许来，子妷亦可从。
盘蔬冬春杂，尊酒清浊共。
令征前事为，觞咏新诗送。
扶杖凌圮址，刺船犯枯葑。
恋池羣鸭回，释峤孤云纵。
人生本坦荡，谁使妄倥偬。
直指桃李阑，幽寻宁止重。','',''),('quantangshi-18076','病鸱','韓愈','quantangshi','','卷19','屋东恶水沟，有鸱堕鸣悲。
青泥揜两翅，拍拍不得离。
羣童呌相召，瓦砾争先之。
计校生平事，杀却理亦宜。
夺攘不愧耻，饱满盘天嬉。
晴日占光景，高风恣追随。
遂凌鸾凤羣，肯顾鸿鹄卑。
今者命运穷，遭逢巧丸儿。
中汝要害处，汝能不得施。
于吾乃何有，不忍乘其危。
丐汝将死命，浴以清水池。
朝餐辍鱼肉，暝宿防狐狸。
自知无以致，蒙德久犹疑。
饱入深竹丛，饥来傍阶基。
亮无责报心，固以听所为。
昨日有气力，飞跳弄藩篱。
今晨忽径去，曾不报我知。
侥幸非汝福，天衢汝休窥。
京城事弹射，竖子不易欺。
勿讳泥坑辱，泥坑乃良规。','',''),('quantangshi-18077','华山女','韓愈','quantangshi','','卷19','街东街西讲佛经，撞钟吹螺闹宫庭。
广张罪福资诱胁，听众狎恰排浮萍。
黄衣道士亦讲说，座下寥落如明星。
华山女儿家奉道，欲驱异敎归仙灵。
洗妆拭面着冠帔，白咽红颊长眉青。
遂来升座演真诀，观门不许人开扃。
不知谁人暗相报，訇然振动如雷霆。
扫除众寺人迹绝，骅骝塞路连椔軿。
观中人满坐观外，后至无地无由听。
抽簪脱钏解环佩，堆金叠玉光青荧。
天门贵人传诏召，六宫愿识师颜形。
玉皇颔首许归去，乘龙驾鹤去青冥。
豪家少年岂知道，来遶百帀脚不停。
云牕雾阁事恍惚，重重翠幕深金屏。
仙梯难攀俗缘重，浪凭青鸟通丁宁。','',''),('quantangshi-18078','读皇甫湜公安园池诗书其后二首 一','韓愈','quantangshi','','卷19','晋人目二子，其犹吹一吷。
区区自其下，顾肯挂牙舌。
春秋书王法，不诛其人身。
尔雅注虫鱼，定非磊落人。
湜也困公安，不自闲穷年。
枉智思掎摭，粪壤污秽岂有臧。
诚不如两忘，但以一概量。','',''),('quantangshi-18079','读皇甫湜公安园池诗书其后二首 二','韓愈','quantangshi','','卷19','我有一池水，蒲苇生其间。
虫鱼沸相嚼，日夜不得闲。
我初往观之，其后益不观。
观之乱我意，不如不观完。
用将济诸人，舍得业孔颜。
百年讵几时，君子不可闲。','',''),('quantangshi-18080','路傍堠','韓愈','quantangshi','','卷19','堆堆路傍堠，一双复一只。
迎我出秦关，送我入楚泽。
千以高山遮，万以远水隔。
吾君勤听治，照与日月敌。
臣愚幸可哀，臣罪庶可释。
何当迎送归，缘路高历历。','',''),('quantangshi-18081','食曲河驿','韓愈','quantangshi','','卷19','晨及曲河驿，凄然自伤情。
羣乌巢庭树，乳燕飞檐楹。
而我抱重罪，孑孑万里程。
亲戚顿乖角，图史弃纵横。
下负明义重，上孤朝命荣。
杀身谅无补，何用答生成。','',''),('quantangshi-18082','过南阳','韓愈','quantangshi','','卷19','南阳郭门外，桑下麦青青。
行子去未已，春鸠鸣不停。
秦商邈既远，湖海浩将经。
孰忍生以戚，吾其寄余龄。','',''),('quantangshi-18083','泷吏','韓愈','quantangshi','','卷19','南行逾六旬，始下昌乐泷。
险恶不可状，船石相舂撞。
往问泷头吏，潮州尚几里。
行当何时到，土风复何似。
泷吏垂手笑，官何问之愚。
譬官居京邑，何由知东吴。
东吴游宦乡，官知自有由。
潮州底处所，有罪乃窜流。
侬幸无负犯，何由到而知。
官今行自到，那遽妄问为。
不虞卒见困，汗出愧且骇。
吏曰聊戏官，侬尝使往罢。
岭南大抵同，官去道苦辽。
下此三千里，有州始名潮。
恶溪瘴毒聚，雷电常汹汹。
鳄鱼大于船，牙眼怖杀侬。
州南数十里，有海无天地。
飓风有时作，掀簸真差事。
圣人于天下，于物无不容。
比闻此州囚，亦在生还侬。
官无嫌此州，固罪人所徙。
官当明时来，事不待说委。
官不自谨慎，宜即引分往。
胡为此水边，神色久戃慌。
㼚大瓶甖小，所任自有宜。
官何不自量，满溢以取斯。
工农虽小人，事业各有守。
不知官在朝，有益国家不。
得无虱其间，不武亦不文。
仁义饬其躬，巧奸败羣伦。
叩头谢吏言，始惭今更羞。
历官二十余，国恩竝未酬。
凡吏之所诃，嗟实颇有之。
不即金木诛，敢不识恩私。
潮州虽云远，虽恶不可过。
于身实已多，敢不持自贺。','',''),('quantangshi-18084','赠别元十八协律六首 一','韓愈','quantangshi','','卷19','知识久去眼，吾行其既远。
瞢瞢莫訾省，默默但寝饭。
子兮何为者，冠佩立宪宪。
何氏之从学，兰蕙已满畹。
于何翫其光，以至岁向晚。
治惟尚和同，无俟于謇謇。
或师绝学贤，不以艺自挽。
子兮独如何，能自媚婉娩。
金石出声音，宫室发关楗。
何人识章甫，而知骏蹄踠。
惜乎吾无居，不得留息偃。
临当背面时，裁诗示缱绻。','',''),('quantangshi-18085','赠别元十八协律六首 二','韓愈','quantangshi','','卷19','英英桂林伯，实惟文武特。
远劳从事贤，来吊逐臣色。
南裔多山海，道里屡纡直。
风波无程期，所忧动不测。
子行诚艰难，我去未穷极。
临别且何言，有泪不可拭。','',''),('quantangshi-18086','赠别元十八协律六首 三','韓愈','quantangshi','','卷19','吾友柳子厚，其人艺且贤。
吾未识子时，已览赠子篇。
寤寐想风采，于今已三年。
不意流窜路，旬日同食眠。
所闻昔已多，所得今过前。
如何又须别，使我抱悁悁。','',''),('quantangshi-18087','赠别元十八协律六首 四','韓愈','quantangshi','','卷19','势要情所重，排斥则埃尘。
骨肉未免然，又况四海人。
嶷嶷桂林伯，矫矫义勇身。
生平所未识，待我逾交亲。
遗我数幅书，继以药物珍。
药物防瘴疠，书劝养形神。
不知四罪地，岂有再起辰。
穷途致感激，肝胆还轮囷。','',''),('quantangshi-18088','赠别元十八协律六首 五','韓愈','quantangshi','','卷19','读书患不多，思义患不明。
患足已不学，既学患不行。
子今四美具，实大华亦荣。
王官不可阙，未宜后诸生。
嗟我摈南海，无由助飞鸣。','',''),('quantangshi-18089','赠别元十八协律六首 六','韓愈','quantangshi','','卷19','寄书龙城守，君骥何时秣。
峡山逢飓风，雷电助撞捽。
乘潮簸扶胥，近岸指一发。
两岩虽云牢，水石互飞发。
屯门虽云高，亦映波浪没。
余罪不足惜，子生未宜忽。
胡为不忍别，感谢情至骨。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-18090','初南食贻元十八协律','韓愈','quantangshi','','卷19','鲎实如惠文，骨眼相负行。
蚝相黏为山，百十各自生。
蒲鱼尾如蛇，口眼不相营。
蛤即是虾蟆，同实浪异名。
章举马甲柱，鬬以怪自呈。
其余数十种，莫不可叹惊。
我来御魑魅，自宜味南烹。
调以咸与酸，芼以椒与橙。
腥臊始发越，咀吞面汗騂。
惟蛇旧所识，实惮口眼狞。
开笼听其去，郁屈尚不平。
卖尔非我罪，不屠岂非情。
不祈灵珠报，幸无嫌怨并。
聊歌以记之，又以告同行。','',''),('quantangshi-18091','宿曾江口示侄孙湘二首 一','韓愈','quantangshi','','卷19','云昏水奔流，天水漭相围。
三江灭无口，其谁识涯圻。
暮宿投民村，高处水半扉。
犬鸡俱上屋，不复走与飞。
篙舟入其家，暝闻屋中唏。
问知岁常然，哀此为生微。
海风吹寒晴，波扬众星辉。
仰视北斗高，不知路所归。','',''),('quantangshi-18092','宿曾江口示侄孙湘二首 二','韓愈','quantangshi','','卷19','舟行忘故道，屈曲高林间。
林间无所有，奔流但潺潺。
嗟我亦拙谋，致身落南蛮。
茫然失所诣，无路何能还。','',''),('quantangshi-18093','答柳柳州食虾蟆','韓愈','quantangshi','','卷19','虾蟆虽水居，水特变形貌。
强号为蛙蛤，于实无所校。
虽然两股长，其奈脊皴疱。
跳踯虽云高，意不离泞淖。
鸣声相呼和，无理只取闹。
周公所不堪，洒灰垂典敎。
我弃愁海滨，恒愿眠不觉。
叵堪朋类多，沸耳作惊爆。
端能败笙磬，仍工乱学校。
虽蒙句践礼，竟不闻报效。
大战元鼎年，孰强孰败桡。
居然当鼎味，岂不辱钓罩。
余初不下喉，近亦能稍稍。
常惧染蛮夷，失平生好乐。
而君复何为，甘食比豢豹。
猎较务同俗，全身斯为孝。
哀哉思虑深，未见许回棹。','',''),('quantangshi-18094','别赵子','韓愈','quantangshi','','卷19','我迁于揭阳，君先揭阳居。
揭阳去京华，其里万有余。
不谓小郭中，有子可与娱。
心平而行高，两通诗与书。
婆娑海水南，簸弄明月珠。
及我迁宜春，意欲携以俱。
摆头笑且言，我岂不足欤。
又奚为于北，往来以纷如。
海中诸山中，幽子颇不无。
相期风涛观，已久不可渝。
又尝疑龙虾，果谁雄牙须。
蚌蠃鱼鼈虫，瞿瞿以狙狙。
识一已忘十，大同细自殊。
欲一穷究之，时岁屡谢除。
今子南且北，岂非亦有图。
人心未尝同，不可一理区。
宜各从所务，未用相贤愚。','',''),('quantangshi-18095','除官赴阙至江州寄鄂岳李大夫','韓愈','quantangshi','','卷19','盆城去鄂渚，风便一日耳。
不枉故人书，无因帆江水。
故人辞礼闱，旌节镇江圻。
而我窜逐者，龙钟初得归。
别来已三岁，望望长迢递。
咫尺不相闻，平生那可计。
我齿落且尽，君鬓白几何。
年皆过半百，来日苦无多。
少年乐新知，衰暮思故友。
譬如亲骨肉，宁免相可不。
我昔实愚蠢，不能降色辞。
子犯亦有言，臣犹自知之。
公其务贳过，我亦请改事。
桑榆傥可收，愿寄相思字。','',''),('quantangshi-18096','南山有高树行赠李宗闵','韓愈','quantangshi','','卷19','南山有高树，花叶何衰衰。
上有凤皇巢，凤皇乳且栖。
四旁多长枝，羣鸟所托依。
黄鹄据其高，众鸟接其卑。
不知何山鸟，羽毛有光辉。
飞飞择所处，正得众所希。
上承凤皇恩，自期永不衰。
中与黄鹄羣，不自隐其私。
下视众鸟羣，汝徒竟何为。
不知挟丸子，心默有所规。
弹汝枝叶间，汝翅不觉摧。
或言由黄鹄，黄鹄岂有之。
慎勿猜众鸟，众鸟不足猜。
无人语凤皇，汝屈安得知。
黄鹄得汝去，婆娑弄毛衣。
前汝下视鸟，各议汝瑕疵。
汝岂无朋匹，有口莫肯开。
汝落蒿艾间，几时复能飞。
哀哀故山友，中夜思汝悲。
路远翅翎短，不得持汝归。','',''),('quantangshi-18097','猛虎行','韓愈','quantangshi','','卷19','猛虎虽云恶，亦各有匹侪。
羣行深谷间，百兽望风低。
身食黄熊父，子食赤豹麛。
择肉于熊豹，肯视兔与狸。
正昼当谷眠，眼有百步威。
自矜无当对，气性纵以乖。
朝怒杀其子，暮还食其妃。
匹侪四散走，猛虎还孤栖。
狐鸣门两旁，乌鹊从噪之。
出逐猴入居，虎不知所归。
谁云猛虎恶，中路正悲啼。
豹来衔其尾，熊来攫其颐。
猛虎死不辞，但惭前所为。
虎坐无助死，况如汝细微。
故当结以信，亲当结以私。
亲故且不保，人谁信汝为。','',''),('quantangshi-18098','雪后寄崔二十六丞公','韓愈','quantangshi','','卷19','蓝田十月雪塞关，我兴南望愁羣山。
攒天嵬嵬冻相映，君乃寄命于其间。
秩卑俸薄食口众，岂有酒食开容颜。
殿前羣公赐食罢，骅骝蹋路骄且闲。
称多量少鉴裁密，岂念幽桂遗榛菅。
几欲犯严出荐口，气象硉兀未可攀。
归来殒涕揜关卧，心之纷乱谁能删。
诗翁憔悴斸荒棘，清玉刻佩联玦环。
脑脂遮眼卧壮士，大弨挂壁无由弯。
干坤惠施万物遂，独于数子怀偏悭。
朝欷暮唶不可解，我心安得如石顽。','',''),('quantangshi-18099','送僧澄观','韓愈','quantangshi','','卷19','浮屠西来何施为，扰扰四海争奔驰。
构楼架阁切星汉，夸雄鬬丽止者谁。
僧伽后出淮泗上，势到众佛尤恢奇。
越商胡贾脱身罪，圭璧满船宁计资。
清淮无波平如席，栏柱倾扶半天赤。
火烧水转扫地空，突兀便高三百尺。
影沈潭底龙惊遁，当昼无云跨虚碧。
借问经营本何人，道人澄观名籍籍。
愈昔从军大梁下，往来满屋贤豪者。
皆言澄观虽僧徒，公才吏用当今无。
后从徐州辟书至，纷纷过客何由记。
人言澄观乃诗人，一座竞吟诗句新。
向风长叹不可见，我欲收歛加冠巾。
洛阳穷秋厌穷独，丁丁啄门疑啄木。
有僧来访呼使前，伏犀插脑高颊权。
惜哉已老无所及，坐睨神骨空潸然。
临淮太守初到郡，远遣州民送音问。
好奇赏俊直难逢，去去为致思从容。','',''),('quantangshi-18100','山南郑相公樊员外酬答为诗其末咸有见及语樊封以示愈依赋十四韵以献','韓愈','quantangshi','','卷19','梁维西南屏，山厉水刻屈。
禀生肖剿刚，难谐在民物。
荥公鼎轴老，烹斡力健倔。
帝咨女予往，牙纛前岔坲。
威风挟惠气，盖壤两劘拂。
茫漫华黑间，指画变怳歘。
诚既富而美，章汇霍炳蔚。
日延讲大训，龟判错衮黻。
樊子坐宾署，演孔刮老佛。
金舂撼玉应，厥臭剧蕙郁。
遗我一言重，跽受惕斋栗。
辞悭义卓阔，呀豁疚掊掘。
如新去耵聍，雷霆逼飓䫻。
缀此岂为训，俚言绍庄屈。','',''),('quantangshi-18101','奉和武相公镇蜀时咏使宅韦太尉所养孔雀','韓愈','quantangshi','','卷19','穆穆鸾凤友，何年来止兹。
飘零失故态，隔绝抱长思。
翠角高独耸，金华焕相差。
坐蒙恩顾重，毕命守堦墀。','',''),('quantangshi-18102','感春三首 一','韓愈','quantangshi','','卷19','偶坐藤树下，暮春下旬间。
藤阴已可庇，落蘂还漫漫。
亹亹新叶大，珑珑晚花干。
青天高寥寥，两蝶飞翻翻。
时节适当尔，怀悲自无端。','',''),('quantangshi-18103','感春三首 二','韓愈','quantangshi','','卷19','黄黄芜菁花，桃李事已退。
狂风簸枯榆，狼籍九衢内。
春序一如此，汝颜安足赖。
谁能驾飞车，相从观海外。','',''),('quantangshi-18104','感春三首 三','韓愈','quantangshi','','卷19','晨游百花林，朱朱兼白白。
柳枝弱而细，悬树垂百尺。
左右同来人，金紫贵显剧。
娇童为我歌，哀响跨筝笛。
艳姬蹋筵舞，清眸刺劒戟。
心怀平生友，莫一在燕席。
死者长眇芒，生者困乖隔。
少年真可喜，老大百无益。','',''),('quantangshi-18105','早赴街西行香赠卢李二中舍人','韓愈','quantangshi','','卷19','天街东西异，祗命遂成游。
月明御沟晓，蝉吟堤树秋。
老僧情不薄，僻寺境还幽。
寂寥二三子，归骑得相收。','',''),('quantangshi-18106','晚寄张十八助敎周郎博士','韓愈','quantangshi','','卷19','日薄风景旷，出归偃前檐。
晴云如擘絮，新月似磨镰。
田野兴偶动，衣冠情久厌。
吾生可携手，叹息岁将淹。','',''),('quantangshi-18107','题张十八所居','韓愈','quantangshi','','卷19','君居泥沟上，沟浊萍青青。
蛙讙桥未扫，蝉嘒门长扃。
名秩后千品，诗文齐六经。
端来问奇字，为我讲声形。','',''),('quantangshi-18108','奉酬卢给事云夫四兄曲江荷花行见寄并呈上钱七兄阁老张十八助敎','韓愈','quantangshi','','卷19','曲江千顷秋波净，平铺红云盖明镜。
大明宫中给事归，走马来看立不正。
遗我明珠九十六，寒光映骨睡骊目。
我今官闲得婆娑，问言何处芙蓉多。
撑舟昆明度云锦，脚敲两舷呌吴歌。
太白山高三百里，负雪崔嵬插花里。
玉山前却不复来，曲江汀滢水平杯。
我时相思不觉一回首，天门九扇相当开。
上界真人足官府，岂如散仙鞭笞鸾凤终日相追陪。','',''),('quantangshi-18109','奉和钱七兄曹长盆池所植','韓愈','quantangshi','','卷19','翻翻江浦荷，而今生在此。
擢擢菰叶长，芳根复谁徙。
露涵两鲜翠，风荡相磨倚。
但取主人知，谁言盆盎是。','',''),('quantangshi-18110','记梦','韓愈','quantangshi','','卷19','夜梦神官与我言，罗缕道妙角与根。
挈携陬维口澜翻，百二十刻须臾间。
我听其言未云足，舍我先度横山腹。
我徒三人共追之，一人前度安不危。
我亦平行蹋𠿕𧇠，神完骨蹻脚不掉。
侧身上视溪谷盲，杖撞玉版声彭𦨻。
神官见我开颜笑，前对一人壮非少。
石坛坡陀可坐卧，我手承颏肘拄座。
隆楼杰阁磊嵬高，天风飘飘吹我过。
壮非少者哦七言，六字常语一字难。
我以指撮白玉丹，行且咀噍行诘盘。
口前截断第二句，绰虐顾我颜不欢。
乃知仙人未贤圣，护短凭愚邀我敬。
我能屈曲自世间，安能从汝巢神山。','',''),('quantangshi-18111','南内朝贺归呈同官','韓愈','quantangshi','','卷19','薄云蔽秋曦，清雨不成泥。
罢贺南内衙，归凉晓凄凄。
绿槐十二街，涣散驰轮蹄。
余惟戆书生，孤身无所赍。
三黜竟不去，致官九列齐。
岂惟一身荣，佩玉冠簪犀。
滉荡天门高，着籍朝厥妻。
文才不如人，行又无町畦。
问之朝廷事，略不知东西。
况于经籍深，岂究端与倪。
君恩太山重，不见酬稗稊。
所职事无多，又不自提撕。
明庭集孔鸾，曷取于凫鹥。
树以松与柏，不宜间蒿藜。
婉娈自媚好，几时不见挤。
贪食以忘躯，尠不调盐醯。
法吏多少年，磨淬出角圭。
将举汝愆尤，以为己阶梯。
收身归关东，期不到死迷。','',''),('quantangshi-18112','朝归','韓愈','quantangshi','','卷19','峩峩进贤冠，耿耿水苍佩。
服章岂不好，不与德相对。
顾影听其声，赬颜汗渐背。
进乏犬鸡效，又不勇自退。
坐食取其肥，无堪等聋瞶。
长风吹天墟，秋日万里晒。
抵暮但昏眠，不成歌慷慨。','',''),('quantangshi-18113','杂诗四首 一','韓愈','quantangshi','','卷19','朝蝇不须驱，暮蚊不可拍。
蝇蚊满八区，可尽与相格。
得时能几时，与汝恣啖咋。
凉风九月到，扫不见踪迹。','',''),('quantangshi-18114','杂诗四首 二','韓愈','quantangshi','','卷19','鹊鸣声楂楂，乌噪声擭擭。
争鬬庭宇间，持身博弹射。
黄鹄能忍饥，两翅久不擘。
苍苍云海路，岁晚将无获。','',''),('quantangshi-18115','杂诗四首 三','韓愈','quantangshi','','卷19','截橑为欂栌，斵楹以为椽。
束蒿以代之，小大不相权。
虽无风雨灾，得不覆且颠。
解辔弃骐麟，蹇驴鞭使前。
昆仑高万里，岁尽道苦邅。
停车卧轮下，绝意于神仙。','',''),('quantangshi-18116','杂诗四首 四','韓愈','quantangshi','','卷19','雀鸣朝营食，鸠鸣暮觅羣。
独有知时鹤，虽鸣不缘身。
喑蝉终不鸣，有抱不列陈。
蛙黾鸣无谓，合合祗乱人。','',''),('quantangshi-18117','读东方朔杂事','韓愈','quantangshi','','卷19','严严王母宫，下维万仙家。
噫欠为飘风，濯手大雨沱。
方朔乃竖子，骄不加禁诃。
偷入雷电室，輷輘掉狂车。
王母闻以笑，卫官助呀呀。
不知万万人，生身埋泥沙。
簸顿五山踣，流漂八维蹉。
曰吾儿可憎，奈此狡狯何。
方朔闻不喜，褫身络蛟蛇。
瞻相北斗柄，两手自相挼。
羣仙急乃言，百犯庸不科。
向观睥睨处，事在不可赦。
欲不布露言，外口实喧哗。
王母不得已，颜嚬口赍嗟。
颔头可其奏，送以紫玉珂。
方朔不惩创，挟恩更矜夸。
诋欺刘天子，正昼溺殿衙。
一旦不辞诀，摄身凌苍霞。','',''),('quantangshi-18118','谴疟鬼','韓愈','quantangshi','','卷19','屑屑水帝魂，谢谢无余辉。
如何不肖子，尚奋疟鬼威。
乘秋作寒热，翁妪所駡讥。
求食欧泄间，不知臭秽非。
医师加百毒，熏灌无停机。
灸师施艾炷，酷若猎火围。
诅师毒口牙，舌作霹雳飞。
符师弄刀笔，丹墨交横挥。
咨汝之胄出，门户何巍巍。
祖轩而父顼，未沫于前徽。
不修其操行，贱薄似汝稀。
岂不忝厥祖，腼然不知归。
湛湛江水情，归居安汝妃。
清波为裳衣，白石为门畿。
呼吸明月光，手掉芙蓉旗。
降集随九歌，饮芳而食菲。
赠汝以好辞，咄汝去莫违。','',''),('quantangshi-18119','示儿','韓愈','quantangshi','','卷19','始我来京师，止携一束书。
辛勤三十年，以有此屋庐。
此屋岂为华，于我自有余。
中堂高且新，四时登牢蔬。
前荣馔宾亲，冠婚之所于。
庭内无所有，高树八九株。
有藤娄络之，春华夏阴敷。
东堂坐见山，云风相吹嘘。
松果连南亭，外有瓜芋区。
西偏屋不多，槐榆翳空虚。
山鸟旦夕鸣，有类涧谷居。
主妇治北堂，膳服适戚疎。
恩封高平君，子孙从朝裾。
开门问谁来，无非卿大夫。
不知官高卑，玉带悬金鱼。
问客之所为，峨冠讲唐虞。
酒食罢无为，棋槊以相娱。
凡此座中人，十九持钧枢。
又问谁与频，莫与张樊如。
来过亦无事，考评道精麤。
跹跹媚学子，墙屏日有徒。
以能问不能，其蔽岂可祛。
嗟我不修饰，事与庸人俱。
安能坐如此，比肩于朝儒。
诗以示儿曹，其无迷厥初。','',''),('quantangshi-18120','庭楸','韓愈','quantangshi','','卷19','庭楸止五株，共生十步间。
各有藤绕之，上各相鈎联。
下叶各垂地，树颠各云连。
朝日出其东，我常坐西偏。
夕日在其西，我常坐东边。
当昼日在上，我在中央间。
仰视何青青，上不见纤穿。
朝暮无日时，我且八九旋。
濯濯晨露香，明珠何联联。
夜月来照之，蒨蒨自生烟。
我已自顽钝，重遭五楸牵。
客来尚不见，肯到权门前。
权门众所趋，有客动百千。
九牛亡一毛，未在多少间。
往既无可顾，不往自可怜。','',''),('quantangshi-18121','翫月喜张十八员外以王六秘书至','韓愈','quantangshi','','卷19','前夕虽十五，月长未满规。
君来晤我时，风露渺无涯。
浮云散白石，天宇开青池。
孤质不自惮，中天为君施。
翫翫夜遂久，亭亭曙将披。
况当今夕圆，又以嘉客随。
惜无酒食乐，但用歌嘲为。','',''),('quantangshi-18122','和李相公摄事南郊览物兴怀呈一二知旧','韓愈','quantangshi','','卷19','灿灿辰角曙，亭亭寒露朝。
川原共澄暎，云日还浮飘。
上宰严祀事，清途振华镳。
圆丘峻且坦，前对南山标。
村树黄复绿，中田稼何饶。
顾瞻想岩谷，兴叹倦尘嚣。
惟彼颠瞑者，去公岂不辽。
为仁朝自治，用静兵以销。
勿惮吐捉勤，可歌风雨调。
圣贤相遇少，功德今宣昭。','',''),('quantangshi-18123','和裴仆射相公假山十一韵','韓愈','quantangshi','','卷19','公乎真爱山，看山旦连夕。
犹嫌山在眼，不得着脚历。
枉语山中人，匄我涧侧石。
有来应公须，归必载金帛。
当轩乍骈罗，随势忽开坼。
有洞若神剜，有岩类天划。
终朝岩洞间，歌鼓燕宾戚。
孰谓衡霍期，近在王侯宅。
傅氏筑已卑，磻溪钓何激。
逍遥功德下，不与事相摭。
乐我盛明朝，于焉傲今昔。','',''),('quantangshi-18124','与张十八同效阮步兵一日复一夕','韓愈','quantangshi','','卷19','一日复一日，一朝复一朝。
秖见有不如，不见有所超。
食作前日味，事作前日调。
不知久不死，悯悯尚谁要。
富贵自絷拘，贫贱亦煎焦。
俯仰未得所，一世已解镳。
譬如笼中鹤，六翮无所摇。
譬如兔得蹄，安用东西跳。
还看古人书，复举前人瓢。
未知所究竟，且作新诗谣。','',''),('quantangshi-18125','送诸葛觉往随州读书','韓愈','quantangshi','','卷19','邺侯家多书，插架三万轴。
一一悬牙签，新若手未触。
为人强记览，过眼不再读。
伟哉羣圣文，磊落载其腹。
行年五十余，出守数已六。
京邑有旧庐，不容久食宿。
台阁多官员，无地寄一足。
我虽官在朝，气势日局缩。
屡为丞相言，虽恳不见录。
送行过浐水，东望不转目。
今子从之游，学问得所欲。
入海观龙鱼，矫翮逐黄鹄。
勉为新诗章，月寄三四幅。','',''),('quantangshi-18126','南溪始泛三首 一','韓愈','quantangshi','','卷19','榜舟南山下，上上不得返。
幽事随去多，孰能量近远。
阴沈过连树，藏昂抵横坂。
石麤肆磨砺，波恶厌牵挽。
或倚偏岸渔，竟就平洲饭。
点点暮雨飘，梢梢新月偃。
余年懔无几，休日怆已晚。
自是病使然，非由取高蹇。','',''),('quantangshi-18127','南溪始泛三首 二','韓愈','quantangshi','','卷19','南溪亦清驶，而无檝与舟。
山农惊见之，随我观不休。
不惟儿童辈，或有杖白头。
馈我笼中瓜，劝我此淹留。
我云以病归，此已颇自由。
幸有用余俸，置居在西畴。
囷仓米谷满，未有旦夕忧。
上去无得得，下来亦悠悠。
但恐烦里闾，时有缓急投。
愿为同社人，鸡豚燕春秋。','',''),('quantangshi-18128','南溪始泛三首 三','韓愈','quantangshi','','卷19','足弱不能步，自宜收朝迹。
羸形可舆致，佳观安事掷。
即此南坂下，久闻有水石。
拕舟入其间，溪流正清激。
随波吾未能，峻濑乍可刺。
鹭起若导吾，前飞数十尺。
亭亭柳带沙，团团松冠壁。
归时还尽夜，谁谓非事役。','',''),('quantangshi-18129','题楚昭王庙','韓愈','quantangshi','','卷19','丘坟满目衣冠尽，城阙连云草树荒。
犹有国人怀旧德，一间茅屋祭昭王。','',''),('quantangshi-18130','宿龙宫滩','韓愈','quantangshi','','卷19','浩浩复汤汤，滩声抑更扬。
奔流疑激电，惊浪似浮霜。
梦觉灯生晕，宵残雨送凉。
如何连晓语，一半是思乡。','',''),('quantangshi-18131','叉鱼招张功曹','韓愈','quantangshi','','卷19','叉鱼春岸阔，此兴在中宵。
大炬然如昼，长船缚似桥。
深窥沙可数，静搒水无摇。
刃下那能脱，波间或自跳。
中鳞怜锦碎，当目讶珠销。
迷火逃翻近，惊人去暂遥。
竞多心转细，得隽语时嚣。
潭罄知存寡，舷平觉获饶。
交头疑凑饵，骈首类同条。
濡沫情虽密，登门事已辽。
盈车欺故事，饲犬验今朝。
血浪凝犹沸，腥风远更飘。
盖江烟羃羃，拂棹影寥寥。
獭去愁无食，龙疑惧见烧。
如棠名既误，钓渭日徒消。
文客惊先赋，篙工喜尽谣。
脍成思我友，观乐忆吾僚。
自可捐忧累，何须强问鸮。','',''),('quantangshi-18132','李员外寄纸笔','韓愈','quantangshi','','卷19','题是临池后，分从起草余。
兔尖针莫竝，茧净雪难如。
莫怪殷勤谢，虞卿正着书。','',''),('quantangshi-18133','次同冠峡','韓愈','quantangshi','','卷19','今日是何朝，天晴物色饶。
落英千尺堕，游丝百丈飘。
泄乳交岩脉，悬流揭浪标。
无心思岭北，猿鸟莫相撩。','',''),('quantangshi-18134','答张十一功曹','韓愈','quantangshi','','卷19','山净江空水见沙，哀猿啼处两三家。
篔簹竞长纤纤笋，踯躅闲开艳艳花。
未报恩波知死所，莫令炎瘴送生涯。
吟君诗罢看双鬓，斗觉霜毛一半加。','',''),('quantangshi-18135','郴州祈雨','韓愈','quantangshi','','卷19','乞雨女郎魂，炮羞洁且繁。
庙开鼯鼠呌，神降越巫言。
旱气期销荡，阴官想骏奔。
行看五马入，萧飒已随轩。','',''),('quantangshi-18136','湘中酬张十一功曹','韓愈','quantangshi','','卷19','休垂绝徼千行泪，共泛清湘一叶舟。
今日岭猿兼越鸟，可怜同听不知愁。','',''),('quantangshi-18137','郴口又赠二首 一','韓愈','quantangshi','','卷19','山作剑攒江写镜，扁舟斗转疾于飞。
回头笑向张公子，终日思归此日归。','',''),('quantangshi-18138','郴口又赠二首 二','韓愈','quantangshi','','卷19','雪颭霜翻看不分，雷惊电激语难闻。
沿涯宛转到深处，何限青天无片云。','',''),('quantangshi-18139','题木居士二首 一','韓愈','quantangshi','','卷19','火透波穿不计春，根如头面干如身。
偶然题作木居士，便有无穷求福人。','',''),('quantangshi-18140','题木居士二首 二','韓愈','quantangshi','','卷19','为神讵比沟中断，遇赏还同爨下余。
朽蠹不胜刀锯力，匠人虽巧欲何如。','',''),('quantangshi-18141','晚泊江口','韓愈','quantangshi','','卷19','郡城朝解缆，江岸暮依村。
二女竹上泪，孤臣水底魂。
双双归蜇燕，一一呌羣猿。
回首那闻语，空看别袖翻。','',''),('quantangshi-18142','湘中','韓愈','quantangshi','','卷19','猿愁鱼踊水翻波，自古流传是汨罗。
苹藻满盘无处奠，空闻渔父扣舷歌。','',''),('quantangshi-18143','别盈上人','韓愈','quantangshi','','卷19','山僧爱山出无期，俗士牵俗来何时。
祝融峰下一回首，即是此生长别离。','',''),('quantangshi-18144','喜雪献裴尚书','韓愈','quantangshi','','卷19','宿云寒不卷，春雪堕如簁。
骋巧先投隙，潜光半入池。
喜深将策试，惊密仰檐窥。
自下何曾污，增高未觉危。
比心明可烛，拂面爱还吹。
妬舞时飘袖，欺梅并压枝。
地空迷界限，砌满接高卑。
浩荡干坤合，霏微物象移。
为祥矜大熟，布泽荷平施。
已分年华晚，犹怜曙色随。
气严当酒换，洒急听窗知。
照曜临初日，玲珑滴晚澌。
聚庭看岳耸，扫路见云披。
阵势鱼丽远，书文鸟篆奇。
纵欢罗艳黠，列贺拥熊螭。
履敝行偏冷，门扃卧更羸。
悲嘶闻病马，浪走信娇儿。
竈静愁烟绝，丝繁念鬓衰。
拟盐吟旧句，授简慕前规。
捧赠同燕石，多惭失所宜。','',''),('quantangshi-18145','春雪','韓愈','quantangshi','','卷19','看雪乘清旦，无人坐独谣。
拂花轻尚起，落地暖初销。
已讶陵歌扇，还来伴舞腰。
洒篁留密节，着柳送长条。
入镜鸾窥沼，行天马度桥。
徧堦怜可掬，满树戏成摇。
江浪迎涛日，风毛纵猎朝。
弄闲时细转，争急[忽]惊飘。
城险疑悬布，砧寒未捣绡。
莫愁阴景促，夜色自相饶。','',''),('quantangshi-18146','闻梨花发赠刘师命','韓愈','quantangshi','','卷19','桃溪惆怅不能过，红艳纷纷落地多。
闻道郭西千树雪，欲将君去醉如何。','',''),('quantangshi-18147','春雪间早梅','韓愈','quantangshi','','卷19','梅将雪共春，彩艳不相因。
逐吹能争密，排枝巧妬新。
谁令香满座，独使净无尘。
芳意饶呈瑞，寒光助照人。
𤫩珑开已徧，点缀坐来频。
那是俱疑似，须知两逼真。
荧煌初乱眼，浩荡忽迷神。
未许琼华比，从将玉树亲。
先期迎献岁，更伴占兹晨。
愿得长辉暎，轻微敢自珍。','',''),('quantangshi-18148','早春雪中闻莺','韓愈','quantangshi','','卷19','朝莺雪里新，雪树眼前春。
带涩先迎气，侵寒已报人。
共矜初听早，谁贵后闻频。
暂啭那成曲，孤鸣岂及辰。
风霜徒自保，桃李讵相亲。
寄谢幽栖友，辛勤不为身。','',''),('quantangshi-18149','梨花下赠刘师命','韓愈','quantangshi','','卷19','洛阳城外清明节，百花寥落梨花发。
今日相逢瘴海头，共惊烂漫开正月。','',''),('quantangshi-18150','和归工部送僧约','韓愈','quantangshi','','卷19','早知皆是自拘囚，不学因循到白头。
汝既出家还扰扰，何人更得死前休。','',''),('quantangshi-18151','入关咏马','韓愈','quantangshi','','卷19','岁老岂能充上驷，力微当自慎前程。
不知何故翻骧首，牵过关门妄一鸣。','',''),('quantangshi-18152','木芙蓉','韓愈','quantangshi','','卷19','新开寒露丛，远比水间红。
艳色宁相妬，嘉名偶自同。
采江官渡晚，搴木古祠空。
愿得勤来看，无令便逐风。','',''),('quantangshi-18153','题张十一旅舍三咏 榴花','韓愈','quantangshi','','卷19','五月榴花照眼明，枝间时见子初成。
可怜此地无车马，颠倒青苔落绛英。','',''),('quantangshi-18154','题张十一旅舍三咏 井','韓愈','quantangshi','','卷19','贾谊宅中今始见，葛洪山下昔曾窥。
寒泉百尺空看影，正是行人渴死时。','',''),('quantangshi-18155','题张十一旅舍三咏 蒲萄','韓愈','quantangshi','','卷19','新茎未徧半犹枯，高架支离倒复扶。
若欲满盘堆马乳，莫辞添竹引龙须。','',''),('quantangshi-18156','峡石西泉','韓愈','quantangshi','','卷19','居然鳞介不能容，石眼环环水一钟。
闻说旱时求得雨，秖疑科斗是蛟龙。','',''),('quantangshi-18157','梁国惠康公主挽歌二首 一','韓愈','quantangshi','','卷19','定諡芳声远，移封大国新。
巽宫尊长女，台室属良人。
河汉重泉夜，梧桐半树春。
龙[轜]非厌翟，还辗禁城尘。','',''),('quantangshi-18158','梁国惠康公主挽歌二首 二','韓愈','quantangshi','','卷19','秦地吹箫女，湘波鼓瑟妃。
佩兰初应梦，奔月竟沦辉。
夫族迎魂去，宫官会葬归。
从今沁园草，无复更芳菲。','',''),('quantangshi-18159','和崔舍人咏月二十韵','韓愈','quantangshi','','卷19','三秋端正月，今夜出东溟。
对日犹分势，腾天渐吐灵。
未高烝远气，半上霁孤形。
赫奕当躔次，虚徐度杳冥。
长河晴散雾，列宿曙分萤。
浩荡英华溢，萧疎物象泠。
池边临倒照，檐际送横经。
花树参差见，臯禽断续聆。
牖光窥寂寞，砧影伴娉婷。
幽坐看侵户，闲吟爱满庭。
辉斜通壁练，彩碎射沙星。
清洁云间路，空凉水上亭。
净堪分顾兔，细得数飘萍。
山翠相凝绿，林烟共幂青。
过隅惊桂侧，当午觉轮停。
属思摛霞锦，追欢罄缥瓶。
郡楼何处望，陇笛此时听。
右掖连台座，重门限禁扃。
风台观滉漾，冰砌步青荧。
独有虞庠客，无由拾落蓂。','',''),('quantangshi-18160','咏雪赠张籍','韓愈','quantangshi','','卷19','只见纵横落，宁知远近来。
飘颻还自弄，历乱竟谁催。
座暖销那怪，池清失可猜。
坳中初盖成，垤处遂成堆。
慢有先居后，轻多去却回。
度前铺瓦陇，发本积墙隈。
穿细时双透，乘危忽半摧。
舞深逢坎井，集早值层台。
砧练终宜捣，阶纨未暇裁。
城寒装睥睨，树冻裹莓苔。
片片匀如翦，纷纷碎若挼。
定非燖鹄鹭，真是屑琼瑰。
纬繣观朝萼，冥茫瞩晚埃。
当窗恒凛凛，出户即皑皑。
压野荣芝菌，倾都委货财。
娥嬉华荡漾，胥怒浪崔嵬。
碛迥疑浮地，云平想辗雷。
随车翻缟带，逐马散银杯。
万屋漫汗合，千株照曜开。
松篁遭搓抑，粪壤获饶培。
隔绝门庭遽，挤排陛级才。
岂堪裨岳镇，强欲效盐梅。
隐匿瑕疵尽，包罗委琐该。
误鸡宵呃喔，惊雀暗裴回。
浩浩过三暮，悠悠帀九垓。
鲸鲵陆死骨，玉石火炎灰。
厚虑填溟壑，高愁㨖斗魁。
日轮埋欲侧，坤轴压将颓。
岸类长蛇搅，陵犹巨象豗。
水官夸杰黠，木气怯胚胎。
着地无由卷，连天不易推。
龙鱼冷蛰苦，虎豹饿号哀。
巧借奢华便，专绳困约灾。
威贪陵布被，光肯离金罍。
赏翫捐他事，歌谣放我才。
狂敎诗硉矹，兴与酒陪鳃。
惟子能谙耳，诸人得语哉。
助留风作党，劝坐火为媒。
雕刻文刀利，搜求智网恢。
莫烦相属和，传示及提孩。','',''),('quantangshi-18161','酬王二十舍人雪中见寄','韓愈','quantangshi','','卷19','三日柴门拥不开，阶平庭满白皑皑。
今朝蹋作琼瑶迹，为有诗从凤沼来。','',''),('quantangshi-18162','送侯喜','韓愈','quantangshi','','卷19','已作龙钟后时者，懒于街里蹋尘埃。
如今便别长官去，直到新年衙日来。','',''),('quantangshi-18163','学诸进士作精卫衔石填海','韓愈','quantangshi','','卷19','鸟有偿冤者，终年抱寸诚。
口衔山石细，心望海波平。
渺渺功难见，区区命已轻。
人皆讥造次，我独赏专精。
岂计休无日，惟应尽此生。
何慙刺客传，不着报雠名。','',''),('quantangshi-18164','奉酬振武胡十二丈大夫','韓愈','quantangshi','','卷19','倾朝共羡宠光频，半岁迁腾作虎臣。
戎斾暂停辞社树，里门先下敬乡人。
横飞玉盏家山晓，远蹀金珂塞草春。
自笑平生夸胆气，不离文字鬓毛新。','',''),('quantangshi-18165','奉和库部卢四兄曹长元日朝回','韓愈','quantangshi','','卷19','天仗宵严建羽旄，春云送色晓鸡号。
金炉香动螭头暗，玉佩声来雉尾高。
戎服上趋承北极，儒冠列侍暎东曹。
太平时节难身遇，郎署何须叹二毛。','',''),('quantangshi-18166','寒食直归遇雨','韓愈','quantangshi','','卷19','寒食时看度，春游事已违。
风光连日直，阴雨半朝归。
不见红球上，那论彩索飞。
惟将新赐火，向曙着朝衣。','',''),('quantangshi-18167','送李六协律归荆南','韓愈','quantangshi','','卷19','早日羁游所，春风送客归。
柳花还漠漠，江燕正飞飞。
歌舞知谁在，宾僚逐使非。
宋亭池水绿，莫忘蹋芳菲。','',''),('quantangshi-18168','题百叶桃花','韓愈','quantangshi','','卷19','百叶双桃晚更红，窥窗暎竹见玲珑。
应知侍史归天上，故伴仙郎宿禁中。','',''),('quantangshi-18169','春雪','韓愈','quantangshi','','卷19','新年都未有芳华，二月初惊见草芽。
白雪却嫌春色晚，故穿庭树作飞花。','',''),('quantangshi-18170','戏题牡丹','韓愈','quantangshi','','卷19','幸自同开俱隐约，何须相倚鬬轻盈。
陵晨并作新妆面，对客偏含不语情。
双燕无机还拂掠，游蜂多思正经营。
长年是事皆抛尽，今日栏边暂眼明。','',''),('quantangshi-18171','盆池五首 一','韓愈','quantangshi','','卷19','老翁真个似童儿，汲水埋盆作小池。
一夜青蛙鸣到晓，恰如方口钓鱼时。','',''),('quantangshi-18172','盆池五首 二','韓愈','quantangshi','','卷19','莫道盆池作不成，藕稍初种已齐生。
从今有雨君须记，来听萧萧打叶声。','',''),('quantangshi-18173','盆池五首 三','韓愈','quantangshi','','卷19','瓦沼晨朝水自清，小虫无数不知名。
忽然分散无踪影，惟有鱼儿作队行。','',''),('quantangshi-18174','盆池五首 四','韓愈','quantangshi','','卷19','泥盆浅小讵成池，夜半青蛙圣得知。
一听暗来将伴侣，不烦鸣唤鬬[雄雌]。','',''),('quantangshi-18175','盆池五首 五','韓愈','quantangshi','','卷19','池光天影共青青，拍岸才添水数瓶。
且待夜深明月去，试看涵泳几多星。','',''),('quantangshi-18176','芍药','韓愈','quantangshi','','卷19','浩态狂香昔未逢，红灯烁烁绿盘笼。
觉来独对情惊恐，身在仙宫第几重。','',''),('quantangshi-18177','奉和虢州刘给事使君三堂新题二十一咏 新亭','韓愈','quantangshi','','卷19','湖上新亭好，公来日出初。
水文浮枕簟，瓦影荫龟鱼。','',''),('quantangshi-18178','奉和虢州刘给事使君三堂新题二十一咏 流水','韓愈','quantangshi','','卷19','汩汩几时休，从春复到秋。
只言池未满，池满强交流。','',''),('quantangshi-18179','奉和虢州刘给事使君三堂新题二十一咏 竹洞','韓愈','quantangshi','','卷19','竹洞何年有，公初斫竹开。
洞门无锁钥，俗客不曾来。','',''),('quantangshi-18180','奉和虢州刘给事使君三堂新题二十一咏 月台','韓愈','quantangshi','','卷19','南馆城阴阔，东湖水气多。
直须台上看，始奈月明何。','',''),('quantangshi-18181','奉和虢州刘给事使君三堂新题二十一咏 渚亭','韓愈','quantangshi','','卷19','自有人知处，那无步往踪。
莫敎安四壁，面面看芙蓉。','',''),('quantangshi-18182','奉和虢州刘给事使君三堂新题二十一咏 竹溪','韓愈','quantangshi','','卷19','蔼蔼溪流慢，梢梢岸筱长。
穿沙碧簳净，落水紫苞香。','',''),('quantangshi-18183','奉和虢州刘给事使君三堂新题二十一咏 北湖','韓愈','quantangshi','','卷19','闻说游湖棹，寻常到此回。
应留醒心处，准拟醉时来。','',''),('quantangshi-18184','奉和虢州刘给事使君三堂新题二十一咏 花岛','韓愈','quantangshi','','卷19','蜂蝶去纷纷，香风隔岸闻。
欲知花岛处，水上觅红云。','',''),('quantangshi-18185','奉和虢州刘给事使君三堂新题二十一咏 柳溪','韓愈','quantangshi','','卷19','柳树谁人种，行行夹岸高。
莫将条系缆，着处有蝉号。','',''),('quantangshi-18186','奉和虢州刘给事使君三堂新题二十一咏 西山','韓愈','quantangshi','','卷19','新月迎宵挂，晴云到晚留。
为遮西望眼，终是懒回头。','',''),('quantangshi-18187','奉和虢州刘给事使君三堂新题二十一咏 竹迳','韓愈','quantangshi','','卷19','无尘从不扫，有鸟莫令弹。
若要添风月，应除数百竿。','',''),('quantangshi-18188','奉和虢州刘给事使君三堂新题二十一咏 荷池','韓愈','quantangshi','','卷19','风雨秋池上，高荷盖水繁。
未谙鸣摵摵，那似卷翻翻。','',''),('quantangshi-18189','奉和虢州刘给事使君三堂新题二十一咏 稻畦','韓愈','quantangshi','','卷19','罫布畦堪数，枝分水莫寻。
鱼肥知已秀，鹤没觉初深。','',''),('quantangshi-18190','奉和虢州刘给事使君三堂新题二十一咏 柳巷','韓愈','quantangshi','','卷19','柳巷还飞絮，春余几许时。
吏人休报事，公作送春诗。','',''),('quantangshi-18191','奉和虢州刘给事使君三堂新题二十一咏 花源','韓愈','quantangshi','','卷19','源上花初发，公应日日来。
丁宁红与紫，慎莫一时开。','',''),('quantangshi-18192','奉和虢州刘给事使君三堂新题二十一咏 北楼','韓愈','quantangshi','','卷19','郡楼乘晓上，尽日不能回。
晚色将秋至，长风送月来。','',''),('quantangshi-18193','奉和虢州刘给事使君三堂新题二十一咏 镜潭','韓愈','quantangshi','','卷19','非铸复非镕，泓澄忽此逢。
鱼鰕不用避，只是照蛟龙。','',''),('quantangshi-18194','奉和虢州刘给事使君三堂新题二十一咏 孤屿','韓愈','quantangshi','','卷19','朝游孤屿南，暮戏孤屿北。
所以孤屿鸟，与公尽相识。','',''),('quantangshi-18195','奉和虢州刘给事使君三堂新题二十一咏 方桥','韓愈','quantangshi','','卷19','非阁复非船，可居兼可过。
君欲问方桥，方桥如此作。','',''),('quantangshi-18196','奉和虢州刘给事使君三堂新题二十一咏 梯桥','韓愈','quantangshi','','卷19','乍似上青冥，初疑蹑菡萏。
自无飞仙骨，欲度何由敢。','',''),('quantangshi-18197','奉和虢州刘给事使君三堂新题二十一咏 月池','韓愈','quantangshi','','卷19','寒池月下明，新月池边曲。
若不妒清妍，却成相映烛。','',''),('quantangshi-18198','游城南十六首 赛神','韓愈','quantangshi','','卷19','白布长衫紫领巾，差科未动是闲人。
麦苗含穟桑生葚，共向田头乐社神。','',''),('quantangshi-18199','游城南十六首 题于宾客庄','韓愈','quantangshi','','卷19','榆荚车前盖地皮，蔷薇蘸水笋穿篱。
马蹄无入朱门迹，纵使春归可得知。','',''),('quantangshi-18200','游城南十六首 晚春','韓愈','quantangshi','','卷19','草树知春不久归，百般红紫鬬芳菲。
杨花榆荚无才思，惟解漫天作雪飞。','',''),('quantangshi-18201','游城南十六首 落花','韓愈','quantangshi','','卷19','已分将身着地飞，那羞践踏损光晖。
无端又被春风误，吹落西家不得归。','',''),('quantangshi-18202','游城南十六首 楸树二首 一','韓愈','quantangshi','','卷19','几岁生成为大树，一朝缠绕困长藤。
谁人与脱青罗帔，看吐高花万万层。','',''),('quantangshi-18203','游城南十六首 楸树二首 二','韓愈','quantangshi','','卷19','幸自枝条能树立，可烦萝蔓作交加。
傍人不解寻根本，却道新花胜旧花。','',''),('quantangshi-18204','游城南十六首 风折花枝','韓愈','quantangshi','','卷19','浮艳侵天难就看，清香扑地只遥闻。
春风也是多情思，故拣繁枝折赠君。','',''),('quantangshi-18205','游城南十六首 赠同游','韓愈','quantangshi','','卷19','唤起窗全曙，催归日未西。
无心花里鸟，更与尽情啼。','',''),('quantangshi-18206','游城南十六首 赠张十八助敎','韓愈','quantangshi','','卷19','喜君眸子重清朗，携手城南历旧游。
忽见孟生题竹处，相看泪落不能收。','',''),('quantangshi-18207','游城南十六首 题韦氏庄','韓愈','quantangshi','','卷19','昔者谁能比，今来事不同。
寂寥青草曲，散漫白榆风。
架倒藤全落，篱崩竹半空。
宁须惆怅立，翻覆本无穷。','',''),('quantangshi-18208','游城南十六首 晚雨','韓愈','quantangshi','','卷19','廉纤晚雨不能晴，池岸草间蚯蚓鸣。
投竿跨马蹋归路，才到城门打鼓声。','',''),('quantangshi-18209','游城南十六首 出城','韓愈','quantangshi','','卷19','暂出城门蹋青草，远于林下见春山。
应须韦杜家家到，祗有今朝一日闲。','',''),('quantangshi-18210','游城南十六首 把酒','韓愈','quantangshi','','卷19','扰扰驰名者，谁能一日闲。
我来无伴侣，把酒对南山。','',''),('quantangshi-18211','游城南十六首 嘲少年','韓愈','quantangshi','','卷19','直把春偿酒，都将命乞花。
祗知闲信马，不觉误随车。','',''),('quantangshi-18212','游城南十六首 楸树','韓愈','quantangshi','','卷19','青幢紫盖立童童，细雨浮烟作彩笼。
不得画师来貌取，定知难见一生中。','',''),('quantangshi-18213','游城南十六首 遣兴','韓愈','quantangshi','','卷19','断送一生惟有酒，寻思百计不如闲。
莫忧世事兼身事，须着人间比梦间。','',''),('quantangshi-18214','送李尚书赴襄阳八韵得长字','韓愈','quantangshi','','卷19','帝忧南国切，改命付忠良。
壤画星摇动，旗分兽簸扬。
五营兵转肃，千里地还方。
控带荆门远，飘浮汉水长。
赐书宽属郡，战马隔邻疆。
纵猎雷霆迅，观棊玉石忙。
风流岘首客，花艳大堤倡。
富贵由身致，谁敎不自强。','',''),('quantangshi-18215','和席八十二韵','韓愈','quantangshi','','卷19','绛阙银河曙，东风右掖春。
官随名共美，花与思俱新。
绮陌朝游间，绫衾夜直频。
横门开日月，高阁切星辰。
庭变寒前草，天销霁后尘。
沟声通苑急，柳色压城匀。
纶綍谋猷盛，丹青步武亲。
芳菲含斧藻，光景畅形神。
傍砌看红药，巡池咏白苹。
多情怀酒伴，余事作诗人。
倚玉难藏拙，吹竽久混真。
坐慙空自老，江海未还身。','',''),('quantangshi-18216','和武相公早春闻莺','韓愈','quantangshi','','卷19','早晚飞来入锦城，谁人敎解百般鸣。
春风红树惊眠处，似妬歌童作艳声。','',''),('quantangshi-18217','游太平公主山庄','韓愈','quantangshi','','卷19','公主当年欲占春，故将台榭押城闉。
欲知前面花多少，直到南山不属人。','',''),('quantangshi-18218','晚春','韓愈','quantangshi','','卷19','谁收春色将归去，慢绿妖红半不存。
榆荚祗能随柳絮，等闲撩乱走空园。','',''),('quantangshi-18219','大行皇太后挽歌词三首 一','韓愈','quantangshi','','卷19','一纪尊名正，三时孝养荣。
高居朝圣主，厚德载羣生。
武帐虚中禁，玄堂掩太平。
秋天笳鼓歇，松柏徧山鸣。','',''),('quantangshi-18220','大行皇太后挽歌词三首 二','韓愈','quantangshi','','卷19','威仪备吉凶，文物杂军容。
配地行新祭，因山托故封。
凤飞终不返，劒化会相从。
无复临长乐，空闻报晓钟。','',''),('quantangshi-18221','大行皇太后挽歌词三首 三','韓愈','quantangshi','','卷19','追攀万国来，警卫百神陪。
画翣登秋殿，容衣入夜台。
云随仙驭远，风助圣情哀。
只有朝陵日，妆匳一暂开。','',''),('quantangshi-18222','广宣上人频见过','韓愈','quantangshi','','卷19','三百六旬长扰扰，不冲风雨即尘埃。
久慙朝士无裨补，空愧高僧数往来。
学道穷年何所得，吟诗竟日未能廻。
天寒古寺游人少，红叶窗前有几堆。','',''),('quantangshi-18223','闲游二首 一','韓愈','quantangshi','','卷19','雨后来更好，绕池徧青青。
柳花闲度竹，菱叶故穿萍。
独坐殊未厌，孤斟讵能醒。
持竿至日暮，幽咏欲谁听。','',''),('quantangshi-18224','闲游二首 二','韓愈','quantangshi','','卷19','兹游苦不数，再到遂经旬。
萍盖污池净，藤笼老树新。
林乌鸣讶客，岸竹长遮邻。
子云祗自守，奚事九衢尘。','',''),('quantangshi-18225','酬马侍郎寄酒','韓愈','quantangshi','','卷19','一壶情所寄，四句意能多。
秋到无诗酒，其如月色何。','',''),('quantangshi-18226','和侯协律咏笋','韓愈','quantangshi','','卷19','竹亭人不到，新笋满前轩。
乍出真堪赏，初多未觉烦。
成行齐婢仆，环立比儿孙。
验长常携尺，愁干屡侧盆。
对吟忘膳饮，偶坐变朝昏。
滞雨膏腴湿，骄阳气候温。
得时方张王，挟势欲腾骞。
见角牛羊没，看皮虎豹存。
攒生犹有隙，散布忽无垠。
讵可持筹算，谁能以理言。
纵横公占地，罗列暗连根。
狂剧时穿壁，横强几触藩。
深潜如避逐，远去若追奔。
始讶妨人路，还惊入药园。
萌芽防寖大，覆载莫偏恩。
已复侵危砌，非徒出短垣。
身宁虞瓦砾，计拟揜兰荪。
且叹高无数，庸知上几番。
短长终不校，先后竟谁论。
外恨苞藏密，中仍节目繁。
暂须廻步履，要取助盘飧。
穰穰疑翻地，森森竞塞门。
戈矛头戢戢，蛇虺首掀掀。
妇懦咨料拣，儿痴谒尽髠。
侯生来慰我，诗句读惊魂。
属和才将竭，呻吟至日暾。','',''),('quantangshi-18227','过鸿沟','韓愈','quantangshi','','卷19','龙疲虎困割川原，亿万苍生性命存。
谁劝君王回马首，真成一掷赌干坤。','',''),('quantangshi-18228','送张侍郎','韓愈','quantangshi','','卷19','司徒东镇驰书谒，丞相西来走马迎。
两府元臣今转密，一方逋寇不难平。','',''),('quantangshi-18229','赠刑部马侍郎','韓愈','quantangshi','','卷19','红旗照海压南荒，征入中台作侍郎。
暂从相公平小寇，便归天阙致时康。','',''),('quantangshi-18230','奉和裴相公东征途经女几山下作','韓愈','quantangshi','','卷19','旗穿晓日云霞杂，山倚秋空剑戟明。
敢请相公平贼后，暂携诸吏上峥嵘。','',''),('quantangshi-18231','郾城晚饮奉赠副使马侍郎及冯李二员外','韓愈','quantangshi','','卷19','城上赤云呈胜气，眉间黄色见归期。
幕中无事惟须饮，即是连镳向阙时。','',''),('quantangshi-18232','酬别留后侍郎','韓愈','quantangshi','','卷19','为文无出相如右，谋师难居却縠先。
归去雪销溱洧动，西来旌斾拂晴天。','',''),('quantangshi-18233','同李二十八夜次襄城','韓愈','quantangshi','','卷19','周楚仍连接，川原乍屈盘。
云垂天不暖，尘涨雪犹干。
印绶归台室，旌旗别将坛。
欲知迎候盛，骑火万星攒。','',''),('quantangshi-18234','同李二十八员外从裴相公野宿西界','韓愈','quantangshi','','卷19','四面星辰着地明，散烧烟火宿天兵。
不关破贼须归奏，自趂新年贺太平。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-18235','过襄城','韓愈','quantangshi','','卷19','郾城辞罢过襄城，颍水嵩山刮眼明。
已去蔡州三百里，家人不用远来迎。','',''),('quantangshi-18236','宿神龟招李二十八冯十七','韓愈','quantangshi','','卷19','荒山野水照斜晖，啄雪寒鸦趂始飞。
夜宿驿亭愁不睡，幸来相就盖征衣。','',''),('quantangshi-18237','次硖石','韓愈','quantangshi','','卷19','数日方离雪，今朝又出山。
试凭高处望，隐约见潼关。','',''),('quantangshi-18238','和李司勋过连昌宫','韓愈','quantangshi','','卷19','夹道疎槐出老根，高甍巨桷压山原。
宫前遗老来相问，今是开元几叶孙。','',''),('quantangshi-18239','次潼关先寄张十二阁老使君','韓愈','quantangshi','','卷19','荆山已去华山来，日出潼关四扇开。
刺史莫辞迎候远，相公亲破蔡州廻。','',''),('quantangshi-18240','次潼关上都统相公','韓愈','quantangshi','','卷19','暂辞堂印执兵权，尽管诸军破贼年。
冠盖相望催入相，待将功德格皇天。','',''),('quantangshi-18241','桃林夜贺晋公','韓愈','quantangshi','','卷19','西来骑火照山红，夜宿桃林腊月中。
手把命圭兼相印，一时重叠赏元功。','',''),('quantangshi-18242','送李员外院长分司东都','韓愈','quantangshi','','卷19','去年秋露下，羇旅逐东征。
今岁春光动，驱驰别上京。
饮中相顾色，送后独归情。
两地无千里，因风数寄声。','',''),('quantangshi-18243','晋公破贼回重拜台司以诗示幕中宾客愈奉和','韓愈','quantangshi','','卷19','南伐旋师太华东，天书夜到册元功。
将军旧压三司贵，相国新兼五等崇。
鵷鹭欲归仙仗里，熊罴还入禁营中。
长慙典午非材职，得就闲官即至公。','',''),('quantangshi-18244','独钓四首 一','韓愈','quantangshi','','卷19','侯家林馆胜，偶入得垂竿。
曲树行藤角，平池散芡盘。
羽沈知食驶，缗细觉牵难。
聊取夸儿女，榆条系从鞍。','',''),('quantangshi-18245','独钓四首 二','韓愈','quantangshi','','卷19','一迳向池斜，池搪野草花。
雨多添柳耳，水长减蒲芽。
坐厌亲刑柄，偷来傍钓车。
太平公事少，吏隐讵相赊。','',''),('quantangshi-18246','独钓四首 三','韓愈','quantangshi','','卷19','独往南塘上，秋晨景气醒。
露排四岸草，风约半池萍。
鸟下见人寂，鱼来闻饵馨。
所嗟无可召，不得倒吾瓶。','',''),('quantangshi-18247','独钓四首 四','韓愈','quantangshi','','卷19','秋半百物变，溪鱼去不来。
风能坼芡觜，露亦染梨腮。
远岫重叠出，寒花散乱开。
所期终莫至，日暮与谁廻。','',''),('quantangshi-18248','枯树','韓愈','quantangshi','','卷19','老树无枝叶，风霜不复侵。
腹穿人可过，皮剥蚁还寻。
寄托惟朝菌，依投绝暮禽。
犹堪持改火，未肯但空心。','',''),('quantangshi-18249','元日酬蔡州马十二尚书去年蔡州元日见寄之什','韓愈','quantangshi','','卷19','元日新诗已去年，蔡州遥寄荷相怜。
今朝纵有谁人领，自是三峰不敢眠。','',''),('quantangshi-18250','咏灯花同侯十一','韓愈','quantangshi','','卷19','今夕知何夕，花然锦帐中。
自能当雪暖，那肯待春红。
黄里排金粟，钗头缀玉虫。
更烦将喜事，来报主人公。','',''),('quantangshi-18251','祖席前字','韓愈','quantangshi','','卷19','祖席洛桥边，亲交共黯然。
野晴山簇簇，霜晓菊鲜鲜。
书寄相思处，杯衔欲别前。
淮阳知不薄，终愿早廻船。','',''),('quantangshi-18252','秋字','韓愈','quantangshi','','卷19','淮南悲木落，而我亦伤秋。
况与故人别，那堪羇宦愁。
荣华今异路，风雨昔同忧。
莫以宜春远，江山多胜游。','',''),('quantangshi-18253','送郑尚书赴南海','韓愈','quantangshi','','卷19','番禺军府盛，欲说暂停杯。
盖海旗幢出，连天观阁开。
衙时龙户集，上日马人来。
风静鶢鶋去，官廉蚌蛤廻。
货通师子国，乐奏武王台。
事事皆殊异，无嫌屈大才。','',''),('quantangshi-18254','答道士寄树鸡','韓愈','quantangshi','','卷19','软湿青黄状可猜，欲烹还唤木盘廻。
烦君自入华阳洞，直割乖龙左耳来。','',''),('quantangshi-18255','左迁至蓝关示侄孙湘','韓愈','quantangshi','','卷19','一封朝奏九重天，夕贬潮州路八千。
欲为圣朝除弊事，肯将衰朽惜残年。
云横秦岭家何在，雪拥蓝关马不前。
知汝远来应有意，好收吾骨瘴江边。','',''),('quantangshi-18256','武关西逢配流吐蕃','韓愈','quantangshi','','卷19','嗟尔戎人莫惨然，湖南地近保生全。
我今罪重无归望，直去长安路八千。','',''),('quantangshi-18257','次邓州界','韓愈','quantangshi','','卷19','潮阳南去倍长沙，恋阙那堪又忆家。
心讶愁来惟贮火，眼知别后自添花。
商颜暮雪逢人少，邓鄙春泥见驿赊。
早晚王师收海岳，普将雷雨发萌芽。','',''),('quantangshi-18258','题临泷寺','韓愈','quantangshi','','卷19','不觉离家已五千，仍将衰病入泷船。
潮阳未到吾能说，海气昏昏水拍天。','',''),('quantangshi-18259','晚次宣溪辱韵州张端公使君惠书叙别酬以绝句二章 一','韓愈','quantangshi','','卷19','韶州南去接宣溪，云水苍茫日向西。
客泪数行先自落，鹧鸪休傍耳边啼。','',''),('quantangshi-18260','晚次宣溪辱韵州张端公使君惠书叙别酬以绝句二章 二','韓愈','quantangshi','','卷19','兼金那足比清文，百首相随愧使君。
俱是岭南巡管内，莫欺荒僻断知闻。','',''),('quantangshi-18261','题秀禅师房','韓愈','quantangshi','','卷19','桥夹水松行百步，竹牀莞席到僧家。
暂拳一手支头卧，还把鱼竿下钓沙。','',''),('quantangshi-18262','将至韶州先寄张端公使君借图经','韓愈','quantangshi','','卷19','曲江山水闻来久，恐不知名访倍难。
愿借图经将入界，每逢佳处便开看。','',''),('quantangshi-18263','过始兴江口感怀','韓愈','quantangshi','','卷19','忆作儿童随伯氏，南来今只一身存。
目前百口还相逐，旧事无人可共论。','',''),('quantangshi-18264','韶州留别张端公使君','韓愈','quantangshi','','卷19','来往再逢梅柳新，别离一醉绮罗春。
久钦江总文才妙，自叹虞翻骨相屯。
鸣笛急吹争落日，清歌缓送款行人。
已知奏课当征拜，那复淹留咏白苹。','',''),('quantangshi-18265','从潮州量移袁州张韶州端公以诗相贺因酬之','韓愈','quantangshi','','卷19','明时远逐事何如，遇赦移官罪未除。
北望讵令随塞雁，南迁才免葬江鱼。
将经贵郡烦留客，先惠高文谢起予。
暂欲系船韶石下，上宾虞舜整冠裾。','',''),('quantangshi-18266','次石头驿寄江西王十中丞阁老','韓愈','quantangshi','','卷19','凭高试廻首，一望豫章城。
人由恋德泣，马亦别羣鸣。
寒日夕始照，风江远渐平。
默然都不语，应识此时情。','',''),('quantangshi-18267','游西林寺题萧二兄郎中旧堂','韓愈','quantangshi','','卷19','中郎有女能传业，伯道无儿可保家。
偶到匡山曾住处，几行衰泪落烟霞。','',''),('quantangshi-18268','自袁州还京行次安陆先寄随州周员外','韓愈','quantangshi','','卷19','行行指汉东，暂喜笑言同。
雨雪离江上，蒹葭出梦中。
面犹含瘴色，眼已见华风。
岁暮难相值，酣歌未可终。','',''),('quantangshi-18269','题广昌馆','韓愈','quantangshi','','卷19','白水龙飞已几春，偶逢遗迹问耕人。
丘坟发掘当官路，何处南阳有近亲。','',''),('quantangshi-18270','寄随州周员外','韓愈','quantangshi','','卷19','陆孟丘杨久作尘，同时存者更谁人。
金丹别后知传得，乞取刀圭救病身。','',''),('quantangshi-18271','酒中留上襄阳李相公','韓愈','quantangshi','','卷19','浊水污泥清路尘，还曾同制掌丝纶。
眼穿长讶双鱼断，耳热何辞数爵频。
银烛未销窗送曙，金钗半醉座添春。
知公不久归钧轴，应许闲官寄病身。','',''),('quantangshi-18272','去岁自刑部侍郎以罪贬潮州刺史乘驿赴任其后家亦谴逐小女道死殡之层峰驿旁山下蒙恩还朝过其墓留题驿梁','韓愈','quantangshi','','卷19','数条藤束木皮棺，草殡荒山白骨寒。
惊恐入心身已病，扶舁沿路众知难。
绕坟不暇号三帀，设祭惟闻饭一盘。
致汝无辜由我罪，百年慙痛泪阑干。','',''),('quantangshi-18273','贺张十八秘书得裴司空马','韓愈','quantangshi','','卷19','司空远寄养初成，毛色桃花眼镜明。
落日已曾交辔语，春风还拟竝鞍行。
长令奴仆知饥渴，须着贤良待性情。
旦夕公归伸拜谢，免劳骑去逐双旌。','',''),('quantangshi-18274','杏园送张彻侍御归使','韓愈','quantangshi','','卷19','东风花树下，送尔出京城。
久抱伤春意，新添惜别情。
归来身已病，相见眼还明。
更遣将诗酒，谁家逐后生。','',''),('quantangshi-18275','雨中寄张博士籍侯主簿喜','韓愈','quantangshi','','卷19','放朝还不报，半路蹋泥归。
雨惯曾无节，雷频自失威。
见墙生菌徧，忧麦作蛾飞。
岁晚偏萧索，谁当救晋饥。','',''),('quantangshi-18276','奉和兵部张侍郎酬郓州马尚书祗召途中见寄开缄之日马帅已再领郓州之作','韓愈','quantangshi','','卷19','来朝当路日，承诏改辕时。
再领须句国，仍迁少昊司。
暖风抽宿麦，清雨卷归旗。
赖寄新珠玉，长吟慰我思。','',''),('quantangshi-18277','早春与张十八博士籍游杨尚书林亭寄第三阁老兼呈白冯二阁老','韓愈','quantangshi','','卷19','墙下春渠入禁沟，渠冰初破满渠浮。
凤池近日长先暖，流到池时更不流。','',''),('quantangshi-18278','奉使常山早次太原呈副使吴郎中','韓愈','quantangshi','','卷19','朗朗闻街鼓，晨起似朝时。
翻翻走驿马，春尽是归期。
地失嘉禾处，风存蟋蟀辞。
暮齿良多感，无事涕垂颐。','',''),('quantangshi-18279','夕次寿阳驿题吴郎中诗后','韓愈','quantangshi','','卷19','风光欲动别长安，春半城边特地寒。
不见园花兼巷柳，马头惟有月团团。','',''),('quantangshi-18280','镇州初归','韓愈','quantangshi','','卷19','别来杨柳街头树，摆弄春风只欲飞。
还有小园桃李在，留花不发待郎归。','',''),('quantangshi-18281','同水部张员外籍曲江春游寄白二十二舍人','韓愈','quantangshi','','卷19','漠漠轻阴晚自开，青天白日映楼台。
曲江水满花千树，有底忙时不肯来。','',''),('quantangshi-18282','和水部张员外宣政衙赐百官樱桃诗','韓愈','quantangshi','','卷19','汉家旧种明光殿，炎帝还书本草经。
岂似满朝承雨露，共看传赐出青冥。
香随翠笼擎初到，色暎银盘写未停。
食罢自知无所报，空然慙汗仰皇扃。','',''),('quantangshi-18283','早春呈水部张十八员外二首 一','韓愈','quantangshi','','卷19','天街小雨润如酥，草色遥看近却无。
最是一年春好处，绝胜烟柳满皇都。','',''),('quantangshi-18284','早春呈水部张十八员外二首 二','韓愈','quantangshi','','卷19','莫道官忙身老大，即无年少逐春心。
凭君先到江头看，柳色如今深未深。','',''),('quantangshi-18285','送桂州严大夫同用南字','韓愈','quantangshi','','卷19','苍苍森八桂，兹地在湘南。
江作青罗带，山如碧玉篸。
户多输翠羽，家自种黄甘。
远胜登仙去，飞鸾不假骖。','',''),('quantangshi-18286','奉酬天平马十二仆射暇日言怀见寄之作','韓愈','quantangshi','','卷19','天平篇什外，政事亦无双。
威令加徐土，儒风被鲁邦。
清为公论重，宽得士心降。
岁晏偏相忆，长谣坐北窗。','',''),('quantangshi-18287','奉使镇州行次承天行营奉酬裴司空','韓愈','quantangshi','','卷19','窜逐三年海上归，逢公复此着征衣。
旋吟佳句还鞭马，恨不身先去鸟飞。','',''),('quantangshi-18288','镇州路上谨酬裴司空相公重见寄','韓愈','quantangshi','','卷19','衔命山东抚乱师，日驰三百自嫌迟。
风霜满面无人识，何处如今更有诗。','',''),('quantangshi-18289','奉和仆射裴相公感跨恩言志','韓愈','quantangshi','','卷19','文武功成后，居为百辟师。
林园穷胜事，钟鼓乐清时。
摆落遗高论，雕镌出小诗。
自然无不可，范蠡尔其谁。','',''),('quantangshi-18290','和仆射相公朝廻见寄','韓愈','quantangshi','','卷19','尽瘁年将久，公今始暂闲。
事随忧共减，诗与酒俱还。
放意机衡外，收身矢石间。
秋台风日迥，正好看前山。','',''),('quantangshi-18291','奉和李相公题萧家林亭','韓愈','quantangshi','','卷19','山公自是林园主，叹惜前贤造作时。
岩洞幽深门尽锁，不因丞相几人知。','',''),('quantangshi-18292','奉和杜相公太清宫纪事陈诚上李相公十六韵','韓愈','quantangshi','','卷19','耒耜兴姬国，輴欙建夏家。
在功诚可尚，于道讵为华。
象帝威容大，仙宗宝历赊。
卫门罗戟槊，图壁杂龙蛇。
礼乐追尊盛，干坤降福遐。
四真皆齿列，二圣亦肩差。
阳月时之首，阴泉气未牙。
殿阶铺水碧，庭炬坼金葩。
紫极观忘倦，青词奏不哗。
噌吰宫夜辟，嘈囐鼓晨挝。
亵味陈奚取，名香荐孔嘉。
垂祥纷可录，俾寿浩无涯。
贵相山瞻峻，清文玉绝瑕。
代工声问远，摄事敬恭加。
皎洁当天月，葳蕤捧日霞。
唱妍酬亦丽，俛仰但称嗟。','',''),('quantangshi-18293','郓州溪堂诗','韓愈','quantangshi','','卷19','帝奠九廛，有叶有年。
有荒不条，河岱之间。
及我宪考，一收正之。
视邦选侯，以公来尸。
公来尸之，人始未信。
公不饮食，以训以徇。
孰饥无食，孰呻孰叹。
孰冤不问，不得分愿。
孰为邦蟊，节根之螟。
羊很狼贪，以口覆城。
吹之喣之，摩手拊之。
箴之石之，膊而磔之。
凡公四封，既富以彊。
谓公吾父，孰违公令。
可以师征，不宁守邦。
公作溪堂，播播流水。
浅有蒲莲，深有葭苇。
公以宾燕，其鼓骇骇。
公燕溪堂，宾校醉饱。
流有跳鱼，岸有集鸟。
既歌以舞，其鼓考考。
公在溪堂，公御琴瑟。
公暨宾赞，稽经诹律。
施用不差，人用不屈。
溪有薲苽，有龟有鱼。
公在中流，右诗左书。
无我斁遗，此邦是庥。','',''),('quantangshi-18294','送张道士','韓愈','quantangshi','','卷19','大匠无弃材，寻尺各有施。
况当营都邑，杞梓用不疑。
张侯嵩高来，面有熊豹姿。
开口论利害，劒锋白差差。
恨无一尺捶，为国笞羌夷。
诣阙三上书，臣非黄冠师。
臣有胆与气，不忍死茅茨。
又不媚笑语，不能伴儿嬉。
乃着道士服，众人莫臣知。
臣有平贼策，狂童不难治。
其言简且要，陛下幸听之。
天空日月高，下照理不遗。
或是章奏繁，裁择未及斯。
宁当不竢报，归袖风披披。
答我事不尔，吾亲属吾思。
昨宵梦倚门，手取连环持。
今日有书至，又言归何时。
霜天熟柿栗，收拾不可迟。
岭北梁可构，寒鱼下清伊。
既非公家用，且复还其私。
从容进退间，无一不合宜。
时有利不利，虽贤欲奚为。
但当励前操，富贵非公谁。','',''),('quantangshi-18295','送郑十校理得洛字','韓愈','quantangshi','','卷19','相公倦台鼎，分正新邑洛。
才子富文华，校讐天禄阁。
寿觞佳节过，归骑春衫薄。
鸟哢正交加，杨花共纷泊。
亲交谁不羡，去去翔寥廓。','',''),('quantangshi-18296','送陆歙州傪','韓愈','quantangshi','','卷19','我衣之华兮，我佩之光。
陆君之去兮，谁与翺翔。
敛此大惠兮，施于一州。
今其去矣，胡不为留。
我作此诗，歌于远道。
无疾其驱，天子有诏。','',''),('quantangshi-18297','送汴州监军俱文珍','韓愈','quantangshi','','卷19','奉使羌池静，临戎汴水安。
冲天鹏翅阔，报国劒铓寒。
晓日驱征骑，春风咏采兰。
谁言臣子道，忠孝两全难。','',''),('quantangshi-18298','赠崔立之','韓愈','quantangshi','','卷19','昔年十日雨，子桑苦寒饥。
哀歌坐空室，不怨但自悲。
其友名子舆，忽然忧且思。
搴裳触泥水，裹饭往食之。
入门相对语，天命良不疑。
好事漆园吏，书之存雄词。
千年事已远，二子情可推。
我读此篇日，正当寒雪时。
吾身固已困，吾友复何为。
薄粥不足裹，深泥谅难驰。
曾无子舆事，空赋子桑诗。','',''),('quantangshi-18299','海水','韓愈','quantangshi','','卷19','海水非不广，邓林岂无枝。
风波一荡薄，鱼鸟不可依。
海水饶大波，邓林多惊风。
岂无鱼与鸟，巨细各不同。
海有吞舟鲸，邓有垂天鹏。
苟非鳞羽大，荡薄不可能。
我鳞不盈寸，我羽不盈尺。
一木有余阴，一泉有余泽。
我将辞海水，濯鳞清冷池。
我将辞邓林，刷羽蒙笼枝。
海水非爱广，邓林非爱枝。
风波亦常事，鳞鱼自不宜。
我鳞日已大，我羽日已修。
风波无所苦，还作鲸鹏游。','',''),('quantangshi-18300','赠河阳李大夫','韓愈','quantangshi','','卷19','四海失巢穴，两都困尘埃。
感恩由未报，惆怅空一来。
裘破气不暖，马羸鸣且哀。
主人情更重，空使劒锋摧。','',''),('quantangshi-18301','苦寒歌','韓愈','quantangshi','','卷19','黄昏苦寒歌，夜半不能休。
岂不有阳春，节岁聿其周。
君何爱重裘，兼味养大贤。
冰食葛制神所怜，填窗塞户慎勿出，暄风暖景明年日。','',''),('quantangshi-18302','芍药歌','韓愈','quantangshi','','卷19','丈人庭中开好花，更无凡木争春华。
翠茎红蘂天力与，此恩不属黄钟家。
温馨熟美鲜香起，似笑无言习君子。
霜刀翦汝天女劳，何事低头学桃李。
娇痴婢子无灵性，竞挽春衫来比并。
欲将双颊一曦红，绿窗磨徧青铜镜。
一尊春酒甘若饴，丈人此乐无人知。
花前醉倒歌者谁，楚狂小子韩退之。','',''),('quantangshi-18303','赠徐州族侄','韓愈','quantangshi','','卷19','我年十八九，壮气起胸中。
作书献云阙，辞家逐秋蓬。
岁时易迁次，身命多厄穷。
一名虽云就，片禄不足充。
今者复何事，卑栖寄徐戎。
萧条资用尽，濩落门巷空。
朝眠未能起，远怀方郁悰。
击门者谁子，问言乃吾宗。
自云有奇术，探妙知天工。
既往怅何及，将来喜还通。
期我语非佞，当为佐时雍。','',''),('quantangshi-18304','嘲鼾睡','韓愈','quantangshi','','卷19','澹师昼睡时，声气一何猥。
顽飙吹肥脂，坑谷相嵬磊。
雄哮乍咽绝，每发壮益倍。
有如阿鼻尸，长唤忍众罪。
马牛惊不食，百鬼聚相待。
木枕十字裂，镜面生痱癗。
铁佛闻皱眉，石人战摇腿。
孰云天地仁，吾欲责真宰。
幽寻虱搜耳，猛作涛翻海。
太阳不忍明，飞御皆惰怠。
乍如彭与黥，呼冤受葅醢。
又如圈中虎，号疮兼吼馁。
虽令伶伦吹，苦韵难可改。
虽令巫咸招，魂爽难复在。
何山有灵药，疗此愿与采。','',''),('quantangshi-18305','嘲鼾睡 二','韓愈','quantangshi','','卷19','澹公坐卧时，长睡无不稳。
吾尝闻其声，深虑五藏损。
黄河弄濆薄，梗涩连拙鮌。
南帝初旧槌，凿窍泄混沌。
迥然忽长引，万丈不可忖。
谓言绝于斯，继出方衮衮。
幽幽寸喉中，草木森苯䔿。
盗贼虽狡狯，亡魂敢窥阃。
鸿蒙总合杂，诡谲骋戾很。
乍如鬬呶呶，忽若怨恳恳。
赋形苦不同，无路寻根本。
何能堙其源，惟有土一畚。','',''),('quantangshi-18306','昼月','韓愈','quantangshi','','卷19','玉盌不磨着泥土，青天孔出白石补。
兔入臼藏蛙缩肚，桂树枯株女闭户。
阴为阳羞固自古，嗟汝下民或敢侮，戏嘲盗视汝目瞽。','',''),('quantangshi-18307','赠张徐州莫辞酒','韓愈','quantangshi','','卷19','莫辞酒，此会固难同。
请看女工机上帛，半作军人旗上红。
莫辞酒，谁为君王之爪牙。
春雷三月不作响，战士岂得来还家。','',''),('quantangshi-18308','辞唱歌','韓愈','quantangshi','','卷19','抑逼敎唱歌，不解看艳词。
坐中把酒人，岂有欢乐姿。
幸有伶者妇，腰身如柳枝。
但令送君酒，如醉如憨痴。
声自肉中出，使人能逶随。
复遣悭恡者，赠金不皱眉。
岂有长直夫，喉中声雌雌。
君心岂无耻，君岂是女儿。
君敎发直言，大声无休时。
君敎哭古恨，不肯复吞悲。
乍可阻君意，艳歌难可为。','',''),('quantangshi-18309','知音者诚希','韓愈','quantangshi','','卷19','知音者诚希，念子不能别。
行行天未晓，携酒踏明月。','',''),('quantangshi-18310','同窦韦寻刘尊师不遇','韓愈','quantangshi','','卷19','秦客何年驻，仙源此地深。
还随蹑凫骑，来访驭风襟。
院闭青霞入，松高老鹤寻。
犹疑隐形坐，敢起窃桃心。','',''),('quantangshi-18311','春雪','韓愈','quantangshi','','卷19','片片驱鸿急，纷纷逐吹斜。
到江还作水，着树渐成花。
越喜飞排瘴，胡愁厚盖砂。
兼云封洞口，助月照天涯。
暝见迷巢鸟，朝逢失辙车。
呈丰尽相贺，宁止力耕家。','',''),('quantangshi-18312','酬蓝田崔丞立之咏雪见寄','韓愈','quantangshi','','卷19','京城数尺雪，寒气倍常年。
泯泯都无地，茫茫岂是天。
崩奔惊乱射，挥霍讶相缠。
不觉侵堂陛，方应折屋椽。
出门愁落道，上马恐平鞯。
朝鼓矜凌起，山斋酩酊眠。
吾方嗟此役，君乃咏其妍。
冰玉清颜隔，波涛盛句传。
朝飧思共饭，夜宿忆同毡。
举目无非白，雄文乃独玄。','',''),('quantangshi-18313','潭州泊船呈诸公','韓愈','quantangshi','','卷19','夜寒眠半觉，鼓笛闹嘈嘈。
暗浪舂楼堞，惊风破竹篙。
主人看使范，客子读离骚。
闻道松醪贱，何须恡错刀。','',''),('quantangshi-18314','饮城南道边古墓上逢中丞过赠礼部卫员外少室张道士','韓愈','quantangshi','','卷19','偶上城南土骨堆，共倾春酒三五杯。
为逢桃树相料理，不觉中丞喝道来。','',''),('quantangshi-18315','池上絮','韓愈','quantangshi','','卷19','池上无风有落晖，杨花晴后自飞飞。
为将纤质凌清镜，湿却无穷不得归。','',''),('quantangshi-18316','赠贾岛','韓愈','quantangshi','','卷19','孟郊死葬北邙山，从此风云得暂闲。
天恐文章浑断绝，更生贾岛着人间。','',''),('quantangshi-18317','赠贾岛','韓愈','quantangshi','','卷19','孟郊死葬北邙山，从此风云得暂闲。
世上不教才子絶，更生贾岛着人间。','',''),('quantangshi-18318','赠译经僧','韓愈','quantangshi','','卷19','万里休言道路赊，有谁敎汝度流沙。
只今中国方多事，不用无端更乱华。','',''),('quantangshi-18319','享惠昭太子庙乐章','王涯','quantangshi','','卷19','威仪毕陈，备乐将阕。
苞茅酒缩，膋萧香彻。
宫臣展事，肃雍在列。
迎精送往，厥鉴昭晰。','',''),('quantangshi-18320','望禁门松雪','王涯','quantangshi','','卷19','宿云开霁景，佳气此时浓。
瑞雪凝清禁，祥烟幂小松。
依稀鸳瓦出，隐映凤楼重。
金阙晴光照，琼枝瑞色封。
叶铺全类玉，柯偃乍疑龙。
讵比寒山上，风霜老昔容。','',''),('quantangshi-18321','广宣上人以诗贺放榜和谢','王涯','quantangshi','','卷19','延英面奉入春闱，亦选功夫亦选奇。
在冶只求金不耗，用心空学秤无私。
龙门变化人皆望，莺谷飞鸣自有时。
独喜至公谁是证，弥天上人与新诗。','',''),('quantangshi-18322','九月九日勤政楼下观百僚献寿','王涯','quantangshi','','卷19','御气黄花节，临轩紫陌头。
早阳生彩仗，霁色入仙楼。
献寿皆鵷鹭，瞻天尽冕旒。
菊樽过九日，凤历肇千秋。
乐奏薰风起，杯酣瑞影收。
年年歌舞度，此地庆皇休。','',''),('quantangshi-18323','春游曲二首 一','王涯','quantangshi','','卷19','万树江边杏，新开一夜风。
满园深浅色，照在绿波中。','',''),('quantangshi-18324','春游曲二首 二','王涯','quantangshi','','卷19','上苑何穷树，花间次第新。
香车与丝骑，风静亦生尘。','',''),('quantangshi-18325','太平词','王涯','quantangshi','','卷19','风俗今和厚，君王在穆清。
行看采华曲，尽是泰阶平。','',''),('quantangshi-18326','送春词','王涯','quantangshi','','卷19','日日人空老，年年春更归。
相欢在尊酒，不用惜花飞。','',''),('quantangshi-18327','塞上曲二首 一','王涯','quantangshi','','卷19','天骄远塞行，出鞘宝刀鸣。
定是酬恩日，今朝觉命轻。','',''),('quantangshi-18328','塞上曲二首 二','王涯','quantangshi','','卷19','塞虏常为敌，边风已报秋。
平生多志气，箭底觅封侯。','',''),('quantangshi-18329','陇上行','王涯','quantangshi','','卷19','负羽到边州，鸣笳度陇头。
云黄知塞近，草白见边秋。','',''),('quantangshi-18330','思君恩','王涯','quantangshi','','卷19','鸡鸣天汉晓，莺语禁林春。
谁入巫山梦，唯应洛水神。','',''),('quantangshi-18331','春闺思','王涯','quantangshi','','卷19','雪尽萱抽叶，风轻水变苔。
玉关音信断，又见发庭梅。','',''),('quantangshi-18332','春江曲','王涯','quantangshi','','卷19','摇漾越江春，相将采白苹。
归时不觉夜，出浦月随人。','',''),('quantangshi-18333','闺人赠远五首 一','王涯','quantangshi','','卷19','花明绮陌春，柳拂御沟新。
为报辽阳客，流芳不待人。','',''),('quantangshi-18334','闺人赠远五首 二','王涯','quantangshi','','卷19','远戍功名薄，幽闺年貌伤。
妆成对春树，不语泪千行。','',''),('quantangshi-18335','闺人赠远五首 三','王涯','quantangshi','','卷19','形影一朝别，烟波千里分。
君看望君处，祗是起行云。','',''),('quantangshi-18336','闺人赠远五首 四','王涯','quantangshi','','卷19','啼莺绿树深，语燕雕梁晚。
不省出门行，沙场知近远。','',''),('quantangshi-18337','闺人赠远五首 五','王涯','quantangshi','','卷19','洞房今夜月，如练复如霜。
为照离人恨，亭亭到晓光。','',''),('quantangshi-18338','从军词三首 一','王涯','quantangshi','','卷19','戈甲从军久，风云识阵难。
今朝拜韩信，计日斩成安。','',''),('quantangshi-18339','从军词三首 二','王涯','quantangshi','','卷19','燕颔多奇相，狼头敢犯边。
寄言班定远，正是立功年。','',''),('quantangshi-18340','从军词三首 三','王涯','quantangshi','','卷19','旄头夜落捷书飞，来奏金门着赐衣。
白马将军频破敌，黄龙戍卒几时归。','',''),('quantangshi-18341','塞下曲二首 一','王涯','quantangshi','','卷19','辛勤几出黄花戍，迢遰初随细柳营。
塞晚每愁残月苦，边愁更逐断篷惊。','',''),('quantangshi-18342','塞下曲二首 二','王涯','quantangshi','','卷19','年少辞家从冠军，金妆宝劒去邀勋。
不知马骨伤寒水，唯见龙城起暮云。','',''),('quantangshi-18343','平戎辞','王涯','quantangshi','','卷19','太白秋高助发兵，长风夜卷虏尘清。
男儿解却腰间劒，喜见从王道化平。','',''),('quantangshi-18344','游春词二首 一','王涯','quantangshi','','卷19','曲江绿柳变烟条，寒谷冰随暖气销。
才见春光生绮陌，已闻清乐动云韶。','',''),('quantangshi-18345','游春词二首 二','王涯','quantangshi','','卷19','经过柳陌与桃蹊，寻逐春光着处迷。
鸟度时时冲絮起，花繁衮衮压枝低。','',''),('quantangshi-18346','秋思二首 一','王涯','quantangshi','','卷19','网轩凉吹动轻衣，夜听更长玉漏稀。
月度天河光转湿，鹊惊秋树叶频飞。','',''),('quantangshi-18347','秋思二首 二','王涯','quantangshi','','卷19','宫连太液见沧波，暑气微消秋意多。
一夜清风苹末起，露珠翻尽满池荷。','',''),('quantangshi-18348','汉苑行','王涯','quantangshi','','卷19','二月春风遍柳条，九天仙乐奏云韶。
蓬莱殿后花如锦，紫阁阶前雪未销。','',''),('quantangshi-18349','秋夜曲','王涯','quantangshi','','卷19','桂魄初生秋露微，轻罗已薄未更衣。
银筝夜久殷勤弄，心怯空房不忍归。','',''),('quantangshi-18350','献寿辞','王涯','quantangshi','','卷19','宫殿参差列九重，祥云瑞气捧堦浓。
微臣欲献唐尧寿，遥指南山对衮龙。','',''),('quantangshi-18351','秋思赠远二首 一','王涯','quantangshi','','卷19','当年只自守空帷，梦里关山觉别离。
不见乡书传雁足，唯看新月吐蛾眉。','',''),('quantangshi-18352','秋思赠远二首 二','王涯','quantangshi','','卷19','厌攀杨柳临清阁，闲采芙蕖傍碧潭。
走马台边人不见，拂云堆畔战初酣。','',''),('quantangshi-18353','春闺思','王涯','quantangshi','','卷19','愁见游空百尺丝，春风挽断更伤离。
闲花落尽青苔地，尽日无人谁得知。','',''),('quantangshi-18354','宫词三十首 一','王涯','quantangshi','','卷19','白人宜着紫衣裳，冠子梳头双眼长。
新睡起来思旧梦，见人忘却道胜常。','',''),('quantangshi-18355','宫词三十首 二','王涯','quantangshi','','卷19','春来新插翠云钗，尚着云头踏殿鞋。
欲得君王回一顾，争扶玉辇下金阶。','',''),('quantangshi-18356','宫词三十首 三','王涯','quantangshi','','卷19','五更初起觉风寒，香炷烧来夜已残。
欲卷珠帘惊雪满，自将红烛上楼看。','',''),('quantangshi-18357','宫词三十首 四','王涯','quantangshi','','卷19','各将金锁锁宫门，院院青娥侍至尊。
头白监门掌来去，问频多是最承恩。','',''),('quantangshi-18358','宫词三十首 五','王涯','quantangshi','','卷19','夜久盘中蜡滴稀，金刀剪起尽霏霏。
传声总是君王唤，红烛台前着舞衣。','',''),('quantangshi-18359','宫词三十首 六','王涯','quantangshi','','卷19','筝翻禁曲觉声难，玉柱皆非旧处安。
记得君王曾道好，长因下辇得先弹。','',''),('quantangshi-18360','宫词三十首 七','王涯','quantangshi','','卷19','一丛高鬓绿云光，官样轻轻淡淡黄。
为看九天公主贵，外边争学内家装。','',''),('quantangshi-18361','宫词三十首 八','王涯','quantangshi','','卷19','宜春院里驻仙舆，夜宴笙歌总不如。
