谁知曾笑他人处，今日将身自入来。','',''),('quantangshi-18363','宫词三十首 十','王涯','quantangshi','','卷19','春风帘里旧青娥，无奈新人夺宠何。
寒食禁花开满树，玉堂终日闭时多。','',''),('quantangshi-18364','宫词三十首 十一','王涯','quantangshi','','卷19','碧绣檐前柳散垂，守门宫女欲攀时。
曾经玉辇从容处，不敢临风折一枝。','',''),('quantangshi-18365','宫词三十首 十二','王涯','quantangshi','','卷19','鸦飞深在禁城墙，多绕重楼复殿傍。
时向春檐瓦沟上，散开朝翅占朝光。','',''),('quantangshi-18366','宫词三十首 十三','王涯','quantangshi','','卷19','白雪猧儿拂地行，惯眠红毯不曾惊。
深宫更有何人到，只晓金阶吠晚萤。','',''),('quantangshi-18367','宫词三十首 十四','王涯','quantangshi','','卷19','百尺仙梯倚阁边，内人争下掷金钱。
风来竞看铜乌转，遥指朱干在半天。','',''),('quantangshi-18368','宫词三十首 十五','王涯','quantangshi','','卷19','春风摆荡禁花枝，寒食秋千满地时。
又落深宫石渠里，尽随流水入龙池。','',''),('quantangshi-18369','宫词三十首 十六','王涯','quantangshi','','卷19','墙墙不断接宫城，金榜皆书殿院名。
万转千回相隔处，各调弦管对闻声。','',''),('quantangshi-18370','宫词三十首 十七','王涯','quantangshi','','卷19','霏霏春雨九重天，渐暖龙池御柳烟。
玉辇游时应不避，千廊万屋自相连。','',''),('quantangshi-18371','宫词三十首 十八','王涯','quantangshi','','卷19','禁门烟起紫沉沉，楼阁当中复道深。
长入暮天凝不散，掖庭宫里动秋砧。','',''),('quantangshi-18372','宫词三十首 十九','王涯','quantangshi','','卷19','炎炎夏日满天时，桐叶交加覆玉墀。
向晚移镫上银簟，丛丛绿鬓坐弹棋。','',''),('quantangshi-18373','宫词三十首 二十','王涯','quantangshi','','卷19','瞳瞳日出大明宫，天乐遥闻在碧空。
禁树无风正和暖，玉楼金殿晓光中。','',''),('quantangshi-18374','宫词三十首 二十一','王涯','quantangshi','','卷19','迥出芙蓉阁上头，九天悬处正当秋。
年年七夕晴光里，宫女穿针尽上楼。','',''),('quantangshi-18375','宫词三十首 二十二','王涯','quantangshi','','卷19','教来鹦鹉语初成，久闭金笼惯认名。
总向春园看花去，独于深院笑人声。','',''),('quantangshi-18376','宫词三十首 二十三','王涯','quantangshi','','卷19','银瓶泻水欲朝妆，烛焰红高粉壁光。
共怪满衣珠翠冷，黄花瓦上有新霜。','',''),('quantangshi-18377','宫词三十首 二十四','王涯','quantangshi','','卷19','迎风殿里罢云和，起听新蝉布浅莎。
为爱九天和露滴，万年枝上最声多。','',''),('quantangshi-18378','宫词三十首 二十五','王涯','quantangshi','','卷19','御果收时属内官，傍檐低压玉阑干。
明朝摘向金华殿，尽日枝边次第看。','',''),('quantangshi-18379','宫词三十首 二十六','王涯','quantangshi','','卷19','内里松香满殿闻，四行阶下暖氤氲。
春深欲取黄金粉，绕树宫娥着绛裙。','',''),('quantangshi-18380','宫词三十首 二十七','王涯','quantangshi','','卷19','禁树传声在九霄，内中残火独遥遥。
千官待取门犹闭，未到宫前下马桥。','',''),('quantangshi-18381','御沟新柳','賈稜','quantangshi','','卷19','御苑阳和早，章沟柳色新。
托根偏近日，布叶乍迎春。
秀质方含翠，清阴欲庇人。
轻云度斜景，多露滴行尘。
褭褭堪离赠，依依独望频。
王孙如可赏，攀折在芳辰。','',''),('quantangshi-18382','御沟新柳','劉遵古','quantangshi','','卷19','韶光先禁柳，几处覆沟新。
映水疑分翠，含烟欲占春。
悠悠迟日晚，褭褭好风频。
吐节茸犹嫩，通条泽稍均。
远和瑶草色，暗拂玉楼尘。
愿假骞飞便，归栖及此辰。','',''),('quantangshi-18383','洛阳清明日雨霁','李正封','quantangshi','','卷19','晓日清明天，夜来嵩少雨。
千门尚烟火，九陌无尘土。
酒绿河桥春，漏闲宫殿午。
游人恋芳草，半犯严城鼓。','',''),('quantangshi-18384','咏露','李正封','quantangshi','','卷19','霏霏灵液重，云表无声落。
霑树急玄蝉，洒池栖皓鹤。
流尘清远陌，飞月澄高阁。
宵润玉堂帘，曙寒金井索。
佳人比珠泪，坐感红绡薄。','',''),('quantangshi-18385','夏游招隐寺暴雨晚晴','李正封','quantangshi','','卷19','竹柏风雨过，萧疎台殿凉。
石渠写奔溜，金刹照颓阳。
鹤飞岩烟碧，鹿鸣涧草香。
山僧引清梵，幡盖绕回廊。','',''),('quantangshi-18386','禅门寺暮钟','李正封','quantangshi','','卷19','簨𥲤高悬于阗钟，黄昏发地殷龙宫。
游人忆到嵩山夜，叠阁连楼倚太空。','',''),('quantangshi-18387','贡院楼北新栽小松','李正封','quantangshi','','卷19','青苍初得地，华省植来新。
尚带山中色，犹含洞里春。
近楼依北户，隐砌净游尘。
鹤寿应成盖，龙形未有鳞。
为梁资大厦，封爵耻嬴秦。
幸此观光日，清风屡得亲。','',''),('quantangshi-18388','南至隔仗望含元殿香炉','崔立之','quantangshi','','卷19','千官望长至，万国拜含元。
隔仗炉光出，浮霜烟气翻。
飘飘萦内殿，漠漠澹前轩。
圣日开如捧，卿云近欲浑。
轮囷洒宫阙，萧索散干坤。
愿倚天风便，披香奉至尊。','',''),('quantangshi-18389','曲池洁寒流','崔立之','quantangshi','','卷19','闲寻欹岸步，因向曲池看。
透底何澄彻，回流乍屈盘。
稍随高树古，迥与远天寒。
月入镜华转，星临珠影攒。
纤鳞时蔽石，转吹或生澜。
愿假涓微效，来濡拙笔端。','',''),('quantangshi-18390','赋得春风扇微和','崔立之','quantangshi','','卷19','时令忽已变，年光俄又春。
高低惠风入，远近芳气新。
靡靡才偃草，泠泠不动尘。
温和乍扇物，煦妪偏感人。
去出桂林漫，来过蕙圃频。
晨辉正澹荡，披拂长相亲。','',''),('quantangshi-18391','南至日隔仗望含元殿香炉','郭遵','quantangshi','','卷19','冕旒亲负扆，卉服尽朝天。
阳谷移初日，金炉出御烟。
芬馨流远近，散漫入貂蝉。
霜仗凝逾白，朱栏映转鲜。
如看浮阙在，稍觉逐风迁。
为沐皇家庆，来瞻羽卫前。','',''),('quantangshi-18392','赋得春风扇微和','郭遵','quantangshi','','卷19','微风飘淑气，散漫及兹晨。
习习何处至，熙熙与春亲。
暧空看早辨，映日度逾频。
高拂非烟杂，低垂众卉新。
霁天轻有霭，绮陌尽无尘。
还似登台意，元和欲煦人。','',''),('quantangshi-18393','赋得风动万年枝','韋紓','quantangshi','','卷19','嘉名标万祀，擢秀出深宫。
嫩叶含烟霭，芳柯振惠风。
参差摇翠色，绮靡舞晴空。
气禀祯祥异，荣霑雨露同。
天年方未极，圣寿比应崇。
幸列华林里，知殊众木中。','',''),('quantangshi-18394','赋得风动万年枝','樊陽源','quantangshi','','卷19','珍木罗前殿，乘春任好风。
振柯方褭褭，舒叶乍蒙蒙。
影动丹墀上，声传紫禁中。
离披偏向日，凌乱半分空。
轻拂祥烟散，低摇翠色同。
长令占天眷，四气借全功。','',''),('quantangshi-18395','赋得风动万年枝','許稷','quantangshi','','卷19','琼树偏春早，光飞处处宜。
晓浮三殿日，暗度万年枝。
婀娜摇仙禁，缤翻映玉池。
含芳烟乍和，拂砌影初移。
为近韶阳煦，皆先众卉垂。
成阴知可待，不与众芳随。','',''),('quantangshi-18396','闰月定四时','許稷','quantangshi','','卷19','玉律穷三纪，推为积闰期。
月余因妙算，岁遍自成时。
乍觉年华改，翻怜物候迟。
六旬知不惑，四气本无欺。
月桂亏还正，阶蓂落复滋。
从斯分历象，共仰定毫厘。','',''),('quantangshi-18397','谢真人还旧山','范傳正','quantangshi','','卷19','麾盖从仙府，笙歌入旧山。
水流丹竈缺，云起草堂关。
白鹿行为卫，青鸾舞自闲。
种松鳞未立，移石藓仍斑。
望路烟霞外，回舆岩岫间。
岂唯辽海鹤，空叹令威还。','',''),('quantangshi-18398','范成君撃洞阴磬','范傳正','quantangshi','','卷19','历历闻金奏，微微下玉京。
为祥家谍久，偏识洞阴名。
澹伫人闻听，铿锵古曲成。
何须百兽舞，自畅九天情。
注目看无见，留心记未精。
云霄如可托，借鹤向层城。','',''),('quantangshi-18399','赋得春风扇微和','范傳正','quantangshi','','卷19','暧暧当迟日，微微扇好风。
吹摇新叶上，光动浅花中。
澹荡凝清昼，氤氲暧碧空。
稍看生绿水，已觉散芳丛。
徙倚情偏适，裴回赏未穷。
妍华不可状，竟夕气融融。','',''),('quantangshi-18400','赋得春风扇微和','豆盧榮','quantangshi','','卷19','春晴生缥缈，软吹和初徧。
池影动渊沦，山容发葱蒨。
迟迟入绮阁，习习流芳甸。
树杪扬莺啼，阶前落花片。
韶光恐闲放，旭日宜游宴。
文客拂尘衣，仁风愿回扇。','',''),('quantangshi-18401','赋得春风扇微和','邵偃','quantangshi','','卷19','微风扇和气，韶景共芳晨。
始见郊原绿，旋过御苑春。
三条开广陌，八水泛通津。
烟动花间叶，香流马上人。
逶迤云彩曙，嘹唳鸟声频。
为报东堂客，明朝桂树新。','',''),('quantangshi-18402','赋得春风扇微和','柳道倫','quantangshi','','卷19','青阳初入律，淑气应春风。
始辨梅花里，俄分柳色中。
依微开夕照，澹荡媚晴空。
拂水生苹末，经岩触桂丛。
稍抽兰叶紫，微吐杏花红。
愿逐仁风布，将俾生植功。','',''),('quantangshi-18403','赋得春风扇微和','陳九流','quantangshi','','卷19','喜见阳和至，遥知橐龠功。
迟迟散南陌，褭褭逐东风。
暗入芳园里，潜吹草木中。
兰荪才有绿，桃杏未成红。
已觉寒光尽，还看淑气通。
由来荣与悴，今日发应同。','',''),('quantangshi-18404','谢真人仙驾还旧山','夏方慶','quantangshi','','卷19','何年成道去，绰约化童颜。
天上辞仙侣，人间忆旧山。
沧桑今已变，萝蔓尚堪攀。
云覆瑶坛净，苔生丹竈闲。
逍遥堪白石，寂寞闭玄关。
应是悲尘世，思将羽驾还。','',''),('quantangshi-18405','公子行','陳羽','quantangshi','','卷19','金羁白面郎，何处蹋青来。
马娇郎半醉，躞蹀望楼台。
似见楼上人，玲珑窗户开。
隔花闻一笑，落日不知回。','',''),('quantangshi-18406','古意','陳羽','quantangshi','','卷19','十三学绣罗衣裳，自怜红袖闻馨香。
人言此是嫁时服，含笑不刺双鸳鸯。
郎年十九髭未生，拜官天下闻郎名。
车马骈阗贺门馆，自然不失为公卿。
是时妾家犹未贫，兄弟出入双车轮。
繁华全盛两相敌，与郎年少为婚姻。
郎家居近御沟水，豪门客尽蹑珠履。
雕盘酒器常不干，晓入中厨妾先起。
姑嫜严肃有规矩，小姑娇憨意难取。
朝参暮拜白玉堂，绣衣着尽黄金缕。
妾貌渐衰郎渐薄，时时强笑意索寞。
知郎本来无岁寒，几回掩泪看花落。
妾年四十丝满头，郎年五十封公侯。
男儿全盛日忘旧，银牀羽帐空飕飗。
庭花红遍蝴蝶飞，看郎佩玉下朝时。
归来略略不相顾，却令侍婢生光辉。
郎恨妇人易衰老，妾亦恨深不忍道。
看郎强健能几时，年过六十还枯[槁]。','',''),('quantangshi-18407','长相思','陳羽','quantangshi','','卷19','相思长相思，相思无限极。
相思苦相思，相思损容色。
容色真可惜，相思不可彻。
日日长相思，相思肠断绝。
肠断绝，泪还续，闲人莫作相思曲。','',''),('quantangshi-18408','送戴端公赴容州','陳羽','quantangshi','','卷19','分命诸侯重，葳蕤绣服香。
八蛮治险阻，千骑蹋繁霜。
山断旌旗出，天晴劒佩光。
还将小戴礼，远出化南方。','',''),('quantangshi-18409','送殷华之洪州','陳羽','quantangshi','','卷19','离堂悲楚调，君奏豫章行。
愁处雪花白，梦中江水清。
扣船歌月色，避浪宿猨声。
还作经年别，相思湖草生。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-18410','春日晴原野望','陳羽','quantangshi','','卷19','东风吹暖气，消散入晴天。
渐变池塘色，欲生杨柳烟。
蒙茸花向月，潦倒客经年。
乡思应愁望，江湖春水连。','',''),('quantangshi-18411','湘妃怨','陳羽','quantangshi','','卷19','舜欲省蛮陬，南巡非逸游。
九山沈白日，二女泣沧洲。
目极楚云断，恨连湘水流。
至今闻鼓瑟，咽绝不胜愁。','',''),('quantangshi-18412','冬晚送友人使西蕃','陳羽','quantangshi','','卷19','驿使向天西，巡羌复入氐。
玉关晴有雪，砂碛雨无泥。
落泪军中笛，惊眠塞上鸡。
逢春乡思苦，万里草萋萋。','',''),('quantangshi-18413','春园即事','陳羽','quantangshi','','卷19','水隔羣物远，夜深风起频。
霜中千树橘，月下五湖人。
听鹤忽忘寝，见山如得邻。
明年还到此，共看洞庭春。','',''),('quantangshi-18414','送友人及第归江东','陳羽','quantangshi','','卷19','五陵春色泛花枝，心醉花前远别离。
落羽耻为关右客，成名空羡里中儿。
都门雨歇愁分处，山店灯残梦到时。
家住洞庭多钓伴，因来相贺话相思。','',''),('quantangshi-18415','梓州与温商夜别','陳羽','quantangshi','','卷19','凤皇城里花时别，客舍莫辞先买酒，相门曾忝共登龙。
迎风骚屑千家竹，隔水悠扬午夜钟。
明日又行西蜀路，不堪天际远山重。','',''),('quantangshi-18416','长安卧病秋夜言怀','陳羽','quantangshi','','卷19','九重门锁禁城秋，月过南宫渐映楼。
紫陌夜深槐露滴，碧空云尽火星流。
风清刻漏传三殿，甲第歌钟乐五侯。
楚客病来乡思苦，寂寥灯下不胜愁。','',''),('quantangshi-18417','喜雪上窦相公','陳羽','quantangshi','','卷19','千门万户雪花浮，点点无声落瓦沟。
全似玉尘销更积，半成冰水结还流。
光添曙色连天远，平地已沾盈尺润，年丰须荷富人侯。','',''),('quantangshi-18418','宴杨驸马山亭','陳羽','quantangshi','','卷19','垂杨拂岸草茸茸，绣户窗前花影重。
鲙下玉盘红缕细，酒开金瓮绿醅醲。
中朝附马何平叔，南国词人陆士龙。
落日泛舟同醉处，回潭百丈映千峯。','',''),('quantangshi-18419','西蜀送许中庸归秦赴举','陳羽','quantangshi','','卷19','春色华阳国，秦人此别离。
驿楼横水影，乡路入花枝。
日暖莺飞好，山晴马去迟。
劒门当石隘，栈阁入云危。
独鹤心千里，贫交酒一巵。
桂条攀偃蹇，兰叶藉参差。
旅梦惊蝴蝶，残芳怨子规。
碧霄今夜月，惆怅上峨嵋。','',''),('quantangshi-18420','小苑春望宫池柳色','陳羽','quantangshi','','卷19','宛宛如丝柳，含黄一望新。
未成沟上暗，且向日边春。
袅娜方遮水，低迷欲醉人。
托空芳郁郁，逐溜影鳞鳞。
弄水滋宵露，垂枝染夕尘。
夹堤连太液，还似映天津。','',''),('quantangshi-18421','中秋夜临镜湖望月','陳羽','quantangshi','','卷19','镜里秋宵望，湖平月彩深。
圆光珠入浦，浮照鹊惊林。
澹动光还碎，婵娟影不沈。
远时生岸曲，空处落波心。
逈彻轮初满，孤明魄未侵。
桂枝如可折，何惜夜登临。','',''),('quantangshi-18422','江上愁思二首 一','陳羽','quantangshi','','卷19','江上翁开门，开门向衰草。
只知愁子孙，不觉生涯老。','',''),('quantangshi-18423','江上愁思二首 二','陳羽','quantangshi','','卷19','江上草茎枯，茎枯叶复焦。
那堪芳意尽，夜夜没寒潮。','',''),('quantangshi-18424','梁城老人怨','陳羽','quantangshi','','卷19','朝为耕种人，暮作刀枪鬼。
