殷勤好去武陵客，莫引世人相逐来。','',''),('quantangshi-18466','赠人','陳羽','quantangshi','','卷19','或棹孤舟或杖藜，寻常适意钓长溪。
草堂竹径在何处，落日孤烟寒渚西。','',''),('quantangshi-18467','句','陳羽','quantangshi','','卷19','稚子新能编笋笠，山妻旧解补荷衣。
秋山隔岸清猨叫，湖水当门白鸟飞。','',''),('quantangshi-18468','东风二章 一','歐陽詹','quantangshi','','卷19','东风叶时，匪沃匪飘。
莫雪凝川，莫阴冱郊。
朝不徯夕乃销，东风之行地上兮。
上德临慝，匪戮匪枭。
莫暴在野，莫丑在阶。
以踣以歼，夕不徯朝，陇西公来浚都兮。','',''),('quantangshi-18469','东风二章 二','歐陽詹','quantangshi','','卷19','东风叶时，匪凿匪[穮]。
莫蛰在泉，莫枯在条。
宵不徯晨乃繇，东风之行地上兮。
上德为政，匪食匪招。
莫顾于家，莫流于辽。
以饱以回，晨不徯霄，陇西公来浚都兮。','',''),('quantangshi-18470','有所恨二章 一','歐陽詹','quantangshi','','卷19','相思君子，吁嗟万里。
亦既至止，曷不觏止。
本不信巫，谓巫言是履。
在门五日，如待之死，有所恨兮。','',''),('quantangshi-18471','有所恨二章 二','歐陽詹','quantangshi','','卷19','相思遗衣，为忆以贻。
亦既受止，曷不保持。
本不欺友，谓友情是违。
隔生之赠，造次亡之，有所恨兮。','',''),('quantangshi-18472','玩月','歐陽詹','quantangshi','','卷19','八月十五夕，旧嘉蟾兔光。
斯从古人好，共下今宵堂。
素魄皎孤凝，芳辉纷四扬。
裴回林上头，泛灧天中央。
皓露助流华，轻风佐浮凉。
清冷到肌骨，洁白盈衣裳。
惜此苦宜玩，揽之非可将。
含情顾广庭，愿勿沈西方。','',''),('quantangshi-18473','咏德上韦检察','歐陽詹','quantangshi','','卷19','少华类太华，太室似少室。
亚相与丞相，亦复无异质。
渟如月临水，肃若松照日。
辉影互光澄，阴森两葱郁。
连城鸾凤分，同气龟龙出。
并力革夷心，通筹整师律。
英豪愿回席，蛮貊皆屈膝。
中外行分途，寰瀛待清谧。','',''),('quantangshi-18474','寓兴','歐陽詹','quantangshi','','卷19','桃李有奇质，樗栎无妙姿。
皆承庆云沃，一种春风吹。
美恶苟同归，喧嚣徒尔为。
相将任玄造，聊醉手中巵。','',''),('quantangshi-18475','答韩十八驽骥吟','歐陽詹','quantangshi','','卷19','故人舒其愤，昨示驽骥篇。
驽以易售陈，骥以难知言。
委曲感既深，咨嗟词亦殷。
伊情有远澜，余志逊其源。
室在周孔堂，道通尧舜门。
调雅声寡同，途遐势难翻。
顾兹万恨来，假彼二物云。
贱贵而贵贱，世人良共然。
巴蕉一叶妖，茙葵一花妍。
毕无才实资，手植堦墀前。
楩柟十围瑰，松柏百尺坚。
罔念梁栋功，野长丘墟边。
伤哉昌黎韩，焉得不迍邅。
上帝本厚生，大君方建元。
宝将庇羣甿，庶此规崇轩。
班尔图永安，抡择期精专。
君看广厦中，岂有树庭萱。','',''),('quantangshi-18476','益昌行','歐陽詹','quantangshi','','卷19','驱马至益昌，倍惊风俗和。
耕夫陇上谣，负者途中歌。
处处川复原，重重山与河。
人烟遍余田，时稼无闲坡。
问业一何修，太守德化加。
问身一何安，太守恩怀多。
贤哉我太守，在古无以过。
爱人甚爱身，治郡如治家。
云雷既奋腾，草木遂萌芽。
乃知良二千，德足为国华。
今时固精求，汉帝非徒嗟。
四海有青春，众植伫扬葩。
期当作说霖，天下同雱𩃱。','',''),('quantangshi-18477','自淮中却赴洛途中作','歐陽詹','quantangshi','','卷19','惆怅策疲马，孤蓬被风吹。
昨东今又西，冉冉长路岐。
岁晚树无叶，夜寒霜满枝。
旅人恒苦辛，冥寞天何知。','',''),('quantangshi-18478','晨装行','歐陽詹','quantangshi','','卷19','村店月西出，山林鹎鵊声。
旅灯彻夜席，束囊事晨征。
寂寂人尚眠，悠悠天未明。
岂无偃息心，所务前有程。','',''),('quantangshi-18479','新都行','歐陽詹','quantangshi','','卷19','缥缈空中丝，蒙笼道傍树。
翻兹叶间吹，惹破花上露。
悠扬丝意去，苒蒻花枝住。
何计脱缠绵，天长春日暮。','',''),('quantangshi-18480','铜雀妓','歐陽詹','quantangshi','','卷19','萧条登古台，回首黄金屋。
落叶不归林，高陵永为谷。
妆容徒自丽，舞态阅谁目。
惆怅繐帷空，歌声苦于哭。','',''),('quantangshi-18481','太原旅怀呈薛十八侍御齐十二奉礼','歐陽詹','quantangshi','','卷19','前来称英隽，有食主人鱼。
后来曰贤才，又受主人车。
伊予亦投刺，恩煦胡凋疎。
既覩主人面，复见主人书。
糊口百家周，赁庑三月余。
眼见寒序臻，坐送秋光除。
西日惄饥肠，北风疾絺裾。
升堂有知音，此意当何如。','',''),('quantangshi-18482','李评事公进示文集因赠之','歐陽詹','quantangshi','','卷19','风雅不坠地，五言始君先。
希微嘉会章，杳冥河梁篇。
理蔓语无枝，言一意则千。
往来更后人，浇荡醨前源。
倾筐实不收，朴樕华争繁。
大教护微旨，哲人生令孙。
高飙激颓波，坐使横流翻。
昔日越重阻，侧聆沧海传。
逮兹觌清扬，幸覩青琅编。
泠泠中山醇，片片昆丘璠。
一杯有余味，再览增光鲜。
对宝人皆鉴，握鞶良自妍。
吾其告先师，六义今还全。','',''),('quantangshi-18483','徐十八晦落第','歐陽詹','quantangshi','','卷19','嘉谷不夏熟，大器当晚成。
徐生异凡鸟，安得非时鸣。
汲汲有所为，驱驱无本情。
懿哉苍梧凤，终见排云征。','',''),('quantangshi-18484','春日途中寄故园所亲','歐陽詹','quantangshi','','卷19','客路度年华，故园云未返。
悠悠去源水，日日只有远。
始叹秋叶零，又看春草晚。
寄书南飞鸿，相忆剧乡县。','',''),('quantangshi-18485','蜀中将归留辞韩相公贯之','歐陽詹','quantangshi','','卷19','宁体即云构，方前恒玉食。
贫居岂及此，要自怀归忆。
在梦关山远，如流岁华逼。
明晨首乡路，迢遰孤飞翼。','',''),('quantangshi-18486','江夏留别华二','歐陽詹','quantangshi','','卷19','弭棹已伤别，不堪离绪催。
十年一心人，千里同舟来。
乡路我尚遥，客游君未回。
将何慰两端，互勉临岐杯。','',''),('quantangshi-18487','送潭州陆户曹之任','歐陽詹','quantangshi','','卷19','三语又为掾，大家闻屈声。
多年名下人，四姓江南英。
衡岳半天秀，湘潭无底清。
何言驱车远，去有蒙庄情。','',''),('quantangshi-18488','福州送郑楚材赴京时监察刘公亮有感激郑意','歐陽詹','quantangshi','','卷19','美人河岳灵，家本荥水濆。
门承若兰族，身蕴如琼文。
早折青桂枝，俯窥鸿鹄羣。
迩来丹霄姿，远逐苍梧云。
有伊光鉴人，惜兹瑶蕙薰。
中酣前激昂，四座同氛氲。
海郡梅霪晴，山邮炎景曛。
回翔罢南游，鸣唳期西闻。
秦塞鸾凤征，越江云雨分。
从兹一别离，伫致如尧君。','',''),('quantangshi-18489','初发太原途中寄太原所思','歐陽詹','quantangshi','','卷19','驱马觉渐远，回头长路尘。
高城已不见，况复城中人。
去意自未甘，居情谅犹辛。
五原东北晋，千里西南秦。
一屦不出门，一车无停轮。
流萍与系匏，早晚期相亲。','',''),('quantangshi-18490','汝川行','歐陽詹','quantangshi','','卷19','汝坟春女蚕忙月，朝起采桑日西没。
轻绡裙露红罗袜，半蹋金梯倚枝歇。
垂空玉腕若无骨，映叶朱唇似花发。
相欢谁是游冶郎，蚕休不得岐路旁。','',''),('quantangshi-18491','智达上人水精念珠歌','歐陽詹','quantangshi','','卷19','水已清，清中不易当其精。
精华极，何宜更复加磨拭。
良工磨拭成贯珠，泓澄洞澈看如无。
星辉月耀莫之逾，骇鸡照乘徒称殊。
上人念佛泛贞谛，一佛一珠以为计。
既指其珠当佛身，亦欲珠明佛像智。
咨董母，访朱公。
得之玓瓅羣奇中，龙龛鹫岭长随躬。
朝自守持纤掌透，夜来月照红条空。
穷川极陆难为宝，孰说軖璖将玛瑙。
连连寒溜下阴轩，荧荧泫露垂秋草。
皎晶晶，彰煌煌。
陆离电烻纷不常，凌眸晕目生光芒。
我来借问修行术，数日殷勤美兹物。
上人视日授微言，心静如斯即诸佛。','',''),('quantangshi-18492','许州途中','歐陽詹','quantangshi','','卷19','秦川行尽颍川长，吴江越岭已同方。
征途渺渺烟茫茫，未得还乡伤近乡。
随萍逐梗见春光，行乐登台鬬在旁。
林间啼鸟野中芳，有似故园皆断肠。','',''),('quantangshi-18493','赋得秋河曙耿耿送郭秀才应举','歐陽詹','quantangshi','','卷19','月没天欲明，秋河尚凝白。
皑皑积光素，耿耿横虚碧。
南斗接，北辰连，空蒙鸿洞浮高天。
荡荡漫漫皆晶然，实类平芜流大川。
星为潭底珠，云是波中烟。
鸡唱漏尽东方作，曲渚苍苍晓霜落。
雁叫疑从清浅惊，凫声似在沿洄泊。
并州细侯直下孙，才应秋赋怀金门。
念排云汉将飞翻，仰之踊跃当华轩。
夜来陪饯欧阳子，偶坐通宵见深旨。
心知慷慨日昭然，前程心在青云里。','',''),('quantangshi-18494','送袁秀才下第归毗陵','歐陽詹','quantangshi','','卷19','羸马出都门，修途指江东。
关河昨夜雨，草木非春风。
矢舍虽未中，璞全终待攻。
层霄秋可翔，岂不随高鸿。','',''),('quantangshi-18495','闻邻舍唱凉州有所思','歐陽詹','quantangshi','','卷19','有善伊凉曲，离别在天涯。
虚堂正相思，所妙发邻家。
声音虽类闻，形影终以遐。
因之增远怀，惆怅菖蒲花。','',''),('quantangshi-18496','陪太原郑行军中丞登汾上阁中丞诗曰汾楼秋水阔宛似到阊门惆怅江湖思惟将南客论南客即詹也辄书即事上答','歐陽詹','quantangshi','','卷19','并州汾上阁，登望似吴阊。
贯郭河通路，萦村水逼乡。
城槐临枉渚，巷市接飞梁。
莫论江湖思，南人正断肠。','',''),('quantangshi-18497','送少微上人归德峯','歐陽詹','quantangshi','','卷19','不负人间累，栖身任所从。
灰心闻密行，菜色见羸容。
幻世方同悟，深居愿继踪。
孤云与禅诵，到后在何峯。','',''),('quantangshi-18498','荆南夏夜水楼怀昭丘直上人云梦李莘','歐陽詹','quantangshi','','卷19','无机成旅逸，中夜上江楼。
云尽月如练，水凉风似秋。
凫声闻梦泽，黛色上昭丘。
不远人情在，良宵恨独游。','',''),('quantangshi-18499','酬裴十二秀才孩子咏','歐陽詹','quantangshi','','卷19','算日未成年，英姿已[襃]然。
王家千里后，荀氏八龙先。
葱蒨松犹嫩，清明月渐圆。
将何一枝桂，容易赏名贤。','',''),('quantangshi-18500','旅次舟中对月寄姜公','歐陽詹','quantangshi','','卷19','中宵天色净，片月出沧洲。
皎洁临孤岛，婵娟入乱流。
应同故园夜，独起异乡愁。
那得修蓬转，从君上庾楼。','',''),('quantangshi-18501','除夜长安客舍','歐陽詹','quantangshi','','卷19','十上书仍寝，如流岁又迁。
望家思献寿，算甲恨长年。
虚牖传寒柝，孤灯照绝编。
谁应问穷辙，泣尽更潸然。','',''),('quantangshi-18502','早秋登慈恩寺塔','歐陽詹','quantangshi','','卷19','宝塔过千仞，登临尽四维。
毫端分马颊，墨点辨蛾眉。
地逈风弥紧，天长日久迟。
因高欲有赋，远意惨生悲。','',''),('quantangshi-18503','太原和严长官八月十五日夜西山童子上方玩月寄中丞少尹','歐陽詹','quantangshi','','卷19','西寺碧云端，东溟白雪团。
年来一夜玩，君在半天看。
素魄当怀上，清光在下寒。
宜裁济江什，有阻惠连欢。','',''),('quantangshi-18504','九日广陵同陈十五先辈登高怀林十二先辈','歐陽詹','quantangshi','','卷19','客路重阳日，登高寄上楼。
风烟今令节，台阁古雄州。
泛菊聊斟酒，持萸嬾插头。
情人共惆怅，良久不同游。','',''),('quantangshi-18505','题严光钓台','歐陽詹','quantangshi','','卷19','弭棹历尘迹，悄然关我情。
伊无昔时节，岂有今日名。
辞贵不辞贱，是心谁复行。
钦哉此溪曲，永独古风清。','',''),('quantangshi-18506','送高士安下第归岷南宁觐','歐陽詹','quantangshi','','卷19','偕隐有贤亲，岷南四十春。
栖云自匪石，观国暂同尘。
就养思儿戏，延年爱鸟伸。
还看谢时去，有类颍阳人。','',''),('quantangshi-18507','述德上兴元严仆射','歐陽詹','quantangshi','','卷19','山横碧立并雄岷，大阜洪川共降神。
心合云雷清祸乱，力回天地作阳春。
非熊德愧当周辅，称杰叨慙首汉臣。
何幸腐儒无一艺，得为门下食鱼人。','',''),('quantangshi-18508','及第后酬故园亲故','歐陽詹','quantangshi','','卷19','才非天授学非师，以此成名曩岂期。
杨叶射频因偶中，桂枝材美敢当之。
称文作艺方慙德，相贺投篇料愧词。
犹着褐衣何足羡，如君即是载鸣时。','',''),('quantangshi-18509','题华十二判官汝州宅内亭','歐陽詹','quantangshi','','卷19','高居胜景谁能有，佳意幽情共可欢。
新柳遶门青翡翠，修篁浮径碧琅玕。
步兵阮籍空除屏，彭泽陶潜谩挂冠。
只在城隍也趋府，岂如吾子道斯安。','',''),('quantangshi-18510','薛舍人使君观察韩判官侍御许雨晴到所居既霁先呈即事','歐陽詹','quantangshi','','卷19','江臯昨夜雨收梅，寂寂衡门与钓台。
西岛落花随水至，前山飞鸟出云来。
观风驷马能言驻，行县双旌许蹔回。
岂不偶然聊为竹，空令石迳扫莓苔。','',''),('quantangshi-18511','元日陪早朝','歐陽詹','quantangshi','','卷19','斗柄东回岁又新，邃旒南面挹来宾。
和光仿髴楼台晓，休气氛氲天地春。
仪龠不唯丹穴鸟，称觞半是越裳人。
江臯腐草今何幸，亦与恒星拱北辰。','',''),('quantangshi-18512','和太原郑中丞登龙兴寺阁','歐陽詹','quantangshi','','卷19','青窗朱户半天开，极目凝神望几回。
晋国颓墉生草树，皇家瑞气在楼台。
千条水入黄河去，万点山从紫塞来。
独恨侍游违长者，不知高意是谁陪。','',''),('quantangshi-18513','咏德上太原李尚书','歐陽詹','quantangshi','','卷19','那以公方郭细侯，并州非复旧并州。
九重帝宅司丹地，十万兵枢拥碧油。
锵玉半为趋合吏，腰金皆是走庭流。
王襃见德空知颂，身在三千最上头。','',''),('quantangshi-18514','和严长官秋日登太原龙兴寺阁野望','歐陽詹','quantangshi','','卷19','百丈化城楼，君登最上头。
九霄回栈路，八到视并州。
烟火遗尧庶，山河启圣猷。
短垣齐介岭，片白指分流。
清铎中天籁，哀鸣下界秋。
境闲知道胜，心远见名浮。
岂念乘肥马，方应驾大牛。
自怜蓬逐吹，不得与良游。','',''),('quantangshi-18515','小苑春望宫池柳色','歐陽詹','quantangshi','','卷19','东风韶景至，垂柳御沟新。
媚作千门秀，连为一道春。
柔荑生女指，嫩叶长龙鳞。
舞絮回青岸，翻烟拂绿苹。
王孙初命赏，佳客欲伤神。
芳意堪相赠，一枝先远人。','',''),('quantangshi-18516','蜀门与林藴分路后屡有山川似闽中因寄林藴藴亦闽人也','歐陽詹','quantangshi','','卷19','村步如延寿，川原似福平。
无人相共识，独自故乡情。','',''),('quantangshi-18517','读周太公传','歐陽詹','quantangshi','','卷19','论兵去商虐，讲德兴周道。
屠沽未遇时，岂异兹川老。','',''),('quantangshi-18518','乐津店北陂','歐陽詹','quantangshi','','卷19','婵娟有丽玉如也，美笑当予系予马。
罗帏碧簟岂相容，行到山头忆山下。','',''),('quantangshi-18519','出蜀门','歐陽詹','quantangshi','','卷19','北客今朝出蜀门，翛然领得入时魂。
游人莫道归来易，三不曾闻古老言。','',''),('quantangshi-18520','题第五司户侍御','歐陽詹','quantangshi','','卷19','曾称野鹤比羣公，忽作长松向府中。
骢马不骑人不识，冷然三尺别生风。','',''),('quantangshi-18521','建溪行待陈诩','歐陽詹','quantangshi','','卷19','偕行那得会心期，先者贪前后者迟。
空忆丽词能状物，每看奇异但相思。','',''),('quantangshi-18522','述德上兴元严仆射','歐陽詹','quantangshi','','卷19','推车阃外主恩新，今日梁川草遍春。
玉色据鞍双节下，扬兵百万路无尘。','',''),('quantangshi-18523','许州送张中丞出临颍镇','歐陽詹','quantangshi','','卷19','心诵阴符口不言，风驱千骑出辕门。
孙吴去后无长策，谁敌留侯直下孙。','',''),('quantangshi-18524','覩亡友题诗处','歐陽詹','quantangshi','','卷19','旧友亲题壁上诗，伤看缘迹不缘词。
门前犹是长安道，无复回车下笔时。','',''),('quantangshi-18525','题秦岭','歐陽詹','quantangshi','','卷19','南下斯须隔帝乡，北行一步掩南方。
悠悠烟景两边意，蜀客秦人各断肠。','',''),('quantangshi-18526','自南山却赴京师石臼岭头即事寄严仆射','歐陽詹','quantangshi','','卷19','鸟企蛇盘地半天，下窥千仞到浮烟。
因高回望沾恩处，认得梁州落日边。','',''),('quantangshi-18527','与洪孺卿自梁州回途中经骆谷见野果有闽中悬壶子即同采摘因呈之洪亦闽人','歐陽詹','quantangshi','','卷19','青苞朱实忽离离，摘得盈筐泪更垂。
上德同之岂无意，故园山路一枝枝。','',''),('quantangshi-18528','韦晤宅听歌','歐陽詹','quantangshi','','卷19','服制虹霓鬓似云，萧郎屋里上清人。
等闲逐酒倾杯乐，飞尽虹梁一夜尘。','',''),('quantangshi-18529','与林藴同之蜀途次嘉陵江认得越鸟声呈林林亦闽中人也','歐陽詹','quantangshi','','卷19','正是闽中越鸟声，几回留听暗沾缨。
伤心激念君深浅，共有离乡万里情。','',''),('quantangshi-18530','送闻上人游嵩山','歐陽詹','quantangshi','','卷19','二室峯峯昔愿游，从云从鹤思悠悠。
丹梯石路君先去，为上青冥最上头。','',''),('quantangshi-18531','永安寺照上人房','歐陽詹','quantangshi','','卷19','草席蒲团不扫尘，松闲石上似无人。
羣阴欲午钟声动，自煮溪蔬养幻身。','',''),('quantangshi-18532','山中老僧','歐陽詹','quantangshi','','卷19','笑向来人话古时，绳牀竹杖自扶持。
秋深头冷不能剃，白黑苍然髪到眉。','',''),('quantangshi-18533','赠鲁山李明府','歐陽詹','quantangshi','','卷19','外户通宵不闭关，抱孙弄子万家闲。
若将邑号称贤宰，又是皇唐李鲁山。','',''),('quantangshi-18534','泉州赴上都留别舍弟及故人','歐陽詹','quantangshi','','卷19','天长地阔多岐路，身即飞蓬共水萍。
匹马将驱岂容易，弟兄亲故满离亭。','',''),('quantangshi-18535','送张骠骑邠宁行营','歐陽詹','quantangshi','','卷19','宝马雕弓金仆姑，龙骧虎视出皇都。
扬鞭莫怪轻胡虏，曾在渔阳敌万夫。','',''),('quantangshi-18536','题棃岭','歐陽詹','quantangshi','','卷19','南北风烟即异方，连峯危栈倚苍苍。
哀猨咽水偏高处，谁不沾衣望故乡。','',''),('quantangshi-18537','秋夜寄僧','歐陽詹','quantangshi','','卷19','尚被浮名诱此身，今时谁与德为邻。
遥知是夜檀溪上，月照千峯为一人。','',''),('quantangshi-18538','观送葬','歐陽詹','quantangshi','','卷19','何事悲酸泪满巾，浮生共是北邙尘。
他时不见北山路，死者还曾哭送人。','',''),('quantangshi-18539','宿建溪中宵即事','歐陽詹','quantangshi','','卷19','𥳌{𥫗/穷}一席眠还坐，蛙噪萤飞夜未央。
僮仆舟人空寂寂，隔帘微月入中仓。','',''),('quantangshi-18540','题王明府郊亭','歐陽詹','quantangshi','','卷19','日日郊亭启竹扉，论桑劝穑是常机。
山城要得牛羊下，方与农人分背归。','',''),('quantangshi-18541','塞上行','歐陽詹','quantangshi','','卷19','闻说胡兵欲利秋，昨来投笔到营州。
骁雄已许将军用，边塞无劳天子忧。','',''),('quantangshi-18542','题别业','歐陽詹','quantangshi','','卷19','千山江上背斜晖，一径中峯见所归。
不信扁舟回在晚，宿云先已到柴扉。','',''),('quantangshi-18543','九日广陵登高怀邵二先辈','歐陽詹','quantangshi','','卷19','簪萸泛菊俯平阡，饮过三杯却惘然。
十岁此辰同醉友，登高各处已三年。','',''),('quantangshi-18544','题延平劒潭','歐陽詹','quantangshi','','卷19','想象精灵欲见难，通津一去水漫漫。
空余昔日凌霜色，长与澄潭生昼寒。','',''),('quantangshi-18545','晚泊漳州营头亭','歐陽詹','quantangshi','','卷19','回峯叠嶂遶庭隅，散点烟霞胜画图。
日暮华轩卷长箔，太清云上对蓬壶。','',''),('quantangshi-18546','赠山南严兵马使','歐陽詹','quantangshi','','卷19','为雁为鸿弟与兄，如雕如鹗杰连英。
天旋地转烟云黑，共鼓长风六合清。','',''),('quantangshi-18547','除夜侍酒呈诸兄示舍弟','歐陽詹','quantangshi','','卷19','莫叹明朝又一春，相看堪共贵兹身。
悠悠寰宇同今夜，膝下传杯有几人。','',''),('quantangshi-18548','皇武 一','柳宗元','quantangshi','','卷19','皇耆其武，于溵于淮。
既巾乃车，环蔡具来。
狡众昏嚚，甚毒于酲。
狂奔呌呶，以干大刑。','',''),('quantangshi-18549','皇武 二','柳宗元','quantangshi','','卷19','皇咨于度，惟汝一德。
旷诛四纪，其徯汝克。
锡汝斧钺，其往视师。
师是蔡人，以宥以厘。','',''),('quantangshi-18550','皇武 三','柳宗元','quantangshi','','卷19','度拜稽首，庙于元龟。
既禡既类，于社是宜。
金节煌煌，锡盾雕戈。
犀甲熊旗，威命是荷。','',''),('quantangshi-18551','皇武 四','柳宗元','quantangshi','','卷19','度拜稽首，出次于东。
天子饯之，罍斝是崇。
鼎臑俎胾，五献百笾。
凡百卿士，班以周旋。','',''),('quantangshi-18552','皇武 五','柳宗元','quantangshi','','卷19','既涉于浐，乃翼乃前。
孰图厥犹，其佐多贤。
宛宛周道，于山于川。
远扬迩昭，陟降连连。','',''),('quantangshi-18553','皇武 六','柳宗元','quantangshi','','卷19','我斾我旗，于道于陌。
训于羣帅，拳勇来格。
公曰徐之，无恃頟頟。
式和尔容，惟义之宅。','',''),('quantangshi-18554','皇武 七','柳宗元','quantangshi','','卷19','进次于郾，彼昏卒狂。
裒凶鞠顽，锋猬斧螗。
赤子匍匐，厥父是亢。
怒其萌芽，以悖太阳。','',''),('quantangshi-18555','皇武 八','柳宗元','quantangshi','','卷19','王旅浑浑，是佚是怙。
既获敌师，若饥得哺。
蔡凶伊窘，悉起来聚。
左捣其虚，靡愆厥虑。','',''),('quantangshi-18556','皇武 九','柳宗元','quantangshi','','卷19','载辟载袚，丞相是临。
弛其武刑，谕我德心。
其危既安，有长如林。
曾是讙譊，化为讴吟。','',''),('quantangshi-18557','皇武 十','柳宗元','quantangshi','','卷19','皇曰来归，汝复相予。
爵之成国，胙以夏区。
度拜稽首，天子圣神。
度拜稽首，皇佑下人。','',''),('quantangshi-18558','皇武 十一','柳宗元','quantangshi','','卷19','淮夷既平，震是朔南。
宜庙宜郊，以告德音。
归牛休马，丰稼于野。
我武惟皇，永保无疆。','',''),('quantangshi-18559','方城 一','柳宗元','quantangshi','','卷19','方城临临，王卒峙之。
匪徼匪竞，皇有正命。
皇命于愬，往舒余仁。
踣彼艰顽，柔惠是驯。','',''),('quantangshi-18560','方城 二','柳宗元','quantangshi','','卷19','愬拜即命，于皇之训。
既砺既攻，以后厥刃。
王师嶷嶷，熊罴是式。
衔勇韬力，日思予殛。','',''),('quantangshi-18561','方城 三','柳宗元','quantangshi','','卷19','寇昏以狂，敢蹈愬疆。
士获厥心，大袒高骧。
长戟酋矛，粲其绥章。
右翦左屠，聿禽其良。','',''),('quantangshi-18562','方城 四','柳宗元','quantangshi','','卷19','其良既宥，告以父母。
恩柔于肌，卒贡尔有。
维彼攸恃，乃侦乃诱维彼攸宅，乃发乃守。','',''),('quantangshi-18563','方城 五','柳宗元','quantangshi','','卷19','其恃爰获，我功我多。
阴谍厥图，以究尔讹。
雨雪洋洋，大风来加。
于燠其寒，于迩其遐。','',''),('quantangshi-18564','方城 六','柳宗元','quantangshi','','卷19','汝阴之茫，悬瓠之峨。
是震是拔，大歼厥家。
狡虏既縻，输于国都。
示之市人，即社行诛。','',''),('quantangshi-18565','方城 七','柳宗元','quantangshi','','卷19','乃谕乃止，蔡有厚喜。
完其室家，仰父俯子。
汝水沄沄，既清而弥。
蔡人行歌，我步逶迟。','',''),('quantangshi-18566','方城 八','柳宗元','quantangshi','','卷19','蔡人歌矣，蔡风和矣。
孰颣蔡初，胡甈尔居。
式慕以康，为愿有余。
是究是咨，皇德既舒。','',''),('quantangshi-18567','方城 九','柳宗元','quantangshi','','卷19','皇曰咨愬，裕乃父功。
昔我文祖，惟西平是庸。
内诲于家，外刑于邦。
孰是蔡人，而不率从。','',''),('quantangshi-18568','方城 十','柳宗元','quantangshi','','卷19','蔡人率止，惟西平有子。
西平有子，惟我有臣。
畴允大邦，俾惠我人。
于庙告功，以顾万方。','',''),('quantangshi-18569','唐铙歌妓吹曲十二篇','柳宗元','quantangshi','','卷19','晋阳武，奋义威。
炀之渝，德焉归。
氓毕屠，绥者谁。
皇烈烈，专天机。
号以仁，扬其旗。
日之升，九土曦。
斥田坼，流洪辉。
有其二，翼余隋。
斮枭鷔，连熊螭。
枯以肉，勍者羸。
后土荡，玄穹弥。
合之育，莾然施。
惟德辅，庆无期。','',''),('quantangshi-18570','唐铙歌妓吹曲十二篇','柳宗元','quantangshi','','卷19','兽之穷，奔大麓。
天厚黄德，狙犷服。
甲之櫜，弓弭矢箙。
皇旅靖，敌逾蹙。
自亡其徒，匪予戮。
屈𧸾猛，虔栗栗。
縻以尺组，噉以秩。
黎之阳，土茫茫。
富兵戎，盈仓箱。
乏者德，莫能享。
驱豺兕，授我疆。','',''),('quantangshi-18571','唐铙歌妓吹曲十二篇','柳宗元','quantangshi','','卷19','战武牢，动河朔。
逆之助，图掎角。
怒鷇麛，抗乔岳。
翘萌牙，傲霜雹。
王谋内定，申掌握。
铺施芟夷，二主缚。
惮华戎，廓封略。
命之瞢，卑以斮。
归有德，唯先觉。','',''),('quantangshi-18572','唐铙歌妓吹曲十二篇','柳宗元','quantangshi','','卷19','泾水黄，陇野茫。
负太白，腾天狼。
有鸟鸷立，羽翼张。
鈎喙决前，钜趯傍。
怒飞饥啸，翾不可当。
老雄死，子复良。
巢岐饮渭，肆翱翔。
顿地纮，提天纲。
列缺掉帜，招摇耀铓。
鬼神来助，梦嘉祥。
脑涂原野，魄飞扬。
星辰复，恢一方。','',''),('quantangshi-18573','唐铙歌妓吹曲十二篇','柳宗元','quantangshi','','卷19','奔鲸沛，荡海垠。
吐霓翳日，腥浮云。
帝怒下顾，哀垫昏。
授以神柄，推元臣。
手援天矛，截修鳞。
披攘蒙霿，开海门。
地平水静，浮天根。
羲和显耀，乘清氛。
赫炎溥畅，融大钧。','',''),('quantangshi-18574','唐铙歌妓吹曲十二篇','柳宗元','quantangshi','','卷19','苞枿𪒶矣，惟根之蟠。
弥巴蔽荆，负南极以安。
[冃]我旧梁氏，缉绥艰难。
江汉之阻，都邑固以完。
圣人作，神武用。
有臣勇智，奋不以众。
投迹死地，谋猷纵。
化敌为家，虑则中。
浩浩海裔，不威而同。
系缧降王，定厥功。
澶漫万里，宣唐风。
蛮夷九译，咸来从。
凯旋金奏，象形容。
震赫万国，罔不龚。','',''),('quantangshi-18575','唐铙歌妓吹曲十二篇','柳宗元','quantangshi','','卷19','河右澶漫，顽为之魁。
王师如雷震，昆仑以颓。
上聋下聪，骜不可廻。
助雠抗有德，惟人之灾。
乃溃乃奋，执缚归厥命。
万室蒙其仁，一夫则病。
濡以鸿泽，皇之圣。
威畏德怀，功以定。
顺之于理，物咸遂厥性。','',''),('quantangshi-18576','唐铙歌妓吹曲十二篇','柳宗元','quantangshi','','卷19','铁山碎，大漠舒。
二虏劲，连穹庐。
背北海，专坤隅。
岁来侵边，或傅于都。
天子命元帅，奋其雄图。
破定襄，降魁渠。
穷竟窟宅，斥余吾。
百蛮破胆，边氓苏。
威武辉耀，明鬼区。
利泽弥万祀，功不可逾。
官臣拜手，惟帝之暮。','',''),('quantangshi-18577','唐铙歌妓吹曲十二篇','柳宗元','quantangshi','','卷19','本邦伊晋，惟时不靖。
根柢之摇，枯叶攸病。
守臣不任，勚于神圣。
惟越之兴，翦焉则定。
洪惟我理，式和以敬。
羣顽既夷，庶绩咸正。
皇謩载大，惟人之庆。','',''),('quantangshi-18578','唐铙歌妓吹曲十二篇','柳宗元','quantangshi','','卷19','吐谷浑盛彊，背西海以夸。
岁侵扰我疆，退匿险且遐。
帝谓神武师。
往征靖皇家。
烈烈斾其旗，熊虎杂龙蛇。
王旅千万人，衔枚默无哗。
束刃逾山徼，张翼纵漠沙。
一举刈膻腥，尸骸积如麻。
除恶务本根，况敢遗萌芽。
洋洋西海水，威命穷天涯。
系虏来王都，犒乐穷休嘉。
登高望还师，竟野如春华。
行者靡不归，亲戚劝要遮。
凯旋献清庙，万国思无邪。','',''),('quantangshi-18579','唐铙歌妓吹曲十二篇','柳宗元','quantangshi','','卷19','麴氏雄西北，别绝臣外区。
既恃远且险，纵傲不我虞。
烈烈王者师，熊螭以为徒。
龙旗翻海浪，馹骑驰坤隅。
贲育搏婴儿，一扫不复余。
平沙际天极，但见黄云驱。
臣靖执长缨，智勇伏囚拘。
文皇南面坐，夷狄千羣趋。
咸称天子神，往古不得俱。
献号天可汗，以覆我国都。
兵戎不交害，各保性与躯。','',''),('quantangshi-18580','唐铙歌妓吹曲十二篇','柳宗元','quantangshi','','卷19','东蛮有谢氏，冠带理海中。
自言我异世，虽圣莫能通。
王卒如飞翰，鹏骞骇羣龙。
轰然自天坠，乃信神武功。
系虏君臣人，累累来自东。
无思不服从，唐业如山崇。
百辟拜稽首，咸愿图形容。
如周王会书，永永传无穷。
睢盱万状乖，咿嗢九译重。
广轮抚四海，浩浩知皇风。
歌诗铙鼓闲，以壮我元戎。','',''),('quantangshi-18581','贞符','柳宗元','quantangshi','','卷19','于穆敬德，黎人皇之。
惟贞厥符，浩浩将之。
仁函于肤，刃莫毕屠。
泽熯于爨，𩰾炎以澣。
殄厥凶德，乃敺乃夷。
懿其休风，是喣是吹。
父子熙熙，相宁以嬉。
赋彻而藏，厚我糗粻。
刑轻以清，我肌靡伤。
贻我子孙，百代是康。
十圣嗣于理，仁后之子。
子思孝父，易患于已。
拱之戴之，神具尔宜。
载扬于雅，承天之嘏。
天之诚神，宜鉴于仁。
神之曷依，宜仁之归。
濮沿于北，祝栗于南。
幅员西东，祗一乃心。
祝唐之纪，后天罔坠。
祝皇之寿，与地咸久。
曷徒祝之，心诚笃之。
神协人同，道以告之。
俾弥亿万年，不震不危。
我代之延，永永毗之。
仁增以崇，曷不尔思。
有号于天，佥曰呜呼。
咨尔皇灵，无替厥符。','',''),('quantangshi-18582','眎民诗','柳宗元','quantangshi','','卷19','帝眎民情，匪幽匪明。
惨或在腹，已如色声。
亦无动威，亦无止力。
弗动弗止，惟民之极。
帝怀民眎，乃降明德。
乃生明翼，明翼者何。
乃房乃杜，惟房与杜。
实为民路，乃定天子。
乃开万国，万国既分。
乃释蠹民，乃学与仕。
乃播与食，乃器与用。
乃货与通，有作有迁。
无迁无作，士实荡荡。
农实董董，工实蒙蒙。
贾实融融，左右惟一。
出入惟同，摄仪以引。
以遵以肆，其风既流。
品物载休，惟天子守。
乃二公之久，惟天子明。
乃二公之成，惟百辟正。
乃二公之令，惟百辟谷。
乃二公之禄，二公行矣。
弗敢忧纵，是获忧共。
二公居矣，弗敢泰止。
是获泰已，既柔一德。
四夷是则，四夷是则，永怀不忒。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-18583','同刘二十八院长述旧言怀感时书事奉寄澧州张员外使君五十二韵之作因其韵增至八十通赠二君子','柳宗元','quantangshi','','卷19','弱岁游玄圃，先容幸弃瑕。
名劳长者记，文许后生夸。
鷃翼尝披隼，蓬心类倚麻。
继酬天禄署，俱尉甸侯家。
宪府初收迹，丹墀共拜嘉。
分行参瑞兽，传点乱宫鸦。
执简宁循枉，持书每去邪。
鸾凤标魏阙，熊武负崇牙。
辨色宜相顾，倾心自不哗。
金炉仄流月，紫殿启晨赮。
未竟迁乔乐，俄成失路嗟。
还如渡辽水，更似谪长沙。
别怨秦城暮，途穷越岭斜。
讼庭闲枳棘，候吏逐麋䴥。
三载皇恩畅，千年圣历遐。
朝宗延驾海，师役罢梁溠。
京邑搜贞干，南宫步渥洼。
世惟材是梓，人仰骥中骅。
歘刺苗人地，仍逾赣石崖。
礼容垂珌琫，戍备响錏鍜。
宠即郎官旧，威从太守加。
建旟翻鸷鸟，负弩绕文蛇。
册府荣八命，中闱盛六珈。
肯随胡质矫，方恶马融奢。
褒德符新换，怀仁道并遮。
俗嫌龙节晚，朝讶介圭赊。
禹贡输苞匦，周官赋秉秅。
雄风吞七泽，异产控三巴。
即事观农稼，因时展物华。
秋原被兰叶，春渚涨桃花。
令肃军无扰，程悬市禁贳。
不应虞竭泽，宁复叹栖苴。
蹀躞驺先驾，笼铜鼓报衙。
染毫东国素，濡印锦溪砂。
货积舟难泊，人归山倍畲。
吴歈工折柳，楚舞旧传芭。
隐几松为曲，倾罇石作污。
寒初荣橘柚，夏首荐枇杷。
祀变荆巫祷，风移鲁妇髽。
已闻施恺悌，还覩正奇衺。
慕友惭连璧，言姻喜附葭。
沈埋全死地，流落半生涯。
入郡腰恒折，逢人手尽叉。
敢辞亲耻污，唯恐长疵瘕。
善幻迷冰火，齐谐笑柏涂。
东门牛屡饭，中散虱空爬。
逸戏看猿鬬，殊音辨马挝。
渚行狐作孽，林宿鸟为𣩈。
同病忧能老，新声厉似姱。
岂知千仞坠，秖为一毫差。
守道甘长绝，明心欲自𠜲。
贮愁听夜雨，隔泪数残葩。
枭族音常聒，豺羣喙竞呀。
岸芦翻毒蜃，磎竹鬬狂{广/秝/牛}。
野鹜行看弋，江鱼或共扠。
瘴氛恒积润，讹火亟生煆。
耳静烦喧蚁，魂惊怯怒蛙。
风枝散陈叶，霜蔓綖寒瓜。
雾密前山桂，冰枯曲沼蕸。
思乡比庄舄，遯世遇眭夸。
渔舍茨荒草，村桥卧古槎。
御寒衾用罽，挹水勺仍椰。
窗蠹惟潜蝎，甍涎竞缀蜗。
引泉开故窦，护药插新笆。
树怪花因槲，虫怜目待虾。
骤歌喉易嗄，饶醉鼻成皻。
曳捶牵羸马，垂蓑牧艾豭。
已看能类鼈，犹讶雉为鷨。
谁采中原菽，徒巾下泽车。
俚儿供苦笋，伧父馈酸樝。
劝策扶危杖，邀持当酒茶。
道流征短褐，禅客会袈裟。
香饭舂菰米，珍蔬折五茄。
方期饮甘露，更欲吸流霞。
屋鼠从穿兀，林狙任攫拏。
春衫裁白紵，朝帽挂乌纱。
屡叹恢恢网，频摇肃肃罝。
衰荣因蓂荚，盈缺几虾蟇。
路识沟边柳，城闻陇上笳。
共思捐佩处，千骑拥青緺。','',''),('quantangshi-18584','弘农公以硕德伟材屈于诬枉左官三岁复为大僚天监昭明人心感悦宗元窜伏湘浦拜贺末由谨献诗五十韵以毕微志','柳宗元','quantangshi','','卷19','知命儒为贵，时中圣所臧。
处心齐宠辱，遇物任行藏。
关识新安地，封传临晋乡。
挺生推豹蔚，遐步仰龙骧。
干有千寻竦，精闻百炼钢。
茂功期舜禹，高韵状羲黄。
足逸诗书囿，锋摇翰墨场。
雅歌张仲德，颂祝鲁侯昌。
宪府初腾价，神州转耀铓。
右言盈简策，左辖备条纲。
响切晨趋佩，烟浓近侍香。
司仪六礼洽，论将七兵扬。
合乐来仪凤，尊祠重饩羊。
卿材优柱石，公器擅岩廊。
峻节临衡峤，和风满豫章。
人归父母育，郡得股肱良。
细故谁留念，烦言肯过防。
璧非真盗客，金有误持郎。
龟虎休前寄，貂蝉冠旧行。
训刑方命吕，理剧复推张。
直用明销恶，还将道胜刚。
敬逾齐国社，恩比召南棠。
希怨犹逢怒，多容竞忤彊。
火炎侵琬琰，鹰击谬鸾凰。
刻木终难对，焚芝未改芳。
远迁逾桂岭，中徙滞余杭。
顾土虽怀赵，知天讵畏匡。
论嫌齐物诞，骚爱远游伤。
丽泽周羣品，重明照万方。
斗间收紫气，台上挂清光。
福为深仁集，妖从盛德禳。
秦民啼畎亩，周士舞康庄。
采绶还垂艾，华簪更截肪。
高居迁鼎邑，遥傅好书王。
碧树环金谷，丹霞映上阳。
留欢唱容与，要醉对清凉。
故友仍同里，常僚每合堂。
渊龙过许劭，冰鲤吊王祥。
玉漏天门静，铜驼御路荒。
涧瀍秋潋灧，嵩少暮微茫。
遵渚徒云乐，冲天自不遑。
降神终入辅，种德会明敭。
独弃伧人国，难窥夫子墙。
通家殊孔李，旧好即潘杨。
世议排张挚，时情弃仲翔。
不言缧绁枉，徒恨纆徽长。
贾赋愁单阏，邹书怯大梁。
炯心那自是，鸣玉机全息，怀沙事不忘。
恋恩何敢死，垂泪对清湘。','',''),('quantangshi-18585','酬韶州裴曹长使君寄道州吕八大使以见示二十韵一首','柳宗元','quantangshi','','卷19','金马尝齐入，铜鱼亦共颁。
疑山看积翠，浈水想澄湾。
标牓同惊俗，清明两照奸。
乘轺参孔仅，按节服侯狦。
贾傅辞宁切，虞童髪未䰔。
秉心方的的，腾口任㘖㘖。
圣理高悬象，爰书降罚锾。
德风流海外，和气满人寰。
御魅恩犹贷，思贤泪自潸。
在亡均寂寞，零落间惸鳏。
夙志随忧尽，残肌触瘴𤸷。
月光摇浅濑，风韵碎枯菅。
海俗衣犹卉，山夷髻不鬟。
泥沙潜虺蜮，榛莽鬬豺獌。
循省诚知惧，安排秖自𢢀。
食贫甘莽卤，被褐谢斓斒。
远物裁青罽，时珍馔白鹇。
长捐楚客佩，未赐大夫环。
异政徒云仰，高踪不可攀。
空劳慰顦顇，妍唱剧妖㛠。','',''),('quantangshi-18586','酬娄秀才将之淮南见赠之什','柳宗元','quantangshi','','卷19','远弃甘幽独，谁云值故人。
好音怜铩羽，濡沫慰穷鳞。
困志情惟旧，相知乐更新。
浪游轻费日，醉舞讵伤春。
风月欢宁间，星霜分益亲。
已将名是患，还用道为邻。
机事齐飘瓦，嫌猜比拾尘。
高冠余肯赋，长铗子忘贫。
晼晚惊移律，睽携忽此辰。
开颜时不再，绊足去何因。
海上销魂别，天边吊影身。
秖应西涧水，寂寞但垂纶。','',''),('quantangshi-18587','酬娄秀才寓居开元寺早秋月夜病中见寄','柳宗元','quantangshi','','卷19','客有故园思，潇湘生夜愁。
病依居士室，梦绕羽人丘。
味道怜知止，遗名得自求。
壁空残月曙，门掩候虫秋。
谬委双金重，难征杂佩酬。
碧霄无枉路，徒此助离忧。','',''),('quantangshi-18588','初秋夜坐赠吴武陵','柳宗元','quantangshi','','卷19','稍稍雨侵竹，翻翻鹊惊丛。
美人隔湘浦，一夕生秋风。
积雾杳难极，沧波浩无穷。
相思岂云远，即席莫与同。
若人抱奇音，朱弦緪枯桐。
清商激西颢，泛灧凌长空。
自得本无作，天成谅非功。
希声閟大朴，聋俗何由聪。','',''),('quantangshi-18589','晨诣超师院读禅经','柳宗元','quantangshi','','卷19','汲井漱寒齿，清心拂尘服。
闲持贝叶书，步出东斋读。
真源了无取，妄迹世所逐。
遗言冀可冥，缮性何由熟。
道人庭宇静，苔色连深竹。
日出雾露余，青松如膏沐。
澹然离言说，悟悦心自足。','',''),('quantangshi-18590','赠江华长老','柳宗元','quantangshi','','卷19','老僧道机熟，默语心皆寂。
去岁别舂陵，沿流此投迹。
室空无侍者，巾履唯挂壁。
一饭不愿余，跏趺便终夕。
风牕疎竹响，露井寒松滴。
偶地即安居，满庭芳草积。','',''),('quantangshi-18591','巽上人以竹闲自采新茶见赠酬之以诗','柳宗元','quantangshi','','卷19','芳丛翳湘竹，零露凝清华。
复此雪山客，晨朝掇灵芽。
蒸烟俯石濑，咫尺凌丹崖。
圆方丽奇色，圭璧无纤瑕。
呼儿爨金鼎，余馥延幽遐。
涤虑发真照，还源荡昏邪。
犹同甘露饭，佛事薰毗耶。
咄此蓬瀛侣，无乃贵流霞。','',''),('quantangshi-18592','零陵赠李卿元侍御简吴武陵','柳宗元','quantangshi','','卷19','理世固轻士，弃捐湘之湄。
阳光竞四溟，敲石安所施。
铩羽集枯干，低昂互鸣悲。
朔云吐风寒，寂历穷秋时。
君子尚容与，小人守兢危。
惨凄日相视，离忧坐自滋。
尊酒聊可酌，放歌谅徒为。
惜无协律者，窈眇弦吾诗。','',''),('quantangshi-18593','界围岩水帘','柳宗元','quantangshi','','卷19','界围汇湘曲，青壁环澄流。
悬泉粲成帘，罗注无时休。
韵磬叩凝碧，锵锵彻岩幽。
丹霞冠其巅，想像凌虚游。
灵境不可状，鬼工谅难求。
忽如朝玉皇，天冕垂前旒。
楚臣昔南逐，有意仍丹丘。
今我始北旋，新诏释缧囚。
采真诚眷恋，许国无淹留。
再来寄幽梦，遗贮催行舟。','',''),('quantangshi-18594','古东门行','柳宗元','quantangshi','','卷19','汉家三十六将军，东方雷动横阵云。
鸡鸣函谷客如雾，貌同心异不可数。
赤丸夜语飞电光，徼巡司隶眠如羊。
当街一叱百吏走，冯敬胷中函匕首。
凶徒侧耳潜惬心，悍臣破胆皆杜口。
魏王卧内藏兵符，子西掩袂真无辜。
羗胡毂下一朝起，敌国舟中非所拟。
安陵谁辨削砺功，韩国讵明深井里。
绝胭断骨那下补，万金宠赠不如土。','',''),('quantangshi-18595','寄韦珩','柳宗元','quantangshi','','卷19','初拜柳州出东郊，道旁相送皆贤豪。
廻眸炫晃别羣玉，独赴异域穿蓬蒿。
炎烟六月咽口鼻，胷鸣肩举不可逃。
桂州西南又千里，漓水鬬石麻兰高。
阴森野葛交蔽日，悬蛇结虺如蒲萄。
到官数宿贼满野，缚壮杀老啼且号。
饥行夜坐设方略，笼铜枹鼓手所操。
奇疮钉骨状如箭，鬼手脱命争纤毫。
今年噬毒得霍疾，支心搅腹戟与刀。
迩来气少筋骨露，苍白瀄汩盈颠毛。
君今矻矻又窜逐，辞赋已复穷诗骚。
神兵庙略频破虏，四溟不日清风涛。
圣恩倘忽念行苇，十年践蹈久已劳。
幸因解网入鸟兽，毕命江海终游遨。
愿言未果身益老，起望东北心滔滔。','',''),('quantangshi-18596','奉和杨尚书郴州追和故李中书夏日登北楼十韵之作依本诗韵次用','柳宗元','quantangshi','','卷19','郡楼有遗唱，新和敌南金。
境以道情得，人期幽梦寻。
层轩隔炎暑，迥野恣窥临。
凤去徽音续，芝焚芳意深。
游鳞出陷浦，唳鹤绕仙岑。
风起三湘浪，云生万里阴。
宏规齐德宇，丽藻竞词林。
静契分忧术，闲同迟客心。
骅骝当远步，鶗鴂莫相侵。
今日登高处，还闻梁父吟。','',''),('quantangshi-18597','杨尚书寄郴笔知是小生本样令更商榷使尽其功輙献长句','柳宗元','quantangshi','','卷19','截玉銛锥作妙形，贮云含雾到南溟。
尚书旧用裁天诏，内史新将写道经。
曲艺岂能裨损益，微辞秖欲播芳馨。
桂阳卿月光辉徧，毫末应传顾兔灵。','',''),('quantangshi-18598','南省转牒欲具江国图令尽通风俗故事','柳宗元','quantangshi','','卷19','圣代提封尽海壖，狼荒犹得纪山川。
华夷图上应初录，风土记中殊未传。
椎髻老人难借问，黄茆深峒敢留连。
南宫有意求遗俗，试检周书王会篇。','',''),('quantangshi-18599','与浩初上人同看山寄京华亲故','柳宗元','quantangshi','','卷19','海畔尖山似劒铓，秋来处处割愁肠。
若为化得身千亿，散上峰头望故乡。','',''),('quantangshi-18600','再至界围岩水帘遂宿岩下','柳宗元','quantangshi','','卷19','发春念长违，中夏欣再覩。
是时植物秀，杳若临悬圃。
歊阳讶垂冰，白日惊雷雨。
笙簧潭际起，鹳鹤云间舞。
古苔凝青枝，阴草湿翠羽。
蔽空素彩列，激浪寒光聚。
的皪沈珠渊，锵鸣捐佩浦。
幽岩画屏倚，新月玉鈎吐。
夜凉星满川，忽疑眠洞府。','',''),('quantangshi-18601','诏追赴都廻寄零陵亲故','柳宗元','quantangshi','','卷19','每忆纤鳞游尺泽，翻愁弱羽上丹霄。
岸傍古堠应无数，次第行看别路遥。','',''),('quantangshi-18602','过衡山见新花开却寄弟','柳宗元','quantangshi','','卷19','故国名园久别离，今朝楚树发南枝。
晴天归路好相逐，正是峰前廻雁时。','',''),('quantangshi-18603','汨罗遇风','柳宗元','quantangshi','','卷19','南来不作楚臣悲，重入修门自有期。
为报春风汨罗道，莫将波浪枉明时。','',''),('quantangshi-18604','朗州窦常员外寄刘二十八诗见促行骑走笔酬赠','柳宗元','quantangshi','','卷19','投荒垂一纪，新诏下荆扉。
疑比庄周梦，情如苏武归。
赐环留逸响，五马助征騑。
不羡衡阳雁，春来前后飞。','',''),('quantangshi-18605','离觞不醉至驿却寄相送诸公','柳宗元','quantangshi','','卷19','无限居人送独醒，可怜寂寞到长亭。
荆州不遇高阳侣，一夜春寒满下厅。','',''),('quantangshi-18606','北还登汉阳北原题临川驿','柳宗元','quantangshi','','卷19','驱车方向阙，廻首一临川。
多垒非余耻，无谋终自怜。
乱松知野寺，余雪记山田。
惆怅樵渔事，今还又落然。','',''),('quantangshi-18607','善谑驿和刘梦得酹淳于先生','柳宗元','quantangshi','','卷19','水上鹄已去，亭中鸟又鸣。
辞因使楚重，名为救齐成。
荒壠遽千古，羽觞难再倾。
刘伶今日意，异代是同声。','',''),('quantangshi-18608','诏追赴都二月至灞亭上','柳宗元','quantangshi','','卷19','十一年前南渡客，四千里外北归人。
诏书许逐阳和至，驿路开花处处新。','',''),('quantangshi-18609','李西川荐琴石','柳宗元','quantangshi','','卷19','远师驺忌鼓鸣琴，去和南风惬舜心。
从此他山千古重，殷勤曾是奉徽音。','',''),('quantangshi-18610','同刘二十八哭吕衡州兼寄江陵李元二侍御','柳宗元','quantangshi','','卷19','衡岳新摧天柱峰，士林顦顇泣相逢。
祗令文字传青简，不使功名上景钟。
三亩空留悬磬室，九原犹寄若堂封。
遥想荆州人物论，几回中夜惜元龙。','',''),('quantangshi-18611','奉酬杨侍郎丈因送八叔拾遗戏赠诏追南来诸宾二首 一','柳宗元','quantangshi','','卷19','贞一来时送彩牋，一行归雁慰惊弦。
翰林寂寞谁为主，鸣凤应须早上天。','',''),('quantangshi-18612','奉酬杨侍郎丈因送八叔拾遗戏赠诏追南来诸宾二首 二','柳宗元','quantangshi','','卷19','一生判却归休，谓着南冠到头。
冶长虽解缧絏，无由得见东周。','',''),('quantangshi-18613','商山临路有孤松往来斫以为明好事者怜之编竹成楥遂其生植感而赋诗','柳宗元','quantangshi','','卷19','孤松停翠盖，托根临广路。
不以险自防，遂为明所误。
幸逢仁惠意，重此藩篱护。
犹有半心存，时将承雨露。','',''),('quantangshi-18614','衡阳与梦得分路赠别','柳宗元','quantangshi','','卷19','十年顦顇到秦京，谁料翻为岭外行。
伏波故道风烟在，翁仲遗墟草树平。
直以慵疎招物议，休将文字占时名。
今朝不用临河别，垂泪千行便濯缨。','',''),('quantangshi-18615','重别梦得','柳宗元','quantangshi','','卷19','二十年来万事同，今朝岐路忽西东。
皇恩若许归田去，晚岁当为邻舍翁。','',''),('quantangshi-18616','三赠刘员外','柳宗元','quantangshi','','卷19','信书成自误，经事渐知非。
今日临岐别，何年待汝归。','',''),('quantangshi-18617','再上湘江','柳宗元','quantangshi','','卷19','好在湘江水，今朝又上来。
不知从此去，更遣几年回。','',''),('quantangshi-18618','清水驿丛竹天水赵云余手种一十二茎','柳宗元','quantangshi','','卷19','檐下疎篁十二茎，襄阳从事寄幽情。
祗应更指伶伦见，写尽雌雄双凤鸣。','',''),('quantangshi-18619','长沙驿前南楼感旧','柳宗元','quantangshi','','卷19','海鹤一为别，存亡三十秋。
今来数行泪，独上驿南楼。','',''),('quantangshi-18620','桂州北望秦驿手开竹径至钓矶留待徐容州','柳宗元','quantangshi','','卷19','幽径为谁开，美人城北来。
王程倘余暇，一上子陵台。','',''),('quantangshi-18621','登柳州城楼寄漳汀封连四州','柳宗元','quantangshi','','卷19','城上高楼接大荒，海天愁思正茫茫。
惊风乱颭芙蓉水，密雨斜侵薜荔墙。
岭树重遮千里目，江流曲似九廻肠。
共来百越文身地，犹自音书滞一乡。','',''),('quantangshi-18622','柳州寄丈人周韶州','柳宗元','quantangshi','','卷19','越绝孤城千万峰，空斋不语坐高舂。
印文生绿经旬合，砚匣留尘尽日封。
梅岭寒烟藏翡翠，桂江秋水露鰅鳙。
丈人本自忘机事，为想年来憔悴容。','',''),('quantangshi-18623','登柳州峨山','柳宗元','quantangshi','','卷19','荒山秋日午，独上意悠悠。
如何望乡处，西北是融州。','',''),('quantangshi-18624','得卢衡州书因以诗寄','柳宗元','quantangshi','','卷19','临蒸且莫叹炎方，为报秋来雁几行。
林邑东廻山似戟，牂牁南下水如汤。
蒹葭浙沥含秋雾，橘柚玲珑透夕阳。
非是白苹洲畔客，还将远意问潇湘。','',''),('quantangshi-18625','答刘连州邦字','柳宗元','quantangshi','','卷19','连璧本难双，分符刺小邦。
崩云下漓水，劈箭上浔江。
负弩啼寒狖，鸣枹惊夜狵。
遥怜郡山好，谢守但临窗。','',''),('quantangshi-18626','岭南江行','柳宗元','quantangshi','','卷19','瘴江南去入云烟，望尽黄茆是海边。
山腹雨晴添象迹，潭心日暖长蛟涎。
射工巧伺游人影，飓母偏惊旅客船。
从此忧来非一事，岂容华髪待流年。','',''),('quantangshi-18627','柳州峒氓','柳宗元','quantangshi','','卷19','郡城南下接通津，异服殊音不可亲。
青箬裹盐归峒客，绿荷包饭趂虚人。
鹅毛御腊缝山罽，鸡骨占年拜水神。
愁向公庭问重译，欲投章甫作文身。','',''),('quantangshi-18628','酬徐二中丞普宁郡内池馆即事见寄','柳宗元','quantangshi','','卷19','鵷鸿念旧行，虚馆对芳塘。
落日明朱槛，繁花照羽觞。
泉归沧海近，树入楚山长。
荣贱俱为累，相期在故乡。','',''),('quantangshi-18629','酬贾鹏山人郡内新栽松寓兴见赠二首 一','柳宗元','quantangshi','','卷19','芳巧自为别，无心乃玄功。
夭夭日放花，荣耀将安穷。
青松遗涧底，擢莳兹庭中。
积雪表明秀，寒花助葱茏。
贞幽夙有慕，持以延清风。','',''),('quantangshi-18630','酬贾鹏山人郡内新栽松寓兴见赠二首 二','柳宗元','quantangshi','','卷19','无能常闭阁，偶以静见名。
奇姿来远山，忽似人家生。
劲色不改旧，芳心与谁荣。
喧卑岂所安，任物非我情。
清韵动竽瑟，谐此风中声。','',''),('quantangshi-18631','种柳戏题','柳宗元','quantangshi','','卷19','柳州柳刺史，种柳柳江边。
谈笑为故事，推移成昔年。
垂阴当覆地，耸干会参天。
好作思人树，惭无惠化传。','',''),('quantangshi-18632','柳州二月榕叶落尽偶题','柳宗元','quantangshi','','卷19','宦情羁思共凄凄，春半如秋意转迷。
山城过雨百花尽，榕叶满庭莺乱啼。','',''),('quantangshi-18633','浩初上人见贻绝句欲登仙人山因以酬之','柳宗元','quantangshi','','卷19','珠树玲珑隔翠微，病来方外事多违。
仙山不属分符客，一任凌空锡杖飞。','',''),('quantangshi-18634','雨中赠仙人山贾山人','柳宗元','quantangshi','','卷19','寒江夜雨声潺潺，晓云遮尽仙人山。
遥知玄豹在深处，下笑羁绊泥涂间。','',''),('quantangshi-18635','别舍弟宗一','柳宗元','quantangshi','','卷19','零落残红倍黯然，双垂别泪越江边。
一身去国六千里，万死投荒十二年。
桂岭瘴来云似墨，洞庭春尽水如天。
欲知此后相思梦，长在荆门郢树烟。','',''),('quantangshi-18636','奉和周二十丈酬郴州侍郎衡江夜泊得韶州书并附当州生黄茶一封率然成篇代意之作','柳宗元','quantangshi','','卷19','丘山仰德耀，天路下征騑。
梦喜三刀近，书嫌五载违。
凝情江月落，属思岭云飞。
会入司徒府，还邀周掾归。','',''),('quantangshi-18637','殷贤戏批书后寄刘连州并示孟仑二童','柳宗元','quantangshi','','卷19','书成欲寄庾安西，纸背应劳手自题。
闻到尽来诸子弟，临池寻已厌家鸡。','',''),('quantangshi-18638','重赠二首 一','柳宗元','quantangshi','','卷19','闻道将雏向墨池，刘家还有异同词。
如今试遣隈墙问，已道世人那得知。','',''),('quantangshi-18639','重赠二首 二','柳宗元','quantangshi','','卷19','世上悠悠不识真，姜芽尽是捧心人。
若道柳家无子弟，往年何事乞西宾。','',''),('quantangshi-18640','叠前','柳宗元','quantangshi','','卷19','小学新翻墨沼波，羡君琼树散枝柯。
左家弄玉唯娇女，空觉庭前鸟迹多。','',''),('quantangshi-18641','叠后','柳宗元','quantangshi','','卷19','事业无成耻艺成，南宫起草旧连名。
劝君火急添功用，趂取当时二妙声。','',''),('quantangshi-18642','铜鱼使赴都寄亲友','柳宗元','quantangshi','','卷19','行尽关山万里余，到时闾井是荒墟。
附庸唯有铜鱼使，此后无因寄远书。','',''),('quantangshi-18643','韩漳州书报彻上人亡因寄二绝 一','柳宗元','quantangshi','','卷19','早岁京华听越吟，闻君江海分逾深。
他时若写兰亭会，莫画高僧支道林。','',''),('quantangshi-18644','韩漳州书报彻上人亡因寄二绝 二','柳宗元','quantangshi','','卷19','频把琼书出袖中，独吟遗句立秋风。
桂江日夜流千里，挥泪何时到甬东。','',''),('quantangshi-18645','柳州城西北隅种柑树','柳宗元','quantangshi','','卷19','手种黄柑二百株，春来新叶徧城隅。
方同楚客怜皇树，不学荆州利木奴。
几岁开花闻喷雪，何人摘实见垂珠。
若教坐待成林日，滋味还堪养老夫。','',''),('quantangshi-18646','闻彻上人亡寄侍郎杨丈','柳宗元','quantangshi','','卷19','东越高僧还姓汤，几时琼佩触鸣璫。
空花一散不知处，谁采金英与侍郎。','',''),('quantangshi-18647','段九秀才处见亡友吕衡州书迹','柳宗元','quantangshi','','卷19','交侣平生意最亲，衡阳往事似分身。
袖中忽见三行字，拭泪相看是故人。','',''),('quantangshi-18648','柳州寄京中亲故','柳宗元','quantangshi','','卷19','林邑山连瘴海秋，牂牁水向郡前流。
劳君远问龙城地，正北三千到锦州。','',''),('quantangshi-18649','种木槲花','柳宗元','quantangshi','','卷19','上苑年年占物华，飘零今日在天涯。
祗因长作龙城守，剩种庭前木槲花。','',''),('quantangshi-18650','摘樱桃赠元居士时在望仙亭南楼与朱道士同处','柳宗元','quantangshi','','卷19','海上朱樱赠所思，楼居况是望仙时。
蓬莱羽客如相访，不是偷桃一小儿。','',''),('quantangshi-18651','酬曹侍御过象县见寄','柳宗元','quantangshi','','卷19','破额山前碧玉流，骚人遥驻木兰舟。
春风无限潇湘意，欲采苹花不自由。','',''),('quantangshi-18652','法华寺石门精舍三十韵','柳宗元','quantangshi','','卷19','拘情病幽郁，旷志寄高爽。
愿言怀名缁，东峰旦夕仰。
始欣云雨霁，尤悦草木长。
道同有爱弟，披拂恣心赏。
松溪𥦖窱入，石栈夤缘上。
萝葛绵层甍，莓苔侵标牓。
密林互对耸，绝壁俨双敞。
堑峭出蒙笼，墟险临滉漾。
稍疑地脉断，悠若天梯往。
结构罩羣崖，廻环驱万象。
小劫不逾瞬，大千若在掌。
体空得化元，观有遗细想。
喧烦困蠛蠓，局蹐疲魍魉。
寸进谅何营，寻直非所枉。
探奇极遥瞩，穷妙閟清响。
理会方在今，神开庶殊曩。
兹游苟不嗣，浩气竟谁养。
道异诚所希，名宾匪余仗。
超摅藉外奖，俯默有内朗。
鉴尔揖古风，终焉乃吾党。
潜躯委缰锁，高步谢尘坱。
蓄志徒为劳，追纵将焉仿。
淹留值颓暮，眷恋睇遐壤。
映日雁联轩，翻云波泱漭。
殊风纷已萃，乡路悠且广。
羁木畏漂浮，离旌倦摇荡。
昔人叹违志，出处今已两。
何用期所归，浮图有遗像。
幽蹊不盈尺，虚室有函丈。
微言信可传，申旦稽吾颡。','',''),('quantangshi-18653','游朝阳岩遂登西亭二十韵','柳宗元','quantangshi','','卷19','谪弃殊隐沦，登陟非远郊。
所怀缓伊郁，讵欲肩夷巢。
高岩瞰清江，幽窟潜神蛟。
开旷延阳景，廻薄攒林梢。
西亭构其巓，反字临呀庨。
背瞻星辰兴，下见云雨交。
惜非吾乡土，得以荫菁茆。
羁贯去江介，世仕尚函崤。
故墅即沣川，数亩均肥硗。
台馆葺荒丘，池塘疏沈坳。
会有圭组恋，遂贻山林嘲。
薄躯信无庸，琐屑剧斗筲。
囚居固其宜，厚羞久已包。
庭除植蓬艾，隟牖悬蟏蛸。
所赖山川客，扁舟枉长梢。
挹流敌清觞，掇野代嘉肴。
适道有高言，取乐非弦匏。
逍遥屏幽昧，淡薄辞喧呶。
晨鸡不余欺，风雨闻嘐嘐。
再期永日闲，提挈移中庖。','',''),('quantangshi-18654','湘口馆潇湘二水所会','柳宗元','quantangshi','','卷19','九疑浚倾奔，临源委萦廻。
会合属空旷，泓澄停风雷。
高馆轩霞表，危楼临山隈。
兹辰始澄霁，纤云尽褰开。
天秋日正中，水碧无尘埃。
杳杳渔父吟，呌呌羁鸿哀。
境胜岂不豫，虑分固难裁。
升高欲自舒，弥使远念来。
归流驶且广，泛舟绝沿洄。','',''),('quantangshi-18655','登蒲州石矶望横江口潭岛深逈斜对香零山','柳宗元','quantangshi','','卷19','隐忧倦永夜，凌雾临江津。
猿鸣稍已疎，登石娱清沦。
日出洲渚静，澄明皛无垠。
浮晖翻高禽，沈景照文鳞。
双江汇西奔，诡怪潜坤珍。
孤山乃北峙，森爽栖灵神。
洄潭或动容，岛屿疑摇振。
陶埴兹择土，蒲鱼相与邻。
信美非所安，羁心屡逡巡。
糺结良可解，纡郁亦已伸。
高歌返故室，自誷非所欣。','',''),('quantangshi-18656','南磵中题','柳宗元','quantangshi','','卷19','秋气集南磵，独游亭午时。
廻风一萧瑟，林影久参差。
始至若有得，稍深遂忘疲。
羁禽响幽谷，寒藻舞沦漪。
去国魂已远，怀人泪空垂。
孤生易为感，失路少所宜。
索寞竟何事，徘徊秖自知。
谁为后来者，当与此心期。','',''),('quantangshi-18657','游石角过小岭至长乌村','柳宗元','quantangshi','','卷19','志适不期贵，道存岂偷生。
久忘上封事，复笑升天行。
窜逐宦湘浦，摇心剧悬旌。
始惊陷世议，终欲逃天刑。
岁月杀忧栗，慵疎寡将迎。
追游疑所爱，且复舒吾情。
石角恣幽步，长乌遂遐征。
磴廻茂树断，景晏寒川明。
旷望少行人，时闻田鹳鸣。
风篁冒水远，霜稻侵山平。
稍与人事闲，益知身世轻。
为农信可乐，居宠真虚荣。
乔木余故国，愿言果丹诚。
四支反田亩，释至东臯耕。','',''),('quantangshi-18658','与崔策登西山','柳宗元','quantangshi','','卷19','鹤鸣楚山静，露白秋江晓。
连袂度危桥，萦廻出林杪。
西岑极远目，毫末皆可了。
重叠九疑高，微茫洞庭小。
逈穷两仪际，高出万象表。
驰景泛颓波，遥风递寒筱。
谪居安所习，稍厌从纷扰。
生同胥靡遗，寿比彭铿夭。
蹇连困颠踣，愚蒙怯幽眇。
非令亲爱疎，谁使心神悄。
偶兹遁山水，得以观鱼鸟。
吾子幸淹留，缓我愁肠绕。','',''),('quantangshi-18659','构法华寺西亭','柳宗元','quantangshi','','卷19','窜身楚南极，山水穷险艰。
步登最高寺，萧散任疎顽。
西垂下斗绝，欲似窥人寰。
反如在幽谷，榛翳不可攀。
命童恣披翦，葺宇横断山。
割如判清浊，飘若升云间。
远岫攒众顶，澄江抱清湾。
夕照临轩堕，栖鸟当我还。
菡萏溢嘉色，篔簹遗清斑。
神舒屏羁锁，志适忘幽孱。
弃逐久枯槁，迨今始开颜。
赏心难久留，离念来相关。
北望间亲爱，南瞻杂夷蛮。
置之勿复道，且寄须臾闲。','',''),('quantangshi-18660','夏夜苦热登西楼','柳宗元','quantangshi','','卷19','苦热中夜起，登楼独褰衣。
山泽凝暑气，星汉湛光辉。
火晶燥露滋，野静停风威。
探汤汲阴井，炀竈开重扉。
凭阑久彷徨，流汗不可挥。
莫辩亭毒意，仰诉璇与玑。
谅非姑射子，静胜安能希。','',''),('quantangshi-18661','觉衰','柳宗元','quantangshi','','卷19','久知老会至，不谓便见侵。
今年宜未衰，稍已来相寻。
齿疎髪就种，奔走力不任。
咄此可奈何，未必伤我心。
彭聃安在哉？周孔亦已沈。
古称寿圣人，曾不留至今。
但愿得美酒，朋友常共酙。
是时春向暮，桃李生繁阴。
日照天正绿，杳杳归鸿吟。
出门呼所亲，扶杖登西林。
高歌足自快，商颂有遗音。','',''),('quantangshi-18662','游南亭夜还叙志七十韵','柳宗元','quantangshi','','卷19','夙抱丘壑尚，率性恣游遨。
中为吏役牵，十祀空悁劳。
外曲徇尘辙，私心寄英髦。
进乏廓庙器，退非乡曲豪。
天命斯不易，鬼责将安逃。
屯难果见凌，剥丧宜所遭。
神明固浩浩，众口徒嗷嗷。
投迹山水地，放情咏离骚。
再怀曩岁期，容与驰轻舠。
虚馆背山郭，前轩面江臯。
重叠间浦溆，逦迤驱岩㟼。
积翠浮澹灧，始疑负灵鳌。
丛林留冲飙，石砾迎飞涛。
旷朗天景霁，樵苏远相号。
澄潭涌沈鸥，半壁跳悬猱。
鹿鸣验食野，鱼乐知观濠。
孤赏诚所悼，暂欣良足襃。
留连俯棂槛，注我壶中醪。
朵颐进芰实，擢手持蟹螯。
炊稻视爨鼎，脍鲜闻操刀。
野蔬盈倾筐，颇杂池沼芼。
缅慕鼓枻翁，啸咏哺其糟。
退想于陵子，三咽资李螬。
斯道难为偕，沈忧安所韬。
曲渚怨鸿鹄，环洲雕兰𦺆。
暮景回西岑，北流逝滔滔。
徘徊遂昏黑，远火明连艘。
木落寒山静，江空秋月高。
歛袂戒还徒，善游矜所操。
趣浅戢长枻，乘深屏轻篙。
旷望援深竿，哀歌叩鸣艚。
中川恣超忽，漫若翔且翱。
淹泊遂所止，野风自颾颾。
涧急惊鳞奔，蹊荒饥兽嗥。
入门守拘絷，凄戚增郁陶。
慕士情未忘，怀人首徒搔。
内顾乃无有，德輶甚鸿毛。
名窃久自欺，食浮固云叨。
问牛悲衅钟，说彘惊临牢。
永遁刀笔吏，宁期簿书曹。
中兴遂羣物，裂壤分鞬櫜。
岷凶既云捕，吴虏亦已鏖。
捍御盛方虎，谟明富伊咎。
披山穷木禾，驾海逾蟠桃。
重来越裳雉，再返西旅獒。
左右抗槐棘，纵横罗雁羔。
三辟咸肆宥，众生均覆焘。
安得奉皇灵，在宥解天弢。
归诚慰松梓，陈力开蓬篙。
卜室有鄠杜，名田占沣涝。
磻溪近余基，阿城连故濠。
螟蛑愿亲燎，荼堇甘自薅。
饥食期农耕，寒衣俟蚕缲。
及骭足为温，满腹宁复饕。
安将蒯及菅，谁慕粱与膏。
弋林敺雀鷃，渔泽从䲡鱽。
观象嘉素履，陈诗谢干旄。
方托麋鹿羣，敢同骐骥槽。
处贱无溷浊，固穷匪淫慆。
踉跄辞束缚，悦怿换煎熬。
登年徒负版，兴役趋代鼛。
目眩绝浑浑，耳喧息嘈嘈。
兹焉毕余命，富贵非吾曹。
长沙哀糺纆，汉阴嗤桔槔。
苟伸击壤情，机事息秋豪。
海雾多蓊郁，越风饶腥臊。
宁唯迫魑魅，所惧齐焄藨。
知罃怀褚中，范叔恋绨袍。
伊人不可期，慷慨徒忉忉。','',''),('quantangshi-18663','韦道安','柳宗元','quantangshi','','卷19','道安本儒士，颇擅弓劒名。
二十游太行，暮闻号哭声。
疾驱前致问，有叟垂华缨。
言我故刺史，失职还西京。
偶为羣盗得，毫缕无余赢。
货财足非恡，二女皆娉婷。
苍黄见驱逐，谁识死与生。
便当此殒命，休复事晨征。
一闻激高义，眦裂肝胆横。
挂弓问所在，趫捷超峥嵘。
见盗寒磵阴，罗列方忿争。
一矢毙酋帅，余党号且惊。
麾令递束缚，纆索相拄撑。
彼姝久褫魄，刃下俟诛刑。
却立不亲授，谕以从父行。
捃收自担肩，转道趋前程。
夜发敲石火，山林如昼明。
父子更抱持，涕血纷交零。
顿首愿归货，纳女称舅甥。
道安旧衣去，义重利固轻。
师婚古所病，合姓非用兵。
朅来事儒术，十载所能逞。
慷慨张徐州，朱邸扬前旌。
投区获所愿，前马出王城。
辕门立奇士，淮水秋风生。
君侯既即世，麾下相欹倾。
立孤抗王命，钟鼓四野鸣。
横溃非所壅，逆节非所婴。
举头自引[刃]，顾义谁顾形。
烈士不忘死，所死在忠贞。
咄嗟徇权子，翕习尤趋荣。
我歌非悼死，所悼时世情。','',''),('quantangshi-18664','哭连州凌员外司马','柳宗元','quantangshi','','卷19','废逐人所弃，遂为鬼神欺。
才难不其然，卒与大患期。
凌人古受氏，吴世夸雄姿。
寂寞富春水，英气方在斯。
六学诚一贯，精义穷发挥。
着书逾十年，幽頥靡不推。
天庭掞高文，万字若波驰。
记室征西府，宏谋耀其奇。
輶轩下东越，列郡苏疲羸。
宛宛凌江羽，来栖翰林枝。
孝文留弓劒，中外方危疑。
抗声促遗诏，定命由陈辞。
徒隶肃曹官，征赋参有司。
出守乌江浒，老迁湟水湄。
高堂倾故国，葬祭限囚羁。
仲叔继幽沦，狂呌唯童儿。
一门既无主，焉用徒生为。
举声但呼天，孰知神者谁。
泣尽目无见，肾伤足不持。
溘死委炎荒，臧获守灵帷。
平生负国谴，骸骨非敢私。
盖棺未塞责，孤旐凝寒飔。
念昔始相遇，腑肠为君知。
进身齐选择，失路同瑕疵。
本期济仁义，今为众所嗤。
灭名竟不试，世义安可支。
恬死百忧尽，苟生万虑滋。
顾余九逝魂，与子各何之。
我歌诚自恸，非独为君悲。','',''),('quantangshi-18665','旦携谢山人至愚池','柳宗元','quantangshi','','卷19','新沐换轻帻，晓池风露清。
自谐尘外意，况与幽人行。
霞散众山逈，天高数雁鸣。
机心付当路，聊适羲皇情。','',''),('quantangshi-18666','独觉','柳宗元','quantangshi','','卷19','觉来窗牖空，寥落雨声晓。
良游怨迟暮，末事惊纷扰。
为问经世心，古人难尽了。','',''),('quantangshi-18667','首春逢耕者','柳宗元','quantangshi','','卷19','南楚春候早，余寒已滋荣。
土膏释原野，百蛰竞所营。
缀景未及郊，穑人先耦耕。
园林幽鸟啭，渚泽新泉清。
农事诚素务，羁囚阻平生。
故池想芜没，遗亩当榛荆。
慕隐既有系，图功遂无成。
聊从田父言，款曲陈此情。
眷然抚耒耜，回首烟云横。','',''),('quantangshi-18668','溪居','柳宗元','quantangshi','','卷19','久为簪组累，幸此南夷谪。
闲依农圃邻，偶似山林客。
晓耕翻露草，夜榜响溪石。
来往不逢人，长歌楚天碧。','',''),('quantangshi-18669','夏初雨后寻愚溪','柳宗元','quantangshi','','卷19','悠悠雨初霁，独绕清溪曲。
引杖试荒泉，解带围新竹。
沈吟亦何事，寂寞固所欲。
幸此息营营，啸歌静炎燠。','',''),('quantangshi-18670','入黄溪闻猿','柳宗元','quantangshi','','卷19','溪路千里曲，哀猿何处鸣。
孤臣泪已尽，虚作断肠声。','',''),('quantangshi-18671','韦使君黄溪祈雨见召从行至祠下口号','柳宗元','quantangshi','','卷19','骄阳愆岁事，良牧念菑畲。
列骑低残月，鸣笳度碧虚。
稍穷樵客路，遥驻野人居。
谷口寒流净，丛祠古木疎。
焚香秋雾湿，奠玉晓光初。
肸蠁巫言报，精诚礼物余。
惠风仍偃草，灵雨会随车。
俟罪非真吏，翻惭奉简书。','',''),('quantangshi-18672','郊居岁暮','柳宗元','quantangshi','','卷19','屏居负山郭，岁暮惊离索。
野逈樵唱来，庭空烧烬落。
世纷因事远，心赏随年薄。
默默谅何为，徒成今与昨。','',''),('quantangshi-18673','秋晓行南谷经荒村','柳宗元','quantangshi','','卷19','杪秋霜露重，晨起行幽谷。
黄叶覆溪桥，荒村唯古木。
寒花疎寂历，幽泉微断续。
机心久已忘，何事惊麋鹿。','',''),('quantangshi-18674','雨后晓行独至愚溪北池','柳宗元','quantangshi','','卷19','宿云散洲渚，晓日明村坞。
高树临清池，风惊夜来雨。
予心适无事，偶此成宾主。','',''),('quantangshi-18675','中夜起望西园值月上','柳宗元','quantangshi','','卷19','觉闻繁露坠，开户临西园。
寒月上东岭，泠泠疎竹根。
石泉远逾响，山鸟时一喧。
倚楹遂至旦，寂寞将何言。','',''),('quantangshi-18676','零陵春望','柳宗元','quantangshi','','卷19','平野春草绿，晓莺啼远林。
日晴潇湘渚，云断岣嵝岑。
仙驾不可望，世途非所任。
凝情空景慕，万里苍梧阴。','',''),('quantangshi-18677','从崔中丞过卢少尹郊居','柳宗元','quantangshi','','卷19','寓居湘岸四无邻，世网难婴每自珍。
莳药闲庭延国老，开罇虚室值贤人。
泉回浅石依高柳，迳转垂藤闲绿筠。
闻道偏为五禽戏，出门鸥鸟更相亲。','',''),('quantangshi-18678','夏昼偶作','柳宗元','quantangshi','','卷19','南州溽暑醉如酒，隐几熟眠开北牖。
日午独觉无余声，山童隔竹敲茶臼。','',''),('quantangshi-18679','雨晴至江渡','柳宗元','quantangshi','','卷19','江雨初晴思远步，日西独向愚溪渡。
渡头水落村迳成，撩乱浮槎在高树。','',''),('quantangshi-18680','江雪','柳宗元','quantangshi','','卷19','千山鸟飞绝，万迳人踪灭。
孤舟蓑笠翁，独钓寒江雪。','',''),('quantangshi-18681','冉溪','柳宗元','quantangshi','','卷19','少时陈力希公侯，许国不复为身谋。
风波一跌逝万里，壮心瓦解空缧囚。
缧囚终老无余事，愿卜湘西冉溪地。
却学寿张樊敬侯，种漆南园待成器。','',''),('quantangshi-18682','法华寺西亭夜饮','柳宗元','quantangshi','','卷19','[只]树夕阳亭，共倾三昧酒。
雾暗水连堦，月明花复牖。
莫厌尊前醉，相看未白首。','',''),('quantangshi-18683','戏题石门长老东轩','柳宗元','quantangshi','','卷19','石门长老身如梦，旃檀成林手所种。
坐来念念非昔人，万徧莲花为谁用。
如今七十自忘机，贪爱都忘筋力微。
莫向东轩春野望，花开日出雉皆飞。','',''),('quantangshi-18684','茅檐下始栽竹','柳宗元','quantangshi','','卷19','瘴茅葺为宇，溽暑常侵肌。
适有重膇疾，蒸郁宁所宜。
东邻幸导我，树竹邀凉飔。
欣然惬吾志，荷锸西岩垂。
楚壤多怪石，垦凿力已疲。
江风忽云暮，舆曳还相追。
萧瑟过极浦，旖旎附幽墀。
贞根期永固，贻尔寒泉滋。
夜牕遂不掩，羽扇宁复持。
清泠集浓露，枕簟凄已知。
网虫依密叶，晓禽栖逈枝。
岂伊纷嚣闲，重以心虑怡。
嘉尔亭亭质，自远弃幽期。
不见野蔓草，蓊蔚有华姿。
谅无淩寒色，岂与青山辞。','',''),('quantangshi-18685','种仙灵毗','柳宗元','quantangshi','','卷19','穷陋阙自养，疠气剧嚣烦。
隆冬乏霜霰，日夕南风温。
杖藜下庭际，曳踵不及门。
门有野田吏，慰我飘零魂。
及言有灵药，近在湘西原。
服之不盈旬，蹩𨇨皆腾骞。
笑忭前即吏，为我擢其根。
蔚蔚遂充庭，英翘忽已繁。
晨起自采曝，杵臼通夜喧。
灵和理内藏，攻疾贵自源。
拥覆逃积雾，伸舒委余暄。
奇功苟可征，宁复资兰荪。
我闻畸人术，一气中夜存。
能令深深息，呼吸还归跟。
疎放固难效，且以药饵论。
痿者不忘起，穷者宁复言。
神哉辅吾足，幸及儿女奔。','',''),('quantangshi-18686','种术','柳宗元','quantangshi','','卷19','守闲事服饵，采术东山阿。
东山幽且阻，疲苶烦经过。
戒徒斸灵根，封植閟天和。
违尔涧底石，彻我庭中莎。
土膏滋玄液，松露坠繁柯。
南东自成亩，缭绕纷相罗。
晨步佳色媚，夜眠幽气多。
离忧苟可怡，孰能知其他。
爨竹茹芳叶，宁虑瘵与瘥。
留连树蕙辞，婉娩采薇歌。
悟拙甘自足，激清愧同波。
单豹且理内，高门复如何。','',''),('quantangshi-18687','种白蘘荷','柳宗元','quantangshi','','卷19','血虫化为疠，夷俗多所神。
衔猜每腊毒，谋富不为仁。
蔬果自远至，杯酒盈肆陈。
言甘中必苦，何用知其真。
华洁事外饰，尤病中州人。
钱刀恐贾害，饥至益逡巡。
窜伏常战栗，怀故逾悲辛。
庶氏有嘉草，攻禬事久泯。
炎帝垂灵编，言此殊足珍。
崎岖乃有得，托以全余身。
纷敷碧树阴，眄睐心所亲。','',''),('quantangshi-18688','新植海石榴','柳宗元','quantangshi','','卷19','弱植不盈尺，远意驻蓬瀛。
月寒空堦曙，幽梦彩云生。
粪壤擢珠树，莓苔插琼英。
芳根閟颜色，徂岁为谁荣。','',''),('quantangshi-18689','戏题堦前芍药','柳宗元','quantangshi','','卷19','凡卉与时谢，妍华丽兹晨。
欹红醉浓露，窈窕留余春。
孤赏白日暮，暄风动摇频。
夜牕蔼芳气，幽卧知相亲。
愿致溱洧赠，悠悠南国人。','',''),('quantangshi-18690','始见白髪题所植海石榴','柳宗元','quantangshi','','卷19','几年封植爱芳丛，韶艳朱颜竟不同。
从此休论上春事，看成古木对衰翁。','',''),('quantangshi-18691','植灵寿木','柳宗元','quantangshi','','卷19','白华照寒水，怡我适野情。
前趋问长老，重复欣嘉名。
蹇连易衰朽，方刚谢经营。
敢期齿杖赐，聊且移孤茎。
丛萼中竞秀，分房外舒英。
柔条乍反植，劲节常对生。
循翫足忘疲，稍觉步武轻。
安能事翦伐，持用资徒行。','',''),('quantangshi-18692','自衡阳移桂十余本植零陵所住精舍','柳宗元','quantangshi','','卷19','谪官去南裔，清湘绕灵岳。
晨登蒹葭岸，霜景霁纷浊。
离披得幽桂，芳本欣盈握。
火耕困烟烬，薪采久摧剥。
道旁且不愿，岑岭况悠邈。
倾筐壅故壤，栖息期鸾鷟。
路远清凉宫，一雨悟无学。
南人始珍重，微我谁先觉。
芳意不可传，丹心徒自渥。','',''),('quantangshi-18693','湘岸移木芙蓉植龙兴精舍','柳宗元','quantangshi','','卷19','有美不自蔽，安能守孤根。
盈盈湘西岸，秋至风露繁。
丽影别寒水，穠芳委前轩。
芰荷谅难杂，反此生高原。','',''),('quantangshi-18694','早梅','柳宗元','quantangshi','','卷19','早梅发高树，逈映楚天碧。
朔吹飘夜香，繁霜滋晓白。
欲为万里赠，杳杳山水隔。
寒英坐销落，何用慰远客。','',''),('quantangshi-18695','南中荣橘柚','柳宗元','quantangshi','','卷19','橘柚怀贞质，受命此炎方。
密林耀朱绿，晚岁有余芳。
殊风限清汉，飞雪滞故乡。
攀条何所叹，北望熊与湘。','',''),('quantangshi-18696','红蕉','柳宗元','quantangshi','','卷19','晚英值穷节，绿润含朱光。
以兹正阳色，窈窕凌清霜。
远物世所重，旅人心独伤。
回晖眺林际，摵摵无遗芳。','',''),('quantangshi-18697','巽公院五咏 净土堂','柳宗元','quantangshi','','卷19','结习自无始，沦溺穷苦源。
流形及兹世，始悟三空门。
华堂开净域，图像焕且繁。
清冷焚众香，微妙歌法言。
稽首愧导师，超遥谢尘昏。','',''),('quantangshi-18698','巽公院五咏 曲讲堂','柳宗元','quantangshi','','卷19','寂灭本非断，文字安可离。
曲堂何为设，高士方在斯。
圣默寄言宣，分别乃无知。
趣中即空假，名相与谁期。
愿言绝闻得，忘意聊思惟。','',''),('quantangshi-18699','巽公院五咏 禅堂','柳宗元','quantangshi','','卷19','发地结菁茅，团团抱虚白。
山花落幽户，中有忘机客。
涉有本非取，照空不待析。
万籁俱缘生，窅然喧中寂。
心境本洞如，鸟飞无遗迹。','',''),('quantangshi-18700','巽公院五咏 芙蓉亭','柳宗元','quantangshi','','卷19','新亭俯朱槛，嘉木开芙蓉。
清香晨风远，溽彩寒露浓。
潇洒出人世，低昂多异容。
尝闻色空喻，造物谁为工。
留连秋月晏，迢递来山钟。','',''),('quantangshi-18701','巽公院五咏 苦竹桥','柳宗元','quantangshi','','卷19','危桥属幽径，缭绕穿疎林。
迸箨分苦节，轻筠抱虚心。
俯瞰涓涓流，仰聆萧萧吟。
差池下烟日，嘲异常鸣山禽。
谅无要津用，栖息有余阴。','',''),('quantangshi-18702','梅雨','柳宗元','quantangshi','','卷19','梅实迎时雨，苍茫值晚春。
愁深楚猿夜，梦断越鸡晨。
海雾连南极，江云暗北津。
素衣今尽化，非为帝京尘。','',''),('quantangshi-18703','零陵早春','柳宗元','quantangshi','','卷19','问春从此去，几日到秦原。
凭寄还乡梦，殷勤入故园。','',''),('quantangshi-18704','田家三首 一','柳宗元','quantangshi','','卷19','蓐食徇所务，驱牛向东阡。
鸡鸣村巷白，夜色归暮田。
札札耒耜声，飞飞来乌鸢。
竭兹筋力事，持用穷岁年。
尽输助徭役，聊就空自眠。
子孙日已长，世世还复然。','',''),('quantangshi-18705','田家三首 二','柳宗元','quantangshi','','卷19','篱落隔烟火，农谈四邻夕。
庭际秋虫鸣，疎麻方寂历。
蚕丝尽输税，机杼空倚壁。
里胥夜经过，鸡黍事筵席。
各言官长峻，文字多督责。
东乡后租期，车毂陷泥泽。
公门少推恕，鞭朴恣狼籍。
努力慎经营，肌肤真可惜。
迎新在此岁，唯恐踵前迹。','',''),('quantangshi-18706','田家三首 三','柳宗元','quantangshi','','卷19','古道饶蒺藜，萦回古城曲。
蓼花被堤岸，陂水寒更绿。
是时收获竟，落日多樵牧。
风高榆柳疎，霜重棃枣熟。
行人迷去住，野鸟竞栖宿。
田翁笑相念，昏黑慎原陆。
今年幸少丰，无厌饘与粥。','',''),('quantangshi-18707','行路难三首 一','柳宗元','quantangshi','','卷19','君不见夸父逐日窥虞渊，跳踉北海超昆仑。
披霄决汉出沆漭，瞥裂左右遗星辰。
须臾力尽道渴死，狐鼠蜂蚁争噬吞。
北方竫人长九寸，开口抵掌更笑喧。
啾啾饮食滴与粒，生死亦足终天年。
睢盱大志小成遂，坐使儿女相悲怜。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-18708','行路难三首 二','柳宗元','quantangshi','','卷19','虞衡斤斧罗千山，工命采斫杙与椽。
深林土剪十取一，百牛连鞅摧双辕。
万围千寻妨道路，东西蹶倒山火焚。
遗余毫末不见保，躏跞磵壑何当存。
羣材未成质已夭，突兀哮豁空岩峦。
柏梁天灾武库火，匠石狼顾相愁冤。
君不见南山栋梁益稀少，爱材养育谁复论。','',''),('quantangshi-18709','行路难三首 三','柳宗元','quantangshi','','卷19','飞雪断道冰成梁，侯家炽炭雕玉房。
蟠龙吐耀虎喙张，熊蹲豹踯争低昂。
攒峦丛㟧射朱光，丹霞翠雾飘奇香。
美人四向回明璫，雪山冰谷曦太阳。
星躔奔走不得止，奄忽双燕栖虹梁。
风台露榭生光饰，死灰弃置参与商。
盛时一去贵反贱，桃笙葵扇安可当。','',''),('quantangshi-18710','闻籍田有感','柳宗元','quantangshi','','卷19','天田不日降皇舆，留滞长沙岁又除。
宣室无由问厘事，周南何处托成书。','',''),('quantangshi-18711','跂乌词','柳宗元','quantangshi','','卷19','城上日出羣乌飞，鵶鵶争赴朝阳枝。
刷毛伸翼和且乐，尔独落魄今何为。
无乃慕高近白日，三足妬尔令尔疾。
无乃饥啼走道旁，贪鲜攫肉人所伤。
翘肖独足下丛薄，口衔低枝始能跃。
还顾泥涂备蝼蚁，仰看栋梁防燕雀。
左右六翮利如刀，踊身失势不得高。
支离无趾犹自免，努力低飞逃后患。','',''),('quantangshi-18712','笼鹰词','柳宗元','quantangshi','','卷19','凄风淅沥飞严霜，苍鹰上击翻曙光。
云披雾裂虹霓断，霹雳掣电捎平冈。
砉然劲翮翦荆棘，下攫狐兔腾苍茫。
爪毛吻血百鸟逝，独立四顾时激昂。
炎风溽暑忽然至，羽翼脱落自摧藏。
草中狸鼠足为患，一夕十顾惊且伤。
但愿清商复为假，拔去万累云间翔。','',''),('quantangshi-18713','放鹧鸪词','柳宗元','quantangshi','','卷19','楚越有鸟甘且腴，嘲嘲自名为鹧鸪。
徇媒得食不复虑，机械潜发罹罝罘。
羽毛摧折触笼籞，烟火煽赫惊庖厨。
鼎前芍药调五味，膳夫攘腕左右视。
齐王不忍觳觫牛，简子亦放邯郸鸠。
二子得意犹念此，况我万里为孤囚。
破笼展翅当远去，同类相呼莫相顾。','',''),('quantangshi-18714','龟背戏','柳宗元','quantangshi','','卷19','长安新技出宫掖，喧喧初徧王侯宅。
玉盘滴沥黄金钱，皎如文龟丽秋天。
八方定位开神卦，六甲离离齐上下。
投变转动玄机卑，星流霞破相参差。
四分五裂势未已，出无入有谁能知。
乍惊散漫无处所，须臾罗列已如故。
徒言万事有盈虚，终朝一掷知胜负。
修门象棋不复贵，魏宫妆奁世所弃。
岂如瑞质耀奇文，愿持千岁寿吾君。
庙堂巾笥非余慕，钱刀儿女徒纷纷。','',''),('quantangshi-18715','闻黄鹂','柳宗元','quantangshi','','卷19','倦闻子规嘲暮声，不意忽有黄鹂鸣。
一声梦断楚江曲，满眼故园春意生。
目极千里无山河，麦芒际天摇清波。
王畿优本少赋役，务闲酒熟饶经过。
此时晴烟最深处，舍南巷北遥相语。
翻日迥度昆明飞，凌风邪看细柳翥。
我今误落千万山，身同伧人不思还。
乡禽何事亦来此，令我生心忆桑梓。
闭声回翅归务速，西林紫椹行当熟。','',''),('quantangshi-18716','浑鸿胪宅闻歌效白紵','柳宗元','quantangshi','','卷19','翠帷双卷出倾城，龙劒破匣霜月明。
朱唇掩仰悄无声，金簧玉磬宫中生。
下沈秋火激太清，天高地逈凝日晶，羽觞荡漾何事倾。','',''),('quantangshi-18717','杨白花','柳宗元','quantangshi','','卷19','杨白花，风吹渡江水。
坐令宫树无颜色，摇荡春光千万里。
茫茫晓日下长秋，哀歌未断城鸦起。','',''),('quantangshi-18718','渔翁','柳宗元','quantangshi','','卷19','渔翁夜傍西岩宿，晓汲清湘燃楚竹。
烟销日出不见人，[唉]乃一声山水绿。
回看天际下中流，岩上无心云相逐。','',''),('quantangshi-18719','饮酒','柳宗元','quantangshi','','卷19','今夕少愉乐，起坐开清尊。
举觞酹先酒，为我驱忧烦。
须臾心自殊，顿觉天地暄。
连山变幽晦，绿水函晏温。
蔼蔼南郭门，树木一何繁。
清阴可自庇，竟夕闻佳言。
尽醉无复辞，偃卧有芳荪。
彼哉晋楚富，此道未必存。','',''),('quantangshi-18720','读书','柳宗元','quantangshi','','卷19','幽沈谢世事，俛默窥唐虞。
上下观古今，起伏千万途。
遇欣或自笑，感戚亦以吁。
缥帙各舒散，前后互相逾。
瘴疴扰灵府，日与往昔殊。
临文乍了了，彻卷兀若无。
竟夕谁与言，但与竹素俱。
倦极便倒卧，熟寐乃一苏。
欠伸展肢体，吟咏心自愉。
得意适其适，非愿为世儒。
道尽即闭口，萧散捐囚拘。
巧者为我拙，智者为我愚。
书史足自悦，安用勤与劬。
贵尔六尺躯，勿为名所驱。','',''),('quantangshi-18721','感遇二首 一','柳宗元','quantangshi','','卷19','西陆动凉气，惊乌号北林。
栖息岂殊性，集枯安可任。
鸿鹄去不返，勾吴阻且深。
徒嗟日沈湎，丸鼓骛奇音。
东海久摇荡，南风已骎骎。
坐使青天暮，小星愁太阴。
众情嗜奸利，居货捐千金。
危根一以振，齐斧来相寻。
揽衣中夜起，感物涕盈襟。
微霜众所践，谁念岁寒心。','',''),('quantangshi-18722','感遇二首 二','柳宗元','quantangshi','','卷19','旭日照寒野，鸒斯起蒿莱。
啁啾有余乐，飞舞西陵隈。
回风旦夕至，零叶委陈荄。
所栖不足恃，鹰隼纵横来。','',''),('quantangshi-18723','咏史','柳宗元','quantangshi','','卷19','燕有黄金台，远致望诸君。
嗛嗛事强怨，三岁有奇勋。
悠哉辟疆理，东海漫浮云。
宁知世情异，嘉谷坐熇焚。
致令委金石，谁愿蠢蠕羣。
风波歘潜构，遗恨意纷纭。
岂不善图后，交私非所闻。
为忠不顾内，晏子亦垂文。','',''),('quantangshi-18724','咏三良','柳宗元','quantangshi','','卷19','束带值明后，顾盼流辉光。
一心在陈力，鼎列夸四方。
款款效忠信，恩义皎如霜。
生时亮同体，死没宁分张。
壮躯闭幽隧，猛志填黄肠。
殉死礼所非，况乃用其良。
霸基弊不振，晋楚更张皇。
疾病命固乱，魏氏言有章。
从邪陷厥父，吾欲讨彼狂。','',''),('quantangshi-18725','咏荆轲','柳宗元','quantangshi','','卷19','燕秦不两立，太子已为虞。
千金奉短计，匕首荆卿趋。
穷年徇所欲，兵势且见屠。
微言激幽愤，怒目辞燕都。
朔风动易水，挥爵前长驱。
函首致宿怨，献田开版图。
炯然耀电光，掌握罔正夫。
造端何其锐，临事竟趑趄。
长虹吐白日，仓卒反受诛。
按劒赫凭怒，风雷助号呼。
慈父断子首，狂走无容躯。
夷城芟七族，台观皆焚污。
始期忧患弭，卒动灾祸枢。
秦皇本诈力，事与桓公殊。
奈何效曹子，实谓勇且愚。
世传故多谬，太史征无且。','',''),('quantangshi-18726','掩役夫张进骸','柳宗元','quantangshi','','卷19','生死悠悠尔，一气聚散之。
偶来纷喜怒，奄忽已复辞。
为役孰贱辱，为贵非神奇。
一朝纩息定，枯巧无妍媸。
生平勤皂枥，锉秣不告疲。
既死给槥椟，葬之东山基。
奈何值崩湍，荡析临路垂。
髐然暴百骸，散乱不复支。
从者幸告余，睠之涓然悲。
猫虎获迎祭，犬马有盖帷。
伫立唁尔魂，岂复识此为。
畚锸载埋瘗，沟渎护其危。
我心得所安，不谓尔有知。
掩骼着春令，兹焉适其时。
及物非吾事，聊且顾尔私。','',''),('quantangshi-18727','省试观庆云图诗','柳宗元','quantangshi','','卷19','设色既成象，卿云示国都。
九天开秘祉，百辟赞嘉谟。
抱日依龙衮，非烟近御炉。
高标连汗漫，逈望接虚无。
裂素荣光发，舒华瑞色敷。
恒将配尧德，垂庆代河图。','',''),('quantangshi-18728','春怀故园','柳宗元','quantangshi','','卷19','九扈鸣已晚，楚乡农事春。
悠悠故池水，空待灌园人。','',''),('quantangshi-18729','团扇诗','劉禹錫','quantangshi','','卷19','团扇复团扇，奉君清暑殿。
秋风入庭树，从此不相见。
上有乘鸾女，苍苍虫网遍。
明年入怀袖，别是机中练。','',''),('quantangshi-18730','宜城歌','劉禹錫','quantangshi','','卷19','野水绕空城，行尘起孤驿。
荒台侧生树，石碣阳镌额。
靡靡度行人，温风吹宿麦。','',''),('quantangshi-18731','顺阳歌','劉禹錫','quantangshi','','卷19','朝辞官军驿，前望顺阳路。
野水啮荒坟，秋虫镂宫树。
曾闻天宝末，胡马西南骛。
城守鲁将军，拔城从此去。','',''),('quantangshi-18732','莫猺歌','劉禹錫','quantangshi','','卷19','莫猺自生长，名字无符籍。
市易杂鲛人，婚姻通木客。
星居占泉眼，火种开山脊。
夜渡千仞溪，含沙不能射。','',''),('quantangshi-18733','度桂岭歌','劉禹錫','quantangshi','','卷19','桂阳岭，下下复高高。
人稀鸟兽骇，地远草木豪。
寄言千金子，知余歌者劳。','',''),('quantangshi-18734','插田歌','劉禹錫','quantangshi','','卷19','冈头花草齐，燕子东西飞。
田塍望如线，白水光参差。
农妇白紵裙，农父绿蓑衣。
齐唱郢中歌，嘤儜如竹枝。
但闻怨响音，不辨俚语词。
时时一大笑，此必相嘲嗤。
水平苗漠漠，烟火生墟落。
黄犬往复还，赤鸡鸣且啄。
路旁谁家郎，乌帽衫袖长。
自言上计吏，年幼离帝乡。
田夫语计吏，君家侬定谙。
一来长安道，眼大不相参。
计吏笑致辞，长安真大处。
省门高轲峨，侬入无度数。
昨来补卫士，唯用筒竹布。
君看二三年，我作官人去。','',''),('quantangshi-18735','葡萄歌','劉禹錫','quantangshi','','卷19','野田生葡萄，缠绕一枝高。
移来碧墀下，张王日日高。
分岐浩繁缛，修蔓蟠诘曲。
扬翘向庭柯，意思如有属。
为之立长檠，布濩当轩绿。
米液溉其根，理疎看渗漉。
繁葩组绶结，悬实珠玑蹙。
马乳带轻霜，龙鳞曜初旭。
有客汾阴至，临堂瞪双目。
自言我晋人，种此如种玉。
酿之成美酒，令人饮不足。
为君持一斗，往取凉州牧。','',''),('quantangshi-18736','蛮子歌','劉禹錫','quantangshi','','卷19','蛮语钩輈音，蛮衣斑斓布。
熏狸掘沙鼠，时节祠盘瓠。
忽逢乘马客，恍若惊麏顾。
腰斧上高山，意行无旧路。','',''),('quantangshi-18737','马嵬行','劉禹錫','quantangshi','','卷19','绿野扶风道，黄尘马嵬驿。
路边杨贵人，坟高三四尺。
乃问里中儿，皆言幸蜀时。
军家诛戚族，天子舍妖姬。
羣吏伏门屏，贵人牵帝衣。
低回转美目，风日为无晖。
贵人饮金屑，倏忽舜英暮。
平生服杏丹，颜色真如故。
属车尘已远，里巷来窥覰。
共爱宿妆妍，君王画眉处。
履綦无复有，履组光未灭。
不见岩畔人，空见凌波袜。
邮童爱踪迹，私手解鞶结。
传看千万眼，缕绝香不歇。
指环照骨明，首饰敌连城。
将入咸阳市，犹得贾胡惊。','',''),('quantangshi-18738','百花行','劉禹錫','quantangshi','','卷19','长安百花时，风景宜轻薄。
无人不沽酒，何处不闻乐。
春风连夜动，微雨凌晓濯。
红焰出墙头，雪光映楼角。
繁紫韵松竹，远黄绕篱落。
临路不胜愁，轻烟去何托。
满庭荡魂魄，照庑成丹渥。
烂熳簇颠狂，飘零劝行乐。
时节易晼晚，清阴覆池阁。
唯有安石榴，当轩慰寂寞。','',''),('quantangshi-18739','壮士行','劉禹錫','quantangshi','','卷19','阴风振寒郊，猛虎正咆哮。
徐行出烧地，连吼入黄茅。
壮士走马去，镫前弯玉弰。
叱之使人立，一发如铍交。
悍睛忽星堕，飞血溅林梢。
彪炳为我席，膻腥充我庖。
里中欣害除，贺酒纷呶号。
明日长桥上，倾城看斩蛟。','',''),('quantangshi-18740','苦雨行','劉禹錫','quantangshi','','卷19','悠悠飞走情，同乐在阳和。
岁中三百日，常恐风雨多。
天人信遐远，时节易蹉跎。
洞房有明烛，无乃酣且歌。','',''),('quantangshi-18741','华山歌','劉禹錫','quantangshi','','卷19','洪罏作高山，元气鼓其橐。
俄然神功就，峻拔在寥廓。
灵迹露指爪，杀气见棱角。
凡木不敢生，神仙聿来托。
天资帝王宅，以我为关钥。
能令下国人，一见换神骨。
高山固无限，如此方为岳。
丈夫无特达，虽贵犹碌碌。','',''),('quantangshi-18742','抛球乐词 一','劉禹錫','quantangshi','','卷19','五彩绣团圆，登君玳瑁筵。
最宜红烛下，偏称落花前。
上客如先起，应须赠一船。','',''),('quantangshi-18743','抛球乐词 二','劉禹錫','quantangshi','','卷19','春早见花枝，朝朝恨发迟。
及看花落后，却忆未开时。
幸有抛球乐，一杯君莫辞。','',''),('quantangshi-18744','华清词','劉禹錫','quantangshi','','卷19','日出骊山东，裴回照温泉。
楼台影玲珑，稍稍开白烟。
言昔太上皇，常居此祈年。
风中闻清乐，往往来列仙。
翠华入五云，紫气归上玄。
哀哀生人泪，泣尽弓劒前。
圣道本自我，凡情徒颙然。
小臣感玄化，一望青冥天。','',''),('quantangshi-18745','送春曲三首 一','劉禹錫','quantangshi','','卷19','春向晚，春晚思悠哉。
风云日已改，花叶自相摧。
漠漠空中去，何时天际来。','',''),('quantangshi-18746','送春曲三首 二','劉禹錫','quantangshi','','卷19','春已暮，冉冉如人老。
映叶见残花，连天是青草。
可怜桃与李，从此同桑枣。','',''),('quantangshi-18747','送春曲三首 三','劉禹錫','quantangshi','','卷19','春景去，此去何时回。
游人千万恨，落日上高台。
寂寞繁花尽，流鸎归莫来。','',''),('quantangshi-18748','初夏曲三首 一','劉禹錫','quantangshi','','卷19','铜壶方促夜，斗柄暂南回。
稍嫌单衣重，初怜北户开。
西园花已尽，新月为谁来。','',''),('quantangshi-18749','初夏曲三首 二','劉禹錫','quantangshi','','卷19','时节过繁华，阴阴千万家。
巢禽命子戏，园果坠枝斜。
寂寞孤飞蝶，窥丛觅晚花。','',''),('quantangshi-18750','初夏曲三首 三','劉禹錫','quantangshi','','卷19','绿水风初暖，青林露早曦。
麦陇雉朝雊，桑野人暮归。
百舌悲花尽，平芜来去飞。','',''),('quantangshi-18751','捣衣曲','劉禹錫','quantangshi','','卷19','爽砧应秋律，繁杵含凄风。
一一远相续，家家音不同。
户庭凝露清，伴侣明月中。
长裾委襞积，轻佩垂𤧚珑。
汗余衫更馥，钿移麝半空。
报寒惊边雁，促思闻候虫。
天狼正芒角，虎落定相攻。
盈箧寄何处，征人如转蓬。','',''),('quantangshi-18752','畲田行','劉禹錫','quantangshi','','卷19','何处好畲田，团团缦山腹。
鑚龟得雨卦，上山烧卧木。
惊麏走且顾，羣雉声咿喔。
红焰远成霞，轻煤飞入郭。
风引上高岑，猎猎度青林。
青林望靡靡，赤光低复起。
照潭出老蛟，爆竹惊山鬼。
夜色不见山，孤明星汉间。
如星复如月，俱逐晓风灭。
本从敲石光，遂至烘天热。
下种暖灰中，乘阳拆牙孽。
苍苍一雨后，苕頴如云发。
巴人拱手吟，耕耨不关心。
由来得地势，径寸有余金。','',''),('quantangshi-18753','鶗鴂吟','劉禹錫','quantangshi','','卷19','朝阳有鸣凤，不闻千万祀。
鶗鴂摧众芳，晨间先入耳。
秋风白露曦，从是尔啼时。
如何上春日，唧唧满庭飞。','',''),('quantangshi-18754','观云篇','劉禹錫','quantangshi','','卷19','兴云感阴气，疾足如见机。
晴来意态行，有若功成归。
葱茏含晚景，洁白凝秋晖。
夜深度银汉，漠漠仙人衣。','',''),('quantangshi-18755','养鸷词','劉禹錫','quantangshi','','卷19','养鸷非玩形，所资击鲜力。
少年昧其理，日日哺不息。
探雏网黄口，旦暮有余食。
宁知下韝时，翅重飞不得。
毰毸止林表，狡兔自南北。
饮啄既已盈，安能劳羽翼。','',''),('quantangshi-18756','别友人后得书因以诗赠','劉禹錫','quantangshi','','卷19','前时送君去，挥手青门桥。
路转不相见，犹闻马萧萧。
今得出关书，行程日已遥。
春还迟君至，共结芳兰苕。','',''),('quantangshi-18757','送华阴尉张苕赴邕府使幕','劉禹錫','quantangshi','','卷19','昔忝南宫郎，往来东观频。
尝披燕公传，耸若窥三辰。
翊圣崇国本，像贤正朝伦。
高视缅今古，清风敻无邻。
兰錡照通衢，一家十朱轮。
酇国嗣侯绝，韦卿世业贫。
夫子承大名，少年振芳尘。
青袍仙掌下，矫首凌烟旻。
公冶本非罪，潘郎一为民。
风霜苦摇落，坚白无缁磷。
一旦逢良时，天光烛幽沦。
重为长裾客，佐彼观风臣。
分野穷禹画，人烟过虞巡。
不言此行远，所乐相知新。
雨起巫山阳，鸟鸣湘水滨。
离筵出苍莽，别曲多悲辛。
今朝一杯酒，明日千里人。
从此孤舟去，悠悠天海春。','',''),('quantangshi-18758','送湘阳熊判官孺登府罢归钟陵因寄呈江西裴中丞二十三兄','劉禹錫','quantangshi','','卷19','射策志未就，从事岁云除。
箧留马卿赋，袖有刘弘书。
忽见夏木深，怅然忆吾庐。
复持州民刺，归谒专城居。
君家诚易知，胜绝倾里闾。
人言北郭生，门有卿相舆。
钟陵霭千里，带郭西江水。
朱槛照河宫，旗亭绿云里。
前年初缺守，慎简由宸扆。
临轩弄郡章，得人方付此。
是时左冯翊，天下第一理。
贵臣持牙璋，优诏发青纸。
迎风奸吏免，先令疲人喜。
何武劾腐儒，陈蕃礼高士。
昔升君子堂，腰下绶犹黄。
汾阴有宝气，赤堇多奇铓。
束简下曲台，佩鞬来历阳。
绮筵陪一笑，兰室袭余芳。
风水忽异势，江湖遂相忘。
因君倘借问，为话老沧浪。','',''),('quantangshi-18759','送韦秀才道冲赴制举','劉禹錫','quantangshi','','卷19','惊禽一辞巢，栖息无少安。
秋扇一离手，流尘蔽霜纨。
故侣不可追，凉风日已寒。
远逢杜陵士，别尽平生欢。
逐客无印绶，楚江多芷兰。
因居暇时游，长铗不复弹。
阅书南轩霁，絙瑟清夜阑。
万境身外寂，一杯腹中宽。
伊昔玄宗朝，冬卿冠鸳鸾。
肃穆升内殿，从容领儒冠。
游夏无措词，阳秋垂不刊。
至今羣玉府，学者空纵观。
世人希德门，揭若攀峰峦。
之子尚明训，锵如振琅玕。
一旦西上书，斑衣拂征鞍。
荆台宿暮雨，汉水浮春澜。
君门起天中，多士如星攒。
烟霞覆双阙，拚舞罗千官。
清漏滴铜壶，仙厨下雕盘。
荧煌仰金榜，错落濡飞翰。
古来才杰士，所嗟遭时难。
一鸣从此始，相望青云端。','',''),('quantangshi-18760','送李策秀才还湖南因寄幕中亲故兼简衡州吕八郎中','劉禹錫','quantangshi','','卷19','深春风日净，昼长幽鸟鸣。
仆夫前致词，门有白面生。
摄衣相问讯，解带坐南荣。
端志见眉睫，苦言发精诚。
因出怀中文，调孤词亦清。
悄如促柱弦，掩抑多不平。
乃言本蜀士，世降岷山灵。
前人秉艺文，高视来上京。
曳绶司徒府，所从信国桢。
析薪委宝林，善响继家声。
何处翳附郭，几人思郈成。
云天望乔木，风水悲流萍。
前与计吏西，始列贡士名。
森然就笔札，从试春官卿。
帝城岐路多，万足伺晨星。
茫茫风尘中，工拙同有营。
寒女劳夜织，山苗荣寸茎。
侯门方击钟，衣褐谁将迎。
弱羽果摧颓，壮心郁怦怦。
谅无蟠木容，聊复蓬累行。
昨日讯灵龟，繇言利艰贞。
当求舍拔中，必在审已明。
誓将息薄游，焦思穷笔精。
莳兰在幽渚，安得扬芬馨。
曰余摧落者，散质负华缨。
一聆苦辛词，再动伊郁情。
身弃言不动，爱才心尚惊。
恨无羊角风，使尔化北溟。
论罢情益亲，涉旬忘归程。
日携邑中客，闲眺江上城。
昼憩命金罍，宵谈转璇衡。
薰风香麈尾，月露濡桃笙。
忽被戒羸骖，薄言事南征。
火云蔚千里，旅思浩已盈。
湘江含碧虚，衡岭浮翠晶。
岂伊山水异，适与人事并。
油幕侣昆丘，粲然叠瑶琼。
庾楼见清月，孔坐多绿醽。
复有衡山守，本自云龙庭。
抗志在灵府，发越侔咸英。
一挥出荥阳，惠彼嗤嗤氓。
隼旟辞灞水，居者皆涕零。
惟昔与伊人，交欢经宿龄。
一从云雨散，滋我鄙吝萌。
北渚不堪愁，南音谁复听。
离忧若去水，浩漾无时停。
尝闻祝融峰，上有神禹铭。
古石琅玕姿，秘文螭虎形。
圣功奠远服，神物拥休祯。
贤人在其下，彷佛疑蓬瀛。
君行历郡斋，大袂拂双旌。
饰容遇朗鉴，肝鬲可以呈。
昔日马相如，临邛坐尽倾。
勉君刷羽翰，蚤取凌青冥。','',''),('quantangshi-18761','送张盥赴举诗','劉禹錫','quantangshi','','卷19','尔生始悬弧，我作座上宾。
引箸举汤饼，祝词天麒麟。
今成一丈夫，坎坷愁风尘。
长裾来谒我，自号庐山人。
道旧与抚孤，悄然伤我神。
依依见眉睫，嘿嘿含悲辛。
永怀同年友，追想出谷晨。
三十二君子，齐飞凌烟旻。
曲江一会时，后会已凋沦。
况今三十载，阅世难重陈。
盛时一已过，来者日日新。
不如摇落树，重有明年春。
火后见琮璜，霜余识松筠。
肃风乃独秀，武部亦绝伦。
尔今持我诗，西见二重臣。
成贤必念旧，保贵在安贫。
清时为丞郎，气力侔陶钧。
乞取斗升水，因之云汉津。','',''),('quantangshi-18762','和州送钱侍御自宣州幕拜官便于华州觐省','劉禹錫','quantangshi','','卷19','五彩绣衣裳，当年正相称。
春风旧关路，归去真多兴。
兰陔行可采，莲府犹回瞪。
杨家绀幰迎，谢守瑶华赠。
御街草泛灧，台柏烟含凝。
曾是平生游，无因理归乘。','',''),('quantangshi-18763','送僧方及南谒柳员外','劉禹錫','quantangshi','','卷19','昔事庐山远，精舍虎溪东。
朝阳照瀑水，楼阁虹霓中。
骋望羡游云，振衣若秋蓬。
旧房闭松月，远思吟江风。
古寺历头陀，奇峰扳祝融。
南登小桂岭，却望归塞鸿。
衣裓贮文章，自言学雕虫。
抢榆念陵厉，覆篑图穹崇。
远郡多暇日，有诗访禅宫。
石门耸峭绝，竹院含空蒙。
幽响滴岩溜，晴芳飘野丛。
海云悬飓母，山果属狙公。
忽忆吴兴郡，白苹正葱茏。
愿言挹风采，邈若窥华嵩。
桂水夏澜急，火山宵焰红。
三衣濡菌露，一锡飞烟空。
勿谓翻译徒，不为文雅雄。
古来赏音者，燋爨得孤桐。','',''),('quantangshi-18764','送惟良上人','劉禹錫','quantangshi','','卷19','高斋洒寒水，是夕山僧至。
玄牝无关锁，琼书舍文字。
灯明香满室，月午霜凝地。
语到不言时，世间人尽睡。','',''),('quantangshi-18765','翠微寺有感','劉禹錫','quantangshi','','卷19','吾王昔游幸，离宫云际开。
朱旗迎夏早，凉轩避暑来。
汤饼赐都尉，寒冰颁上才。
龙髯不可望，玉座生尘埃。','',''),('quantangshi-18766','观柘枝舞二首 一','劉禹錫','quantangshi','','卷19','胡服何葳蕤，仙仙登绮墀。
神飙猎红蕖，龙烛暎金枝。
垂带覆纤腰，安钿当妩眉。
翘袖中繁鼓，倾眸遡华榱。
燕秦有旧曲，淮南多冶词。
欲见倾城处，君看赴节时。','',''),('quantangshi-18767','观柘枝舞二首 二','劉禹錫','quantangshi','','卷19','山鸡临清镜，石燕赴遥津。
何如上客会，长袖入华裀。
体轻似无骨，观者皆耸神。
曲尽回身处，层波犹注人。','',''),('quantangshi-18768','连州腊日观莫徭腊西山','劉禹錫','quantangshi','','卷19','海天杀气薄，蛮军步伍嚣。
林红叶尽变，原黑草初烧。
围合繁钲息，禽兴大斾摇。
张罗依道口，嗾犬上山腰。
猜鹰虑奋迅，惊鹿时局跳。
瘴云四面起，腊雪半空消。
箭头余鹄血，鞍傍见雉翘。
日暮还城邑，金笳发丽谯。','',''),('quantangshi-18769','寄陕州姚中丞','劉禹錫','quantangshi','','卷19','八月天气肃，二陵风雨收。
旌旗阙下来，云日关东秋。
禹迹想前事，汉台余故丘。
俳徊襟带地，左右帝王州。
留滞悲昔老，恩光荣彻侯。
相思望棠树，一寄商声讴。','',''),('quantangshi-18770','奉酬湖州崔郎中见寄五韵','劉禹錫','quantangshi','','卷19','山阳昔相遇，灼灼晨葩鲜。
同游翰墨场，和乐埙箎然。
一落名宦途，浩如乘风船。
行当衰暮日，卧理淮海边。
犹期谢病后，共乐桑榆年。','',''),('quantangshi-18771','学阮公体三首 一','劉禹錫','quantangshi','','卷19','少年负志气，信道不从时。
只言绳自直，安知室可欺。
百胜难虑敌，三折乃良医。
人生不失意，焉能慕知己。','',''),('quantangshi-18772','学阮公体三首 二','劉禹錫','quantangshi','','卷19','朔风悲老骥，秋霜动鸷禽。
出门有远道，平野多层阴。
灭没驰绝塞，振迅拂华林。
不因感衰节，安能激壮心。','',''),('quantangshi-18773','学阮公体三首 三','劉禹錫','quantangshi','','卷19','昔贤多使气，忧国不谋身。
目览千载事，心交上古人。
侯门有仁义，灵台多苦辛。
不学腰如磬，徒使甑生尘。','',''),('quantangshi-18774','秋晚题湖城驿池上亭','劉禹錫','quantangshi','','卷19','秋次池上馆，林塘照南荣。
尘衣纷未解，幽思浩已盈。
风莲坠故萼，露菊含晚英。
恨为一夕客，愁听晨鸡鸣。','',''),('quantangshi-18775','贾客词','劉禹錫','quantangshi','','卷19','贾客无定游，所游唯利并。
眩俗杂良苦，乘时取重轻。
心计析秋毫，摇钩侔悬衡。
锥刀既无弃，转化日已盈。
邀福祷波神，施财游化城。
妻约雕金钏，女垂贯珠缨。
高赀比封君，奇货通幸卿。
趋时鸷鸟思，藏镪盘龙形。
大艑浮通川，高楼次旗亭。
行止皆有乐，关梁自无征。
农夫何为者，辛苦事寒耕。','',''),('quantangshi-18776','调瑟词','劉禹錫','quantangshi','','卷19','调瑟在张弦，弦平音自足。
朱弦二十五，缺一不成曲。
美人爱高张，瑶轸再三促。
上弦虽独响，下应不相属。
日暮声未和，寂寥一枯木。
却顾膝上弦，流泪难相续。','',''),('quantangshi-18777','读张曲江集作','劉禹錫','quantangshi','','卷19','圣言贵忠恕，至道重观身。
法在何所恨，色相斯为仁。
良时难久恃，阴谪岂无因。
寂寞韶阳庙，魂归不见人。','',''),('quantangshi-18778','偶作二首 一','劉禹錫','quantangshi','','卷19','终朝对尊酒，嗜兴非嗜甘。
终日偶众人，纵言不纵谈。
世情闲静见，药性病多谙。
寄谢嵇中散，予无甚不堪。','',''),('quantangshi-18779','偶作二首 二','劉禹錫','quantangshi','','卷19','万卷堆牀书，学者识其真。
万里长江水，征夫渡要津。
养生非但药，悟佛不因人。
燕石何须辨，逢时即至珍。','',''),('quantangshi-18780','昏镜词','劉禹錫','quantangshi','','卷19','昏镜非美金，漠然丧其晶。
陋容多自欺，谓若他镜明。
瑕疵既不见，妍态随意生。
一日四五照，自言美倾城。
饰带以纹绣，装匣以琼瑛。
秦宫岂不重，非适乃为轻。','',''),('quantangshi-18781','咏古二首有所寄 一','劉禹錫','quantangshi','','卷19','车音想辚辚，不见綦下尘。
可怜平阳第，歌舞娇青春。
金屋容色在，文园词赋新。
一朝复得幸，应知失意人。','',''),('quantangshi-18782','咏古二首有所寄 二','劉禹錫','quantangshi','','卷19','寂寥照镜台，遗基古南阳。
真人昔来游，翠凤相随翔。
目成在桑野，志遂贮椒房。
岂无三千女，初心不可忘。','',''),('quantangshi-18783','磨镜篇','劉禹錫','quantangshi','','卷19','流尘翳明镜，岁久看如漆。
门前负局人，为我一磨拂。
萍开绿池满，晕尽金波溢。
白日照空心，圆光走幽室。
山神妖气沮，野魅真形出。
却思未磨时，瓦砾来唐突。','',''),('quantangshi-18784','登司马错古城','劉禹錫','quantangshi','','卷19','将军将秦师，西南奠遐服。
故垒清江上，苍烟晦乔木。
登临直萧辰，周览壮前躅。
堑平陈叶满，墉高秋蔓绿。
废井抽寒菜，毁台生鲁谷。
耕人得古器，宿雨多遗镞。
楚塞郁重叠，蛮溪纷诘曲。
留此数仞基，几人伤远目。','',''),('quantangshi-18785','谒柱山会禅师','劉禹錫','quantangshi','','卷19','我本山东人，平生多感慨。
弱冠游咸京，上书金马外。
结交当世贤，驰声溢四塞。
勉修贵及早，狃捷不知退。
锱铢扬芬馨，寻尺招瑕纇。
淹留郢南都，摧颓羽翰碎。
安能咎往事，且欲去沈痗。
吾师得真如，寄在人寰内。
哀我堕名网，有如翾飞辈。
瞳瞳揭智烛，照使出昏昧。
静见玄关启，歆然初心会。
夙尚一何微，今得信可大。
觉路明证入，便门通忏悔。
悟理言自忘，处屯道犹泰。
色身岂吾宝，慧性非形碍。
思此灵山期，未卜何年载。','',''),('quantangshi-18786','卧病闻常山旋师策勋宥过王泽大洽因寄李六侍郎','劉禹錫','quantangshi','','卷19','寂寂重寂寂，病夫卧秋斋。
夜蛩思幽壁，槁叶鸣空堦。
南国异气候，火旻尚昏霾。
瘴烟跕飞羽，沴气伤百骸。
昨闻凯歌旋，饮至酒如淮。
无战陋丹水，垂仁轻槀街。
清庙既策勋，圆丘俟燔柴。
车书一以混，幽远靡不怀。
逐客顦顇久，故乡云雨乖。
禽鱼各有化，予欲问齐谐。','',''),('quantangshi-18787','善卷坛下作','劉禹錫','quantangshi','','卷19','先生见尧心，相与去九有。
斯民既已治，我得安林薮。
道为自然贵，名是无穷寿。
瑶坛在此山，识者常回首。','',''),('quantangshi-18788','武陵观火诗','劉禹錫','quantangshi','','卷19','楚乡祝融分，炎火常为虞。
是时直突烟，发自晨炊徒。
盲风扇其威，白昼曛阳鸟。
操绠不暇汲，循墙还避逾。
怒如列缺光，迅与芬轮俱。
联延掩四远，赫弈成洪炉。
汹疑云涛翻，飒若鬼神趋。
当前迎惞𨹮，是物同膏腴。
金乌入梵天，赤龙游玄都。
腾烟透窻户，飞焰生栾栌。
火山摧半空，星雨洒中衢。
瑶坛被髹漆，宝树攒珊瑚。
光县与琴焦，旗亭无酒濡。
市人委百货，邑令遗双凫。
余势下隈隩，长熛烘舳舻。
吹焚照水府，炙浪愁天吴。
灾罢云日晚，心惊视听殊。
高灰辨廪庾，黑土连闉闍。
众烬合星罗，游氛铄人肤。
厚地藏宿热，遥林呈骤枯。
火德资生人，庸可一日无。
御之失其道，敲石弥天隅。
晋库走龙劒，吴宫伤燕雏。
五行有沴气，先哲垂訏谟。
宋郑同日起，时当贤大夫。
无苛自可乐，弭患非所图。
贤守恤人瘼，临烟驻骊驹。
吊场色惨忸，颜失词劬愉。
下令蠲里布，指期轻市租。
閈垣适未立，苫盖自相娱。
山木行剪伐，江泥宜墐途。
邑臣不必曾，何用征越巫。','',''),('quantangshi-18789','崔元受少府自贬所还遗山姜花以诗答之','劉禹錫','quantangshi','','卷19','故人博罗尉，遗我山姜花。
采从碧海上，来自谪仙家。
云涛润孤根，阴火照晨葩。
静摇扶桑日，艳对瀛洲霞。
世人爱芳辛，搴撷忘幽遐。
传名入帝里，飞驿辞天涯。
王济本尚味，石崇方鬬奢。
雕盘多不识，绮席乃增华。
驿马损筋骨，贵人滋齿牙。
顾予藜藿士，持此重咨嗟。','',''),('quantangshi-18790','途中早发','劉禹錫','quantangshi','','卷19','马踏尘上霜，月明江头路。
行人朝气锐，宿鸟相辞去。
流水隔远村，缦山多红树。
悠悠关塞内，往来无闲步。','',''),('quantangshi-18791','和董庶中古散调词赠尹果毅','劉禹錫','quantangshi','','卷19','昔听东武吟，壮年心已悲。
如何今濩落，闻君辛苦辞。
言有穷巷士，弱龄颇尚奇。
读得玄女符，生当事边时。
借名游侠窟，结客幽并儿。
往来长楸间，能带双鞬驰。
崩腾天宝末，尘暗燕南垂。
爟火入咸阳，诏征神武师。
是时占军幕，插羽扬金羁。
万夫列辕门，观射中戟支。
誓当雪国讐，亲爱从此辞。
中宵倚长劒，起视蚩尤旗。
介马晨萧萧，阵云竟天涯。
阴风猎白草，旗槊光参差。
勇气贯中肠，视身忽如遗。
生擒白马将，虏骑不敢追。
贵臣上战功，名姓随意移。
终岁肌骨苦，他人印累累。
谒者既清宫，诸侯各罢戏。
上将赐甲第，门戟不可窥。
眦血下沾襟，天高问无期。
却寻故乡路，孤影空相随。
行逢里中旧，扑遬昔所嗤。
一言合侯王，腰佩黄金龟。
问我何自苦，可怜真数奇。
迟回顾徒御，得色悬双眉。
翻然悟世途，抚己昧所宜。
田园已芜没，流浪江海湄。
鸷禽毛翮摧，不见翔云姿。
衰容蔽逸气，孑孑无人知。
寂寞草玄徒，长吟下书帷。
为君发哀韵，若扣瑶林枝。
有客识其真，潺湲涕交颐。
饮尔一杯酒，陶然足自怡。','',''),('quantangshi-18792','望衡山','劉禹錫','quantangshi','','卷19','东南倚盖卑，维岳资柱石。
前当祝融居，上拂朱鸟翮。
青冥结精气，磅礴宣地脉。
还闻肤寸阴，能致弥天泽。','',''),('quantangshi-18793','游桃源一百韵','劉禹錫','quantangshi','','卷19','沅江清悠悠，连山郁岑寂。
回流抱绝巘，皎镜含虚碧。
昏旦递明媚，烟岚分委积。
香蔓垂绿潭，暴龙照孤碛。
渊明着前志，子骥思远跖。
寂寂无何乡，密尔天地隔。
金行太元岁，渔者偶探赜。
寻花得幽踪，窥洞穿暗隙。
依微闻鸡犬，豁达值阡陌。
居人互将迎，笑语如平昔。
广乐虽交奏，海禽心不怿。
挥手一来归，故溪无处觅。
绵绵五百载，市朝几迁革。
有路在壶中，无人知地脉。
皇家感至道，圣祚自天锡。
金阙传本枝，玉函留宝历。
禁山开秘宇，复户洁灵宅。
蘂检香氛氲，醮坛烟幂幂。
我来尘外躅，莹若朝星析。
崖转对翠屏，水穷留画鷁。
三休俯乔木，千级扳峭壁。
旭日闻撞钟，彩云迎蹑屐。
遂登最高顶，纵目还楚泽。
平湖见草青，远岸连霞赤。
幽寻如梦想，绵思属空阒。
夤缘且忘疲，耽玩近成癖。
清猨伺晓发，瑶草凌寒坼。
祥禽舞葱茏，珠树摇玓瓅。
羽人顾我笑，劝我税归轭。
霓裳何飘颻，童颜洁白皙。
重岩是藩屏，驯鹿受羁靮。
楼居弥清霄，萝茑成翠帟。
仙翁遗竹杖，王母留桃核。
姹女飞丹砂，青童护金液。
宝气浮鼎耳，神光生劒脊。
虚无天乐来，僁窣鬼兵役。
丹丘肃朝礼，玉札工䌷绎。
枕中淮南方，牀下阜乡舄。
明灯坐遥夜，幽籁听淅沥。
因话近世仙，耸然心神惕。
乃言瞿氏子，骨状非凡格。
往事黄先生，羣儿多侮剧。
謷然不屑意，元气贮肝膈。
往往游不归，洞中观博弈。
言高未易信，犹复加诃责。
一旦前致辞，自云仙期迫。
言师有道骨，前事常被谪。
如今三山上，名字在真籍。
悠然谢主人，后岁当来觌。
言毕依庭树，如烟去无迹。
观者皆失次，惊追纷络绎。
日暮山径穷，松风自萧槭。
适逢修蛇见，瞋目光激射。
如严三清居，不使恣搜索。
唯余步纲势，八趾在沙砾。
至今东北隅，表以坛上石。
列仙徒有名，世人非目击。
如何庭庑际，白日振飞翮。
洞天岂幽远，得道如咫尺。
一气无死生，三光自迁易。
因思人间世，前路何狭窄。
瞥然此生中，善祝期满百。
大方播羣类，秀气肖翕辟。
性静本同和，物牵成阻厄。
是非鬬方寸，荤血昏精魄。
遂令多夭伤，犹喜见斑白。
喧喧车马驰，苒苒桑榆夕。
共安缇绣荣，不悟泥途适。
纷吾本孤贱，世业在逢掖。
九流宗指归，百氏旁捃摭。
公卿偶慰荐，乡曲缪推择。
居安白社贫，至傲玄纁辟。
功名希自取，簪组俟扬历。
书府蚤怀铅，射宫曾发的。
起草香生帐，坐曹乌集柏。
赐燕聆箫韶，侍祠阅琮璧。
尝闻履忠信，可以行蛮貊。
自述希古心，忘恃干时画。
巧言忽成锦，苦志徒食蘖。
平地生峰峦，深心有矛戟。
层波一震荡，弱植忽沦溺。
北渚吊灵均，长岑思亭伯。
祸来昧几兆，事去空叹息。
尘累与时深，流年随漏滴。
才能疑木雁，报施迷夷跖。
楚奏絷钟仪，商歌劳甯戚。
禀生非悬解，对镜方感激。
自从婴网罗，每事问龟策。
王正降雷雨，环玦赐迁斥。
倘伏夷平人，誓将依羽客。
买山构精舍，领徒开讲席。
冀无身外忧，自有闲中益。
道芽期日就，尘虑乃冰释。
且欲遗姓名，安能慕竹帛。
长生尚学致，一溉岂虚掷。
芝术资糇粮，烟霞拂巾帻。
黄石履看堕，洪崖肩可拍。
聊复嗟蜉蝣，何烦哀虺蜴。
青囊既深味，琼葩亦屡摘。
纵无西山资，犹免长戚戚。','',''),('quantangshi-18794','客有为余话登天坛遇雨之状因以赋之','劉禹錫','quantangshi','','卷19','清晨登天坛，半路逢阴晦。
疾行穿雨过，却立视云背。
白日照其上，风雷走于内。
滉漾雪海翻，槎牙玉山碎。
蛟龙露鬐鬣，神鬼含变态。
万状互生灭，百音以繁会。
俯观羣动静，始觉天宇大。
山顶自晶明，人间已霶霈。
豁然重昏歛，涣若春冰溃。
反照入松门，瀑流飞缟带。
遥光泛物色，余韵吟天籁。
洞府撞仙钟，村墟起夕霭。
却见山下侣，已如迷世代。
问我何处来，我来云雨外。','',''),('quantangshi-18795','秋江早发','劉禹錫','quantangshi','','卷19','轻阴迎晓日，霞霁秋江明。
草树含远思，襟怀有余清。
凝睇万象起，郎吟孤愤平。
渚鸿未矫翼，而我已遐征。
因思市朝人，方听晨鸡鸣。
昏昏恋衾枕，安见元气英。
纳爽耳目变，玩奇筋骨轻。
沧洲有奇趣，浩然吾将行。','',''),('quantangshi-18796','有僧言罗浮事因为诗以写之','劉禹錫','quantangshi','','卷19','君言罗浮上，容易见九垠。
渐高元气壮，汹涌来翼身。
夜宿最高峰，瞻望浩无邻。
海黑天宇旷，星辰来逼人。
是时当朏魄，阴物恣腾振。
日光吐鲸背，劒影开龙鳞。
倏若万马驰，旌旗耸奫沦。
又如广乐奏，金石含悲辛。
疑其有巨灵，怪物尽来宾。
阴阳迭用事，乃俾夜作晨。
咿喔天鸡鸣，扶桑色昕昕。
赤波千万里，涌出黄金轮。
下视生物息，霏如隙中尘。
醯鸡仰瓮口，亦谓云汉津。
世人信耳目，方寸度大钧。
安知视听外，怪愕不可陈。
悠悠想大方，此乃杯水滨。
知小天地大，安能识其真。','',''),('quantangshi-18797','裴祭酒尚书见示春归城南青松坞别墅寄王左丞高侍郎之什命同作','劉禹錫','quantangshi','','卷19','蚤宦阅人事，晚怀生道机。
时从学省出，独望郊园归。
野彴度春水，山花映岩扉。
石头解金章，林下步绿薇。
青松郁成坞，修竹盈尺围。
吟风起天籁，蔽日无炎威。
危径盘羊肠，连甍耸翚飞。
幽谷响樵斧，澄潭环钓矶。
因高见帝城，冠盖扬光辉。
白云难持寄，清韵投所希。
二公如长离，比翼翔太微。
含情谢林壑，酬赠骈珠玑。
顾予久郎潜，愁寂对芳菲。
一闻丘中趣，再抚黄金徽。','',''),('quantangshi-18798','和河南裴尹侍郎宿斋天平寺诣九龙祠祈雨二十韵','劉禹錫','quantangshi','','卷19','有事九龙庙，洁斋梵王祠。
玉箫何时绝，碧树空凉飔。
吏散埃𡏖息，月高庭宇宜。
重城肃穆闭，涧水潺湲时。
人希夜复闲，虑静境亦随。
缅怀断鳌足，凝想乘鸾姿。
朱明盛农节，膏泽方愆期。
瞻言五灵瑞，能救百谷萎。
咿喔晨鸡鸣，阑干斗柄垂。
修容谒神像，注意陈正词。
惊飙起泓泉，若调雷雨师。
黑烟耸鳞甲，洒液如棼丝。
丰隆震天衢，列缺挥火旗。
炎空忽凄紧，高溜悬绠縻。
生物已霶霈，湿云稍离披。
丹霞启南陆，白水含东菑。
熙熙飞走适，蔼蔼草树滋。
浮光动宫观，远思盈川坻。
吴公敏于政，谢守工为诗。
商山有病客，言贺舒庞眉。','',''),('quantangshi-18799','冬夜宴河中李相公中堂命筝歌送酒','劉禹錫','quantangshi','','卷19','朗朗鵾鸡弦，华堂夜多思。
帘外雪已深，座中人半醉。
翠蛾发清响，曲尽有余意。
酌我莫忧狂，老来无逸气。','',''),('quantangshi-18800','重至衡阳伤柳仪曹','劉禹錫','quantangshi','','卷19','忆昨与故人，湘江岸头别。
我马映林嘶，君帆转山灭。
马嘶循古道，帆灭如流电。
千里江蓠春，故人今不见。','',''),('quantangshi-18801','谪居悼往二首 一','劉禹錫','quantangshi','','卷19','邑邑何邑邑，长沙地卑湿。
楼上见春多，花前恨风急。
猿愁肠断呌，鹤病翘趾立。
牛衣独自眠，谁哀仲卿泣。','',''),('quantangshi-18802','谪居悼往二首 二','劉禹錫','quantangshi','','卷19','郁郁何郁郁，长安远如日。
终日念乡关，燕来鸿复还。
潘岳岁寒思，屈平顦顇颜。
殷勤望归路，无雨即登山。','',''),('quantangshi-18803','有獭吟','劉禹錫','quantangshi','','卷19','有獭得嘉鱼，自谓天见怜。
先祭不敢食，捧鳞望青玄。
人立寒沙上，心专眼悁悁。
渔翁以为妖，举块投其咽。
呼儿贯鱼归，与獭同烹煎。
关关黄金鹗，大[翅]摇江烟。
下见盈寻鱼，投身擘洪连。
攫拏隐鳞去，哺雏林岳巅。
鸱乌欲伺隙，遥噪莫敢前。
长居青云路，弹射无由缘。
何地无江湖，何水无鲔鳣。
天意不宰割，菲祭徒虔虔。
空余知礼重，载在淹中篇。','',''),('quantangshi-18804','白太守行','劉禹錫','quantangshi','','卷19','闻有白太守，抛官归旧溪。
苏州十万户，尽作婴儿啼。
太守驻行舟，阊门草萋萋。
挥袂谢啼者，依然两眉低。
朱户非不崇，我心如重狴。
华池非不清，意在寥廓栖。
夸者窃所怪，贤者默思齐。
我为太守行，题在隐起圭。','',''),('quantangshi-18805','乐天寄洛下新诗兼喜微之欲到因以抒怀也','劉禹錫','quantangshi','','卷19','松间风未起，万叶不自吟。
池上月未来，清辉同夕阴。
宫征不独运，埙篪自相寻。
一从别乐天，诗思日已沈。
吟君洛中作，精绝百炼金。
乃知孤鹤情，月露为知音。
微之从东来，威凤鸣归林。
羡君先相见，一豁平生心。','',''),('quantangshi-18806','月夜忆乐天兼寄微之','劉禹錫','quantangshi','','卷19','今宵帝城月，一望雪相似。
遥想洛阳城，清光正如此。
知君当此夕，亦望镜湖水。
展转相忆心，月明千万里。','',''),('quantangshi-18807','早夏郡中书事','劉禹錫','quantangshi','','卷19','水禽渡残月，飞雨洒高城。
华堂对嘉树，帘庑含晓清。
拂镜整危冠，振衣步前楹。
将吏俨成列，簿书纷来萦。
言下辨曲直，笔端破交争。
虚怀询病苦，怀律操剽轻。
阍吏告无事，归来解簪缨。
高帘覆朱阁，忽尔闻调笙。','',''),('quantangshi-18808','酬乐天七月一日夜即事见寄','劉禹錫','quantangshi','','卷19','夜树风韵清，天河云彩轻。
故苑多露草，隔城闻鹤鸣。
摇落从此始，别离含远情。
闻君当是夕，倚瑟吟商声。
外物岂不足，中怀向谁倾。
秋来念归去，同听嵩阳笙。','',''),('quantangshi-18809','令狐相公见示赠竹二十韵仍命继和','劉禹錫','quantangshi','','卷19','高人必爱竹，寄兴良有以。
峻节可临戎，虚心宜待士。
众芳信妍媚，威凤难栖止。
遂于鼙鼓间，移植东南美。
封以梁国土，浇之浚泉水。
得地色不移，凌空势方起。
新青排故叶，余粉笼疎理。
犹复隔墙藩，何因出尘滓。
兹辰去前蔽，永日劳瞪视。
槭槭林已成，荧荧玉相似。
规摹起心匠，洗涤在颐指。
曲直既瞭然，孤高何卓尔。
垂梢覆内屏，迸笋侵前戺。
妓席拂云鬓，宾阶荫珠履。
抱琴恣闲翫，执卷堪斜倚。
露下悬明璫，风来韵清征。
坚贞贯四候，标格殊百卉。
岁晚当自知，繁华岂云比。
古诗无赠竹，高唱从此始。
一听清瑶音，峥然长在耳。','',''),('quantangshi-18810','和令狐相公晚泛汉江书怀寄洋州崔侍郎阆州高舍人二曹长','劉禹錫','quantangshi','','卷19','雨过远山出，江澄暮霞生。
因浮济川舟，遂作适野行。
郊树映缇骑，水禽避红旌。
田夫捐畚锸，织妇窥柴荆。
古岸夏花发，遥林晚蝉清。
沿洄方翫境，鼓角已登城。
部内有良牧，望中寄深情。
临觞念佳期，泛瑟动离声。
寂寞一病士，夙昔接羣英。
多谢谪仙侣，几时还玉京。','',''),('quantangshi-18811','和乐天洛城春齐梁体八韵','劉禹錫','quantangshi','','卷19','帝城宜春入，游人喜意长。
草生季伦谷，花出莫愁坊。
断云发山色，轻风漾水光。
楼前戏马地，树下鬬鸡场。
白头自为侣，绿酒亦满觞。
潘园观种植，谢墅阅池塘。
至闲似隐逸，过老不悲伤。
相问焉功德，银黄游故乡。','',''),('quantangshi-18812','洛中早春赠乐天','劉禹錫','quantangshi','','卷19','漠漠复霭霭，半晴将半阴。
春来自何处，无迹日以深。
韶嫩冰后木，轻盈烟际林。
藤生欲有托，柳弱不自任。
花意已含蓄，鸟言尚沈吟。
期君当此时，与我恣追寻。
翻愁烂熳后，春暮却伤心。','',''),('quantangshi-18813','和乐天宴李周美中丞宅池上赏樱桃花','劉禹錫','quantangshi','','卷19','樱桃千万枝，照耀如雪天。
王孙宴其下，隔水疑神仙。
宿露发清香，初阳动暄妍。
妖姬满髻插，酒客折枝传。
同此赏芳月，几人有华筵。
杯行勿遽辞，好醉逸三年。','',''),('quantangshi-18814','酬乐天闻新蝉见赠','劉禹錫','quantangshi','','卷19','碧树鸣蝉后，烟云改容光。
瑟然引秋气，芳草日夜黄。
夹道喧古槐，临池思垂杨。
离人下忆泪，志士激刚肠。
昔闻阻山川，今听同匡牀。
人情便所遇，音韵岂殊常。
因之比笙竽，送我游醉乡。','',''),('quantangshi-18815','和乐天秋凉闲卧','劉禹錫','quantangshi','','卷19','暑退人体轻，雨余天色改。
荷珠贯索断，竹粉残妆在。
高僧扫室请，逸客登楼待。
槐柳渐萧疎，闲门少光彩。','',''),('quantangshi-18816','酬乐天咏老见示','劉禹錫','quantangshi','','卷19','人谁不愿老，老去有谁怜。
身瘦带频减，髪稀冠自偏。
废书缘惜眼，多炙为随年。
经事还谙事，阅人如阅川。
细思皆幸矣，下此便翛然。
莫道桑榆晚，微霞尚满天。','',''),('quantangshi-18817','岁夜咏怀','劉禹錫','quantangshi','','卷19','弥年不得意，新岁又如何。
念昔同游者，而今有几多。
以闲为自在，将寿补蹉跎。
春色无情故，幽居亦见过。','',''),('quantangshi-18818','酬牛相公独饮偶醉寓言见示','劉禹錫','quantangshi','','卷19','宫漏夜丁丁，千门闭霜月。
华堂列红烛，丝管静中发。
歌眉低有思，舞体轻无骨。
主人启酡颜，酣畅浃肌髪。
犹思城外客，阡陌不可越。
春意日夕深，此欢无断绝。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-18819','萋兮吟','劉禹錫','quantangshi','','卷19','天涯浮云生，争蔽日月光。
穷巷秋风起，先摧兰蕙芳。
万货列旗亭，恣心注明璫。
名高毁所集，言巧智难防。
勿谓行大道，斯须成太行。
莫吟萋兮什，徒使君子伤。','',''),('quantangshi-18820','韩十八侍御见示岳阳楼别窦司直诗因令属和重以自述故足成六十二韵','劉禹錫','quantangshi','','卷19','楚望何苍然，曾澜七百里。
孤城寄远目，一写无穷已。
荡漾浮天盖，四环宣地理。
积涨在三秋，混成非一水。
冬游见清浅，春望多洲沚。
云锦远沙明，风烟青草靡。
火星忽南见，月硖方东迤。
雪波西山来，隐若长城起。
独专朝宗路，驶悍不可止。
支川让其威，蓄缩至南委。
熊武走蛮落，潇湘来奥鄙。
炎蒸动泉源，积潦搜山趾。
归往无旦夕，包含通远迩。
行当白露时，眇视秋光里。
曙色未昭晰，露华遥斐衅。
浩尔神骨清，如观混元始。
北风忽震荡，惊浪迷津涘。
怒激鼓铿訇，蹙成山岿硊。
鵾鹏疑变化，罔象何恢诡。
嘘吸写楼台，腾骧露鬐尾。
景移羣动息，波静繁音弭。
明月出中央，青天绝纤滓。
素光淡无际，绿静平如砥。
空影渡鵷鸿，秋声思芦苇。
鲛人弄机杼，贝阙骈红紫。
珠蛤吐玲珑，文鳐翔旖旎。
水乡吴蜀限，地势东南庳。
翼轸粲垂精，衡巫屹环峙。
名雄七泽薮，国辨三苗氏。
唐羿断修虵，荆王惮青兕。
秦狩迹犹在，虞巡路从此。
轩后奏宫商，骚人咏兰芷。
茅岭潜相应，橘洲傍可指。
郭璞验幽经，罗含着前纪。
观津戚里族，按道侯家子。
联袂登高楼，临轩笑相视。
假守亦高卧，墨曹正垂耳。
契阔话凉温，壶觞慰迁徙。
地偏山水秀，客重杯盘侈。
红袖花欲然，银灯昼相似。
兴酣更抵掌，乐极同启齿。
笔锋不能休，藻思一何绮。
伊余负微尚，夙昔慙知己。
出入金马门，交结青云士。
袭芳践兰室，学古游槐市。
策慕宋前军，文师汉中垒。
陋容昧俯仰，孤志无依倚。
卫足不如葵，漏川空叹蚁。
幸逢万物泰，独处穷途否。
锻翮重叠伤，兢魂再三褫。
蘧瑷亦屡化，左丘犹有耻。
桃源访仙宫，薜服祠山鬼。
故人南台旧，一别如弦矢。
今朝会荆峦，斗酒相宴喜。
为余出新什，笑拚随伸纸。
晔若观五色，欢然臻四美。
委曲风涛事，分明穷达旨。
洪韵发华钟，凄音激清征。
羊浚要共和，江淹多杂拟。
徒欲仰高山，焉能追逸轨。
湘洲路四达，巴陵城百雉。
何必颜光禄，留诗张内史。','',''),('quantangshi-18821','和郴州杨侍郎翫郡斋紫薇花十四韵','劉禹錫','quantangshi','','卷19','几年丹霄上，出入金华省。
暂别万年枝，看花桂阳岭。
南方足奇树，公府成佳境。
绿阴交广除，明艳透萧屏。
雨余人吏散，燕语帘栊静。
懿此含晓芳，翛然忘簿领。
紫茸垂组缕，金[缕]攒锋頴。
露溽暗传香，风轻徐就影。
苒弱多意思，从容占光景。
得地在侯家，移根近仙井。
开尊好凝睇，倚瑟仍回颈。
游蜂驻彩冠，舞鹤迷烟顶。
兴生红药后，爱与甘棠并。
不学夭桃姿，浮荣在俄顷。','',''),('quantangshi-18822','春日寄杨八唐州二首 一','劉禹錫','quantangshi','','卷19','淮西春草长，淮水逶迤光。
燕入新村落，人耕旧战场。
可怜行春守，立马看斜桑。','',''),('quantangshi-18823','春日寄杨八唐州二首 二','劉禹錫','quantangshi','','卷19','漠漠淮上春，莠苗生故垒。
梨花方城路，荻笋萧陂水。
高斋有谪仙，坐啸清风起。','',''),('quantangshi-18824','酬冯十七舍人宿卫赠别五韵','劉禹錫','quantangshi','','卷19','少年为别日，隋宫杨柳阴。
白首相逢处，巴江烟浪深。
使星上三蜀，春雨霑衣襟。
王程促速意，夜语殷勤心。
却归天上去，遗我云间音。','',''),('quantangshi-18825','酬湖州崔郎中见寄','劉禹錫','quantangshi','','卷19','风筝吟秋空，不肖指爪声。
高人灵府间，律吕伴咸英。
昔年与兄游，文似马长卿。
今来寄新诗，乃类陶渊明。
磨砻老益智，吟咏闲弥精。
岂非山水乡，荡漾神机清。
渚烟蕙兰动，溪雨虹霓生。
冯君虚上舍，待余乘兴行。','',''),('quantangshi-18826','秋日书怀寄河南王尹','劉禹錫','quantangshi','','卷19','公府想无事，西池秋水清。
去年为狎客，永日奉高情。
况有台上月，如闻云外笙。
不知桑落酒，今岁与谁倾。','',''),('quantangshi-18827','酬留守牛相公宫城早秋寓言见寄','劉禹錫','quantangshi','','卷19','晓月映宫树，秋光起天津。
凉风稍动叶，宿露未生尘。
星气尚芳丽，旷望感心神。
挥毫成逸韵，开合迟来宾。
摆去将相印，渐为逍遥身。
如招后房宴，却要白头人。','',''),('quantangshi-18828','海阳十咏 吏隐亭','劉禹錫','quantangshi','','卷19','结构得奇势，朱门交碧浔。
外来始一望，写尽平生心。
日轩漾波影，月砌镂松阴。
几度欲归去，回眸情更深。','',''),('quantangshi-18829','海阳十咏 切云亭','劉禹錫','quantangshi','','卷19','逈破林烟出，俯窥石潭空。
波摇杏梁日，松韵碧窻风。
隔水生别岛，带桥如断虹。
九疑南面事，尽入寸眸中。','',''),('quantangshi-18830','海阳十咏 云英潭','劉禹錫','quantangshi','','卷19','芳幄覆云屏，石奁开碧镜。
支流日飞洒，深处自疑莹。
潜去不见迹，清音常满听。
有时病朝酲，来此心神醒。','',''),('quantangshi-18831','海阳十咏 玄览亭','劉禹錫','quantangshi','','卷19','潇洒青林际，夤缘碧潭隈。
淙流冒石下，轻波触砌回。
香风逼人度，幽花覆水开。
故令无四壁，晴夜月光来。','',''),('quantangshi-18832','海阳十咏 裴溪','劉禹錫','quantangshi','','卷19','楚客忆关中，疏溪想汾水。
萦纡非一曲，意态如千里。
倒影罗文动，微波笑颜起。
君今赐环归，何人承玉趾。','',''),('quantangshi-18833','海阳十咏 飞练瀑','劉禹錫','quantangshi','','卷19','晶晶掷岩端，洁光如可把。
琼枝曲不折，云片晴犹下。
石坚激清响，叶动承余洒。
前时明月中，见是银河泻。','',''),('quantangshi-18834','海阳十咏 蒙池','劉禹錫','quantangshi','','卷19','潆渟幽壁下，深净如无力。
风起不成文，月来同一色。
地灵草木瘦，人远烟霞逼。
往往疑列仙，围碁在岩侧。','',''),('quantangshi-18835','海阳十咏 棼丝瀑','劉禹錫','quantangshi','','卷19','飞流透嵌隙，喷洒如丝棼。
含晕迎初旭，翻光破夕曛。
余波遶石去，碎响隔溪闻。
却望琼沙际，逶迤见脉分。','',''),('quantangshi-18836','海阳十咏 双溪','劉禹錫','quantangshi','','卷19','流水遶双岛，碧溪相并深。
浮花拥曲处，远影落中心。
闲鹭久独立，曝龟惊复沈。
苹风有时起，满谷箫韶音。','',''),('quantangshi-18837','海阳十咏 月窟','劉禹錫','quantangshi','','卷19','溅溅漱幽石，注入团圆处。
有如常满杯，承彼清夜露。
岩曲月斜照，林寒春晚煦。
游人不敢触，恐有蛟龙护。','',''),('quantangshi-18838','武夫词','劉禹錫','quantangshi','','卷19','武夫何洸洸，衣紫袭绛裳。
借问胡为尔，列校在鹰扬。
依倚将军势，交结少年场。
探丸害公吏，抽刃妒名倡。
家产既不事，顾盼自生光。
酣歌高楼上，袒裼大道傍。
昔为编户人，秉耒甘哺糠。
今来从军乐，跃马饫膏粱。
犹思风尘起，无种取侯王。','',''),('quantangshi-18839','虎丘寺路宴','劉禹錫','quantangshi','','卷19','青林虎丘寺，林际翠微路。
立见山僧来，遥从鸟飞处。
兹峰沦宝玉，千载惟丘墓。
埋劒人空传，凿山龙已去。
扪萝披翳荟，路转夕阴遽。
虎啸崖谷寒，猿鸣松杉暮。
徘徊北楼上，海江穷一顾。
日映千里帆，鸦归万家树。
暂因惬所适，果得捐外虑。
庭暗栖还云，檐香滴甘露。
久迷空寂理，多为声华故。
永欲投此山，余生岂能悞。','',''),('quantangshi-18840','缺题','劉禹錫','quantangshi','','卷19','故人日已远，窻下尘满琴。
坐对一撙酒，恨多无力斟。
幕疎萤色逈，露重月华深。
万境与羣籁，此时情岂任。','',''),('quantangshi-18841','晚步扬子游南塘望沙尾','劉禹錫','quantangshi','','卷19','淮海多夏雨，晓来天始晴。
萧条长风至，千里孤云生。
卑湿久喧浊，搴开偶虚清。
客游广陵郡，晚出临江城。
郊外绿杨阴，江中沙屿明。
归帆翳尽日，去棹闻遗声。
乡国殊渺漫，羁心目悬旌。
悠然京华意，怅望怀远程。
薄暮大山上，翩翩双鸟征。','',''),('quantangshi-18842','和浙西李大夫晚下北固山喜径松成阴怅然怀古偶题临江亭并浙东元相公所和依本韵','劉禹錫','quantangshi','','卷19','一辞温室树，几见武昌柳。
荀谢年何少，韦平望已久。
种松夹石道，纡组临沙阜。
目览帝王州，心存股肱守。
叶动惊彩翰，波澄见頳首。
晋宋齐梁都，千山万江口。
烟散隋宫出，涛来海门吼。
风俗太伯余，衣冠永嘉后。
江长天作限，山固壤无朽。
自古称佳丽，非贤谁奄有。
八元邦族盛，万石门风厚。
天柱揭东溟，文星照北斗。
高亭一骋望，举酒共为寿。
因赋咏怀诗，远寄同心友。
禁中晨夜直，江左东西偶。
将手握兵符，儒腰盘贵绶。
颁条风有自，立事言无苟。
农野闻让耕，军人不使酒。
用材当构厦，知道宁窥牖。
谁谓青云高，鹏飞终背负。','',''),('quantangshi-18843','始至云安寄兵部韩侍郎中书白舍人二公近曾远守故有属焉','劉禹錫','quantangshi','','卷19','天外巴子国，山头白帝城。
波清蜀[柹]尽，云散楚台倾。
迅濑下哮吼，两岸势争衡。
阴风鬼神过，暴雨蛟龙生。
硖断见孤邑，江流照飞甍。
蛮军击严鼓，笮马引双旌。
望阙遥拜舞，分庭备将迎。
铜符一以合，文墨纷来萦。
暮色四山起，愁猿数处声。
重关羣吏散，静视寒灯明。
故人青霞意，飞舞集蓬瀛。
昔曾在池籞，应知鱼鸟情。','',''),('quantangshi-18844','更衣曲','劉禹錫','quantangshi','','卷19','博山炯炯吐香雾，红烛引至更衣处。
夜如何其夜漫漫，邻鸡未鸣寒雁度。
庭前雪压松桂丛，廊下点点悬纱笼。
满堂醉客争笑语，嘈囋琵琶青幕中。','',''),('quantangshi-18845','桃源行','劉禹錫','quantangshi','','卷19','渔舟何招招，浮在武陵水。
拖纶掷饵信流去，误入桃源行数里。
清源寻尽花绵绵，踏花觅径至洞前。
洞门苍黑烟雾生，暗行数步逢虚明。
俗人毛骨惊仙子，争来致词何至此。
须臾皆破冰雪颜，笑言委曲问人间。
因嗟隐身来种玉，不知人世如风烛。
筵羞石髓劝客餐，灯爇松脂留客宿。
鸡声犬声遥相闻，晓色葱茏开五云。
渔人振衣起出户，满庭无路花纷纷。
翻然恐失乡悬处，一息不肯桃源住。
桃花满溪水似镜，尘心如垢洗不去。
仙家一出寻无踪，至今流水山重重。','',''),('quantangshi-18846','洞庭秋月行','劉禹錫','quantangshi','','卷19','洞庭秋月生湖心，层波万顷如镕金。
孤轮徐转光不定，游气蒙蒙隔寒镜。
是时白露三秋中，湖平月上天地空。
岳阳楼头暮角绝，荡漾已过君山东。
山城苍苍夜寂寂，水月逶迤绕城白。
荡桨巴童歌竹枝，连樯估客吹羗笛。
势高夜久阴力全，金气肃肃开星躔。
浮云野马归四裔，遥望星斗当中天。
天鸡相呼曙霞出，歛影含光让朝日。
日出喧喧人不闲，夜来清景非人间。','',''),('quantangshi-18847','九华山歌','劉禹錫','quantangshi','','卷19','奇峰一见惊魂魄，意想洪罏始开辟。
疑是九龙夭矫欲攀天，忽逢霹雳一声化为石。
不然何至今，悠悠亿万年，气势不死如腾仚。
云含幽兮月添冷，月凝晖兮江漾影。
结根不得要路津，逈秀长在无人境。
轩皇封禅登云亭，大禹会寄临东溟。
乘樏不来广乐绝，独与猨鸟愁青荧。
君不见敬亭之山黄索漠，兀如断岸无棱角。
宣城谢守一首诗，遂使声名齐五岳。
九华山，九华山。
自是造化一尤物，焉能籍甚乎人间。','',''),('quantangshi-18848','泰娘歌','劉禹錫','quantangshi','','卷19','泰娘家本阊门西，门前绿水环金堤。
有时妆成好天气，走上臯桥折花戏。
风流太守韦尚书，路傍忽见停隼旟。
斗量明珠鸟传意，绀幰迎入专城居。
长鬟如云衣似雾，锦茵罗荐承轻步。
舞学惊鸿水榭春，歌传上客兰堂暮。
从郎西入帝城中，贵游簪组香帘栊。
低鬟缓视抱明月，纤指破拔生胡风。
繁华一旦有消歇，题剑无光履声绝。
洛阳旧宅生草莱，杜陵萧萧松柏哀。
妆奁虫网厚如茧，博山炉侧倾寒灰。
蕲州刺史张公子，白马新到铜驼里。
自言买笑掷黄金，月堕云中从此始。
安知鵩鸟座隅飞，寂寞旅魂招不归。
秦嘉镜有前时结，韩寿香销故箧衣。
山城少人江水碧，断雁哀猨风雨夕。
朱弦已绝为知音，云鬓未秋私自惜。
举目风烟非旧时，梦寻归路乡多参差。
如何将此千行泪，更洒湘江斑竹枝。','',''),('quantangshi-18849','龙阳县歌','劉禹錫','quantangshi','','卷19','县门白日无尘土，百姓县前挽鱼罟。
主人引客登大堤，小儿纵观黄犬怒。
鹧鸪惊鸣绕篱落，橘柚垂芳照窗户。
沙平草绿见吏稀，寂历斜阳照县鼓。','',''),('quantangshi-18850','墙阴歌','劉禹錫','quantangshi','','卷19','白日左右浮天潢，朝晡影入东西墙。
昔为儿童在阴戏，当时意小觉日长。
东邻侯家吹笙簧，随阴促促移象牀。
西邻田舍乏糟糠，就影汲汲舂黄粱。
因思九州四海外，家家只占墙阴内。
莫言墙阴数尺间，老却主人如等闲。
君看眼前光阴促，中心莫学太行山。','',''),('quantangshi-18851','踏潮歌','劉禹錫','quantangshi','','卷19','屯门积日无回飙，沧波不归成踏潮。
轰如鞭矻石且摇，亘空欲驾鼋鼍桥。
惊湍蹙缩悍而骄，大陵高岸失岧嶤。
四边无阻音响调，背负元气掀重霄。
介鲸得性方逍遥，仰鼻嘘吸扬朱翘。
海人狂顾迭相招，罽衣髽首声哓哓。
征南将军登丽谯，赤旗指麾不敢嚣。
翌日风回沴气消，归涛纳纳景昭昭。
乌泥白沙复满海，海色不动如青瑶。','',''),('quantangshi-18852','白鹭儿','劉禹錫','quantangshi','','卷19','白鹭儿，最高格。
毛衣新成雪不敌，众禽喧呼独凝寂。
孤眠芊芊草，久立潺潺石。
前山正无云，飞去入遥碧。','',''),('quantangshi-18853','平齐行二首 一','劉禹錫','quantangshi','','卷19','胡尘昔起蓟北门，河南地属平卢军。
貂裘代马绕东岳，峄阳孤桐削为角。
地形十二虏意骄，恩泽含容历四朝。
鲁人皆解带弓箭，齐人不复闻箫韶。
今朝天子圣神武，手握玄符平九土。
初哀狂童袭故事，文告不来方振怒。
去秋诏下诛东平，官军四合犹婴城。
春来羣乌噪且惊，气如坏山堕其庭。
牙门大将有刘生，夜半射落欃枪星。
帐中虏血流满地，门外三军舞连臂。
驿骑函首过黄河，城中无贼天气和。
朝廷侍郎来慰抚，耕夫满野行人歌。','',''),('quantangshi-18854','平齐行二首 二','劉禹錫','quantangshi','','卷19','泰山沈寇六十年，旅祭不享生愁烟。
今逢圣君欲封禅，神使阴兵来阻战。
妖氛扫尽河水清，日观杲杲卿云见。
开元黄帝东封时，百神受职争奔驰。
千钧猛簴顺流下，洪波涵淡浮熊罴。
侍臣燕公秉文笔，玉检告天无愧词。
当今睿孙承圣祖，岳神望幸河宗舞。
青门大道属车尘，共待葳蕤翠华举。','',''),('quantangshi-18855','送裴处士应制举诗','劉禹錫','quantangshi','','卷19','裴生久在风尘里，气劲言高少知己。
注书曾学郑司农，历国多于孔夫子。
往年访我到连州，无穷绝境终日游。
登山雨中试蜡屐，入洞夏里披貂裘。
白帝城边又相遇，歛翼三年不飞去。
忽然结束如秋蓬，自称对策明光宫。
人言策中说何事，掉头不答看飞鸿。
彤庭翠松迎晓日，凤衔金榜云间出。
中贵腰鞭立倾酒，宰臣委佩观摇笔。
古称射策如弯弧，一发偶中何时无。
由来草泽无忌讳，努力满挽当亨衢。
忆得当年识君处，嘉禾驿后联墙住。
垂钩钓得王余鱼，踏芳共登苏小墓。
此事今同梦想间，相看一笑且开颜。
老大希逢旧邻里，为君扶病到方山。','',''),('quantangshi-18856','三乡驿楼伏覩玄宗望女几山诗小臣斐然有感','劉禹錫','quantangshi','','卷19','开元天子万事足，唯惜当时光景促。
三乡陌上望仙山，归作霓裳羽衣曲。
仙心从此在瑶池，三清八景相追随。
天上忽乘白云去，世间空有秋风词。','',''),('quantangshi-18857','城西行','劉禹錫','quantangshi','','卷19','城西簇簇三叛族，叛者为谁蔡吴蜀。
中使提刀出禁来，九衢车马轰如雷。
临刑与酒杯未覆，讐家白官先请肉。
守吏能然董卓脐，饥乌来觇桓玄目。
城西人散泰阶平，雨洗血痕春草生。','',''),('quantangshi-18858','武昌老人说笛歌','劉禹錫','quantangshi','','卷19','武昌老人七十余，手把庾令相问书。
自言少小学吹笛，早事曹王曾赏激。
往年镇戍到蕲州，楚山萧萧笛竹秋。
当时买材恣搜索，典却身上乌貂裘。
古苔苍苍封老节，石上孤生饱风雪。
商声五音随指发，水中龙应行云绝。
曾将黄鹤楼上吹，一声占尽秋江月。
如今老去语尤迟，音韵高低耳不知。
气力已微心尚在，时时一曲梦中吹。','',''),('quantangshi-18859','西山兰若试茶歌','劉禹錫','quantangshi','','卷19','山僧后檐茶数丛，春来映竹抽新茸。
宛然为客振衣起，自傍芳丛摘鹰觜。
斯须炒成满室香，便酌砌下金沙水。
骤雨松声入鼎来，白云满盌花俳徊。
悠扬喷鼻宿酲散，清峭彻骨烦襟开。
阳崖阴岭各殊气，未若竹下莓苔地。
炎帝虽尝未解煎，桐君有箓那知味。
新芽连拳半未舒，自摘至煎俄顷余。
木兰霑露香微似，瑶草临波色不如。
僧言灵味宜幽寂，采采翘英为嘉客。
不辞缄封寄郡斋，甎井铜炉损标格。
何况蒙山顾渚春，白泥赤印走风尘。
欲知花乳清泠味，须是眠云跂石人。','',''),('quantangshi-18860','聚蚊谣','劉禹錫','quantangshi','','卷19','沈沈夏夜兰堂开，飞蚊伺暗声如雷。
嘈然歘起初骇听，殷殷若自南山来。
喧腾鼓舞喜昏黑，昧者不分听者惑。
露花滴沥月上天，利觜迎人着不得。
我躯七尺尔如芒，我孤尔众能我伤。
天生有时不可遏，为尔设幄潜匡牀。
清商一来秋日晓，羞尔微形饲丹鸟。','',''),('quantangshi-18861','百舌吟','劉禹錫','quantangshi','','卷19','晓星寥落春云低，初闻百舌间关啼。
花树满空迷处所，摇动繁英坠红雨。
笙簧百啭音韵多，黄鹂吞声燕无语。
东方朝日迟迟升，迎风弄景如自矜。
数声不尽又飞去，何许相逢绿杨路。
绵蛮宛转似娱人，一心百舌何纷纷。
酡颜侠少停歌听，坠珥妖姬和睡闻。
可怜光景何时尽，谁能低回避鹰隼。
廷尉张罗自不关，潘郎挟弹无情损。
天生羽族尔何微，舌端万变乘春晖。
南方朱鸟一朝见，索漠无言蒿下飞。','',''),('quantangshi-18862','飞鸢操','劉禹錫','quantangshi','','卷19','鸢飞杳杳青云里，鸢鸣萧萧风四起。
旗尾飘扬势渐高，箭头砉划声相似。
长空悠悠霁日悬，六翮不动凝风烟。
游鵾翔雁出其下，庆云清景相回旋。
忽闻饥乌一噪聚，瞥下云中争腐鼠。
腾音砺吻相喧呼，仰天大吓疑鵷鶵。
畏人避犬投高处，俛啄无声犹屡顾。
青鸟自爱玉山禾，仙禽徒贵华亭露。
朴遬危巢向暮时，毰毸饱腹蹲枯枝。
游童挟弹一麾肘，臆碎羽分人不悲。
天生众禽各有类，威凤文章在仁义。
鹰隼仪形蝼蚁心，虽能戾天何足贵。','',''),('quantangshi-18863','秋萤引','劉禹錫','quantangshi','','卷19','汉陵秦苑遥苍苍，陈根腐叶秋萤光。
夜空寥寂金气净，千门九陌飞悠扬。
纷纶晖映互明灭，金炉星喷镫花发。
露华洗濯清风吹，低昂不定招摇垂。
高丽罘罳照蛛网，斜历璇题舞罗幌。
曝衣楼上拂香帬，承露台前转仙掌。
槐市诸生夜读书，北窗分明辨鲁鱼。
行子东山起征思，中郎骑省悲秋气。
铜雀人归自入帘，长门帐开来照泪。
谁言向晦常自明，儿童走步娇女争。
天生有光非自炫，远近低昂暗中见。
撮蚊妖鸟亦夜起，翅如车轮而已矣。','',''),('quantangshi-18864','伤秦姝行','劉禹錫','quantangshi','','卷19','长安二月花满城，插花女儿弹银筝。
南宫仙郎下朝晚，曲头驻马闻新声。
马蹄逶迟心荡漾，高楼已远犹频望。
此时意重千金轻，鸟传消息绀轮迎。
芳筵银烛一相见，浅笑低鬟初目成。
蜀弦铮摐指如玉，皇帝弟子韦家曲。
青牛文梓赤金簧，玫瑰宝柱秋雁行。
歛蛾收[袂]凝清光，抽弦缓调怨且长。
八鸾锵锵渡银汉，九雏威凤鸣朝阳。
曲终韵尽意不足，余思悄绝愁空堂。
从郎镇南别城阙，楼船理曲潇湘月。
冯夷蹁跹舞渌波，鲛人出听停绡梭。
北池含烟瑶草短，万松亭下清风满。
秦声一曲此时闻，岭泉呜咽南云断。
来自长陵小市东，蕣华零落瘴江风。
侍儿掩泣收银甲，鹦鹉不言愁玉笼。
博山炉中香自灭，镜奁尘暗同心结。
从此东山非昔游，长嗟人与弦俱绝。','',''),('quantangshi-18865','竞渡曲','劉禹錫','quantangshi','','卷19','沅江五月平堤流，邑人相将浮彩舟。
灵均何年歌已矣，哀谣振檝从此起。
杨桴击节雷阗阗，乱流齐进声轰然。
蛟龙得雨鬐鬛动，螮蝀饮河形影联。
刺史临流褰翠帏，揭竿命爵分雄雌。
先鸣余勇争鼓舞，未至衔枚颜色沮。
百胜本自有前期，一飞由来无定所。
风俗如狂重此时，纵观云委江之湄。
彩旗夹岸照蛟室，罗袜凌波呈水嬉。
曲终人散空愁暮，招屈亭前水东注。','',''),('quantangshi-18866','翰林白二十二学士见寄诗一百篇因以答贶','劉禹錫','quantangshi','','卷19','吟君遗我百篇诗，使我独坐形神驰。
玉琴清夜人不语，琪树春朝风正吹。
郢人斤斵无痕迹，仙人衣裳弃刀尺。
世人方内欲相寻，行尽四维无处觅。','',''),('quantangshi-18867','忆春草','劉禹錫','quantangshi','','卷19','忆春草，处处多情洛阳道。
金谷园中见日迟，铜驼陌上迎风早。
河南大尹频出难，只得池塘十步看。
府门闭后满街月，几处游人草头歇。
馆娃宫外姑苏台，郁郁芊芊拨不开。
无风自偃君知否，西子帬裾曾拂来。','',''),('quantangshi-18868','乐天寄忆旧游因作报白君以答','劉禹錫','quantangshi','','卷19','报白君，别来已渡江南春。
江南春色何处好，燕子双飞故官道。
春城三百七十桥，夹岸朱楼隔柳条。
丫头小儿荡画桨，长袂女郎簪翠翘。
郡斋北轩卷罗幕，碧池逶迤遶画阁。
池边绿竹桃李花，花下舞筵铺彩霞。
吴娃足情言语黠，越客有酒巾冠斜。
坐中皆言白太守，不负风光向杯酒。
酒酣襞牋飞逸韵，至今传在人人口。
报白君，相思空望嵩丘云。
其奈钱塘苏小小，忆君泪点石榴帬。','',''),('quantangshi-18869','两如何诗谢裴令公赠别二首 一','劉禹錫','quantangshi','','卷19','一言一顾重，重何如。
今日陪游清洛苑，昔年别入承明庐。','',''),('quantangshi-18870','两如何诗谢裴令公赠别二首 二','劉禹錫','quantangshi','','卷19','一东一西别，别何如。
终期大冶再熔炼，愿托扶摇翔碧虚。','',''),('quantangshi-18871','唐侍御寄游道林岳麓二寺诗并沈中丞姚员外所和见征继作','劉禹錫','quantangshi','','卷19','湘西古刹双蹲蹲，羣峰朝拱如骏奔。
青松步障深五里，龙宫黯黯神为阍。
高殿呀然压苍巘，俯瞰长江疑欲吞。
橘洲泛浮金实动，水郭缭绕朱楼骞。
语余百响入天籁，众奇引步轻翩翻。
泉清石布博棋子，萝密鸟韵如簧言。
回廊架险高且曲，新径穿林明复昏。
浅流忽浊山兽过，古木半空天火痕。
星使双飞出禁垣，元侯饯之游石门。
紫髯翼从红袖舞，竹风松雪香温黁。
远持清琐照巫峡，一戞惊断三声猨。
灵山会中身不预，吟想峭绝愁精魂。
恨无黄金千万饼，布地买取为丘园。','',''),('quantangshi-18872','将赴汝州途出浚下留辞李相公','劉禹錫','quantangshi','','卷19','长安旧游四十载，鄂渚一别十四年。
后来富贵已零落，岁寒松柏犹依然。
初逢贞元尚文主，云阙天池共翔舞。
相看却数六朝臣，屈指如今无四五。
夷门天下之咽喉，昔时往往生疮疣。
联翩旧相来镇压，四海吐纳皆通流。
久别凡经几多事，何由说得平生意。
千思万虑尽如空，一笑一言真可贵。
世间何事最殷勤，白头将相逢故人。
功成名遂会归老，请问东山为近邻。','',''),('quantangshi-18873','平蔡州三首 一','劉禹錫','quantangshi','','卷19','蔡州城中众心死，妖星夜落照壕水。
汉家飞将下天来，马棰一挥门洞开。
贼徒崩腾望旗拜，有若羣蛰惊春雷。
狂童面缚登槛车，太白夭矫垂捷书。
相公从容来镇抚，常侍郊迎负文弩。
四人归业闾里闲，小儿跳浪健儿舞。','',''),('quantangshi-18874','平蔡州三首 二','劉禹錫','quantangshi','','卷19','汝南晨鸡喔喔鸣，城头鼓角音和平。
路傍老人忆旧事，相与感激皆涕零。
老人收泣前致辞，官军入城人不知。
忽惊元和十二载，重见天宝承平时。','',''),('quantangshi-18875','平蔡州三首 三','劉禹錫','quantangshi','','卷19','九衢车马浑浑流，使臣来献淮西囚。
四夷闻风失匕筯，天子受贺登高楼。
妖童擢髪不足数，血污城西一抱土。
南峯无火楚泽闲，夜行不锁穆陵关。
策勋礼毕天下泰，猛士按劒看恒山。','',''),('quantangshi-18876','送僧仲剬东游兼寄呈灵澈上人','劉禹錫','quantangshi','','卷19','释子道成神气闲，住持曾上清凉山。
晴空礼拜见真像，金毛五髻卿云间。
西游长安隶僧籍，本寺门前曲江碧。
松间白月照宝书，竹下香泉洒瑶席。
前时学得经论成，奔驰象马开禅扃。
高筵谈柄一麾拂，讲下门徒如醉醒。
旧闻南方多长老，次第来入荆门道。
荆州本自重弥天，南朝塔庙犹依然。
宴坐东阳枯树下，经行居止故台边。
忽忆遗民社中客，为我衡阳驻飞锡。
讲罢同寻相鹤经，闲来共蜡登山屐。
一旦扬眉望沃州，自言王谢许同游。
凭将杂拟三十首，寄与江南汤慧休。','',''),('quantangshi-18877','观棋歌送儇师西游','劉禹錫','quantangshi','','卷19','长沙男子东林师，闲读艺经工弈棋。
有时凝思如入定，暗覆一局谁能知。
今年访予来小桂，方袍袖中贮新势。
山人无事秋日长，白昼懵懵眠匡牀。
因君临局看鬬智，不觉迟景沈西墙。
自从仙人遇樵子，直到开元王长史。
前身后身付余习，百变千化无穷已。
初疑磊落曙天星，次见搏击三秋兵。
雁行布陈众未晓，虎穴得子人皆惊。
行尽三湘不逢敌，终日饶人损机格。
自言台阁有知音，悠然远起西游心。
商山夏木阴寂寂，好处俳徊驻飞锡。
忽思争道画平沙，独笑无言心有适。
蔼蔼京城在九天，贵游豪士足华筵。
此时一行出人意，赌取声名不要钱。','',''),('quantangshi-18878','吐绶鸟词','劉禹錫','quantangshi','','卷19','越山有鸟翔寥廓，嗉中天绶光若若。
越人偶见而奇之，因名吐绶江南知。
四明天姥神仙地，朱鸟星精钟异气。
赤玉雕成彪炳毛，红绡翦出玲珑翅。
湖烟始开山日高，迎风吐绶盘花绦。
临波似染琅琊草，映叶疑开阿母桃。
花红草绿人间事，未若灵禽自然贵。
鹤吐明珠暂报恩，鹊衔金印空为瑞。
春和秋霁野花开，翫景寻芳处处来。
翠幕雕笼非所慕，珠丸柘弹莫相猜。
栖月啼烟凌缥缈，高林先见金霞晓。
三山仙路寄遥情，刷羽扬翘欲上征。
不学碧鸡依井络，愿随青鸟向层城。
太液池中有黄鹄，怜君长向高枝宿。
如何一借羊角风，来听箫韶九成曲。','',''),('quantangshi-18879','八月十五日夜桃源翫月','劉禹錫','quantangshi','','卷19','尘中见月心亦闲，况是清秋仙府间。
凝光悠悠寒露坠，此时立在最高山。
碧虚无云风不起，山上长松山下水。
羣动翛然一顾中，天高地平千万里。
少君引我升玉坛，礼空遥请真仙官。
云軿欲下星斗动，天乐一声肌骨寒。
金霞昕昕渐东上，轮欹影促犹频望。
绝景良时难再并，他年此日应惆怅。','',''),('quantangshi-18880','送鸿举游江[西]','劉禹錫','quantangshi','','卷19','禅客学禅兼学文，出山初似无心云。
从风卷舒来何处，缭绕巴山不得去。
山州古寺好闲居，读尽龙王宫里书。
使君滩头拣石砚，白帝城边寻野蔬。
忽然登高心瞥起，又欲浮杯信流水。
烟波浩淼鱼鸟情，东去三千三百里。
荆门峡断无盘涡，湘平汉阔清光多。
庐山雾开见瀑布，江西月净闻渔歌。
钟陵八郡多名守，半是西方社中友。
与师相见便谈空，想得高斋狮子吼。','',''),('quantangshi-18881','采菱行','劉禹錫','quantangshi','','卷19','白马湖平秋日光，紫菱如锦彩鸳翔。
荡舟游女满中央，采菱不顾马上郎。
争多逐胜纷相向，时转兰桡破轻浪。
长鬟弱袂动参差，钗影钏文浮荡漾。
笑语哇咬顾晚晖，蓼花缘岸扣舷归。
归来共到市桥步，野蔓系船萍满衣。
家家竹楼临广陌，下有连樯多估客。
携觞荐芰夜经过，醉踏大堤相应歌。
屈平祠下沅江水，月照寒波白烟起。
一曲南音此地闻，长安北望三千里。','',''),('quantangshi-18882','和牛相公溪醉歌见寄','劉禹錫','quantangshi','','卷19','脱屣将相守冲谦，唯于山水独不廉。
枕伊背洛得胜地，鸣臯少室来轩檐。
相形面势默指画，言下变化随顾瞻。
清池曲榭人所致，野趣幽芳天与添。
有时转入潭岛间，珍木如幄藤为帘。
忽然便有江湖思，沙砾平浅草纤纤。
怪石钓出太湖底，珠树移自天台尖。
崇兰迎风绿泛艳，坼莲含露红𧞋襜。
修廊架空远岫入，弱柳覆槛流波霑。
渚蒲抽芽劒脊动，岸荻迸笋锥头銛。
携觞命侣极永日，此会虽数心无厌。
人皆置庄身不到，富贵难与逍遥兼。
唯公出处得自在，决就放旷辞炎炎。
座宾尽欢恣谈谑，愧我掉头还奋髯。
能令商于多病客，亦觉自适非沈潜。','',''),('quantangshi-18883','和浙西李大夫霜夜对月听小童吹觱篥歌依本韵','劉禹錫','quantangshi','','卷19','海门双青暮烟歇，万顷金波涌明月。
侯家小儿能觱篥，对此清光天性发。
长江凝练树无风，浏栗一声霄汉中。
涵胡画角怨边草，萧瑟清蝉吟野丛。
冲融顿挫心使指，雄吼如风转如水。
思妇多情珠泪垂，仙禽欲舞双翅起。
郡人寂听衣满霜，江城月斜楼影长。
才惊指下繁韵息，已见树杪明星光。
谢公高斋吟激楚，恋阙心同在羁旅。
一奏荆人白雪歌，如闻雒客扶风邬。
吴门水驿按山阴，文字殷勤寄意深。
欲识阳陶能绝处，少年荣贵道伤心。','',''),('quantangshi-18884','叹水别白二十二','劉禹錫','quantangshi','','卷19','水，至清，尽美。
从一勺，至千里。
利人利物，时行时止。
道性净皆然，交情淡如此。
君游金谷堤上，我在石渠署里。
两心相忆似流波，潺湲日夜无穷已。','',''),('quantangshi-18885','同留守王仆射各赋春中一物从一韵至七','劉禹錫','quantangshi','','卷19','莺，能语，多情。
春将半，天欲明。
始逢南陌，复集东城。
林疎时见影，花密但闻声。
营中缘催短笛，楼上来定哀筝。
千门万户垂杨里，百转如簧烟景晴。','',''),('quantangshi-18886','伤我马词','劉禹錫','quantangshi','','卷19','生于碛礰善驰走，万里南来困丘阜。
青菰寒菽非适口，病闻北风犹举首。
金台已平骨空朽，投之龙渊从尔友。','',''),('quantangshi-18887','清湘词二首 一','劉禹錫','quantangshi','','卷19','湘水流，湘水流，九疑云物至今愁。
君问二妃何处所，零陵香草雨中收。','',''),('quantangshi-18888','清湘词二首 二','劉禹錫','quantangshi','','卷19','斑竹枝，斑竹枝，泪痕点点寄相思。
楚客欲闻瑶瑟怨，潇湘深夜月明时。','',''),('quantangshi-18889','和乐天春词依忆江南曲拍为句 一','劉禹錫','quantangshi','','卷19','春去也，多谢洛城人。
弱柳从风疑举袂，丛兰裛露似霑巾，独坐亦含嚬。','',''),('quantangshi-18890','和乐天春词依忆江南曲拍为句 二','劉禹錫','quantangshi','','卷19','春过也，笑惜艳阳年。
犹有桃花流水上，无辞竹叶醉樽前，惟待见青天。','',''),('quantangshi-18891','泽宫诗 一','劉禹錫','quantangshi','','卷19','秩秩泽宫，有的维鹄。
祁祁庶士，于以干禄。','',''),('quantangshi-18892','泽宫诗 二','劉禹錫','quantangshi','','卷19','彼鹄斯微，若止若翔。
千里之差，起于毫芒。','',''),('quantangshi-18893','泽宫诗 三','劉禹錫','quantangshi','','卷19','我矢既直，我弓既良。
依于高墉，因我不臧。','',''),('quantangshi-18894','泽宫诗 四','劉禹錫','quantangshi','','卷19','高墉伊何，维器与时。
视之以心，谁谓鹄微。','',''),('quantangshi-18895','酬令狐相公六言见寄','劉禹錫','quantangshi','','卷19','已嗟别离太远，更被光阴苦催。
吴苑燕辞人去，汾川雁带书来。
愁吟月落犹望，忆梦天明未回。
今日便令歌者，唱兄诗送一杯。','',''),('quantangshi-18896','答乐天临都驿见赠','劉禹錫','quantangshi','','卷19','北固山边波浪，东都城里风尘。
世事不同心事，新人何似故人。','',''),('quantangshi-18897','再赠乐天','劉禹錫','quantangshi','','卷19','一政政官轧轧，一年年老骎骎。
身外名何足算，别来诗且同吟。','',''),('quantangshi-18898','酬杨侍郎凭见寄','劉禹錫','quantangshi','','卷19','十年毛羽催颓，一旦天书召回。
看看瓜时欲到，故侯也好归来。','',''),('quantangshi-18899','春有情篇','劉禹錫','quantangshi','','卷19','为问游春侣，春情何处寻。
花含欲语意，草有鬬生心。
雨频催发色，云轻不作阴。
纵令无月夜，芳兴暗中深。','',''),('quantangshi-18900','七夕二首 一','劉禹錫','quantangshi','','卷19','河鼓灵旗动，嫦娥破镜斜。
满空天是幕，徐转斗为车。
机罢犹安石，桥成不碍槎。
谁知观津女，竟夕望云涯。','',''),('quantangshi-18901','七夕二首 二','劉禹錫','quantangshi','','卷19','天衢启云帐，神驭上星桥。
初喜渡河汉，频惊转斗杓。
余霞张锦幛，轻电闪红绡。
非是人间世，还悲后会遥。','',''),('quantangshi-18902','边风行','劉禹錫','quantangshi','','卷19','边马萧萧鸣，边风满碛生。
暗添弓箭力，斗上鼓鼙声。
袭月寒晕起，吹云阴阵成。
将军占气候，出号夜翻营。','',''),('quantangshi-18903','送工部萧郎中刑部李郎中并以本官兼中丞分命充京西京北覆粮使','劉禹錫','quantangshi','','卷19','霜简映金章，相辉同舍郎。
天威巡虎落，星使出鸳行。
尊俎成全策，京坻阅见粮。
归来虏尘灭，画地奏明光。','',''),('quantangshi-18904','送太常萧博士弃官归养赴东都','劉禹錫','quantangshi','','卷19','兄弟尽鸳鸾，归心切问安。
贪荣五彩服，遂挂两梁冠。
侍膳曾调鼎，循陔更握兰。
从今别君后，长忆德星看。','',''),('quantangshi-18905','送河南皇甫少尹赴绛州','劉禹錫','quantangshi','','卷19','祖帐临周道，前旌指晋城。
午桥羣吏散，亥字老人迎。
诗酒同行乐，别离方见情。
从此洛阳社，吟咏属书生。','',''),('quantangshi-18906','发华州留别张侍御','劉禹錫','quantangshi','','卷19','束简下延阁，买符驱短辕。
同人惜分袂，结念醉芳樽。
切切别弦急，萧萧征骑烦。
临岐无限意，相视却忘言。','',''),('quantangshi-18907','奉送家兄归王屋山隐居二首 一','劉禹錫','quantangshi','','卷19','洛阳天坛上，依稀似玉京。
夜分先见日，月静远闻笙。
云路将鸡犬，丹台有姓名。
古来成道者，兄弟亦同行。','',''),('quantangshi-18908','奉送家兄归王屋山隐居二首 二','劉禹錫','quantangshi','','卷19','春来山事好，归去亦逍遥。
水净苔莎色，露香芝术苗。
登台吸瑞景，飞步翼神飙。
愿荐埙篪曲，相将学玉箫。','',''),('quantangshi-18909','送王师鲁协律赴湖南使幕','劉禹錫','quantangshi','','卷19','翩翩马上郎，驱传渡三湘。
橘树沙洲暗，松醪酒肆香。
素风传竹帛，高价聘琳琅。
楚水多兰芷，何人事搴芳。','',''),('quantangshi-18910','送赵中丞自司金郎转官参山南令狐仆射幕府','劉禹錫','quantangshi','','卷19','绿树满褒斜，西南蜀路赊。
驿门临白草，县道入黄花。
相府开油幕，门生逐绛纱。
行看布政后，还从入京华。','',''),('quantangshi-18911','送卢处士归嵩山别业','劉禹錫','quantangshi','','卷19','世业嵩山隐，云深无四邻。
药炉烧姹女，酒瓮贮贤人。
晚日华阴雾，秋风函谷尘。
送君从此去，铃阁少谈宾。','',''),('quantangshi-18912','洛中送崔司业使君扶侍赴唐州','劉禹錫','quantangshi','','卷19','绿野芳城路，残春柳絮飞。
风鸣驌驦马，日照老莱衣。
洛苑鱼书至，江村雁户归。
相思望淮水，双鲤不应稀。','',''),('quantangshi-18913','送李友路秀才赴举','劉禹錫','quantangshi','','卷19','谁怜相门子，不语望秋山。
生长绮纨内，辛勤笔砚间。
荣亲在名字，好学弃官班。
伫俟明年桂，高堂开笑颜。','',''),('quantangshi-18914','送从弟郎中赴浙西','劉禹錫','quantangshi','','卷19','衔命出尚书，新恩换使车。
汉庭无右者，梁苑重归欤。
又食建业水，曾依京口居。
共经何限事，宾主两如初。','',''),('quantangshi-18915','送元上人归稽亭','劉禹錫','quantangshi','','卷19','重叠稽亭路，山僧归独行。
远峰斜日影，本寺旧钟声。
徒侣问新事，烟云怆别情。
应夸乞食处，踏遍凤凰城。','',''),('quantangshi-18916','赠别君素上人诗','劉禹錫','quantangshi','','卷19','穷巷唯秋草，高僧独扣门。
相欢如旧识，问法到无言。
水为风生浪，珠非尘可昏。
悟来皆是道，此别不销魂。','',''),('quantangshi-18917','送深法师游南岳','劉禹錫','quantangshi','','卷19','师在白云乡，名登善法堂。
十方传句偈，八部会坛场。
飞锡无定所，宝书留旧房。
唯应衔果雁，相送至衡阳。','',''),('quantangshi-18918','赠别约师','劉禹錫','quantangshi','','卷19','师逢吴兴守，相伴住禅扃。
春雨同栽树，秋灯对讲经。
庐山曾结社，桂水远扬舲。
话旧还惆怅，天南望柳星。','',''),('quantangshi-18919','秋日过鸿举法师寺院便送归江陵','劉禹錫','quantangshi','','卷19','看画长廊遍，寻僧一径幽。
小池兼鹤净，古木带蝉秋。
客至茶烟起，禽归讲席收。
浮杯明日去，相望水悠悠。','',''),('quantangshi-18920','春日退朝','劉禹錫','quantangshi','','卷19','紫陌夜来雨，南山朝下看。
戟枝迎日动，阁影助松寒。
瑞气转绡縠，游光泛波澜。
御沟新柳色，处处拂归鞍。','',''),('quantangshi-18921','蜀先主庙','劉禹錫','quantangshi','','卷19','天地英雄气，千秋尚凛然。
势分三足鼎，业复五铢钱。
得相能开国，生儿不象贤。
凄凉蜀故妓，来舞魏宫前。','',''),('quantangshi-18922','经东都安国观九仙公主旧院作','劉禹錫','quantangshi','','卷19','仙院御沟东，今来事不同。
门开青草日，楼闭绿杨风。
将犬升天路，披云赴月宫。
武皇曾驻跸，亲问主人翁。','',''),('quantangshi-18923','观八阵图','劉禹錫','quantangshi','','卷19','轩皇传上略，蜀相运神机。
水落龙蛇出，沙平鹅鹳飞。
波涛无动势，鳞介避余威。
会有知兵者，临流指是非。','',''),('quantangshi-18924','八月十五日夜翫月','劉禹錫','quantangshi','','卷19','天将今夜月，一遍洗寰瀛。
暑退九霄净，秋澄万景清。
星辰让光彩，风露发晶英。
能变人间世，翛然是玉京。','',''),('quantangshi-18925','太和戊申岁大有年诏赐百僚出城观秋稼谨书盛事以俟采诗者','劉禹錫','quantangshi','','卷19','长安铜雀鸣，秋稼与云平。
玉烛调寒暑，金风报顺成。
川原呈上瑞，恩泽赐闲行。
欲反重城掩，犹闻歌吹声。','',''),('quantangshi-18926','金陵怀古','劉禹錫','quantangshi','','卷19','潮满冶城渚，日斜征虏亭。
蔡洲新草绿，幕府旧烟青。
兴废由人事，山川空地形。
后庭花一曲，幽怨不堪听。','',''),('quantangshi-18927','昼居池上亭独吟','劉禹錫','quantangshi','','卷19','日午树阴正，独吟池上亭。
静看蜂教诲，闲想鹤仪形。
法酒调神气，清琴入性灵。
浩然机已息，几杖复何铭。','',''),('quantangshi-18928','分司东都蒙襄阳李司徒相公书问因以奉寄','劉禹錫','quantangshi','','卷19','早忝金马客，晚为商洛翁。
知名四海内，多病一生中。
举世往还尽，何人心事同。
几时登岘首，恃旧揖三公。','',''),('quantangshi-18929','门下相公荣加册命天下同欢忝沐眷私辄感申贺','劉禹錫','quantangshi','','卷19','册命出宸衷，官仪自古崇。
特膺平土拜，光赞格天功。
再佩扶阳印，常乘鲍氏骢。
七贤遗老在，犹得咏清风。','',''),('quantangshi-18930','病中一二禅客见问因以谢之','劉禹錫','quantangshi','','卷19','劳动诸贤者，同来问病夫。
添炉烹雀舌，洒水净龙须。
身是芭蕉喻，行须筇竹扶。
医王有妙药，能乞一丸无。','',''),('quantangshi-18931','秋江晚泊','劉禹錫','quantangshi','','卷19','长泊起秋色，空江涵霁晖。
暮霞千万状，宾鸿次第飞。
古戍见旗逈，荒村闻犬稀。
轲峨艑上客，劝酒夜相依。','',''),('quantangshi-18932','步出武陵东亭临江寓望','劉禹錫','quantangshi','','卷19','鹰至感风候，霜余变林麓。
孤颿带日来，寒江转沙曲。
戍摇旗影动，津晚橹声促。
月上彩霞收，渔歌远相续。','',''),('quantangshi-18933','秋日送客至潜水驿','劉禹錫','quantangshi','','卷19','候吏立沙际，田家连竹溪。
枫林社日鼓，茅屋午时鸡。
鹊噪晚禾地，蝶飞秋草畦。
驿楼宫树近，疲马再三嘶。','',''),('quantangshi-18934','湖州崔郎中曹长寄三癖诗自言癖在诗与琴酒其词逸而高吟咏不足昔柳吴兴亭臯陇首之句王融书之白团扇故为四韵以谢之','劉禹錫','quantangshi','','卷19','视事画屏中，自称三癖翁。
管弦泛春渚，旌斾拂晴虹。
酒对青山月，琴韵白苹风。
会书团扇上，知君文字工。','',''),('quantangshi-18935','为郎分司寄上都同舍','劉禹錫','quantangshi','','卷19','籍通金马门，家在铜駞陌。
省闼昼无尘，宫树朝凝碧。
荒街浅深辙，古渡潺湲石。
唯有嵩丘云，堪夸早朝客。','',''),('quantangshi-18936','登陕州北楼却忆京师亲友','劉禹錫','quantangshi','','卷19','独上百尺楼，目穷思亦愁。
初日徧露草，野田荒悠悠。
尘息长道白，林清宿烟收。
回首云深处，永怀乡旧游。','',''),('quantangshi-18937','途中早发','劉禹錫','quantangshi','','卷19','中庭望启明，促促事晨征。
寒树鸟初动，霜桥人未行。
水流白烟起，日上彩霞生。
隐士应高枕，无人问姓名。','',''),('quantangshi-18938','陕州河亭陪韦五大夫雪后眺望因以留别与韦有布衣之旧一别二纪经迁贬而归','劉禹錫','quantangshi','','卷19','雪霁太阳津，城池表里春。
河流添马颊，原色动龙鳞。
万里独归客，一杯逢故人。
登高向西望，关路正飞尘。','',''),('quantangshi-18939','城东闲游','劉禹錫','quantangshi','','卷19','借问池台主，多居要路津。
千金买绝境，永日属闲人。
竹径萦纡入，花林委曲巡。
斜阳众客散，空锁一园春。','',''),('quantangshi-18940','罢郡归洛阳闲居','劉禹錫','quantangshi','','卷19','十年江海守，旦夕有归心。
及此西还日，空成东武吟。
花间数杯酒，月下一张琴。
闻说功名事，依前惜寸阴。','',''),('quantangshi-18941','晚泊牛渚','劉禹錫','quantangshi','','卷19','芦苇晚风起，秋江鳞甲生。
残霞忽变色，游雁有余声。
戍鼓音响绝，渔家灯火明。
无人能咏史，独自月中行。','',''),('quantangshi-18942','宿诚禅师山房题赠二首 一','劉禹錫','quantangshi','','卷19','宴坐白云端，清江直下看。
来人望金刹，讲席绕香坛。
虎啸夜林动，鼍鸣秋涧寒。
众音徒起灭，心在净中观。','',''),('quantangshi-18943','宿诚禅师山房题赠二首 二','劉禹錫','quantangshi','','卷19','不出孤峰上，人间四十秋。
视身如传舍，阅世似东流。
法为因缘立，心从次第修。
中宵问真偈，有住是吾忧。','',''),('quantangshi-18944','赠澧州高大夫司马霞[寓]','劉禹錫','quantangshi','','卷19','前年牧锦城，马蹋血泥行。
千里追戎首，三军许勇名。
残兵疑鹤唳，空垒辩乌声。
一误云中级，南游湘水清。','',''),('quantangshi-18945','闻董评事疾因以书赠','劉禹錫','quantangshi','','卷19','繁露传家学，青莲译梵书。
火风乖四大，文字废三余。
欹枕昼眠静，折巾秋鬓疎。
武皇思视草，谁许茂陵居。','',''),('quantangshi-18946','咏庭梅寄人','劉禹錫','quantangshi','','卷19','蚤花常犯寒，繁实常苦酸。
何事上春日，坐令芳意阑。
夭桃定相笑，游妓肯回看。
君问调金鼎，方知正味难。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-18947','德宗神武孝文皇帝挽歌二首 一','劉禹錫','quantangshi','','卷19','出震清多难，乘时播大钧。
操弦调六气，挥翰动三辰。
运偶升天日，哀深率土人。
瑶池无辙迹，谁见属车尘。','',''),('quantangshi-18948','德宗神武孝文皇帝挽歌二首 二','劉禹錫','quantangshi','','卷19','凤翣拥铭旌，威迟异吉行。
汉仪陈祕器，楚挽咽繁声。
驻綍辞清庙，凝笳背直城。
唯应留内传，知是向蓬瀛。','',''),('quantangshi-18949','敬宗睿武昭愍孝皇帝挽歌三首 一','劉禹錫','quantangshi','','卷19','宝历方无限，仙期忽有涯。
事亲崇汉礼，传圣法殷家。
晚出芙蓉阙，春归棠棣华。
玉轮今日动，不是画云车。','',''),('quantangshi-18950','敬宗睿武昭愍孝皇帝挽歌三首 二','劉禹錫','quantangshi','','卷19','任贤劳梦寐，登位富春秋。
欲遂东人幸，宁虞杞国忧。
长杨收羽骑，太液泊龙舟。
惟有衣冠在，年年怆月游。','',''),('quantangshi-18951','敬宗睿武昭愍孝皇帝挽歌三首 三','劉禹錫','quantangshi','','卷19','讲学金华殿，亲畊钩盾田。
侍臣容谏猎，方士信求仙。
虹影俄侵日，龙髯不上天。
空余水银海，长照夜灯前。','',''),('quantangshi-18952','文宗元圣昭献孝皇帝挽歌三首','劉禹錫','quantangshi','','卷19','继体三才理，承颜九族亲。
禹功留海内，殷历付天伦。
调露曲常在，秋风词尚新。
本支方百代，先让棣华春。','',''),('quantangshi-18953','文宗元圣昭献孝皇帝挽歌三首 二','劉禹錫','quantangshi','','卷19','月落宫车动，风凄仪杖闲。
路唯瞻凤翣，人尚想龙颜。
御宇方无事，乘云遂不还。
圣情悲望处，沈日下西山。','',''),('quantangshi-18954','文宗元圣昭献孝皇帝挽歌三首 三','劉禹錫','quantangshi','','卷19','享国十五载，升天千万年。
龙镳仙路远，骑吹礼容全。
日下初陵外，人悲旧劒前。
周南有遗老，掩泪望秦川。','',''),('quantangshi-18955','故相国燕国公于司空挽歌二首 一','劉禹錫','quantangshi','','卷19','雕弓封旧国，黑弰继前功。
十年镇南雍，九命作司空。
池台乐事尽，箫鼓葬仪雄。
一代英豪气，晓散白杨风。','',''),('quantangshi-18956','故相国燕国公于司空挽歌二首 二','劉禹錫','quantangshi','','卷19','阴山贵公子，来葬五陵西。
前马悲无主，犹带朔风嘶。
汉水晋山郭，襄杨白铜鞮。
至今有遗爱，日暮人凄凄。','',''),('quantangshi-18957','伤丘中丞','劉禹錫','quantangshi','','卷19','邺下杀才子，苍茫冤气凝。
枯杨映漳水，野火上西陵。
马鬣今无所，龙门昔共登。
何人为吊客，唯是有青蝇。','',''),('quantangshi-18958','河南观察使故相国袁公挽歌三首 一','劉禹錫','quantangshi','','卷19','五驱龙虎节，一入凤凰池。
令尹自无喜，羊公人不疑。
天归京兆日，叶下洞庭时。
湘水秋风至，凄凉吹素旗。','',''),('quantangshi-18959','河南观察使故相国袁公挽歌三首 二','劉禹錫','quantangshi','','卷19','丹旐发江臯，人悲雁亦号。
湘南罢亥市，汉上改词曹。
表墓双碑立，尊名一字褒。
尝闻平楚狱，为报里门高。','',''),('quantangshi-18960','河南观察使故相国袁公挽歌三首 三','劉禹錫','quantangshi','','卷19','返葬三千里，荆衡达帝畿。
逢人即故吏，拜奠尽沾衣。
地得青乌相，宾惊白鹤飞。
五公碑尚在，今日亦同归。','',''),('quantangshi-18961','哭王仆射相公','劉禹錫','quantangshi','','卷19','子侯一日病，滕公千载归。
门庭怆已变，风物澹无辉。
羣吏谒新府，旧宾沾素衣。
歌堂忽暮哭，贺雀尽惊飞。','',''),('quantangshi-18962','伤韦宾客','劉禹錫','quantangshi','','卷19','韦公八十余，位至六尚书。
五福唯无富，一生谁得如。
桂枝攀最久，兰省出仍初。
海内时流尽，何人动素车。','',''),('quantangshi-18963','再经故元九相公宅池上作','劉禹錫','quantangshi','','卷19','故池春又至，一到一伤情。
雁鹜羣犹下，蛙螟衣已生。
竹丛身后长，台势雨来倾。
六尺孤安在，人间未有名。','',''),('quantangshi-18964','请告东归发灞桥却寄诸僚友','劉禹錫','quantangshi','','卷19','征徒出灞涘，回首伤如何。
故人云雨散，满目山川多。
行车无停轨，流景同迅波。
前欢渐成昔，感叹益劳歌。','',''),('quantangshi-18965','初至长安','劉禹錫','quantangshi','','卷19','左迁凡二纪，重见帝城春。
老大归朝客，平安出岭人。
每行经旧处，却想似前身。
不改南山色，其余事事新。','',''),('quantangshi-18966','岁杪将发楚州呈乐天','劉禹錫','quantangshi','','卷19','楚泽雪初霁，楚城春欲归。
清淮变寒色，远树含清晖。
原野已多思，风霜潜减威。
与君同旅雁，北向刷毛衣。','',''),('quantangshi-18967','鹤叹二首 一','劉禹錫','quantangshi','','卷19','寂寞一双鹤，主人在西京。
故巢吴苑树，深院洛阳城。
徐引竹间步，远含云外情。
谁怜好风月，邻舍夜吹笙。','',''),('quantangshi-18968','鹤叹二首 二','劉禹錫','quantangshi','','卷19','丹顶宜承日，霜翎不染泥。
爱池能久立，看月未成栖。
一院春草长，三山归路迷。
主人朝谒早，贪养汝南鸡。','',''),('quantangshi-18969','答白刑部闻新蝉','劉禹錫','quantangshi','','卷19','蝉声未发前，已自感流年。
一入凄凉耳，如闻断续弦。
晴清依露叶，晚急畏霞天。
何事秋卿咏，逢时亦悄然。','',''),('quantangshi-18970','和裴相公寄白侍郎求双鹤','劉禹錫','quantangshi','','卷19','皎皎华亭鹤，来随太守船。
青云意长在，沧海别经年。
留滞清洛苑，裴回明月天。
何如凤池上，双舞入祥烟。','',''),('quantangshi-18971','终南秋雪','劉禹錫','quantangshi','','卷19','南岭见秋雪，千门生早寒。
闲时驻马望，高处卷帘看。
雾散琼枝出，日斜铅粉残。
偏宜曲江上，倒影入清澜。','',''),('quantangshi-18972','和乐天早寒','劉禹錫','quantangshi','','卷19','雨引苔侵壁，风驱叶拥堦。
久留闲客话，宿请老僧斋。
酒瓮新陈接，书签次第排。
翛然自有处，摇落不伤怀。','',''),('quantangshi-18973','曲江春望','劉禹錫','quantangshi','','卷19','凤城烟雨歇，万象含佳气。
酒后人倒狂，花时天似醉。
三春车马客，一代繁华地。
何事独伤怀，少年曾得意。','',''),('quantangshi-18974','同乐天和微之深春二十首 一','劉禹錫','quantangshi','','卷19','何处深春好，春深万乘家。
宫门皆映柳，辇路尽穿花。
池色连天汉，城形象帝车。
旌旗暖风里，猎猎向西斜。','',''),('quantangshi-18975','同乐天和微之深春二十首 二','劉禹錫','quantangshi','','卷19','何处深春好，春深阿母家。
瑶池长不夜，珠树正开花。
桥峻通星渚，楼暄近日车。
层城十二阙，相对日西斜。','',''),('quantangshi-18976','同乐天和微之深春二十首 三','劉禹錫','quantangshi','','卷19','何处深春好，春深执政家。
恩光贪捧日，贵重不看花。
玉馔堂交印，沙堤柱碍车。
多门一已闭，直道更无斜。','',''),('quantangshi-18977','同乐天和微之深春二十首 四','劉禹錫','quantangshi','','卷19','何处深春好，春深大镇家。
前旌光照日，后骑蹙成花。
节院收衙队，球场簇看车。
广筵歌舞散，书号夕阳斜。','',''),('quantangshi-18978','同乐天和微之深春二十首 五','劉禹錫','quantangshi','','卷19','何处深春好，春深贵戚家。
枥嘶无价马，庭发有名花。
欲进宫人食，先薰命妇车。
晚归长带酒，冠盖任倾斜。','',''),('quantangshi-18979','同乐天和微之深春二十首 六','劉禹錫','quantangshi','','卷19','何处深春好，春深恩泽家。
炉添龙脑炷，绶结虎头花。
宾客珠成履，婴孩锦缚车。
画堂帘幕外，来去燕飞斜。','',''),('quantangshi-18980','同乐天和微之深春二十首 七','劉禹錫','quantangshi','','卷19','何处深春好，春深京兆家。
人眉新柳叶，马色醉桃花。
盗息无鸣鼓，朝回自走车。
能令帝城外，不敢迳由斜。','',''),('quantangshi-18981','同乐天和微之深春二十首 八','劉禹錫','quantangshi','','卷19','何处深春好，春深刺史家。
夜阑犹命乐，雨甚亦寻花。
傲客多凭酒，新姬苦上车。
公门吏散后，风摆戟衣斜。','',''),('quantangshi-18982','同乐天和微之深春二十首 九','劉禹錫','quantangshi','','卷19','何处深春好，春深羽客家。
芝田绕舍色，杏树满山花。
云是淮王宅，风为列子车。
古坛操简处，一迳入林斜。','',''),('quantangshi-18983','同乐天和微之深春二十首 十','劉禹錫','quantangshi','','卷19','何处深春好，春深小隐家。
芟庭留野菜，撼树去狂花。
醉酒一千日，贮书三十车。
雉衣从露体，不敢有余斜。','',''),('quantangshi-18984','同乐天和微之深春二十首 十一','劉禹錫','quantangshi','','卷19','何处深春好，春深富室家。
唯多贮金帛，不拟负莺花。
国乐呼连辔，行厨载满车。
归来看理曲，灯下宝钗斜。','',''),('quantangshi-18985','同乐天和微之深春二十首 十二','劉禹錫','quantangshi','','卷19','何处深春好，春深豪士家。
多沽味浓酒，贵买色深花。
已臂鹰随马，连催妓上车。
城南踏青处，村落逐原斜。','',''),('quantangshi-18986','同乐天和微之深春二十首 十三','劉禹錫','quantangshi','','卷19','何处深春好，春深贵胄家。
迎呼偏熟客，拣选最多花。
饮馔开华幄，笙歌出钿车。
兴酣罇易罄，连泻酒瓶斜。','',''),('quantangshi-18987','同乐天和微之深春二十首 十四','劉禹錫','quantangshi','','卷19','何处深春好，春深唱第家。
名传一纸榜，兴管九衢花。
荐听诸侯乐，来随计吏车。
杏园抛曲处，挥袖向风斜。','',''),('quantangshi-18988','同乐天和微之深春二十首 十五','劉禹錫','quantangshi','','卷19','何处深春好，春深少妇家。
能偷新禁曲，自剪入时花。
追逐同游伴，平章贵价车。
从来不堕马，故谴髻鬟斜。','',''),('quantangshi-18989','同乐天和微之深春二十首 十六','劉禹錫','quantangshi','','卷19','何处深春好，春深幼女家。
双鬟梳顶髻，两面绣帬花。
妆坏频临镜，身轻不占车。
秋千争次第，牵拽彩绳斜。','',''),('quantangshi-18990','同乐天和微之深春二十首 十七','劉禹錫','quantangshi','','卷19','何处深春好，春深兰若家。
当香收柏叶，养蜜近梨花。
野迳宜行乐，游人尽驻车。
菜园篱落短，遥见桔槔斜。','',''),('quantangshi-18991','同乐天和微之深春二十首 十八','劉禹錫','quantangshi','','卷19','何处深春好，春深老宿家。
小栏围蕙草，高架引藤花。
四字香书印，三乘壁画车。
迟回听句偈，双树晚阴斜。','',''),('quantangshi-18992','同乐天和微之深春二十首 十九','劉禹錫','quantangshi','','卷19','何处深春好，春深种莳家。
分畦十字水，接树两般花。
栉比栽篱槿，咿哑转井车。
可怜高处望，棊布不曾斜。','',''),('quantangshi-18993','同乐天和微之深春二十首 二十','劉禹錫','quantangshi','','卷19','何处春深好，春深稚子家。
争骑一竿竹，偷折四邻花。
笑击羊皮鼓，行牵犊颔车。
中庭贪夜戏，不觉玉绳斜。','',''),('quantangshi-18994','赠眼医婆罗门僧','劉禹錫','quantangshi','','卷19','三秋伤望眼，终日哭途穷。
两目今先暗，中年似老翁。
看朱渐成碧，羞日不禁风。
师有金篦术，如何为发蒙。','',''),('quantangshi-18995','海门潮别浩初师','劉禹錫','quantangshi','','卷19','前日过萧寺，看师上讲筵。
都人礼白足，施者散金钱。
方便无非教，经行不废禅。
还知习居士，发论侍弥天。','',''),('quantangshi-18996','始闻蝉有怀白宾客去岁白有闻蝉见寄诗云秖应催我老兼遣报君知之句','劉禹錫','quantangshi','','卷19','蝉韵极清切，始闻何处悲。
人含不平意，景值欲秋时。
此岁方晼晚，谁家无别离。
君言催我老，已是去年诗。','',''),('quantangshi-18997','赠乐天','劉禹錫','quantangshi','','卷19','一别旧游尽，相逢俱涕零。
在人虽晚达，于树似冬青。
痛饮连宵醉，狂吟满坐听。
终期抛印绶，共占少微星。','',''),('quantangshi-18998','到郡未浃日登西楼见乐天题诗因即事因寄','劉禹錫','quantangshi','','卷19','湖上收宿雨，城中无昼尘。
楼依新柳贵，池带乱苔春。
云水正一望，簿书来绕身。
烟波洞庭路，愧彼扁舟人。','',''),('quantangshi-18999','秋夕不寐寄乐天','劉禹錫','quantangshi','','卷19','洞户夜帘卷，华堂秋簟清。
萤飞过池影，蛩思绕阶声。
老枕知将雨，高窗报欲明。
何人谙此景，远问白先生。','',''),('quantangshi-19000','冬日晨兴寄乐天','劉禹錫','quantangshi','','卷19','庭树晓禽动，郡楼残点声。
灯挑红烬落，酒暖白光生。
髪少嫌梳利，颜衰恨镜明。
独吟谁应和，须寄洛阳城。','',''),('quantangshi-19001','答乐天见忆','劉禹錫','quantangshi','','卷19','与老无期约，到来如等闲。
偏伤朋友尽，移兴子孙间。
笔底心无毒，杯前胆不{犭亍}。
唯余忆君梦，飞过武牢关。','',''),('quantangshi-19002','和乐天诮失婢牓者','劉禹錫','quantangshi','','卷19','把镜朝犹在，添香夜不归。
鸳鸯拂瓦去，鹦鹉透笼飞。
不逐张公子，即随刘武威。
新知正相乐，从此脱青衣。','',''),('quantangshi-19003','八月十五日夜半云开然后翫月因书一时之景寄呈乐天','劉禹錫','quantangshi','','卷19','半夜碧云收，中天素月流。
开城邀好客，置酒赏清秋。
影透衣香润，光凝歌黛愁。
斜辉犹可翫，移宴上西楼。','',''),('quantangshi-19004','秋日书怀寄白宾客','劉禹錫','quantangshi','','卷19','州远雄无益，年高健亦衰。
兴情逢酒在，筋力上楼知。
蝉噪芳意尽，雁来愁望时。
商山紫芝客，应不向秋悲。','',''),('quantangshi-19005','酬乐天初冬早寒见寄','劉禹錫','quantangshi','','卷19','乍起衣犹冷，微吟帽半欹。
霜凝南屋瓦，鸡唱后园枝。
洛水碧云晓，吴宫黄叶时。
两传千里意，书札不如诗。','',''),('quantangshi-19006','和令狐相公郡斋对紫薇花','劉禹錫','quantangshi','','卷19','明丽碧天霞，丰茸紫绶花。
香闻荀令宅，艳入孝王家。
几岁自荣乐，高情方叹嗟。
有人移上苑，犹足占年华。','',''),('quantangshi-19007','令狐相公俯赠篇章斐然仰谢','劉禹錫','quantangshi','','卷19','鄂渚临流别，梁园冲雪来。
旅愁随冻释，欢意待花开。
城晓乌频起，池春雁欲回。
饮和心自醉，何必管弦催。','',''),('quantangshi-19008','酬令狐相公早秋见寄','劉禹錫','quantangshi','','卷19','公来第四秋，乐国号无愁。
军士游书肆，商人占酒楼。
熊罴交黑矟，宾客满青油。
今日文章主，梁王不姓刘。','',''),('quantangshi-19009','和令狐相公入潼关','劉禹錫','quantangshi','','卷19','寒光照旌节，关路晓无尘。
吏谒前丞相，山迎旧主人。
东瞻军府静，西望敕书频。
心共黄河水，同升天汉津。','',''),('quantangshi-19010','和令狐相公寻白阁老见留小饮因赠','劉禹錫','quantangshi','','卷20','傲士更逢酒，乐天仍对花。
文章管星历，情兴占年华。
宦达翻思退，名高却不夸。
惟存浩然气，相共赏烟霞。','',''),('quantangshi-19011','酬令狐相公雪中游玄都见忆','劉禹錫','quantangshi','','卷20','好雪动高情，心期在玉京。
人披鹤氅出，马踏象筵行。
照耀楼台变，淋漓松桂清。
玄都留五字，使入步虚声。','',''),('quantangshi-19012','和令狐相公以司空裴相见招南亭看雪四韵','劉禹錫','quantangshi','','卷20','重门不下关，枢务有余闲。
上客同看雪，高亭尽见山。
瑞呈霄汉外，兴入笑言间。
知是平阳会，人人带酒还。','',''),('quantangshi-19013','和郓州令狐相公春晚对花','劉禹錫','quantangshi','','卷20','朱门退公后，高兴对花枝。
望阙无穷思，看书欲尽时。
含芳朝竞发，凝艳晚相宜。
人意殷勤惜，狂风岂得知。','',''),('quantangshi-19014','酬令狐相公春日言怀见寄','劉禹錫','quantangshi','','卷20','前陪看花处，邻里近王昌。
今想临戎地，旌旗出汶阳。
营飞柳絮雪，门耀戟枝霜。
东望清河水，心随艑上郎。','',''),('quantangshi-19015','途次大梁雪中奉天平令狐相公书问兼示新什因思曩岁从此拜辞形于短篇以申仰谢','劉禹錫','quantangshi','','卷20','远守宦情薄，故人书信来。
共曾花下别，今独雪中回。
纸尾得新什，眉头还暂开。
此时同雁鹜，池上一徘徊。','',''),('quantangshi-19016','酬令狐相公秋怀见寄','劉禹錫','quantangshi','','卷20','寂寞蝉声静，差池燕羽回。
秋风怜越绝，朔气想台骀。
相去数千里，无因同一杯。
殷勤望飞雁，新自塞垣来。','',''),('quantangshi-19017','酬[太]原令狐相公见寄','劉禹錫','quantangshi','','卷20','书信来天外，琼瑶满匣中。
衣冠南渡远，旌节北门雄。
鹤唳华亭月，马嘶榆塞风。
山川几千里，惟有两心同。','',''),('quantangshi-19018','酬令狐相公岁暮远怀见寄','劉禹錫','quantangshi','','卷20','别侣孤鹤怨，冲天威凤归。
容光一以间，梦想是耶非。
芳讯远弥重，知音老更稀。
不如湖上雁，北向整毛衣。','',''),('quantangshi-19019','酬令狐相公亲仁郭家花下即事见寄','劉禹錫','quantangshi','','卷20','荀令园林好，山公游赏频。
岂无花下侣，远望眼中人。
斜日渐移影，落英纷委尘。
一吟相思曲，惆怅江南春。','',''),('quantangshi-19020','酬令狐相公首夏闲居书怀见寄','劉禹錫','quantangshi','','卷20','蕙草芳未歇，绿槐阴已成。
金罍唯独酌，瑶瑟有离声。
翔泳各殊势，篇章空寄情。
应怜三十载，未变使君名。','',''),('quantangshi-19021','酬令狐相公庭前白菊花谢偶书所怀见寄','劉禹錫','quantangshi','','卷20','数丛如雪色，一旦冒霜开。
寒蘂差池落，清香断续来。
思深含别怨，芳谢惜年催。
千里难同赏，看看又早梅。','',''),('quantangshi-19022','酬令狐相公季冬南郊宿斋见寄','劉禹錫','quantangshi','','卷20','坛下雪初霁，南城冻欲生。
斋心祠上帝，高步领名卿。
沐浴含芳泽，周旋听佩声。
犹怜广平守，寂寞竟何成。','',''),('quantangshi-19023','贞元中侍郎舅氏牧华州时余再忝科第前后由华觐谒陪登伏毒寺屡焉亦曾赋诗题于梁栋今典冯诩暇日登楼南望三峰浩然生思追想昔年之事因成篇题旧寺','劉禹錫','quantangshi','','卷20','曾作关中客，频经伏毒岩。
晴烟沙苑树，晚日渭川帆。
昔是青春貌，今悲白雪髯。
郡楼空一望，含意卷高帘。','',''),('quantangshi-19024','酬令狐相公杏园花下饮有怀见寄','劉禹錫','quantangshi','','卷20','年年曲江望，花发即经过。
未饮心先醉，临风思倍多。
三春看又尽，两地欲如何。
日望长安道，空成劳者歌。','',''),('quantangshi-19025','令狐相公见示题洋州崔侍郎宅双木瓜花顷接侍郎同舍陪宴树下吟翫来什辄成和章','劉禹錫','quantangshi','','卷20','金牛蜀楼远，玉树帝城春。
荣耀生华馆，逢迎欠主人。
帘前疑小雪，墙外丽行尘。
来去皆回首，情深是德邻。','',''),('quantangshi-19026','和令狐相公春早朝回盐铁使院中作','劉禹錫','quantangshi','','卷20','柳动御沟清，威迟堤上行。
城隅日未过，山色雨初晴。
莺避传呼起，花临府署明。
簿书盈几案，要自有高情。','',''),('quantangshi-19027','和令狐仆射相公题龙回寺','劉禹錫','quantangshi','','卷20','兹地回銮日，皇家禅圣时。
路无胡马迹，人识汉官仪。
天子旌旗度，法王龙象随。
知怀去家叹，经此益迟迟。','',''),('quantangshi-19028','令狐相公频示新什早春南望遐想汉中因抒短章以寄情愫','劉禹錫','quantangshi','','卷20','军城临汉水，旌斾起春风。
远思见江草，归心看塞鸿。
野花沿古道，新叶映行宫。
惟有诗兼酒，朝朝两不同。','',''),('quantangshi-19029','和令狐相公咏栀子花','劉禹錫','quantangshi','','卷20','蜀国花已尽，越桃今已开。
色疑琼树倚，香似玉京来。
且赏同心处，那忧别叶催。
佳人如拟咏，何必待寒梅。','',''),('quantangshi-19030','酬令狐相公新蝉见寄','劉禹錫','quantangshi','','卷20','相去三千里，闻蝉同此时。
清吟晓露叶，愁噪夕阳枝。
忽尔弦断绝，俄闻管参差。
洛桥碧云晚，西望佳人期。','',''),('quantangshi-19031','酬乐天闲卧见寄','劉禹錫','quantangshi','','卷20','散诞向阳眠，将闲敌地仙。
诗情茶助爽，药力酒能宣。
风碎竹间日，露明池底天。
同年未同隐，缘欠买山钱。','',''),('quantangshi-19032','酬乐天小亭寒夜有怀','劉禹錫','quantangshi','','卷20','寒夜阴云起，疎林宿鸟惊。
斜风闪灯影，迸雪打窗声。
竟夕不能寐，同年知此情。
汉皇无奈老，何况本书生。','',''),('quantangshi-19033','将之官留辞裴令公留守','劉禹錫','quantangshi','','卷20','祖帐临伊水，前旌指渭河。
风烟里数少，云雨别情多。
重叠受恩久，邅回如命何。
东山与东阁，终异再经过。','',''),('quantangshi-19034','酬喜相遇同州与乐天替代','劉禹錫','quantangshi','','卷20','旧托松心契，新交竹使符。
行年同甲子，筋力羡丁夫。
别后诗成帙，携来酒满壶。
今朝停五马，不独为罗敷。','',''),('quantangshi-19035','闲坐忆乐天以诗问酒熟未','劉禹錫','quantangshi','','卷20','案头开缥帙，肘后检青囊。
唯有达生理，应无治老方。
减书存眼力，省事养心王。
君酒何时熟，相携入醉乡。','',''),('quantangshi-19036','秋中暑退赠乐天','劉禹錫','quantangshi','','卷20','暑服宜秋着，清琴入夜弹。
人情皆向菊，风意欲摧兰。
岁稔贫心泰，天凉病体安。
相逢取次第，却甚少年欢。','',''),('quantangshi-19037','乐天池馆夏景方妍白莲初开彩舟空泊唯邀缁侣因以戏之','劉禹錫','quantangshi','','卷20','池馆今正好，主人何寂然。
白莲方出水，碧树未鸣蝉。
静室宵闻磬，斋厨晚绝烟。
蕃僧如共载，应不是神仙。','',''),('quantangshi-19038','酬乐天感秋凉见寄','劉禹錫','quantangshi','','卷20','庭晚初辨色，林秋微有声。
槿衰犹强笑，莲逈却多情。
檐燕归心动，韝鹰俊气生。
闲人占闲景，酒熟且同倾。','',''),('quantangshi-19039','秋晚新晴夜月如练有怀乐天','劉禹錫','quantangshi','','卷20','雨歇晚霞明，风调夜景清。
月高微晕散，云薄细鳞生。
露草百虫思，秋林千叶声。
相望一步地，脉脉万重情。','',''),('quantangshi-19040','新秋对月寄乐天','劉禹錫','quantangshi','','卷20','月露发光彩，此时方见秋。
夜凉金气应，天静火星流。
蛩响偏依井，萤飞直过楼。
相知尽白首，清景复追游。','',''),('quantangshi-19041','酬乐天小台晚坐见忆','劉禹錫','quantangshi','','卷20','小台堪远望，独上清秋时。
有酒无人劝，看山秖自知。
幽禽啭新竹，孤莲落静池。
高门勿遽掩，好客无前期。','',''),('quantangshi-19042','早秋雨后寄乐天','劉禹錫','quantangshi','','卷20','夜云起河汉，朝雨洒高林。
梧叶先风落，草虫迎湿吟。
簟凉扇恩薄，室静琴思深。
且喜炎前别，安能怀寸阴。','',''),('quantangshi-19043','秋晚病中乐天以诗见问力疾奉酬','劉禹錫','quantangshi','','卷20','耳虚多听远，展传晨鸡鸣。
一室背灯卧，中宵扫叶声。
兰芳经雨败，鹤病得秋轻。
肯踏衡门草，唯应是友生。','',''),('quantangshi-19044','和乐天烧药不成命酒独醉','劉禹錫','quantangshi','','卷20','九转欲成就，百神应主持。
婴啼鼎上去，老貌镜前悲。
却顾空丹竈，回心向酒巵。
醺然耳热后，暂似少年时。','',''),('quantangshi-19045','元日乐天见过因举酒为贺','劉禹錫','quantangshi','','卷20','渐入有年数，喜逢新岁来。
震方天籁动，寅位帝车回。
门巷扫残雪，林园惊早梅。
与君同甲子，寿酒让先杯。','',''),('quantangshi-19046','酬马大夫以愚献通草茇葜酒感通拔二字因而寄别之作','劉禹錫','quantangshi','','卷20','泥沙难振拔，谁复问穷通。
莫讶提壶赠，家传枕麴风。
成谣独酌后，深意片言中。
不进终无已，应须荀令公。','',''),('quantangshi-19047','奉和司空裴相公中书即事通简旧僚之作','劉禹錫','quantangshi','','卷20','谭笑在岩廊，人人尽所长。
仪形见山立，文字动星光。
日运丹青笔，时看赤白囊。
伫闻戎马息，入贺领鸳行。','',''),('quantangshi-19048','微之镇武昌中路见寄蓝桥怀旧之作凄然继和兼寄安平','劉禹錫','quantangshi','','卷20','今日油幢引，他年黄纸追。
同为三楚客，独有九霄期。
宿草恨长在，伤禽飞尚迟。
武昌应已到，新柳映红旗。','',''),('quantangshi-19049','将赴苏州途出洛阳留守李相公累申宴饯宠行话旧形于篇章谨抒下情以申仰谢','劉禹錫','quantangshi','','卷20','岁杪风物动，雪余宫苑晴。
兔园宾客至，金谷管弦声。
洛水故人别，吴宫新燕迎。
越郎忧不浅，怀袖有琼英。','',''),('quantangshi-19050','牛相公留守见示城外新墅有溪竹秋月亲情多往宿游恨不得去因成四韵兼简洛中亲故之什兼命同作','劉禹錫','quantangshi','','卷20','别墅洛城外，月明村野通。
光辉满地上，丝管发舟中。
堤艳菊花露，岛凉松叶风。
高情限清禁，寒漏滴深宫。','',''),('quantangshi-19051','牛相公林亭雨后偶成','劉禹錫','quantangshi','','卷20','飞雨过池阁，浮光生草树。
新竹开粉奁，初莲爇香注。
野花无时节，水鸟自来去。
若问知境人，人间第一处。','',''),('quantangshi-19052','酬滑州李尚书秋日见寄','劉禹錫','quantangshi','','卷20','一入石渠署，三闻宫树蝉。
丹霄未得路，白发又添年。
双节外台贵，孤箫中禁传。
征黄在旦夕，早晚发南燕。','',''),('quantangshi-19053','和西川李尚书汉州微月游房太尉西湖','劉禹錫','quantangshi','','卷20','木落汉川夜，西湖悬玉鈎。
旌旗环水次，舟檝泛中流。
目极想前事，神交如共游。
瑶琴久已绝，松韵自悲秋。','',''),('quantangshi-19054','和重题','劉禹錫','quantangshi','','卷20','林端落照尽，湖上远岚清。
水榭芝兰室，仙舟鱼鸟情。
人琴久寂寞，烟月若平生。
一泛钓璜处，再吟锵玉声。','',''),('quantangshi-19055','酬李相公喜归乡国自巩县夜泛洛水见寄','劉禹錫','quantangshi','','卷20','巩树烟月上，清光含碧流。
且无三已色，犹泛五湖州。
鹏息风还起，凤归林正秋。
虽攀小山桂，此地不淹留。','',''),('quantangshi-19056','和李相公平泉潭上喜见初月','劉禹錫','quantangshi','','卷20','家山见初月，林壑悄无尘。
幽境此何夕，清光如为人。
潭空破镜入，风动翠蛾嚬。
会向琐窗望，追思伊洛滨。','',''),('quantangshi-19057','和李相公初归平泉过龙门南岭遥望山居即事','劉禹錫','quantangshi','','卷20','暂别明庭去，初随优诏还。
曾为鹏鸟赋，喜过凿龙山。
新墅烟火起，野程泉石间。
岩廊人望在，只得片时闲。','',''),('quantangshi-19058','和李相公以平泉新墅获方外之名因为诗以报洛中士君子兼见寄之什','劉禹錫','quantangshi','','卷20','业继韦平后，家依昆阆间。
恩华辞北第，潇洒爱东山。
满室图书在，入门松菊闲。
垂天虽暂息，一举出人寰。','',''),('quantangshi-19059','发苏州后登武丘寺望海楼','劉禹錫','quantangshi','','卷20','独宿望海楼，夜深珍木冷。
僧房已闭户，山月方出岭。
碧池涵劒彩，宝刹摇星影。
却忆郡斋中，虚眠此时景。','',''),('quantangshi-19060','松江送处州奚使君','劉禹錫','quantangshi','','卷20','吴越古今路，沧波朝夕流。
从来别离地，能使管弦愁。
江草带烟暮，海云含雨秋。
知君五陵客，不乐石门游。','',''),('quantangshi-19061','题报恩寺','劉禹錫','quantangshi','','卷20','云外支硎寺，名声敌虎丘。
石文留马迹，峰势耸牛头。
泉眼潜通海，松门预带秋。
迟回好风景，王谢昔曾游。','',''),('quantangshi-19062','罢郡姑苏北归渡杨子津 一','劉禹錫','quantangshi','','卷20','几岁悲南国，今朝赋北征。
归心渡江勇，病体得秋轻。
海阔石门小，城高粉堞明。
金山旧游寺，过岸听钟声。','',''),('quantangshi-19063','罢郡姑苏北归渡杨子津 二','劉禹錫','quantangshi','','卷20','故国荒台在，前临震泽波。
绮罗随世尽，麋鹿古时多。
筑用金锤力，摧因石鼠窠。
昔年雕辇路，唯有采樵歌。','',''),('quantangshi-19064','寻汪道士不遇','劉禹錫','quantangshi','','卷20','仙子东南秀，泠然善驭风。
笙歌五云里，天地一壶中。
受箓金华洞，焚香玉帝宫。
我来君闭户，应是向崆峒。','',''),('quantangshi-19065','谢柳子厚寄叠石砚','劉禹錫','quantangshi','','卷20','常时同砚席，寄砚感离羣。
清越敲寒玉，参差叠碧云。
烟岚馀斐亹，水墨两氛氲。
好与陶贞白，松窻写紫文。','',''),('quantangshi-19066','元日感怀','劉禹錫','quantangshi','','卷20','振蛰春潜至，湘南人未归。
身加一日长，心觉去年非。
燎火委虚烬，儿童炫彩衣。
异乡无旧识，车马到门稀。','',''),('quantangshi-19067','谢宣州崔相公赐马','劉禹錫','quantangshi','','卷20','浮云金络膝，昨日别朱轮。
衔草如怀恋，嘶风尚意频。
曾将此君子，不是换佳人。
从此西归路，应容蹑后尘。','',''),('quantangshi-19068','南中书来','劉禹錫','quantangshi','','卷20','君书问风俗，此地接炎州。
淫祀多青鬼，居人少白头。
旅情偏在夜，乡思岂唯秋。
每羡朝宗水，门前尽日流。','',''),('quantangshi-19069','题招隐寺','劉禹錫','quantangshi','','卷20','隐士遗尘在，高僧精舍开。
地形临渚断，江势触山回。
楚野花多思，南禽声例哀。
殷勤最高顶，闲即望乡来。','',''),('quantangshi-19070','思归寄山中友人','劉禹錫','quantangshi','','卷20','萧条对秋色，相忆在云泉。
木落病身死，潮平归思悬。
凉钟山顶寺，暝火渡头船。
此地非吾土，闲留又一年。','',''),('quantangshi-19071','有感','劉禹錫','quantangshi','','卷20','死且不自觉，其余安可论。
昨宵凤池客，今日雀罗门。
骑吏尘未息，铭旌风已翻。
平生红粉爱，惟解哭黄昏。','',''),('quantangshi-19072','途次敷水驿伏覩华州舅氏昔日行县题诗处潸然有感','劉禹錫','quantangshi','','卷20','昔日股肱守，朱轮兹地游。
繁华日已谢，章句此空留。
蔓草佳城闭，故林棠树秋。
今来重垂泪，不忍过西州。','',''),('quantangshi-19073','奉和郑相公以考功十弟山姜花俯赐篇咏','劉禹錫','quantangshi','','卷20','采撷黄姜蘂，封题青琐闱。
共闻调膳日，正是退朝归。
响为纤筵发，情随彩翰飞。
故将天下宝，万里与光辉。','',''),('quantangshi-19074','题淳于髠墓','劉禹錫','quantangshi','','卷20','生为齐赘壻，死作楚先贤。
应以客卿葬，故临官道边。
寓言本多兴，放意能合权。
我有一石酒，置君坟树前。','',''),('quantangshi-19075','送春词','劉禹錫','quantangshi','','卷20','昨来楼上迎春处，今日登楼又送归。
兰蘂残妆含露泣，柳条长袖向风挥。
佳人对镜容颜改，楚客临江心事违。
万古至今同此恨，无如一醉尽忘机。','',''),('quantangshi-19076','送李尚书镇滑州','劉禹錫','quantangshi','','卷20','南徐报政入文昌，东郡须才别建章。
视草名高同蜀客，拥旄年少胜荀郎。
黄河一曲当城下，缇骑千重照路傍。
自古相门还出相，如今人望在岩廊。','',''),('quantangshi-19077','送浑大夫赴丰州','劉禹錫','quantangshi','','卷20','凤衔新诏降恩华，又见旌旗出浑家。
故吏来辞辛属国，精兵愿逐李轻车。
毡裘君长迎风驭，锦带酋豪踏雪衙。
其奈明年好春日，无人唤看牡丹花。','',''),('quantangshi-19078','送源中丞充新罗册立使','劉禹錫','quantangshi','','卷20','相门才子称华簪，持节东行捧德音。
身带霜威辞凤阙，口传天语到鸡林。
烟开鳌背千寻碧，日浴鲸波万顷金。
想见扶桑受恩处，一时西拜尽倾心。','',''),('quantangshi-19079','送王司马之陕州','劉禹錫','quantangshi','','卷20','暂辍清斋出太常，空携诗卷赴甘棠。
府公既有朝中旧，司马应容酒后狂。
案牍来时唯署字，风烟入兴便成章。
两京大道多游客，每遇词人战一场。','',''),('quantangshi-19080','洛中送杨处厚入关便游蜀','劉禹錫','quantangshi','','卷20','洛阳秋日正凄凄，君去西秦更向西。
旧学三冬今转富，曾伤六翮养初齐。
王城晓入窥丹凤，蜀路晴来见碧鸡。
早识卧龙应有分，不妨从此蹑丹梯。','',''),('quantangshi-19081','送周使君罢渝州归郢州别墅','劉禹錫','quantangshi','','卷20','君思郢上吟归去，故自渝南掷郡章。
野戍岸边留画舸，绿萝阴下到山庄。
池荷雨后依香起，庭草春深绶带长。
只恐鸣驺催上道，不容待得晚菘尝。','',''),('quantangshi-19082','奉送浙西李仆射相公赴镇','劉禹錫','quantangshi','','卷20','建节东行是旧游，欢声喜气满吴州。
郡人重得黄丞相，童子争迎郭细侯。
诏下初辞温室树，梦中先到景阳楼。
自怜不识平津阁，遥望旌旗汝水头。','',''),('quantangshi-19083','重送浙西李相公顷廉问江南已经七载后歴滑台剑南两镇遂入相今复领旧地新加旌旄','劉禹錫','quantangshi','','卷20','江北万人看玉节，江南千骑引金铙。
凤从池上游沧海，鹤到辽东识旧巢。
城下清波含百谷，窻中远岫列三茅。
碧鸡白马回翔久，却忆朱方是乐郊。','',''),('quantangshi-19084','送前进士蔡京赴学究科','劉禹錫','quantangshi','','卷20','耳闻战鼓带经锄，振发声名自里闾。
已是世间能赋客，更攻窻下绝编书。
朱门达者谁能识，绛帐书生尽不如。
幸遇天官旧丞相，知君无翼上空虚。','',''),('quantangshi-19085','送唐舍人出镇闽中','劉禹錫','quantangshi','','卷20','暂辞鸳鹭出蓬瀛，忽拥貔貅镇粤城。
闽岭夏云迎皂盖，建溪秋树映红旌。
山川远地由来好，富贵当年别有情。
了却人间婚嫁事，复归朝右作公卿。','',''),('quantangshi-19086','送李中丞赴楚州','劉禹錫','quantangshi','','卷20','缇骑朱旗入楚城，士林皆贺振家声。
儿童但喜迎宾守，故吏犹应记姓名。
万顷水田连郭秀，四时烟月映淮清。
忆君初得昆山玉，同向扬州携手行。','',''),('quantangshi-19087','奉送李户部侍郎自河南尹再除本官归阙','劉禹錫','quantangshi','','卷20','昔年内署振雄词，今日东都结去思。
宫女犹传洞箫赋，国人先咏衮衣诗。
华星却复文昌位，别鹤重归太乙池。
想到金闺待通籍，一时惊喜见风仪。','',''),('quantangshi-19088','送蕲州李郎中赴任','劉禹錫','quantangshi','','卷20','楚关蕲水路非赊，东望云山日夕佳。
薤叶照人呈夏簟，松花满盌试新茶。
楼中饮兴因明月，江上诗情为晚霞。
北地交亲长引领，早将玄鬓到京华。','',''),('quantangshi-19089','送国子令狐博士赴兴元觐省','劉禹錫','quantangshi','','卷20','相门才子高阳族，学省清资五品官。
谏院过时荣棣萼，谢庭归去踏芝兰。
山中花带烟岚晚，栈底江涵雪水寒。
伯仲到家人尽贺，柳营莲府递相欢。','',''),('quantangshi-19090','送李二十九兄员外赴邠宁使幕','劉禹錫','quantangshi','','卷20','家袭韦平身业文，素风清白至今贫。
南宫通籍新郎吏，西候从戎旧主人。
城外草黄秋有雪，烽头烟静虏无尘。
鼎门为别霜天晓，剩把离殇三五巡。','',''),('quantangshi-19091','送分司陈郎中秖召直史馆重修三圣实録','劉禹錫','quantangshi','','卷20','蝉鸣官树引行车，言自成周赴玉除。
远取南朝贵公子，重修东观帝王书。
常时载笔窥金匮，暇日登楼到石渠。
若问旧人刘子政，如今白首在南徐。','',''),('quantangshi-19092','送慧则法师归上都因呈广宣上人','劉禹錫','quantangshi','','卷20','昨日东林看讲时，都人象马蹋琉璃。
雪山童子应前世，金粟如来是本师。
一锡言归九城路，三衣曾拂万年枝。
休公久别如相问，楚客逢秋心更悲。','',''),('quantangshi-19093','送义舟师却还黔南','劉禹錫','quantangshi','','卷20','黔江秋水浸云霓，独泛慈航路不迷。
猨狖窥斋林叶动，蛟龙闻咒浪花低。
如莲半偈心常悟，问菊新诗手自携。
常说摩围似灵鹫，却将山屐上丹梯。','',''),('quantangshi-19094','送景玄师东归','劉禹錫','quantangshi','','卷20','东林寺里一沙弥，心爱当时才子诗。
山下偶随流水出，秋来却赴白云期。
滩头蹑屐挑沙菜，路上停舟读古碑。
想到旧房抛锡杖，小松应有过檐枝。','',''),('quantangshi-19095','汉寿城春望','劉禹錫','quantangshi','','卷20','汉寿城边野草春，荒祠古墓对荆榛。
田中牧竖烧刍狗，陌上行人看石麟。
华表半空经霹雳，碑文才见满埃尘。
不知何日东瀛变，此地还成要路津。','',''),('quantangshi-19096','荆门道怀古','劉禹錫','quantangshi','','卷20','南国山川旧帝畿，宋台梁馆尚依稀。
马嘶古道行人歇，麦秀空城野雉飞。
风吹落叶填宫井，火入荒陵化宝衣。
徒使词臣庾开府，咸阳终日苦思归。','',''),('quantangshi-19097','朗州窦员外见示与澧州元郎中郡斋赠答长句二篇因以继和','劉禹錫','quantangshi','','卷20','鸳鹭差池出建章，彩旗朱户蔚相望。
新恩共理犬牙地，昨日同含鸡舌香。
白芷江边分驿路，山桃蹊外接甘棠。
应怜一罢金闺籍，枉渚逢春十度伤。','',''),('quantangshi-19098','早春对雪奉寄澧州元郎中','劉禹錫','quantangshi','','卷20','新赐鱼书墨未干，贤人暂出远人安。
朝驱旌斾行时令，夜见星辰忆旧官。
梅蘂覆堦铃阁暖，雪峰当户戟枝寒。
宁知楚客思公子，北望长吟澧有兰。','',''),('quantangshi-19099','窦朗州见示与澧州元郎中早秋赠答命同作','劉禹錫','quantangshi','','卷20','邻境诸侯同舍郎，芷江兰浦恨无梁。
秋风门外旌旗动，晓露庭中橘柚香。
玉簟微凉宜白昼，金笳入暮应清商。
骚人昨夜闻鶗鴂，不叹流年惜众芳。','',''),('quantangshi-19100','松滋渡望峡中','劉禹錫','quantangshi','','卷20','渡头轻雨洒寒梅，云际溶溶雪水来。
梦渚草长迷楚望，夷陵土黑有秦灰。
巴人泪应猿声落，蜀客船从鸟道回。
十二碧峰何处所，永安宫外是荒台。','',''),('quantangshi-19101','衢州徐员外使君遗以缟紵兼竹书箱因成一篇用答佳贶','劉禹錫','quantangshi','','卷20','烂柯山下旧仙郎，列宿来添婺女光。
远放歌声分白紵，知传家学与青箱。
水朝沧海何时去，兰在幽林亦自芳。
闻说天台有遗爱，人将琪树比甘棠。','',''),('quantangshi-19102','唐秀才赠端州紫石砚以诗答之','劉禹錫','quantangshi','','卷20','端州石砚人间重，赠我因知正草玄。
阙里庙堂空旧物，开方竈下岂天然。
玉蜍吐水霞光静，彩翰摇风绛锦鲜。
此日佣工记名姓，因君数到墨池前。','',''),('quantangshi-19103','览董评事思归之什因以诗赠','劉禹錫','quantangshi','','卷20','几年油幕佐征东，却泛沧浪狎钓童。
欹枕醉眠成戏蝶，抱琴闲望送归鸿。
文儒自袭胶西相，倚伏能齐塞上翁。
更说扁舟动乡思，青菰已熟奈秋风。','',''),('quantangshi-19104','谢寺双桧','劉禹錫','quantangshi','','卷20','双桧苍然古貌奇，含烟吐雾郁参差。
晚依禅客当金殿，初对将军映画旗。
龙象界中成宝盖，鸳鸯瓦上出高枝。
长明灯是前朝焰，曾照青青年少时。','',''),('quantangshi-19105','寄杨八寿州','劉禹錫','quantangshi','','卷20','风猎红旗入寿春，满城歌舞向朱轮。
八公山下清淮水，千骑尘中白面人。
桂岭雨余多鹤迹，茗园晴望似龙鳞。
圣朝方用敢言者，次第应须旧谏臣。','',''),('quantangshi-19106','洛中寺北楼见贺监草书题诗','劉禹錫','quantangshi','','卷20','高楼贺监昔曾登，壁上笔踪龙虎腾。
中国书流尚皇象，北朝文士重徐陵。
偶因独见空惊目，恨不同时便伏膺。
唯恐尘埃转磨灭，再三珍重嘱山僧。','',''),('quantangshi-19107','闻韩宾擢第归觐以诗美之兼贺韩十五曹长时韩牧永州','劉禹錫','quantangshi','','卷20','零陵香草满郊坰，丹穴雏飞入翠屏。
孝若归来成画赞，孟阳别后有山铭。
兰陔旧地花才结，桂树新枝色更青。
为报儒林丈人道，如今从此鬓星星。','',''),('quantangshi-19108','宣上人远寄和礼部王侍郎放榜后诗因而继和','劉禹錫','quantangshi','','卷20','礼闱新榜动长安，九陌人人走马看。
一日声名遍天下，满城桃李属春官。
自吟白雪诠词赋，指示青云借羽翰。
借问至公谁印可，支郎天眼定中观。','',''),('quantangshi-19109','赠东岳张炼师','劉禹錫','quantangshi','','卷20','东岳真人张炼师，高情雅淡世间稀。
堪为列女书青简，久事元君住翠微。
金缕机中抛锦字，玉清台上着霓衣。
云衢不要吹箫伴，只拟乘鸾独自飞。','',''),('quantangshi-19110','秘书山崔少监见示坠马长句因而和之','劉禹錫','quantangshi','','卷20','麟台少[监]旧仙郎，洛水桥边坠马伤。
尘污腰间青襞绶，风飘掌上紫游缰。
上车着作应来问，折臂三公定送方。
犹赖德全如醉者，不妨吟咏入篇章。','',''),('quantangshi-19111','寄杨虢州与之旧姻','劉禹錫','quantangshi','','卷20','避地江湖知几春，今来本郡拥朱轮。
阮郎无复里中旧，杨仆却为关外人。
各系一官难命驾，每怀前好易沾巾。
玉城山里多灵药，摆落功名且养神。','',''),('quantangshi-19112','秋日题窦员外崇德里新居','劉禹錫','quantangshi','','卷20','长爱街西风景闲，到君居处暂开颜。
清光门外一渠水，秋色墙头数点山。
疎种碧松通月朗，多栽红药待春还。
莫言堆案无余地，认得诗人在此间。','',''),('quantangshi-19113','蒙恩转仪曹郎依前充集贤学士举韩潮州自代因寄七言','劉禹錫','quantangshi','','卷20','翔鸾阙下谢恩初，通籍由来在石渠。
暂入南宫判祥瑞，还归内殿阅图书。
故人犹在三江外，同病凡经二纪余。
今日荐君嗟久滞，不惟文体似相如。','',''),('quantangshi-19114','途次华州陪钱大夫登城北楼春望因覩李崔令狐三相国唱和之什翰林旧侣继踵华城山水清高鸾凤翔集皆忝宿眷遂题此诗','劉禹錫','quantangshi','','卷20','城楼四望出风尘，见尽关西渭北春。
百二山河雄上国，一双旌斾委名臣。
壁中今日题诗处，天上同时草诏人。
莫怪老郎呈滥吹，宦途虽别旧情亲。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-19115','始闻秋风','劉禹錫','quantangshi','','卷20','昔看黄菊与君别，今听玄蝉我却回。
五夜飕飗枕前觉，一年颜状镜中来。
马思边草拳毛动，雕眄青云睡眼开。
天地肃清堪四望，为君扶病上高台。','',''),('quantangshi-19116','洛中初冬拜表有怀上京故人','劉禹錫','quantangshi','','卷20','凤楼南面控三条，拜表郎官早渡桥。
清洛晓光铺碧簟，上阳霜叶剪红绡。
省门簪组初成列，云路鸳鸾想退朝。
寄谢殷勤九天侣，抢榆水击各逍遥。','',''),('quantangshi-19117','尉迟郎中见示自南迁牵复却至洛城东旧居之作因以和之','劉禹錫','quantangshi','','卷20','曾遭飞语十年谪，新受恩光万里还。
朝服不妨游洛浦，郊园依旧看嵩山。
竹含天籁清商乐，水遶庭台碧玉环。
留作功成退身地，如今只是暂时闲。','',''),('quantangshi-19118','洛中酬福建陈判官见赠','劉禹錫','quantangshi','','卷20','潦倒声名拥肿材，一生多故苦邅回。
南宫旧籍遥相管，东洛闲门昼未开。
静对道流论药石，偶逢词客与琼瑰。
怪君近日文锋利，新向延平看劒来。','',''),('quantangshi-19119','和苏十郎中谢病闲居时严常侍萧给事同过访叹初有二毛之作','劉禹錫','quantangshi','','卷20','清羸隐几望云空，左掖鸳鸾到室中。
一卷素书消永日，数茎斑髪对秋风。
菱花照后容虽改，蓍草占来命已通。
莫怪人人惊早白，缘君尚是黑头翁。','',''),('quantangshi-19120','酬淮南廖参谋秋夕见过之作','劉禹錫','quantangshi','','卷20','扬州从事夜相寻，无限新诗月下吟。
初服已惊玄髪长，高情犹向碧云深。
语余时举一杯酒，坐久方闻四处砧。
不逐繁华访闲散，知君摆落俗人心。','',''),('quantangshi-19121','题王郎中宣义里新居','劉禹錫','quantangshi','','卷20','爱君新买街西宅，客到如游鄠杜间。
雨后退朝贪种树，申时出省趂看山。
门前巷陌三条近，墙内池亭万境闲。
见拟移居作邻里，不论时节请开关。','',''),('quantangshi-19122','酬朗州崔员外与任十四兄侍御同过鄙人旧居见怀之什时守吴郡','劉禹錫','quantangshi','','卷20','昔日居邻招屈亭，枫林橘树鹧鸪声。
一辞御苑青门去，十见蛮江白芷生。
自此曾沾宣室召，如今又守阖闾城。
何人万里能相忆，同舍仙郎与外兄。','',''),('quantangshi-19123','刘驸马水亭避暑','劉禹錫','quantangshi','','卷20','千竿竹翠数莲红，水阁虚凉玉簟空。
琥珀琖红疑漏酒，水晶帘莹更通风。
赐冰满盌沈朱实，法馔盈盘覆碧笼。
尽日逍遥避烦暑，再三珍重主人翁。','',''),('quantangshi-19124','述旧贺迁寄陕虢孙常侍','劉禹錫','quantangshi','','卷20','南宫幸袭芝兰后，左辅曾交印绶来。
多病未离清洛苑，新恩已历望仙台。
关头古塞桃林静，城下长河竹箭回。
闻说随车有零雨，此时偏动子荆才。','',''),('quantangshi-19125','江陵严司空见示与成都武相公唱和因命同作','劉禹錫','quantangshi','','卷20','南荆西蜀大行台，幕府旌门相对开。
名重三司平水土，威雄八阵役风雷。
彩云朝望青城起，锦浪秋经白帝来。
不是郢中清唱发，谁当丞相掞天才。','',''),('quantangshi-19126','庙庭偃松诗','劉禹錫','quantangshi','','卷20','势轧枝偏根已危，高情一见与扶持。
忽从顦顇有生意，却为离披无俗姿。
影入岩廊行乐处，韵含天籁宿斋时。
谢公莫道东山去，待取阴成满凤池。','',''),('quantangshi-19127','赠致仕滕庶子先辈','劉禹錫','quantangshi','','卷20','朝服归来昼锦荣，登科记上更无兄。
寿觞每使曾孙献，胜境长携众妓行。
[矍]铄据鞍时骋健，殷勤把酒尚多情。
凌寒却向山阴去，衣绣郎君雪里行。','',''),('quantangshi-19128','哭吕衡州时予方谪居','劉禹錫','quantangshi','','卷20','一夜霜风凋玉芝，苍生望绝士林悲。
空怀济世安人略，不见男婚女嫁时。
遗草一函归太史，旅坟三尺近要离。
朔方徙岁行当满，欲为君刊第二碑。','',''),('quantangshi-19129','夔州窦员外使君见示悼妓诗顾余尝识之因命同作','劉禹錫','quantangshi','','卷20','前年曾见两鬟时，今日惊吟悼妓诗。
凤管学成知有籍，龙媒欲换叹无期。
空廊月照常行地，后院花开旧折枝。
寂寞鱼山青草里，何人更立智琼祠。','',''),('quantangshi-19130','窦夔州见寄寒食日忆故姬小红吹笙因和之','劉禹錫','quantangshi','','卷20','鸾声窈眇管参差，清韵初调众乐随。
幽院妆成花下弄，高楼月好夜深吹。
忽惊暮雨飘零尽，唯有朝云梦想期。
闻道今年寒食日，东山旧路独行迟。','',''),('quantangshi-19131','哭庞京兆','劉禹錫','quantangshi','','卷20','俊骨英才气袖然，策名飞步冠羣贤。
逢时已自致高位，得疾还因倚少年。
天上别归京兆府，人间空数茂陵阡。
今朝穗帐哭君处，前日见铺歌舞筵。','',''),('quantangshi-19132','送李庚先辈赴选','劉禹錫','quantangshi','','卷20','一家何啻十朱轮，诸父双飞秉大钧。
曾脱素衣参幕客，却为精舍读书人。
离筵雒水侵杯色，征路函关向晚尘。
今日山公旧宾主，知君不负帝城春。','',''),('quantangshi-19133','阳山庙观赛神','劉禹錫','quantangshi','','卷20','汉家都尉旧征蛮，血食如今配此山。
曲盖幽深苍桧下，洞箫愁绝翠屏间。
荆巫脉脉传神语，野老娑娑起醉颜。
日落风生庙门外，几人连蹋竹歌还。','',''),('quantangshi-19134','送僧元暠东游','劉禹錫','quantangshi','','卷20','宝书翻译学初成，振锡如飞白足轻。
彭泽因家凡几世，灵山预会是前生。
传灯已悟无为理，濡露犹怀罔极情。
从此多逢大居士，何人不愿解珠璎。','',''),('quantangshi-19135','赠日本僧智藏','劉禹錫','quantangshi','','卷20','浮杯万里过沧溟，遍礼名山适性灵。
深夜降龙潭水黑，新秋放鹤野田青。
身无彼我那怀土，心会真如不读经。
为问中华学道者，几人雄猛得宁馨。','',''),('quantangshi-19136','送元简上人适越','劉禹錫','quantangshi','','卷20','孤云出岫本无依，胜境名山即是归。
久向吴门游好寺，还思越水洗尘机。
浙江涛惊狮子吼，稽岭峰疑灵鹫飞。
更入天台石桥去，垂珠璀璨拂三衣。','',''),('quantangshi-19137','送宗密上人归南山草堂寺因谒河南尹白侍郎','劉禹錫','quantangshi','','卷20','宿习修来得慧根，多闻第一却忘言。
自从七祖传心印，不要三乘入便门。
东泛沧江寻古迹，西归紫阁出尘喧。
河南白尹大檀越，好把真经相对翻。','',''),('quantangshi-19138','西塞山怀古','劉禹錫','quantangshi','','卷20','西晋楼船下益州，金陵王气黯然收。
千寻铁锁沈江底，一片降幡出石头。
人世几回伤往事，山形依旧枕江流。
今逢四海为家日，故垒萧萧芦荻秋。','',''),('quantangshi-19139','广宣上人寄在蜀与韦令公唱和诗卷因以令公手扎答诗示之','劉禹錫','quantangshi','','卷20','碧云佳句久传芳，曾向成都住草堂。
振锡常过长者宅，披衣犹带令公香。
一时风景添诗思，八部人天入道塲。
吾家本自有柴桑。','',''),('quantangshi-19140','白舍人自杭州寄新诗有柳色春藏苏小家之句因而戏酬兼寄浙东元相公','劉禹錫','quantangshi','','卷20','钱塘山水有奇声，暂谪仙官领百城。
女妓还闻名小小，使君谁许唤卿卿。
鳌惊震海风雷起，蜃鬬嘘天楼阁成。
莫道骚人在三楚，文星今向斗牛明。','',''),('quantangshi-19141','春日书怀寄东洛白二十二杨八二庶子','劉禹錫','quantangshi','','卷20','曾向空门学坐禅，如今万事尽忘筌。
眼前名利同春梦，醉里风情敌少年。
野草芳菲红锦地，游丝撩乱碧罗天。
心知洛下闲才子，不作诗魔即酒颠。','',''),('quantangshi-19142','白舍人见酬拙诗因以寄谢','劉禹錫','quantangshi','','卷20','虽陪三品散班中，资历从来事不同。
名姓也曾镌石柱，诗篇未得上屏风。
甘陵旧党凋零尽，魏阙新知礼数崇。
烟水五湖如有伴，犹应堪作钓鱼翁。','',''),('quantangshi-19143','白舍人曹长寄新诗有游宴之盛因以戏酬','劉禹錫','quantangshi','','卷20','苏州刺史例能诗，西掖今来替左司。
二八城门开道路，五千兵马引旌旗。
水通山寺笙歌去，骑过虹桥劒戟随。
若共吴王鬬百草，不如应是欠西施。','',''),('quantangshi-19144','苏州白舍人寄新诗有叹早白无儿之句因以赠之','劉禹錫','quantangshi','','卷20','莫嗟华髪与无儿，却是人间久远期。
雪里高山头白早，海中仙果子生迟。
于公必有高门庆，谢守何烦晓镜悲。
幸免如新分非浅，祝君长咏梦熊诗。','',''),('quantangshi-19145','酬乐天扬州初逢席上见赠','劉禹錫','quantangshi','','卷20','巴山楚水凄凉地，二十三年弃置身。
怀旧空吟闻篴赋，到乡翻似烂柯人。
沈舟侧畔千帆过，病树前头万木春。
今日听君歌一曲，暂凭杯酒长精神。','',''),('quantangshi-19146','罢郡归洛途次山阳留辞郭中丞使君','劉禹錫','quantangshi','','卷20','自到山阳不许辞，高斋日夜有佳期。
管弦正合看书院，语笑方酣各咏诗。
银汉雪晴褰翠幕，清淮月影落金巵。
洛阳归客明朝去，容趂城东花发时。','',''),('quantangshi-19147','楚州开元寺北院枸杞临井繁茂可观羣贤赋诗因以继和','劉禹錫','quantangshi','','卷20','僧房药树依寒井，井有香泉树有灵。
翠黛叶生笼石甃，殷红子熟照铜瓶。
枝繁本是仙人杖，根老新成瑞犬形。
上品功能甘露味，还知一勺可延龄。','',''),('quantangshi-19148','和乐天鹦鹉','劉禹錫','quantangshi','','卷20','养来鹦鹉觜初红，宜在朱楼绣户中。
频学唤人缘性慧，偏能识主为情通。
歛毛睡足难销日，嚲翅愁时愿见风。
谁遣聪明好颜色，事须安置入深笼。','',''),('quantangshi-19149','洛中逢白监同话游梁之乐因寄宣武令狐相公','劉禹錫','quantangshi','','卷20','曾经谢病各游梁，今日相逢忆孝王。
少有一身兼将相，更能四面占文章。
开颜坐上催飞盏，廻首庭中看舞枪。
借问风前兼月下，不知何客对胡牀。','',''),('quantangshi-19150','河南王少尹宅燕张常侍白舍人兼呈卢郎中李员外二副使','劉禹錫','quantangshi','','卷20','将星夜落使星来，三省清臣到外台。
事重各衔天子诏，礼成同把故人杯。
卷帘松竹雪初霁，满院池塘春欲回。
第一林亭迎好客，殷勤莫惜玉山颓。','',''),('quantangshi-19151','和宣武令狐相公郡斋对新竹','劉禹錫','quantangshi','','卷20','新竹翛翛韵晓风，隔囱依砌尚蒙笼。
数间素壁初开后，一段清光入坐中。
欹枕闲看知自适，含毫朗咏与谁同。
此君若欲长相见，政事堂东有旧丛。','',''),('quantangshi-19152','和乐天送鹤上裴相公别鹤之作','劉禹錫','quantangshi','','卷20','昨日看成送鹤诗，高笼提出白云司。
朱门乍入应迷路，玉树容栖莫拣枝。
双舞庭中花落处，数声池上月明时。
三山碧海不归去，且向人间呈羽仪。','',''),('quantangshi-19153','阙下待传点呈诸同舍','劉禹錫','quantangshi','','卷20','禁漏晨钟声欲绝，旌旗组绶影相交。
殿含佳气当龙首，阁倚晴天见凤巢。
山色葱笼丹槛外，霞光泛灧翠松梢。
多慙再入金门籍，不敢为文学解嘲。','',''),('quantangshi-19154','和乐天以镜换酒','劉禹錫','quantangshi','','卷20','把取菱花百炼镜，换他竹叶十旬杯。
嚬眉厌老终难去，蘸甲须欢便到来。
妍丑太分迷忌讳，松乔俱傲绝嫌猜。
校量功力相千万，好去从空白玉台。','',''),('quantangshi-19155','同乐天送河南冯尹学士','劉禹錫','quantangshi','','卷20','可怜五马风流地，暂辍金貂侍从才。
阁上掩书刘向去，门前修刺孔融来。
崤陵路静寒无雨，洛水桥长昼起雷。
共羡府中棠棣好，先于城外百花开。','',''),('quantangshi-19156','同白二十二赠王山人','劉禹錫','quantangshi','','卷20','爱名之世忘名客，多事之时无事身。
古老相传见来久，岁年虽变貌常新。
飞章上达三清路，受箓平交五岳神。
笑听冬冬朝暮鼓，只能催得市朝人。','',''),('quantangshi-19157','题集贤阁','劉禹錫','quantangshi','','卷20','凤池西畔图书府，玉树玲珑景气闲。
长听余风送天乐，时登高阁望人寰。
青山云绕栏干外，紫殿香来步武间。
曾是先贤翔集地，每看壁记一慙颜。','',''),('quantangshi-19158','和令狐相公初归京国赋诗言怀','劉禹錫','quantangshi','','卷20','凌云羽翮掞天才，扬历中枢与外台。
相印昔辞东阁去，将星还拱北辰来。
殿庭捧日彯缨入，阁道看山曳履回。
口不言功心自适，吟诗酿酒待花开。','',''),('quantangshi-19159','和乐天南园试小乐','劉禹錫','quantangshi','','卷20','闲步南园烟雨晴，遥闻丝竹出墙声。
欲抛丹笔三川去，先教清商一部成。
花木手栽偏有兴，歌词自作别生情。
多才遇景皆能咏，当日人传满凤城。','',''),('quantangshi-19160','答乐天戏赠','劉禹錫','quantangshi','','卷20','才子声名白侍郎，风流虽老尚难当。
诗情逸似陶彭泽，斋日多如周太常。
矻矻将心求净法，时时偷眼看春光。
知君技痒思欢宴，欲倩天魔破道塲。','',''),('quantangshi-19161','同乐天送令狐相公赴东都留守','劉禹錫','quantangshi','','卷20','尚书劒履出明光，居守旌旗赴洛阳。
世上功名兼将相，人间声价是文章。
衙门晓辟分天仗，宾幕初开辟省郎。
从发坡头向东望，春风处处有甘棠。','',''),('quantangshi-19162','刑部白侍郎谢病长告改宾客分司以诗赠别','劉禹錫','quantangshi','','卷20','鼎食华轩到眼前，拂衣高谢岂徒然。
九霄路上辞朝客，四皓丛中作少年。
他日卧龙终得雨，今朝放鹤且冲天。
洛阳旧有衡茆在，亦拟抽身伴地仙。','',''),('quantangshi-19163','和留守令狐相公答白宾客','劉禹錫','quantangshi','','卷20','麦陇和风吹树枝，商山逸客出关时。
身无拘束起长晚，路足交亲行自迟。
官拂象筵终日待，私将鸡黍几人期。
君来不用飞书报，万户先从纸贵知。','',''),('quantangshi-19164','酬郓州令狐相公官舍言怀见寄兼呈乐天','劉禹錫','quantangshi','','卷20','词人各在一涯居，声味虽同迹自疎。
佳句传因多好事，尺题稀为不便书。
已通戎略逢黄石，仍占星文耀碧虚。
闻说朝天在来岁，霸陵春色待行车。','',''),('quantangshi-19165','吟白乐天哭崔儿二篇怆然寄赠','劉禹錫','quantangshi','','卷20','吟君苦调我霑缨，能使无情尽有情。
四望车中心未释，千秋亭下赋初成。
庭梧已有栖雏处，池鹤今无子和声。
从此期君比琼树，一枝吹折一枝生。','',''),('quantangshi-19166','答乐天所寄咏怀且释其枯树之叹','劉禹錫','quantangshi','','卷20','衙前有乐馔常精，宅内连池酒任倾。
自是官高无狎客，不论年长少欢情。
骊龙颔被探珠去，老蚌胚还应月生。
莫羡三春桃与李，桂花成实向秋荣。','',''),('quantangshi-19167','赴苏州酬别乐天','劉禹錫','quantangshi','','卷20','吴郡鱼书下紫宸，长安厩吏送朱轮。
二南风化承遗爱，八咏声名蹑后尘。
梁氏夫妻为寄客，陆家兄弟是州民。
江城春日追游处，共忆东归旧主人。','',''),('quantangshi-19168','福先寺雪中酬别乐天','劉禹錫','quantangshi','','卷20','龙门宾客会龙宫，东去旌旗驻上东。
二八笙歌云幕下，三千世界雪花中。
离堂未暗排红烛，别曲含凄扬晚风。
才子从今一分散，便将诗咏向吴侬。','',''),('quantangshi-19169','和乐天耳顺吟兼寄敦诗','劉禹錫','quantangshi','','卷20','吟君新什慰蹉跎，屈指同登耳顺科。
邓禹功成三纪事，孔融书就八年多。
已经将相谁能尔，抛却丞郎争奈何。
独恨长洲数千里，且随鱼鸟泛烟波。','',''),('quantangshi-19170','和白侍郎送令狐相公镇太原','劉禹錫','quantangshi','','卷20','十万天兵貂锦衣，晋城风日斗生辉。
行台仆射深恩重，从事中郎旧路归。
叠鼓蹙成汾水浪，闪旗惊断塞鸿飞。
边庭自此无烽火，拥节还来坐紫微。','',''),('quantangshi-19171','酬乐天见寄','劉禹錫','quantangshi','','卷20','元君后辈先零落，崔相同年不少留。
华屋坐来能几日，夜台归去便千秋。
背时犹自居三品，得老终须卜一丘。
若使吾徒还早达，亦应箫鼓入松楸。','',''),('quantangshi-19172','乐天寄重和晚达冬青一篇因成再答','劉禹錫','quantangshi','','卷20','风云变化饶年少，光景蹉跎属老夫。
秋隼得时凌汗漫，寒龟饮气受泥涂。
东隅有失谁能免，北叟之言岂便无。
振臂犹堪呼一掷，争知掌下不成卢。','',''),('quantangshi-19173','河南白尹有喜崔宾客归洛兼见怀长句因而继和','劉禹錫','quantangshi','','卷20','几年侍从作名臣，却向青云索得身。
朝士忽为方外士，主人仍是眼中人。
双鸾游处天京好，五马行时海峤春。
遥羡光阴不虚掷，肯令丝竹暂生尘。','',''),('quantangshi-19174','和杨师臯给事伤小姬英英','劉禹錫','quantangshi','','卷20','见学胡琴见艺成，今朝追想几伤情。
拈弦花下呈新曲，放拨灯前谢改名。
但是好花皆易落，从来尤物不长生。
鸾台夜直衣衾冷，云雨无因入禁城。','',''),('quantangshi-19175','和乐天洛下醉吟寄太原令狐相公兼见怀长句','劉禹錫','quantangshi','','卷20','旧相临戎非称意，词人作尹本多情。
从容自使边尘静，谈笑不闻桴鼓声。
章句新添塞下曲，风流旧占洛阳城。
昨来亦有吴趋咏，惟寄东都与北京。','',''),('quantangshi-19176','郡斋书怀寄江南白尹兼简分司崔宾客','劉禹錫','quantangshi','','卷20','谩读图书三十车，年年为郡老天涯。
一生不得文章力，百口空为饱暖家。
绮季衣冠称鬓面，吴公政事副词华。
还思谢病吟归去，同醉城东桃李花。','',''),('quantangshi-19177','题于家公主旧宅','劉禹錫','quantangshi','','卷20','树绕荒台叶满池，箫声一绝草虫悲。
邻家犹学宫人髻，园客争偷御果枝。
马埒蓬蒿藏狡兔，凤楼烟雨啸愁鸱。
何郎独在无恩泽，不似当初傅粉时。','',''),('quantangshi-19178','酬乐天贻贺金紫之什','劉禹錫','quantangshi','','卷20','久学文章含白凤，却因政事赐金鱼。
郡人未识闻谣咏，天子知名与诏书。
珍重贺诗呈锦绣，愿言归计竝园庐。
旧来词客多无位，金紫同游谁得如。','',''),('quantangshi-19179','乐天见示伤微之敦诗晦叔三君子皆有深分因成是诗以寄','劉禹錫','quantangshi','','卷20','吟君叹逝双绝句，使我伤怀奏短歌。
世上空惊故人少，集中惟觉祭文多。
芳林新叶催陈叶，流水前波让后波。
万古到今同此恨，闻琴泪尽欲如何。','',''),('quantangshi-19180','和乐天柘枝','劉禹錫','quantangshi','','卷20','柘枝本出楚王家，玉面添娇舞态奢。
松鬓改梳鸾凤髻，新衫别识鬬鸡纱。
鼓催残拍腰身软，汗透罗衣雨点花。
画筵曲罢辞归去，便随王母上烟霞。','',''),('quantangshi-19181','和乐天题真娘墓','劉禹錫','quantangshi','','卷20','薝卜林中黄土堆，罗襦绣黛已成灰。
芳魂虽死人不怕，蔓草逢春花自开。
幡盖向风疑舞袖，镜灯临晓似妆台。
吴王娇女坟相近，一片行云应往来。','',''),('quantangshi-19182','客有话汴州新政书事寄令狐相公','劉禹錫','quantangshi','','卷20','天下咽喉今大宁，军城喜气彻青冥。
庭前劒戟朝迎日，笔底文章夜应星。
三省壁中题姓字，万人头上见仪形。
汴州忽复承平事，正月看灯户不扃。','',''),('quantangshi-19183','令狐相公见示河中杨少尹赠答兼命继之','劉禹錫','quantangshi','','卷20','两首新诗百字余，朱弦玉磬韵难如。
汉家丞相重征后，梁苑仁风一变初。
四面诸侯瞻节制，八方通货溢河渠。
自从却縠为元帅，大将归来尽把书。','',''),('quantangshi-19184','和令狐相公送赵常盈炼师与中贵人同拜岳及天台投龙毕却赴京','劉禹錫','quantangshi','','卷20','银璫谒者引霓旌，霞帔仙官到赤城。
白鹤迎来天乐动，金龙掷下海神惊。
元君伏奏归中禁，武帝亲斋礼上清。
何事夷门请诗送，梁王文字上声名。','',''),('quantangshi-19185','酬令狐相公赠别','劉禹錫','quantangshi','','卷20','越声长苦有谁闻，老向湘山与楚云。
海峤新辞永嘉守，夷门重见信陵君。
田园松菊今迷路，霄汉鸳鸿久绝羣。
幸遇甘泉尚词赋，不知何客荐雄文。','',''),('quantangshi-19186','酬令狐相公寄贺迁拜之什','劉禹錫','quantangshi','','卷20','邅廻二纪重为郎，洛下遥分列宿光。
不见当关呼早起，曾无侍史与焚香。
三花秀色通春幌，十字清波遶宅墙。
白发青衫谁比数，相怜只是有梁王。','',''),('quantangshi-19187','夏日寄宣武令狐相公','劉禹錫','quantangshi','','卷20','长忆梁王逸兴多，西园花尽兴如何。
近来溽暑侵亭馆，应觉清谈胜绮罗。
境入篇章高韵发，风穿号令众心和。
承明欲谒先相报，愿拂朝衣逐晓珂。','',''),('quantangshi-19188','酬令狐留守巡内至集贤院见寄','劉禹錫','quantangshi','','卷20','仙院文房隔旧宫，当时盛事尽成空。
墨池半在颓垣下，书带犹生蔓草中。
巡内因经九重苑，裁诗又继二南风。
为兄手写殷勤句，遍历三台各一通。','',''),('quantangshi-19189','和令狐相公言怀寄河中杨少尹','劉禹錫','quantangshi','','卷20','章句慙非第一流，世间才子昔陪游。
吴宫已叹芙蓉死，边月空悲芦管秋。
任向洛阳称傲吏，苦教河上领诸侯。
石渠甘对图书老，关外杨公安稳不。','',''),('quantangshi-19190','令狐相公自天平移镇太原以诗申贺','劉禹錫','quantangshi','','卷20','北都留守将天兵，出入香街宿禁扃。
鼙鼓夜闻惊朔雁，旌旗晓动拂参星。
孔璋旧檄家家有，叔度新歌处处听。
夷落遥知真汉相，争来屈膝看仪刑。','',''),('quantangshi-19191','重酬前寄','劉禹錫','quantangshi','','卷20','边烽寂寂尽收兵。
宫树苍苍静掩扃，戎羯归心如内地。
天狼无角比凡星，新成丽句开缄后。
便入清歌满坐听，吴苑晋祠遥望处。
可怜南北太相形。','',''),('quantangshi-19192','令狐相公自太原累示新诗因以酬寄','劉禹錫','quantangshi','','卷20','飞蓬卷尽塞云寒，战马闲嘶汉地宽。
万里胡天无警急，一笼烽火报平安。
灯前妓乐留宾宴，雪后山河出猎看。
珍重新诗远相寄，风情不似四登坛。','',''),('quantangshi-19193','酬令狐相公使宅别斋初栽桂树见怀之作','劉禹錫','quantangshi','','卷20','清淮南岸家山树，黑水东边第一栽。
影近画梁迎晓日，香随绿酒入金杯。
根留本土依江润，叶起寒棱映月开。
早晚阴城比梧竹，九霄还放彩雏来。','',''),('quantangshi-19194','酬令狐相公见寄','劉禹錫','quantangshi','','卷20','才兼文武播雄名，遗爱芳尘满洛城。
身在行台为仆射，书来角里访先生。
闲游占得嵩山色，醉卧高听洛水声。
千里相思难命驾，七言诗里寄深情。','',''),('quantangshi-19195','郡内书情献裴侍中留守','劉禹錫','quantangshi','','卷20','功成频献乞身章，摆落襄阳镇洛阳。
万乘旌旗分一半，八方风雨会中央。
兵符今奉黄公略，书殿曾随翠凤翔。
心寄华亭一双鹤，曰陪高步绕池塘。','',''),('quantangshi-19196','酬乐天衫酒见寄','劉禹錫','quantangshi','','卷20','酒法众传吴米好，舞衣偏尚越罗轻。
动摇浮蚁香浓甚，装束轻鸿意态生。
阅曲定知能自适，举杯应叹不同倾。
终朝相忆终年别，对景临风无限情。','',''),('quantangshi-19197','自左冯归洛下酬乐天兼呈裴令公','劉禹錫','quantangshi','','卷20','新恩通籍在龙楼，分务神都近旧丘。
自有园公紫芝侣，仍追少傅赤松游。
华林霜叶红霞晚，伊水晴光碧玉秋。
更接东山文酒会，始知江左未风流。','',''),('quantangshi-19198','秋斋独坐寄乐天兼呈吴方之大夫','劉禹錫','quantangshi','','卷20','空斋寂寂不生尘，药物方书绕病身。
纤草数茎胜静地，幽禽忽至似佳宾。
世间忧喜虽无定，释氏销磨尽有因。
同向洛阳闲度日，莫教风景属他人。','',''),('quantangshi-19199','和乐天斋戒月满夜对道场偶怀咏','劉禹錫','quantangshi','','卷20','常修清净去繁华，人识王城长者家。
案上香烟铺贝叶，佛前灯焰透莲花。
持斋已满招闲客，理曲先闻命小娃。
明日若过方丈室，还应问为法来邪。','',''),('quantangshi-19200','吴方之见示独酌小醉首篇乐天续有酬答皆含戏谑极至风流两篇之中竝蒙见属辄呈滥吹益美来章','劉禹錫','quantangshi','','卷20','闲门共寂任张罗，静室同虚养太和。
尘世欢娱开意少，醉乡风景独游多。
散金疏傅寻常乐，枕麴刘生取次歌。
计会雪中争挈榼，鹿裘鹤氅递相过。','',''),('quantangshi-19201','酬乐天斋满日裴令公置宴席上戏赠','劉禹錫','quantangshi','','卷20','一月道场斋戒满，今朝华幄管弦迎。
衔杯本自多狂态，事佛无妨有佞名。
酒力半酣愁已散，文锋未钝老犹争。
平阳不独容宾醉，听取喧呼吏舍声。','',''),('quantangshi-19202','酬乐天偶题酒瓮见寄','劉禹錫','quantangshi','','卷20','从君勇断抛名后，世路荣枯见几回。
门外红尘人自走，瓮头清酒我初开。
三冬学任胸中有，万户侯须骨上来。
何幸相招同醉处，洛阳城里好池台。','',''),('quantangshi-19203','酬乐天请裴令公开春加宴','劉禹錫','quantangshi','','卷20','高名大位能兼有，恣意遨游是特恩。
二室烟霞成步障，三川风物是家园。
晨窥苑树韶光动，晚度河桥春思繁。
弦管常调客常满，但逢花处即开樽。','',''),('quantangshi-19204','乐天示过敦诗旧宅有感一篇吟之泫然追想昔事因成继和以寄苦怀','劉禹錫','quantangshi','','卷20','凄凉同到故人居，门枕寒流古木疎。
向秀心中嗟栋宇，萧何身后散图书。
本营归计非无意，唯算生涯尚有余。
忽忆前言更惆怅，丁宁相约速悬车。','',''),('quantangshi-19205','寄和东川杨尚书慕巢兼寄西川继之二公近从弟兄情分偏睦早忝游旧因成是诗','劉禹錫','quantangshi','','卷20','太华莲峰降岳灵，两川棠树接郊坰。
政同兄弟人人乐，曲奏埙篪处处听。
杨叶百穿荣会府，芝泥五色耀天庭。
各抛笔砚夸旄钺，莫遣文星让将星。','',''),('quantangshi-19206','和乐天洛下雪中宴集寄汴州李尚书','劉禹錫','quantangshi','','卷20','洛城无事足杯盘，风雪相和岁欲兰。
