笙歌要请频何爽，笑语忘机拙更欢。
遥想兔园今日会，琼林满眼映旗竿。','',''),('quantangshi-19207','和牛相公游南庄醉后寓言戏赠乐天兼见示','劉禹錫','quantangshi','','卷20','城外园林初夏天，就中野趣在西偏。
蔷薇乱发多临水，鸂鶒双游不避船。
水底远山云似雪，桥边平岸草如烟。
白家唯有杯觞兴，欲把头盘打少年。','',''),('quantangshi-19208','乐天以愚相访沽酒致欢因成七言聊以奉答','劉禹錫','quantangshi','','卷20','少年曾醉酒旗下，同辈黄衣颔亦黄。
蹴踏青云寻入仕，萧条白发且飞觞。
令征古事欢生雅，客唤闲人兴任狂。
犹胜独居荒草院，蝉声听尽到寒螿。','',''),('quantangshi-19209','和思黯忆南庄见示','劉禹錫','quantangshi','','卷20','丞相新家伊水头，智囊心匠日增修。
化成池沼无痕迹，奔走清波不自由。
台上看山徐举酒，潭中见月慢回舟。
从来天下推尤物，合属人间第一流。','',''),('quantangshi-19210','酬思黯见示小饮四韵','劉禹錫','quantangshi','','卷20','抛却人间第一官，俗情惊怪我方安。
兵府相印无心恋，洛水嵩云恣意看。
三足鼎中知味久，百寻竿上掷身难。
追呼故旧连宵饮，直到天明兴未阑。','',''),('quantangshi-19211','和仆射牛相公春日闲坐见怀','劉禹錫','quantangshi','','卷20','官曹崇重难频入，第宅清闲且独行。
阶蚁相逢如偶语，园蜂速去恐违程。
人于红药惟看色，莺到垂杨不惜声。
东洛池台怨抛掷，移文非久会应成。','',''),('quantangshi-19212','酬元九侍御赠璧竹鞭长句','劉禹錫','quantangshi','','卷20','碧玉孤根生在林，美人相赠比双金。
初开郢客缄封后，想见巴山冰雪深。
多节本怀端直性，露青犹有岁寒心。
何时策马同归去，关树扶疎敲镫吟。','',''),('quantangshi-19213','酬窦员外使君寒食日途次松滋渡先寄示四韵','劉禹錫','quantangshi','','卷20','楚乡寒食橘花时，野渡临风驻彩旗。
草色连云人去住，水纹如縠燕差池。
朱轮尚忆羣飞雉，青绶初县左顾龟。
非是湓城旧司马，水曹何事与新诗。','',''),('quantangshi-19214','寄杨八拾遗','劉禹錫','quantangshi','','卷20','闻君前日独庭争，汉帝偏知白马生。
忽领簿书游太学，宁劳侍从厌承明。
洛阳本自宜才子，海内而今有直声。
为谢同僚老博士，范云来岁即公卿。','',''),('quantangshi-19215','酬窦员外郡斋宴客偶命柘枝因见寄兼呈张十一院长元九侍御','劉禹錫','quantangshi','','卷20','分忧余刃又从公，白羽胡牀啸咏中。
彩笔谕戎矜倚马，华堂留客看惊鸿。
渚宫油幕方高步，澧浦甘棠有几丛。
若问骚人何处所，门临寒水落江枫。','',''),('quantangshi-19216','谢窦员外旬休早凉见示诗','劉禹錫','quantangshi','','卷20','新秋十日澣朱衣，铃阁无声公吏归。
风韵渐高梧叶动，露光初重槿花稀。
四时苒苒催容鬓，三爵油油忘是非。
更报明朝池上酌，人知太守字玄晖。','',''),('quantangshi-19217','南海马大夫远示着述兼酬拙诗辄着微诚再有长句时蔡戎未弭故见于篇末','劉禹錫','quantangshi','','卷20','汉家旄节付雄才，百越南溟统外台。
身在绛纱传六艺，腰悬青绶亚三台。
连天浪静长鲸息，映日帆多宝舶来。
闻道楚氛犹未灭，终须旌斾扫云雷。','',''),('quantangshi-19218','和南海马大夫闻杨侍郎出守郴州因有寄上之作','劉禹錫','quantangshi','','卷20','忽惊金印驾枝轓，遂别鸣珂听晓猿。
碧落仙来虽暂谪，赤泉侯在是深恩。
玉环庆远瞻台坐，铜柱勋高压海门。
一咏琼瑶百忧散，何劳更树北堂萱。','',''),('quantangshi-19219','马大夫见示浙西王侍御赠答诗因命同作','劉禹錫','quantangshi','','卷20','忆逐羊车凡几时，今来旧府统戎师。
象筵照室会词客，铜鼓临轩舞海夷。
百越酋豪称故吏，十洲风景助新诗。
秣陵从事何年别，一见琼章如素期。','',''),('quantangshi-19220','寄唐州杨八归厚','劉禹錫','quantangshi','','卷20','淮安古地拥州师，画角金铙旦夕吹。
浅草遥迎鷫鸘马，春风乱颭辟邪旗。
谪仙年月今应满，戆谏声名众所知。
何况迁乔旧同伴，一双先入凤凰池。','',''),('quantangshi-19221','寄朗州温右史曹长','劉禹錫','quantangshi','','卷20','暂别瑶墀鸳鹭行，彩旗双引到沅湘。
城边流水桃花过，帘外春风杜若香。
史笔枉将书纸尾，朝缨不称濯沧浪。
云台公业家声在，征诏何时出建章。','',''),('quantangshi-19222','酬杨司业巨源见寄','劉禹錫','quantangshi','','卷20','辟雍流水近灵台，中有诗篇绝世才。
渤海归人将集去，棃园弟子请词来。
琼枝未识魂空断，宝匣初临手自开。
莫道专城管云雨，其如心似不然灰。','',''),('quantangshi-19223','酬国子崔博士立之见寄','劉禹錫','quantangshi','','卷20','健笔高科早绝伦，后来无不揖芳尘。
遍看今日乘轩客，多是昔年呈卷人。
胄子执经瞻讲坐，郎官共食接华茵。
烦君远寄相思曲，慰问天南一逐臣。','',''),('quantangshi-19224','张郎中籍远寄长句开缄之日已及新秋因举目前仰酬高韵','劉禹錫','quantangshi','','卷20','南宫词客寄新篇，清似湘灵促柱弦。
京邑旧游劳梦想，历阳秋色正澄鲜。
云衔日脚成山雨，风驾潮头入渚田。
对此独吟还独酌，知音不见思怆然。','',''),('quantangshi-19225','浙东元相公书叹梅雨郁蒸之候因寄七言','劉禹錫','quantangshi','','卷20','稽山自与岐山别，何事连年鸑鷟飞。
百辟商量旧相入，九天祗候老臣归。
平湖晚泛窥清镜，高阁晨开扫翠微。
今日看书最惆怅，为闻梅雨损朝衣。','',''),('quantangshi-19226','酬严给事贺加五品兼简同制水部李郎中','劉禹錫','quantangshi','','卷20','九天雨露传青诏，八舍郎官换绿衣。
初佩银鱼随仗入，宜乘白马退朝归。
雕盘贺喜开瑶席，彩笔题诗出锁闱。
闻道水曹偏得意，霞朝雾夕有光辉。','',''),('quantangshi-19227','裴相公大学士见示答张秘书谢马诗并羣公属和因命追作','劉禹錫','quantangshi','','卷20','草玄门户少尘埃，丞相并州寄马来。
初自寒垣衔苜蓿，忽行幽径破莓苔。
寻花缓辔威迟去，带酒垂鞭躞蹀回。
不与王侯与词客，知轻富贵重清才。','',''),('quantangshi-19228','奉和裴侍中将赴汉南留别座上诸公','劉禹錫','quantangshi','','卷20','金貂晓出凤池头，玉节前临南雍州。
暂辍洪炉观剑戟，还将大笔注春秋。
管弦席上留高韵，山水途中入胜游。
岘首风烟看未足，便应重拜富民侯。','',''),('quantangshi-19229','和苏郎中寻丰安里旧居寄主客张郎中','劉禹錫','quantangshi','','卷20','漳滨卧起恣闲游，宣室征还未白头。
旧隐来寻通德里，新篇写出畔牢愁。
池看科斗成文字，鸟听提壶忆献酬。
同学同年又同舍，许君云路并华輈。','',''),('quantangshi-19230','酬浙东李侍郎越州春晚即事长句','劉禹錫','quantangshi','','卷20','越中蔼蔼繁华地，秦望峰前禹穴西。
湖草初生边雁去，山花半谢杜鹃啼。
青油昼卷临高阁，红斾晴翻绕古堤。
明日汉庭征旧德，老人争出若耶溪。','',''),('quantangshi-19231','酬淮南牛相公述旧见贻','劉禹錫','quantangshi','','卷20','少年曾忝汉庭臣，晚岁空余老病身。
初见相如成赋日，寻为丞相扫门人。
追思往事咨嗟久，喜奉清光笑语频。
犹有登朝旧冠冕，待公三入拂埃尘。','',''),('quantangshi-19232','和仆射牛相公追感韦裴六相登庸皆四十余未五十薨殁岂早荣枯之义今年将六十犹粗强健因亲故劝酒率然成篇并见寄之作','劉禹錫','quantangshi','','卷20','坐镇清朝独殷然，闲征故事数前贤。
用才同践钧衡地，禀气终分大小年。
威凤本池思泛泳，仙查旧路望回旋。
犹怜绮季深山里，唯有松风与石田。','',''),('quantangshi-19233','和仆射牛相公以离阙庭七年班行亲故亡殁十无一人再覩龙颜喜庆虽极感叹风烛能不怆然因成四韵并示集贤中书二相公所和','劉禹錫','quantangshi','','卷20','久辞龙阙拥红旗，喜见天颜拜赤墀。
三省英寮非旧侣，万年芳树长新枝。
交朋接武居仙院，幕客追风入凤池。
云母屏风即施设，可怜荣耀冠当时。','',''),('quantangshi-19234','和仆射牛相公见示长句','劉禹錫','quantangshi','','卷20','静得天和兴自浓，不缘宦达性灵慵。
大鹏六月有闲意，仙鹤千年无躁容。
流辈尽来多叹息，官班高后少过从。
唯应加筑露台上，剩见终南云外峰。','',''),('quantangshi-19235','和牛相公雨后寓怀见示','劉禹錫','quantangshi','','卷20','金火交争正抑扬，萧萧飞雨助清商。
晓看纨扇恩情薄，夜觉纱灯刻数长。
树上早蝉才发响，庭中百草已无光。
当年富贵亦惆怅，何况悲翁发似霜。','',''),('quantangshi-19236','和陈许王尚书酬白少傅侍郎长句因通简汝洛旧游之什','劉禹錫','quantangshi','','卷20','寥廓高翔不可追，风云失路蹔相随。
方同洛下书生咏，又见军前大将旗。
雪里命宾开玉帐，饮中请号驻金巵。
竹林一自王戎去，嵇阮虽贫兴未衰。','',''),('quantangshi-19237','和仆射牛相公寓言二首 一','劉禹錫','quantangshi','','卷20','两度竿头立定夸，回眸举袖拂青霞。
尽抛今日贵人样，复振前朝名相家。
御史定来休直宿，尚书依旧趂参衙。
具瞻尊重诚无敌，犹忆洛阳千树花。','',''),('quantangshi-19238','和仆射牛相公寓言二首 二','劉禹錫','quantangshi','','卷20','心如止水鉴常明，见尽人间万物情。
雕鹗腾空犹逞俊，骅骝啮足自无惊。
时来未觉权为祟，贵了方知退是荣。
只恐重重世缘在，事须三度副苍生。','',''),('quantangshi-19239','酬太原狄尚书见寄','劉禹錫','quantangshi','','卷20','家声烜赫冠前贤，时无穹崇镇北边。
身上官衔如座主，幕中谭笑取同年。
幽并侠少趋鞭弭，燕赵佳人奉管弦。
仍把天兵书号笔，远题长句寄山川。','',''),('quantangshi-19240','酬宣州崔大夫见寄','劉禹錫','quantangshi','','卷20','白衣曾拜汉尚书，今日恩光到敝庐。
再入龙楼称绮季，应缘狗监说相如。
中郎南镇权方重，内史高斋兴有余。
遥想敬亭春欲暮，百花飞尽柳花初。','',''),('quantangshi-19241','酬皇甫十少尹暮秋久雨喜晴有怀见示','劉禹錫','quantangshi','','卷20','雨余独坐卷帘帷，便得诗人喜霁诗。
摇落从来长年感，惨舒偏是病身知。
扫开云雾呈光景，流尽潢污见路岐。
何况菊香新酒熟，神州司马好狂时。','',''),('quantangshi-19242','再授连州至衡阳酬柳柳州赠别','劉禹錫','quantangshi','','卷20','去国十年同赴召，渡湘千里又分岐。
重临事异黄丞相，三黜名慙柳士师。
归目并随回雁尽，愁肠正遇断猿时。
桂江东过连山下，相望长吟有所思。','',''),('quantangshi-19243','望夫山','劉禹錫','quantangshi','','卷20','何代提戈去不还，独留形影白云间。
肌肤销尽雪霜色，罗绮点成苔藓斑。
江燕不能传远信，野花空解妒愁颜。
近来岂少征人妇，笑采蘼芜上北山。','',''),('quantangshi-19244','怀妓 一','劉禹錫','quantangshi','','卷20','玉钗重合两无缘，鱼在深潭鹤在天。
得意紫鸾休舞镜，能言青鸟罢衔牋。
金盆已覆难收水，玉轸长抛不续弦。
若向蘼芜山下过，遥将红泪洒穷泉。','',''),('quantangshi-19245','怀妓 二','劉禹錫','quantangshi','','卷20','鸾飞远树栖何处，凤得新巢想称心。
红壁尚留香漠漠，碧云初断信沈沈。
情知点污投泥玉，犹自经营买笑金。
从此山头似人石，丈夫形状泪痕深。','',''),('quantangshi-19246','怀妓 三','劉禹錫','quantangshi','','卷20','但曾行处遍寻看，虽是生离死一般。
买笑树边花已老，画眉窗下月犹残。
云藏巫峡音容断，路隔星桥过往难。
莫怪诗成无泪滴，尽倾东海也须干。','',''),('quantangshi-19247','怀妓 四','劉禹錫','quantangshi','','卷20','三山不见海沈沈，岂有仙踪更可寻。
青鸟去时云路断，姮娥归处月宫深。
纱窗遥想春相忆，书幌谁怜夜独吟。
料得夜来天上镜，只应偏照两人心。','',''),('quantangshi-19248','答东阳于令寒碧图诗','劉禹錫','quantangshi','','卷20','东阳本是佳山水，何况曾经沈隐侯。
化得邦人解吟咏，如今县令亦风流。
新开谭洞疑仙境，远写丹青到雍州。
落在寻常画师手，犹能三伏凛生秋。','',''),('quantangshi-19249','麻姑山','劉禹錫','quantangshi','','卷20','曾游仙迹见丰碑，除却麻姑更有谁。
云盖青山龙卧处，日临丹洞鹤归时。
霜凝上界花开晚，月冷中天果熟迟。
人到便须抛世事，稻田还儗种灵芝。','',''),('quantangshi-19250','自江陵沿流道中','劉禹錫','quantangshi','','卷20','三千三百西江水，自古如今要路津。
月夜歌谣有渔父，风天气色属商人。
沙村好处多逢寺，山叶红时觉胜春。
行到南朝征战地，古来名将尽为神。','',''),('quantangshi-19251','别夔州官吏','劉禹錫','quantangshi','','卷20','三年楚国巴城守，一去扬州扬子津。
青帐联延喧驿步，白头俯伛到江滨。
巫山暮色常含雨，峡水秋来不恐人。
惟有九歌词数首，里中留与赛蛮神。','',''),('quantangshi-19252','鱼复江中','劉禹錫','quantangshi','','卷20','扁舟尽室贫相逐，白发藏冠镊更加。
远水自澄终日绿，晴林长落过春花。
客情浩荡逢乡语，诗意留连重物华。
风樯好住贪程去，斜日青帘背酒家。','',''),('quantangshi-19253','巫山神女庙','劉禹錫','quantangshi','','卷20','巫山十二郁苍苍，片石亭亭号女郎。
晓雾乍开疑卷幔，山花欲谢似残妆。
星河好夜闻清佩，云雨归时带异香。
何事神仙九天上，人间来就楚襄王。','',''),('quantangshi-19254','柳絮','劉禹錫','quantangshi','','卷20','飘扬南陌起东邻，漠漠蒙蒙暗度春。
花巷暖随轻舞蝶，玉楼晴拂艳妆人。
萦回谢女题诗笔，点缀陶公漉酒巾。
何处好风偏似雪，隋河堤上古江津。','',''),('quantangshi-19255','赠同年陈长史员外','劉禹錫','quantangshi','','卷20','明州长史外台郎，忆昔同年翰墨场。
一自分襟多岁月，相逢满眼是凄凉。
推贤有愧韩安国，论旧唯存盛孝章。
所叹谬游东阁下，看君无计出恓惶。','',''),('quantangshi-19256','送周鲁儒赴举诗','劉禹錫','quantangshi','','卷20','宋日营阳内史孙，因家占得九疑村。
童心便有爱书癖，手指今余把笔痕。
自握蛇珠辞白屋，欲凭鸡卜谒金门。
若逢广坐问羊酪，从此知名在一言。','',''),('quantangshi-19257','送曹璩归越中旧隐诗','劉禹錫','quantangshi','','卷20','行尽潇湘万里余，少逢知己忆吾庐。
数间茅屋闲临水，一盏秋灯夜读书。
地远何当随计吏，策成终自诣公车。
剡中若问连州事，唯有千山画不如。','',''),('quantangshi-19258','白鹰','劉禹錫','quantangshi','','卷20','毛羽斒斓白紵裁，马前擎出不惊猜。
轻抛一点入云去，喝杀三声掠地来。
绿玉觜攒鸡脑破，玄金爪擘兔心开。
都缘解搦生灵物，所以人人道俊哉。','',''),('quantangshi-19259','送工部张侍郎入蕃吊祭','劉禹錫','quantangshi','','卷20','月窟宾诸夏，云官降九天。
饰终邻好重，锡命礼容全。
水咽犹登陇，沙鸣稍极边。
路因乘驿近，志为饮冰坚。
毳帐差池见，乌旗摇曳前。
归来赐金石，荣耀自编年。','',''),('quantangshi-19260','早秋送台院杨侍御归朝','劉禹錫','quantangshi','','卷20','仙署棣华春，当时已绝伦。
今朝丹阙下，更入白眉人。
重振高阳族，分居要路津。
一门科第足，五府辟书频。
鸷鸟得秋气，法星悬火旻。
圣朝寰海静，所至不埋轮。','',''),('quantangshi-19261','送陆侍御归淮南使府五韵','劉禹錫','quantangshi','','卷20','江左重诗篇，陆生名久传。
凤城来已熟，羊酪不嫌膻。
归路芙蓉府，离堂玳瑁筵。
泰山呈腊雪，隋柳布新年。
曾忝扬州荐，因君达短牋。','',''),('quantangshi-19262','送令狐相公自仆射出镇南梁','劉禹錫','quantangshi','','卷20','夏木正阴成，戎装出帝京。
沾襟辞阙泪，回首别乡情。
云树褒中路，风烟汉上城。
前旌传谷去，后骑踏桥声。
久领鸳行重，无嫌虎绶轻。
终提一麾去，再入福苍生。','',''),('quantangshi-19263','奉送裴司徒令公自东都留守再命太原','劉禹錫','quantangshi','','卷20','星使出关东，兵符赐上公。
山河归旧国，管龠换离宫。
行色旌旗动，军声鼓角雄。
爱棠余故吏，骑竹见新童。
汉垒三秋静，胡沙万里空。
其如天下望，旦夕咏清风。','',''),('quantangshi-19264','海阳湖别浩初师','劉禹錫','quantangshi','','卷20','近郭看殊境，独游常鲜懽。
逢君驻缁锡，观貌称林峦。
湖满景方霁，野香春未阑。
爱泉移席近，闻石辍棊看。
风止松犹韵，花繁露未干。
桥形出树曲，岩影落池寒别路千嶂里，诗情暮云端。
他年买山处，似此得隳官。','',''),('quantangshi-19265','许给事见示哭工部刘尚书诗因命同作','劉禹錫','quantangshi','','卷20','汉室贤王后，孔门高第人。
济时成国器，乐道任天真。
特达圭无玷，坚贞竹有筠。
总戎宽得众，市义贵能贫。
护塞无南牧，驰心拱北辰。
乞身来阙下，赐告卧漳滨。
荣耀初题劒，清羸已拖绅。
宫星徒列位，隙日不回轮。
自昔追飞侣，今为侍从臣。
素弦哀已绝，青简叹犹新。
未遂挥金乐，空悲撤瑟晨。
凄凉竹林下，无复见清尘。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-19266','武陵书怀五十韵','劉禹錫','quantangshi','','卷20','西汉开支郡，南朝号戚藩。
四封当列宿，百雉俯清沅。
高岸朝霞合，惊湍激箭奔。
积阴春暗度，将霁雾先昏。
俗尚东皇祀，谣传义帝冤。
桃花迷隐迹，楝叶慰忠魂。
户算资渔猎，乡豪恃子孙。
照山畲火动，踏月俚歌喧。
拥檝舟为市，连甍竹覆轩。
披沙金粟见，拾羽翠翘翻。
茗折苍溪秀，苹生枉渚暄。
禽惊格磔起，鱼戏噞喁繁。
沈约台榭故，李衡墟落存。
湘灵悲鼓瑟，泉客泣酬恩。
露变蒹葭浦，星悬橘柚村。
虎咆空野震，鼍作满川浑。
邻里皆迁客，儿童习左言。
炎天无冽井，霜月见芳荪。
清白家传远，诗书志所敦。
列科叨甲乙，从宦出丘樊。
结友心多契，驰声气尚吞。
士安曾重赋，元礼许登门。
草檄嫖姚幕，巡兵戊己屯。
筑台先自隗，送客独留髠。
遂结王畿绶，来观衢室罇。
鸢飞入鹰隼，鱼目俪璵璠。
晓烛罗驰道，朝阳辟帝阍。
王正会夷夏，月朔盛旗幡。
独立当瑶阙，传呵步紫垣。
按章清犴狱，视祭洁苹蘩。
御历昌期远，传家宝祚蕃。
繇文光夏启，神教畏轩辕。
内禅因天性，雄图授化元。
继明悬日月，出震统干坤。
大孝三朝备，洪恩九族敦。
百川宗渤澥，五岳辅昆仑。
何幸逢休运，微班识至尊。
校緍资筦榷，复土奉山园。
一失贵人意，徒闻太学论。
直庐辞锦帐，远守愧朱幡。
巢幕方犹燕，抢榆尚笑鲲。
邅回过荆楚，流落感凉温。
旅望花无色，愁心醉不惛。
春江千里草，暮雨一声猿。
问卜安冥数，看方理病源。
带赊衣改制，尘涩劒成痕。
三秀悲中散，二毛伤虎贲。
来忧御魑魅，归愿牧鸡豚。
就日秦京远，临风楚奏烦。
南登无灞岸，旦夕上高原。','',''),('quantangshi-19267','早秋集贤院即事','劉禹錫','quantangshi','','卷20','金数已三伏，火星正西流。
树含秋露晓，阁倚碧天秋。
灰琯应新律，铜壶添夜筹。
商飙从朔塞，爽气入神州。
蕙草香书殿，槐花点御沟。
山明真色见，水静浊烟收。
早岁忝华省，再来成白头。
幸依羣玉府，末路尚瀛洲。','',''),('quantangshi-19268','奉和吏部杨尚书太常李卿二相公策免后即事述怀赠答十韵','劉禹錫','quantangshi','','卷20','文雅关西族，衣冠赵北都。
有声真汉相，无纇胜隋珠。
当轴龙为友，临池凤不孤。
九天开内殿，百辟看晨趋。
诫满澄欹器，成功别大罏。
余芳在公论，积庆是神扶。
步武离台席，徊翔集帝梧。
诠材秉秦镜，典乐去齐竽。
潇洒风尘外，逢迎诗酒徒。
唯应待华诰，更食万钱厨。','',''),('quantangshi-19269','晚岁登武陵城顾望水陆怅然有作','劉禹錫','quantangshi','','卷20','星象承乌翼，蛮陬想犬牙。
俚人祠竹节，仙洞闭桃花。
城基历汉魏，江源自賨巴。
华表廖王墓，菜地黄琼家。
霜轻菊秀晚，石浅水纹斜。
樵音绕故垒，汲路明寒沙。
清风稍改叶，卢橘始含葩。
野桥过驿骑，丛祠发逈笳。
跳鳞避举网，倦鸟寄行楂。
路尘高出树，山火远连霞。
夕曛转赤岸，浮霭起苍葭。
轧轧渡水桨，连连赴林鸦。
呌阍道非远，赐环期自赊。
孤臣本危涕，乔木在天涯。','',''),('quantangshi-19270','罢郡归洛阳寄友人','劉禹錫','quantangshi','','卷20','远谪年犹少，初归鬓已衰。
门闲故吏去，室静老僧期。
不见蜘蛛集，频为佝偻欺。
颖微囊未出，寒甚谷难吹。
濩落唯心在，平生有己知。
商歌夜深后，听者竟为谁。','',''),('quantangshi-19271','经伏波神祠','劉禹錫','quantangshi','','卷20','蒙蒙篁竹下，有路上壶头。
汉垒麏鼯鬬，蛮溪雾雨愁。
怀人敬遗像，阅世指东流。
自负霸王略，安知恩泽侯。
乡园辞石柱，筋力尽炎洲。
一以功名累，飜思马少游。','',''),('quantangshi-19272','和汴州令狐相公到镇改月偶书所怀','劉禹錫','quantangshi','','卷20','受脤新梁苑，和羹旧傅岩。
援毫动星宿，垂钓取韬钤。
赫奕三川至，欢呼百姓瞻。
绿油貔虎拥，青纸凤皇衔。
外垒曾无警，中厨亦罢监。
推诚人自服，去杀令逾严。
赳赳容皆饰，幡幡口尽钳。
为兄怜庾翼，选壻得萧咸。
郁倔咽喉地，骈臻水陆兼。
度桥鸣绀幰，入肆扬云帆。
端月当中气，东风应远占。
管弦喧夜景，灯烛掩寒蟾。
酒每倾三雅，书能发百函。
词人羞布鼓，远客献貂襜。
歌榭白团扇，舞筵金缕衫。
旌旗遥一簇，舄履近相搀。
花树当朱阁，晴河逼翠帘。
衣风飘叆叇，烛泪滴巉岩。
玉斝虚频易，金炉暖更添。
映镮窥艳艳，隔袖见纤纤。
谢傅何由接，桓伊定不凡。
应怜郡斋老，旦夕镊霜䫇。','',''),('quantangshi-19273','遥贺白宾客分司初到洛中戏呈冯尹','劉禹錫','quantangshi','','卷20','西辞望苑去，东占洛阳才。
度岭无愁思，看山不懊来。
冥鸿何所慕，辽鹤乍飞廻。
洗竹通新迳，携琴上旧台。
尘埃长者撤，风月故人杯。
闻道龙门峻，还因上客开。','',''),('quantangshi-19274','白侍郎大尹自河南寄示池北新葺水斋即事招宾十四韵兼命同作','劉禹錫','quantangshi','','卷20','公府有高政，新斋池上开。
再吟佳句后，一似画图来。
结构疎林下，夤缘曲岸隈。
绿波穿户牖，碧甃叠琼瓌。
幽异当轩满，清光绕砌廻。
潭心澄晚镜，渠口起晴雷。
瑶草缘堤种，松烟上岛栽。
游鱼惊拨刺，浴鹭喜毰毸。
为客烹林笋，因僧采石苔。
酒瓶常不罄，书案任成堆。
檐外青雀舫，坐中鹦鹉杯。
蒲根抽九节，莲萼捧重台。
芳讯此时到，胜游何日陪。
共讥吴太守，自占洛阳才。','',''),('quantangshi-19275','和令狐相公谢太原李侍中寄蒲桃','劉禹錫','quantangshi','','卷20','珍果出西域，移根到北方。
昔年随汉使，今日寄梁王。
上相芳缄至，行台绮席张。
鱼鳞含宿润，马乳带残霜。
染指铅粉腻，满喉甘露香。
酝成十日酒，味敌五云桨。
咀嚼停金盏，称嗟响画堂。
慙非末至客，不得一枝尝。','',''),('quantangshi-19276','和令狐相公玩白菊','劉禹錫','quantangshi','','卷20','家家菊尽黄，梁国独如霜。
莹静真琪树，分明对玉堂。
仙人披雪氅，素女不红妆。
粉蝶来难见，麻衣拂更香。
向风摇羽扇，含露滴琼桨。
高艳遮银井，繁枝覆象牀。
桂丛慙竝发，梅蘂妬先芳。
一入瑶华咏，从兹播乐章。','',''),('quantangshi-19277','令狐相公见示新栽蕙兰二草之什兼命同作','劉禹錫','quantangshi','','卷20','上国庭前草，移来汉水浔。
朱门虽易地，玉树有余阴。
艳彩凝还泛，清香绝复寻。
光华童子佩，柔软美人心。
惜晚含远思，赏幽空独吟。
寄言知音者，一奏风中琴。','',''),('quantangshi-19278','和令狐相公南斋小宴听阮咸','劉禹錫','quantangshi','','卷20','阮巷久芜沈，四弦有遗音。
雅声发兰室，远思含竹林。
座绝众宾语，庭移芳树阴。
飞觞助真气，寂听无流心。
影似白团扇，调谐朱弦琴。
一毫不平意，幽怨古犹今。','',''),('quantangshi-19279','和令狐相公九日对黄白二菊花见怀','劉禹錫','quantangshi','','卷20','素萼迎寒秀，金英带露香。
繁华照旄钺，荣盛对银黄。
琮璧交辉映，衣裳杂彩章。
晴云遥盖覆，秋蝶近悠扬。
空想逢九日，何由陪一觞。
满丛佳色在，未肯委严霜。','',''),('quantangshi-19280','令狐仆射与余投分素深纵山川阻修然音问相继今年十一月仆射疾不起闻予已承讣书寝门长恸后日有使者两辈持书并诗计其日时已是卧疾手笔盈幅翰墨尚新律词一篇音韵弥切收泪握管以成报章虽广陵之弦于今绝矣而盖泉之感犹庶闻焉焚之繐帐之前附于旧编之末','劉禹錫','quantangshi','','卷20','前日寝门恸，至今悲有余。
已嗟万化尽，方见八行书。
满纸传相忆，裁诗怨索居。
危弦音有绝，哀玉韵[犹]虚。
忽叹幽明异，俄惊岁月除。
文章虽不朽，精魂竟焉如。
零泪霑青简，伤心见素车。
凄凉从此后，无复望双鱼。','',''),('quantangshi-19281','和乐天闲园独赏八韵前以蜂鹤拙句寄呈今辱蜗蚁妍词见答因成小巧以取大咍','劉禹錫','quantangshi','','卷20','永日无人事，芳园任兴行。
陶庐树可爱，潘宅雨新晴。
傅粉琅玕节，熏香菡萏茎。
榴花裙色好，桐子药丸成。
柳蠹枝偏亚，桑空叶再生。
睢盱欲鬬雀，索漠不言莺。
动植随四气，飞沈含五情。
抢榆与水击，小大强为名。','',''),('quantangshi-19282','奉和裴令公新成绿野堂即书','劉禹錫','quantangshi','','卷20','蔼蔼鼎门外，澄澄洛水湾。
堂皇临绿野，坐卧看青山。
位极却忘贵，功成欲爱闲。
官名司管龠，心术去机关。
禁苑凌晨出，园花及露攀。
池塘鱼拔刺，竹迳鸟绵蛮。
志在安潇洒，尝经历险艰。
高情方造适，众意望征还。
好客交珠履，华筵舞玉颜。
无因随贺燕，翔集画梁间。','',''),('quantangshi-19283','三月三日与乐天及河南李尹奉陪裴令公泛洛禊饮各赋十二韵','劉禹錫','quantangshi','','卷20','洛下今修禊，羣贤胜会稽。
盛筵陪玉铉，通籍尽金闺。
波上神仙妓，岸旁桃李蹊。
水嬉如鹭振，歌响杂莺啼。
历览风光好，沿洄意思迷。
棹歌能俪曲，墨客竞分题。
翠幄连云起，香车向道齐。
人夸绫步障，马惜锦障泥。
尘暗宫墙外，霞明苑树西。
舟形随鷁转，桥影与虹低。
川色晴犹远，乌声暮欲栖。
唯余踏青伴，待月魏王堤。','',''),('quantangshi-19284','乐天少傅五月长斋广延缁徒谢绝文友坐成睽间因以戏之','劉禹錫','quantangshi','','卷20','五月长斋戒，深居绝送迎。
不离通德里，便是法王城。
举目皆僧事，全家少俗情。
精修无上道，结念未来生。
宾合缁衣占，书堂信鼓鸣。
戏童为塔象，啼鸟学经声。
黍用青菰角，葵承玉露烹。
马家供薏苡，刘氏饷芜菁。
暗网笼歌扇，流尘晦酒铛。
不知何次道，作佛几时成。','',''),('quantangshi-19285','酬乐天晚夏闲居欲相访先诗见贻','劉禹錫','quantangshi','','卷20','池榭堪临泛，翛然散郁陶。
步因驱鹤缓，吟为听蝉高。
林密添新竹，枝低缒晚桃。
酒醅晴易熟，药圃夏频薅。
老是班行旧，闲为乡里豪。
经过更何处，风景属吾曹。','',''),('quantangshi-19286','酬乐天醉后狂吟十韵','劉禹錫','quantangshi','','卷20','散诞人间乐，逍遥地上仙。
诗家登逸品，释氏悟真筌。
制诰留台阁，歌词入管弦。
处身于木雁，任世变桑田。
吏隐情兼遂，儒玄道两全。
八关斋适罢，三雅兴尤偏。
文墨中年旧，松筠晚岁坚。
鱼书曾替代，香火有因缘。
欲向醉乡去，犹为色界牵。
好吹杨柳曲，为我舞金钿。','',''),('quantangshi-19287','牛相公见示新什谨依本韵次用以抒下情','劉禹錫','quantangshi','','卷20','剧韵新篇至，因难始见能。
雨天龙变化，晴日凤骞腾。
游海惊何极，闻韶素不曾。
惬心时拊髀，击节日麾肱。
符彩添隃墨，波澜起剡藤。
拣金光熠熠，累璧势层层。
珠媚多藏贾，花撩欲定僧。
封来真宝物，寄与愧交朋。
已老无时疾，长贫望岁登。
雀罗秋寂寂，虫翅晓薨薨。
羸骥方辞绊，虚舟已绝絙。
荣华甘死别，健羡亦生憎。
玉柱琤瑽韵，金觥雹凸棱。
何时良宴会，促膝对华灯。','',''),('quantangshi-19288','奉和中书崔舍人八月十五日夜翫月二十韵','劉禹錫','quantangshi','','卷20','暮景中秋爽，阴灵既望圆。
浮精离碧海，分照接虞渊。
迥见孤轮出，高从倚盖旋。
二仪含皎澈，万象共澄鲜。
整御当西陆，舒光丽上玄。
从星变风雨，顺日助陶甄。
远近同时望，晶荧此夜偏。
运行调玉烛，洁白应金天。
曲沼疑瑶镜，通衢若象筵。
逢人尽冰雪，遇景即神仙。
引素吞银汉，凝清洗绿烟。
臯禽警露下，邻杵思风前。
水是还珠浦，山成种玉田。
劒沈三尺影，灯罢九枝然。
象外形无迹，寰中影有迁。
稍当云阙正，未映斗城悬。
静对挥宸翰，闲临襞彩牋。
境同牛渚上，宿在凤池边。
兴掩寻安道，词胜命仲宣。
从今纸贵后，不复咏陈篇。','',''),('quantangshi-19289','奉和淮南李相公早秋即事寄成都武相公','劉禹錫','quantangshi','','卷20','八柱共承天，东西别隐然。
远夷争慕化，真相故临边。
竝进夔龙位，仍齐龟鹤年。
同心舟已济，造膝璧常联。
对领专征寄，遥持造物权。
斗牛添气色，井络静氛烟。
献可通三略，分甘出万钱。
汉南趋节制，赵北赐山川。
玉帐观渝舞，虹旌猎楚田。
步嫌双绶重，梦入九城偏。
秋雨离情动，新诗乐府传。
聆音还窃拚，不觉抚么弦。','',''),('quantangshi-19290','元和癸巳岁仲秋诏发江陵偏师问罪蛮徼后命宣慰释兵归降凯旋之辰率尔成咏寄荆南严司空','劉禹錫','quantangshi','','卷20','蛮水阻朝宗，兵符下渚宫。
前筹得上策，无战已成功。
汉使星飞入，夷心草偃同。
歌谣开竹栈，拜舞戢桑弓。
就日知冰释，投人念鸟穷。
网罗三面解，章奏九门通。
卉服联操袂，雕题尽鞠躬。
降幡秋练白，驿骑昼尘红。
火号休传警，机桥罢亘空。
登山不见虏，振斾自生风。
江远烟波静，军回气色雄。
伫看闻喜后，金石赐元戎。','',''),('quantangshi-19291','和李六侍御文宣王庙释奠作','劉禹錫','quantangshi','','卷20','叹息鲁先师，生逢周室卑。
有心律天道，无位救陵夷。
历聘不能用，领徒空尔为。
儒风正礼乐，旅象入蓍龟。
西狩非其应，中都安足施。
世衰由我贱，泣下为人悲。
遗教光文德，兴王叶梦期。
土田封后胤，冕服饰虚仪。
钟鼓胶庠荐，牲牢郡邑祠。
闻君喟然叹，偏在上丁时。','',''),('quantangshi-19292','和窦中丞晚入容江作','劉禹錫','quantangshi','','卷20','汉郡三十六，郁林东南遥。
人伦选清臣，天外颁诏条。
桂水步秋浪，火山凌雾朝。
分圻辨风物，入境闻讴谣。
莎岸见长亭，烟林隔丽谯。
日落舟益驶，川平旗自飘。
珠浦远明灭，金沙晴动摇。
一吟道中作，离思悬层霄。','',''),('quantangshi-19293','南海马大夫见惠着述三通勒成四帙上自邃古达于国朝采其菁华至简如富钦受嘉贶诗以谢之','劉禹錫','quantangshi','','卷20','红旗阅五兵，绛帐领诸生。
味道轻鼎食，退公犹笔耕。
青箱传学远，金匮纳书成。
一瞬见前事，九流当抗行。
编蒲曾苦思，垂竹愧无名。
今日承芳讯，谁言赠衮荣。','',''),('quantangshi-19294','和杨侍郎初至郴州纪事书情题郡斋八韵','劉禹錫','quantangshi','','卷20','旌节下朝台，分圭从北回。
城头鹤立处，驿树凤栖来。
旧路芳尘在，新恩馹骑催。
里闾风偃草，鼓舞拚成雷。
吏散山禽啭，庭香夏蕊开。
郡斋堪四望，壁记有三台。
人讶征黄晚，文非吊屈哀。
一吟梁甫曲，知是卧龙才。','',''),('quantangshi-19295','和东川王相公新涨驿池八韵','劉禹錫','quantangshi','','卷20','今日池塘上，初移造物权。
苞藏成别岛，沿浊致清涟。
变化生言下，蓬瀛落眼前。
泛觞惊翠羽，开幕对红莲。
远写风光入，明含气象全。
渚烟笼驿树，波日漾宝筵。
曲岸留缇骑，中流转彩船。
无因接元礼，共载比神仙。','',''),('quantangshi-19296','酬杨八庶子喜韩吴兴与余同迁见赠','劉禹錫','quantangshi','','卷20','早遇圣明朝，雁行登九霄。
文轻傅武仲，酒逼盖宽饶。
舍矢同瞻鹄，当筵共赛枭。
琢磨三益重，唱和五音调。
台柏烟常起，池荷香暗飘。
星文辞北极，旗影度东辽。
直道由来黜，浮名岂敢要。
三湘与百越，雨散又云摇。
远守慙侯籍，征还荷诏条。
顇容唯舌在，别恨几魂销。
满眼悲陈事，逢人少旧僚。
烟霞为老伴，蒲柳任先凋。
虎绶悬新印，龙舼理去桡。
断肠天北郡，携手洛阳桥。
幢盖今虽贵，弓旌会见招。
其如草玄客，空宇久寥寥。','',''),('quantangshi-19297','和兵部郑侍郎省中四松诗十韵','劉禹錫','quantangshi','','卷20','右相历中台，移松武库栽。
紫茸抽组绶，青实长玫瑰。
便有干霄势，看成构厦材。
数分天柱半，影逐日轮回。
旧赏台阶去，新知谷口来。
息阴常仰望，翫境几裴回。
翠粒晴悬露，苍鳞雨起苔。
凝音助瑶瑟，飘蘂泛金罍。
月桂花遥烛，星榆叶对开。
终须似鸡树，荣茂近昭回。','',''),('quantangshi-19298','酬郑州权舍人见寄十二韵','劉禹錫','quantangshi','','卷20','朱户凌晨启，碧梧含早凉。
人从桔柣至，书到漆沮傍。
拚会因佳句，情深取断章。
惬心同笑语，入耳胜笙簧。
忆昔三条路，居邻数仞墙。
学堂青玉案，彩服紫罗囊。
麟角看成就，龙驹见抑扬。
彀中飞一箭，云际落双鸧。
甸邑叨前列，天台愧后行。
鲤庭传事业，鸡树遂翱翔。
书殿连鳷鹊，神池接凤凰。
追游蒙尚齿，惠好结中肠。
铩翮方抬举，危根易损伤。
一麾怜弃置，五字借恩光。
汝海崆峒秀，溱流芍药芳。
风行能偃草，境静不争桑。
转斾趋关右，颁条匝渭阳。
病吟犹有思，老醉已无狂。
尘满鸿沟道，沙惊白狄乡。
伫闻黄纸诏，促召紫微郎。','',''),('quantangshi-19299','和牛相公题姑苏所寄太湖石兼寄李苏州','劉禹錫','quantangshi','','卷20','震泽生奇石，沈潜得地灵。
初辞水府出，犹带龙宫腥。
发自江湖国，来荣卿相庭。
从风夏云势，上汉古查形。
拂拭鱼鳞见，铿锵玉韵聆。
烟波含宿润，苔藓助新青。
嵌穴胡雏貌，纤铓虫篆铭。
孱颜傲林薄，飞动向雷霆。
烦热近还散，余酲见便醒。
凡禽不敢息，浮壒莫能停。
静称垂松盖，鲜宜映鹤翎。
忘忧常目击，素尚与心冥。
眇小欺湘燕，团圆笑落星。
徒然想融结，安可测年龄。
采取询乡耋，搜求按旧经。
垂钩入空隙，隔浪动晶荧。
有获人争贺，欢谣众共听。
一州惊阅宝，千里远扬舲。
覩物洛阳陌，怀人吴御亭。
寄言垂天翼，早晚起沧溟。','',''),('quantangshi-19300','浙西李大夫述梦四十韵并浙东元相公酬和斐然继声','劉禹錫','quantangshi','','卷20','位是才能取，时因际会遭。
羽仪呈鸑鷟，铓刃试豪曹。
洛下推年少，山东许地高。
门承金铉鼎，家有玉璜韬。
海浪扶鹏翅，天风引骥髦。
便知蓬阁閟，不识鲁衣襃。
兴发春塘草，魂交益部刀。
形开犹抱膝，烛尽遽挥毫。
昔仕当初筮，逢时咏载橐。
怀铅辨虫蠹，染素学鹅毛。
车骑方休汝，归来欲效陶。
南台资謇谔，内署选风骚。
羽化如乘鲤，楼居旧冠鳌。
美香焚湿麝，名果赐干萄。
议赦蝇栖笔，邀歌蚁泛醪。
代言无所戏，谢表自称叨。
兰焰凝芳泽，芝泥莹玉膏。
对频声价出，直久梦魂劳。
草诏令归马，批章答献獒。
银花悬院牓，翠羽映帘条。
讽谏欣然纳，奇觚率尔操。
禁中时谔谔，天下免忉忉。
左顾龟成印，双飞鹄织袍。
谢宾缘地密，洁己是心豪。
五日思归沐，三春羡众邀。
茶炉依绿笋，棊局就红桃。
溟海桑潜变，阴阳炭暗熬。
仙成脱屣去，臣恋捧弓号。
建节辞乌柏，宣风看鹭涛。
土山京口峻，铁瓮郡城牢。
曲岛花千树，官池水一篙。
莺来和丝管，雁起拂麾旄。
宛转倾罗扇，回旋堕玉搔。
罚筹长竖纛，觥盏样如舠。
山是千重障，江为四面濠。
卧龙曾得雨，孤鹤尚鸣臯。
剑用熊开匣，弓闲蛰受弢。
凤姿尝在竹，鷃羽不离蒿。
吴月分双镇，东西接万艘。
今朝比潘陆，江海更滔滔。','',''),('quantangshi-19301','和浙西李大夫伊川卜居','劉禹錫','quantangshi','','卷20','早入八元数，尝承三接恩。
飞鸣天上路，镇压海西门。
清望寰中许，高情物外存。
时来诚不让，归去每形言。
洛下思招隐，江干压作藩。
按经修道具，依样买山村。
开凿随人化，幽阴为律暄。
远移难得树，立变旧荒园。
绝塞通潜径，平泉占上原。
烟霞遥在想，簿领益为繁。
丹禁虚东合，苍生望北辕。
徒令双白鹤，五里自翩飜。','',''),('quantangshi-19302','省试风光草际浮','劉禹錫','quantangshi','','卷20','熙熙春景霁，草绿春光丽。
的历乱相鲜，葳蕤互亏蔽。
乍疑芊绵里，稍动丰茸际。
影碎翻崇兰，浮香转丛蕙。
含烟绚碧彩，带露如珠缀。
幸因采掇日，况此临芳岁。','',''),('quantangshi-19303','历阳书事七十韵','劉禹錫','quantangshi','','卷20','一夕为湖地，千年列郡名。
霸王迷路处，亚父所封城。
汉置东南尉，梁分肘腋兵。
本吴风俗剽，兼楚语音伧。
沸井今无涌，乌江旧有名。
土台游柱史，石室隐彭铿。
曹操祠犹在，濡须坞未平。
海潮随月大，江水应春生。
忆昨深山里，终朝看火耕。
鱼书来北阙，鷁首下南荆。
云雨巫山暗，蕙兰湘水清。
章华树已失，鄂渚草来迎。
庐阜香炉出，湓城粉堞明。
雁飞彭蠡暮，鸦噪大雷晴。
平野分风使，恬和趁夜程。
贵池登陆峻，舂谷渡桥鸣。
骆驿主人问，悲欢故旧情。
几年方一面，卜昼便三更。
助喜杯盘盛，忘机笑语訇。
管清疑警鹤，弦巧似娇莺。
炽炭烘蹲兽，华茵织鬬鲸。
回裾飘雾雨，急节堕琼英。
敛黛凝愁色，施钿耀翠晶。
容华本南国，妆束学西京。
日落方收鼓，天寒更炙笙。
促筵交履舄，痛饮倒簪缨。
谑浪容优孟，娇怜许智琼。
蔽明添翠帟，命烛拄金茎。
坐久罗衣皱，杯频粉面騂。
兴来从请曲，意堕即飞觥。
令急重须改，欢冯醉尽呈。
诘朝还选胜，来日又寻盟。
道别殷勤惜，邀筵次第争。
唯闻嗟短景，不复有余酲。
众散扃朱户，相携话素诚。
晤言犹亹亹，残漏自丁丁。
出祖千夫拥，行厨五熟烹。
离亭临野水，别思入哀筝。
接境人情洽，方冬馔具精。
中流为界道，隔岸数飞甍。
沙浦王浑镇，沧洲谢脁城。
望夫人化石，梦帝日环营。
半渡趋津吏，缘堤簇郡甿。
场黄堆晚稻，篱碧见冬菁。
里社争来献，壶浆各自擎。
鸱夷倾底写，[粔籹]鬬成。
采石风传柝，新林暮击钲。
茧纶牵拨刺，犀焰照澄泓。
露冕观原野，前驱抗斾旌。
分庭展宾主，望阙拜恩荣。
比屋惸嫠辈，连年水旱并。
遐思常后已，下令必先庚。
远岫低屏列，支流曲带萦。
湖鱼香胜肉，官酒重于饧。
忆昔泉源变，斯须地轴倾。
鸡笼为石颗，龟眼入泥坑。
事系人风重，官从物论轻。
江春俄澹荡，楼月几亏盈。
柳长千丝宛，田塍一线絣。
游鱼将婢从，野雉见媒惊。
波净攒凫鹊，洲香发杜蘅。
一钟菰葑米，千里水葵羹。
受谴时方久，分忧政未成。
比琼虽碌碌，于铁尚铮铮。
早忝登三署，曾闻奏六英。
无能甘负弩，不慎在提衡。
口语成中遘，毛衣阻上征。
时闻关利钝，智亦有聋盲。
昔愧山东妙，今慙海内兄。
后来登甲乙，早已在蓬瀛。
心托秦明镜，才非楚白珩。
齿衰亲药物，宦薄傲公卿。
捧日皆元老，宣风尽大彭。
好令朝集使，结束赴新正。','',''),('quantangshi-19304','和武中丞秋日寄怀简诸僚故','劉禹錫','quantangshi','','卷20','退朝还公府，骑吹息繁阴。
吏散秋庭寂，乌啼烟树深。
威生奉白简，道胜外华簪。
风物清远目，功名怀寸阴。
云衢念前侣，彩翰写冲襟。
凉菊照幽径，败荷攒碧浔。
感时江海思，报国松筠心。
空愧寿陵步，芳尘何处寻。','',''),('quantangshi-19305','和令狐相公春日寻花有怀白侍郎阁老','劉禹錫','quantangshi','','卷20','芳菲满雍州，鸾凤许同游。
