功名耻计擒生数，直斩楼兰报国恩。','',''),('quantangshi-19573','塞下曲五首 四','張仲素','quantangshi','','卷20','陇水潺湲陇树秋，征人到此泪双流。
乡关万里无因见，西戍河源早晚休。','',''),('quantangshi-19574','塞下曲五首 五','張仲素','quantangshi','','卷20','阴碛茫茫塞草肥，桔槔烽上暮云飞。
交河北望天连海，苏武曾将汉节归。','',''),('quantangshi-19575','秋思二首 一','張仲素','quantangshi','','卷20','碧窗斜日蔼深晖，愁听寒螿泪湿衣。
梦里分明见关塞，不知何路向金微。','',''),('quantangshi-19576','秋思二首 二','張仲素','quantangshi','','卷20','秋天一夜静无云，断续鸿声到晓闻。
欲寄征衣问消息，居延城外又移军。','',''),('quantangshi-19577','汉苑行二首','張仲素','quantangshi','','卷20','回雁高飞太液池，新花低发上林枝。
年光到处皆堪赏，春色人间总不知。','',''),('quantangshi-19578','汉苑行二首 二','張仲素','quantangshi','','卷20','春风淡荡景悠悠，莺啭高枝燕入楼。
千步回廊闻凤吹，珠帘处处上银钩。','',''),('quantangshi-19579','天马辞二首 一','張仲素','quantangshi','','卷20','天马初从渥水来，郊歌曾唱得龙媒。
不知玉塞沙中路，苜蓿残花几处开。','',''),('quantangshi-19580','天马辞二首 二','張仲素','quantangshi','','卷20','躞蹀宛驹齿未齐，摐金喷玉向风嘶。
来时欲尽金河道，猎猎轻风在碧蹄。','',''),('quantangshi-19581','燕子楼诗三首 一','張仲素','quantangshi','','卷20','楼上残灯伴晓霜，独眠人起合欢牀。
相思一夜情多少，地角天涯不是长。','',''),('quantangshi-19582','燕子楼诗三首 二','張仲素','quantangshi','','卷20','北邙松栢锁愁烟，燕子楼人思悄然。
自埋劒履歌尘散，红袖香消已十年。','',''),('quantangshi-19583','燕子楼诗三首 三','張仲素','quantangshi','','卷20','适看鸿雁岳阳回，又覩玄禽逼社来。
瑶瑟玉箫无意绪，任从蛛网任从灰。','',''),('quantangshi-19584','赋得冬日可爱','庾承宣','quantangshi','','卷20','宿雾开天霁，寒郊见初日。
林疎照逾远，冰轻影微出。
岂假阳和气，暂忘玄冬律。
愁抱望自宽，羁情就如失。
欣欣事几许，曈曈状非一。
倾心倘知期，良愿自兹毕。','',''),('quantangshi-19585','赠毛仙翁','鄭澣','quantangshi','','卷20','至道无名，至人长生。
爰观绘事，以挹真形。
方口渥丹，浓眉刷青。
松姿本秀，鹤质自轻。
道德神仙，内蕴心灵。
红肌丝发，外彰华精。
色如含芳，貌若和光。
胚浑造化，含吐阴阳。
吾闻安期，隐见不常。
或在世间，或游上苍。
猗欤真人，得非后身。
写此仙骨，久而不磷。
皎皎明眸，瞭然如新。
蔼蔼童颜，的然如春。
金石可并，丹青不冺。
通天台上，有见常人。
俗士观瞻，方悟幽尘。
君子图之，敬兮如神。','',''),('quantangshi-19586','和李德裕游汉州房公湖二首 一','鄭澣','quantangshi','','卷20','太尉留琴地，时移重可寻。
徽弦一掩抑，风月助登临。
荣驻青油骑，高张白雪音。
秖言酬唱美，良史记王箴。','',''),('quantangshi-19587','和李德裕游汉州房公湖二首 二','鄭澣','quantangshi','','卷20','静对烟波夕，犹思栋宇青。
卧龙空有处，驯鸟独忘情。
顾步襟期远，参差物象横。
自宜雕乐石，爽气际青城。','',''),('quantangshi-19588','中书相公任兵部侍郎日后阁植四松逾数年澣忝此官因献拙什','鄭澣','quantangshi','','卷20','丞相当时植，幽襟对此开。
人知舟檝器，天假栋梁材。
错落龙鳞出，䙰褷鹤翅回。
重阴罗武库，细响静山台。
得地公堂里，移根涧水隈。
吴臣梦寐远，秦岳岁年摧。
转觉飞缨缪，何因继组来。
几寻珠履迹，愿比角弓培。
栢悦犹依社，星高久照台。
后凋应共操，无复问良媒。','',''),('quantangshi-19589','和李德裕房公旧竹亭闻琴','鄭澣','quantangshi','','卷20','石室寒飙惊，孙枝雅器裁。
坐来山水操，玄断吊遗埃。','',''),('quantangshi-19590','句','鄭澣','quantangshi','','卷20','但虑彩色污，无虞臂胛肥。','',''),('quantangshi-19591','游栖霞寺','張彙','quantangshi','','卷20','跻险入幽林，翠微含竹殿。
泉声无休歇，山色时隐见。
潮来杂风雨，梅落成霜霰。
一从方外游，顿觉尘心变。','',''),('quantangshi-19592','春风扇微和','張彙','quantangshi','','卷20','木德生和气，微微入曙风。
暗催南向叶，渐翥北归鸿。
澹荡侵冰谷，悠扬转蕙丛。
拂尘回广路，泛籁过遥空。
暖上烟光际，云移律侯中。
扶摇如可借，从此戾苍穹。','',''),('quantangshi-19593','观藏冰','張彙','quantangshi','','卷20','寒气方穷律，阴精正结冰。
体坚风带壮，影素月临凝。
冬赋凌人掌，春期命妇升。
凿来壶色彻，纳处镜光澄。
鲁史曾留问，幽诗旧见称。
同观里射享，王道颂还兴。','',''),('quantangshi-19594','赋得春风扇微和','張彙','quantangshi','','卷20','习习和风扇，悠悠淑气微。
阳升知候改，律应喜春归。
池柳晴初拆，林莺暖欲飞。
川原浮彩翠，台馆动光辉。
泛艳摇丹阙，扬芳入粉闱。
发生当有分，枯朽幸因依。','',''),('quantangshi-19595','金谷园怀古','張彙','quantangshi','','卷20','缓步洛城下，轸怀金谷园。
昔人随水逝，旧树逐春繁。
冉冉摇风弱，菲菲裛露翻。
歌台岂易见，舞袖乍如存。
戏蝶香中起，流莺暗处喧。
徒闻施锦帐，此地拥行轩。','',''),('quantangshi-19596','句','張彙','quantangshi','','卷20','应念路傍憔悴翼，昔年乔木幸同迁。','',''),('quantangshi-19597','立春日晓望三素云','李應','quantangshi','','卷20','玄鸟初来日，灵仙望里分。
冰容朝上界，玉辇拥朝云。
碧落流轻艳，红霓间彩文。
带烟时缥缈，向斗更氤氲。
仿髴随风驭，迢遥出晓雰。
兹辰三见后，希得从元君。','',''),('quantangshi-19598','立春日晓望三素云','陳師穆','quantangshi','','卷20','晴晓初春日，高心望素云。
彩光浮玉辇，紫气隐元君。
缥缈中天去，逍遥上界分。
鸾骖攀不及，仙吹远难闻。
礼候于斯覩，明循在解纷。
人归悬想处，霞色自氛氲。','',''),('quantangshi-19599','立春日晓望三素云','李季何','quantangshi','','卷20','霭霭青春曙，飞仙驾五云。
浮轮初缥缈，承盖下氤氲。
薄影随风度，殊容向日分。
羽毛纷共远，环佩杳犹闻。
静合烟霞色，遥将鸾鹤羣。
年年瞻此节，应许从元君。','',''),('quantangshi-19600','春台晴望','李程','quantangshi','','卷20','曲台送春目，景物丽新晴。
霭霭烟收翠，忻忻木向荣。
静看迟日上，闲爱野云平。
风慢游丝转，天开远水明。
登高尘虑息，观徼道心清。
更有迁乔意，翩翩出谷莺。','',''),('quantangshi-19601','玉壶冰','李程','quantangshi','','卷20','琢玉性惟坚，成壶体更圆。
虚心含众象，应物受寒泉。
温润资天质，清贞禀自然。
日融光乍散，雪照色逾鲜。
至鉴功宁宰，无私照岂偏。
明将水镜对，白与粉闱连。
拂拭终为美，提携伫见传。
勿令毫发累，遗恨鲍公篇。','',''),('quantangshi-19602','赋得竹箭有筠','李程','quantangshi','','卷20','常爱凌寒竹，坚贞可喻人。
能将先进礼，义与后凋邻。
冉冉犹全节，青青尚有筠。
陶钧二仪内，柯叶四时春。
待凤花仍吐，停霜色更新。
方持不易操，对此欲观身。','',''),('quantangshi-19603','观庆云图','李程','quantangshi','','卷20','五云从表瑞，藻绘宛成图。
柯叶何时改，丹青此不渝。
非烟色尚丽，似盖状应殊。
渥彩看犹在，轻阴望已无。
方将遇翠幄，那羡起苍梧。
欲识从龙处，今逢圣合符。','',''),('quantangshi-19604','赠毛仙翁','李程','quantangshi','','卷20','茫茫尘累愧腥膻，强把蜉蝣望列仙。
闲指紫霄峯下路，却归白鹿洞中天。
吹箫凤去经何代，茹玉方传得几年。
他日更来人世看，又应东海变桑田。','',''),('quantangshi-19605','省试春台晴望','高弁','quantangshi','','卷20','层台聊一望，遍赏帝城春。
风暖闻啼鸟，冰开见跃鳞。
晴山烟外翠，香蘂日边新。
已变青门柳，初销紫陌尘。
金汤千里国，车骑万方人。
此处云霄近，凭高愿致身。','',''),('quantangshi-19606','霜菊','席夔','quantangshi','','卷20','时令忽已变，行看被霜菊。
可怜后时秀，当此凛风肃。
淅沥翠枝翻，凄清金蘂馥。
凝姿节堪重，澄艳景非淑。
宁祛青女威，愿盈君子掬。
持来泛罇酒，永以照幽独。','',''),('quantangshi-19607','赋得竹箭有筠','席夔','quantangshi','','卷20','共爱东南美，青青叹有筠。
贞姿众木异，秀色四时均。
枝叶当无改，风霜岂惮频。
虚心如待物，劲节自留春。
鲜润期栖凤，婵娟可并人。
可怜初箨卷，粉泽更宜新。','',''),('quantangshi-19608','省试观庆云图','李行敏','quantangshi','','卷20','缣素传休祉，丹青状庆云。
非烟凝漠漠，似盖乍纷纷。
尚驻从龙意，全舒捧日文。
光因五色起，影向九霄分。
裂素观嘉瑞，披图贺圣君。
宁同窥汗漫，方此覩氛氲。','',''),('quantangshi-19609','赋得冬日可爱','陳諷','quantangshi','','卷20','寒日临清昼，寥天一望时。
未消埋迳雪，先暖读书帷。
属思光难驻，舒情影若遗。
晋臣曾比德，谢客昔言诗。
散彩宁偏照，流阴信不追。
余辉如可就，回烛幸无私。','',''),('quantangshi-19610','郡斋三月下旬作','崔護','quantangshi','','卷20','春事日已歇，池塘旷幽寻。
残红披独坠，嫩绿间浅深。
偃仰卷芳褥，顾步爱新阴。
谋春未及竟，夏初遽见侵。','',''),('quantangshi-19611','五月水边柳','崔護','quantangshi','','卷20','结根挺涯涘，垂影覆清浅。
睡脸寒未开，嬾腰晴更软。
摇空条已重，拂水带方展。
似醉烟景凝，如愁月露泫。
丝长鱼悞恐，枝弱禽惊践。
长别几多情，含春任攀搴。','',''),('quantangshi-19612','三月五日陪裴大夫泛长沙东湖','崔護','quantangshi','','卷20','上巳余风景，芳辰集远坰。
彩舟浮泛荡，绣毂下娉婷。
林树回葱蒨，笙歌入杳冥。
湖光迷翡翠，草色醉蜻蜓。
鸟弄桐花日，鱼翻谷雨萍。
从今留胜会，谁看画兰亭。','',''),('quantangshi-19613','山鸡舞石镜','崔護','quantangshi','','卷20','庐峯开石镜，人说舞山鸡。
物象纤舞隐，禽情秖自迷。
景当烟雾歇，心喜锦翎齐。
宛转乌呈彩，婆娑凤欲栖。
何言资羽族，在地得天倪。
应笑翰音者，终朝饮败醯。','',''),('quantangshi-19614','题都城南庄','崔護','quantangshi','','卷20','去年今日此门中，人面桃花相映红。
人面不知何处在，桃花依旧笑春风。','',''),('quantangshi-19615','晚鸡','崔護','quantangshi','','卷20','黯黯严城罢鼓鼙，数声相续出寒栖。
不嫌惊破纱窗梦，却恐为奴半夜啼。','',''),('quantangshi-19616','赠药山高僧惟俨二首 一','李翱','quantangshi','','卷20','练得身形似鹤形，千株松下两函经。
我来问道无余说，云在青霄水在瓶。','',''),('quantangshi-19617','赠药山高僧惟俨二首 二','李翱','quantangshi','','卷20','选得幽居惬野情，终年无送亦无迎。
有时直上孤峯顶，月下披云啸一声。','',''),('quantangshi-19618','赠毛仙翁','李翱','quantangshi','','卷20','紫霄仙客下三山，因救生灵到世间。
龟鹤计年承甲子，冰霜为质驻童颜。
韬藏休咎传真箓，变化荣枯试小还。
从此便教尘骨贵，九霄云路愿追攀。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-19619','拜禹歌','李翱','quantangshi','','卷20','惟天地之无穷兮，哀生人之常勤。
往者吾弗及兮，来者吾弗闻。
已而，已而。','',''),('quantangshi-19620','广庆寺','李翱','quantangshi','','卷20','传者不足信，见景胜如闻。
一水远赴海，两山高入云。
鱼龙晴自戏，猿狖晚成羣。
醉酒斜阳下，离心草自薰。','',''),('quantangshi-19621','奉酬刘言史宴光风亭','李翱','quantangshi','','卷20','闰余春早景沈沈，禊饮风亭恣赏心。
红袖青娥留永夕，汉阴宁肯羡山阴。','',''),('quantangshi-19622','戏赠诗','李翱','quantangshi','','卷20','县君好砖渠，绕水恣行游。
鄙性乐疎野，凿地便成沟。
两岸值芳草，中央漾清流。
所尚既不同，砖凿可自修。
从他后人见，境趣谁为幽。','',''),('quantangshi-19623','题浯溪石','皇甫湜','quantangshi','','卷20','次山有文章，可惋只在碎。
然长于指叙，约洁有余态。
心语适相应，出句多分外。
于诸作者间，拔戟成一队。
中行虽富剧，粹美若可盖。
子昂感遇佳，未若君雅裁。
退之全而神，上与千载对。
李杜才海翻，高下非可概。
文与一气间，为物莫与大。
先王路不荒，岂不仰吾辈。
石屏立衙衙，溪口扬素濑。
我思何人知，徙倚如有待。','',''),('quantangshi-19624','石佛谷','皇甫湜','quantangshi','','卷20','[澶漫]太行北，千里一块石。
平腹有壑谷，深广数百尺。
土僧何为者，老草毛发白。
寝处容身龛，足膝隐成迹。
金仙琢灵象，相好倚北壁。
花座五云扶，玉豪六虚射。
文人留纪述，时事可辨析。
鸟迹巧均分，龙骸极癯瘠。
枯松间槎枿，猛兽恣腾掷。
蛣𧎜虫食纵，悬垂露凝滴。
精艺贯古今，穷岩谁爱惜。
托师禅诵余，勿使尘埃积。','',''),('quantangshi-19625','出世篇','皇甫湜','quantangshi','','卷20','生当为大丈夫，断羁罗，出泥涂。
四散号呶，[俶扰]无隅。
埋之深渊，飘然上浮。
骑龙披青云，泛览游八区。
经太山，绝大海，一长吁。
西摩月镜，东弄日珠。
上括天之门，直指帝所居。
羣仙来迎塞天衢，凤皇鸾鸟灿金舆。
音声嘈嘈满太虚，旨饮食兮照庖厨。
食之不饫饫不尽，使人不陋复不愚。
旦旦狎玉皇，夜夜御天姝。
当御者几人，百千为番。
宛宛舒舒，忽不自知。
支消体化膏露明，湛然无色茵席濡。
俄而散漫，[斐]然虚无。
翕然复抟，抟久而苏。
精神如太阳，霍然照清都。
四肢为琅玕，五脏为璠璵。
颜如芙蓉，顶为醍醐。
与天地相终始，浩漫为欢娱。
下顾人间，溷粪蝇蛆。','',''),('quantangshi-19626','蜀绵州越王楼诗','樊宗師','quantangshi','','卷20','危楼倚天门，如𨶻星辰宫。
榱薄龙虎怪，洄洄绕雷风。
徂秋试登临，大霭屯乔空。
不见西北路，考怀益雕穷。
石濑薄溅溅，上山杳穹穹。
昔人创为逝，所适酡颜红。
今我兹之来，犹校成岁功。
辍田植科亩，游圃歌芳丛。
地财无丛厚，人室安取丰。
既乏富庶能，千万慙文翁。','',''),('quantangshi-19627','催妆','盧儲','quantangshi','','卷20','昔年将去玉京游，第一仙人许状头。
今日幸为秦晋会，早教鸾凤下妆楼。','',''),('quantangshi-19628','官舍迎内子有庭花开','盧儲','quantangshi','','卷20','芍药斩新栽，当庭数朵开。
东风与拘束，留待细君来。','',''),('quantangshi-19629','古松感兴','皇甫松','quantangshi','','卷20','皇天后土力，使我向此生。
贵贱不我均，若为天地情。
我家世道德，旨意匡文明。
家集四百卷，独立天地经。
寄言青松姿，岂羡朱槿荣。
昭昭大化光，共此遗芳馨。','',''),('quantangshi-19630','怨回纥歌','皇甫松','quantangshi','','卷20','白首南朝女，愁听异域歌。
收兵颉利国，饮马胡芦河。
毳布腥膻久，穹庐岁月多。
雕巢城上宿，吹笛泪滂沱。','',''),('quantangshi-19631','江上送别','皇甫松','quantangshi','','卷20','祖席驻征棹，开帆候信潮。
隔筵桃叶泣，吹管杏花飘。
船去鸥飞阁，人归尘上桥。
别离惆怅泪，江路湿红蕉。','',''),('quantangshi-19632','采莲子二首 一','皇甫松','quantangshi','','卷20','菡萏香连十顷陂，小姑贪戏采莲迟。
晚来弄水船头湿，更脱红裙裹鸭儿。','',''),('quantangshi-19633','采莲子二首 二','皇甫松','quantangshi','','卷20','船动湖光灧灧秋，贪看年少信船流。
无端隔水抛莲子，遥被人知半日羞。','',''),('quantangshi-19634','抛球乐 一','皇甫松','quantangshi','','卷20','红拨一声飘，轻球坠越绡。
带翻金孔雀，香满绣蜂腰。
少少抛分数，花枝正索饶。','',''),('quantangshi-19635','抛球乐 二','皇甫松','quantangshi','','卷20','金蹙花球小，真珠绣带垂。
几回冲蜡烛，千度入春怀。
上客终须醉，觥杯自乱排。','',''),('quantangshi-19636','劝僧酒','皇甫松','quantangshi','','卷20','劝僧一杯酒，共看青青山。
酣然万象灭，不动心印闲。','',''),('quantangshi-19637','登郭隗台','皇甫松','quantangshi','','卷20','燕相谋在兹，积金黄巍巍。
上诸欲何颜，使我千载悲。','',''),('quantangshi-19638','杨柳枝词二首 一','皇甫松','quantangshi','','卷20','烂漫春归水国时。
吴王宫殿柳丝垂，黄莺长叫空闺畔。
西子无因更得知。','',''),('quantangshi-19639','杨柳枝词二首 二','皇甫松','quantangshi','','卷20','春入行宫映翠微，玄宗侍女舞烟丝。
如今柳向空城绿，玉笛何人更把吹。','',''),('quantangshi-19640','浪淘沙二首 一','皇甫松','quantangshi','','卷20','滩头细草接疎林，浪恶罾船半欲沈。
宿鹭眠洲非旧浦，去年沙觜是江心。','',''),('quantangshi-19641','浪淘沙二首 二','皇甫松','quantangshi','','卷20','蛮歌豆蔻北人愁，松雨蒲风野艇秋。
浪起䴔䴖眠不得，寒沙细细入江流。','',''),('quantangshi-19642','句','皇甫松','quantangshi','','卷20','夜入真珠室，朝游玳瑁宫。','',''),('quantangshi-19643','送皇甫湜赴举','馬異','quantangshi','','卷20','马蹄声特特，去入天子国。
借问去是谁，秀才皇甫湜。
吞吐一腹文，八音兼五色。
主文有崔李，郁郁为朝德。
青铜镜必明，朱丝绳必直。
称意太平年，愿子长相忆。','',''),('quantangshi-19644','贞元旱岁','馬異','quantangshi','','卷20','赤地炎都寸草无，百川水沸煮虫鱼。
定应燋烂无人救，泪落三篇古尚书。','',''),('quantangshi-19645','暮春醉中寄李干秀才','馬異','quantangshi','','卷20','欢异且交亲，酒生开瓮春。
不须愁犯卯，且乞醉过申。
折草为筹筯，铺花作锦裀。
娇莺解言语，留客也殷勤。','',''),('quantangshi-19646','答卢仝结交诗','馬異','quantangshi','','卷20','有鸟自南翔，口衔一书扎，达我山之维。
开缄金玉焕陆离，乃是卢仝结交诗。
此诗峭绝天边格，力与文星色相射。
长河拔作数条丝，太华磨成一拳石。
莫嗟独笑无往还，月中芳桂难追攀。
况值乱邦不平年，回陵倒谷如等闲。
与君俯首大艰阻，喙长三尺不得语。
因君今日形章句，羡猕猴兮着衣裳。
悲蚯蚓兮安翅羽，上天不识察。
仰我为辽天失所，将吾劒兮切淤泥。
使良骥兮捕老鼠，昨日脱身卑贱笼。
卯星借与老人峯，抱锄劚地芸芝术。
偃盖参天旧有松，术与松兮保身世。
卧居居兮起于于，漱潺潺兮聆嘒嘒。
道在其中可终岁，不教辜负尧为帝。
烧我荷衣摧我身，回看天地如砥平。
钢刀锉骨不辞去，卑躬君子今明明。
俛首辞山心惨恻，白云虽好恋不得。
看云且拟直须臾，疾风又卷西飞翼。
为报覃怀心结交，死生富贵存后凋。
我心不畏朱公叔，君意须防刘孝标。
以胶投漆苦不早，就中相去万里道。
河水悠悠山之间，无由把袂摅怀抱。
忆仝吟能文，洽臭成兰薰。
不知何处清风夕，拟使张华见陆云。','',''),('quantangshi-19647','白云起封中诗','呂溫','quantangshi','','卷20','封开白云起，汉帝坐斋宫。
望在泥金上，疑生祕玉中。
攒柯初缭绕，布叶渐蒙笼。
日观祥光合，天门瑞气通。
无心已出岫，有势欲凌风。
倘遣成膏泽，从兹遍大空。','',''),('quantangshi-19648','终南精舍月中闻磬声诗','呂溫','quantangshi','','卷20','月峰禅室掩，幽磬静昏氛。
思入空门妙，声从觉路闻。
泠泠满虚壑，杳杳出寒云。
天籁疑难辨，霜钟谁可分。
偶来游法界，便欲谢人羣。
竟夕听真响，尘心自解纷。','',''),('quantangshi-19649','青出蓝诗','呂溫','quantangshi','','卷20','物有无穷好，蓝青又出青。
朱研未比德，白受始成形。
袍袭宜从政，衿垂可问经。
当时不采撷，作色几飘零。','',''),('quantangshi-19650','奉和李相公早朝于中书候传点偶书所怀奉呈门下武相公中书郑相公','呂溫','quantangshi','','卷20','禁门留骑吹，内省正衣冠。
稍辨旗常色，尚闻钟漏残。
九天炉气暖，六月玉声寒。
宿雾开霞观，晨光泛露盘。
致君期反朴，求友得如兰。
政自同归理，言成共不刊。
准绳临百度，领袖映千宫。
卧鼓流沙静，飞航涨海安。
尽规酬主意，偕赋代交欢。
雅韵人间满，多慙窃和难。','',''),('quantangshi-19651','奉和武中丞秋日台中寄怀简诸僚友','呂溫','quantangshi','','卷20','圣朝思纪律，宪府得中贤。
指顾风行地，仪形月丽天。
不仁恒自远，为政复何先。
虚室唯生白，闲情却草玄。
迎霜红叶早，过雨碧苔鲜。
鱼乐翻秋水，乌声隔暮烟。
旧游多绝席，感物遂成篇。
更许穷荒谷，追歌白雪前。','',''),('quantangshi-19652','吐蕃别馆和周十一郎中杨七录事望白水山作','呂溫','quantangshi','','卷20','纯精结奇状，皎皎天一涯。
玉嶂拥清气，莲峰开白花。
半岩晦云雪，高顶澄烟霞。
朝昏对宾馆，隐映如仙家。
夙闻蕴孤尚，终欲穷幽遐。
暂因行役暇，偶得志所嘉。
明时无外户，胜境即中华。
况今舅甥国，谁道隔流沙。','',''),('quantangshi-19653','奉和张舍人阁中直夜思闻雅琴因书事通简僚友','呂溫','quantangshi','','卷20','迢递天上直，寂寞丘中琴。
忆尔山水韵，起予仁智心。
凝情在正始，超想疎烦襟。
凉生子夜后，月照禁垣深。
远风霭兰气，微露清桐阴。
方袭缁衣庆，永奉南薰吟。','',''),('quantangshi-19654','和舍弟惜花绝句','呂溫','quantangshi','','卷20','去年无花看，今年未看花。
更闻飘落尽，走马向谁家。','',''),('quantangshi-19655','和恭听晓笼中山鹊','呂溫','quantangshi','','卷20','掩[抑]中天意，凄怆触笼音。
惊晓一闻处，伤春千里心。','',''),('quantangshi-19656','和舍弟让笼中鹰','呂溫','quantangshi','','卷20','未用且求安，无猜也不残。
九天飞势在，六月目[睛]寒。
动触樊笼倦，闲消肉食难。
主人憎恶鸟，试待一呼看。','',''),('quantangshi-19657','同恭夏日题寻真观李宽中秀才书院','呂溫','quantangshi','','卷20','闭院开轩笑语阑，江山并入一壶宽。
微风但觉杉香满，烈日方知竹气寒。
披卷最宜生白室，吟诗好就步虚坛。
愿君此地攻文字，如炼仙家九转丹。','',''),('quantangshi-19658','同舍弟恭岁暮寄晋州李六协律三十韵','呂溫','quantangshi','','卷20','古人犹悲秋，况复岁暮时。
急景迫流念，穷阴结长悲。
阳乌下西岭，月鹊惊南枝。
揽衣步霜砌，倚杖临冰池。
怳怳若有失，悄悄良不怡。
忽闻晨起吟，宛是同所思。
有美壮感激，无何远栖迟。
摧藏变化用，掩抑扶摇姿。
时杰岂虚出，天道信可欺。
巨川望汔济，寒谷待潜吹。
劒匣益精利，玉韬宁磷缁。
戒哉轻沽诸，行矣自宠之。
伊我抱微尚，仲氏即心期。
讨论自少小，形影相差池。
比来胸中气，欲耀天下奇。
云雨沛萧艾，烟阁双萎蕤。
几年困方枘，一旦迷多岐。
道因穷理悟，命以尽性知。
事去类绝弦，时来如转规。
伊吕偶然得，孔墨徒尔为。
早行多露悔，强进触藩羸。
功名岂身利，仁义非吾私。
万物自身化，一失何驱驰。
不如任行止，委命安所宜。
劝君休感叹，与予陶希夷。
明年郊天后，庆泽岁华滋。
曲水杏花雪，香街青柳丝。
良时且暂欢，罇酒聊共持。
闲过漆园叟，醉看五陵儿。
寄言思隐处，不久来相追。','',''),('quantangshi-19659','青海西寄窦三端公','呂溫','quantangshi','','卷20','时同事弗同，穷节厉阴风。
我役流沙外，君朝紫禁中。
从容非所羡，辛苦竟何功。
但示酬恩路，浮生任转蓬。','',''),('quantangshi-19660','蕃中拘留岁余回至陇石先寄城中亲故','呂溫','quantangshi','','卷20','蓬转星霜改，兰陔色养违。
穷泉百死别，绝域再生归。
镜数成丝发，囊收抆血衣。
酬恩有何力，秖弃一毛微。','',''),('quantangshi-19661','吐蕃别馆卧病寄朝中诸友','呂溫','quantangshi','','卷20','星汉纵横车马喧，风摇玉佩烛花繁。
岂知羸卧穷荒外，日满深山犹闭门。','',''),('quantangshi-19662','吐蕃别馆中和日寄朝中僚旧','呂溫','quantangshi','','卷20','清时令节千官会，绝域穷山一病夫。
遥想满堂欢笑处，几人缘我向西隅。','',''),('quantangshi-19663','及第后答潼关主人','呂溫','quantangshi','','卷20','本欲云雨化，却随波浪翻。
一沾太常第，十过潼关门。
志力且虚弃，功名谁复论。
主人故相问，[慙]笑不能言。','',''),('quantangshi-19664','河中城南姚家浴后题赠主人','呂溫','quantangshi','','卷20','新浴振轻衣，满堂寒月色。
主人有美酒，况是曾相识。','',''),('quantangshi-19665','看浑中丞山桃花初有他客不通晚方得入因有戏赠','呂溫','quantangshi','','卷20','朝来驻马香街里，风度遥闻语笑声。
无事闭门教日晚，山桃落尽不胜情。','',''),('quantangshi-19666','赠友人','呂溫','quantangshi','','卷20','南山双乔松，擢本皆千寻。
夕流膏露津，朝被青云阴。
负雪出深涧，摇风倚高岑。
明堂久不构，云干何森森。
匠意方雕巧，时情正夸淫。
生材会有用，天地岂无心。','',''),('quantangshi-19667','道州夏日郡内北桥新亭书怀赠何元二处士','呂溫','quantangshi','','卷20','结构池梁上，登临日几回。
晴空交密叶，阴岸积苍苔。
爽气中央满，清风四面来。
振衣生羽翰，高枕出尘埃。
齐物鱼何乐，忘机鸟不猜。
闲销炎昼静，选胜火云开。
僻远宜孱性，优游赖废材。
愿为长泛梗，莫作重然灰。
守道穷非过，先时动是灾。
寄言徐孺子，宾榻旦徘徊。','',''),('quantangshi-19668','道州弘道县主簿知县三年颇着廉慎秩满县阙申使请留将赴衡州题其厅事','呂溫','quantangshi','','卷20','为理赖同力，陟明非所任。
废田方垦草，新柘未成阴。
术浅功难就，人疲感易深。
烦君驻归棹，与慰不欺心。','',''),('quantangshi-19669','道州将赴衡州酬别江华毛令','呂溫','quantangshi','','卷20','布帛精麄任土宜，疲人识信每先期。
明朝别后无他嘱，虽是蒲鞭也莫施。','',''),('quantangshi-19670','道州夏日早访荀参军林园敬酬见赠','呂溫','quantangshi','','卷20','高眠日出始开门，竹径旁通到后园。
陶亮横琴空有意，任棠置水竟无言。
松窗宿翠含风薄，槿援朝花带露繁。
山郡本来车马少，更容相访莫辞喧。','',''),('quantangshi-19671','道州敬酬何处士怀郡楼月夜之作','呂溫','quantangshi','','卷20','清质悠悠素彩融，长川迥陆合为空。
佳人甚近山城闭，夏夜相望水镜中。','',''),('quantangshi-19672','道州敬酬何处士书情见赠','呂溫','quantangshi','','卷20','意气曾倾四国豪，偶来幽寺息尘劳。
严陵钓处江初满，梁甫吟时月正高。
新识几人知杞梓，故园何岁长蓬蒿。
期君自致青云上，不用伤心叹二毛。','',''),('quantangshi-19673','戏赠灵澈上人','呂溫','quantangshi','','卷20','僧家亦有芳春兴，自是禅心无滞境。
君看池水湛然时，何曾不受花枝影。','',''),('quantangshi-19674','二月一日是贞元旧节有感绝句寄黔南窦三洛阳卢七','呂溫','quantangshi','','卷20','同事先皇立玉墀，中和旧节又支离。
今朝各自看花处，万里遥知掩泪时。','',''),('quantangshi-19675','初发道州答崔三连州题海阳亭见寄绝句','呂溫','quantangshi','','卷20','吏中习隐好跻攀，不扰疲人便自闲。
闻说殷勤海阳事，令人转忆舜祠山。','',''),('quantangshi-19676','答段秀才','呂溫','quantangshi','','卷20','尽日看花君不来，江城半夜与君开。
楼中共指南园火，红烬随花落碧苔。','',''),('quantangshi-19677','宗礼欲往桂州苦雨因以戏赠','呂溫','quantangshi','','卷20','农人辛苦绿苗齐，正爱梅天水满堤。
知汝使车行意速，但令骢马着鄣泥。','',''),('quantangshi-19678','道州奉寄襄阳裴相公','呂溫','quantangshi','','卷20','悠悠世路自浮沈，岂问仁贤待物心。
最忆过时留宴处，艳歌催酒后亭深。','',''),('quantangshi-19679','吐蕃别馆月夜','呂溫','quantangshi','','卷20','三五穷荒月，还应照北堂。
回身向暗卧，不忍见圆光。','',''),('quantangshi-19680','望思台作','呂溫','quantangshi','','卷20','浸润成宫蛊，苍黄弄父兵。
人情疑始变，天性感还生。
宇县犹能洽，闺门讵不平。
空令千载后，凄怆望思名。','',''),('quantangshi-19681','孟冬蒲津关河亭作','呂溫','quantangshi','','卷20','息驾非穷途，未济岂迷津。
独立大河上，北风来吹人。
雪霜自兹始，草木当更新。
严冬不肃杀，何以见阳春。','',''),('quantangshi-19682','巩路感怀','呂溫','quantangshi','','卷20','马嘶白日暮，劒鸣秋气来。
我心浩无际，河上空徘徊。','',''),('quantangshi-19683','题梁宣帝陵二首 一','呂溫','quantangshi','','卷20','即讐终自翦，覆国岂为雄。
假号孤城里，何殊在甬东。','',''),('quantangshi-19684','题梁宣帝陵二首 二','呂溫','quantangshi','','卷20','祀夏功何薄，尊周义不成。
凄凉庾信赋，千载共伤情。','',''),('quantangshi-19685','岳阳怀古','呂溫','quantangshi','','卷20','晨飙发荆州，落日到巴丘。
方知刳剡利，可接鬼神游。
二湖豁南寖，九派驶东流。
襟带三千里，尽在岳阳楼。
忆昔鬬羣雄，此焉争上游。
吴昌屯虎旅，晋盛骛龙舟。
宋齐纷祸难，梁陈成寇雠。
钟鼓长震耀，鱼龙不得休。
风雪一萧散，功业忽如浮。
今日时无事，空江满白鸥。','',''),('quantangshi-19686','道州途中即事','呂溫','quantangshi','','卷20','零桂佳山水，[荥]阳旧自同。
经途看不暇，遇境说难穷。
叠嶂青时合，澄湘漫处空。
舟移明镜里，路入画屏中。
岩壑千家接，松萝一径通。
渔烟生缥缈，犬吠隔笼葱。
戏鸟留余翠，幽花恡晚红。
光翻沙濑日，香散橘园风。
信美非吾土，分忧属贱躬。
守愚资地僻，恤隐望年丰。
且保心能静，那求政必工。
课终如免戾，归养洛城东。','',''),('quantangshi-19687','登少陵原望秦中诸川太原王至德妙用有水术因用感叹','呂溫','quantangshi','','卷20','少陵最高处，旷望极秋空。
君山喷清源，脉散秦川中。
荷锸自成雨，由来非鬼工。
如何盛明代，委弃伤豳风。
泾灞徒络绎，漆沮虚会同。
东流滔滔去，沃野飞秋蓬。
大禹平水土，吾人得其宗。
发机回地势，运思与天通。
早欲献奇策，丰财叙西戎。
岂知年三十，未识大明宫。
卷尔出岫云，追吾入冥鸿。
无为学惊俗，狂醉哭途穷。','',''),('quantangshi-19688','奉敕祭南岳十四韵','呂溫','quantangshi','','卷20','皇家礼赤帝，谬获司风域。
致斋紫盖下，宿设祝融侧。
鸣涧惊宵寐，清猿递时刻。
澡洁事夙兴，簪佩思尽饰。
危坛象岳趾，秘殿翘翚翼。
登拜不遑愿，酌献皆累息。
赞道仪匪繁，祝史词甚直。
忽觉心魂悸，如有精灵逼。
漠漠云气生，森森杉栢黑。
风吹虚箫韵，露洗寒玉色。
寂寞有至公，馨香在明德。
礼成谢邑吏，驾言归郡职。
憩桑访蚕事，遵畴课农力。
所愿风雨时，回首瞻南极。','',''),('quantangshi-19689','经河源军汉邨作','呂溫','quantangshi','','卷20','行行忽到旧河源，城外千家作汉村。
樵采为侵征虏墓，耕耘犹就破羌屯。
金汤天险长全设，伏腊华风亦暗存。
暂驻单车空下泪，有心无力复何言。','',''),('quantangshi-19690','题河州赤岸桥','呂溫','quantangshi','','卷20','左南桥上见河州，遗老相依赤岸头。
匝塞歌钟受恩者，谁怜被发哭东流。','',''),('quantangshi-19691','题阳人城','呂溫','quantangshi','','卷20','忠驱义感即风雷，谁道南方乏武才。
天下起兵诛董卓，长沙子弟最先来。','',''),('quantangshi-19692','晋王龙骧墓','呂溫','quantangshi','','卷20','虎旗龙舰顺长风，坐引全吴入掌中。
孙皓小儿何足取，便令千载笑争功。','',''),('quantangshi-19693','题石勒城二首 一','呂溫','quantangshi','','卷20','长驱到处积人头，大斾连营压上游。
建业乌栖何足问，慨然归去王中州。','',''),('quantangshi-19694','题石勒城二首 二','呂溫','quantangshi','','卷20','天生杰异固难驯，应变摧枯若有神。
夷甫自能疑倚啸，忍将虚诞误时人。','',''),('quantangshi-19695','刘郎浦口号','呂溫','quantangshi','','卷20','吴蜀成婚此水浔，明珠步障幄黄金。
谁将一女轻天下，欲换刘郎鼎峙心。','',''),('quantangshi-19696','自江华之衡阳途中作','呂溫','quantangshi','','卷20','孤棹迟迟怅有违，沿湘数日逗晴晖。
人生随分为忧喜，回雁峰南是北归。','',''),('quantangshi-19697','吐蕃别馆送杨七录事先归','呂溫','quantangshi','','卷20','愁云重拂地，飞雪乱遥程。
莫虑前山暗，归人正眼明。','',''),('quantangshi-19698','奉送范司空赴朔方','呂溫','quantangshi','','卷20','筑坛登上将，膝席委前筹。
虏灭南侵迹，朝分北顾忧。
抗旌回广漠，抚劒动旄头。
坐见黄云暮，行看白草秋。
山横旧秦塞，河绕古灵州。
戍守如无事，惟应猎骑游。','',''),('quantangshi-19699','送文畅上人东游','呂溫','quantangshi','','卷20','随缘聊振锡，高步出东城。
水止无恒地，云行不计程。
到时为彼岸，过处即前生。
今日临岐别，吾徒自有情。','',''),('quantangshi-19700','喜俭北至送宗礼南行','呂溫','quantangshi','','卷20','洞庭舟始泊，桂江帆又开。
魂从会处断，愁向笑中来。
惝怳看残景，殷勤祝此杯。
衡阳刷羽待，成取一行回。','',''),('quantangshi-19701','送段九秀才归沣州','呂溫','quantangshi','','卷20','湘南孤白芷，幽托在清浔。
岂有馨香发，空劳知处深。
摧贤路已隔，赈乏力不任。
慙我一言分，贞君千里心。
寸义薄联组，片诚敌兼金。
方期践冰雪，无使弱思侵。','',''),('quantangshi-19702','衡州送李十一兵曹赴浙东','呂溫','quantangshi','','卷20','慷慨视别劒，凄清泛离琴。
前程楚塞断，此恨洞庭深。
文字已久废，循良非所任。
期君碧云上，千里一扬音。','',''),('quantangshi-19703','临洮送袁七书记归朝','呂溫','quantangshi','','卷20','忆年十五在江湄，闻说平凉且半疑。
岂料殷勤洮水上，却将家信托袁师。','',''),('quantangshi-19704','江陵酒中留别坐客','呂溫','quantangshi','','卷20','寻常纵恣倚青春，不契心期便不亲。
今日烟波九疑去，相逢尽是眼中人。','',''),('quantangshi-19705','道州酬送何山人之容州','呂溫','quantangshi','','卷20','匣有青萍筒有书，何门不可曳长裾。
应须定取真知者，遣对明君说子虚。','',''),('quantangshi-19706','道州送戴简处士往贺州谒杨侍郎','呂溫','quantangshi','','卷20','羸马孤童鸟道微，三千客散独南归。
山公念旧偏知我，今日因君泪满衣。','',''),('quantangshi-19707','春日游郭驸马大安亭子','呂溫','quantangshi','','卷20','戚里容闲客，山泉若化成。
寄游芳径好，借赏彩船轻。
春至花常满，年多水更清。
此中如传舍，但自立功名。','',''),('quantangshi-19708','楚州追制后舍弟直长安县失囚花下共饮','呂溫','quantangshi','','卷20','天子收郡印，京兆责狱囚。
狂兄与狂弟，不解对花愁。','',''),('quantangshi-19709','衡州岁前游合江亭见山樱蕊未折因赋含彩恡惊春','呂溫','quantangshi','','卷20','山樱先春发，红蕊满霜枝。
幽处竟谁见，芳心空自知。
似夺朝日照，疑畏暖风吹。
欲问含彩意，恐惊轻薄儿。','',''),('quantangshi-19710','衡州登楼望南馆临水花呈房戴段李诸公','呂溫','quantangshi','','卷20','夭桃临方塘，暮色堪秋思。
托根岂求润，照影非自媚。
罥挂青柳丝，零落绿钱地。
佳期竟何许，时有幽禽至。','',''),('quantangshi-19711','合江亭槛前多高竹不见远岸花客命翦之感而成咏','呂溫','quantangshi','','卷20','吉凶岂前卜，人事何飜覆。
缘看数日花，却翦凌霜竹。
常言契君操，今乃妨众目。
自古病当门，谁言出幽独。','',''),('quantangshi-19712','道州春游欧阳家林亭','呂溫','quantangshi','','卷20','道州城北欧阳家，去郭一里占烟霞。
主人虽朴甚有思，解留满地红桃花。
桃花成泥不须扫，明朝更访桃源老。
政成兴足告即归，门前便是家山道。','',''),('quantangshi-19713','衡州早春偶游黄溪口号','呂溫','quantangshi','','卷20','偶寻皇溪日欲没，早梅未尽山樱发。
无事江城闭此身，不得坐待花间月。','',''),('quantangshi-19714','衡州夜后把火看花留客','呂溫','quantangshi','','卷20','红芳暗落碧池头，把火遥看且少留。
半夜忽然风更起，明朝不复上南楼。','',''),('quantangshi-19715','夜后把火看花南园招李十一兵曹不至呈座上诸公','呂溫','quantangshi','','卷20','夭桃红烛正相鲜，傲吏闲斋困独眠。
应是梦中飞作蝶，悠扬只在此花前。','',''),('quantangshi-19716','顺宗至德大圣大安孝皇帝挽歌词三首 一','呂溫','quantangshi','','卷20','遐视轻神宝，传归属圣猷。
尧功终有待，文德本无忧。
坐受朝汾水，行看告岱丘。
那知鼎成后，龙驭弗淹留。','',''),('quantangshi-19717','顺宗至德大圣大安孝皇帝挽歌词三首 二','呂溫','quantangshi','','卷20','监抚垂三纪，声徽洽万方。
礼因驰道着，明自垦田彰。
积渐承鸿业，从容守太康。
更留园寝诏，恭听有余芳。','',''),('quantangshi-19718','顺宗至德大圣大安孝皇帝挽歌词三首 三','呂溫','quantangshi','','卷20','早秋同轨至，晨斾露华滋。
挽度千夫咽，笳凝六马迟。
劒悲长闭日，衣望出游时。
风起西陵树，凄凉满孝思。','',''),('quantangshi-19719','咏蜀客石琹枕','呂溫','quantangshi','','卷20','可怜他山石，几度负贞坚。
推迁强为用，雕斲伤自然。
文含巴江浪，色起青城烟。
更闻余玉声，时入朱丝弦。','',''),('quantangshi-19720','河南府试赎帖赋得乡饮酒诗','呂溫','quantangshi','','卷20','酌言修旧典，刈楚始登堂。
百拜宾仪尽，三终乐奏长。
想同莺出谷，看似雁成行。
礼罢知何适，随云入帝乡。','',''),('quantangshi-19721','赋得失羣鹤','呂溫','quantangshi','','卷20','杳杳冲天鹤，风排势暂违。
有心长自负，无伴可相依。
万里宁辞远，三山讵忆归。
但令毛羽在，何处不翻飞。','',''),('quantangshi-19722','道州南楼换柱','呂溫','quantangshi','','卷20','鸿灾起无朕，有见非前知。
蚁入不足恤，柱倾何可追。
良工操斤斧，沈吟方在斯。
殚材事朽废，曷若新宏规。','',''),('quantangshi-19723','道州北池放鹅','呂溫','quantangshi','','卷20','我非好鹅癖，尔乏鸣雁姿。
安得免沸鼎，澹然游清池。
见生不忍食，深情固在斯。
能自远飞去，无念稻粱为。','',''),('quantangshi-19724','廻风有怀','呂溫','quantangshi','','卷20','银宫翠岛烟霏霏，珠树玲珑朝日晖。
神仙望见不得到，却逐回风何处归。','',''),('quantangshi-19725','蕃中答退浑词二首 一','呂溫','quantangshi','','卷20','退浑儿，退浑儿，朔风长在气何衰。
万羣铁马从奴虏，强弱由人莫叹时。','',''),('quantangshi-19726','蕃中答退浑词二首 二','呂溫','quantangshi','','卷20','退浑儿，退浑儿，冰消青海草如丝。
明堂天子朝万国，神岛龙驹将与谁。','',''),('quantangshi-19727','上官昭容书楼歌','呂溫','quantangshi','','卷20','汉家婕妤唐昭容，工诗能赋千载同。
自言才艺是天真，不服丈夫胜妇人。
歌阑舞罢闲无事，纵恣优游弄文字。
玉楼宝架中天居，缄奇秘异万卷馀。
水精编帙录钿轴，云母捣纸黄金书。
风吹花露清旭时，绮窗高挂红绡帷。
香囊盛烟绣结络，翠羽拂案青琉璃。
吟披啸卷终无已，皎皎渊机破研理。
词萦彩翰紫鸾回，思耿寥天碧云起。
碧云起，心悠哉。
境深转苦坐自摧，金梯珠履声一断。
瑶阶日夜生青苔，青苔祕空关。
曾比羣玉山，神仙杳何许。
遗逸满人间，君不见洛阳南市卖书肆。
有人买得研神记，纸上香多蠹不成。
昭容题处犹分明，令人惆怅难为情。','',''),('quantangshi-19728','闻砧有感','呂溫','quantangshi','','卷20','千门俨云端，此地富罗纨。
秋月三五夜，砧声满长安。
幽人感中怀，静听泪丸澜。
所恨捣衣者，不知天下寒。','',''),('quantangshi-19729','早觉有感','呂溫','quantangshi','','卷20','东方殊未明，暗室虫正飞。
先觉忽先起，衣裳颠倒时。
严冬寒漏长，此夜如何其。
不用思秉烛，扶桑有清晖。','',''),('quantangshi-19730','冬日病中即事','呂溫','quantangshi','','卷20','墙下长安道，嚣尘咫尺间。
久牵身外役，暂得病中闲。
背喜朝阳满，心怜暮鸟还。
吾庐在何处，南有白云山。','',''),('quantangshi-19731','病中自户部员外郎转司封','呂溫','quantangshi','','卷20','羸卧承新命，优容获所安。
遣儿迎贺客，无力拂尘冠。
偃仰晴轩暖，支离晓镜寒。
那堪报恩去，感激对衰兰。','',''),('quantangshi-19732','久病初朝衢中即事','呂溫','quantangshi','','卷20','沉疴矌十旬，还过直城闉。
老马犹知路，羸童欲怕人。
久隳三径计，更强百年身。
许国将何力，空生衣上尘。','',''),('quantangshi-19733','道州城北楼观李花','呂溫','quantangshi','','卷20','夜疑关山月，晓似沙场雪。
曾使西域来，幽情望超越。
将念浩无际，欲言忘所说。
岂是花感人，自怜抱孤节。','',''),('quantangshi-19734','道州秋夜南楼即事','呂溫','quantangshi','','卷20','谁念独坐愁，日暮此南楼。
云去舜祠闭，月明潇水流。
猿声何处晓，枫叶满山秋。
不分匣中镜，少年看白头。','',''),('quantangshi-19735','道州观野火','呂溫','quantangshi','','卷20','南风吹烈火，焰焰烧楚泽。
阳景当昼迟，阴天半夜赤。
过处若彗扫，来时如电激。
岂复辨萧兰，焉能分玉石。
虫蛇尽烁烂，虎兕出奔迫。
积秽一荡除，和气始融液。
尧时既敬授，禹稼斯肇迹。
遍生合颖禾，大秀两岐麦。
家有京坻咏，人无沟壑戚。
乃悟焚如功，来岁终受益。','',''),('quantangshi-19736','衡州早春二首 一','呂溫','quantangshi','','卷20','碧水何逶迤，东风吹沙草。
烟波千万曲，不辨嵩阳道。','',''),('quantangshi-19737','衡州早春二首 二','呂溫','quantangshi','','卷20','病肺不饮酒，伤心不看花。
惟惊望乡处，犹自隔长沙。','',''),('quantangshi-19738','郡内书怀寄刘连州窦夔州','呂溫','quantangshi','','卷20','朱邑何为者，桐乡有古祠。
我心常所慕，二郡老人知。','',''),('quantangshi-19739','偶然作二首 一','呂溫','quantangshi','','卷20','栖栖复汲汲，忽觉年四十。
今朝满衣泪，不是伤春泣。','',''),('quantangshi-19740','偶然作二首 二','呂溫','quantangshi','','卷20','中夜兀然坐，无言空涕涕。
丈夫志气事，儿女安得知。','',''),('quantangshi-19741','古兴','呂溫','quantangshi','','卷20','越欧百炼时，楚卞三泣地。
二宝无人识，千龄皆弃置。
空岩起白虹，古狱生紫气。
安得命世客，直来开奥秘。
劒任刜钟看，玉从投火试。
必能绝疑惑，然后论奇异。','',''),('quantangshi-19742','风咏','呂溫','quantangshi','','卷20','微风生青苹，习习出金塘。
轻摇深林翠，静猎幽径芳。
掩抑时未来，鸿毛亦无伤。
一朝乘严气，万里号清霜。
北走摧邓林，东去落扶桑。
扫却垂天云，澄清无私光。
悠然返空寂，晏海通舟航。','',''),('quantangshi-19743','镜中叹白发','呂溫','quantangshi','','卷20','年过潘岳才三岁，还见星星两鬓中。
纵使他时能早达，定知不作黑头公。','',''),('quantangshi-19744','友人邀听歌有感','呂溫','quantangshi','','卷20','文章抛尽爱功名，三十无成白发生。
辜负壮心羞欲死，劳君贵买断肠声。','',''),('quantangshi-19745','贞元十四年旱甚见权门移芍药花','呂溫','quantangshi','','卷20','绿原青壠渐成尘，汲井开园日日新。
四月带花移芍药，不知忧国是何人。','',''),('quantangshi-19746','冬夜即事','呂溫','quantangshi','','卷20','百忧攒心起复卧，夜长耿耿不可过。
风吹雪片似花落，月照冰文如镜破。','',''),('quantangshi-19747','道州郡斋卧疾寄东馆诸贤','呂溫','quantangshi','','卷20','东池送客醉年华，闻道风流胜习家。
独卧郡斋寥落意，隔帘微雨湿梨花。','',''),('quantangshi-19748','读小弟诗有感因口号以示之','呂溫','quantangshi','','卷20','忆吾未冠赏年华，二十年间在咄嗟。
今来羡汝看花岁，似汝追思昨日花。','',''),('quantangshi-19749','读句践传','呂溫','quantangshi','','卷20','丈夫可杀不可羞，如何送我海西头。
更生更聚终须报，二十年间死即休。','',''),('quantangshi-19750','道州月叹','呂溫','quantangshi','','卷20','别馆月，犁牛冰河金山雪。
道州月，霜树子规啼是血。
壮心感此孤劒鸣，沈火在灰殊未灭。','',''),('quantangshi-19751','风叹','呂溫','quantangshi','','卷20','青海风，飞沙射面随惊蓬。
洞庭风，危樯欲折身若空。
西驰南走有何事，会须一决百年中。','',''),('quantangshi-19752','道州感兴','呂溫','quantangshi','','卷20','当代知文字，先皇记姓名。
七年天下立，万里海西行。
苦节终难辨，劳生竟自轻。
今朝流落处，啸水遶孤城。','',''),('quantangshi-19753','和李使君三郎早秋城北亭宴崔司士因寄关中张评事','呂溫','quantangshi','','卷20','黄花古城路，上尽见青山。
桑柘晴川口，牛羊落照间。
野情随卷幔，尘事隔重关。
道合偏重赏，官微独不闲。
鹤分琴久罢，书到雁应还。
为谢登临客，琼林寄一攀。','',''),('quantangshi-19754','题从叔园林','呂溫','quantangshi','','卷20','阮宅闲园暮，窻中见树阴。
樵歌依野草，僧语过长林。
鸟向花间井，人弹竹里琴。
自嫌身未老，已有住山心。','',''),('quantangshi-19755','送僧归漳州','呂溫','quantangshi','','卷20','几夏京城住，今朝独远归。
修行四分律，护净七条衣。
溪寺黄橙熟，沙田紫芋肥。
九龙潭上路，同去客应稀。','',''),('quantangshi-19756','列女操','孟郊','quantangshi','','卷20','梧桐相待老，鸳鸯会双死。
贞女贵狥夫，舍生亦如此。
波澜誓不起，妾心井中水。','',''),('quantangshi-19757','灞上轻薄行','孟郊','quantangshi','','卷20','长安无缓步，况值天景莫。
相逢灞浐间，亲戚不相顾。
自叹方拙身，忽随轻薄伦。
常恐失所避，化为车辙尘。
此中生白发，疾走亦未歇。','',''),('quantangshi-19758','长安羁旅行','孟郊','quantangshi','','卷20','十日一理发，每梳飞旅尘。
三旬九过饮，每食唯旧贫。
万物皆及时，独余不觉春。
失名谁肯访，得意争相亲。
直木有恬翼，静流无躁鳞。
始知喧竞场，莫处君子身。
野策藤竹轻，山蔬薇蕨新。
潜歌归去来，事外风景真。','',''),('quantangshi-19759','长安道','孟郊','quantangshi','','卷20','胡风激秦树，贱子风中泣。
家家朱门开，得见不可入。
长安十二衢，投树鸟亦急。
高阁何人家，笙簧正喧吸。','',''),('quantangshi-19760','送远吟','孟郊','quantangshi','','卷20','河水昏复晨，河边相送频。
离杯有泪饮，别柳无枝春。
一笑忽然歛，万愁俄已新。
东波与西日，不惜远行人。','',''),('quantangshi-19761','古薄命妾','孟郊','quantangshi','','卷20','不惜十指弦，为君千万弹。
常恐新声至，坐使故声残。
弃置今日悲，即是昨日欢。
将新变故易，持故为新难。
青山有蘼芜，泪叶长不干。
空令后代人，采掇幽思攒。','',''),('quantangshi-19762','古离别','孟郊','quantangshi','','卷20','松山云缭绕，萍路水分离。
云去有归日，水分无合时。
春芳役双眼，春色柔四支。
杨柳织别愁，千条万条丝。','',''),('quantangshi-19763','杂怨 一','孟郊','quantangshi','','卷20','忆人莫至悲，至悲空自衰。
寄人莫剪衣，剪衣未必归。
朝为双蒂花，莫为四散飞。
花落还遶树，游子不顾期。','',''),('quantangshi-19764','杂怨 二','孟郊','quantangshi','','卷20','夭桃花清晨，游女红粉新。
夭桃花薄暮，游女红粉故。
树有百年花，人无一定颜。
花送人老尽，人悲花自闲。','',''),('quantangshi-19765','杂怨 三','孟郊','quantangshi','','卷20','贫女镜不明，寒花日少容。
暗蛩有虚织，短线无长缝。
浪水不可照，狂夫不可从。
浪水多散影，狂夫多异踪。
持此一生薄，空城万恨浓。','',''),('quantangshi-19766','静女吟','孟郊','quantangshi','','卷20','艳女皆妬色，静女独检踪。
任礼耻任妆，嫁德不嫁容。
君子易求聘，小人难自从。
此志谁与谅，琴弦幽韵重。','',''),('quantangshi-19767','归信吟','孟郊','quantangshi','','卷20','泪墨洒为书，将寄万里亲。
书去魂亦去，兀然空一身。','',''),('quantangshi-19768','山老吟','孟郊','quantangshi','','卷20','不行山下地，唯种山上田。
腰斧斫旅松，手飘汲家泉。
讵知文字力，莫记日月迁。
蟠木为我身，始得全天年。','',''),('quantangshi-19769','游子吟','孟郊','quantangshi','','卷20','慈母手中线，游子身上衣。
临行密密缝，意恐迟迟归。
谁言寸草心，报得三春晖。','',''),('quantangshi-19770','小隐吟','孟郊','quantangshi','','卷20','我饮不在醉，我欢长寂然。
酌溪四五盏，听弹两三弦。
炼性静栖白，洗情深寄玄。
号怒路傍子，贪败不贪全。','',''),('quantangshi-19771','苦寒吟','孟郊','quantangshi','','卷20','天寒色青苍，北风呌枯桑。
厚冰无裂文，短日有冷光。
敲石不得火，壮阴夺正阳。
苦调竟何言，冻吟成此章。','',''),('quantangshi-19772','猛将吟','孟郊','quantangshi','','卷20','拟脍楼兰肉，蓄怒时未扬。
秋鼙无退声，夜剑不隐光。
虎队手驱出，豹篇心卷藏。
古今皆有言，猛将出北方。','',''),('quantangshi-19773','伤哉行','孟郊','quantangshi','','卷20','众毒蔓贞松，一枝难久荣。
岂知黄庭客，仙骨生不成。
春色舍芳蕙，秋风遶枯茎。
弹琴不成曲，始觉知音倾。
馆月改旧照，吊宾写余情。
还舟空江上，波浪送铭旌。','',''),('quantangshi-19774','怨诗','孟郊','quantangshi','','卷20','试妾与君泪，两处滴池水。
看取芙蓉花，今年为谁死。','',''),('quantangshi-19775','湘弦怨','孟郊','quantangshi','','卷20','昧者理芳草，蒿兰同一锄。
狂飙怒秋林，曲直同一枯。
嘉木忌深蠹，哲人悲巧诬。
灵均入回流，靳尚为良谟。
我愿分众泉，清浊各异渠。
我愿分众巢，枭鸾相远居。
此志谅难保，此情竟何如。
湘弦少知音，孤响空踟蹰。','',''),('quantangshi-19776','楚竹吟酬卢虔端公见和湘弦怨','孟郊','quantangshi','','卷20','握中有新声，楚竹人未闻。
识音者谓谁，清夜吹赠君。
昔为潇湘引，曾动潇湘云。
一呌凤改听，再惊鹤失羣。
江花匪秋落，山日当昼曛。
众浊响杂沓，孤清思氛氲。
欲知怨有形，愿向明月分。
一掬灵均泪，千年湘水文。','',''),('quantangshi-19777','远愁曲','孟郊','quantangshi','','卷20','飘颻何所从，遗冢行未逢。
东西不见人，哭向青青松。
此地有时尽，此哀无处容。
声翻太白云，泪洗蓝田峰。
水涉七八曲，山登千万重。
愿邀玄夜月，出视白日踪。','',''),('quantangshi-19778','贫女词寄从叔先辈简','孟郊','quantangshi','','卷20','蚕女非不勤，今年独无春。
二月冰雪深，死尽万木身。
时令自逆行，造化岂不仁。
仰企碧霞仙，高控沧海云。
永别劳苦场，飘颻游无垠。','',''),('quantangshi-19779','边城吟','孟郊','quantangshi','','卷20','西城近日天，俗禀气候偏。
行子独自渴，主人仍卖泉。
烧烽碧云外，牧马青坡巅。
何处鹘突梦，归思寄仰眠。','',''),('quantangshi-19780','新平歌送许问','孟郊','quantangshi','','卷20','边柳三四尺，暮春离别歌。
早回儒士驾，莫饮土番河。
谁识匣中宝，楚云章句多。','',''),('quantangshi-19781','杀气不在边','孟郊','quantangshi','','卷20','杀气不在边，凛然中国秋。
道险不在山，平地有摧輈。
河南又起兵，清浊俱锁流。
岂唯私客艰，拥滞官行舟。
况余隔晨昏，去家成阻修。
忽然两鬓雪，同是一日愁。
独寝夜难晓，起视星汉浮。
凉风荡天地，日夕声飕飗。
万物无少色，兆人皆老忧。
长策苟未立，丈夫诚可羞。
灵响复何事，剑鸣思戮讐。','',''),('quantangshi-19782','结爱','孟郊','quantangshi','','卷20','心心复心心，结爱务在深。
一度欲离别，千回结衣襟。
结妾独守志，结君早归意。
始知结衣裳，不如结心肠。
坐结行亦结，结尽百年月。','',''),('quantangshi-19783','弦歌行','孟郊','quantangshi','','卷20','驱傩击鼓吹长笛，瘦鬼染面惟齿白。
暗中崒崒拽茅鞭，倮足朱[褌]行戚戚。
相顾笑声冲庭燎，桃弧射矢时独呌。','',''),('quantangshi-19784','覆巢行','孟郊','quantangshi','','卷20','荒城古木枝多枯，飞禽嗷嗷朝哺雏。
枝倾巢覆雏坠地，乌鸢下啄更相呼。
阳和发生均孕育，鸟兽有情知不足。
枝危巢小风雨多，未容长成已先覆。
灵枝珍木满上林，凤巢阿阁重且深。
尔今所托非本地，乌鸢何得同尔心。','',''),('quantangshi-19785','出门行 一','孟郊','quantangshi','','卷20','长河悠悠去无极，百龄同此可叹息。
秋风白露霑人衣，壮心凋落夺颜色。
少年出门将诉谁，川无梁兮路无岐。
一闻陌上苦寒奏，使我伫立惊且悲。
君今得意厌粱肉，岂复念我贫贱时。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-19786','出门行 二','孟郊','quantangshi','','卷20','海风萧萧天雨霜，穷愁独坐夜何长。
驱车旧忆太行险，始知游子悲故乡。
美人相思隔天阙，长望云端不可越。
手持琅玕欲有赠，爱而不见心断绝。
南山峩峩白石烂，碧海之波浩漫漫。
参辰出没不相待，我欲横天无羽翰。','',''),('quantangshi-19787','湘妃怨','孟郊','quantangshi','','卷20','南巡竟不返，二妃怨逾积。
万里丧蛾眉，潇湘水空碧。
冥冥荒山下，古庙收贞魄。
乔木深青春，清光满瑶席。
搴芳徒有荐，灵意殊脉脉。
玉佩不可亲，徘徊烟波夕。','',''),('quantangshi-19788','巫山曲','孟郊','quantangshi','','卷20','巴江上峡重复重，阳台碧峭十二峰。
荆王猎时逢暮雨，夜卧高丘梦神女。
轻红流烟湿艳姿，行云飞去明星稀。
目极魂断望不见，猿啼三声泪滴衣。','',''),('quantangshi-19789','巫山高','孟郊','quantangshi','','卷20','见尽数万里，不闻三声猿。
但飞萧萧雨，中有亭亭魂。
千载楚王恨，遗文宋玉言。
至今晴明天，云结深闺门。','',''),('quantangshi-19790','楚怨','孟郊','quantangshi','','卷20','秋入楚江水，独照汨罗魂。
手把绿荷泣，意愁珠泪翻。
九门不可入，一犬吠千门。','',''),('quantangshi-19791','塘下行','孟郊','quantangshi','','卷20','塘边日欲斜，年少早还家。
徒将白羽扇，调妾木兰花。
不是城头树，那栖来去鸦。','',''),('quantangshi-19792','临池曲','孟郊','quantangshi','','卷20','池中春蒲叶如带，紫菱成角莲子大。
罗裙蝉鬓倚迎风，双双伯劳飞向东。','',''),('quantangshi-19793','车遥遥','孟郊','quantangshi','','卷20','路喜到江尽，江上又通舟。
舟车两无阻，何处不得游。
丈夫四方志，女子安可留。
郎自别日言，无令生远愁。
旅雁忽呌月，断猿寒啼秋。
此夕梦君梦，君在百城楼。
寄泪无因波，寄恨无因輈。
愿为驭者手，与郎回马头。','',''),('quantangshi-19794','征妇怨 一','孟郊','quantangshi','','卷20','良人昨日去，明月又不圆。
别时各有泪，零落青楼前。
君泪濡罗巾，妾泪满路尘。
罗巾长在手，今得随妾身。
路尘如得风，得上君车轮。','',''),('quantangshi-19795','征妇怨 二','孟郊','quantangshi','','卷20','渔阳千里道，近如中门限。
中门逾有时，渔阳长在眼。
生在绿罗下，不识渔阳道。
良人自戍来，夜夜梦中到。','',''),('quantangshi-19796','空城雀','孟郊','quantangshi','','卷20','一雀入官仓，所食宁损几。
祗虑往覆频，官仓终害尔。
鱼网不在天，鸟罗不张水。
饮啄要自然，可以空城里。','',''),('quantangshi-19797','闲怨','孟郊','quantangshi','','卷20','妾恨比斑竹，下盘烦冤根。
有笋未出土，中已含泪痕。','',''),('quantangshi-19798','羽林行','孟郊','quantangshi','','卷20','朔雪寒断指，朔风劲裂冰。
胡中射雕者，此日犹不能。
翩翩羽林儿，锦臂飞苍鹰。
挥鞭快白马，走出黄河凌。','',''),('quantangshi-19799','古意','孟郊','quantangshi','','卷20','河边织女星，河畔牵牛郎。
未得渡清浅，相对遥相望。','',''),('quantangshi-19800','古别离','孟郊','quantangshi','','卷20','欲别牵郎衣，郎今到何处。
不恨归来迟，莫向临邛去。','',''),('quantangshi-19801','游侠行','孟郊','quantangshi','','卷20','壮士性刚决，火中见石裂。
杀人不回头，轻生如蹔别。
岂知眼有泪，肯白头上发。
半生无恩酬，剑闲一百月。','',''),('quantangshi-19802','黄雀吟','孟郊','quantangshi','','卷20','黄雀舞承尘，倚恃主人仁。
主人忽不仁，买弹弹尔身。
何不远飞去，蓬蒿正繁新。
蒿粒无人争，食之足为珍。
莫覰翻车粟，覰翻罪有因。
黄雀不知言，赠之徒殷勤。','',''),('quantangshi-19803','有所思','孟郊','quantangshi','','卷20','桔槔烽火昼不灭，客路迢迢信难越。
古镇刀攒万片霜，寒江浪起千堆雪。
此时西去定如何，空使南心远凄切。','',''),('quantangshi-19804','求仙曲','孟郊','quantangshi','','卷20','仙教生为门，仙宗静为根。
持心若妄求，服食安足论。
铲惑有灵药，饵真成本源。
自当出尘网，驭凤登昆仑。','',''),('quantangshi-19805','婵娟篇','孟郊','quantangshi','','卷20','花婵娟，泛春泉。
竹婵娟，笼晓烟。
妓婵娟，不长妍。
月婵娟，真可怜。
夜半姮娥朝太一，人间本自无灵匹。
汉宫承宠不多时，飞燕婕妤相妬嫉。','',''),('quantangshi-19806','南浦篇','孟郊','quantangshi','','卷20','南浦桃花亚水红，水边柳絮由春风。
鸟鸣喈喈烟蒙蒙，自从远送对悲翁。
此翁已与少年别，唯忆深山深谷中。','',''),('quantangshi-19807','清东曲','孟郊','quantangshi','','卷20','樱桃花参差，香雨红霏霏。
含笑竞攀折，美人湿罗衣。
采采清东曲，明眸艳圭玉。
青巾艑上郎，上下看不足。
南阳公首词，编入新乐录。','',''),('quantangshi-19808','望远曲','孟郊','quantangshi','','卷20','朝朝候归信，日日登高台。
行人未去植庭梅，别来三见庭花开。
庭花开尽复几时，春光骀荡阻佳期。
愁来望远烟尘隔，空怜绿鬓风吹白，何当归见远行客。','',''),('quantangshi-19809','织妇辞','孟郊','quantangshi','','卷20','夫是田中郎，妾是田中女。
当年嫁得君，为君秉机杼。
筋力日已疲，不息窻下机。
如何织纨素，自着蓝缕衣。
官家牓村路，更索栽桑树。','',''),('quantangshi-19810','古意','孟郊','quantangshi','','卷20','荡子守边戍，佳人莫相从。
去来年月多，苦愁改形容。
上山复下山，踏草成古踪。
徒言采蘼芜，十度一不逢。
鉴独是明月，识志唯寒松。
井桃始开花，一见悲万重。
人颜不再春，桃色有再浓。
捐气入空房，无憀乍从容。
启贴理针线，非独学裁缝。
手持未染彩，绣为白芙蓉。
芙蓉无染污，将以表心素。
欲寄未归人，当春无信去。
无信反增愁，愁心缘陇头。
愿君如陇水，冰镜水还流。
宛宛青丝线，纤纤白玉钩。
玉钩不亏缺，青丝无断绝。
回还胜双手，解尽心中结。','',''),('quantangshi-19811','折杨柳 一','孟郊','quantangshi','','卷20','杨柳多短枝，短枝多别离。
赠远屡攀折，柔条安得垂。
青春有定节，离别无定时。
但恐人别促，不怨来迟迟。
莫言短枝条，中有长相思。
朱颜与绿杨，并在别离期。','',''),('quantangshi-19812','折杨柳 二','孟郊','quantangshi','','卷20','楼上春风过，风前杨柳歌。
枝疎缘别苦，曲怨为年多。
花惊燕地云，叶映楚池波。
谁堪别离此，征戍在交河。','',''),('quantangshi-19813','和丁助教塞上吟','孟郊','quantangshi','','卷20','哭雪复吟雪，广文丁夫子。
江南万里寒，曾未及如此。
整顿气候谁，言从生灵始。
无令恻隐者，哀哀不能已。','',''),('quantangshi-19814','古怨别','孟郊','quantangshi','','卷20','飒飒秋风生，愁人怨离别。
含情两相向，欲语气先咽。
心曲千万端，悲来却难说。
别后唯所思，天涯共明月。','',''),('quantangshi-19815','古别曲','孟郊','quantangshi','','卷20','山川古今路，纵横无断绝。
来往天地间，人皆有离别。
行衣未束带，中肠已先结。
不用看镜中，自知生白发。
欲陈去留意，声向言前咽。
愁结填心胸，茫茫若为说。
荒郊烟莽苍，旷野风凄切。
处处得相随，人那不如月。','',''),('quantangshi-19816','戏赠陆大夫十二丈 一','孟郊','quantangshi','','卷20','莲子不可得，荷花生水中。
犹胜道傍柳，无事荡春风。','',''),('quantangshi-19817','戏赠陆大夫十二丈 二','孟郊','quantangshi','','卷20','渌萍与荷叶，同此一水中。
风吹荷叶在，渌萍西复东。','',''),('quantangshi-19818','戏赠陆大夫十二丈 三','孟郊','quantangshi','','卷20','莲叶未开时，苦心终日卷。
春水徒荡漾，荷花未开展。','',''),('quantangshi-19819','劝善吟','孟郊','quantangshi','','卷20','瘦郭有志气，相哀老龙钟。
劝我少吟诗，俗窄难尔容。
一口百味别，况在醉会中。
四座正当喧，片言何由通。
顾余昧时调，居止多疎慵。
见书眼始开，闻乐耳不聪。
视听互相隔，一身且莫同。
天疾难自医，诗癖将何攻。
见君如见书，语善千万重。
自悲咄咄感，变作烦恼翁。
烦恼不可欺，古剑澁亦雄。
知君方少年，少年怀古风。
藏书拄屋脊，不惜与凡聋。
我愿拜少年，师之学崇崇。
从他笑为矫，矫善亦可宗。','',''),('quantangshi-19820','望夫石','孟郊','quantangshi','','卷20','望夫石，夫不来兮江水碧。
行人悠悠朝与莫，千年万年色如故。','',''),('quantangshi-19821','寒江吟','孟郊','quantangshi','','卷20','冬至日光白，始知阴气凝。
寒江波浪冻，千里无平冰。
飞鸟绝高羽，行人皆晏兴。
荻洲素浩渺，崎岸澌碐磳。
烟舟忽自阻，风帆不相乘。
何况异形体，信任为股肱。
涉江莫涉凌，得意须得朋。
结交非贤良，谁免生爱憎。
冻水有再浪，失飞有载腾。
一言纵丑词，万响无善应。
取鉴谅不远，江水千万层。
何当春风吹，利涉吾道弘。','',''),('quantangshi-19822','审交','孟郊','quantangshi','','卷20','种树须择地，恶土变木根。
结交若失人，中道生谤言。
君子芳桂性，春荣冬更繁。
小人槿花心，朝在夕不存。
莫蹑冬冰坚，中有潜浪翻。
唯当金石交，可以贤达论。','',''),('quantangshi-19823','怨别','孟郊','quantangshi','','卷20','一别一回老，志士白发早。
在富易为容，居贫难自好。
沉忧损性灵，服药亦枯槁。
秋风游子衣，落日行远道。
君问去何之，贱身难自保。','',''),('quantangshi-19824','百忧','孟郊','quantangshi','','卷20','萱草女儿花，不解壮士忧。
壮士心是剑，为君射斗牛。
朝思除国讐，暮思除国讐。
计尽山河画，意穷草木筹。
智士日千虑，愚夫唯四愁。
何必在波涛，然后惊沈浮。
伯伦心不醉，四皓迹难留。
出处各有时，众议徒啾啾。','',''),('quantangshi-19825','路病','孟郊','quantangshi','','卷20','病客无主人，艰哉求卧难。
飞光赤道路，内火焦肺肝。
欲饮井泉竭，欲医囊用单。
稚颜能几日，壮志忽已残。
人子不言苦，归书但云安。
愁环在我肠，宛转终无端。','',''),('quantangshi-19826','衰松','孟郊','quantangshi','','卷20','近世交道衰，青松落颜色。
人心忌孤直，木性随改易。
既摧栖日干，未展擎天力。
终是君子材，还思君子识。','',''),('quantangshi-19827','遣兴','孟郊','quantangshi','','卷20','弦贞五条音，松直百尺心。
贞弦含古风，直松凌高岑。
浮声与狂葩，胡为欲相侵。','',''),('quantangshi-19828','退居','孟郊','quantangshi','','卷20','退身何所食，败力不能闲。
种稻耕白水，负薪斫青山。
众听喜巴唱，独醒愁楚颜。
日莫静归时，幽幽扣松关。','',''),('quantangshi-19829','卧病','孟郊','quantangshi','','卷20','贫病诚可羞，故牀无新裘。
春色烧肌肤，时餐苦咽喉。
倦寝意蒙昧，强言声幽柔。
承颜自俛仰，有泪不敢流。
默默寸心中，朝愁续莫愁。','',''),('quantangshi-19830','隐士','孟郊','quantangshi','','卷20','本末一相返，漂浮不还真。
山野多馁士，市井无饥人。
虎豹忌当道，麋鹿知藏身。
奈何贪竞者，日与患害亲。
颜貌岁岁改，利心朝朝新。
孰知富生祸，取富不取贫。
宝玉忌出璞，出璞先为尘。
松栢忌出山，出山先为薪。
君子隐石壁，道书为我隣。
寝兴思其义，澹泊味始真。
陶公自放归，尚平去有依。
草木择地生，禽鸟顺性飞。
青青与冥冥，所保各不违。','',''),('quantangshi-19831','独愁','孟郊','quantangshi','','卷20','前日远别离，昨日生白发。
欲知万里情，晓卧半牀月。
常恐百虫鸣，使我芳草歇。','',''),('quantangshi-19832','春日有感','孟郊','quantangshi','','卷20','雨滴草芽出，一日长一日。
风吹柳线垂，一枝连一枝。
独有愁人颜，经春如等闲。
且持酒满杯，狂歌狂笑来。','',''),('quantangshi-19833','将见故人','孟郊','quantangshi','','卷20','故人季夏中，及此百余日。
无日不相思，明镜改形色。
宁知仲冬时，忽有相逢期。
振衣起踯躅，頳鲤跃天池。','',''),('quantangshi-19834','伤时','孟郊','quantangshi','','卷20','常闻贫贱士之常，嗟尔富者莫相笑。
男儿得路即荣名，邂逅失途成不调。
古人结交而重义，今人结交而重利。
劝人一种种桃李，种亦直须遍天地。
一生不爱嘱人事，嘱即直须为生死。
我亦不羡季伦富，我亦不笑原宪贫。
有财有势即相识，无财无势同路人。
因知世事皆如此，却向东溪卧白云。','',''),('quantangshi-19835','寓言','孟郊','quantangshi','','卷20','谁言碧山曲，不废青松直。
谁言浊水泥，不污明月色。
我有松月心，俗骋风霜力。
贞明既如此，摧折安可得。','',''),('quantangshi-19836','偶作','孟郊','quantangshi','','卷20','利剑不可近，美人不可亲。
利剑近伤手，美人近伤身。
道险不在广，十步能摧轮。
情爱不在多，一夕能伤神。','',''),('quantangshi-19837','劝学','孟郊','quantangshi','','卷20','击石乃有火，不击元无烟。
人学始知道，不学非自然。
万事须己运，他得非我贤。
青春须早为，岂能长少年。','',''),('quantangshi-19838','赠农人','孟郊','quantangshi','','卷20','劝尔勤耕田，盈尔仓中粟。
劝尔伐桑株，减尔身上服。
清霜一委地，万草色不绿。
狂飙一入林，万叶不着木。
青春如不耕，何以自结束。','',''),('quantangshi-19839','长安早春','孟郊','quantangshi','','卷20','旭日朱楼光，东风不惊尘。
公子醉未起，美人争探春。
探春不为桑，探春不为麦。
日日出西园，秖望花柳色。
乃知田家春，不入五侯宅。','',''),('quantangshi-19840','罪松','孟郊','quantangshi','','卷20','虽为青松姿，霜风何所宜。
二月天下树，绿于青松枝。
勿谓贤者喻，勿谓愚者规。
伊吕代封爵，夷齐终身饥。
彼曲既在斯，我正实在兹。
泾流合渭流，清浊各自持。
天令设四时，荣衰有常期。
荣合随时荣，衰合随时衰。
天令既不从，甚不敬天时。
松乃不臣木，青青独何为。','',''),('quantangshi-19841','感兴','孟郊','quantangshi','','卷20','拔心草不死，去根柳亦荣。
独有失意人，恍然无力行。
昔为连理枝，今为断弦声。
连理时所重，断弦今所轻。
吾欲进孤舟，三峡水不平。
吾欲载车马，太行路峥嵘。
万物根一气，如何互相倾。','',''),('quantangshi-19842','感怀 一','孟郊','quantangshi','','卷20','秋气悲万物，惊风振长道。
登高有所思，寒雨伤百草。
平生有亲爱，零落不相保。
五情今已伤，安得自能老。','',''),('quantangshi-19843','感怀 二','孟郊','quantangshi','','卷20','晨登洛阳坂，目极天茫茫。
羣物归大化，六龙颓西荒。
豺狼日已多，草木日已霜。
饥年无遗粟，众鸟去空场。
路傍谁家子，白首离故乡。
含酸望松栢，仰面诉穹苍。
去去勿复道，苦饥形貌伤。','',''),('quantangshi-19844','感怀 三','孟郊','quantangshi','','卷20','徘徊不能寐，耿耿含酸辛。
中夜登高楼，忆我旧星辰。
四时互迁移，万物何时春。
唯忆首阳路，永谢当时人。','',''),('quantangshi-19845','感怀 四','孟郊','quantangshi','','卷20','长安佳丽地，宫月生蛾眉。
阴气凝万里，坐看芳草衰。
玉堂有玄鸟，亦以从此辞。
伤哉志士叹，故国多迟迟。
深宫岂无乐，扰扰复何为。
朝见名与利，莫还生是非。
姜牙佐周武，世业永巍巍。','',''),('quantangshi-19846','感怀 五','孟郊','quantangshi','','卷20','举才天道亲，首阳谁采薇。
去去荒泽远，落日当西归。
羲和驻其轮，四海借余晖。
极目何萧索，惊风正离披。
鸱鸮鸣高树，众鸟相因依。
东方有一士，岁莫常苦饥。
主人数相问，脉脉今何为。
贫贱亦有乐，且愿掩柴扉。','',''),('quantangshi-19847','感怀 六','孟郊','quantangshi','','卷20','火云流素月，三五何明明。
光曜侵白日，贤愚迷至精。
四时更变化，天道有亏盈。
常恐今已没，须臾还复生。','',''),('quantangshi-19848','感怀 七','孟郊','quantangshi','','卷20','河梁莫相遇，草草不复言。
汉家正离乱，王粲别荆蛮。
野泽何萧条，悲风振空山。
举头是星辰，念我何时还。
亲爱久别散，形神各离迁。
未为生死诀，长在心目间。','',''),('quantangshi-19849','感怀 八','孟郊','quantangshi','','卷20','有鸟东西来，哀鸣过我前。
愿飞浮云外，饮啄见青天。','',''),('quantangshi-19850','达士','孟郊','quantangshi','','卷20','四时如逝水，百川皆东波。
青春去不还，白发镊更多。
达人识元化，变愁为高歌。
倾产取一醉，富者奈贫何。
君看土中宅，富贵无偏颇。','',''),('quantangshi-19851','暮秋感思 一','孟郊','quantangshi','','卷20','西风吹垂杨，条条脆如藕。
上有噪日蝉，催人成皓首。
亦恐旅步难，何独朱颜丑。
欲慰一时心，莫如千日酒。','',''),('quantangshi-19852','暮秋感思 二','孟郊','quantangshi','','卷20','优哉遵渚鸿，自得养身旨。
不[啄]太仓粟，不饮方塘水。
振羽戛浮云，罝罗任徒尔。','',''),('quantangshi-19853','古兴','孟郊','quantangshi','','卷20','楚血未干衣，荆虹尚埋辉。
痛玉不痛身，抱璞求所归。','',''),('quantangshi-19854','劝友','孟郊','quantangshi','','卷20','至白涅不缁，至交淡不疑。
人生静躁殊，莫厌相箴规。
胶漆武可接，金兰文可思。
堪嗟无心人，不如松栢枝。','',''),('quantangshi-19855','夷门雪赠主人','孟郊','quantangshi','','卷20','夷门贫士空吟雪，夷门豪士皆饮酒。
酒声欢闲入雪销，雪声激切悲枯朽。
悲欢不同归去来，万里春风动江柳。','',''),('quantangshi-19856','尧歌 一','孟郊','quantangshi','','卷20','尔室何不安，尔孝无与齐。
一言应对姑，一度为出妻。
往辙才晚钟，还辙及晨鸡。
往还迹徒新，很戾竟独迷。
娥女无礼数，污家如粪泥。
父母吞声哭，禽鸟亦为啼。
如何天与恶，不得和鸣栖。','',''),('quantangshi-19857','尧歌 二','孟郊','quantangshi','','卷20','山色挽心肝，将归尽日看。
村肩篮轝子，野坐白发官。
莺弄方短短，花明碎攒攒。
瑠璃堆可掬，琴瑟饶多欢。
翠韵仙窈窕，岚漪出无端。
养馆洞庭秋，响答虚吹弹。','',''),('quantangshi-19858','乱离','孟郊','quantangshi','','卷20','天下无义剑，中原多疮痍。
哀哀陆大夫，正直神反欺。
子路已成血，嵇康今尚嗤。
为君每一恸，如剑在四肢。
折羽不复飞，逝水不复归。
直松摧高柯，弱蔓将何依。
朝为春日欢，夕为秋日悲。
泪下无尺寸，纷纷天雨丝。
积怨成疾疹，积恨成狂痴。
怨草岂有边，恨水岂有涯。
怨恨驰我心，茫茫日何之。','',''),('quantangshi-19859','劝酒','孟郊','quantangshi','','卷20','白日无定影，清江无定波。
人无百年寿，百年复如何。
堂上陈美酒，堂下列清歌。
劝君今曲巵，勿谓朱颜酡。
松栢岁岁茂，丘陵日日多。
君看终南山，千古青峨峨。','',''),('quantangshi-19860','去妇','孟郊','quantangshi','','卷20','君心匣中镜，一破不复全。
妾心藕中丝，虽断犹牵连。
安知御轮士，今日翻回辕。
一女事一夫，安可再移天。
君听去鹤言，哀哀七丝弦。','',''),('quantangshi-19861','君子勿郁郁士有谤毁者作诗以赠之 一','孟郊','quantangshi','','卷20','君子勿郁郁，听我青蝇歌。
人间少平地，森耸山岳多。
折輈不在道，覆舟不在河。
须知一尺水，日夜增高波。
叔孙毁仲尼，臧仓掩孟轲。
兰艾不同香，自然难为和。
良玉烧不热，直竹文不颇。
自古皆如此，其如道在何。','',''),('quantangshi-19862','君子勿郁郁士有谤毁者作诗以赠之 二','孟郊','quantangshi','','卷20','日往复不见，秋堂莫仍学。
玄发不知白，晓入寒铜觉。
为林未离树，有玉犹在璞。
谁把碧梧枝，刻作云门乐。','',''),('quantangshi-19863','闻砧','孟郊','quantangshi','','卷20','杜鹃声不哀，断猿啼不切。
月下谁家砧，一声肠一绝。
杵声不为客，客闻发自白。
杵声不为衣，欲令游子归。','',''),('quantangshi-19864','游子','孟郊','quantangshi','','卷20','萱草生堂堦，游子行天涯。
慈亲倚堂门，不见萱草花。','',''),('quantangshi-19865','自叹','孟郊','quantangshi','','卷20','愁与发相形，一愁白数茎。
有发能几多，禁愁日日生。
古若不置兵，天下无战争。
古若不置名，道路无欹倾。
太行耸巍峩，是天产不平。
黄河奔浊浪，是天生不清。
四蹄日日多，双轮日日成。
二物不在天，安能免营营。','',''),('quantangshi-19866','求友','孟郊','quantangshi','','卷20','北风临大海，坚冰临河面。
下有大波澜，对之无由见。
求友须在良，得良终相善。
求友若非良，非良中道变。
欲知求友心，先把黄金炼。','',''),('quantangshi-19867','投所知','孟郊','quantangshi','','卷20','苦心知苦节，不容一毛发。
炼金索坚贞，洗玉求明洁。
自慙所业微，功用如鸠拙。
何殊嫫母颜，对彼寒塘月。
君存古人心，道出古人辙。
尽美固可扬，片善亦不遏。
朝向公卿说，暮向公卿说。
谁谓黄钟管，化为君子舌。
一说清嶰竹，二说变嶰谷。
三说四说时，寒花拆寒木。
𣊪𣊪家道路，灿灿我衣服。
岂直辉友朋，亦用慰骨肉。
一暖荷匹素，一饱荷升粟。
而况大恩恩，此身报得足。
且将食檗劳，酬之作金刀。','',''),('quantangshi-19868','病客吟','孟郊','quantangshi','','卷20','主人夜呻吟，皆入妻子心。
客子昼呻吟，徒为虫鸟音。
妻子手中病，愁思不复深。
童仆手中病，忧危独难任。
丈夫久飘泊，神气自然沈。
况于滞疾中，何人免嘘𠾬。
大海亦有涯，高山亦有岑。
沈忧独无极，尘泪互盈襟。','',''),('quantangshi-19869','感怀','孟郊','quantangshi','','卷20','孟冬阴气交，两河正屯兵。
烟尘相驰突，烽火日夜惊。
太行险阻高，挽粟输连营。
奈何操弧者，不使枭巢倾。
犹闻汉北儿，怙乱谋纵横。
擅摇干戈柄，呼呌豺狼声。
白日临尔躯，胡为丧丹诚。
岂无感激士，以致天下平。
登高望寒原，黄云郁峥嵘。
坐驰悲风莫，叹息空沾缨。','',''),('quantangshi-19870','离思','孟郊','quantangshi','','卷20','不寐亦不语，片月秋稍举。
孤鸿忆霜羣，独鹤叫云侣。
怨彼浮花心，飘飘无定所。
高张系繂帆，远过梅根渚。
回织别离字，机声有酸楚。','',''),('quantangshi-19871','结交','孟郊','quantangshi','','卷20','铸镜须青铜，青铜易磨拭。
结交远小人，小人难姑息。
铸镜图鉴微，结交图相依。
凡铜不可照，小人多是非。','',''),('quantangshi-19872','伤春','孟郊','quantangshi','','卷20','两河春草海水清，十年征战城郭腥。
乱兵杀儿将女去，二月三月花冥冥。
千里无人旋风起，莺啼燕语荒城里。
春色不拣墓傍株，红颜皓色逐春去。
春去春来那得知，今人看花古人墓，令人惆怅山头路。','',''),('quantangshi-19873','择友','孟郊','quantangshi','','卷20','兽中有人性，形异遭人隔。
人中有兽心，几人能真识。
古人形似兽，皆有大圣德。
今人表似人，兽心安可测。
虽笑未必和，虽哭未必戚。
面结口头交，肚里生荆棘。
好人常直道，不顺世间逆。
恶人巧谄多，非义苟且得。
若是效真人，坚心如铁石。
不谄亦不欺，不奢复不溺。
面无恡色容，心无诈忧惕。
君子大道人，朝夕恒的的。','',''),('quantangshi-19874','夜忧','孟郊','quantangshi','','卷20','岂独科斗死，所嗟文字捐。
蒿蔓转骄弄，菱荇减婵娟。
未遂摆鳞志，空思吹浪旋。
何当再霖雨，洗濯生华鲜。','',''),('quantangshi-19875','惜苦','孟郊','quantangshi','','卷20','于鹄值谏议，以球不能官。
焦蒙值舍人，以杯不得完。
可惜大雅旨，意此小团栾。
名回不敢辨，心转实是难。
不惜为君转，转非君子观。
转之复转之，强转谁能欢。
哀哉虚转言，不可穷波澜。','',''),('quantangshi-19876','寒地百姓吟','孟郊','quantangshi','','卷20','无火炙地眠，半夜皆立号。
冷箭何处来，棘针风骚劳。
霜吹破四壁，苦痛不可逃。
高堂捶钟饮，到晓闻烹炮。
寒者愿为蛾，烧死彼华膏。
华膏隔仙罗，虚遶千万遭。
到头落地死，踏地为游遨。
游遨者是谁，君子为郁陶。','',''),('quantangshi-19877','出东门','孟郊','quantangshi','','卷20','饿马骨亦耸，独驱出东门。
少年一日程，衰叟十日奔。
寒景不我为，疾走落平原。
眇默荒草行，恐惧夜魄翻。
一生自组织，千首大雅言。
道路如抽蚕，宛转羁肠繁。','',''),('quantangshi-19878','教坊歌儿','孟郊','quantangshi','','卷20','十岁小小儿，能歌得朝天。
六十孤老人，能诗独临川。
去年西京寺，众伶集讲筵。
能嘶竹枝词，供养绳牀禅。
能诗不如歌，怅望三百篇。','',''),('quantangshi-19879','访疾','孟郊','quantangshi','','卷20','冷气入疮痛，夜来痛如何。
疮从公怒生，岂以私恨多。
公怒亦非道，怒消乃天和。
古有焕辉句，嵇康闲婆娑。
请君吟啸之，正气庶不讹。','',''),('quantangshi-19880','酒德','孟郊','quantangshi','','卷20','酒是古明镜，辗开小人心。
醉见异举止，醉闻异声音。
酒功如此多，酒屈亦以深。
罪人免罪酒，如此可为箴。','',''),('quantangshi-19881','冬日','孟郊','quantangshi','','卷20','老人行人事，百一不及周。
冻马四蹄吃，陟卓难自收。
短景仄飞过，午光不上头。
少壮日与辉，衰老日与愁。
日愁疑在日，岁箭迸如讐。
万事有何味，一生虚自囚。
不知文字利，到死空遨游。','',''),('quantangshi-19882','饥雪吟','孟郊','quantangshi','','卷20','饥乌夜相啄，疮声互悲鸣。
冰肠一直刀，天杀无曲情。
大雪压梧桐，折柴堕峥嵘。
安知鸾凤巢，不与枭鸢倾。
下有幸灾儿，拾遗多新争。
但求彼失所，但夸此经营。
君子亦拾遗，拾遗非拾名。
将补鸾凤巢，免与枭鸢并。
因为饥雪吟，至晓竟不平。','',''),('quantangshi-19883','偷诗','孟郊','quantangshi','','卷20','饿犬齚枯骨，自吃馋饥涎。
今文与古文，各各称可怜。
亦如婴儿食，饧桃口旋旋。
唯有一点味，岂见逃景延。
绳床独坐翁，默览有所传。
终当罢文字，别着逍遥篇。
从来文字净，君子不以贤。','',''),('quantangshi-19884','晚雪吟','孟郊','quantangshi','','卷20','贫富喜雪晴，出门意皆饶。
镜海见纤悉，冰天步飘颻。
一一仙子行，家家尘声销。
小儿击玉指，大耋歌圣朝。
睿气流不尽，瑞仙何敻寥。
始知望幸色，终疑异礼招。
市井亦清洁，闾阎耸岧嶤。
苍生愿东顾，翠华仍西遥。
天念岂薄厚，宸衷多忧焦。
忧焦致太平，以兹时比尧。
古耳有未通，新词有潜韶。
甘为酒伶摈，坐耻歌女娇。
选音不易言，裁正逢今朝。
今朝前古文，律异同一调。
愿于尧琯中，奏尽郁抑谣。','',''),('quantangshi-19885','自惜','孟郊','quantangshi','','卷20','倾尽眼中力，抄诗过与人。
自悲风雅老，恐被巴竹嗔。
零落雪文字，分明镜精神。
坐甘冰抱晚，永谢酒怀春。
徒有言言旧，慙无默默新。
始惊儒教误，渐与佛乘亲。','',''),('quantangshi-19886','老恨','孟郊','quantangshi','','卷20','无子抄文字，老吟多飘零。
有时吐向床，枕席不解听。
鬬蚁甚微细，病闻亦清泠。
小大不自识，自然天性灵。','',''),('quantangshi-19887','湖州取解述情','孟郊','quantangshi','','卷20','霅水徒清深，照影不照心。
白鹤未轻举，众鸟争浮沉。
因兹挂帆去，遂作归山吟。','',''),('quantangshi-19888','落第','孟郊','quantangshi','','卷20','晓月难为光，愁人难为肠。
谁言春物荣，独见叶上霜。
雕鹗失势病，鹪鹩假翼翔。
弃置复弃置，情如刀劒伤。','',''),('quantangshi-19889','咏怀','孟郊','quantangshi','','卷20','浊水心易倾，明波兴初发。
思逢海底人，乞取蚌中月。
此兴若未谐，此心终不歇。','',''),('quantangshi-19890','病起言怀','孟郊','quantangshi','','卷20','强行寻溪水，洗却残病姿。
花景晼晚尽，麦风清泠吹。
交道贱来见，世情贫去知。
高闲思楚逸，澹泊厌齐儿。
终伴碧山侣，结言青桂枝。','',''),('quantangshi-19891','秋夕贫居述怀','孟郊','quantangshi','','卷20','卧冷无远梦，听秋酸别情。
高枝低枝风，千叶万叶声。
浅井不供饮，瘦田长废耕。
今交非古交，贫语闻皆轻。','',''),('quantangshi-19892','夜感自遣','孟郊','quantangshi','','卷20','夜学晓未休，苦吟神鬼愁。
如何不自闲，心与身为讐。
死辱片时痛，生辱长年羞。
清桂无直枝，碧江思旧游。','',''),('quantangshi-19893','再下第','孟郊','quantangshi','','卷20','一夕九起嗟，梦短不到家。
两度长安陌，空将泪见花。','',''),('quantangshi-19894','下第东归留别长安知己','孟郊','quantangshi','','卷20','共照日月影，独为愁思人。
岂知鶗鴂鸣，瑶草不得春。
一片两片云，千里万里身。
云归嵩之阳，身寄江之滨。
弃置复何道，楚情吟白苹。','',''),('quantangshi-19895','失意归吴因寄东台刘复侍御','孟郊','quantangshi','','卷20','自念西上身，忽随东归风。
长安日下影，又落江湖中。
离娄岂不明，子野岂不聪。
至宝非眼别，至音非耳通。
因缄俗外词，仰寄高天鸿。','',''),('quantangshi-19896','下第东南行','孟郊','quantangshi','','卷20','越风东南清，楚日潇湘明。
试逐伯鸾去，还作灵均行。
江蓠伴我泣，海月投人惊。
失意容貌改，畏途性命轻。
时闻丧侣猿，一叫千愁并。','',''),('quantangshi-19897','叹命','孟郊','quantangshi','','卷20','三十年来命，唯藏一卦中。
题诗还问易，问易蒙复蒙。
本望文字达，今因文字穷。
影孤别离月，衣破道路风。
归去不自息，耕耘成楚农。','',''),('quantangshi-19898','远游','孟郊','quantangshi','','卷20','慈乌不远飞，孝子念先归。
而我独何事，四时心有违。
江海恋空积，波涛信来稀。
长为路傍食，着尽家中衣。
别劒不割物，离人难作威。
远行少僮仆，驱使无是非。
为性玩好尽，积愁心绪微。
始知时节驶，夏日非长辉。','',''),('quantangshi-19899','商州客舍','孟郊','quantangshi','','卷20','商山风雪壮，游子衣裳单。
四望失道路，百忧攒肺肝。
日短觉易老，夜长知至寒。
泪流潇湘弦，调苦屈宋弹。
识声今所易，识意古所难。
声意今讵辨，高明鉴其端。','',''),('quantangshi-19900','长安旅情','孟郊','quantangshi','','卷20','尽说青云路，有足皆可至。
我马亦四蹄，出门似无地。
玉京十二楼，峩峩倚青翠。
下有千朱门，何门荐孤士。','',''),('quantangshi-19901','长安羇旅','孟郊','quantangshi','','卷20','听乐别离中，声声入幽肠。
晓泪滴楚瑟，夜魄遶吴乡。
几回羇旅情，梦觉残烛光。','',''),('quantangshi-19902','渭上思归','孟郊','quantangshi','','卷20','独访千里信，回临千里河。
家在吴楚乡，泪寄东南波。','',''),('quantangshi-19903','登科后','孟郊','quantangshi','','卷20','昔日龌龊不足夸，今朝放荡思无涯。
春风得意马蹄疾，一日看尽长安花。','',''),('quantangshi-19904','初于洛中选','孟郊','quantangshi','','卷20','尘土日易没，驱驰力无余。
青云不我与，白首方选书。
宦途事非远，拙者取自疎。
终然恋皇邑，誓以结吾庐。
帝城富高门，京路遶胜居。
碧水走龙蛇，蜿蜒遶庭除。
寻常异方客，过此亦踟蹰。','',''),('quantangshi-19905','乙酉岁舍弟扶侍归兴义庄居后独止舍待替人','孟郊','quantangshi','','卷20','谁言旧居止，主人忽成客。
僮仆强与言，相惧终脉脉。
出亦何所求，入亦何所索。
饮食迷精麤，衣裳失宽窄。
回风卷闲簟，新月生空壁。
士有百役身，官无一姓宅。
丈夫耻自餙，衰须从飒白。
兰交早已谢，榆景徒相迫。
惟予心中镜，不语光历历。','',''),('quantangshi-19906','西斋养病夜怀多感因呈上从叔子云','孟郊','quantangshi','','卷20','远客夜衣薄，厌眠待鸡鸣。
一床空月色，四壁秋蛩声。
守淡遗众俗，养疴念余生。
方全君子拙，耻学小人明。
蚊蚋亦有时，羽毛各有成。
如何骐骥迹，蜷局未能行。
西北有平路，运来无相轻。','',''),('quantangshi-19907','秋怀 一','孟郊','quantangshi','','卷20','孤骨夜难卧，吟虫相唧唧。
老泣无涕涕，秋露为滴沥。
去壮暂如翦，来衰纷似织。
触绪无新心，丛悲有余忆。
讵忍逐南帆，江山践往昔。','',''),('quantangshi-19908','秋怀 二','孟郊','quantangshi','','卷20','秋月颜色冰，老客志气单。
冷露滴梦破，峭风梳骨寒。
席上印病文，肠中转愁盘。
疑怀无所凭，虚听多无端。
梧桐枯峥嵘，声响如哀弹。','',''),('quantangshi-19909','秋怀 三','孟郊','quantangshi','','卷20','一尺月透户，仡栗如劒飞。
老骨坐亦惊，病力所尚微。
虫苦贪剪色，鸟危巢焚辉。
孀娥理故丝，孤哭抽余思。
浮年不可追，衰步多夕归。','',''),('quantangshi-19910','秋怀 四','孟郊','quantangshi','','卷20','秋至老更贫，破屋无门扉。
一片月落床，四壁风入衣。
疎梦不复远，弱心良易归。
商葩将去绿，缭绕争余辉。
野步踏事少，病谋向物违。
幽幽草根虫，生意与我微。','',''),('quantangshi-19911','秋怀 五','孟郊','quantangshi','','卷20','竹风相戛语，幽闺暗中闻。
鬼神满衰听，恍惚难自分。
商叶堕干雨，秋衣卧单云。
病骨可剸物，酸呻亦成文。
瘦攒如此枯，壮落随西曛。
褭褭一线命，徒言系絪緼。','',''),('quantangshi-19912','秋怀 六','孟郊','quantangshi','','卷20','老骨惧秋月，秋月刀劒棱。
纤辉不可干，冷魂坐自凝。
羇雌巢空镜，仙飙荡浮冰。
惊步恐自翻，病大不敢凌。
单床寤皎皎，瘦卧心兢兢。
洗河不见水，透浊为清澄。
诗壮昔空说，诗衰今何凭。','',''),('quantangshi-19913','秋怀 七','孟郊','quantangshi','','卷20','老病多异虑，朝夕非一心。
商虫哭衰运，繁响不可寻。
秋草瘦如发，贞芳缀疎金。
晚鲜讵几时，驰景还易阴。
弱习徒自耻，莫知欲何任。
露才一见谗，潜智早已深。
防深不防露，此意古所箴。','',''),('quantangshi-19914','秋怀 八','孟郊','quantangshi','','卷20','岁莫景气干，秋风兵甲声。
织织劳无衣，喓喓徒自鸣。
商声耸中夜，蹇支废前行。
青发如秋园，一翦不复生。
少年如饿花，瞥见不复明。
君子山岳定，小人丝毫争。
多争多无寿，天道戒其盈。','',''),('quantangshi-19915','秋怀 九','孟郊','quantangshi','','卷20','冷露多瘁索，枯风晓吹嘘。
秋深月清苦，虫老声麤疎。
頳珠枝累累，芳金蔓舒舒。
草木亦趣时，寒荣似春余。
悲彼零落生，与我心何如。','',''),('quantangshi-19916','秋怀 十','孟郊','quantangshi','','卷20','老人朝夕异，生死每日中。
坐随一啜安，卧与万景空。
视短不到门，听涩讵逐风。
还如刻削形，免有纤悉聪。
浪浪谢初始，皎皎幸归终。
孤隔文章友，亲密蒿莱翁。
岁绿闵以黄，秋节迸又穷。
四时既相迫，万虑自然丛。
南逸浩淼际，北贫硗确中。
曩怀沈遥江，衰思结秋嵩。
锄食难满腹，叶衣多丑躬。
尘缕不自整，古吟将谁通。
幽竹啸鬼神，楚铁生虬龙。
志士多异感，运郁由邪衷。
常思书破衣，至死教初童。
习乐莫习声，习声多顽聋。
明明胸中言，愿写为高崇。','',''),('quantangshi-19917','秋怀 十一','孟郊','quantangshi','','卷20','幽苦日日甚，老力步步微。
常恐暂下牀，至门不复归。
饥者重一食，寒者重一衣。
泛广岂无涘，恣行亦有随。
语中失次第，身外生疮痍。
桂蠹既潜朽，桂花损贞姿。
詈言一失香，千古闻臭词。
将死始前悔，前悔不可追。
哀哉轻薄行，终日与驷驰。','',''),('quantangshi-19918','秋怀 十二','孟郊','quantangshi','','卷20','流运闪欲尽，枯折皆相号。
棘枝风哭酸，桐叶霜颜高。
老虫干铁鸣，惊兽孤玉咆。
商气洗声瘦，晚阴驱景劳。
集耳不可遏，噎神不可逃。
蹇行散余郁，幽坐谁与曹。
抽壮无一线，剪怀盈千刀。
清诗既名朓，金菊亦姓陶。
收拾昔所弃，咨嗟今比毛。
幽幽岁晏言，零落不可操。','',''),('quantangshi-19919','秋怀 十三','孟郊','quantangshi','','卷20','霜气入病骨，老人身生冰。
衰毛暗相刺，冷痛不可胜。
鷕鷕伸至明，强强揽所凭。
瘦坐形欲折，腹饥心将崩。
劝药左右愚，言语如见憎。
耸耳噎神开，始知功用能。
日中视余疮，暗隙闻绳蝇。
彼齅一何酷，此味半点凝。
潜毒尔无厌，余生我堪矜。
冻飞幸不远，冬令反心惩。
出没各有时，寒热苦相凌。
仰谢调运翁，请命愿有征。','',''),('quantangshi-19920','秋怀 十四','孟郊','quantangshi','','卷20','黄河倒上天，众水有却来。
人心不及水，一直去不回。
一直亦有巧，不肯至蓬莱。
一直不知疲，唯闻至省台。
忍古不失古，失古志易摧。
失古劒亦折，失古琴亦哀。
夫子失古泪，当时落漼漼。
诗老失古心，至今寒皑皑。
古骨无浊肉，古衣如藓苔。
劝君勉忍古，忍古销尘埃。','',''),('quantangshi-19921','秋怀 十五','孟郊','quantangshi','','卷20','詈言不见血，杀人何纷纷。
声如穷家犬，吠窦何誾誾。
詈痛幽鬼哭，詈侵黄金贫。
言词岂用多，憔悴在一闻。
古詈舌不死，至今书云云。
今人咏古书，善恶宜自分。
秦火不爇舌，秦火空爇文。
所以詈更生，至今横絪緼。','',''),('quantangshi-19922','靖安寄居','孟郊','quantangshi','','卷20','寄静不寄华，爱兹嵽嵲居。
渴饮浊清泉，饥食无名蔬。
败菜不敢火，补衣亦写书。
古云俭成德，今乃实起予。
戆叟戆不足，贤人贤有余。
役生皆促促，心竟谁舒舒。
万马踏风衢，众尘随犇车。
高宾尽不见，大道夜方虚。
卧有洞庭梦，坐无长安储。
英髦空骇耳，烟火独微如。
厚念恐伤性，薄田忆亲锄。
承世不出力，冬竹肯抽葅。
外物莫相诱，约心誓从初。
碧芳既似水，日日咏归欤。','',''),('quantangshi-19923','雪','孟郊','quantangshi','','卷20','忽然太行雪，昨夜飞入来。
崚嶒堕庭中，严白何皑皑。
奴婢晓开户，四肢冻徘徊。
咽言词不成，告诉情状摧。
官给未入门，家人尽以灰。
意劝莫笑雪，笑雪贫为灾。
将暖此残疾，典卖争致杯。
教令再举手，夸曜余生才。
强起吐巧词，委曲多新裁。
为尔作非夫，忍耻轰暍雷。
书之与君子，庶免生嫌猜。','',''),('quantangshi-19924','春怨','孟郊','quantangshi','','卷20','春物与愁客，遇时各有违。
故花辞新枝，新泪落故衣。
日莫两寂寞，飘然亦同归。','',''),('quantangshi-19925','懊恼','孟郊','quantangshi','','卷20','恶诗皆得官，好诗空抱山。
抱山冷殑殑，终日悲颜颜。
好诗更相嫉，劒戟生牙关。
前贤死已久，犹在咀嚼间。
以我残杪身，清峭养高闲。
求闲未得闲，众诮瞋虤虤。','',''),('quantangshi-19926','游城南韩氏庄','孟郊','quantangshi','','卷20','初疑潇湘水，锁在朱门中。
时见水底月，动摇池上风。
清气润竹林，白光连虚空。
浪簇霄汉羽，岸芳金碧丛。
何言数亩间，环泛路不穷。
愿逐神仙侣，飘然汗漫通。','',''),('quantangshi-19927','与二三友秋宵会话清上人院 一','孟郊','quantangshi','','卷20','何处山不幽，此中情又别。
一僧敲一磬，七子吟秋月。
激石泉韵清，寄枝风啸咽。
泠然诸境静，顿觉浮累灭。
扣寂兼探真，通宵讵能辍。','',''),('quantangshi-19928','与二三友秋宵会话清上人院 二','孟郊','quantangshi','','卷20','好鸟无杂栖，华堂有嘉携。
琴樽互倾奏，歌赋相和谐。
但嘉鱼水合，莫令云雨乖。
一为鵾鸡弹，再鼓壮士怀。
初景待谁晓，新春逐君来。
愿言良友会，高驾不知回。','',''),('quantangshi-19929','招文士饮','孟郊','quantangshi','','卷20','曹刘不免死，谁敢负年华。
文士莫辞酒，诗人命属花。
退之如放逐，李白自矜夸。
万古忽将似，一朝同叹嗟。
何言天道正，独使地形斜。
南士愁多病，北人悲去家。
梅芳已流管，柳色未藏鸦。
相劝罢吟雪，相从愁饮霞。
醒时不可过，愁海浩无涯。','',''),('quantangshi-19930','陪侍御叔游城南山墅','孟郊','quantangshi','','卷20','夜坐拥肿亭，昼登崔巍岑。
日窥万峰首，月见双泉心。
松气清耳目，竹氛碧衣襟。
伫想琅玕字，数听枯槁吟。','',''),('quantangshi-19931','登华岩寺楼望终南山赠林校书兄弟','孟郊','quantangshi','','卷20','地脊亚为崖，耸出冥冥中。
楼根插迥云，殿翼翔危空。
前山胎元气，灵异生不穷。
势吞万象高，秀夺五岳雄。
一望俗虑醒，再登仙愿崇。
青莲三居士，昼景真赏同。','',''),('quantangshi-19932','游终南山','孟郊','quantangshi','','卷20','南山塞天地，日月石上生。
高峰夜留景，深谷昼未明。
山中人自正，路险心亦平。
长风驱松柏，声拂万壑清。
到此悔读书，朝朝近浮名。','',''),('quantangshi-19933','游终南龙池寺','孟郊','quantangshi','','卷20','飞鸟不到处，僧房终南巅。
龙在水长碧，雨开山更鲜。
步出白日上，坐依清溪边。
地寒松桂短，石险道路偏。
晚磬送归客，数声落遥天。','',''),('quantangshi-19934','南阳公请东樱桃亭子春宴','孟郊','quantangshi','','卷20','万木皆未秀，一林先含春。
此地独何力，我公布深仁。
霜叶日舒卷，风枝远埃尘。
初英濯紫霞，飞雨流清津。
赏异出嚣杂，折芳积懽忻。
文心兹焉重，俗尚安能珍。
碧玉妆粉比，飞琼穠艳均。
鸳鸯七十二，花态并相新。
常恐遗秀志，迨兹广宴陈。
芳菲争胜引，歌咏竟良辰。
方知戏马会，永谢登龙宾。','',''),('quantangshi-19935','游华山云台观','孟郊','quantangshi','','卷20','华岳独灵异，草木恒新鲜。
山尽五色石，水无一色泉。
仙酒不醉人，仙芝皆延年。
夜闻明星馆，时韵女萝弦。
敬兹不能寐，焚栢吟道篇。','',''),('quantangshi-19936','喜与长文上人宿李秀才小山池亭','孟郊','quantangshi','','卷20','灯尽语不尽，主人庭砌幽。
柳枝星影曙，兰叶露华浮。
块岭笑羣岫，片池轻众流。
更闻清净子，逸唱颇难俦。','',''),('quantangshi-19937','邀花伴','孟郊','quantangshi','','卷20','边地春不足，十里见一花。
及时须邀游，日莫饶风沙。','',''),('quantangshi-19938','石淙 一','孟郊','quantangshi','','卷20','岩谷不自胜，水木幽奇多。
朔风入空曲，泾流无大波。
迢递径难尽，参差势相罗。
雪霜有时洗，尘土无由和。
洁冷诚未厌，晚步将如何。','',''),('quantangshi-19939','石淙 二','孟郊','quantangshi','','卷20','出曲水未断，入山深更重。
泠泠若仙语，皎皎多异容。
万响不相杂，四时皆有浓。
日月互分照，云霞各生峰。
久迷向方理，逮兹耸前踪。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-19940','石淙 三','孟郊','quantangshi','','卷20','荒策每恣远，戆步难自回。
已抱苔藓疾，尚凌潺湲隈。
驿骥苦衔勒，笼禽恨摧颓。
实力苟未足，浮夸信悠哉。
顾惟非时用，静言还自咍。','',''),('quantangshi-19941','石淙 四','孟郊','quantangshi','','卷20','朔水刀劒利，秋石琼瑶鲜。
鱼龙气不腥，潭洞状更妍。
磴雪入呀谷，掬星洒遥天。
声忙不及韵，势疾多断涟。
输去虽有恨，躁气一何颠。
蜿蜒相缠掣，荦确亦回旋。
黑草濯铁发，白苔浮冰钱。
具生此云遥，非德不可甄。
何况被犀士，制之空以权。
始知静刚猛，文教从来先。','',''),('quantangshi-19942','石淙 五','孟郊','quantangshi','','卷20','空谷耸视听，幽湍泽心灵。
疾流脱鳞甲，叠岸冲风霆。
丹巘堕环景，霁波灼虚形。
淙淙豗厚轴，棱棱攒高冥。
弱栈跨旋碧，危梯倚凝青。
飘飘鹤骨仙，飞动鳌背庭。
常闻夸大言，下顾皆细萍。','',''),('quantangshi-19943','石淙 六','孟郊','quantangshi','','卷20','百尺明镜流，千曲寒星飞。
为君洗故物，有色如新衣。
不饮泥土污，但饮雪霜饥。
石棱玉纤纤，草色琼霏霏。
谷硙有余力，溪舂亦多机。
从来一智萌，能使众利归。
因之山水中，喧然论是非。','',''),('quantangshi-19944','石淙 七','孟郊','quantangshi','','卷20','入深得奇趣，升险为良跻。
搜胜有闻见，逃俗无踪蹊。
穴流恣回转，窍景忘东西。
戆兽鲜猜惧，罗人巧罝罤。
幽驰异处所，忍虑多端倪。
虚护我何饱，实归彼非迷。
斯文浪云洁，此旨谁得齐。','',''),('quantangshi-19945','石淙 八','孟郊','quantangshi','','卷20','屑珠泻潺湲，裂玉何威瓌。
若调千瑟弦，未果一曲谐。
古骇毛发栗，险惊视听乖。
二老皆劲骨，风趋缘欹崖。
地远有余美，我游采弃怀。
乘时幸勤鉴，前恨多幽霾。
弱力谢刚健，蹇策贵安排。
始知随事静，何必当夕斋。','',''),('quantangshi-19946','石淙 九','孟郊','quantangshi','','卷20','昔浮南渡飙，今攀朔山景。
物色多瘦削，吟笑还孤永。
日月冻有棱，雪霜空无影。
玉喷不生冰，瑶涡旋成井。
潜角时耸光，隐鳞乍漂冏。
再吟获新胜，返步失前省。
惬怀虽已多，惕虑未能整。
颓阳落何处，升魄衔疎岭。','',''),('quantangshi-19947','石淙 十','孟郊','quantangshi','','卷20','圣朝搜岩谷，此地多遗玩。
怠惰成远游，顽疎恣灵观。
劲飙刷幽视，怒水慑余愞。
曾是结芳诚，远兹勉流倦。
冰条耸危虑，霜翠莹遐眄。
物诱信多端，荒寻谅难遍。
去矣朔之隅，翛然楚之甸。','',''),('quantangshi-19948','游韦七洞庭别业','孟郊','quantangshi','','卷20','洞庭如潇湘，叠翠荡浮碧。
松桂无赤日，风物饶清激。
逍遥展幽韵，参差逗良觌。
道胜不知疲，冥搜自无斁。
旷然青霞抱，永矣白雪适。
崆峒非凡乡，蓬瀛在仙籍。
无言从远尚，还思君子识。
波涛漱古岸，铿锵辨奇石。
灵响非外求，殊音自中积。
人皆走烦浊，君能致虚寂。
何以祛扰扰，叩调清淅淅。
既惧豪华损，誓从诗书益。
一举独往姿，再摇飞遁迹。
山深有变异，意惬无惊惕。
采翠夺日月，照耀迷昼夕。
松斋何用扫，萝院自然涤。
业峻谢烦芜，文高追古昔。
暂遥朱门恋，终立青史绩。
物表易淹留，人间重离析。
难随洞庭酌，且醉横塘席。','',''),('quantangshi-19949','越中山水','孟郊','quantangshi','','卷20','日觉耳目胜，我来山水州。
蓬瀛若仿髴，田野如泛浮。
碧嶂几千遶，清泉万余流。
莫穷合沓步，孰尽派别游。
越水净难污，越天阴易收。
气鲜无隐物，目视远更周。
举俗媚葱蒨，连冬撷芳柔。
菱湖有余翠，茗圃无荒畴。
赏异忽已远，探奇诚淹留。
永言终南色，去矣销人忧。','',''),('quantangshi-19950','春集越州皇甫秀才山亭','孟郊','quantangshi','','卷20','嘉宾在何处，置亭春山巅。
顾余寂寞者，谬厕芳菲筵。
视听日澄澈，声光坐连绵。
晴湖泻峰嶂，翠浪多萍藓。
何以逞高志，为君吟秋天。','',''),('quantangshi-19951','和皇甫判官游琅琊溪','孟郊','quantangshi','','卷20','山中琉璃境，物外琅琊溪。
房廊逐岩壑，道路随高低。
碧濑漱白石，翠烟含青霓。
客来暂游践，意欲忘簪圭。
树杪灯火夕，云端钟梵齐。
时同虽可仰，迹异难相携。
唯当清宵梦，仿髴愿攀跻。','',''),('quantangshi-19952','汝州南潭陪陆中丞公宴','孟郊','quantangshi','','卷20','一雨百泉涨，南潭夜来深。
分明碧沙底，写出青天心。
远客洞庭至，因兹涤烦襟。
既登飞云舫，愿奏清风琴。
高岸立旗戟，潜蛟失浮沈。
威棱护斯浸，魍魉逃所侵。
山态变初霁，水声流新音。
耳目极眺听，潺湲与嵚岑。
谁言柳太守，空有白苹吟。','',''),('quantangshi-19953','汝州陆中丞席喜张从事至同赋十韵','孟郊','quantangshi','','卷20','汝水无浊波，汝山饶奇石。
大贤为此郡，佳士来如积。
有客乘白驹，奉义惬所适。
清风荡华馆，雅瑟泛瑶席。
芳醑静无喧，金尊光有涤。
纵情孰虑损，听论自招益。
愿折若木枝，却彼曜灵夕。
贵贱一相接，忧悰忽转易。
会合勿言轻，别离古来惜。
请君驻征车，良遇难再觌。','',''),('quantangshi-19954','夜集汝州郡斋听陆僧辩弹琴','孟郊','quantangshi','','卷20','康乐宠词客，清宵意无穷。
征文北山外，借月南楼中。
千里愁并尽，一樽欢暂同。
胡为戛楚琴，淅沥起寒风。','',''),('quantangshi-19955','同年春燕','孟郊','quantangshi','','卷20','少年三十士，嘉会良在兹。
高歌摇春风，醉舞摧花枝。
意荡晼晚景，喜凝芳菲时。
马迹攒騕褭，乐声韵参差。
视听改旧趣，物象含新姿。
红雨花上滴，绿烟柳际垂。
淹中讲精义，南皮献清词。
前贤与今人，千载为一期。
明鉴有皎洁，澄玉无磷缁。
永与沙泥别，各整云汉仪。
盛气自中积，英名日四驰。
塞鸿绝俦匹，海月难等夷。
郁抑忽已尽，亲朋乐无涯。
幽蘅发空曲，芳杜绵所思。
浮迹自聚散，壮心谁别离。
愿保金石志，无令有夺移。','',''),('quantangshi-19956','罗氏花下奉招陈侍御','孟郊','quantangshi','','卷20','眼在枝上春，落地成埃尘。
不是风流者，谁为攀折人。
宁辞波浪阔，莫道往来频。
拾紫岂宜晚，掇芳须及晨。
劳收贾生泪，强起屈平身。
花下本无俗，酒中别有神。
游蜂不饮故，戏蝶亦争新。
万物尽如此，过时非所珍。','',''),('quantangshi-19957','游石龙涡','孟郊','quantangshi','','卷20','石龙不见形，石雨如散星。
山下晴皎皎，山中阴泠泠。
水飞林木杪，珠缀莓苔屏。
畜异物皆别，当晨景欲暝。
泉芳春气碧，松月寒色青。
险力此独壮，猛兽亦不停。
日暮且回去，浮心恨未宁。','',''),('quantangshi-19958','浮石亭','孟郊','quantangshi','','卷20','曾是风雨力，崔巍漂来时。
落星夜皎洁，近榜朝逶迤。
翠潋递明灭，清潨泻欹危。
况逢蓬岛仙，会合良在兹。','',''),('quantangshi-19959','看花 一','孟郊','quantangshi','','卷20','家家有芍药，不妨至温柔。
温柔一同女，红笑笑不休。
月娥双双下，楚艳枝枝浮。
洞里逢仙人，绰约青宵游。','',''),('quantangshi-19960','看花 二','孟郊','quantangshi','','卷20','芍药谁为壻，人人不敢来。
唯应待诗老，日日殷勤开。
玉立无气力，春凝且裴徊。
将何谢青春，痛饮一百杯。','',''),('quantangshi-19961','看花 三','孟郊','quantangshi','','卷20','芍药吹欲尽，无奈晓风何。
余花欲谁待，唯待谏郎过。
谏郎不事俗，黄金买高歌。
高歌夜更清，花意晚更多。','',''),('quantangshi-19962','看花 四','孟郊','quantangshi','','卷20','饮之不见底，醉倒深红波。
红波荡谏心，谏心终无它。
独游终难醉，挈榼徒经过。
问花不解语，劝得酒无多。','',''),('quantangshi-19963','看花 五','孟郊','quantangshi','','卷20','三年此村落，春色入心悲。
料得一孀妇，经时独泪垂。','',''),('quantangshi-19964','济源春','孟郊','quantangshi','','卷20','太行横偃脊，百里芳崔巍。
济滨花异颜，枋口云如裁。
新画彩色湿，上界光影来。
深红缕草木，浅碧珩溯洄。
千家门前饮，一道传禊杯。
玉鳞吞金钩，仙璇瑠璃开。
朴童茂言语，善俗无惊猜。
狂吹寝恒宴，晓清梦先回。
治生鲜惰夫，积学多深材。
再游讵癫戆，一洗惊尘埃。','',''),('quantangshi-19965','济源寒食 一','孟郊','quantangshi','','卷20','风巢袅袅春鵶鵶，无子老人仰面嗟。
柳弓苇箭覰不见，高红远绿劳相遮。','',''),('quantangshi-19966','济源寒食 二','孟郊','quantangshi','','卷20','女婵童子黄短短，耳中闻人惜春晚。
逃蜂匿蝶踏地来，抛却斋糜一瓷椀。','',''),('quantangshi-19967','济源寒食 三','孟郊','quantangshi','','卷20','一日踏春一百回，朝朝没脚走芳埃。
饥童饿马埽花喂，向晚饮溪三两杯。','',''),('quantangshi-19968','济源寒食 四','孟郊','quantangshi','','卷20','莓苔井上空相忆，辘轳索断无消息。
酒人皆倚春发绿，病叟独藏秋发白。','',''),('quantangshi-19969','济源寒食 五','孟郊','quantangshi','','卷20','长安落花飞上天，南风引至三殿前。
可怜春物亦朝谒，唯我孤吟渭水边。','',''),('quantangshi-19970','济源寒食 六','孟郊','quantangshi','','卷20','枋口花间掣手归，嵩阳为我留红晖。
可怜踯躅千万尺，柱地柱天疑欲飞。','',''),('quantangshi-19971','济源寒食 七','孟郊','quantangshi','','卷20','蜜蜂为主各磨牙，咬尽村中万木花。
君家瓮瓮今应满，五色冬笼甚可夸。','',''),('quantangshi-19972','游枋口 一','孟郊','quantangshi','','卷20','一步复一步，出行千里幽。
为取山水意，故作寂寞游。
太行青巅高，枋口碧照浮。
明明无底镜，泛泛忘机鸥。
老逸不自限，病狂不可周。
恣闲饶淡薄，怠玩多淹留。
芳物竞晼晚，绿梢挂新柔。
和友莺相遶，言语亦以稠。
始知万类然，静躁难相求。','',''),('quantangshi-19973','游枋口 二','孟郊','quantangshi','','卷20','耸我残病骨，健如一仙人。
镜中照千里，镜浪洞百神。
此神日月华，不作寻常春。
三十夜皆明，四时昼恒新。
鸟声尽依依，兽心亦忻忻。
澄幽出所怪，闪异坐微絪。
可来复可来，此地灵相亲。','',''),('quantangshi-19974','与王二十一员外涯游枋口柳溪','孟郊','quantangshi','','卷20','万株古柳根，挐此磷磷溪。
野榜多屈曲，仙浔无端倪。
春桃散红烟，寒竹含晚凄。
晓听忽以异，芳树安能齐。
共疑落镜中，坐泛红景低。
水意酒易醒，浪情事非迷。
小儒峭章句，大贤嘉提携。
潜窦韵灵瑟，翠崖鸣玉圭。
主人稷卨翁，德茂芝术畦。
凿出幽隐端，气象皆升跻。
曾是清乐抱，逮兹几省溪。
宴位席兰草，滥觞惊凫鹥。
灵味荐鲂瓣，金花屑橙韲。
江调摆衰俗，洛风远尘泥。
徒言奏狂狷，讵敢忘筌蹄。','',''),('quantangshi-19975','与王二十一员外涯游昭成寺','孟郊','quantangshi','','卷20','洛友寂寂约，省骑霏霏尘。
游僧步晚磬，话茗含芳春。
瑶策冰入手，粉壁画莹神。
頳廊芙蓉霁，碧殿瑠璃匀。
玄讲岛岳尽，渊咏文字新。
屡笑寒竹宴，况接青云宾。
顾慙余眷下，衰瘵婴残身。','',''),('quantangshi-19976','嵩少','孟郊','quantangshi','','卷20','沙弥舞袈裟，走向踯躅飞。
闲步亦惺惺，芳援相依依。
噎塞春咽喉，蜂蝶事光辉。
羣嬉且已晚，孤引将何归。
流艳去不息，朝英亦疎微。','',''),('quantangshi-19977','旅次洛城东水亭','孟郊','quantangshi','','卷20','水竹色相洗，碧花动轩楹。
自然逍遥风，荡涤浮竞情。
霜落叶声燥，景寒人语清。
我来招隐亭，衣上尘暂轻。','',''),('quantangshi-19978','洛桥晚望','孟郊','quantangshi','','卷20','天津桥下冰初结，洛阳陌上人行绝。
榆柳萧疎楼阁闲，月明直见嵩山雪。','',''),('quantangshi-19979','北郭贫居','孟郊','quantangshi','','卷20','进乏广莫力，退为蒙笼居。
三年失意归，四向相识疎。
地僻草木壮，荒条扶我庐。
夜贫灯烛绝，明月照吾书。
欲识贞静操，秋蝉饮清虚。','',''),('quantangshi-19980','题陆鸿渐上饶新开山舍','孟郊','quantangshi','','卷20','惊彼武陵状，移归此岩边。
开亭拟贮云，凿石先得泉。
啸竹引清吹，吟花成新篇。
乃知高洁情，摆落区中缘。','',''),('quantangshi-19981','题韦承总吴王故城下幽居','孟郊','quantangshi','','卷20','才饱身自贵，巷荒门岂贫。
韦生堪继相，孟子愿依邻。
夜思琴语切，昼情茶味新。
霜枝留过鹊，风竹扫蒙尘。
郢唱一声发，吴花千片春。
对君何所得，归去觉情真。','',''),('quantangshi-19982','苏州昆山惠聚寺僧房','孟郊','quantangshi','','卷20','昨日到上方，片云挂石牀。
锡杖莓苔青，袈裟松栢香。
晴磬无短韵，古灯含永光。
有时乞鹤归，还访逍遥场。','',''),('quantangshi-19983','题从叔述灵岩山壁','孟郊','quantangshi','','卷20','换却世上心，独起山中情。
露衣凉且鲜，云策高复轻。
喜见夏日来，变为松景清。
每将逍遥听，不厌飕飗声。
远念尘末宗，未疎俗间名。
桂枝妄举手，萍路空劳生。
仰谢开净弦，相招时一鸣。','',''),('quantangshi-19984','题林校书花严寺书窗','孟郊','quantangshi','','卷20','隐咏不夸俗，问禅徒净居。
翻将白云字，寄向青莲书。
拟古投松坐，就明开纸疏。
昭昭南山景，独与心相如。','',''),('quantangshi-19985','蓝溪元居士草堂','孟郊','quantangshi','','卷20','市井不容义，义归山谷中。
夫君宅松桂，招我栖蒙笼。
人朴情虑肃，境闲视听空。
清溪宛转水，修竹徘徊风。
木倦采樵子，土劳稼穑翁。
读书业虽异，敦本志亦同。
蓝岸青漠漠，蓝峰碧崇崇。
日昏各命酒，寒蛩鸣蕙丛。','',''),('quantangshi-19986','新卜清罗幽居恭奉献陆大夫','孟郊','quantangshi','','卷20','黔娄住何处，仁邑无馁寒。
岂悟旧羇旅，变为新闲安。
二顷有余食，三农行可观。
笼禽得高巢，辙鲋还层澜。
翳翳桑柘墟，纷纷田里欢。
兵戈忽消散，耦耕非艰难。
嘉木偶良酌，芳阴庇清弹。
力农唯一事，趣世徒万端。
静觉本相厚，动为末所残。
此外有余暇，锄荒出幽兰。','',''),('quantangshi-19987','题韦少保静恭宅藏书洞','孟郊','quantangshi','','卷20','高意合天制，自然状无穷。
仙华凝四时，玉藓生数峰。
书祕漆文字，匣藏金蛟龙。
闲为气候肃，开作云雨浓。
洞隐谅非久，岩梦诚必通。
将缀文士集，贯就真珠丛。','',''),('quantangshi-19988','生生亭','孟郊','quantangshi','','卷20','滩闹不妨语，跨溪仍置亭。
置亭嵽嵲头，开窗纳遥青。
遥青新画出，三十六扇屏。
褭褭立平地，棱棱浮高冥。
一日数开扉，仙闪目不停。
徒夸远方岫，曷若中峰灵。
拔意千余丈，浩言永堪铭。
浩言无愧同，愧同忍丑醒。
致之未有力，力在君子听。','',''),('quantangshi-19989','寒溪 一','孟郊','quantangshi','','卷20','霜洗水色尽，寒溪见纤鳞。
幸临虚空镜，照此残悴身。
潜滑不自隐，露底莹更新。
豁如君子怀，曾是危陷人。
始明浅俗心，夜结朝已津。
净漱一掬碧，远消千虑尘。
始知泥步泉，莫与山源隣。','',''),('quantangshi-19990','寒溪 二','孟郊','quantangshi','','卷20','洛阳岸边道，孟氏庄前溪。
舟行素冰折，声作青瑶嘶。
绿水结绿玉，白波生白圭。
明明宝镜中，物物天照齐。
仄步下危曲，攀枯闻孀啼。
霜芬稍消歇，凝景微茫齐。
痴坐直视听，戆行失踪蹊。
岸童斸棘劳，语言多悲凄。','',''),('quantangshi-19991','寒溪 三','孟郊','quantangshi','','卷20','晓饮一杯酒，踏雪过清溪。
波澜冻为刀，剸割凫与鹥。
宿羽皆翦弃，血声沉沙泥。
独立欲何语，默念心酸嘶。
冻血莫作春，作春生不齐。
冻血莫作花，作花发孀啼。
幽幽棘针村，冻死难耕犂。','',''),('quantangshi-19992','寒溪 四','孟郊','quantangshi','','卷20','篙工磓玉星，一路随迸萤。
朔冻哀彻底，獠馋咏潜鯹。
冰齿相磨啮，风音酸铎铃。
清悲不可逃，洗出纤悉听。
碧潋卷已尽，彩缕飞飘零。
下蹑滑不定，上栖折难停。
哮嘐呷喢冤，仰诉何时宁。','',''),('quantangshi-19993','寒溪 五','孟郊','quantangshi','','卷20','一曲一直水，白龙何鳞鳞。
冻飙杂碎号，韲音坑谷辛。
柧椾吃无力，飞走更相仁。
猛弓一折弦，余喘争来宾。
大严此之立，小杀不复陈。
皎皎何皎皎，氤氲复氤氲。
瑞晴刷日月，高碧开星辰。
独立两脚雪，孤吟千虑新。
天欃徒昭昭，箕舌虚齗齗。
尧圣不听汝，孔微亦有臣。
谏书竟成章，古义终难陈。','',''),('quantangshi-19994','寒溪 六','孟郊','quantangshi','','卷20','因冻死得食，杀风仍不休。
以兵为仁义，仁义生刀头。
刀头仁义腥，君子不可求。
波澜抽劒冰，相劈如仇讐。
尖雪入鱼心，鱼心明愀愀。
怳如罔两说，似诉割切由。
谁使异方气，入此中土流。
翦尽一月春，闭为百谷幽。
仰怀新霁光，下照疑忧愁。','',''),('quantangshi-19995','寒溪 七','孟郊','quantangshi','','卷20','溪老哭甚寒，涕泗冰珊珊。
飞死走死形，雪裂纷心肝。
劒刃冻不割，弓弦彊难弹。
常闻君子武，不食天杀残。
斸玉掩骼胔，吊琼哀阑干。','',''),('quantangshi-19996','寒溪 八','孟郊','quantangshi','','卷20','溪风摆余冻，溪景衔明春。
玉消花滴滴，虬解光鳞鳞。
悬步下清曲，消期濯芳津。
千里冰裂处，一勺暖亦仁。
凝精互相洗，漪涟竞将新。
忽如劒疮尽，初起百战身。','',''),('quantangshi-19997','立德新居 一','孟郊','quantangshi','','卷20','立德何亭亭，西南耸高隅。
阳崖泄春意，井圃留冬芜。
胜引即纡道，幽行岂通衢。
碧峰远相揖，清思谁言孤。
寺秩虽贵家，浊醪良可哺。','',''),('quantangshi-19998','立德新居 二','孟郊','quantangshi','','卷20','耸城架霄汉，洁宅涵絪緼。
开门洛北岸，时锁嵩阳云。
夜高星辰大，昼长天地分。
厚韵属疎语，薄名谢嚣闻。
兹焉有殊隔，永矣难及羣。','',''),('quantangshi-19999','立德新居 三','孟郊','quantangshi','','卷20','宾秩已觉厚，私储常恐多。
清贫聊自尔，素责将如何。
俭教先勉力，修襟无余佗。
良栖一枝木，灵巢片叶荷。
仰笑鵾鹏辈，委身拂天波。','',''),('quantangshi-20000','立德新居 四','孟郊','quantangshi','','卷20','疎门不掩水，洛色寒更高。
晓碧流视听，夕清濯衣袍。
为于仁义得，未觉登陟劳。
远岸雪难莫，劲枝风易号。
霜禽各啸侣，吾亦爱吾曹。','',''),('quantangshi-20001','立德新居 五','孟郊','quantangshi','','卷20','崎岖有悬步，委曲饶荒寻。
远树足良木，疎巢无争禽。
素魄衔夕岸，绿水生晓浔。
空旷伊洛视，仿髴潇湘心。
何必尚远异，忧劳满行襟。','',''),('quantangshi-20002','立德新居 六','孟郊','quantangshi','','卷20','悬途多仄足，崎圃无修畦。
芳兰与宿艾，手撷心不迷。
品子懒读书，辕驹难服犂。
虚食日相投，夸肠讵能低。
耻从新学游，愿将古农齐。','',''),('quantangshi-20003','立德新居 七','孟郊','quantangshi','','卷20','都城多耸秀，爱此高县居。
伊雒遶街巷，鸳鸯飞阎闾。
翠景何的砾，霜飔飘空虚。
突出万家表，独治二亩蔬。
一旬一手版，十日九手锄。','',''),('quantangshi-20004','立德新居 八','孟郊','quantangshi','','卷20','手锄手自勖，激劝亦已饶。
畏彼棃栗儿，空资玩弄骄。
夜景卧难尽，昼光坐易消。
治旧得新义，耕荒生嘉苗。
锄治苟惬适，心形俱逍遥。','',''),('quantangshi-20005','立德新居 九','孟郊','quantangshi','','卷20','玉蹄裂鸣水，金绶忽照门。
拂拭贫士席，拜候丞相辕。
德疎未为高，礼至方觉尊。
岂唯耀兹日，可以荣远孙。
如何一阳朝，独荷众瑞繁。','',''),('quantangshi-20006','立德新居 十','孟郊','quantangshi','','卷20','东南富水木，寂寥蔽光辉。
此地足文字，及时隘骖騑。
仄雪踏为平，涩行变如飞。
令畦生气色，嘉绿新霏微。
天意资厚养，贤人肯相违。','',''),('quantangshi-20007','西上经灵宝观','孟郊','quantangshi','','卷20','道士无白发，语音灵泉清。
青松多寿色，白石恒夜明。
放步霁霞起，振衣华风生。
真文祕中顶，宝气浮四楹。
一片古关路，万里今人行。
上仙不可见，驱策徒西征。','',''),('quantangshi-20008','泛黄河','孟郊','quantangshi','','卷20','谁开昆仑源，流出混沌河。
积雨飞作风，惊龙喷为波。
湘瑟飕飗弦，越宾呜咽歌。
有恨不可洗，虚此来经过。','',''),('quantangshi-20009','往河阳宿峡陵寄李侍御','孟郊','quantangshi','','卷20','莫天寒风悲屑屑，啼鸟遶树泉水噎。
行路解鞍投古陵，苍苍隔山见微月。
鸮鸣犬吠霜烟昏，开囊拂巾对盘飧。
人生穷达感知己，明日投君申片言。','',''),('quantangshi-20010','鵶路溪行呈陆中丞','孟郊','quantangshi','','卷20','鵶路不可越，三十六渡溪。
有物饮碧水，高林挂青霓。
历览道更险，驱使迹频暌。
视听易常主，心魂互相迷。
浪石忽摇动，沙堤信难跻。
危峰紫霄外，古木浮云齐。
出阻望汝郡，大贤多招携。
疲马恋旧秣，羁禽思故栖。
应怜泣楚玉，弃置如尘泥。','',''),('quantangshi-20011','独宿岘首忆长安故人','孟郊','quantangshi','','卷20','月迥无隐物，况复大江秋。
江城与沙村，人语风飕飗。
岘亭当此时，故人不同游。
故人在长安，亦可将梦求。','',''),('quantangshi-20012','自商行谒复州卢使君虔','孟郊','quantangshi','','卷21','一身遶千山，远作行路人。
未遂东吴归，暂出西京尘。
仲宣荆州客，今余竟陵宾。
往迹虽不同，托意皆有因。
商岭莓苔滑，石坂上下频。
江汉沙泥洁，永日光景新。
独泪起残夜，孤吟望初晨。
驱驰竟何事，章句依深仁。','',''),('quantangshi-20013','梦泽中行','孟郊','quantangshi','','卷21','楚山争蔽亏，日月无全辉。
楚路饶回惑，旅人有迷归。
骐骥思北首，鹧鸪愿南飞。
我怀京洛游，未厌风尘衣。','',''),('quantangshi-20014','京山行','孟郊','quantangshi','','卷21','众䖟聚病马，流血不得行。
后路起夜色，前山闻虎声。
此时游子心，百尺风中旌。','',''),('quantangshi-20015','旅次湘沅有怀灵均','孟郊','quantangshi','','卷21','分拙多感激，久游遵长途。
经过湘水源，怀古方踟蹰。
旧称楚灵均，此处殒忠躯。
侧聆故老言，遂得旌贤愚。
名参君子场，行为小人儒。
骚文炫贞亮，体物情崎岖。
三黜有愠色，即非贤哲模。
五十爵高秩，谬膺从大夫。
胸襟积忧愁，容鬓复雕枯。
死为不吊鬼，生作猜谤徒。
吟泽洁其身，忠节宁见输。
怀沙灭其性，孝行焉能俱。
且闻善称君，一何善自殊。
且闻过称己，一何过不渝。
悠哉风土人，角黍投川隅。
相传历千祀，哀悼延八区。
如今圣明朝，养育无羁孤。
君臣逸雍熙，德化盈纷敷。
巾车徇前侣，白日犹昆吾。
寄君臣子心，戒此真良图。','',''),('quantangshi-20016','过彭泽','孟郊','quantangshi','','卷21','扬帆过彭泽，舟人讶叹息。
不见种柳人，霜风空寂历。','',''),('quantangshi-20017','过分水岭','孟郊','quantangshi','','卷21','山壮马力短，马行石齿中。
十步九举辔，回环失西东。
溪水变为雨，悬崖阴蒙蒙。
客衣飘颻秋，葛花零落风。
白日舍我没，征途忽然穷。','',''),('quantangshi-20018','分水岭别夜示从弟寂','孟郊','quantangshi','','卷21','南中少平地，山水重叠生。
别泉万余曲，迷舟独难行。
四际乱峰合，一眺千虑并。
潺湲冬夏冷，光彩昼夜明。
赏心难久胜，离肠忽自惊。
古木摇霁色，高风动秋声。
饮尔一樽酒，慰我百忧轻。
嘉期何处定，此晨堪寄情。','',''),('quantangshi-20019','连州吟 一','孟郊','quantangshi','','卷21','春风朝夕起，吹绿日日深。
试为连州吟，泪下不可禁。
连山何连连，连天碧岑岑。
哀猿哭花死，子规裂客心。
兰芷结新佩，潇湘遗旧音。
怨声能翦弦，坐抚零落琴。','',''),('quantangshi-20020','连州吟 二','孟郊','quantangshi','','卷21','羽翼不自有，相追力难任。
唯凭方寸灵，独夜万里寻。
方寻魂飘颻，南梦山岖嵚。
仿髴惊魍魉，悉窣闻枫林。
正直被放者，鬼魅无所侵。
贤人多安排，俗士多虚钦。
孤怀吐明月，众毁铄黄金。
愿君保玄曜，壮志无自沉。','',''),('quantangshi-20021','连州吟 三','孟郊','quantangshi','','卷21','朝亦连州吟，暮亦连州吟。
连州果有信，一纸万里心。
开缄白云断，明月堕衣襟。
南风嘶舜琯，苦竹动猿音。
万里愁一色，潇湘雨淫淫。
两劒忽相触，双蛟恣浮沈。
鬬水正回斡，倒流安可禁。
空愁江海信，惊浪隔相寻。','',''),('quantangshi-20022','旅行','孟郊','quantangshi','','卷21','楚水结冰薄，楚云为雨微。
野梅参差发，旅榜逍遥归。','',''),('quantangshi-20023','上河阳李大夫','孟郊','quantangshi','','卷21','上将秉神略，至兵无猛威。
三军当严冬，一抚胜重衣。
霜劒夺众景，夜星失长辉。
苍鹰独立时，恶鸟不敢飞。
武牢锁天关，河桥纽地机。
大将奚以安，守此称者稀。
贫士少颜色，贵门多轻肥。
试登山岳高，方见草木微。
山岳恩既广，草木心皆归。','',''),('quantangshi-20024','投赠张端公','孟郊','quantangshi','','卷21','君子量不极，胸吞百川流。
嫉邪霜气直，问俗春辞柔。
日户昼辉静，月杯夜景幽。
咏惊芙蓉发，笑激风飙秋。
鸾步独无侣，鹤音仍寡俦。
幸霑分寸顾，散此千万忧。','',''),('quantangshi-20025','赠苏州韦郎中使君','孟郊','quantangshi','','卷21','谢客吟一声，霜落羣听清。
文含元气柔，鼓动万物轻。
嘉木依性植，曲枝亦不生。
尘埃徐庾词，金玉曹刘名。
章句作雅正，江山益鲜明。
萍苹一浪草，菰蒲片池荣。
曾是康乐咏，如今搴其英。
顾惟菲薄质，亦愿将此并。','',''),('quantangshi-20026','上张徐州','孟郊','quantangshi','','卷21','为水不入海，安得浮天波。
为木不在山，安得横日柯。
再来君子傍，始觉精义多。
大德唯一施，众情自偏颇。
至乐无宫征，至声遗讴謌。
愿鼓空桑弦，永使万物和。
顾己诚拙讷，干名已蹉跎。
献词惟在口，所欲无余佗。
乍作支泉石，乍作翳松萝。
一不改方圆，破质为琢磨。
贱子本如此，大贤心若何。
岂是无异途，异途难经过。','',''),('quantangshi-20027','上包祭酒','孟郊','quantangshi','','卷21','岳岳冠盖彦，英英文字雄。
琼音独听时，尘韵固不同。
春云生纸上，秋涛起胸中。
时吟五君咏，再举七子风。
何幸松桂侣，见知勤苦功。
愿将黄鹤翅，一借飞云空。','',''),('quantangshi-20028','赠别崔纯亮','孟郊','quantangshi','','卷21','食荠肠亦苦，强歌声无欢。
出门即有碍，谁谓天地宽。
有碍非遐方，长安大道傍。
小人智虑险，平地生太行。
镜破不改光，兰死不改香。
始知君子心，交久道益彰。
君心与我怀，离别俱回遑。
譬如浸蘖泉，流苦已日长。
忍泣目易衰，忍忧形易伤。
项籍岂不壮，贾生岂不良。
当其失意时，涕泗各沾裳。
古人劝加餐，此餐难自强。
一饭九祝噎，一嗟十断肠。
况是儿女怨，怨气凌彼苍。
彼苍若有知，白日下清霜。
今朝始惊叹，碧落空茫茫。','',''),('quantangshi-20029','赠文应上人','孟郊','quantangshi','','卷21','栖迟青山巅，高静身所便。
不践有命草，但饮无声泉。
斋性空转寂，学情深更专。
经文开贝叶，衣制垂秋莲。
厌此俗人羣，暂来还却旋。','',''),('quantangshi-20030','严河南','孟郊','quantangshi','','卷21','赤令风骨峭，语言清霜寒。
不必用雄威，见者毛发攒。
我有赤令心，未得赤令官。
终朝衡门下，忍志将筑弹。
君从西省郎，正有东洛观。
洛民萧条久，威恩悯抚难。
苦竹声啸雪，夜斋闻千竿。
诗人偶寄耳，听苦心多端。
多端落杯酒，酒中方得欢。
隐士多饮酒，此言信难刊。
取次令坊沽，举止务在宽。
何必红烛娇，始言清宴阑。
丈夫莫矜庄，矜庄不中看。','',''),('quantangshi-20031','赠李观','孟郊','quantangshi','','卷21','谁言形影亲，灯灭影去身。
谁言鱼水欢，水竭鱼枯鳞。
昔为同恨客，今为独笑人。
舍予在泥辙，飘迹上云津。
卧木易成蠹，弃花难再春。
何言对芳景，愁望极萧晨。
埋劒谁识气，匣弦日生尘。
愿君语高风，为余问苍旻。','',''),('quantangshi-20032','吴安西馆赠从弟楚客','孟郊','quantangshi','','卷21','蒙笼杨柳馆，中有南风生。
风生今为谁，湘客多远情。
孤枕楚水梦，独帆楚江程。
觉来残恨深，尚与归路并。
玉匣五弦在，请君时一鸣。','',''),('quantangshi-20033','赠章仇将军','孟郊','quantangshi','','卷21','将军不夸劒，才气为英雄。
五岳拽力内，百川倾意中。
本立谁敢拔，飞文自难穷。
前时天地翻，已有扶正功。','',''),('quantangshi-20034','赠道月上人','孟郊','quantangshi','','卷21','僧貌净无点，僧衣宁缀华。
寻常昼日行，不使身影斜。
饭术煮松柏，坐山敷云霞。
欲知禅隐高，缉薜为袈裟。','',''),('quantangshi-20035','抒情因上郎中二十二叔监察十五叔兼呈李益端公柳缜评事','孟郊','quantangshi','','卷21','方凭指下弦，写出心中言。
寸草贱子命，高山主人恩。
游边风沙意，梦楚波涛魂。
一日引别袂，九回沾泪痕。
自悲何以然，在礼阙晨昏。
名利时转甚，是非宵亦喧。
浮情少定主，百虑随世翻。
举此胸臆恨，幸从贤哲论。
明明三飞鸾，照物如朝暾。','',''),('quantangshi-20036','赠城郭道士','孟郊','quantangshi','','卷21','望里失却山，听中遗却泉。
松枝休策云，药囊翻贮钱。
曾依青桂隣，学得白雪弦。
别来意未回，世上为隐仙。','',''),('quantangshi-20037','桐庐山中赠李明府','孟郊','quantangshi','','卷21','静境无浊氛，清雨零碧云。
千山不隐响，一叶动亦闻。
即此佳志士，精微谁相羣。
欲识楚章句，袖中兰茝薰。','',''),('quantangshi-20038','献汉南樊尚书','孟郊','quantangshi','','卷21','天下昔崩乱，大君识贤臣。
众木尽摇落，始见竹色真。
兵势走山岳，阳光潜埃尘。
心开玄女符，面缚清波人。
异俗既从化，浇风亦归淳。
自公理斯郡，寒谷皆变春。
旗影卷赤电，劒锋匣青鳞。
如何嵩高气，作镇楚水滨。
云镜忽开霁，孤光射无垠。
乃知寻常鉴，照影不照神。','',''),('quantangshi-20039','赠转运陆中丞','孟郊','quantangshi','','卷21','掌运职既大，摧邪名更雄。
鹏飞簸曲云，鹗怒生直风。
投彼霜雪令，翦除荆棘丛。
楚仓倾向西，吴米发自东。
帆影咽河口，车声聋关中。
尧知才策高，人喜道路通。
皆经内史力，继得酇侯功。
莱子真为少，相如未免穷。
衣花野菡萏，书叶山梧桐。
不是宗匠心，谁怜久栖蓬。','',''),('quantangshi-20040','赠万年陆郎中','孟郊','quantangshi','','卷21','天子忧剧县，寄深华省郎。
纷纷风响佩，蛰蛰劒开霜。
旧事笑堆案，新声唯雅章。
谁言百里才，终作横天梁。
江鸿耻承眷，云津未能翔。
徘徊尘俗中，短毳无辉光。','',''),('quantangshi-20041','擢第后东归书怀献座主吕侍御','孟郊','quantangshi','','卷21','昔岁辞亲泪，今为恋主泣。
去住情难竝，别离景易戢。
夭矫大空鳞，曾为小泉蛰。
幽意独沈时，震雷忽相及。
神行既不宰，直致非所执。
至运本遗功，轻生各自立。
大君思此化，良佐自然集。
宝镜无私光，时文有新习。
慈亲诫志就，贱子归情急。
擢第谢灵台，牵衣出皇邑。
行襟海日曙，逸抱江风入。
蒹葭得波浪，芙蓉红岸湿。
云寺势动摇，山钟韵嘘吸。
旧游期再践，悬水得重挹。
松萝虽可居，青紫终当拾。','',''),('quantangshi-20042','古意赠梁肃补阙','孟郊','quantangshi','','卷21','曲木忌日影，谗人畏贤明。
自然照烛间，不受邪佞轻。
不有百炼火，孰知寸金精。
金铅正同炉，愿分精与麤。','',''),('quantangshi-20043','赠黔府王中丞楚','孟郊','quantangshi','','卷21','旧说天下山，半在黔中青。
又闻天下泉，半落黔中鸣。
山水千万遶，中有君子行。
儒风一以扇，污俗心皆平。
我愿中国春，化从异方生。
昔为阴草毒，今为阳华英。
嘉实缀绿蔓，凉湍泻清声。
逍遥物景胜，视听空旷并。
困骥犹在辕，沉珠尚隐精。
路遐莫及眄，泥污日已盈。
岁晏将何从，落叶甘自轻。','',''),('quantangshi-20044','上达奚舍人','孟郊','quantangshi','','卷21','北山少日月，草木苦风霜。
贫士在重坎，食梅有酸肠。
万俗皆走圆，一身犹学方。
常恐众毁至，春叶成秋黄。
大贤秉高鉴，公烛无私光。
暗室晓未及，幽行涕空行。','',''),('quantangshi-20045','赠主人','孟郊','quantangshi','','卷21','斗水泻大海，不如泻枯池。
分明贤达交，岂顾豪华儿。
海有不足流，豪有不足资。
枯鳞易为水，贫士易为施。
幸覩君子席，会将幽贱期。
侧闻清风议，饫如黄金巵。
此道与日月，同光无尽时。','',''),('quantangshi-20046','赠建业契公','孟郊','quantangshi','','卷21','师住青山寺，清华常绕身。
虽然到城郭，衣不上栖尘。','',''),('quantangshi-20047','献襄阳于大夫','孟郊','quantangshi','','卷21','襄阳青山郭，汉江白铜堤。
谢公领兹郡，山水无尘泥。
铁马万霜雪，绛旗千虹霓。
风漪参差泛，石板重叠跻。
旧泪不复堕，新欢居然齐。
还畊竟原野，归老相扶携。
物色增暧暧，寒芳更萋萋。
渊清有遐略，高躅无近蹊。
即此富苍翠，自然引翔栖。
曩游常抱忆，夙好今尚暌。
愿言从逸辔，暇日凌清溪。','',''),('quantangshi-20048','赠郑夫子鲂','孟郊','quantangshi','','卷21','天地入胸臆，吁嗟生风雷。
文章得其微，物象由我裁。
宋玉逞大句，李白飞狂才。
苟非圣贤心，孰与造化该。
勉矣郑夫子，骊珠今始胎。','',''),('quantangshi-20049','大隐坊 崔从事郧以直隳职','孟郊','quantangshi','','卷21','古人留清风，千载遥赠君。
破松见贞心，裂竹见直文。
残月色不改，高贤德常新。
家怀诗书富，宅抱草木贫。
安得一蹄泉，来化千尺鳞。
含意永不语，钓璜幽水滨。','',''),('quantangshi-20050','大隐坊 章仇将军良弃功守贫','孟郊','quantangshi','','卷21','饮君江海心，讵能辨浅深。
挹君山岳德，谁能齐嵚岑。
东海精为月，西岳气凝金。
进则万景昼，退则羣物阴。
我欲荐此言，天门峻沈沈。
风飙亦感激，为我飕飗吟。','',''),('quantangshi-20051','大隐坊 赵记室俶在职无事','孟郊','quantangshi','','卷21','卑静身后老，高动物先摧。
方圆水任器，刚劲木成灰。
大道母羣物，达人腹众才。
时吟尧舜篇，心向无为开。
彼隐山万曲，我隐酒一杯。
公庭何所有，日日清风来。','',''),('quantangshi-20052','赠韩郎中愈 一','孟郊','quantangshi','','卷21','何以定交契，赠君高山石。
何以保贞坚，赠君青松色。
贫居过此外，无可相彩饰。
闻君硕鼠诗，吟之泪空滴。','',''),('quantangshi-20053','赠韩郎中愈 二','孟郊','quantangshi','','卷21','硕鼠既穿墉，又啮机上丝。
穿墉有闲土，啮丝无余衣。
朝吟枯桑柘，暮泣空杼机。
岂是无巧妙，丝断将何施。
众人尚肥华，志士多饥羸。
愿君保此节，天意当察微。','',''),('quantangshi-20054','赠韩郎中愈 三','孟郊','quantangshi','','卷21','前日远别离，今日生白发。
欲知万里情，晓卧半牀月。
常恐百虫秋，使我芳草歇。','',''),('quantangshi-20055','戏赠无本 一','孟郊','quantangshi','','卷21','长安秋声干，木叶相号悲。
瘦僧卧冰凌，嘲咏含金痍。
金痍非战痕，峭病方在兹。
诗骨耸东野，诗涛涌退之。
有时踉跄行，人惊鹤阿师。
可惜李杜死，不见此狂痴。','',''),('quantangshi-20056','戏赠无本 二','孟郊','quantangshi','','卷21','燕僧耸听词，袈裟喜新翻。
北岳厌利杀，玄功生微言。
天高亦可飞，海广亦可源。
文章杳无底，劚掘谁能根。
梦灵仿髴到，对我方与论。
拾月鲸口边，何人免为吞。
燕僧摆造化，万有随手犇。
补缀杂霞衣，笑傲诸贵门。
将明文在身，亦尔道所存。
朔雪凝别句，朔风飘征魂。
再期嵩少游，一访蓬萝村。
春草步步绿，春山日日暄。
遥莺相应吟，晚听恐不繁。
相思塞心胸，高逸难攀援。','',''),('quantangshi-20057','寄张籍','孟郊','quantangshi','','卷21','夜镜不照物，朝光何时升。
黯然秋思来，走入志士膺。
志士惜时逝，一宵三四兴。
清汉徒自朗，浊河终无澄。
旧爱忽已远，新愁坐相凌。
君其隐壮怀，我亦逃名称。
古人贵从晦，君子忌党朋。
倾败生所竞，保全归懵懵。
浮云何当来，潜虬会飞腾。','',''),('quantangshi-20058','忆周秀才素上人时闻各在一方','孟郊','quantangshi','','卷21','东西分我情，魂梦安能定。
野客云作心，高僧月为性。
浮云自高闲，明月常空净。
衣敝得古风，居山无俗病。
吟听碧云语，手把青松柄。
羡尔欲寄书，飞禽杳难倩。','',''),('quantangshi-20059','舟中喜遇从叔简别后寄上时从叔初擢第归江南郊不从行','孟郊','quantangshi','','卷21','一意两片云，暂合还却分。
南云乘庆归，北云与谁羣。
寄声千里风，相唤闻不闻。','',''),('quantangshi-20060','怀南岳隐士 一','孟郊','quantangshi','','卷21','见说祝融峰，擎天势似腾。
藏千寻布水，出十八高僧。
古路无人迹，新霞吐石棱。
终居将尔叟，一一共余登。','',''),('quantangshi-20061','怀南岳隐士 二','孟郊','quantangshi','','卷21','千峰映碧湘，真叟此中藏。
饭不煮石吃，眉应似发长。
枫梩搘酒瓮，鹤虱落琴牀。
强效忘机者，斯人尚未忘。','',''),('quantangshi-20062','春夜忆萧子真','孟郊','quantangshi','','卷21','半夜不成寐，灯尽又无月。
独向堦前立，子规啼不歇。
况我有金兰，忽尔为胡越。
争得明镜中，久长无白发。','',''),('quantangshi-20063','寄院中诸公','孟郊','quantangshi','','卷21','奕奕秋水傍，骎骎绿云蹄。
月仙有高曜，灵凤无卑栖。
翠色遶云谷，碧华凝月溪。
竹林递历览，云寺行攀跻。
冠豸独屈蠖，匣龙期剸犀。
千山惊月晓，百里闻霜鼙。
戎府多秀异，谢公期相携。
因之仰羣彦，养拙固难齐。','',''),('quantangshi-20064','寄洺州李大夫','孟郊','quantangshi','','卷21','自从蓟师反，中国事纷纷。
儒道一失所，贤人多在军。
鸟巢忧迸射，鹿耳骇惊闻。
剑折唯恐匣，弓贪不让勋。
方知省事将，动必谢前羣。
鹳阵常先罢，鱼符最晚分。
步闲洺水曲，笑激太行云。
诗叟未相识，竹儿争见君。
殷勤越谈说，记尽古风文。','',''),('quantangshi-20065','寄卢虔使君','孟郊','quantangshi','','卷21','霜露再相换，游人犹未归。
岁新月改色，客久线断衣。
有鹤冰在翅，竟久力难飞。
千家旧素沼，昨日生绿辉。
春色若可借，为君步芳菲。','',''),('quantangshi-20066','寄崔纯亮','孟郊','quantangshi','','卷21','百川有余水，大海无满波。
器量各相悬，贤愚不同科。
羣辩有姿语，众欢无行歌。
唯余洛阳子，郁郁恨常多。
时读过秦篇，为君涕滂沱。','',''),('quantangshi-20067','汴州离乱后忆韩愈李翱','孟郊','quantangshi','','卷21','会合一时哭，别离三断肠。
残花不待风，春尽各飞扬。
欢去收不得，悲来难自防。
孤门清馆夜，独卧明月牀。
忠直血白刃，道路声苍黄。
食恩三千士，一旦为豺狼。
海岛士皆直，夷门士非良。
人心既不类，天道亦反常。
自杀与彼杀，未知何者臧。','',''),('quantangshi-20068','寄张籍','孟郊','quantangshi','','卷21','未见天子面，不如双盲人。
贾生对文帝，终日犹悲辛。
夫子亦如盲，所以空泣麟。
有时独斋心，仿髴梦称臣。
梦中称臣言，觉后真埃尘。
东京有眼富不如，西京无眼贫西京。
无眼犹有耳隔墙，时闻天子车辚辚。
辚辚车声辗冰玉，南郊坛上礼百神。
西明寺后穷瞎张太祝，纵尔有眼谁尔珍。
天子咫尺不得见，不如闭眼且养真。','',''),('quantangshi-20069','寄义兴小女子','孟郊','quantangshi','','卷21','江南庄宅浅，所固唯疎篱。
小女未解行，酒弟老更痴。
家中多吴语，教尔遥可知。
山怪夜动门，水妖时弄池。
所忧痴酒肠，不解委曲辞。
渔妾性崛强，耕童手皴厘。
想兹为襁褓，如鸟拾柴枝。
我咏元鲁山，胸臆流甘滋。
终当学自乳，起坐常相随。','',''),('quantangshi-20070','忆江南弟','孟郊','quantangshi','','卷21','白首眼垂血，望尔唯梦中。
筋力强起时，魂魄犹在东。
眼光寄明星，起来东望空。
望空不见人，江海波无穷。
衰老无气力，呼叫不成风。
孑然忆忆言，落地何由通。
常师共被教，竟作生离翁。
生离不可诉，上天何曾聪。
未忍对松栢，自鞭残朽躬。
自鞭亦何益，知教非所崇。
努力拄杖来，余活与尔同。
不然死后耻，遗死亦有终。','',''),('quantangshi-20071','宿空侄院寄澹公','孟郊','quantangshi','','卷21','夜坐冷竹声，二三高人语。
灯窗看律钞，小师别为侣。
雪檐晴滴滴，茗椀华举举。
磬音多风飙，声韵闻江楚。
官街不相隔，诗思空愁予。
明日策杖归，去住两延伫。','',''),('quantangshi-20072','寄陕府邓给事','孟郊','quantangshi','','卷21','陕城临大道，馆宇屹几鲜。
候谒随芳语，铿词芬蜀牋。
从来镜目下，见尽道心前。
自谓古诗量，异将新学偏。
戆人年六十，每月请三千。
不敢等闲用，愿为长寿钱。
非关亦洁尔，将以救羸然。
孤省痴皎皎，默吟写绵绵。
病书凭昼日，驿信寄宵鞭。
疾诉将何谕，肆鳞今倒悬。
尘鲤见枯浪，土鬣思干泉。
感感无绪荡，愁愁作□边。
贞元文祭酒，比谨学韦玄。
满坐风无杂，当朝雅独全。
见知嘱徐孺，赏句类陶渊。
一顾生鸿羽，再言将鹤翩。
宣扬隘车马，君子凑骈阗。
曾是此同睠，至今应赐怜。
磨墨零落泪，楷字贡仁贤。','',''),('quantangshi-20073','送谏议十六叔至孝义渡后奉寄','孟郊','quantangshi','','卷21','晓渡明镜中，霞衣相飘颻。
浪凫惊亦双，蓬客将谁僚。
别饮孤易醒，离忧壮难销。
文清虽无敌，儒贵不敢骄。
江吏捧紫泥，海旗剪红蕉。
分明太守礼，跨蹑毗陵桥。
伊洛去未回，遐瞩空寂寥。','',''),('quantangshi-20074','至孝义渡寄郑军事唐二十五','孟郊','quantangshi','','卷21','咫尺不得见，心中空嗟嗟。
官街泥水深，下脚道路斜。
嵩少玉峻峻，伊雒碧华华。
岸亭当四迥，诗老独一家。
洧叟何所如，郑石唯有些。
何当来说事，为君开流霞。','',''),('quantangshi-20075','答友人','孟郊','quantangshi','','卷21','白日照清水，浅深无隐姿。
君子业高文，怀抱多正思。
砥行碧山石，结交青松枝。
碧山无转易，青松难倾移。
落落出俗韵，琅琅大雅词。
自非随氏掌，明月安能持。
千里不可倒，一返无近期。
如何非意中，良觌忽在兹。
道语必疎淡，儒风易凌迟。
愿存坚贞节，勿为霜霰欺。','',''),('quantangshi-20076','酬友人见寄新文','孟郊','quantangshi','','卷21','为客栖未定，况当玄月中。
繁云翳碧霄，落雪和清风。
郊陌绝行人，原隰多飞蓬。
耕牛返村巷，野鸟依房栊。
我无饥冻忧，身托莲花宫。
安闲赖禅伯，复得疏尘蒙。
览君郢曲文，词彩何冲融。
讴吟不能已，顿觉形神空。','',''),('quantangshi-20077','答韩愈李观别因献张徐州','孟郊','quantangshi','','卷21','富别愁在颜，贫别愁销骨。
懒磨旧铜镜，畏见新白发。
古树春无花，子规啼有血。
离弦不堪听，一听四五绝。
世途非一险，俗虑有千结。
有客步大方，驱车独迷辙。
故人韩与李，逸翰双皎洁。
哀我摧折归，赠词纵横设。
徐方国东枢，元戎天下杰。
禰生投刺游，王粲吟诗谒。
高情无遗照，朗抱开晓月。
有土不埋冤，有雠皆为雪。
愿为直草木，永向君地列。
愿为古琴瑟，永向君听发。
欲识丈夫心，会将孤剑说。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-20078','答昼上人止谗作','孟郊','quantangshi','','卷21','烈烈鸑鷟吟，铿铿琅玕音。
枭摧明月啸，鹤起清风心。
渭水不可浑，泾流徒相侵。
俗侣唱桃叶，隐士鸣桂琴。
子野真遗却，浮浅藏渊深。','',''),('quantangshi-20079','答姚怤见寄','孟郊','quantangshi','','卷21','日月不同光，昼夜各有宜。
贤哲不苟合，出处亦待时。
而我独迷见，意求异士知。
如将舞鹤管，误向惊凫吹。
大雅难具陈，正声易漂沦。
君有丈夫泪，泣人不泣身。
行吟楚山玉，义泪沾衣巾。','',''),('quantangshi-20080','答郭郎中','孟郊','quantangshi','','卷21','松栢死不变，千年色青青。
志士贫更坚，守道无异营。
每弹潇湘瑟，独抱风波声。
中有失意吟，知者泪满缨。
何以报知者，永存坚与贞。','',''),('quantangshi-20081','答卢虔故园见寄','孟郊','quantangshi','','卷21','访旧无一人，独归清雒春。
花闻哭声死，水见别容新。
乱后故乡宅，多为行路尘。
因悲楚左右，谤玉不知珉。','',''),('quantangshi-20082','汝坟蒙从弟楚材见赠时郊将入秦楚材适楚','孟郊','quantangshi','','卷21','朝为主人心，暮为行客吟。
汝水忽凄咽，汝风流苦音。
北阙秦门高，南路楚石深。
分泪洒白日，离肠绕青岑。
何以寄远怀，黄鹤能相寻。','',''),('quantangshi-20083','同从叔简酬卢殷少府','孟郊','quantangshi','','卷21','梅尉吟楚声，竹风为凄清。
深虚冰在性，高洁云入情。
借水洗闲貌，寄蕉书逸名。
羞将片石文，鬬此双琼英。','',''),('quantangshi-20084','酬李侍御书记秋夕雨中病假见寄','孟郊','quantangshi','','卷21','秋风遶衰柳，远客闻雨声。
重兹阻良夕，孤坐唯积诚。
果枉移疾咏，中含嘉虑明。
洗涤烦浊尽，视听昭旷生。
未觉衾枕倦，久为章奏婴。
达人不宝药，所保在闲情。','',''),('quantangshi-20085','答卢仝','孟郊','quantangshi','','卷21','楚屈入水死，诗孟踏雪僵。
直气苟有存，死亦何所妨。
日劈高查牙，清棱含冰浆。
前古后古冰，与山气势强。
闪怪千石形，异状安可量。
有时春镜破，百道声飞扬。
潜仙不足言，朗客无隐肠。
为君倾海宇，日夕多文章。
天下岂无缘，此山雪昂藏。
烦君前致词，哀我老更狂。
狂歌不及狂，歌声缘凤皇。
凤兮何当来，消我孤直疮。
君文真凤声，宣隘满铿锵。
洛友零落尽，逮兹悲重伤。
独自奋异骨，将骑白角翔。
再三劝莫行，寒气有刀枪。
仰慙君子多，慎勿作芬芳。','',''),('quantangshi-20086','奉报翰林张舍人见遗之诗','孟郊','quantangshi','','卷21','百虫笑秋律，清削月夜闻。
晓棱视听微，风剪叶已纷。
君子鉴大雅，老人非俊羣。
收拾古所弃，俛仰补空文。
孤韵耻春俗，余响逸零雰。
自然蹈终南，涤暑凌寒氛。
岩霰不知午，磵澌镇含曛。
曾是醒古醉，所以多隐沦。
江调乐之远，溪谣生徒新。
众蕴有余采，寒泉空哀呻。
南谢竟莫至，北宋当时珍。
赜灵各自异，酌酒谁能均。
昔咏多写讽，今词讵无因。
品松何高翠，宫殿没荒榛。
苔趾识宏制，沙潨游崩津。
忽吟陶渊明，此即羲皇人。
心放出天地，形拘在风尘。
前贤素行阶，夙嗜青山勤。
达士立明镜，朗言为近臣。
将期律万有，倾倒甄无垠。
鸑鷟应蟋蟀，丝毫意皆申。
况于三千章，哀叩不为神。','',''),('quantangshi-20087','送从弟郢东归','孟郊','quantangshi','','卷21','尔去东南夜，我无西北梦。
谁言贫别易，贫别愁更重。
晓色夺明月，征人逐羣动。
秋风楚涛高，旅榜将谁共。','',''),('quantangshi-20088','山中送从叔简赴举','孟郊','quantangshi','','卷21','石根百尺杉，山眼一片泉。
倚之道气高，饮之诗思鲜。
于此逍遥场，忽奏别离弦。
却笑薜萝子，不同鸣跃年。','',''),('quantangshi-20089','送别崔寅亮下第','孟郊','quantangshi','','卷21','天地唯一气，用之自偏颇。
忧人成苦吟，达士为高歌。
君子识不浅，桂枝忧更多。
岁晏期攀折，时归且婆娑。
素质如削玉，清词若倾河。
虬龙未化时，鱼鳖同一波。
去矣当自适，故乡饶薜萝。','',''),('quantangshi-20090','大梁送柳淳先入关','孟郊','quantangshi','','卷21','青山辗为尘，白日无闲人。
自古推高车，争利西入秦。
王门与侯门，待富不待贫。
空携一束书，去去谁相亲。','',''),('quantangshi-20091','送无怀道士游富春山水','孟郊','quantangshi','','卷21','造化绝高处，富春独多观。
山浓翠滴洒，水折珠摧残。
溪镜不隐发，树衣长遇寒。
风猿虚空飞，月狖叫啸酸。
信此神仙路，岂为时俗安。
煮金阴阳火，囚怪星宿坛。
花发我未识，玉生忽藂攒。
蓬莱浮荡漾，非道相从难。','',''),('quantangshi-20092','送温初下第','孟郊','quantangshi','','卷21','日落浊水中，夜光谁能分。
高怀无近趣，清抱多远闻。
欲识丈夫志，心藏孤岳云。
长安风尘别，咫尺不见君。','',''),('quantangshi-20093','送卢虔端公守复州','孟郊','quantangshi','','卷21','师旷听羣木，自然识孤桐。
正声逢知音，愿出大朴中。
知音不韵俗，独立占古风。
忽挂触邪冠，逮逐南飞鸿。
肃肃太守章，明明华毂熊。
商山无平路，楚水有惊潨。
日月千里外，光阴难载同。
新愁徒自积，良会何由通。','',''),('quantangshi-20094','送任载齐古二秀才自洞庭游宣城','孟郊','quantangshi','','卷21','洞庭非人境，道路行虚空。
二客月中下，一帆天外风。
鱼龙波五色，金碧树千丛。
闪怪如可惧，在诚无不通。
扣奇知浩淼，采异访穹崇。
物表即高韵，人间访仙公。
宣城文雅地，谢守声闻融。
证玉易为力，辨珉谁不同。
从兹阮籍泪，且免泣途穷。','',''),('quantangshi-20095','送晓公归庭山','孟郊','quantangshi','','卷21','庭山何崎岖，寺路缘翠微。
秋霁山尽出，日落人独归。
云生高高步，泉洒田田衣。
枯巢无还羽，新木有争飞。
兹焉不可继，梦寐空清辉。','',''),('quantangshi-20096','送豆卢策归别墅','孟郊','quantangshi','','卷21','短松鹤不巢，高石云不栖。
君今潇湘去，意与云鹤齐。
力买奇险地，手开清浅溪。
身披薜荔衣，山陟莓苔梯。
一卷冰雪文，避俗常自携。','',''),('quantangshi-20097','送清远上人归楚山旧寺','孟郊','quantangshi','','卷21','波中出吴境，霞际登楚岑。
山寺一别来，云萝三改阴。
诗夸碧云句，道证青莲心。
应笑泛萍者，不知松隐深。','',''),('quantangshi-20098','山中送从叔简','孟郊','quantangshi','','卷21','莫以手中琼，言邀世上名。
莫以山中迹，久向人间行。
松栢有霜操，风泉无俗声。
应怜枯朽质，惊此别离情。','',''),('quantangshi-20099','送萧炼师入四明山','孟郊','quantangshi','','卷21','闲于独鹤心，大于高松年。
迥出万物表，高栖四明巅。
千寻直裂峰，百尺倒泻泉。
绛雪为我饭，白云为我田。
静言不语俗，灵踪时步天。','',''),('quantangshi-20100','感别送从叔校书简再登科东归','孟郊','quantangshi','','卷21','长安车马道，高槐结浮阴。
下有名利人，一人千万心。
黄鹄多远势，沧溟无近浔。
怡怡静退姿，泠泠思归吟。
菱唱忽生听，芸书回望深。
清风散言笑，余花缀衣襟。
独恨鱼鸟别，一飞将一沈。','',''),('quantangshi-20101','送玄亮师','孟郊','quantangshi','','卷21','兰泉涤我襟，杉月栖我心。
茗啜绿净花，经诵清柔音。
何处笑为别，淡情愁不侵。','',''),('quantangshi-20102','送李尊师玄','孟郊','quantangshi','','卷21','口诵碧简文，身是青霞君。
头冠两片月，肩披一条云。
松骨轻自飞，鹤心高不羣。','',''),('quantangshi-20103','同昼上人送郭秀才江南寻兄弟','孟郊','quantangshi','','卷21','地上春色生，眼前诗彩明。
手携片宝月，言是高僧名。
溪转万曲心，水流千里声。
飞鸣向谁去，江鸿弟与兄。','',''),('quantangshi-20104','春日同韦郎中使君送邹儒立少府扶侍赴云阳','孟郊','quantangshi','','卷21','离思着百草，绵绵生无穷。
侧闻畿甸秀，三振词策雄。
太守不韵俗，诸生皆变风。
郡斋敞西清，楚瑟惊南鸿。
海畔帝城望，云阳天色中。
酒酣正芳景，诗缀新碧丛。
服彩老莱并，侍车江革同。
过隋柳顦顇，入洛花蒙笼。
高步讵留足，前程在层空。
独慙病鹤羽，飞送力难崇。','',''),('quantangshi-20105','送从叔校书简南归','孟郊','quantangshi','','卷21','长安别离道，宛在东南隅。
寒草根未死，愁人心已枯。
促促水上景，遥遥天际途。
生随昏晓中，皆被日月驱。
北骑达山岳，南帆指江湖。
高踪一超越，千里在须臾。','',''),('quantangshi-20106','送韩愈从军','孟郊','quantangshi','','卷21','志士感恩起，变衣非变性。
亲宾改旧观，僮仆生新敬。
坐作羣书吟，行为孤剑咏。
始知出处心，不失平生正。
凄凄天地秋，凛凛军马令。
驿尘时一飞，物色极四静。
王师既不战，庙略在无竞。
王粲有所依，元瑜初应命。
一章喻檄明，百万心气定。
今朝旌鼓前，笑别丈夫盛。','',''),('quantangshi-20107','同茅郎中使君送河南裴文学','孟郊','quantangshi','','卷21','河南有归客，江风绕行襟。
送君无尘听，舞鹤清瑟音。
菱蔓缀楚棹，日华正嵩岑。
如何谢文学，还起会云吟。','',''),('quantangshi-20108','送李翺习之','孟郊','quantangshi','','卷21','习之势翩翩，东南去遥遥。
赠君双履足，一为上臯桥。
臯桥路逶迤，碧水清风飘。
新秋折藕花，应对吴语娇。
千巷分渌波，四门生早潮。
湖榜轻褭褭，酒旗高寥寥。
小时屐齿痕，有处应未销。
旧忆如雾星，怳见于梦消。
言之烧人心，事去不可招。
独孤宅前曲，箜篌醉中谣。
壮年俱悠悠，逮兹各焦焦。
执手复执手，唯道无枯凋。','',''),('quantangshi-20109','送丹霞子阮芳颜上人归山','孟郊','quantangshi','','卷21','松色不肯秋，玉性不可柔。
登山须正路，饮水须直流。
倩鹤附书信，索云作衣裘。
仙村莫道远，枉策招交游。','',''),('quantangshi-20110','送从舅端适楚地','孟郊','quantangshi','','卷21','归情似泛空，飘荡楚波中。
羽扇扫轻汗，布帆筛细风。
江花折菡萏，岸影泊梧桐。
元舅唱离别，贱生愁不穷。','',''),('quantangshi-20111','送卢汀侍御归天德幕','孟郊','quantangshi','','卷21','仲宣领骑射，结束皆少年。
匹马黄河岸，射雕清霜天。
旌旗防日北，道路上云巅。
古雪无销铄，新冰有堆填。
清溪徒耸诮，白璧自招贤。
岂比重恩者，闭门方独全。','',''),('quantangshi-20112','送草书献上人归庐山','孟郊','quantangshi','','卷21','狂僧不为酒，狂笔自通天。
将书云霞片，直至清明巅。
手中飞黑电，象外泻玄泉。
万物随指顾，三光为回旋。
聚书云霮䨴，洗砚山晴鲜。
忽怒画虵虺，喷然生风烟。
江人愿停笔，惊浪恐倾船。','',''),('quantangshi-20113','和薛先辈送独孤秀才上都赴嘉会得青字','孟郊','quantangshi','','卷21','秦云攀窈窕，楚桂搴芳馨。
五色岂徒尔，万枝皆有灵。
仙谣天上贵，林咏雪中青。
持此一为赠，送君翔杳冥。','',''),('quantangshi-20114','送崔爽之湖南','孟郊','quantangshi','','卷21','江与湖相通，二水洗高空。
定知一日帆，使得千里风。
雪唱与谁和，俗情多不通。
何当逸翮纵，飞起泥沙中。','',''),('quantangshi-20115','送超上人归天台','孟郊','quantangshi','','卷21','天台山最高，动蹑赤城霞。
何以静双目，扫山除妄花。
何以洁其性，滤泉去泥沙。
灵境物皆直，万松无一斜。
月中见心近，云外将俗赊。
山兽护方丈，山猿捧袈裟。
遗身独得身，笑我牵名华。','',''),('quantangshi-20116','同李益崔放送王炼师还楼观兼为羣公先营山居','孟郊','quantangshi','','卷21','十年白云士，一卷紫芝书。
来结崆峒侣，还期缥缈居。
霞冠遗彩翠，月帔上空虚。
寄谢泉根水，清泠闲有余。','',''),('quantangshi-20117','张徐州席送岑秀才','孟郊','quantangshi','','卷21','振振芝兰步，升自君子堂。
泠泠松桂吟，生自楚客肠。
羇鸟无定栖，惊蓬在他乡。
去兹门馆闲，即彼道路长。
雨余山川净，麦熟草木凉。
楚泪滴章句，京尘染衣裳。
赠君无余佗，久要不可忘。','',''),('quantangshi-20118','送黄构擢第后归江南','孟郊','quantangshi','','卷21','澹澹沧海气，结成黄香才。
幼龄思奋飞，弱冠游灵台。
一鹗顾乔木，众禽不敢猜。
一骥骋长衢，众兽不敢陪。
遂得会风雨，感通如云雷。
至矣小宗伯，确乎心不回。
能令幽静人，声实喧九垓。
却忆江南道，祖筵花里开。
春风不能别，别罢空徘徊。','',''),('quantangshi-20119','送道士','孟郊','quantangshi','','卷21','千年山上行，山上无遗踪。
一日人间游，六合人皆逢。
自有意中侣，白寒徒相从。','',''),('quantangshi-20120','送孟寂赴举','孟郊','quantangshi','','卷21','烈士不忧身，为君吟苦辛。
男儿久失意，宝剑亦生尘。
浮俗官是贵，君子道所珍。
况当圣明主，岂乏证玉臣。
浊水无白日，清流鉴苍旻。
贤愚皎然别，结交当有因。','',''),('quantangshi-20121','同溧阳宰送孙秀才','孟郊','quantangshi','','卷21','废瑟难为弦，南风难为歌。
幽幽拙疾中，忽忽浮梦多。
清韵始啸侣，雅言相与和。
讼闲每往招，祖送奈若何。
牵苦强为赠，邦邑光峨峨。','',''),('quantangshi-20122','溧阳唐兴寺观蔷薇花同诸公饯陈明府','孟郊','quantangshi','','卷21','忽惊红琉璃，千艳万艳开。
佛火不烧物，净香空徘徊。
花下印文字，林间咏觞杯。
羣官饯宰官，此地车马来。','',''),('quantangshi-20123','送柳淳','孟郊','quantangshi','','卷21','青山临黄河，下有长安道。
世上名利人，相逢不知老。','',''),('quantangshi-20124','送殷秀才南游','孟郊','quantangshi','','卷21','诗句临离袂，酒花薰别颜。
水程千里外，岸泊几宵间。
风叶乱辞木，雪猿清叫山。
南中多古事，咏遍始应还。','',''),('quantangshi-20125','送青阳上人游越','孟郊','quantangshi','','卷21','秋风吹白发，微官自萧索。
江僧何用叹，溪县饶寂寞。
楚思物皆清，越山胜非薄。
时看镜中月，独向衣上落。
多谢入冥鸿，笑予在笼鹤。','',''),('quantangshi-20126','奉同朝贤送新罗使','孟郊','quantangshi','','卷21','淼淼望远国，一萍秋海中。
恩传日月外，梦在波涛东。
浪兴豁胸臆，泛程舟虚空。
既兹吟仗信，亦以难私躬。
实怪赏不足，异鲜悦多丛。
安危所系重，征役谁能穷。
彼俗媚文史，圣朝富才雄。
送行数百首，各以铿奇工。
宂隶窃抽韵，孤属思将同。','',''),('quantangshi-20127','留弟郢不得送之江南','孟郊','quantangshi','','卷21','刚有下水船，白日留不得。
老人独自归，苦泪满眼黑。','',''),('quantangshi-20128','送陆畅归湖州因凭题故人皎然塔陆羽坟','孟郊','quantangshi','','卷21','淼淼霅寺前，白苹多清风。
昔游诗会满，今游诗会空。
孤吟玉凄恻，远思景蒙笼。
杼山塼塔禅，竟陵广宵翁。
饶彼草木声，仿髴闻余聪。
因君寄数句，遍为书其藂。
追吟当时说，来者实不穷。
江调难再得，京尘徒满躬。
送君溪鸳鸯，彩色双飞东。
东多高静乡，芳宅冬亦崇。
手自撷甘旨，供养欢冲融。
待我遂前心，收拾使有终。
不然洛岸亭，归死为大同。','',''),('quantangshi-20129','送淡公 一','孟郊','quantangshi','','卷21','燕本冰雪骨，越淡莲花风。
五言双宝刀，联响高飞鸿。
翰苑钱舍人，诗韵铿雷公。
识本未识淡，仰咏嗟无穷。
清恨生物表，朗玉倾梦中。
常于冷竹坐，相语道意冲。
嵩洛兴不薄，稽江事难同。
明年若不来，我作黄蒿翁。
何以兀其心为君学虚空。','',''),('quantangshi-20130','送淡公 二','孟郊','quantangshi','','卷21','坐爱青草上，意含沧海滨。
渺渺独见水，悠悠不问人。
镜浪洗手绿，剡花入心春。
虽然防外触，无奈饶衣新。
行当译文字，慰此吟殷勤。','',''),('quantangshi-20131','送淡公 三','孟郊','quantangshi','','卷21','铜斗饮江酒，手拍铜斗歌。
侬是拍浪儿，饮则拜浪婆。
脚踏小船头，独速舞短蓑。
笑伊渔阳操，空恃文章多。
闲倚青竹竿，白日奈我何。','',''),('quantangshi-20132','送淡公 四','孟郊','quantangshi','','卷21','短蓑不怕雨，白鹭相争飞。
短楫画菰蒲，鬬作豪横归。
笑伊水健儿，浪战求光辉。
不如竹枝弓，射鸭无是非。','',''),('quantangshi-20133','送淡公 五','孟郊','quantangshi','','卷21','射鸭复射鸭，鸭惊菰蒲头。
鸳鸯亦零落，彩色难相求。
侬是清浪儿，每踏清浪游。
笑伊乡贡郎，踏土称风流。
如何丱角翁，至死不裹头。','',''),('quantangshi-20134','送淡公 六','孟郊','quantangshi','','卷21','师得天文章，所以相知怀。
数年伊雒同，一旦江湖乖。
江湖有故庄，小女啼喈喈。
我忧未相识，乳养难和谐。
幸以片佛衣，诱之令看斋。
斋中百福言，催促西归来。','',''),('quantangshi-20135','送淡公 七','孟郊','quantangshi','','卷21','伊洛气味薄，江湖文章多。
坐缘江湖岸，意识鲜明波。
铜斗短蓑行，新章其奈何。
兹焉激切句，非是等闲歌。
制之附驿回，勿使余风讹。
都城第一寺，昭成屹嵯峨。
为师书广壁，仰咏时经过。
徘徊相思心，老泪双滂沱。','',''),('quantangshi-20136','送淡公 八','孟郊','quantangshi','','卷21','江南邑中寺，平地生胜山。
开元吴语僧，律韵高且闲。
妙药溪岸平，桂榜往复还。
树石相鬬生，红绿各异颜。
风味我遥忆，新奇师独攀。','',''),('quantangshi-20137','送淡公 九','孟郊','quantangshi','','卷21','报恩兼报德，寺与山争鲜。
橙橘金盖槛，竹蕉绿凝禅。
经章音韵细，风磬清泠翩。
离肠绕师足，旧忆随路延。
不知几千尺，至死方绵绵。','',''),('quantangshi-20138','送淡公 十','孟郊','quantangshi','','卷21','乡在越镜中，分明见归心。
镜芳步步绿，镜水日日深。
异刹碧天上，古香清桂岑。
朗约徒在昔，章句忽盈今。
幸因西飞叶，书作东风吟。
落我病枕上，慰此浮恨侵。','',''),('quantangshi-20139','送淡公 十一','孟郊','quantangshi','','卷21','牵师袈裟别，师断袈裟归。
问师何苦去，感吃言语稀。
意恐被诗饿，欲住将底依。
卢殷刘言史，饿死君已噫。
不忍见别君，哭君他是非。','',''),('quantangshi-20140','送淡公 十二','孟郊','quantangshi','','卷21','诗人苦为诗，不如脱空飞。
一生空鷕气，非谏复非讥。
脱枯挂寒枝，弃如一唾微。
一步一步乞，半片半片衣。
倚诗为活计，从古多无肥。
诗饥老不怨，劳师泪霏霏。','',''),('quantangshi-20141','送魏端公入朝','孟郊','quantangshi','','卷21','东洛尚淹翫，西京足芳妍。
大宾威仪肃，上客冠劒鲜。
岂惟空恋阙，亦以将朝天。
局促尘末吏，幽老病中弦。
徒怀青云价，忽至白发年。
何当补风教，为荐三百篇。','',''),('quantangshi-20142','送卢郎中汀','孟郊','quantangshi','','卷21','洛水春渡阔，别离心悠悠。
一生空吟诗，不觉成白头。
向事每计较，与山实绸缪。
太华天上开，其下车辙流。
县街无尘土，过客多淹留。
坐饮孤驿酒，行思独山游。
逸关岚气明，照渭空漪浮。
玉珂摆新欢，声与鸾凤俦。
朝谒大家事，唯余去无由。','',''),('quantangshi-20143','送郑仆射出节山南','孟郊','quantangshi','','卷21','国老出为将，红旗入青山。
再招门下生，结束余病孱。
自笑骑马丑，强从驱驰间。
顾顾磨天路，褭褭镜下颜。
文魄既飞越，宦情唯等闲。
羡他白面少，多是清朝班。
惜命非所报，慎行诚独艰。
悠悠去住心，两说何能删。','',''),('quantangshi-20144','别妻家','孟郊','quantangshi','','卷21','芙蓉湿晓露，秋别南浦中。
鸳鸯卷新赠，遥恋东牀空。
碧水不息浪，清溪易生风。
参差坐成阻，飘颻去无穷。
孤云目虽断，明月心相通。
私情讵销铄，积芳在春藂。','',''),('quantangshi-20145','赠姚怤别','孟郊','quantangshi','','卷21','美人废琴瑟，不是无巧弹。
闻君郢中唱，始觉知音难。
惊蓬无还根，驰水多分澜。
倦客厌出门，疲马思解鞍。
何以写此心，赠君握中丹。','',''),('quantangshi-20146','赠竟陵卢使君虔别','孟郊','quantangshi','','卷21','赤日千里火，火中行子心。
孰不苦焦灼，所行为贫侵。
山木岂无凉，猛兽蹲清阴。
归人忆平坦，别路多岖嵚。
赖得竟陵守，时闻建安吟。
赠别折楚芳，楚芳摇衣襟。','',''),('quantangshi-20147','与韩愈李翺张籍话别','孟郊','quantangshi','','卷21','朱弦奏离别，华灯少光辉。
物色岂有异，人心顾将违。
客程殊未已，岁华忽然微。
秋桐故叶下，寒露新雁飞。
远游起重恨，送人念先归。
夜集类饥鸟，晨光失相依。
马迹遶川水，雁书还闺闱。
常恐亲朋阻，独行知虑非。','',''),('quantangshi-20148','监察十五叔东斋招李益端公会别','孟郊','quantangshi','','卷21','欲知惜别情，泻水还清池。
此地有君子，芳兰步葳蕤。
手掇杂英佩，意摇春夜思。
莫作遶山云，循环无定期。','',''),('quantangshi-20149','汴州留别韩愈','孟郊','quantangshi','','卷21','不饮浊水澜，空滞此汴河。
坐见遶岸水，尽为还海波。
四时不在家，弊服断线多。
远客独顦顇，春英落婆娑。
汴水饶曲流，野桑无直柯。
但为君子心，叹息终靡他。','',''),('quantangshi-20150','赠别殷山人说易后归幽墅','孟郊','quantangshi','','卷21','夫子说天地，若与灵龟言。
幽幽人不知，一一予所敦。
秋月吐白夜，凉风韵清源。
旁通忽已远，神感寂不喧。
一悟祛万结，夕怀倾朝烦。
旅輈无停波，别马嘶去辕。
殷勤荒草士，会有知己论。','',''),('quantangshi-20151','寿安西渡奉别郑相公 一','孟郊','quantangshi','','卷21','洛河向西道，石波横磷磷。
清风送君子，车远无还尘。
春别亦萧索，况兹冰霜晨。
零落景易入，郁抑抱难申。
百宵华灯宴，一旦星散人。
岁去弦吐箭，忧来蚕抽纶。
绵绵无穷事，各各驰遶身。
徘徊黄缥缈，倏忽春霜宾。
相为物表物，永谢区中姻。
日嗟来教士，仰望无由亲。','',''),('quantangshi-20152','寿安西渡奉别郑相公 二','孟郊','quantangshi','','卷21','东都清风减，君子西归朝。
独抱岁晏恨，泗吟不成谣。
贵游意多味，贱别情易消。
回雁忆前叫，浪凫念后漂。
悠悠孤飞景，耸耸衔霜条。
昧趣多滞涩，嬾朋寡新僚。
病深理方悟，悔至心自烧。
寂静道何在，忧勤学空饶。
乃知减闻见，始遂情逍遥。
文字徒营织，声华谅疑骄。
顾慙耕稼士，朴略气韵调。
善士有余食，佳畦冬生苗。
养人在养身，此旨清如韶。
愿贡高古言，敢望锡类招。','',''),('quantangshi-20153','宇文秀才斋中海柳咏','孟郊','quantangshi','','卷21','玉缕青葳蕤，结为芳树姿。
忽惊明月钩，钩出珊瑚枝。
灼灼不死花，蒙蒙长生丝。
饮栢泛仙味，咏兰拟古词。
霜风清飕飕，与君长相思。','',''),('quantangshi-20154','摇柳','孟郊','quantangshi','','卷21','弱弱本易惊，看看势难定。
因风似醉舞，尽日不能正。
时邀咏花女，笑辍春妆镜。','',''),('quantangshi-20155','晓鹤','孟郊','quantangshi','','卷21','晓鹤弹古舌，婆罗门叫音。
应吹天上律，不使尘中寻。
虚空梦皆断，歆唏安能禁。
如开孤月口，似说明星心。
既非人间韵，枉作人间禽。
不如相将去，碧落窠巢深。','',''),('quantangshi-20156','和蔷薇花歌','孟郊','quantangshi','','卷21','仙机札札织凤皇，花开七十有二行。
天霞落地攒红光，风枝袅袅时一扬。
飞散葩馥遶空王，忽惊锦浪洗新色。
又似宫娃逞妆饰，终当一使移花根，还比蒲桃天上植。','',''),('quantangshi-20157','邀人赏蔷薇','孟郊','quantangshi','','卷21','蜀色庶可比，楚丛亦应无。
醉红不自力，狂艳如索扶。
丽蘂惜未埽，宛枝长更纡。
何人是花侯，诗老强相呼。','',''),('quantangshi-20158','和宣州钱判官使院厅前石楠树','孟郊','quantangshi','','卷21','大朴既一剖，众材争万殊。
懿兹南海华，来与北壤俱。
生长如自惜，雪霜无凋渝。
笼笼抱灵秀，簇簇抽芳肤。
寒日吐丹艳，頳子流细珠。
鸳鸯花数重，翡翠叶四铺。
雨洗新妆色，一枝如一姝。
耸异敷庭际，倾妍来坐隅。
散彩饰机案，余辉盈盘盂。
高意因造化，常情逐荣枯。
主公方寸中，陶植在须臾。
养此奉君子，赏觌日为娱。
始觉石楠咏，价倾赋两都。
棠颂庶可比，桂词难以逾。
因谢丘墟木，空采落泥涂。
时来开佳姿，道去卧枯株。
争芳无由缘，受气如郁纡。
抽肝在郢匠，叹息何踟蹰。','',''),('quantangshi-20159','酬郑毗踯躅咏','孟郊','quantangshi','','卷21','不似人手致，岂关地势偏。
孤光褭余翠，独影舞多妍。
迸火烧闲地，红星堕青天。
忽惊物表物，嘉客为留连。','',''),('quantangshi-20160','品松','孟郊','quantangshi','','卷21','追悲谢灵运，不得殊常封。
纵然孔与颜，亦莫及此松。
此松天格高，耸异千万重。
抓拏巨灵手，擘裂少室峰。
擘裂风雨狞，抓拏指爪𦟛。
道入难抱心，学生易堕踪。
时时数点仙，袅袅一线龙。
霏微岚浪际，游戏颢兴浓。
品松徒高高，雌鸣讵噰噰。
赏异尚可贵，赏潜谁能容。
名华非典实，翦弃徒纤茸。
刻削大雅文，所以不敢慵。','',''),('quantangshi-20161','答李员外小榼味','孟郊','quantangshi','','卷21','一拳芙蓉水，倾玉何泠泠。
仙情夙已高，诗味今更馨。
试啜月入骨，再衔愁尽醒。
荷君道古诚，使我善飞翎。','',''),('quantangshi-20162','井上枸杞架','孟郊','quantangshi','','卷21','深锁银泉甃，高叶架云空。
不与凡木并，自将仙盖同。
影疎千点月，声细万条风。
迸子邻沟外，飘香客位中。
花杯承此饮，椿岁小无穷。','',''),('quantangshi-20163','蜘蛛讽','孟郊','quantangshi','','卷21','万类皆有性，各各禀天和。
蚕身与汝身，汝身何太讹。
蚕身不为己，汝身不为佗。
蚕丝为衣裳，汝丝为网罗。
济物几无功，害物日已多。
百虫虽切恨，其将奈尔何。','',''),('quantangshi-20164','蚊','孟郊','quantangshi','','卷21','五月中夜息，饥蚊尚营营。
但将膏血求，岂觉性命轻。
顾己宁自愧，饮人以偷生。
愿为天下幮，一使夜景清。','',''),('quantangshi-20165','烛蛾','孟郊','quantangshi','','卷21','灯前双舞蛾，厌生何太切。
想尔飞来心，恶明不恶灭。
天若百尺高，应去掩明月。','',''),('quantangshi-20166','和钱侍郎甘露','孟郊','quantangshi','','卷21','玄天何以言，瑞露青松繁。
忽见垂书迹，还惊涌澧源。
春枝晨袅袅，香味晓翻翻。
子礼忽来献，臣心固易敦。
清风惜不动，薄雾肯蒙昏。
嘉昼色更晶，仁慈久乃存。
一方难独占，天下恐争论。
侧听飞中使，重荣华德门。
从公乐万寿，余庆及儿孙。','',''),('quantangshi-20167','和令狐侍郎郭郎中题项羽庙','孟郊','quantangshi','','卷21','碧草凌古庙，清尘锁秋窗。
当时独宰割，猛志谁能降。
鼓气雷作敌，劒光电为双。
新悲徒自起，旧恨空浮江。','',''),('quantangshi-20168','读张碧集','孟郊','quantangshi','','卷21','天宝太白殁，六艺已消歇。
大哉国风本，丧而王泽竭。
先生今复生，斯文信难缺。
下笔证兴亡，陈词备风骨。
高秋数奏琴，澄潭一轮月。
谁作采诗官，忍之不挥发。','',''),('quantangshi-20169','听琴','孟郊','quantangshi','','卷21','飒飒微雨收，翻翻橡叶鸣。
月沈乱峰西，寥落三四星。
前溪忽调琴，隔林寒琤琤。
闻弹正弄声，不敢枕上听。
回烛整头簪，漱泉立中庭。
定步屐齿深，貌禅目冥冥。
微风吹衣襟，亦认宫征声。
学道三十年，未免忧死生。
闻弹一夜中，会尽天地情。','',''),('quantangshi-20170','闻夜啼赠刘正元','孟郊','quantangshi','','卷21','寄泣须寄黄河泉，此中怨声流彻天。
愁人独有夜灯见，一纸乡书泪滴穿。','',''),('quantangshi-20171','喜雨','孟郊','quantangshi','','卷21','朝见一片云，暮成千里雨。
凄清湿高枝，散漫沾荒土。','',''),('quantangshi-20172','终南山下作','孟郊','quantangshi','','卷21','见此原野秀，始知造化偏。
山村不假阴，流水自雨田。
家家梯碧峰，门门锁青烟。
因思蜕骨人，化作飞桂仙。','',''),('quantangshi-20173','观种树','孟郊','quantangshi','','卷21','种树皆待春，春至难久留。
君看朝夕花，谁免离别愁。
心意已零落，种之仍未休。
胡为好奇者，无事自买忧。','',''),('quantangshi-20174','春雨后','孟郊','quantangshi','','卷21','昨夜一霎雨，天意苏羣物。
何物最先知，虚庭草争出。','',''),('quantangshi-20175','答友人赠炭','孟郊','quantangshi','','卷21','青山白屋有仁人，赠炭价重双乌银。
驱却坐上千重寒，烧出炉中一片春。
吹霞弄日光不定，暖得曲身成直身。','',''),('quantangshi-20176','烂柯石','孟郊','quantangshi','','卷21','仙界一日内，人间千载穷。
双碁未徧局，万物皆为空。
樵客返归路，斧柯烂从风。
唯余石桥在，犹自凌丹虹。','',''),('quantangshi-20177','寻言上人','孟郊','quantangshi','','卷21','万里莓苔地，不见驱驰踪。
唯开文字窗，时写日月容。
竹韵漫萧屑，草花徒蒙茸。
披霜入众木，独自识青松。','',''),('quantangshi-20178','喷玉布','孟郊','quantangshi','','卷21','去尘咫尺步，山笑康乐岩。
天开紫石屏，泉缕明月帘。
仙凝刻削迹，灵绽云霞纤。
悦闻若有待，瞥见终无厌。
俗玩讵能近，道嬉方可淹。
踏着不死机，欲归多浮嫌。
古醉今忽醒，今求古仍潜。
古今相共失，语默两难恬。
赠君喷玉布，一濯高崭崭。','',''),('quantangshi-20179','姑蔑城','孟郊','quantangshi','','卷21','劲越既成土，强吴亦为墟。
皇风一已被，兹邑信平居。
抚俗观旧迹，行春布新书。
兴亡意何在，绵叹空踌蹰。','',''),('quantangshi-20180','峥嵘岭','孟郊','quantangshi','','卷21','疏凿顺高下，结构横烟霞。
坐啸郡斋肃，玩奇石路斜。
古树浮绿气，高门结朱华。
始见峥嵘状，仰止逾可嘉。','',''),('quantangshi-20181','寻裴处士','孟郊','quantangshi','','卷21','涉水更登陆，所向皆清真。
寒草不藏径，灵峰知有人。
悠哉炼金客，独与烟霞亲。
曾是欲轻举，谁言空隐沦。
远心寄白月，华发回青春。
对此钦胜事，胡为劳我身。','',''),('quantangshi-20182','子庆诗','孟郊','quantangshi','','卷21','王家事已奇，孟氏庆无涯。
献子还生子，羲之又有之。
凤兮且莫叹，鲤也会闻诗。
小小豫章甲，纤纤玉树姿。
人来唯仰乳，母抱未知慈。
我欲拣其养，放麛者是谁。','',''),('quantangshi-20183','憩淮上观公法堂','孟郊','quantangshi','','卷21','动觉日月短，静知时岁长。
自悲道路人，暂宿空闲堂。
孤烛让清昼，纱巾歛辉光。
高僧积素行，事外无刚强。
我有岩下桂，愿为炉中香。
不惜青翠姿，为君扬芬芳。
淮水色不污，汴流徒浑黄。
且将琉璃意，净缀芙蓉章。
明日还独行，羇愁来旧肠。','',''),('quantangshi-20184','江邑春霖奉赠陈侍御','孟郊','quantangshi','','卷21','江上花木冻，雨中零落春。
应由放忠直，在此成漂沦。
嘉艳皆损污，好音难殷勤。
天涯多远恨，雪涕盈芳辰。
坐哭青草上，卧吟幽水滨。
兴言念风俗，得意唯波鳞。
枕席病流湿，檐楹若飞津。
始知吴楚水，不及京洛尘。
风浦荡归棹，泥陂陷征轮。
两途日无遂，相赠唯沾巾。','',''),('quantangshi-20185','溧阳秋霁','孟郊','quantangshi','','卷21','晚雨晓犹在，萧寥激前阶。
星星满衰鬓，耿耿入秋怀。
旧识半零落，前心骤相乖。
饱泉亦恐醉，惕宦肃如斋。
上客处华池，下寮宅枯崖。
叩高占生物，龃龉回难谐。','',''),('quantangshi-20186','列仙文 方诸青童君','孟郊','quantangshi','','卷21','大霞霏晨晖，元气无常形。
玄辔飞霄外，八景乘高清。
手把玉皇袂，携我晨中生。
玄庭自嘉会，金书拆华名。
贤女密所妍，相期洛水軿。','',''),('quantangshi-20187','列仙文 清虚真人','孟郊','quantangshi','','卷21','歘驾空清虚，徘徊西华馆。
琼轮暨晨抄，虎骑逐烟散。
惠风振丹旌，明烛朗八焕。
解襟墉房内，神铃鸣璀璨。
栖景若林柯，九弦空中弹。
遗我积世忧，释此千载叹。
怡眄无极已，终夜复待旦。','',''),('quantangshi-20188','列仙文 金母飞空歌','孟郊','quantangshi','','卷21','驾我八景舆，歘然入玉清。
龙羣拂霄上，虎旗摄朱兵。
逍遥三弦际，万流无暂停。
哀此去留会，劫尽天地倾。
当寻无中景，不死亦不生。
体彼自然道，寂观合大冥。
南岳挺直干，玉英曜頴精。
有任靡期事，无心自虚灵。
嘉会绛河内，相与乐未英。','',''),('quantangshi-20189','列仙文 安度明','孟郊','quantangshi','','卷21','丹霞焕上清，八风鼓太和。
回我神霄辇，遂造岭玉阿。
咄嗟天地外，九围皆我家。
上采白日精，下饮黄月华。
灵观空无中，鹏路无间邪。
顾见魏贤安，浊气伤汝和。
勤研玄中思，道成更相过。','',''),('quantangshi-20190','夏日谒智远禅师','孟郊','quantangshi','','卷21','吾师当几祖，说法云无空。
禅心三界外，宴坐天地中。
院静鬼神去，身与草木同。
因知护王国，满钵盛毒龙。
抖擞尘埃衣，谒师见真宗。
何必千万劫，瞬息去樊笼。
盛夏火为日，一堂十月风。
不得为弟子，名姓挂儒宫。','',''),('quantangshi-20191','访嵩阳道士不遇','孟郊','quantangshi','','卷21','先生五兵游，文焰藏金鼎。
日下鹤过时，人间空落影。
常言一粒药，不堕生死境。
何当列御寇，去问仙人请。','',''),('quantangshi-20192','听蓝溪僧为元居士说维摩经','孟郊','quantangshi','','卷21','古树少枝叶，真僧亦相依。
山木自曲直，道人无是非。
手持维摩偈，心向居士归。
空景忽开霁，雪花犹在衣。
洗然水溪昼，寒物生光辉。','',''),('quantangshi-20193','借车','孟郊','quantangshi','','卷21','借车载家具，家具少于车。
借者莫弹指，贫穷何足嗟。
百年徒役走，万事尽随花。','',''),('quantangshi-20194','喜符郎诗有天纵','孟郊','quantangshi','','卷21','念符不由级，屹得文章阶。
白玉抽一毫，绿珉已难排。
偷笔作文章，乞墨潜磨揩。
海鲸始生尾，试摆蓬壶涡。
幸当禁止之，勿使恣狂怀。
自悲无子嗟，喜妬双喈喈。','',''),('quantangshi-20195','凭周况先辈于朝贤乞茶','孟郊','quantangshi','','卷21','道意勿乏味，心绪病无悰。
蒙茗玉花尽，越瓯荷叶空。
锦水有鲜色，蜀山饶芳藂。
云根才翦绿，印缝已霏红。
曾向贵人得，最将诗叟同。
幸为乞寄来，救此病劣躬。','',''),('quantangshi-20196','上昭成阁不得于从侄僧悟空院叹嗟','孟郊','quantangshi','','卷21','欲上千级阁，问天三四言。
未尽数十登，心目风浪翻。
手手把惊魄，脚脚踏坠魂。
却流至旧手，傍掣犹欲奔。
老病但自悲，古蠹木万痕。
老力安可夸，秋海萍一根。
孤叟何所归，昼眼如黄昏。
常恐失好步，入彼市井门。
结僧为亲情，策竹为子孙。
此诚徒切切，此意空存存。
一寸地上语，高天何由闻。','',''),('quantangshi-20197','魏博田兴尚书听嫂命不立非夫人诗','孟郊','quantangshi','','卷21','君子躭古礼，如馋鱼吞钩。
昨闻敬嫂言，掣心东北流。
魏博田尚书，与礼相绸缪。
善词闻天下，一日一再周。','',''),('quantangshi-20198','读经','孟郊','quantangshi','','卷21','垂老抱佛脚，教妻读黄经。
经黄名小品，一纸千明星。
曾读大般若，细感肸蠁听。
当时把斋中，方寸抱万灵。
忽复入长安，蹴踏日月宁。
老方却归来，收拾可丁丁。
拂拭尘几案，开函就孤亭。
儒书难借索，僧签饶芳馨。
驿驿不开手，铿铿闻异铃。
得善如焚香，去恶如脱腥。
安得颜子耳，曾未如此听。
听之何有言，德教贵有形。
何言中国外，有国如海萍。
海萍国教异，天声各泠泠。
安排未定时，心火竞荧荧。
将如庶几者，声尽形元冥。','',''),('quantangshi-20199','谢李輈再到','孟郊','quantangshi','','卷21','等闲拜日晚，夫妻独相疮。
况是贤人冤，何必哭飞杨。
昨夜梦得劒，为君藏中肠。
会将当风烹，血染布衣裳。
劳君又扣门，词句失寻常。
我不忍出厅，血字湿土墙。
血字耿不灭，我心惧惶惶。
会有铿锵夫，见之目生光。
生光非等闲，君其且安祥。','',''),('quantangshi-20200','忽不贫喜卢仝书船归洛','孟郊','quantangshi','','卷21','贫孟忽不贫，请问孟何如。
卢仝归洛船，崔嵬但载书。
江潮清翻翻，淮潮碧徐徐。
夜信为朝信，朝信良卷舒。
江淮君子水，相送仁有余。
我去官色衫，肩经入君庐。
喃喃肩经郎，言语倾琪琚。
琪琚铿好词，鸟鹊跃庭除。
书船平安归，喜报乡里闾。
我愿拾遗柴，巢经于空虚。
下免尘土侵，上为云霞居。
日月更相锁，道义分明储。
不愿空岧峣，但愿实工夫。
实空二理微，分别相起予。
经书荒芜多，为君勉勉锄。
勉勉不敢专，传之方在诸。','',''),('quantangshi-20201','吊国殇','孟郊','quantangshi','','卷21','徒言人最灵，白骨乱纵横。
如何当春死，不及羣草生。
尧舜宰干坤，器农不器兵。
秦汉盗山岳，铸杀不铸畊。
天地莫生金，生金人竞争。','',''),('quantangshi-20202','吊比干墓','孟郊','quantangshi','','卷21','殷辛帝天下，厌为天下尊。
干刚既一断，贤愚无二门。
佞是福身本，忠是丧己源。
饿虎不食子，人无骨肉恩。
日影不入地，下埋冤死魂。
有骨不为土，应作直木根。
今来过此乡，下马吊此坟。
静念君臣间，有道谁敢论。','',''),('quantangshi-20203','吊元鲁山 一','孟郊','quantangshi','','卷21','[搏]鸷有余饱，鲁山长饥空。
豪人饫鲜肥，鲁山饭蒿蓬。
食名皆霸官，食力乃尧农。
君子耻新态，鲁山与古终。
天璞本平一，人巧生异同。
鲁山不自剖，全璞竟没躬。','',''),('quantangshi-20204','吊元鲁山 二','孟郊','quantangshi','','卷21','自剖多是非，流滥将何归。
奔竞立诡节，凌侮争怪辉。
五常坐销铄，万类随衰微。
以兹见鲁山，道蹇无所依。','',''),('quantangshi-20205','吊元鲁山 三','孟郊','quantangshi','','卷21','君子不自蹇，鲁山蹇有因。
苟含天地秀，皆是天地身。
天地蹇既甚，鲁山道莫伸。
天地气不足，鲁山食更贫。
始知补元化，竟须得贤人。','',''),('quantangshi-20206','吊元鲁山 四','孟郊','quantangshi','','卷21','贤人多自霾，道理与俗乖。
细功不敢言，远韵方始谐。
万物饱为饱，万人怀为怀。
一声苟失所，众憾来相排。
所以元鲁山，饥衰难与偕。','',''),('quantangshi-20207','吊元鲁山 五','孟郊','quantangshi','','卷21','远阶无近级，造次不可升。
贤人洁肠胃，寒日空澄凝。
血誓竟讹谬，膏明易煎蒸。
以之驱鲁山，疎迹去莫乘。','',''),('quantangshi-20208','吊元鲁山 六','孟郊','quantangshi','','卷21','言从鲁山宦，尽化尧时心。
豺狼耻狂噬，齿牙闭霜金。
竞来辟田土，相与畊嵚岑。
当宵无关锁，竟岁饶歌吟。
善教复天术，美词非俗箴。
精微自然事，视听不可寻。
因书鲁山绩，庶合箫韶音。','',''),('quantangshi-20209','吊元鲁山 七','孟郊','quantangshi','','卷21','箫韶太平乐，鲁山不虚作。
千古若有知，百年幸如昨。
谁能嗣教化，以此洗浮薄。
君臣贵深遇，天地有灵橐。
力运既艰难，德符方合漠。
名位苟虚旷，声明自销铄。
礼法虽相救，贞浓易糟粕。
哀哀元鲁山，毕竟谁能度。','',''),('quantangshi-20210','吊元鲁山 八','孟郊','quantangshi','','卷21','当今富教化，元后得贤相。
冰心镜衰古，霜议清遐障。
幽埋尽洸洗，滞旅免流浪。
唯余鲁山名，未获旌廉让。
二三贞苦士，刷视耸危望。
发秋青山夜，目断丹阙亮。
诱类幸从兹，嘉招固非妄。
小生奏狂狷，感惕增万状。','',''),('quantangshi-20211','吊元鲁山 九','孟郊','quantangshi','','卷21','黄犊不知孝，鲁山自驾车。
非贤不可妻，鲁山竟无家。
供养耻佗力，言词岂纤瑕。
将谣鲁山德，赜海谁能涯。','',''),('quantangshi-20212','吊元鲁山 十','孟郊','quantangshi','','卷21','遗婴尽雏乳，何况骨肉枝。
心肠结苦诚，胸臆垂甘滋。
事已出古表，谁言独今奇。
贤人母万物，岂弟流前诗。','',''),('quantangshi-20213','哭李观','孟郊','quantangshi','','卷21','志士不得老，多为直气伤。
阮公终日哭，寿命固难长。
颜子既殂谢，孔门无辉光。
文星落奇曜，宝劒摧修铓。
常作金应石，忽为宫别商。
为尔吊琴瑟，断弦难再张。
偏毂不可转，只翼不可翔。
清尘无吹嘘，委地难飞扬。
此义古所重，此风今则亡。
自闻丧元宾，一日八九狂。
沈痛此丈夫，惊呼彼穹苍。
我有出俗韵，劳君疾恶肠。
知音既已矣，微言谁能彰。
旅葬无高坟，栽松不成行。
哀歌动寒日，赠泪沾晨霜。
神理本窅窅，今来更茫茫。
何以荡悲怀，万事付一觞。','',''),('quantangshi-20214','李少府厅吊李元宾遗字','孟郊','quantangshi','','卷21','零落三四字，忽成千万年。
那知冥寞客，不有补亡篇。
斜月吊空壁，旅人难独眠。
一生能几时，百虑来相煎。
戚戚故交泪，幽幽长夜泉。
已矣难重言，一言一潸然。','',''),('quantangshi-20215','悼吴兴汤衡评事','孟郊','quantangshi','','卷21','君生霅水清，君殁霅水浑。
空令骨肉情，哭得白日昏。
大夜不复晓，古松长闭门。
琴弦绿水绝，诗句青山存。
昔为芳春颜，今为荒草根。
独问冥冥理，先儒未曾言。','',''),('quantangshi-20216','哀孟云卿嵩阳荒居','孟郊','quantangshi','','卷21','戚戚抱幽独，宴宴沈荒居。
不闻新欢笑，但覩旧诗书。
艺蘖意弥苦，耕山食无余。
定交昔何在，至戚今或疎。
薄俗易销歇，淳风难久舒。
秋芜上空堂，寒槿落枯渠。
剃草恐伤蕙，摄衣自理锄。
残芳亦可饵，遗秀谁忍除。
徘徊未能去，为尔涕涟如。','',''),('quantangshi-20217','哭卢贞国','孟郊','quantangshi','','卷21','一别难与期，存亡易寒燠。
下马入君门，声悲不成哭。
自能富才艺，当冀深荣禄。
皇天负我贤，遗恨至两目。
平生叹无子，家家亲相嘱。','',''),('quantangshi-20218','伤旧游','孟郊','quantangshi','','卷21','去春会处今春归，花数不减人数稀。
朝笑片时暮成泣，东风一向还西辉。','',''),('quantangshi-20219','吊房十五次卿少府','孟郊','quantangshi','','卷21','日高方得起，独赏些些春。
可惜宛转鸎，好音与佗人。
昔年此气味，还走曲江滨。
逢着韩退之，结交方殷勤。
蜀客骨目高，聪辩劒戟新。
如何昨日欢，今日见无因。
英奇一谢世，视听一为尘。
谁言老泪短，泪短沾衣巾。','',''),('quantangshi-20220','逢江南故昼上人会中郑方回','孟郊','quantangshi','','卷21','相逢失意中，万感因语至。
追思东林日，掩抑北邙泪。
筐箧有遗文，江山旧清气。
尘生逍遥注，墨故飞动字。
荒毁碧涧居，虚无青松位。
珠沈百泉暗，月死羣象闭。
永谢平生言，知音岂容易。','',''),('quantangshi-20221','哭祕书包大监','孟郊','quantangshi','','卷21','哲人卧病日，贱子泣玉年。
常恐宝镜破，明月难再圆。
文字未改素，声容忽归玄。
始知知音稀，千载一绝弦。
旧馆有遗琴，清风那复传。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-20222','悼幼子','孟郊','quantangshi','','卷21','一闭黄蒿门，不闻白日事。
生气散成风，枯骸化为地。
负我十年恩，欠尔千行泪。
洒之北原上，不待秋风至。','',''),('quantangshi-20223','悼亡','孟郊','quantangshi','','卷21','山头明月夜增辉，增辉不照重泉下。
泉下双龙无再期，金蚕玉燕空销化。
朝云暮雨成古墟，萧萧野竹风吹亚。','',''),('quantangshi-20224','吊李元宾坟','孟郊','quantangshi','','卷21','晓上荒凉原，吊彼寂寥魂。
眼咽此时泪，耳凄在日言。
冥冥千万年，坟锁孤松根。','',''),('quantangshi-20225','览崔爽遗文因纾幽怀','孟郊','quantangshi','','卷21','堕泪数首文，悲结千里坟。
苍旻且留我，白日空遗君。
仙鹤未巢月，衰凤先坠云。
清风独起时，旧语如再闻。
瑶草罢葳蕤，桂花休氛氲。
万物与我心，相感吴江濆。','',''),('quantangshi-20226','峡哀 一','孟郊','quantangshi','','卷21','昔多相与笑，今谁相与哀。
峡哀哭幽魂，噭噭风吹来。
堕魄抱空月，出没难自裁。
齑粉一闪间，春涛百丈雷。
峡水声不平，碧沲牵清洄。
沙棱箭箭急，波齿齗齗开。
呀彼无底吮，待此不测灾。
谷号相喷激，石怒争旋回。
古醉有复乡，今缧多为能。
字孤徒仿髴，衔雪犹惊猜。
薄俗少直肠，交结须横财。
黄金买相吊，幽泣无余漼。
我有古心意，为君空摧颓。','',''),('quantangshi-20227','峡哀 二','孟郊','quantangshi','','卷21','上天下天水，出地入地舟。
石劒相劈斫，石波怒蛟虬。
花木叠宿春，风飙凝古秋。
幽怪窟穴语，飞闻肸蠁流。
沈哀日已深，衔诉将何求。','',''),('quantangshi-20228','峡哀 三','孟郊','quantangshi','','卷21','三峡一线天，三峡万绳泉。
上仄碎日月，下掣狂漪涟。
破魂一两点，凝幽数百年。
峡晖不停午，峡险多饥涎。
树根锁枯棺，孤骨褭褭悬。
树枝哭霜栖，哀韵杳杳鲜。
逐客零落肠，到此汤火煎。
性命如纺绩，道路随索缘。
奠泪吊波灵，波灵将闪然。','',''),('quantangshi-20229','峡哀 四','孟郊','quantangshi','','卷21','峡乱鸣清磬，产石为鲜鳞。
喷为腥雨涎，吹作黑井身。
怪光闪众异，饿劒唯待人。
老肠未曾饱，古齿崭岩嗔。
嚼齿三峡泉，三峡声齗齗。','',''),('quantangshi-20230','峡哀 五','孟郊','quantangshi','','卷21','峡螭老解语，百丈潭底闻。
毒波为计校，饮血养子孙。
既非臯陶吏，空食沈狱魂。
潜怪何幽幽，魄说徒云云。
峡听哀哭泉，峡吊鳏寡猿。
峡声非人声，劒水相劈翻。
斯谁士诸谢，奏此沉苦言。','',''),('quantangshi-20231','峡哀 六','孟郊','quantangshi','','卷21','谗人峡虬心，渴罪呀然浔。
所食无直肠，所语饶枭音。
石齿嚼百泉，石风号千琴。
幽哀莫能远，分雪何由寻。
月魄高卓卓，峡窟清沉沉。
衔诉何时明，抱痛已不禁。
犀飞空波涛，裂石千嵚岑。','',''),('quantangshi-20232','峡哀 七','孟郊','quantangshi','','卷21','峡棱剸日月，日月多摧辉。
物皆斜仄生，鸟亦斜仄飞。
潜石齿相锁，沉魂招莫归。
恍惚清泉甲，斑斓碧石衣。
饿咽潺湲号，涎似泓浤肥。
峡青不可游，腥草生微微。','',''),('quantangshi-20233','峡哀 八','孟郊','quantangshi','','卷21','峡景滑易堕，峡花怪非春。
红光根潜涎，碧雨飞沃津。
巴谷蛟螭心，巴乡魍魉亲。
噉生不问贤，至死独养身。
腥语信者谁，拗歌欢非真。
仄田无异稼，毒水多狞鳞。
异类不可友，峡哀哀难伸。','',''),('quantangshi-20234','峡哀 九','孟郊','quantangshi','','卷21','峡水劒戟狞，峡舟霹雳翔。
因依虺蜴手，起坐风雨忙。
峡旅多窜官，峡氓多非良。
滑心不可求，滑习积已长。
漠漠涎雾起，齗齗涎水光。
渴贤如之何，忽在水中央。','',''),('quantangshi-20235','峡哀 十','孟郊','quantangshi','','卷21','枭鸱作人语，蛟虬吸水波。
能于白日间，谄欲晴风和。
骇智蹶众命，蕴腥布深萝。
齿泉无底贫，锯涎在处多。
仄树鸟不巢，踔𨃚猿相过。
峡哀不可听，峡怨其奈何。','',''),('quantangshi-20236','杏殇 一','孟郊','quantangshi','','卷21','冻手莫弄珠，弄珠珠易飞。
惊霜莫翦春，翦春无光辉。
零落小花乳，斓斑昔婴衣。
拾之不盈把，日暮空悲归。','',''),('quantangshi-20237','杏殇 二','孟郊','quantangshi','','卷21','地上空拾星，枝上不见花。
哀哀孤老人，戚戚无子家。
岂若没水凫，不如拾巢鸦。
浪鷇破便飞，风雏褭相夸。
芳婴不复生，向物空悲嗟。','',''),('quantangshi-20238','杏殇 三','孟郊','quantangshi','','卷21','应是一线泪，入此春木心。
枝枝不成花，片片落翦金。
春寿何可长，霜哀亦已深。
常时洗芳泉，此日洗泪襟。','',''),('quantangshi-20239','杏殇 四','孟郊','quantangshi','','卷21','儿生月不明，儿死月始光。
儿月两相夺，儿命果不长。
如何此英英，亦为吊苍苍。
甘为堕地尘，不为末世芳。','',''),('quantangshi-20240','杏殇 五','孟郊','quantangshi','','卷21','踏地恐土痛，损彼芳树根。
此诚天不知，翦弃我子孙。
垂枝有千落，芳命无一存。
谁谓生人家，春色不入门。','',''),('quantangshi-20241','杏殇 六','孟郊','quantangshi','','卷21','冽冽霜杀春，枝枝疑纤刀。
木心既零落，山窍空呼号。
班班落地英，点点如明膏。
始知天地间，万物皆不牢。','',''),('quantangshi-20242','杏殇 七','孟郊','quantangshi','','卷21','哭此不成春，泪痕三四斑。
失芳蝶既狂，失子老亦孱。
且无生生力，自有死死颜。
灵凤不衔诉，谁为扣天关。','',''),('quantangshi-20243','杏殇 八','孟郊','quantangshi','','卷21','此儿自见灾，花发多不谐。
穷老收碎心，永夜抱破怀。
声死更何言，意死不必喈。
病叟无子孙，独立犹束柴。','',''),('quantangshi-20244','杏殇 九','孟郊','quantangshi','','卷21','霜似败红芳，剪啄十数双。
参差呻细风，噞喁沸浅江。
泣凝不可消，恨壮难自降。
空遗旧日影，怨彼小书窗。','',''),('quantangshi-20245','吊江南老家人春梅','孟郊','quantangshi','','卷21','念尔筋力尽，违我衣食恩。
奈何粗犷儿，生鞭见死痕。
旧使常以礼，新怨将谁吞。
胡为乎泥中，消歇教义源。','',''),('quantangshi-20246','哭李丹员外并寄杜中丞','孟郊','quantangshi','','卷21','生死方知交态存，忍将齚齖报幽魂。
十年同在平原客，更遣何人哭寝门。','',''),('quantangshi-20247','哭刘言史','孟郊','quantangshi','','卷21','诗人业孤峭，饿死良已多。
相悲与相笑，累累其奈何。
精异刘言史，诗肠倾珠河。
取次抱置之，飞过东溟波。
可惜大国谣，飘为四夷歌。
常于众中会，颜色两切[磋]。
今日果成死，葬襄之洛河。
洛岸远相吊，洒泪双滂沱。','',''),('quantangshi-20248','吊卢殷 一','孟郊','quantangshi','','卷21','诗人多清峭，饿死抱空山。
白云既无主，飞出意等闲。
久病牀席尸，护丧童仆孱。
故书穷鼠啮，狼藉一室间。
君归新鬼乡，我面古玉颜。
羞见入地时，无人叫追攀。
百泉空相吊，日久哀潺潺。','',''),('quantangshi-20249','吊卢殷 二','孟郊','quantangshi','','卷21','唧唧复唧唧，千古一月色。
新新复新新，千古一花春。
邙风噫孟郊，嵩秋葬卢殷。
北邙前后客，相吊为埃尘。
北邙棘针草，泪根生苦辛。
烟火不自暖，筋力早已贫。
幽荐一杯泣，泻之清洛滨。
添为断肠声，愁杀长别人。','',''),('quantangshi-20250','吊卢殷 三','孟郊','quantangshi','','卷21','棘针风相号，破碎诸苦哀。
苦哀不可闻，掩耳亦入来。
哭弦多煎声，恨涕有余摧。
噫贫气已焚，噫死心更灰。
梦世浮闪闪，泪波深洄洄。
薤歌一以去，蒿闭不复开。','',''),('quantangshi-20251','吊卢殷 四','孟郊','quantangshi','','卷21','登封草木深，登封道路微。
日月不与光，莓苔空生衣。
可怜无子翁，蚍蜉缘病肌。
挛卧岁时长，涟涟但幽噫。
幽噫虎豹闻，此外相访稀。
至亲唯有诗，抱心死有归。
河南韩先生，后君作因依。
磨一片嵌岩，书千古光辉。','',''),('quantangshi-20252','吊卢殷 五','孟郊','quantangshi','','卷21','贤人无计较，生苦死徒夸。
佗名润子孙，君名润泥沙。
可惜千首文，闪如一朝花。
零落难苦言，起坐空惊嗟。','',''),('quantangshi-20253','吊卢殷 六','孟郊','quantangshi','','卷21','耳闻陋巷生，眼见鲁山君。
饿死始有名，饿名高氛氲。
戆叟老壮气，感之为忧云。
所忧唯一泣，古今相纷纷。
平生与君说，逮此俱云云。','',''),('quantangshi-20254','吊卢殷 七','孟郊','quantangshi','','卷21','初识漆鬓发，争为新文章。
夜踏明月桥，店饮吾曹床。
醉啜二杯酿，名郁一县香。
寺中摘梅花，园里翦浮芳。
高嗜绿蔬羹，意轻肥腻羊。
吟哦无滓韵，言语多古肠。
白首忽然至，盛年如偷将。
清浊俱莫追，何须駡沧浪。','',''),('quantangshi-20255','吊卢殷 八','孟郊','quantangshi','','卷21','前贤多哭酒，哭酒免哭心。
后贤试衔之，哀至无不深。
少年哭酒时，白发亦已侵。
老年哭酒时，声韵随生沈。
寄言哭酒宾，勿作登封音。
登封徒放声，天地竟难寻。','',''),('quantangshi-20256','吊卢殷 九','孟郊','quantangshi','','卷21','同人少相哭，异类多相号。
始知禽兽痴，却至天然高。
非子病无泪，非父念莫劳。
如何裁亲疎，用礼如用刀。
孤丧鲜匍匐，闭哀抱郁陶。
烦他手中葬，诚信焉能褒。
嗟嗟无子翁，死弃如脱毛。','',''),('quantangshi-20257','吊卢殷 十','孟郊','quantangshi','','卷21','圣人哭贤人，骨化气为星。
文章飞上天，列宿增晶荧。
前古文可数，今人文亦灵。
高名称谪仙，升降曾莫停。
有文死更香，无文生亦腥。
为君铿好辞，永传作谧宁。','',''),('quantangshi-20258','寄远曲','張籍','quantangshi','','卷21','美人来去春江暖，江头无人湘水满。
浣沙石上水禽栖，江南路长春日短。
兰舟桂楫常渡江，无因重寄双琼璫。','',''),('quantangshi-20259','行路难','張籍','quantangshi','','卷21','湘东行人长叹息，十年离家归未得。
弊裘羸马苦难行，僮仆饥寒少筋力。
君不见牀头黄金尽，壮士无颜色。
龙蟠泥中未有云，不能生彼升天翼。','',''),('quantangshi-20260','征妇怨','張籍','quantangshi','','卷21','九月匈奴杀边将，汉军全没辽水上。
万里无人收白骨，家家城下招魂葬。
妇人依倚子与夫，同居贫贱心亦舒。
夫死战场子在腹，妾身虽存如昼烛。','',''),('quantangshi-20261','白紵歌','張籍','quantangshi','','卷21','皎皎白紵白且鲜，将作春衣称少年。
裁缝长短不能定，自持刀尺向姑前。
复恐兰膏污纤指，常遣傍人收堕珥。
衣裳着时寒食下，还把玉鞭鞭白马。','',''),('quantangshi-20262','野老歌','張籍','quantangshi','','卷21','老农家贫在山住，耕种山田三四亩。
苗疎税多不得食，输入官仓化为土。
岁暮锄犂傍空室，呼儿登山收橡实。
西江贾客珠百斛，船中养犬长食肉。','',''),('quantangshi-20263','寄衣曲','張籍','quantangshi','','卷21','织素缝衣独苦辛，远因回使寄征人。
官家亦自寄衣去，贵从妾手着君身。
高堂姑老无侍子，不得自到边城里。
殷勤为看初着时，征夫身上宜不宜。','',''),('quantangshi-20264','送远曲','張籍','quantangshi','','卷21','戏马台南山簇簇，山边饮酒歌别曲。
行人醉后起登车，席上回尊劝僮仆。
青天漫漫覆长路，远游无家安得住。
愿君到处自题名，他日知君从此去。','',''),('quantangshi-20265','筑城词','張籍','quantangshi','','卷21','筑城处，千人万人齐把杵。
重重土坚试行锥，军吏执鞭催作迟。
来时一年深碛里，尽着短衣渴无水。
力尽不得抛杵声，杵声未尽人皆死。
家家养男当门户，今日作君城下土。','',''),('quantangshi-20266','猛虎行','張籍','quantangshi','','卷21','南山北山树冥冥，猛虎白日绕林行。
向晚一身当道食，山中麋鹿尽无声。
年年养子在空谷，雌雄上山不相逐。
谷中近窟有山村，长向村家取黄犊。
五陵年少不敢射，空来林下看行迹。','',''),('quantangshi-20267','别离曲','張籍','quantangshi','','卷21','行人结束出门去，几时更踏门前路。
忆昔君初纳采时，不言身属辽阳戍。
早知今日当别离，成君家计良为谁。
男儿生身自有役，那得误我少年时。
不如逐君征战死，谁能独老空闺里。','',''),('quantangshi-20268','牧童词','張籍','quantangshi','','卷21','远牧牛，遶村四面禾黍稠。
陂中饥乌啄牛背，令我不得戏壠头。
入陂草多牛散行，白犊时向芦中鸣。
隔堤吹叶应同伴，还鼓长鞭三四声。
牛牛食草莫相触，官家截尔头上角。','',''),('quantangshi-20269','沙堤行呈裴相公','張籍','quantangshi','','卷21','长安大道沙为堤，早风无尘雨无泥。
宫中玉漏下三刻，朱衣导骑丞相来。
路傍高楼息歌吹，千车不行行者避。
街官闾吏相传呼，当前十里惟空衢。
白麻诏下移相印，新堤未成旧堤尽。','',''),('quantangshi-20270','求仙行','張籍','quantangshi','','卷21','汉皇欲作飞仙子，年年采药东海里。
蓬莱无路海无边，方士舟中相枕死。
招摇在天回白日，甘泉玉树无仙实。
九皇真人终不下，空向离宫祠太乙。
丹田有气凝素华，君能保之升绛霞。','',''),('quantangshi-20271','古钗叹','張籍','quantangshi','','卷21','古钗堕井无颜色，百尺泥中今复得。
凤凰宛转有古仪，欲为首饰不称时。
女伴传看不知主，罗袖拂拭生光辉。
兰膏已尽股半折，雕文刻样无年月。
虽离井底入匣中，不用还与坠时同。','',''),('quantangshi-20272','各东西','張籍','quantangshi','','卷21','游人别，一东复一西。
出门相背两不返，惟信车轮与马蹄。
道路悠悠不知处，山高海阔谁辛苦。
远游不定难寄书，日日空寻别时语。
浮云上天雨堕地，暂时会合终离异。
我今与子非一身，安得死生不相弃。','',''),('quantangshi-20273','节妇吟寄东平李司空师道','張籍','quantangshi','','卷21','君知妾有夫，赠妾双明珠。
感君缠绵意，系在红罗襦。
妾家高楼连苑起，良人执戟明光里。
知君用心如日月，事夫誓拟同生死。','',''),('quantangshi-20274','宴客词','張籍','quantangshi','','卷21','上客不用顾金羁，主人有酒君莫违。
请君看取园中花，地上渐多枝上稀。
山头树影不见石，溪水无风应更碧。
人人齐醉起舞时，谁觉翻衣与倒帻。
明朝花尽人已去，此地独来空绕树。','',''),('quantangshi-20275','永嘉行','張籍','quantangshi','','卷21','黄头鲜卑入洛阳，胡儿执戟升明堂。
晋家天子作降虏，公卿奔走如牛羊。
紫陌旌幡暗相触，家家鸡犬惊上屋。
妇人出门随乱兵，夫死眼前不敢哭。
九州诸侯自顾土，无人领兵来护主。
北人避胡多在南，南人至今能晋语。','',''),('quantangshi-20276','采莲曲','張籍','quantangshi','','卷21','秋江岸边莲子多，采莲女儿凭船歌。
青房圆实齐戢戢，争前竞折漾微波。
试牵绿茎下寻藕，断处丝多刺伤手。
白练束腰袖半卷，不插玉钗妆梳浅。
船中未满度前洲，借问阿谁家住远。
归时共待暮潮上，自弄芙蓉还荡桨。','',''),('quantangshi-20277','伤歌行','張籍','quantangshi','','卷21','黄门诏下促收捕，京兆尹系御史府。
出门无复部曲随，亲戚相逢不容语。
辞成谪尉南海州，受命不得须臾留。
身着青衫骑恶马，中门之外无送者。
邮夫防吏急喧驱，往往惊堕马蹄下。
长安里中荒大宅，朱门已除十二戟。
高堂舞榭锁管弦，美人遥望西南天。','',''),('quantangshi-20278','吴宫怨','張籍','quantangshi','','卷21','吴宫四面秋江水，江清露白芙蓉死。
吴王醉后欲更衣，座上美人娇不起。
宫中千门复万户，君恩反覆谁能数。
君心与妾既不同，徒向君前作歌舞。
茱萸满宫红实垂，秋风袅袅生繁枝。
姑苏台上夕燕罢，佗人侍寝还独归。
白日在天光在地，君今那得长相弃。','',''),('quantangshi-20279','北邙行','張籍','quantangshi','','卷21','洛阳北门北邙道，丧车辚辚入秋草。
车前齐唱薤露歌，高坟新起白峨峨。
朝朝暮暮人送葬，洛阳城中人更多。
千金立碑高百尺，终作谁家柱下石。
山头松柏半无主，地下白骨多于土。
寒食家家送纸钱，乌鸢作窠衔上树。
人居朝市未解愁，请君暂向北邙游。','',''),('quantangshi-20280','关山月','張籍','quantangshi','','卷21','秋月朗朗关山上，山中行人马蹄响。
关山秋来雨雪多，行人见月唱边歌。
海边茫茫天气白，胡儿夜度黄龙碛。
军中探骑暮出城，伏兵暗处低旌戟。
溪水连天霜草平，野驼寻水碛中鸣。
陇头风急雁不下，沙场苦战多流星。
可怜万国关山道，年年战骨多秋草。','',''),('quantangshi-20281','陇头行','張籍','quantangshi','','卷21','陇头路断人不行，胡骑夜入凉州城。
汉兵处处格鬬死，一朝尽没陇西地。
驱我边人胡中去，散放牛羊食禾黍。
去年中国养子孙，今着毡裘学胡语。
谁能更使李轻车，收取凉州入汉家。','',''),('quantangshi-20282','楚妃叹','張籍','quantangshi','','卷21','湘云初起江沉沉，君王遥在云梦林。
江南雨多旌旗暗，台下朝朝春水深。
章华殿前朝万国，君心独自无终极。
楚兵满地能逐禽，谁用一身骋筋力。
西江若飜云梦中，麋鹿死尽应还宫。','',''),('quantangshi-20283','春日行','張籍','quantangshi','','卷21','春日融融池上暖，竹牙出土兰心短。
草堂晨起酒半醒，家僮报我园花满。
头上皮冠未曾整，直入花间不寻径。
树树殷勤尽遶行，攀枝未徧春日暝。
不用积金着青天，不用服药求神仙。
但愿园里花长好，一生饮酒花前老。','',''),('quantangshi-20284','秋夜长','張籍','quantangshi','','卷21','秋天如水夜未央，天汉东西月色光。
愁人不寐畏枕席，暗虫唧唧遶我傍。
荒城为村无更声，起看北斗天未明。
白露满田风袅袅，千声万声鹖鸟鸣。','',''),('quantangshi-20285','白鼍鸣','張籍','quantangshi','','卷21','天欲雨，有东风，南溪白鼍鸣窟中。
六月人家井无水，夜闻鼍声人尽起。','',''),('quantangshi-20286','洛阳行','張籍','quantangshi','','卷21','洛阳宫阙当中州，城上峨峨十二楼。
翠华西去几时返，枭巢乳鸟藏蛰燕。
御门空锁五十年，税彼农夫修玉殿。
六街朝暮鼓冬冬，禁兵持戟守空宫。
百官月月拜章表，驿使相续长安道。
上阳宫树黄复绿，野豺入苑食麋鹿。
陌上老翁双泪垂，共说武皇巡幸时。','',''),('quantangshi-20287','春江曲','張籍','quantangshi','','卷21','春江无云潮水平，蒲心出水凫雏鸣。
长干夫壻爱远行，自染春衣缝已成。
妾身生长金陵侧，去年随夫住江北。
春来未到父母家，舟小风多渡不得。
欲辞舅姑先问人，私向江头祭水神。','',''),('quantangshi-20288','送远曲','張籍','quantangshi','','卷21','吴门向西流水长，水长柳暗烟茫茫。
行人送客各惆怅，话离叙别倾清觞。
吟丝竹，鸣笙簧，酒酣性逸歌猖狂。
行人告我挂帆去，此去何时返故乡。
殷勤振衣两相嘱，世事近来还浅促。
愿君看取吴门山，带雪经春依旧绿。
行人行处求知亲，送君去去徒酸辛。','',''),('quantangshi-20289','塞下曲','張籍','quantangshi','','卷21','边州八月修城堡，候骑先烧碛中草。
胡风吹沙度陇飞，陇头林木无北枝。
将军阅兵青塞下，鸣鼓逢逢促猎围。
天寒山路石断裂，白日不销帐上雪。
乌孙国乱多降胡，诏使名王持汉节。
年年征战不得闲，边人杀尽唯空山。','',''),('quantangshi-20290','董逃行','張籍','quantangshi','','卷21','洛阳城头火曈曈，乱兵烧我天子宫。
宫城南面有深山，尽将老幼藏其间。
重岩为屋橡为食，丁男夜行候消息。
闻道官军犹掠人，旧里如今归未得。
董逃行，汉家几时重太平。','',''),('quantangshi-20291','少年行','張籍','quantangshi','','卷21','少年从猎出长杨，禁中新拜羽林郎。
独对辇前射双虎，君王手赐黄金璫。
日日鬬鸡都市里，赢得宝刀重刻字。
百里报仇夜出城，平明还在娼楼醉。
遥闻虏到平陵下，不待诏书行上马。
斩得名王献桂宫，封侯起第一日中。
不为六郡良家子，百战始取边城功。','',''),('quantangshi-20292','白头吟','張籍','quantangshi','','卷21','请君漆上琴，弹我白头吟。
忆昔君前娇笑语，两情宛转如萦素。
宫中为我起高楼，更开花池种芳树。
春天百草秋始衰，弃我不待白头时。
罗襦玉珥色未暗，今朝已道不相宜。
扬州青铜作明镜，暗中持照不见影。
人心回互自无穷，眼前好恶那能定。
君恩已去若再返，菖蒲花开月长满。','',''),('quantangshi-20293','将军行','張籍','quantangshi','','卷21','弹筝峡东有胡尘，天子择日拜将军。
蓬莱殿前赐六纛，还领禁兵为部曲。
当朝受诏不辞家，夜向咸阳原上宿。
战车彭彭旌旗动，三十六军齐上陇。
陇头战胜夜亦行，分兵处处收旧城。
胡儿杀尽阴碛暮，扰扰唯有牛羊声。
边人亲戚曾战没，今逐官军收旧骨。
碛西行见万里空，幕府独奏将军功。','',''),('quantangshi-20294','贾客乐','張籍','quantangshi','','卷21','金陵向西贾客多，船中生长乐风波。
欲发移船近江口，船头祭神各浇酒。
停杯共说远行期，入蜀经蛮谁别离。
金多众中为上客，夜夜算缗眠独迟。
秋江初月猩猩语，孤帆夜发潇湘渚。
水工持檝防暗滩，直过山边及前侣。
年年逐利西复东，姓名不在县籍中。
农夫税多长辛苦，弃业长为贩宝翁。','',''),('quantangshi-20295','羁旅行','張籍','quantangshi','','卷21','远客出门行路难，停车敛策在门端。
荒城无人霜满路，野火烧桥不得度。
寒虫入窟鸟归巢，僮仆问我谁家去。
行寻田头暝未息，双毂长辕碍荆棘。
缘冈入涧投田家，主人舂米为夜食。
晨鸡喔喔茅屋傍，行人起扫车上霜。
旧山已别行已远，身计未成难复返。
长安陌上相识稀，遥望天山白日晚。
谁能听我辛苦行，为向君前歌一声。','',''),('quantangshi-20296','车遥遥','張籍','quantangshi','','卷21','征人遥遥出古城，双轮齐动驷马鸣。
山川无处不归路，念君长作万里行。
野田人稀秋草绿，日暮放马车中宿。
惊麏游兔在我傍，独唱乡歌对僮仆。
君家大宅凤城隅，年年道上随行车。
愿为玉銮系华轼，终日有声在君侧。
门前旧辙久已平，无由复得君消息。','',''),('quantangshi-20297','妾薄命','張籍','quantangshi','','卷21','薄命妇，良家子，无事从军去万里。
汉家天子平四夷，护羌都尉裹尸归。
念君此行为死别，对君裁缝泉下衣。
与君一日为夫妇，千年万岁亦相守。
君爱龙城征战功，妾愿青楼歌乐同。
人生各各有所欲，讵得将心入君腹。','',''),('quantangshi-20298','朱鹭','張籍','quantangshi','','卷21','翩翩兮朱鹭，来泛春塘栖绿树。
羽毛如翦色如染，远飞欲下双翅敛。
避人引子入深壍，动处水纹开滟滟。
谁知豪家网尔躯，不如饮啄江海隅。','',''),('quantangshi-20299','远别离','張籍','quantangshi','','卷21','莲叶团团杏花拆，长江鲤鱼鬐鬣赤。
念君少年弃亲戚，千里万里独为客。
谁言远别心不易，天星坠地能为石。
几时断得城南陌，勿使居人有行役。','',''),('quantangshi-20300','楚宫行','張籍','quantangshi','','卷21','章华宫中九月时，桂花半落红橘垂。
江头骑火照辇道，君王夜从云梦归。
霓旌凤盖到双阙，台上重重歌吹发。
千门万户开相当，烛笼左右列成行。
下辇更衣入洞房，洞房侍女尽焚香。
玉阶罗幕微有霜，齐言此夕乐未央。
玉酒湛湛盈华觞，丝竹次第鸣中堂。
巴姬起舞向君王，回身垂手结明璫。
愿君千年万年寿，朝出射麋夜饮酒。','',''),('quantangshi-20301','江南行','張籍','quantangshi','','卷21','江南人家多橘树，吴姬舟上织白苎。
土地卑湿饶虫蛇，连木为牌入江住。
江村亥日长为市，落帆度桥来蒲里。
清莎覆城竹为屋，无井家家饮潮水。
长干午日沽春酒，高高酒旗悬江口。
娼楼两岸临水栅，夜唱竹枝留北客。
江南风土欢乐多，悠悠处处尽经过。','',''),('quantangshi-20302','乌夜啼引','張籍','quantangshi','','卷21','秦乌啼哑哑，夜啼长安吏人家。
吏人得罪囚在狱，倾家卖产将自赎。
少妇起听夜啼乌，知是官家有赦书。
下牀心喜不重寐，未明上堂贺舅姑。
少妇语啼乌，汝啼慎勿虚。
借汝庭树作高巢，年年不令伤尔雏。','',''),('quantangshi-20303','促促词','張籍','quantangshi','','卷21','促促复促促，家贫夫妇欢不足。
今年为人送租船，去年捕鱼在江边。
家中姑老子复小，自执吴绡输税钱。
家家桑麻满地黑，念君一身空努力。
愿教牛蹄团团羊角直，君身常在应不得。','',''),('quantangshi-20304','宛转行','張籍','quantangshi','','卷21','华屋重翠幄，绮席雕象牀。
远漏微更疎，薄衾中夜凉。
炉气暗裴徊，寒灯背斜光。
妍姿结宵态，寝臂幽梦长。
宛转复宛转，忆君更未央。','',''),('quantangshi-20305','短歌行','張籍','quantangshi','','卷21','青天荡荡高且虚，上有白日无根株。
流光暂出还入地，使我年少不须臾。
与君相逢勿寂寞，衰老不复如今乐。
玉巵盛酒置君前，再拜愿君千万年。','',''),('quantangshi-20306','山头鹿','張籍','quantangshi','','卷21','山头鹿，角芟芟，尾促促。
贫儿多租输不足，夫死未葬儿在狱。
早日熬熬蒸野冈，禾黍不收无狱粮。
县家唯忧少军食，谁能令尔无死伤。','',''),('quantangshi-20307','湘江曲','張籍','quantangshi','','卷21','湘水无潮秋水阔，湘中月落行人发。
送人发，送人归，白苹茫茫鹧鸪飞。','',''),('quantangshi-20308','楚妃怨','張籍','quantangshi','','卷21','梧桐叶下黄金井，横架辘轳牵素绠。
美人初起天未明，手拂银瓶秋水冷。','',''),('quantangshi-20309','离宫怨','張籍','quantangshi','','卷21','高堂别馆连湘渚，长向春光开万户。
荆王去去不复来，宫中美人自歌舞。','',''),('quantangshi-20310','成都曲','張籍','quantangshi','','卷21','锦江近西烟水绿，新雨山头荔枝熟。
万里桥边多酒家，游人爱向谁家宿。','',''),('quantangshi-20311','寒塘曲','張籍','quantangshi','','卷21','寒塘沉沉柳叶疎，水暗人语惊栖凫。
舟中少年醉不起，持烛照水射游鱼。','',''),('quantangshi-20312','春别曲','張籍','quantangshi','','卷21','长江春水绿堪染，莲叶出水大如钱。
江头橘树君自种，那不长系木兰船。','',''),('quantangshi-20313','春堤曲','張籍','quantangshi','','卷21','野塘䴔䴖飞树头，绿蒲紫菱盖碧流。
狂客谁家爱云水，日日独来城下游。','',''),('quantangshi-20314','乌栖曲','張籍','quantangshi','','卷21','西山作宫潮满池，宫鸟晓鸣茱萸枝。
吴姬采莲自唱曲，君王昨夜舟中宿。','',''),('quantangshi-20315','雀飞多','張籍','quantangshi','','卷21','雀飞多，触网罗，网罗高树颠。
汝飞蓬蒿下，勿复投身网罗间。
粟积仓，禾在田。
巢之雏，望其母来还。','',''),('quantangshi-20316','泗水行','張籍','quantangshi','','卷21','泗水流急石纂纂，鲤鱼上下红尾短。
春冰销散日华满，行舟往来浮桥断。
城边鱼市人早行，水烟漠漠多棹声。','',''),('quantangshi-20317','废居行','張籍','quantangshi','','卷21','胡马崩腾满阡陌，都人避乱唯空宅。
宅边青桑垂宛宛，野蚕食叶还成茧。
黄雀衔草入燕窠，啧啧啾啾白日晚。
去时禾黍埋地中，饥兵掘土翻重重。
鸱枭养子庭树上，曲墙空屋多旋风。
乱定几人还本土，唯有官家重作主。','',''),('quantangshi-20318','寄菖蒲','張籍','quantangshi','','卷21','石上生菖蒲，一寸十二节。
仙人劝我食，令我头青面如雪。
逢人寄君一绛囊，书中不得传此方。
君能来作栖霞侣，与君同入丹玄乡。','',''),('quantangshi-20319','江村行','張籍','quantangshi','','卷21','南塘水深芦笋齐，下田种稻不作畦。
耕场磷磷在水底，短衣半染芦中泥。
田头刈莎结为屋，归来系牛还独宿。
水淹手足尽有疮，山蝱遶身飞扬扬。
桑林椹黑蚕再眠，妇姑采桑不向田。
江南热旱天气毒，雨中移秧颜色鲜。
一年耕种长苦辛，田熟家家将赛神。','',''),('quantangshi-20320','樵客吟','張籍','quantangshi','','卷21','上山采樵选枯树，深处樵多出辛苦。
秋来野火烧栎林，枝柯已枯堪采取。
斧声坎坎在幽谷，采得齐梢青葛束。
日西待伴同下山，竹担弯弯向身曲。
共知路傍多虎窟，未出深林不敢歇。
村西地暗狐兔行，稚子呌时相应声。
采樵客，莫采松与栢。
松栢生枝直且坚，与君作屋成家宅。','',''),('quantangshi-20321','湖南曲','張籍','quantangshi','','卷21','潇湘多别离，风起芙蓉洲。
江上人已远，夕阳满中流。
鸳鸯东南飞，飞上青山头。','',''),('quantangshi-20322','春水曲','張籍','quantangshi','','卷21','鸭鸭，觜唼唼。
青蒲生，春水狭。
荡漾木兰船，中有双少年。
少年醉，鸭不起。','',''),('quantangshi-20323','云童行','張籍','quantangshi','','卷21','云童童，白龙之尾垂江中。
今年天旱不作雨，水足墙上有禾黍。','',''),('quantangshi-20324','新桃行','張籍','quantangshi','','卷21','桃生叶婆娑，枝叶四向多。
高未出墙颠，蒿苋相凌摩。
植之三年余，今年初试花。
秋来已成实，其阴良已嘉。
青蝉不来鸣，安得迅羽过。
常恶牵丝虫，蒙幂成网罗。
顾托戏儿童，勿折吾柔柯。
明年结其实，磊磊充汝家。','',''),('quantangshi-20325','忆远曲','張籍','quantangshi','','卷21','水上山沈沈，征途复绕林。
途荒人行少，马迹犹可寻。
雪中独立树，海口失侣禽。
离忧如长线，千里萦我心。','',''),('quantangshi-20326','长塘湖','張籍','quantangshi','','卷21','长塘湖，一斛水中半斛鱼。
大鱼如柳叶，小鱼如针锋，水浊谁能辨真龙。','',''),('quantangshi-20327','废瑟词','張籍','quantangshi','','卷21','古瑟在匣谁复识，玉柱颠倒朱丝黑。
千年曲谱不分明，乐府无人传正声。
秋虫暗穿尘作色，腹中不辨工人名。
几时天下复古乐，此瑟还奏云门曲。','',''),('quantangshi-20328','野居','張籍','quantangshi','','卷21','贫贱易为适，荒郊亦安居。
端坐无余思，弥乐古人书。
秋田多良苗，野水多游鱼。
我无耒与网，安得充廪厨。
寒天白日短，檐下暖我躯。
四肢暂宽柔，中肠郁不舒。
多病减志气，为客足忧虞。
况复苦时节，览景独踟蹰。','',''),('quantangshi-20329','西州','張籍','quantangshi','','卷21','羌胡据西州，近甸无边城。
山东收税租，养我防塞兵。
胡骑来无时，居人常震惊。
嗟我五陵间，农者罢耘耕。
边头多杀伤，士卒难全形。
郡县发丁役，丈夫各征行。
生男不能养，惧身有姓名。
良马不念秣，烈士不苟营。
所愿除国难，再逢天下平。','',''),('quantangshi-20330','杂怨','張籍','quantangshi','','卷21','切切重切切，秋风桂枝折。
人当少年嫁，我当少年别。
念君非征行，年年长远途。
妾身甘独殁，高堂有舅姑。
山川岂遥远，行人自不返。','',''),('quantangshi-20331','惜花','張籍','quantangshi','','卷21','春潭足芳树，水清不如素。
幽人爱华景，一一空山暮。
月出潭气白，游鱼暗冲石。
夜深春思多，酒醒山寂寂。','',''),('quantangshi-20332','三原李氏园宴集','張籍','quantangshi','','卷21','暮春天早热，邑居苦嚣烦。
言从君子乐，乐彼李氏园。
园中有草堂，池引泾水泉。
开户西北望，远见嵯峨山。
借问主人翁，北州佐戎轩。
仆夫守旧宅，为客侍华筵。
高怀有余兴，竹树芳且鲜。
倾我所持觞，尽日共留连。
疎拙不偶俗，常喜形体闲。
况来幽栖地，能不重叹言。','',''),('quantangshi-20333','沈千运旧居','張籍','quantangshi','','卷21','汝北君子宅，我来见颓墉。
乱离子孙尽，地属邻里翁。
土木被丘墟，溪路不连通。
旧井蔓草合，牛羊坠其中。
君辞天下书，放意任体躬。
一生不自力，家与逆旅同。
高议切星辰，余声激瘖聋。
方将旌旧闾，百世可封崇。
嗟其未积年，已为荒林丛。
时岂无知音，不能崇此风。
浩荡竟无覩，我将安所从。','',''),('quantangshi-20334','赠别孟郊','張籍','quantangshi','','卷21','历历天上星，沉沉水中萍。
幸当清秋夜，流影及微形。
君生衰俗间，立身如礼经。
纯诚发新文，独有金石声。
才名振京国，归省东南行。
停车楚城下，顾我不念程。
宝镜曾坠水，不磨岂自明。
苦节居贫贱，所知赖友生。
欢会方别离，戚戚忧虑并。
安得在一方，终老无送迎。','',''),('quantangshi-20335','卧疾','張籍','quantangshi','','卷21','身病多思虑，亦读神农经。
空堂留灯烛，四壁青荧荧。
羁旅随人欢，贫贱还自轻。
今来问良医，乃知病所生。
僮仆各忧愁，杵臼无停声。
见我形顦顇，劝药语丁宁。
春雨枕席冷，窗前新禽鸣。
开门起无力，遥爱鸡犬行。
服药察耳目，渐如醉者醒。
顾非达性命，犹为忧患生。','',''),('quantangshi-20336','卧疾','張籍','quantangshi','','卷21','身病始知道，卧读神农经。
空房夜留灯，四壁青荧荧。
羇旅逐人欢，贫贱还自轻。
今来问良医，乃知病所生。
僮仆各相忧，杵臼无停声。
见我形憔悴，劝药语丁宁。
春雨枕席冷，窗前新禽鸣。
开门起无力，遥爱鷄犬行。
服药察耳目，渐觉如酒醒。
方悟养生者，不为忧患并。','',''),('quantangshi-20337','别段生','張籍','quantangshi','','卷21','与子骨肉亲，愿言长相随。
况离父母傍，从我学书诗。
同在道路间，讲论亦未亏。
为文于我前，日夕生光仪。
行役多疾疚，赖此相扶持。
贫贱事难拘，今日有别离。
我去秦城中，子留汴水湄。
离情两飘断，不异风中丝。
幼年独为客，举动难得宜。
努力自修励，常如见我时。
送我登山冈，再拜问还期。
还期在新年，勿怨欢会迟。','',''),('quantangshi-20338','哭于鹄','張籍','quantangshi','','卷21','青山无逸人，忽觉大国贫。
良玉沈幽泉，名为天下珍。
野性疎时俗，再拜乃从军。
气高终不合，去如镜上尘。
我初有章句，相合者唯君。
今来吊嗣子，对陇烧新文。
耕者废其耜，爨者绝其薪。
苟无新衣裳，曷用光我身。
奠酒徒拜手，哀怀安能陈。
徒保金石韵，千载人所闻。','',''),('quantangshi-20339','南归','張籍','quantangshi','','卷21','促促念道路，四支不常宁。
行车未及家，天外非尽程。
骨肉待我欢，乡里望我荣。
岂知东与西，顦顇竟无成。
人言苦夜长，穷者不念明。
惧离其寝寐，百忧伤性灵。
世道多险薄，相劝毕中诚。
远游无知音，不如商贾行。
达人有常志，愚夫劳所营。
旧山行去远，言归乐此生。','',''),('quantangshi-20340','惜花','張籍','quantangshi','','卷21','蒙蒙庭树花，坠地无颜色。
日暮东风起，飘扬玉阶侧。
残蘂在犹稀，青条耸复直。
为君结芳实，令君勿叹息。','',''),('quantangshi-20341','奉和舍人叔直省时思琴','張籍','quantangshi','','卷21','蔼蔼紫薇直，秋意深无穷。
滴沥仙阁漏，肃穆禁池风。
竹月泛凉影，萱露澹幽丛。
地清物态胜，宵闲琴思通。
时属雅音际，逈凝虚抱中。
达人掌枢近，常与隐默同。','',''),('quantangshi-20342','离妇','張籍','quantangshi','','卷21','十载来夫家，闺门无瑕疵。
薄命不生子，古制有分离。
托身言同穴，今日事乖违。
念君终弃捐，谁能强在兹。
堂上谢姑嫜，长跪请离辞。
姑嫜见我往，将决复沉疑。
与我古时钏，留我嫁时衣。
高堂拊我身，哭我于路陲。
昔日初为妇，当君贫贱时。
昼夜常纺绩，不得事蛾眉。
辛勤积黄金，济君寒与饥。
洛阳买大宅，邯郸买侍儿。
夫壻乘龙马，出入有光仪。
将为富家妇，永为子孙资。
谁谓出君门，一身上车归。
有子未必荣，无子坐生悲。
为人莫作女，作女实难为。','',''),('quantangshi-20343','怀别','張籍','quantangshi','','卷21','仆人驱行轩，低昂出我门。
离堂无留客，席上唯琴樽。
古道随水曲，悠悠绕荒村。
远程未奄息，别念在朝昏。
端居愁岁永，独此留清景。
岂无经过人，寻叹门巷静。
君如天上雨，我如屋下井。
无因同波流，愿作形与影。','',''),('quantangshi-20344','学仙','張籍','quantangshi','','卷21','楼观开朱门，树木连房廊。
中有学仙人，少年休谷粮。
高冠如芙蓉，霞月披衣裳。
六时朝上清，佩玉纷铿锵。
自言天老书，祕覆云锦囊。
百年度一人，妄泄有灾殃。
每占有仙相，然后传此方。
先生坐中堂，弟子跪四厢。
金刀截身发，结誓焚灵香。
弟子得其诀，清斋入空房。
守神保元气，动息随天罡。
炉烧丹砂尽，昼夜候火光。
药成既服食，计日乘鸾凰。
虚空无灵应，终岁安所望。
勤劳不能成，疑虑积心肠。
虚羸生疾疹，寿命多夭伤。
身殁惧人见，夜埋山谷傍。
求道慕灵异，不如守寻常。
先王知其非，戒之在国章。','',''),('quantangshi-20345','夜怀','張籍','quantangshi','','卷21','穷居积远念，转转迷所归。
幽蕙零落色，暗萤参差飞。
病生秋风簟，泪堕月明衣。
无愁坐寂寞，重使奏清徽。','',''),('quantangshi-20346','城南','張籍','quantangshi','','卷21','漾漾南涧水，来作曲池流。
言寻参差岛，晓榜轻盈舟。
万绕不再止，千寻尽孤幽。
藻涩讶人重，萍分指鱼游。
繁苗毯下垂，密箭翻回輈。
曝鼈乱自坠，阴藤斜相钩。
卧蒋黑米吐，翻芰紫角稠。
桥低竞俯偻，亭近闲夷犹。
目为逐胜朗，手因掇芳柔。
渐喜游来极，忽疑归无由。
气状虽可览，纤微谅难搜。
未听主人赏，徒爱清华秋。','',''),('quantangshi-20347','怀友','張籍','quantangshi','','卷21','人生有行役，谁能如草木。
别离感中怀，乃为我桎梏。
百年受命短，光景良不足。
念我别离者，愿怀日月促。
平地施道路，车马往不复。
空知为良田，秋望禾黍熟。
端居无俦侣，日夜祷耳目。
立身难自觉，常恐忧与辱。
穷贱无闲暇，疾痛多嗜欲。
我思携手人，逍遥任心腹。','',''),('quantangshi-20348','寄别者','張籍','quantangshi','','卷21','寒天正飞雪，行人心切切。
同为万里客，中路忽离别。
别君汾水东，望君汾水西。
积雪无平冈，空山无人蹊。
羸马时倚辕，行行未遑食。
下车劝僮仆，相顾莫叹息。
讵知佳期隔，离念终无极。','',''),('quantangshi-20349','献从兄','張籍','quantangshi','','卷21','悠悠旱天云，不远如飞尘。
贤达失其所，沉飘同众人。
擢秀登王畿，出为良使宾。
名高满朝野，幼贱谁不闻。
一朝遇谗邪，流窜八九春。
诏书近迁移，组绶未及身。
冬井无寒冰，玉润难为焚。
虚怀日迢遥，荣辱常保纯。
我念出游时，勿吟康乐文。
愿言灵溪期，聊欲相依因。','',''),('quantangshi-20350','寄韩愈','張籍','quantangshi','','卷21','野馆非我室，新居未能安。
读书避尘杂，方觉此地闲。
过郭多园墟，桑果相接连。
独游竟寂寞，如寄空云山。
夏景常昼毒，密林无鸣蝉。
临溪一盥濯，清去肢体烦。
出林望曾城，君子在其间。
戎府草章记，阻我此游盘。
忆昔西潭时，并持钓鱼竿。
共忻得鲂鲤，烹鲙于我前。
几朝还复来，叹息时独言。','',''),('quantangshi-20351','赠姚怤','張籍','quantangshi','','卷21','漏天日无光，泽土松不长。
君今职下位，志气安得扬。
白发文思壮，才为国贤良。
无人识高韵，荐于天子傍。
况我愚朴姿，强趋利名场。
远同干贵人，身举固难彰。
昔逢汴水滨，今会习池阳。
岂无再来期，顾恐非此方。
愿为石中泉，不为瓦上霜。
离别勿复道，所贵不相忘。','',''),('quantangshi-20352','病中寄白学士拾遗','張籍','quantangshi','','卷21','秋亭病客眠，庭树满枝蝉。
凉风绕砌起，斜影入牀前。
梨晚渐红坠，菊寒无黄鲜。
倦游寂寞日，感叹蹉跎年。
尘欢久消委，华念独迎延。
自寓城阙下，识君弟事焉。
君为天子识，我方沉病缠。
无因会同语，悄悄中怀煎。','',''),('quantangshi-20353','雨中寄元宗简','張籍','quantangshi','','卷21','秋堂羸病起，盥漱风雨朝。
竹影冷疎涩，榆叶暗飘萧。
街径多坠果，墙隅有蜕蜩。
延瞻游步阻，独坐闲思饶。
君居应如此，恨言相去遥。','',''),('quantangshi-20354','野寺后池寄友','張籍','quantangshi','','卷21','佛寺连野水，池幽夏景清。
繁木荫芙蕖，时有水禽鸣。
通溪岸蹔断，分渚流复萦。
伴僧钟磬罢，月来池上明。
友人竟不至，东北见高城。
独游自寂寞，况此恨盈盈。','',''),('quantangshi-20355','董公诗','張籍','quantangshi','','卷21','谁主东诸侯，元臣陇西公。
旌节居汴水，四方皆承风。
在朝四十年，天下诵其功。
相我明天子，政成如太宗。
东方有艰难，公乃出临戎。
单车入危城，慈惠安羣凶。
公谓其党言，汝材甚骁雄。
为我帐下士，出入卫我躬。
汝息为我子，汝亲我为翁。
众皆相顾泣，无不和且恭。
其父教子义，其妻勉夫忠。
不自以为资，奉上但颙颙。
公衣无文采，公食少肥浓。
所忧在万人，人实我宁空。
轻刑宽其政，薄赋弛租庸。
四郡三十城，不知岁饥凶。
天子临朝喜，元老留在东。
今闻扬盛德，就安我大邦。
百辟贺明主，皇风恩赐重。
朝廷有大事，就决其所从。
海内既无虞，君臣方肃雍。
端居任僚属，宴语常从容。
翩翩者苍乌，来巢于林丛。
甘瓜生场圃，一蔕实连中。
田有嘉谷陇，异亩穗亦同。
贤人佐圣人，德与神明通。
感应我淳化，生瑞我地中。
昔者此州人，但矜马与弓。
今公施德礼，自然威武崇。
公其共百年，受禄将无穷。','',''),('quantangshi-20356','祭退之','張籍','quantangshi','','卷21','呜呼吏部公，其道诚巍昂。
生为大贤姿，天使光我唐。
德义动鬼神，鉴用不可详。
独得雄直气，发为古文章。
学无不该贯，吏治得其方。
三次论诤退，其志亦刚强。
再使平山东，不言所谋臧。
荐待皆寒羸，但取其才良。
亲朋有孤稚，婚姻有办营。
如彼天有斗，人可为信常。
如彼岁有春，物宜得华昌。
哀哉未申施，中年遽殂丧。
朝野良共哀，矧于知旧肠。
籍在江湖间，独以道自将。
学诗为众体，久乃溢笈囊。
略无相知人，黯如雾中行。
北游偶逢公，盛语相称明。
名因天下闻，传者入歌声。
公领试士司，首荐到上京。
一来遂登科，不见苦贡场。
观我性朴直，乃言及平生。
由兹类朋党，骨肉无以当。
坐令其子拜，常呼幼时名。
追招不隔日，继践公之堂。
出则连辔驰，寝则对榻牀。
搜穷古今书，事事相酌量。
有花必同寻，有月必同望。
为文先见草，酿熟偕共觞。
新果及异鲑，无不相待尝。
到今三十年，曾不少异更。
公文为时师，我亦有微声。
而后之学者，或号为韩张。
我官麟台中，公为大司成。
念此委末秩，不能力自扬。
特状为博士，始获升朝行。
未几享其资，遂忝南宫郎。
是事赖拯扶，如屋有栋梁。
去夏公请告，养疾城南庄。
籍时官休罢，两月同游翔。
黄子陂岸曲，地旷气色清。
新池四平涨，中有蒲荇香。
北台临稻畴，茂柳多阴凉。
板亭坐垂钓，烦苦稍已平。
共爱池上佳，联句舒遐情。
偶有贾秀才，来兹亦同并。
移船入南溪，东西纵篙撑。
划波激船舷，前后飞鸥鸧。
回入潭濑下，网截鲤与鲂。
踏沙掇水蔬，树下烝新秔。
日来相与嬉，不知暑日长。
柴翁携童儿，聚观于岸傍。
月中登高滩，星汉交垂芒。
钓车掷长线，有获齐欢惊。
夜阑乘马归，衣上草露光。
公为游溪诗，唱咏多慨慷。
自期此可老，结社于其乡。
籍受新官诏，拜恩当入城。
公因同归还，居处隔一坊。
中秋十六夜，魄圆天差晴。
公既相邀留，坐语于堦楹。
乃出二侍女，合弹琵琶筝。
临风听繁丝，忽遽闻再更。
顾我数来过，是夜凉难忘。
公疾浸日加，孺人视药汤。
来候不得宿，出门每回遑。
自是将重危，车马候纵横。
门仆皆逆遣，独我到寝房。
公有旷达识，生死为一纲。
及当临终晨，意色亦不荒。
赠我珍重言，傲然委衾裳。
公比欲为书，遗约有修章。
令我署其末，以为后事程。
家人号于前，其书不果成。
子符奉其言，甚于亲使令。
鲁论未讫注，手迹今微茫。
新亭成未登，闭在庄西厢。
书札与诗文，重叠我笥盈。
顷息万事尽，肠情多摧伤。
旧茔盟津北，野窆动鼓钲。
柳车一出门，终天无回箱。
籍贫无赠赀，曷用申哀诚。
衣器陈下帐，醪饵奠堂皇。
明灵庶鉴知，仿髴斯来飨。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-20357','蓟北旅思','張籍','quantangshi','','卷21','日日望乡国，空謌白苎词。
长因送人处，忆得别家时。
失意还独语，多愁祗自知。
客亭门外柳，折尽向南枝。','',''),('quantangshi-20358','江南春','張籍','quantangshi','','卷21','江南杨柳春，日暖地无尘。
渡口过新雨，夜来生白苹。
晴沙鸣乳燕，芳树醉游人。
向晚青山下，谁家祭水神。','',''),('quantangshi-20359','西楼望月','張籍','quantangshi','','卷21','城西楼上月，复是雪晴时。
寒夜共来望，思乡独下迟。
幽光落水堑，净色在霜枝。
明日千里去，此中还别离。','',''),('quantangshi-20360','别鹤','張籍','quantangshi','','卷21','双鹤出云溪，分飞各自迷。
空巢在松顶，折羽落红泥。
寻水终不饮，逢林亦未栖。
别离应易老，万里雨凄凄。','',''),('quantangshi-20361','江陵孝女','張籍','quantangshi','','卷21','孝女独垂发，少年唯一身。
无家空托墓，主祭不从人。
相吊有行客，起庐无旧邻。
江头闻哭处，寂寂楚花春。','',''),('quantangshi-20362','山中古祠','張籍','quantangshi','','卷21','春草空祠墓，荒林唯鸟飞。
记年碑石在，经乱祭人稀。
野鼠缘朱帐，阴尘盖画衣。
近门潭水黑，时见宿龙归。','',''),('quantangshi-20363','渔阳将','張籍','quantangshi','','卷21','塞深沙草白，都护领燕兵。
放火烧奚帐，分旗筑汉城。
下营看岭势，寻雪觉人行。
更向桑干北，擒生问碛名。','',''),('quantangshi-20364','听夜泉','張籍','quantangshi','','卷21','细泉深处落，夜久渐闻声。
独起出门听，欲寻当涧行。
还疑隔林远，复畏有风生。
月下长来此，无人亦到明。','',''),('quantangshi-20365','送南迁客','張籍','quantangshi','','卷21','去去远迁客，瘴中衰病身。
青山无限路，白首不归人。
海国战骑象，蛮州市用银。
一家分几处，谁见日南春。','',''),('quantangshi-20366','蓟北春怀','張籍','quantangshi','','卷21','渺渺水云外，别来音信稀。
因逢过江使，却寄在家衣。
问路更愁远，逢人空说归。
今朝蓟城北，又见塞鸿飞。','',''),('quantangshi-20367','思远人','張籍','quantangshi','','卷21','野桥春水清，桥上送君行。
去去人应老，年年草自生。
出门看远道，无信向边城。
杨柳别离处，秋蝉今复鸣。','',''),('quantangshi-20368','赠同溪客','張籍','quantangshi','','卷21','幽居得相近，烟景每寥寥。
共伐临溪树，因为过水桥。
自教青鹤舞，分采紫芝苗。
更爱南峰住，寻君路恐遥。','',''),('quantangshi-20369','望行人','張籍','quantangshi','','卷21','秋风窗下起，旅雁向南飞。
日日出门望，家家行客归。
无因见边使，空待寄寒衣。
独倚青楼暮，烟深鸟雀稀。','',''),('quantangshi-20370','送宫人入道','張籍','quantangshi','','卷21','旧宠昭阳里，寻仙此最稀。
名初出宫籍，身未称霞衣。
已别歌舞贵，长随鸾鹤飞。
中官看入洞，空驾玉轮归。','',''),('quantangshi-20371','送越客','張籍','quantangshi','','卷21','见说孤帆去，东南到会稽。
春云剡溪口，残月镜湖西。
水鹤沙边立，山鼯竹里啼。
谢家曾住处，烟洞入应迷。','',''),('quantangshi-20372','赠辟谷者','張籍','quantangshi','','卷21','学得餐霞法，逢人与小还。
身轻曾试鹤，力弱未离山。
无食犬犹在，不耕牛自闲。
朝朝空漱水，叩齿草堂间。','',''),('quantangshi-20373','思江南旧游','張籍','quantangshi','','卷21','江臯三月时，花发石楠枝。
归客应无数，春山自不知。
独行愁道远，回信畏家移。
杨柳东西渡，茫茫欲问谁。','',''),('quantangshi-20374','夜到渔家','張籍','quantangshi','','卷21','渔家在江口，潮水入柴扉。
行客欲投宿，主人犹未归。
竹深村路远，月出钓船稀。
遥见寻沙岸，春风动草衣。','',''),('quantangshi-20375','送远使','張籍','quantangshi','','卷21','扬旌过陇头，陇水向西流。
塞路依山远，戍城逢笛秋。
寒沙阴漫漫，疲马去悠悠。
为问征行将，谁封定远侯。','',''),('quantangshi-20376','不食姑','張籍','quantangshi','','卷21','几年山里住，已作绿毛身。
护气常稀语，存思自见神。
养龟同不食，留药任生尘。
要问西王母，仙中第几人。','',''),('quantangshi-20377','古苑杏花','張籍','quantangshi','','卷21','废苑杏花在，行人愁到时。
独开新堑底，半露旧烧枝。
晚色连荒辙，低阴覆折碑。
茫茫古陵下，春尽又谁知。','',''),('quantangshi-20378','送流人','張籍','quantangshi','','卷21','独向长城北，黄云暗塞天。
流名属边将，旧业作公田。
拥雪添军垒，收冰当井泉。
知君住应老，须记别乡年。','',''),('quantangshi-20379','宿临江驿','張籍','quantangshi','','卷21','楚驿南渡口，夜深来客稀。
月明见潮上，江静觉鸥飞。
旅宿今已远，此行殊未归。
离家久无信，又听捣寒衣。','',''),('quantangshi-20380','送蛮客','張籍','quantangshi','','卷21','借问炎州客，天南几日行。
江连恶溪路，山遶夜郎城。
柳叶瘴云湿，桂丛蛮鸟声。
知君却回日，记得海花名。','',''),('quantangshi-20381','襄国别友','張籍','quantangshi','','卷21','晓色荒城下，相看秋草时。
独游无定计，不欲道来期。
别处去家远，愁中驱马迟。
归人渡烟水，遥暎野棠枝。','',''),('quantangshi-20382','送远客','張籍','quantangshi','','卷21','南原相送处，秋水草还生。
同作忆乡客，如今分路行。
因谁寄归信，渐远问前程。
明日重阳节，无人上古城。','',''),('quantangshi-20383','山中赠日南僧','張籍','quantangshi','','卷21','独向双峰老，松门闭两崖。
翻经上蕉叶，挂衲落藤花。
甃石新开井，穿林自种茶。
时逢海南客，蛮语问谁家。','',''),('quantangshi-20384','征西将','張籍','quantangshi','','卷21','黄沙北风起，半夜又翻营。
战马雪中宿，探人冰上行。
深山旗未展，阴碛鼓无声。
几道征西将，同收碎叶城。','',''),('quantangshi-20385','寄友人','張籍','quantangshi','','卷21','忆在江南日，同游三月时。
采茶寻远涧，鬬鸭向春池。
送客沙头宿，招僧竹里碁。
如今各千里，无计得相随。','',''),('quantangshi-20386','送防秋将','張籍','quantangshi','','卷21','白首征西将，犹能射戟支。
元戎选部曲，军吏换旌旗。
逐虏招降远，开边旧垒移。
重收陇外地，应似汉家时。','',''),('quantangshi-20387','律僧','張籍','quantangshi','','卷21','苦行长不出，清羸最少年。
持斋唯一食，讲律岂曾眠。
避草每移径，滤虫还入泉。
从来天竺法，到此几人传。','',''),('quantangshi-20388','山中秋夜','張籍','quantangshi','','卷21','寂寂山景静，幽人归去迟。
横琴当月下，压酒及花时。
冷露湿茆屋，暗泉冲竹篱。
西峰采药伴，此夕恨无期。','',''),('quantangshi-20389','送南客','張籍','quantangshi','','卷21','行路雨修修，青山尽海头。
天涯人去远，岭北水空流。
夜市连铜柱，巢居属象州。
来时旧相识，谁向日南游。','',''),('quantangshi-20390','宿江店','張籍','quantangshi','','卷21','野店临西浦，门前有橘花。
停灯待贾客，卖酒与渔家。
夜静江水白，路回山月斜。
闲寻泊船处，潮落见平沙。','',''),('quantangshi-20391','岭表逢故人','張籍','quantangshi','','卷21','过岭万余里，旅游经此稀。
相逢去家远，共说几时归。
海上见花发，瘴中唯鸟飞。
炎州望乡伴，自识北人衣。','',''),('quantangshi-20392','出塞','張籍','quantangshi','','卷21','秋塞雪初下，将军远出师。
分营长记火，放马不收旗。
月冷边帐湿，沙昏夜探迟。
征人皆白首，谁见灭胡时。','','');